-- Generato da tools/build_db.py da data/it/quests.json, gossip.json, options.json e books.json: NON modificare a mano.
WoWForeverIT_QuestIT.DataIT = {
    [2] = {
        title = { it = "Sharptalon's Claw", enHash = "919c763f", vanilla = true },
        text = { it = "Il possente ippogrifo Sharptalon è stato ucciso, e l'artiglio della bestia abbattuta è la testimonianza della tua vittoria. Senani Thunderheart, a Splintertree Post, sarà senza dubbio interessata a vedere questo trofeo come prova delle tue imprese.", enHash = "345596d4", vanilla = true },
        objectives = { it = "Porta Sharptalon's Claw a Senani Thunderheart a Splintertree Post, in Ashenvale.", enHash = "b7e62bbb", vanilla = true },
        progress = { it = "Sì, possente $C, ho percepito il tuo arrivo. Immagino che tu abbia altre notizie da riferirmi sulla tua caccia?", enHash = "99341091", vanilla = true },
        reward = { it = "Davvero notevole, $N... l'artiglio di Sharptalon non dev'essere stato facile da ottenere! La caccia di Ashenvale procede bene per te!\n\nSharptalon terrorizzava da tempo i peon dei campi di legname lungo il suo cammino, mentre cercavano di arrivare fin qui a Splintertree Post. Non appena si saprà che sei $Gstato:stata; tu ad abbattere la bestia, di sicuro si leveranno molti canti al tuo coraggio attorno ai fuochi e nelle segherie di tutta Ashenvale!", enHash = "151580c8", vanilla = true },
    },
    [5] = {
        title = { it = "Lo stomaco brontolante di Jitters", enHash = "dd90a74f", vanilla = true },
        text = { it = "Sono settimane che me ne sto nascosto in questa città fantasma, e non ho mangiato altro che larve ed erbacce! Mi serve del cibo decente, e per averlo pago bene.\n\nPortami un banchetto e ti ricompenserò profumatamente.\n\nHo sentito che Chef Grual, alla Scarlet Raven Tavern di Darkshire, fa degli ottimi Dusky Crab Cake...", enHash = "92355e66", vanilla = true },
        objectives = { it = "Parla con Chef Grual.", enHash = "715df407", vanilla = true },
        reward = { it = "Ti servono dei Crab Cake, eh? Be', forse posso cucinartene un po'...", enHash = "31dc6a9a", vanilla = true },
    },
    [6] = {
        title = { it = "Taglia su Garrick Padfoot", enHash = "408a996c" },
        text = { it = "Garrick Padfoot, un tagliagole che da settimane tormenta i nostri contadini e mercanti, è stato visto in una baracca vicino ai vigneti, a est dell'abbazia, oltre il ponte. Portami la testa di quel furfante e guadagnati la taglia!\n\nMa stai $Gattento:attenta;, $N. Garrick ha radunato intorno a sé una banda di delinquenti. Non sarà un uomo facile da raggiungere.", enHash = "ee6d961d" },
        objectives = { it = "Uccidi Garrick Padfoot e porta la sua testa a Deputy Willem, alla Northshire Abbey.", enHash = "c6ab298f" },
        progress = { it = "Hai trovato la baracca di Garrick? Ci siamo finalmente liberati di quel furfante?", enHash = "84c4b0ba" },
        reward = { it = "Ah, l'hai preso! Hai reso un grande servizio a Elwynn, e ti sei $Gguadagnato:guadagnata; una bella taglia!", enHash = "521e4a09" },
    },
    [7] = {
        title = { it = "Ripulire l'accampamento dei kobold", enHash = "4919d8dc" },
        text = { it = "Il tuo primo compito è fare pulizia, $N. Un clan di kobold ha infestato i boschi a nord. Vai là e combatti i Kobold Vermin che trovi. Riduci il loro numero, così che un giorno potremo cacciarli da Northshire.", enHash = "2ca26b59" },
        objectives = { it = "Uccidi 10 Kobold Vermin, poi torna da Marshal McBride.", enHash = "18af4929" },
        progress = { it = "Come va la caccia, $N? Hai trovato e sconfitto quei Kobold Vermin?", enHash = "73628fb4" },
        reward = { it = "Ben fatto, $Gcittadino:cittadina;. Quei kobold sono ladri e codardi, ma in gran numero sono una minaccia per noi. E gli umani di Stormwind non hanno bisogno di un'altra minaccia.\n\nPer averli sconfitti, ti sono grato.", enHash = "a611a5a4" },
    },
    [8] = {
        title = { it = "L'affare di un ladro", enHash = "cecc1842" },
        text = { it = "Ehi, $Gamico:amica;! Faresti un favore a un giovanotto che ha già combattuto zombi senza cervello e ragni ben più del dovuto?\n\nHo qui una lettera da portare a Brill... a una locandiera che si chiama Renee qualcosa. Il cognome non conta granché.\n\nComunque, è un posticino accogliente, pieno di vittime della pestilenza che cercano di rifarsi una vita. Ed è un ottimo posto anche per riposarti, se ne avrai bisogno. Dovresti farci un salto... fallo e ti pagherò bene.", enHash = "9dae0f5c" },
        objectives = { it = "Consegna la Nondescript Letter a Innkeeper Renee nelle Tirisfal Glades.", enHash = "6df40a17" },
        progress = { it = "Sì? Sì? Che c'è?\n\nI Reietti hanno di certo un appetito enorme. Fai come se fossi a casa tua... sì, riposa quelle ossa stanche. Mi chiamo Renee, se ti serve qualcosa.", enHash = "b41aee2b", vanilla = true },
        reward = { it = "Oh? Una lettera? Che bella notizia! Aspettavo notizie dalla mia cara vecchia madre a Deathknell. Una santa, davvero. Chissà come se la cava.\n\nCosa? Troppo allegra? Non te la bevi, eh?\n\nBe', allora sparisci... tanto non sono affari tuoi chi mi manda la lettera. Avanti! Sparisci!\n\nTorna quando avrai qualche moneta da spendere... $Gfannullone:fannullona;.\n\nVedrai che tra poco tornerai qui a riposarti dopo una lunga giornata d'avventure, o qualche stupidaggine del genere.", enHash = "514078a6", vanilla = true },
    },
    [9] = {
        title = { it = "I campi della morte", enHash = "5fe1a224", vanilla = true },
        text = { it = "Guarda cos'è successo a questo posto! Queste terre erano abitate da brava gente di campagna. Ma quei maledetti ladri li hanno cacciati tutti via. Non me, però! Solo che a quanto pare gli Harvest Watcher si sono presi i campi.\n\nSe te la senti di lavorare, vorrei che tu andassi là fuori e ne uccidessi venti. Torna quando hai finito, per la paga. Se finisci con quelli nel mio campo, ripulisci anche i campi vicini.", enHash = "753fbf11", vanilla = true },
        objectives = { it = "Farmer Saldean vuole che tu uccida 20 Harvest Watcher.", enHash = "512269ca", vanilla = true },
        progress = { it = "Ah, vedo che sei $Gtornato:tornata;! Spero che tu abbia lavorato sodo a ripulire quei campi dagli Harvest Watcher. Ne hai già uccisi venti?", enHash = "3c5dc1f4", vanilla = true },
        reward = { it = "Bel lavoro, $Gamico:amica;. Ti sei $Gguadagnato:guadagnata; la paga. Chissà, forse Westfall tornerà a prosperare.", enHash = "660dd520", vanilla = true },
    },
    [11] = {
        title = { it = "Taglia sugli gnoll Riverpaw", enHash = "1671c729" },
        text = { it = "Gli gnoll, creature brutali che in queste terre non hanno niente di buono da fare, sono stati visti lungo i confini dell'Elwynn Forest. Un grosso branco, molto più numeroso di quanto possiamo gestire da soli, ha infestato i boschi a sud della torre di guardia laggiù. Un altro gruppo ha infestato le zone vicino allo Stone Cairn Lake, a est.\n\nL'esercito di Stormwind encomierà chiunque aiuti a ucciderli. Portami le loro Painted Gnoll Armband come prova dell'impresa.", enHash = "f1622e19" },
        objectives = { it = "Porta 8 Painted Gnoll Armband a Deputy Rainer, alla caserma.", enHash = "e505cf6b" },
        progress = { it = "Salute, $N. Hai ucciso qualche gnoll...?", enHash = "58b1f987", vanilla = true },
        reward = { it = "Vedo che hai avuto da fare! Ti ringraziamo, $N.", enHash = "db270895", vanilla = true },
    },
    [12] = {
        title = { it = "La People's Militia", enHash = "9bcd8a7d", vanilla = true },
        text = { it = "La People's Militia ha un solo scopo: difendere le terre di Westfall e riportare la pace da queste parti. Purtroppo il prezzo della pace è spesso il sangue.\n\nUno dei miei esploratori ha portato notizia di una banda di Defias Trapper che semina il caos qui vicino. Ho segnalazioni di Defias Trapper avvistati vicino alla Jangolode Mine, a nord-ovest, e anche alla Molsen Farm e alla Furlbrow's Pumpkin Farm. Se vuoi unirti alle nostre file, uccidi 15 Defias Trapper e 15 Defias Smuggler, poi torna da me.", enHash = "f67ea32c", vanilla = true },
        objectives = { it = "Gryan Stoutmantle vuole che tu uccida 15 Defias Trapper e 15 Defias Smuggler e poi torni da lui, a Sentinel Hill.", enHash = "f16305f7", vanilla = true },
        progress = { it = "Forse non sono stato chiaro, aspirante. Per dimostrare il tuo valore al servizio della People's Militia e della Luce devi uccidere 15 Defias Trapper e 15 Defias Smuggler, e poi tornare da me a cose fatte.", enHash = "b31dc097", vanilla = true },
        reward = { it = "Ben fatto, $N. Il mio esploratore ha visto le tue azioni valorose. Finora ti stai dimostrando all'altezza.", enHash = "420afc3f", vanilla = true },
    },
    [13] = {
        title = { it = "La People's Militia", enHash = "9bcd8a7d", vanilla = true },
        text = { it = "Una banda di feroci Defias Pillager è stata vista saccheggiare la Gold Coast Quarry, Moonbrook e l'Alexston Farmstead. La People's Militia non tollererà un simile comportamento. Parti subito, $N, e fa' sentire la presenza della Luce in Westfall.\n\nLa Gold Coast Quarry è vicino alla riva, a ovest della torre. Come passo successivo del tuo addestramento, voglio che tu uccida 15 di quegli immondi Defias Pillager e 15 Defias Looter.", enHash = "664ecbbe", vanilla = true },
        objectives = { it = "Gryan Stoutmantle vuole che tu uccida 15 Defias Pillager e 15 Defias Looter e torni da lui, a Sentinel Hill.", enHash = "1f911560", vanilla = true },
        progress = { it = "Non abbiamo tempo per parlare, $N. I Defias Pillager negano alla gente di Westfall la pace e la prosperità che merita. Accertati che siano stati uccisi almeno 15 Defias Pillager e 15 Defias Looter. Sarà un messaggio chiaro: qui la corruzione non è la benvenuta.", enHash = "7aca5910", vanilla = true },
        reward = { it = "Il tuo valore per la People's Militia è stato confermato dalle azioni coraggiose che hai compiuto finora.", enHash = "12c631cd", vanilla = true },
    },
    [14] = {
        title = { it = "La People's Militia", enHash = "9bcd8a7d", vanilla = true },
        text = { it = "Alcuni Defias ci sono sfuggiti. Il mio esploratore più fidato riferisce che questi Defias hanno saccheggiato e depredato le campagne, fin giù nel sud di Westfall. Crediamo che si nascondano nelle Dagger Hills, a tramare la prossima mossa. Uccidi quei miserabili nel nome della People's Militia.", enHash = "d65c94f5", vanilla = true },
        objectives = { it = "Gryan Stoutmantle vuole che tu uccida 15 Defias Highwayman, 5 Defias Pathstalker e 5 Defias Knuckleduster e poi torni da lui, a Sentinel Hill.", enHash = "8d11ccef", vanilla = true },
        progress = { it = "$N, non è tempo di chiacchiere oziose. Se vuoi ancora dimostrare il tuo valore alla People's Militia devi uccidere i Defias di cui ti ho parlato prima. Torna da me quando avrai compiuto il tuo dovere.", enHash = "2f727224", vanilla = true },
        reward = { it = "Quando lasciai le terre contaminate di Lordaeron, tornai a una situazione cupa qui nella mia terra. Ma per Westfall c'è ancora speranza. Come dimostra il tuo valore in battaglia, per me è evidente che servi la nostra causa con onore. È con grande orgoglio che ti accolgo nella People's Militia. Che la Luce ti illumini.", enHash = "389f3519", vanilla = true },
    },
    [15] = {
        title = { it = "Indaga su Echo Ridge", enHash = "6be789d1" },
        text = { it = "$N, i miei esploratori mi dicono che l'infestazione di kobold è più estesa di quanto pensassimo. Un gruppo di Kobold Worker si è accampato vicino all'Echo Ridge Mine, a nord.\n\nVa' alla miniera e toglili di mezzo. Sappiamo che sono almeno 10. Uccidili, controlla se ce ne sono altri, poi torna da me a fare rapporto.", enHash = "e55fd0e3" },
        objectives = { it = "Uccidi 10 Kobold Worker, poi torna da Marshal McBride a fare rapporto.", enHash = "19359332" },
        progress = { it = "Sei $Gstato:stata; alle miniere? Sei $Gpronto:pronta; a fare rapporto?", enHash = "e9262f28", vanilla = true },
        reward = { it = "Non mi piace sentir parlare di tutti questi kobold nella nostra miniera. Non ne verrà niente di buono. Ecco, prendi questo come compenso e, quando sarai $Gpronto:pronta;, vieni di nuovo a parlarmi. Vorrei che tornassi alle miniere un'altra volta...", enHash = "516d2687" },
    },
    [16] = {
        title = { it = "Offri da bere a Gerard", enHash = "907dc067", vanilla = true },
        progress = { it = "Lavorare la terra mette sete, e sono sempre in cerca di Refreshing Spring Water.\n\nSe ne hai, sono disposto a fare uno scambio.", enHash = "70511a3e", vanilla = true },
        reward = { it = "Grazie, $N! E torna pure, se vuoi fare un altro scambio.", enHash = "e4609a23", vanilla = true },
    },
    [17] = {
        title = { it = "Reagenti da Uldaman", enHash = "7a56b083", vanilla = true },
        text = { it = "Ho sentito parlare di una pianta scoperta da poco, i Magenta Fungus Cap. Crescono a grappoli, nel profondo del sito di scavo di Uldaman; forse si trovano anche altrove, ma per ora è l'unico posto che conosco. Voglio studiarne il possibile uso in alchimia, ed è qui che entri in gioco tu.\n\nTrova i Magenta Cap Clusters e portami una dozzina di cappelli. Sta' $Gattento:attenta;: se li urti, i grappoli potrebbero sputare spore velenose.\n\nFallo per me, e ti preparerò una partita di uno dei miei famosi elisir ristoratori!", enHash = "09ecf1bb", vanilla = true },
        objectives = { it = "Porta 12 Magenta Fungus Cap a Ghak Healtouch, a Thelsamar.", enHash = "d1a382ce", vanilla = true },
        progress = { it = "Ti sei $Gprocurato:procurata; i Magenta Fungus Cap che mi servono per il mio lavoro alchemico? Niente cappelli, niente ricompensa!", enHash = "4ddbd5c3", vanilla = true },
        reward = { it = "Ben fatto, $N: hai dimostrato ancora una volta quanto vali! I cappelli saranno uno studio interessante, puoi giurarci!\n\nE ora, come promesso, gusta un assaggio di uno dei miei intrugli ristoratori più potenti, dalla mia scorta personale...\n\nSe sei $Gun alchimista esperto:un'alchimista esperta;, forse potremmo fare altri affari. In ogni caso, ti ringrazio per il tuo aiuto!", enHash = "cfd5b039", vanilla = true },
    },
    [18] = {
        title = { it = "Fratellanza di ladri", enHash = "0108ae8f" },
        text = { it = "Da poco un nuovo gruppo di ladri si aggira per Northshire. Si fanno chiamare Defias Brotherhood, e sono stati visti oltre il fiume, a est.\n\nNon so cosa stiano tramando, ma di sicuro niente di buono! Portami le bandane che indossano, e ti ricompenserò con un'arma.", enHash = "a1618f21" },
        objectives = { it = "Porta 12 Red Burlap Bandana a Deputy Willem, fuori dalla Northshire Abbey.", enHash = "6071c0bf" },
        progress = { it = "Mi hai già procurato quelle bandane?", enHash = "1c05363c" },
        reward = { it = "Vedo che sei $Gtornato:tornata; con delle bandane. L'esercito di Stormwind apprezza il tuo aiuto.", enHash = "bcb31b25" },
    },
    [19] = {
        title = { it = "Tharil'zun", enHash = "911f1494", vanilla = true },
        text = { it = "I Blackrock Outrunner e i Blackrock Renegade tendono imboscate tra qui e lo Stonewatch Keep. Il capo degli Outrunner è un orco di nome Tharil'zun: quell'orco lo vogliamo. Portami la testa di Tharil'zun!", enHash = "cb2711b9", vanilla = true },
        objectives = { it = "Porta Tharil'zun's Head a Marshal Marris, a Redridge.", enHash = "0ec77362", vanilla = true },
        progress = { it = "La pressione degli orchi di Blackrock è sempre alta. Ma almeno ci hai liberati di Tharil'zun?", enHash = "221a6d63", vanilla = true },
        reward = { it = "Tharil'zun era un orco feroce e astuto. Ben fatto — di sicuro non è caduto facilmente. Ecco la tua ricompensa, $N.", enHash = "5603055a", vanilla = true },
    },
    [20] = {
        title = { it = "La minaccia Blackrock", enHash = "a32b82a9", vanilla = true },
        text = { it = "Gli orchi Blackrock sono arrivati dalle Burning Steppes e hanno occupato lo Stonewatch Keep, a nord. Da lì saccheggiano le zone a nord di Lakeshire e costringono i cittadini a restare in paese, chiusi come bestie in un recinto.\n\nAiutaci a liberare Lakeshire da questa minaccia. Uccidi questi orchi Blackrock e portami dieci delle loro Battleworn Axe come prova.\n\nI Blackrock ci minacciano da nord, ma ci sono arrivate segnalazioni di altri orchi nell'angolo sud-orientale di Redridge. Se ne trovi laggiù, da' la caccia anche a loro.", enHash = "aaa4680d", vanilla = true },
        objectives = { it = "Porta 10 Battleworn Axe a Marshal Marris, a Lakeshire.", enHash = "0f48449c", vanilla = true },
        progress = { it = "Hai ucciso degli orchi, $N? Se è così, fammi vedere...", enHash = "03dd8407", vanilla = true },
        reward = { it = "Sono un bel po' di orchi in meno di cui preoccuparsi, grazie.", enHash = "7836ec8f", vanilla = true },
    },
    [21] = {
        title = { it = "Scontro a Echo Ridge", enHash = "b2fa494f" },
        text = { it = "Le tue indagini precedenti dimostrano che l'Echo Ridge Mine va ripulita. Torna alla miniera e aiuta a liberarla dai kobold.\n\nNon perdere tempo, $N. Più a lungo i kobold restano indisturbati nella miniera, più si radicano a Northshire.", enHash = "4b204cf0" },
        objectives = { it = "Uccidi 12 Kobold Laborer, poi torna da Marshal McBride alla Northshire Abbey.", enHash = "d09128fc" },
        progress = { it = "Lo so che è un lavoro sanguinoso, $N, ma è fondamentale per la sicurezza di Northshire. Sei $Gpronto:pronta; a fare rapporto?", enHash = "7fe40452", vanilla = true },
        reward = { it = "Ancora una volta ti sei $Gguadagnato:guadagnata; il mio rispetto e la gratitudine dell'esercito di Stormwind. Nella miniera potrebbero esserci ancora dei kobold, ma manderò altri contro di loro. Abbiamo altri compiti per te.", enHash = "ed7ea75b" },
    },
    [22] = {
        title = { it = "Goretusk Liver Pie", enHash = "c7dc2686", vanilla = true },
        text = { it = "Le cipolle sono sbucciate. L'aglio è tritato. Il rosmarino è pestato. La crosta è cotta. L'aneto è tritato. Il sugo sobbolle. Ora, per il mio famoso pasticcio di carne, mi mancano solo 8 Goretusk Liver!", enHash = "c69c7709", vanilla = true },
        objectives = { it = "A Salma Saldean servono 8 Goretusk Liver per fare una Goretusk Liver Pie.", enHash = "f116cd08", vanilla = true },
        progress = { it = "Per il mio famoso pasticcio di carne mi mancano solo 8 Goretusk Liver!", enHash = "b9f899c9", vanilla = true },
        reward = { it = "Questi sono perfetti, $N! Grazie mille. Io e Farmer Saldean stasera faremo festa. Ed ecco qualcosina per te, per la fatica. Non pensavi mica che avrei lasciato $Gun:una; $C come te a pancia vuota, vero?", enHash = "c7c51a40", vanilla = true },
    },
    [23] = {
        title = { it = "Ursangous's Paw", enHash = "c8fc4d1b", vanilla = true },
        text = { it = "La zampa del possente orso Ursangous è il tuo trofeo per questa parte della caccia di Ashenvale. Sulla zampa c'è un piccolo emblema a quarto di luna; il significato dell'emblema resta un mistero.\n\nLa zampa va portata a Senani Thunderheart a Splintertree Post, per dimostrare che hai battuto la possente creatura e completato questa parte della caccia.", enHash = "d9fea47e", vanilla = true },
        objectives = { it = "Porta Ursangous's Paw a Senani Thunderheart a Splintertree Post, in Ashenvale.", enHash = "4866d317", vanilla = true },
        progress = { it = "Ah — $N — stavo giusto pensando a te! Come va la caccia?", enHash = "79b2d77f", vanilla = true },
        reward = { it = "Ah, la zampa di Ursangous! La tua abilità è notevole, $C; gli sono attribuite numerose uccisioni. La mezzaluna sulla sua zampa è senza dubbio il segno che era stato addestrato dagli elfi della notte che si aggirano per Ashenvale. Ursangous è... era uno degli orsi più possenti che si potessero trovare da queste parti. Aver battuto una creatura simile è la prova della tua volontà e della tua determinazione.\n\nI tuoi antenati ne sarebbero fieri!", enHash = "17203b7c", vanilla = true },
    },
    [24] = {
        title = { it = "Shadumbra's Head", enHash = "3b9f46f3", vanilla = true },
        text = { it = "Shadumbra, un tempo veloce, ora giace immobile mentre reclami la vittoria su di esso. La testa del nightsaber ucciso è un trofeo adatto a questo scontro della caccia di Ashenvale. Senani Thunderheart, a Splintertree Post, vorrà vedere un trofeo simile per riconoscerti il merito di questa parte della caccia di Ashenvale.", enHash = "5feb514f", vanilla = true },
        objectives = { it = "Porta Shadumbra's Head a Senani Thunderheart a Splintertree Post, in Ashenvale.", enHash = "36f74c4b", vanilla = true },
        progress = { it = "Salve di nuovo, $N! Sei $Gvenuto:venuta; a mostrarmi le prove della tua caccia?", enHash = "f847e5a1", vanilla = true },
        reward = { it = "Una vittoria per $N nella caccia di Ashenvale! Ben fatto — la testa di Shadumbra è senza dubbio un trofeo adatto a uno scontro così notevole.\n\nLa ferocia di Shadumbra era nota in tutto l'avamposto. Ogni viaggio verso ovest, soprattutto a piedi per raggiungere lo Zoram Strand, era pieno di pericoli a causa di quella tigre. Grazie a te, il pericolo è diminuito.", enHash = "046ab974", vanilla = true },
    },
    [25] = {
        title = { it = "Stallo a Stonetalon", enHash = "aa96b599", vanilla = true },
        text = { it = "Se vuoi renderti utile, perché non fai qualcosa per la situazione vicino al Talondeep Path?\n\nI trasporti tra Ashenvale e Stonetalon sono fermi perché il lago si è animato e attacca tutto ciò che gli si avvicina... cioè chiunque passi sul sentiero. Ancora più utile che menare le mani sugli elementali dell'acqua sarebbe qualcuno che vada a dare un'occhiata al gazebo sul Mystral Lake — quello da cui si vede bene l'avamposto dell'Alleanza.\n\nTe la senti di renderti utile?", enHash = "7f532093", vanilla = true },
        objectives = { it = "Elimina 12 Befouled Water Elemental al Mystral Lake, dritto a est del Talondeep Path e a sud-ovest di Splintertree Post.\n\nVa' a dare un'occhiata al gazebo sul Mystral Lake, quello che domina l'avamposto dell'Alleanza lì vicino.\n\nTorna da Mastok Wrilehiss a Splintertree Post, in Ashenvale.", enHash = "1aa3f95b", vanilla = true },
        progress = { it = "Già di ritorno? Com'è la situazione là fuori — tutto sistemato, grazie a te?", enHash = "1ffd9ce9", vanilla = true },
        reward = { it = "Già, ho sentito che qualcuno ha messo a soqquadro quel lago come un turbine di polvere attraverso le Barrens. E da quel che si dice, forse potremmo allestire là fuori un punto d'osservazione per tenere d'occhio i nostri amici dell'Alleanza. Sempre che riusciamo a farlo senza dare nell'occhio...\n\nSembra che alla fine ti sia $Greso:resa; parecchio utile; i trasporti tra qui e Stonetalon dovrebbero avere vita più facile. Prendi questo — te lo sei $Gguadagnato:guadagnata;.", enHash = "8fd465c7", vanilla = true },
    },
    [26] = {
        title = { it = "Una lezione da imparare", enHash = "af31d488", vanilla = true },
        text = { it = "$N, seguo i tuoi progressi con grande piacere. Stai davvero diventando $Gun prezioso protettore:una preziosa protettrice; della natura.\n\nÈ giunto il momento che tu impari di più su uno dei vari aspetti animali in cui Cenarius ci ha concesso di trasformarci — un aspetto che ti dona il controllo e la padronanza dell'acqua. Per questo devi recarti nel villaggio di Nighthaven, a Moonglade, e parlare con Dendrite Starblaze del Cenarion Circle. Sarà lui a guidarti oltre.", enHash = "b95eb370", vanilla = true },
        objectives = { it = "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.", enHash = "0c58ff24", vanilla = true },
        reward = { it = "Salute a te, giovane $Gdruido:druida;. È giunto il momento che tu conosca la nostra Aquatic Form. È una forma che ti permette di muoverti liberamente nell'acqua, senza limiti di tempo. Scoprirai che questo aspetto è uno strumento utile e una benedizione... ma prima di padroneggiarlo bisogna guadagnarselo.\n\nDovrai superare due prove. La prima verificherà la tua capacità di agire in acqua sotto pressione. La seconda metterà alla prova la tua determinazione a comprendere gli aspetti della forma stessa.\n\nTieniti $Gpronto:pronta;, perché il momento delle prove è arrivato.", enHash = "e4cc7f95", vanilla = true },
    },
    [27] = {
        title = { it = "Una lezione da imparare", enHash = "af31d488", vanilla = true },
        text = { it = "$N, seguo i tuoi progressi con grande piacere. Stai davvero diventando $Gun prezioso protettore:una preziosa protettrice; della natura.\n\nÈ giunto il momento che tu impari di più su uno dei vari aspetti animali in cui Cenarius ci ha concesso di trasformarci — un aspetto che ti dona il controllo e la padronanza dell'acqua. Per questo devi recarti nel villaggio di Nighthaven, a Moonglade, e parlare con Dendrite Starblaze del Cenarion Circle. Sarà lui a guidarti oltre.", enHash = "b95eb370", vanilla = true },
        objectives = { it = "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.", enHash = "0c58ff24", vanilla = true },
        reward = { it = "Salute a te, giovane $Gdruido:druida;. È giunto il momento che tu conosca la nostra Aquatic Form. È una forma che ti permette di muoverti liberamente nell'acqua, senza limiti di tempo. Scoprirai che questo aspetto è uno strumento utile e una benedizione... ma prima di padroneggiarlo bisogna guadagnarselo.\n\nDovrai superare due prove. La prima verificherà la tua capacità di agire in acqua sotto pressione. La seconda metterà alla prova la tua determinazione a comprendere gli aspetti della forma stessa.\n\nTieniti $Gpronto:pronta;, perché il momento delle prove è arrivato.", enHash = "e4cc7f95", vanilla = true },
    },
    [28] = {
        title = { it = "Prova del lago", enHash = "b04a9dfd", vanilla = true },
        text = { it = "Per la tua prima prova, cerca nelle profondità del Lake Elune'ara uno Shrine Bauble. Si deteriora in fretta, quindi portalo subito allo Shrine of Remulos. Usa il ninnolo al santuario, poi parla con Tajarri, che si trova lì; è una delle guardiane più fidate di Moonglade.\n\nHai solo un tempo limitato per completare il compito, e potresti trovarti in competizione con altri druidi che cercano anche loro dei ninnoli. L'agilità mentale e fisica sarà fondamentale per la tua riuscita.\n\nBuona fortuna, $N.", enHash = "4b39d627", vanilla = true },
        objectives = { it = "Trova uno Shrine Bauble nel Lake Elune'ara e portalo allo Shrine of Remulos, nella parte nord-occidentale di Moonglade. Una volta lì, usa lo Shrine Bauble.\n\nPoi, per completare la prova, devi parlare con Tajarri al santuario.", enHash = "824237b8", vanilla = true },
        progress = { it = "Per completare la Prova del Lago devi usare lo Shrine Bauble entro i confini di questo santuario. Finché non lo farai, la tua prova resterà incompiuta e rischierà di fallire.", enHash = "007d94da", vanilla = true },
        reward = { it = "Bene, bene, sembra che $Gun altro druido:un'altra druida; abbia superato la Prova del Lago! Ben fatto, $Gmio giovane amico:mia giovane amica; — ben fatto.\n\nCome ho detto, mi chiamo Tajarri. È mio dovere e mio privilegio fare da guardiana a Moonglade, e in particolare a questo santuario. Keeper Remulos guida il Cenarion Circle nella salvaguardia della natura e dell'equilibrio, e il suo santuario ne è un tributo duraturo. Usare il ninnolo qui è un modo di riconoscere l'importanza di questo luogo per il Circle.", enHash = "99c9d444", vanilla = true },
    },
    [29] = {
        title = { it = "Prova del lago", enHash = "b04a9dfd", vanilla = true },
        text = { it = "Per la tua prima prova, cerca nelle profondità del Lake Elune'ara uno Shrine Bauble. Si deteriora in fretta, quindi portalo subito allo Shrine of Remulos. Usa il ninnolo al santuario, poi parla con Tajarri, che si trova lì; è una delle guardiane più fidate di Moonglade.\n\nHai solo un tempo limitato per completare il compito, e potresti trovarti in competizione con altri druidi che cercano anche loro dei ninnoli. L'agilità mentale e fisica sarà fondamentale per la tua riuscita.\n\nBuona fortuna, $N.", enHash = "4b39d627", vanilla = true },
        objectives = { it = "Trova uno Shrine Bauble nel Lake Elune'ara e portalo allo Shrine of Remulos, nella parte nord-occidentale di Moonglade. Una volta lì, usa lo Shrine Bauble.\n\nPoi, per completare la prova, devi parlare con Tajarri al santuario.", enHash = "824237b8", vanilla = true },
        progress = { it = "Per completare la Prova del Lago devi usare lo Shrine Bauble entro i confini di questo santuario. Finché non lo farai, la tua prova resterà incompiuta e rischierà di fallire.", enHash = "007d94da", vanilla = true },
        reward = { it = "Bene, bene, sembra che $Gun altro druido:un'altra druida; abbia superato la Prova del Lago! Ben fatto, $Gmio giovane amico:mia giovane amica; — ben fatto.\n\nCome ho detto, mi chiamo Tajarri. È mio dovere e mio privilegio fare da guardiana a Moonglade, e in particolare a questo santuario. Keeper Remulos guida il Cenarion Circle nella salvaguardia della natura e dell'equilibrio, e il suo santuario ne è un tributo duraturo. Usare il ninnolo qui è un modo di riconoscere l'importanza di questo luogo per il Circle.", enHash = "99c9d444", vanilla = true },
    },
    [30] = {
        title = { it = "Prova del leone marino", enHash = "c3b862bb", vanilla = true },
        text = { it = "Per la seconda prova ti serviranno le due metà che formano il Pendant of the Sea Lion. Una metà trae potere dall'agilità dell'aspetto del leone marino, che scivola nell'acqua; l'altra trae potere dall'incredibile resistenza dell'aspetto del leone marino. I druidi attingono in egual misura a entrambe queste qualità per incarnare l'aspetto della loro Aquatic Form.\n\nParla con gli abitanti di Moonglade per scoprire dove potrebbero trovarsi le due parti, e portale entrambe qui per unirle. Una volta formato il pendente, portalo a Dendrite Starblaze.", enHash = "5730c00d", vanilla = true },
        objectives = { it = "Trova l'Half Pendant of Aquatic Agility e l'Half Pendant of Aquatic Endurance. Parla con gli abitanti di Moonglade per avere indizi su dove possano trovarsi questi oggetti.\n\nForma il Pendant of the Sea Lion unendo le due metà del pendente. Per farlo devi trovarti vicino allo Shrine of Remulos.\n\nPorta il pendente completo a Dendrite Starblaze, nel villaggio di Nighthaven, a Moonglade.", enHash = "e8106a8e", vanilla = true },
        progress = { it = "Hai formato il pendente da farmi esaminare, $N? Se ti serve aiuto per trovare le parti, prova a chiedere informazioni alla gente del posto. Non solo troverai ciò che cerchi, ma avrai anche un motivo per esplorare questa radura meravigliosa e sacra.", enHash = "6d3f31a0", vanilla = true },
        reward = { it = "Hai completato la Prova del Leone Marino, $N — congratulazioni.\n\nOgni passo per ottenere il pendente dimostra che agilità e resistenza sono entrambe necessarie per agire in armonia con ciò che desideri fare sott'acqua. Nessuna delle due può esistere senza l'altra, ed entrambe sono impossibili senza la tua disponibilità a fare tuo l'aspetto del leone marino.\n\nRicorda bene queste lezioni: ti serviranno quando avrai ottenuto la tua Aquatic Form.", enHash = "ccb078b3", vanilla = true },
    },
    [31] = {
        title = { it = "Aquatic Form", enHash = "e61ab7d2", vanilla = true },
        text = { it = "Hai completato le lezioni che tutti i giovani druidi devono imparare prima di poter assumere un aspetto acquatico. Ora torna dal tuo istruttore, Turak Runetotem, a Thunder Bluff. Mostragli il tuo pendente e dimostragli che sei $Gpronto:pronta; a imparare ciò che ha da insegnarti. Completerà il tuo addestramento, permettendoti di diventare una cosa sola con l'acqua.\n\nArrivederci, giovane $Gdruido:druida;. Parleremo ancora.", enHash = "ed08fdba", vanilla = true },
        objectives = { it = "Torna a Thunder Bluff e mostra il Pendant of the Sea Lion a Turak Runetotem.", enHash = "cbff602e", vanilla = true },
        progress = { it = "La notizia del tuo ritorno a Thunder Bluff ti ha preceduto, ma mi servirà una prova delle lezioni che hai imparato a Moonglade prima di insegnarti la tua Aquatic Form.\n\nHai il Pendant of the Sea Lion?", enHash = "1be073cf", vanilla = true },
        reward = { it = "Davvero notevole, $N. I tuoi antenati sarebbero fieri dei tuoi progressi! Sei $Gpronto:pronta; a imparare la tua Aquatic Form, ed è un piacere per me insegnartela.\n\nInoltre, in riconoscimento di quanto hai fatto nelle due prove, ti do questo oggetto. Spero che sia un'aggiunta gradita al tuo equipaggiamento di $Gprotettore:protettrice; della natura e custode dell'equilibrio.", enHash = "9d2b101a", vanilla = true },
    },
    [33] = {
        title = { it = "Lupi oltre il confine", enHash = "5feaa36c" },
        text = { it = "Odio quei maledetti Timber Wolf! Però le bistecche di lupo mi piacciono proprio... Portami della Tough Wolf Meat e te la scambierò con qualcosa che ti tornerà utile.\n\nLa Tough Wolf Meat si ottiene cacciando i Timber Wolf e gli Young Wolf che vagano per le campagne di Northshire.", enHash = "f102f4e3" },
        objectives = { it = "Porta 8 pezzi di Tough Wolf Meat a Eagan Peltskinner, fuori dalla Northshire Abbey.", enHash = "a1314bc0" },
        progress = { it = "Ehi, $N. Comincio ad avere fame... hai preso quella Tough Wolf Meat?", enHash = "c1cfa904" },
        reward = { it = "Hai lavorato sodo! Non vedo l'ora di cucinare quella carne di lupo...\n\nHo qui alcune cose che potrebbero interessarti: scegli pure!", enHash = "471b5da3" },
    },
    [34] = {
        title = { it = "Un ospite sgradito", enHash = "45d34bae", vanilla = true },
        text = { it = "Un'altra volta il mio giardino è stato calpestato e saccheggiato. E so bene chi è il bruto che lo fa. È quel maledetto cinghiale, quello che Marshal Marris ha preso a chiamare Bellygrub.\n\nAdesso non potrò ripiantare i narcisi fino alla prossima stagione. Rovinati! Tutti rovinati da quell'unico cinghiale molesto. Metti fine a quella peste! Mostrami la sua zanna e sarò felice di ricompensarti. Sembra che passi il tempo a razzolare nel campo a sud-ovest di Lakeshire, ma ogni tanto se ne viene fin qui e mi entra in giardino.", enHash = "844c21b3", vanilla = true },
        objectives = { it = "Martie Jainrose di Lakeshire vuole che tu uccida Bellygrub. Portale la sua zanna come prova.", enHash = "810e081d", vanilla = true },
        progress = { it = "Bellygrub sta ancora facendo dei suoi, o sei $Griuscito:riuscita; a liberare Lakeshire da quella peste una volta per tutte?", enHash = "59858d86", vanilla = true },
        reward = { it = "Finalmente la minaccia è sepolta! Grazie, $N, mi hai reso un gran servizio. Questa stagione il giardino sarà in piena fioritura!", enHash = "20e7f756", vanilla = true },
    },
    [35] = {
        title = { it = "Altre preoccupazioni", enHash = "a670804f" },
        text = { it = "Se temi che le voci sui murloc siano vere, allora fai così — va' al ponte a est di Elwynn e parla con Guard Thomas. È di stanza al ponte da una settimana e saprà com'è la situazione della zona.\n\nPortami il suo rapporto.", enHash = "a543a87d" },
        objectives = { it = "Marshal Dughan vuole che tu parli con Guard Thomas.", enHash = "724858eb" },
        reward = { it = "Sì, i murloc si sono insediati nei torrenti di Elwynn est e tutt'intorno. Non sappiamo perché siano qui, ma sono aggressivi e almeno in parte intelligenti.", enHash = "78bcb0e3" },
    },
    [36] = {
        title = { it = "Westfall Stew", enHash = "f6fd6789", vanilla = true },
        text = { it = "Non avrei mai pensato che sarebbe arrivato il giorno in cui avrei lasciato la fattoria. Ma i campi sono invasi dai ladri ed è diventato troppo pericoloso per noi qui. Appena Farmer Furlbrow avrà riparato il carro, ci metteremo in viaggio. \n \nMagari potresti farmi un favore? Lascia che butti giù la mia ricetta per la Westfall Stew. Ti prego, portala a Salma Saldean, alla fattoria laggiù. La fattoria dei Saldean è appena oltre il bivio.", enHash = "c645208e", vanilla = true },
        objectives = { it = "Verna Furlbrow vuole che tu consegni la sua ricetta per la Westfall Stew a Salma Saldean.", enHash = "00ab46cd", vanilla = true },
        progress = { it = "Mi mancherà tanto quella Verna Furlbrow. Non è che per caso l'hai vista venendo qui?", enHash = "b50a11bc", vanilla = true },
        reward = { it = "Quella Verna è sempre stata una ragazza così dolce. Ci mancherà qui a Westfall ma, detto tra noi, in fondo è una ragazza di città e Stormwind le starà benissimo. Ma basta pettegolezzi! Ora possiamo fare la Westfall Stew!", enHash = "a8ca14b8", vanilla = true },
    },
    [37] = {
        title = { it = "Trova le guardie scomparse", enHash = "16523154" },
        text = { it = "Qualche giorno fa abbiamo mandato due guardie, Rolf e Malakai, a indagare lungo il fiume, e non sono ancora tornate. Per completare il mio rapporto devo sapere cosa è successo a quegli uomini.\n\nVa' a nord lungo il fiume e trova le guardie... o quel che ne resta.", enHash = "119a6eee" },
        objectives = { it = "Guard Thomas vuole che tu vada a nord lungo il fiume e cerchi le due guardie scomparse, Rolf e Malakai.", enHash = "f0bd9bd4" },
        reward = { it = "Il cadavere è stato in gran parte spogliato, ma lì vicino, tra le cose sparse, c'è un medaglione con incise le parole: \"Footman Malakai Stone\".", enHash = "7fcd14f8" },
    },
    [38] = {
        title = { it = "Westfall Stew", enHash = "f6fd6789", vanilla = true },
        text = { it = "Aiutami a preparare un po' di Westfall Stew! Torna con questi ingredienti: \n \n 3 Stringy Vulture Meat \n 3 Goretusk Snout \n 3 Murloc Eye \n 3 Okra", enHash = "2ac060f9", vanilla = true },
        objectives = { it = "Salma Saldean vuole 3 Stringy Vulture Meat, 3 Goretusk Snout, 3 Murloc Eye, 3 Okra.", enHash = "f7e5d614", vanilla = true },
        progress = { it = "Torna con questi ingredienti: \n \n 3 Stringy Vulture Meat \n 3 Goretusk Snout \n 3 Murloc Eye \n 3 Okra", enHash = "b3321f34", vanilla = true },
        reward = { it = "Quell'Okra addenserà per bene questo brodo! Ora aggiungiamo la Stringy Vulture Meat, qualche Murloc Eye e quei deliziosi Goretusk Snout. E abbiamo finito! Per tutto il tuo aiuto, $N, voglio che tu prenda la prima pentola di Westfall Stew di oggi!", enHash = "0ac04873", vanilla = true },
    },
    [39] = {
        title = { it = "Consegna il rapporto di Thomas", enHash = "10774eac" },
        text = { it = "Riferisci a Marshal Dughan della morte di Malakai e Rolf, e digli che i murloc di Elwynn est non possono essere contenuti con le truppe che abbiamo qui.\n\nSo che non abbiamo molte truppe da mandare, ma spero che Dughan trovi qualcuno.", enHash = "8192eab0" },
        objectives = { it = "Fai rapporto a Marshal Dughan, a Goldshire.", enHash = "431873bc" },
        reward = { it = "Mmh, sono notizie preoccupanti. Le nostre difese sono già ridotte all'osso, e perdere Rolf e Malakai per colpa di quei murloc ci mette in una posizione ancora peggiore.\n\nSe le cose non migliorano, entro fine settimana si combatterà a Goldshire!", enHash = "f2909dea" },
    },
    [40] = {
        title = { it = "Un pericolo che sa di pesce", enHash = "e717da02" },
        text = { it = "$N, c'è una nuova minaccia nell'Elwynn Forest! I murloc stanno risalendo a nuoto i torrenti di Elwynn est, spaventano i pesci e attaccano la brava gente!\n\nHo avvisato Marshal Dughan, ma lui è più preoccupato per gli gnoll e i banditi. Non è convinto che i murloc siano un pericolo.\n\nTi prego, $N, parla con Dughan e convincilo a mandare più truppe a est!", enHash = "fe9842d3" },
        objectives = { it = "Remy \"Two Times\" vuole che tu parli con Marshal Dughan, a Goldshire.", enHash = "c97aa377" },
        reward = { it = "Sì, ho parlato con Remy. Lo rispetto come mercante, ma tutte le segnalazioni di murloc a est sono state a dir poco vaghe.\n\nHo preso nota delle tue preoccupazioni, ma finché non ricevo un rapporto militare su una minaccia murloc, non possiamo permetterci di mandare altre truppe a est.", enHash = "c8baf063" },
    },
    [45] = {
        title = { it = "Scopri la sorte di Rolf", enHash = "d74d08d2" },
        text = { it = "Continuando a cercare nella zona, trovi impronte palmate che portano a est lungo la riva dello Stone Cairn Lake. In lontananza, a est, si intravede a malapena un villaggio di murloc.\n\nForse la sorte di Rolf si è compiuta là...", enHash = "07d6f595" },
        objectives = { it = "Cerca Rolf nel villaggio dei murloc, o i segni della sua morte.", enHash = "e04430c3" },
        reward = { it = "Al collo del cadavere trovi un medaglione di metallo con incise le parole \"Footman Rolf Hartford\".", enHash = "e3e48d7c" },
    },
    [46] = {
        title = { it = "Taglia sui murloc", enHash = "1253a951", vanilla = true },
        text = { it = "L'esercito di Stormwind ha messo una taglia sui Murloc Lurker e sui Murloc Forager di Elwynn. Massacrali e portami le loro Torn Murloc Fin, e l'esercito di Stormwind ti ricompenserà bene.\n\nI murloc hanno costruito un villaggio allo Stone Cairn Lake a nord di qui, e un altro a sud, dove il torrente si biforca.", enHash = "e718af7f", vanilla = true },
        objectives = { it = "Porta 8 Torn Murloc Fin a Guard Thomas, al ponte a est di Elwynn.", enHash = "fa24c752", vanilla = true },
        progress = { it = "Come va la caccia, $N?", enHash = "4dab737b", vanilla = true },
        reward = { it = "Hai le pinne? Ottimo! Marshal Dughan è in ansia per la situazione dei murloc a Elwynn est, e vorrei potergli dire che sta tornando sotto controllo.\n\nQuello che hai fatto ha aiutato a renderlo possibile.", enHash = "359d9b5d", vanilla = true },
    },
    [47] = {
        title = { it = "Scambio di Gold Dust", enHash = "d1dba811" },
        text = { it = "I kobold di queste parti a volte si portano addosso della Gold Dust. Mi farebbe proprio comodo — portamene un po' e ti faccio il miglior prezzo della città... il miglior prezzo della città!\n\nI kobold li trovi nella Fargodeep Mine a sud, e intorno alla Jasperlode Mine a nord-est.", enHash = "58603cd5" },
        objectives = { it = "Porta 10 Gold Dust a Remy \"Two Times\", a Goldshire. La Gold Dust si raccoglie dai kobold dell'Elwynn Forest.", enHash = "ecd9eefe" },
        progress = { it = "Psst! Ce l'hai quella Gold Dust per me... per me?", enHash = "57ab449e" },
        reward = { it = "Grazie per la polvere, $N. Ecco i tuoi soldi e... ecco un gettone da parte di certi miei soci. Potrebbe tornarti utile... utile.", enHash = "c1628f93" },
    },
    [48] = {
        title = { it = "Dolce ambra", enHash = "202e3fb3", vanilla = true },
        text = { it = "Nella terra a sud, dove i tralci si torcono e strisciano,\nc'è un pozzo nascosto, dove acque profonde scorrono.\nPura come la sacra Figlia della Luce,\nportami ora un po' di Holy Spring Water.", enHash = "34648c8e", vanilla = true },
        objectives = { it = "Porta dell'Holy Spring Water a Grimbooze Thunderbrew.", enHash = "b7a88a11", vanilla = true },
        progress = { it = "Hic! Oh oh! Vuoi il bis?\n\nNella terra a sud, dove i tralci si torcono e strisciano,\nc'è un pozzo nascosto, dove acque profonde scorrono.\nPura come la sacra Figlia della Luce,\nportami ora un po' di Holy Spring Water.", enHash = "f785d817", vanilla = true },
        reward = { it = "Hic! Oh oh!", enHash = "5fef6dbc", vanilla = true },
    },
    [49] = {
        title = { it = "Dolce ambra", enHash = "202e3fb3", vanilla = true },
        text = { it = "L'ambra è il colore del più lungo amore della mia vita,\ncome le ultime braci del tramonto nel cielo lassù.\nProcurami, perché il mio amore possa nascere,\nun sacco per tipo: orzo, segale e mais.", enHash = "ee0b977b", vanilla = true },
        objectives = { it = "Grimbooze Thunderbrew vuole un Sack of Barley, un Sack of Rye e un Sack of Corn.", enHash = "676cc727", vanilla = true },
        progress = { it = "Il bis? Ma certo!\n\nL'ambra è il colore del più lungo amore della mia vita,\ncome le ultime braci del tramonto nel cielo lassù.\nProcurami, perché il mio amore possa nascere,\nun sacco per tipo: orzo, segale e mais.", enHash = "58b012bc", vanilla = true },
        reward = { it = "Hic! Oh oh!", enHash = "5fef6dbc", vanilla = true },
    },
    [50] = {
        title = { it = "Dolce ambra", enHash = "202e3fb3", vanilla = true },
        text = { it = "Mescolerò e mescolerò finché avremo il mosto,\ne sarà la nostra scorta privata, ben nascosta.\nUn alambicco va forgiato con un metallo forte:\nportami del Truesilver per finire questa canzone.", enHash = "9439fa7f", vanilla = true },
        objectives = { it = "Grimbooze Thunderbrew vuole del Truesilver.", enHash = "43a1b95a", vanilla = true },
        progress = { it = "Un bis per te? Ma certo, $Gamico:amica;!\n\nMescolerò e mescolerò finché avremo il mosto,\ne sarà la nostra scorta privata, ben nascosta.\nUn alambicco va forgiato con un metallo forte:\nportami del Truesilver per finire questa canzone.", enHash = "83dbe011", vanilla = true },
        reward = { it = "Hic! Oh oh!", enHash = "5fef6dbc", vanilla = true },
    },
    [51] = {
        title = { it = "Dolce ambra", enHash = "202e3fb3", vanilla = true },
        text = { it = "Non ancora filtrato, ma appena distillato,\ncome terra non seminata che attende, già arata.\nOra preparerò il nostro mucchio di carbone:\nportami un ramo di sicomoro, è la tua prossima missione.", enHash = "f7b159c1", vanilla = true },
        objectives = { it = "Porta un Sycamore Branch a Grimbooze Thunderbrew.", enHash = "5ca50bcb", vanilla = true },
        progress = { it = "Un bis? Per te, questo e altro!\n\nNon ancora filtrato, ma appena distillato,\ncome terra non seminata che attende, già arata.\nOra preparerò il nostro mucchio di carbone:\nportami un ramo di sicomoro, è la tua prossima missione.", enHash = "7ef354f8", vanilla = true },
        reward = { it = "Hic! Oh oh!", enHash = "5fef6dbc", vanilla = true },
    },
    [52] = {
        title = { it = "Proteggi la frontiera", enHash = "35096c8d" },
        text = { it = "Salute, $N. Gli animali selvatici diventano sempre più aggressivi via via che ci si allontana da Goldshire, e l'Eastvale Logging Camp subisce attacchi quasi continui di lupi e orsi!\n\nQui il tuo aiuto ci farebbe comodo.", enHash = "4b547d7b" },
        objectives = { it = "Uccidi 8 Prowler e 5 Young Forest Bear, poi torna da Guard Thomas, al ponte a est di Elwynn.", enHash = "94c5d225" },
        progress = { it = "Hai ucciso quei lupi e quegli orsi?", enHash = "9d3a00bc", vanilla = true },
        reward = { it = "Grazie mille dell'aiuto, $N. Dev'esserci qualcosa nella foresta che rende questi animali così audaci.\n\nQualunque cosa sia, spero che ci resti.", enHash = "48bd7f84", vanilla = true },
    },
    [53] = {
        title = { it = "Dolce ambra", enHash = "202e3fb3", vanilla = true },
        text = { it = "Un liquido dolce, limpido come le lacrime di un bambino,\ncol passare degli anni si fa di un bell'ambra profondo.\nMa prima di ubriacarci fino in fondo,\nva costruita una botte di quercia carbonizzata.", enHash = "7832ecad", vanilla = true },
        objectives = { it = "Porta a Grimbooze Thunderbrew un fascio di Charred Oak.", enHash = "7796c44e", vanilla = true },
        progress = { it = "Certo che te la ricanto, $Gamico:amica;!\n\nUn liquido dolce, limpido come le lacrime di un bambino,\ncol passare degli anni si fa di un bell'ambra profondo.\nMa prima di ubriacarci fino in fondo,\nva costruita una botte di quercia carbonizzata.", enHash = "4a9eec49", vanilla = true },
        reward = { it = "Invecchiato nella botte, filtrato nel carbone,\nti passa sulle labbra e dritto nell'anima scende.\nAllora beviamo, facciamo un brindisi a te,\ne già che ci siamo a me, Grimbooze Thunderbrew!", enHash = "df0a29fe", vanilla = true },
    },
    [54] = {
        title = { it = "Presentati a Goldshire", enHash = "b1e04d8e" },
        text = { it = "$N, sei $Gun:una; $C che ha dimostrato di tenere alla sicurezza di Northshire. D'ora in poi ti occuperai della protezione dell'Elwynn Forest che la circonda.\n\nSe accetti questo incarico, ho preparato dei documenti da consegnare a Marshal Dughan, a Goldshire. Goldshire si trova lungo la strada a sud, oltre i cancelli di confine.", enHash = "547ca639" },
        objectives = { it = "Porta i Marshal McBride's Documents a Marshal Dughan, a Goldshire.", enHash = "ac81c235" },
        progress = { it = "Hai notizie da McBride? Northshire è un giardino in confronto all'Elwynn Forest, ma mi chiedo cosa abbia da riferire Marshal McBride.\n\nEcco, dammi i suoi documenti...", enHash = "51f2e698" },
        reward = { it = "Bene, qui dice che ti è stato conferito lo status di vicesceriffo facente funzione presso i Marshal di Stormwind. Congratulazioni.\n\nE buona fortuna: tenere al sicuro Elwynn non è una passeggiata... con quasi tutto l'esercito occupato a fare chissà cosa per chissà quale nobile!\n\nÈ difficile stare dietro alla politica in questi giorni bui...", enHash = "92e06770" },
    },
    [55] = {
        title = { it = "Morbent Fel", enHash = "bce1f746", vanilla = true },
        text = { it = "Morbent Fel si nasconde nella sua tana, la casa appollaiata in cima alla collina a est, che domina il cimitero di Raven Hill. Il suo tempo in questa terra sta per finire...\n\nUsa Morbent's Bane contro di lui. Renderà impotenti le sue magie protettive.\n\nUccidilo. Uccidilo, e salvaci dalla sua malvagità. Sii lo strumento della mia vendetta, e $Gun eroe:un'eroina; di Duskwood!", enHash = "18ea6cd3", vanilla = true },
        objectives = { it = "Usa Morbent's Bane su Morbent Fel, uccidi Morbent Fel, poi riporta Morbent's Bane a Sven, al suo accampamento.", enHash = "2fe6c73c", vanilla = true },
        progress = { it = "Morbent Fel è stato sconfitto?!", enHash = "c7428524", vanilla = true },
        reward = { it = "Morbent Fel è stato sconfitto. I Dark Rider sono ancora in libertà, ma una piccola parte di quel che speravo oltre ogni speranza si è avverata.\n\nHai fatto l'impossibile, e le tue imprese vivranno per sempre nelle leggende di Duskwood.\n\nVa', $N. E forse, un giorno, il destino ti riporterà da me...", enHash = "0e231bb1", vanilla = true },
    },
    [56] = {
        title = { it = "La Guardia Notturna", enHash = "c67c1598", vanilla = true },
        text = { it = "Come comandante della Guardia Notturna, ho giurato di proteggere i cittadini di Darkshire. Stormwind ha ritirato le guardie che aveva di stanza qui, lasciandoci a cavarcela da soli.\n\nSe ti senti all'altezza del compito, ci serve il tuo aiuto! Aiuta la Guardia Notturna spingendoti nei Tranquil Gardens, appena a sud di Darkshire, e uccidendo 8 Skeletal Warrior e 6 Skeletal Mage. La minaccia dei non morti va fermata!", enHash = "309e3cb8", vanilla = true },
        objectives = { it = "Commander Althea Ebonlocke di Darkshire vuole che tu uccida 8 Skeletal Warrior e 6 Skeletal Mage.", enHash = "5f91467d", vanilla = true },
        progress = { it = "Vedo che sei $Gtornato:tornata;, $N. Se vuoi dimostrare di essere utile alla Guardia Notturna, torna da me quando avrai ucciso 8 Skeletal Warrior e 6 Skeletal Mage.", enHash = "ae4028d1", vanilla = true },
        reward = { it = "Ottimo, $N. Per il servizio reso alla gente di Darkshire sarai $Gricompensato:ricompensata;.", enHash = "1900781b", vanilla = true },
    },
    [57] = {
        title = { it = "La Guardia Notturna", enHash = "c67c1598", vanilla = true },
        text = { it = "$N, mi arrivano segnalazioni di un'infestazione di non morti nella foresta! Se te la senti, va' al cimitero di Raven Hill e uccidi 15 di quegli immondi Skeletal Fiend e 15 Skeletal Horror. Ci sono segnalazioni di scheletri anche appena a sud di Darkshire, dentro e intorno al Tranquil Gardens Cemetery. I non morti vanno cacciati da Duskwood!", enHash = "30279eba", vanilla = true },
        objectives = { it = "Commander Althea Ebonlocke di Darkshire vuole che tu uccida 15 Skeletal Fiend e 15 Skeletal Horror.", enHash = "6ce9fdbf", vanilla = true },
        progress = { it = "Torna da me quando avrai ucciso 15 Skeletal Fiend e 15 Skeletal Horror, $N.", enHash = "a8a82d9d", vanilla = true },
        reward = { it = "La gente di Darkshire ti ringrazia, $N. Hai dimostrato di essere $Gun grande alleato:una grande alleata; della Guardia Notturna.", enHash = "135355ee", vanilla = true },
    },
    [58] = {
        title = { it = "La Guardia Notturna", enHash = "c67c1598", vanilla = true },
        text = { it = "La situazione a Raven Hill è ancora grave. La sicurezza di Darkshire è nelle tue mani, $N. Non ho abbastanza Watcher per tenere il paese al sicuro. Devi partire ancora una volta per Raven Hill e liberare il mausoleo orientale da 20 Plague Spreader!", enHash = "5049dfd1", vanilla = true },
        objectives = { it = "Commander Althea Ebonlocke di Darkshire vuole che tu uccida 20 Plague Spreader nel mausoleo orientale di Raven Hill.", enHash = "8d842796", vanilla = true },
        progress = { it = "Mi serve il tuo aiuto, $N. Va' al cimitero a nord-ovest e libera il mausoleo orientale da 20 Plague Spreader.\n\nTorna da me quando avrai finito.", enHash = "ced7d619", vanilla = true },
        reward = { it = "A nome della gente di Darkshire e come capo della Guardia Notturna, ti ringrazio, $N, per il tuo coraggio e la tua dedizione. Che la Luce illumini il tuo cammino.", enHash = "d0a4d8b4", vanilla = true },
    },
    [59] = {
        title = { it = "Armature di stoffa e di cuoio", enHash = "95cb5779" },
        text = { it = "Per il tuo acume e il tuo valore, ho qui un buono che vale un pezzo d'armatura. Voglio che tu lo porti a Sara Timberlain, all'Eastvale Logging Camp. Dalle il buono e ti confezionerà l'armatura. E quando l'avrai ricevuta, $N, usala in difesa di Elwynn.\n\nL'Eastvale Logging Camp è oltre la postazione di Guard Thomas, a est.", enHash = "3bdba907" },
        objectives = { it = "Dai lo Stormwind Armor Marker a Sara Timberlain.", enHash = "6923c25a" },
        progress = { it = "L'esercito di Stormwind mi ha incaricata di fornire ai suoi uomini armature di stoffa e di cuoio.\n\nSe hai un buono per me, ti farò volentieri qualcosa.", enHash = "eb8415e9", vanilla = true },
        reward = { it = "Ah, grazie per il buono. Prendi pure l'armatura che preferisci.\n\nBuona fortuna, $Gvaloroso:valorosa; $C. E che questa armatura ti serva bene.", enHash = "bc0a72d9", vanilla = true },
    },
    [60] = {
        title = { it = "Candele dei kobold", enHash = "6a56c7cf" },
        text = { it = "Salve, $Gbuon signore:buona signora;! Hai un momento?\n\nIo e mio fratello abbiamo una bottega da speziale a Stormwind, e sono qui a raccogliere Large Candle per la cera. Puoi aiutarmi?\n\nLe Large Candle si prendono dai kobold, e girano voci che i kobold stiano infestando le miniere di Elwynn... la Fargodeep Mine a sud e la Jasperlode Mine a est. Ti consiglio di cercare le candele in uno di quei posti.", enHash = { "87b5f3e1", "3a911fc8" } },
        objectives = { it = "Porta 8 Large Candle a William Pestle, a Goldshire.", enHash = "06749ade" },
        progress = { it = "Hai già raccolto quelle candele?", enHash = "16392a07" },
        reward = { it = "Eri $Gimpegnato:impegnata; a cacciare kobold, eh? Grazie per le candele, $N, ed ecco la tua ricompensa...", enHash = "ace23897" },
    },
    [61] = {
        title = { it = "Consegna a Stormwind", enHash = "3362e9d2" },
        text = { it = "Mio fratello Morgan aspetta a Stormwind il mio carico di candele. Non ho abbastanza tempo per fare il viaggio di persona, ma se ti va di portargli tu il carico, ti pagherà bene.\n\nHo già impacchettato le candele, e Morgan lo trovi nella nostra bottega, la Pestle's Apothecary, nello Stormwind Trade District.", enHash = "6ef52340" },
        objectives = { it = "Porta William's Shipment a Morgan Pestle, nello Stormwind Trade District.", enHash = "98a6a6fe" },
        progress = { it = "Oh, un carico da parte di mio fratello? Splendido! Oggi la fortuna mi sorride davvero!", enHash = "7c21a981" },
        reward = { it = "Ecco il tuo pagamento... e già che sei qui, dai un'occhiata in giro! Di sicuro abbiamo una pozione o qualche altro ninnolo che ti tornerebbe utile.", enHash = "104bd1b0" },
    },
    [62] = {
        title = { it = "La Fargodeep Mine", enHash = "368e2b37" },
        text = { it = "La miniera di Northshire non è l'unica ad avere problemi! Mi arrivano rapporti che anche la Fargodeep Mine, a Elwynn, è diventata un rifugio per i kobold.\n\nEsplora la miniera, conferma questi rapporti e poi torna da me. La miniera è quasi esattamente a sud di Goldshire, tra i poderi degli Stonefield e dei Maclure.", enHash = "507a1bcc" },
        objectives = { it = "Esplora la Fargodeep Mine, poi torna da Marshal Dughan, a Goldshire.", enHash = "5420a9c3" },
        progress = { it = "Cos'hai da riferire, $N? Sei $Gstato:stata; alla Fargodeep Mine?", enHash = "17f6fbe4", vanilla = true },
        reward = { it = "Brutte notizie. E adesso cosa, i draghi?!? Dovremo aumentare le pattuglie vicino a quella miniera. Grazie del tuo impegno, $N. E aspetta un momento... potrei avere un altro incarico per te.", enHash = "237f7522" },
    },
    [63] = {
        title = { it = "Il richiamo dell'acqua", enHash = "eab41910", vanilla = true },
        text = { it = "Lungo la costa di Silverpine, a ovest del Sepulcher, troverai un santuario che la piaga ha corrotto. Gli spiriti che ci sono non parlano più al nostro popolo, e toccherà a te sconfiggere la manifestazione e purificare la pozza.\n\nPrendi i bracciali dell'elementale, insieme alle gocce rimaste della pozione di Brine, e mettili sul braciere. Il rituale dovrebbe bastare a evocare uno spirito puro con cui potrai comunicare.\n\nPortami la prova che il compito è stato svolto, e ti ricompenserò con il tuo totem.", enHash = "7a8b87e8", vanilla = true },
        objectives = { it = "Sconfiggi la Corrupt Manifestation of Water e metti i Corrupted Manifestation's Bracers insieme alle Remaining Drops of Purest Water sul Brazier of Everfount, nella Silverpine Forest.", enHash = "a9e17d0c", vanilla = true },
        progress = { it = "Il braciere riflette ancora la luce dei dintorni, e la fiamma si sposta leggermente mentre ti avvicini.\n\nLa corruzione sulle colline sembra essersi tenuta a distanza, e a parte i componenti mancanti il braciere sembra pronto per il rituale che evocherà una manifestazione purificata dell'acqua.", enHash = "d4517d19", vanilla = true },
        reward = { it = "Metti i bracciali sul braciere, poi versi nella fiamma le gocce rimaste della pozione di Brine. Le gocce crepitano quando toccano la fiamma, e cominci a recitare le semplici parole che ti ha insegnato Islen...", enHash = "43d3ac09", vanilla = true },
    },
    [64] = {
        title = { it = "Il cimelio dimenticato", enHash = "9a3b01dc", vanilla = true },
        text = { it = "È stato orribile! Verna mi ha svegliato quando ha sentito un baccano nei campi. I campi erano pieni di teppisti. Siamo partiti di corsa e mi sono dimenticato di prendere il mio orologio da taschino. Me l'aveva dato il padre di Verna il giorno delle nozze, e mi si stringe lo stomaco a sapere che ce l'hanno quei ladri. L'orologio l'ho lasciato nell'armadio della casa colonica. Cerca il campo di zucche a ovest: non puoi sbagliarti. Se me lo riporti, ti sarò davvero grato!", enHash = "939697cc", vanilla = true },
        objectives = { it = "Farmer Furlbrow vuole che tu recuperi il suo orologio da taschino dall'armadio della sua casa colonica, alla fattoria delle zucche a ovest.", enHash = "86dc30d3", vanilla = true },
        progress = { it = "Non è che sei $Griuscito:riuscita; a recuperare il mio orologio?", enHash = "5e80cf2e", vanilla = true },
        reward = { it = "Il mio orologio! Grazie mille, gentile $Gsignore:signora;!\n\nSiamo solo poveri contadini e abbiamo perso la nostra terra, ma ti prego, accetta questa ricompensa come segno della nostra riconoscenza.", enHash = { "cff1643e", "95ff3948" }, vanilla = true },
    },
    [65] = {
        title = { it = "La Defias Brotherhood", enHash = "86683501", vanilla = true },
        text = { it = "La banda di miserabili responsabile di aver cacciato la brava gente di Westfall da questa terra si fa chiamare Defias Brotherhood. Ho bisogno che tu ti infiltri in questo clan di teppisti. Dobbiamo sapere chi è a capo del cartello e dove si nascondono. A Lakeshire, nella locanda, c'è un ladro di nome Wiley che mi deve un favore.\n\nVa' a Lakeshire, nelle Redridge Mountains a est di Elwynn, e scopri quello che puoi.", enHash = "ec93460d", vanilla = true },
        objectives = { it = "Gryan Stoutmantle vuole che tu parli con Wiley, a Lakeshire.", enHash = "4b9cef0c", vanilla = true },
        reward = { it = "Quindi ti manda Stoutmantle? Be', ho un debito con lui.", enHash = "64f24276", vanilla = true },
    },
    [66] = {
        title = { it = "La leggenda di Stalvan", enHash = "73f3d412", vanilla = true },
        text = { it = "Ieri notte un disturbo orribile mi ha percorso le vene. Ho sentito che mia nipote, Alyssa, era in grave pericolo. Ho consultato le carte e la Morte mi ha fissata dal tavolo.\n\nDopo un lungo viaggio attraverso una trance oscura sono riuscita a scoprire un indizio su questo mistero terrificante. Mi è venuto un nome, il nome di Stalvan.\n\nCerca il cancelliere al Town Hall e vedi se riesci a scoprire di più su questo tizio. Temo per tutti noi.", enHash = "aec03219", vanilla = true },
        objectives = { it = "Cerca Clerk Daltry al Darkshire Town Hall.", enHash = "bbe202a0", vanilla = true },
        reward = { it = "Ah, quindi ti manda Madame Eva. . . .", enHash = "7937cb65", vanilla = true },
    },
    [67] = {
        title = { it = "La leggenda di Stalvan", enHash = "73f3d412", vanilla = true },
        text = { it = "Stalvan, eh? Fammi controllare il registro del paese.\n\nStalvan. . .Stalvan. . .vediamo. Ah, eccolo! Ho la scheda di un certo Stalvan Mistmantle. L'ultimo indirizzo registrato è la Moonbrook Schoolhouse. Roba vecchia, altroché!\n\nMi fai un favore? Se ti capita di andare a Moonbrook, fammi sapere se trovi qualcosa di nuovo su questo tizio. Mi piace tenere le schede in ordine.", enHash = "62c12518", vanilla = true },
        objectives = { it = "Va' alla Moonbrook Schoolhouse e riporta a Clerk Daltry ogni informazione aggiornata su Stalvan.", enHash = "ec849bb5", vanilla = true },
        reward = { it = "Il vecchio baule cigola mentre si apre. . . .", enHash = "c0aeae53", vanilla = true },
    },
    [68] = {
        title = { it = "La leggenda di Stalvan", enHash = "73f3d412", vanilla = true },
        text = { it = "Nel vecchio baule trovi una Dusty Unsent Letter.", enHash = "e715442e", vanilla = true },
        objectives = { it = "Porta la Dusty Unsent Letter a Clerk Daltry.", enHash = "a823f47e", vanilla = true },
        progress = { it = "Ah, mi ricordo di te. Sei $Gquello:quella; che chiedeva di quel tale Stalvan. L'hai poi trovato quel che cercavi?", enHash = "d8bed734", vanilla = true },
        reward = { it = "Interessante. Quindi quel tipo a Moonbrook ci ha passato davvero un po' di tempo. È piuttosto strano che la lettera non sia mai stata consegnata. In ogni caso, aggiorno il registro.", enHash = "5f6c6966", vanilla = true },
    },
    [69] = {
        title = { it = "La leggenda di Stalvan", enHash = "73f3d412", vanilla = true },
        text = { it = "Oh cielo! Devo essermelo perso la prima volta. Nel registro, proprio sotto il primo indirizzo di Stalvan, ce n'è un altro, cancellato solo a metà. Sembra che fosse diretto alla Lion's Pride Inn, a Goldshire. Faresti bene a controllare là, $N.", enHash = "c2e19453", vanilla = true },
        objectives = { it = "Va' alla Lion's Pride Inn e vedi se qualcuno lì ha sentito il nome Stalvan.", enHash = "b1de730a", vanilla = true },
        reward = { it = "Stalvan? Di sicuro mi dice qualcosa.", enHash = "d4ef4450", vanilla = true },
    },
    [70] = {
        title = { it = "La leggenda di Stalvan", enHash = "73f3d412", vanilla = true },
        text = { it = "Il nome Stalvan mi dice qualcosa. Ora ricordo.\n\nMolti anni fa, in una notte di tempesta, arrivò un messaggero in cerca di un riparo per la notte. Verso la mezzanotte l'uomo scese di corsa le scale urlando, il volto pallido di paura. Ancora in camicia da notte, sparì nel diluvio.\n\nNella fretta dimenticò le sue lettere nella cassa al piano di sopra. Non tornò mai a riprenderle. Ne resta una di quel tale Stalvan, indirizzata al Canal District di Stormwind. Serviti pure.", enHash = "c2663fde", vanilla = true },
        objectives = { it = "Recupera Stalvan's Undelivered Letter dalla cassa e consegnala al Canal District di Stormwind.", enHash = "96edbcae", vanilla = true },
        progress = { it = "Cos'hai lì? Fammi dare un'occhiata. . .", enHash = "19748557", vanilla = true },
        reward = { it = "Hai un bel coraggio a portare questa roba qui.", enHash = "c6f1adc7", vanilla = true },
    },
    [71] = {
        title = { it = "Rapporto a Thomas", enHash = "3294805d" },
        text = { it = "Ora che hai entrambi i medaglioni, consegnali a Guard Thomas al ponte, così che sappia che fine hanno fatto le sue guardie uccise.", enHash = "c7dbbecb" },
        objectives = { it = "Consegna Rolf and Malakai's Medallions a Guard Thomas, al ponte a est di Elwynn.", enHash = "4c9cd78b" },
        progress = { it = "Salve, $N. Hai scoperto che fine hanno fatto Rolf e Malakai?", enHash = "ea349703" },
        reward = { it = "Hai confermato i miei timori, $N. I murloc sono una minaccia che non possiamo ignorare.", enHash = "c30f9031" },
    },
    [72] = {
        title = { it = "La leggenda di Stalvan", enHash = "73f3d412", vanilla = true },
        text = { it = "Mio padre è stato il custode della tenuta molto prima di me. Fu lui a dover asciugare il sangue dopo il massacro. Ma questo non c'entra.\n\nGli ultimi fondi dei Flintridge si sono esauriti. Ora anche le ultime cose di famiglia finiscono all'asta. Colpa degli avvoltoi del fisco. Immagino che, se proprio muori dalla voglia di saperne di più, sei $Glibero:libera; di frugare in questa roba. Chissà cosa puoi trovare.", enHash = "a0fec09a", vanilla = true },
        objectives = { it = "Fruga tra le cose imballate in cerca di un indizio.", enHash = "ff240bb1", vanilla = true },
        reward = { it = "Fai scivolare piano il coperchio della cassa. . . .", enHash = "1c0fd0d6", vanilla = true },
    },
    [74] = {
        title = { it = "La leggenda di Stalvan", enHash = "73f3d412", vanilla = true },
        text = { it = "Dentro la cassa trovi oggetti di ogni tipo: cimeli ammuffiti, un ritratto di famiglia, qualche trofeo di caccia e alcuni libri vecchi. Quasi in fondo, sotto un vaso di ceramica, scopri A Torn Journal Page.", enHash = "7c45fa2e", vanilla = true },
        objectives = { it = "La Torn Journal Page che hai scoperto ti dà il prossimo indizio.", enHash = "64bb1fb0", vanilla = true },
        progress = { it = "Cos'hai lì? Non riesco a vedere. Ho la vista molto debole. Mettimelo tra le mani.", enHash = "ee9a3495", vanilla = true },
        reward = { it = "Riesco a malapena a distinguere quelle lettere. Ma quella calligrafia mi ricorda qualcosa che ho visto una volta, prima che la mia vista si facesse così debole.", enHash = "de2172e1", vanilla = true },
    },
    [75] = {
        title = { it = "La leggenda di Stalvan", enHash = "73f3d412", vanilla = true },
        text = { it = "Quando sono venuto a stare qui, nella cassa al piano di sopra c'era un fascio di pergamene. Le ho guardate una volta appena arrivato, ma ho rinunciato quando la nebbia mi ha annebbiato gli occhi.\n\nFa' un favore a un vecchio quasi cieco e controlla la cassa di sopra: magari c'è qualcosa che ti aiuta nella tua ricerca su questo Stalvan. Sono quasi sicuro che ci sia una pagina di diario sbiadita che potrebbe interessarti. Portamela e ti aiuterò come posso.", enHash = "261d2c96", vanilla = true },
        objectives = { it = "Marshal Haggard vuole che tu controlli la cassa di sopra per trovare la Faded Journal Page.", enHash = "421056c2", vanilla = true },
        progress = { it = "L'hai trovata quella pagina di cui ti ho detto, $N?", enHash = "7890e84c", vanilla = true },
        reward = { it = "L'hai trovata!", enHash = "b40ec7f7", vanilla = true },
    },
    [76] = {
        title = { it = "La Jasperlode Mine", enHash = "d4df039f" },
        text = { it = "Grazie a te sappiamo che la Fargodeep Mine è infestata dai kobold. Ora ci serve qualcuno che vada a esplorare la più lontana Jasperlode Mine.\n\nEsplora la Jasperlode e conferma se ci sono kobold. Per raggiungere la miniera, va' a est lungo la strada fino alla Tower of Azora. Dalla torre, prosegui a nord e troverai la miniera ai piedi delle colline.", enHash = "071ec8ac" },
        objectives = { it = "Esplora la Jasperlode Mine, poi torna a fare rapporto a Marshal Dughan, a Goldshire.", enHash = "5fae2cde" },
        progress = { it = "Salute, $N. Cos'hai da riferire? Hai esplorato la Jasperlode Mine?", enHash = "0fe4ff2c", vanilla = true },
        reward = { it = "Kobold alla Jasperlode Mine, dici? Maledizione! La situazione peggiora di minuto in minuto!\n\nGrazie del rapporto, $N. Avrei preferito però che le notizie che hai portato fossero buone.", enHash = "aa86ed07" },
    },
    [78] = {
        title = { it = "La leggenda di Stalvan", enHash = "73f3d412", vanilla = true },
        text = { it = "Conosco qualcuno che potrebbe darti una mano. Ai tempi in cui guidavo la Stormwind Guard, andavamo a bere alla Scarlet Raven Tavern di Darkshire. Il locandiere di lì, Smitts, era un bell'esperto di storie locali. Mostragli questa pagina e senti cos'ha da dire.", enHash = "be7bdf6f", vanilla = true },
        objectives = { it = "Porta la Faded Journal Page a Tavernkeep Smitts.", enHash = "573942e4", vanilla = true },
        progress = { it = "Ti manda Marshal Haggard? E dirlo subito, no?\n\nAh, il buon vecchio Haggard. Povero diavolo, fra non molto sarà cieco del tutto. Comunque, fammi vedere cos'hai lì.", enHash = "a90160e1", vanilla = true },
        reward = { it = "Per la Luce! Certo che la riconosco quella calligrafia.", enHash = "f461f79e", vanilla = true },
    },
    [79] = {
        title = { it = "La leggenda di Stalvan", enHash = "73f3d412", vanilla = true },
        text = { it = "Ho seguito per anni la leggenda di quel tale Stalvan. Quando qualche anno fa massacrarono quei nobili in visita, andai a indagare insieme a Haggard. Trovai queste pagine infangate, ma non riuscimmo mai a collegare la calligrafia a quel pazzo nel bosco. Le prove che hai raccolto dimostrano la sua colpa. Porta questa a Commander Ebonlocke subito e raccontale quel che hai scoperto!", enHash = "b7235596", vanilla = true },
        objectives = { it = "Porta la pagina infangata a Commander Ebonlocke.", enHash = "09424723", vanilla = true },
        progress = { it = "Sarà meglio che sia importante, $C. Fammi vedere cos'hai e raccontami la tua storia. Ma per la Luce, fa' in fretta. La difesa di Darkshire è la mia priorità numero uno. Non ho tempo da sprecare in piste che non portano a niente.", enHash = "fee27c8c", vanilla = true },
        reward = { it = "Però, hai dimostrato di essere $Gun bel detective:una bella detective;, $C.", enHash = "f41e9ac7", vanilla = true },
    },
    [80] = {
        title = { it = "La leggenda di Stalvan", enHash = "73f3d412", vanilla = true },
        text = { it = "Quel viscido di Stalvan lo tengo d'occhio da parecchio. Ma se questa pagina è stata scritta dalla stessa mano, la sua colpa è provata al di là di ogni dubbio.\n\nIn tutti i suoi anni a tenere il Town Registry, Clerk Daltry è diventato un esperto nel riconoscere le calligrafie. Mostragli questa pagina e vedi se la scrittura corrisponde a quella della firma sul registro.", enHash = "8caa7796", vanilla = true },
        objectives = { it = "Mostra la Bloodstained Journal Page a Clerk Daltry.", enHash = "d8598ad5", vanilla = true },
        progress = { it = "Di nuovo qui, $N? Cos'hai questa volta?", enHash = "13221694", vanilla = true },
        reward = { it = "Ma certo! La scrittura di questa pagina corrisponde davvero a quella delle firme sul registro.", enHash = "0cc0c95f", vanilla = true },
    },
    [83] = {
        title = { it = "Capi di lino rosso", enHash = "ecda69a1" },
        text = { it = "La banda dei Defias a Northshire porta maschere di tela di sacco, ma i Defias di Elwynn portano il lino, che posso usare per fare bei capi di lino.\n\nPortami delle Red Linen Bandana e le userò per cucirti qualcosa.\n\nI membri della banda dei Defias hanno accampamenti sparsi per tutta Elwynn.", enHash = "df916e3a" },
        objectives = { it = "Porta 6 Red Linen Bandana a Sara Timberlain, all'Eastvale Logging Camp.", enHash = "770cced7" },
        progress = { it = "Sto finendo il lino, $N. Ne hai un po' per me?", enHash = "601ffa01", vanilla = true },
        reward = { it = "Ah, sono delle belle bandane, anche se un po' ruvide...\n\nEcco qua!", enHash = "d1cc1f1a", vanilla = true },
    },
    [84] = {
        title = { it = "Di nuovo da Billy", enHash = "ae36e686", vanilla = true },
        text = { it = "Ecco qua. E quando darai questa torta a quel Billy, digli che spero gli vada di traverso!", enHash = "ef6c2210", vanilla = true },
        objectives = { it = "Porta la Pork Belly Pie a Billy Maclure, ai Maclure Vineyards.", enHash = "6c79cf51", vanilla = true },
        progress = { it = "Ugh... Muoio di fame! Ce l'hai quella torta per me, $N?", enHash = "85528a31", vanilla = true },
        reward = { it = "Mm, che bontà! Questa torta è la migliore!\n\nMi sa che la memoria mi sta tornando...", enHash = "b301ace7", vanilla = true },
    },
    [85] = {
        title = { it = "La collana perduta", enHash = "427bb2f2", vanilla = true },
        text = { it = "Ho perso la mia collana, e credo che me l'abbia presa quel monello di Billy Maclure! Di solito sguscia come un topo intorno ai Maclure Vineyards, a est di qui.\n\nRiprendimi la collana e scalderai il cuore di una vecchia vedova.", enHash = "7a84cacf", vanilla = true },
        objectives = { it = "Parla con Billy Maclure.", enHash = "0d04669d", vanilla = true },
        reward = { it = "Hai perso cosa? Be', io non ho preso nessuna collana, perché non sono un ladro!\n\nMagari so chi è stato, ma...<sogghigna>...ho troppa fame per ricordarmelo.", enHash = "55f55d5b", vanilla = true },
    },
    [86] = {
        title = { it = "Una torta per Billy", enHash = "b136d9a7", vanilla = true },
        text = { it = "Magari, se avessi una torta, potrei dirti chi ce l'ha quella collana. E sai, mi sa che quella vecchia signora Bernice, nell'altra fattoria, fa delle Pork Belly Pie buonissime...\n\nMagari, se le portassi dei Chunk of Boar Meat presi dai cinghiali che gironzolano intorno alle nostre fattorie, e le dicessi a cosa serve, te ne sfornerebbe una.", enHash = "71f8e2a2", vanilla = true },
        objectives = { it = "Porta 4 Chunk of Boar Meat ad Auntie Bernice Stonefield, alla Stonefield Farm.", enHash = "96955ebf", vanilla = true },
        progress = { it = "Non mi pare giusto dar da mangiare proprio al ragazzo che mi ha rubato la collana, ma se è questo che ci vuole per riavere ciò che è mio, così sia!\n\nCe l'hai quella carne di cinghiale?", enHash = "7036b821", vanilla = true },
        reward = { it = "Questa carne di cinghiale selvatico è dura, sì, ma falla sobbollire abbastanza e viene fuori una torta gustosa davvero!", enHash = "bcf39522", vanilla = true },
    },
    [87] = {
        title = { it = "Goldtooth", enHash = "b4878668", vanilla = true },
        text = { it = "Stavo giocando vicino alla Fargodeep Mine e credo di aver fatto cadere, ehm... cioè, di aver visto, la collana della vecchia signora. Non chiedermi come ci sia finita... non sono stato io!\n\nComunque, ho visto un kobold grosso con un dente d'oro raccogliere la collana e correre dentro la miniera. Va' a cercare quel kobold e troverai la collana, lo giuro!", enHash = "a3900dda", vanilla = true },
        objectives = { it = "Porta Bernice's Necklace ad \"Auntie\" Bernice Stonefield, alla Stonefield Farm.", enHash = "76b83c17", vanilla = true },
        progress = { it = "Salve, $N. Hai trovato la mia collana?", enHash = "169b82ee", vanilla = true },
        reward = { it = "Oh, l'hai trovata! Grazie, grazie, $Gcaro:cara;!\n\nTieni, prendi questo. Era di mio marito, e diceva sempre che portava fortuna. Se solo non l'avesse dimenticato nella sua ultima campagna! *sniff*", enHash = "87228315", vanilla = true },
    },
    [88] = {
        title = { it = "Princess deve morire!", enHash = "861f3d61", vanilla = true },
        text = { it = "I Brackwell hanno un maiale da concorso, Princess. La scrofa è ENORME, ed è diventata così sgattaiolando fin qui a mangiarsi le mie verdure!\n\nQuindi, prima che venga nei nostri campi... Princess deve morire! Portami il suo collare come prova dell'impresa e ti darò qualcosa per il disturbo!\n\nPrincess di solito sta al Brackwell Pumpkin Patch, a est, oltre la fattoria dei Maclure. Prendila prima che le venga fame e torni qui!", enHash = "eaf72310", vanilla = true },
        objectives = { it = "Uccidi Princess, prendi il suo collare e portalo a Ma Stonefield, alla Stonefield Farm.", enHash = "a51d3dc9", vanilla = true },
        progress = { it = "L'hai già vista? L'hai presa?", enHash = "71603687", vanilla = true },
        reward = { it = "Grazie al cielo! Quella scrofa stava diventando così grossa che si sarebbe mangiata tutto il raccolto! Grazie, $N.\n\nAllora, una di queste fa al caso tuo?", enHash = "85672b49", vanilla = true },
    },
    [89] = {
        title = { it = "Il ponte di Everstill", enHash = "aac540ee", vanilla = true },
        text = { it = "Durante l'ultima invasione degli orchi siamo stati costretti a fondere il nostro ferro per farne proiettili, spade e armature. Abbiamo mandato a dire a Stormwind di spedirci altro materiale, ma una banda di gnoll di Redridge ha assaltato la carovana ed è scappata sulle colline dietro Lakeshire.\n\nAdesso siamo a corto di rifornimenti per ricostruire questo ponte. Se mi porti 5 Iron Pike e 5 Iron Rivet, $N, farò in modo che tu sia $Gricompensato:ricompensata;.\n\nE adesso al lavoro!", enHash = "500d6edc", vanilla = true },
        objectives = { it = "Porta 5 Iron Pike e 5 Iron Rivet a Foreman Oslow, a Lakeshire.", enHash = "2f79d1b0", vanilla = true },
        progress = { it = "Questo ponte non si costruisce da solo! Allora, dove sono quegli Iron Pike e quegli Iron Rivet?", enHash = "1056d264", vanilla = true },
        reward = { it = "Ottimo lavoro, $N. Questi rifornimenti aiuteranno moltissimo i lavori del ponte. Rimetteremo in sesto questa bellezza in un attimo.", enHash = "8145b82a", vanilla = true },
    },
    [90] = {
        title = { it = "Seasoned Wolf Kabobs", enHash = "fd8cd0e4", vanilla = true },
        text = { it = "I Seasoned Wolf Kabob sono il piatto forte della casa! Certo che posso fartene un po'. Ma prima mi servono gli ingredienti. Portami 10 Lean Wolf Flank e delle Stormwind Seasoning Herbs. Di lupi qui nella foresta ce ne sono tanti, di sicuro trovare i Flank non sarà un problema. Per le erbe, cerca Felicia Gump nel suo negozio di fiori nel quartiere dei canali di Stormwind.", enHash = "4d39e00a", vanilla = true },
        objectives = { it = "Raccogli 10 Lean Wolf Flank e le Stormwind Seasoning Herbs, poi torna da Chef Grual, a Darkshire.", enHash = "2b8cbe79", vanilla = true },
        progress = { it = "Sei già $Griuscito:riuscita; a trovare 10 Lean Wolf Flank? E le erbe da Felicia, a Stormwind?", enHash = "e16d2bcf", vanilla = true },
        reward = { it = "Ottimo lavoro, $N! Goditi la prelibatezza chiamata Seasoned Wolf Kabob!", enHash = "aea70d80", vanilla = true },
    },
    [91] = {
        title = { it = "La legge di Solomon", enHash = "66db00bb", vanilla = true },
        text = { it = "Un nemico di Stormwind si è stabilito nelle colline orientali di Redridge. Questo malvagio criminale usa l'Arcano per diffondere terrore e miseria sul nostro paese e sulla nostra gente. Conduce i suoi affari immondi sotto il nome di Morganth.\n\nMorganth ora controlla lo Shadowhide Gnoll Clan e lo usa per i suoi voleri. Come stabilito dalla legge di Lakeshire, aiutare un criminale del Regno è punibile con la morte.\n\nQuesti gnoll ignobili vanno uccisi!\n\nConsegnami 10 Shadowhide Pendant e sarai $Gricompensato:ricompensata;.", enHash = "115b77c7", vanilla = true },
        objectives = { it = "Porta 10 Shadowhide Pendant a Bailiff Conacher, nel Lakeshire Town Hall.", enHash = "df65092a", vanilla = true },
        progress = { it = "Consegnami 10 Shadowhide Pendant e sarai $Gricompensato:ricompensata;.", enHash = "81cefe3e", vanilla = true },
        reward = { it = "La Corte di Lakeshire riconosce il tuo impegno per la giustizia, $N. Facendo rispettare le leggi del Regno hai contribuito a difendere la giustizia di questa terra.", enHash = "38bb418b", vanilla = true },
    },
    [92] = {
        title = { it = "Redridge Goulash", enHash = "7a150731", vanilla = true },
        text = { it = "Niente mi farebbe più piacere che prepararti un po' di Redridge Goulash. Ma c'è un piccolo problema. Durante la recente rivolta degli orchi ho sfamato l'intera brigata delle truppe di Stormwind. Adesso la mia dispensa è vuota. Però, se mi procuri tu gli ingredienti, ti accontento volentieri.\n\nPortami cinque pezzi di Tough Condor Meat, cinque Great Goretusk Snout e cinque porzioni di Crisp Spider Meat.", enHash = "dcfbfaac", vanilla = true },
        objectives = { it = "Chef Breanna di Lakeshire vuole cinque pezzi di Tough Condor Meat, cinque Great Goretusk Snout e cinque porzioni di Crisp Spider Meat.", enHash = "d4f3f5de", vanilla = true },
        progress = { it = "Mi servono ancora cinque pezzi di Tough Condor Meat, cinque Great Goretusk Snout e cinque porzioni di Crisp Spider Meat.", enHash = "c3734290", vanilla = true },
        reward = { it = "Ben fatto, $N. E che begli esemplari! Ed ecco la tua deliziosa specialità, il Redridge Goulash!", enHash = "4ae29305", vanilla = true },
    },
    [93] = {
        title = { it = "Dusky Crab Cakes", enHash = "ecc5c51b", vanilla = true },
        text = { it = "Ti svelo un piccolo segreto — i Dusky \"Crab\" Cake sono fatti davvero con zampe di ragno! Lo so, è un po' disgustoso, ma hanno un bel sapore aspro e sono degli ottimi spuntini! Portami delle Gooey Spider Leg e te ne preparo qualcuno.\n\nMi dicono che i Venom Web Spider siano una buona fonte — fanno il nido a nord, tra le colline e il fiume.", enHash = "e7ca7c3c", vanilla = true },
        objectives = { it = "Raccogli 6 Gooey Spider Leg e portale a Chef Grual, a Darkshire.", enHash = "948217df", vanilla = true },
        progress = { it = "Salve, $N. Hai già preso quelle Gooey Spider Leg?", enHash = "cbe2e82f", vanilla = true },
        reward = { it = "Ah sì, un bel mazzo di zampe che hai lì! Fammele condire con le mie spezie segrete (non guardare!) e lasciamole sfrigolare un po' in padella...\n\nE anche se i Dusky Crab Cake sono la mia specialità e la ricetta non la do a nessuno, ecco la ricetta di un piatto quasi altrettanto buono.", enHash = "2fbe77c9", vanilla = true },
    },
    [94] = {
        title = { it = "Un occhio vigile", enHash = "8042d6be", vanilla = true },
        text = { it = "Il mio rivale, Morganth, è un mago malvagio di grande potere che vive nella Tower of Ilgalar, a Redridge. Ho messo a punto un modo per spiarlo, l'Eye of Azora, e ora posso osservarlo da lontano.\n\nMa per studiare i suoi pensieri... mi serve altro aiuto.\n\nSe te la senti, porta il mio Glyph of Azora alla Tower of Ilgalar. Posalo sulla Lion Statue vicino alla torre.\n\nQuando sarà fatto, il potere di Azora concederà visioni dei piani futuri di Morganth.", enHash = "0c34b7f6", vanilla = true },
        objectives = { it = "Porta il Glyph of Azora alla Lion Statue vicino alla Tower of Ilgalar, a Redridge.", enHash = "cf28e828", vanilla = true },
        progress = { it = "Questa Lion Statue sta qui da decenni, e fa la guardia solitaria alla famigerata Tower of Ilgalar.\n\nAlla base della statua c'è un incavo, dove si potrebbe incastonare una gemma o un glifo...", enHash = "e457a40f", vanilla = true },
        reward = { it = "Posi il Glyph of Azora sulla pietra. Aderisce da solo... e da esso senti la voce incorporea di Theocritus:\n\nTi sono grato, giovane $N. Ora puoi parlarmi attraverso questo glifo, e potrei avere altri incarichi per te... dopo aver sondato i pensieri del mio rivale.", enHash = "74efd87b", vanilla = true },
    },
    [95] = {
        title = { it = "La vendetta di Sven", enHash = "7a0396c2", vanilla = true },
        text = { it = "Un tempo lavoravo una delle fattorie a sud-est... finché i Dark Rider del Deadwind Pass non piombarono sulla mia fattoria e massacrarono la mia famiglia mentre ero via!\n\nAl mio ritorno vidi una figura in ombra aggirarsi furtiva vicino al fienile, mentre seppelliva qualcosa. Fuggì prima che potessi prenderlo, e non potevo attardarmi perché ero alle calcagna dei Dark Rider. Così non ho mai scoperto cosa fosse nascosto.\n\nSe riesci a trovare quel che quella figura ha seppellito, te ne sarei grato. Il nascondiglio è dietro il vecchio ceppo vicino al fienile.", enHash = "2d527aad", vanilla = true },
        objectives = { it = "Va' a Sven's Farm e trova cosa è stato sepolto dietro il vecchio ceppo.", enHash = "d712ff92", vanilla = true },
        reward = { it = "Qui c'è un cumulo di terra, ammucchiato in fretta come se qualcuno avesse avuto bisogno di nascondere qualcosa... senza molto tempo per farlo.", enHash = "e6db9e1c", vanilla = true },
    },
    [96] = {
        title = { it = "Il richiamo dell'acqua", enHash = "eab41910", vanilla = true },
        text = { it = "Prendi frammento. Prendi frammento e dai vita.\n\nDai vita e capisci. Capisci che acqua è vita... corruzione ferma vita.\n\nTu proteggi e dai vita con potere di acqua.", enHash = "c80149db", vanilla = true },
        objectives = { it = "Porta lo Shard of Water a Islen Waterseer, nelle Barrens.", enHash = "6c24d55c", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata;. Splendido!\n\nCom'è andato il tuo viaggio a Silverpine? Ci hai messo molto?\n\nÈ difficile per me capire se laggiù hai avuto successo, perché gran parte di quella terra è ormai corrotta. Il suo fetore soffoca qualunque bene tu possa aver fatto. Ma i piccoli successi a volte sono importanti quanto quelli grandi. Purificare l'acqua laggiù è stato fondamentale per te, e per tutti gli sciamani.", enHash = "2ccb0141", vanilla = true },
        reward = { it = "Questa è la prova che ti avevo chiesto. Hai fatto bene, $N.\n\nSono lieta di essere la prima a congratularmi con te e a darti questo... il tuo Water Totem.\n\nUsalo bene, e buona fortuna.\n\nLa tua prossima prova non arriverà prima di un po' di tempo, quindi impara bene le tue lezioni. L'acqua pura non solo ridà la vita a chi è ferito, ma può avere molti altri effetti. Ti consiglio di cercare un istruttore di sciamani quando hai tempo. Potrebbe avere altri incantesimi da insegnarti.", enHash = "809eae30", vanilla = true },
    },
    [97] = {
        title = { it = "La leggenda di Stalvan", enHash = "73f3d412", vanilla = true },
        text = { it = "Fa' sapere subito a Commander Ebonlocke che la calligrafia corrisponde, $N! I suoi sospetti erano giusti!", enHash = "95598c37", vanilla = true },
        objectives = { it = "Riporta la notizia a Commander Ebonlocke.", enHash = "045f79eb", vanilla = true },
        progress = { it = "Sì, $N?", enHash = "befc103a", vanilla = true },
        reward = { it = "Lo sapevo! Ottimo lavoro, $N.", enHash = "46a9e43b", vanilla = true },
    },
    [98] = {
        title = { it = "La leggenda di Stalvan", enHash = "73f3d412", vanilla = true },
        text = { it = "Stalvan Mistmantle ha condotto una vita di depravazione. Vittime innocenti sono morte per mano sua. È senza dubbio colpevole di innumerevoli delitti. Ora quel folle minaccia Darkshire. Solo la Luce sa che atti sordidi stia tramando. Va' al suo cottage appena a nord del paese, $C, e giustizia Stalvan, una volta per tutte.\n\nQuando sarà fatto, va' da Madame Eva e mostrale il suo anello di famiglia. In fondo è stata la sua premonizione a portare a questa scoperta raccapricciante. Ma grazie a lei Darkshire è più sicura.", enHash = "1bdf3949", vanilla = true },
        objectives = { it = "Uccidi Stalvan Mistmantle e mostra a Madame Eva il suo anello di famiglia.", enHash = "1f2e3042", vanilla = true },
        progress = { it = "Sì, $N?", enHash = "befc103a", vanilla = true },
        reward = { it = "Lo so, $N: Stalvan è morto. Ho sentito un'onda di speranza attraversare la foresta corrotta. Una volta per tutte, Duskwood è libera dalla sua sete di sangue. La mia gioia è offuscata dal pensiero di chi è caduto preda di quella bestia orribile. Ciò nonostante, sei $Gun:una; $C $Gcoraggioso:coraggiosa; e $Gastuto:astuta;.", enHash = "c3279a1b", vanilla = true },
    },
    [99] = {
        title = { it = "La follia di Arugal", enHash = "2770798a", vanilla = true },
        text = { it = "Più cresce la mia comprensione della magia di Arugal, più cresce il mio disprezzo per quello sciocco sciagurato. Sono vicino a completare le mie ricerche sul suo cosiddetto rimedio.\n\nLa mia conoscenza sarà completa quando avrò capito quale incantesimo provoca gli strani comportamenti che si vedono a Pyrewood Village. Di giorno i contadini sembrano umani. Ma quando cala il sole gli abitanti si trasformano in Moonrage Worgen.\n\nDevo ricavare energia dai ceppi incantati che Arugal ha lanciato su di loro. Portami sei Pyrewood Shackles incantati, $N.", enHash = "cc5e41e0", vanilla = true },
        objectives = { it = "Porta 6 Pyrewood Shackles a Dalar Dawnweaver, al Sepulcher.", enHash = "83375c71", vanilla = true },
        progress = { it = "Ti sei già $Gprocurato:procurata; i Pyrewood Shackles, $N?", enHash = "b62a7f17", vanilla = true },
        reward = { it = "La tua tenacia è ammirevole. Con la conoscenza che mi hai aiutato a raccogliere, Arugal cadrà e la sua magia avventata sarà annullata. Onore a te, $N.", enHash = "0d55b7db", vanilla = true },
    },
    [100] = {
        title = { it = "Il richiamo dell'acqua", enHash = "eab41910", vanilla = true },
        text = { it = "Mentre pronunci le ultime parole della formula, esplode un lampo di luce. Il suono delle gocce d'acqua che colpiscono la fiamma si è spento, e i tuoi sensi vengono sopraffatti mentre gli spiriti corrotti intorno a te vengono distrutti.", enHash = "785bf22a", vanilla = true },
        objectives = { it = "Parla con la Minor Manifestation of Water, nella Silverpine Forest.", enHash = "21957ea2", vanilla = true },
        reward = { it = "Grazie a te. Grazie agli sciamani.\n\nLa corruzione si ritira, ma la vita continua a spegnersi. Tocca a sciamani proteggere vita.", enHash = "2d6ce6ec", vanilla = true },
    },
    [101] = {
        title = { it = "Il Totem of Infliction", enHash = "14e51d34", vanilla = true },
        text = { it = "Mentre la corruzione mistica si insinua nella foresta, il bisogno di proteggersi è innegabile, $N. I venti mi sussurrano e parlano di un grande pericolo che ti attende paziente nel prossimo futuro.\n\nSe vuoi proteggerti, nobile $C, portami 10 Ghoul Fang, 10 Skeleton Finger e 5 Vial of Spider Venom. Per te incanterò un Totem of Infliction che ferirà chi tenta di farti violenza.", enHash = "fb65f95b", vanilla = true },
        objectives = { it = "Porta 10 Ghoul Fang, 10 Skeleton Finger e 5 Vial of Spider Venom a Madame Eva, a Darkshire.", enHash = "d0e643d5", vanilla = true },
        progress = { it = "Portami 10 Ghoul Fang, 10 Skeleton Finger e 5 Vial of Spider Venom. Per te incanterò un Totem of Infliction che ferirà chi tenta di farti violenza.", enHash = "9f061427", vanilla = true },
        reward = { it = "Molto saggio da parte tua, $N. Questo Totem of Infliction ti aiuterà a proteggerti dal male che si annida per tutta Azeroth e oltre. Quando ti senti $Gminacciato:minacciata;, stringi questo totem e trova conforto nella sua aura magica. Sii $Gcoraggioso:coraggiosa;, gentile $C. Ti servirà tutto il coraggio che riesci a raccogliere, perché vedo molto sangue nel tuo futuro.", enHash = "fa0c4e5b", vanilla = true },
    },
    [102] = {
        title = { it = "Pattugliare Westfall", enHash = "3c46c7c8", vanilla = true },
        text = { it = "Stormwind ci ha abbandonati. Un vento immondo di degrado soffia per le pianure di Westfall. Questa era la mia terra, e non volterò le spalle ai cittadini che scelgono di restare qui. Noi, che un tempo eravamo contadini, resisteremo.\n\nIl tuo compito, se decidi di accettarlo, è pattugliare le praterie di Westfall. Da' la caccia agli gnoll immondi che sembrano lavorare insieme ai ladri delle Deadmines e uccidili. Portami otto Gnoll Paw e ricompenserò il tuo coraggio.", enHash = "0e783e79", vanilla = true },
        objectives = { it = "Porta 8 Gnoll Paw a Captain Danuvin, a Sentinel Hill.", enHash = "ab20464d", vanilla = true },
        progress = { it = "Hai già raccolto 8 zampe da quegli gnoll traditori?", enHash = "beb6d2bf", vanilla = true },
        reward = { it = "Ben fatto, $N. Con avventurieri valorosi come te che combattono al fianco della People's Militia, Westfall potrebbe davvero tornare il prospero granaio che era un tempo. Ti prego, accetta questo in riconoscimento del tuo impegno instancabile.", enHash = "b4ec4cfb", vanilla = true },
    },
    [103] = {
        title = { it = "Custode della fiamma", enHash = "8f613a29", vanilla = true },
        text = { it = "La notte in cui morì la famiglia del guardiano del faro fu orribile. Guardai, impotente, mentre Old Murk-Eye guidava l'attacco. Ma quel che è fatto è fatto, e ora mi preoccupo per la vita dei marinai del Great Sea le cui navi si avvicinano agli scogli insidiosi della costa. Senza nessuno a vegliare sulla fiamma, la responsabilità è ricaduta su di me.\n\nAiutami a tenere accesa la torcia portandomi 5 fiaschi d'olio dai mostri del raccolto.", enHash = "6e2415c3", vanilla = true },
        objectives = { it = "Porta 5 Flask of Oil a Captain Grayson, al Westfall Lighthouse.", enHash = "e3d6ca68", vanilla = true },
        progress = { it = "La fiamma non brucerà a lungo senza olio, $N.", enHash = "1378e311", vanilla = true },
        reward = { it = "Sia lode a te, $Gvaloroso:valorosa; $C. Gli scogli della Westfall Coast saranno illuminati grazie alla tua fatica. Molte vite saranno risparmiate, finché la torcia resterà accesa.\n\nIo sono morto inutilmente proprio su questa riva. La mia pena nell'aldilà è fare in modo che nessun altro segua il mio destino.", enHash = "3717b80f", vanilla = true },
    },
    [104] = {
        title = { it = "La minaccia della costa", enHash = "b075da3b", vanilla = true },
        text = { it = "Quando la mia vita finì sugli scogli, non avevo idea di cosa mi riservasse l'aldilà. Quella notte il faro era spento perché Old Murk-Eye aveva messo in fuga la famiglia del guardiano. Tornarono e riaccesero la fiamma, ma Old Murk-Eye convinse i murloc dalla mente più debole a razziare di nuovo il faro insieme a lui. La seconda volta la famiglia non fu altrettanto fortunata, e sotto i miei occhi morirono inermi.\n\nUccidi Old Murk-Eye se lo vedi lungo la riva, portami una delle sue scaglie e ti ricompenserò.", enHash = "91cfa8a8", vanilla = true },
        objectives = { it = "Porta una scaglia di Old Murk-Eye a Captain Grayson, al Westfall Lighthouse.", enHash = "f6402a14", vanilla = true },
        progress = { it = "Hai già fatto strage della minaccia chiamata Old Murk-Eye? È stato avvistato mentre si aggirava lungo la costa di Westfall.\n\nTorna da me quando quella bestia immonda sarà morta.", enHash = "e1af6bce", vanilla = true },
        reward = { it = "Dunque quel pagano immondo di Murk-Eye è morto. Ben fatto, $N. Per mano tua una vita è stata spenta, ma forse molte altre sono state salvate. Il Great Sea, per quanto irto di pericoli, stanotte sarà un pizzico più sicuro grazie al tuo eroismo.", enHash = "822e1549", vanilla = true },
    },
    [106] = {
        title = { it = "Giovani innamorati", enHash = "b418483b", vanilla = true },
        text = { it = "Oh, sono maledetta! Il mio cuore appartiene a Tommy Joe Stonefield, ma le nostre famiglie sono acerrime nemiche. Così non posso vederlo, anche se i miei occhi non vedono l'ora di posarsi su quel bel viso!\n\nTi prego, prendi questa lettera e dalla a Tommy Joe. Di solito sta al fiume a ovest della Stonefield Farm, che si trova proprio a ovest di qui.", enHash = "c8d4f0ab", vanilla = true },
        objectives = { it = "Dai Maybell's Love Letter a Tommy Joe Stonefield.", enHash = "5d74b1b9", vanilla = true },
        progress = { it = "Hai cosa?? Maybell è la luce della mia vita grigia. Presto, fammi vedere la sua lettera!", enHash = "ab4dd796", vanilla = true },
        reward = { it = "Ah! Non sopporto di stare lontano da lei. Devo vederla!!", enHash = "196bac85", vanilla = true },
    },
    [107] = {
        title = { it = "Un biglietto per William", enHash = "8bed998c", vanilla = true },
        text = { it = "Scommetto che William Pestle ha una pozione per unire i nostri due giovani innamorati!\n\nTieni, porta questo biglietto a William. Alloggia alla Lion's Pride Inn, a Goldshire.", enHash = "1daa694c", vanilla = true },
        objectives = { it = "Porta Gramma Stonefield's Note a William Pestle.", enHash = "b8179fa8", vanilla = true },
        progress = { it = "Hai un biglietto da \"Gramma\" Stonefield, eh? Non vedo Mildred da anni! Chissà cos'ha da dire...", enHash = "73d0e27c", vanilla = true },
        reward = { it = "Il mio cuore va a quelle due povere anime, Maybell e Tommy Joe. Ricordo di essere stato giovane e innamorato, una volta.\n\nCi dev'essere qualcosa che posso fare per aiutarli! Fammi pensare...", enHash = "f332d245", vanilla = true },
    },
    [109] = {
        title = { it = "Rapporto a Gryan Stoutmantle", enHash = "17e952e2" },
        text = { it = "Mi sa che di combattimenti ne hai già visti parecchi, $C. Se non l'hai ancora fatto, dovresti presentarti a Gryan Stoutmantle. È a capo della People's Militia, che difende le terre coltivate di Westfall. Scommetto che il tuo aiuto gli farebbe comodo. Di solito lo trovi nella torre di pietra su Sentinel Hill, poco lontano dalla strada, in mezzo a Westfall.", enHash = "9c84a3cb" },
        objectives = { it = "Parla con Gryan Stoutmantle. Di solito lo si trova nella torre di pietra su Sentinel Hill, poco lontano dalla strada, in mezzo a Westfall.", enHash = "4abfb413" },
        reward = { it = "Ah, così ti manda il mio amico? Che gentilezza.\n\nBe', la monarchia di Stormwind ha abbandonato la nostra causa. Ora tocca alla People's Militia tenere la terra libera dalla corruzione. Se la nostra causa ti interessa, posso mettere a frutto le tue capacità di combattimento in nome della libertà.", enHash = "8d755e09", vanilla = true },
    },
    [111] = {
        title = { it = "Parla con Gramma", enHash = "b99c4b77", vanilla = true },
        text = { it = "Ti prego, $N, parla con mia nonna. Se c'è qualcuno che può trovare il modo di farmi stare insieme a Maybell, è lei.\n\nÈ dentro casa nostra, a est di qui.", enHash = "f0b64f92", vanilla = true },
        objectives = { it = "Parla con Gramma Stonefield.", enHash = "7aec53f0", vanilla = true },
        progress = { it = "Non vedo l'ora di sentire come reagiranno i miei amici!\n\nNon se lo aspetteranno mai.", enHash = "71dd776a", vanilla = true },
        reward = { it = "Finché le nostre famiglie sono in lite, Tommy Joe e Maybell non hanno un gran futuro, ma... forse possiamo farli stare insieme almeno per un po'.\n\nMmh, cosa possiamo fare...", enHash = "acbb7c66", vanilla = true },
    },
    [112] = {
        title = { it = "Raccogliere le alghe", enHash = "fae1b906", vanilla = true },
        text = { it = "Posso preparare un Invisibility Liquor per Maybell, così potrà sgattaiolare via dai Maclure Vineyards e raggiungere Tommy Joe. Ma per farlo mi serve del Crystal Kelp.\n\nAnche se di solito le alghe crescono nell'oceano... a volte le raccolgono i murloc. Vedi se i murloc vicino al Crystal Lake ne hanno. Il Crystal Lake è appena a est di Goldshire.", enHash = "c3950638", vanilla = true },
        objectives = { it = "Porta 4 Crystal Kelp Frond a William Pestle, a Goldshire.", enHash = "e0468fcb", vanilla = true },
        progress = { it = "Ce l'hai quel Crystal Kelp? Sono sicuro che Maybell non veda l'ora di rivedere il suo innamorato...", enHash = "f14068af", vanilla = true },
        reward = { it = "Li hai presi. Ottimo! Ora, solo un momento mentre preparo la pozione...", enHash = "901e6387", vanilla = true },
    },
    [114] = {
        title = { it = "La fuga", enHash = "388ef710", vanilla = true },
        text = { it = "Porta questo Invisibility Liquor alla giovane Maybell. Dovrebbe durare abbastanza da permetterle di andare a trovare Tommy Joe.", enHash = "49659461", vanilla = true },
        objectives = { it = "Porta l'Invisibility Liquor a Maybell Maclure.", enHash = "0d46a765", vanilla = true },
        progress = { it = "Hai consegnato la mia lettera a Tommy Joe? Cosa ha detto??", enHash = "c5865fa2", vanilla = true },
        reward = { it = "Oh... santo cielo! Mi sento in colpa a ingannare la mia famiglia, ma quello che provo per Tommy Joe è troppo forte per ignorarlo.\n\nGrazie, $N. Berrò questo liquore appena ne avrò l'occasione e sgattaiolerò via per raggiungere il mio amore.\n\nE per te... prendi questo, ti prego.", enHash = "26420066", vanilla = true },
    },
    [115] = {
        title = { it = "Magia delle ombre", enHash = "4ab5dead", vanilla = true },
        text = { it = "Gli orchi Blackrock hanno arruolato degli shadowcaster per sostenere i loro attacchi a Redridge, e si sono portati dietro strumenti di potere oscuro: i Midnight Orb. Questi orbi hanno inferto colpi pesanti ai difensori di Redridge, ed è indispensabile togliere dal conflitto questi oggetti corrotti dai demoni.\n\nTrova e portami i Midnight Orb degli shadowcaster Blackrock che avrai ucciso. Li farò distruggere: questo mondo sarebbe un posto migliore senza di loro!", enHash = "41e03f20", vanilla = true },
        objectives = { it = "Porta 3 Midnight Orb a Marshal Marris, a Lakeshire.", enHash = "a8411d5f", vanilla = true },
        progress = { it = "Come va lo scontro con gli shadowcaster? Li hai trovati i Midnight Orb?", enHash = "61615289", vanilla = true },
        reward = { it = "Grazie, $N. Li manderò subito a distruggere.", enHash = "59d06fa9", vanilla = true },
    },
    [116] = {
        title = { it = "Tempi di magra", enHash = "6b027491", vanilla = true },
        text = { it = "Mi trovo proprio in difficoltà, $N. Le bottiglie stanno per finire. L'ultimo carico di alcolici è in ritardo da un pezzo. L'invasione degli orchi è stata un inferno.\n\nMagari potresti lavorare per me?\n\nMi serve che tu vada a prendere un barilotto di Thunderbrew Lager da Grimbooze Thunderbrew, sulle colline di Westfall, una botticella di Merlot a Stormwind, una bottiglia di Moonshine a Darkshire e un otre di Sweet Rum a Goldshire. Portameli qui e farò in modo che tu sia $Gricompensato:ricompensata;.", enHash = "430f42f9", vanilla = true },
        objectives = { it = "Barkeep Daniels di Lakeshire ha bisogno di un barilotto di Thunderbrew Lager, una botticella di Merlot, una bottiglia di Moonshine e un otre di Sweet Rum.", enHash = "f576f671", vanilla = true },
        progress = { it = "Mi serve che tu vada a prendere un barilotto di Thunderbrew Lager da Grimbooze Thunderbrew, sulle colline di Westfall, una botticella di Merlot a Stormwind, una bottiglia di Moonshine a Darkshire e un otre di Sweet Rum a Goldshire. Portameli qui e farò in modo che tu sia $Gricompensato:ricompensata;.", enHash = "92642ea4", vanilla = true },
        reward = { it = "Un ottimo lavoro, $N! So bene quante strade hai dovuto percorrere per procurarti questa bella scelta di liquori. Ma i miei clienti torneranno a essere contenti!\n\nMia moglie è una brava sarta. Accetta questo mantello che ha cucito lei, in cambio del tuo servizio.", enHash = "3c1afa00", vanilla = true },
    },
    [117] = {
        title = { it = "Thunderbrew", enHash = "783c4fe6", vanilla = true },
        text = { it = "Fa' presto, $Gamico mio:amica mia;, muoviti in fretta, \nperché la nostra ricca lager abbia il gusto \ndella birra e non della minestra, \nper la cotta servono i luppoli.", enHash = "e7addf14", vanilla = true },
        objectives = { it = "Porta a Grimbooze Thunderbrew 5 Hops per completare la sua birra speciale.", enHash = "35e552f4", vanilla = true },
        progress = { it = "Fa' presto, $Gamico mio:amica mia;, muoviti in fretta, \nperché la nostra ricca lager abbia il gusto\ndella birra e non della minestra,\nper la cotta servono i luppoli.", enHash = "bf69c060", vanilla = true },
        reward = { it = "Luppolo e orzo, lievito e malto, \nle papille subiscono un vero assalto, \nnon c'è da implorare, non c'è da pregare: \nla Thunderbrew Lager arriva in barile!", enHash = "a1a4d62a", vanilla = true },
    },
    [118] = {
        title = { it = "Il prezzo dei ferri", enHash = "19cbafe5", vanilla = true },
        text = { it = "Ho usato così tanto ferro per equipaggiare le Stormwind Guard che non me ne resta abbastanza per ferrare i cavalli della stalla!\n\nPorta questo biglietto a Blacksmith Argus, a Goldshire. Gli spiega il mio problema e gli chiede un carico di ferri di cavallo.", enHash = "73e2e03c", vanilla = true },
        objectives = { it = "Porta Verner's Note a Smith Argus, a Goldshire.", enHash = "06e13c7f", vanilla = true },
        progress = { it = "Cosa c'è? Ti manda Verner, dici? Be', dammelo il suo biglietto. E PARLA PIÙ FORTE!", enHash = "9f69f44c", vanilla = true },
        reward = { it = "Eh, così al vecchio Verner servono dei ferri!?!", enHash = "28a51cfc", vanilla = true },
    },
    [119] = {
        title = { it = "Torna da Verner", enHash = "d702696d", vanilla = true },
        text = { it = "Va bene, glieli do i suoi 50 ferri di cavallo...\n\nEccoli qua, tutti incassati e pronti da portare! Di' a Verner che è stato un piacere fare affari, e assicurati che legga il biglietto attaccato a questa cassa!", enHash = "bd856be2", vanilla = true },
        objectives = { it = "Torna da Verner Osgood, a Redridge. Dagli il Crate of Horseshoes.", enHash = "06f59d24", vanilla = true },
        progress = { it = "Ottimo, sei $Gtornato:tornata;! Li hai presi i ferri?", enHash = "3a5be468", vanilla = true },
        reward = { it = "Grazie, questo mi aiuta davvero.\n\nMa cos'è questo? Argus ha mandato un biglietto con la cassa... Cosa?? Argus vuole che lo PAGHI? Bah!\n\nBe', $N, grazie dell'aiuto.", enHash = "056f9162", vanilla = true },
    },
    [120] = {
        title = { it = "Messaggero per Stormwind", enHash = "7ba88cf9", vanilla = true },
        text = { it = "Sono tempi duri, $C. La cittadina è sotto assedio continuo. Senza rinforzi andremo di sicuro incontro alla sconfitta. Il messaggio che ora ti affido è della massima importanza. Fa' arrivare subito questo rapporto a General Marcus Jonathan, a Stormwind. Una volta fatta la consegna, torna immediatamente da me con qualunque notizia, buona o cattiva.\n\nE ora fa' presto!", enHash = "7ced098a", vanilla = true },
        objectives = { it = "Magistrate Solomon ti ha dato un rapporto da consegnare a General Marcus Jonathan, a Stormwind. Il giudice vuole che torni da lui appena fatta la consegna.", enHash = "dd92416c", vanilla = true },
        progress = { it = "Che cos'hai lì?", enHash = "c31a5dd8", vanilla = true },
        reward = { it = "Riposo, $C.\n\nMagistrate Solomon è un capo nobile. Le sue parole hanno molto peso per me. Chiederò udienza al Re e gli esporrò con chiarezza la situazione. Assicura al buon giudice che ha il sostegno dell'esercito di Stormwind. I rinforzi partiranno appena arriverà l'ordine di Sua Maestà.", enHash = "fc59012d", vanilla = true },
    },
    [121] = {
        title = { it = "Messaggero per Stormwind", enHash = "7ba88cf9", vanilla = true },
        text = { it = "Mentre aspetto una risposta dal Re, voglio che tu porti questa lettera a Magistrate Solomon.\n\nPuoi andare, $C!", enHash = "0e4ebc50", vanilla = true },
        objectives = { it = "Porta la lettera di risposta di General Marcus Jonathan a Magistrate Solomon, a Lakeshire.", enHash = "6c705119", vanilla = true },
        progress = { it = "Il generale ha mandato notizie? I rinforzi stanno arrivando?", enHash = "4807406a", vanilla = true },
        reward = { it = "Grazie del tuo tempo, $C. Per il servizio reso a Lakeshire e a Stormwind ti ricompenso con queste monete.\n\nE ora scusami, ma trovo questa corrispondenza alquanto misteriosa. Qualcosa non va nel nostro Regno. Temo che questo sia l'inizio del conflitto, non la fine.", enHash = "486bea86", vanilla = true },
    },
    [122] = {
        title = { it = "Squame del ventre", enHash = "0308decb", vanilla = true },
        text = { it = "Mi servono delle squame del ventre dei cuccioli di drago nero per pagare i ferri che Argus mi ha mandato da Goldshire. Se me ne procuri 6, posso pagarne una parte ad Argus... e me ne resta abbastanza per fabbricare qualcosa per te.\n\nI Black Dragon Whelp volano spesso a sud di Lakeshire, ma tendono a vagare. Potresti dover stare all'erta e cacciarli quando li vedi.", enHash = "ce9fd68f", vanilla = true },
        objectives = { it = "Raccogli 6 Underbelly Whelp Scale dai Black Dragon Whelp e portale a Verner Osgood, a Redridge.", enHash = "8af92dc9", vanilla = true },
        progress = { it = "Lo so che quell'avido di Argus manderà qualcuno a prendersi le sue squame, se non gliele do presto. Le hai trovate quelle squame?", enHash = "869d0706", vanilla = true },
        reward = { it = "Grazie! Queste mi tirano fuori dai debiti con Argus...", enHash = "a474b3c4", vanilla = true },
    },
    [123] = {
        title = { it = "Il Collector", enHash = "eb36979e", vanilla = true },
        text = { it = "Questo biglietto è un registro con l'elenco dei giorni e delle ore in cui una persona — indicata solo come \"The Collector\" — riceverà un carico d'oro dalle miniere dell'Elwynn Forest.\n\nDal registro sembra che il Collector risieda vicino al Brackwell Pumpkin Patch, a Elwynn est.\n\nLa cosa sembra importante. Dovresti riferirla a Marshal Dughan, a Goldshire.", enHash = "e425d61e", vanilla = true },
        objectives = { it = "Va' da Marshal Dughan, a Goldshire, e dagli The Collector's Schedule.", enHash = "7f902745", vanilla = true },
        progress = { it = "Cosa?!? Sono mesi che i nostri uomini non lavorano nelle miniere di Elwynn!\n\nFammi vedere quel biglietto che hai...", enHash = "a80d9460", vanilla = true },
        reward = { it = "Mmh... Ho sentito parlare di questo \"Collector\", ma non so per chi lavori. Grazie per il registro. Ci aiuterà a risolvere questo mistero.", enHash = "dabea12d", vanilla = true },
    },
    [124] = {
        title = { it = "Un ululato di gnoll", enHash = "4bc6793b", vanilla = true },
        text = { it = "Come se gli orchi che ci attaccano non bastassero! Adesso ho gnoll bruti e mistici che si aggirano lungo il crinale a nord della mia stalla, e si prendono i cavalli quando si allontanano...\n\nSe riesci a liberarci di quegli gnoll, io e i miei cavalli te ne saremmo molto grati.", enHash = "627d6b5a", vanilla = true },
        objectives = { it = "Uccidi 10 Redridge Brute e 8 Redridge Mystic, poi torna da Verner Osgood.", enHash = "9e56d6d6", vanilla = true },
        progress = { it = "I miei cavalli sono ancora nervosi, e di notte sento ancora quel maledetto ululato di lupo. Ti prego, $N, fa' qualcosa per quegli gnoll!", enHash = "85f88706", vanilla = true },
        reward = { it = "Grazie di tutto il tuo aiuto, $N.", enHash = "505bb18f", vanilla = true },
    },
    [125] = {
        title = { it = "Gli attrezzi perduti", enHash = "1bba50ee", vanilla = true },
        text = { it = "Mi servirebbe proprio una mano qui, $N. Con il paese sotto assedio è difficile far arrivare i rifornimenti. I miei attrezzi stavano arrivando da Goldshire su un carro, ma il ponte è saltato. Abbiamo messo gli attrezzi su una barca e gli orchi l'hanno centrata con una catapulta. Con la mia fortuna, la cassetta degli attrezzi è colata a picco sul fondo del lago.\n\nRecupera la mia cassetta, $N, e ne varrà la pena.", enHash = "583b2ade", vanilla = true },
        objectives = { it = "Foreman Oslow di Lakeshire vuole che tu recuperi la sua cassetta degli attrezzi dal fondo del Lake Everstill.", enHash = "50124ff3", vanilla = true },
        progress = { it = "Sei $Griuscito:riuscita; a trovare i miei attrezzi?", enHash = "79401330", vanilla = true },
        reward = { it = "Un recupero eccellente, $N! Non pensavo che avrei rivisto questi attrezzi.", enHash = "637c464d", vanilla = true },
    },
    [126] = {
        title = { it = "Ululati sulle colline", enHash = "a8f98242", vanilla = true },
        text = { it = "$N, gli gnoll sono ancora là fuori. Sento i loro latrati mentre cacciano sulle colline sopra Lakeshire. E un ululato è più forte degli altri: Yowler, il loro capo.\n\nUccidi Yowler e disperdi il suo branco! Portami la sua zampa come prova.\n\nE sta' $Gattento:attenta;: questo gnoll non è il loro capo per caso. Non è un Mongrel qualsiasi...", enHash = "3834a2eb", vanilla = true },
        objectives = { it = "Porta Yowler's Paw a Verner Osgood, a Lakeshire.", enHash = "36dc173d", vanilla = true },
        progress = { it = "Yowler è una creatura pericolosa, $N. Se non sei $Gpronto:pronta; ad affrontarlo, capisco.", enHash = "d66ee62a", vanilla = true },
        reward = { it = "Ancora una volta, grazie dell'aiuto. L'esercito di Stormwind è così impegnato con gli orchi che non ha truppe per proteggere Redridge dalle minacce locali come gli gnoll.", enHash = "9937529d", vanilla = true },
    },
    [127] = {
        title = { it = "Vendere pesce", enHash = "d6e14928", vanilla = true },
        text = { it = "Il Lake Everstill è famoso per i suoi Spotted Sunfish. C'è sempre richiesta... e io sono a corto!\n\nPortamene una partita di 10 e te li pagherò bene. Se non sai pescare, allora... magari puoi prenderli dai murloc!", enHash = "6714eca0", vanilla = true },
        objectives = { it = "Porta 10 Spotted Sunfish a Dockmaster Baren, a Lakeshire.", enHash = "6592e429", vanilla = true },
        progress = { it = "Hai un po' di Spotted Sunfish per me, eh?", enHash = "da37ade8", vanilla = true },
        reward = { it = "È un piacere fare affari con te, $Gcompagno:compagna;!", enHash = "c289340a", vanilla = true },
    },
    [128] = {
        title = { it = "Taglia sui Blackrock", enHash = "90f68067", vanilla = true },
        text = { it = "Il Blackrock Clan va distrutto. Il Nemico ha invaso le nostre terre. Queste montagne ricadono sotto il diritto sovrano del Re di Stormwind. Le nostre fonti ci dicono che i capi di ogni unità del Clan sono chiamati Champion. Li trovi nel loro accampamento a nord, appena a ovest della strada per le Burning Steppes.\n\nMagistrate Solomon vuole morti questi bruti immondi. Uccidi 15 Blackrock Champion e torna da me.", enHash = "1bdbd0a1", vanilla = true },
        objectives = { it = "Uccidi 15 Blackrock Champion e Guard Howe, a Lakeshire, ti ricompenserà.", enHash = "0804909a", vanilla = true },
        progress = { it = "Torna quando avrai ucciso 15 Blackrock Champion.", enHash = "9e2bc621", vanilla = true },
        reward = { it = "Vedo che hai combattuto valorosamente contro il Blackrock Clan, $C. Il tuo servizio alla nostra cittadina è davvero grande.", enHash = "eda201b0", vanilla = true },
    },
    [129] = {
        title = { it = "Un pranzo gratis", enHash = "fa126d95", vanilla = true },
        text = { it = "Mi fai un favore? Ho preparato un pranzo per Guard Parker, ma è fuori di pattuglia... lui è una guardia di Stormwind grande e grossa e sa difendersi, ma là fuori è troppo pericoloso per una cittadina come me.\n\nQuindi, se gli porti tu il pranzo e poi torni qui, ti offro un pranzo gratis! Parker pattuglia il tratto di strada che porta a Duskwood.", enHash = "e0d377f7", vanilla = true },
        objectives = { it = "Porta Parker's Lunch a Guard Parker. Lui pattuglia la strada che porta a Darkshire.", enHash = "3cea1f77", vanilla = true },
        progress = { it = "Me lo manda Darcy un pranzo, eh? Che cuore gentile che ha. Be'... vediamolo!", enHash = "3b062d0b", vanilla = true },
        reward = { it = "Grazie, un pasto mi serviva proprio. Difendere Lakeshire da orchi e gnoll è un lavoro duro!", enHash = "5832196f", vanilla = true },
    },
    [130] = {
        title = { it = "Visita all'erborista", enHash = "0e8861ae", vanilla = true },
        text = { it = "Prima di tornare da Darcy, le porteresti dei fiori da parte mia? Li trovi al negozio dell'erborista, a Lakeshire, all'estremità ovest del paese.\n\nMa quando prendi i fiori... non dire all'erborista, Martie, da chi vengono né per chi sono...", enHash = "7accae00", vanilla = true },
        objectives = { it = "Parla con l'erborista di Redridge, Martie Jainrose.", enHash = "30a44d50", vanilla = true },
        reward = { it = "Ti serve un mazzo di fiori? Non sei in paese da molto... hai già trovato qualcuno che ti fa battere il cuore, qui?\n\nSo che non dovrei ficcanasare, ma fa piacere vedere che c'è amore nell'aria... soprattutto in tempi pericolosi come questi.", enHash = "14173403", vanilla = true },
    },
    [131] = {
        title = { it = "Consegna di narcisi", enHash = "46a00a1b", vanilla = true },
        text = { it = "Ecco il tuo mazzo. Per te ho scelto i narcisi. Sono i miei preferiti!", enHash = "fb2a4b9c", vanilla = true },
        objectives = { it = "Da' a Darcy il Daffodil Bouquet.", enHash = "43ff486b", vanilla = true },
        progress = { it = "Ciao di nuovo, $N. Gli è piaciuto il pranzo che gli ho mandato, a Parker?", enHash = "e2086440", vanilla = true },
        reward = { it = "Oh, che belli! Non vedo l'ora di metterli nell'acqua!\n\nPerò... questi sono i fiori preferiti di Martie. Non ti avrà mandato da quella volpe gelosa a prendere il mazzo, Parker? Non le avrai detto per chi erano, vero? Perché se gliel'hai detto, non mi stupirebbe che li avesse avvelenati.\n\nOh, ma non è colpa tua. Grazie, ed ecco il tuo pasto.", enHash = "530efa99", vanilla = true },
    },
    [132] = {
        title = { it = "La Defias Brotherhood", enHash = "86683501", vanilla = true },
        text = { it = "Quello che sto per dirti potrebbe costarmi la vita. La banda dei Defias sta preparando qualcosa di grosso. L'ultima volta che ne ho sentito parlare lavoravano insieme a vari gnoll, kobold e perfino goblin.\n\nPorta questo biglietto a Stoutmantle. Spiega tutto quello che so sull'argomento.", enHash = "2321260a", vanilla = true },
        objectives = { it = "Porta Wiley's Note a Gryan Stoutmantle, in Westfall.", enHash = "29f1d224", vanilla = true },
        progress = { it = "È un piacere rivederti, $N. Cos'aveva da dire Wiley?", enHash = "21e11356", vanilla = true },
        reward = { it = "Bah! Avrei dovuto lasciar marcire quel farabutto quando ne avevo l'occasione. Ma questa informazione è cruciale. Bel lavoro.", enHash = "3b46c4ff", vanilla = true },
    },
    [133] = {
        title = { it = "Effigie per i ghoul", enHash = "f823277d", vanilla = true },
        text = { it = "Vivo così lontano dalla protezione del paese che è un miracolo se i ghoul e i morti che camminano non mi hanno ancora mangiato! Anzi, proprio ieri un branco di Bone Chewer martellava sui muri di casa mia!\n\nVoglio fare un'effigie — una specie di \"spaventapasseri\" per i ghoul. Per farla mi servono delle Ghoul Rib. Puoi prenderle da Flesh Eater, Bone Chewer, Brain Eater, Rotted One e Plague Spreader.\n\nPortami le costole e ti ripagherò con qualche moneta.", enHash = "edb082cb", vanilla = true },
        objectives = { it = "Raccogli 7 Ghoul Rib e portale ad Abercrombie, alla sua baracca.", enHash = "930c5791", vanilla = true },
        progress = { it = "Mi sembra di sentire un branco di ghoul che sgattaiola dietro casa — meglio che tiri su in fretta quell'effigie! Me le hai prese quelle Ghoul Rib?", enHash = "095394d7", vanilla = true },
        reward = { it = "Ah, grazie. Faranno proprio al caso mio!", enHash = "9c0da8c3", vanilla = true },
    },
    [134] = {
        title = { it = "Ogre ladri", enHash = "31a695ff", vanilla = true },
        text = { it = "Qualche settimana fa stavo raccogliendo erbe lontano da casa, e una banda di ogre mi ha assalito! Sono scappato, e ho dovuto lasciare indietro una cassa di attrezzi e di erbe preziose.\n\nDopo avermi cacciato, gli ogre sono tornati impettiti al tumulo degli ogre nel sud di Duskwood. Sono sicuro che la mia cassa è da qualche parte vicino al tumulo.\n\nTi prego, $N, recuperamela, perché mi manca tantissimo.", enHash = "2e566944", vanilla = true },
        objectives = { it = "Riporta Abercrombie's Crate ad Abercrombie.", enHash = "a19543d2", vanilla = true },
        progress = { it = "Ce l'hai la mia cassa? Se sì, allora ti prego... dammela subito!", enHash = "241e0e56", vanilla = true },
        reward = { it = "Grazie al Negrom-... be', grazie a TE, $N! Ti sei $Gguadagnato:guadagnata; la ricompensa e anche di più.\n\nAha! Felice! Notti felici in arrivo!!", enHash = "68043f98", vanilla = true },
    },
    [135] = {
        title = { it = "La Defias Brotherhood", enHash = "86683501", vanilla = true },
        text = { it = "Mi chiedo cosa intendesse Wiley quando ha nominato gli Stonemason. Forse gli è scappato di bocca. Possibile che la banda dei Defias sia legata agli Stonemason? Solo un uomo lo saprebbe con certezza: Mathias Shaw, a capo dello SI:7. Mostragli Wiley's Note e vedi se ha qualcosa da aggiungere a questo mistero che si allarga. Se fai fatica a trovare Shaw, controlla nei Barracks dell'Old Town.", enHash = "3892614e", vanilla = true },
        objectives = { it = "Porta Wiley's Note a Mathias Shaw, a Stormwind.", enHash = "972f6d06", vanilla = true },
        progress = { it = "Che affari hai con me? Sono un uomo molto occupato...", enHash = "4fc67c16", vanilla = true },
        reward = { it = "Questa faccenda potrebbe essere più complessa di quanto Stoutmantle non creda.", enHash = "e3aba976", vanilla = true },
    },
    [136] = {
        title = { it = "Il tesoro nascosto di Captain Sanders", enHash = "f425b4de", vanilla = true },
        text = { it = "Se stai leggendo questo, vuol dire che il vecchio Captain Sanders riposa in fondo al mare. Quindi il mio tesoro adesso è tuo, ti basta seguire gli indizi.\n\nPer prima cosa devi trovare il mio baule. Ormai sarà mezzo sepolto nella sabbia, lungo la costa occidentale di Westfall, vicino al relitto. Di relitti ce n'è tanti, ma sulla costa c'è una sola ancora arrugginita. Trova quell'ancora e troverai il mio baule! Cerca lì dentro il prossimo indizio.", enHash = "8c86bbc4", vanilla = true },
        objectives = { it = "Trova il baule di Captain Sanders e cercaci dentro il prossimo indizio.", enHash = "0fc78f76", vanilla = true },
        reward = { it = "Il baule si apre lentamente, cigolando. Sabbia e acqua sembrano essere il suo unico contenuto. Ma aspetta! Un piccolo granchio sguscia fuori con un indizio per il tesoro tra le chele!", enHash = "29818490", vanilla = true },
    },
    [138] = {
        title = { it = "Il tesoro nascosto di Captain Sanders", enHash = "f425b4de", vanilla = true },
        text = { it = "L'indizio per il tesoro dice: Bel lavoro, $Gcompagno:compagna;! Ora devi puntare dritto a est. A est su per le alture, a est fino alla strada. Cerca le vecchie rovine del camino vicino al bordo della strada. Là troverai un vecchio barile con il tuo prossimo indizio.", enHash = "ba2a4778", vanilla = true },
        objectives = { it = "Trova il vecchio barile vicino al camino in rovina e cercaci dentro il prossimo indizio.", enHash = "22faa994", vanilla = true },
        reward = { it = "Bel lavoro, $Gcacciatore:cacciatrice; di tesori!", enHash = "cb2d5b59", vanilla = true },
    },
    [139] = {
        title = { it = "Il tesoro nascosto di Captain Sanders", enHash = "f425b4de", vanilla = true },
        text = { it = "Frugando nel barile trovi un altro pezzo di pergamena. Questo dice: Ora, da questo barile, volgiti a nord. Dritto, in linea d'aria, continua a camminare finché non vedi la brocca vuota accanto al mulino a vento solitario sulle alture a picco sul mare. Se frughi intorno a quella brocca, potresti trovare proprio ciò che cerchi.", enHash = "1c46e954", vanilla = true },
        objectives = { it = "Cerca il prossimo indizio nella brocca vuota accanto al mulino a vento.", enHash = "d4fb0b05", vanilla = true },
        reward = { it = "Sei sulla strada del colpo grosso, cercatore di tesori!", enHash = "eff6c123", vanilla = true },
    },
    [140] = {
        title = { it = "Il tesoro nascosto di Captain Sanders", enHash = "f425b4de", vanilla = true },
        text = { it = "E infatti, in fondo all'Old Jug c'è un altro indizio per il tesoro di Sanders. L'inchiostro è colato in alcuni punti e la carta sa di whisky, ma qualche riga si riesce a leggere: Ora che hai trovato la mia vecchia brocca di whisky, sei quasi al tesoro! Volgiti a ovest dalla bottiglia e scendi fino alla riva. Una volta $Garrivato:arrivata; all'acqua, continua! Nuota dritto a ovest finché non trovi l'isola con il mio baule del tesoro!", enHash = "1b6eff1b", vanilla = true },
        objectives = { it = "Trova il baule di Captain Sanders e aprilo per la tua ricompensa.", enHash = "fdcd9b81", vanilla = true },
        reward = { it = "I cardini del vecchio baule sono arrugginiti, ma funzionano ancora. Forzi il baule e prendi il bottino.\n\nCongratulazioni!", enHash = "d7b60682", vanilla = true },
    },
    [141] = {
        title = { it = "La Defias Brotherhood", enHash = "86683501", vanilla = true },
        text = { it = "La Stonemasons' Guild era guidata da un uomo di nome Edwin VanCleef. VanCleef fu il responsabile della ricostruzione di Stormwind dopo che gli orchi la rasero al suolo nella Prima Guerra. A quanto pare VanCleef e i suoi uomini non furono contenti di come li trattò il re a ricostruzione finita. Questo potrebbe spiegare un paio di cose.\n\nHo scritto un resoconto più dettagliato per il tuo Maestro in Westfall. Portaglielo subito!", enHash = "9e7a19e7", vanilla = true },
        objectives = { it = "Porta il rapporto di Shaw a Gryan Stoutmantle, in Westfall.", enHash = "bcaed7b7", vanilla = true },
        progress = { it = "Master Shaw ha fatto luce sulla faccenda?", enHash = "3fb7e64b", vanilla = true },
        reward = { it = "Edwin VanCleef... conosco bene quel nome. Pensare che un uomo così operoso e capace possa trasformarsi in un simile farabutto mi turba. Mi serviranno altre prove prima di crederci.", enHash = "28cdba96", vanilla = true },
    },
    [142] = {
        title = { it = "La Defias Brotherhood", enHash = "86683501", vanilla = true },
        text = { it = "Dobbiamo scoprire dove si trova il nascondiglio dei Defias. $N, il mio esploratore riferisce che un Defias Messenger è stato visto sulle strade tra Moonbrook, la Gold Coast Quarry e la Jangolode Mine. Voglio che tu lo catturi. Se oppone resistenza, uccidilo e portami tutto ciò che ha con sé.", enHash = "6e0d25cc", vanilla = true },
        objectives = { it = "Da' la caccia al Defias Messenger in Westfall e porta il suo messaggio a Stoutmantle.", enHash = "455fc83b", vanilla = true },
        progress = { it = "$N, sei $Griuscito:riuscita; a raccogliere qualche informazione? Hai trovato il messaggero?", enHash = "4da5e9dc", vanilla = true },
        reward = { it = "Questa sì che è una prova solida che al comando c'è VanCleef. Ora ci resta solo da sapere dove si nasconde la banda dei Defias.\n\nMentre eri via abbiamo avuto un colpo di fortuna. Abbiamo catturato un ladro che cercava di rubare il carro di Saldean. Ha promesso di condurci al nascondiglio in cambio della vita. Voglio che tu difenda il traditore, così potrà rivelarci il nascondiglio. Torna da me quando avrai scoperto il posto.", enHash = "00e82384", vanilla = true },
    },
    [143] = {
        title = { it = "Messaggero per Westfall", enHash = "806c5822", vanilla = true },
        text = { it = "C'è qualcosa di strano nell'esercito di Stormwind. A quest'ora avrebbero già dovuto essere qui in forze. Il tempo, però, è un lusso che non abbiamo. Non resterò a guardare mentre la gente di Lakeshire dà la vita, senza prima cercare altri aiuti. Mi è arrivata voce che a Westfall si sta formando una milizia popolare.\n\nPorta questo appello al loro capo, Gryan Stoutmantle. Forse gli uomini di Stoutmantle possono darci un po' di sostegno qui, finché il Re non manda le riserve.", enHash = "ceaf1bae", vanilla = true },
        objectives = { it = "Magistrate Solomon vuole che tu porti il suo appello scritto a Gryan Stoutmantle, a Westfall.", enHash = "4e5a33b0", vanilla = true },
        progress = { it = "Salve, $C. Che affari hai con la People's Militia?", enHash = "d542aaed", vanilla = true },
        reward = { it = "$GBuon messaggero:Buona messaggera;, hai servito bene il tuo padrone.", enHash = "6783d797", vanilla = true },
    },
    [144] = {
        title = { it = "Messaggero per Westfall", enHash = "806c5822", vanilla = true },
        text = { it = "Il biglietto di Magistrate Solomon mi fa male a leggerlo. Ma è evidente che non sa nulla della guerra che si combatte a Westfall, altrimenti non si aspetterebbe aiuto dalla Militia. Se anche Stormwind non ci avesse abbandonati, non avremmo avuto bisogno della Militia.\n\nPorta questa risposta al tuo padrone a Redridge, $C. E fagli sapere che ho il cuore pesante per la perdita di brav'uomini.", enHash = "dd3c6c17", vanilla = true },
        objectives = { it = "Torna da Magistrate Solomon con la risposta di Gryan Stoutmantle.", enHash = "126461e1", vanilla = true },
        progress = { it = "Dobbiamo aspettarci presto la People's Militia? Le notizie di Lord Stoutmantle sono buone?", enHash = "0c481d0a", vanilla = true },
        reward = { it = "Devo dire che non va affatto bene. Non immaginavo che la situazione di Stoutmantle non fosse diversa dalla nostra qui a Lakeshire. Quale azione è tanto importante da richiamare l'esercito di Stormwind lontano dalla sua gente? Bah, non dovrei rimuginare ad alta voce.\n\nEcco, messaggero. Accetta queste monete in cambio del servizio reso alla cittadina. Potrei chiamarti di nuovo.", enHash = "5678c1b8", vanilla = true },
    },
    [145] = {
        title = { it = "Messaggero per Darkshire", enHash = "a8fe38b9", vanilla = true },
        text = { it = "Mi serve di nuovo il tuo aiuto. Ho scritto a Lord Ebonlocke chiedendogli di mandare le sue guardie addestrate, la Guardia Notturna, ad aiutare nella difesa di Lakeshire. È indispensabile che il messaggio gli arrivi in fretta. Devi usare la massima prudenza. Ebonlocke è il sindaco di Darkshire, nel cuore di Duskwood. Non allontanarti dalle strade.", enHash = "0c5e5d52", vanilla = true },
        objectives = { it = "Magistrate Solomon vuole che tu porti una lettera a Lord Ebonlocke, a Darkshire.", enHash = "2265d583", vanilla = true },
        progress = { it = "Sembri venire da lontano, $C. Cosa ti porta qui a Darkshire?", enHash = "16306bf8", vanilla = true },
        reward = { it = "Grazie per aver fatto un viaggio così lungo. Sono informazioni davvero importanti.", enHash = "dfa8f337", vanilla = true },
    },
    [146] = {
        title = { it = "Messaggero per Darkshire", enHash = "a8fe38b9", vanilla = true },
        text = { it = "Se non conoscessi di persona Magistrate Solomon, direi che quell'uomo è impazzito. Mandare la Guardia Notturna a Lakeshire perché Stormwind rifiuta gli aiuti? La Guardia Notturna è nata proprio perché Stormwind ci ha abbandonati quando questa magia immonda è filtrata nella terra. Se mandassi via la mia Guardia Notturna, questo paese sarebbe travolto dal male prima ancora che le guardie raggiungano il limitare della foresta.\n\nPorta questa lettera di risposta a chi ti ha mandato, a Lakeshire.", enHash = "2bb5b26a", vanilla = true },
        objectives = { it = "Torna da Magistrate Solomon con la lettera di risposta di Lord Ebonlocke.", enHash = "8a0219f0", vanilla = true },
        progress = { it = "Ah, che piacere rivederti, messaggero. Devo informare il maresciallo che la Guardia Notturna è in arrivo da Darkshire?", enHash = "da0e3beb", vanilla = true },
        reward = { it = "Per la Luce! L'esercito di Stormwind si è ritirato da Westfall. E la Guardia non protegge più Darkshire? Qui c'è di mezzo un tradimento. Com'è possibile?\n\nOh, ho dimenticato di ricompensare il tuo servizio, $C. Ecco qualche moneta. E ora scusami. Qualcosa non va a Stormwind e devo vederci chiaro.", enHash = "cb8a3e28", vanilla = true },
    },
    [147] = {
        title = { it = "Caccia all'uomo", enHash = "31cc73ed", vanilla = true },
        text = { it = "Se il \"Collector\" prende l'oro dalle nostre miniere, allora sta rubando al regno! Consegna il Collector alla giustizia e portami l'anello citato nel registro delle consegne che mi hai dato. Forse ci dirà per chi lavora il Collector...\n\nQuel registro delle consegne dice che il Collector si nasconde al Brackwell Pumpkin Patch. Dovresti cercarlo lì.", enHash = "e0fab75e", vanilla = true },
        objectives = { it = "Trova e uccidi \"the Collector\", poi torna da Marshal Dughan con The Collector's Ring.", enHash = "b421bf09", vanilla = true },
        progress = { it = "Hai trovato il Collector? Hai scoperto per chi lavora?", enHash = "086b08ba", vanilla = true },
        reward = { it = "L'hai trovato? Ben fatto, $N. Non \"riscuoterà\" più dalle miniere di Elwynn!\n\nE questo anello che hai trovato è interessante... è un anello da membro della vecchia Stonemason's Guild di Stormwind. Perché un ladruncolo da quattro soldi dovrebbe avere l'anello di una gilda di artigiani, e perché i ladri Defias riscuotono denaro dalle nostre miniere?\n\nDomande difficili. Spero che un giorno avremo delle risposte.", enHash = "050863cd", vanilla = true },
    },
    [148] = {
        title = { it = "Rifornimenti da Darkshire", enHash = "7bcac1ee", vanilla = true },
        text = { it = "Oh, cosa può fare un povero vecchio? Mi servono dei rifornimenti da Darkshire, ma il villaggio è così lontano e io sono così vecchio e malandato... non ce la farei mai a fare il viaggio.\n\nPuoi andare a Darkshire e portarmi del Ghost Hair Thread? Puoi averlo da Madame Eva, a casa sua, sulla piazza di Darkshire.", enHash = "6372cd76", vanilla = true },
        objectives = { it = "Parla con Madame Eva.", enHash = "d9ec29e9", vanilla = true },
        reward = { it = "Ah, ti serve del Ghost Hair Thread, vero? Temo di non averne, ma posso fartene un po'... se mi procuri tu i capelli di fantasma.", enHash = "57ac0b06", vanilla = true },
    },
    [149] = {
        title = { it = "Ghost Hair Thread", enHash = "15af2bf7", vanilla = true },
        text = { it = "C'è un povero spirito triste, Blind Mary, che infesta una vecchia fattoria sulle colline a sud di Darkshire.\n\nTieni, prendi questo Spectral Comb e chiedi a Blind Mary di pettinarsi. Poi riportami il pettine e ne ricaverò i Ghost Hair che mi servono per il filo.\n\nE sta' $Gattento:attenta;, perché adesso vicino a quella casa si annidano cose oscure...", enHash = "7b940cd1", vanilla = true },
        objectives = { it = "Porta lo Spectral Comb a Blind Mary.", enHash = "3d0c5e63", vanilla = true },
        progress = { it = "<Singhiozzo> Oh, ti prego, non guardarmi! Mi sono strappata questi occhi con le mie mani, eppure sento ancora il tuo sguardo!\n\nSono orrenda! Orrenda! Ti prego, gira lo sguardo!!", enHash = "b214f6e5", vanilla = true },
        reward = { it = "Cos'è questo? Un pettine? È bellissimo! E scivola tra i miei capelli come se non fossero l'orrore rigido e stopposo che sono.\n\nOh, se solo avessi uno specchio...", enHash = "cff8f7f9", vanilla = true },
    },
    [150] = {
        title = { it = "Bracconieri murloc", enHash = "8fb37b89", vanilla = true },
        text = { it = "I murloc stanno diventando un problema. Gruppi sempre più grandi di quegli uomini-pesce gettano l'ancora lungo le rive del Lake Everstill e pescano a più non posso! Dobbiamo toglierli di mezzo prima che si mangino tutto il pesce del lago!\n\nCaccia i murloc! Portami otto delle loro pinne e forse avrò qualcosa per te...", enHash = "fbc46c75", vanilla = true },
        objectives = { it = "Porta 8 Murloc Fin a Dockmaster Baren, a Lakeshire.", enHash = "d00a7583", vanilla = true },
        progress = { it = "Le hai quelle pinne? Sbrigati, dobbiamo cacciare quei murloc dal lago!", enHash = "9f24581d", vanilla = true },
        reward = { it = "Ben fatto, $N. Spero che quei murloc non ti abbiano dato troppo filo da torcere.\n\nÈ strano vederli così lontani dal mare. Mi chiedo se non siano qui perché stanno scappando da qualcosa...", enHash = "952bc0f7", vanilla = true },
    },
    [151] = {
        title = { it = "Povera vecchia Blanchy", enHash = "44aacf66", vanilla = true },
        text = { it = "Povera vecchia Blanchy! Una bestia così stanca, dopo tutto il lavoro che le abbiamo fatto fare. L'avevo nutrita prima di lasciare la fattoria, ma non ci aspettavamo che il carro si rompesse. Se riuscissi a portarle qualche manciata d'avena dai campi, te ne sarei grata.\n\nScommetto che ne trovi un po' intorno a tutte le fattorie di Westfall, se riesci a stare alla larga da quelle macchine orribili che hanno preso il sopravvento. Ci sono diverse fattorie a sud-ovest di qui.", enHash = "94b4a248", vanilla = true },
        objectives = { it = "Verna Furlbrow, in Westfall, vuole che tu le porti 8 Handful of Oats.", enHash = "36071af7", vanilla = true },
        progress = { it = "La vecchia Blanchy è allo stremo. Ti è capitato di trovarle un po' d'avena?", enHash = "92173ad6", vanilla = true },
        reward = { it = "Grazie mille, $N! La povera vecchia Blanchy sarà felicissima!", enHash = "ac3ff185", vanilla = true },
    },
    [152] = {
        title = { it = "La costa non è sicura", enHash = "9ddff9a5", vanilla = true },
        text = { it = "Avrai notato tutti i relitti lungo la costa. Il Great Sea è davvero infido. La costa di Westfall va tenuta sgombra, così che i marinai che approdano sulle nostre spiagge siano al sicuro. I murloc però sono un guaio.\n\nUccidi 7 Tidehunter, 7 Warrior, 7 Oracle e 7 Coastrunner e farò in modo che tu sia $Gricompensato:ricompensata;.", enHash = "cc77d355", vanilla = true },
        objectives = { it = "Uccidi 7 Tidehunter, 7 Warrior, 7 Oracle e 7 Coastrunner e torna da Captain Grayson, al Westfall Lighthouse.", enHash = "02766b46", vanilla = true },
        progress = { it = "Uccidi 7 Tidehunter, 7 Warrior, 7 Oracle e 7 Coastrunner e farò in modo che tu sia $Gricompensato:ricompensata;.", enHash = "58d7d90c", vanilla = true },
        reward = { it = "Ben fatto, $N. Hai un bel talento per il combattimento. Grazie a te la costa di Westfall è un posto più sicuro.", enHash = "b86694dd", vanilla = true },
    },
    [153] = {
        title = { it = "Red Leather Bandana", enHash = "2e80929a", vanilla = true },
        text = { it = "Il fronte dei Defias si sposta di continuo. Seguo i loro movimenti da parecchio tempo. Per inciso, ho appurato che molti membri della banda si possono riconoscere dalle Red Leather Bandana che portano.\n\nPortamene 15, di queste bandane, e farò in modo che tu sia $Gricompensato:ricompensata;.", enHash = "d9906ba9", vanilla = true },
        objectives = { it = "Porta 15 Red Leather Bandana a Scout Galiaan, a Sentinel Hill.", enHash = "ce242026", vanilla = true },
        progress = { it = "Portami 15 Red Leather Bandana e ti pagherò bene.", enHash = "6464fc52", vanilla = true },
        reward = { it = "Bel lavoro, $R. Ti prego, accetta uno di questi oggetti come pagamento per tutta la tua fatica.", enHash = "4978f7a9", vanilla = true },
    },
    [154] = {
        title = { it = "Restituisci il pettine", enHash = "c394f640", vanilla = true },
        text = { it = "NO!!!!!\n\nPrendilo, portami via questo pettine!\n\nSono un mostro, e nessuno mi troverà mai più bella!", enHash = "0152fc35", vanilla = true },
        objectives = { it = "Riporta il Ghost Hair Comb a Madame Eva, a Darkshire.", enHash = "3b2b60a5", vanilla = true },
        progress = { it = "Sento che hai visto Blind Mary. Hai il mio pettine...?", enHash = "268510f9", vanilla = true },
        reward = { it = "Con questo posso fare una matassa di Ghost Hair Thread, e mi avanzeranno anche alcuni capelli. Ecco qualche moneta per quelli che avanzano.", enHash = "88ae5691", vanilla = true },
    },
    [155] = {
        title = { it = "La Defias Brotherhood", enHash = "86683501", vanilla = true },
        text = { it = "Quindi Stoutmantle manda $Gun:una; $R $Gsmilzo:smilza; come te a proteggermi? Immagino che dovrai bastare. Meglio se ti porti anche qualche amico.\n\nSai come funziona, vero? Tu mi guardi le spalle e io ti porto al nascondiglio dei Defias. Ma stammi bene vicino. Ora la banda dei Defias vuole la mia testa. Se mi vedono con te, cercheranno di uccidermi.\n\nFammi sapere quando tu e gli amici che riesci a radunare siete pronti a partire.", enHash = "08e62e7f", vanilla = true },
        objectives = { it = "Scorta il Defias Traitor fino al nascondiglio segreto della Defias Brotherhood. Quando il Defias Traitor ti avrà mostrato dove si nascondono VanCleef e i suoi uomini, torna da Gryan Stoutmantle con l'informazione.", enHash = "bef09a06", vanilla = true },
        progress = { it = "Che affari hai con me? Sono un uomo molto occupato...", enHash = "50568420", vanilla = true },
        reward = { it = "Ottimo, $N! Ora che sappiamo dove si nasconde, VanCleef è praticamente nostro.", enHash = "a7dd782b", vanilla = true },
    },
    [156] = {
        title = { it = "Raccogli i Rot Blossom", enHash = "532727de", vanilla = true },
        text = { it = "Se mi porti dei Rot Blossom posso prepararti una dose di Zombie Juice.\n\nI Rot Blossom crescono in posti strani. In particolare, mi dicono che si trovano dentro i teschi degli Skeletal Horror e degli Skeletal Fiend... non che io abbia mai guardato da così vicino!\n\nIl Raven Hill Cemetery e i Tranquil Gardens pullulano di quegli scheletri. Tanto vale farli fuori mentre cerchi i Rot Blossom. La città di Darkshire te ne sarebbe grata.", enHash = "3573c5bb", vanilla = true },
        objectives = { it = "Raccogli 8 Rot Blossom e portali a Tavernkeep Smitts, a Darkshire.", enHash = "3fe66a6d", vanilla = true },
        progress = { it = "Ciao, $N. Hai già quei Rot Blossom per me?", enHash = "d87503e5", vanilla = true },
        reward = { it = "Bene, hai preso i Rot Blossom. E dirò ad Althea Ebonlocke della Guardia Notturna che stavi uccidendo scheletri.\n\nTenere al sicuro la gente di Darkshire è un compito gravoso per la Guardia Notturna, e sapere che anche altri aiutano ad arginare la marea di mostri a Duskwood è davvero una buona notizia.", enHash = "13b74a1c", vanilla = true },
    },
    [157] = {
        title = { it = "Consegna il filo", enHash = "31bb1a74", vanilla = true },
        text = { it = "Ecco il tuo filo, $N. Ha mille usi, dal legare gli spiriti maligni al cucire la vita dentro oggetti inanimati.", enHash = "46a22eb8", vanilla = true },
        objectives = { it = "Porta il Ghost Hair Thread ad Abercrombie, nella sua baracca a nord del Raven Hill Cemetery.", enHash = "0e72296d", vanilla = true },
        progress = { it = "Devo tendere il Ghost Hair Thread lungo la porta e le finestre per tenere fuori gli spiriti indesiderati. Me l'hai preso?", enHash = "e07602f1", vanilla = true },
        reward = { it = "Splendido! Andrà benissimo...\n\nTieni, $Gcaro:cara; $N, prendi questo come pagamento per la tua nobile azione.", enHash = "c41d56e8", vanilla = true },
    },
    [158] = {
        title = { it = "Zombie Juice", enHash = "b62256e6", vanilla = true },
        text = { it = "Mi serve una bottiglia di un certo liquore — Zombie Juice. Tavernkeep Smitts, alla Scarlet Raven Tavern di Darkshire, dovrebbe averne.\n\nE fa' in fretta, ti prego, $N. Queste notti si fanno fredde, e mi serve quella bevanda per rimettermi il fuoco nelle vene!", enHash = "2bed17aa", vanilla = true },
        objectives = { it = "Parla con Tavernkeep Smitts.", enHash = "fd9a2133", vanilla = true },
        reward = { it = "Ti serve dello Zombie Juice, eh? Hmm... è roba forte — non me lo chiede quasi nessuno.", enHash = "42b3d27d", vanilla = true },
    },
    [159] = {
        title = { it = "Consegna dello Zombie Juice", enHash = "5ea206b4", vanilla = true },
        text = { it = "Ecco il tuo Zombie Juice...\n\n...e sta' $Gattento:attenta; con questa roba. È abbastanza forte da resuscitare i morti!", enHash = "7136db0a", vanilla = true },
        objectives = { it = "Porta lo Zombie Juice ad Abercrombie, alla sua baracca.", enHash = "4dc17b30", vanilla = true },
        progress = { it = "Mi serve quello Zombie Juice per scaldarmi in queste notti fredde e buie. Me l'hai preso?", enHash = "31227789", vanilla = true },
        reward = { it = "Mille grazie, $N. Scaldi il cuore di un vecchio con la tua stupid-... voglio dire... con la tua gentilezza!\n\nEccoti qua, $Gamico:amica;. Prendi questo come segno della mia gratitudine.", enHash = "e0e7940b", vanilla = true },
    },
    [160] = {
        title = { it = "Un biglietto per il sindaco", enHash = "2e7b97a2", vanilla = true },
        text = { it = "Porta questo biglietto a Ello Ebonlocke, il sindaco di Darkshire.\n\nLui e io siamo vecchi amici... e quando lo leggerà e scoprirà quel che hai fatto per me... sono sicuro che sarà felice quanto me! Ahahaha!", enHash = "c5c962b8", vanilla = true },
        objectives = { it = "Porta la Letter to Ello di Abercrombie a Ello Ebonlocke, sindaco di Darkshire.", enHash = "fb8915e8", vanilla = true },
        progress = { it = "Abercrombie...? Non conosco nessuno con questo nome. Dici di avere una lettera per me da parte di questo tale Abercrombie?\n\nBe', allora diamole un'occhiata...", enHash = "ccfbaae2", vanilla = true },
        reward = { it = "<Ello guarda la lettera...>\n\nChe lingua è questa? Sembra antica... non riesco a leggerla.", enHash = "16e1b607", vanilla = true },
    },
    [161] = {
        title = { it = "Un'ombra minacciosa", enHash = "88b632d7", vanilla = true },
        text = { it = "Se i miei sospetti sono giusti, questa è una specie di polvere esplosiva. Deve essere analizzata da un esperto di esplosivi, così sapremo con cosa abbiamo a che fare. Ashlan Stonesmirk è stato assegnato al reggimento che sorveglia Dun Modr e il Thandol Span. Ho bisogno che tu faccia un viaggio impegnativo e pericoloso, $N.\n\nAttraversa l'Algaz Gate, segui la strada attraverso le Wetlands e cerca Stonesmirk a Dun Modr. Ascolta il mio consiglio: resta sulle strade e non fermarti per nessun motivo!", enHash = "6e3a8e6b", vanilla = true },
        objectives = { it = "Chief Engineer Hinderweir vuole che tu porti la polvere dall'odore strano ad Ashlan Stonesmirk, l'esperto di esplosivi a Dun Modr.", enHash = "618636b4", vanilla = true },
        progress = { it = "Hai detto qualcosa, $Gragazzo mio:ragazza mia;? Non sento un accidente, con questo ronzio nelle orecchie. Di': cos'hai lì?", enHash = { "7a22b737", "dca3df17" }, vanilla = true },
        reward = { it = "Ah, be', il vecchio Hinderweir fa bene a preoccuparsi.", enHash = "bc4aef14", vanilla = true },
    },
    [163] = {
        title = { it = "Raven Hill", enHash = "74eb6151", vanilla = true },
        text = { it = "Qualcosa non va a Raven Hill, $N. Calor giura che qualcuno — o qualcosa — infesta gli edifici laggiù. Per due notti di fila ha notato le ombre muoversi, e la terza notte prima ancora dice di aver visto una luce a una delle finestre.\n\nSe, come dici, ti sta a cuore la sicurezza di Duskwood, scopri che mostro infesta Raven Hill.", enHash = "9a23fa0a", vanilla = true },
        objectives = { it = "Scopri cosa infesta Raven Hill.", enHash = "e0b0fd10", vanilla = true },
        reward = { it = "No! Ti prego, non uccidermi! Sono solo io... Jitters!! Sono dappertutto... non riesco a sfuggirgli! Mostri a Raven Hill? N-n-no... impossibile. Solo l'innocuo Jitters.", enHash = "a345d5f6", vanilla = true },
    },
    [164] = {
        title = { it = "Consegne per Sven", enHash = "04f16e43", vanilla = true },
        text = { it = "Conosci Sven? Ecco un uomo che fa l'opera della Luce! Lui e i suoi seguaci hanno un accampamento all'estremità nord-occidentale di Duskwood.\n\nPurtroppo sono così pochi che non possono permettersi di staccare un uomo per andare a prendere i rifornimenti in città. Glieli porteresti tu, questi rifornimenti?", enHash = "f11ed8e3", vanilla = true },
        objectives = { it = "Consegna i rifornimenti a Sven.", enHash = "50215fc6", vanilla = true },
        progress = { it = "Hai l'aria robusta, $C. Sei $Gvenuto:venuta; a unirti alla nostra battaglia?", enHash = "d79927a4", vanilla = true },
        reward = { it = "Questi rifornimenti saranno utilissimi. L'aiuto della famiglia Carevin è sempre gradito. Ecco qualcosina per il disturbo.", enHash = "a89f2d44", vanilla = true },
    },
    [165] = {
        title = { it = "L'eremita", enHash = "3cef35b2", vanilla = true },
        text = { it = "C'era un vecchio che veniva in paese piuttosto spesso a comprare rifornimenti, ma è da parecchio che non lo vedo. Se ricordo bene, vive in una baracca che domina il cimitero di Raven Hill. Forse dovresti andare a vedere se è successo qualcosa.", enHash = "7722aed0", vanilla = true },
        objectives = { it = "Va' a vedere come sta il vecchio nella baracca vicino al cimitero di Raven Hill.", enHash = "022211a6", vanilla = true },
        reward = { it = "Elaine Carevin? Eheh, oh sì... i Carevin, certo.\n\nNo, non c'è niente che non va, ma adesso per me è dura andare in paese. Le strade sono pericolose e non ringiovanisco di certo. Magari puoi fare qualche favore a un vecchio?", enHash = "495f39f9", vanilla = true },
    },
    [166] = {
        title = { it = "La Defias Brotherhood", enHash = "86683501", vanilla = true },
        text = { it = "Ti resta un solo compito da portare a termine. Edwin VanCleef deve essere assassinato. Per quanto mi rattristi condannare a morte un uomo, è per il bene supremo della gente di Westfall che VanCleef sia sepolto una volta per tutte. Portami la testa del criminale, una volta compiuta l'impresa.", enHash = "6199d7d1", vanilla = true },
        objectives = { it = "Uccidi Edwin VanCleef e porta la sua testa a Gryan Stoutmantle.", enHash = "b9f0221e", vanilla = true },
        progress = { it = "Come va la caccia a Edwin VanCleef?", enHash = "4674b867", vanilla = true },
        reward = { it = "$N, il tuo coraggio è notevole. La People's Militia ti ringrazia per il servizio reso alla gente di Westfall. Con VanCleef morto, questo segna l'inizio della fine per la Defias Brotherhood. Speriamo che presto la pace torni a benedire le pianure di questa bella terra.\n\nTi saluto, $Gsignore:signora;!", enHash = { "a06bc848", "6ca6cf74" }, vanilla = true },
    },
    [167] = {
        title = { it = "Oh, fratello...", enHash = "bac093f1", vanilla = true },
        text = { it = "Eravamo in fondo a una miniera enorme a Westfall, nascosta sotto un fienile a Moonbrook. Non ho idea di dove siano sbucati quei ladri puzzolenti. Comunque, la galleria ci è crollata addosso. Io ne sono uscito, ma gli altri... be'... degli altri non si è più saputo nulla.\n\nSembra che tu là dentro possa avere più fortuna. Se potessi cercare mio fratello, te ne sarei grato. Portava sempre con sé il suo Explorers' League Badge. Se non riesci a trovarlo, quel distintivo mi darebbe almeno un po' di pace.", enHash = "66d73a49", vanilla = true },
        objectives = { it = "Porta Foreman Thistlenettle's Explorers' League Badge a Wilder Thistlenettle, a Stormwind.", enHash = "1b8dad6d", vanilla = true },
        progress = { it = "Hai trovato qualche traccia di mio fratello? C'è ancora speranza dopo tutto questo tempo?", enHash = "2d7de9e5", vanilla = true },
        reward = { it = "I miei sospetti erano fondati. Povero fratello mio... Be', grazie per aver dato una conclusione a questo mistero, anche se la conclusione era cupa.", enHash = "24134359", vanilla = true },
    },
    [168] = {
        title = { it = "Raccogliere ricordi", enHash = "a3504a07", vanilla = true },
        text = { it = "Molti dei miei amici sono morti in quel giorno orribile in cui la galleria della miniera è crollata. Se le tue avventure dovessero portarti in quell'ala della miniera a Moonbrook, ti prego, tieni gli occhi aperti per qualsiasi segno che possa identificarli. Se ti capita di trovare qualcuna delle loro Miners' Union Card, riportamele e farò in modo che le loro famiglie trovino una risposta a questo terribile incidente.", enHash = "9f5b5640", vanilla = true },
        objectives = { it = "Recupera 4 Miners' Union Card e riportale a Wilder Thistlenettle, a Stormwind.", enHash = "0628212b", vanilla = true },
        progress = { it = "Sei $Griuscito:riuscita; a recuperare qualche Miners' Union Card dei miei vecchi compagni di lavoro?", enHash = "2721c4cc", vanilla = true },
        reward = { it = "Grazie di averle raccolte, $N. Il tuo impegno aiuterà a dare pace ai morti dopo questa tragedia. Mi occuperò io di avvisare le famiglie.", enHash = "cfd91b5b", vanilla = true },
    },
    [169] = {
        title = { it = "Wanted: Gath'Ilzogg", enHash = "45671b9c", vanilla = true },
        text = { it = "Wanted! Gath'Ilzogg, capo degli attacchi Blackrock allo Stonewatch Keep e delle incursioni contro la cittadina di Lakeshire.\n\nGath'Ilzogg è estremamente pericoloso. Si dice sia rintanato nel forte appena conquistato, a tramare altri crimini del Blackrock Clan contro l'umanità. L'infestazione degli orchi va soffocata a ogni costo. Sarà data una generosa ricompensa a qualunque anima coraggiosa consegni la testa di Gath'Ilzogg a Magistrate Solomon.", enHash = "d9a7ea77", vanilla = true },
        objectives = { it = "Uccidi Gath'Ilzogg e porta la sua testa a Magistrate Solomon, a Lakeshire, per la ricompensa.", enHash = "68044617", vanilla = true },
        progress = { it = "Che cos'hai lì, $R?", enHash = "3c2370d7", vanilla = true },
        reward = { it = "Lavoro fantastico, $N! Gath'Ilzogg ha guidato quei bruti in battaglia, uccidendo molti umani innocenti. La rivincita è nostra. È il primo passo per riconquistare il forte per il regno di Stormwind!", enHash = "d7fa4692", vanilla = true },
    },
    [170] = {
        title = { it = "Una nuova minaccia", enHash = "afc8b9b9" },
        text = { it = "Spero che tu sia qui per darci una mano, $C. Dopo l'ultimo attacco dei trogg, ci serve tutto l'aiuto possibile.\n\nHo sentito che quei maledetti spuntano un po' ovunque, e a quanto pare la Coldridge Valley non fa eccezione. Sono stati avvistati su tutte le colline a sud-est e vicino al lago ghiacciato.\n\nE non è tutto: solo poche notti fa hanno attaccato e travolto il nostro accampamento a ovest!\n\nQui siamo un po' a corto di uomini, $Gragazzo:ragazza;, e ci servono braccia forti per ricacciare indietro i trogg.", enHash = { "21ff7c74", "0bf890aa" } },
        objectives = { it = "Balir Frosthammer vuole che tu uccida 6 Rockjaw Trogg e 6 Burly Rockjaw Trogg.", enHash = "8ed4d56c" },
        progress = { it = "Tenaci, quei maledetti, eh?", enHash = "7a7464d8", vanilla = true },
        reward = { it = "Se i problemi che abbiamo avuto qui sono un segnale di ciò che succede nel resto delle nostre terre, per la barba di Magni, ci aspettano dei guai! Posso solo sperare che il re e il Senato stiano prendendo provvedimenti contro la minaccia dei trogg.", enHash = "6d741b6b", vanilla = true },
    },
    [171] = {
        title = { it = "$GUn tutore:Una tutrice; dell'Alleanza", enHash = "09d51b53", vanilla = true },
        text = { it = "Sei $Gstato:stata; così gentile con me, $N. Non avrei mai sognato di divertirmi così tanto durante la Settimana dei Bambini. Grazie. Non voglio essere triste per quello che mi è successo e tutto il resto: i miei mi hanno sempre detto di superare qualunque cosa brutta succeda. Sai, da grande voglio essere un eroe... proprio come te.\n\nMi dispiace dirlo, ma è ora che torni a casa. Torniamo indietro, e dirò alla matrona che persona fantastica sei!", enHash = "8cc6d826", vanilla = true },
        objectives = { it = "Riporta il tuo protetto all'orfanotrofio di Stormwind consegnando lo Human Orphan Whistle a Orphan Matron Nightingale, nel Cathedral District.", enHash = "97ff0501", vanilla = true },
        progress = { it = "È un piacere rivederti, $N. Hai portato a termine i compiti di cui ti sei $Gfatto:fatta; carico durante la Settimana dei Bambini?", enHash = "3e18d334", vanilla = true },
        reward = { it = "Che il cielo ti benedica, $N. Hai fatto per Randis più di quanto la maggior parte della gente penserebbe mai di fare per lui. Grazie: sei una stella splendente nei cieli dell'Alleanza.\n\nTi prego, se riesci a trovare un po' di tempo, torna a trovarci. So che a Randis farebbe piacere, e anche a me.\n\nRandis si è divertito tantissimo con te, $N. Voleva darti uno dei suoi animaletti preferiti, perché ti ricordi di lui.", enHash = "a3e89ac6", vanilla = true },
    },
    [172] = {
        title = { it = "Settimana dei Bambini", enHash = "7db99b89", vanilla = true },
        text = { it = "Vuoi aiutarci qui all'orfanotrofio? Che il cielo ti benedica, $Gamico:amica;: il tuo aiuto durante la Settimana dei Bambini sarà prezioso.\n\nPrendi questo fischietto. Potrai usarlo solo per poco tempo, di solito non più a lungo della Settimana dei Bambini stessa. Quando lo usi, potrai parlare con il bambino di cui hai accettato di occuparti. Se lo usi di nuovo, il bambino se ne andrà.\n\nForza, $N, usa il fischietto e conosci il tuo protetto! Sono $Psicuro:sicura; che il bambino non vedrà l'ora di conoscerti.", enHash = "0af62f95", vanilla = true },
        objectives = { it = "Usa l'Orcish Orphan Whistle per parlare con il bambino di cui ti occuperai durante la Settimana dei Bambini.", enHash = "44aea721", vanilla = true },
        reward = { it = "Zug zug! Mi chiamo Grunth, e immagino che sarai tu a occuparti di me? Sei $Gun avventuriero:un'avventuriera;, come lo erano la mia mamma e il mio papà. La mia matrona dice che sono morti con onore in battaglia. Sono contento di conoscerti.\n\nSpero che faremo un sacco di cose insieme. Ho alcune cose che vorrei fare, e la matrona dice che durante questa settimana sarai come $Gun fratello maggiore:una sorella maggiore; per me. Mi piacerebbe un sacco.", enHash = { "2ef8c4f0", "2e5b9f5c" }, vanilla = true },
    },
    [173] = {
        title = { it = "Worgen nei boschi", enHash = "fe05cd26", vanilla = true },
        text = { it = "L'oscurità sembra attirata inesorabilmente da Duskwood. La missione di Master Carevin è scacciare il male e l'eresia. È grazie ai nostri sforzi che la gente di Darkshire resta al sicuro.\n\nTi credi $Gdegno:degna; di unirti a noi?\n\nUna volta la pensavo come te. Deluso dall'inerzia della Guardia, mi sono unito a Master Carevin. Se vuoi dimostrare il tuo valore, non sarà con le parole.\n\nMetti alla prova le tue capacità contro i worgen Nightbane Shadow Weaver a Brightwood Grove — luminoso, ah! — e al Rotting Orchard.", enHash = "e781c519", vanilla = true },
        objectives = { it = "Uccidi 6 worgen Nightbane Shadow Weaver per Calor, a Darkshire.", enHash = "bb47eab6", vanilla = true },
        progress = { it = "$N, come va la caccia?", enHash = "604c1df4", vanilla = true },
        reward = { it = "Notevole, $N. Sembra che tu sia capace di cavartela da $Gsolo:sola;. Forse per $Guno:una; con le tue capacità si può trovare una sfida più adatta.\n\nÈ curioso, però... I worgen sembravano comparire dal nulla. Ma poi, con tutte le altre creature strane che hanno passato i nostri confini, immagino sia solo una preoccupazione fra tante.", enHash = "b24e823f", vanilla = true },
    },
    [174] = {
        title = { it = "Guarda le stelle", enHash = "176e586e", vanilla = true },
        text = { it = "Il mio amico gnomo, Cog, ha promesso di aiutarmi a costruire un congegno che mi permetta di scrutare verso le stelle. Esiste una verità, oltre la magia, che può spiegare la strana trasformazione della foresta.\n\nPortami un tubo di bronzo fatto da un ingegnere esperto. È il primo passo, secondo il progetto di Cog.", enHash = "9f127e0c", vanilla = true },
        objectives = { it = "Viktori Prism'Antras di Darkshire vuole che tu gli porti un tubo di bronzo.", enHash = "7b0ed27b", vanilla = true },
        progress = { it = "Hai già trovato un ingegnere esperto che faccia un tubo di bronzo?", enHash = "816f0416", vanilla = true },
        reward = { it = "È perfetto, $N. Il primo passo è compiuto!", enHash = "86bda630", vanilla = true },
    },
    [175] = {
        title = { it = "Guarda le stelle", enHash = "176e586e", vanilla = true },
        text = { it = "Secondo il progetto di Cog, ora mi serve un modo per riflettere la luce. Ricordo una donna di nome Mary che da queste parti era conosciuta perché portava sempre con sé uno specchio. Magari puoi rintracciare Mary e vedere se può prestarci una superficie riflettente per questo progetto. Credo che un tempo vivesse nella parte meridionale di Duskwood. . .", enHash = "234a0977", vanilla = true },
        objectives = { it = "Trova Mary e convincila a cedere una superficie riflettente per il progetto di Viktori.", enHash = "6dd2aa1c", vanilla = true },
        reward = { it = "Ma sì, un tempo avevo uno specchio.", enHash = "4a6e1784", vanilla = true },
    },
    [176] = {
        title = { it = "WANTED: \"Hogger\"", enHash = "27f05241" },
        text = { it = "Wanted: Hogger\n\nUn enorme gnoll, Hogger, si aggira per i boschi di Elwynn sud-ovest. Ha respinto ogni tentativo di catturarlo.\n\nL'esercito di Stormwind ha messo una taglia generosa sullo gnoll. Per ottenere la ricompensa, i cacciatori di taglie devono portare la prova della morte di Hogger a Marshal Dughan, a Goldshire.", enHash = "48e4c9ec" },
        objectives = { it = "Uccidi lo gnoll Hogger e porta la sua Huge Gnoll Claw a Marshal Dughan.", enHash = "e72ba297" },
        progress = { it = "Sì, Hogger è stato una vera spina nel fianco per me e i miei uomini. Hai qualcosa da riferire sulla bestia?", enHash = "b7e98c10", vanilla = true },
        reward = { it = "Ah! Ben fatto! Cominciavo a pensare che nessuno sarebbe riuscito ad abbattere quel mostro!\n\nEcco qua, $N. E grazie — quello gnoll mi stava dando un mal di testa grande come il Blackrock Spire!", enHash = "deb9df46", vanilla = true },
    },
    [177] = {
        title = { it = "Guarda le stelle", enHash = "176e586e", vanilla = true },
        text = { it = "Lo specchio era uno dei miei tesori più belli, fino a. . .l'incidente. Dopo quel che è successo l'ho buttato dietro il fienile. Là dietro si aggirava un Insane Ghoul. Forse l'ha raccolto lui. Si dice che quella bestia diabolica stia nel Tranquil Gardens Cemetery.", enHash = "d55c1db1", vanilla = true },
        objectives = { it = "Recupera Blind Mary's Looking Glass dall'Insane Ghoul e portalo a Viktori, a Darkshire.", enHash = "1d337583", vanilla = true },
        progress = { it = "Ho mostrato a Cog l'inizio della nostra macchina per guardare le stelle. È rimasto colpito. Ti è capitato di trovare un congegno riflettente?", enHash = "c346ad68", vanilla = true },
        reward = { it = "Magnifico! Andrà a meraviglia. Mille grazie!", enHash = "db0ea271", vanilla = true },
    },
    [178] = {
        title = { it = "Il recupero di Theocritus", enHash = "7882f325", vanilla = true },
        text = { it = "<Senti una voce incorporea...>\n\nNon ti allarmare. Sono Theocritus, High Mage della Tower of Azora, nell'Elwynn Forest. Il pendaglio che hai in mano è un mezzo di comunicazione tra gli Shadowhide Gnoll e il loro padrone, Morganth.\n\nDopo mesi di ricerche, credo di poter comunicare anch'io attraverso questi pendagli. Se senti questo messaggio, allora il mio incantesimo ha funzionato.\n\nPortami questo pendaglio e ti ricompenserò per il servizio.", enHash = "bf29ece9", vanilla = true },
        objectives = { it = "Porta il Faded Shadowhide Pendant a Theocritus the Mage.", enHash = "05865e2e", vanilla = true },
        progress = { it = "Ti ho parlato attraverso un pendaglio, dici? Hmm... dallo a me, così posso studiarlo.", enHash = "caa74462", vanilla = true },
        reward = { it = "Ti sono grato, $N. Quel messaggio l'ho mandato agli Shadowhide Pendant settimane fa e lo credevo un fallimento. Ma pare che l'incantesimo abbia raggiunto almeno qualche pendaglio, dopo un notevole ritardo.\n\nCol tempo spero di imparare a mandare un attacco attraverso i pendagli, per immobilizzare gli Shadowhide Gnoll che li portano.\n\nMa prima che sia possibile, temo che serva ancora molta ricerca.", enHash = "84e44c1a", vanilla = true },
    },
    [179] = {
        title = { it = "Equipaggiamento nanico", enHash = "736d4d1a" },
        text = { it = "Chi abbiamo qui? Hai l'aria di chi ha bisogno di qualcosa per tenere le mani al caldo, eh?\n\nTi dico io cosa ti servirebbe: un bel paio di guanti caldi. E, anima gentile come sono, te ne procurerei volentieri un paio della tua misura. Ho solo una condizione.\n\nDevi andare a prendermi un po' di carne di lupo. Bell'accordo, eh? Tu mi porti la carne di lupo, e io farò in modo che il gelo non ti porti via nessun dito. Allora, che ne dici?", enHash = "cecb4625" },
        objectives = { it = "Sten Stoutarm vuole 8 pezzi di Tough Wolf Meat.", enHash = "1a7a3d73" },
        progress = { it = "I lupi ti danno un po' di filo da torcere? Faresti bene a stare alla larga da zanne, artigli e altre parti appuntite, eh?", enHash = "64970671" },
        reward = { it = "Ah! Magnifico. La carne di lupo andrà benissimo. Oh, non preoccuparti, $N, non mi dimentico la mia parte dell'accordo. Ecco, uno di questi dovrebbe andarti bene.", enHash = "6aa962c6" },
    },
    [180] = {
        title = { it = "Wanted: Lieutenant Fangore", enHash = "2861083a", vanilla = true },
        text = { it = "Wanted: Lieutenant Fangore\n\nCapo riconosciuto dello Shadowhide Gnoll Clan, al servizio del nemico della cittadina e del Regno, Morganth. Per mandato di Magistrate Solomon, questo ignobile traditore di Stormwind è ricercato morto. Mostra la sua zampa al magistrato come prova della sua morte.", enHash = "c92efcc8", vanilla = true },
        objectives = { it = "Uccidi Lieutenant Fangore e torna da Magistrate Solomon, a Lakeshire, con la sua zampa.", enHash = "ca204492", vanilla = true },
        progress = { it = "Che notizie porti davanti alla Corte?", enHash = "2610db51", vanilla = true },
        reward = { it = "Dunque il malvagio Lieutenant Fangore è morto? Finalmente ci siamo liberati di quella creatura immonda. Sei molto $Gcoraggioso:coraggiosa;, $C. La cittadina di Lakeshire ti ringrazia per il tuo aiuto.", enHash = "a5bda135", vanilla = true },
    },
    [181] = {
        title = { it = "Guarda le stelle", enHash = "176e586e", vanilla = true },
        text = { it = "Ora manca solo un pezzo per completare questo congegno. Il progetto di Cog richiede una lente di qualche tipo. L'unica lente che conosco abbastanza grande sarà molto difficile da procurarsi.\n\nC'è un ogre di nome Zzarc'Vul che sta nel tumulo nel sud di Duskwood. Se ci riesci, portami il suo monocolo e lo userò come lente!", enHash = "a9fa7d65", vanilla = true },
        objectives = { it = "Trova Zzarc'Vul nel tumulo degli ogre a sud, a Duskwood, e porta il suo monocolo a Viktori, a Darkshire.", enHash = "a7297756", vanilla = true },
        progress = { it = "Sei $Griuscito:riuscita; a convincere Zzarc'Vul a prestarci il suo monocolo per il nostro esperimento?", enHash = "c316281a", vanilla = true },
        reward = { it = "Finalmente! Il congegno per osservare le stelle è completo! Grazie, $N. Ora posso continuare le mie ricerche. . .", enHash = "fd95667f", vanilla = true },
    },
    [182] = {
        title = { it = "La grotta dei troll", enHash = "657692f0" },
        text = { it = "Io e mio fratello Senir siamo stati mandati in diverse zone del Dun Morogh a indagare sulla minaccia dei troll. Il Senato ha già il suo daffare con i trogg, quindi non ha bisogno di altri fastidi.\n\nDa quello che ho visto, i troll qui nella Coldridge Valley non sono molto radicati: stanno soprattutto nella grotta a sud. Direi che l'esercito non servirà: qualche braccio forte dovrebbe bastare e avanzare.\n\nForse vorresti dare una mano in questa impresa? Ho l'autorità per offrirti un compenso per il tuo aiuto.", enHash = "ade946e1" },
        objectives = { it = "Grelin Whitebeard vuole che tu uccida 14 Frostmane Troll Whelp.", enHash = "c803a963" },
        progress = { it = "Da quello che ho scoperto, questi troll vengono dal clan Frostmane. Temo di non sapere molto altro su di loro che possa esserti utile, $N.", enHash = "6e55f877", vanilla = true },
        reward = { it = "Argh! Maledetti troll, che la Luce li fulmini!\n\n<Fa qualche respiro e sembra calmarsi... un po'.>\n\nUn gruppo di loro è venuto di notte e mi ha rubato il diario! Lo sapevo che non dovevo fidarmi di quel buono a nulla di un appr...", enHash = "0ab9aade" },
    },
    [183] = {
        title = { it = "Il cacciatore di cinghiali", enHash = "33b42e32", vanilla = true },
        text = { it = "Niente di meglio di una giornata a caccia di cinghiali, eh?\n\nAnche se qui nella Coldridge Valley ci sono così tanti cinghiali che quasi non c'è più gusto. Non serve nemmeno provocarli: sono già tutti infuriati e pronti a caricare da soli. Anzi, ultimamente ce ne sono così tanti in zona che è diventato pericoloso fare la mia caccia quotidiana.\n\nPer farla breve, se potessi aiutarmi a ucciderne un po', te ne sarei grato.", enHash = "faf22198", vanilla = true },
        objectives = { it = "Talin Keeneye vuole che tu uccida 12 Small Crag Boar.", enHash = "309ba61a", vanilla = true },
        progress = { it = "Come va la caccia?", enHash = "29108c63", vanilla = true },
        reward = { it = "Ottimo! Ora posso tornare alla mia... tranquilla... caccia. Grazie, $N.", enHash = "fb9f4740", vanilla = true },
    },
    [184] = {
        title = { it = "Furlbrow's Deed", enHash = "adef3333", vanilla = true },
        text = { it = "Questo è l'atto di proprietà di una distesa di terreni agricoli in Westfall. È firmato da un certo Theodore Furlbrow e controfirmato dalla moglie, Verna. E sul retro dell'atto ci sono parole scarabocchiate in fretta:\n\n\"Abbiamo messo sotto pressione Furlbrow e ci siamo presi il suo atto. Abbiamo pensato che potesse tornare utile, se volevi falsificarne uno per il tuo posto.\n\nI Furlbrow non ci daranno guai. L'ultima volta che li ho visti stavano lasciando Westfall, bloccati con il carro rotto.\"\n\nPensi che i Furlbrow rivorrebbero il loro atto...", enHash = "af3eedb0", vanilla = true },
        objectives = { it = "Porta Furlbrow's Deed a Farmer Furlbrow.", enHash = "ee3949da", vanilla = true },
        progress = { it = "Hai l'atto della mia fattoria?? Questa sì che è una bella notizia! Dei farabutti me l'hanno rubato giorni fa... Credevo fosse perso per sempre!\n\nTi prego, dammelo. Stiamo lasciando Westfall e non torneremo tanto presto, ma se lo facessimo ci servirebbero quelle carte...", enHash = "f70e81d1", vanilla = true },
        reward = { it = "Grazie mille, $N! Come dicevo, queste terre non sono più adatte alla gente onesta, ma se le cose migliorano, questo atto ci permetterà di riprenderci la nostra terra.\n\nNon ho molto da offrirti, ma tieni — prendi questo.", enHash = "eb291d1e", vanilla = true },
    },
    [185] = {
        title = { it = "Maestria nella caccia alla tigre", enHash = "b8f07ff6", vanilla = true },
        text = { it = "Quando ero solo una ragazzina, mio padre mi insegnò l'arte della caccia alla tigre.\n\nI felini giovani sono molto più facili da seguire e da uccidere. Per questo cominceremo con qualcosa di semplice. Spesso si trovano giovani tigri vicino all'accampamento della spedizione.\n\nMetti alla prova la tua abilità nel seguire le tracce e vedi se riesci a cacciare qualcuna di queste bestie.", enHash = "8ff9ffad", vanilla = true },
        objectives = { it = "Ajeck Rouack, della Nesingwary's Expedition, vuole che tu uccida 10 Young Stranglethorn Tiger.", enHash = "d2da1bb9", vanilla = true },
        progress = { it = "Non me la sento di addestrarti oltre, $N, finché non avrai dimostrato di saper uccidere prima le tigri più giovani.", enHash = "df72b000", vanilla = true },
        reward = { it = "Ben fatto, $N. Sei $Gpronto:pronta; per il passo successivo.", enHash = "e44bd1e3", vanilla = true },
    },
    [186] = {
        title = { it = "Maestria nella caccia alla tigre", enHash = "b8f07ff6", vanilla = true },
        text = { it = "Stai imparando, $C. Ora mettiamo alla prova la tua abilità con i felini adulti. Stavolta uccidi 10 Stranglethorn Tiger.", enHash = "49009b4d", vanilla = true },
        objectives = { it = "Ajeck Rouack, della Nesingwary's Expedition, vuole che tu uccida 10 Stranglethorn Tiger.", enHash = "7f3ed941", vanilla = true },
        progress = { it = "Se aspiri a sfide più grandi, devi prima dimostrare quanto vali con il compito che hai davanti. Torna da me dopo aver ucciso 10 Stranglethorn Tiger.", enHash = "e4be0846", vanilla = true },
        reward = { it = "Sono colpita, $C. Stai facendo davvero buoni progressi.", enHash = "974b5c44", vanilla = true },
    },
    [187] = {
        title = { it = "Maestria nella caccia alla tigre", enHash = "b8f07ff6", vanilla = true },
        text = { it = "Ora alzerò la posta e metterò davvero alla prova la tua abilità. Dimostrami che sai uccidere 10 Elder Stranglethorn Tiger. Se ci riesci, sarai $Gpronto:pronta; per la tua sfida finale, prima che io ti proclami $Gmaestro cacciatore:maestra cacciatrice; di tigri alla presenza di Master Nesingwary.\n\nLe Elder Stranglethorn Tiger non solo sono le più difficili da trovare, ma sono anche le più feroci da sconfiggere.", enHash = "59b3b3c2", vanilla = true },
        objectives = { it = "Ajeck Rouack, della Nesingwary's Expedition, vuole che tu uccida 10 Elder Stranglethorn Tiger.", enHash = "dfd7462b", vanilla = true },
        progress = { it = "Devi uccidere 10 Elder Stranglethorn Tiger prima che io ti affidi la sfida finale, quella che stabilirà se sei $Gun vero maestro:una vera maestra; nella caccia alla tigre.", enHash = "be0a89f1", vanilla = true },
        reward = { it = "Davvero notevole. Credo che tu sia quasi $Gpronto:pronta;.", enHash = "3ee53e75", vanilla = true },
    },
    [188] = {
        title = { it = "Maestria nella caccia alla tigre", enHash = "b8f07ff6", vanilla = true },
        text = { it = "Ecco la sfida finale che ti propongo. Da settimane seguiamo le tracce di una tigre sfuggente. Chiamiamo la bestia Sin'Dall. Vediamo se riesci a fare ciò che $Gnessun altro:nessun'altra; $R ha mai fatto prima: stanare e uccidere Sin'Dall. Portami la sua zampa come prova della tua impresa.\n\nRintracciarla non sarà un compito facile.", enHash = "4223b04d", vanilla = true },
        objectives = { it = "Ajeck Rouack, della Nesingwary's Expedition, vuole che tu uccida Sin'Dall e torni con la sua zampa.", enHash = "d8727727", vanilla = true },
        progress = { it = "Come procede la caccia a Sin'Dall?", enHash = "c8a02fd8", vanilla = true },
        reward = { it = "Davvero notevole, non c'è che dire! Sei $Gun vero maestro:una vera maestra; della caccia alla tigre, $N!", enHash = "ef315d61", vanilla = true },
    },
    [189] = {
        title = { it = "Bloodscalp Ears", enHash = "1bb4ed42", vanilla = true },
        text = { it = "Maledetti troll! Stanno facendo fuori i nostri agenti nella giungla! Ho già perso un bel po' delle mie guardie migliori negli scontri con loro. I costi si accumulano! Come lo spiego a Baron Revilgaz?\n\nUn'azione decisa... Pensa, Kebok... non ti hanno messo al posto che occupi oggi per startene con le mani in mano... Ci sono! Tu... $N, giusto? Mi aiuterai, vero? C'è da guadagnarci!\n\nEcco l'accordo... tu mi porti le orecchie di quindici troll Bloodscalp, e io ti ricompenso bene.", enHash = "b1383b0b", vanilla = true },
        objectives = { it = "Procurati 15 Bloodscalp Ear e riportale a Kebok, a Booty Bay.", enHash = "d074b594", vanilla = true },
        progress = { it = "Hai avuto successo, spero? Sono dappertutto, quei troll. Sudici diavoli.\n\nOh sì, questo mi ricorda una cosa! Dillo anche ai tuoi amici, eh? Ci farebbe comodo parecchio aiuto!", enHash = "3c1d9476", vanilla = true },
        reward = { it = "Oh, eccellente, eccellente. Questo aiuterà un po', per il momento...\n\n<La sua voce si spegne mentre borbotta di margini di profitto e di costi...>\n\nCosa? Sei ancora qui? Una ricompensa? Ah, giusto... certo, ecco, prendi questo... dovrebbe bastare e avanzare.", enHash = "98126821", vanilla = true },
    },
    [190] = {
        title = { it = "Maestria nella caccia alla pantera", enHash = "f06d0875", vanilla = true },
        text = { it = "Se vuoi partecipare alla caccia con questo gruppo di assi che Hemet ha radunato, dovrai dimostrare di essere $Gun abile cacciatore:un'abile cacciatrice; di pantere. Cominceremo con qualcosa di semplice, non preoccuparti. Vediamo se riesci a uccidere 10 Young Panther, per cominciare.\n\nRintracciarle è solo metà della sfida...", enHash = "3bc5a995", vanilla = true },
        objectives = { it = "Sir S. J. Erlgadin, della Nesingwary's Expedition, vuole che tu uccida 10 Young Panther.", enHash = "1ccbd361", vanilla = true },
        progress = { it = "Un vero cacciatore di pantere sarebbe in giro per i campi, a braccare la sua preda. Mostra un po' di impegno per il tuo obiettivo, $C, e torna là fuori.", enHash = "fb0aee80", vanilla = true },
        reward = { it = "Un buon inizio, $N!", enHash = "366474b1", vanilla = true },
    },
    [191] = {
        title = { it = "Maestria nella caccia alla pantera", enHash = "f06d0875", vanilla = true },
        text = { it = "Ora sei $Gpronto:pronta; ad alzare il livello. Se vuoi dimostrarti $Gdegno:degna; di frequentare gente del calibro di questi esperti di caccia grossa, dovrai dimostrare di saper uccidere 10 Panther.\n\nQuei bestioni sono più resistenti. Non sono facili come quelle giovani che uccidevi prima.", enHash = "22680e9d", vanilla = true },
        objectives = { it = "Sir S. J. Erlgadin, della Nesingwary's Expedition, vuole che tu uccida 10 Panther.", enHash = "339cc369", vanilla = true },
        progress = { it = "Va' a uccidere 10 Panther! Facci vedere cosa sai fare!", enHash = "26451156", vanilla = true },
        reward = { it = "Esecuzione perfetta, $N!", enHash = "4f7ea12e", vanilla = true },
    },
    [192] = {
        title = { it = "Maestria nella caccia alla pantera", enHash = "f06d0875", vanilla = true },
        text = { it = "Ora viene la parte difficile. Un vero cacciatore di pantere può dimostrare la sua abilità abbattendo le Shadowmaw Panther, le più letali di Stranglethorn. Dimostraci che sai uccidere 10 di queste bestie.\n\nSe pensi che sia difficile seguirne le tracce, aspetta di provare a ucciderne una...", enHash = "1b682ea0", vanilla = true },
        objectives = { it = "Sir S. J. Erlgadin, della Nesingwary's Expedition, vuole che tu uccida 10 Shadowmaw Panther.", enHash = "20cc53cc", vanilla = true },
        progress = { it = "Che ci fai qui, $N! Dovresti strisciare nella boscaglia, cercando di uccidere 10 Shadowmaw Panther. Credevo che ti considerassi $Gun cacciatore:una cacciatrice; di grossa selvaggina?", enHash = "9254cd6b", vanilla = true },
        reward = { it = "Hai fatto un ottimo lavoro, $N!", enHash = "eb946a20", vanilla = true },
    },
    [193] = {
        title = { it = "Maestria nella caccia alla pantera", enHash = "f06d0875", vanilla = true },
        text = { it = "Hai quasi dimostrato di essere $Gun maestro:una maestra; nella caccia alla pantera. Una pantera di nome Bhag'thera si aggira per la giungla. Finora ha eluso il nostro gruppo. Vediamo se riesci a usare la tua abilità per uccidere il grande Bhag'thera.\n\nPortami la Fang of Bhag'thera e ti sarai $Gguadagnato:guadagnata; il mio rispetto!", enHash = "54912d40", vanilla = true },
        objectives = { it = "Sir S. J. Erlgadin, della Nesingwary's Expedition, vuole che tu gli porti la Fang of Bhag'thera.", enHash = "9f60d2ea", vanilla = true },
        progress = { it = "Bhag'thera può rivelarsi una bestia sfuggente. Come procede la caccia?", enHash = "6121dc2a", vanilla = true },
        reward = { it = "Dunque il grande Bhag'thera è morto! Alla tua salute, $N. Sei davvero $Gun:una; $C possente!", enHash = "147ed455", vanilla = true },
    },
    [194] = {
        title = { it = "Maestria nella caccia al raptor", enHash = "ea51d1cd", vanilla = true },
        text = { it = "Quindi credi che le tue abilità di caccia siano in forma smagliante? Posso metterle alla prova in un attimo. Addentrati in quella giungla e uccidi 10 Stranglethorn Raptor. Vedremo quanto sei $Gbravo:brava; nella caccia grossa.\n\nE no, non ti dirò dove trovarli! Scovare le bestie è metà della sfida.", enHash = "42fa320b", vanilla = true },
        objectives = { it = "Hemet Nesingwary vuole che tu uccida 10 Stranglethorn Raptor.", enHash = "e85dba9a", vanilla = true },
        progress = { it = "Non ho mai conosciuto un cacciatore che abbia abbattuto qualcosa standosene intorno al fuoco del campo. Avevi intenzione di uccidere quegli Stranglethorn Raptor o speravi che morissero di vecchiaia?", enHash = "df4d5a50", vanilla = true },
        reward = { it = "Ben fatto, $Gvecchio mio:mia signora;!", enHash = { "a1ab5de8", "bae36651" }, vanilla = true },
    },
    [195] = {
        title = { it = "Maestria nella caccia al raptor", enHash = "ea51d1cd", vanilla = true },
        text = { it = "Ora alziamo il livello della sfida e vediamo se sei all'altezza. Avventurati nella giungla e abbatti 10 di quei dannati Lashtail Raptor. Vediamo cosa sai fare!", enHash = "2c75656d", vanilla = true },
        objectives = { it = "Hemet Nesingwary vuole che tu uccida 10 Lashtail Raptor.", enHash = "54e63259", vanilla = true },
        progress = { it = "Un vero cacciatore si concentra sulla sua preda. Tu, $Gamico mio:amica mia;, sembri più $Ginteressato:interessata; a chiacchierare intorno al fuoco del campo. Ora vai là fuori e uccidi 10 Lashtail, prima che io ripulisca da loro l'intera dannata giungla in una sola battuta di caccia.", enHash = "0d08e063", vanilla = true },
        reward = { it = "Ecco come ci si guadagna un trofeo o due sopra il vecchio camino! Bella caccia, $N!", enHash = "b4fdb876", vanilla = true },
    },
    [196] = {
        title = { it = "Maestria nella caccia al raptor", enHash = "ea51d1cd", vanilla = true },
        text = { it = "Vediamo come te la cavi con la prossima sfida. Là fuori c'è una razza di raptor molto astuta. Li chiamiamo Jungle Stalker. Sono molto più difficili da scovare e da uccidere delle altre razze con cui hai tentato la fortuna finora. Uccidi 10 Jungle Stalker e ti darò una soffiata sulla caccia migliore di tutte.", enHash = "dc2897c1", vanilla = true },
        objectives = { it = "Hemet Nesingwary vuole che tu uccida 10 Jungle Stalker.", enHash = "2df23b22", vanilla = true },
        progress = { it = "Bah! Che ci fai lì senza far niente, $N! Un vero cacciatore di grossa selvaggina non si arrende mai quando ha la preda nel mirino. Quei Jungle Stalker non verranno di corsa a questo fuoco per buttarcisi dentro. $GChe ragazzo sciocco:Che ragazza sciocca;.", enHash = { "adb7f4d5", "693b5533" }, vanilla = true },
        reward = { it = "Oh oh! Abbiamo $Gun vero sterminatore:una vera sterminatrice; di raptor! Ben fatto, $Gvecchio mio:bella signora;!", enHash = { "67e54fe4", "264752cb" }, vanilla = true },
    },
    [197] = {
        title = { it = "Maestria nella caccia al raptor", enHash = "ea51d1cd", vanilla = true },
        text = { it = "Visto che nella giungla ti sei $Gdimostrato:dimostrata; così intraprendente, lascia che ti parli di un raptor feroce che nemmeno io sono riuscito a uccidere. Ajeck, qui, chiama questo astuto raptor Tethis.\n\nSe vuoi dimostrare di essere $Gun vero maestro:una vera maestra;, uccidi Tethis e portami il suo artiglio. Sarebbe un'impresa che nessun altro cacciatore di grossa selvaggina ha mai compiuto.", enHash = "da95f618", vanilla = true },
        objectives = { it = "Hemet Nesingwary vuole che tu uccida Tethis, un raptor sfuggente e pericoloso di Stranglethorn.", enHash = "7f14bd9a", vanilla = true },
        progress = { it = "Come procede la caccia a Tethis? Hai seguito le sue tracce fin qui all'accampamento, eh?", enHash = "7ea8fdd7", vanilla = true },
        reward = { it = "Master $N, $Glo sterminatore:la sterminatrice; di raptor!\n\nSuona bene, eh?", enHash = "25c4b40e", vanilla = true },
    },
    [198] = {
        title = { it = "Provviste per Private Thorsen", enHash = "ac3ce596", vanilla = true },
        text = { it = "Mmh. Sì, in effetti avrei qualcosa da farti fare. Lieutenant Doren e i suoi seguaci, su a nord, hanno bisogno delle solite provviste da parte nostra.\n\nNon sono state consegnate, e con i troll all'attacco mi serve qualcuno che se ne occupi. L'accampamento di Doren si trova a nord-ovest della strada, all'ingresso di Stranglethorn da Duskwood. Consegna le provviste a Private Thorsen; se non è nell'accampamento, starà pattugliando la zona a sud. Se ne occuperà lui.\n\nBada, se fallisci, dovrai risarcirmi.", enHash = "657fa6dd", vanilla = true },
        objectives = { it = "Consegna le Miscellaneous Goblin Supplies a Private Thorsen.", enHash = "f3b3bf25", vanilla = true },
        progress = { it = "Sì? Cosa vuoi? Oh, le provviste dei goblin. Strano vedere $Gun:una; $R che le consegna, di solito mandano uno dei loro. Non importa... non le hai toccate, vero? Bene, bene... non vorremmo che succedesse qualcosa alle nostre mine, oh no.", enHash = "652700c5", vanilla = true },
        reward = { it = "Queste mine ci aiuteranno a difenderci da quell'animale di Kurzen e dai suoi uomini. Grazie per averle portate. Se cerchi altro lavoro, probabilmente posso trovarti qualcosa da fare. E non dovrai avere a che fare con quei goblin, eh?", enHash = "d467f065", vanilla = true },
    },
    [199] = {
        title = { it = "Un'ombra minacciosa", enHash = "88b632d7", vanilla = true },
        text = { it = "Prendi un campione della polvere dall'odore strano.", enHash = "ef24bb69", vanilla = true },
        objectives = { it = "Torna da Chief Engineer Hinderweir e mostragli l'indizio che hai scoperto.", enHash = "ad753bba", vanilla = true },
        progress = { it = "Ti è capitato di scoprire qualche indizio, $N?", enHash = "96616e69", vanilla = true },
        reward = { it = "Questa è una scoperta allarmante, a dir poco!", enHash = "d7277a2d", vanilla = true },
    },
    [200] = {
        title = { it = "Bookie Herod", enHash = "1c524d8f", vanilla = true },
        text = { it = "Se Kurzen conosce il segreto di Thorsen, allora abbiamo una spia tra noi. Dobbiamo scoprire come è trapelato il segreto!\n\nIl contatto di Thorsen nell'accampamento di Kurzen era Bookie Herod. Herod è l'ufficiale della logistica di Kurzen e sa tutto su come funziona il Kurzen's Compound. Se riesci a prendere gli appunti o i registri di Herod, forse potremo scoprire come è stato smascherato Thorsen.\n\nQuando eravamo ancora con Kurzen, l'ufficio di Bookie era all'ultimo piano dell'unica casa a due piani dell'accampamento. I suoi registri sono probabilmente ancora lì.", enHash = "1df50fb6", vanilla = true },
        objectives = { it = "Trova i Bookie Herod's Records.", enHash = "4021004a", vanilla = true },
        reward = { it = "Questi sono gli appunti e i registri di Bookie Herod.\n\nTra questi ci sono: un elenco delle provviste dell'accampamento, richieste di materiali da parte di Colonel Kurzen e varie lettere e corrispondenze.", enHash = "5f13e395", vanilla = true },
    },
    [201] = {
        title = { it = "Indaga sull'accampamento", enHash = "fecf51f1", vanilla = true },
        text = { it = "Mi è giunta voce di un gruppo di cacciatori che si è accampato a monte del campo minerario della Venture Company sul Lake Nazferiti. Ora, di solito non me ne importerebbe, ma, per quanto sembri improbabile, ho sentito che tra quei cacciatori c'è Hemet Nesingwary. Ha di certo le conoscenze giuste, se capisci cosa intendo, e la prudenza non è mai troppa.\n\nPerché non vai a dare un'occhiata all'accampamento, $N, a vedere cosa stanno combinando?", enHash = "0367f14e", vanilla = true },
        objectives = { it = "Trova l'accampamento dei cacciatori e riferisci la sua posizione a Krazek, a Booty Bay.", enHash = "7c806f5a", vanilla = true },
        progress = { it = "Allora? Hai avuto fortuna nel trovare l'accampamento?", enHash = "b20c4fa5", vanilla = true },
        reward = { it = "Mmm, quindi le mie informazioni erano corrette, come al solito. Interessante. Be', non credo che rischino di interferire con i nostri affari, ma forse hanno bisogno di qualcuno dei nostri eccellenti prodotti. Mmm...", enHash = "3e55c35b", vanilla = true },
    },
    [202] = {
        title = { it = "Colonel Kurzen", enHash = "3541be75", vanilla = true },
        text = { it = "Hai dato prova di te più e più volte, e la tua intraprendenza sembra rivaleggiare perfino con quella di Kurzen in persona. Potresti essere la salvezza della nostra banda di ribelli... se riesci a misurarti con Kurzen e a prevalere!\n\nComanda i suoi uomini dal fondo dello Stockpile. Devi entrare in quella caverna, farti strada tra i suoi difensori e affrontare Kurzen e i suoi capi.\n\nAddio, $N. La mia speranza, e il destino dei miei uomini, vengono con te.", enHash = "4b4344f5", vanilla = true },
        objectives = { it = "Uccidi 6 Kurzen Elite e 4 Kurzen Subchief, e porta Kurzen's Head a Lieutenant Doren, al Rebel Camp.", enHash = "83425cb0", vanilla = true },
        progress = { it = "Oso sperare che Kurzen e i suoi difensori siano morti, $N?", enHash = "6ff32e01", vanilla = true },
        reward = { it = "Non osavo credere ai rapporti, ma ci porti la prova che... Kurzen e i suoi capi sono stati sconfitti. Ci hai salvato!\n\nQueste giungle sono piene di minacce di ogni tipo, ma nessuna aveva l'intelletto crudele di Kurzen. Ora che non c'è più, possiamo tutti respirare più tranquilli.", enHash = "5e471093", vanilla = true },
    },
    [203] = {
        title = { it = "La seconda ribellione", enHash = "a6cd19b5", vanilla = true },
        text = { it = "Contro Colonel Kurzen stiamo combattendo una battaglia persa. Non solo è un tattico brillante, ma ci supera di numero almeno 10 a 1! Per sopravvivere dobbiamo usare contro di lui le sue stesse tattiche clandestine.\n\nEntra nel suo accampamento a est e uccidi i suoi uomini. Tanti. E vattene prima che i rinforzi riescano a chiuderti in trappola.", enHash = "d0a641b9", vanilla = true },
        objectives = { it = "Uccidi 15 Kurzen Jungle Fighter.\n\nTorna da Sergeant Yohwa, al Rebel Camp.", enHash = "d670074d", vanilla = true },
        progress = { it = "Spero che la tua caccia sia andata a buon fine, $N. Senza il tuo aiuto non resisteremo a lungo contro di lui.", enHash = "a42a8b73", vanilla = true },
        reward = { it = "Ben fatto. La perdita di quei Jungle Fighter allenterà un po' la pressione sul nostro accampamento.\n\nMa ora che hai avuto un assaggio delle forze che affrontiamo, vuoi ancora schierarti dalla nostra parte?", enHash = "29080502", vanilla = true },
    },
    [204] = {
        title = { it = "Cattiva medicina", enHash = "1c376ff5", vanilla = true },
        text = { it = "Per avere una possibilità contro Kurzen, dobbiamo privarlo dei suoi guaritori. Si è circondato di un gran numero di Medicine Man che curano le sue truppe con i Jungle Remedy e avvelenano i nostri combattenti con i Venom Fern Extract.\n\nCi servono quei rimedi per curare la nostra gente, e ci serve un campione di quegli estratti da studiare, per poter preparare rimedi nostri. Cerca entrambi nel Kurzen's Compound — i suoi Medicine Man avranno i rimedi, e gli estratti sono probabilmente riposti in qualche cassa di provviste dell'accampamento.", enHash = "a072b01a", vanilla = true },
        objectives = { it = "Porta 7 Jungle Remedy e 1 Venom Fern Extract a Sergeant Yohwa, al Rebel Camp.", enHash = "9b062410", vanilla = true },
        progress = { it = "Aspetto quei rimedi e quell'estratto, $N.", enHash = "20f3afed", vanilla = true },
        reward = { it = "Ben fatto, $N. Grazie a questi rimedi più di noi resteranno in vita e in grado di combattere. E gli estratti ci aiuteranno a creare rimedi nostri.", enHash = "b622cae3", vanilla = true },
    },
    [205] = {
        title = { it = "Stregoneria troll", enHash = "091b9b57", vanilla = true },
        text = { it = "Mentre studio le leggende che hai recuperato, raccogli per me gli strumenti della malvagia magia troll. Entra nel territorio dei troll Skullsplitter, un'altra tribù, lontano a sud, e procurati degli Skullsplitter Fetish dai loro Witch Doctor e Mystic.", enHash = "f7f53203", vanilla = true },
        objectives = { it = "Porta 4 Skullsplitter Fetish a Brother Nimetz, al Rebel Camp.", enHash = "ed7c763c", vanilla = true },
        progress = { it = "Hai quei feticci, $N? Potrebbero custodire il segreto della degradazione di Kurzen... devo saperlo!", enHash = "a23cea5e", vanilla = true },
        reward = { it = "Grazie. Studierò questi feticci e vedrò se custodiscono il segreto della caduta di Kurzen nel male.", enHash = "a6953741", vanilla = true },
    },
    [206] = {
        title = { it = "Mai'Zoth", enHash = "fba820db", vanilla = true },
        text = { it = "Kurzen sarà anche morto, ma... ciò che lo ha spinto al male vive ancora! Con i miei studi ho scoperto questo: un Ogre Mage — Mai'Zoth — vive in un Ogre Mound tra le montagne orientali di Stranglethorn. Si dice che usi una magia capace di controllare la mente, e non ho dubbi che sia stato lui a corrompere Kurzen.\n\nSe Mai'Zoth resterà in vita, il suo male potrebbe influenzare altri, e perfino far emergere un altro Kurzen.\n\nUccidilo, e portami il suo Mind's Eye, l'artefatto che usa per corrompere gli altri.", enHash = "349758e9", vanilla = true },
        objectives = { it = "Porta il Mind's Eye a Brother Nimetz, al Rebel Camp.", enHash = "3873611d", vanilla = true },
        progress = { it = "Ti do la mia benedizione. La forza di Mai'Zoth è pari solo alla sua malvagità.", enHash = "32c32717", vanilla = true },
        reward = { it = "Aha! Ce l'hai fatta! Sei una grande forza del bene, $N, e che la tua forza non si affievolisca mai!\n\nStudierò questo Mind's Eye e stabilirò se può essere usato per il bene. Altrimenti... dovrà essere distrutto.", enHash = "f8a76590", vanilla = true },
    },
    [207] = {
        title = { it = "Il mistero di Kurzen", enHash = "c4ef61e6", vanilla = true },
        text = { it = "Un tempo Colonel Kurzen era un uomo grande e nobile — devo scoprire cosa lo ha fatto sprofondare nella depravazione! Forse è sotto l'influsso della magia troll. Per averne conferma, devo studiare alcune delle loro leggende.\n\nCi sono 4 tavolette nascoste tra le rovine troll di Stranglethorn. Devo vedere cosa c'è scritto su queste tavolette! Trascrivi i loro segni e riportami le trascrizioni.\n\nLa prima tavoletta è nelle Bal'lal Ruins, la seconda nella Vile Reef, e la terza e la quarta nelle Ruins of Zul'Kunda.", enHash = "d0cbf59e", vanilla = true },
        objectives = { it = "Trova le 4 tavolette e riporta le loro leggende a Brother Nimetz.", enHash = "7c6493bd", vanilla = true },
        progress = { it = "$N! Hai le leggende troll? Devo conoscere i loro segreti!", enHash = "e8d2a7fc", vanilla = true },
        reward = { it = "Grazie, $N. Studierò queste leggende per vedere se c'è qualche legame tra i troll e il male che si è impadronito di Colonel Kurzen.", enHash = "4085f6a1", vanilla = true },
    },
    [208] = {
        title = { it = "Cacciatore di grossa selvaggina", enHash = "c9b06c8d", vanilla = true },
        text = { it = "$N, sei $Gun cacciatore degno:una cacciatrice degna; della nostra compagnia. Dai campi di battaglia di Lordaeron alla giungla più profonda, raramente ho visto un'abilità con le armi pari a quella che hai dimostrato.\n\nHai ucciso la feroce Sin'Dall, lo sfuggente Bag'thera e l'infido Tethis. Ma il vero premio è la testa di King Bangalash. Quella tigre bianca è il motivo per cui sono qui. È da un bel po' di tempo che ho messo gli occhi su di lui. Uccidi King Bangalash e la tua abilità di caccia si dimostrerà seconda a nessuno.", enHash = "ca956fe4", vanilla = true },
        objectives = { it = "Hemet Nesingwary vuole che tu gli porti la testa di King Bangalash, la grande tigre bianca.", enHash = "b32d0adf", vanilla = true },
        progress = { it = "Vedo che sei $Gtornato:tornata;, $Gvecchio mio:ragazza mia;. King Bangalash mi ha fatto tornare all'accampamento strisciando molte volte. Tieni duro.", enHash = { "ba5f0f00", "204a7b99" }, vanilla = true },
        reward = { it = "Dannatamente ben fatto! Benissimo! Congratulazioni, $N, per essere $Griuscito:riuscita; dove altri hanno fallito.\n\nSono onorato di annoverarti tra i compagni della nostra grande squadra di caccia. Nessuno dubiterà mai della tua abilità nella caccia e nel seguire le tracce!\n\nAlla tua salute, dico io! Alla salute!", enHash = "13c30198", vanilla = true },
    },
    [209] = {
        title = { it = "Skullsplitter Tusks", enHash = "44cf1cfe", vanilla = true },
        text = { it = "Uccidere abbastanza tigri da sostenere l'esportazione di zanne di tigre verso le isole dei South Seas è costoso e difficile. Per fortuna abbiamo messo a punto una tecnica che ci permette di prendere dei comuni oggetti simili a corna e trasformarli in falsi impossibili da scoprire.\n\nLa cosa più somigliante che abbiamo trovato, incredibilmente, sono le zanne dei troll Skullsplitter.\n\nEhi, prima che tu dica qualcosa: occhio non vede, cuore non duole, giusto? Portamene un bel po', così possiamo metterci al lavoro sulla spedizione del mese!", enHash = "5c2df523", vanilla = true },
        objectives = { it = "Procura 18 Skullsplitter Tusk e riportali a Kebok.", enHash = "74ca6561", vanilla = true },
        progress = { it = "Tipi tosti, eh? Allora, hai avuto fortuna? Scusa se sembro impaziente, ma questa faccenda è stata una grossa spina nel fianco! Allora?", enHash = "e9443ccd", vanilla = true },
        reward = { it = "Ah, ottimo lavoro, ottimo lavoro! Uff, anche se avresti potuto pulire meglio il... Be', non importa, non importa! Grazie, $N: grazie al tuo aiuto la nostra attività vedrà di sicuro aumentare produzione e rendimento! Bene, bene, e ora passiamo ad altro...", enHash = "ae800726", vanilla = true },
    },
    [210] = {
        title = { it = "La cucina di Krazek", enHash = "d6a96b36", vanilla = true },
        text = { it = "All'accampamento cucino quasi sempre io. Ed era un gran lavoro, finché non ho comprato una pentola da cucina meccanica da un mercante goblin di Booty Bay. La pentola è una meraviglia! Mi ha fatto risparmiare ore e ore... finché non si è rotta!\n\nPuoi riportare la pentola al goblin per me, così la aggiusta? Si chiama Krazek.", enHash = "f08a3151", vanilla = true },
        objectives = { it = "Porta Krazek's Crock Pot al goblin Krazek.", enHash = "1f1cd730", vanilla = true },
        progress = { it = "Salve! Mi hai portato qualcosa?", enHash = "ef1f8d3a", vanilla = true },
        reward = { it = "Oh, vedo, è una Krazek's Crock Pot! Un lavoro geniale, ma ogni tanto può rompersi una molla o saltare un ingranaggio. Vediamo cosa c'è che non va in questa...\n\nAha! Il caricatore a vapore è arrugginito, ha una guarnizione a snodo incrinata e al fobulatore mancano dei denti. Mi sorprende che la pentola riuscisse anche solo a far bollire una rapa in questo stato!\n\nSe posso aggiustarla? Certo che posso aggiustarla!\n\nMa c'è un prezzo. Oh sì, c'è sempre un prezzo...", enHash = "e77aea28", vanilla = true },
    },
    [212] = {
        title = { it = "Un piatto da servire freddo", enHash = "f11949f1", vanilla = true },
        text = { it = "Uno dei miei piatti più famosi è il basilisco freddo in vinaigrette al lime. Ma il problema è che... la carne è impossibile da tenere fresca, e stasera devo servire il piatto per il compleanno di un nobile!\n\nQuindi, se riesci a portarmi in fretta un Chilled Basilisk Haunch da un Cold Eye Basilisk appena ucciso, ti dovrò un banchetto da re!\n\nSi sa che i Cold Eye Basilisk si aggirano lungo le dune della spiaggia nel nord-ovest di Stranglethorn, quindi hai molta strada da fare. E sii $Grapido:rapida;!", enHash = "3873593c", vanilla = true },
        objectives = { it = "Uccidi un Cold Eye Basilisk, prendi un Chilled Basilisk Haunch e riportalo ad Angus Stern, al Blue Recluse.\n\n<Per riuscire in questa missione non devi liberare il tuo spirito.>", enHash = "bcba0af5", vanilla = true },
        progress = { it = "$N! Hai quel cosciotto? Devo cominciare presto a prepararlo, o il banchetto sarà rovinato!", enHash = "0907501a", vanilla = true },
        reward = { it = "Ah, questo andrà benissimo! Mille, mille grazie!\n\nOra, se vuoi scusarmi, devo tagliare, marinare e guarnire il cosciotto per il banchetto.", enHash = "cd6ffae9", vanilla = true },
    },
    [213] = {
        title = { it = "Acquisizione ostile", enHash = "dee44e41", vanilla = true },
        text = { it = "Stavolta l'ha fatta grossa! Già era abbastanza grave che Gelriz facesse fuori a spintoni i magnati nominati dai principi del commercio, ora cerca pure di mettersi in mezzo agli affari del pirata più famigerato!\n\nRevilgaz non lo tollererà, e mi ha detto di occuparmi del problema a modo mio.\n\nA modo mio? Furto. I geologi della Venture Co. vicino al Lake Nazferiti sono molto interessati a quegli strani cristalli blu che trovano nelle miniere. Portami dei campioni della pietra presi dai loro geologi; non m'importa cosa dovrai fare per procurarteli.", enHash = "e8d1075a", vanilla = true },
        objectives = { it = "Recupera 8 Tumbled Crystal e riportali a Kebok, a Booty Bay.", enHash = "a1851950", vanilla = true },
        progress = { it = "Mi servono quelle pietre, $N. Con qualunque mezzo necessario! Fallo e basta, non darmi i dettagli!\n\nContano i risultati, $N, niente di più, niente di meno.", enHash = "7b160240", vanilla = true },
        reward = { it = "Affascinante. Che i cristalli siano stati levigati con questo procedimento può solo significare che intendono usarli come una specie di combustibile o come qualche altro catalizzatore. Di più non so. Bisognerà spedire dei campioni a Head Chemist Gigglefont.", enHash = "10027554", vanilla = true },
    },
    [214] = {
        title = { it = "Red Silk Bandanas", enHash = "90e810f0", vanilla = true },
        text = { it = "Non è un segreto che il marchio della Defias Gang siano le loro bandane rosse. Ma abbiamo scoperto che il materiale di cui sono fatte indica il grado del membro.\n\nDetto questo, voglio che tu elimini più Defias di alto grado che puoi. I membri di grado più alto si troveranno senz'altro nel nascondiglio segreto di VanCleef. Quando hai finito, portami 10 Red Silk Bandana come prova della loro morte e ti ricompenserò. Buona fortuna, $N.", enHash = "e656ef8d", vanilla = true },
        objectives = { it = "Scout Riell, alla Sentinel Hill Tower, vuole che le porti 10 Red Silk Bandana.", enHash = "9c29b641", vanilla = true },
        progress = { it = "Stai riprendendo la nostra terra alla banda dei Defias? Se è così, mostrami 10 Red Silk Bandana come prova.", enHash = "06a0909f", vanilla = true },
        reward = { it = "Ben fatto, $N! A nome della People's Militia ti saluto per il tuo impegno. Presto restituiremo questa terra alla gente, con l'aiuto di anime coraggiose come te.", enHash = "23bc3f93", vanilla = true },
    },
    [215] = {
        title = { it = "Segreti della giungla", enHash = "bda01760", vanilla = true },
        text = { it = "Grazie per avermi salvato, $N. So cosa sembra, ma... lasciami spiegare.\n\nLieutenant Doren mi aveva incaricato di arruolarmi di nuovo tra gli uomini di Kurzen, per spiarli e portare ai ribelli informazioni di cui hanno un disperato bisogno. Quello che hai visto qui era, credevo, la mia occasione per infiltrarmi nel Kurzen's Compound. Mi sbagliavo, e grazie ancora per avermi salvato.\n\nEra una missione segretissima, quindi non devi dirlo a nessuno. Ma se parli con Doren, te lo spiegherà lui.", enHash = "bb8d3855", vanilla = true },
        objectives = { it = "Parla con Lieutenant Doren, al Rebel Camp.", enHash = "8056f5d4", vanilla = true },
        reward = { it = "Sì, quello che ti ha detto Thorsen è vero. Devi essere $Gdiscreto:discreta; su questa faccenda. Un tempo noi ribelli eravamo ferocemente leali a Colonel Kurzen. Ma la corruzione di Kurzen era tale che la nostra passione si è trasformata in rabbia. Se si venisse a sapere che di recente Private Thorsen ha avuto a che fare con gli uomini di Kurzen, una notte si ritroverebbe con la gola tagliata.\n\nPer quanto ne so, solo Sergeant Yohwa, Thorsen e io eravamo al corrente della missione di Thorsen. Ma dev'esserci qualcun altro. Un traditore.", enHash = "f4e688f2", vanilla = true },
    },
    [216] = {
        title = { it = "Tra l'incudine e i Thistlefur", enHash = "1191a320", vanilla = true },
        text = { it = "I furbolg Thistlefur minacciano la nostra espansione! Thistlefur Village, a est di qui, blocca la via tra noi e Splintertree Post. È un percorso che aggirerebbe il villaggio di Astranaar; senza di esso, diamo all'Alleanza una via di espansione in più.\n\n$N, non possiamo permettere... un divario nelle vie di espansione!\n\nVa' a Thistlefur Village e dirada i furbolg. Riceverai un compenso per questo incarico, ma soprattutto farai il tuo dovere per l'Orda!", enHash = "1f7d4453", vanilla = true },
        objectives = { it = "Abbatti 12 Thistlefur Avenger e 12 Thistlefur Shaman; la maggior parte si trova a est dello Zoram Strand, a Thistlefur Village. Fatto questo, torna da Karang Amakkar allo Zoram'gar Outpost, in Ashenvale.", enHash = "caa978bd", vanilla = true },
        progress = { it = "Hai portato la battaglia ai Thistlefur? Con una via libera tra le nostre basi, le nostre possibilità di prenderci tutta Ashenvale aumentano moltissimo.", enHash = "4cd275a6", vanilla = true },
        reward = { it = "Ben fatto, $C, ben fatto! Continuerò a mandare forze a diradare i furbolg, ma almeno posso contare su un'altra via, libera dagli impicci dell'Alleanza. La conquista di Ashenvale da parte dell'Orda è ormai in pieno svolgimento!\n\nOggi ti sei $Gguadagnato:guadagnata; la paga, $Geroe:eroina;. Ti saluto!", enHash = "cd0bfafd", vanilla = true },
    },
    [217] = {
        title = { it = "In difesa delle terre del re", enHash = "87756ca8", vanilla = true },
        text = { it = "$N, i nostri esploratori hanno individuato il capo di questa recente incursione dei trogg. A quanto pare le bestie del Loch Modan seguono un capoclan di nome Grawmug. Grawmug però è sorvegliatissimo. Due delle sue guardie migliori, Gnasher e Brawler, non si allontanano mai da lui.\n\nSe ti senti $Gdegno:degna;, $N, voglio che sia tu a guidare la missione per assassinare Grawmug e i suoi due sgherri. Con i capi dei trogg morti, potremmo davvero avere una possibilità di ricacciare quelle bestie sottoterra.", enHash = "2e76b700", vanilla = true },
        objectives = { it = "Uccidi il capo dei trogg, Grawmug, e le sue due guardie, Gnasher e Brawler, poi torna a riferire a Captain Rugelfuss, nella torre di guardia a sud.", enHash = "37926b75", vanilla = true },
        progress = { it = "Grawmug e le sue due guardie, Gnasher e Brawler, sono ancora vivi. La tua missione non è compiuta finché tutti e 3 non saranno morti. L'impero dei nani conta su di te, $N.", enHash = "4dd42346", vanilla = true },
        reward = { it = "Eccellente, $N! Hai portato speranza al Loch Modan. Con Grawmug morto, abbiamo più possibilità di vedere i trogg spazzati via da questa terra.", enHash = "4e066c7e", vanilla = true },
    },
    [218] = {
        title = { it = "Il diario rubato", enHash = "7f84b8cd" },
        text = { it = "Il mio diario! L'hanno portato nella grotta. Quello che l'aveva... era un bestione grosso, con strani segni sulla pelle e sul viso. Non sono riuscito a vederlo meglio di così.\n\nCon i troll hai avuto fortuna: magari potresti andare a recuperarmelo?", enHash = "262aaf4b" },
        objectives = { it = "Grelin Whitebeard vuole che tu uccida Grik'nir the Cold e recuperi il suo diario.", enHash = "a884da01" },
        progress = { it = "$N! Novità?", enHash = "a1b02f31", vanilla = true },
        reward = { it = "Magnifico, $N! Grazie mille per aver recuperato il mio quaderno. Be', sembra che la situazione dei troll qui nella Coldridge Valley sia sotto controllo e non dia troppi motivi di preoccupazione.\n\nQuando avrò dato gli ultimi ritocchi al mio rapporto, mi servirà qualcuno che lo porti a mio fratello Senir.", enHash = "c43eda9f", vanilla = true },
    },
    [219] = {
        title = { it = "Disperso in azione", enHash = "ff685357", vanilla = true },
        text = { it = "Finalmente, amici dell'Alleanza!\n\nAiuto... vi prego...\n\nL'ultima cosa che ricordo è che quegli orchi immondi hanno sopraffatto il nostro reggimento. Quasi tutti gli uomini sono stati uccisi. Ho preso un colpo forte alla testa e tutto è diventato nero. Adesso mi tengono prigioniero in questa grotta. Aiutatemi, sono ferito gravemente.\n\nMi servirà aiuto per tornare in paese... vi prego... siete la mia ultima speranza...", enHash = "c402a939", vanilla = true },
        objectives = { it = "Proteggi Corporal Keeshan nel viaggio di ritorno a Redridge.", enHash = "228eb7e2", vanilla = true },
        progress = { it = "Sì?", enHash = "00388a38", vanilla = true },
        reward = { it = "Hai servito bene il Regno, $C. Grazie per aver aiutato Corporal Keeshan a fuggire da quei temuti orchi Blackrock. Sarai $Gricompensato:ricompensata; per le tue azioni coraggiose di oggi.", enHash = "677d92aa", vanilla = true },
    },
    [220] = {
        title = { it = "Il richiamo dell'acqua", enHash = "eab41910", vanilla = true },
        text = { it = "Islen avrà un ultimo compito per te prima di ricompensarti con il tuo prossimo totem. La fiala d'acqua che ti ho dato è necessaria per quel compito, qualunque sia.\n\nOra va' e trovala. Ci rivedremo, un giorno.", enHash = "0d1c8db1", vanilla = true },
        objectives = { it = "Porta la Vial of Purest Water a Islen Waterseer, nelle Barrens.", enHash = "d31b9e15", vanilla = true },
        progress = { it = "Salve di nuovo, $N. Ti trovo bene.\n\nCosa ti riporta da me così presto?", enHash = "694b8b98", vanilla = true },
        reward = { it = "Ah, una fiala d'acqua creata e benedetta da Brine, e raccolta da te, nientemeno.\n\nIl liquido di questa fiala sarà fondamentale per creare una sapta per te, ma servirà anche per un altro compito.\n\nLa sapta che creerò per te andrà usata per vedere gli spiriti dell'acqua al santuario della Silverpine Forest, a sud dell'Undercity. Le gocce rimaste... be', delle gocce rimaste ti parlerò se ti senti $Gpronto:pronta;.\n\nSei $Gpronto:pronta; per un altro viaggio, $N?", enHash = "951846f7", vanilla = true },
    },
    [221] = {
        title = { it = "Worgen nei boschi", enHash = "fe05cd26", vanilla = true },
        text = { it = "Avrai notato qualche worgen più grosso che si aggira con gli Shadow Weaver nei boschi, no? Da quel che possiamo dire, sono questi Dark Runner a fare il grosso delle file dei worgen.\n\nNelle mie perlustrazioni ho notato anche che hanno invaso il Rotting Orchard, a sud-ovest del paese. Questi worgen sono un po' più duri degli ultimi che hai affrontato.\n\nSta' in guardia.", enHash = "26d43678", vanilla = true },
        objectives = { it = "Uccidi 12 worgen Nightbane Dark Runner per Calor, a Darkshire.", enHash = "6130297d", vanilla = true },
        progress = { it = "Già di ritorno, $N? Spero che tu non sia $Gvenuto:venuta; a dirmi che hai rinunciato.", enHash = "09f5c5bf", vanilla = true },
        reward = { it = "Te la sei cavata bene contro i Dark Runner, $N. Ma sembra che il loro numero sia inesauribile. Ogni volta che facciamo progressi, ne spuntano altri a riempire le file.\n\nQual è il potere maligno che li attira qui? Perché sono venuti a turbare il nostro regno infelice...\n\nIo riporrò la mia fiducia in Master Carevin. Di sicuro andrà a fondo della questione.", enHash = "06e4b7db", vanilla = true },
    },
    [222] = {
        title = { it = "Worgen nei boschi", enHash = "fe05cd26", vanilla = true },
        text = { it = "Quel che hai fatto finora mi ha convinto che sei $Gpronto:pronta; ad affrontare i worgen più duri che infestano i boschi.\n\nFra i worgen che si sono fatti una nuova casa qui, i Vile Fang e i Tainted One si sono rivelati i più pericolosi. Si sono sistemati vicino ad alcune caverne e nella miniera a sud.\n\nDa lontano si vede perfino la luce dei loro falò...", enHash = "4999a3b8", vanilla = true },
        objectives = { it = "Uccidi 8 worgen Nightbane Vile Fang e 8 Nightbane Tainted One per Calor, a Darkshire.", enHash = "dcd89758", vanilla = true },
        progress = { it = "Bestie che mettono paura, vero? Ma non temere, $N: chi sta dalla parte della Luce non cadrà mai!", enHash = "78efe610", vanilla = true },
        reward = { it = "$N, a dirti la verità non credevo che saresti $Garrivato:arrivata; fin qui, ma è chiaro che sei $Gun:una; $C con cui fare i conti. Anzi, se vuoi unirti ufficialmente alla lotta di Master Carevin, ti scriverò volentieri una lettera di raccomandazione.", enHash = "df5b19a2", vanilla = true },
    },
    [223] = {
        title = { it = "Worgen nei boschi", enHash = "fe05cd26", vanilla = true },
        text = { it = "Ecco qua, $N. Porta questo messaggio a Master Carevin.\n\n<Tira fuori in fretta un pezzo di pergamena sbiadita e te lo porge.>\n\nAncora qualcuno come te, e saremo più numerosi della Guardia Notturna! Forse allora potremo portare a termine il lavoro che noi pochi mandiamo avanti oggi.", enHash = "2bb9cc33", vanilla = true },
        objectives = { it = "Porta il biglietto di Calor a Jonathan Carevin.", enHash = "512e81a3", vanilla = true },
        progress = { it = "Sì, che c'è? Fa' in fretta, ho questioni urgenti di cui occuparmi.", enHash = "f3a54ed9", vanilla = true },
        reward = { it = "Scusa l'accoglienza fredda, $N, ma come avrai capito sono un uomo estremamente occupato. Vedo che hai fatto colpo su Calor — e ti assicuro che non è cosa da poco — e che ti ha dato la sua raccomandazione.\n\nIn giro c'è gente poco raccomandabile, $N, e ci serve l'aiuto di tutti quelli che hanno dimostrato il proprio valore. Combattiamo contro i demoni, i non morti e chi dà loro aiuto. Sii vigile, sta' $Gattento:attenta;, e non fidarti di nessuno che non aiuti la nostra causa.\n\nGloria nella Luce.", enHash = "e9637dd3", vanilla = true },
    },
    [224] = {
        title = { it = "In difesa delle terre del re", enHash = "87756ca8", vanilla = true },
        text = { it = "Dobbiamo proteggere il Loch, $N! Con tanti soldati del re che combattono valorosamente su campi di battaglia lontani, qui sul fronte interno siamo sopraffatti. I trogg scavano gallerie e sbucano da ogni fessura! L'infestazione di trogg è la minaccia più grande per Ironforge. Questi mutanti disgustosi vanno distrutti.\n\nAbbiamo bisogno di te, $Gvaloroso avventuriero:valorosa avventuriera;: va' avanti e fa' strage della minaccia trogg. Uccidi 10 Stonesplinter Trogg e 10 Stonesplinter Scout, poi torna a riferire.", enHash = "a5cc3957", vanilla = true },
        objectives = { it = "Mountaineer Cobbleflint, della torre di guardia a sud, vuole che tu uccida 10 Stonesplinter Trogg e 10 Stonesplinter Scout.", enHash = "07562ffa", vanilla = true },
        progress = { it = "Il Loch Modan è sotto assedio, $N! Ci serve ogni membro dell'Alleanza in grado di combattere. Hai già ucciso 10 Stonesplinter Trogg e 10 Stonesplinter Scout?", enHash = "21b9e1a4", vanilla = true },
        reward = { it = "Ben fatto, $N! Hai dimostrato un coraggio fuori dal comune sul campo di battaglia. La nostra guerra contro i trogg si vincerà con imprese come la tua. Hai servito bene King Magni.\n\nSe ti senti $Gportato:portata; per questo genere di avventure, ti consiglio di parlare con Mountaineer Gravelgaw. Il capitano gli ha assegnato una pattuglia difficile, e sono sicuro che un po' d'aiuto gli farebbe comodo. Passa da Gravelgaw, subito dentro la torre.", enHash = "e49bb38d", vanilla = true },
    },
    [225] = {
        title = { it = "La tomba consunta", enHash = "95f92d89", vanilla = true },
        text = { it = "Sulla lapide consunta si legge soltanto:\n\nMORGAN LADIMORE\n\n<Guardando meglio, noti che la terra sopra la tomba è stata smossa di recente, e che una buona parte è stata spostata...>", enHash = "c3c47773", vanilla = true },
        objectives = { it = "Parla con Sirra Von'Indi, a Darkshire.", enHash = "0823e435", vanilla = true },
        reward = { it = "Morgan Ladimore?\n\nAhh, sì, certo. La sua è una storia lunga e dolorosa. Lo conoscevo bene, prima che partisse per la guerra, ma è stata l'ultima volta che l'ho visto. Era un uomo nobile e buono, ma ha fatto una brutta fine.\n\nAspetta, qui dovrei avere qualcosa che racconta la storia meglio dei miei ricordi...", enHash = "c697fe3c", vanilla = true },
    },
    [226] = {
        title = { it = "Lupi alle calcagna", enHash = "0aac9c9e", vanilla = true },
        text = { it = "Io e Sven abbiamo giorni pericolosi davanti, con il negromante a est e tutto il resto. E qui fuori, soli come siamo, il cibo dobbiamo cacciarcelo da noi. Sembra che ogni volta che torno all'accampamento con addosso un po' di carne, dalla foresta sbuchino Starving Dire Wolf o Rabid Dire Wolf in cerca di un boccone. Inutile dirlo: vivere qui fuori è un mestiere pericoloso!\n\nMa se ci liberassi da un po' di quei lupi, per noi sarebbe più facile. Si aggirano soprattutto a nord e a est di qui, vicino al fiume.", enHash = "793a451b", vanilla = true },
        objectives = { it = "Uccidi 12 Starving Dire Wolf e 8 Rabid Dire Wolf, poi torna da Lars a Sven's Camp, al confine occidentale di Duskwood.", enHash = "b184b15b", vanilla = true },
        progress = { it = "Sei ancora a caccia di lupi...?", enHash = "bb7585cb", vanilla = true },
        reward = { it = "Oh, bene. Hai diradato parecchio quel branco, e senza quei lupi alle calcagna possiamo concentrarci su Morbent Fel.\n\nTieni, prendi un po' di questi Flash Bundle. Li fanno in città, e molti sono stati donati a Sven per aiutarlo nella sua causa.", enHash = "e040dbe3", vanilla = true },
    },
    [227] = {
        title = { it = "Morgan Ladimore", enHash = "fa082deb", vanilla = true },
        text = { it = "<Fruga tra gli scaffali e ne tira fuori un libro rilegato in pelle.>\n\nSe vuoi saperne di più, potresti chiedere ad Althea: è lei che si è occupata dei... guai... con lui, ultimamente.", enHash = "a2cbefff", vanilla = true },
        objectives = { it = "Parla con Commander Althea Ebonlocke, a Darkshire.", enHash = "ddbef405", vanilla = true },
        reward = { it = "Morgan Ladimore? Mai sentito...\n\nOh, intendi Mor'Ladim! Immagino che tu non conosca la storia.\n\nBe', te la faccio breve. Un non morto errante che si fa chiamare Mor'Ladim si aggira per Duskwood. Da quel che abbiamo raccolto, sembra essere il corpo non morto di Morgan Ladimore, che a quanto pare tu conosci. Ci sta dando problemi di ogni tipo: attacca i Watchman di pattuglia e uccide la gente.\n\n<Ti squadra.>\n\nSembri abbastanza capace: forse potresti dargli pace tu.", enHash = "1d5627b3", vanilla = true },
    },
    [228] = {
        title = { it = "Mor'Ladim", enHash = "02f8a23c", vanilla = true },
        text = { it = "Da quel che mi dicono i miei esploratori, Mor'Ladim vaga per tutta Duskwood, seguendo un percorso strano e tortuoso attraverso il cimitero. L'abbiamo sepolto oltre la casa sulla collina: sai dov'è?\n\nNon c'è niente che io possa fare per aiutarti, ma ti auguro buona fortuna.", enHash = "cac1dff7", vanilla = true },
        objectives = { it = "Uccidi Mor'Ladim, poi porta il suo teschio a Commander Althea Ebonlocke, a Darkshire.", enHash = "fa213b72", vanilla = true },
        progress = { it = "Non ti biasimo se hai difficoltà con lui, $N. Mor'Ladim ci è già costato alcuni dei nostri Watcher più forti.", enHash = "c1fafb93", vanilla = true },
        reward = { it = "L'hai ucciso? Non è cosa da poco, $N! A nome della gente di Darkshire e della Guardia Notturna, ti ringrazio.\n\nAh... c'è però una piccola questione...", enHash = "8520b3ac", vanilla = true },
    },
    [229] = {
        title = { it = "La figlia sopravvissuta", enHash = "c49e8f0d", vanilla = true },
        text = { it = "Avrei dovuto dirtelo prima...\n\nCome posso metterla...\n\nMorgan può anche aver creduto che la sua famiglia fosse tutta morta, ma in realtà sua figlia Sarah Ladimore adesso è una Watcher. L'hanno sempre tormentata le... circostanze... della morte del padre. Forse potresti andare tu a darle la notizia.", enHash = "c1151e69", vanilla = true },
        objectives = { it = "Parla con Watcher Sarah Ladimore, a Darkshire.", enHash = "3d80798c", vanilla = true },
        reward = { it = "Sì? Mio padre...\n\n<I suoi occhi si abbassano.>\n\nVorrei... che ci fosse stato qualcosa che potevo fare per lui... Se solo gli avessi parlato prima che...", enHash = "dfa64126", vanilla = true },
    },
    [230] = {
        title = { it = "Sven's Camp", enHash = "73994529", vanilla = true },
        text = { it = "Scavando nel cumulo, trovi un piccolo libro sporco di terra.\n\nIl libro non ha titolo, ma... contiene informazioni che Sven vorrebbe sapere.", enHash = "18d8fe58", vanilla = true },
        objectives = { it = "Porta il Book from Sven's Farm a Sven.", enHash = "c6003f9b", vanilla = true },
        progress = { it = "Hai trovato cosa?? Ti prego, fammelo vedere...", enHash = "05fad834", vanilla = true },
        reward = { it = "<Sven legge le pagine del libro, poi lo chiude di colpo.>\n\nQuella figura in ombra che ho visto era un testimone della morte della mia famiglia! Ci sono domande che vorrei fare a quell'uomo... se solo sapessi chi era!", enHash = "e91a0d9f", vanilla = true },
    },
    [231] = {
        title = { it = "L'amore di una figlia", enHash = "506ef81f", vanilla = true },
        text = { it = "Tieni, prendi questo e posalo sulla sua tomba. Forse... in qualche modo saprà che sto bene, e che nessuno di noi lo ritiene responsabile di quel che è successo.\n\n<Adesso ha le lacrime agli occhi, mentre si sfila un anello dalla mano destra e te lo preme fra le mani.>\n\nE... grazie, $N.", enHash = "37166a2e", vanilla = true },
        objectives = { it = "Porta l'anello di Sarah Ladimore alla tomba di Morgan Ladimore.", enHash = "55b5a0de", vanilla = true },
        progress = { it = "Lasciami in pace...", enHash = "2e685a0c", vanilla = true },
        reward = { it = "<Una voce spettrale risuona nel vento...>\n\nQuesto è...? Sarah? Può essere che sia ancora viva? Il peso mi si toglie dalle spalle...\n\n$N. Prendi la mia spada, Archeus. Ora che la mia anima trova pace, non me ne faccio più niente. Fu forgiata per fare del bene e, anche se io mi sono dimostrato indegno di impugnarla, forse tu porterai avanti la Luce attraverso di essa.\n\nLys, amore mio...", enHash = "8216692b", vanilla = true },
    },
    [233] = {
        title = { it = "Consegna della posta nella Coldridge Valley", enHash = "d029cd75" },
        text = { it = "Mmh, immagino che tu non sia $Gdisposto:disposta; a farmi un favore, $Gragazzo:ragazza;? Oggi è arrivata dal passo una pila di lettere, ma non ho tempo di recapitarle.\n\nSono tutte indirizzate a Talin Keeneye. Lo trovi a ovest, lungo la strada. Si è accampato vicino al lago ghiacciato.\n\nChe ne dici?", enHash = { "9472538b", "f5fdd189" } },
        objectives = { it = "Consegna la pila di lettere a Talin Keeneye.", enHash = "62aa68a7" },
        progress = { it = "Sì? Hai qualcosa per me?", enHash = "571ab160", vanilla = true },
        reward = { it = "Grazie, aspettavo queste lettere da un bel po'...\n\nPurtroppo non sono tutte per me. Questa è indirizzata a Grelin Whitebeard. Non è troppo lontano, se vuoi portargliela.", enHash = "aafd2d12", vanilla = true },
    },
    [234] = {
        title = { it = "Consegna della posta nella Coldridge Valley", enHash = "d029cd75", vanilla = true },
        text = { it = "Se ricordo bene, l'accampamento di Grelin è lungo la strada, a sud-est. Di sicuro non vedrà l'ora di ricevere la sua posta.", enHash = "7a606323", vanilla = true },
        objectives = { it = "Consegna la lettera a Grelin Whitebeard.", enHash = "26c5cb73", vanilla = true },
        progress = { it = "Posso aiutarti in qualcosa?", enHash = "302c7898", vanilla = true },
        reward = { it = "Ah, ottimo. Era da un po' che non ricevevo notizie da Ironforge.", enHash = "2a3f9705", vanilla = true },
    },
    [235] = {
        title = { it = "La caccia di Ashenvale", enHash = "543bb59f", vanilla = true },
        text = { it = "Attenzione, giovani avventurieri! Le terre selvagge di Ashenvale vi aspettano!\n\nL'Orda ha stabilito una presenza solida nelle terre a nord delle Barrens. I nostri due avamposti — Splintertree Post e lo Zoram Strand Outpost — si adoperano per portare gloria all'Orda! Chi vuole mettersi alla prova dovrebbe cercare una guida laggiù. Da notare: Senani Thunderheart, a Splintertree Post, subito a nord delle Barrens, cerca avventurieri disposti a prendere parte a una grande caccia di Ashenvale!", enHash = "d1827415", vanilla = true },
        objectives = { it = "Parla con Senani Thunderheart a Splintertree Post, in Ashenvale.", enHash = "4a6d4371", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta; nella nuova frontiera, $N. Ashenvale è una terra di opportunità, dove $Gun giovane:una giovane; $C come te può trovare occasioni senza fine per dimostrare il proprio valore. Guardati intorno qui all'avamposto, e non mancare di spingerti fino allo Zoram Strand, perché anche lì l'Orda ha un altro avamposto.\n\nLa tua presenza qui mi dice che sei $Gvenuto:venuta; per sapere di più sulla caccia. Ascolta bene, e condividerò volentieri con te quello che ti serve sapere.", enHash = "5155084f", vanilla = true },
    },
    [237] = {
        title = { it = "In difesa delle terre del re", enHash = "87756ca8", vanilla = true },
        text = { it = "Mountaineer Cobbleflint ha parlato benissimo di te, $R. Per questo sto per affidarti una missione della massima importanza. Dobbiamo tenere sotto pressione le forze trogg che ci invadono, finché i nostri fratelli nani non tornano dal fronte dell'Alleanza.\n\nAvviati verso le colline a sud e uccidi 10 Stonesplinter Skullthumper e 10 Stonesplinter Seer. I tuoi attacchi ci faranno guadagnare tempo. Torna a riferire quando la missione è compiuta.", enHash = "448197b7", vanilla = true },
        objectives = { it = "Mountaineer Gravelgaw, nella torre di guardia a sud, vuole che tu uccida 10 Stonesplinter Skullthumper e 10 Stonesplinter Seer, e torni a riferirglielo.", enHash = "2cad543b", vanilla = true },
        progress = { it = "Ci serve altro tempo, $R. I tuoi ordini sono di uccidere 10 Stonesplinter Skullthumper e 10 Stonesplinter Seer. Tieni il nemico sotto pressione finché non ci concedono i rinforzi. Non è tempo di starsene con le mani in mano.", enHash = "d9c9b4de", vanilla = true },
        reward = { it = "Hai portato a termine bene la tua missione, $R. Il re in persona ne sarebbe fiero.\n\nI rinforzi che ci avevano promesso, però, non sono mai arrivati. A quanto pare il fronte dell'Alleanza è un mare cremisi del sangue dei nostri fratelli caduti. La notizia di quelle perdite lascia l'amaro in bocca. Ma non possiamo lasciare che quelle morti siano vane. Dobbiamo serrare le file in questi tempi bui e riportare gloria all'Alleanza.\n\nParla con Mountaineer Wallbang per un nuovo incarico. Ora c'è bisogno di te più che mai.", enHash = "b58bf29c", vanilla = true },
    },
    [239] = {
        title = { it = "La Westbrook Garrison ha bisogno d'aiuto!", enHash = "d9ce0cf4" },
        text = { it = "La guarnigione al nostro confine occidentale manda notizia che l'attività di gnoll e ladri è in aumento. Chiedono che mandiamo altri soldati di Stormwind... ma non ne abbiamo proprio da mandare!\n\nSe puoi aiutare, ci farebbe comodo. Va' a parlare con Deputy Rainer, alla Westbrook Garrison, e senti cosa c'è da fare.\n\nLa guarnigione è lungo la strada, a ovest. Dopo aver attraversato il ponte sul ruscello, sarà sulla destra.", enHash = "286aeeac" },
        objectives = { it = "Va' alla Westbrook Garrison e parla con Deputy Rainer.", enHash = "7ae9c60e" },
        reward = { it = "Ti manda Marshal Dughan, eh? Be', non sei dell'esercito, ma se ti manda Dughan a me basta!\n\nLa nostra situazione è, a dir poco, tesa. Spero che tu possa darci una mano.", enHash = "05d8da7a" },
    },
    [240] = {
        title = { it = "Torna da Jitters", enHash = "95724952", vanilla = true },
        text = { it = "Ed eccoci qua — \"Crab\" Cake alla Grual!", enHash = "d463fcc1", vanilla = true },
        objectives = { it = "Torna da Jitters con i Dusky Crab Cake.", enHash = "e65c2038", vanilla = true },
        progress = { it = "$N, sei qui! Hai il mio cibo?!?", enHash = "593b7877", vanilla = true },
        reward = { it = "Aha! Grazie, $N. Erano proprio quel che ci voleva!\n\nE tieni, lascia che te li paghi!", enHash = "3ab3fa37", vanilla = true },
    },
    [244] = {
        title = { it = "Gnoll alle porte", enHash = "41021558", vanilla = true },
        text = { it = "Salve, $C. Ho l'incarico di pattugliare questo tratto di strada. Per ora la strada è sicura, ma ho visto accampamenti di gnoll a nord e a est di qui.\n\nLakeshire deve sapere che le forze degli gnoll si stanno radunando! Presentati a Deputy Feldon, a Lakeshire, e parlagli degli gnoll. Fallo, e di sicuro Feldon ti offrirà la paga di un esploratore.\n\nDi solito Feldon ispeziona la zona a sud del ponte per Lakeshire.", enHash = "5ef5b3b6", vanilla = true },
        objectives = { it = "Presentati a Deputy Feldon.", enHash = "95cc1cdc", vanilla = true },
        reward = { it = "Ci sono gnoll di Redridge così vicini a Elwynn?? Potrebbero essere pronti ad avanzare verso la nostra terra. Presto la gente di Lakeshire potrebbe non essere l'unica sotto assedio!\n\nEcco la tua paga, anche se ci porti notizie terribili. E arrivano in un brutto momento, perché non siamo attrezzati per affrontarle.", enHash = "dcd534b7", vanilla = true },
    },
    [245] = {
        title = { it = "Minacce a otto zampe", enHash = "7f511e7c", vanilla = true },
        text = { it = "Salve, $C. Avrai visto quei ragni che si sono impadroniti del confine occidentale, no? Quelle minacce a otto zampe sono troppo per noi, e la comandante non ha uomini a sufficienza da mandare così lontano da Darkshire.\n\nMi dispiace chiedertelo, ma sembri in grado di occupartene. Non posso prometterti niente di grande valore, ma posso ricompensarti se ci aiuti a stanare quegli insetti immondi.\n\nAh, e un consiglio: se puoi, evita il loro veleno.", enHash = "09f53a7a", vanilla = true },
        objectives = { it = "Uccidi 15 Pygmy Venom Web Spider, poi torna a riferire a Watcher Dodds, a Duskwood.", enHash = "e14d15ba", vanilla = true },
        progress = { it = "Faresti meglio a stare $Gattento:attenta; con quei ragni: ci ho rimesso qualche uomo, e credimi, non è un bello spettacolo un uomo appeso a testa in giù nelle loro ragnatele dopo che il veleno ha cominciato ad ammorbidirlo.\n\nNon vorrei vederti diventare il pranzo di uno di quegli insetti.", enHash = "366caae7", vanilla = true },
        reward = { it = "Ah! Sei $Gtornato:tornata;. E a quanto pare non troppo $Gmalconcio:malconcia;. Naturalmente, $N, la Guardia Notturna ti è grata per il tuo lavoro, e una ricompensa te l'avevo promessa, quindi eccola.", enHash = "509d48d9", vanilla = true },
    },
    [246] = {
        title = { it = "Valutare la minaccia", enHash = "2168980b", vanilla = true },
        text = { it = "Non abbiamo uomini da mandare, ma qualcosa va fatto per quegli gnoll di cui mi hai parlato.\n\nEsplora il sud di Redridge in cerca di gnoll. Incalzali, uccidi quelli che puoi e torna da me con un conteggio del loro numero e una valutazione della minaccia che rappresentano. Quegli gnoll li trovi accampati lungo tutta la strada meridionale di Redridge.\n\nFallo per l'esercito di Stormwind, $N, e sarai $Gricompensato:ricompensata;.", enHash = "ff68dfb1", vanilla = true },
        objectives = { it = "Uccidi 10 Redridge Mongrel e 6 Redridge Poacher, poi torna a riferire a Deputy Feldon, a Lakeshire.", enHash = "fda66405", vanilla = true },
        progress = { it = "Scusami, $N, ma qui abbiamo già le mani legate da tante cose. Se non hai niente da riferire, devo dedicarmi ad altro.", enHash = "a2385461", vanilla = true },
        reward = { it = "<Deputy Feldon ascolta il tuo rapporto...>\n\nLà è accampata una forza consistente di gnoll, e da quello che mi dici sono tipi duri. Non dev'essere stato facile raccogliere queste informazioni.\n\nEcco a te, $N. Ti siamo grati per l'aiuto.\n\nE se non l'hai già fatto, parla con Marshal Marris e Magistrate Solomon, dentro Lakeshire. La nostra situazione si fa sempre più disperata: sono sicuro che tutti e due avranno bisogno di te.", enHash = "32734b20", vanilla = true },
    },
    [247] = {
        title = { it = "La caccia completata", enHash = "d097818d", vanilla = true },
        reward = { it = "$N, hai ucciso tutte e tre le bestie che compongono la caccia di Ashenvale. Mi hai portato prove sufficienti della loro fine; la tua forza e la tua tenacia sono fuori discussione. Nelle tue vene scorre il sangue di $Gun cacciatore:una cacciatrice;, e meriti ogni elogio!\n\nTi prego, accetta questo ninnolo come congratulazioni per le grandi imprese che hai compiuto oggi ad Ashenvale per l'Orda. Che i tuoi antenati veglino su di te!", enHash = "55d189eb", vanilla = true },
    },
    [248] = {
        title = { it = "Guardare più lontano", enHash = "08b4c3e7", vanilla = true },
        text = { it = "Ho tenuto d'occhio la Tower of Ilgalar, e riesco a capire che Morganth è in conflitto con gli orchi dello Stonewatch Keep. Non conosco il motivo della loro contesa, ma tu puoi aiutarmi a sciogliere il mistero.\n\nPrendi un altro Glyph of Azora, poi sali in cima alla torre di guardia ancora intatta accanto allo Stonewatch Keep.\n\nTrova un oggetto adatto su cui posare il glifo. Una cassa o un vaso — un posto dove il glifo non venga notato — farà al caso mio.", enHash = "71538bd7", vanilla = true },
        objectives = { it = "Sali sulla torre di guardia intatta accanto allo Stonewatch Keep.\n\nTrova un contenitore adatto dove mettere il Glyph of Azora.", enHash = "6df88d51", vanilla = true },
        progress = { it = "Questo vaso un tempo conteneva un liquore dall'odore disgustoso, ma ora giace vuoto e dimenticato su un paio di barili.", enHash = "7f03c49c", vanilla = true },
        reward = { it = "È un recipiente adatto per il Glyph of Azora, e permette a Theocritus di scavare nelle menti dentro lo Stonewatch Keep.", enHash = "d6a1a1e7", vanilla = true },
    },
    [249] = {
        title = { it = "Morganth", enHash = "f3157b38", vanilla = true },
        text = { it = "Dopo molte osservazioni, ho scoperto i piani di Morganth.\n\nCerca la Scythe of Elune... e forse l'ha trovata! Se è così, presto le Redridge Mountains, e il regno di Stormwind, sentiranno la sua oscura potenza.\n\nNon sono pronto a misurarmi con Morganth, ma temo che vada affrontato ora. Quindi devi entrare tu nella Tower of Ilgalar e affrontare Morganth.\n\nSconfiggilo e portami il suo Pendant of Shadow. Fallo, e il regno ti dovrà molto.", enHash = "ef68e7b1", vanilla = true },
        objectives = { it = "Sconfiggi Morganth.\n\nPorta il suo Pendant of Shadow a Theocritus, alla Tower of Azora, nell'Elwynn Forest.", enHash = "47ca0cbf", vanilla = true },
        progress = { it = "Sbrigati, $N, prima che i miei timori sul potere di Morganth che si diffonde diventino realtà!", enHash = "e059542b", vanilla = true },
        reward = { it = "Hai fatto bene, $N. Sconfiggendo lo stregone Morganth hai salvato Stormwind da un grave pericolo.\n\nTi offro questa ricompensa con umiltà. E ti augurerei pace, se questi fossero tempi di pace.\n\nMa invece ti auguro fortuna nelle tue prove, e vittoria negli scontri che verranno.", enHash = "85c0784f", vanilla = true },
    },
    [250] = {
        title = { it = "Un'ombra minacciosa", enHash = "88b632d7", vanilla = true },
        text = { it = "Siano lodate le stelle, qualcuno si preoccupa della sorte della diga. Prima la distruzione del Thandol Span e poi il saccheggio di Dun Modr! Non ho dubbi che la diga sarà il bersaglio della prossima minaccia dei Dark Iron. Quasi tutto il servizio di sicurezza qui è stato riassegnato al fronte dell'Alleanza, compreso il mio ispettore capo.\n\nPer questo ho bisogno di te, $N. Ho visto dei Dark Iron Sapper aggirarsi intorno alla rampa orientale della diga. Indaga nella zona e riporta un indizio.", enHash = "6940c38c", vanilla = true },
        objectives = { it = "Indaga nella zona vicino alla rampa orientale della diga e porta a Chief Engineer Hinderweir un indizio che riveli cosa stanno tramando i Dark Iron Dwarf.", enHash = "aaf7faba", vanilla = true },
        reward = { it = "Il barile dall'aria sospetta contiene una polvere dall'odore strano.", enHash = "e5720127", vanilla = true },
    },
    [251] = {
        title = { it = "Traduci il biglietto di Abercrombie", enHash = "3b0baa15", vanilla = true },
        text = { it = "Porta il biglietto che mi hai dato a Sirra Von'Indi. È molto istruito in lingue e arti antiche: se c'è qualcuno qui che può tradurre questo messaggio, è lui.", enHash = "f7da51de", vanilla = true },
        objectives = { it = "Porta la Letter to Ello a Sirra Von'Indi.", enHash = "3a2915e6", vanilla = true },
        progress = { it = "Un biglietto di Abercrombie l'eremita, eh? Non lo conosco, anche se, se vive laggiù al cimitero, di sicuro so che il cervello gli è marcito!", enHash = "031b856b", vanilla = true },
        reward = { it = "<Sirra comincia a tradurre il biglietto...>", enHash = "3a93f06b", vanilla = true },
    },
    [252] = {
        title = { it = "La traduzione per Ello", enHash = "215d9080", vanilla = true },
        text = { it = "Oh cielo! Se quel che c'è scritto su questo biglietto è vero, allora Abercrombie ha fatto qualcosa di... indicibile.\n\nFaresti meglio a riportare il biglietto tradotto a Ello.\n\nE fallo in fretta, perché temo che una sciagura stia già avanzando pesante verso il nostro paese...", enHash = "84d5b087", vanilla = true },
        objectives = { it = "Porta la Translated Letter a Lord Ello Ebonlocke.", enHash = "08df641b", vanilla = true },
        progress = { it = "Ah, il biglietto è tradotto? Ti prego, fammelo vedere...", enHash = "c1d31916", vanilla = true },
        reward = { it = "<Ello legge la lettera... e il suo volto si fa bianco. Poi ti guarda...>\n\nAnche se l'aiuto che hai dato ad Abercrombie può essere nato dalla gentilezza, quel che hai fatto ha condannato il nostro paese.\n\n<Ello si perde nei suoi pensieri...>", enHash = "a6d0a7b9", vanilla = true },
    },
    [253] = {
        title = { it = "La sposa dell'Embalmer", enHash = "f831f807", vanilla = true },
        text = { it = "L'Embalmer è un nome che ricorre in una delle nostre storie per bambini. Era un alchimista gentile, impazzito per la morte della moglie, Eliza. Per riportarla in vita usò la magia oscura e mise il proprio cuore nel petto della sposa morta.\n\nQuesto fece rivivere Eliza... ma la maledisse con una fame di carne umana, e costrinse l'Embalmer a tenerla sepolta.\n\nIl suo cuore è il suo potere. Trova la tomba della moglie, recupera il cuore e portamelo mentre ancora batte. Fa' questo e il suo potere sarà spezzato.", enHash = "6828359c", vanilla = true },
        objectives = { it = "Trova la tomba di Eliza. Recupera da lei l'Embalmer's Heart, poi torna da Ello Ebonlocke.", enHash = "c09dec82", vanilla = true },
        progress = { it = "L'hai già trovata la tomba di Eliza? Ce l'hai il cuore dell'Embalmer?", enHash = "dbc6add3", vanilla = true },
        reward = { it = "Ce l'hai fatta! La magia dentro il suo cuore reggerà contro il male dell'Embalmer, e sarà un'egida potente sul paese di Darkshire.\n\nHai fatto una grande cosa per la nostra gente, $N. Il tuo nome resterà per sempre nei nostri annali.", enHash = "e0474a36", vanilla = true },
    },
    [254] = {
        title = { it = "Scavando nella terra", enHash = "c414aef4", vanilla = true },
        reward = { it = "Scavi nella terra smossa sopra la tomba... e trovi i resti di una bara.\n\nDentro la bara senti il vibrare di dita adunche che grattano e il digrignare di denti marci...\n\nVuoi aprire la bara e recuperare il cuore dell'Embalmer?", enHash = "a6aebc2a", vanilla = true },
    },
    [255] = {
        title = { it = "Mercenari", enHash = "98fe4c14", vanilla = true },
        text = { it = "Due mesi solo per sentirsi dire da Ironforge che ci concederanno una manciata di soldati per la nostra difesa, e altri due mesi prima che arrivino! Già è grave che il nostro villaggio resti senza protezione, ma anche lo scavo e la diga... la diga! sono esposti agli attacchi.\n\nNon ho scelta, a quanto pare. Mi serviranno braccia a pagamento.\n\nE tu che ne dici? Hai l'aria di fare al caso mio, $C. Un gruppo di ogre si è accampato a nord-est del lago. Forse potresti reclutare qualcun altro e aiutarci a togliere questa minaccia dal villaggio.", enHash = "0f538871", vanilla = true },
        objectives = { it = "Magistrate Bluntnose di Thelsamar ti ha assunto per uccidere 4 Mo'grosh Ogre, 4 Mo'grosh Brute e 4 Mo'grosh Enforcer.", enHash = "b56f4be0", vanilla = true },
        progress = { it = "Hai avuto fortuna?", enHash = "b333ad2c", vanilla = true },
        reward = { it = "Ah, questa sì che è un'ottima notizia! Il tuo impegno è molto apprezzato da me e dalla gente di Thelsamar. E meglio ancora: se riusciamo a risolvere il problema degli ogre, potremo spostare l'attenzione su quei trogg maledetti dalla Luce.", enHash = "3e33ad6f", vanilla = true },
    },
    [256] = {
        title = { it = "WANTED: Chok'sul", enHash = "88383259", vanilla = true },
        text = { it = "Per ordine del magistrato di Thelsamar:\n\nChok'sul, l'ogre ritenuto capo e coordinatore degli attacchi contro il villaggio di Thelsamar, la Stonewrought Dam e il sito di scavo, è ricercato morto con qualunque mezzo necessario.\n\nSarà corrisposto un compenso in denaro quando al magistrato verrà portata la prova della morte di Chok'sul.\n\nChok'sul è stato visto l'ultima volta all'accampamento degli ogre, nella parte nord-orientale del Loch Modan.", enHash = "51047f28", vanilla = true },
        objectives = { it = "Uccidi Chok'sul e porta la sua testa a Magistrate Bluntnose, a Thelsamar.", enHash = "3af375c1", vanilla = true },
        progress = { it = "Sì? C'è qualcosa che posso fare per te?", enHash = "ac0d5c75", vanilla = true },
        reward = { it = "Bleah! Cos'è quella cosa? E perché mai l'hai portata...\n\nPerbacco...! Ma davvero? Be', che la Luce mi fulmini, quella è la testa di quel maledetto ogre? Questa sì che è una bella presa, allora! Tieni, la tua ricompensa e i ringraziamenti miei e della gente di Thelsamar.", enHash = "2357b4d8", vanilla = true },
    },
    [257] = {
        title = { it = "La vanteria di un cacciatore", enHash = "0a9f4dff", vanilla = true },
        text = { it = "Credi di poter competere con Daryl the Bold, eh? Direi proprio di no! Certo, sei più che $Gbenvenuto:benvenuta; a provarci. Ecco una sfida che dovrebbe essere al di sopra delle tue capacità, quindi non prendertela troppo se non riesci ad affrontarla.\n\nUno stormo di avvoltoi ha fatto il nido qui nel Loch Modan. Perché non provi ad abbatterne qualcuno? Facciamo così: se superi la mia sfida in quindici minuti, ti do il mio arco o il mio fucile.\n\n<Ti squadra con aria sprezzante.>\n\nA quanto pare non hai molto da perdere, comunque.", enHash = "167cde14", vanilla = true },
        objectives = { it = "Uccidi 6 Mountain Buzzard e torna da Daryl the Youngling, al Farstrider Lodge, entro 15 minuti.", enHash = "f221fa28", vanilla = true },
        progress = { it = "Niente da fare? Non prendertela troppo, $N...\n\nNon tutti possono essere me.", enHash = "940c4b41", vanilla = true },
        reward = { it = "Cosa? Ce l'hai fatta?\n\nDammi retta, $Nama, non montarti la testa. Voglio dire, qualunque ragazzino senza barba con un arco avrebbe potuto uccidere esemplari... così piccoli. E spero che uccidere gli avvoltoi non ti piaccia troppo, eh? Non vorremmo che si estinguessero.\n\nBe', ehm... Che non si dica mai che Daryl the Bold non ha mantenuto la parola.", enHash = "d8b2a42d", vanilla = true },
    },
    [258] = {
        title = { it = "La sfida di un cacciatore", enHash = "9f23564d", vanilla = true },
        text = { it = "$Nath, giusto? Vedo che scoppi d'orgoglio per aver superato la prima prova, eh? Come ti ho già detto, non è una grande impresa.\n\nDovresti provare con la caccia al cinghiale. Credimi, non è una caccia al cinghiale della Coldridge Valley, quindi faresti bene a stare in guardia. Questa volta ti do solo dodici minuti.\n\nNon prendertela se fallisci. Ti darei perfino la camicia che ho addosso, se ci riuscissi!\n\nTe l'ho mai raccontata la storia di come mi sono fatto la mia famosa cicatrice? No? Fu due anni fa...", enHash = "773cb245", vanilla = true },
        objectives = { it = "Uccidi 5 Elder Mountain Boar e torna da Daryl the Youngling, al Farstrider Lodge, entro 12 minuti.", enHash = "355dcb00", vanilla = true },
        progress = { it = "È naturale compiangersi un po' quando ti mette in ombra qualcuno così nuovo a questo mondo. Non prendertela, $Nah.\n\nMmh? Ho sbagliato il tuo nome?", enHash = "bcd2e64d", vanilla = true },
        reward = { it = "Sembri un po' $Gmalconcio:malconcia;. Senza dubbio i cinghiali ti hanno dato del filo da torcere, eh? $GTranquillo:Tranquilla;, sarò discreto sulla tua fatica: immagino quanto debba essere dura per te senza le accuse delle malelingue.\n\nOh! Sei $Griuscito:riuscita; a uccidere i cinghiali? Io... be', cioè... voglio dire, non sono sorpreso! Qualunque bambino avrebbe potuto... scommessa?\n\nQuale scommessa?", enHash = "68adb808", vanilla = true },
    },
    [261] = {
        title = { it = "Lungo il sentiero scarlatto", enHash = "3e70c398", vanilla = true },
        text = { it = "Sarò franco. Siamo in guerra con il Flagello. È un male che corrompe la nostra gente e infetta la nostra terra. Deve essere fermato prima che ci travolga e trascini il nostro mondo nell'ombra. Noi della Crociata Scarlatta abbiamo giurato di combattere il Flagello anima e corpo.\n\nSe sei con noi, allora fatti coraggio e dimostra la tua lealtà — distruggi gli Undead Ravager di Desolace, nella Valley of Bones, a sud.\n\nFallo, e la Crociata ti accoglierà a braccia aperte.", enHash = "654efee1", vanilla = true },
        objectives = { it = "Distruggi 30 Undead Ravager, poi torna da Brother Anton, a Nijel's Point.", enHash = "2e428659", vanilla = true },
        progress = { it = "Il Flagello diventa più potente a ogni giorno che passa. Se desideri davvero fermarne l'avanzata, allora dimostramelo.", enHash = "1257b927", vanilla = true },
        reward = { it = "Hai dimostrato la tua determinazione, e la Crociata Scarlatta ti elogia.\n\nSe non ti tiri indietro davanti a un giusto massacro, allora forse il tuo cammino è insieme a noi...", enHash = "70b3105a", vanilla = true },
    },
    [262] = {
        title = { it = "La Shadowy Figure", enHash = "c27bf91a", vanilla = true },
        text = { it = "Devo sapere chi era quello che sgattaiolava nell'ombra la notte in cui la mia famiglia è stata uccisa!\n\nTi prego, $N, hai dimostrato di essere $Gpieno:piena; di risorse. Ti prego, trova quella figura in ombra. Devo sapere che segreti nasconde!\n\nNon ho indizi che tu non conosca già, ma tieni — prendi il libro che hai trovato alla mia fattoria. Forse qualcuno in paese può collegare questo libro al suo proprietario.", enHash = "e72e762f", vanilla = true },
        objectives = { it = "Prendi il libro che hai trovato alla fattoria di Sven e mostralo alla gente di Darkshire.", enHash = "cbddbcb8", vanilla = true },
        progress = { it = "Se hai qualcosa che appartiene alla figura in ombra che cerchi, fammela vedere. Forse riesco a indovinare qualcosa sul suo proprietario.", enHash = "27f25074", vanilla = true },
        reward = { it = "Hmm... Qualcuno ha maneggiato questo libro di recente, qualcuno mosso dalla vendetta. Ma le impressioni rimaste sopra, almeno quelle del proprietario originale, sono deboli.\n\nQuello che posso dirti, però, è che il proprietario originale di questo libro non è di Darkshire.", enHash = "448723ac", vanilla = true },
    },
    [263] = {
        title = { it = "In difesa delle terre del re", enHash = "87756ca8", vanilla = true },
        text = { it = "I Mountaineer mi dicono che sei piuttosto $Gcoraggioso:coraggiosa; e capace, $N. Ci serve $Gun:una; $R come te da queste parti. Il problema dei trogg non migliora di certo. Le riserve sono state chiamate al fronte e qui siamo rimasti soli. Ma ora che abbiamo qui $Gun:una; $C con esperienza, vediamo cosa sai fare.\n\nVa' fuori e uccidi 10 Stonesplinter Shaman e 10 Stonesplinter Bonesnapper. Vediamo se sei all'altezza della tua fama, Ammazzatrogg.", enHash = "90026b9a", vanilla = true },
        objectives = { it = "Mountaineer Wallbang, nella torre di guardia a sud, vuole che tu uccida 10 Stonesplinter Shaman e 10 Stonesplinter Bonesnapper.", enHash = "0a354148", vanilla = true },
        progress = { it = "Già di ritorno? Nel caso non fossi stato chiaro, ci serve che tu uccida 10 Stonesplinter Shaman e 10 Stonesplinter Bonesnapper, $N. E adesso vai a prenderli, Ammazzatrogg!", enHash = "b40f8466", vanilla = true },
        reward = { it = "L'ho capito nell'istante in cui ti ho visto, $N: avresti reso fiera Ironforge. Hai servito bene King Magni. Ora che ti sei $Gdimostrato:dimostrata; un aiuto così leale per il Regno, forse dovresti parlare con il capitano e vedere se ti affida un incarico più alto.\n\nTi saluto, $N.", enHash = "58ba9192", vanilla = true },
    },
    [264] = {
        title = { it = "Finché morte non ci separi", enHash = "d37b434e", vanilla = true },
        text = { it = "Lurido verme! Mi lascia per la sua maledetta crociata. Perché \"la Luce è la cosa più importante che abbiamo contro le minacce dei non morti\".\n\nE i suoi figli, allora?! E IO?! Notte dopo notte sono rimasta seduta ad aspettarlo con pazienza... sempre seconda al suo dannato dovere!\n\nEbbene, guarda cosa ti porta la \"giustizia\", $N! Lui è morto e io porto addosso proprio quello che cercava di fermare!\n\nPrendi questo ciarpame e mettilo sulla sua tomba al Sepulcher. Non voglio più avere niente a che fare con quello... né con lui!", enHash = "816a29e4", vanilla = true },
        objectives = { it = "Metti Clarice's Pendant sulla Yuriv's Tomb, a Silverpine.", enHash = "44b05a54", vanilla = true },
        progress = { it = "La pietra è fredda al tatto, ma è evidente che è stata maltrattata. Il terreno intorno è cosparso di rifiuti; tacche e solchi decorano il rilievo sopra la bara; e la vegetazione attorno alla tomba ha cominciato a ricoprire il luogo.\n\nNessuno si cura di chi è sepolto qui, tanto meno delle vittime della piaga.", enHash = "2ca56bbd", vanilla = true },
        reward = { it = "Posi il pendente senza valore sulla tomba, e la gemma incastonata sembra spegnersi visibilmente.\n\nMentre ti alzi per andartene, abbassi lo sguardo sul pendente; giace senza vita sopra le mani del rilievo scolpito in cima alla bara. I tuoi pensieri vengono interrotti da una brezza forte e fredda che passa sopra il Sepulcher. Per un attimo tutto intorno a te è silenzioso.", enHash = "a48549d7", vanilla = true },
    },
    [265] = {
        title = { it = "La ricerca nell'ombra continua", enHash = "6879a2ea", vanilla = true },
        text = { it = "Ecco il tuo libro, $N, e ti auguro fortuna con la tua ricerca. Se chiedi ad altri in paese, forse possono darti altri indizi.\n\nE te ne do ancora uno: anche se l'autore di questo libro è un forestiero per Darkshire, il libro è stato comprato qui.", enHash = "2b509aee", vanilla = true },
        objectives = { it = "Vedi se altri in paese hanno indizi sulla figura in ombra.", enHash = "f41de840", vanilla = true },
        progress = { it = "Certe volte vendo libri bianchi a studiosi e maghi, o a chiunque voglia tenere un diario.\n\nRicordo bene tutti quelli a cui ho venduto un libro negli ultimi mesi...", enHash = "ed34d6c6", vanilla = true },
        reward = { it = "Ah, sì. Questo libro l'ho venduto un mese fa a un tipo losco. Non mi ha detto il suo nome, ma era un tipo nervoso e agitato, che si guardava sempre alle spalle.\n\nSpero che ti sia d'aiuto...", enHash = "8ef23a49", vanilla = true },
    },
    [266] = {
        title = { it = "Chiedi alla locanda", enHash = "d5e0d95a", vanilla = true },
        text = { it = "Ecco il tuo libro, e buona fortuna con le tue domande.\n\nPotresti allargare la ricerca alla locanda. Se la persona che cerchi ha passato del tempo in paese, è probabile che qualcuno l'abbia vista lì.", enHash = "357e75e8", vanilla = true },
        objectives = { it = "Cerca indizi sulla figura in ombra alla locanda.", enHash = "321c4046", vanilla = true },
        progress = { it = "La Scarlet Raven non ha più il giro d'affari di una volta, ma qualche viaggiatore di passaggio capita ancora.\n\nSe sai descrivermi la persona che cerchi, magari me la ricordo.", enHash = "3433df43", vanilla = true },
        reward = { it = "Oh sì, questo libro me lo ricordo. Il suo proprietario ha preso una stanza per qualche giorno, e passava le notti al bancone a scrivere.\n\nHa lasciato il paese in fretta, borbottando di essere braccato da... qualcosa. L'ultima volta che l'ho visto andava a ovest, fuori dal paese, in cerca di un nuovo posto dove nascondersi.\n\nIl primo posto che trova a ovest è Raven Hill...", enHash = "1a81e211", vanilla = true },
    },
    [267] = {
        title = { it = "La minaccia dei trogg", enHash = "3615d218", vanilla = true },
        text = { it = "$C, forse saprai già della minaccia dei trogg che incombe sulle terre dei nani. Con l'Ironforge Reserve richiamata al fronte dell'Alleanza, ci resta una frazione delle forze di difesa necessarie a tenere sicure queste terre. Il mio reggimento è assegnato alla guardia del cancello qui, e non possiamo lasciare il posto per paura di un'invasione.\n\nMa serve mettere un po' di pressione su quei maledetti trogg che si aggirano tra le colline. Se te la senti, scatena un assalto contro i trogg. Riportami 8 Trogg Stone Teeth come prova.", enHash = "52d4e6ab", vanilla = true },
        objectives = { it = "Porta 8 Trogg Stone Teeth a Captain Rugelfuss, nella torre di guardia a sud.", enHash = "ad8528d1", vanilla = true },
        progress = { it = "Hai 8 Trogg Stone Teeth da mostrarmi? Se no, c'è ancora del lavoro da fare, $N.", enHash = "1483b238", vanilla = true },
        reward = { it = "Sono davvero colpito, $N. Hai reso un grande favore alla razza dei nani difendendo le nostre terre. King Magni Bronzebeard in persona ne sarebbe fiero!", enHash = "62ffc472", vanilla = true },
    },
    [268] = {
        title = { it = "Torna da Sven", enHash = "69716de1", vanilla = true },
        text = { it = "Il libro che hai trovato era solo a metà. Ho dovuto lasciarlo alla fattoria di Sven quando sono fuggito là...\n\nTieni. Porta a Sven il mio diario completo. Racconta molto meglio quel che è successo alla sua fattoria.\n\nAnche se in queste settimane questo diario è stata la mia unica compagnia, se cederlo mi evita di affrontare Sven e la sua ira, lo faccio volentieri!", enHash = "8d32079a", vanilla = true },
        objectives = { it = "Torna da Sven con il diario completo di Jitters.", enHash = "6c79d431", vanilla = true },
        progress = { it = "Hai scoperto chi era la Shadowy Figure?", enHash = "62778455", vanilla = true },
        reward = { it = "Questo diario mi spiega molte cose, e mi mette sulla strada contro i Dark Rider! Ho visto questi cavalieri a Duskwood, e li ho visti parlare con il mago Morbent Fel, al Forlorn Rowe.", enHash = "4f1d8150", vanilla = true },
    },
    [269] = {
        title = { it = "In cerca di saggezza", enHash = "f5f5c837", vanilla = true },
        text = { it = "Va' alla città di Stormwind e parla con Bishop Farthing, alla Cathedral of Light. Dagli il diario di Jitters e digli che intendi affrontare Morbent Fel.\n\nAnche se Stormwind ha abbandonato Darkshire, Farthing è un'anima buona e molto saggia. Può aiutarti nella tua impresa per salvarci.\n\nLa tua missione è pericolosa, ma sbrigati, $N. Con ogni ora che passa, le ombre di Duskwood si fanno più fitte.", enHash = "73738a9c", vanilla = true },
        objectives = { it = "Consegna Jitters' Completed Journal a Bishop Farthing, a Stormwind.", enHash = "e8466dfc", vanilla = true },
        progress = { it = "Riposati, $Gfratello:sorella;. Vedo che hai viaggiato a lungo, e che porti un peso gravoso. Sai dirmi cos'è che getta quell'ombra scura su di te?", enHash = { "d2d62c2c", "dbd87920" }, vanilla = true },
        reward = { it = "<Dopo aver letto il diario e aver ascoltato le tue intenzioni...>\n\nUna corruzione maligna ha messo radici nella già tormentata Duskwood. Ringrazio la Luce che ad affrontarla ci sia $Gun eroe:un'eroina; come te.\n\nMa prima devi prepararti alla prova che ti aspetta... perché il negromante Morbent Fel è immensamente potente, e si è cinto di incantesimi oscuri che lo proteggono dagli attacchi fisici. Se vuoi sconfiggerlo, ti servirà un'arma che quelle protezioni non possono fermare.", enHash = "f4457d6d", vanilla = true },
    },
    [270] = {
        title = { it = "La flotta maledetta", enHash = "23d76485", vanilla = true },
        text = { it = "Anni fa la Third Fleet di Kul'Tiras affondò lungo le coste delle Wetlands, una distesa di paludi a nord del regno nanico di Ironforge. Su una delle navi c'era un carico di Lightforge Iron.\n\nQuesto metallo è prezioso per noi, perché gli oggetti forgiati con esso colpiscono con la verità sacra. Se devi affrontare Morbent Fel, ti servirà un'arma così.\n\nVa' a Menethil Harbor e parla con il mio collega nano Glorin Steelbrow. Se quel metallo perduto si può trovare, lui saprà dove cercare.", enHash = "573018bb", vanilla = true },
        objectives = { it = "Va' a Menethil Harbor, nelle Wetlands, e parla con Glorin Steelbrow.", enHash = "b71b9494", vanilla = true },
        reward = { it = "Il Lightforge Iron è un metallo prezioso, ma pare che la tua impresa sia terribile. Hai fatto molta strada, $GFratello:Sorella;. Con un po' di fortuna, potresti trovare proprio quel che cerchi!\n\nE se il metallo lo trovi, so chi può farne un'arma contro questo negromante di cui parli, a Duskwood.", enHash = { "9fea661f", "6b7496a1" }, vanilla = true },
    },
    [271] = {
        title = { it = "La vendetta di Vyrin", enHash = "9513c5ea", vanilla = true },
        text = { it = "Non è che ti interesserebbe una piccola vendetta per Sua Baldanza? Daryl un po' di abilità ce l'ha, mi duole ammetterlo.\n\nUn anno fa un grosso orso era il bersaglio del Farstrider Lodge, ma nessuno dei cacciatori ebbe fortuna con lui. Così Daryl pensò di provarci. Tutto ciò che ricavò dai suoi sforzi fu quella brutta cicatrice sopra l'occhio.\n\nUccidi l'orso, e sono sicura che perfino Daryl resterebbe senza parole, per una volta.\n\nL'orso, Ol' Sooty, lo trovi intorno alla sua tana, sulle colline sopra Thelsamar.", enHash = "ebafd09a", vanilla = true },
        objectives = { it = "Uccidi Ol' Sooty e poi mostra il tuo trofeo a Daryl the Youngling, al Farstrider Lodge.", enHash = "ceb24f2d", vanilla = true },
        progress = { it = "Ah, $N! Già di ritorno? Senza dubbio sei $Gstato:stata; di nuovo a caccia. Non preoccuparti se hai avuto qualche battuta d'arresto: alla lunga ti renderà migliore!\n\n...Peggio di così non potresti comunque diventare...", enHash = "51815a84", vanilla = true },
        reward = { it = "Ehm... cos'è questa? Una testa d'orso, a quanto pare.\n\n<Si passa un dito lungo la cicatrice, senza accorgersene.>\n\nBe', quella che ti sei $Gportato:portata; dietro è una preda piuttosto interessante. Non può essere quell'orso di allora...\n\n<Si interrompe e comincia a tremare visibilmente.>\n\nOh, portala via, portala via! Togli quella cosa macabra di qui!", enHash = "33f71235", vanilla = true },
    },
    [272] = {
        title = { it = "Prova del leone marino", enHash = "c3b862bb", vanilla = true },
        text = { it = "Per la seconda prova ti serviranno le due metà che formano il Pendant of the Sea Lion. Una metà trae potere dall'agilità dell'aspetto del leone marino, che scivola nell'acqua; l'altra trae potere dall'incredibile resistenza dell'aspetto del leone marino. I druidi attingono in egual misura a entrambe queste qualità per incarnare l'aspetto della loro Aquatic Form.\n\nParla con gli abitanti di Moonglade per scoprire dove potrebbero trovarsi le due parti, e portale entrambe qui per unirle. Una volta formato il pendente, portalo a Dendrite Starblaze.", enHash = "5730c00d", vanilla = true },
        objectives = { it = "Trova l'Half Pendant of Aquatic Agility e l'Half Pendant of Aquatic Endurance. Parla con gli abitanti di Moonglade per avere indizi su dove possano trovarsi questi oggetti.\n\nForma il Pendant of the Sea Lion unendo le due metà del pendente. Per farlo devi trovarti vicino allo Shrine of Remulos.\n\nPorta il pendente completo a Dendrite Starblaze, nel villaggio di Nighthaven, a Moonglade.", enHash = "e8106a8e", vanilla = true },
        progress = { it = "Hai formato il pendente da farmi esaminare, $N? Se ti serve aiuto per trovare le parti, prova a chiedere informazioni alla gente del posto. Non solo troverai ciò che cerchi, ma avrai anche un motivo per esplorare questa radura meravigliosa e sacra.", enHash = "6d3f31a0", vanilla = true },
        reward = { it = "Hai completato la Prova del Leone Marino, $N — congratulazioni.\n\nOgni passo per ottenere il pendente dimostra che agilità e resistenza sono entrambe necessarie per agire in armonia con ciò che desideri fare sott'acqua. Nessuna delle due può esistere senza l'altra, ed entrambe sono impossibili senza la tua disponibilità a fare tuo l'aspetto del leone marino.\n\nRicorda bene queste lezioni: ti serviranno quando avrai ottenuto la tua Aquatic Form.", enHash = "ccb078b3", vanilla = true },
    },
    [273] = {
        title = { it = "Rifornire lo scavo", enHash = "730e233f", vanilla = true },
        text = { it = "Non è comunque troppo tardi: puoi andare a cercare Huldar. Non può essersi allontanato molto; per quanto siano forti, Miran e Saean non possono andare tanto veloci carichi di quei barili.\n\nStanno prendendo la via normale per il sito: escono dal villaggio verso sud e seguono la curva del Loch.\n\nNon dovresti avere problemi a trovarli, a meno che non siano già arrivati.", enHash = "80efe82e", vanilla = true },
        objectives = { it = "Parla con Huldar.", enHash = "b488a8ec", vanilla = true },
        reward = { it = "Hmph, ci vuole ben più di un'imboscata dei Dark Iron per fermare le consegne!\n\nMa Saean... non avrei mai sospettato che fosse uno dei loro simpatizzanti. Lavoriamo con lui da quasi un anno... forse non ho colto i segnali.\n\nBe', ci penserò più tardi.", enHash = "f8d0b144", vanilla = true },
    },
    [274] = {
        title = { it = "Un'ombra minacciosa", enHash = "88b632d7", vanilla = true },
        text = { it = "Questa non è una normale polvere da mina. Guarda i minuscoli cristalli d'argento. E quell'odore inconfondibile! Be', è chiaro come il sole che questo è Seaforium Powder. Il Seaforium di per sé è innocuo. Ma una volta bagnato potrebbe far saltare Ironforge fuori dalla montagna.\n\nLa reazione chimica si può disinnescare mescolando quattro componenti: Lurker Venom, un Mo'grosh Crystal frantumato, una Crocolisk Tear e questo Disarming Colloid. E ora avvisa Hinderweir prima che sia troppo tardi!", enHash = "d3660734", vanilla = true },
        objectives = { it = "Ashlan Stonesmirk vuole che tu torni da Chief Engineer Hinderweir e lo informi della nuova scoperta.", enHash = "bb11e85f", vanilla = true },
        progress = { it = "Cos'è che mi porti da parte di Ashlan?", enHash = "b39591b4", vanilla = true },
        reward = { it = "Un Disarming Colloid? Per il Seaforium? Oh, santo cielo!", enHash = "67e214ed", vanilla = true },
    },
    [275] = {
        title = { it = "Pustole sulla terra", enHash = "f29cf9a1", vanilla = true },
        text = { it = "Non so perché, ma nelle Wetlands cresce un'infezione. I Fen Creeper si sono levati. Sono pustole malate e febbricitanti sulla terra, e perché la febbre passi devono essere eliminati e lasciati tornare nelle paludi.\n\nI Fen Creeper si trascinano tra i corsi d'acqua delle Wetlands.", enHash = "063b797f", vanilla = true },
        objectives = { it = "Uccidi 12 Fen Creeper, poi torna da Rethiel the Greenwarden, nelle Wetlands.", enHash = "ef7aef11", vanilla = true },
        progress = { it = "Le Wetlands piangono ancora, e i Fen Creeper ancora infuriano. Torna da me quando il tuo compito sarà finito.", enHash = "b3253a22", vanilla = true },
        reward = { it = "Questa terra è placata dai tuoi sforzi, e per questo ti concederò un dono.", enHash = "01e3974f", vanilla = true },
    },
    [276] = {
        title = { it = "Zampe che calpestano", enHash = "d45b6691", vanilla = true },
        text = { it = "I Mosshide Gnoll hanno vissuto in pace nelle Wetlands per molti anni, ma ora crescono di numero. Le loro zampe calpestano i cespugli e i fiori della palude, e le loro asce immonde tagliano troppo legno per alimentare i fuochi.\n\nNon sono più in equilibrio con la terra. Perché le Wetlands sopravvivano, gli gnoll vanno ridotti.\n\nUccidi 15 Mosshide Gnoll e 10 Mosshide Mongrel. Dai loro la caccia a sud, vicino alla porta nanica di Algaz. Quando l'avrai fatto, torna da me.", enHash = "a37c1320", vanilla = true },
        objectives = { it = "Uccidi 15 Mosshide Gnoll e 10 Mosshide Mongrel, poi torna da Rethiel the Greenwarden, nelle Wetlands.", enHash = "be5ab4d8", vanilla = true },
        progress = { it = "Il tuo compito ti aspetta ancora, giovane $C.", enHash = "8b93f277", vanilla = true },
        reward = { it = "Riducendo il numero degli gnoll, ti sei $Gpreso:presa; cura della salute delle Wetlands. Anche se in passato la mia fiducia nella tua gente è stata messa a dura prova, $R, può ancora essere ristabilita.", enHash = "a6a5a779", vanilla = true },
    },
    [277] = {
        title = { it = "Il tabù del fuoco", enHash = "839b45cb", vanilla = true },
        text = { it = "I Mosshide tagliano gli alberi delle Wetlands, e usano la carne degli alberi per scaldarsi con il fuoco. Non sopporterò più questo dolore!\n\nPriva i Mosshide dei loro rozzi acciarini, gli arnesi con cui accendono il fuoco. Gli acciarini li portano tutti i Mosshide, tranne i Mosshide Gnoll e i Mosshide Mongrel più piccoli.", enHash = "bbe59ae4", vanilla = true },
        objectives = { it = "Porta 9 Crude Flint a Rethiel the Greenwarden.", enHash = "7e7459d8", vanilla = true },
        progress = { it = "Hai gli arnesi del fuoco degli gnoll?", enHash = "bf7a1f78", vanilla = true },
        reward = { it = "... grazie. Frantumerò questi acciarini e li getterò in mare, perché non siano mai più usati per bruciare legno vivo.", enHash = "0a342d99", vanilla = true },
    },
    [278] = {
        title = { it = "Un'ombra minacciosa", enHash = "88b632d7", vanilla = true },
        text = { it = "Comincia subito a raccogliere i materiali per il disinnesco, $N. Il Lurker Venom lo trovi sui ragni che vivono nel Loch Modan. Anche le Crocolisk Tear si trovano qui nel Loch. Ma un Mo'grosh Crystal sarà molto difficile da procurare. Gli ogre a nord-est li estraggono, ma i cristalli sono una merce molto rara.\n\nDobbiamo essere pronti a disinnescare un attacco dei Dark Iron! Torna da me quando avrai raccolto gli oggetti che servono, e preparerò la miscela.", enHash = "dfded595", vanilla = true },
        objectives = { it = "Chief Engineer Hinderweir vuole che tu raccolga Lurker Venom, un Mo'grosh Crystal e una Crocolisk Tear.", enHash = "7989a6bb", vanilla = true },
        progress = { it = "Hai gli oggetti che servono? Il tempo stringe!!", enHash = "6b01aa94", vanilla = true },
        reward = { it = "Giusto in tempo, $N!", enHash = "aefa916f", vanilla = true },
    },
    [279] = {
        title = { it = "Artigli dal profondo", enHash = "490cf5c5", vanilla = true },
        text = { it = "I murloc stanno strisciando fuori dalle acque profonde e costruiscono i loro villaggi sulla costa. Danno fastidio ai nostri pescatori e ai nostri mercanti, e vanno fermati.\n\nUno di questi murloc, Gobbler, si aggira insieme agli altri Bluegill Murloc e tormenta i mercanti lungo la strada, per poi ritirarsi sempre al sicuro nelle capanne dei murloc qui vicino. I nostri mercanti sono in pericolo, e pagheremo per metterli al sicuro.\n\nGobbler si aggira nell'insenatura del fiume a nord di qui. Trovalo, uccidi i suoi simili e portami la sua testa.", enHash = "4e85770d", vanilla = true },
        objectives = { it = "Uccidi 12 Bluegill Murloc.\n\nUccidi Gobbler e prendi la sua testa.\n\nPorta Gobbler's Head a Karl Boran, a Menethil Harbor.", enHash = "6c1fae91", vanilla = true },
        progress = { it = "I nostri mercanti non saranno al sicuro finché non ci saremo liberati di Gobbler e di quei murloc.", enHash = "ae825cbe", vanilla = true },
        reward = { it = "Ah, ben fatto, $N.\n\nAccetta questo come pagamento per aver adempiuto al tuo contratto con i Merchant Marines.", enHash = "8179995c", vanilla = true },
    },
    [280] = {
        title = { it = "Un'ombra minacciosa", enHash = "88b632d7", vanilla = true },
        text = { it = "Oggi, poco fa, ho visto dei Dark Iron Insurgent nuotare verso la diga con un grosso barilotto. Non c'era nessun Mountaineer a fermarli! Temo che abbiano piazzato il Seaforium alla base della diga, e potrebbe saltare da un momento all'altro! Lascia che unisca tutti questi ingredienti nella Disarming Mixture. Ecco fatto.\n\nOra ho bisogno che tu prenda questa miscela e la versi nel barilotto prima che sia troppo tardi! Presto!", enHash = "64ed7058", vanilla = true },
        objectives = { it = "Chief Engineer Hinderweir vuole che tu scenda a nuoto fino alla base della diga, trovi il barilotto di polvere e vi versi la Disarming Mixture per impedire l'esplosione.", enHash = "9c22d57a", vanilla = true },
        progress = { it = "Il coperchio del barilotto si svita lentamente.", enHash = "2798c3f2", vanilla = true },
        reward = { it = "Il barilotto frigge appena mentre la Disarming Mixture si deposita.", enHash = "94d5a8bd", vanilla = true },
    },
    [281] = {
        title = { it = "Recuperare la merce", enHash = "d5e2e5cf", vanilla = true },
        text = { it = "Non molto tempo fa un mercantile, la Blind Princess, è stato assalito dai murloc. Anche se la nave se l'è cavata intatta, gran parte del carico è stata trascinata in mare da quelle creature, compresa una statuetta di Terenas Menethil di grande valore. Vogliamo che quella statuetta venga recuperata.\n\nCerca casse, barili e altre tracce del carico perduto nelle capanne dei murloc sulla costa. Trova la Menethil Statuette e riportamela.", enHash = "d3282489", vanilla = true },
        objectives = { it = "Cerca nelle casse e nei barili degli accampamenti murloc sulla costa.", enHash = "99fed310", vanilla = true },
        reward = { it = "Questa cassa è coperta di graffi di artigli e di segni lasciati dall'acqua. Forzandola si scopre paglia fradicia e marcia, come se dentro fosse stato riposto qualcosa di valore. Frughi tra la paglia...\n\n...e trovi una bracciata di bottiglie rosse.", enHash = "7a9dd9c0", vanilla = true },
    },
    [282] = {
        title = { it = "Le osservazioni di Senir", enHash = "0abba316", vanilla = true },
        text = { it = "Pensavo di mandare il mio apprendista da mio fratello Senir con il rapporto, ma mi sentirei molto più tranquillo se fosse in mani più... affidabili. Sempre che la cosa non ti dispiaccia, s'intende.\n\nMmh... per arrivare a Kharanos dovrai passare dalla galleria.\n\nParla con Mountaineer Thalos prima di attraversarla. Ormai è completamente infestata dai trogg.\n\nSegui la strada fino ad Anvilmar, poi continua verso est fino alla galleria: Thalos è di guardia lì vicino.", enHash = "140caf66", vanilla = true },
        objectives = { it = "Parla con Mountaineer Thalos.", enHash = "d7688404", vanilla = true },
        progress = { it = "Salve! Fai attenzione, $N: la galleria per il Dun Morogh è infestata dai trogg e non è sicura.\n\nSe non hai affari urgenti nel Dun Morogh, devo chiederti di restare ad Anvilmar finché la galleria non sarà più sicura.", enHash = "e132262b", vanilla = true },
        reward = { it = "Mmh, be', se Whitebeard ti manda nel Dun Morogh per affari importanti, non posso certo fermarti, no?\n\nAlmeno lascia che ti dia qualche consiglio e qualche indicazione.", enHash = "f4166526", vanilla = true },
    },
    [283] = {
        title = { it = "Un'ombra minacciosa", enHash = "88b632d7", vanilla = true },
        text = { it = "Il barilotto frigge appena.", enHash = "5e4a4a73", vanilla = true },
        objectives = { it = "La Disarming Mixture sembra aver fatto effetto. Torna da Chief Engineer Hinderweir a riferire la buona notizia.", enHash = "2fd4c97f", vanilla = true },
        reward = { it = "Grazie mille, $N!! Hai salvato la Stonewrought Dam! Senza il tuo aiuto i terroristi Dark Iron avrebbero di certo decretato la fine di questo grande monumento. Hai reso fieri il Regno e l'Alleanza, $Gvaloroso:valorosa; $C.\n\nLa diga è di nuovo al sicuro... almeno per ora...", enHash = "f63b0f38", vanilla = true },
    },
    [284] = {
        title = { it = "La ricerca continua", enHash = "a08ed003", vanilla = true },
        text = { it = "Perlustri a fondo questo gruppo di capanne murloc e non trovi traccia della Menethil Statuette.\n\nForse una delle due capanne vicine, a nord e a nord-est, avrà altri indizi.", enHash = "d149202b", vanilla = true },
        objectives = { it = "Cerca la Menethil Statuette.", enHash = "5acdddc9", vanilla = true },
        reward = { it = "Questo barile è quasi intatto. Lo forzi...\n\n...e ti assale l'odore pungente del formaggio. È un po' bagnato, ma ancora buono!", enHash = "16f32c40", vanilla = true },
    },
    [285] = {
        title = { it = "Cerca in altre capanne", enHash = "78d6e6b0", vanilla = true },
        text = { it = "Questo gruppo di capanne murloc, dopo un'ispezione accurata, non rivela nulla.\n\n...ma sei $Gcerto:certa; che il prossimo indizio che troverai sarà quello buono.\n\nUna delle capanne a nord deve avere la Menethil Statuette!", enHash = "a802dc67", vanilla = true },
        objectives = { it = "Continua a cercare la Menethil Statuette nelle capanne murloc.", enHash = "a72c7ffa", vanilla = true },
        reward = { it = "Questo barile è mezzo sepolto tra il fango e l'erba...", enHash = "73cf05c5", vanilla = true },
    },
    [286] = {
        title = { it = "Riporta la statuetta", enHash = "84849fa2", vanilla = true },
        text = { it = "Dopo aver liberato il barile dalla melma e averlo aperto, si trova una figurina argentea avvolta in paglia fine. Raffigura un giovane paladino dai capelli lunghi con il martello sollevato.\n\nDeve essere la Menethil Statuette! Ora devi riportarla a Karl Boran, a Menethil Harbor.", enHash = "8bd25619", vanilla = true },
        objectives = { it = "Porta la Menethil Statuette a Karl Boran.", enHash = "92357868", vanilla = true },
        progress = { it = "Hai la statuetta?", enHash = "07d4eb8f", vanilla = true },
        reward = { it = "Il capitano della Blind Princess sarà sollevato di sapere che questo carico prezioso è stato recuperato. Ti sei $Gguadagnato:guadagnata; in pieno questo compenso per i servizi resi.\n\nFa piacere vedere gente affidabile come te, soprattutto in tempi difficili come questi.", enHash = "45ff56c7", vanilla = true },
    },
    [287] = {
        title = { it = "Il Frostmane Hold", enHash = "05719330", vanilla = true },
        text = { it = "Sono indietro con il mio rapporto, e il tuo aiuto mi farebbe comodo, $N. Sono appena riuscito a scoprire dove si sono rintanati i troll, ma ne ho visti così tanti che ho avuto paura di entrare.\n\nEcco cosa mi serve... Scendi nella grotta, dai un'occhiata in giro, uccidi qualcuno dei troll, poi torna qui.\n\nPrendi la strada che esce da Kharanos verso nord; quando arrivi al ponte, segui il fiume ghiacciato verso ovest fino all'Iceflow Lake. Troverai Brewnall Village sulla sponda occidentale. L'Hold è a sud-ovest del villaggio.", enHash = "e13e5739", vanilla = true },
        objectives = { it = "Esplora il Frostmane Hold e uccidi 5 Frostmane Headhunter per Senir Whitebeard, a Kharanos.", enHash = "2b4d854a", vanilla = true },
        progress = { it = "Non riesci a trovarlo? Le mie indicazioni erano chiarissime! Non abbiamo molto tempo, devi sbrigarti! Non tornare finché non avrai trovato la grotta.", enHash = "54876ed9", vanilla = true },
        reward = { it = "Ah, $N! Non pensavo che avresti avuto problemi a trovare il posto: le mie indicazioni sono eccellenti, sai...\n\nAllora lasciami finire il rapporto.\n\n<Tira fuori un foglio e ci scarabocchia sopra per un momento.>\n\nEcco! Be', ahah, questa sì che è buffa... Non è che, $N, ti dispiacerebbe farmi un ultimo favore?", enHash = "526ee0df", vanilla = true },
    },
    [288] = {
        title = { it = "La Third Fleet", enHash = "3794f826", vanilla = true },
        text = { it = "Un tempo ero Primo Ufficiale sulla Wave Mistress, nave di linea della Third Fleet di Kul Tiras. La Flotta Dannata. Dannata, perché nel suo ultimo viaggio la flotta fu attaccata dai Red Dragon. Draghi controllati dagli orchi!\n\nNon avevamo scampo contro quel fuoco di drago... e la nostra flotta fu bruciata e affondata al largo di questa costa. Sono l'unico sopravvissuto di quelle povere navi...\n\n...Oh, la testa mi martella e mi pulsa! Mi serve una bevuta fresca se devo domare questa sbornia e continuare il racconto.", enHash = "58899fc0", vanilla = true },
        objectives = { it = "Compra un Flagon of Mead per First Mate Fitzsimmons.", enHash = "7519eae4", vanilla = true },
        progress = { it = "Oh, ho una sete tremenda! Non offriresti da bere a questo povero, patetico scemo?", enHash = "e9231f3f", vanilla = true },
        reward = { it = "Ah! Questo sì che ci voleva, e scioglie la lingua. Grazie, socio!", enHash = "6f426590", vanilla = true },
    },
    [289] = {
        title = { it = "L'equipaggio maledetto", enHash = "ff7a5d80", vanilla = true },
        text = { it = "<Rinfrancato, Fitzsimmons riprende il racconto...>\n\nSono l'unico sopravvissuto della sventurata Third Fleet di Kul Tiras, naufragata al largo della costa a nord. Ma anche se sono l'unico membro della flotta che ancora respira, non sono l'unico che ancora cammina! Perché su una delle nostre navi era nascosto un tesoro grande e terribile, e il suo potere sinistro tiene le anime dei miei fratelli intrappolate negli scafi marcescenti delle navi.\n\nMa se riesci a liberare qualcuno dei miei fratelli, forse potrai spezzare la loro maledizione.", enHash = "582fe33a", vanilla = true },
        objectives = { it = "Uccidi 13 Cursed Sailor, 5 Cursed Marine e First Mate Snellig. Porta Snellig's Snuffbox a First Mate Fitzsimmons, a Menethil Harbor.", enHash = "0fb631f4", vanilla = true },
        progress = { it = "Nei miei sogni, a volte sento i gemiti dannati dei miei fratelli! Ti prego, $Gbuon signore:buona signora;, liberali dai vincoli e fa' tacere le loro grida.", enHash = { "51a773fc", "d35a3ddc" }, vanilla = true },
        reward = { it = "Ti ringrazio, $N. E anche la gratitudine dei miei fratelli maledetti va a te.", enHash = "66c09997", vanilla = true },
    },
    [290] = {
        title = { it = "Spezzare la maledizione", enHash = "c345203a", vanilla = true },
        text = { it = "Per spezzare la maledizione e liberare tutti i miei fratelli, quella... cosa... stivata sulla mia nave va recuperata e purificata! Non so cosa fosse, ma so che era custodita al sicuro nella cassaforte della nave, su cui vegliava Captain Halyndor.\n\nIl mio vecchio capitano è ancora nei miei sogni. So che cammina sulla mia nave dannata, l'Intrepid. Prendi la chiave da lui e usala per aprire la cassaforte dell'Intrepid.\n\nPoi, quando avrai la cosa maledetta, portala al sacerdote Glorin Steelbrow, in città.", enHash = "04f03a4e", vanilla = true },
        objectives = { it = "Prendi l'Intrepid Strongbox Key da Captain Halyndor.\n\nUsa la chiave per aprire l'Intrepid's Locked Strongbox.", enHash = "c75644d6", vanilla = true },
        progress = { it = "Questa cassa è chiusa saldamente a chiave.", enHash = "f2e6cb1d", vanilla = true },
        reward = { it = "La chiave è arrugginita, ma entra nella serratura alla perfezione.", enHash = "a9dea610", vanilla = true },
    },
    [291] = {
        title = { it = "I rapporti", enHash = "71daad10", vanilla = true },
        text = { it = "Eccellente! Porta il mio rapporto al Senator Barin Redstone. È un tipo burbero, quindi non farti scoraggiare dal suo umore tutt'altro che solare. Si trova a Ironforge, nella sala dove King Magni tiene corte.\n\nNon conosci la strada per Ironforge? Prendi la strada che esce da Kharanos verso nord, attraversa il ponte, poi segui la strada verso est — ci sono grandi stendardi ai lati della strada — su per il fianco della montagna.\n\nA proposito, ti spiacerebbe evitare di dire che mi hai aiutato? Non posso lasciargli credere che qui non stia lavorando sodo, capisci?", enHash = "bf32d341", vanilla = true },
        objectives = { it = "Consegna il rapporto di Senir al Senator Barin Redstone, a Ironforge.", enHash = "a4a97677", vanilla = true },
        progress = { it = "Mmh... a quanto pare le mie guardie stanno diventando meno selettive con i postulanti. Allora, cosa vuoi? Fai in fretta.", enHash = "75c2fce6", vanilla = true },
        reward = { it = "<Scorre rapidamente il rapporto.>\n\nAutorità del RE!? Magni ha perso completamente il senno! E quel maledetto Whitebeard... Ha preso l'iniziativa di testa sua, eh? Al Senato non farà affatto piacere saperlo, per niente.\n\nCome, sei ancora qui? Vai, prima che chiami le guardie!", enHash = "dab41c22", vanilla = true },
    },
    [292] = {
        title = { it = "L'Eye of Paleth", enHash = "f269f8e9", vanilla = true },
        text = { it = "Aprendo la cassa si scopre una sfera annerita che pulsa di una luce sinistra. È il tesoro di cui parlava Fitzsimmons: un Cursed Eye of Paleth.\n\nPorta il Cursed Eye of Paleth al sacerdote nano Glorin Steelbrow, a Menethil Harbor. Chiedigli come togliere la maledizione dall'Eye.", enHash = "5ab0f678", vanilla = true },
        objectives = { it = "Porta il Cursed Eye of Paleth a Glorin Steelbrow.", enHash = "5e914392", vanilla = true },
        progress = { it = "Quell'ubriacone di Fitzsimmons ti manda da me? Be', puoi dirgli che non ho birra in più. Dovrà andare a elemosinare da qualcun altro!", enHash = "f09cf066", vanilla = true },
        reward = { it = "Un Eye of Paleth? Incredibile! Mmh... c'è qualcosa che non va in questo. L'hai trovato su uno di quei relitti? Be', questo spiega tutto! Ma... non sapevo che ne avessero uno sulla Third Fleet...\n\nNon c'è da stupirsi che Fitzsimmons fosse così spaventato. Un Cursed Eye of Paleth non è cosa da riderci sopra.", enHash = "e1190675", vanilla = true },
    },
    [293] = {
        title = { it = "Purificare l'Eye", enHash = "b163423a", vanilla = true },
        text = { it = "Non riesco a togliere la maledizione dall'Eye of Paleth. Gli Eye furono creati da sacerdoti umani, quindi dovrai andare a Stormwind a cercare qualcuno che possa aiutarti. Parla con Archbishop Benedictus. È a capo della Cathedral of Light di Stormwind. Lui può aiutarti.\n\nLo spero, per il tuo bene.", enHash = "ffcca730", vanilla = true },
        objectives = { it = "Porta il Cursed Eye of Paleth ad Archbishop Benedictus. Benedictus si trova nella Cathedral of Light, nella città di Stormwind.", enHash = "2525cd82", vanilla = true },
        progress = { it = "Che sfera è quella che hai? Sembra... lordata.", enHash = "5c742557", vanilla = true },
        reward = { it = "Un Eye of Paleth. Ma questo ha visto molto dolore... deve essere stato testimone di una tragedia terribile, terribile.\n\nLascia che lo purifichi, perché gli Eye furono creati per splendere, e i loro poteri possono essere molto pericolosi se corrotti come questo.", enHash = "fb962716", vanilla = true },
    },
    [294] = {
        title = { it = "La vendetta di Ormer", enHash = "7f406fcd", vanilla = true },
        text = { it = "La situazione è grave, questo è certo. Quando abbiamo portato alla luce queste ossa abbiamo attirato i raptor. Quelle bestie immonde hanno ucciso i miei compagni e hanno intrappolato quassù me, Merrin e il povero cercatore.\n\nAiuta a ripulire le Wetlands da questi raptor, $N. I Mottled Raptor e i Mottled Screecher sono appena a ovest del promontorio, là. Uccidine 10 di ciascuno, se ci riesci.\n\nSarà un buon inizio per la vendetta che ho in mente per loro.", enHash = "e2a72967", vanilla = true },
        objectives = { it = "Ormer Ironbraid, al Whelgar Excavation Site, vuole che tu uccida 10 Mottled Screecher e 10 Mottled Raptor.", enHash = "b84c251c", vanilla = true },
        progress = { it = "Uccidi 10 Mottled Raptor e 10 Mottled Screecher, $N. I miei colleghi non meritavano la sorte che è toccata loro. È ora di pareggiare i conti.", enHash = "0a906623", vanilla = true },
        reward = { it = "Uccidere è un mestiere sporco, ma hai fatto bene il tuo lavoro, $N. Se non fossi obbligato a restare con il cercatore e Merrin, sarei laggiù a versare sangue al tuo fianco.", enHash = "ab7f88a1", vanilla = true },
    },
    [295] = {
        title = { it = "La vendetta di Ormer", enHash = "7f406fcd", vanilla = true },
        text = { it = "Ora è il momento di far pentire davvero quei maledetti raptor della loro sete di sangue. Proprio là sotto ci sono a bizzeffe Mottled Scytheclaw e Mottled Razormaw. Falla pagare a quelle creature marce uccidendone 10 di ciascuna!", enHash = "12ac65ce", vanilla = true },
        objectives = { it = "Ormer Ironbraid vuole che tu uccida 10 raptor Mottled Scytheclaw e 10 raptor Mottled Razormaw, poi che torni da lui al Whelgar Excavation Site.", enHash = "4c221daa", vanilla = true },
        progress = { it = "Voglio che quei Mottled Scytheclaw e quei Mottled Razormaw paghino per quello che hanno fatto. Ne hai già uccisi 10 di ciascuna specie?", enHash = "70a3a2a4", vanilla = true },
        reward = { it = "Hai fatto un lavoro coi fiocchi ripulendo quei raptor, $N!", enHash = "7badfdc1", vanilla = true },
    },
    [296] = {
        title = { it = "La vendetta di Ormer", enHash = "7f406fcd", vanilla = true },
        text = { it = "Mentre eri laggiù ho notato che uno di quei mostri spiccava sugli altri. Era più grosso e più minaccioso. Scommetto che è stato lui a guidare gli altri fin qui, a devastare il sito di scavo.\n\nTi chiedo ora un ultimo compito, $N. Fa' in modo che Sarltooth sia assicurato alla giustizia. E vista la gravità dei suoi crimini, in questo caso giustizia vuol dire morte! Portami uno dei suoi artigli come prova della sua morte.", enHash = "eeae9c7c", vanilla = true },
        objectives = { it = "Ormer Ironbraid, al Whelgar Excavation Site, vuole che tu uccida Sarltooth e torni da lui con uno dei suoi artigli, una volta compiuto il compito.", enHash = "c99ad4dd", vanilla = true },
        progress = { it = "Sarltooth è morto? Hai riscattato la memoria dei caduti?", enHash = "4793a18c", vanilla = true },
        reward = { it = "Grazie, $N. Quello che hai fatto qui non sarà dimenticato. Molti nani innocenti sono morti in questo sito, mentre facevano solo il loro lavoro. La vendetta che hai portato a quelle creature malvagie dovrebbe farle pensare due volte prima di attaccare ancora i sudditi di King Magni.", enHash = "ba8ce501", vanilla = true },
    },
    [297] = {
        title = { it = "Raccogliere gli idoli", enHash = "6ed0ade2", vanilla = true },
        text = { it = "Di recente, poco prima che i trogg sbucassero nel sito, avevamo portato alla luce un gran numero di strani idoli intagliati. Ma non abbiamo avuto modo di studiarli, perché subito dopo la scoperta i trogg ci hanno cacciati dalle rovine! E quegli idoli hanno uno strano effetto sui trogg: li fanno andare in furia!\n\nPortami 8 idoli: voglio studiarli, e li voglio fuori dalle mani dei trogg! Gli idoli li trovi sui trogg che infestano il sito.", enHash = "2973a541", vanilla = true },
        objectives = { it = "Porta a Magmar Fellhew 8 Carved Stone Idol.", enHash = "a6e09879", vanilla = true },
        progress = { it = "Ce li hai quegli idoli? Dobbiamo studiarli e riferire le nostre scoperte a Ironforge!", enHash = "4db64d19", vanilla = true },
        reward = { it = "Li hai presi! Ben fatto, $N!\n\nE non sembri neanche troppo $Gmalconcio:malconcia;, pur con quei trogg in furia in giro. Ti terrò d'occhio... prometti bene.", enHash = "ff637ad3", vanilla = true },
    },
    [298] = {
        title = { it = "Rapporto sullo scavo", enHash = "31e74637", vanilla = true },
        text = { it = "Devo mandare un rapporto sui progressi a Thelsamar: un rapporto sui progressi e una nuova richiesta di altra polvere esplosiva! Ecco il rapporto. Portalo a Jern Hornhelm. È il nostro referente a Thelsamar.\n\nNon è un compito difficile, ma va fatto.", enHash = "d234e06c", vanilla = true },
        objectives = { it = "Porta Ironband's Progress Report a Jern Hornhelm, a Thelsamar.", enHash = "b71e241b", vanilla = true },
        progress = { it = "Oh, un rapporto sui progressi dal sito? Ottimo!", enHash = "4c7b7f72", vanilla = true },
        reward = { it = "Bah! Ironband ha guai con i trogg. Mi chiedo se voglia quella polvere esplosiva per scavare o per usarla contro quelle bestie di trogg...\n\nBe', in un modo o nell'altro è polvere ben spesa!\n\nQuello che è strano, però, è che gliene ho mandata in abbondanza settimane fa. Chissà dove è finita...", enHash = "35ca47ca", vanilla = true },
    },
    [299] = {
        title = { it = "Riportare alla luce il passato", enHash = "6597889d", vanilla = true },
        text = { it = "Poco prima dell'invasione ho portato alla luce una grande tavoletta chiamata Goaz Stone. Il testo tradotto si interrompe in 4 punti. Parla di un \"piano divino\" e di una \"profezia dannata\".\n\nTemo che il tempo stia per scadere. Sono troppo vecchio per scendere ad affrontare quelle bestie. Ma tu sei forte.\n\nSetaccia il sito di scavo e riporta alla luce i 4 frammenti mancanti della tavoletta: Ados, Modr, Golm e Neru. Cercali negli artefatti antichi o dove il terreno è smosso. Portameli, così potrò cominciare a sciogliere il mistero!", enHash = "2421fcbb", vanilla = true },
        objectives = { it = "Prospector Whelgar vuole che tu setacci il sito di scavo in cerca dei 4 frammenti mancanti della tavoletta: Ados, Modr, Golm e Neru.", enHash = "ddfb8371", vanilla = true },
        progress = { it = "Hai già riportato alla luce i quattro frammenti, $N? Ados, Modr, Golm e Neru...", enHash = "4d6f05ce", vanilla = true },
        reward = { it = "Ah, la Goaz Stone è completa! Ottimo lavoro, $N. Davvero ottimo. Ora posso continuare la delicata traduzione di questa scrittura dei titani. Riesco già a distinguere parole nuove! Mmh... qui dice: \"Antichi Dei... Incatenati Sotto la Terra\". È l'inizio di qualcosa di epico.", enHash = "ffb45579", vanilla = true },
    },
    [301] = {
        title = { it = "Rapporto a Ironforge", enHash = "c11bf7a6", vanilla = true },
        text = { it = "Ci servirà un'autorizzazione per dare a Ironband altra polvere esplosiva. Dovrai portare il suo rapporto al quartier generale della Lega degli Esploratori, a Ironforge.\n\nEcco il rapporto. Consegnalo a Prospector Stormpike, e appena gliel'hai dato preparati a schivare. Stormpike è una testa calda, e non sarà contento di sentire quanto vanno a rilento i lavori di Ironband allo scavo.\n\nStormpike lo trovi nell'Assembly of Explorers.", enHash = "4193f363", vanilla = true },
        objectives = { it = "Porta Ironband's Progress Report a Prospector Stormpike.", enHash = "a2df7255", vanilla = true },
        progress = { it = "Noi Stormpike non amiamo essere disturbati per questioni banali, $C. Spero che tu porti notizie degne della mia preziosa attenzione.", enHash = "9d0c9808", vanilla = true },
        reward = { it = "Maledetto quell'Ironband! Gli ho mandato un carico di polvere esplosiva settimane fa, ma in questo rapporto non ne fa parola.\n\nQuindi... dov'è finita la polvere esplosiva?!?", enHash = "82e0fd63", vanilla = true },
    },
    [302] = {
        title = { it = "Polvere per Ironband", enHash = "109ab41b", vanilla = true },
        text = { it = "Se a Ironband serve ancora polvere esplosiva, allora per Magni l'avrà! Ho mandato avanti l'approvazione con un messaggero a Jern Hornhelm, a Thelsamar. Preparerà lui la polvere e gli altri rifornimenti da portare a Ironband.\n\nE un'altra cosa: voglio che tu ti accerti di persona che il carico di polvere arrivi a destinazione. L'ultimo non ci è arrivato, quindi tieni la mente sveglia e gli occhi aperti.", enHash = "a8593950", vanilla = true },
        objectives = { it = "Parla con Jern Hornhelm, a Thelsamar.", enHash = "1da5c2b2", vanilla = true },
        reward = { it = "Cosa? Stormpike vuole che sia tu a seguire di persona il carico fino a Ironband?\n\nIo... immagino vada bene, l'unico problema è che ho già mandato Huldar con i portatori, Miran e Saean. Li hai mancati per poco, sono partiti da pochissimo.", enHash = "b48d5852", vanilla = true },
    },
    [303] = {
        title = { it = "La guerra dei Dark Iron", enHash = "d384f78b", vanilla = true },
        text = { it = "La guerra infuria sia in patria sia all'estero. Mentre possenti soldati nani danno la vita in territori lontani nel nome dell'Alleanza, le nostre terre cadono preda delle malefatte dei Dark Iron Dwarf. Hanno devastato il Thandol Span. Dun Modr è caduta poco dopo.\n\nCi serve che tu raduni le forze e respinga il fronte. Se riesci a uccidere 15 Dark Iron Dwarf, 5 Tunneler, 5 Saboteur e 5 Demolitionist, la riserva potrebbe arrivare in tempo per chiudere la spinta.\n\nOra fa' presto!", enHash = "09014b72", vanilla = true },
        objectives = { it = "Motley Garmason, a Dun Modr, vuole che tu uccida 15 Dark Iron Dwarf, 5 Dark Iron Tunneler, 5 Dark Iron Saboteur e 5 Dark Iron Demolitionist.", enHash = "83c7177a", vanilla = true },
        progress = { it = "Roggo non è riuscito a contattare le forze di riserva. Ci serve pressione offensiva su quell'accampamento Dark Iron, $C. Adesso torna là fuori e fa' il tuo dovere verso King Magni!", enHash = "29160cb9", vanilla = true },
        reward = { it = "Hai rispettato bene i tuoi ordini, $C. Ti sei $Gdimostrato:dimostrata; $Gun soldato valoroso:una soldatessa valorosa; e $Gun leale servitore:una leale servitrice; di King Magni, e per questo ti saluto! Con la pressione che hai messo sull'accampamento Dark Iron, ora abbiamo qualche possibilità di cacciarli dalle nostre terre per sempre... se solo arrivasse quella maledetta riserva...", enHash = "f7eff778", vanilla = true },
    },
    [304] = {
        title = { it = "Un compito tetro", enHash = "4c0c32b7", vanilla = true },
        text = { it = "Molti dei miei soldati sono morti nella battaglia di Dun Modr. Mio fratello è perito quando il West Bridge sul Thandol Span è stato distrutto. Sì, i nani Dark Iron sono una razza diabolica. Da quello che Roggo è riuscito a raccogliere, il capo di questa banda di bruti nelle Wetlands è uno stregone di nome Balgaras the Foul. È però un bel codardo. Manda i suoi soldati a fare il lavoro sporco e resta inafferrabile, evitando il pericolo.\n\nSe riesci a trovare quella feccia senza spina dorsale, uccidilo e portami il suo orecchio. Ti ricompenserò, $C.", enHash = "faa4fe28", vanilla = true },
        objectives = { it = "Uccidi Balgaras the Foul e porta il suo orecchio a Longbraid the Grim, fuori da Dun Modr.", enHash = "dfbaa2b9", vanilla = true },
        progress = { it = "Sei già $Griuscito:riuscita; a trovare Balgaras the Foul, $C? Ci sfugge da parecchio tempo.", enHash = "13def7fa", vanilla = true },
        reward = { it = "Balgaras the Foul è finalmente morto. Anche se la sua morte non riporterà indietro i tanti nani innocenti morti inutilmente per mano sua, aiuterà a ridare pace a chi è sopravvissuto. Con Balgaras morto, la feccia Dark Iron rimasta dovrebbe essere abbastanza facile da gestire. Ora dobbiamo spazzarli via prima che mandino da queste parti un nuovo capo.\n\nHai fatto bene, $C.", enHash = "6acd4831", vanilla = true },
    },
    [305] = {
        title = { it = "In cerca della squadra di scavo", enHash = "514422f2", vanilla = true },
        text = { it = "Oh, tu devi essere $Gl'esploratore:l'esploratrice; che Longbraid ha detto che avrebbe mandato! Non puoi immaginare quanto sono stato in pena.\n\nMia moglie, Merrin, mi manda lettere ogni settimana da un mese. Fa parte della squadra di scavo di Whelgar. Ma sono passate quasi due settimane dall'ultima lettera. Qualcosa non va di sicuro!\n\nLongbraid aveva detto che avrebbe mandato un esploratore a controllare, se non avessimo avuto notizie della squadra. Immagino che $Gquell'esploratore:quell'esploratrice; sia tu, $N. Trova Merrin al sito di scavo, a est!", enHash = "425b73b2", vanilla = true },
        objectives = { it = "Tarrel Rockweaver vuole che tu raggiunga l'Excavation Site e contatti Merrin Rockweaver.", enHash = "48f6323e", vanilla = true },
        reward = { it = "Oh, siano ringraziati i cieli, sei qui!", enHash = "178d2b6a", vanilla = true },
    },
    [306] = {
        title = { it = "In cerca della squadra di scavo", enHash = "514422f2", vanilla = true },
        text = { it = "È stato orribile! Stavamo portando alla luce certi artefatti rari e abbiamo cominciato a trovare queste ossa enormi.\n\nPrima che ci rendessimo conto di cosa stava succedendo, questi Mottled Raptor hanno invaso il sito di scavo. Molte vite sono andate perdute.\n\nOrmer, qui, così coraggioso, ha salvato il cercatore e me. Ci ha difesi mentre correvamo al riparo. Ora siamo intrappolati. E il nostro duro lavoro è in rovina.\n\nEcco, riporta questo biglietto al mio caro Tarrel. Gli spiegherà la situazione.", enHash = "3596796a", vanilla = true },
        objectives = { it = "Torna da Tarrel Rockweaver con Merrin's Note.", enHash = "fa6c696b", vanilla = true },
        progress = { it = "Sei $Griuscito:riuscita; a trovare Merrin? Ha mandato sue notizie?", enHash = "9be53f68", vanilla = true },
        reward = { it = "Che notizie orribili! Almeno tre di loro sono sopravvissuti. Ma quando finirà questa mattanza? Aspetto con ansia il giorno in cui i sudditi di re Magni potranno vivere senza paura.", enHash = "3a0436e1", vanilla = true },
    },
    [307] = {
        title = { it = "Zampe sporche", enHash = "721f9251", vanilla = true },
        text = { it = "La Silver Stream Mine, a est, si è esaurita da tempo. La Miners' League l'aveva convertita in un deposito, ma ora ci si sono insediati i kobold, e mettono le loro zampe sporche su buoni attrezzi nanici!\n\nPresto staneremo quei parassiti, ma la Lega vuole che qualcuno tiri fuori la sua roba dalla miniera prima che noi guerrieri ci entriamo a passo di carica e rompiamo tutto. Sarà una discesa dura: forse ti conviene avere dei compagni al fianco.\n\nLa roba è riposta nelle Miners' League Crate sparse per la miniera. Buona fortuna.", enHash = "2eca005a", vanilla = true },
        objectives = { it = "Va' alla Silver Stream Mine e raccogli 4 carichi di Miners' Gear.\n\nTorna da Mountaineer Stormpike.", enHash = "b8e6b5ad", vanilla = true },
        progress = { it = "Ce l'hai quel Miners' Gear, $N?", enHash = "c419aaee", vanilla = true },
        reward = { it = "Hai visto tanti kobold là dentro? Non vedo l'ora che arrivi l'ordine di ripulirne la miniera. Il pensiero delle loro mani lerce che artigliano in giro per la nostra miniera mi fa ribollire lo stomaco!", enHash = "b62ca6d6", vanilla = true },
    },
    [309] = {
        title = { it = "Proteggere il carico", enHash = "146470b6", vanilla = true },
        text = { it = "$GPronto:Pronta; a partire, $N?\n\nPrima di tutto dobbiamo portare questa polvere a Ironband. Sarà un bel peso da trasportare per me, e da queste parti può farsi pericoloso — e chissà cos'altro hanno in serbo per me i Dark Iron.\n\nMi sentirò molto più tranquillo se vieni con me.", enHash = "5a645162", vanilla = true },
        objectives = { it = "Fa' in modo che Miran e il carico arrivino al sito di scavo, poi avvisa Prospector Ironband.", enHash = "77b8b71d", vanilla = true },
        progress = { it = "Dov'è la mia polvere, $N? Il bisogno si fa più disperato ogni giorno.", enHash = "5bc0da96", vanilla = true },
        reward = { it = "Oh, sia lodata la Luce, la polvere è arrivata. Ma quelle che porti sono anche notizie preoccupanti. Pensare che i Dark Iron abbiano simpatizzanti in grado di procurare materiale del genere per i loro piani infami.\n\nÈ una faccenda per qualcun altro, in un altro momento. Io devo mettere a frutto questa polvere.", enHash = "f61cb31d", vanilla = true },
    },
    [310] = {
        title = { it = "Rivali acerrimi", enHash = "c581f9d5", vanilla = true },
        text = { it = "Devo ammetterlo, quei Thunderbrew fanno delle bevande niente male. Ma devono imparare che la loro non è l'unica birra decente! Forse puoi aiutarmi a dargli questa lezione...\n\nTieni, prendi questo barile di Barleybrew Scalder. Intrufolati nel seminterrato della Thunderbrew Distillery a Kharanos e scambialo con uno dei loro barili di Thunder Ale. Poi vedremo se ai loro clienti piace più la mia birra della loro!\n\nE se i barili sono sorvegliati, forse dovrai distrarre la guardia...", enHash = "c06b211b", vanilla = true },
        objectives = { it = "Nel seminterrato della Thunderbrew Distillery, a Kharanos, sostituisci un barile di Thunder Ale con un Barrel of Barleybrew Scalder.", enHash = "3ff6eb5f", vanilla = true },
        progress = { it = "La data su questo barile dice che verrà spillato presto.", enHash = "25383ccd", vanilla = true },
        reward = { it = "Sistemi in fretta il barile di Barleybrew Scalder di Marleth tra i barili dei Thunderbrew.", enHash = "6b32a2f1", vanilla = true },
    },
    [311] = {
        title = { it = "Ritorno da Marleth", enHash = "265e6456", vanilla = true },
        text = { it = "Dopo aver infilato un barile di Scalder di Marleth nella cantina della Kharanos Distillery, prendi un barile di Thunder Ale come prova dell'impresa...", enHash = "75945a0a", vanilla = true },
        objectives = { it = "Porta il barile di Thunder Ale a Marleth Barleybrew, a Brewnall Village.", enHash = "71fff9d6", vanilla = true },
        progress = { it = "Hai fatto lo scambio?", enHash = "e685d68c", vanilla = true },
        reward = { it = "Niente male, $N! Hai avuto difficoltà a superare la loro guardia?\n\nPoco importa — mille grazie, e se mai avrai bisogno di una stout con un po' di carattere, non dimenticarti dei Barleybrew!", enHash = "d7221c93", vanilla = true },
    },
    [312] = {
        title = { it = "La scorta rubata di Tundra MacGrann", enHash = "0ee0ccef", vanilla = true },
        text = { it = "Avevo carne secca salata per un mese intero, chiusa sotto chiave per la stagione fredda. La tenevo chiusa perché non la prendessero gli orsi! Ma mentre ero via a cacciare cervi, quella bestia di Old Icebeard si è portata via la cassa della carne. Non riuscirà però a sfondare quel Thorium. Solo che, se non riavrò la mia carne, morirò di fame.\n\nTu sembri un po' più $Gfurtivo:furtiva; di me. Magari puoi recuperarmi la scorta? Con questa gamba malandata non entrerò e uscirò mai da quella grotta abbastanza in fretta.", enHash = "6c6e4b20", vanilla = true },
        objectives = { it = "Recupera la carne secca di Tundra MacGrann dalla cassa della carne rubata, nella grotta di Old Icebeard.", enHash = "a1fcfdca", vanilla = true },
        progress = { it = "Sei $Griuscito:riuscita; ad aprire la mia cassa della carne, $N?", enHash = "baac0571", vanilla = true },
        reward = { it = "Che anima gentile che sei, $N! Grazie al tuo coraggio non mi ritroverò a morire di fame quando arriveranno le raffiche della stagione fredda.", enHash = "facdae7e", vanilla = true },
    },
    [313] = {
        title = { it = "Il Grizzled Den", enHash = "69859569", vanilla = true },
        text = { it = "Guidare una macchina d'assedio non è per tutti. Ci vogliono polso di ferro e nervi d'acciaio... per fortuna ho entrambi! E tu? Di che tempra sei? Vuoi dimostrarmelo?\n\nBe'... voglio rendere il mio mezzo, Trollplow, un po' più accogliente. Che ne dici di procurarmi un mucchio di Wendigo Mane dal Grizzled Den, a ovest di Kharanos? Quelle criniere sarebbero un tappeto magnifico per il ponte interno di Trollplow!", enHash = "fc6f1057", vanilla = true },
        objectives = { it = "Raccogli 8 Wendigo Mane e portale a Pilot Stonegear.", enHash = "d002d2d2", vanilla = true },
        progress = { it = "Ehi, $N. Sei già $Gstato:stata; al Grizzled Den? Quei Wendigo sanno essere feroci.", enHash = "6a8518cd", vanilla = true },
        reward = { it = "Ah sì, queste criniere andranno benissimo! Hai molto fegato, $C — scommetto che vedremo grandi cose da te.", enHash = "e159fd83", vanilla = true },
    },
    [314] = {
        title = { it = "Proteggere il gregge", enHash = "c50fbd0b", vanilla = true },
        text = { it = "Abbiamo sentito le grida nel cuore della notte. Poi stamattina, com'era prevedibile, al gregge mancavano due arieti. Quella bestia infame di Vagash si sta accanendo sul nostro sostentamento. Con la maggior parte dell'esercito di King Magni in terre lontane a combattere con l'Alleanza, non c'è nessuno a tenere a bada Vagash.\n\nForse sei abbastanza $Gcoraggioso:coraggiosa; da stanare la bestia e ucciderla. Portami una delle sue zanne e ti ricompenserò. Vagash si aggira proprio sopra il ranch, ma sei $Gavvertito:avvertita;: è letale.", enHash = "0a3ff3f9", vanilla = true },
        objectives = { it = "Rudra Amberstill vuole che tu uccida Vagash e le porti la sua zanna, al ranch degli arieti.", enHash = "72ea404c", vanilla = true },
        progress = { it = "Vagash terrorizza ancora il gregge! Ti prego, aiutaci uccidendo quella miserabile bestia.", enHash = "d0f76352", vanilla = true },
        reward = { it = "Ottimo lavoro! Veron sarà felicissimo quando sentirà la buona notizia. Uccidere Vagash non è un'impresa da poco. Immagino che un giorno combatterai al fianco degli uomini di King Magni sul fronte dell'Alleanza.", enHash = "f7a700df", vanilla = true },
    },
    [315] = {
        title = { it = "La stout perfetta", enHash = "c595aa0b", vanilla = true },
        text = { it = "Sono in missione: una missione per fare la stout perfetta. So di poterci riuscire — fare birra ce l'ho nel sangue. Devo solo trovare la ricetta giusta...\n\nI troll Frostmane coltivano una pianta, lo Shimmerweed, su in alto tra le colline a est. Lo usano nei loro strani rituali tribali. Noi nani non ci abbiamo trovato grande utilità, ma ha un sapore unico... e voglio provarlo nelle mie birre!\n\nProcurami un po' di Shimmerweed dai Frostmane Seer, o rubalo dalle Shimmerweed Basket dei troll.", enHash = "1f3fb258", vanilla = true },
        objectives = { it = "Porta 6 Shimmerweed a Rejold Barleybrew, a Brewnall Village.", enHash = "b5e396a6", vanilla = true },
        progress = { it = "Hai quello Shimmerweed? Ho quasi pronta una cotta di stout, e voglio provare a buttare l'erba in questa miscela.", enHash = "748d6fdb", vanilla = true },
        reward = { it = "Ottimo! Non vedo l'ora di usarli in qualcuna delle mie ricette. Ce n'è una in particolare in cui penso che starà benissimo...", enHash = "75eac12d", vanilla = true },
    },
    [317] = {
        title = { it = "Rifornire Jetsteam", enHash = "14ddfaeb", vanilla = true },
        text = { it = "Mi sto preparando per una missione della Siege Brigade. È lunga, e devo rifornire Jetsteam con provviste per un mese. Quindi, mentre Steelgrill lavora al mio carro, puoi andare a caccia per me?\n\nMi servirà della pelliccia per il giaciglio e della carne di cinghiale per il cibo. La carne la prendi dai cinghiali e la pelliccia dagli orsi... li trovi entrambi nei campi innevati a sud del Grizzled Den.", enHash = "54d7853d", vanilla = true },
        objectives = { it = "Raccogli 4 Chunk of Boar Meat e 2 Thick Bear Fur e consegnali a Pilot Bellowfiz, allo Steelgrill's Depot.", enHash = "34f51dd2", vanilla = true },
        progress = { it = "I preparativi procedono bene. Come va la caccia?", enHash = "250a290d", vanilla = true },
        reward = { it = "Per la barba di Magni, hai cacciato davvero parecchio!! Grazie, $N.", enHash = "58fa6751", vanilla = true },
    },
    [318] = {
        title = { it = "Evershine", enHash = "08adbf0d", vanilla = true },
        text = { it = "Rejold Barleybrew fa esperimenti con le sue birre. Alcune sono buone, altre cattive, e certe... be', certe stendono chiunque tranne il nano più robusto.\n\nVive a Brewnall Village, a ovest di Kharanos, e una delle sue bevande, l'Evershine, è quella che voglio. Mi aiuterà a stare al caldo mentre sono in viaggio nel freddo.\n\nE... quella roba benedetta brucia così forte che posso buttarla nella fornace di Jetsteam per una scarica di potenza! Questo trucchetto mi ha tirato fuori da più di un guaio.", enHash = "303c7c84", vanilla = true },
        objectives = { it = "Fatti dare un barilotto di Evershine da Rejold Barleybrew, a Brewnall Village.", enHash = "f2908e6e", vanilla = true },
        reward = { it = "Bellowfiz ha bisogno del mio Evershine? Mmh... va bene.", enHash = "faae7fa8", vanilla = true },
    },
    [319] = {
        title = { it = "Un favore per l'Evershine", enHash = "a14247d5", vanilla = true },
        text = { it = "Un barilotto di Evershine ce l'ho a portata di mano, ma... mi fai un favore? A Brewnall Village farebbe comodo una mano contro gli animali selvatici che vagano per le nevi qui intorno. A volte si avvicinano troppo.\n\nNon abbiamo paura di questi orsi, felini e cinghiali — nessun nano che si rispetti ne avrebbe — ma se ci togli di mezzo quegli animali, avremo più tempo per il nostro artigianato e le nostre birre.", enHash = "ffae0d93", vanilla = true },
        objectives = { it = "Uccidi 6 Ice Claw Bear, 8 Elder Crag Boar e 8 Snow Leopard, poi torna da Rejold Barleybrew, a Brewnall Village.", enHash = "8cab69f7", vanilla = true },
        progress = { it = "Ti sei $Goccupato:occupata; di quegli animali selvatici?", enHash = "1e3467bf", vanilla = true },
        reward = { it = "Grazie, $N. Sarà bello lavorare ai nostri mestieri senza sentire tutti quei ringhi e grugniti fuori dal villaggio.", enHash = "07c8d23f", vanilla = true },
    },
    [320] = {
        title = { it = "Ritorno da Bellowfiz", enHash = "0c137f97", vanilla = true },
        text = { it = "Ecco il tuo barilotto di Evershine, $N. E ancora grazie per la caccia di prima.", enHash = "0497e4bc", vanilla = true },
        objectives = { it = "Consegna il barilotto di Evershine a Pilot Bellowfiz, allo Steelgrill's Depot.", enHash = "af9df4ff", vanilla = true },
        progress = { it = "Hai preso quell'Evershine?", enHash = "7008bbff", vanilla = true },
        reward = { it = "Sì, andrà benissimo. Credo che ne aprirò una bottiglia proprio adesso, per assaggiarla...", enHash = "f364f003", vanilla = true },
    },
    [321] = {
        title = { it = "Lightforge Iron", enHash = "f3313377", vanilla = true },
        text = { it = "I relitti al largo di questa costa sono la sventurata Third Fleet di Kul'Tiras, bruciata e affondata dai Red Dragon durante l'ultima Grande Guerra.\n\nLa flotta veniva da Lordaeron, ma con lei c'era una nave, un vascello da guerra elfico: la Flying Osprey. Trasportava un carico di Lightforge Iron e si era unita alla Third Fleet per avere protezione. Ironico che sia affondata per opera degli stessi draghi...\n\nBasta storia. La Flying Osprey è naufragata a sud di Menethil Harbor. Se trovi lì il Lightforge Iron, portamelo.", enHash = "9e37e02a", vanilla = true },
        objectives = { it = "Cerca tra i relitti della Flying Osprey, nelle Wetlands.", enHash = "e106a6c3", vanilla = true },
        reward = { it = "Questa cassa è impregnata d'acqua e le fiancate sono rotte. Molti segni di artigli rovinano l'interno e l'esterno della cassa... come se dei murloc l'avessero frugata e ne avessero rubato il tesoro.\n\nMa in fondo alla cassa, ben infilato, c'è un solo Lightforge Ingot. Purtroppo ne serviranno molti altri per avere metallo a sufficienza da forgiare un'arma.", enHash = "c00eead6", vanilla = true },
    },
    [322] = {
        title = { it = "L'arma benedetta", enHash = "ad066416", vanilla = true },
        text = { it = "Nel Dwarven District di Stormwind c'è un armaiolo nano che sa lavorare il Lightforge Iron. Si chiama Grimand Elmore.\n\nHo messo in una cassa il metallo che hai trovato. Portala a Grimand e raccontagli la tua storia. Sono sicuro che darà una mano a chi è impegnato in un'impresa come la tua, e ti forgerà un'arma: un'arma che farà preoccupare perfino Morbent Fel!", enHash = "7418ed82", vanilla = true },
        objectives = { it = "Porta la Crate of Lightforge Ingots a Grimand Elmore, a Stormwind.", enHash = "d2a83068", vanilla = true },
        progress = { it = "In cosa posso mettere la mia arte al tuo servizio, $C?", enHash = "3f99ac65", vanilla = true },
        reward = { it = "Quella sì che è una bella storia. E Lightforge Iron! Non lavoro un metallo simile da anni. Sarà un onore lavorarlo di nuovo. E dovrai tornare da me più avanti a raccontarmi la tua battaglia contro il negromante.\n\nMa stiamo correndo troppo. Prima, la tua arma contro Morbent Fel...", enHash = "0d4f65e5", vanilla = true },
    },
    [323] = {
        title = { it = "Dimostra il tuo valore", enHash = "005d0508", vanilla = true },
        text = { it = "Morbent Fel è un negromante, e un alleato dei Dark Rider. Ti metterei contro il potere di Morbent Fel, ma non ti manderò contro quel mostro immondo senza prima conoscere la tua forza.\n\nIl tuo coraggio me l'hai già dimostrato, ma se vuoi davvero affrontare il negromante, allora devi dimostrare la tua abilità contro i suoi servi.", enHash = "2beba0b7", vanilla = true },
        objectives = { it = "Uccidi 15 Skeletal Raider, 3 Skeletal Healer e 3 Skeletal Warder, poi torna da Sven.", enHash = "8b41ab59", vanilla = true },
        progress = { it = "Combatti con forza, $N. E non disperare, perché la disperazione è l'arma più grande del male.", enHash = "07c4bb44", vanilla = true },
        reward = { it = "La tua abilità in combattimento, $N, è fuori discussione. La tua determinazione potrebbe portarci fino alla fine di Morbent Fel!", enHash = "1686c415", vanilla = true },
    },
    [324] = {
        title = { it = "I lingotti perduti", enHash = "48b8cf59", vanilla = true },
        text = { it = "Preso l'unico Lightforge Ingot dalla cassa impregnata d'acqua, è chiaro che i murloc hanno rubato il resto. Dai la caccia ai murloc predoni vicino al relitto della Flying Osprey per recuperare il Lightforge Iron perduto.", enHash = "7a385a54", vanilla = true },
        objectives = { it = "Raccogli 5 Lightforge Ingot, poi torna da Glorin Steelbrow, nelle Wetlands.", enHash = "105cc4b9", vanilla = true },
        progress = { it = "L'hai trovato il Lightforge Iron che ti serve?", enHash = "9f98110b", vanilla = true },
        reward = { it = "Ah, li hai trovati! E adesso battiamo questo Lightforge Iron fino a farne qualcosa di utile, eh?", enHash = "adcbf7f4", vanilla = true },
    },
    [325] = {
        title = { it = "Armi in pugno", enHash = "a1fa7035", vanilla = true },
        text = { it = "Ecco l'arma contro quel mostro di cui parlavi. Sei $Gpronto:pronta;, $N. Buona fortuna, e aspetto con ansia il racconto della tua gloria!", enHash = "95e4269a", vanilla = true },
        objectives = { it = "Porta Morbent's Bane a Sven, a Duskwood.", enHash = "22748ecd", vanilla = true },
        progress = { it = "Salve, $N. Non sei $Gstato:stata; via molto, ma vedo nei tuoi occhi un fuoco che prima non c'era.", enHash = "bf2c0e89", vanilla = true },
        reward = { it = "Ah, questa reggerà contro quel mostro di Morbent Fel! Ben fatto!\n\nSei $Gpronto:pronta;. Morbent Fel cadrà.", enHash = "483ba667", vanilla = true },
    },
    [328] = {
        title = { it = "La chiave nascosta", enHash = "e1aa79f8", vanilla = true },
        text = { it = "Anche se in questi registri non si trova alcun accenno a Private Thorsen, nascosta nella rilegatura di uno dei libri contabili di Herod c'è una Small Brass Key.\n\nE, studiando meglio i suoi appunti, tra le varie carte si trovano alcuni riferimenti a un \"forziere sicuro\". Il forziere si trova da qualche parte nello Stockpile — il complesso di caverne sul retro del Kurzen's Compound.\n\nSe si trova questo forziere sicuro, e se la Small Brass Key riesce ad aprirlo, forse si svelerà il mistero di come è stato scoperto Thorsen.", enHash = "4dcd477a", vanilla = true },
        objectives = { it = "Usa la Small Brass Key per aprire il Bookie Herod's Strongbox.", enHash = "d4b0717d", vanilla = true },
        progress = { it = "Il forziere è rinforzato in bronzo, molto robusto e molto pesante.", enHash = "0f4cbfc3", vanilla = true },
        reward = { it = "Aprendo il forziere, è chiaro che è qui che Herod tiene le monete e gli oggetti di maggior valore.", enHash = "a7b4dfad", vanilla = true },
    },
    [329] = {
        title = { it = "La spia smascherata!", enHash = "61b231a2", vanilla = true },
        text = { it = "Tra gli oggetti di valore del forziere c'è un Muddy Note scarabocchiato. Anche se è a malapena leggibile, sembra un itinerario di Private Thorsen. Descrive nei dettagli i suoi percorsi di pattuglia, con chi parla e come passa il tempo con i ribelli. È firmato con una sola lettera: -M.\n\nMa chiunque abbia scritto questo biglietto deve essere stato molto vicino a Thorsen. Chiunque abbia scritto questo biglietto è il traditore all'interno del Rebel Camp.", enHash = "40c37fc2", vanilla = true },
        objectives = { it = "Porta il Muddy Note a Lieutenant Doren, al Rebel Camp.", enHash = "47772352", vanilla = true },
        progress = { it = "Hai scoperto chi conosceva il segreto di Thorsen? C'è un traditore tra noi?", enHash = "b46e83e9", vanilla = true },
        reward = { it = "Grazie, $N. Questo biglietto è l'indizio che ci serve per stanare il traditore!", enHash = "94877eb7", vanilla = true },
    },
    [330] = {
        title = { it = "I turni di pattuglia", enHash = "f0e897e8", vanilla = true },
        text = { it = "Il biglietto che mi hai dato è firmato con una \"-M\"... non so cosa possa significare.\n\nMa... il biglietto dice anche che la settimana scorsa questa persona ha condiviso i percorsi di pattuglia con Thorsen. Quindi chiunque abbia fatto la pattuglia con Thorsen la settimana scorsa dev'essere il traditore!\n\nVa' da Corporal Sethman. Si occupa dei turni di pattuglia e può dirti chi era con Thorsen.", enHash = "a8538a51", vanilla = true },
        objectives = { it = "Parla con Corporal Sethman.", enHash = "7897adb6", vanilla = true },
        reward = { it = "Oh, sì, posso controllarlo io per te. Vediamo... la settimana scorsa c'era...\n\n...ma guarda, in turno con Thorsen c'era Private Merle. Hanno avuto gli stessi orari di pattuglia per tutta la settimana scorsa.", enHash = "b95cb81c", vanilla = true },
    },
    [331] = {
        title = { it = "Rapporto a Doren", enHash = "95689bb7", vanilla = true },
        text = { it = "Lieutenant Doren voleva che tornassi a fargli rapporto con quelle informazioni sulle pattuglie?", enHash = "a472bc28", vanilla = true },
        objectives = { it = "Parla con Lieutenant Doren.", enHash = "6b193b9b", vanilla = true },
        reward = { it = "Mi addolora scoprire che è stato Merle a tradirci. È sempre stato un soldato coraggioso, e credevo che il suo cuore fosse leale. Ma è un gran sollievo averlo smascherato — con una spia come lui tra noi... non resisteremmo a lungo contro Colonel Kurzen.", enHash = "95dbdeb6", vanilla = true },
    },
    [332] = {
        title = { it = "Pubblicità per l'enoteca", enHash = "f7c772a7" },
        text = { it = "Se parli di vino con qualcuno, allora sai che noi Gallina vendiamo il vino migliore di Stormwind. E non siamo lontani, sempre nel Trade District lungo i bei canali della città.\n\nTieni, prendi questo volantino. Portalo a mia sorella Suzetta, alla nostra bottega, e avrai in omaggio una bottiglia del nostro famoso pinot nero. Non te ne pentirai!", enHash = "7abd0994" },
        objectives = { it = "Va' alla Gallina Winery e porta a Suzetta Gallina il Wine Ticket per una bottiglia di vino gratis.", enHash = "d3dff243" },
        progress = { it = "Salve e $Gbenvenuto:benvenuta;, $Gsignore:signora;. Hai già assaggiato uno dei nostri ottimi vini?", enHash = { "0e25e2da", "356f2b86" } },
        reward = { it = "Ah, quindi hai visto Renato? Bene, ecco a te, $Gsignore:signora;. Una bottiglia del nostro pinot nero speciale. Non ne troverai uno uguale in tutta Azeroth!", enHash = { "d21e0b4c", "ade00b6f" } },
    },
    [333] = {
        title = { it = "Harlan ha bisogno di rifornimenti", enHash = "a8606ae4", vanilla = true },
        text = { it = "Ultimamente abbiamo lavorato parecchio. Sembra che tutti comprino armature e vestiti resistenti. Quasi come se si aspettassero una stagione fredda e dura...\n\nMa sono preoccupazioni per il futuro. La mia preoccupazione di oggi è che sto finendo i capi di maglia da vendere. Mi serve un altro carico dal nostro fornitore.\n\nSe puoi portare questa richiesta a Rema Schneider, al Canal Tailor and Fit Shop, te ne sarò molto grato.", enHash = "b809e914", vanilla = true },
        objectives = { it = "Va' al Canal Tailor Shop e porta a Rema Schneider la Cloth Request di Harlan Bagley.", enHash = "5aded779", vanilla = true },
        progress = { it = "Porti notizie da parte del signor Bagley?", enHash = "e6e6f681", vanilla = true },
        reward = { it = "Qui c'è scritto che gli affari di Harlan vanno a gonfie vele. È una buona notizia, ma mi chiedo perché la gente abbia bisogno di tutta quell'armatura. Non ho sentito parlare di nessuna guerra aperta... c'è qualcosa che i nobili non ci stanno dicendo?\n\nBe', grazie di aver portato la richiesta. Ecco il tuo compenso, e penserò io a far avere a Harlan i suoi rifornimenti.", enHash = "c40ed9bc", vanilla = true },
    },
    [334] = {
        title = { it = "Un pacco per Thurman", enHash = "ddc70678", vanilla = true },
        text = { it = "Mio figlio Thurman fa l'apprendista ai Larson Clothiers, nel Mage's Quarter. Oggi aveva fretta e ha dimenticato le forbici e gli aghi. So che $Gun grande:una grande; $C come te avrà compiti importanti per le mani, ma senza i suoi attrezzi Thurman non può fare il lavoro da apprendista!\n\nTi prego, $N. Puoi portargli il suo Sewing Kit? I Larson Clothiers sono uno dei due negozi di vestiti del Mage's Quarter: è quello più addentro, vicino alla Mage's Tower.", enHash = "284c2574", vanilla = true },
        objectives = { it = "Va' ai Larson Clothiers, nello Stormwind Mage Quarter, e dai a Thurman Schneider il suo Sewing Kit.", enHash = "28ffa9a7", vanilla = true },
        progress = { it = "Sei qui per comprare dei vestiti?", enHash = "deb3c453", vanilla = true },
        reward = { it = "Oh, accidenti! Pensavo che dimenticare il kit mi avrebbe liberato dal lavoro. Adesso immagino che dovrò aiutare i Larson a cucire...\n\nVabbè. Il divertimento verrà dopo, immagino.", enHash = "bc07a1b5", vanilla = true },
    },
    [335] = {
        title = { it = "Un intruglio per nobili", enHash = "8bbf9687", vanilla = true },
        text = { it = "Lord Wishock sta facendo parecchio rumore in seno all'House of Nobles. È venuto a sapere del nostro piccolo \"locale\" quaggiù e si sta dando da fare per un'indagine completa. Ho un piano per tenere Wishock \"occupato\", ma mi servirà il tuo aiuto.\n\nC'è un fiore che cresce nel Garden of Stalvan, alle porte di Darkshire. Questo fiorellino bianco si chiama Tear of Tilloa. Mi servirà anche una Musquash Root, che si trova solo proprio ai piedi delle cascate molto più in basso della Stonewrought Dam, nelle Wetlands.", enHash = "a5aef272", vanilla = true },
        objectives = { it = "Zardeth the Black Claw vuole che tu gli porti una Tear of Tilloa da Darkshire e una Musquash Root dalle Wetlands.", enHash = "d2368d02", vanilla = true },
        progress = { it = "Presto Wishock avrà abbastanza appoggi da procurarci molti guai. Sei già $Griuscito:riuscita; a procurarti la Tear of Tilloa o la Musquash Root?", enHash = "d403d3e7", vanilla = true },
        reward = { it = "Magnifico! Questi sì che sono campioni di qualità!", enHash = "b3835ec0", vanilla = true },
    },
    [336] = {
        title = { it = "Un intruglio per nobili", enHash = "8bbf9687", vanilla = true },
        text = { it = "Lord Wishock, come tutti gli uomini, ha le sue debolezze. La sua è la passione per il liquore. L'ipocrisia è sbalorditiva. Quello sciocco banale passa le giornate a cercare di far chiudere la nostra piccola \"taverna\", mentre passa le notti al piano di sopra ad accumulare un conto che non paga mai. Bene, vediamo come gli piace questo intruglio speciale che ho preparato per lui: la Black Claw Stout. Ha una bella botta, $N.\n\nPortagliela e vedi se gli piace. Con ogni probabilità quel vecchio sciocco bighellona per l'Hall of Petitioners.", enHash = "eb1488c5", vanilla = true },
        objectives = { it = "Porta la Black Claw Stout a Lord Wishock, all'Hall of Petitioners.", enHash = "440f92f1", vanilla = true },
        progress = { it = "Non vedi che sono occupato? Le mie parole devono essere ascoltate! Io sono molto importante per il futuro di questo Regno!\n\nOh... cos'hai lì? Ma sembra una bevanda rinfrescante...", enHash = "0d128365", vanilla = true },
        reward = { it = "Ah, grazie di avermi portato questa bella stout, servo. Ecco un rame per te. Ora togliti di torno e lasciami gustare la mia bevanda!", enHash = "b48db013", vanilla = true },
    },
    [337] = {
        title = { it = "Un vecchio libro di storia", enHash = "c2da8fe1", vanilla = true },
        text = { it = "Anche se la copertina di questo libro è rovinata dai graffi e incrostata di fango, sul dorso si legge ancora \"The History of Stormwind\". Aprendolo, sulla prima pagina si vede chiaro il sigillo della Stormwind Library.\n\nSembra che qualcuno abbia preso in prestito questo libro e non l'abbia mai restituito...", enHash = "72e7ac88", vanilla = true },
        objectives = { it = "Restituisci il libro \"The History of Stormwind\" alla Stormwind Library.", enHash = "cbb3b051", vanilla = true },
        progress = { it = "Ooh! Cos'è quel vecchio libro che hai lì? Posso vederlo??", enHash = "8d4047d5", vanilla = true },
        reward = { it = "Oh cielo! Questo libro non stava su questi scaffali da prima della ricostruzione di Stormwind, anni fa. Andrà restaurato, ovviamente, è messo male, ma sarà un onore metterlo nella nostra raccolta di libri rari.\n\nGrazie, $Gsignore:signora;. Prendi questo come pagamento per aver riportato il libro!", enHash = { "9a88bcea", "e733ed8a" }, vanilla = true },
    },
    [338] = {
        title = { it = "The Green Hills of Stranglethorn", enHash = "08df1c86", vanilla = true },
        text = { it = "Master Nesingwary si arrabbierà tantissimo se lo scopre!\n\nMi aveva affidato la correzione delle bozze del suo romanzo, The Green Hills of Stranglethorn. Andava tutto bene, ma una forte raffica di vento ha attraversato l'accampamento e ha sparpagliato le pagine dappertutto!\n\nHo recuperato quasi tutte le pagine, ma molte sono ancora sparse per la giungla. Raccogli le pagine per completare ciascuno dei quattro capitoli.\n\nTi aiuterò a metterle in ordine. Riportami i capitoli quando li avrai tutti e quattro.", enHash = "f22099f5", vanilla = true },
        objectives = { it = "Raccogli le pagine mancanti del manoscritto di The Green Hills of Stranglethorn. Quando tutti e quattro i capitoli saranno completi, riportali a Barnil.", enHash = "887c2eed", vanilla = true },
        progress = { it = "Hai già rimesso insieme i capitoli, $N?", enHash = "e6a9587d", vanilla = true },
        reward = { it = "Mi hai proprio risparmiato un mucchio di guai, $N! Non so come ringraziarti. Ormai non manca molto prima di vedere il libro di Master Nesingwary nelle biblioteche di tutto il mondo!", enHash = "02283f94", vanilla = true },
    },
    [339] = {
        title = { it = "Chapter I", enHash = "5adea156", vanilla = true },
        text = { it = "Il Chapter I era davvero avvincente! Master Nesingwary delinea lo sfondo della storia e menziona i suoi compagni di caccia, tra cui anche me!\n\nMa non è questo il punto. Vediamo quali pagine mancano ancora. Sembra che le pagine 1, 4, 6 e 8 siano ancora là fuori, da qualche parte nella giungla!", enHash = "96005405", vanilla = true },
        objectives = { it = "Porta le pagine 1, 4, 6 e 8 di Nesingwary's The Green Hills of Stranglethorn a Barnil Stonepot, per completare il Chapter I.", enHash = "078088cc", vanilla = true },
        progress = { it = "Non è che per caso sei $Griuscito:riuscita; a trovare le pagine 1, 4, 6 e 8? Ci servono solo quelle quattro per ricomporre il Chapter I.", enHash = "98026cbf", vanilla = true },
        reward = { it = "Finalmente! Il Chapter I è completo!", enHash = "677d7d3a", vanilla = true },
    },
    [340] = {
        title = { it = "Chapter II", enHash = "00f589d3", vanilla = true },
        text = { it = "Il Chapter II era pieno zeppo di storie emozionanti di caccia alla pantera e alla tigre. Mi prenderei a calci per aver lasciato volar via le pagine!\n\nSembra che io abbia recuperato tutte le pagine, tranne le pagine 10, 11, 14 e 16.", enHash = "635ea06f", vanilla = true },
        objectives = { it = "Porta le pagine 10, 11, 14 e 16 di Nesingwary's The Green Hills of Stranglethorn a Barnil Stonepot, per completare il Chapter II.", enHash = "55ff9d5f", vanilla = true },
        progress = { it = "Ci servono ancora le pagine 10, 11, 14 e 16 per completare il Chapter II, $N.", enHash = "152c5483", vanilla = true },
        reward = { it = "Il Chapter II è finalmente completo! Ben fatto!", enHash = "23be7e6f", vanilla = true },
    },
    [341] = {
        title = { it = "Chapter III", enHash = "1dbbb0f6", vanilla = true },
        text = { it = "Il Chapter III era il mio preferito. Racconta la prima preda di Sir Erlgadin e Lady Rouack con un fucile nanico. E la fine del Chapter III, accidenti, che suspense!\n\nMi sembra che ci servano ancora le pagine 18, 20, 21 e 24 per finire il capitolo. Quelle pagine sono là fuori, da qualche parte...", enHash = "188f0c76", vanilla = true },
        objectives = { it = "Porta le pagine 18, 20, 21 e 24 di Nesingwary's The Green Hills of Stranglethorn a Barnil Stonepot, per completare il Chapter III.", enHash = "c8970dbb", vanilla = true },
        progress = { it = "Hai avuto fortuna con le pagine 18, 20, 21 o 24? Sono le uniche che ci servono per ricomporre il Chapter III.", enHash = "85290f85", vanilla = true },
        reward = { it = "Uff! Ottimo lavoro, $N. Il Chapter III è di nuovo tutto intero!", enHash = "4a504938", vanilla = true },
    },
    [342] = {
        title = { it = "Chapter IV", enHash = "00f589e0", vanilla = true },
        text = { it = "Ah, il Chapter IV: il gran finale! E che finale è stato!\n\nCi mancano solo tre pagine per questo capitolo. Ci servono le pagine 25, 26 e 27 per ricomporre il Chapter IV.", enHash = "76cd6cdd", vanilla = true },
        objectives = { it = "Porta le pagine 25, 26 e 27 di Nesingwary's The Green Hills of Stranglethorn a Barnil Stonepot, per completare il Chapter IV.", enHash = "9260bf05", vanilla = true },
        progress = { it = "Ci servono solo tre pagine per finire il Chapter IV, $N. Hai già le pagine 25, 26 o 27?", enHash = "57bbe46b", vanilla = true },
        reward = { it = "Magnifico! Ora il Chapter IV è pronto!", enHash = "5ac50d5b", vanilla = true },
    },
    [343] = {
        title = { it = "A proposito di fortezza", enHash = "d26d2107", vanilla = true },
        text = { it = "Terrò un discorso sulla Fortezza dello Spirito, e vorrei recitare dei passi da un certo libro di metallurgia: \"The Stresses of Iron\". Una copia di questo libro dovrebbe essere nella Royal Library, dentro Stormwind Keep. Puoi recuperarmela? Se lo fai, che le benedizioni della Luce siano con te!\n\nLa Royal Library è molto grande, ma il bibliotecario capo, Milton Sheaf, conosce ogni scaffale come se fosse suo figlio. Parla con lui, il libro te lo troverà.", enHash = "b9f3b3f9", vanilla = true },
        objectives = { it = "Va' alla Royal Library, dentro Stormwind Keep, e parla con Milton Sheaf. Può trovarti il libro di metallurgia che serve a Brother Kristoff per il suo discorso.", enHash = "7aa6c420", vanilla = true },
        reward = { it = "Metallurgia? Ah sì, abbiamo molti libri sull'argomento, e siamo felici di aiutare Brother Kristoff con il suo discorso! Ora... qual era il libro preciso che serviva al buon fratello?", enHash = "28129c22", vanilla = true },
    },
    [344] = {
        title = { it = "Brother Paxton", enHash = "db78e6ac", vanilla = true },
        text = { it = "The Stresses of Iron? Sì, il libro lo conosco. Davvero buono, scritto dal minatore nano Margulf Blaggon qualche decennio fa. Ha passato quasi tutto il suo tempo nelle profondità delle montagne di Khaz Modan, a scavare minerale. Tipo sveglio!\n\nMa dov'ero rimasto? Ah sì, The Stresses of Iron! Temo che il libro sia stato spostato alla Northshire Abbey. Il custode della biblioteca dell'abbazia, Brother Paxton, voleva farne una copia per i suoi scaffali.\n\nMa è successo mesi fa. Mi chiedo perché ci stia mettendo tanto...", enHash = "8e401589", vanilla = true },
        objectives = { it = "Parla con Brother Paxton, alla Northshire Abbey.", enHash = "c23e1c55", vanilla = true },
        reward = { it = "Il signor Sheaf si chiede dove sia finito il suo libro? Be', è un po' imbarazzante. Il libro ce l'ho io, ma sto ancora facendo la mia copia e non sono proprio pronto a restituire l'originale!", enHash = "6a1284df", vanilla = true },
    },
    [345] = {
        title = { it = "Rifornimenti di inchiostro", enHash = "623dc4c7", vanilla = true },
        text = { it = "Volevo finire la mia copia di The Stresses of Iron, ma...\n\nBe', vedi, l'inchiostro per i libri che copio me lo faccio da solo. È una mia ricetta: non cola e non sbava, e asciuga molto in fretta. Purtroppo asciuga troppo in fretta! L'ultima partita si è seccata prima che finissi la copiatura, e non ho avuto modo di farne dell'altro!\n\nPer farne ancora mi serve del Rethban Iron Ore dalle Redridge Mountains. Il mio fornitore abituale è Foreman Oslow, a Lakeshire.", enHash = "bad83baf", vanilla = true },
        objectives = { it = "Parla con Foreman Oslow, a Lakeshire, e chiedigli del Rethban Iron Ore.", enHash = "0bdd8a4c", vanilla = true },
        reward = { it = "Ti serve cosa?? Forse non l'hai notato, ma siamo occupati a rinforzare le difese di Lakeshire e a riparare i danni dei recenti attacchi degli orchi. Se ti serve del Rethban Iron Ore, dovrai procurartelo da $Gsolo:sola;!", enHash = "7a9ddf4e", vanilla = true },
    },
    [346] = {
        title = { it = "Torna da Kristoff", enHash = "4a0381e1", vanilla = true },
        text = { it = "Ora che ho finito di copiare il libro, ecco l'originale di The Stresses of Iron. Grazie della pazienza e, se vedi Milton, digli per favore che mi dispiace per il lungo ritardo.", enHash = "ab857725", vanilla = true },
        objectives = { it = "Torna da Brother Kristoff, a Cathedral Square. Dagli il libro The Stresses of Iron.", enHash = "51ab13d5", vanilla = true },
        progress = { it = "Sei $Griuscito:riuscita; a trovare il libro?", enHash = "532ade7f", vanilla = true },
        reward = { it = "È proprio quello! Grazie, $N. Che la Luce splenda luminosa sul tuo corpo e sul tuo spirito!", enHash = "e57dabab", vanilla = true },
    },
    [347] = {
        title = { it = "Rethban Ore", enHash = "fd14d98a", vanilla = true },
        text = { it = "Il Rethban Ore prende il nome dall'uomo che per primo lo trovò, Bart Rethban. Fuso non è resistente come il ferro, ma il minerale ha un colore scuro e opaco che certi scrivani usano nelle loro tinture. Si trova nelle Rethban Caverns, a nord di qui.\n\nDi solito ne abbiamo un po' in magazzino, ma siamo troppo occupati a prepararci agli attacchi degli orchi per raccoglierne. E poi... adesso nelle Rethban Caverns vivono i Redridge Gnoll, e sono i loro Drudger a raccogliere il minerale.\n\nQuindi, se te ne serve, dovrai procurartelo da $Gsolo:sola;.", enHash = "3cf75638", vanilla = true },
        objectives = { it = "Raccogli 5 carichi di Rethban Ore e portali a Brother Paxton, alla Northshire Library.", enHash = "06c4f2f8", vanilla = true },
        progress = { it = "Ce l'hai il Rethban Ore?", enHash = "3b47a266", vanilla = true },
        reward = { it = "Oh, splendido! Posso usare questo minerale per fare la mia tintura, e poi finire di copiare The Stresses of Iron.\n\nGrazie, $N!", enHash = "d577cd80", vanilla = true },
    },
    [348] = {
        title = { it = "Febbre di Stranglethorn", enHash = "372dba99", vanilla = true },
        text = { it = "Sto male... così... tanto m-m-male...\n\n...ho preso la Febbre di Stranglethorn... virus m-m-mortale...\n\n...l'unica cura... è... è... mangiare il cuore di M-m-m-m-mokk the Savage... sfuggente bestia bianca...\n\n...Witch Doctor Unbagwa... l'unico che può e-e-evocarlo...\n\n...cerca Unbagwa nella grotta nascosta sul capo meridionale...\n\n...fa' presto... sto morendo... morendo...", enHash = "20afda36", vanilla = true },
        objectives = { it = "Trova Witch Doctor Unbagwa e fagli evocare Mokk the Savage. Porta l'Heart of Mokk a Fin Fizracket.", enHash = "45efe324", vanilla = true },
        progress = { it = "...mamma?\n\n...che freddo...\n\n...sto andando nel Twisting Nether... t-t-t-tienimi, mamma...", enHash = "7b8179e5", vanilla = true },
        reward = { it = "...sento tornare le forze...\n\nDove sono? A Booty Bay? Oh, cielo! Ho fatto un sogno stranissimo...\n\n...la debolezza non mi ha ancora lasciato del tutto...", enHash = "4a535bee", vanilla = true },
    },
    [349] = {
        title = { it = "Febbre di Stranglethorn", enHash = "372dba99", vanilla = true },
        text = { it = "Testo temporaneo 02 — descrizione.", enHash = "c858fe32", vanilla = true },
        objectives = { it = "Testo temporaneo 02 — registro.", enHash = "a5c5b37a", vanilla = true },
        progress = { it = "Witch Doctor Unbagwa sapere cosa piacere a Mokk the Savage. Sì, sì!\n\nIo parlare con spiriti e fare venire lui, io fare.\n\nMa anche altre bestie-gorilla piacere parlare con spiriti. Tu proteggere Witch Doctor Unbagwa e io fare venire lui da te.\n\nWitch Doctor Unbagwa volere prima qualcosa. Tu portare 10 Gorilla Fang e io cominciare parlare con spiriti!", enHash = "f7c57a50", vanilla = true },
        reward = { it = "A Witch Doctor Unbagwa piacere Gorilla Fang! Per te io parlare con spiriti. Fare venire Mokk the Savage.\n\nMa tu proteggere Witch Doctor Unbagwa da altre bestie-gorilla, o niente Mokk per te!", enHash = "5363bb07", vanilla = true },
    },
    [350] = {
        title = { it = "Rivolgiti a un vecchio amico", enHash = "3b48b306", vanilla = true },
        text = { it = "Che Marzon sia in contatto con un membro dei Defias e abbia legami con Lescovar...\n\nAvendo ucciso VanCleef e Thredd, sarà difficile vedere Lescovar portato davvero davanti alla giustizia: le tue prove non valgono niente senza le loro testimonianze. E questo senza nemmeno considerare che Lescovar è un nobile e ha ottimi agganci. Di fatto lo mette al di sopra della legge.\n\nTi servirà altro aiuto. Mi ripugna farlo, ma conosco qualcuno che ci darà una mano. Trias lo trovi nel Trade District della città.", enHash = "ce0bb683", vanilla = true },
        objectives = { it = "Parla con Elling Trias, a Stormwind.", enHash = "48d31969", vanilla = true },
        reward = { it = "Stai scherzando? Shaw vuole di nuovo il mio aiuto? Ma che faccia tosta...\n\nLa Defias Brotherhood, dici? Be', sei proprio $Gportatore:portatrice; di notizie meravigliose, eh? Adesso mi dirai che Deathwing è ancora vivo e sta attaccando la città.\n\nVa bene, raccontami tutto dall'inizio. E non tralasciare niente che ti sembri poco importante. Devo sapere tutto.", enHash = "9b598cba", vanilla = true },
    },
    [353] = {
        title = { it = "La consegna per Stormpike", enHash = "4431256c", vanilla = true },
        text = { it = "Gli Stormpike sono un clan nanico rispettato, noto per i suoi gusti raffinati ed esigenti. Non c'è da stupirsi, quindi, che Gringer Stormpike, un Mountaineer di Ironforge, mi abbia commissionato un'arma.\n\nL'arma è finita, ma... Mountaineer Stormpike è lontano, nella remota Loch Modan. Se hai in programma di viaggiare verso nord, puoi consegnargli questo pacco?\n\nL'ultimo messaggio di Mountaineer Stormpike diceva che è di stanza alla torre di guardia settentrionale, a Loch Modan.", enHash = "166df94e", vanilla = true },
        objectives = { it = "Consegna il Package for Stormpike a Mountaineer Stormpike, a Loch Modan.", enHash = "c9a8e3e1", vanilla = true },
        progress = { it = "Vieni fin da Stormwind? Mi dicono che laggiù nelle terre degli umani si mette male, con briganti e orchi in giro. Il posto perfetto perché $Gun:una; $C possa dimostrare il proprio valore!", enHash = "79d3f958", vanilla = true },
        reward = { it = "Aha! Quindi Grimand ha finalmente finito la mia ascia! Non vedo l'ora di provarla su qualche trogg e qualche kobold!\n\nMille grazie, $N. È stato un bel viaggio per questa consegna. Ecco qualche moneta per il disturbo.", enHash = "3441fd09", vanilla = true },
    },
    [354] = {
        title = { it = "Morti in famiglia", enHash = "dc2f89ed" },
        text = { it = "La famiglia Agamand era la più prospera delle Tirisfal Glades. Lavoravo ai loro mulini... prima della Piaga.\n\nQuando arrivò il Flagello, gli Agamand fortificarono la loro casa e convinsero chi era al loro servizio a restare e ad aiutarli a difenderla. Eravamo degli sciocchi, ma almeno eravamo sciocchi leali.\n\nGli Agamand, nel loro orgoglio, ci condannarono alla non morte. E ora sono servi del Flagello!\n\nServi i Reietti sconfiggendo gli Agamand che caddero per la Piaga. Servi me portandomi i loro resti.", enHash = "009fbe9e" },
        objectives = { it = "Porta Gregor's Remains, Nissa's Remains e Thurman's Remains a Coleman Farthing, a Brill.", enHash = "f1a1c95e" },
        progress = { it = "Hai i resti degli Agamand? Quelle bestie maledette sono finalmente distrutte?", enHash = "9bc78e43", vanilla = true },
        reward = { it = "La vendetta ha un sapore dolce, non trovi? Quando hai distrutto gli Agamand, hai colto in loro un accenno di libero arbitrio? Lo spero. Spero che abbiano conosciuto la paura prima di essere ridotti in polvere.\n\nÈ una speranza sciocca, lo so. Ma è una speranza che coltivo lo stesso.", enHash = "3c7db28d", vanilla = true },
    },
    [355] = {
        title = { it = "Parla con Sevren", enHash = "cd68df03", vanilla = true },
        text = { it = "Mi hai dato i resti degli Agamand e hai soddisfatto il mio desiderio di vendetta. Ma gli Agamand Mills sono una minaccia per tutti i Reietti, non solo per me.\n\nHo parlato a Magistrate Sevren delle tue imprese contro gli Agamand, e desidera parlare con te.", enHash = "31bc92c7", vanilla = true },
        objectives = { it = "Parla con Magistrate Sevren, a Brill.", enHash = "09539da4", vanilla = true },
        reward = { it = "Coleman parla bene di te, $N, e racconta delle tue incursioni riuscite negli Agamand Mills.\n\nI Reietti hanno di nuovo bisogno delle tue doti...", enHash = "22f830ca", vanilla = true },
    },
    [356] = {
        title = { it = "Pattuglia di retroguardia", enHash = "0c2ed923" },
        text = { it = "I difensori del Bulwark che proteggono Tirisfal dalle Plaguelands sono in allerta costante. Ma a volte qualche creatura del Flagello riesce a passare.\n\nIl nostro successo al Bulwark dipende dal combattere su un solo fronte: non possiamo permettere un attacco alle spalle, né che la linea di rifornimento dei nostri difensori venga tagliata.\n\nAiuta il Bulwark. Pattuglia a est e uccidi ogni creatura del Flagello che trovi. Dedica un impegno particolare alla Balnir Farmstead, a est: è diventata un rifugio per le creature del Flagello che si infiltrano.", enHash = "0cdffa85" },
        objectives = { it = "Uccidi 8 Bleeding Horror e 8 Wandering Spirit, poi torna a fare rapporto a Linnea, al suo accampamento.", enHash = "2eee1e12" },
        progress = { it = "Hai un rapporto sulla tua pattuglia?", enHash = "62e43504", vanilla = true },
        reward = { it = "Molto bene. Il tuo impegno fa molto per tenere a bada il Flagello. Manderò un encomio al mio superiore, Executor Zygand.", enHash = "346671fd", vanilla = true },
    },
    [357] = {
        title = { it = "L'identità del lich", enHash = "e7630fa1", vanilla = true },
        text = { it = "C'è un lich che dimora sull'isola del Brightwater Lake, a nord. Anche se è un Reietto dotato di libero arbitrio, crede che tutti gli altri non morti siano schiavi del Flagello e fa attaccare dai suoi servitori chiunque gli si avvicini.\n\nMa proprio perché è un Reietto, la Regina lo vorrà. E se è esperto di negromanzia, la sua conoscenza sarebbe... molto utile per noi.\n\nPer scoprire la sua identità e i suoi talenti, devo vedere il suo libro di incantesimi. Intrufolati nel suo accampamento e prendilo, poi torna da me.", enHash = "94c11924", vanilla = true },
        objectives = { it = "Porta il Lich's Spellbook a Bethor Iceshard, nell'Undercity.", enHash = "4e5858ad", vanilla = true },
        progress = { it = "$N, hai recuperato il libro?", enHash = "0d033790", vanilla = true },
        reward = { it = "Molto bene, $N. Studierò questo libro e scoprirò l'identità di quel lich. Hai servito bene la tua Regina.\n\n<Bethor apre il libro e ne fissa intensamente le pagine luminose...>\n\nSorprendente! Il libro che hai recuperato appartiene nientemeno che a Gunther Arcanus!\n\nGunther era un abile negromante in vita; lui e io eravamo amici e compagni d'armi, prima della Piaga. E a giudicare dal suo libro, da morto è diventato ancora più potente.\n\nLe sue abilità ci sarebbero di grande aiuto.", enHash = "b96d74df", vanilla = true },
    },
    [358] = {
        title = { it = "Profanatori di tombe", enHash = "9b0a4364" },
        text = { it = "Le fosse comuni, a sud-ovest di Garren's Haunt, a nord, furono scavate per contenere il... notevole... numero di morti che Tirisfal subì quando arrivò la Piaga.\n\nFinora i corpi in quelle fosse sono stati risparmiati dalla non morte, ma ora il Flagello manda gli gnoll Rot Hide a raccogliere i cadaveri e a usarli per ingrossare i suoi eserciti. Non lo si può permettere!\n\nIl tuo compito è duplice: uccidi i Rot Hide alla fossa comune e a Garren's Haunt, e prendi da loro l'Embalming Ichor che dà loro la vita.", enHash = "63f2f440" },
        objectives = { it = "Uccidi Rot Hide Graverobber e Rot Hide Mongrel.\n\nPorta 8 Embalming Ichor a Magistrate Sevren, a Brill.", enHash = "caa5cab7" },
        progress = { it = "Il tuo compito è concluso? Hai distrutto quegli esseri cagneschi e li hai svuotati del loro icore?", enHash = "ddbf4464", vanilla = true },
        reward = { it = "Fatto da maestro, $N. Il Flagello si sbaglia se crede di poter usare quei cadaveri contro di noi, e il fluido che hai raccolto dagli schiavi Rot Hide sarà studiato dai nostri speziali. Potrebbe nascondere segreti utilizzabili contro di loro.\n\nCome ho detto, ben fatto. Ma la nostra lotta continua, e il conflitto ti offrirà di sicuro altre occasioni per dimostrare il tuo valore ai Reietti.", enHash = "3837ebb1", vanilla = true },
    },
    [359] = {
        title = { it = "Doveri dei Reietti", enHash = "5ceb1d57", vanilla = true },
        text = { it = "Mi serve un rapporto aggiornato dalla stazione di sosta della Guardiamorte, a est.\n\nDevo sapere se altre forze del Flagello sono filtrate oltre il Bulwark ed entrate in Tirisfal. La nostra vigilanza sul confine con le Plaguelands va mantenuta: non possiamo lasciare che il Flagello prenda piede più saldamente qui!\n\nVa' a sud lungo la strada, poi a est al bivio, fino alla stazione di sosta. Parla con Deathguard Linnea. È lei ad avere le informazioni che mi servono.", enHash = "95100fc4", vanilla = true },
        objectives = { it = "Parla con Deathguard Linnea.", enHash = "56d024d2", vanilla = true },
        reward = { it = "Magistrate Sevren vuole un rapporto? E va bene: i difensori del Bulwark tengono a bada la maggior parte del Flagello, ma qualcuno ogni tanto passa.\n\nAbbiamo visto attività sporadica del Flagello a est di questa stazione, con una concentrazione intorno alla Balnir Farmstead.", enHash = "d7ca2f25", vanilla = true },
    },
    [360] = {
        title = { it = "Torna dal magistrato", enHash = "4063181b", vanilla = true },
        text = { it = "Ora torna da Magistrate Sevren con le informazioni che ti ho dato. Le vorrà il prima possibile, quindi sii veloce.\n\nE se sulla via del ritorno incontri creature del Flagello, abbattile: non possiamo lasciarle vagare indisturbate per le nostre terre.", enHash = "a73c8bef", vanilla = true },
        objectives = { it = "Torna da Magistrate Sevren, a Brill.", enHash = "2e10ec3b", vanilla = true },
        reward = { it = "È preoccupante sentire che il Flagello riesce a passare oltre il Bulwark. Il Re dei Lich e i suoi servi non danno tregua nei loro assalti.\n\nMa noi non cederemo. Non ci prenderà di nuovo!", enHash = "80dc45f6", vanilla = true },
    },
    [361] = {
        title = { it = "Una lettera mai consegnata", enHash = "6663e730", vanilla = true },
        text = { it = "Questa è una lettera scritta da Thurman, il figlio maggiore di Gregor Agamand. È indirizzata a una certa Yvette Farthing, ma non sembra esserle mai arrivata...", enHash = "8f7eed91", vanilla = true },
        objectives = { it = "Trova Yvette Farthing e consegnale la lettera di Thurman Agamand.", enHash = "d66fa170", vanilla = true },
        progress = { it = "Sì?", enHash = "00388a38", vanilla = true },
        reward = { it = "Oh... il mio povero Thurman! L'avevo supplicato di lasciare Agamand Mills con me e mio padre, ma la sua lealtà alla famiglia era troppo forte! E lo sapevo! Lo sapevo che Brand voleva fargli del male!! Oh, maledetta questa Piaga, e maledetto il Flagello!\n\n<Il viso di Yvette si distende e si fa freddo.>\n\nMa i rimpianti sono per i deboli. Ora che sono una Reietta, ho nuovi obiettivi, e l'amore non è tra questi. Ti ringrazio per aver consegnato questa lettera: mi ero chiesta che fine avesse fatto il mio amore di un tempo.\n\nMa quella vita è finita. Per sempre.", enHash = "dc343386", vanilla = true },
    },
    [362] = {
        title = { it = "I mulini infestati", enHash = "c4b80f09" },
        text = { it = "Devlin Agamand era il minore dei due figli della famiglia Agamand, e in vita i due non avrebbero potuto essere più diversi. Thurman era alto e gentile, mentre il fratello minore era debole e aveva la lingua tagliente.\n\nQuando gli Agamand Mills caddero per la Piaga, non mi sorprese sentire che Devlin era stato tra i primi a soccombere. Il suo farneticare folle si sente ancora vicino alla strada che porta agli Agamand Mills.\n\nSto raccogliendo i resti degli Agamand, e voglio il povero Devlin. Trovalo, distruggilo e portami le sue ossa.", enHash = "727cbd01" },
        objectives = { it = "Uccidi Devlin Agamand e porta Devlin's Remains a Coleman Farthing, a Brill.", enHash = "465432c1" },
        progress = { it = "Hai trovato Devlin?", enHash = "b123b9de", vanilla = true },
        reward = { it = "Grazie. Le ossa di Devlin staranno benissimo sulla mia mensola.\n\nSe il mio cuore freddo può trovare un po' di calore, è nel sapere che gli Agamand sono distrutti. Hanno tradito me e la mia famiglia quando arrivò la Piaga: ora giuro che schiaccerò i loro resti sotto il tacco!", enHash = "89f680ab", vanilla = true },
    },
    [363] = {
        title = { it = "Un brusco risveglio", enHash = "1ea2cc9d" },
        text = { it = "Era ora che ti svegliassi. Stavamo per gettarti nel fuoco insieme agli altri, ma a quanto pare ce l'hai fatta.\n\nIo sono Mordo, il custode della cripta di Deathknell. E tu non sei più $Glo schiavo:la schiava; del Re dei Lich.\n\nParla con Shadow Priest Sarvis, nella cappella ai piedi della collina: ti dirà il resto di ciò che devi sapere.", enHash = "cd7a2241" },
        objectives = { it = "Parla con Shadow Priest Sarvis.", enHash = "52a3cdc5" },
        reward = { it = "$GUn altro morto:Un'altra morta; che cammina, eh? Dev'essere stato un bel colpo, svegliarsi nella cripta con solo il freddo e Mordo ad accoglierti...\n\nVedo la confusione sul tuo volto. Lascia che provi a spiegarti la nostra... situazione...\n\nLa nostra nuova guida, Lady Sylvanas, ci ha liberati dal controllo del Re dei Lich. La Signora Oscura ci guida nella guerra contro l'odiato Flagello e contro gli ultimi baluardi dell'umanità, che ci braccano a ogni passo.", enHash = "614d3976" },
    },
    [364] = {
        title = { it = "I Senza Mente", enHash = "0e76f773" },
        text = { it = "Noi Reietti siamo in guerra con il Flagello, l'esercito del Re dei Lich: armate di non morti risvegliati con la negromanzia, bestie immonde del nord e spettri tormentati.\n\nLa parte settentrionale del villaggio è stata invasa dai Senza Mente, e vanno distrutti. Distruggili senza pietà, anche se un tempo erano nostri fratelli e sorelle. I Caduti non sono altro che schiavi del Re dei Lich.", enHash = "9b45fa92" },
        objectives = { it = "Shadow Priest Sarvis vuole che tu uccida 8 Mindless Zombie e 8 Wretched Zombie.", enHash = "77516160" },
        progress = { it = "Non andrai lontano in questa nuova vita se non riesci a uccidere nemmeno il più debole degli zombi, $N. Non tornare finché non avrai qualche successo da riferire.", enHash = "8397d08e" },
        reward = { it = "È un peccato non poter portare il Flagello dalla nostra parte: le sue schiere sterminate ci farebbero comodo nelle battaglie che ci attendono.\n\nMa non si unirà mai a noi, quindi non abbiamo altra scelta che distruggerlo.", enHash = "d3e85f4e" },
    },
    [365] = {
        title = { it = "Campi di dolore", enHash = "93c2e3fd", vanilla = true },
        text = { it = "Cosa abbiamo qui? Sembri $Gun novellino:una novellina; $C. Se speri di dimostrare il tuo valore alla Signora Oscura, devi imparare le usanze dei Reietti.\n\nA ovest troverai una fattoria. Gli umani infestano la terra come la muffa su un cadavere in putrefazione. E, peggio ancora, la Crociata Scarlatta pattuglia i dintorni dalla sua torre. Dai una lezione a quella feccia e ruba loro 10 delle preziose zucche.\n\nQuando ne avrai 10, portale ad Apothecary Johaan, a Brill.", enHash = "5bb32764", vanilla = true },
        objectives = { it = "Ruba 10 zucche dalla fattoria a ovest, appena a nord di Deathknell, e portale ad Apothecary Johaan, a Brill.", enHash = "7251e1df", vanilla = true },
        progress = { it = "Deathguard Simmer ha mandato a dire che mi avresti procurato dei reagenti di cui ho gran bisogno. Sei già $Griuscito:riuscita; a raccogliere 10 zucche, $N?", enHash = "c1faa86b", vanilla = true },
        reward = { it = "Hai eseguito bene gli ordini, giovane $C. Ti stai rivelando $Gprezioso:preziosa; per l'esercito della Signora Oscura.", enHash = "b869ccdb", vanilla = true },
    },
    [366] = {
        title = { it = "Restituisci il libro", enHash = "c3948228", vanilla = true },
        text = { it = "Molto tempo fa io e Gunther, insieme a Thule Ravenclaw, che ora è un negromante del Flagello, eravamo amici e studenti nel Kirin Tor, una società di maghi di Dalaran.\n\nIo e Gunther cademmo entrambi per la Piaga, ma pensavo che lui fosse rimasto morto o fosse stato risvegliato tra le file del Re dei Lich. È bello sapere che è libero.\n\nDobbiamo averlo con noi. Ho lanciato sul suo libro un incantesimo che, quando lo vedrà, gli mostrerà che anch'io sono libero dal Re dei Lich. Sapendolo, spero che si unirà a noi.", enHash = "2a3b0849", vanilla = true },
        objectives = { it = "Restituisci Gunther's Spellbook a Gunther, sull'isola di Gunther's Retreat.", enHash = "3689583b", vanilla = true },
        progress = { it = "I tuoi padroni sono degli sciocchi a mandarti qui, perché non sarò mai più schiavo del Flagello!", enHash = "725d8c6b", vanilla = true },
        reward = { it = "Il mio libro?!? Allora eri tu $Gil ladro:la ladra; che l'ha rubato!\n\nMa... cos'è questo nuovo incantamento che ci è stato messo sopra... Bethor? È a Lordaeron?\n\nSe esiste ancora, allora forse anche lui è sfuggito alla presa del Re dei Lich...", enHash = "d823e44a", vanilla = true },
    },
    [367] = {
        title = { it = "Una nuova piaga", enHash = "a92604d1", vanilla = true },
        text = { it = "Lady Sylvanas si è rivolta alla Royal Apothecary Society. La Signora Oscura crede che la nostra conoscenza, unita alla nuova magia, sarà la chiave della caduta di Arthas. Ci ha sfidati a preparare una nuova piaga, una piaga più letale di qualunque male su Azeroth. Questa nuova malattia manderà in rovina l'esercito del Flagello di Arthas.\n\nI miei studi indicano che il sangue delle bestie potrebbe essere la chiave. Portami 5 Vial of Darkhound Blood, così potrò mettere alla prova la mia teoria.", enHash = "09630961", vanilla = true },
        objectives = { it = "Apothecary Johaan, nella città di Brill, vuole che tu raccolga 5 Vial of Darkhound Blood.", enHash = "60c33e3d", vanilla = true },
        progress = { it = "Hai già raccolto 5 Vial of Darkhound Blood, $N? Il tempo stringe!", enHash = "9502679e", vanilla = true },
        reward = { it = "Hai fatto bene, $N, e ti ringrazio per il tuo impegno.", enHash = "a42365f9", vanilla = true },
    },
    [368] = {
        title = { it = "Una nuova piaga", enHash = "a92604d1" },
        text = { it = "Mentre raccoglievi i campioni per me, i miei esperimenti mi hanno fatto capire che serviranno altri reagenti perché questa nuova malattia si diffonda come si deve. Avvelenare qualche sventurato è un gioco da ragazzi. Appestare un mondo intero si rivela un po' più complicato.\n\nMi serviranno 5 Vile Fin Scale dai murloc dei dintorni. Troverai quelle creature lungo la costa a nord o a ovest.", enHash = "17f9b722" },
        objectives = { it = "Apothecary Johaan, della città di Brill, ha bisogno di 5 Vile Fin Scale prese dai murloc delle Tirisfal Glades.", enHash = "72a1deef" },
        progress = { it = "$N, sei $Griuscito:riuscita; a ottenere 5 Vile Fin Scale dai murloc?", enHash = "8bf57e14", vanilla = true },
        reward = { it = "Le scaglie sono perfette, $N. Esattamente ciò che mi serviva per questa mistura.", enHash = "210c564f", vanilla = true },
    },
    [369] = {
        title = { it = "Una nuova piaga", enHash = "a92604d1", vanilla = true },
        text = { it = "Mentre eri in giro a raccogliere, ho scoperto un vecchio testo in uno dei miei tomi che racconta di un'antica piaga che sterminò migliaia di vittime innocenti. In seguito si scoprì che l'agente letale di quella piaga si era conservato nel veleno dei Night Web Spider.\n\nPortami un po' di veleno di Vicious Night Web Spider per completare questo esperimento. Voglio vedere se l'elemento contagioso del veleno funzionerà con la mia nuova mistura. Si dice che i ragni si trovino nelle Tirisfal Glades orientali.", enHash = "c579f4da", vanilla = true },
        objectives = { it = "Apothecary Johaan, nella città di Brill, vuole che tu gli porti 4 campioni di veleno di Vicious Night Web Spider.", enHash = "45a89f15", vanilla = true },
        progress = { it = "Hai già un po' di veleno di Vicious Night Web Spider, $N? È l'ultimo componente che mi serve per provare il mio esperimento.", enHash = "fb09b1b9", vanilla = true },
        reward = { it = "Ah, questo veleno andrà a meraviglia, $N. Tutto il resto è stato aggiunto alla mia mistura e fatto ridurre. Finalmente sono pronto a provare questo nuovo agente letale!", enHash = "54758651", vanilla = true },
    },
    [370] = {
        title = { it = "In guerra con la Crociata Scarlatta", enHash = "2fcd170b" },
        text = { it = "I documenti strategici di Executor Arren contengono tutti i dettagli che ci servono per cancellare l'infestazione umana da queste terre. Secondo le informazioni, la Crociata Scarlatta ha assegnato Captain Perrine e una brigata alla torre in rovina a sud-ovest di Brill.\n\nUccidi Perrine insieme a 3 Zealot e 3 Missionary, poi torna a fare rapporto.", enHash = "fce67e6b" },
        objectives = { it = "Executor Zygand, a Brill, vuole che tu uccida Captain Perrine, 3 Scarlet Zealot e 3 Scarlet Missionary.", enHash = "c7bad693" },
        progress = { it = "Giovane $C, non dovresti sprecare il tuo tempo qui a Brill mentre la tua gente ha bisogno che tu combatta per la sua causa. Ora prendi le armi, va' a sud-ovest, alla torre in rovina, e uccidi Captain Perrine insieme a 3 Scarlet Zealot e 3 Scarlet Missionary. Condurremo la Crociata Scarlatta al macello come bestiame.", enHash = "5b51ce05", vanilla = true },
        reward = { it = "La morte di Captain Perrine farà senza dubbio piacere alla Signora Oscura. Hai svolto bene il tuo dovere, $C.", enHash = "e5f343ea", vanilla = true },
    },
    [371] = {
        title = { it = "In guerra con la Crociata Scarlatta", enHash = "2fcd170b", vanilla = true },
        text = { it = "Siamo ancora in guerra, e la Crociata Scarlatta si fa sempre più forte. Il rapporto che mi ha mandato Executor Arren indica che i crociati scarlatti hanno condotto razzie dalla torre in rovina di Tirisfal sud-orientale, vicino alla Balnir Farmstead, al comando di Captain Vachon.\n\nUccidi Vachon insieme a 5 Scarlet Friar. Dovrebbe essere un colpo devastante per la Crociata!", enHash = "8d274b1c", vanilla = true },
        objectives = { it = "Executor Zygand, a Brill, ti ha incaricato di uccidere Captain Vachon e 5 Scarlet Friar.", enHash = "a03a41b7", vanilla = true },
        progress = { it = "Vedo che sei $Gtornato:tornata;, ma il tuo compito non è concluso. Forse ti sta bene che dei semplici umani interferiscano con il piano della Signora Oscura? Oppure sai rispondere alla chiamata del dovere e uccidere Captain Vachon e la sua banda di Scarlet Friar!", enHash = "2b6b7ec7", vanilla = true },
        reward = { it = "La morte di Captain Vachon rallenterà parecchio l'avanzata della Crociata Scarlatta in Tirisfal. Ma incombono altre minacce.", enHash = "f630f006", vanilla = true },
    },
    [372] = {
        title = { it = "In guerra con la Crociata Scarlatta", enHash = "2fcd170b", vanilla = true },
        text = { it = "I crociati scarlatti hanno condotto razzie dalla torre in rovina di Tirisfal settentrionale, oltre Faol's Rest. Secondo le informazioni che abbiamo, a capo di quella banda malvagia c'è un comandante spietato di nome Captain Melrache.\n\nOra ti affido una missione speciale e pericolosa. Uccidi Melrache e le sue due guardie del corpo, nel nome della Signora Oscura.", enHash = "97d3524e", vanilla = true },
        objectives = { it = "Executor Zygand, nella città di Brill, vuole che tu assassini Captain Melrache e le sue due guardie del corpo.", enHash = "e364115e", vanilla = true },
        progress = { it = "Non hai ancora compiuto il tuo dovere, $C. Non possiamo sperare di portare avanti il piano della Signora Oscura con la Crociata Scarlatta che tormenta i nostri soldati. Mandali a morte e compi il tuo dovere verso Sylvanas!", enHash = "26db73ca", vanilla = true },
        reward = { it = "Hai fatto estremamente bene, $C. Con combattenti spietati come te che conquistano nel nome dei Reietti, la nostra razza è un passo più vicina a sconfiggere Arthas una volta per tutte. Ho un buon presentimento su di te, $Gcompagno:compagna;.", enHash = "d173fb16", vanilla = true },
    },
    [373] = {
        title = { it = "La lettera mai spedita", enHash = "95ba6406", vanilla = true },
        text = { it = "Frugando addosso a Edwin VanCleef, tra le altre cose scopri una lettera mai spedita. È indirizzata a Baros Alexston, il City Architect di Stormwind, City Hall, Cathedral Square.\n\nSembra scritta e sigillata di recente.", enHash = "7bf54488", vanilla = true },
        objectives = { it = "Consegna la Letter to the City Architect a Baros Alexston, a Stormwind.", enHash = "bd3cb3e8", vanilla = true },
        progress = { it = "Sì? C'è qualcosa in cui posso aiutarti?", enHash = "965a86b0", vanilla = true },
        reward = { it = "Edwin VanCleef, dici? Mi sarei aspettato più facilmente una lettera da mia nonna morta... Quindi l'hai ucciso? Perdonami se lo dico, ma sono un po' sorpreso. Da giovane era un combattente senza pari. Vediamo cosa sente il bisogno di scrivermi dopo tutti questi anni.\n\n<Baros scorre la lettera.>\n\nEdwin... Vedo che gli anni non ti hanno cambiato di una virgola, idealista come sempre, e romantico. Non gli importa chi fa soffrire, $N. La vendetta lo ha divorato. Ma poi, non sono sicuro di potergliene fare una colpa.", enHash = "533135c5", vanilla = true },
    },
    [374] = {
        title = { it = "Prova della morte", enHash = "7c789b7c" },
        text = { it = "Executor Zygand mi dice che sei $Gstato:stata; in giro a uccidere crociati scarlatti. Le Tirisfal Glades ne brulicano.\n\nVarimathras, luogotenente della Signora Oscura, si sta occupando di persona di cancellare dalla faccia della terra la feccia di Azeroth, la razza umana. Qui nelle Tirisfal Glades affrontiamo una razza di umani particolarmente fastidiosa: la Crociata Scarlatta.\n\nParti all'attacco della Crociata Scarlatta, $C. Riportami 10 Scarlet Insignia Ring come prova della tua lealtà a Varimathras e alla Signora Oscura.", enHash = "0b353de5" },
        objectives = { it = "Porta 10 Scarlet Insignia Ring a Deathguard Burgess, a Brill.", enHash = "57bdf9f9" },
        progress = { it = "Hai già raccolto 10 Scarlet Insignia Ring, $C?", enHash = "ad3460d0", vanilla = true },
        reward = { it = "Varimathras ne sarebbe fiero. Servi bene i tuoi capi, $C.", enHash = "5c1137da", vanilla = true },
    },
    [375] = {
        title = { it = "Il gelo della morte", enHash = "39a1a1f6" },
        text = { it = "Ora fa così freddo. La Piaga della Non Morte mi striscia nelle vene come un serpente di ghiaccio. Lo Stato Senza Mente mi raggiungerà presto. Ma nessun destino segnato mi impedirà di servire la nostra Signora Oscura. Quando arrivò la chiamata, cucii sacchi per i cadaveri dei soldati caduti del possente esercito di Sylvanas.\n\nOra le mani mi tremano per il gelo. Se mi portassi cinque Duskbat Pelt e del Coarse Thread, potrei cucirmi una coperta. Aiutami, $N, così potrò continuare a servire la causa.", enHash = "eb772b8f" },
        objectives = { it = "Porta cinque Duskbat Pelt e del Coarse Thread a Gretchen Dedmar, a Brill.", enHash = "3ecb4e88" },
        progress = { it = "Hai già cinque Duskbat Pelt e del Coarse Thread, $N?", enHash = "299ef9b7", vanilla = true },
        reward = { it = "Apprezzo il tuo impegno, $N. Che un giorno Sylvanas riconosca il tuo coraggio...", enHash = "1828c659", vanilla = true },
    },
    [376] = {
        title = { it = "I Dannati", enHash = "35e1328c" },
        text = { it = "I miei compiti sono curare i nostri guerrieri feriti, confezionare armature e vestiti e aiutare Shadow Priest Sarvis in qualunque altra cosa gli serva.\n\nA quanto pare, anche tu verrai $Garruolato:arruolata; al suo servizio... a dare la caccia ai Senza Mente, se conosco i suoi piani. Be', se vuoi restare $Gtutto intero:tutta intera; (e non ho dubbi che tu lo voglia), forse posso aiutarti. Mi stanno finendo zampe e ali: se me ne porti un po', ti troverò un'armatura. A sud troverai parecchi lupi e pipistrelli.", enHash = "711f2579" },
        objectives = { it = "Novice Elreth ha bisogno di 6 Scavenger Paw e 6 Duskbat Wing.", enHash = "397154b2" },
        progress = { it = "Cerca di non farti male finché non ti avrò procurato un'armatura.", enHash = "47638e45" },
        reward = { it = "Grazie, $N. Quest'armatura dovrebbe esserti utile.\n\nSperiamo che serva più a te che all'ultimo che l'ha indossata...", enHash = "f32ed940" },
    },
    [377] = {
        title = { it = "Delitto e castigo", enHash = "cdab668a", vanilla = true },
        text = { it = "Come se trascurare gli abitanti di Duskwood non bastasse, ora l'House of Nobles sputa in faccia al Darkshire Council con la decisione di imprigionare Dextren Ward a Stormwind invece di decapitare quel criminale, come vuole la sentenza di Lord Ebonlocke.\n\nWard è stato colto a vendere a Morbent Fel i cadaveri del cimitero, un crimine punibile con la morte. Eppure Stormwind lo rivendica come proprio prigioniero.\n\nAssassina Ward nello Stormwind Stockade, portami la sua mano, e ti ricompenserò.", enHash = "7a997e66", vanilla = true },
        objectives = { it = "Councilman Millstipe, di Darkshire, vuole che gli porti la mano di Dextren Ward.", enHash = "255bd132", vanilla = true },
        progress = { it = "Finché a un profanatore di morti come Dextren Ward è concesso vivere, la giustizia resta tradita. Torna da me quando la condanna a morte di Lord Ebonlocke sarà eseguita su quel profanatore di Ward. Daremo alle famiglie dei morti la pace che meritano e, meglio ancora, manderemo un messaggio chiaro all'House of Nobles di Stormwind.", enHash = "81e91bf8", vanilla = true },
        reward = { it = "Così Dextren Ward ha finalmente pagato per i suoi crimini contro l'umanità? Ce ne siamo liberati, di quella feccia, dico io. E complimenti a te, $Gamico mio:amica mia;! Non solo hai dato alle famiglie dei morti la serenità che meritano, ma hai mandato un messaggio pungente a quei burocrati corrotti dell'House of Nobles. Stormwind deve farsi carico dei bisogni della gente di Duskwood, o ci libereremo dalla loro tirannia.", enHash = "dc2a88bb", vanilla = true },
    },
    [378] = {
        title = { it = "La furia scava a fondo", enHash = "6938ae09", vanilla = true },
        text = { it = "Hai dimostrato la tua lealtà a King Magni, $C. E il tuo odio per la feccia dei Dark Iron è grande quanto il mio.\n\nC'è un compito che vorrei portare a termine io stesso, ma l'onore mi lega a restare con Longbraid. Roggo però ha raccolto informazioni che provano che Kam Deepfury fu tra i cospiratori dell'attacco al Thandol Span. Fu per i piani di Deepfury che Longbraid perse i suoi cari.\n\nDeepfury è trattenuto per ragioni politiche nello Stormwind Stockade. Lo voglio morto, $N. Per Longbraid! Portami la sua testa!", enHash = "562ea4c3", vanilla = true },
        objectives = { it = "Motley Garmason vuole che la testa di Kam Deepfury gli sia portata a Dun Modr.", enHash = "ccde46e8", vanilla = true },
        progress = { it = "Non lascerò che la sciocca burocrazia umana si intrometta nelle questioni dei nani, $N. Kam Deepfury è un cospiratore accertato dell'attacco al Thandol Span. La brava gente di King Magni ha perso la vita per l'inganno di Deepfury. Gli umani si accontenteranno anche di lasciar marcire Deepfury nello Stockade, ma io non dormirò sonni tranquilli finché Deepfury non sarà ucciso.", enHash = "1d8adee2", vanilla = true },
        reward = { it = "Così Kam Deepfury ha finalmente provato cosa vuol dire finire nelle mani della Morte? Bene. Se lo merita, quella feccia codarda dei Dark Iron. Hai fatto bene, $C. Le vittime dell'attacco al Thandol Span erano solo vittime in un mondo lacerato da guerra e disordini. Le loro famiglie avranno la pace di sapere che Deepfury ha avuto la punizione che meritava. La morte del fratello di Longbraid è stata vendicata.", enHash = "f2022c38", vanilla = true },
    },
    [380] = {
        title = { it = "Night Web's Hollow", enHash = "631cec97" },
        text = { it = "Una delle nostre difficoltà più grandi è procurarci le risorse naturali che ci servono per sopravvivere. L'oro scarseggiava già quando l'Alleanza era all'apice del suo potere.\n\nA nord-ovest c'è una miniera d'oro invasa dai ragni. Ci serve l'oro della miniera, ma non possiamo certo prenderlo finché quei ragni ci strisciano dentro. Non ho molti uomini da dedicare a questo compito, quindi dovremo fare poco alla volta.\n\nVai lassù e vedi cosa puoi fare per noi, $N.", enHash = "0579a574" },
        objectives = { it = "Executor Arren vuole che tu uccida 10 Young Night Web Spider e 8 Night Web Spider.", enHash = "993c49f6" },
        progress = { it = "$GAttento:Attenta; al veleno dei ragni, $N. Se senti un bruciore acuto, faresti bene a fartelo controllare.", enHash = "cb97f7d7" },
        reward = { it = "Mmh, be', è un inizio. Ci vorranno settimane, o mesi, per ripulire del tutto l'infestazione. Dopo dovremo scendere laggiù con delle torce per bruciare le ragnatele.\n\nHai fatto bene il tuo dovere, $N. Sono sicuro di trovarti qualcos'altro da fare.", enHash = "f287ba43" },
    },
    [381] = {
        title = { it = "La Crociata Scarlatta", enHash = "2fa41a60" },
        text = { it = "Sarai $Gcontento:contenta; di sapere che a quanto pare nella miniera stiamo facendo progressi, in buona parte grazie al tuo impegno. Ora possiamo rivolgere lo sguardo ad altre questioni.\n\nI miei esploratori riferiscono che un distaccamento della Crociata Scarlatta sta allestendo un accampamento a sud-est di qui. La Crociata Scarlatta è un'organizzazione spregevole che ci dà la caccia, e non si fermerà finché ogni $R, che appartenga al Flagello del Re dei Lich o no, non sarà $Gdistrutto:distrutta;. Dobbiamo colpire per primi!\n\nFai attenzione: il loro zelo empio li rende avversari pericolosi.", enHash = "84f41966" },
        objectives = { it = "Porta a Executor Arren 12 Scarlet Armband presi da Scarlet Convert e Scarlet Initiate.", enHash = "8a38b195" },
        progress = { it = "Quegli stolti... Si mandano da soli nella tomba, e pure contenti.", enHash = "bfee4a2c" },
        reward = { it = "Se solo dessero ascolto alla ragione, eh, $N? Magari potremmo farli accomodare e discutere in modo civile... ah!\n\nStolti accecati dalla Luce.", enHash = "e97b7b82", vanilla = true },
    },
    [382] = {
        title = { it = "Il messaggero rosso", enHash = "7bdeb0d5", vanilla = true },
        text = { it = "I rapporti dei miei superiori a Brill indicano che un agente della Crociata Scarlatta è stato mandato dallo Scarlet Monastery qui a Deathknell. Secondo i rapporti, il messaggero porta con sé informazioni importanti. Non ho altri dettagli, ma qualunque cosa sia, dobbiamo averla!\n\nSei la persona più qualificata che ho a disposizione, $N. Trova quel messaggero e portami tutte le informazioni che riesci a trovare.", enHash = "5c3c850c", vanilla = true },
        objectives = { it = "Uccidi Meven Korgal, il messaggero, all'accampamento dei crociati, poi porta a Executor Arren tutte le informazioni che trovi.", enHash = "c5343e9c", vanilla = true },
        progress = { it = "Come procede la tua missione, $N?", enHash = "c9690f48", vanilla = true },
        reward = { it = "Mmh... Vediamo cos'hai portato...\n\n<Comincia a sfogliare i documenti che hai recuperato.>\n\nNotizie delle loro imprese contro di noi... Inutili. Rapporti di ricognizione... Nuovi ordini, \"Continuare a costruire un accampamento vicino alla città in rovina...\" Niente che non sapessimo già... Ah, e questo cos'è? Una mappa con le posizioni di alcuni dei loro comandanti sul campo e dei loro agenti! Questa ci sarà utile.", enHash = "bef36628", vanilla = true },
    },
    [383] = {
        title = { it = "Informazioni vitali", enHash = "3ca87253", vanilla = true },
        text = { it = "Questi andranno portati al mio superiore, Executor Zygand, a Brill. Con queste informazioni potremo infliggere un colpo decisivo alla Crociata Scarlatta. I tuoi servigi sono stati utili qui a Deathknell, ma mi serve qualcuno che li consegni a Zygand, e credo che lui saprà trovarti un lavoro più adatto.\n\nPrendi la strada a nord, fuori da Deathknell. Poco dopo essere $Gentrato:entrata; nella Tirisfal vera e propria, arriverai a un incrocio. Prendi la diramazione a est e continua verso est. Lungo la strada passerai accanto a Cold Hearth Manor.", enHash = "c71c1462", vanilla = true },
        objectives = { it = "Consegna gli Scarlet Crusade Documents a Executor Zygand, a Brill.", enHash = "fecabe8a", vanilla = true },
        progress = { it = "Sì, cosa vuoi?", enHash = "8148363a", vanilla = true },
        reward = { it = "Sì, molto bene. Hai fatto bene a procurarti queste informazioni, $N. Mmh... i nomi degli ufficiali nelle Tirisfal Glades...\n\nImmagina il colpo che potremmo dare al morale di quei maledetti fanatici, se uccidessimo i loro capi con un unico, rapido attacco.", enHash = "0a2c25b0", vanilla = true },
    },
    [384] = {
        title = { it = "Beer Basted Boar Ribs", enHash = "3ff9b4f9", vanilla = true },
        text = { it = "Niente piace ai clienti della mia taverna più delle Beer Basted Boar Ribs! L'unico problema è che il cacciatore di pelli della zona che mi portava le provviste si è arruolato nell'esercito del re, per aiutare nella guerra sul fronte dell'Alleanza.\n\nMagari puoi darmi una mano tu? Se mi porti sei Crag Boar Rib e una Rhapsody Malt dalla taverna qui, ti darò la ricetta di famiglia delle mie famose Beer Basted Boar Ribs, per non parlare di un assaggio gratis! Il segreto è nel Malt!", enHash = "f0b14a0b", vanilla = true },
        objectives = { it = "Ragnar Thunderbrew, a Kharanos, vuole 6 Crag Boar Rib e un boccale di Rhapsody Malt.", enHash = "d464c627", vanilla = true },
        progress = { it = "Mi serviranno sei Crag Boar Rib e un boccale di Rhapsody Malt, $N.", enHash = "8ff71bc3", vanilla = true },
        reward = { it = "Il Malt è fermentato, i cinghiali son morti,\ne prima che tutto sia fatto e detto\nci toccherà lottare per essere i primi\na gustare queste saporite Beer Basted Boar Ribs!", enHash = "ca291baf", vanilla = true },
    },
    [385] = {
        title = { it = "Caccia ai crocolisk", enHash = "ac4deb30", vanilla = true },
        text = { it = "Molti cacciatori vengono attirati al Loch Modan per cacciare i nostri famosi crocolisk. Ci sono sempre mercanti in cerca di pelli di crocolisk per vestiti o armature, e c'è anche chi gradisce il sapore della loro carne.\n\nUn po' di commercio lo facciamo, ma non tanto, perché i crocolisk sono feroci e si sono asserragliati sulle isole del Loch. Ma non lasciare che ti dissuada: è una bella esperienza, lottare con le fauci di quelle bestie.\n\nEh, una volta...", enHash = "07c6dc5d", vanilla = true },
        objectives = { it = "Procura 5 pezzi di Crocolisk Meat e 6 Crocolisk Skin per Marek Ironheart, al Farstrider Lodge.", enHash = "6ffef595", vanilla = true },
        progress = { it = "Te l'ho raccontata di quella volta che per poco non ci ho rimesso la mano con uno dei croco? Brutta bestia, denti come coltelli. Ma ho avuto fortuna... Gli ho bloccato le fauci con il coltello. Quel coltello ce l'ho ancora qui da qualche parte...", enHash = "815e9312", vanilla = true },
        reward = { it = "Ma bene, questi che hai raccolto sono esemplari eccellenti, $N. Bei soldi per materiali di qualità, questo è certo.", enHash = "4ca89af8", vanilla = true },
    },
    [386] = {
        title = { it = "Chi la fa l'aspetti...", enHash = "53a75334", vanilla = true },
        text = { it = "Targorr the Dread serviva sotto Gath'Ilzogg come boia supremo. I suoi metodi erano spietati, perfino per i sudici standard degli orchi. Uomini che si erano battuti con coraggio per difendere il Regno venivano torturati a suo capriccio. Ora è rinchiuso nello Stormwind Stockade, condannato a morte. Eppure qualcosa non torna. Uno dei nobili burocrati ha bloccato la sua esecuzione. Sono sicuro che sotto c'è un imbroglio.\n\nMetti fine a Targorr the Dread, $N. Va' allo Stockade e decapitalo, prima che l'inganno ci travolga.", enHash = "d35475e9", vanilla = true },
        objectives = { it = "Porta la testa di Targorr the Dread a Guard Berton, a Lakeshire.", enHash = "81338b07", vanilla = true },
        progress = { it = "Sei già $Gstato:stata; a Stormwind, allo Stockade? Temo che l'imbroglio che ha tenuto in vita Targorr the Dread così a lungo finirà per portargli la libertà. È stato condannato a morte, $N, non a fare da pedina politica al capriccio di un nobile.", enHash = "06df2192", vanilla = true },
        reward = { it = "Targorr the Dread ha finalmente incontrato il suo destino. Da parte mia sono contento di sapere che la bestia ora sa cosa vuol dire finire nella morsa spietata della Morte. Hai fatto bene, $N. A volte la giustizia più vera si trova solo fuori dal tribunale e oltre la vista appannata della politica.", enHash = "3ec58822", vanilla = true },
    },
    [387] = {
        title = { it = "Sedare la rivolta", enHash = "ed2ef82f", vanilla = true },
        text = { it = "La rivolta va sedata! Mi serve il tuo aiuto. Se si sparge la voce che la prigione è in mano ai detenuti, perdo il posto! Questo è un caso di imbroglio come pochi ne ho visti. Ma adesso quello che conta è piegare questi prigionieri, per la sicurezza di Stormwind.\n\nLa pena per l'insurrezione è la morte. Uccidi qualcuno di questi deviati! Dovrebbe bastare a riportare le cose sotto controllo.", enHash = "f57f0d17", vanilla = true },
        objectives = { it = "Warden Thelwater, di Stormwind, vuole che tu uccida 10 Defias Prisoner, 8 Defias Convict e 8 Defias Insurgent nello Stockade.", enHash = "27e490cc", vanilla = true },
        progress = { it = "Lo Stockade è ancora in mano loro! Bisogna far capire a questi ratti dei Defias che le loro azioni non saranno tollerate. Adesso torna laggiù e usa la forza!", enHash = "57fc3542", vanilla = true },
        reward = { it = "I tuoi sforzi nello Stockade sono stati valorosi, $N. È evidente che il problema è più grande di noi due. Ma tu hai fatto bene, e di questo ti sono grato.", enHash = "d0ab2a0e", vanilla = true },
    },
    [388] = {
        title = { it = "Il colore del sangue", enHash = "4e99b21d", vanilla = true },
        text = { it = "L'amarezza mi scorre nelle vene come un fiume gelido. Mio nipote, Mac, era un bravo ragazzo. Aveva appena 14 anni. Quando l'esercito fu mandato al fronte, Mac prese le armi per difendere la città. Faceva la guardia nello Stockade, dove è rinchiusa la banda dei Defias. Mac rimproverò alcuni prigionieri perché strappavano le coperte di lana per farne sciarpe, il simbolo della loro banda. Per questo Mac fu pugnalato alle spalle.\n\nVoglio vendetta. Portami 10 delle loro preziose Wool Bandana. Sono del colore del sangue.", enHash = "6372966a", vanilla = true },
        objectives = { it = "Nikova Raskol, di Stormwind, vuole che tu raccolga 10 Red Wool Bandana.", enHash = "6a133f74", vanilla = true },
        progress = { it = "Vedo che sei $Gtornato:tornata;, $C. Hai già raccolto 10 Red Wool Bandana da quella feccia dei Defias nello Stockade?", enHash = "17349bd4", vanilla = true },
        reward = { it = "Quindi queste bandane, luridi simboli di corruzione, sono ciò per cui il mio Mac è dovuto morire? Che spreco. Che sacrificio tragico.\n\nMa ahimè, non posso tornare al passato. Sappi solo, $N, che con quello che hai fatto hai reso giustizia alla mia famiglia.", enHash = "030384e5", vanilla = true },
    },
    [389] = {
        title = { it = "Bazil Thredd", enHash = "d361de49", vanilla = true },
        text = { it = "VanCleef e io eravamo membri della Stonemasons Guild. Il nostro progetto principale era ricostruire Stormwind dopo la guerra.\n\nQuando avevamo finito il nostro lavoro, siamo stati truffati. I nobili si sono rifiutati di pagarci per l'opera. Ad alcuni degli Stonemason più anziani sono stati offerti incarichi di governo, ma VanCleef li ha rifiutati per lealtà verso tutti gli Stonemason. Ha guidato una rivolta e ha lasciato la città, giurando vendetta.\n\nIl suo luogotenente, Bazil Thredd, potrebbe sapere di più sui piani di VanCleef. È tenuto prigioniero nello Stockade.", enHash = "4c86a906", vanilla = true },
        objectives = { it = "Parla con Warden Thelwater, nello Stockade.", enHash = "0a06ff0b", vanilla = true },
        reward = { it = "Che diamine vuoi, per la Luce? Non vedi che qui abbiamo una crisi?\n\nBazil Thredd?! Perché mai vorresti parlare con quel bastardo? E come faccio a sapere che non sei $Guno:una; dei suoi compari, $Gvenuto:venuta; quaggiù a dare una mano alla sua maledetta rivolta? Se non fossero aperte tutte quelle dannate celle, ti ci butterei dentro per un po'!", enHash = "e9c4e4d7", vanilla = true },
    },
    [391] = {
        title = { it = "I tumulti nello Stockade", enHash = "7e0d05d2", vanilla = true },
        text = { it = "Mettiamo subito in chiaro una cosa, $N: non mi fido di te. Ma, stando così le cose, probabilmente non farai differenza.\n\nAllora si fa così: scendi laggiù e fatti la tua chiacchierata con Thredd. Se sei davvero dalla nostra parte, uccidilo e portami la sua testa a lavoro finito. E se si scopre che sei dalla sua parte, e non torni su... quando ti troveremo, morirai insieme al resto dei vermi.", enHash = "b732fcb7", vanilla = true },
        objectives = { it = "Uccidi Bazil Thredd e riporta la sua testa a Warden Thelwater, allo Stockade.", enHash = "3a6d2153", vanilla = true },
        progress = { it = "O mi porti la testa di Thredd, o prendo la tua: intesi, $N?", enHash = "89a888c0", vanilla = true },
        reward = { it = "Senza Thredd a guidarli, si spera che i tumulti siano più controllabili. Vedremo.\n\nDevo dire che, dopo mezz'ora, non mi aspettavo proprio che tornassi su, ma a quanto pare ti avevo giudicato male.\n\nImmagino, allora, che da lui non sia uscito molto di utile? Ma io so un paio di cose che potrebbero interessarti sulle attività di Thredd.", enHash = "b1dbe1b8", vanilla = true },
    },
    [392] = {
        title = { it = "Il visitatore curioso", enHash = "51955323", vanilla = true },
        text = { it = "Nei primi anni di prigionia di Thredd non ha mai avuto visite. Immaginavo che non servisse più alla Brotherhood, e che quindi l'avessero abbandonato.\n\nPoi, qualche mese fa, è cambiato tutto: ha cominciato a ricevere visite regolari... una volta, forse due alla settimana. Era un uomo strano, di quelli silenziosi. Avevo i miei sospetti, ma i suoi documenti erano tutti in regola.\n\nI documenti dicevano che si chiamava Maelik; ecco la sua descrizione. Non credo che verrà più a trovare Thredd.", enHash = "67a943d8", vanilla = true },
        objectives = { it = "Porta la Sealed Description of Thredd's Visitor a Baros Alexston, a Stormwind.", enHash = "17f2b3e3", vanilla = true },
        progress = { it = "Sì, $N? Cos'hai trovato?", enHash = "cb3948a0", vanilla = true },
        reward = { it = "Hmm. Maelik? No, il nome non mi dice niente, e nemmeno questa descrizione. Ma potrebbe essere chiunque! Un ex Stonemason, uno della Defias Brotherhood... Però, se ha i buoni agganci che dice Thelwater, forse qualcun altro potrebbe riconoscerlo. Fammi pensare.", enHash = "ee9fa245", vanilla = true },
    },
    [393] = {
        title = { it = "L'ombra del passato", enHash = "13a81b8a", vanilla = true },
        text = { it = "Non ne ho davvero idea, $N. C'è qualcun altro che potrebbe aiutarti, e si dà il caso che mi debba un favore per... be', lasciamo perdere. Master Mathias Shaw dello SI:7 lo trovi nella caserma di Old Town. Shaw tiene il dito su quasi tutti i traffici loschi o sottobanco della città.\n\nSe c'è qualcuno che lo sa, è lui.", enHash = "c526ff8c", vanilla = true },
        objectives = { it = "Porta la Sealed Description of Thredd's Visitor a Master Mathias Shaw, a Stormwind.", enHash = "e0f522ea", vanilla = true },
        progress = { it = "Salve. In cosa posso esserti utile, $C?", enHash = "f595d826", vanilla = true },
        reward = { it = "Cosa? Cos'è questo? Sì, credo di sapere chi è quest'uomo, ma il suo nome non è Maelik. Gli assassini portano molti nomi e molte maschere, e le buttano via quando non servono più. Un altro alias che si sa aver usato è Marzon, anche se di sicuro nemmeno quello è il suo vero nome.\n\nIn ogni caso è un assassino, e io so parecchio di lui.\n\nAl momento Marzon è al soldo di Lord Gregor Lescovar, un nobile di reputazione losca, e questo pur tenendo conto della corruzione della nobiltà di Stormwind.", enHash = "ed46d8b2", vanilla = true },
    },
    [394] = {
        title = { it = "La testa della bestia", enHash = "100e2838", vanilla = true },
        text = { it = "Trova Shaw a Old Town. Fagli sapere che la minaccia di Lescovar è stata risolta e del tuo ruolo nelle trame del nobile contro la città. Sono sicuro che sarà fiero di avere $Gun altro eroe:un'altra eroina; tra i cittadini di Stormwind.\n\nCon ogni probabilità ti manderà a incontrare il principe o qualche altro nobile. Non montarti la testa, $N. I nobili possono credere quanto vogliono di comandare la città, ma certe cose restano fuori dalla loro portata.", enHash = "6cb55fe1", vanilla = true },
        objectives = { it = "Parla con Mathias Shaw, a Stormwind.", enHash = "cc18f587", vanilla = true },
        reward = { it = "È morto, dunque? La tua giustizia è stata rapida, $N. Prego la Luce di non diventare mai la tua preda!\n\n<Ride e ti dà una pacca sulla spalla.>\n\nNon è una critica, $N. Come potrei, io che sono il maestro di tutti gli assassini? Ma in verità hai reso un grande servizio alla gente di Stormwind, e di questo ti ringrazio.", enHash = "9f5fd6b0", vanilla = true },
    },
    [395] = {
        title = { it = "La fine della Brotherhood", enHash = "63cc08c3", vanilla = true },
        text = { it = "Ah, quasi dimenticavo. Alexston è passato mentre eri via, voleva parlarti. Di sicuro vuole riferire ai nobili quel che è successo con la Defias Brotherhood.\n\nUn consiglio, $N: se qualcuno dovesse chiedere, io riferirei tutti i particolari tranne che è stata la tua mano a uccidere Lescovar. Fidati. Sono... pratico... di come vanno certe cose.\n\nE quanto a Trias, be', non parlarne con nessuno... mai... se puoi evitarlo.", enHash = "461c1c1b", vanilla = true },
        objectives = { it = "Parla con Baros Alexston, a Stormwind.", enHash = "b196138b", vanilla = true },
        reward = { it = "È bello vederti, $N. Ho sentito che Lord Gregor Lescovar è stato trovato morto non molto tempo fa.\n\nPare che tu abbia avuto successo nella tua missione. Hai la mia gratitudine per aver salvato me, e molti altri, dalla vendetta di VanCleef.", enHash = "f5435249", vanilla = true },
    },
    [396] = {
        title = { it = "Udienza dal Re", enHash = "d9c0b837", vanilla = true },
        text = { it = "Ho preparato un rapporto per il Re. Credo che debba essere tu a consegnarglielo, insieme al resoconto di quel che hai scoperto. Non preoccuparti: non c'è dubbio che ti loderà per aver fatto il tuo dovere verso la gente di Stormwind.\n\nLa tua udienza è fissata a breve, quindi faresti meglio a sbrigarti: c'è un bel pezzo di strada fino a Stormwind Keep.", enHash = "56d343b9", vanilla = true },
        objectives = { it = "Consegna il rapporto di Baros Alexston sulla Defias Brotherhood a King Varian Wrynn, a Stormwind Keep.", enHash = "60e02876", vanilla = true },
        progress = { it = "$N, giusto? Baros Alexston mi ha avvisato che saresti $Gvenuto:venuta;. Devo dire che sono molto interessata a quel che hai da raccontare.", enHash = "dd2f162f", vanilla = true },
        reward = { it = "Meriti lode per il servizio che hai reso a Stormwind, $N. Se VanCleef avesse avuto successo nelle sue macchinazioni, avrebbe senza dubbio fatto un danno considerevole al regno, cosa che ovviamente dobbiamo evitare.\n\nPrendi questo, $C, come segno della riconoscenza del Re. Mi dispiace solo che non possa consegnartelo di persona, ma è via per una missione diplomatica e non tornerà per un po'.", enHash = "a9f71a0f", vanilla = true },
    },
    [397] = {
        title = { it = "Ci hai servito bene", enHash = "66799f5c", vanilla = true },
        text = { it = "Mi dicono che Lord Wishock ha gradito la sua bevanda.\n\nCi hai servito bene, $N. Grazie a te gli stregoni di Stormwind potranno praticare le nostre arti senza disturbi. Per quel che hai fatto ho preparato un dono speciale per te. Parla con il mio servo, Zggi, e prenditi la ricompensa.", enHash = "02e44e46", vanilla = true },
        objectives = { it = "Parla con Zggi, il servo di Zardeth the Blackclaw, per ritirare la ricompensa.", enHash = "4803bbd4", vanilla = true },
        reward = { it = "Padrone dice dare dono a $N. Zggi vuole tenere bel dono ma Zggi sa che non deve tradire Padrone.", enHash = "122ef8bc", vanilla = true },
    },
    [398] = {
        title = { it = "Wanted: Maggot Eye", enHash = "401663bf" },
        text = { it = "Wanted: Maggot Eye!\n\nBestia immonda perfino per gli standard degli gnoll, Maggot Eye è stato condannato a morte per i suoi crimini contro i Reietti. Questo spregevole furfante ruba cadaveri per l'esercito del Re dei Lich. Maggot Eye è stato visto l'ultima volta a saccheggiare le terre vicino a Garren's Haunt, a nord di Brill.\n\nLa città di Brill offre una ricompensa all'anima capace che sappia eseguire la condanna. Mostra a Executor Zygand la zampa del furfante, una volta compiuta l'impresa.\n\nLa pietà è per i deboli.", enHash = "e174719e" },
        objectives = { it = "Uccidi Maggot Eye e torna da Executor Zygand, a Brill, con la sua zampa per la ricompensa.", enHash = "0466bf13" },
        progress = { it = "Sì?", enHash = "00388a38", vanilla = true },
        reward = { it = "Le azioni infami di Maggot Eye sono state finalmente vendicate. Forse i tuoi atti di valore manderanno un messaggio chiaro a chi vuole fare del male alla nostra gente. A nome della città di Brill ti ringrazio, $N.", enHash = "c1e974dd", vanilla = true },
    },
    [399] = {
        title = { it = "Umili origini", enHash = "1e0c601b", vanilla = true },
        text = { it = "Mi sembra un'eternità da quando ero un ragazzo e lavoravo nella fattoria a Westfall. Dicono che non si possa più tornare indietro, ed è vero. Doppiamente vero nel mio caso: la casa della mia famiglia è stata bruciata e occupata dai ladri.\n\nHo parlato con mio padre della sorte di alcune mie cose, tra cui la mia prima bussola. Non è riuscito a salvarle. Dice però che dovrebbero essere nascoste da qualche parte nella fattoria.\n\nL'Alexston Farmstead lo trovi a ovest di Sentinel Hill. Potresti andare a recuperarla per me?", enHash = "b0eb33a6", vanilla = true },
        objectives = { it = "Va' alla casa di Baros Alexston, a Westfall, cerca la sua bussola e riportagliela a Cathedral Square, a Stormwind.", enHash = "1e5c7494", vanilla = true },
        progress = { it = "$N! Hai avuto fortuna?", enHash = "f23703cd", vanilla = true },
        reward = { it = "Oh, grazie, $N! Non ha alcun uso pratico per me, ma il valore affettivo... Inutile dirlo, grazie di avermela portata... a costo della tua stessa incolumità, per non parlare del tempo che ci è voluto per arrivare fin giù a Westfall. Hai la mia gratitudine, e prendi questo come segno del mio ringraziamento.", enHash = "afa722c0", vanilla = true },
    },
    [400] = {
        title = { it = "Attrezzi per Steelgrill", enHash = "ecccc48f", vanilla = true },
        text = { it = "Beldin Steelgrill possiede l'officina meccanica del posto, ed è il miglior tecnico di macchine d'assedio che ci sia! Ma non è tenero con i suoi attrezzi. Ti giuro che rompe quasi più Arclight Spanner di quanti gliene possiamo fornire!\n\nAbbiamo appena evaso il suo ultimo ordine di attrezzi. Se glielo consegni tu, di sicuro saprà ricompensarti per il disturbo.\n\nLa sua officina, lo Steelgrill's Depot, è appena a nord-est di Kharanos. Ed è un ritrovo di piloti veterani di macchine d'assedio, quindi tieni le orecchie aperte per qualche occasione, mentre sei lì.", enHash = "9d6b23b0", vanilla = true },
        objectives = { it = "Consegna Steelgrill's Tools a Beldin Steelgrill.", enHash = "53d07b75", vanilla = true },
        progress = { it = "Mmh? Sembri un po' giovane per essere $Gun pilota:una pilota; di macchine d'assedio. Ma non importa... hai qualcosa da riparare?\n\nBe', prendi il numero e mettiti $Gcomodo:comoda;. Al momento sto lavorando a un paio di motori e per almeno qualche giorno non avrò tempo per un altro lavoro.\n\nOppure eri qui per qualcos'altro...?", enHash = "cd7b0fe3", vanilla = true },
        reward = { it = "Hai i miei attrezzi? Ben fatto, $Gragazzo:ragazza;, ben fatto! Ho rotto l'ultimo fang-ratchet un'ora fa e me ne serve uno per finire le riparazioni alla macchina d'assedio di Pilot Stonegear. Hai fatto una buona cosa a trascinare fin qui quegli attrezzi, $N.\n\nTieni, prendi queste monete per il tuo aiuto.", enHash = { "6a2fdc34", "7ffe0728" }, vanilla = true },
    },
    [401] = {
        title = { it = "Aspetta che Sirra finisca", enHash = "86353381", vanilla = true },
        text = { it = "Ho quasi finito di tradurre quel biglietto. Se torni fra qualche momento dovrei aver finito.", enHash = "4b568972", vanilla = true },
        objectives = { it = "Aspetta un momento, poi parla di nuovo con Sirra Von'Indi.", enHash = "9efb2bb6", vanilla = true },
        reward = { it = "Ecco qua. È tradotto...\n\n<L'aria si fa pesante, come se una cortina nera e spessa calasse sulla terra...>", enHash = "25de8e7d", vanilla = true },
    },
    [404] = {
        title = { it = "Un compito putrido", enHash = "efcd6388", vanilla = true },
        text = { it = "Il Flagello è filtrato nelle Tirisfal Glades e ha infestato la zona a ovest di Brill, vicino al vecchio ponte.\n\nVa' là e ricaccia indietro i Rotting Dead e i Ravaged Corpse che troverai. Disperdi le loro ossa e riporta le loro Putrid Claw, e i Guardiamorte ti ricompenseranno.", enHash = "23dc70f6", vanilla = true },
        objectives = { it = "Porta 7 Putrid Claw a Deathguard Dillinger, a Brill.", enHash = "4b62f599", vanilla = true },
        progress = { it = "Hai portato a termine il compito che ti ho affidato? Hai quelle Putrid Claw?", enHash = "ebf339c6", vanilla = true },
        reward = { it = "Ben fatto. Mi dispiace non essere stato lì a vederti ridurre quei non morti in poltiglia putrida!", enHash = "5c26cef1", vanilla = true },
    },
    [405] = {
        title = { it = "Il lich prodigo", enHash = "02f513b3", vanilla = true },
        text = { it = "Bethor Iceshard, un mago potente e di alto rango nell'Undercity a sud, mi ordina di mandargli un agente di provato valore contro il Flagello. Tu, $N, sarai quell'agente.\n\nPresenta questi ordini a Bethor. Sarà lui a istruirti sulla tua missione. Non ne conosco i dettagli, ma riguarda il reclutamento di un Lich sviato. E sarà pericolosa.\n\nQuindi preparati, $C. Non devi fallire.\n\nBethor lo trovi nel Magic Quarter dell'Undercity.", enHash = "a29b95f0", vanilla = true },
        objectives = { it = "Presenta Sevren's Orders a Bethor Iceshard, nell'Undercity.", enHash = "7435018c", vanilla = true },
        progress = { it = "Salute. O non sai chi sono io, oppure i tuoi affari con me sono urgenti.\n\nPerché, se nessuna delle due cose fosse vera, non saresti così $Gsciocco:sciocca; da disturbarmi...", enHash = "0c48fac7", vanilla = true },
        reward = { it = "Ah, sei tu l'agente mandato da Magistrate Sevren. Allora sì, i tuoi affari con me sono cruciali.\n\nConfido che Sevren abbia trovato qualcuno all'altezza del mio compito... ma vedremo.", enHash = "6d0f9d59", vanilla = true },
    },
    [407] = {
        title = { it = "Campi di dolore", enHash = "93c2e3fd", vanilla = true },
        text = { it = "Zucche innocue, vero? O almeno così sembrerebbe. Se vogliamo respingere l'avanzata di Arthas da nord e l'infestazione umana da sud, dobbiamo cominciare a sfruttare tutto il potenziale del nostro dono della non morte.\n\nCon un po' d'ingegno una semplice zucca diventa un agente al servizio della nostra Signora Oscura. Questa zucca, intrisa della mia ultima formula, si rivelerà una vera prelibatezza.\n\nUn altro Scarlet Zealot è stato catturato e viene tenuto nella cantina della Gallows' End Tavern. Porta questa zucca allo sciocco.", enHash = "a7fedc9d", vanilla = true },
        objectives = { it = "Porta la Laced Pumpkin al Captured Scarlet Zealot, tenuto nella cantina della Gallows' End Tavern.", enHash = "e867f4e0", vanilla = true },
        progress = { it = "Stammi lontano, creatura immonda ed empia! Che la Luce mi protegga! La Crociata Scarlatta libererà Azeroth della tua...\n\n...oh, aspetta. È cibo per me? Ho una fame...", enHash = "e415a696", vanilla = true },
        reward = { it = "Per la Luce! Finalmente del cibo! Dolce, dolce zucca...", enHash = "e36be38d", vanilla = true },
    },
    [408] = {
        title = { it = "La cripta di famiglia", enHash = "02f82101", vanilla = true },
        text = { it = "La zona degli Agamand Mills è diventata un punto d'appoggio per il Flagello. Il suo punto più forte è l'Agamand Family Crypt, dove ha posto il quartier generale il suo capo militare locale, uno scheletro di nome Captain Dargol. Con la negromanzia ha risvegliato gli antenati degli Agamand e vuole usarli contro di noi.\n\nNon possiamo permetterlo: devi fermarlo tu. Va' all'Agamand Family Crypt e sconfiggi gli antenati Agamand risvegliati.\n\nE portami il teschio di Captain Dargol.", enHash = "0ef953fa", vanilla = true },
        objectives = { it = "Uccidi 8 Wailing Ancestor e 8 Rotting Ancestor.\n\nUccidi Captain Dargol e porta il suo teschio a Magistrate Sevren, a Brill.", enHash = "34f38ba5", vanilla = true },
        progress = { it = "Non possiamo permetterci di perdere tempo, $N. A ogni ora che passa, la presa del Flagello sulle Tirisfal Glades si fa più salda.", enHash = "5ad77d48", vanilla = true },
        reward = { it = "Le tue azioni hanno inferto un colpo significativo al Flagello. E la tua vittoria non passerà inosservata: né ai Reietti, né ai nostri nemici.\n\nContinua la lotta come facciamo tutti, $N, e un giorno scacceremo da Azeroth il Re dei Lich in persona!", enHash = "390d34d9", vanilla = true },
    },
    [409] = {
        title = { it = "Dimostrare la fedeltà", enHash = "7e6de3bc", vanilla = true },
        text = { it = "Dici di non essere $Gvincolato:vincolata; alla volontà del Re dei Lich, e l'incantesimo che Bethor ha posto sul mio libro lo conferma. Ma prima di crederti devo avere la prova che sei $Gnemico:nemica; del Flagello.\n\nC'è un vecchio altare insanguinato appena al largo della costa meridionale di quest'isola. Lo usa un potente agente del Flagello, Lillith Nefara.\n\nPrendi una Candle of Beckoning da questa cassa qui. Accendila sull'altare e Lillith si sveglierà. Distruggi Lillith, e crederò che sei $Gnemico:nemica; del Re dei Lich.", enHash = "f7020e9b", vanilla = true },
        objectives = { it = "Procurati una Candle of Beckoning.\n\nEvoca Lillith Nefara e uccidila.\n\nTorna da Gunther, sulla sua isola.", enHash = "8f88442a", vanilla = true },
        progress = { it = "Attendo la prova della tua fedeltà, $C.", enHash = "37aafdc5", vanilla = true },
        reward = { it = "Hai sconfitto Lillith Nefara, dimostrando di essere $Gnemico:nemica; del Flagello. Incredibile.\n\nCredevo di essere l'unico non morto con il libero arbitrio, ma mi hai mostrato che ce ne sono altri che hanno spezzato il dominio del Re dei Lich.", enHash = "8a415c00", vanilla = true },
    },
    [410] = {
        title = { it = "L'ombra dormiente", enHash = "b7f96fff", vanilla = true },
        progress = { it = "Questo è un tavolo vecchio, malridotto e insanguinato.", enHash = "cc33eb92", vanilla = true },
        reward = { it = "Posi la Candle of Beckoning sul tavolo e l'accendi...", enHash = "10937730", vanilla = true },
    },
    [411] = {
        title = { it = "Il ritorno del lich prodigo", enHash = "3baab5d6", vanilla = true },
        text = { it = "Porta questa Nether Gem al mio vecchio compagno Bethor. Ci permetterà di comunicare... e ho molto da dirgli.", enHash = "d9f1471d", vanilla = true },
        objectives = { it = "Porta la Nether Gem a Bethor Iceshard, nell'Undercity.", enHash = "a63ab225", vanilla = true },
        progress = { it = "Hai restituito il libro di Gunther? Ha risposto?", enHash = "44d013bd", vanilla = true },
        reward = { it = "L'hai convinto a unirsi a noi! Hai compiuto una grande impresa per i Reietti, $N. La Signora Oscura ne sarà informata.", enHash = "3c5d8c50", vanilla = true },
    },
    [412] = {
        title = { it = "Operazione Recombobulation", enHash = "80bb639e", vanilla = true },
        text = { it = "Da un'analisi più approfondita della situazione di Gnomeregan, sembrerebbe che non solo non siamo riusciti a sterminare i trogg, ma che per giunta abbiamo trasformato gran parte della razza degli gnomi in orribili Leper Gnome, privi di mente e votati al male.\n\nIo e Ozzie abbiamo in progetto di annullare il terribile effetto lebbroso con la nostra ultima invenzione: il Recombobulator. La macchina è quasi finita, ma abbiamo un disperato bisogno di Restabilization Cog e Gyromechanic Gear. Recuperane un po' per noi dai Leper Gnome davanti a Gnomeregan.", enHash = "c202c569", vanilla = true },
        objectives = { it = "Porta 8 Restabilization Cog e 8 Gyromechanic Gear a Razzle Sprysprocket, a Kharanos.", enHash = "b55d9361", vanilla = true },
        progress = { it = "Il Recombobulator sarà in funzione appena avremo abbastanza Restabilization Cog e Gyromechanic Gear.", enHash = "0c9450a2", vanilla = true },
        reward = { it = "Questi Gyromechanic Gear e Restabilization Cog corrispondono perfettamente agli schemi di Ozzie per il Recombobulation Device. Appena avrò aggiunto un po' di idrolubrificante ai pistoni a combustione interna, regolato il crank-o-ratchet e aumentato la viscosità del gel di elettrogomma, la razza degli gnomi tornerà come nuova.", enHash = "158c6e2b", vanilla = true },
    },
    [413] = {
        title = { it = "Shimmer Stout", enHash = "42bffd6e", vanilla = true },
        text = { it = "Vorrei che mio fratello Wellart assaggiasse la mia nuova Shimmer Stout. È un Mountaineer di stanza nella torre di guardia a sud, una delle due torri al confine con il Loch Modan.\n\nNon sarà un birraio come tutti noi Barleybrew, ma le bevute gli piacciono e so che questa gli piacerà.\n\nPuoi portargli questo Barrel of Shimmer Stout da parte mia?", enHash = "cec8a148", vanilla = true },
        objectives = { it = "Porta il Barrel of Shimmer Stout a Mountaineer Barleybrew.", enHash = "bdaa36a8", vanilla = true },
        progress = { it = "Salve, $C! E quale faccenda ti porta fin quaggiù?\n\nQualcosa di emozionante, spero. Non faccio una bella scazzottata da giorni, e questo barile di birra è quasi a secco...", enHash = "66b16216", vanilla = true },
        reward = { it = "<Mountaineer Barleybrew assaggia la Shimmer Stout...>\n\nOh. Whoa! Questa roba ti fa brillare gli occhi sul serio. Mi sembra di vedere al buio!", enHash = "af589f3a", vanilla = true },
    },
    [414] = {
        title = { it = "Stout per Kadrell", enHash = "d4a4ddcf", vanilla = true },
        text = { it = "Ho continuato a bere quella Shimmer Stout che ha fatto mio fratello — è roba coi fiocchi! Voglio farla assaggiare a un altro Mountaineer. Si chiama Kadrell, e di solito pattuglia la strada che passa per Thelsamar, nel Loch Modan.\n\nPer arrivare a Thelsamar, vai a sud-est attraverso la galleria, poi gira a nord-est quando il sentiero si apre in una strada. Segui quella strada dritto fino a Thelsamar.\n\nDai a Mountaineer Kadrell questo barilotto di Shimmer Stout e senti cosa ne pensa!", enHash = "57551891", vanilla = true },
        objectives = { it = "Porta il Cask of Shimmer Stout a Mountaineer Kadrell.", enHash = "b2a38754", vanilla = true },
        progress = { it = "Salute, $C, e $Gbenvenuto:benvenuta; a Thelsamar!", enHash = "46e27609", vanilla = true },
        reward = { it = "Allora, fammi assaggiare...\n\nPer la barba di Magni! Questa roba ti fa girare la testa! E alleggerisce anche le membra.\n\nMi sembra di poter volare!", enHash = "6f42d32b", vanilla = true },
    },
    [415] = {
        title = { it = "La nuova birra di Rejold", enHash = "f1dca3c6", vanilla = true },
        text = { it = "Rejold Barleybrew, a Brewnall Village, ti sta cercando.\n\nVuole parlarti di una nuova bevanda che sta preparando... ha detto qualcosa sul fatto che l'hai aiutato. Faresti bene a tornare a Brewnall Village e sentire cosa ha da dire.\n\nPotrebbe scapparci qualche bevuta gratis per te...", enHash = "f4fbcc59", vanilla = true },
        objectives = { it = "Parla con Rejold Barleybrew.", enHash = "688a9fbb", vanilla = true },
        reward = { it = "$N! Ti ricordi quello Shimmerweed che mi hai portato? Be', l'ho usato in un paio di ricette a cui stavo lavorando, e una è venuta benissimo!\n\nTieni, provala e dimmi cosa ne pensi...", enHash = "16e361e3", vanilla = true },
    },
    [416] = {
        title = { it = "Caccia ai ratti", enHash = "147f6ce2", vanilla = true },
        text = { it = "Abbiamo un bel problema di infestazione a ovest. I kobold Tunnel Rat si sono insediati tra le colline, hanno messo su le loro tane e stanno sporcando la nostra terra con il loro lerciume!\n\nLi vogliamo eliminati. Dagli la caccia, portami le loro orecchie e guadagnati la taglia.\n\nI kobold Tunnel Rat e le loro tane li trovi a ovest di Thelsamar, sparsi lungo il fianco della montagna.", enHash = "d878d1c5", vanilla = true },
        objectives = { it = "Porta 12 Tunnel Rat Ear a Mountaineer Kadrell, a Thelsamar.", enHash = "ce9f33d6", vanilla = true },
        progress = { it = "Salute, $N. Come va la caccia ai ratti?", enHash = "58f30048", vanilla = true },
        reward = { it = "Ugh! Quando ho chiesto quelle orecchie non immaginavo che puzzassero così!\n\nEcco la tua ricompensa, $N. Ben fatto.", enHash = "467b4a2a", vanilla = true },
    },
    [417] = {
        title = { it = "La vendetta di un pilota", enHash = "331f726f", vanilla = true },
        text = { it = "Hildelve ha scritto nel suo diario di essere stato attaccato da Mangeclaw, un \"enorme Ice Claw Bear\". Ha messo in fuga la bestia, ma non prima che lo dilaniasse selvaggiamente.\n\nA giudicare dallo stato del corpo di Hildelve, Mangeclaw dev'essere tornato più tardi e averlo ucciso.\n\nHildelve però ha scritto nel suo diario il suo unico, ultimo desiderio:\n\nVendetta su Mangeclaw.", enHash = "b6b24f1c", vanilla = true },
        objectives = { it = "Uccidi Mangeclaw.\n\nPorta la sua Mangy Claw e Hildelve's Journal a Pilot Hammerfoot.", enHash = "dcef8b1a", vanilla = true },
        progress = { it = "Salve, $N. Hai notizie del mio amico Hildelve?", enHash = "889c8e0f", vanilla = true },
        reward = { it = "È una brutta notizia, perché Hildelve era un buon amico. E avrei voluto essere lì con te quando hai trovato quella bestia di Mangeclaw!\n\nGrazie, $N. I piloti dell'Ironforge Siege Brigade ricorderanno ciò che hai fatto.", enHash = "2d025ba4", vanilla = true },
    },
    [418] = {
        title = { it = "I Thelsamar Blood Sausage", enHash = "186d0a91", vanilla = true },
        text = { it = "Qui a Thelsamar non c'è mai carenza di pance vuote: i bambini che entrano ed escono, gli operai dello scavo che arrivano dopo una dura giornata di lavoro. Siamo famosi per i nostri sanguinacci: non li avrai mica già assaggiati?\n\nNo? Be', da queste parti i pasti te li devi guadagnare, e non pensare che, solo perché sei $Gun:una; $C elegante, farai eccezione.\n\nMi serviranno Bear Meat, Boar Intestine per i budelli e Spider Ichor per insaporire. Tu procurami quella roba, e lascia cucinare a Vidra!", enHash = "55f2c41f", vanilla = true },
        objectives = { it = "Porta 3 pezzi di Bear Meat, 3 Boar Intestine e 3 Spider Ichor a Vidra Hearthstove, a Thelsamar.", enHash = "4b33356d", vanilla = true },
        progress = { it = "Sono pronta a mettermi ai fornelli: ce li hai gli ingredienti per me?", enHash = "1db02ac9", vanilla = true },
        reward = { it = "Credimi, sembra molto più difficile di quanto non sia, ma...\n\nOh, non ho mai conosciuto nessuno che si interessasse tanto alla preparazione dei sanguinacci, ma ti do lo stesso la ricetta, non si sa mai. Ecco qua, e bada di mangiarli freschi!", enHash = "888189b1", vanilla = true },
    },
    [419] = {
        title = { it = "Il pilota scomparso", enHash = "1b7f2dcb", vanilla = true },
        text = { it = "Il mio amico e collega pilota di macchine d'assedio, Mori Hildelve, si è perso tra le colline. Stavamo cercando un minerale raro che serve per una polvere esplosiva di alta qualità e, durante le ricerche, lui ha portato il suo mezzo su per una collina ripida e l'ha sfasciato!\n\nConvinto che quel minerale fosse comunque tra queste montagne, Hildelve mi ha incaricato di sorvegliare i nostri mezzi mentre lui proseguiva a piedi a cercarlo.\n\nSono passati giorni, e di notte ho sentito dei ringhi bestiali tra le colline. Mori è duro come il ferro, ma sono preoccupato.\n\nTi prego, $N. Trovalo.", enHash = "1f92c56f", vanilla = true },
        objectives = { it = "Trova Pilot Hildelve.", enHash = "936626f0", vanilla = true },
        reward = { it = "Ecco il cadavere di un nano — dilaniato, congelato e ripulito dai saprofagi di montagna. Stretto nella mano ha un libro con gli appunti scarabocchiati alla svelta di Mori Hildelve. E addosso, ancora in ottime condizioni, porta un Brigadier's Vest.\n\nDev'essere qui, in questa scena macabra, che il pilota di macchine d'assedio ha trovato la fine.", enHash = "767e48ce", vanilla = true },
    },
    [420] = {
        title = { it = "Le osservazioni di Senir", enHash = "0abba316", vanilla = true },
        text = { it = "I trogg nella galleria sono estremamente ostili, e non hanno esitato ad attaccare chi la attraversa. Però sembri abbastanza $Grobusto:robusta;, quindi dovresti cavartela.\n\nIndicazioni? Se vai a parlare con Senir, lo trovi a Kharanos.\n\nAttraversa la galleria e, una volta $Guscito:uscita; dall'altra parte, segui la strada: arriva dritta a Kharanos.", enHash = "26b7494e", vanilla = true },
        objectives = { it = "Consegna il rapporto di Grelin a Senir Whitebeard, a Kharanos.", enHash = "aa2016d7", vanilla = true },
        progress = { it = "Come stai? Ti va di bere qualcosa con me? Col freddo non c'è molto altro da fare.", enHash = "24201f8d", vanilla = true },
        reward = { it = "Cos'è questo? Ah, il rapporto di mio fratello. Mmh...\n\nGli avevo detto di non abusare del nome del re, ma non mi ha ascoltato. Poco male, credo, anche se di sicuro al Senato qualcuno si arrabbierà. Non che a qualcuno non servisse una bella scossa! Ah!\n\nComunque, suppongo che questo voglia dire che dovrei mandare anch'io il mio rapporto a Ironforge, ma devo ammettere che sono un po' indietro. Maledetto freddo.\n\nPiù avanti dovrei avere del lavoro per te, se ti interessa.", enHash = "9cccfdba", vanilla = true },
    },
    [421] = {
        title = { it = "Dimostra il tuo valore", enHash = "3ef112e5", vanilla = true },
        text = { it = "Lady Sylvanas ha incaricato Varimathras di conquistare le terre umane e naniche a sud.\n\nMa quello sciocco di Arugal — ciarlatano di Dalaran e ora bestia maledetta di Shadowfang Keep — ha lasciato che la sua magia avventata devastasse la roccaforte strategica della Silverpine Forest.\n\nMi serve qualcuno esperto nelle vie del combattimento per aiutarmi a ripulire il disastro di Arugal. Dimostrami il tuo valore uccidendo 5 Moonrage Whitescalp. Quelle bestie miserabili si trovano spesso appena fuori dalla strada, giù per la collina qui sotto.", enHash = "de7bfacd", vanilla = true },
        objectives = { it = "Dalar Dawnweaver, al Sepulcher, vuole che tu uccida 5 Moonrage Whitescalp.", enHash = "50caa29a", vanilla = true },
        progress = { it = "Se vuoi dimostrarmi il tuo valore, devi uccidere 5 Moonrage Whitescalp. Porta a termine quel compito, e farò in modo che la tua abilità sia impiegata in incarichi più degni.", enHash = "73325cd4", vanilla = true },
        reward = { it = "Mi hai servito bene, $C. Per me è evidente che sarai un aiuto prezioso mentre mi preparo a liberare la Silverpine Forest dalla maledizione di Arugal.", enHash = "3c91660a", vanilla = true },
    },
    [422] = {
        title = { it = "La follia di Arugal", enHash = "2770798a", vanilla = true },
        text = { it = "Come Arugal sia stato accettato nel Kirin Tor resta per me un mistero. La sua conoscenza degli incantesimi sembrava trasparente come un ninnolo di vetro soffiato.\n\nOra quel che conta è capire esattamente quale magia abbia usato Arugal, così che io possa rivolgerla contro di lui e assicurare la Silverpine Forest alla Signora Oscura.\n\nAll'inizio Arugal si fermò alla fattoria del grano appena a nord del ponte. Uno degli Inseguitori della Morte ha riferito di aver visto dei libri di incantesimi, ma non è riuscito a recuperarli. Recuperami da quei libri l'incantesimo chiamato Remedy of Arugal.", enHash = "38e5149d", vanilla = true },
        objectives = { it = "Recupera il Remedy of Arugal per Dalar Dawnweaver, al Sepulcher.", enHash = "4d6cc7b4", vanilla = true },
        progress = { it = "Prima di sapere con cosa abbiamo a che fare, $C, devo studiare l'incantesimo chiamato Remedy of Arugal. Portamelo subito, o sarò costretto a cercarmi un servitore all'altezza.", enHash = "85332ce9", vanilla = true },
        reward = { it = "È esattamente l'incantesimo che cercavo, $C. Se la tua dedizione alla causa della Signora Oscura resterà salda, scoprirai di avere un bel futuro tra i Reietti.", enHash = "86a58fa6", vanilla = true },
    },
    [423] = {
        title = { it = "La follia di Arugal", enHash = "2770798a", vanilla = true },
        text = { it = "Dopo aver esaminato il lavoro di Arugal, i miei peggiori sospetti hanno trovato conferma. Quel vecchio incapace non era all'altezza di pulire i pitali a Dalaran, figurarsi di rappresentare il Kirin Tor nella sua ora più buia. Che sciocchi!\n\nArugal usava oggetti incantati per rinforzare la sua magia debole. Devo esaminare quegli oggetti di persona. Va' e uccidi Moonrage Glutton e Moonrage Darksoul finché non avrai raccolto abbastanza dei loro ceppi incantati per le mie ricerche. Quelle creature immonde sono state avvistate a nord e a est.", enHash = "d8836643", vanilla = true },
        objectives = { it = "Porta 6 Glutton Shackles e 3 Darksoul Shackles a Dalar Dawnweaver, al Sepulcher.", enHash = "5b874d42", vanilla = true },
        progress = { it = "Mi serviranno 6 Glutton Shackles e 3 Darksoul Shackles prima di poter valutare la situazione e trovare una soluzione definitiva per Arugal. Ora esegui gli ordini e uccidi Moonrage Glutton e Moonrage Darksoul finché non avrai ciò che mi serve.", enHash = "63420421", vanilla = true },
        reward = { it = "Spero di riuscire a ricavare abbastanza energia da un campione così limitato. Forse avrei dovuto farti raccogliere più ceppi.\n\nCiò nonostante, hai mostrato grande abilità nel procurarli, $C.", enHash = "f417db20", vanilla = true },
    },
    [424] = {
        title = { it = "La follia di Arugal", enHash = "2770798a", vanilla = true },
        text = { it = "In effetti mi ci vorrà più tempo di quanto pensassi per scoprire gli oscuri segreti dietro gli incantesimi che Arugal usava.\n\nMa nel frattempo ho bisogno che tu ti occupi di un piccolo problema che i nostri Darkstalker hanno scoperto. A quanto pare Arugal ha lasciato che la sua magia si diffondesse fino alla Deep Elem Mine, sulle colline a sud-est.\n\nLa miniera sarebbe una bella risorsa per l'avanzata di Varimathras.\n\nVoglio che tu decapiti il caposquadra corrotto della miniera, Grimson the Pale. Con la sua morte la miniera sarà nostra.", enHash = "a2186006", vanilla = true },
        objectives = { it = "Uccidi Grimson the Pale e porta la sua testa a Dalar Dawnweaver, al Sepulcher.", enHash = "8ff45db9", vanilla = true },
        progress = { it = "Grimson the Pale è stato ucciso? Varimathras non sarà contento se ignoriamo i suoi ordini.", enHash = "4d7e55d0", vanilla = true },
        reward = { it = "Ottimo. La miniera fornirà risorse eccellenti alle nostre forze, mentre ci espandiamo per Silverpine e fin dentro Azeroth.", enHash = "696befd0", vanilla = true },
    },
    [425] = {
        title = { it = "Ivar the Foul", enHash = "5966bb31", vanilla = true },
        text = { it = "A me e a mio fratello Quinn era stato affidato il compito di esplorare la Silverpine Forest e fare rapporto a High Executor Hadrec. Ma non siamo andati lontano — mentre attraversavamo questa fattoria siamo stati attaccati dal ghoul Ivar the Foul.\n\nA Ivar siamo sfuggiti, ma ha dilaniato Quinn. La pozione che gli hai dato lo sta guarendo, ma Ivar potrebbe tornare prima che Quinn si rimetta.\n\nUccidi Ivar, così Quinn avrà il tempo di guarire. Ivar di solito sta nel fienile là in fondo, ad aspettare che io abbassi la guardia.", enHash = "f7324669", vanilla = true },
        objectives = { it = "Uccidi Ivar the Foul e porta Ivar's Head a Rane Yorick, all'Ivar Patch.", enHash = "b8ea4bde", vanilla = true },
        progress = { it = "Hai ucciso Ivar the Foul? Se non vuoi farlo per me e per mio fratello, fallo per i Reietti.", enHash = "2f4fc759", vanilla = true },
        reward = { it = "Ah, grazie. Te ne sono grata, $N.\n\nE ti citerò nel rapporto che farò ai miei superiori.", enHash = "54092bad", vanilla = true },
    },
    [426] = {
        title = { it = "I mulini invasi", enHash = "ca7a6c7f" },
        text = { it = "Il Flagello sta cercando di formare una base agli Agamand Mills. Se ci riesce, potrà lanciare altri attacchi dentro Tirisfal.\n\nGli ordini sono stati dati. Il Flagello ai Mills va distrutto.\n\nVa' ai Mills. Raccogli le Notched Rib dai Rattlecage Soldier e dai Cracked Skull Soldier, e le Blackened Skull dai Darkeye Bonecaster.\n\nPer arrivare ai Mills, segui la strada verso ovest. Dopo aver attraversato il ponte, prendi il bivio successivo a nord e poi continua verso nord. Quando vedrai i mulini a vento, la battaglia avrà inizio.", enHash = "aca5bfcf" },
        objectives = { it = "Raccogli 5 Notched Rib e 3 Blackened Skull, poi torna da Deathguard Dillinger, a Brill.", enHash = "3331770b" },
        progress = { it = "Le nostre battaglie contro il Flagello continuano, $N. Fa' la tua parte e ricaccia quei non morti maledetti e senza mente nelle Plaguelands!", enHash = "cb218180", vanilla = true },
        reward = { it = "Il tuo impegno nella guerra si sente tra noi, $N. Non ti ringrazierò per aver fatto ciò che è necessario, ma i Guardiamorte di Tirisfal ricorderanno il tuo nome.", enHash = "571f319f", vanilla = true },
    },
    [427] = {
        title = { it = "In guerra con la Crociata Scarlatta", enHash = "2fcd170b", vanilla = true },
        text = { it = "I documenti forniti da Executor Arren sono proprio la svolta che ci serviva nella nostra battaglia contro la miserabile Crociata Scarlatta. Ora conosciamo le sue posizioni esatte in tutte le Tirisfal Glades.\n\nMa i Guardiamorte hanno preoccupazioni più grandi. L'esercito del Re dei Lich cresce di numero ogni notte. Ci serve qualcuno con \"iniziativa\" come te per mandare la Crociata Scarlatta nella tomba.\n\nDimostrami che sei in grado di servire la Signora Oscura: va' a ovest, alla torre oltre la Solliden Farmstead, e uccidi 10 Scarlet Warrior.", enHash = "559b8472", vanilla = true },
        objectives = { it = "Executor Zygand di Brill vuole che tu uccida 10 Scarlet Warrior.", enHash = "d1bdf4fd", vanilla = true },
        progress = { it = "Se vuoi dimostrare il tuo valore alla Signora Oscura, uccidi 10 Scarlet Warrior, $C.", enHash = "772a0e13", vanilla = true },
        reward = { it = "Ottimo, $C. La tua abilità nell'arte del combattimento è innegabile.", enHash = "c385dd79", vanilla = true },
    },
    [428] = {
        title = { it = "Inseguitori della Morte dispersi", enHash = "0903b7df", vanilla = true },
        text = { it = "Un paio di settimane fa due dei nostri Inseguitori della Morte, Rane e Quinn Yorick, sono stati mandati in missione di ricognizione nel nord di Silverpine. Non ne abbiamo più notizie.\n\nPotrebbero essere caduti vittime del Flagello, ma se è così voglio conferma. Trova questi Inseguitori della Morte.\n\nIl loro primo obiettivo era esplorare le fattorie nel nord di Silverpine. È da lì che dovresti cominciare la ricerca.", enHash = "4c67fd43", vanilla = true },
        objectives = { it = "Trova gli Inseguitori della Morte Quinn e Rane Yorick.", enHash = "3c4bf1be", vanilla = true },
        reward = { it = "Ci hai trovati! E appena in tempo...", enHash = "8c45fb98", vanilla = true },
    },
    [429] = {
        title = { it = "Cuori selvaggi", enHash = "dd3f5a03", vanilla = true },
        text = { it = "Mio fratello Quinn è stato ferito gravemente dal ghoul Ivar the Foul, e non so se guarirà come si deve senza un aiuto magico. Anche se non sono una speziale, so bene che i nostri speziali sanno preparare pozioni curative con i cuori scoloriti dei worg.\n\nRaccogli quei cuori e portali ad Apothecary Renferrel, al Sepulcher a sud. Poi torna qui con la pozione.\n\nDi worg ne trovi in abbondanza tra qui e il Malden's Orchard, a est.", enHash = "e2f49c1e", vanilla = true },
        objectives = { it = "Raccogli 6 Discolored Worg Heart e portali ad Apothecary Renferrel, al Sepulcher.", enHash = "a27f85af", vanilla = true },
        progress = { it = "Ho poco tempo, $C, perché la Signora Oscura mi ha affidato un compito grave.", enHash = "4d544649", vanilla = true },
        reward = { it = "<Renferrel prende i cuori.>\n\nÈ preoccupante sentire che i nostri Inseguitori della Morte hanno fallito la missione.\n\nSperiamo che questi fallimenti siano rari.\n\nTi darò la pozione tra un istante, ma ecco la sua ricetta: se quegli Inseguitori della Morte si ritrovassero ad aver bisogno di aiuto in futuro, forse potrai darglielo tu.", enHash = "4e639f80", vanilla = true },
    },
    [430] = {
        title = { it = "Torna da Quinn", enHash = "c49fba50", vanilla = true },
        text = { it = "Ecco la pozione per aiutare Quinn Yorick a rimettersi.\n\nE ora, se vuoi scusarmi, ho un lavoro molto importante da portare avanti...", enHash = "e8890268", vanilla = true },
        objectives = { it = "Porta la pozione di Quinn a Quinn Yorick, all'Ivar Patch, a nord del Sepulcher.", enHash = "83e70009", vanilla = true },
        progress = { it = "Mia sorella mi ha detto che sei qui per aiutarci. È vero?", enHash = "1175bb12", vanilla = true },
        reward = { it = "<Quinn prende la pozione e la beve.>\n\nSì, la sento fare effetto. Presto riuscirò a viaggiare.\n\nMi hai reso un grande favore, $N.", enHash = "62cc2669", vanilla = true },
    },
    [431] = {
        title = { it = "Candles of Beckoning", enHash = "80983c69", vanilla = true },
        reward = { it = "Afferri una delle candele e la metti nello zaino.", enHash = "542f1875", vanilla = true },
    },
    [432] = {
        title = { it = "Maledetti trogg!", enHash = "535d9783", vanilla = true },
        text = { it = "Quei trogg maledetti dalla Luce, che mi riducono il cantiere a un rottame! Guarda lì, se ne va un altro barile di polvere!\n\nOhhh, come vorrei scendere laggiù e torcere ognuno di quei loro colli rinsecchiti! Li voglio morti tutti!\n\nNon può farmi bene, tutto questo stress e questa rabbia... Cosa mi hanno lasciato? Niente!\n\nLi ucciderei di persona, ma non ho più la mira di una volta! Tu scendi nella cava e ammazzane un po', di quei luridi bastardi! Ti pagherò! Falli soffrire, uccidili!", enHash = "b3fa59b2", vanilla = true },
        objectives = { it = "Uccidi 6 Rockjaw Skullthumper per Foreman Stonebrow, alla Gol'Bolar Quarry.", enHash = "dae35191", vanilla = true },
        progress = { it = "Mi fa infuriare! Grrr...", enHash = "5a878ba0", vanilla = true },
        reward = { it = "Be', così mi sento un po' meglio...\n\nMa non mi darò pace finché non saranno tutti morti! Tutti quanti!", enHash = "d1d24260", vanilla = true },
    },
    [433] = {
        title = { it = "Il servitore pubblico", enHash = "a17cf6e9", vanilla = true },
        text = { it = "Come membro del Senato e della Lega degli Esploratori, mi sono assunto il compito di occuparmi di questa parte dell'infestazione di trogg che attanaglia le nostre terre.\n\nAlla Gol'Bolar Quarry hanno combinato un bel disastro, e senza motivo. Mentre scavavamo in profondità nella terra, sono sbucati fuori, distruggendo le nostre attrezzature e cacciando via i minatori. Non ci resta molto da fare, se non sterminarli tutti, ricostruire e poi tornare al lavoro.\n\nSe mi aiuti con i trogg, ti ricompenserò volentieri per il tuo tempo.", enHash = "4872c60c", vanilla = true },
        objectives = { it = "Uccidi 10 Rockjaw Bonesnapper per Senator Mehr Stonehallow, alla Gol'Bolar Quarry.", enHash = "49d75cfe", vanilla = true },
        progress = { it = "Se riusciamo a togliere i trogg dalla Gol'Bolar Quarry, sarà il primo di molti passi che dovremo compiere per liberarci di questa minaccia.", enHash = "72715499", vanilla = true },
        reward = { it = "È un inizio. Speriamo di poterne approfittare e di spostare qui qualche Mountaineer per mettere in sicurezza la zona. Poi potremo cominciare a rimettere in piedi le nostre strutture e far tornare i minatori al lavoro.\n\nGrazie del tuo aiuto, $N.", enHash = "4664387f", vanilla = true },
    },
    [434] = {
        title = { it = "L'attacco!", enHash = "085b362a", vanilla = true },
        text = { it = "Dopo che avrò messo addosso a Spybot il travestimento, andrà a parlare con Lescovar. Le guardie dovrebbero lasciarlo passare senza problemi.\n\nMentre tu mi procuravi il materiale, io ho pensato a far sapere a Marzon che era ora che lui e Lescovar si rivedessero. Gli ho anche fatto arrivare qualche informazione falsa.\n\nLescovar congederà le guardie e aspetterà Marzon qui fuori in giardino. Quando li senti parlare dei Defias, entra in azione. Devi ucciderli tutti e due prima che le guardie tornino! Quando hai finito, parla con Trias.", enHash = "cbac3c14", vanilla = true },
        objectives = { it = "Resta nel giardino finché Lord Gregor Lescovar e Marzon the Silent Blade non hanno finito di parlare. Poi uccidili tutti e due e torna da Elling Trias, a Stormwind.", enHash = "092ec819", vanilla = true },
        progress = { it = "Sì, $N? Le cose vanno bene con Tyrion? Mi ha messo al corrente della situazione e l'ho aiutato a ingannare Marzon perché andasse al castello.\n\nMarzon è stato una spina nel fianco di molte persone a Stormwind, e parecchie di loro sono miei cari amici. Nessuno tocca i miei amici... non se sa cosa gli conviene.\n\nÈ solo un peccato che nel frattempo stia facendo indirettamente un favore a Shaw e allo SI:7. Pazienza, non tutti i piani sono perfetti.", enHash = "3f4b5dfa", vanilla = true },
        reward = { it = "Quindi è fatta? Bene. Grazie mille per la tua discrezione, $N. Hai dimostrato il tuo valore più di una volta. Starò di sicuro a guardare te e i tuoi progressi dentro l'Alleanza.\n\nMi raccomando, tieni la fedina pulita.", enHash = "997007b1", vanilla = true },
    },
    [435] = {
        title = { it = "Scortare Erland", enHash = "0728c072", vanilla = true },
        text = { it = "I lupi là fuori non se ne vanno, e mi guardano con occhi malvagi ogni volta che metto piede fuori da quella porta. Devono avere una fame incredibile, per pensare che valga la pena mangiarmi.\n\nDevo fare rapporto alla mia compagna di squadra, Rane Yorick, degli Inseguitori della Morte. E per arrivare da Rane mi serve aiuto contro quei lupi.\n\nTi prego, scortami! E là fuori di lupi ce ne sono tanti, quindi avremo più possibilità se hai degli amici che possono aiutare...", enHash = "c5c94af7", vanilla = true },
        objectives = { it = "Scorta Erland tra i lupi, fino a Rane Yorick.", enHash = "7ccd2092", vanilla = true },
        progress = { it = "Ti prego, fa' in fretta. C'è molto pericolo qui intorno e non possiamo restare fermi a chiacchierare.", enHash = "b6773c22", vanilla = true },
        reward = { it = "Grazie dell'aiuto, $N. Temevo che Erland fosse stato sopraffatto dai pericoli di Silverpine. Con il tuo aiuto, vedo che non è così.", enHash = "b54d5d0a", vanilla = true },
    },
    [436] = {
        title = { it = "Ironband's Excavation", enHash = "73355767", vanilla = true },
        text = { it = "Prospector Ironband dirige uno scavo di antiche rovine a est del lago. Ultimamente i suoi progressi sono lenti, soprattutto considerando tutti i rifornimenti che gli abbiamo mandato.\n\nIronband è un nano tosto e onesto, che tiene ai risultati: per questo temo che ci siano forze all'opera contro di lui.\n\nVa' all'Ironband's Excavation e parla con Magmar Fellhew. È lui a gestire i dettagli del sito e saprà perché c'è questo rallentamento.\n\nPer arrivare al sito di scavo, gira intorno alla punta meridionale del lago e poi va' a est.", enHash = "4011cde0", vanilla = true },
        objectives = { it = "Parla con Explorer Fellhew.", enHash = "8649c948", vanilla = true },
        reward = { it = "Jern vuole sapere qual è il rallentamento, eh?\n\nIronband sta mettendo insieme il suo ultimo rapporto sui progressi con tutti i dettagli, ma io posso dirti questo:\n\nSono i trogg!!", enHash = "4e076382", vanilla = true },
    },
    [437] = {
        title = { it = "I Dead Fields", enHash = "266c3cc6", vanilla = true },
        text = { it = "I nostri primi rapporti di ricognizione su Silverpine dicono che i Rot Hide hanno una base in una vecchia fattoria a nord, i Dead Fields. Abbiamo lanciato piccoli attacchi contro di loro, ma ogni volta vengono rinforzati dalla banshee Nightlash, che con la sua magia mette in rotta le nostre forze.\n\nVogliamo Nightlash distrutta.\n\nVa' ai Dead Fields e assalta i Rot Hide. Se non vedi Nightlash, uccidi i Rot Hide finché non compare, e poi sconfiggila.\n\nLa sua essenza si ridurrà in polvere. Portami quella polvere come prova.", enHash = "ed723945", vanilla = true },
        objectives = { it = "Uccidi gli gnoll Rot Hide ai Dead Fields.\n\nQuando compare Nightlash, uccidila.\n\nPorta l'Essence of Nightlash a High Executor Hadrec, al Sepulcher.", enHash = "3208101c", vanilla = true },
        progress = { it = "Hai sconfitto Nightlash, $N? Il nostro successo contro i Rot Hide dipende dalla sua distruzione!", enHash = "9b11def7", vanilla = true },
        reward = { it = "Ho saputo della tua incursione riuscita contro i Rot Hide, $N, e questa essenza è la prova della morte di Nightlash.\n\nOggi il Flagello ha perso terreno. Il tuo valore per i Reietti cresce.", enHash = "43502470", vanilla = true },
    },
    [438] = {
        title = { it = "Il Decrepit Ferry", enHash = "bbf5dfcf", vanilla = true },
        text = { it = "$N, abbiamo scoperto un nuovo covo del Flagello: il Decrepit Ferry. Il traghetto si trova a est del Sepulcher ed è pattugliato fittamente da Rot Hide e altri non morti.\n\nCi dev'essere un motivo per l'occupazione della zona da parte del Flagello. Va' al Decrepit Ferry e scopri perché il Flagello è lì.", enHash = "77aa1508", vanilla = true },
        objectives = { it = "Va' al Decrepit Ferry.\n\nCerca il motivo della presenza del Flagello.", enHash = "f536219b", vanilla = true },
        reward = { it = "Dentro questa barca è ammassata una pila di cadaveri avvolti in teli. E guardando a est, oltre il Lordamere Lake, si scorge un molo sulla sponda opposta, sulla Fenris Isle.\n\nLa sorte di quei cadaveri dev'essere sulla Fenris Isle.", enHash = "f37e209c", vanilla = true },
    },
    [439] = {
        title = { it = "Indizi sui Rot Hide", enHash = "d59c4c65", vanilla = true },
        text = { it = "Tra i cadaveri spunta una mano, scoperta. È la mano di una donna, butterata dalla piaga ma relativamente fresca.\n\nSulla mano c'è un anello. Sfilandolo ed esaminandolo si scopre un'incisione:\n\n\"Per Deliah\"", enHash = "ec9bac8d", vanilla = true },
        objectives = { it = "Porta Deliah's Ring a High Executor Hadrec, al Sepulcher.", enHash = "164efdcd", vanilla = true },
        progress = { it = "$N. Sei $Gtornato:tornata;, quindi immagino che le tue indagini abbiano dato frutto?", enHash = "6a439447", vanilla = true },
        reward = { it = "Dici che questo anello era portato da una donna, uccisa di recente?\n\nL'unico posto qui vicino da cui può venire un corpo simile sono le fosse comuni di Tirisfal. Gli gnoll Rot Hide devono portare quei cadaveri sulla Fenris Isle!", enHash = "5b8bf39b", vanilla = true },
    },
    [440] = {
        title = { it = "L'anello inciso", enHash = "936edcf9", vanilla = true },
        text = { it = "Se vuoi trovare il marito o l'innamorato che ha dato a Deliah il suo anello... allora parla con Magistrate Sevren, a Brill. Dovrebbe avere i registri delle morti recenti e, con un po' di fortuna, può scoprire chi è Deliah.\n\nMa non ci spererei. Chiunque le abbia dato l'anello è probabilmente morto. O, se è non morto, probabilmente di Deliah non gli importa più.", enHash = "6a33ad10", vanilla = true },
        objectives = { it = "Porta Deliah's Ring a Magistrate Sevren, a Brill.", enHash = "e2b2f4ba", vanilla = true },
        progress = { it = "Salve, $N. Cosa ti riporta a Brill?", enHash = "dd1fd594", vanilla = true },
        reward = { it = "Una Deliah viveva a Brill non molto tempo fa. Fu sepolta nella fossa comune, ma se quello che dici è vero, allora gli gnoll Rot Hide devono aver rubato il suo corpo e averlo portato a Silverpine.\n\nI Rot Hide, come tutto il Flagello, vanno distrutti. Confido che tu ti stia adoperando perché accada.", enHash = "078f2e2a", vanilla = true },
    },
    [441] = {
        title = { it = "Raleigh e l'Undercity", enHash = "4648464d", vanilla = true },
        text = { it = "Deliah aveva un marito, Raleigh, che ora vive nell'Undercity. Se la Deliah che viveva a Brill è quella a cui apparteneva l'anello, Raleigh lo saprà.\n\nRaleigh si trova nel Trade Quarter dell'Undercity.", enHash = "1b03e06c", vanilla = true },
        objectives = { it = "Porta Deliah's Ring a Raleigh.", enHash = "64cfb142", vanilla = true },
        progress = { it = "Ci conosciamo?", enHash = "8ede6569", vanilla = true },
        reward = { it = "Sì, questo anello era di mia moglie. La sua sorte è stata la sorte di tutti quelli che non reggono a questi tempi duri. Non provo nulla per la sua morte, né per la storia che mi racconti del suo corpo rubato.\n\nSentimenti simili in me si sono raffreddati da tempo. Ma un desiderio brucia ancora nel mio cuore morto, $N.\n\nIl desiderio di vendetta.", enHash = "a905e57d", vanilla = true },
    },
    [442] = {
        title = { it = "Assalto alla Fenris Isle", enHash = "72929838", vanilla = true },
        text = { it = "È giunto il momento di assaltare la roccaforte del Flagello in Silverpine: la Fenris Isle.\n\nDevi tornare sull'isola e distruggere Thule Ravenclaw. Voglio la sua testa!\n\nQuesta missione è tanto pericolosa quanto vitale, $N. Non devi fallire.", enHash = "930656c3", vanilla = true },
        objectives = { it = "Porta Thule's Head a High Executor Hadrec, al Sepulcher.", enHash = "d96629a4", vanilla = true },
        progress = { it = "Non si può permettere al Flagello di restare in Silverpine, $N. Torna da me quando avrai la prova della morte di Thule.", enHash = "1a90631c", vanilla = true },
        reward = { it = "La morte di Thule Ravenclaw non è stata cosa da poco, $N. Renferrel mi dice che le energie liberate quando hai distrutto Thule si sono sentite fin qui, al Sepulcher.\n\nLe tue azioni risuonano tra le file dei Reietti. Il tuo valore per noi cresce.", enHash = "b9f7942e", vanilla = true },
    },
    [443] = {
        title = { it = "Rot Hide Ichor", enHash = "d5ec927c", vanilla = true },
        text = { it = "Prima di lanciare un assalto alla Fenris Isle, dobbiamo capire chi c'è dietro gli gnoll Rot Hide. I nostri speziali credono che la loro origine stia nello strano fluido che scorre nei loro corpi.\n\nVa' sulla Fenris Isle, a est del Decrepit Ferry, e raccogli il Rot Hide Ichor dagli gnoll che vi troverai. Portalo ad Apothecary Renferrel, di stanza fuori dal Sepulcher.", enHash = "9f52fb32", vanilla = true },
        objectives = { it = "Porta 8 bottiglie di Rot Hide Ichor ad Apothecary Renferrel, al Sepulcher.", enHash = "145c757b", vanilla = true },
        progress = { it = "Hai il Rot Hide Ichor, $N?", enHash = "87af0a34", vanilla = true },
        reward = { it = "Molto bene. Questo Ichor ci aiuterà a capire la natura dei Rot Hide, e forse ci mostrerà il loro punto debole...\n\n...ammesso che ne abbiano uno.", enHash = "96c19840", vanilla = true },
    },
    [444] = {
        title = { it = "Le origini dei Rot Hide", enHash = "641a58d8", vanilla = true },
        text = { it = "Ho ridotto l'Ichor che mi hai portato e l'ho separato nei suoi componenti di base. I miei risultati non sono conclusivi, ma ho stabilito che nella sua creazione sono state usate magie da stregone e negromantiche.\n\nMentre continuo a studiare l'Ichor, voglio che tu ne porti un campione a Bethor Iceshard, nell'Undercity. Bethor non è uno speziale, ma la sua conoscenza della magia può aiutare a sciogliere il mistero dei Rot Hide.\n\nVa'. Bethor lo troverai nel Magic Quarter dell'Undercity.", enHash = "0a68d1d8", vanilla = true },
        objectives = { it = "Porta il Sample Ichor a Bethor Iceshard, nell'Undercity.", enHash = "8fef6271", vanilla = true },
        progress = { it = "I miei studi richiedono grande concentrazione. Spero quindi che la tua visita non sia una frivolezza.", enHash = "61133af6", vanilla = true },
        reward = { it = "Questa sostanza è intrisa di incantesimi potenti, alcuni dei quali non vedo da tanto, tanto tempo...\n\nUn momento — devo invocare un incantesimo di divinazione...", enHash = "3391abbd", vanilla = true },
    },
    [445] = {
        title = { it = "Consegna alla Silverpine Forest", enHash = "fd0f15e7", vanilla = true },
        text = { it = "Il tempo è un lusso che non è concesso a chi è al servizio di Lady Sylvanas. Di sicuro ormai lo sai.\n\nCome membro della Royal Apothecary Society è mio dovere condividere le mie conoscenze con i colleghi, perché i nostri sforzi comuni possano un giorno dare alla Signora Oscura la nuova piaga che desidera tanto.\n\nPorta queste scoperte ad Apothecary Renferrel, di stanza al Sepulcher, nella Silverpine Forest. Segui le strade verso sud da Brill. Dall'Undercity va' a sud-ovest.", enHash = "fc46bbff", vanilla = true },
        objectives = { it = "Porta le scoperte di Apothecary Johaan ad Apothecary Renferrel, nella Silverpine Forest.", enHash = "f2d2a947", vanilla = true },
        progress = { it = "Che affari hai con me, $C?", enHash = "30cab3a0", vanilla = true },
        reward = { it = "Ah, che gentile da parte di Apothecary Johaan mandare le sue ricerche. Con tante novità qui a Silverpine, mi ero quasi scordato delle scoperte che arrivano da Lordaeron e dalle Tirisfal Glades. Il che mi ricorda che devo mandare presto quei campioni alla Necropolis.\n\nMa scusa le mie divagazioni. Trattieniti ancora a Silverpine, $N. Ci farebbe comodo $Gun:una; $C in gamba come te da queste parti.", enHash = "66ed6cc2", vanilla = true },
    },
    [446] = {
        title = { it = "Thule Ravenclaw", enHash = "79436689", vanilla = true },
        text = { it = "Questo Ichor è stato creato da un mio vecchio collega: Thule Ravenclaw. Prima della grande guerra era un mago giovane e promettente, ma quando il Re dei Lich salì al potere tradì i suoi confratelli e si alleò con il Flagello.\n\nNon immaginavo che fosse ancora vivo, né che guidasse i Rot Hide nelle loro incursioni contro di noi!\n\nConosco molti dei suoi incantesimi e posso aiutare a preparare una pozione per contrastarli. Riporta questa pergamena ad Apothecary Renferrel. Contiene le formule necessarie per la pozione.", enHash = "31ec5c4d", vanilla = true },
        objectives = { it = "Porta Bethor's Scroll ad Apothecary Renferrel, al Silverpine Sepulcher.", enHash = "a7c0ba59", vanilla = true },
        progress = { it = "Salve, $N. Cos'aveva da dire Bethor?", enHash = "d900d060", vanilla = true },
        reward = { it = "Questa pergamena è intrisa di magia potente. Non ho mai usato forze simili in una pozione... sarà una miscela potente, e dovrebbe servirti bene se attaccherai Thule nella sua roccaforte sulla Fenris Isle.", enHash = "31f31114", vanilla = true },
    },
    [447] = {
        title = { it = "Una ricetta per la morte", enHash = "3164862a", vanilla = true },
        text = { it = "I numeri di Arthas sono schiaccianti. Ma con una nuova piaga potremmo sterminare una volta per tutte sia l'esercito del Flagello sia l'infestazione umana.\n\nI miei studi hanno dimostrato che il sangue di ragno unito a una tossina ricavata dal cuore di un orso grigio dà un elisir letale. Raccogli campioni dai ragni dello Skittering Dark a nord-ovest e dagli orsi che vagano per la Silverpine Forest. Consegna i reagenti a Master Apothecary Faranell, della Royal Apothecary Society, nell'Undercity.", enHash = "d786ff74", vanilla = true },
        objectives = { it = "Raccogli 6 Grizzled Bear Heart e 6 campioni di Skittering Blood e consegnali a Master Apothecary Faranell, nell'Undercity.", enHash = "d2f554e4", vanilla = true },
        progress = { it = "Salute, $C. Che affari hai con la Royal Apothecary Society?", enHash = "bfe3fb84", vanilla = true },
        reward = { it = "Che gentile da parte di Apothecary Renferrel mandarti da me, $N. Questi campioni si riveleranno davvero utili alla causa. Comincerò subito a studiarne le proprietà tossiche e contaminanti.", enHash = "b96338e9", vanilla = true },
    },
    [448] = {
        title = { it = "Rapporto a Hadrec", enHash = "1db2c77e", vanilla = true },
        text = { it = "Prima di lanciare un assalto alla Fenris Isle, fa' rapporto a High Executor Hadrec. Potrebbe avere altre informazioni o l'equipaggiamento che ti servirà.", enHash = "445ec729", vanilla = true },
        objectives = { it = "Fa' rapporto a High Executor Hadrec, al Sepulcher.", enHash = "1fcaceb0", vanilla = true },
        reward = { it = "Se quello che dice Bethor è vero, allora Thule Ravenclaw è una forza di cui occuparsi, e presto.\n\nPer aiutarti in questo compito, puoi prendere qualcosa dal nostro arsenale qui...", enHash = "dee06ad8", vanilla = true },
    },
    [449] = {
        title = { it = "Il rapporto degli Inseguitori della Morte", enHash = "41a44db9", vanilla = true },
        text = { it = "Anche se le ferite di Quinn stanno guarendo, voglio far arrivare il nostro rapporto a High Executor Hadrec il più in fretta possibile. Contiene informazioni vitali per l'occupazione di Silverpine da parte dei Reietti.", enHash = "cebc2eb9", vanilla = true },
        objectives = { it = "Porta il Deathstalker Report a High Executor Hadrec, al Sepulcher.", enHash = "45667fbb", vanilla = true },
        progress = { it = "Hai scoperto che fine hanno fatto gli Inseguitori della Morte?", enHash = "a8218e8c", vanilla = true },
        reward = { it = "Non avevo messo in conto quanto fosse forte la presenza del Flagello nella Silverpine Forest, né i guai che i nostri Inseguitori della Morte avrebbero incontrato nelle loro ricognizioni.\n\nIl tuo aiuto ai nostri Inseguitori della Morte è stato inestimabile, $N. E ne riceverai un encomio.", enHash = "9161f94a", vanilla = true },
    },
    [450] = {
        title = { it = "Una ricetta per la morte", enHash = "3164862a", vanilla = true },
        text = { it = "Puoi renderti ancora utile alla Royal Apothecary Society, $N.\n\nQuando Arugal ha lanciato la sua magia infame sulla foresta, ha maledetto uno dei nostri membri più promettenti, Apothecary Berard. Ora Berard è un servo senza mente di Arugal e per noi è inutile. Ma le sue scoperte potrebbero valere qualcosa. Studiava un'antica piaga che secoli fa sterminò tutta la vita acquatica del Lake Lordamere.\n\nRecupera Berard's Journal dal suo studio nella Pyrewood Village Inn e portalo ad Apothecary Renferrel.", enHash = "a87195d6", vanilla = true },
        objectives = { it = "Recupera a Pyrewood Village il diario di Apothecary Berard e portalo ad Apothecary Renferrel, al Sepulcher.", enHash = "d76f9ef2", vanilla = true },
        progress = { it = "Vedo che sei $Gtornato:tornata;, $N.", enHash = "9d66aa18", vanilla = true },
        reward = { it = "Il diario di Apothecary Berard! Ma sei davvero $Gcoraggioso:coraggiosa;, $N. Ora vediamo cosa combinava Berard prima di impazzire...", enHash = "ea5f592e", vanilla = true },
    },
    [451] = {
        title = { it = "Una ricetta per la morte", enHash = "3164862a", vanilla = true },
        text = { it = "Stando a Berard's Journal, il muschio dei Lake Skulker e dei Lake Creeper potrebbe tornare utile alla nostra impresa di preparare una nuova piaga. Quelle bestie vivono sulle isole del Lake Lordamere, a est.\n\nParla anche di un rarissimo Hardened Tumor che aveva trovato su un murloc Vile Fin. A quanto pare il tumore è così raro che Berard riuscì a procurarsene uno solo.\n\nRaccogli campioni del muschio e il raro Hardened Tumor e portali a Master Apothecary Faranell, nell'Undercity.", enHash = "bda831f6", vanilla = true },
        objectives = { it = "Porta 6 campioni di Lake Creeper Moss, 6 campioni di Lake Skulker Moss e un Hardened Tumor a Master Apothecary Faranell, nell'Undercity.", enHash = "50c85190", vanilla = true },
        progress = { it = "Cosa ti riporta nell'Undercity, $N?", enHash = "692bbe5d", vanilla = true },
        reward = { it = "Che colpo per la Royal Apothecary Society, perdere Berard. Ma grazie al tuo duro lavoro e alle diligenti ricerche di Apothecary Renferrel, gli studi di Berard saranno ancora utili alla causa della Signora Oscura.\n\nSiamo sul punto di ottenere qualcosa di grande, $N. Se non fossi così $Gesperto:esperta; nelle vie del combattimento, cercherei di reclutarti nella Society.", enHash = "84cf4c71", vanilla = true },
    },
    [452] = {
        title = { it = "Imboscata a Pyrewood", enHash = "9986896b", vanilla = true },
        text = { it = "Sei $Garrivato:arrivata; giusto in tempo, $N!\n\nIl Pyrewood Council tornerà da un momento all'altro. Arugal ha altre faccende di cui occuparsi nel maniero. Usa il Council come semplici burattini per tenere sotto controllo i servi senza mente di Pyrewood. Ma credo che senza la guida del Pyrewood Council i figli di Arugal si rivolteranno contro il loro padrone.\n\nNon posso affrontarli tutti da sola. Ho bisogno che tu mi aiuti. Insieme possiamo annientare il Council per Lady Sylvanas.", enHash = "9e0333bc", vanilla = true },
        objectives = { it = "Aiuta Deathstalker Faerleia a uccidere il Pyrewood Council.", enHash = "a2a44c11", vanilla = true },
        reward = { it = "Hai combattuto come $Gun vero discepolo:una vera discepola; della Signora Oscura, $N. Ora che il consiglio è morto, forse potremo prendere il controllo di questa città una volta per tutte e cacciare Arugal da Shadowfang Keep. Ti rendo onore!", enHash = "0c651b7c", vanilla = true },
    },
    [453] = {
        title = { it = "Trovare la Shadowy Figure", enHash = "78ea6f11", vanilla = true },
        text = { it = "Buona fortuna, $N. Spero che tu trovi quel tipo, e spero che tu lo trovi vivo.\n\nSe ha lasciato la sicurezza di Darkshire, può essere finito preda delle bestie selvatiche.", enHash = "dc1af39e", vanilla = true },
        objectives = { it = "Trova la Shadowy Figure. I tuoi indizi:\n\nNon è di Darkshire.\n\nÈ una persona nervosa e agitata.\n\nHa lasciato Darkshire ed è andato a ovest.", enHash = "53723837", vanilla = true },
        progress = { it = "Chi sei?? Lasciami in pace!", enHash = "5e3b1310", vanilla = true },
        reward = { it = "<Jitters sospira...>\n\nSì, sono io l'autore di quel libro. Alla fine mi hai trovato, eh?\n\nBe', se hai letto quel diario... allora ne sai solo metà!", enHash = "139067ae", vanilla = true },
    },
    [454] = {
        title = { it = "Dopo l'imboscata", enHash = "f2fb2f67", vanilla = true },
        text = { it = "Prima di questa... faccenda, facevamo avanti e indietro trasportando i barili di polvere. Ora dobbiamo dividerci il lavoro: Miran prende i barili e io sorveglio gli altri.\n\nNon me la sento di lasciare che Miran porti il resto del carico da solo. Quando sarà pronto a partire, potresti scortarlo nel prossimo viaggio?", enHash = "1b5dab37", vanilla = true },
        objectives = { it = "Parla con Miran.", enHash = "c36218d7", vanilla = true },
        reward = { it = "Salve, $C.\n\nMi scorterai fino al sito di scavo? Che bella notizia... Dopo Saean e i suoi compari, chissà cos'altro hanno in serbo i Dark Iron.\n\nComunque, lascia che faccia gli ultimi controlli. Riparlami quando sei $Gpronto:pronta; a partire.", enHash = "545439fe", vanilla = true },
    },
    [455] = {
        title = { it = "Il varco di Algaz", enHash = "60d6a114", vanilla = true },
        text = { it = "Gli orchi del clan Dragonmaw hanno un rifugio nelle Wetlands. E adesso si sono estesi dentro Dun Algaz! Non possiamo lasciare che mantengano questo appiglio, o Loch Modan resterà tagliato fuori da Menethil Harbor, il nostro porto e la nostra roccaforte nelle Wetlands.\n\nSfonda attraverso Dun Algaz fino alle Wetlands di là, e già che ci sei uccidi qualche orco! Presentati a Valstag Ironjaw, a Menethil Harbor.\n\nMenethil si raggiunge attraverso Dun Algaz, poi a nord lungo la strada, poi a ovest al bivio.\n\nContiamo su di te, $N. Non fallire.", enHash = "610396fd", vanilla = true },
        objectives = { it = "Attraversa Dun Algaz.\n\nUccidi 8 Dragonmaw Scout e 6 Dragonmaw Grunt.\n\nPresentati a Valstag Ironjaw, a Menethil Harbor.", enHash = "40ec473d", vanilla = true },
        progress = { it = "Vieni da Loch Modan? Com'è la situazione degli orchi all'Algaz Gate?", enHash = "9967eeaf", vanilla = true },
        reward = { it = "Il tuo rapporto è pieno di brutte notizie!\n\nVedo che i Dragonmaw stanno facendo una mossa decisa dentro Algaz. Di solito i Dragonmaw se ne stanno nascosti sulle colline. Cosa li abbia spinti a riversarsi su Algaz resta un mistero...\n\nGrazie, $N. E probabilmente vorremo il tuo aiuto per occuparci di questi orchi.", enHash = "14899844", vanilla = true },
    },
    [456] = {
        title = { it = "L'equilibrio della natura", enHash = "253fc0dd", vanilla = true },
        text = { it = "Salute, $N. Sono Conservator Ilthalaine. Il mio compito a Shadowglen è assicurarmi che l'equilibrio della natura venga mantenuto.\n\nQuest'anno le piogge di primavera sono state particolarmente abbondanti: alcune bestie della foresta sono prosperate, mentre altre hanno sofferto.\n\nPurtroppo i Nightsaber e i Thistle Boar sono diventati troppo numerosi. Shadowglen può produrre solo una certa quantità di cibo per le sue bestie. Parti, giovane $C, e riduci il numero di Thistle Boar e di Nightsaber, perché l'armonia della natura sia preservata.", enHash = "4738dd6f", vanilla = true },
        objectives = { it = "Uccidi 7 Young Nightsaber e 4 Young Thistle Boar, poi torna da Conservator Ilthalaine.", enHash = "9523c51b", vanilla = true },
        progress = { it = "C'è ancora del lavoro da fare, $N. Torna da me quando avrai ridotto il numero di Nightsaber e di Thistle Boar.", enHash = "f7ea6ea6", vanilla = true },
        reward = { it = "Hai svolto bene il tuo compito, $N.", enHash = "5b771f62", vanilla = true },
    },
    [457] = {
        title = { it = "L'equilibrio della natura", enHash = "253fc0dd", vanilla = true },
        text = { it = "Ridurre il numero delle creature più giovani qui a Shadowglen è stato un buon inizio, $N, ma c'è ancora del lavoro da fare.\n\nSe non si affronta il problema, le risorse della foresta si esauriranno troppo in fretta. Uccidere le bestie della natura è un male necessario, per il bene di tutti coloro che condividono questa terra. Addentrati nella foresta e abbatti i Mangy Nightsaber e i Thistle Boar, in nome dell'equilibrio.", enHash = "06d6b33c", vanilla = true },
        objectives = { it = "Conservator Ilthalaine ha bisogno che tu uccida 7 Mangy Nightsaber e 7 Thistle Boar.", enHash = "08a24a9d", vanilla = true },
        progress = { it = "Il tuo compito non è ancora concluso, $N. Torna da me quando saranno stati uccisi 8 Mangy Nightsaber e 8 Thistle Boar.", enHash = "525b2880", vanilla = true },
        reward = { it = "Hai dimostrato bene la tua dedizione alla natura, $N. $GUn giovane:Una giovane; $C come te ha un futuro promettente.", enHash = "39b6f288", vanilla = true },
    },
    [458] = {
        title = { it = "La protettrice dei boschi", enHash = "f21824f9", vanilla = true },
        text = { it = "Grazie al cielo sei qui, $C. Strane notizie mi sono giunte attraverso i sussurri degli spiriti della foresta.\n\nLa misteriosa protettrice dei boschi, Tarindrella, è tornata a Shadowglen. Da anni la presenza della driade non si avvertiva nelle foreste di Kalimdor. Se ha fatto ritorno in questa terra, di certo qualcosa non va.\n\nCerca Tarindrella e scopri di cosa si occupa nel nostro boschetto. Una delle Sentinelle l'ha vista a sud-ovest di Aldrassil.", enHash = "19f4ab9a", vanilla = true },
        objectives = { it = "Trova la driade chiamata Tarindrella.", enHash = "636c35d0", vanilla = true },
        reward = { it = "Vedo che mi hai trovata, giovane $R. Melithar è un druido saggio, se ti ha mandato da me.", enHash = "f528abc7", vanilla = true },
    },
    [459] = {
        title = { it = "La protettrice dei boschi", enHash = "f21824f9", vanilla = true },
        text = { it = "Qualcosa di malvagio si sta preparando nelle foreste di Teldrassil. Guarda lungo le colline, dove un tempo vivevano i pacifici furbolg. Hanno abbandonato le loro case e si stanno radunando sotto il nome della tribù Gnarlpine.\n\nSolo la corruzione del malvagio Fel Moss può causare una simile trasformazione. I Grell e i Grellkin hanno infestato la zona e minacciano gli abitanti di Shadowglen.\n\nAffronta quei Grell e Grellkin, $N, e scopri se sono davvero caduti sotto l'incantesimo del malvagio Fel Moss.", enHash = "a2ed61f2", vanilla = true },
        objectives = { it = "Raccogli 8 Fel Moss e portali a Tarindrella.", enHash = "db0d93df", vanilla = true },
        progress = { it = "Chiarisci i miei sospetti, $N. Portami 8 Fel Moss.", enHash = "850d15eb", vanilla = true },
        reward = { it = "Il tuo servizio alle creature di Shadowglen merita una ricompensa, $N.\n\nPerò hai confermato i miei timori. Se i Grell sono stati contaminati dal Fel Moss, si può solo immaginare cosa sia accaduto alla tribù Gnarlpine, i furbolg che un tempo vivevano qui.\n\nSe ti troverai a Dolanaar, valente $C, cerca il sapiente druido Athridas Bearmantle. Anche lui ha a cuore la salute della foresta.", enHash = "b9263d20", vanilla = true },
    },
    [460] = {
        title = { it = "Riposare in pezzi", enHash = "0836508e", vanilla = true },
        text = { it = "Non hai l'aria di un Rot Hide. Bene. Avevo perso la speranza...\n\nMi chiamo Alaric, e un tempo ero il servitore capo e la guardia del corpo di Thule. Usò la sua magia per \"proteggermi\" dalla Piaga della Non Morte, ma il suo incantesimo mi diede invece una non vita da cui non posso fuggire. E dopo aver creato i maledetti gnoll Rot Hide, Thule mi decapitò... e diede la mia testa agli gnoll come giocattolo!\n\nTi prego, portami dal mio corpo. Credo che gli gnoll l'abbiano sepolto qui, a Fenris Keep, vicino alla stalla, in una tomba senza nome.", enHash = "eab06706", vanilla = true },
        objectives = { it = "Porta Alaric's Head alla sua tomba.", enHash = "e6cb138c", vanilla = true },
        progress = { it = "Questa tomba è stata scavata in fretta.", enHash = "bcfbb290", vanilla = true },
        reward = { it = "Grazie, $N. Temevo che gli gnoll avessero distrutto il mio corpo. È un bene sapere che non l'hanno fatto.", enHash = "4493f529", vanilla = true },
    },
    [461] = {
        title = { it = "La nicchia nascosta", enHash = "211fae5e", vanilla = true },
        text = { it = "So di una nicchia nascosta dentro il maniero che custodisce un oggetto caro a Thule e ai suoi vecchi colleghi. Custodisce anche qualcosa che potresti trovare utile. Portami là!\n\nL'alcova è nella torre sud-occidentale del maniero, dietro uno scaffale impolverato.\n\nPrendi il mio corpo, ma lascia i miei stivali. Tanto non mi sono mai andati bene...", enHash = "1a849cfb", vanilla = true },
        objectives = { it = "Porta Alaric all'alcova nascosta.", enHash = "2f622f15", vanilla = true },
        progress = { it = "È questo il punto! Portami più vicino...", enHash = "b65aa5b6", vanilla = true },
        reward = { it = "Ecco fatto, è aperta. Lasciami qui. In questo maniero ho passato i giorni migliori della mia vita, e il pensiero di riposare fra le sue mura mi conforta.\n\nMi raccomando, chiudi bene l'alcova — non voglio che quei Rot Hide mi trovino.\n\nAh, e prendi questo. Te lo sei $Gguadagnato:guadagnata;.", enHash = "a7266f59", vanilla = true },
    },
    [463] = {
        title = { it = "Il Greenwarden", enHash = "40857bb9", vanilla = true },
        text = { it = "Hai sentito parlare del Greenwarden? Non è che lo stai cercando, vero? Be', io dico che sei $Gpazzo:pazza; se è così, ma chi sono io per impedire a $Gun folle:una folle; di andare incontro alla sua morte?\n\nSe cerchi quella bestia, ho sentito dire che sta nella palude, a est della strada dove si biforca per Dun Modr. Se ne sta in agguato là in mezzo ai crocolisk... e a cose peggiori!\n\nE lascia qui i tuoi soldi. Dove stai andando non ti serviranno... e non vorrai scheggiare un dente al vecchio Greenie con il tuo oro, quando ti morderà in due, vero?", enHash = { "8c87659a", "e5a13a1d" }, vanilla = true },
        objectives = { it = "Trova il Greenwarden.", enHash = "13eacf1c", vanilla = true },
        reward = { it = "Le radici e le felci parlano bene di te, $Gpiccolo:piccola;. Ho molti nomi, ma rispondo solo a pochi. Tu però puoi chiamarmi Rethiel.\n\nE devi ascoltare... perché queste terre piangono da ferite infette, e io ti affiderei il compito di risanarle.", enHash = "362ab0f1", vanilla = true },
    },
    [464] = {
        title = { it = "Stendardi di guerra", enHash = "b4ac658f", vanilla = true },
        text = { it = "Il clan orchesco Dragonmaw fu quasi distrutto alla fine della Seconda Guerra, dopo che perse il controllo dei suoi draghi rossi addomesticati. I draghi non erano molto contenti dei loro vecchi padroni, e diedero ai Dragonmaw una caccia feroce. I pochi rimasti fuggirono da Grim Batol e si rifugiarono sulle montagne a est della Whelgar's Excavation.\n\nOra hanno ripreso forza e hanno un accampamento a nord-est di Menethil.\n\nVogliamo che tu attacchi quell'accampamento. Raccogli e portami i loro stendardi di guerra come prova.", enHash = "ece042b4", vanilla = true },
        objectives = { it = "Porta 8 Dragonmaw War Banner a Captain Stoutfist.", enHash = "5e3279e7", vanilla = true },
        progress = { it = "Hai attaccato l'accampamento dei Dragonmaw?", enHash = "75801178", vanilla = true },
        reward = { it = "Ben combattuto, $N. I Dragonmaw non sono la minaccia che erano quando avevano i draghi, ma restano avversari feroci.\n\nI Dragonmaw sono guidati da Nek'rosh, figlio di Nekros, che anni fa era a capo dei Dragonmaw. Nekros usò una magia potente per domare i Red Dragon, ma quando quella magia gli venne meno... i draghi non furono contenti.\n\nNekros fu ucciso, e suo figlio ha giurato vendetta contro i draghi che uccisero suo padre.", enHash = "354ca46f", vanilla = true },
    },
    [465] = {
        title = { it = "La mossa di Nek'rosh", enHash = "dea37b89", vanilla = true },
        text = { it = "Mentre combattevi i Dragonmaw, abbiamo scoperto altri dei loro piani.\n\nNek'rosh ha costruito catapulte e punta ad assediare Menethil! E con i combattimenti a Dun Algaz siamo di fatto tagliati fuori dai rinforzi!\n\nDevi eliminare quelle catapulte. Sono nell'accampamento dei Dragonmaw.\n\nEcco, prendi quest'esca. Apriti la strada fino alle catapulte e dai loro fuoco con l'esca.\n\nE quando l'avrai fatto, trova e uccidi Nek'rosh. Dobbiamo tagliare la testa a questa bestia dei Dragonmaw.", enHash = "9ac783e1", vanilla = true },
        objectives = { it = "Distruggi le catapulte dei Dragonmaw.", enHash = "a005f998", vanilla = true },
        progress = { it = "La prima catapulta è davanti a te. Le darai fuoco?", enHash = "0e855002", vanilla = true },
        reward = { it = "Metti un po' di esca sulla catapulta, poi fai scoccare una scintilla.\n\nLa fiamma divampa e si propaga in fretta!", enHash = "bb01ea18", vanilla = true },
    },
    [466] = {
        title = { it = "Alla ricerca dell'Incendicite", enHash = "6c9c03d4", vanilla = true },
        text = { it = "Ho sentito dire che un minerale raro, l'Incendicite, è stato trovato nelle Wetlands, in una grotta a nord-ovest di Algaz Gate. L'Incendicite è roba instabile e difficile da usare senza saltare in aria, ma sono sicuro che, fuso nel modo giusto, potrebbe dare proiettili da cannone che picchiano davvero forte!\n\nPortami dell'Incendicite Ore e troverò qualcuno abbastanza coraggioso da sperimentarci sopra.\n\nAh, e per estrarre quel minerale da un filone ti servirà l'abilità in estrazione mineraria. Se non ce l'hai, allora... portati in quella grotta un amico che ce l'abbia!", enHash = "19f1b045", vanilla = true },
        objectives = { it = "Porta 6 Incendicite Ore a Pilot Stonegear, nel Dun Morogh.", enHash = "c24bc3d0", vanilla = true },
        progress = { it = "Dov'è quel minerale, $N?!", enHash = "7e6bae66", vanilla = true },
        reward = { it = "Hai preso il minerale! Ben fatto, $N! Metto subito qualcuno a lavorarci. Speriamo che non si faccia saltare in aria!", enHash = "7909ed88", vanilla = true },
    },
    [467] = {
        title = { it = "La ricerca di Stonegear", enHash = "3c086a28", vanilla = true },
        text = { it = "Pilot Stonegear ama la sua macchina d'assedio, come dovrebbe fare ogni pilota! Ed è sempre in cerca di nuovi modi per aumentare la potenza di fuoco del suo carro!\n\nHa sentito voci su un minerale raro e cerca qualcuno che vada a trovarglielo. Se ti cominciano a prudere i piedi, cerca Stonegear allo Steelgrill's Depot, nel Dun Morogh, e senti cosa vuole.", enHash = "85eb15dd", vanilla = true },
        objectives = { it = "Parla con Pilot Stonegear.", enHash = "bfcfe3ee", vanilla = true },
        reward = { it = "Salve, $N. Sei qui per l'incarico che ho, eh? Fa piacere vedere $Gun giovane:una giovane; $R come te con il sangue che ribolle all'idea dell'avventura!", enHash = "dfc968d4", vanilla = true },
    },
    [468] = {
        title = { it = "Presentati a Mountaineer Rockgar", enHash = "755b8d9f", vanilla = true },
        text = { it = "Mountaineer Rockgar cerca volontari per una missione attraverso Dun Algaz e dentro le Wetlands.\n\nSe vuoi bagnarti gli stivali in quella contea fradicia a nord, parla con Rockgar a Dun Algaz. Dun Algaz è a nord lungo la strada, oltre la torre di guardia.", enHash = "4b87ea11", vanilla = true },
        objectives = { it = "Parla con Mountaineer Rockgar.", enHash = "bb88fd22", vanilla = true },
        reward = { it = "Salve, $C! Sei qui per la missione di ricognizione, vero? Benissimo!\n\nSpero che il tuo equipaggiamento sia in buone condizioni, perché questa missione \"di ricognizione\" si è trasformata in qualcosa di più sporco...", enHash = "54647bbf", vanilla = true },
    },
    [469] = {
        title = { it = "Consegna quotidiana", enHash = "c2f9ea1b", vanilla = true },
        text = { it = "Salve, $Gviaggiatore:viaggiatrice;!\n\nNon è che per caso stai andando verso Menethil? Se non ci vai, ti consiglierei di fermartici: è un buon posto per comprare provviste e anche per farsi una pinta e rilassarsi.\n\nOra, se per caso stai andando proprio da quelle parti, non ti dispiacerebbe portare questo fascio di pelli di crocolisk a James Halloran, il conciatore?\n\nLo farei io, ma mia moglie è di pessimo umore ultimamente, e vorrei rimandare il più possibile il momento di affrontarla.", enHash = "19dfd124", vanilla = true },
        objectives = { it = "Consegna il Bundle of Crocolisk Skins a James Halloran, il conciatore, a Menethil Harbor.", enHash = "e3305946", vanilla = true },
        progress = { it = "Salve, $C. Posso interessarti un paio di stivali? O magari delle pelli conciate di fresco?", enHash = "7a25078d", vanilla = true },
        reward = { it = "Mmh, questo viene da Einar, giusto? È quasi una settimana che non mi porta le pelli di persona. Di sicuro sono screzi con la moglie!\n\nForse prima o poi manderò mia moglie a parlare con Sida...", enHash = "26ccb2f0", vanilla = true },
    },
    [470] = {
        title = { it = "A frugare nella melma", enHash = "c419c678", vanilla = true },
        text = { it = "Durante la mia visita settimanale all'Ironbeard's Tomb sono stata attaccata da orribili melme gocciolanti! Naturalmente sono andata nel panico.\n\nHo tirato la mia borsa addosso a una di loro, ma non è servito a niente! La melma se l'è risucchiata... Per fortuna mi ha dato il tempo di scappare.\n\nLa brutta notizia è che mi serve davvero il contenuto della borsa!\n\nNon so a quale melma ho tirato la borsa: erano tutte identiche! L'Ironbeard's Tomb è a nord-est di qui, vicino a Dun Modr. Grazie infinite!", enHash = "402f397b", vanilla = true },
        objectives = { it = "Una delle melme all'Ironbeard's Tomb ha Sida's Bag: recuperala e riportagliela a Menethil Harbor.", enHash = "3c3a27ed", vanilla = true },
        progress = { it = "Hai trovato la mia borsa?", enHash = "aa9c2ba6", vanilla = true },
        reward = { it = "Oh, grazie, $N! Temevo che fosse persa per sempre!\n\n<Svuota in fretta sul terreno il contenuto della borsa ricoperta di melma, poi lo raccoglie.>\n\nMmh, a me non serve più granché, ma lavalo bene e sono sicura che potrai farne buon uso.", enHash = "5dc8e7e2", vanilla = true },
    },
    [471] = {
        title = { it = "I doveri dell'apprendista", enHash = "ead32317", vanilla = true },
        text = { it = "Ho mandato il mio apprendista nelle paludi a scuoiare qualcuno dei nostri famosi crocolisk giganti delle Wetlands. Quando non è tornato, sono andato a cercarlo... Diciamo che non è stato un bello spettacolo.\n\nLa levatrice dice che potrebbe cavarsela, ma intanto a me servono ancora le pelli!\n\n...Se ti va di ucciderne qualcuno in più, di quei bruti, non avrei niente in contrario, dopo quello che hanno fatto. I crocolisk li trovi a nord lungo la costa, oltre le capanne dei murloc.", enHash = "5a8733b2", vanilla = true },
        objectives = { it = "Raccogli 6 Giant Crocolisk Skin e portale a James Halloran, a Menethil Harbor.", enHash = "7126c4c4", vanilla = true },
        progress = { it = "Il mio apprendista è come un figlio per me. Sarà dura per lui vivere con una gamba sola.\n\nAh, $N, come va? Hai le mie pelli?", enHash = "e55c8952", vanilla = true },
        reward = { it = "Mmh... Non è che ti interesserebbe diventare il mio apprendista, vero?\n\nAh! No, sto scherzando. Sei troppo $Gvecchio:vecchia;, tanto per cominciare. E poi, a vederti, sembra che tu abbia altre ambizioni nella vita. Comunque, queste pelli che hai procurato sono ottime, e saprò farne buon uso.", enHash = "1f39632f", vanilla = true },
    },
    [472] = {
        title = { it = "La caduta di Dun Modr", enHash = "b72270f7", vanilla = true },
        text = { it = "Dun Modr è caduta in mano ai Dark Iron Dwarf!\n\nLe mie ferite sono gravi, $C. Gran parte del reggimento è stata uccisa! I bruti Dark Iron ci hanno attaccati prima che potessimo riorganizzarci dopo l'imboscata del Thandol Span.\n\nIl nostro comandante, Longbraid, ha suonato il corno della ritirata. Mentre lasciavamo la città sono stato colpito alla schiena da un'ascia vagante. È andato tutto nero.\n\nMi sono svegliato qui a Menethil, ma temo per i miei compagni soldati. Dentro di me arde ancora la speranza. Forse Longbraid è ancora vivo! Vedi se riesci a trovarlo vicino a Dun Modr, $R!", enHash = "c82251b2", vanilla = true },
        objectives = { it = "Cerca Longbraid vicino alla città di Dun Modr.", enHash = "01f01518", vanilla = true },
        reward = { it = "Quale $C $Gcoraggioso:coraggiosa; porta notizie da Menethil? Ah, ti chiamano $N.\n\nPorti speranza in una situazione senza speranza. È davvero una buona notizia che il giovane Harlo sia sopravvissuto. Mentre fuggiva ha ricevuto una ferita grave. Avevamo pochissimo tempo per mandarlo via sulla groppa dell'unico destriero rimasto al reggimento.\n\nMa ora ci troviamo in una situazione pericolosa. Dun Modr è caduta e siamo solo l'ombra del grande reggimento che eravamo.", enHash = "4a344ca2", vanilla = true },
    },
    [473] = {
        title = { it = "Presentati a Captain Stoutfist", enHash = "6921b03c", vanilla = true },
        text = { it = "$N. Il clan orchesco Dragonmaw sta mostrando la sua forza non solo ad Algaz. Captain Stoutfist ha chiesto di parlare con chi è disposto a dare aiuto contro questi orchi. È dentro la fortezza, nella sala di guerra.", enHash = "9912f1e6", vanilla = true },
        objectives = { it = "Parla con Captain Stoutfist.", enHash = "68a33ee5", vanilla = true },
        reward = { it = "$N. Valstag mi ha riferito i tuoi successi passati con gli orchi Dragonmaw a Dun Algaz. Sei $Gun:una; $R di valore.\n\nE ho un compito per te.", enHash = "5b37a5ea", vanilla = true },
    },
    [474] = {
        title = { it = "Sconfiggi Nek'rosh", enHash = "26860932", vanilla = true },
        text = { it = "Ora che le catapulte sono state bruciate, trova e uccidi Chieftain Nek'rosh.", enHash = "ae9e438d", vanilla = true },
        objectives = { it = "Uccidi Chieftain Nek'rosh.\n\nPorta Nek'rosh's Head a Captain Stoutfist.", enHash = "627cdbaf", vanilla = true },
        progress = { it = "Hai ucciso Nek'rosh?", enHash = "7b2455b0", vanilla = true },
        reward = { it = "Fatto con vigore, $N. Hai inferto un colpo decisivo al clan orchesco Dragonmaw. Forse non si riprenderanno mai. E la distruzione di quelle catapulte ha messo Menethil Harbor al sicuro.\n\nSei $Gun:una; $R di merito, e il regno di Ironforge ricompensa chi lo serve bene.", enHash = "9a3ff431", vanilla = true },
    },
    [475] = {
        title = { it = "Una brezza inquietante", enHash = "7b71caa6", vanilla = true },
        text = { it = "Una brezza inquietante soffia attraverso la foresta.\n\nGaerolas Talvethren serve come Grande Custode dei Druidi dell'Artiglio in letargo nel Ban'ethil Barrow Den. Il suo dovere di protettore scelto dei Dormienti è garantire la loro sicurezza, perché il loro patto con Ysera resti adempiuto.\n\nMa le notizie da Gaerolas tardano, e mi innervosisco. Va' a est, a Starbreeze Village, e riporta un rapporto di Gaerolas, così che io possa mettere a tacere i miei timori sapendo che i miei fratelli sognanti dormono al sicuro.", enHash = "7ab277ba", vanilla = true },
        objectives = { it = "Cerca Gaerolas Talvethren a Starbreeze Village.", enHash = "3f0632f1", vanilla = true },
        reward = { it = "Siano ringraziati gli spiriti della foresta, sei qui! Sapevo che Athridas avrebbe fiutato i guai e mandato aiuto.", enHash = "468d414e", vanilla = true },
    },
    [476] = {
        title = { it = "La corruzione dei Gnarlpine", enHash = "989ed0f7", vanilla = true },
        text = { it = "La tribù Gnarlpine è stata corrotta!\n\nI furbolg, un tempo pacifici, si sono rivoltati contro i protettori della foresta. Mi hanno teso un'imboscata mentre partivo per il Ban'ethil Barrow Den e poi hanno saccheggiato Starbreeze Village. Ursal the Mauler, il loro capo, usa i poteri malvagi del Fel Moss per farli impazzire.\n\nSono troppo ferito per tornare da Athridas a portargli questa grave notizia. Il compito resta a te, giovane $C. Possiamo solo sperare che gli Gnarlpine impazziti non siano ancora arrivati a Ban'ethil!", enHash = "691272ae", vanilla = true },
        objectives = { it = "Torna da Athridas Bearmantle, a Dolanaar.", enHash = "86d75507", vanilla = true },
        reward = { it = "Per le stelle! Questo è davvero molto inquietante!", enHash = "2b425395", vanilla = true },
    },
    [477] = {
        title = { it = "Passaggi di confine", enHash = "435c2e1d", vanilla = true },
        text = { it = "Come forse sai, la città di Ambermill resta un focolaio di opposizione umana, soprattutto per il sostegno che riceve dai maghi di Dalaran.\n\nNon so quale sia il loro piano, ma il fatto che si interessino a un villaggio sperduto come Ambermill significa che deve avere un'importanza più grande.\n\nStanno spedendo casse a carrettate da Hillsbrad. Molti di quei rifornimenti finiscono in un piccolo accampamento a nord di Pyrewood Village. Recupera il contenuto di una cassa e portamelo.", enHash = "726f26bf", vanilla = true },
        objectives = { it = "Recupera il contenuto di una delle casse dei maghi di Dalaran. Pyrewood Village si trova a sud.", enHash = "a2cd5d2c", vanilla = true },
        reward = { it = "<Facendo leva sul coperchio della cassa, trovi un assortimento di oggetti imballati con cura. In cima alla cassa c'è un fascio di mappe, ingiallite dal tempo, che sembrano raffigurare la Silverpine Forest e altre parti del Lordaeron occidentale.\n\nSotto le mappe c'è un ciondolo magico dall'aria misteriosa.>", enHash = "f29b03dc", vanilla = true },
    },
    [478] = {
        title = { it = "Mappe e rune", enHash = "0c6dfaa7", vanilla = true },
        text = { it = "<Togli in fretta il ciondolo dalla cassa e rimetti il coperchio.>", enHash = "36808b3d", vanilla = true },
        objectives = { it = "Porta lo strano ciondolo a Shadow Priest Allister, al Sepulcher.", enHash = "5fa4e11a", vanilla = true },
        progress = { it = "Hai scoperto qualcosa di utile, $N?", enHash = "4af5ab83", vanilla = true },
        reward = { it = "Mappe e questo... ciondolo, eh? Interessante.\n\nÈ evidente che i maghi di Dalaran si interessano ad Ambermill per qualche scopo, ma il loro fine mi resta oscuro.\n\nForse Dalar saprà qualcosa sul loro uso.", enHash = "0ad81dd0", vanilla = true },
    },
    [479] = {
        title = { it = "Indagini ad Ambermill", enHash = "35cbcc72", vanilla = true },
        text = { it = "Dalar sta cercando di individuare la fonte degli incantesimi dei maghi. Per ora dovremo rallentarli in ogni modo possibile...\n\nGli evocatori, i maghi e i protettori portano senza dubbio i ciondoli addosso. Strappaglieli e portameli.\n\nPrendi la strada principale verso sud e poi il bivio a est, dentro Ambermill.", enHash = "27cb2aa8", vanilla = true },
        objectives = { it = "Procura 8 Dalaran Pendant per Shadow Priest Allister, al Sepulcher.", enHash = "3da45e84", vanilla = true },
        progress = { it = "Dobbiamo fare in fretta: i loro piani non devono andare in porto, o rischiamo di perdere la presa sulla Silverpine Forest.", enHash = "034478ff", vanilla = true },
        reward = { it = "Dalar ha scoperto che la tessitura è a buon punto, nonostante la battuta d'arresto.\n\nUn mago di grande potere sta guidando l'energia magica. Va fermato in fretta.", enHash = "37bbfe5d", vanilla = true },
    },
    [480] = {
        title = { it = "Il Tessitore", enHash = "56804dff", vanilla = true },
        text = { it = "Un arcimago di grande potere sta sovrintendendo alla riattivazione del nodo di energia ley. Con i progressi che hanno fatto, la nostra unica speranza di fermarli è ucciderlo. Sarà difficile: senza dubbio è protetto da molti altri maghi e guardiani.\n\nDevi andare, e devi eliminarlo in fretta. Quando sarà morto, recupera il suo bastone per me. Va', ora.", enHash = "2b687ca1", vanilla = true },
        objectives = { it = "Uccidi l'arcimago di Dalaran, poi recupera il suo bastone per Shadow Priest Allister, al Sepulcher.", enHash = "a96ba680", vanilla = true },
        progress = { it = "Presto, il tempo stringe, $N!", enHash = "0734b45a", vanilla = true },
        reward = { it = "La magia dei maghi si dissolve e le energie ley tornano a sopirsi. I tuoi sforzi hanno dato frutto, $N, e abbiamo inferto un duro colpo ai nostri nemici e agli arroganti maghi di Dalaran.\n\nDobbiamo però restare vigili, sapendo che quella fonte di energia è così a portata di mano... Bisognerà fare piani per il futuro.", enHash = "15f44cd3", vanilla = true },
    },
    [481] = {
        title = { it = "L'analisi di Dalar", enHash = "f6c33750", vanilla = true },
        text = { it = "Porta il ciondolo a Dalar Dawnweaver: forse può fare luce sui piani dei maghi.", enHash = "33e9db7a", vanilla = true },
        objectives = { it = "Porta il ciondolo inciso di rune a Dalar Dawnweaver, al Sepulcher.", enHash = "63f90dd2", vanilla = true },
        progress = { it = "Sì, $C? Che c'è?", enHash = "ab34f09f", vanilla = true },
        reward = { it = "Interessante: altre macchinazioni del Kirin Tor, a quanto pare. Questo è un artefatto potente. I maghi più potenti del Kirin Tor lo usavano spesso per incanalare le energie magiche.\n\nIl fatto che ne stiano portando così tanti ad Ambermill significa che devono avere per le mani un progetto di una certa portata.\n\nVedrò se riesco a penetrare le loro barriere e a scoprire le loro intenzioni.", enHash = "c37def2f", vanilla = true },
    },
    [482] = {
        title = { it = "Le intenzioni di Dalaran", enHash = "751b8e6e", vanilla = true },
        text = { it = "Ma certo! Come ho potuto dimenticarlo?\n\nAmbermill era uno dei siti segnalati dal Kirin Tor, annotato perché ospita un nodo di energia ley dormiente. I maghi devono avere in mente di riattivare il nodo e usarne le energie per qualche scopo più grande.\n\nNon possiamo permettere che accada...\n\nPer attivare le energie ley della zona servirà una gran quantità di potere: possiamo rallentarli portando via i ciondoli ai maghi.\n\nRiferisci l'informazione ad Allister, sarà lui a decidere il da farsi.", enHash = "ced82878", vanilla = true },
        objectives = { it = "Parla con Shadow Priest Allister, al Sepulcher.", enHash = "5d949c46", vanilla = true },
        reward = { it = "Porti cattive notizie, $N. Se Dalar ha ragione — e non ho motivo di credere il contrario — dobbiamo muoverci in fretta.\n\nDevo consultarmi con lui sul piano d'attacco. Ma nel frattempo dovremo rallentare i loro progressi.", enHash = "9f5e7b32", vanilla = true },
    },
    [483] = {
        title = { it = "Le Relics of Wakening", enHash = "7d774bd0" },
        text = { it = "Sono stati visti invasori Gnarlpine devastare il Ban'ethil Barrow Den, a ovest.\n\nI druidi addormentati resteranno intrappolati nell'Emerald Dream per l'eternità, ignari della loro sorte, a meno che non li aiutiamo. Il delicato rituale di letargo non si può spezzare senza le Relics of Wakening.\n\nVa' al Den e recupera il Raven Claw Talisman, la Black Feather Quill, il Sapphire of Sky e la Rune of Nesting. I druidi li custodiscono in casse sacre. Portameli e preparerò il rituale del risveglio.", enHash = "2d00fdf3" },
        objectives = { it = "Recupera le Relics of Wakening e portale ad Athridas Bearmantle, a Dolanaar.", enHash = "2a5a4796" },
        progress = { it = "$N, i Druidi dell'Artiglio rapiti resteranno intrappolati per sempre nell'Emerald Dream se non riusciamo a recuperare le Relics of Wakening dal Ban'ethil Barrow Den, a ovest.\n\nOgni minuto che perdiamo avvicina la loro sorte di un passo alla condanna eterna.", enHash = "67dc44d6", vanilla = true },
        reward = { it = "Ci sei $Griuscito:riuscita;, giovane $C! Ben fatto. E appena in tempo, aggiungerei.", enHash = "f428577a", vanilla = true },
    },
    [484] = {
        title = { it = "Young Crocolisk Skins", enHash = "aa75148f", vanilla = true },
        text = { it = "Sono James Halloran, il conciatore. Le mie pelli di crocolisk conciate sono ricercate ovunque, e le spedizioni partono in nave per i porti di tutto il mondo.\n\nHai conosciuto Einar? È uno dei cacciatori che mi portano le pelli di crocolisk.\n\nSono un po' a corto delle pelli più morbide, quelle che vengono dai crocolisk giovani.\n\nVisto che ne ho poche, ti pago profumatamente per un mazzo di quelle pelli. I crocolisk giovani li trovi nelle paludi appena fuori città.", enHash = "561d9dd4", vanilla = true },
        objectives = { it = "Procura 4 Young Crocolisk Skin a James Halloran, a Menethil Harbor.", enHash = "75a4eb77", vanilla = true },
        progress = { it = "$N, giusto? Hai le mie pelli?", enHash = "bc1f507c", vanilla = true },
        reward = { it = "Bel lavoro, $N. La qualità di queste pelli è ottima. Devo metterle in conciatura il prima possibile. Oh, ma prima di arrivare a quello, c'è un altro lavoro che mi serve e che credo tu possa sbrigare.", enHash = "92beb9d6", vanilla = true },
    },
    [486] = {
        title = { it = "Ursal the Mauler", enHash = "126f4906", vanilla = true },
        text = { it = "Ora è giunto il momento di salvare i Druidi dell'Artiglio. Se falliamo adesso, $N, resteranno perduti nel sonno per sempre.\n\nPreparerò le Relics of Wakening e compirò il rituale. Perché il mio lavoro abbia effetto, la bestia maledetta responsabile di questa orribile situazione va uccisa. Solo allora il rituale sarà completo.\n\nFu Ursal the Mauler a interferire con la chiamata dei nostri fratelli, ed è Ursal the Mauler che ora deve pagare, perché possano essere liberati. Va' al Gnarlpine Hold, a sud-ovest, e uccidilo.", enHash = "24691f5b", vanilla = true },
        objectives = { it = "Uccidi Ursal the Mauler e torna da Athridas Bearmantle, a Dolanaar.", enHash = "a3e58488", vanilla = true },
        progress = { it = "I nostri fratelli non potranno essere svegliati finché Ursal the Mauler non sarà stato ucciso, $N.", enHash = "3843acd7", vanilla = true },
        reward = { it = "$N, ti sei $Gdimostrato:dimostrata; $Gun:una; $C $Gdegnissimo:degnissima; e capace. $GUn:Una; $R che segue la via dell'onore con la tua stessa fermezza troverà di certo grande gloria in questo mondo.\n\nChe gli spiriti della foresta ti proteggano ovunque ti portino i tuoi viaggi.", enHash = "ecd44ba3", vanilla = true },
    },
    [487] = {
        title = { it = "La strada per Darnassus", enHash = "823a64b2", vanilla = true },
        text = { it = "La strada per Darnassus va tenuta sicura. I viaggiatori che vanno da Dolanaar a Darnassus riferiscono di attacchi spietati da parte dei furbolg corrotti della tribù Gnarlpine.\n\nOgni giorno notizie importanti e merci viaggiano da e verso Darnassus lungo questa strada. Non possiamo permetterci che una banda di eretici ribelli terrorizzi la gente.\n\nPrendi le armi nel nome della foresta sacra, $C. La loro tana si trova da qualche parte sotto questo punto d'osservazione. Uccidi 6 di questi Gnarlpine Ambusher e torna a riferirmelo.", enHash = "83dd4d23", vanilla = true },
        objectives = { it = "Uccidi 6 Gnarlpine Ambusher e torna da Sentinel Amara Nightwalker, fuori da Dolanaar.", enHash = "5458cd05", vanilla = true },
        progress = { it = "La strada non è ancora sicura, $C. Parti, uccidi 6 Gnarlpine Ambusher e torna da me.", enHash = "ba00e08b", vanilla = true },
        reward = { it = "Hai servito bene la brava gente di Dolanaar e di Darnassus, $Gvaloroso:valorosa; $C. Come membro della forza delle Sentinelle di Teldrassil, saluto il tuo impegno.", enHash = "3cc9e4e7", vanilla = true },
    },
    [488] = {
        title = { it = "Gli ordini di Zenn", enHash = "cd10fcf2" },
        text = { it = "Hai voglia di lavorare, a quanto vedo. Fortuna tua che non passa giorno senza che io desideri $Gun giovane:una giovane; $C che esegua i miei ordini.\n\nVedi, $N, posso renderti molto felice e darti cose che non ti saresti mai $Gsognato:sognata; di avere. Ma perché accada, devi portarmi certi oggetti.\n\nI miei affari nella foresta richiedono spesso certi... reagenti. Procurami 3 Nightsaber Fang, 3 Strigid Owl Feather e 3 pezze di Webwood Spider Silk.\n\nQuesto resti un nostro piccolo segreto, $R.", enHash = "c7656ffb" },
        objectives = { it = "Porta a Zenn Foulhoof, fuori da Dolanaar, 3 Nightsaber Fang, 3 Strigid Owl Feather e 3 pezze di Webwood Spider Silk.", enHash = "63992905" },
        progress = { it = "Sei $Gstato indaffarato:stata indaffarata; come un'apetta, $N? Aspettavo che mi portassi ciò che mi serve.", enHash = "b7fa6162" },
        reward = { it = "Ah ah! Ben fatto davvero.\n\nChi avrebbe mai immaginato che io, Zenn Foulhoof, avrei avuto $Gun:una; $R ai miei ordini? Di certo non io! Ma così va... questo nostro amato mondo è pieno di sorprese.\n\nTre urrà per gli ingenui e i creduloni!", enHash = "547c2395" },
    },
    [489] = {
        title = { it = "Cerca la redenzione!", enHash = "6cade1ae" },
        text = { it = "Il Consiglio della Foresta ha saputo che hai aiutato Zenn Foulhoof. Il satiro è un nemico della foresta. Da $R, dovresti sapere che non si profana la foresta uccidendo le creature della Natura.\n\nDevi redimerti agli occhi del Consiglio, se vuoi restare $Gamico:amica; di Teldrassil.\n\nDa' una lezione a Foulhoof e sarai $Gredento:redenta;. I Fel Cone sono semi corrotti che cadono dagli alberi. Emanano fumo verde.\n\nDanne un po' a Foulhoof. Crederà che gli hai portato uno spuntino innocuo.", enHash = "cf24b6f4" },
        objectives = { it = "Raccogli 3 Fel Cone e dalli a Zenn Foulhoof, fuori da Dolanaar.", enHash = "24eb32ca" },
        progress = { it = "Cos'hai per me, $N? Un delizioso spuntino, immagino?", enHash = "82cae059", vanilla = true },
        reward = { it = "Ah, che dolce $R! Sapevo che saresti $Gtornato utile:tornata utile;!", enHash = "34d978b3", vanilla = true },
    },
    [491] = {
        title = { it = "La bacchetta per Bethor", enHash = "e203e13f", vanilla = true },
        text = { it = "Thule una volta mi raccontò che, tanto tempo fa, lui e due colleghi crearono una bacchetta magica, intrecciando le bacchette da apprendista che ciascun mago possedeva. Quella bacchetta era il simbolo della loro amicizia e, benché Thule finisse per detestarla, non riusciva a separarsene né a lasciarla agli altri. Così la rubò e la nascose a Fenris Keep.\n\nEcco. Porta la bacchetta a Bethor Iceshard, uno degli amici di Thule di un tempo. Sono certo che la vorrà.", enHash = "674bf005", vanilla = true },
        objectives = { it = "Porta la Woven Wand a Bethor Iceshard, nel Magic Quarter dell'Undercity.", enHash = "d87e695f", vanilla = true },
        progress = { it = "$N. Hai sconfitto Thule Ravenclaw?", enHash = "1d9a814f", vanilla = true },
        reward = { it = "...cos'è questa? Thule aveva la nostra Woven Wand? La credevo perduta quando la nostra amicizia si spezzò e lui passò dalla parte del Re dei Lich!\n\nNon deve averne invocato il potere, perché altrimenti l'avrei percepito. Ed è un bene che non l'abbia usata...\n\nQuesta è una scoperta meravigliosa. Te ne sono grato, $N, e sarai $Gricompensato:ricompensata;.", enHash = "488f365c", vanilla = true },
    },
    [492] = {
        title = { it = "Una nuova piaga", enHash = "a92604d1", vanilla = true },
        text = { it = "Stando ai Guardiamorte, un altro di quegli sciocchi Mountaineer nani è appena stato catturato. Ai Guardiamorte piace usare la cantina della Gallows' End Tavern come cella di custodia, finché i prigionieri non vengono trattati \"a dovere\".\n\nPerché non vai a vedere quanto piace al Captured Mountaineer questa bevanda speciale che ho preparato per lui? Contiene un accenno discreto di ciò che la Signora Oscura ha in serbo per il resto di Azeroth.", enHash = "298d71a4", vanilla = true },
        objectives = { it = "Porta Johaan's Special Drink al Captured Mountaineer.", enHash = "994f8941", vanilla = true },
        progress = { it = "Ah, se avessi il mio fidato fucile saresti $Gbell'e morto:bell'e morta;, $C. Aspetta solo che arrivi la Steam Tank Brigade a salvarmi!", enHash = "c6169ccc", vanilla = true },
        reward = { it = "Ah, finalmente da bere. Di sicuro non è Rhapsody Malt, ma a questo punto mi accontento di qualunque cosa mi bagni la gola.", enHash = "a25d19af", vanilla = true },
    },
    [493] = {
        title = { it = "Viaggio verso le Hillsbrad Foothills", enHash = "5ac72944", vanilla = true },
        text = { it = "La Royal Apothecary Society è sotto fortissima pressione da parte della Signora Oscura perché sviluppi una nuova piaga. Lavoriamo con diligenza e abbiamo fatto molti progressi. Crediamo che il successo arriverà molto più in fretta se condivideremo le informazioni dentro la Society.\n\nPer questo voglio che tu consegni le mie ultime scoperte ad Apothecary Lydon, a Tarren Mill, una cittadina annidata nelle Hillsbrad Foothills. Il viaggio sarà lungo.\n\nVa' a sud e resta sulle strade. Segui con attenzione i cartelli!", enHash = "9d980607", vanilla = true },
        objectives = { it = "Consegna le scoperte di Apothecary Renferrel ad Apothecary Lydon, nella città di Tarren Mill, nelle Hillsbrad Foothills.", enHash = "5903b473", vanilla = true },
        progress = { it = "Hai qualcosa per me?", enHash = "ac74d893", vanilla = true },
        reward = { it = "Ah, ottimo. Apothecary Renferrel ha tutto il mio rispetto. Non vedo l'ora di studiare il suo lavoro.", enHash = "25d910ba", vanilla = true },
    },
    [494] = {
        title = { it = "È ora di colpire", enHash = "5b8aa364", vanilla = true },
        text = { it = "Silenzio e ascolta, $C.\n\nSono stata mandata in questa postazione per sorvegliare la città di Hillsbrad. La mia è una missione di ricognizione. È indispensabile che tu mandi subito parola a High Executor Darthalia, a Tarren Mill. Falle sapere che io, Deathstalker Lesh, mando questo messaggio:\n\n\"Il grido del corvo da ovest ci chiama.\"\n\nSegui la strada verso est e fa' bene attenzione ai cartelli. Ora, sbrigati! Va' a Tarren Mill, e con urgenza, aggiungerei!", enHash = "d1c1100e", vanilla = true },
        objectives = { it = "Va' a Tarren Mill a consegnare il messaggio di Deathstalker Lesh a High Executor Darthalia.", enHash = "b8bb8e38", vanilla = true },
        reward = { it = "Il grido del corvo da ovest ci chiama?\n\nOttime notizie! Hillsbrad è matura per l'attacco. Ora possiamo mettere in atto il nostro piano di distruzione. Varimathras sarà soddisfatto.", enHash = "2d0f7a36", vanilla = true },
    },
    [496] = {
        title = { it = "Elixir of Suffering", enHash = "327d3e6b", vanilla = true },
        text = { it = "Ah, un altro giorno miserabile a Tarren Mill. Tutta quest'aria pulita mi mette di pessimo umore, $N.\n\nPrima riusciamo ad appestare gli umani di qui, meglio è. Ho condotto studi accurati sui possibili agenti letali da usare nei miei intrugli, ma non ho il tempo di raccoglierli tutti.\n\nSe vuoi renderti utile, procurami queste cose: 10 Gray Bear Tongue e il rarissimo e introvabile Creeper Ichor. Troverai sia gli orsi sia i creeper appena fuori Tarren Mill.", enHash = "9459d215", vanilla = true },
        objectives = { it = "Apothecary Lydon, a Tarren Mill, vuole 10 Gray Bear Tongue e un po' di Creeper Ichor.", enHash = "8e1f317d", vanilla = true },
        progress = { it = "Vedo che sei $Gtornato:tornata;. Spero che tu sia $Griuscito:riuscita; a raccogliere gli agenti che mi servono. Un altro giorno senza morti mi metterà di umore cupo.", enHash = "678a9f7f", vanilla = true },
        reward = { it = "Questi esemplari sono perfetti. Be', $N, sei $Griuscito:riuscita; a portarmi un minimo accenno di gioia in un'altra giornata miserabile. I tuoi sforzi sono apprezzati.", enHash = "db8baf00", vanilla = true },
    },
    [498] = {
        title = { it = "Il salvataggio", enHash = "4dfffc22", vanilla = true },
        text = { it = "Io e altri guerrieri siamo stati mandati dal Capoguerra a recuperare un oggetto a Durnholde e a indagare su questo cosiddetto Syndicate.\n\nSiamo andati a Durnholde a dare un'occhiata, ma siamo stati colti di sorpresa da un gran numero di umani. Abbiamo combattuto con coraggio, ma il loro numero è bastato a sconfiggerci. Alcuni di noi li hanno presi prigionieri, ma io sono riuscito a fuggire.\n\nDurnholde è appena a sud-est di qui, oltre il fiume. Drull e Tog'thar sono tenuti là: devi andare a liberarli.", enHash = "90f5d79c", vanilla = true },
        objectives = { it = "Krusk, a Tarren Mill, vuole che tu liberi Drull e Tog'thar da Durnholde Keep.", enHash = "3566e65c", vanilla = true },
        progress = { it = "Devi fare in fretta, $C. Rabbrividisco a pensare cosa potrebbero fare gli umani a Drull e Tog'thar.", enHash = "0fc5c480", vanilla = true },
        reward = { it = "Quindi gli umani pensavano di trasformare i nostri guerrieri in schiavi, eh? Gliela faremo vedere!\n\nA quanto pare hanno portato Gol'dir, il nostro capo, in un altro posto. Dobbiamo trovarlo e salvarlo. Ma per ora non abbiamo idea di dove sia...\n\nQuando avremo una pista, non mancherò di dirtelo, $N.", enHash = "99e7f170", vanilla = true },
    },
    [499] = {
        title = { it = "Elixir of Suffering", enHash = "327d3e6b", vanilla = true },
        text = { it = "Mi basterà un momento per mescolare questi componenti in quello che ho battezzato Elixir of Suffering.\n\nEcco fatto! Ah, niente rallegra una giornata cupa in queste miserabili colline come portare un po' di sofferenza nel mondo.\n\nVediamo se la nostra pozioncina ha ottenuto l'effetto voluto.\n\nFa' assaggiare alla mia assistente Umpi quel che la Signora Oscura ha in serbo per gli umani e per il Flagello.", enHash = "65e03602", vanilla = true },
        objectives = { it = "Dai l'Elixir of Suffering a Umpi.", enHash = "2efc6952", vanilla = true },
        progress = { it = "Cra cra!", enHash = "4746603f", vanilla = true },
        reward = { it = "Craaa!", enHash = "af6a2b57", vanilla = true },
    },
    [500] = {
        title = { it = "Taglia sui Crushridge", enHash = "eb1751fb", vanilla = true },
        text = { it = "Gli ogre Crushridge hanno scavato un tumulo di ogre sulle Alterac Mountains, vicino alla città in rovina di Alterac. E i miei esploratori mi dicono che hanno occupato anche quelle rovine.\n\nNon possiamo lasciare che si mettano comodi lassù: se pensano di essere al sicuro dove sono, il loro prossimo passo sarà scendere sulle colline, e questo li porterebbe proprio alla nostra porta!\n\nVa' a nord, nelle Alterac Mountains, e dai la caccia agli ogre. Portami i Dirty Knucklebone che portano con sé e ti guadagnerai una bella taglia.", enHash = "3a4a4983", vanilla = true },
        objectives = { it = "Raccogli 9 Dirty Knucklebone dagli ogre Crushridge nelle Alterac Mountains. Portali a Marshal Redpath, a Southshore.", enHash = "cd2ab12c", vanilla = true },
        progress = { it = "$N, stai ancora dando la caccia agli ogre? Hai gli ossicini che ti avevo chiesto di raccogliere?", enHash = "4b71aacf", vanilla = true },
        reward = { it = "Molto bene, $N. Devi aver fatto a pezzi un bel mucchio di ogre per raccogliere tutti questi ossicini.\n\nQuesto dovrebbe tenerceli lontani. Almeno per un po'.", enHash = "752ed6d9", vanilla = true },
    },
    [501] = {
        title = { it = "Elixir of Pain", enHash = "836fac1e", vanilla = true },
        text = { it = "Oh, $N... i fiori sbocciano a Hillsbrad e l'aria è così fresca e frizzante. Non posso far altro che crogiolarmi nella miseria di tutto questo. Guardo fuori dalla mia finestra sporca e aspetto con ansia il giorno in cui la nostra nuova piaga porterà a questo mondo la morte che merita.\n\nPer quanto mi piacerebbe starmene seduto a rimuginare tutto il giorno, il mio dovere verso la Signora Oscura mi chiama. Mi aiuti? Le mie ricerche mi portano a credere di poter preparare il più splendido degli intrugli di morte con il sangue di un Mountain Lion. Portamene un po' e ci divertiremo un pochino.", enHash = "4ef62ebf", vanilla = true },
        objectives = { it = "Porta 10 fiale di Mountain Lion Blood ad Apothecary Lydon, a Tarren Mill.", enHash = "28733a72", vanilla = true },
        progress = { it = "Mi ricordo di te, $N. Dovevi aiutarmi a preparare il mio ultimo elisir. Mi serve quel sangue prima di poter portare agli abitanti di Hillsbrad la mia personale forma di miseria.", enHash = "abda88ab", vanilla = true },
        reward = { it = "Raccolta superba, $N.", enHash = "42a2955f", vanilla = true },
    },
    [502] = {
        title = { it = "Elixir of Pain", enHash = "836fac1e", vanilla = true },
        text = { it = "Ah, niente come l'odore del sangue fresco tra le colline!\n\nOra mescoliamo un po' di questo e un pizzico di quello e che il vero divertimento cominci! Quel che ho creato con questo sangue mi piace chiamarlo Elixir of Pain. Se i miei calcoli sono giusti, questo intruglio potrebbe essere l'inizio di qualcosa di molto bello per Lady Sylvanas. Ma quel che ci serve è una prova.\n\nPorta questo elisir alla fattoria più a nord degli Hillsbrad Fields, a sud-ovest. Vediamo come piace questo \"regalino\" a Stanley, il cagnolino di Farmer Ray.", enHash = "d574c534", vanilla = true },
        objectives = { it = "Fa' bere l'Elixir of Pain a Stanley.", enHash = "d2656030", vanilla = true },
        progress = { it = "Bau?", enHash = "06c10f70", vanilla = true },
        reward = { it = "Versi un po' di elisir nella mano e la porgi davanti al muso di Stanley.", enHash = "2d232c1b", vanilla = true },
    },
    [503] = {
        title = { it = "Gol'dir", enHash = "0c10ed8a", vanilla = true },
        text = { it = "Da quel che capisco dai documenti che hai procurato, Gol'dir è tenuto prigioniero in una grande base del Syndicate a nord, molto probabilmente nelle Alterac Mountains. È prigioniero da troppo tempo e va liberato.", enHash = "0c9bb02f", vanilla = true },
        objectives = { it = "Libera Gol'dir, poi torna da Krusk, a Tarren Mill.", enHash = "1817749b", vanilla = true },
        progress = { it = "Dammi la chiave, $C, apro io la serratura.", enHash = "2bed8153", vanilla = true },
        reward = { it = "Grazie, $N. Ho guidato io la spedizione da Durotar agli ordini del Capoguerra, ma come vedi i nostri piani sono andati un po' storti. Mi hanno tenuto prigioniero qui in questa città, costringendomi a lavorare, a trasportare pesi, a scavare...\n\nQuel che ho sofferto però non conta. C'è un'informazione importante che devi consegnare a chi guida il nostro gruppo adesso.", enHash = "ee4ed5f1", vanilla = true },
    },
    [504] = {
        title = { it = "Crushridge Warmongers", enHash = "83a36e13", vanilla = true },
        text = { it = "Ora che hai avuto un assaggio degli ogre Crushridge, voglio che tu li faccia sanguinare sul serio...\n\nEntra nelle Ruins of Alterac e cerca i Crushridge Warmonger. Voglio che tu ne abbatta un buon numero: è l'unico modo perché quei bruti imparino a stare lontani dal territorio dell'Alleanza.", enHash = "fb78514b", vanilla = true },
        objectives = { it = "Uccidi 15 Crushridge Warmonger, poi torna da Marshal Redpath, a Southshore.", enHash = "bbabdd1d", vanilla = true },
        progress = { it = "Hai altri Warmonger da uccidere, $N. Dovresti essere su in montagna a svolgere il tuo compito, non quaggiù con l'arma riposta.", enHash = "5c249852", vanilla = true },
        reward = { it = "Molto bene. Ecco la tua ricompensa.\n\nE mentre davi la caccia a quei Warmonger, com'era la città di Alterac? Sarà in cattive condizioni, immagino. Gli ogre non sono noti per la loro pulizia.\n\nPer fortuna, i tuoi sforzi aiuteranno a tenerli lontani da Southshore.", enHash = "4eab6cde", vanilla = true },
    },
    [505] = {
        title = { it = "Gli assassini del Syndicate", enHash = "b158ce8a", vanilla = true },
        text = { it = "Sono il nuovo magistrato di Southshore, nominato di recente dopo l'assassinio del magistrato precedente. Gli assassini non sono mai stati trovati, ma grazie alle nostre indagini siamo quasi certi che siano stati assoldati dal Syndicate, una banda di ladri guidata da nobili malvagi dell'ormai caduto regno di Alterac.\n\nIl Syndicate ha un accampamento a nord di Tarren Mill, in mano all'Orda, e i nostri ultimi indizi portavano a quell'accampamento. Uccidi i membri del Syndicate che trovi laggiù.", enHash = "de42cca7", vanilla = true },
        objectives = { it = "Uccidi 12 Syndicate Footpad e 8 Syndicate Thief, poi torna da Magistrate Henry Maleb, a Southshore.", enHash = "749e3f19", vanilla = true },
        progress = { it = "Hai eliminato quei delinquenti del Syndicate, confido?", enHash = "bd99a49e", vanilla = true },
        reward = { it = "Grazie, $N. Anche se forse sono ancora in giro, speriamo che alcuni dei ladri e dei tagliaborse che hai ucciso fossero i responsabili della morte dell'ultimo magistrato. Ma anche se non lo fossero, il Syndicate porta corruzione in questa terra ed è una macchia sulla razza umana.\n\nLa loro morte è ben accetta a Southshore.", enHash = "ce39564a", vanilla = true },
    },
    [506] = {
        title = { it = "L'eredità di Blackmoore", enHash = "39bd2cfc", vanilla = true },
        text = { it = "Un giorno o due fa ho ricevuto la visita del capo di questo Syndicate. Si chiamava Aliden Perenolde e si faceva chiamare signore di queste terre. Mi ha confidato il suo piano: prendere come schiavi gli orchi che gli si oppongono, proprio come avevano progettato suo padre e il suo mentore, il disprezzato Blackmoore.\n\nPiù importante ancora: si è portato dietro la sua amante, una ragazzina esile di nome Elysa. Al collo aveva il pendaglio che il Capoguerra desidera.\n\nOra va', io me la caverò da solo, dopo aver sistemato le mie faccende qui.", enHash = "d824df22", vanilla = true },
        objectives = { it = "Porta a Krusk, a Tarren Mill, le informazioni raccolte da Gol'dir.", enHash = "e8277f10", vanilla = true },
        reward = { it = "Che sfacciataggine, questi umani arroganti! Mostreremo loro che gli orchi non si piegheranno mai al loro volere!\n\nOra questa sarà la nostra missione, oltre a recuperare il ninnolo che il Capoguerra desidera. Sembra che portando a termine l'una porteremo a termine anche l'altra.", enHash = "f5a27791", vanilla = true },
    },
    [507] = {
        title = { it = "Lord Aliden Perenolde", enHash = "0b39c33e", vanilla = true },
        text = { it = "È chiaro che Perenolde va ucciso, la sua sozzura va tolta dal mondo. Il suo maniero si trova un bel pezzo a nord di qui, sulle rive del Lordamere Lake. Fa' il tuo dovere, $N, poi recupera il pendaglio che il Capoguerra desidera e torna qui.", enHash = "ea9155f5", vanilla = true },
        objectives = { it = "Uccidi Lord Aliden Perenolde e chiedi alla sua amante, Elysa, del pendaglio di Taretha.", enHash = "c8287eda", vanilla = true },
        progress = { it = "C-cosa vuoi?", enHash = "2259f79f", vanilla = true },
        reward = { it = "No, no, ti prego, non farmi del male! Non ho mai voluto fare del male alla tua gente, mi ha tenuta qui contro la mia volontà! Ti prego... risparmiami!", enHash = "93a76dc2", vanilla = true },
    },
    [508] = {
        title = { it = "Il dono di Taretha", enHash = "022507f7", vanilla = true },
        text = { it = "Il pendaglio? Certo che puoi averlo... Prendilo! Non voglio più niente che me lo ricordi... ti prego, ti prego, vattene in pace...", enHash = "4baee469", vanilla = true },
        objectives = { it = "Porta il pendaglio di Taretha a Krusk, a Tarren Mill.", enHash = "42ad32df", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata;, $N. Hai un successo da riferire?", enHash = "6784d3cb", vanilla = true },
        reward = { it = "È strano che il Capoguerra si spenda tanto per una cosa così piccola. Non pretendo di capirlo, ma lo seguirò, qualunque cosa ordini. Hai fatto bene, $N, e di sicuro il Capoguerra sarà contento di sapere del tuo successo.", enHash = "d9c03a8c", vanilla = true },
    },
    [509] = {
        title = { it = "Elixir of Agony", enHash = "e9b5484c", vanilla = true },
        text = { it = "Un altro giorno, un altro elisir da preparare. Se dipendesse da me, lascerei che i patetici umani e il Flagello se la sbrigassero tra loro. Sembrano già decisi ad ammazzarsi a vicenda.\n\nPurtroppo la nostra Signora Oscura vuole accelerare un pochino il processo, e allora perché non passare queste giornate tetre spargendo un po' di morte e di malattia per la terra?\n\nEcco il piano, $N: va' a Nethander Stead, a sud di Tarren Mill e a est del fiume e di Southshore. Raccogli per me 6 Mudsnout Blossom nel campo, per il mio prossimo elisir.", enHash = "fcd1d2a6", vanilla = true },
        objectives = { it = "Porta 6 Mudsnout Blossom ad Apothecary Lydon, a Tarren Mill.", enHash = "067fdbf5", vanilla = true },
        progress = { it = "Fortuna a Nethander Stead?", enHash = "e9fd7db1", vanilla = true },
        reward = { it = "Ah, il puzzo orribile dei Mudsnout Blossom. Almeno quei luridi gnoll servono a qualcosa.", enHash = "9f74bf6e", vanilla = true },
    },
    [510] = {
        title = { it = "Foreboding Plans", enHash = "6afe6791", vanilla = true },
        text = { it = "Tra questi documenti c'è una lista di rifornimenti richiesti. Comprende oggetti comuni (cibo, armi, vestiti) e attrezzatura più insolita (maschere, olio, veleno).\n\nMa la cosa più notevole è l'urgenza della richiesta: questi rifornimenti servivano presto per portare a termine quella che nel documento viene descritta come una \"missione importante contro Southshore.\"", enHash = "365b1a28", vanilla = true },
        objectives = { it = "Porta i Foreboding Plans a Magistrate Maleb, a Southshore.", enHash = "dc0d9dd4", vanilla = true },
        progress = { it = "$N, sembri in ansia. C'è qualcosa che vuoi dirmi?", enHash = "9fa7e69c", vanilla = true },
        reward = { it = "<Maleb legge i documenti.>\n\nSono molto preoccupanti, $N. Dalle informazioni di questi documenti, e dalle azioni passate del Syndicate, dobbiamo presumere che quella banda di tagliagole abbia dichiarato guerra a Southshore.", enHash = "9d20bf22", vanilla = true },
    },
    [511] = {
        title = { it = "Encrypted Letter", enHash = "100c8e02", vanilla = true },
        text = { it = "Una delle lettere su questo tavolo è cifrata e indecifrabile.", enHash = "afa5104f", vanilla = true },
        objectives = { it = "Porta l'Encrypted Letter a Loremaster Dibbs, a Southshore.", enHash = "b3039089", vanilla = true },
        progress = { it = "Sì, $Gsignore:signora;? Hai qualcosa da sbrigare con me?", enHash = { "de5c5621", "829bdec1" }, vanilla = true },
        reward = { it = "Che cos'è? Aspetta un momento... fammi dare un'occhiata più da vicino.\n\n...\n\nHm, non ho mai visto questo tipo di cifratura, ma devo ammettere che le mie conoscenze in quel campo non sono affatto complete.", enHash = "e494a004", vanilla = true },
    },
    [512] = {
        title = { it = "Morti nobili", enHash = "377a8b65", vanilla = true },
        text = { it = "Temo che i capi del Syndicate vogliano la rovina di Southshore. Dobbiamo colpire duramente questi capi prima che i loro piani si realizzino.\n\nEntra nelle rovine di Strahnbrad, nelle Alterac Mountains a nord. Pensiamo che il Syndicate usi la zona come quartier generale.\n\nSappiamo che questa banda di tagliagole è guidata da ex nobili di Alterac. Potrebbero nascondersi fingendosi normali agenti del Syndicate, ma capirai di aver ucciso un nobile dall'anello con sigillo che porta.\n\nPortami quegli anelli con sigillo.", enHash = "bcd668f7", vanilla = true },
        objectives = { it = "Porta 7 Alterac Signet Ring a Magistrate Maleb, a Southshore.", enHash = "7e92a9b4", vanilla = true },
        progress = { it = "Hai dato la caccia al Syndicate? Hai quegli anelli?", enHash = "afd1ab2f", vanilla = true },
        reward = { it = "Privare il Syndicate dei suoi nobili gli toglierà la capacità di agire con decisione, e lo ridurrà a nient'altro che una banda di delinquenti.\n\nServi bene la tua Alleanza, $N.", enHash = "004eb856", vanilla = true },
    },
    [513] = {
        title = { it = "Elixir of Agony", enHash = "e9b5484c", vanilla = true },
        text = { it = "Proprio quando pensavo che sarebbe passato un altro giorno senza un briciolo di gioia, mi hai portato quei magnifici Mudsnout Blossom.\n\nPrima li ridurrò in un bel composto. Poi ci servirà che Master Apothecary Faranell, nell'Undercity, ci applichi il suo colloide di decomposizione, e allora sì che ci divertiremo davvero!\n\nTieni, prendi questo Mudsnout Composite e portalo subito di corsa a Master Faranell, $N.", enHash = "0f9869ee", vanilla = true },
        objectives = { it = "Porta il Mudsnout Composite a Master Apothecary Faranell, nell'Undercity.", enHash = "650bb7cd", vanilla = true },
        progress = { it = "Non vedi che sono occupato, $C? La Signora Oscura pretende una nuova piaga prima che l'avanzata del Flagello da Northrend ci travolga. E con la minaccia umana che incalza da sud, il tempo diventa la mia merce più preziosa. Spero per te che sia importante!", enHash = "52c0eb6f", vanilla = true },
        reward = { it = "Ti manda Apothecary Lydon? Ah, potevi dirlo subito!\n\nNonostante il carattere tetro, Apothecary Lydon è uno dei nostri membri più devoti e capaci.\n\nIl bravo compare manda del Mudsnout Composite! Adesso ho capito cosa sta combinando il nostro amico a Hillsbrad. E il suo modo di ragionare mi piace. La Signora Oscura sarebbe assai colpita dai progressi che sta facendo verso la nuova piaga.", enHash = "6a827c2e", vanilla = true },
    },
    [514] = {
        title = { it = "Lettera per Stormpike", enHash = "e7638bd1", vanilla = true },
        text = { it = "Ho un collega a Ironforge che forse può aiutare a decifrare questa lettera. Va' alla biblioteca nell'Hall of Explorers, a Ironforge, e parla con Prospector Stormpike. Digli che ti mando io e mostragli la lettera. Se c'è qualcuno a nord della Blackrock Spire che può leggerla, è lui.", enHash = "ce68237b", vanilla = true },
        objectives = { it = "Porta la Cleverly Encrypted Letter a Prospector Stormpike, a Ironforge.", enHash = "f99af820", vanilla = true },
        progress = { it = "Ti ha mandato Dibbs, da Southshore? Come se la passa quel vecchio topo di biblioteca?", enHash = "5202a0d8", vanilla = true },
        reward = { it = "Ah, una cifratura! Una mia specialità. Vediamo un po'...", enHash = "1a1aec84", vanilla = true },
    },
    [515] = {
        title = { it = "Elixir of Agony", enHash = "e9b5484c", vanilla = true },
        text = { it = "Un composto di mudsnout? Assolutamente geniale! Come mai non ci ho pensato io?\n\nLascia che aggiunga il mio colloide di decomposizione a questo intruglio diabolico.\n\nPer attivare gli agenti contaminanti in questa miscela di mudsnout, a Lydon serviranno una Strong Troll's Blood Potion, qualche Daggerspine Scale e qualche Torn Fin Eye dalla costa meridionale di Hillsbrad. Saprà lui cosa fare, una volta che gli avrai portato tutti i reagenti. E ah, quanto sono impaziente di sapere come va il suo esperimento!", enHash = "c4924450", vanilla = true },
        objectives = { it = "Porta la Mudsnout Mixture, una Strong Troll's Blood Potion, 5 Daggerspine Scale e 5 Torn Fin Eye ad Apothecary Lydon, a Tarren Mill.", enHash = "b2741a3c", vanilla = true },
        progress = { it = "Che piacere vederti di ritorno, $N. Mi stavo annoiando terribilmente. Non una sola cosa divertente da fare, a parte avvelenare e infettare Umpi e poi rianimarla... ancora e ancora e ancora.\n\nCom'è andato il viaggio all'Undercity? Hai avuto la fortuna di massacrare qualche umano lungo la strada?", enHash = "1b6e6c0d", vanilla = true },
        reward = { it = "L'eccitazione per questo esperimento mi mette allegria! Mi sei $Gstato:stata; di grande aiuto, $N. Insieme spargeremo morte e malattia su questa terra!", enHash = "5ee13845", vanilla = true },
    },
    [516] = {
        title = { it = "Beren's Peril", enHash = "8f271c84", vanilla = true },
        text = { it = "Mi sono arrivati rapporti su un gruppo di non morti che si sta asserragliando per preparare un attacco contro di noi. Con questa informazione possiamo ribaltare la situazione e attaccarli per primi, stroncando sul nascere il loro piccolo piano.\n\nPurtroppo le mie informazioni sono frammentarie, a dir poco. Pare che si nascondano in un luogo noto come Beren's Peril. La posizione esatta non si conosce, ma sembra sia una grotta fra le colline, vicino a una sacca di maghi di Dalaran.\n\nConfido nella tua intraprendenza. Trovali e annientali.", enHash = "9429f2ad", vanilla = true },
        objectives = { it = "Individua Beren's Peril, poi uccidi 6 Ravenclaw Drudger e 6 Ravenclaw Guardian, e torna da Shadow Priest Allister, al Sepulcher.", enHash = "ae7fab60", vanilla = true },
        progress = { it = "Hai già individuato la loro base, $N? Il tempo stringe!", enHash = "ea6b02e1", vanilla = true },
        reward = { it = "Se i nostri esploratori e i nostri agenti continueranno a procurarci informazioni preziose come questa, toglieremo dalle nostre terre il Flagello del Re dei Lich in men che non si dica.", enHash = "9ab1cddf", vanilla = true },
    },
    [517] = {
        title = { it = "Elixir of Agony", enHash = "e9b5484c", vanilla = true },
        text = { it = "Questo nuovo elisir è finalmente pronto per la prova. Ma perché sprecare una piaga tanto buona e tanto contagiosa su una semplice rana o su un cane? Divertiamoci sul serio, nel nome di Lady Sylvanas.\n\nScendi a Dun Garok. Sai, la caserma dove sgattaiolano quei sudici nanetti. Rubami un barile della loro Shindigger Stout. Quando avrò quel barile, tu e io faremo una gran festa, $N.", enHash = "d9c558f6", vanilla = true },
        objectives = { it = "Porta un barile di Shindigger Stout ad Apothecary Lydon, a Tarren Mill.", enHash = "1aea0116", vanilla = true },
        progress = { it = "Certe volte mi annoio talmente qui a Tarren Mill che mi metto ad aprire il barattolo di formaldeide e lascio che il delizioso aroma si spanda nell'aria. Anche se Umpi si innervosisce un po'.\n\nAllora, sei $Griuscito:riuscita; a procurarti un barile dai nani? Giuro che se devo fissare questo elisir letale un altro giorno senza usarlo su qualcuno mi metto a urlare.", enHash = "ebcdb68e", vanilla = true },
        reward = { it = "Finalmente! Ora siamo pronti all'azione!", enHash = "65cc1341", vanilla = true },
    },
    [518] = {
        title = { it = "La Crown of Will", enHash = "f80308a3", vanilla = true },
        text = { it = "Mug'Thol e i suoi ogre Crushridge hanno invaso le rovine di Alterac. Sarà difficile infliggergli una punizione seria senza prima sfoltire il numero degli ogre.\n\nDopo averli indeboliti, procederemo.\n\nChiaro? Bene. Ora va'.", enHash = "cc4eb9cb", vanilla = true },
        objectives = { it = "Uccidi 14 Crushridge Mauler per Melisara, a Tarren Mill.", enHash = "26cdfcc6", vanilla = true },
        progress = { it = "Noto che il tuo compito non è finito, $N. Devo informare Sharlindra della tua incompetenza?", enHash = "afa7a947", vanilla = true },
        reward = { it = "La neve si tinge di rosso del sangue degli ogre, ma non possiamo fermare i nostri sforzi finché lo spirito e il numero dei Crushridge non saranno schiacciati e ridotti in polvere nella terra e nella neve.", enHash = "46b17897", vanilla = true },
    },
    [519] = {
        title = { it = "La Crown of Will", enHash = "f80308a3", vanilla = true },
        text = { it = "Targ, Muckrake e Glommus sono i luogotenenti di Mug'Thol. Gli sono fedeli, anche se chi può dire cosa spinge un ogre alla fedeltà.\n\nPortami le loro teste, $N, e poi non resterà che prendere la testa di Mug'Thol, corona compresa.", enHash = "4238382b", vanilla = true },
        objectives = { it = "Uccidi Targ, Muckrake e Glommus e porta le loro teste a Melisara, a Tarren Mill.", enHash = "ea9c71ea", vanilla = true },
        progress = { it = "Voglio le loro teste, $N, non scuse.", enHash = "3f2a84c5", vanilla = true },
        reward = { it = "...e io che pensavo che gli ogre puzzassero già abbastanza.\n\nQuando mi porterai la testa di Mug'Thol, le farò infilzare tutte e quattro su delle picche sopra Alterac. Un monumento adatto a chi va contro la volontà della Signora Oscura.", enHash = "01a6626a", vanilla = true },
    },
    [520] = {
        title = { it = "La Crown of Will", enHash = "f80308a3", vanilla = true },
        text = { it = "Con i luogotenenti di Mug'Thol morti, non resta che uccidere Mug'Thol e recuperare la Crown of Will. Non ho dubbi che non vorrà separarsene. Probabilmente ti starà anche aspettando, vista la... dipartita... dei suoi compagni.\n\nTrova Mug'Thol, e portami la sua testa e la Crown. La resistenza dei Crushridge sarà finita.", enHash = "58b428c2", vanilla = true },
        objectives = { it = "Uccidi Mug'Thol e riporta la sua testa con la Crown of Will a Melisara, a Tarren Mill.", enHash = "01d58fbd", vanilla = true },
        progress = { it = "Tre teste le ho, me ne serve una quarta. Sarà quella di Mug'Thol, o sarà la tua, $N. Te lo prometto.", enHash = "2bf69693", vanilla = true },
        reward = { it = "Hai fatto bene il tuo dovere, $N. La testa di Mug'Thol ornerà la vetta più alta delle rovine di Alterac, e la Guardiamorte spazzerà sottoterra quel che resta dei Crushridge.", enHash = "3aa1ce89", vanilla = true },
    },
    [521] = {
        title = { it = "La Crown of Will", enHash = "f80308a3", vanilla = true },
        text = { it = "Non resta che consegnare la Crown of Will a Sharlindra, nell'Undercity. Farà in modo che venga consegnata a Lady Sylvanas. Ti sconsiglio di pensare di usarla per i tuoi scopi, $N: la sorte di Mug'Thol dovrebbe bastare come esempio.", enHash = "2fed972a", vanilla = true },
        objectives = { it = "Consegna la Crown of Will a Sharlindra, nell'Undercity.", enHash = "a145c98a", vanilla = true },
        progress = { it = "Sì? Hai qualcosa da riferire?", enHash = "65f5e756", vanilla = true },
        reward = { it = "Dunque è questa la reliquia che l'ogre usava per sottrarsi alla volontà della Signora Oscura...\n\nStrano che una cosa così semplice possa avere un potere tanto grande. E finire in mani così goffe. Ben fatto, $N: consegnerò la corona a Lady Sylvanas, e farò in modo che venga a sapere della tua impresa.", enHash = "97b1204e", vanilla = true },
    },
    [522] = {
        title = { it = "Assassin's Contract", enHash = "b8886ee1", vanilla = true },
        text = { it = "Questo è un contratto per l'assassinio di Magistrate Henry Maleb. È stato sigillato con ceralacca rossa, usando un anello con sigillo inconfondibile.", enHash = "5a172372", vanilla = true },
        objectives = { it = "Porta l'Assassin's Contract a Magistrate Maleb, a Southshore.", enHash = "656e8f1e", vanilla = true },
        progress = { it = "Sei senza fiato! Hai qualcosa da riferire?", enHash = "9f574b24", vanilla = true },
        reward = { it = "<Maleb esamina il contratto.>\n\nQuesto spiega l'ultimo attacco a Southshore. Il Syndicate deve avercela con me, come l'aveva con l'ultimo magistrato!", enHash = "240c3d28", vanilla = true },
    },
    [523] = {
        title = { it = "La fine del barone", enHash = "5822e971", vanilla = true },
        text = { it = "Il contratto che hai recuperato è firmato da Baron Vardus, un nobile dell'ex regno di Alterac, noto per il suo cuore di ghiaccio e i suoi metodi brutali. Non mi sorprende che dietro a tutto questo ci fosse uno come il barone.\n\nTrova quest'uomo. Trovalo, e consegnalo alla giustizia. Deve trovarsi in uno dei covi del Syndicate: forse tra le rovine di Strahnbrad, o forse nella valle a nord di esse.", enHash = "a2b0da1f", vanilla = true },
        objectives = { it = "Porta l'Head of Baron Vardus a Magistrate Maleb, a Southshore.", enHash = "6504ceb3", vanilla = true },
        progress = { it = "Baron Vardus non può pensare che Southshore gli permetta di mandarci contro i suoi delinquenti impunemente. Voglio la sua testa!", enHash = "4bef4ac7", vanilla = true },
        reward = { it = "Grazie, $N. La mia testa riposa un po' più tranquilla, sapendo che quel furfante ha perso la sua.", enHash = "ce3d95e5", vanilla = true },
    },
    [524] = {
        title = { it = "Elixir of Agony", enHash = "e9b5484c", vanilla = true },
        text = { it = "Qui accanto i Guardiamorte tengono prigionieri alcuni contadini catturati. High Executor Darthalia sospettava che tra loro si nascondesse uno degli strateghi militari di Stormwind. A quanto pare il tizio è stato trovato morto nelle Plaguelands ieri notte. Darthalia, che ha sempre un occhio di riguardo per me, ha deciso di lasciare i prigionieri a mia disposizione.\n\nCredo sia ora di offrire una festa a quei contadini. Sembra proprio una bella idea!\n\nPosa questo barile infetto sul tappeto nella loro stanza. Birra appestata per tutti!", enHash = "acb81e07", vanilla = true },
        objectives = { it = "Posa il Tainted Keg sul tappeto, per i contadini prigionieri.", enHash = "d72ffca8", vanilla = true },
        progress = { it = "Dal tappeto sale un odore di muffa.", enHash = "41015469", vanilla = true },
        reward = { it = "Posi il barile infetto sul tappeto polveroso.", enHash = "aab2b907", vanilla = true },
    },
    [525] = {
        title = { it = "Altri misteri", enHash = "26991721", vanilla = true },
        text = { it = "Ho decifrato la lettera, ma non so cosa pensarne. L'hai trovata tra dei ladri, sulle colline ai piedi delle montagne di Alterac? Molto strano...\n\nDovresti portarla al magistrato di Southshore. Anche se questa lettera è criptica, la sua è la città più vicina ad Alterac; se si sta preparando una minaccia, dovrebbe saperlo.", enHash = "3362ec43", vanilla = true },
        objectives = { it = "Porta la Decrypted Letter a Magistrate Maleb, a Southshore.", enHash = "1c03a4eb", vanilla = true },
        progress = { it = "$N. Hai di nuovo viaggiato tra le colline e le montagne? Che notizie porti?", enHash = "4253dc13", vanilla = true },
        reward = { it = "<Maleb legge la lettera.>\n\nQuesta è la traduzione di una lettera che hai trovato in un accampamento del Syndicate? Non l'ha scritta un ladro, e nemmeno un nobile di Alterac.\n\nSembra che il Syndicate abbia legami con un altro potere, e rabbrividisco al pensiero di quale possa essere.", enHash = "a1809bed", vanilla = true },
    },
    [526] = {
        title = { it = "Lightforge Ingots", enHash = "eb7642fb", vanilla = true },
        text = { it = "In quella cassa avrai anche trovato un Lightforge Ingot, ma non basta per forgiare niente di decente!\n\nDovresti tornare là e cercarne altri. Magari i murloc intorno a quella nave naufragata ne hanno addosso.", enHash = "a033c627", vanilla = true },
        objectives = { it = "Raccogli 5 Lightforge Ingot, poi torna da Glorin Steelbrow, nelle Wetlands.", enHash = "105cc4b9", vanilla = true },
        progress = { it = "L'hai trovato il Lightforge Iron che ti serve?", enHash = "9f98110b", vanilla = true },
        reward = { it = "Ah, li hai trovati! E adesso battiamo questo Lightforge Iron fino a farne qualcosa di utile, eh?", enHash = "af19695e", vanilla = true },
    },
    [527] = {
        title = { it = "La battaglia di Hillsbrad", enHash = "e86f3124", vanilla = true },
        text = { it = "Sull'attenti quando ti rivolgi a me, $C.\n\nSono sotto il comando diretto di Varimathras. Dobbiamo reprimere l'infestazione umana finché i nostri speziali non avranno sviluppato la nuova piaga.\n\nLe nostre informazioni ci portano a credere che la città di Hillsbrad sia vulnerabile a un attacco. Il tuo primo incarico mira a interrompere i loro rifornimenti di cibo e le loro infrastrutture.\n\nVa' a ovest. Saccheggia le fattorie più a nord degli Hillsbrad Fields. Assicurati che anche i proprietari, Farmer Ray e Farmer Getz, vengano giustiziati.", enHash = "a4d5f6a5", vanilla = true },
        objectives = { it = "Uccidi 6 Hillsbrad Farmhand, 6 Hillsbrad Farmer, Farmer Ray e Farmer Getz, poi torna a riferire a Darthalia, a Tarren Mill.", enHash = "47330f57", vanilla = true },
        progress = { it = "Come High Executor di Tarren Mill, sotto il comando diretto di Varimathras e della Signora Oscura, sei $Gtenuto:tenuta; a obbedire ai miei ordini.\n\nForse prendi questa guerra con l'Alleanza alla leggera? Se è così dovrei decapitarti qui e ora. Altrimenti va' a ovest, alla città di Hillsbrad, e combatti contro gli umani, come ordinato.\n\nPuoi andare.", enHash = "ee0d0bc1", vanilla = true },
        reward = { it = "Riposo, $C. Vedo che sei $Gtornato:tornata; dalla battaglia. Le mie fonti mi dicono che ti sei $Gcomportato:comportata; bene sul fronte di Hillsbrad.", enHash = "8a2d87d6", vanilla = true },
    },
    [528] = {
        title = { it = "La battaglia di Hillsbrad", enHash = "e86f3124", vanilla = true },
        text = { it = "La notizia dell'attacco alle fattorie del nord ha gettato la gente del posto nel panico. Ottimo.\n\nI nostri Inseguitori della Morte riferiscono che i contadini fuggono verso i campi nell'Hillsbrad meridionale. Gli sciocchi credono di potersi nascondere nei frutteti e sfuggire alla loro fine.\n\nDimostra che si sbagliano, $N. Torna agli Hillsbrad Fields e stana i contadini acquattati. Falli a pezzi nel nome della nostra Signora Oscura.\n\nPuoi andare!", enHash = "11ad26ad", vanilla = true },
        objectives = { it = "Uccidi 15 Hillsbrad Peasant, poi torna a riferire a Darthalia, a Tarren Mill.", enHash = "6bc97718", vanilla = true },
        progress = { it = "Hai i tuoi ordini, $C. Smettila di gingillarti qui a Tarren Mill quando c'è del lavoro da fare altrove.", enHash = "bdd40f7f", vanilla = true },
        reward = { it = "La morsa della morte si stringe intorno alla città di Hillsbrad. La battaglia va bene.", enHash = "0427b14e", vanilla = true },
    },
    [529] = {
        title = { it = "La battaglia di Hillsbrad", enHash = "e86f3124", vanilla = true },
        text = { it = "Gli umani di Hillsbrad oppongono una resistenza inattesa. Il problema sembra essere che la gente del posto viene armata dal fabbro locale. Dobbiamo interrompere tutte le linee di rifornimento.\n\nLa tua missione sarà giustiziare Blacksmith Verringtan. Uccidi anche i suoi apprendisti. Già che ci sei, riporta un carico di ferro dalla loro scorta. I rifornimenti ci torneranno utili quando avremo finito di conquistare Hillsbrad e cominceremo a radere al suolo Southshore.", enHash = "0e8be59e", vanilla = true },
        objectives = { it = "Uccidi Blacksmith Verringtan e 4 Hillsbrad Apprentice Blacksmith.\n\nRecupera un carico di ferro e torna a riferire a Darthalia, a Tarren Mill.", enHash = "ccc16c78", vanilla = true },
        progress = { it = "Sei $Griuscito:riuscita; a eseguire gli ordini, $C? Ti sei $Gsbarazzato:sbarazzata; di Verringtan e dei suoi aiutanti? E dov'è quel carico di ferro?", enHash = "264ea229", vanilla = true },
        reward = { it = "Missione compiuta, $C. E svolta anche con una certa abilità, devo dire.", enHash = "36755d3a", vanilla = true },
    },
    [530] = {
        title = { it = "La vendetta di un marito", enHash = "17e21ff2", vanilla = true },
        text = { it = "Valdred, un tempo mio caro amico, è l'assassino di mia moglie. Anche se non sono capace di provare dolore, la vendetta la desidero eccome. Se uccidi Valdred e mi porti le sue mani maledette, ti ricompenserò.\n\nL'ultima volta ho saputo che era al Greymane Wall, nel sud di Silverpine, e cercava di fuggire nel regno di Gilneas.", enHash = "23eb23ea", vanilla = true },
        objectives = { it = "Uccidi Valdred Moray.\n\nPorta le sue mani a Raleigh Andrean, nell'Undercity.", enHash = "9fc119fb", vanilla = true },
        progress = { it = "Hai quelle mani, $N?", enHash = "e1bfc872", vanilla = true },
        reward = { it = "Ah, bene. Queste mani hanno ucciso mia moglie, Deliah. La vendetta per il suo omicidio era l'unica cosa che mi stesse a cuore, e tu ne sei $Gstato:stata; lo strumento.\n\nEcco, prendi l'anello che mi hai riportato. Deliah è morta per me da così tanto tempo che il suo anello è un ninnolo che non mi importa più di tenere. Terrò invece queste mani, a ricordo del tradimento del mio amico.", enHash = "fbd984f2", vanilla = true },
    },
    [531] = {
        title = { it = "La vendetta di Vyrin", enHash = "9513c5ea", vanilla = true },
        text = { it = "Luce! Non portare cose del genere dentro il Lodge... è antigienico, indicibile, in... in... antigienico!\n\nPortala via di qui, vuoi? Nessuno ha voglia di vedere il tuo piccolo trofeo insanguinato, davvero!", enHash = "764da067", vanilla = true },
        objectives = { it = "Porta la testa di Ol' Sooty a Vyrin Swiftwind, al Farstrider Lodge.", enHash = "9e300367", vanilla = true },
        progress = { it = "Ottimo lavoro, $N! Gliel'abbiamo fatta vedere! Dai, passami la testa e me ne occupo io.", enHash = "b3c16406", vanilla = true },
        reward = { it = "Grazie per avermi aiutata con il mio piccolo piano, $N. Era mesi che morivo dalla voglia di rifarmi su quel ragazzino presuntuoso e altezzoso, e direi che ce la siamo cavata piuttosto bene! Tieni, prendi questo: te lo sei $Gguadagnato:guadagnata;.", enHash = "2e126e07", vanilla = true },
    },
    [532] = {
        title = { it = "La battaglia di Hillsbrad", enHash = "e86f3124", vanilla = true },
        text = { it = "La città di Hillsbrad è allo sbando e crediamo che cadrà presto. Dobbiamo però continuare a essere spietati finché la feccia umana non sarà spazzata via da queste colline per l'eternità.\n\nNonostante le perdite enormi, gli umani si stringono intorno ai loro capi e continuano a combattere. Dobbiamo eliminare il loro capo, Magistrate Burnside, e anche il consiglio cittadino. Distruggi anche il loro venerato documento politico, l'Hillsbrad Proclamation. E già che ci sei, ruba il registro della città.", enHash = "78bd1096", vanilla = true },
        objectives = { it = "Uccidi Magistrate Burnside e 5 Hillsbrad Councilman. Distruggi l'Hillsbrad Proclamation. Ruba l'Hillsbrad Town Registry. Poi torna a riferire a Darthalia, a Tarren Mill.", enHash = "dba28eb8", vanilla = true },
        progress = { it = "Che notizie porti?", enHash = "466a3f87", vanilla = true },
        reward = { it = "La voce delle tue imprese a Hillsbrad ha corso veloce. Hai fatto un buon lavoro, $C.", enHash = "29c522a7", vanilla = true },
    },
    [533] = {
        title = { it = "Infiltrazione", enHash = "daddb5f3", vanilla = true },
        text = { it = "Finalmente cominciano ad arrivare voci e notizie, troviamo prove di dove si trovi Gol'dir. Gli umani lo spostano di continuo, ma stiamo restringendo il campo e ci concentriamo sul grande accampamento del Syndicate appena a nord di qui.\n\nVa' là, $N, e riporta tutte le informazioni su cui riesci a mettere le mani.", enHash = "c9cc7f15", vanilla = true },
        objectives = { it = "Recupera informazioni su dove si trovi Gol'dir per Krusk, a Tarren Mill.", enHash = "39ed9d6a", vanilla = true },
        progress = { it = "Hai trovato qualcosa? Temo che le speranze per Gol'dir si riducano di giorno in giorno...", enHash = "84877ccb", vanilla = true },
        reward = { it = "Finalmente sappiamo dove tengono Gol'dir. L'accampamento in questione non è lontano da qui, e speriamo che non siano preparati come lo erano quando ci catturarono la prima volta.", enHash = "45bc0777", vanilla = true },
    },
    [535] = {
        title = { it = "Valik", enHash = "06ac9003", vanilla = true },
        text = { it = "Urrgh... Ferito, morente e davanti al nemico.\n\nSenza dubbio mi ucciderai comunque, ma se mi porti un po' di Southshore Stout (quelli come te bevono, vero?), ti dirò quello che vuoi sapere.", enHash = "1f8d7ff1", vanilla = true },
        objectives = { it = "Porta un boccale di Southshore Stout a Valik, nell'accampamento del Syndicate.", enHash = "3cfd1f29", vanilla = true },
        progress = { it = "Mi hai portato qualcosa da bere o sei solo $Gtornato:tornata; a finire il lavoro?", enHash = "c1721d5a", vanilla = true },
        reward = { it = "Vista la mia morte imminente, credo di poter dire tranquillamente che questa è la cosa più dolce che abbia mai assaggiato... Ecco, prendi questo, da morto non mi servirà a niente.\n\nBe', avanti, fallo!", enHash = "4ce7d005", vanilla = true },
    },
    [536] = {
        title = { it = "Giù lungo la costa", enHash = "3a0d6829", vanilla = true },
        text = { it = "Trasferito dalla guardia cittadina di Stormwind a Southshore, una città che a vederla dovrebbe essere abbandonata... Puzza di porto giorno e notte.\n\nPer non parlare del vecchio Redpath... Vuole che mi occupi dei murloc. Ah!\n\nRiesco a malapena a trovare la forza di andare fino a qualcuna delle sacche di quei pesci sovracresciuti giù lungo il Western Strand. Se ci andassi tu al posto mio e te ne occupassi, te ne sarei riconoscente.", enHash = "9fc23e6d", vanilla = true },
        objectives = { it = "Uccidi 10 Torn Fin Tidehunter e 10 Torn Fin Oracle per Lieutenant Farren Orinelle, a Southshore.", enHash = "44cb2eae", vanilla = true },
        progress = { it = "Un'altra birra, per favore, l'ultima sembra essere sparita!\n\nLuce, quanto devo restare ancora bloccato qui?\n\nOh, sei tu, $N. Li hai già uccisi quei murloc?", enHash = "cbc725ad", vanilla = true },
        reward = { it = "Spero che basti a convincere Redpath che ho — ah! — eseguito i suoi ordini e liberato Southshore della terribile e orribile minaccia dei temutissimi murloc! Perché non può esserci male peggiore delle devastazioni di un pesce sovracresciuto!", enHash = "29e0e483", vanilla = true },
    },
    [537] = {
        title = { it = "Il consiglio oscuro", enHash = "6297cbf7", vanilla = true },
        text = { it = "La lettera che mi hai portato è stata scritta da un essere che si fa chiamare Nagaz, un membro dell'Argus Wake. Non so cosa sia questo Argus Wake, ma se hanno stretto un'alleanza con il Syndicate, devono essere una minaccia.\n\nVoglio che tu trovi Nagaz e gli Argus Shadow Mage nominati in quella lettera. Voglio che tu li trovi, e li uccida.\n\nCerca nelle Uplands, dove il Syndicate è più forte. Si trovano a nord di Strahnbrad.\n\nCon un po' di fortuna, troverai lì questi emissari dell'Argus Wake.", enHash = "7e1d594d", vanilla = true },
        objectives = { it = "Uccidi 4 Argus Shadow Mage.\n\nPorta l'Head of Nagaz a Magistrate Maleb, a Southshore.", enHash = "7cd001ce", vanilla = true },
        progress = { it = "Hai trovato gli emissari dell'Argus Wake?", enHash = "7b86c827", vanilla = true },
        reward = { it = "Ben fatto, $N. L'Argus Wake non sembra un gruppo che vorremmo alla guida del Syndicate.\n\nE anche se qui hai distrutto il loro capo, Nagaz era solo il servitore di qualcun altro. L'Argus Wake potrebbe avere radici profonde in tutto il continente di Azeroth.\n\nO perfino nel mondo intero.", enHash = "ba7243d1", vanilla = true },
    },
    [538] = {
        title = { it = "Southshore", enHash = "30e3d2c0", vanilla = true },
        text = { it = "$N. Se non ti spaventa un lungo viaggio, allora ho un compito per te, di nuovo per aiutare Stormwind a riempire la sua biblioteca.\n\nIl vecchio regno di Alterac cadde dopo la grande guerra, e aveva una grande raccolta di libri. È una tragedia che la città sia in rovina, ma è ancora più tragico che tutto il loro sapere sia andato perduto! Dobbiamo recuperare quel che possiamo.\n\nSouthshore è la città più vicina alle Ruins of Alterac. Va' là e parla con Loremaster Dibbs. Può indicarti le rovine e dirti quali libri vi si possono trovare.", enHash = "4e8f7238", vanilla = true },
        objectives = { it = "Parla con Loremaster Dibbs, a Southshore.", enHash = "0f312a41", vanilla = true },
        reward = { it = "Ah sì, mi ricordo di Milton. Un topo di biblioteca, non c'è dubbio. Che sia benedetto.\n\nE ha ragione. Le Ruins of Alterac custodiscono ancora depositi di sapere in pericolo di andare perduti!\n\nOra ad Alterac vivono gli ogre, e a loro del sapere importa ben poco.", enHash = "6b4dd0c2", vanilla = true },
    },
    [539] = {
        title = { it = "La battaglia di Hillsbrad", enHash = "e86f3124", vanilla = true },
        text = { it = "L'Hillsbrad Town Registry indica che l'Azureload Mine è sotto il controllo dell'Alleanza. Non solo: la miniera è una delle principali fonti di minerale di ferro per le armerie dell'Alleanza.\n\nAnche se abbiamo inferto un colpo decisivo alla città di Hillsbrad, l'Alleanza continua a sostenere e a proteggere con accanimento l'Azureload Mine.\n\nLa miniera si trova proprio a sud di Hillsbrad. Va' là e uccidi il caposquadra, un umano di nome Bonds. Uccidi anche i suoi minatori. Dovrebbe essere un messaggio chiaro per l'Alleanza.", enHash = "5ed56190", vanilla = true },
        objectives = { it = "Uccidi Foreman Bonds e 10 Hillsbrad Miner, poi torna a riferire a Darthalia, a Tarren Mill.", enHash = "0040802d", vanilla = true },
        progress = { it = "Ti sono stati dati ordini precisi: attaccare l'Azureload Mine. Spero per te che i motivi per cui bighelloni a Tarren Mill siano buoni, o ti farò decapitare per tradimento.", enHash = "6697d5cc", vanilla = true },
        reward = { it = "La Signora Oscura sarà contenta quando saprà di avere una nuova miniera con cui armare i suoi soldati.", enHash = "79380b5f", vanilla = true },
    },
    [540] = {
        title = { it = "Preservare il sapere", enHash = "c4ad3d27", vanilla = true },
        text = { it = "Quegli ogre bestiali ora abitano tra le rovine di Alterac, e rabbrividisco a pensare cosa stiano facendo ai preziosi libri rimasti là. Devi recuperare quel che puoi!\n\nEntra nelle Ruins of Alterac e cerca i tomi saccheggiati dagli ogre. Prendi tutto quel che riesci a trovare e portamelo, ma cerca anche un libro in particolare: The Arm of Gri'lek. Contiene antiche tradizioni dei troll che devo studiare, e le Ruins of Alterac sono l'ultimo posto in cui si sappia ci fosse una copia intatta di questo libro.", enHash = "c1e1a4ea", vanilla = true },
        objectives = { it = "Porta 5 Recovered Tome e il Worn Leather Book che contiene The Arm of Gri'lek a Loremaster Dibbs, a Southshore.", enHash = "096a3165", vanilla = true },
        progress = { it = "Vorrei poter cercare anch'io tra le rovine, ma temo che queste vecchie ossa non mi reggerebbero durante la salita sulle montagne. Comunque, come procede la tua caccia al sapere, $N?", enHash = "a1863547", vanilla = true },
        reward = { it = "Oh, li hai presi! Splendido! Devo cominciare subito a studiare The Arm of Gri'lek!", enHash = "cfdb0ac9", vanilla = true },
    },
    [541] = {
        title = { it = "La battaglia di Hillsbrad", enHash = "e86f3124", vanilla = true },
        text = { it = "I nani aiutano gli umani? Maledetti quei piccoli esseri immondi.\n\nMetteremo alla prova la forza della cosiddetta Alleanza. Vedremo quanta voglia hanno quegli spacca-caviglie di aiutare gli umani, una volta assaggiata la nostra ira. Sappiamo esattamente dov'è la loro roccaforte in questo territorio.\n\nHanno messo su una caserma nell'Hillsbrad sud-orientale, lungo Thoradin's Wall: si chiama Dun Garok. L'ultima missione di questa battaglia è assediare Dun Garok, $C. Captain Ironhill, il loro capo, deve morire.", enHash = "f757275a", vanilla = true },
        objectives = { it = "Va' a Dun Garok, uccidi 10 Mountaineer, 8 Rifleman, 4 Priest e Captain Ironhill, poi torna a riferire a Darthalia, a Tarren Mill.", enHash = "fef6d978", vanilla = true },
        progress = { it = "Dun Garok è un ostacolo troppo grande per te, $C? E io che pensavo ti fossi $Gdistinto:distinta; valorosamente a Hillsbrad.\n\nSe non sei all'altezza della missione che ti è stata assegnata, ne troverò un altro capace di ottenere risultati migliori. Quanto a te, be', sono certa che alla Signora Oscura servano sempre altri becchini nelle Tirisfal Glades.", enHash = "da143e10", vanilla = true },
        reward = { it = "Quel che hai fatto sul campo di battaglia merita la lode più alta.", enHash = "472303c9", vanilla = true },
    },
    [542] = {
        title = { it = "Ritorno da Milton", enHash = "c7dc8758", vanilla = true },
        text = { it = "Mi serve un po' di tempo per studiare il libro The Arm of Gri'lek che mi hai portato, anche se sono sicuro che Milton non veda l'ora di aggiungere gli altri libri recuperati alla collezione di Stormwind.\n\nEccoti i libri che hai raccolto nelle Ruins of Alterac, impacchettati e catalogati. Riportali a Milton Sheaf, a Stormwind, e sono sicuro che te ne sarà grato.", enHash = "f3b2f580", vanilla = true },
        objectives = { it = "Porta i Tomes of Alterac a Milton Sheaf, a Stormwind.", enHash = "f40d5261", vanilla = true },
        progress = { it = "$N, sei $Gtornato:tornata;! Com'è andata la tua incursione ad Alterac? Hai riportato qualcosa?", enHash = "027186ec", vanilla = true },
        reward = { it = "Perbacco! Ma guarda qui! Non posso credere che siano sopravvissuti alla rovina di Alterac. E a tutti quegli ogre!\n\nGrazie, $N. Grazie di cuore! Hai aiutato a preservare il sapere degli umani, e aggiungi lustro alla Royal Library of Stormwind.", enHash = "93b71577", vanilla = true },
    },
    [543] = {
        title = { it = "La Perenolde Tiara", enHash = "e09c2d90", vanilla = true },
        text = { it = "La Perenolde Tiara è un antico cimelio dei \"nobili\" Perenolde, la famiglia che regnava su Alterac prima che quel regno cadesse in rovina. Si dice sia stata forgiata da mastri gioiellieri a Ironforge e ornata con gli smeraldi più pregiati.\n\nQuando Alterac fu distrutta la Tiara andò perduta, ma corre voce che un Ogre Mage, Grel'borg the Miser, l'abbia trovata e ora vaghi per le Ruins of Alterac in cerca di altri tesori.\n\nVorremmo che la recuperassi per noi.", enHash = "0c422a99", vanilla = true },
        objectives = { it = "Porta la Perenolde Tiara a Remington Ridgewell, a Stormwind.", enHash = "aef26ef5", vanilla = true },
        progress = { it = "Salve, $N. Cerca di non calpestarmi i risvolti dei pantaloni. Questo completo è appena stato fatto su misura.", enHash = "cf684ada", vanilla = true },
        reward = { it = "Ah, è splendida. Andrà pulita, naturalmente, ma ti sei davvero $Gsuperato:superata;, $N. Farò preparare la tiara e sistemare nella nostra collezione al più presto.\n\nCome sono certo converrai, la nostra gratitudine è grande quanto la nostra collezione.", enHash = "5bd85d10", vanilla = true },
    },
    [544] = {
        title = { it = "Irruzione in prigione", enHash = "412e4edb", vanilla = true },
        text = { it = "Sono venuto a Tarren Mill per fare ricerca, ma adesso devo risolvere una crisi. Vedi, quattro Reietti sono fuggiti dall'Undercity qualche mese fa. Hanno voltato le spalle ai loro fratelli, ma la cosa peggiore è che hanno rubato alla Signora Oscura.\n\nQuesti ladri sono entrati in una cripta sorvegliata e hanno rubato quattro manufatti, oggetti che servivano ai nostri speziali per certi studi. Sylvanas vuole indietro quei manufatti.\n\nI ladri sono fuggiti dall'Undercity a Dalaran, e quei maghi li hanno messi in quarantena nel Lordamere Internment Camp.", enHash = "39e2a562", vanilla = true },
        objectives = { it = "Trova i traditori e recupera i loro manufatti, poi torna da Magus Voidglare, a Tarren Mill.", enHash = "c5fb4fb9", vanilla = true },
        progress = { it = "Hai trovato i ladri? E, cosa più importante, hai trovato quel che hanno rubato?", enHash = "a11bd059", vanilla = true },
        reward = { it = "Hai reso un grande servizio ai Reietti, $N. Questi manufatti ci sono mancati molto.\n\nEd è un piacere sapere che Kegan e gli altri traditori hanno avuto giustizia.", enHash = "1b061f21", vanilla = true },
    },
    [545] = {
        title = { it = "Le pattuglie di Dalaran", enHash = "98663ab4", vanilla = true },
        text = { it = "I maghi di Dalaran hanno costruito una vasta cupola magica intorno al cuore della loro città. C'è chi crede fosse per proteggersi dalle violenze di questi tempi, e chi dice che volessero solo la solitudine, per studiare e tramare.\n\nA me non importa quale fosse il motivo. Mi importa che le periferie in rovina della loro città, fuori dalla cupola, potrebbero nascondere preziosi tesori magici.\n\nMa la zona è pattugliata dai maghi e dai loro schiavi elementali.\n\nQuindi dagli la caccia, e torna quando il loro numero sarà ridotto a sufficienza.", enHash = "e71ca42f", vanilla = true },
        objectives = { it = "Uccidi 6 Dalaran Summoner e 12 Elemental Slave, poi torna da Magus Voidglare, a Tarren Mill.", enHash = "f0b9d39c", vanilla = true },
        progress = { it = "Hai già diradato le pattuglie di Dalaran intorno alle loro rovine?", enHash = "ea7582f5", vanilla = true },
        reward = { it = "Molto bene. Quelle rovine adesso dovrebbero essere abbastanza sicure da esplorare, se si sta attenti.\n\nGrazie, $N.", enHash = "17054db1", vanilla = true },
    },
    [546] = {
        title = { it = "Souvenir di morte", enHash = "78b46447", vanilla = true },
        text = { it = "Ho sentito che Darthalia ti ha arruolato per far guerra agli umani di Hillsbrad. Che invidia...\n\nMentre tu te ne vai in giro a divertirti — ammazzare umani, saccheggiare la città, terrorizzare gente innocente — io resto qui di guardia a Tarren Mill.\n\nMagari avrai pietà di un vecchio Guardiamorte come me? Vedi, io colleziono teschi umani. E tu combatterai contro gli umani ancora per un bel po'. Nel corso della tua lunga battaglia portamene 30, e farò in modo che ne valga la pena.", enHash = "f43cc170", vanilla = true },
        objectives = { it = "Deathguard Samsa, a Tarren Mill, vuole 30 Hillsbrad Human Skull.", enHash = "6cb42366", vanilla = true },
        progress = { it = "Allora, torna $Gil fortunato:la fortunata; $N? Quanti umani hai massacrato oggi? Centinaia, spero!\n\nHai qualche teschio per me?", enHash = "874dcd86", vanilla = true },
        reward = { it = "Teschi preziosi! Che meraviglia! Ti devo quel che ho promesso, $N!", enHash = "d0d8c1cc", vanilla = true },
    },
    [547] = {
        title = { it = "La spada di Humbert", enHash = "c51e73ce", vanilla = true },
        text = { it = "High Executor Darthalia mi ha mandato a sorvegliare Dun Garok da lontano. Avevo piantato il campo appena fuori vista. Ma quando è arrivato il mattino e ho dovuto far bollire l'acqua, mi sono allontanato a raccogliere legna.\n\nAl ritorno al campo ho scoperto che la mia roba era sparita.\n\nA quanto pare erano passati degli esploratori nani da Dun Garok e se l'erano portata via. Mi serve la mia spada! Se riesci a riprendermela te ne sarei molto riconoscente. Ci sono così tanti nani là... sarà piuttosto difficile trovare lo sporco ladruncolo che l'ha rubata.", enHash = "4b002ae4", vanilla = true },
        objectives = { it = "Recupera la spada di Deathguard Humbert a Dun Garok e riportagliela a Tarren Mill.", enHash = "c4b1e440", vanilla = true },
        progress = { it = "Sei $Griuscito:riuscita; a recuperare la mia spada, $N? High Executor Darthalia mi appenderà alle travi, se scopre la mia sciocchezza.", enHash = "8432f493", vanilla = true },
        reward = { it = "L'hai trovata!\n\nAh, mi sento di nuovo intero con la mia preziosa spada in mano. Grazie mille!", enHash = "b3c6ba73", vanilla = true },
    },
    [549] = {
        title = { it = "WANTED: personale del Syndicate", enHash = "92cf2ce7", vanilla = true },
        text = { it = "Per autorità di Lady Sylvanas, tutti i membri dell'organizzazione nota come Syndicate sono ricercati morti. Chi verrà preso in custodia o catturato sarà giustiziato sul posto. Al momento si sa che si stanno radunando tra le rovine di Durnholde Keep, a sud-est di Tarren Mill.\n\nUna bella ricompensa è offerta a chiunque porti prova delle proprie imprese a High Executor Darthalia.", enHash = "d6a5b6f4", vanilla = true },
        objectives = { it = "Uccidi 10 Syndicate Rogue e 10 Syndicate Watchman. Torna da High Executor Darthalia, a Tarren Mill, per la ricompensa.", enHash = "a525fa75", vanilla = true },
        progress = { it = "Non hai niente di meglio da fare che startene qui davanti a me, $C? Da High Executor ho questioni più urgenti che fissare il tuo muso putrefatto.", enHash = "d402fa2e", vanilla = true },
        reward = { it = "Eccellente, $C. Di questo passo la peste del Syndicate sarà spazzata via da questa terra in men che non si dica.", enHash = "af08a5f8", vanilla = true },
    },
    [550] = {
        title = { it = "La battaglia di Hillsbrad", enHash = "e86f3124", vanilla = true },
        text = { it = "Poiché hai combattuto con tanto valore e tanta tenacia nella battaglia di Hillsbrad, ho scritto questo encomio, in cui esalto le tue prodezze in combattimento perché l'alto comando ne prenda atto.\n\nPorta questo encomio sigillato a Varimathras, nell'Undercity. Va' con orgoglio, $C.", enHash = "992f312e", vanilla = true },
        objectives = { it = "Porta Darthalia's Sealed Commendation a Varimathras, nell'Undercity.", enHash = "96d71da1", vanilla = true },
        progress = { it = "Cosa porta $Gun:una; $C fin nell'Undercity dal campo di battaglia?", enHash = "a3c1726f", vanilla = true },
        reward = { it = "Quindi sei tu $Gil famigerato:la famigerata; $C che ha inferto un colpo tanto decisivo alle forze dell'Alleanza nelle Hillsbrad Foothills? La voce delle tue gloriose imprese è arrivata in fretta all'Undercity.\n\nHai un bel futuro nei ranghi della Signora Oscura, se continui a mostrare questa capacità di comando e questa perizia in battaglia.\n\nAnche se la nostra minaccia principale è l'esercito del Flagello del Re dei Lich che scende da nord, il \"problema\" umano continua a intralciare i nostri piani di battaglia. Tu però hai dimostrato che gli umani possono cadere, e cadranno.", enHash = "9d1fd545", vanilla = true },
    },
    [551] = {
        title = { it = "L'Ensorcelled Parchment", enHash = "32319b23", vanilla = true },
        text = { it = "Questa pergamena è incantata con una magia che la rende indecifrabile. Ma una parola in cima al foglio si può leggere:\n\n\n      Nagaz", enHash = "1e9963d7", vanilla = true },
        objectives = { it = "Porta l'Ensorcelled Parchment a Loremaster Dibbs, a Southshore.", enHash = "d978937e", vanilla = true },
        progress = { it = "Oh. Hai qualcosa che vorresti farmi vedere? Qualche frammento di sapere raccolto su in montagna, spero...", enHash = "3e48320d", vanilla = true },
        reward = { it = "Altri appunti cifrati?\n\nVorrei avere il talento per decifrare tutti gli strani scritti che arrivano giù da Alterac. Ma temo di non avere le conoscenze necessarie.", enHash = "22aaddb9", vanilla = true },
    },
    [552] = {
        title = { it = "La vendetta di Helcular", enHash = "b91942b2", vanilla = true },
        text = { it = "Master Helcular aveva quasi completato la sua trasformazione in Lich quando un gruppo di umani inferociti scoprì la sua tana rituale sulle colline e lo uccise brutalmente. Come se non bastasse, ne seppellirono il cadavere nel cimitero di Southshore.\n\nUna simile mancanza di rispetto per il grande mago è inaccettabile. Come suo apprendista, farò in modo che la pioggia della vendetta si abbatta sulla città di Southshore.\n\nPrima ci servirà Helcular's Rod. Gli Yeti hanno invaso la sua tana rituale. Senza dubbio ce l'ha una di quelle bestie.", enHash = "1116d6a6", vanilla = true },
        objectives = { it = "Recupera Helcular's Rod dagli Yeti e riportala a Novice Thaivand, a Tarren Mill.", enHash = "edbd5e27", vanilla = true },
        progress = { it = "Hai già recuperato Helcular's Rod? Ci sono così tanti Yeti in questa regione che sarà molto difficile trovarla. Ma dobbiamo averla per andare avanti.", enHash = "008eb02f", vanilla = true },
        reward = { it = "L'hai trovata! Ottimo, $N!", enHash = "7eaa76d3", vanilla = true },
    },
    [553] = {
        title = { it = "La vendetta di Helcular", enHash = "b91942b2", vanilla = true },
        text = { it = "Tieni, prendi la Rod of Helcular. Ti servirà.\n\nHelcular preparò 3 pire cerimoniali come parte del suo incantesimo più potente. La Flame of Azel e la Flame of Veraz si trovano nelle Foothill Caverns. La Flame of Uzel si trova in una grotta sopra le caverne, più a nord tra le montagne.\n\nLa Rod of Helcular va caricata con ognuna delle tre fiamme. Una volta completato il rituale, conficca la verga nella tomba di Helcular a Southshore, la città umana a sud, sorvegliatissima. La vendetta sarà nostra!", enHash = "20acb66c", vanilla = true },
        objectives = { it = "Carica la Rod of Helcular con i poteri della Flame of Azel, della Flame of Veraz e della Flame of Uzel.\n\nConficca la verga carica nella tomba di Helcular, a Southshore.", enHash = "90a92b22", vanilla = true },
        progress = { it = "La tomba di Helcular brulica di un'energia mistica.", enHash = "50652358", vanilla = true },
        reward = { it = "Dal terreno sale un gran rombo.", enHash = "42b84e8c", vanilla = true },
    },
    [554] = {
        title = { it = "La decifrazione di Stormpike", enHash = "23ca4a1e", vanilla = true },
        text = { it = "Prospector Stormpike è un maestro della decrittazione e della decifrazione. Se gli porti la pergamena che hai trovato, con un po' di fortuna riuscirà a darle un senso. Stormpike al momento sta studiando nel quartier generale dei cercatori, a Ironforge.\n\nE quando lo vedi digli che hai parlato con me: ultimamente gli sto mandando parecchio lavoro.", enHash = "9cca4956", vanilla = true },
        objectives = { it = "Porta l'Ensorcelled Parchment a Prospector Stormpike, a Ironforge.", enHash = "769f7ae4", vanilla = true },
        progress = { it = "Altre interruzioni?\n\nAh, questa pergamena è coperta da un incantesimo molto intricato, tessuto con finezza. Posso districarlo, naturalmente, ma ci vorrà tempo. E il tempo per me è molto prezioso...\n\nForse te la compro e basta?", enHash = "5c23b9e9", vanilla = true },
        reward = { it = "Una decisione saggia. Non credo che esista un altro studioso oltre a me con le capacità per tradurre questa pergamena. E se il suo contenuto si rivelerà interessante, non temere. Ti manderò a chiamare.", enHash = "8985dd9b", vanilla = true },
    },
    [555] = {
        title = { it = "Soothing Turtle Bisque", enHash = "2ec79d74", vanilla = true },
        text = { it = "Se c'è una cosa che imparerai su Southshore è che abbiamo una delle cucine migliori a nord di Stormwind!\n\nPrendi la mia ricetta segreta della Turtle Bisque, per esempio. Ho conosciuto gente che veniva da lontano come Darkshire solo per gustarsene una scodella. A proposito, ultimamente non riesco più a prepararla. Prima salivo io stesso oltre Dalaran, fino al Lake Lordamere, a cacciare gli Snapjaw, ma adesso è troppo pericoloso. Se mi porti un po' di Turtle Meat dagli Snapjaw a nord e delle Soothing Spices, te ne preparo un po'!", enHash = "0a018838", vanilla = true },
        objectives = { it = "Porta 10 Turtle Meat e delle Soothing Spices a Chef Jessen, a Southshore.", enHash = "bd40dbb3", vanilla = true },
        progress = { it = "Fortuna con gli ingredienti? Te lo dico io, questo territorio non è più il posto tranquillo di una volta. Ah, se solo non ci fossero stati questi disordini...", enHash = "ed9ccd99", vanilla = true },
        reward = { it = "Saranno tutti contenti: la Soothing Turtle Bisque di Chef Jessen torna in tavola!", enHash = "9ac04bd5", vanilla = true },
    },
    [556] = {
        title = { it = "Gettoni di pietra", enHash = "f28ca9b5", vanilla = true },
        text = { it = "Un talento notevole dei maghi di Dalaran è la loro dimestichezza con gli elementali: creature potenti che vengono da altre dimensioni. I maghi usano gettoni magici per controllare questi elementali. Magus Voidglare vorrebbe qualcuno di questi gettoni da studiare.\n\nEntra nei territori dei maghi di Dalaran, a ovest di Hillsbrad, e raccogli i gettoni.\n\nPuoi trovarli addosso a qualunque cittadino di Dalaran, ma ti consiglio di andare a caccia al campo di internamento. È più sicuro di Dalaran stessa.", enHash = "e4d61686", vanilla = true },
        objectives = { it = "Porta 10 Worn Stone Token a Keeper Bel'varil, a Tarren Mill.", enHash = "9ea670d4", vanilla = true },
        progress = { it = "Hai i Worn Stone Token, $N? Il Magus non vede l'ora di svelarne i segreti.", enHash = "a0059157", vanilla = true },
        reward = { it = "Questi andranno benissimo. Anche se la loro magia sembra svanita, è meglio che i primi esperimenti del Magus siano su esemplari inerti come questi.\n\nGrazie, $N.", enHash = "a02145f8", vanilla = true },
    },
    [557] = {
        title = { it = "Bracciali del vincolo", enHash = "bca83928", vanilla = true },
        text = { it = "Il Magus sarà impegnato a studiare i gettoni di pietra che hai raccolto, ma so che prima o poi vorrà anche degli esemplari della loro controparte: i bracciali del vincolo. Vengono stretti ai polsi degli elementali veri e propri e li legano al servizio del mago.\n\nDa' la caccia agli elementali tra le rovine di Dalaran e raccogli i loro Bracers of Earth Binding: il Magus ne sarà contento.", enHash = "c56608b4", vanilla = true },
        objectives = { it = "Porta 4 Bracers of Earth Binding a Keeper Bel'varil, a Tarren Mill.", enHash = "e22c4352", vanilla = true },
        progress = { it = "Salve, $N. Gli elementali sono una preda dura, ma so che sei all'altezza del compito. Hai quei bracciali del vincolo?", enHash = "343a0725", vanilla = true },
        reward = { it = "Li hai trovati. Immagino che gli elementali a cui li hai tolti fossero d'accordo?\n\nHm... la morte non mi ha solo fermato il cuore, a quanto pare mi ha anche tolto il senso dei tempi comici.\n\nBe', grazie, $N. Servi bene il Magus, e quindi la Signora Oscura.", enHash = "595f97fa", vanilla = true },
    },
    [558] = {
        title = { it = "Jaina's Autograph", enHash = "21fb66d0", vanilla = true },
        text = { it = "Dicono che Lady Jaina Proudmoore, a Theramore, sia una delle più grandi eroine che l'Alleanza abbia mai avuto. Da grande voglio essere un eroe dell'Alleanza anch'io!\n\nConosci Jaina, $N? Mi faresti un favore, per piacere? Potresti procurarmi il suo autografo? Non so come chiederglielo, e probabilmente sarebbe troppo occupata per uno come me... ma tu! Sei $Gun avventuriero:un'avventuriera; proprio come lei! Scommetto che a te l'autografo lo darebbe subito!\n\nPer piacere?", enHash = "ecfddc2b", vanilla = true },
        objectives = { it = "Raggiungi Theramore e cerca di ottenere l'autografo di Lady Jaina Proudmoore per il tuo protetto.", enHash = "5fa6de33", vanilla = true },
        progress = { it = "Un giorno voglio essere un eroe proprio come Jaina... be', un eroe maschio, cioè.", enHash = "e38346a0", vanilla = true },
        reward = { it = "WOW! Mi hai procurato l'autografo di Lady Jaina! Grazie mille! E wow... ci ha scritto sopra un messaggio personale, per me! Lo sapevo che sarebbe stata fantastica, e magari un giorno la ringrazierò di persona... quando diventerò un eroe dell'Alleanza!\n\nSei $Gil migliore:la migliore;, $N. Grazie di essere così gentile con me.", enHash = "6c1f2573", vanilla = true },
    },
    [559] = {
        title = { it = "La prova di Farren", enHash = "030daf74", vanilla = true },
        text = { it = "Ci credi, $N? Redpath non era soddisfatto di tutti i murloc che abbiamo ucciso... oh, adesso non fare $Gil modesto:la modesta;, un po' di mano ce l'hai messa anche tu. Adesso vuole che gli porti le prove dei morti: tagliare teste di murloc fredde e viscide da sottoporre alla sua approvazione.", enHash = "c0df7dba", vanilla = true },
        objectives = { it = "Raccogli 10 Murloc Head dai murloc del Western Strand per Lieutenant Farren Orinelle, a Southshore.", enHash = "e3731ce9", vanilla = true },
        progress = { it = "Le hai prese quelle teste per me, $N?", enHash = "e118d186", vanilla = true },
        reward = { it = "Oh, per l'amor della Luce... stanno gocciolando per terra.\n\nIo non sopporto di toccare quelle cose. Il pesce va benissimo, ma quando mette le gambe e comincia a camminare... Non mangio pesce da settimane, credimi, e a Southshore questo vuol dire non mangiare granché.", enHash = "00f2a952", vanilla = true },
    },
    [560] = {
        title = { it = "La prova di Farren", enHash = "030daf74", vanilla = true },
        text = { it = "Sai, $N, preferirei proprio non prendere queste teste... Visto che ormai le hai in mano tu, ti spiacerebbe consegnarle a Redpath per me?", enHash = "549736bc", vanilla = true },
        objectives = { it = "Consegna il sacco di teste di murloc a Marshall Redpath, a Southshore.", enHash = "db9d7e58", vanilla = true },
        progress = { it = "Salve, $Gcittadino:cittadina;. Sei $Gvenuto:venuta; a offrire il tuo braccio per la sicurezza di Southshore?", enHash = "2fd3716e", vanilla = true },
        reward = { it = "Sei $Gil galoppino:la galoppina; di Farren, eh?\n\nSe hai aiutato Farren a procurarsi queste teste, allora grazie. Southshore ha bisogno di gente che lavori sodo e si impegni per mantenere la propria protezione.", enHash = { "a374c42f", "b2787aa3" }, vanilla = true },
    },
    [561] = {
        title = { it = "La prova di Farren", enHash = "030daf74", vanilla = true },
        text = { it = "Per favore, informa Lieutenant Orinelle che vorrei che concentrasse i suoi sforzi sui naga che infestano l'Eastern Strand. Quando avrà dei risultati, digli di venire a rapporto di persona.", enHash = "da087962", vanilla = true },
        objectives = { it = "Parla con Lieutenant Farren Orinelle, a Southshore.", enHash = "599d380c", vanilla = true },
        reward = { it = "I naga, eh? Redpath deve aver appena ricevuto la mia stessa informazione... Ah! Non sarà lui a prendersi una promozione grazie alla mia fatica. Lascia che ti spieghi.", enHash = "bf99ad75", vanilla = true },
    },
    [562] = {
        title = { it = "Verso Stormwind!", enHash = "d7bc8bcb", vanilla = true },
        text = { it = "Il mio vecchio mentore nella guardia cittadina di Stormwind mi ha mandato un messaggio: l'alto comando dell'Alleanza comincia a preoccuparsi per la minaccia dei naga. Da quel che ha sentito, ci sono buone possibilità di promozione — o almeno di trasferimento — per chi si dimostra utile su questo fronte.\n\nC'è solo un piccolo problema... Io i naga non li reggo, $N. Oh, certo, saprei sedare una rissa da taverna o portare via un mendicante molesto, ma i naga sono troppo per me. Devi aiutarmi, $N!", enHash = "d0156f92", vanilla = true },
        objectives = { it = "Uccidi 10 Daggerspine Shorehunter e 10 Daggerspine Siren per Lieutenant Farren Orinelle, a Southshore.", enHash = "276b297a", vanilla = true },
        progress = { it = "Ho una lettera pronta da mandare a Major Samuelson, a Stormwind. Mi servono solo i risultati.", enHash = "48815200", vanilla = true },
        reward = { it = "Con i naga messi a tacere a Southshore, il trasferimento è praticamente mio. Rivedrò Stormwind... via da questo porto dimenticato dalla Luce.", enHash = "01565b82", vanilla = true },
    },
    [563] = {
        title = { it = "Trasferimento", enHash = "6881b140", vanilla = true },
        text = { it = "Non dovrebbe essere un problema far leggere il mio rapporto. Il nuovo capitano della guardia, Major Samuelson, era il mio mentore quando ero di stanza a Stormwind. Dovrebbe bastargli e avanzare come scusa per farmi trasferire di nuovo in città. Ho bisogno però che gli porti tu il mio rapporto... non vorrei che il vecchio Redpath se ne accorgesse.", enHash = "9a465a54", vanilla = true },
        objectives = { it = "Consegna il rapporto di Farren a Major Samuelson, a Stormwind Keep.", enHash = "a347e2ff", vanilla = true },
        progress = { it = "Salve, $Gcittadino:cittadina;. La guardia cittadina di Stormwind può esserti utile?", enHash = "9627b550", vanilla = true },
        reward = { it = "Cos'è questo? Ah... così il mio allievo attento si è dedicato al problema dei naga a Southshore. Grazie di avermelo portato, ne terrò senz'altro conto quando rivedrò le assegnazioni del personale il mese prossimo.", enHash = "14fcd7ac", vanilla = true },
    },
    [564] = {
        title = { it = "Una minaccia costosa", enHash = "298d33b3", vanilla = true },
        text = { it = "Non c'è niente che mi dia più fastidio di perdere questi bei cavalli. E credimi, ne abbiamo persi parecchi tra quei fastidiosi non morti, quella maledetta banda del Syndicate e tutti gli altri buoni a nulla che gironzolano da queste parti.\n\nMa giuro sulla tomba del mio vecchio nonno che non c'è minaccia peggiore per i nostri cavalli dei Mountain Lion lassù ad Alterac. Scendono sempre dalle colline a complicarmi la vita!\n\nTi credi $Gun eroe:un'eroina;? E allora va' a fare qualcosa!", enHash = "f8d8dd47", vanilla = true },
        objectives = { it = "Darren Malvew, a Southshore, vuole che tu uccida 8 Mountain Lion e 10 Hulking Mountain Lion.", enHash = "cd7549b4", vanilla = true },
        progress = { it = "I Mountain Lion ci ammazzano i cavalli a destra e a manca e tu te ne stai qui a chiacchierare del tempo e di che altro.\n\nDovrei proprio andarmi a cercare $Gun eroe vero:un'eroina vera;. Più ammazzare e meno parlare.", enHash = "36e4d419", vanilla = true },
        reward = { it = "Questa sì che è una bella notizia! Avrei dovuto cercarmi $Gun vero eroe:una vera eroina; di guerra fin dal primo giorno per occuparsi di quelle bestie. Tuo padre sarebbe stato fiero di te, $N.", enHash = "c28d1f0b", vanilla = true },
    },
    [565] = {
        title = { it = "Lo Yeti Fur Cloak di Bartolo", enHash = "c5586dd7", vanilla = true },
        text = { it = "Io, il grande Bartolo, ti farò il famosissimo Yeti Fur Cloak, rinomato in tutta l'Alleanza!\n\nGira il mondo e trovati un mantello migliore, ti sfido. Oh, aspetta, cosa dici, $Gpiccolo:piccola; $R? \"Bartolo, non c'è mantello più bello!\" Sì, sì! Questo l'ho già sentito.\n\nA Bartolo servono un Bolt of Wool, un Hillman's Cloak fatto da un abile conciatore, del Fine Thread e Yeti Fur, naturalmente! Portami queste cose e sarai $Gun cliente soddisfatto:una cliente soddisfatta;!", enHash = "e333c0fe", vanilla = true },
        objectives = { it = "Porta a Bartolo Ginsetti, a Southshore, un Bolt of Wool, un Hillman's Cloak, del Fine Thread e 10 ciuffi di Yeti Fur.", enHash = "3d3c424a", vanilla = true },
        progress = { it = "Così sei $Gtornato:tornata; dal grande Bartolo. Forse hai finito di raccogliere i materiali per il tuo Yeti Fur Cloak? O magari ti piace soltanto crogiolarti nella grandezza di me, Bartolo!", enHash = "103d7a27", vanilla = true },
        reward = { it = "Ora è il momento che il grande Bartolo faccia la sua magia! Non mi serve il bastone di un mago né la verga di un incantatore. Perché io, il grande Bartolo, faccio magie con un semplice ago e un filo!", enHash = "5f6c1125", vanilla = true },
    },
    [566] = {
        title = { it = "WANTED: Baron Vardus", enHash = "2fce4ebe", vanilla = true },
        text = { it = "Per ordine di High Executor Darthalia, l'umano noto come Baron Vardus è ricercato per crimini contro i Reietti. Vardus è noto come membro di alto rango dell'organizzazione chiamata Syndicate.\n\nÈ stato avvistato l'ultima volta nelle Uplands, nelle Alterac Mountains, a nord di Tarren Mill.\n\nLo si vuole morto. Porta la prova della sua morte a High Executor Darthalia per riscuotere la ricompensa.", enHash = "6926639b", vanilla = true },
        objectives = { it = "Uccidi Baron Vardus e consegna la sua testa a High Executor Darthalia, a Tarren Mill.", enHash = "99f77a14", vanilla = true },
        progress = { it = "Ah, $N. Forse sei $Gvenuto:venuta; a riscuotere la taglia sulla testa di Baron Vardus?", enHash = "c87ec6d9", vanilla = true },
        reward = { it = "Un lavoro produttivo il tuo, $N. Con Baron Vardus morto, il numero dei capi del Syndicate diminuisce. La loro resistenza e il loro fastidio avranno vita breve.", enHash = "10dcb08d", vanilla = true },
    },
    [567] = {
        title = { it = "Pericolosi!", enHash = "38d58717", vanilla = true },
        text = { it = "Pericolosi!\n\nI seguenti umani di Hillsbrad sono stati giudicati pericolosi e su di loro pende una taglia di High Executor Darthalia:\n\nClerk Horrace Whitesteed. Ricercato per l'omicidio di Deathguard Toma.\n\nCitizen Wilkes. Ricercato per l'omicidio di Apothecary Eli.\n\nMiner Hackett. Ricercato per l'omicidio di Deathstalker Fry.\n\nFarmer Kalaba. Ricercato per l'imboscata ai rifornimenti dell'Undercity.\n\nTutti questi nemici sono nascosti e saranno difficili da trovare. Una ricompensa sarà concessa alla notizia della loro morte.", enHash = "af4c40dd", vanilla = true },
        objectives = { it = "High Executor Darthalia, a Tarren Mill, offre una taglia su Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett e Farmer Kalaba.", enHash = "80043944", vanilla = true },
        progress = { it = "Sì?", enHash = "00388a38", vanilla = true },
        reward = { it = "Sei $Gun bel cacciatore:una bella cacciatrice; di taglie, $C. Ben fatto.", enHash = "aa8badc7", vanilla = true },
    },
    [568] = {
        title = { it = "La difesa di Grom'gol", enHash = "e51ee2a0", vanilla = true },
        text = { it = "Throm'ka, $C!\n\nIl tuo arrivo a Grom'gol è davvero tempestivo. Come comandante del campo base del Capoguerra qui nella giungla, l'onore mi impone di garantire la sicurezza di tutti i membri dell'Orda. La nostra missione di assicurare una linea di rifornimento sicura verso Stonard è ostacolata da alcuni degli abitanti del posto.\n\nTi affido il compito di sfoltire la popolazione di raptor fuori da Grom'gol. Quando avrai fatto progressi significativi, torna a riferire da me per un nuovo incarico.", enHash = "e72cac2d", vanilla = true },
        objectives = { it = "Commander Aggro'gosh, del campo base di Grom'gol, vuole che tu uccida 15 Lashtail Raptor.", enHash = "1797343a", vanilla = true },
        progress = { it = "I nostri rifornimenti sono ancora ostacolati dai raptor del posto, $C.", enHash = "41058be2", vanilla = true },
        reward = { it = "Hai compiuto il tuo dovere con onore, $C.", enHash = "bc031f37", vanilla = true },
    },
    [569] = {
        title = { it = "La difesa di Grom'gol", enHash = "e51ee2a0", vanilla = true },
        text = { it = "Quando siamo arrivati in questa giungla non avevamo intenzione di fare guerra alle tribù del posto. La nostra missione di rifornire Stonard ha la massima priorità. Ma sono sorte delle complicazioni. Una banda di ogre del posto ha occupato le Mizjah Ruins, a sud-est di Grom'gol. Nonostante gli avvertimenti, continuano a tendere agguati alle nostre carovane di rifornimenti.\n\nTi affido il compito di occuparti di questi ogre poco collaborativi.\n\nVa' alle rovine e cerca di cacciarli dalla zona. Se non altro, sarà un messaggio chiaro.", enHash = "01223782", vanilla = true },
        objectives = { it = "Commander Aggro'gosh, del campo base di Grom'gol, vuole che tu uccida 10 Mosh'Ogg Brute e 5 Mosh'Ogg Witch Doctor.", enHash = "1d48b024", vanilla = true },
        progress = { it = "Hai fatto progressi con gli ogre delle Mizjah Ruins, $C?", enHash = "9e38fe82", vanilla = true },
        reward = { it = "Ben fatto. Hai servito il Capoguerra con onore.", enHash = "8b1c4a78", vanilla = true },
    },
    [570] = {
        title = { it = "L'incantamento di Mok'thardin", enHash = "887e8689", vanilla = true },
        text = { it = "Il potere della magia della giungla va compreso e poi imbrigliato dall'Orda. Finora i miei rituali hanno avuto successo. Posso lanciare incantamenti molto potenti. Per te, $Gvaloroso:valorosa; $C, creerò davvero un oggetto speciale.\n\nPortami degli artigli di Shadowmaw Panther e una zanna di tigressa. Non va bene una zanna qualsiasi: deve essere in condizioni perfette.\n\nLe bestie si aggirano in tutta la giungla, ma ne troverai alcune qui vicino, appena oltre il fiume, dalle Mizjah Ruins verso sud-est.", enHash = "708f083e", vanilla = true },
        objectives = { it = "Far Seer Mok'thardin, al campo base di Grom'gol, vuole 8 Shadowmaw Claw e una Pristine Tigress Fang.", enHash = "e546e7ed", vanilla = true },
        progress = { it = "Che notizie porti?", enHash = "f4562312", vanilla = true },
        reward = { it = "La tua conoscenza della giungla è grande, $N. Questi esemplari saranno perfetti. Ringrazierò gli spiriti per aver sacrificato bestie così belle alla causa dell'Orda.", enHash = "73f8da62", vanilla = true },
    },
    [571] = {
        title = { it = "L'incantamento di Mok'thardin", enHash = "887e8689", vanilla = true },
        text = { it = "Quello che mi serve adesso sarà molto difficile da procurare.\n\nPer tenere insieme tutte queste piume, gli artigli e la zanna perfetta, mi serve un legame magico. Funzionerà solo un Aged Gorilla Sinew.\n\nPotrai trovarne uno solo su un Elder Mistvale Gorilla. Si sa che vanno in cerca di cibo a est di Booty Bay.\n\nIl tendine deve essere perfetto. Potresti doverne uccidere parecchi prima di trovare esattamente quello che mi serve, ma la caccia ne varrà la pena.", enHash = "b31aa122", vanilla = true },
        objectives = { it = "Porta un Aged Gorilla Sinew a Far Seer Mok'thardin, a Grom'gol.", enHash = "c4eb8684", vanilla = true },
        progress = { it = "La fortuna è stata dalla tua parte, $N? Sei $Griuscito:riuscita; a procurarti un Aged Gorilla Sinew?", enHash = "ad5406a6", vanilla = true },
        reward = { it = "Un tendine davvero perfetto, $N. I tuoi sforzi saranno presto ripagati.", enHash = "72423633", vanilla = true },
    },
    [572] = {
        title = { it = "L'incantamento di Mok'thardin", enHash = "887e8689", vanilla = true },
        text = { it = "Le cose che hai raccolto dalle bestie feline della Vale sono solo il primo requisito per un potente oggetto incantato. Questi ninnoli della giungla, uniti al mio rituale sciamanico, ti daranno uno strumento molto utile per aiutare l'Orda e il Capoguerra.\n\nMa ora devi raccogliere per me delle Jungle Stalker Feather. Per tradizione, le bestie portano le piume sulle fasce che hanno al braccio. Troverai una tribù di questi raptor proprio a sud di Grom'gol, non lontano dalla grande arena.", enHash = "0544ea7b", vanilla = true },
        objectives = { it = "Porta 10 Jungle Stalker Feather a Far Seer Mok'thardin, al campo base di Grom'gol.", enHash = "005c00b5", vanilla = true },
        progress = { it = "La tua raccolta ha dato frutti?", enHash = "1bace754", vanilla = true },
        reward = { it = "Eccellente. Le preparerò subito.", enHash = "198af398", vanilla = true },
    },
    [573] = {
        title = { it = "L'incantamento di Mok'thardin", enHash = "887e8689", vanilla = true },
        text = { it = "Manca solo un ultimo reagente per completare l'incantamento.\n\nA sud, verso la costa occidentale, in alto sopra le scogliere, si trova la Holy Spring. Questa sorgente è oggetto di grande contesa tra studiosi di religione e di misticismo. Ogni razza di Azeroth sostiene che le acque della sorgente siano state rese divine per il proprio popolo.\n\nL'ultima cosa che ti chiedo: portami della Holy Spring Water. Ma fa' attenzione. Una spedizione di Naga Explorer è avanzata fino alla sorgente. Dovrai occuparti anche di loro.", enHash = "1579394a", vanilla = true },
        objectives = { it = "Far Seer Mok'thardin, di Grom'gol, ha bisogno di Holy Spring Water. Vuole anche che tu uccida 10 Naga Explorer.", enHash = "50cbd8a1", vanilla = true },
        progress = { it = "Sono quasi pronto a completare l'incantamento. Hai fatto quanto ti ho chiesto?", enHash = "01785d79", vanilla = true },
        reward = { it = "Con questa Holy Spring Water il girocollo cerimoniale è pronto per l'incantamento.\n\nPortalo con orgoglio, $N, in nome del Capoguerra e in difesa della possente Orda.", enHash = "25e3e3f8", vanilla = true },
    },
    [574] = {
        title = { it = "Forze speciali", enHash = "f1af682f", vanilla = true },
        text = { it = "Ora che molte delle sue truppe regolari sono state decimate, devi affrontare le sue forze meglio addestrate. Quando non sono nelle terre selvagge a massacrare i nostri soldati ribelli, si trovano in fondo al Kurzen's Compound, in una caverna che chiamano lo Stockpile.\n\nConosco di persona molti soldati di Kurzen, e so che sono abili, leali e crudeli. Non è un compito facile quello che ti affido, $N.\n\nDopo averli sconfitti, fai rapporto a Lieutenant Doren, il mio ufficiale comandante. Vorrà sentire il tuo rapporto di persona.", enHash = "4b7873af", vanilla = true },
        objectives = { it = "Uccidi 10 Kurzen Commando e 6 Kurzen Headshrinker.\n\nFai rapporto a Lieutenant Doren, al Rebel Camp.", enHash = "13a97fec", vanilla = true },
        progress = { it = "Sergeant Yohwa mi dice che sei abile e $Gcoraggioso:coraggiosa;, $C. Hai qualcosa da riferire?", enHash = "2e642c9e", vanilla = true },
        reward = { it = "$N. Sergeant Yohwa si fidava delle tue capacità, e io mi fido di lei. La sconfitta che hai inflitto alle forze di Kurzen va quasi oltre ogni speranza. Temevo che noi ribelli fossimo soli, e da soli non avremmo mai potuto tenere testa alla genialità del colonnello.\n\nForse c'è ancora speranza di sopravvivere.", enHash = "a93b8ffb", vanilla = true },
    },
    [575] = {
        title = { it = "Domanda e offerta", enHash = "7a337c85", vanilla = true },
        text = { it = "\"Il miglior conciatore dei South Seas e dei mondi vecchi e nuovi.\" È così che mi chiamano. Io! Drizzlik! Il miglior concia... Ehm. Bene.\n\nI miei articoli in pelle sono noti in lungo e in largo come i più raffinati, la scelta degli intenditori!\n\nHo appena ricevuto un ordine da Director Riddlevox della Tinkers' Union per una dozzina dei suoi stivali preferiti della linea Excelsior. I nostri più venduti, a dire il vero.\n\nPer cominciare con la forma di base, mi servono pelli di crocolisk prese dai coccodrilli lungo il fiume, nella Stranglethorn settentrionale.", enHash = "6be977d2", vanilla = true },
        objectives = { it = "Porta 2 Large River Crocolisk Skin a Drizzlik, a Booty Bay.", enHash = "d3fd0c22", vanilla = true },
        progress = { it = "La mia attrezzatura è pronta, $N, mi servono solo quelle pelli. Non vogliamo far aspettare Riddlevox, questo è certo.\n\nNon è una buona idea, per nessuno, lasciare insoddisfatto il capo inventore della Tinkers' Union.", enHash = "c90005de", vanilla = true },
        reward = { it = "Queste pelli dovrebbero andare. La loro qualità non conta troppo, visto che formeranno lo strato interno degli stivali, ma è comunque importante che siano comode.\n\nSe sono un po' troppo rigide, userò del sangue di tigre per ammorbidirle. Trucchi del mestiere, sai?", enHash = "98f89cad", vanilla = true },
    },
    [576] = {
        title = { it = "Apri l'occhio", enHash = "b386a767", vanilla = true },
        text = { it = "Alt! Chi va là?\n\nArgh, senza il mio speciale occhio incantato non servo a niente. Già era abbastanza brutto aver perso gli occhi in battaglia! Ma per un colpo di fortuna abbiamo attraccato a Menethil, e un mago girovago ha incantato uno speciale occhio di vetro che mi ha fatto tornare a vedere.\n\nIeri notte, mentre uscivo, mi sono fatto assalire da un gruppo di Bloodsail Buccaneers. Mi hanno preso l'occhio, sì! Pare che quei tizi siano arrivati fino a Booty Bay.\n\nAiuti un vecchio lupo di mare a riavere il suo occhio?", enHash = "a6d7cea8", vanilla = true },
        objectives = { it = "Dizzy One-Eye, a Booty Bay, vuole che tu recuperi il suo occhio dai Bloodsail Buccaneers.", enHash = "e53f76c5", vanilla = true },
        progress = { it = "Ahoy, $Gragazzo mio:ragazza mia;! Forse non ci vedo, ma ti sento l'odore da un capo all'altro del porto.\n\nMi servirebbe proprio il mio occhio. Il capitano mi farà passare sotto la chiglia quando scoprirà che la mia pupilla è nelle mani di quegli sporchi Bloodsail Buccaneers.\n\nA cosa serve una vedetta che non ci vede? La coffa era la mia casa... senza i miei fanali sarei fortunato a poter strofinare la sentina.", enHash = "a48c4f62", vanilla = true },
        reward = { it = "Corpo di mille balene e balene di mille corpi! Hai trovato il mio bell'occhio! Vediamo se entra ancora.\n\n$N in vista! Perbacco, ci vedo!!", enHash = "4d762956", vanilla = true },
    },
    [577] = {
        title = { it = "Montaggio richiesto", enHash = "d1d3746d", vanilla = true },
        text = { it = "Be', ho messo a punto la forma di base degli stivali, e stanno venendo bene, ma le pelli che mi hai portato non basteranno per gli strati interni.\n\n\"Cosa facciamo, Drizzlik?\" È senz'altro la domanda che hai sulle labbra, e be', che fortuna che tu stia parlando con Drizzlik, perché ora ti dirà lui cosa faremo!\n\nGli strati interni non si vedranno mai davvero, quindi prenderemo delle pelli più spesse ed economiche dai coccodrilli intorno al Lake Nazferiti per imbottire gli stivali.", enHash = "4f463913", vanilla = true },
        objectives = { it = "Porta 5 Snapjaw Crocolisk Skin a Drizzlik, a Booty Bay.", enHash = "e0b450cb", vanilla = true },
        progress = { it = "Stivali di cuoio Excelsior di Drizzlik, lavorazione finissima, stivali al cento per cento in pelle di crocolisk d'acqua salata di alta qualità. Non ce n'è di migliori!\n\nDifficile battere una descrizione così entusiasta, vero?\n\nTranne, forse, se hai quelle pelli per me?", enHash = "80973488", vanilla = true },
        reward = { it = "I miei stivali... sono come le salsicce, $N. Bell'aspetto, ottimo sapore. Ti dico che sono pieni solo degli ingredienti e delle carni migliori, e tu li mangi, e ti piacciono.\n\nÈ più sicuro, e più piacevole, se ti fidi di me e non chiedi troppo nei dettagli cosa c'è davvero dentro.", enHash = "e3e73b7d", vanilla = true },
    },
    [578] = {
        title = { it = "La Stone of the Tides", enHash = "0da06def", vanilla = true },
        text = { it = "Se sull'isola ci sono davvero un mago goblin e dei Water Elemental, potrebbe significare che la Stone of the Tides può essere mia!\n\nVoglio che tu trovi quest'isola infestata... e scopra cosa sta succedendo. Ah, e se per caso vuoi saperne di più sulla Stone of the Tides, porta questo biglietto alla Stormwind Library: dovrebbero riuscire a trovarti una copia del libro in cui ho letto per la prima volta la leggenda.\n\nPossibile che Gazban abbia davvero scoperto la pietra...?", enHash = "4d2ae419", vanilla = true },
        objectives = { it = "Trova l'isola infestata per Baron Revilgaz, a Booty Bay.", enHash = "6546517d", vanilla = true },
        progress = { it = "I troll possedevano davvero oggetti magici straordinari, $N. E ora, forse, ho l'occasione di aggiungerne uno alla mia vasta collezione. Hai avuto fortuna a trovare l'origine della voce?", enHash = "88885440", vanilla = true },
        reward = { it = "Allora le storie erano vere! Incredibile!\n\nPerò dovremo trovare un modo per vincere la maledizione della Stone of the Tides, se vogliamo recuperarla. La maledizione è una faccenda magica: ci servirà uno di quei maghi per aiutarci.", enHash = "45939ac5", vanilla = true },
    },
    [579] = {
        title = { it = "Stormwind Library", enHash = "18d0cc0c", vanilla = true },
        progress = { it = "King Anduin dà grande importanza al sapere, e per questo ha stanziato fondi per mettere a disposizione del pubblico copie di vari tomi e scritti. È semplicissimo: tu mi porti una library scrip e io ti do una copia di uno dei libri disponibili.", enHash = "f57b0d81", vanilla = true },
        reward = { it = "Ti interessa qualcuno di questi titoli, $N?", enHash = "cc4e0bd0", vanilla = true },
    },
    [580] = {
        title = { it = "Il grog perduto di Whiskey Slim", enHash = "3b236f24", vanilla = true },
        text = { it = "Stavamo brindando a più non posso al largo delle Overlook Cliffs, con le vecchie Hinterlands appena in lontananza. Pensavo che il mare ci avrebbe inghiottiti tutti interi.\n\nIl vecchio Slim sa tutto sul coraggio in bottiglia! Il capitano aveva una cassa di Pupellyverbos Port che avevamo requisito a un corsaro diretto a Stormwind.\n\nCosì, quando è arrivata quella tempesta al largo delle Hinterlands, ho fatto irruzione nel grog. Un'onda grossa ci ha colpiti e ha buttato quelle bottiglie fuori bordo. Il capitano mi farà assaggiare il gatto a nove code, se non mi aiuti a riprenderle!", enHash = "beac4045", vanilla = true },
        objectives = { it = "Whiskey Slim, a Booty Bay, vuole che tu gli porti le bottiglie di Pupellyverbos Port che ha perso.", enHash = "31898a97", vanilla = true },
        progress = { it = "Che mi venga un colpo! Sto quasi finendo l'alcol! Il capitano leverà l'ancora e il vecchio Slim resterà a secco come il Tanaris Desert. E quando scoprirà che manca il suo Pupellyverbos Port... accidenti!", enHash = "d3ccc52c", vanilla = true },
        reward = { it = "Corpo di mille balene! Hai trovato il grog del capitano!\n\nTi devo un grosso favore, $Gamico:amica;.\n\nPare che fuori si stia preparando una tempesta. Forse mi terrò al caldo con una di queste bottiglie mentre aspettiamo che passi...", enHash = "9cdc8b0f", vanilla = true },
    },
    [581] = {
        title = { it = "Alla ricerca di Yenniku", enHash = "c06d6ce3", vanilla = true },
        text = { it = "Una sventura incombe. Una sventura sul figlio più giovane del mio capo, Yenniku. Come vuole un'usanza del nostro popolo, fu affidato ai troll Gurubashi di Zul'Gurub, ma dopo che la mia tribù, la tribù Darkspear, se ne andò con l'orco Thrall, il povero Yenniku fu perduto per noi. Sono stato mandato dalla lontana Orgrimmar, di nuovo a Stranglethorn, a cercare il figlio del mio capo.\n\nE credo che sia nelle mani della tribù Bloodscalp.\n\nSe vuoi aiutarmi, dai la caccia ai Bloodscalp. Puoi trovarli a nord. Raccogli le loro zanne e torna da me.", enHash = "120f3f8d", vanilla = true },
        objectives = { it = "Porta 9 Bloodscalp Tusk a Nimboya, al Grom'gol Base Camp.", enHash = "c9d95dc4", vanilla = true },
        progress = { it = "$C. Mostrami che hai fatto preda della tribù Bloodscalp.\n\nMostrami i tuoi trofei.", enHash = "e29308e7", vanilla = true },
        reward = { it = "Sono buone zanne, $N. Dimostri di avere la forza per dare la caccia ai Bloodscalp.\n\nE questo è un bene, perché non hai ancora finito di cacciarli.", enHash = "fd8a5e58", vanilla = true },
    },
    [582] = {
        title = { it = "A caccia di teste", enHash = "eb39558f", vanilla = true },
        text = { it = "Dobbiamo scoprire se Yenniku è morto.\n\nUccidi i Bloodscalp Headhunter e prendi le loro Shrunken Head. Devi raccogliere molte, molte teste, e io le esaminerò per assicurarmi che tra queste non ci sia quella di Yenniku.\n\nE se Yenniku è stato ucciso dai Bloodscalp, allora che una maledizione di 600 anni si abbatta sullo spirito del loro capo, Gan'zulah!\n\nVa', $N. Troverai molti Headhunter presso le rovine di Zuuldaia e Zul'Kunda, lungo la costa a nord.", enHash = "87d74a34", vanilla = true },
        objectives = { it = "Porta 20 Shrunken Head a Nimboya, al Grom'gol Base Camp.", enHash = "b3f62e7f", vanilla = true },
        progress = { it = "$N. Temo per il figlio del nostro capo. Hai le Shrunken Head, così che io possa esaminarle?", enHash = "138c7234", vanilla = true },
        reward = { it = "Grazie, $N. Esaminerò queste teste per assicurarmi che il povero Yenniku sia stato risparmiato dall'ascia del cacciatore di teste.", enHash = "a36d567d", vanilla = true },
    },
    [583] = {
        title = { it = "Benvenuti nella giungla", enHash = "0180b1d3", vanilla = true },
        text = { it = "$GBenvenuto:Benvenuta; a Stranglethorn!\n\nForse non lo sai, ma quel nano laggiù è l'unico e inimitabile Hemet Nesingwary, famoso eroe di guerra dell'Alleanza e maestro della caccia grossa. Non è tipo da accogliere estranei nel suo accampamento, ma dall'aspetto si direbbe che tu ne abbia viste parecchie, $C.\n\nEssendo anche lui un veterano di molte battaglie, Master Nesingwary ha un debole per i compagni eroi.\n\nVa' a parlargli. Forse può darti qualche consiglio di caccia.", enHash = "5bea0614", vanilla = true },
        objectives = { it = "Parla con Hemet Nesingwary.", enHash = "a3c43f0a", vanilla = true },
        reward = { it = "Proprio un piacere fare la tua conoscenza, $N. Era da un po' che non vedevo $Gun:una; $C da queste parti.\n\nMi sono unito a questa spedizione per un solo scopo: cacciare una bestia grande e sfuggente. Visto che sei una specie di $Geroe:eroina;, sono disposto a farti partecipare alla caccia, ma prima devi dimostrare quanto vali.\n\nTi insegnerò l'arte di uccidere i raptor. Ajeck ti addestrerà nella caccia alla tigre. E Sir Erlgadin è un maestro nel seguire le tracce delle pantere.\n\nDimostra la tua abilità e ti farò partecipare alla grande caccia.", enHash = "565b3a58", vanilla = true },
    },
    [584] = {
        title = { it = "Le teste del clan Bloodscalp", enHash = "115935ee", vanilla = true },
        text = { it = "Yenniku non era tra le teste, e ne ringrazio il Grande Serpente. Ma non siamo più vicini a trovarlo.\n\nDobbiamo conoscere la verità, e temo che la conoscano solo il capo dei Bloodscalp e il suo stregone. Sono nemici della tribù Darkspear e non parleranno di loro spontanea volontà, quindi dovremo strappare la verità dalle loro labbra morte!\n\nPortami le teste di Gan'zulah e di Nezzliok the Dire e mettile in questo calderone.\n\nSi trovano nel cuore di Zul'Kunda. Porta le loro teste... poi li faremo parlare.", enHash = "dc377ac6", vanilla = true },
        objectives = { it = "Porta Gan'zulah's Head e Nezzliok's Head al Bubbling Cauldron, al Grom'gol Base Camp.", enHash = "33342bef", vanilla = true },
        progress = { it = "Il brodo verdastro nel calderone ribolle.", enHash = "cad494e4", vanilla = true },
        reward = { it = "Metti le teste di Gan'zulah e di Nezzliok nel calderone...", enHash = "c2f488e1", vanilla = true },
    },
    [585] = {
        title = { it = "A colloquio con Nezzliok", enHash = "6d342c9a", vanilla = true },
        text = { it = "<La testa di Nezzliok parla.>\n\nÈ vero. So dove è stato portato il figlio dei Darkspear. Mi hai sconfitto e hai incatenato il mio spirito, ma non dirò nulla senza un'offerta che mi plachi!\n\nI Bloodscalp sono in guerra con gli Skullsplitter. Per guadagnarti il mio favore, ruba agli Skullsplitter 3 dei loro teschi trofeo e mettili qui con noi, così che il mio spirito abbia degli schiavi nel Nether. Un teschio deve venire dal loro mucchio di trofei a Balia'mah, un altro da Ziata'jai e l'ultimo da Zul'Mamwe.", enHash = "690d3c22", vanilla = true },
        objectives = { it = "Porta un Balia'mah Trophy, un Ziata'jai Trophy e un Zul'Mamwe Trophy al Bubbling Cauldron, al Grom'gol Base Camp.", enHash = "8c4f759a", vanilla = true },
        progress = { it = "Attendo i teschi...", enHash = "e126e188", vanilla = true },
        reward = { it = "Sì. Questi mi serviranno bene. Quando il mio spirito sarà liberato, entrerò nel Nether con tre ottimi servitori!\n\nSei $Gun:una; $R che fa onore al suo clan, e hai saputo placarmi.", enHash = "ac8dfc69", vanilla = true },
    },
    [586] = {
        title = { it = "A colloquio con Gan'zulah", enHash = "844b58fb", vanilla = true },
        text = { it = "<La testa di Gan'zulah parla.>\n\nTi maledico! E maledico i tuoi antenati!\n\nSolo il sangue e la vendetta possono placare la mia rabbia, quindi se è questo che desideri, allora... fai così:\n\nGettati nel cuore degli Skullsplitter, a est. Uccidi i più feroci tra loro e, se sopravvivi... va' a infrangerti contro il loro capo, Ana'thek the Cruel. Ah! Portami la sua armatura in frantumi, se ci riesci!\n\nChe ti strappi gli arti e ti lasci a marcire, pasto per i necrofagi.", enHash = "d0112579", vanilla = true },
        objectives = { it = "Uccidi 8 Skullsplitter Hunter, 6 Skullsplitter Headhunter e 4 Skullsplitter Berserker.\n\nPorta la Broken Armor of Ana'thek al Bubbling Cauldron, al Grom'gol Base Camp.", enHash = "ccdc6d4f", vanilla = true },
        progress = { it = "Anche se la mia carne si stacca bollendo dal teschio, sento ancora l'odore della tua paura.\n\nAh! Non porterai mai a termine il mio compito...", enHash = "585e5ddd", vanilla = true },
        reward = { it = "Non voglio crederci, ma non posso negare ciò che hai fatto. E la mia rabbia si placa, ora che Ana'thek è stato sconfitto.\n\nLa tua potenza ti porterà a grandi imprese, $N. Ma un giorno... ti rivedrò nel Nether, e misureremo di nuovo le nostre forze.\n\nTi aspetterò.", enHash = "c56ee4c0", vanilla = true },
    },
    [587] = {
        title = { it = "Una presa di tabacco", enHash = "b4347dba", vanilla = true },
        text = { it = "Ah, la vita di mare. Non dirò che è la bella vita, ma è la mia vita.\n\nQuando arrivo in porto mi piace trovarmi una buona bottiglia di grog e del tabacco da fiuto di qualità. Brutte abitudini, ma cos'è un pirata senza i suoi vizi, giusto?\n\nQuindi puoi immaginare quanto ci sono rimasto male quando ho scoperto che l'erborista qui in città l'ha finito. Dice che il suo carico è stato dirottato da quei maledetti Bloodsail Raiders.\n\nScommetto che $Gun:una; $C $Gimpavido:impavida; come te potrebbe convincerli a dividere la merce, eh?", enHash = "03925608", vanilla = true },
        objectives = { it = "Deeg, a Booty Bay, vuole che tu gli porti 15 porzioni di Snuff.", enHash = "e38af881", vanilla = true },
        progress = { it = "Hai avuto fortuna con la merce, $Gcompagno:compagna;?", enHash = "26441734", vanilla = true },
        reward = { it = "Ottimo lavoro, $N! E proprio prima che io debba salpare! Non so come ringraziarti, $Gvecchio amico mio:vecchia amica mia;.", enHash = "d1ccdca1", vanilla = true },
    },
    [588] = {
        title = { it = "Il destino di Yenniku", enHash = "dbe8cb83", vanilla = true },
        text = { it = "<Nezzliok parla.>\n\nHai placato me e il mio capo, quindi ti dirò ciò che cerchi di scoprire...\n\nIl giovane Yenniku è perduto per il suo clan.\n\nÈ stato preso dallo stregone Zanzil the Outcast. Ora Zanzil lo controlla, corpo e anima, e solo la magia più potente potrebbe liberarlo.\n\nUna magia che tu non possiedi, $C.\n\nForse i tuoi alleati Darkspear possono offrire una speranza di salvezza per Yenniku. Ma ne dubito.", enHash = "b3a20326", vanilla = true },
        objectives = { it = "Parla con Kin'weelay.", enHash = "a8e401de", vanilla = true },
        reward = { it = "Zanzil the Outcast?\n\nSe Yenniku è prigioniero di quel troll, uno stregone vile e potente, allora temo che resti solo una debole speranza. Debole. E minuscola come il più piccolo degli insetti.\n\nMa è pur sempre una speranza.", enHash = "854fd647", vanilla = true },
    },
    [589] = {
        title = { it = "I Singing Crystals", enHash = "dcbc3a59", vanilla = true },
        text = { it = "Le leggende parlano di un gioiello nascosto nel profondo del cuore di Stranglethorn. Lo chiamiamo il Mind's Eye, e ha grandi poteri. Se riuscirai a ottenere questo Eye, forse potremo usarlo per riportare il perduto Yenniku fuori dall'oscurità.\n\nConsulterò gli spiriti della giungla per trovare il Mind's Eye. Nel frattempo, tu entra nella Crystalvein Mine, a sud-est di qui, e raccogli dei Pulsing Blue Shard dagli Ironjaw Basilisk. I frammenti sono rari, ma ci servirà la loro magia per piegare il Mind's Eye alla nostra volontà.", enHash = "68057bf8", vanilla = true },
        objectives = { it = "Porta 3 Pulsing Blue Shard a Kin'weelay, al Grom'gol Base Camp.", enHash = "d8b0ddbd", vanilla = true },
        progress = { it = "Hai i frammenti, $N? Mi servono per il mio rituale finale, quando avremo il Mind's Eye.", enHash = "042bf10a", vanilla = true },
        reward = { it = "Hai fatto bene, $N. Questi frammenti sono ben formati. Già li sento cantare per me.\n\nE mentre eri via, ho parlato con gli spiriti della giungla. So dove si trova il Mind's Eye...\n\n...E chi lo custodisce.", enHash = "57bcd09b", vanilla = true },
    },
    [590] = {
        title = { it = "L'affare di un ladro", enHash = "cecc1842", vanilla = true },
        text = { it = "Cosa?\n\nCosa?!\n\nVuoi dei soldi? Non ti devo neanche un soldo.\n\nLettera? Quale lettera? Oh, allora vuoi fare a botte? E va bene, $Gamico:amica;... facciamolo! Figurati se ti devo dei soldi...", enHash = "36aefc78", vanilla = true },
        objectives = { it = "Sconfiggi Calvin Montague a Deathknell.", enHash = "21e90841", vanilla = true },
        reward = { it = "Incredibile! Che abilità!\n\nPensavo che fossi una preda facile, $N. Mi hai conciato per bene, eh.\n\nEcco le monete che ti avevo promesso... non quante avevo detto, ma è colpa del fatto che ti avevo mentito fin dall'inizio.", enHash = "54cc777e", vanilla = true },
    },
    [591] = {
        title = { it = "Il Mind's Eye", enHash = "4c5f5b1e", vanilla = true },
        text = { it = "Il Mind's Eye è nelle mani di un mago ogre, a est di qui, nel profondo del tumulo degli ogre Mosh'Ogg. Si chiama Mai'Zoth. Lo conosco da quando i Darkspear vivevano a Stranglethorn — è crudele, e la sua magia è potente.\n\nE se ha il Mind's Eye, la sua magia sarà ancora più forte.\n\nDevi affrontare Mai'Zoth e strappargli il Mind's Eye. È un compito pericoloso, ma è l'unica speranza che abbiamo di salvare Yenniku.", enHash = "8743c284", vanilla = true },
        objectives = { it = "Porta il Mind's Eye a Kin'weelay, al Grom'gol Base Camp.", enHash = "91b35f67", vanilla = true },
        progress = { it = "Salute, $N. Gli spiriti cantano lodi al tuo coraggio, eppure non mi raccontano nulla della tua impresa contro Mai'Zoth.\n\nHai l'Eye?", enHash = "7bc4fe77", vanilla = true },
        reward = { it = "Hai recuperato l'occhio! La tua potenza è materia da leggenda, $N!\n\nE per prendere l'Eye devi aver sconfitto Mai'Zoth e averlo mandato nel Nether. Ecco perché prima gli spiriti non volevano nominarlo.\n\nÈ un bene che abbia lasciato il mondo della carne e delle ossa, ma ora che si trova nel regno degli spiriti... temo che darà inizio a un nuovo dominio.\n\nMa questa è una preoccupazione per un'altra volta. Ora devo celebrare un rituale per piegare il Mind's Eye ai nostri bisogni...", enHash = "8e4dee1e", vanilla = true },
    },
    [592] = {
        title = { it = "Salvare Yenniku", enHash = "c2a09f21", vanilla = true },
        text = { it = "Ho trasformato il Mind's Eye in una Soul Gem. Il suo scopo è duplice: devi usarla per stordire Yenniku e, una volta stordito, posargliela sulla testa per imprigionarne l'anima.\n\nPoi porta la gemma a Nimboya.\n\nYenniku vive con Zanzil the Outcast, nelle Ruins of Aboraz, lungo la Crystal Shore, nel lontano Cape of Stranglethorn.", enHash = "6cfdbf4f", vanilla = true },
        objectives = { it = "Porta la Filled Soul Gem a Nimboya.", enHash = "b12fe6af", vanilla = true },
        progress = { it = "$N. Kin'weelay mi ha detto che sei $Gpartito:partita; per catturare Yenniku.\n\nÈ vero? L'hai preso?", enHash = "488de765", vanilla = true },
        reward = { it = "Ce l'hai fatta! Hai liberato Yenniku dalla volontà di Zanzil e hai portato a termine la missione che credevo così disperata.\n\nLa nostra tribù ricorderà il tuo nome nei canti, $N, e incideremo la tua storia nella pietra perché viva per sempre.", enHash = "4600004a", vanilla = true },
    },
    [593] = {
        title = { it = "Riempire la Soul Gem", enHash = "b6de1572", vanilla = true },
        progress = { it = "Yenniku è in piedi davanti a te, stordito, con la mente altrove...", enHash = "f8ed5f88", vanilla = true },
        reward = { it = "Posi la Soul Gem sulla sua fronte. Rabbrividisce mentre la sua anima viene risucchiata, lasciandosi dietro il corpo, un guscio vuoto senza mente.", enHash = "e3e48cea", vanilla = true },
    },
    [594] = {
        title = { it = "Messaggio in bottiglia", enHash = "e4c5a867", vanilla = true },
        text = { it = "Il biglietto dice, con una calligrafia piuttosto buona:\n\nA chiunque possa aiutarmi:\n\nti prego, ho un disperato bisogno di aiuto. Un grande Skymane mi tiene prigioniera su un'isola dei South Seas.\n\nLe stelle, di notte, mi sono sconosciute e nascoste dagli alberi della giungla, ma nei giorni più limpidi vedo la Wild Shore a nord-ovest, e quelle che sembrano grandi navi a vela a sud-ovest.\n\nTi supplico, $Gmio salvatore:mia salvatrice;, ti prego, aiutami.", enHash = "0d44ae0e", vanilla = true },
        objectives = { it = "Trova chi ha scritto il messaggio in bottiglia.", enHash = "39f4d460", vanilla = true },
        reward = { it = "Sei $Gvenuto:venuta; a liberarmi?", enHash = "9a5a4075", vanilla = true },
    },
    [595] = {
        title = { it = "I Bloodsail Buccaneers", enHash = "f2996ce5", vanilla = true },
        text = { it = "Hai proprio voglia di lavorare, $Gcompagno:compagna;. Non so perché $Gun:una; $C $R di terraferma voglia aiutare i Blackwater Raiders, ma non ti manderò via.\n\nLa nostra nave è appena attraccata qui a Booty Bay, e si dice che i nostri rivali, quei maledetti, sporchi Bloodsail Buccaneers, siano stati avvistati in tutta la Stranglethorn meridionale.\n\nI ragazzi sono tutti troppo presi dal grog e dalle donne! Mi serve un esploratore.\n\nControlla l'insenatura appena a nord di Booty Bay, lungo la Savage Coast, e vedi cosa trovi.", enHash = "149fe3a1", vanilla = true },
        objectives = { it = "First Mate Crazz vuole che tu controlli l'insenatura a nord di Booty Bay.", enHash = "6e39e18b", vanilla = true },
        reward = { it = "Sopra il barile trovi una mappa con un testo scritto in fretta, insieme a qualche moneta.", enHash = "9bb50956", vanilla = true },
    },
    [596] = {
        title = { it = "Bloody Bone Necklaces", enHash = "a921cfe2", vanilla = true },
        text = { it = "Sono stato mandato a Grom'gol per aiutare Nimboya nella sua missione, ma... anch'io ho le mie ragioni per essere qui.\n\nLa tribù Bloodscalp è nemica della nostra tribù. Raccogliere trofei dei nostri nemici ci dà potere su di loro. Puoi aiutare la nostra tribù dando la caccia ai nostri nemici.\n\nVivono a nord. Uccidi i troll Bloodscalp e prendi le loro Bloody Bone Necklace. Raccoglile in gran numero, e la tua ricompensa sarà grande.", enHash = "4b926045", vanilla = true },
        objectives = { it = "Porta 25 Bloody Bone Necklace a Kin'weelay, al Grom'gol Base Camp.", enHash = "b8ceb620", vanilla = true },
        progress = { it = "Un giorno i Bloodscalp saranno schiacciati dai Darkspear! Hai le collane del nostro nemico condannato?", enHash = "e20ff519", vanilla = true },
        reward = { it = "Ah, molto bene. Le farò bollire, le prosciugherò, e gli spiriti dei loro proprietari si indeboliranno mentre riduco in poltiglia le loro collane!\n\nEcco, $N. Questo ripagherà il mio debito con te.", enHash = "f60000ad", vanilla = true },
    },
    [597] = {
        title = { it = "I Bloodsail Buccaneers", enHash = "f2996ce5", vanilla = true },
        text = { it = "La mappa mostra Booty Bay con una \"X\" rossa disegnata esattamente nel punto in cui ti trovi.\n\nIl testo scarabocchiato dice:\n\n\"Voi uomini dovete allestire un accampamento in questo punto e restare in silenzio. Aspettate il segnale dal posto di comando meridionale prima di attaccare. Se qualcuno si avvicina, uccidetelo.\"", enHash = "ab403b65", vanilla = true },
        objectives = { it = "Riferisci le tue scoperte a First Mate Crazz, a Booty Bay.", enHash = "0b11ed7f", vanilla = true },
        reward = { it = "Certo che mi ricordo di te, $C. Di ritorno dalla ricognizione, vedo...", enHash = "eaf0564c", vanilla = true },
    },
    [598] = {
        title = { it = "Split Bone Necklace", enHash = "9b982ccc", vanilla = true },
        text = { it = "Ora che hai raccolto i trofei dei Bloodscalp, ho un altro compito per te. La tribù di troll Skullsplitter vive a sud-est, e da anni siamo in guerra con loro. Anche se i Darkspear non vivono più a Stranglethorn, siamo ancora legati al nostro conflitto con gli Skullsplitter.\n\nQuindi, dai loro la caccia. Raccogli le loro Split Bone Necklace e torna da me. Aiutaci nella nostra guerra, e ti guadagnerai l'amicizia dei Darkspear.", enHash = "c2851012", vanilla = true },
        objectives = { it = "Porta 25 Split Bone Necklace a Kin'weelay, al Grom'gol Base Camp.", enHash = "d929f3bd", vanilla = true },
        progress = { it = "Gli Skullsplitter malediranno il giorno in cui ci hanno portato alla guerra! Hai completato il tuo compito?", enHash = "66d2644c", vanilla = true },
        reward = { it = "Grande è la tua forza, se hai ottenuto queste collane, $N. Gli Skullsplitter cadono davanti a te come giovani alberelli schiacciati a terra da un basilisco!\n\nLe tue imprese sono una benedizione per noi.", enHash = "53270165", vanilla = true },
    },
    [599] = {
        title = { it = "I Bloodsail Buccaneers", enHash = "f2996ce5", vanilla = true },
        text = { it = "Corpo di mille balene! Quindi i Bloodsail Buccaneers stanno preparando una specie di attacco a Booty Bay? Ma che faccia tosta, quelle canaglie. Booty Bay sarà sempre in mano ai Blackwater Raiders!\n\nÈ una faccenda più grossa di quanto pensassi. Riferisci subito quello che hai scoperto a Fleet Master Seahorn! Il vecchio lupo di mare è da qualche parte in città...", enHash = "b76c4347", vanilla = true },
        objectives = { it = "Riferisci a Fleet Master Seahorn dell'attacco che i Bloodsail stanno preparando.", enHash = "2c0849cf", vanilla = true },
        reward = { it = "I Bloodsail Buccaneers attaccano Booty Bay? Tanto varrebbe che si buttassero giù dalle Overlook Cliffs. Comunque, portandomi questa informazione hai reso un grande servizio alla mia flotta di bucanieri. I Blackwater Raiders ti ringraziano.", enHash = "20c3aa30", vanilla = true },
    },
    [600] = {
        title = { it = "L'estrazione mineraria della Venture Company", enHash = "98b95c80", vanilla = true },
        text = { it = "La Venture Company ha una serie di attività in tutta Stranglethorn che impediscono ai goblin gran lavoratori, come me, di guadagnare oro onestamente! Ti prego, devi aiutarmi!\n\nLa Venture Company sta scavando vicino alla Crystalvein Mine, a nord. Non riescono a entrare nella miniera per via di tutti quei basilischi, ma riescono comunque a estrarre Singing Crystals dalle colline intorno.\n\nPrendi i loro cristalli e fagli vedere che la giungla non è roba loro.\n\nE... ehm... portami quei cristalli come prova!", enHash = "7ff3ea7e", vanilla = true },
        objectives = { it = "Porta 10 Singing Blue Crystal a Crank Fizzlebub, a Booty Bay.", enHash = "833326e2", vanilla = true },
        progress = { it = "Hai quei cristalli? Mi servono!\n\nCioè... ho bisogno di sapere che la malvagia Venture Company sta perdendo terreno a Stranglethorn. Perché, sai, noi gente onesta dobbiamo pur campare!", enHash = "df78b155", vanilla = true },
        reward = { it = "Ottimo! Magnifico! Posso ricavarci un bel gruzzolo!\n\nQuella Venture Company ha proprio scelto la giungla sbagliata in cui scavare, eh? Staremmo tutti meglio se se ne andassero da qui.\n\nGrazie, $N. Oggi hai compiuto una buona azione.", enHash = "f76a6cae", vanilla = true },
    },
    [601] = {
        title = { it = "I Water Elemental", enHash = "852877d5", vanilla = true },
        text = { it = "I Water Elemental sono stati senza dubbio evocati da Gazban, il mago goblin che si dice abbia scoperto la Stone of the Tides. Come forse sai, la Stone of the Tides maledice chi la porta, facendolo svanire e ricomparire...\n\nForse possiamo trovare un modo per contrastare la maledizione. Possiamo far analizzare a un mago di Dalaran il residuo magico di uno dei Water Elemental Bracers. Ho bisogno che torni sull'isola e recuperi qualche esemplare.", enHash = "dceac8e0", vanilla = true },
        objectives = { it = "Procura 6 Water Elemental Bracers per Baron Revilgaz, a Booty Bay.", enHash = "167c41a9", vanilla = true },
        progress = { it = "Hai avuto fortuna, $N?", enHash = "6904992e", vanilla = true },
        reward = { it = "Mmh, non ho l'occhio per esaminare questi bracciali e capire se qualcuno servirà, ma sono sicuro che almeno uno potrà aiutarci. Portali a Dalaran e falli esaminare da un mago.\n\nDopotutto, non posso certo lasciare Booty Bay solo per chiacchierare con quei noiosi vecchi maghi.\n\nNon che io sia preoccupato che qualcuno provi a farsi largo a gomitate per diventare il nuovo barone. Nessuno si mette contro Revilgaz e vive per raccontarlo.", enHash = "031f1488", vanilla = true },
    },
    [602] = {
        title = { it = "Analisi magica", enHash = "8a0cff64", vanilla = true },
        text = { it = "A quanto ho sentito, i maghi di Dalaran sono impegnati a ricostruire la loro città distrutta; sono sicuro che ne troverai uno disposto a dedicare un po' di tempo a esaminare i bracciali. Se c'è una cosa che so dei maghi, è che non resistono a un enigma magico.\n\nPrendi la Bag of Water Elemental Bracers e vedi se riescono a fare luce sulla maledizione della pietra. Cerca in particolare Archmage Ansirem Runeweaver. Ho già avuto a che fare con lui, e la sua conoscenza è vasta.", enHash = "7a759b8c", vanilla = true },
        objectives = { it = "Porta la Bag of Water Elemental Bracers ad Archmage Ansirem Runeweaver, a Dalaran.", enHash = "9ee5b50d", vanilla = true },
        progress = { it = "Se non ti dispiace, in questo momento sono piuttosto occupato.", enHash = "3e4c4ed4", vanilla = true },
        reward = { it = "La Stone of the Tides? Molto interessante. Forse ti sorprenderà sapere che, diversi anni fa, ho scritto un tomo sulle leggende del Gurubashi Empire. Della pietra so parecchio.\n\nAlmeno uno di questi bracciali sembra avere un residuo magico che posso analizzare.\n\nVediamo cosa riesco a vedere...", enHash = "e1e91121", vanilla = true },
    },
    [603] = {
        title = { it = "La chiave di Ansirem", enHash = "941f4ea2", vanilla = true },
        text = { it = "Il mago che possiede la pietra ne amplifica il potere attraverso una specie di punto focale... un altare di qualche tipo. Dovresti riuscire a spezzarlo sovraccaricandolo.\n\nGuarda caso, conosco proprio la cosa che fa al caso nostro: un antico pugnale, un'altra reliquia troll. C'è solo un... piccolo problema.\n\nVedi, ho trovato il pugnale durante le mie ricerche a Stranglethorn, ma l'ho dato a mia figlia Catelyn, una testa calda, che è scappata a Booty Bay per fare la pirata.", enHash = "602bfb8c", vanilla = true },
        objectives = { it = "Parla con Catelyn, a Booty Bay.", enHash = "de128229", vanilla = true },
        reward = { it = "Il mio pugnale? Cosa sei, $Gun comico:una comica;?\n\nCosa? Vuoi solo sentirmi ripetere come sono passata dall'essere la miglior combattente di coltello di Booty Bay allo zimbello di tutta la pirateria?\n\nHo perso un duello al coltello con uno dei Bloodsail Buccaneers (una manica di gran bastardi, quelli!) e lui si è preso la mia lama come bottino.\n\nNon è che una combattente di coltello possa tirare avanti solo con gli insulti e la lingua tagliente...", enHash = "a06cb319", vanilla = true },
    },
    [604] = {
        title = { it = "I Bloodsail Buccaneers", enHash = "f2996ce5", vanilla = true },
        text = { it = "Crazz parla molto bene della tua dedizione ai Blackwater Raiders. Ti affiderò una missione della massima importanza per la flotta.\n\nInfiltrati nel cosiddetto posto di comando meridionale che i Bloodsail Buccaneers hanno allestito sulla Wild Shore. Fai irruzione nell'accampamento. Portami le loro carte nautiche insieme ai loro ordini scritti. Vedremo esattamente cosa stanno tramando quei farabutti.", enHash = "206a58ec", vanilla = true },
        objectives = { it = "Fleet Master Seahorn, a Booty Bay, vuole che tu uccida 10 Bloodsail Swashbuckler e riporti le Bloodsail Charts e i Bloodsail Orders.", enHash = "140dddc3", vanilla = true },
        progress = { it = "Ahoy, $N. Che notizie porti dall'accampamento dei Bloodsail a sud?", enHash = "ac56e9f0", vanilla = true },
        reward = { it = "Perfetto, $N. Ora che conosciamo il loro piano, è solo questione di tempo.\n\nE pensare che quegli sciocchi hanno gettato l'ancora proprio al largo del capo...", enHash = "6a83ffa3", vanilla = true },
    },
    [605] = {
        title = { it = "Frammenti blu cantanti", enHash = "77d67d2e", vanilla = true },
        text = { it = "I Singing Crystals esistono solo a Stranglethorn, e per certa gente valgono parecchio. Io quei cristalli riesco a piazzarli, ma quella maledetta Venture Company rende difficile a un onesto imprenditore come me raccoglierne anche solo uno!\n\nVorrei assumerti.\n\nI basilischi di Stranglethorn mangiano il cristallo. È questo che dà loro la pelle indurita, e a volte se ne può ricavare cristallo di discreta qualità.\n\nPuoi prenderlo da qualsiasi basilisco, ma quelli meno cattivi stanno lungo le rive a sud di Zul'Kunda, a nord.", enHash = "1b3454cf", vanilla = true },
        objectives = { it = "Porta 10 Singing Crystal Shard a Crank Fizzlebub.", enHash = "4aa89010", vanilla = true },
        progress = { it = "Hai già quei frammenti? Ti darò una bella fetta dei profitti!", enHash = "54fa56fc", vanilla = true },
        reward = { it = "Aha! Questi andranno benissimo, $N. Sì, proprio benissimo!\n\nEcco la tua parte, e... è stato un piacere fare affari con te.", enHash = "ec8586ed", vanilla = true },
    },
    [606] = {
        title = { it = "Spaventare Shaky", enHash = "4a8003fb", vanilla = true },
        text = { it = "Se c'è una cosa che non sopporto, è la gente che non paga i debiti di gioco! E sono in tanti a dovermi dei soldi. Pensi di potermi aiutare a riscuotere?\n\nPer cominciare, c'è \"Shaky\" Phillipe, giù ai moli. Mi deve parecchio dopo la partita della settimana scorsa e voglio quello che mi spetta! Ma per averlo dovremo spaventarlo.\n\nEsci dalla città e dai la caccia agli Elder Mistvale Gorilla. Trova una bella scelta di frattaglie, poi portale a Shaky. Non fargli capire che vengono da un animale: lascia che pensi al peggio.", enHash = "b0246b72", vanilla = true },
        objectives = { it = "Porta 5 Mistvale Giblets a \"Shaky\" Phillipe, a Booty Bay.", enHash = "9498cc82", vanilla = true },
        progress = { it = "Ehi! Non mi piace come mi guardi, $Gsignore:signora;.", enHash = { "2e1917b6", "36523dd6" }, vanilla = true },
        reward = { it = "Ack! Dove le hai prese? No, non dirmelo. Non voglio saperlo!\n\nChi ti manda? Sea Wolf?", enHash = "8f150777", vanilla = true },
    },
    [607] = {
        title = { it = "Torna da MacKinley", enHash = "ed5a14ea", vanilla = true },
        text = { it = "Ecco, prendi questo sacchetto e dallo a Sea Wolf. E digli che avevo intenzione di ripagarlo! Lo giuro!\n\nMi sono solo ubriacato un po' e ho perso la strada, e... sai com'è. Capirà — non c'è bisogno di passare alle maniere forti!", enHash = "cb4be9f2", vanilla = true },
        objectives = { it = "Porta Shaky's Payment a \"Sea Wolf\" MacKinley.", enHash = "a9a4139f", vanilla = true },
        progress = { it = "Ecco, ecco, $N. Hai preso Shaky's Payment?", enHash = "2e6e2e0f", vanilla = true },
        reward = { it = "Eh eh, ben fatto! E quando hai mostrato a Shaky quelle frattaglie, quanto ha tremato?\n\nAh! È così facile da leggere che quando gioco a carte con lui non posso fare a meno di vincere!\n\nGrazie per l'aiuto, $N. Ora tocca a te ricevere la paga...", enHash = "18456f9b", vanilla = true },
    },
    [608] = {
        title = { it = "I Bloodsail Buccaneers", enHash = "f2996ce5", vanilla = true },
        text = { it = "Maledetta la sfacciataggine di Firallon! Non saprebbe guidare una barchetta attraverso il Crystal Lake, figurarsi un'intera flotta contro di noi.\n\nI Bloodsail Buccaneers pagheranno per la loro imprudenza. Ora che conosciamo il loro piano d'attacco, possiamo contrattaccare prima che capiscano cosa li ha colpiti.\n\nMa perché mandare l'intera flotta a fare il lavoro di un solo gruppo di coraggiosi avventurieri? $N, porta alcuni dei tuoi compagni più abili al punto di sbarco di Firallon e assassina i capi dei Bloodsail. La loro flotta affonderà poco dopo...", enHash = "95640039", vanilla = true },
        objectives = { it = "Fleet Master Seahorn, a Booty Bay, vuole che tu uccida Captain Stillwater, Captain Keelhaul e Fleet Master Firallon.", enHash = "a363f666", vanilla = true },
        progress = { it = "Qual è il problema, $N? Dobbiamo attaccare prima che lo facciano i Bloodsail Buccaneers!", enHash = "cf071e90", vanilla = true },
        reward = { it = "Ah, che grande giorno per i Blackwater Raiders! Tre urrà per te, $N!", enHash = "ae9a54e1", vanilla = true },
    },
    [609] = {
        title = { it = "Debiti voodoo", enHash = "1a13e131", vanilla = true },
        text = { it = "La mia lista si sta accorciando, ma c'è ancora gente che mi deve dei soldi.\n\nPoi ci sono Maury \"Club Foot\" Wilkins, Jon-Jon the Crow e Chucky \"Ten Thumbs\".\n\nI debiti di questi cani rognosi sono scaduti da mesi, e pensavo che avessero lasciato la città per non pagare! Poi ho sentito che sono maledetti e stregati e che ora vagano tra le rovine nella giungla. Ma non m'importa che fine abbiano fatto — voglio quello che è mio!\n\nSono nelle Ruins of Aboraz e nelle Ruins of Jubuwal, a nord-est di qui. Trovali e riscuoti.", enHash = "9d6afcfb", vanilla = true },
        objectives = { it = "Porta Maury's Clubbed Foot, Jon-Jon's Golden Spyglass e Chucky's Huge Ring a \"Sea Wolf\" MacKinley, a Booty Bay.", enHash = "d78e338f", vanilla = true },
        progress = { it = "$N, hai trovato quei tre cani? Hai riscosso i loro oggetti di valore?", enHash = "00a73de4", vanilla = true },
        reward = { it = "Ottimo! Posso ricavarci un buon prezzo, soprattutto da quello che c'è dentro il piede di Maury! Grazie mille, $N!\n\nSpero che quei tre abbiano imparato la lezione: non scommettere mai qualcosa che non puoi permetterti di perdere.\n\nE forse per loro è troppo tardi, ma... dovrebbero scegliere con più attenzione con chi giocare d'azzardo.", enHash = "05811df1", vanilla = true },
    },
    [610] = {
        title = { it = "\"Pretty Boy\" Duncan", enHash = "1668bb35", vanilla = true },
        text = { it = "Ti ha mandato mio PADRE? Pensavo che quel vecchio brontolone avesse già rinunciato a me.\n\nNon è davvero colpa sua se sono scappata, solo che non avrebbe dovuto aspettarsi che accettassi di vivere una vita noiosa, a leggere libri ammuffiti e a frequentare maghi grigi, rigidi e barbosi!\n\nSe ti serve il mio pugnale, dovrai riprenderlo a \"Pretty Boy\" Duncan, uno dei Bloodsail Buccaneers. Piantagli qualcosa tra le spalle e sono sicura che te lo darà.", enHash = "83945005", vanilla = true },
        objectives = { it = "Prendi Catelyn's Blade a \"Pretty Boy\" Duncan.", enHash = "16ca10a5", vanilla = true },
        progress = { it = "Non ero mai stata battuta prima, sai, $N? Certo, qualche taglio l'avevo preso, in un duello al coltello non si può evitare, ma lui mi ha colpita di lato alla testa e mi ha fatto perdere i sensi. Quando mi sono ripresa, la mia lama era sparita.\n\nPer quanto il mio soprannome possa far pensare il contrario, mi serve comunque un coltello per combattere, e per me deve essere quello.", enHash = "1a6bf4d8", vanilla = true },
        reward = { it = "Hai battuto Duncan? Allora non sei $Gcosì inesperto:così inesperta; come sembravi a prima vista.\n\nImmagino che questo voglia dire anche che non dovrei sfidarti a duello tanto presto!", enHash = "de4246b9", vanilla = true },
    },
    [611] = {
        title = { it = "La maledizione delle maree", enHash = "7b2ad6e2", vanilla = true },
        text = { it = "Quindi cerchi una specie di altare? Be', io non sono un'esperta di rovine troll come mio padre, ma ho sentito parlare di una città troll sommersa vicino a quell'isola che stai cercando. Forse dovresti provare lì.\n\nMi hai riportato il coltello, quindi immagino che tu possa prenderlo in prestito... ma quando hai finito lo rivoglio!", enHash = "aa877457", vanilla = true },
        objectives = { it = "Distruggi l'Altar of the Tides con Catelyn's Blade, uccidi Gazban e riporta la Stone of the Tides e Catelyn's Blade a Baron Revilgaz.", enHash = "7c84486c", vanilla = true },
        progress = { it = "Hai recuperato la Stone of the Tides per me, $N? Ho già fatto spazio e comprato un bel piedistallo per metterla in mostra.", enHash = "128e546d", vanilla = true },
        reward = { it = "Straordinario! La Stone of the Tides! Avrà un posto d'onore nella mia collezione di manufatti troll antichi. Hai visto come sembra quasi che una marea sia intrappolata nella sua superficie? Magnifico!", enHash = "5b0f997c", vanilla = true },
    },
    [613] = {
        title = { it = "Aprire il piede di Maury", enHash = "cbf113b2", vanilla = true },
        text = { it = "Maledizione! Quel mozzo di Maury ha messo un lucchetto al suo piede, e non riesco ad aprirlo! Il suo bottino è dentro il piede, ed è quello che mi deve!\n\nDobbiamo trovare la chiave per aprire il lucchetto. Si sapeva che Maury giocava d'azzardo con gli ogre Mosh'Ogg, nel loro tumulo a nord-est. E mi ha raccontato, quando era ancora vivo, che l'ultima volta che era andato al tumulo l'avevano cacciato via perché aveva vinto troppo. Forse gli ogre di laggiù hanno la sua chiave.\n\nMa se ce l'hanno, potresti dover ucciderne un bel po' per trovare quello giusto...", enHash = "0cd7d790", vanilla = true },
        objectives = { it = "Porta Maury's Key a \"Sea Wolf\" Mackinley, a Booty Bay.", enHash = "c429b00e", vanilla = true },
        progress = { it = "Ohilà, $N! Hai già trovato Maury's Key?", enHash = "3b1a8809", vanilla = true },
        reward = { it = "L'hai trovata! Grazie mille, $N. Mi sei $Gstato:stata; di grande aiuto!\n\nEcco qua — te lo sei $Gguadagnato:guadagnata;!", enHash = "22e54a6b", vanilla = true },
    },
    [614] = {
        title = { it = "Il forziere del capitano", enHash = "61960082", vanilla = true },
        text = { it = "Un tempo navigavo da qui fino a Ratchet, in Kalimdor. Ero un capitano di successo, con una reputazione impeccabile.\n\nFinché...\n\nQuei maledetti giganti marini mi hanno rovinato! Mi hanno distrutto la nave, ucciso l'equipaggio e mi hanno messo su una scialuppa diretta a Booty Bay. E uno dei giganti, Gorlash, mi ha rubato il mio forziere del capitano. Ha detto che lo voleva come tabacchiera. Che faccia tosta!\n\nHo sentito che Gorlash si aggira lungo la costa a est di qui. Trovalo e riportami il mio forziere! Fallo, e ti sarai $Gguadagnato:guadagnata; la gratitudine di un capitano.", enHash = "f9b80e7d", vanilla = true },
        objectives = { it = "Porta Smotts' Chest a Hecklebury Smotts, a Booty Bay.", enHash = "9e43fb2d", vanilla = true },
        progress = { it = "Ahoy, $N! Hai trovato Gorlash? Quel forziere era il mio preferito, e ha uno scomparto segreto dove tenevo i miei tesori più preziosi!", enHash = "cf114da8", vanilla = true },
        reward = { it = "L'hai trovato! Oh, che giorno felice, questo! Grazie, $N. Riavere il mio forziere spegne un po' del fuoco che ho dentro.\n\nMa la mia vendetta non è completa...", enHash = "f29aa488", vanilla = true },
    },
    [615] = {
        title = { it = "La sciabola del capitano", enHash = "6b16e118", vanilla = true },
        text = { it = "Dopo aver perso la mia prima nave per colpa di quei giganti, ne ho comprata un'altra. L'ho chiamata Smotts' Revenge, l'ho riempita di provviste e di marinai e sono partito alla ricerca di quei farabutti. Li ho trovati, ma... mi hanno battuto. Hanno distrutto la Smotts' Revenge, ucciso il mio secondo equipaggio e mi hanno messo su un'altra scialuppa.\n\nStavolta un altro dei giganti, Negolash, mi ha rubato la sciabola.\n\nAffronta Negolash e riportami la mia sciabola!\n\nParla con Sprogger. Era il mio cuoco sulla Smotts' Revenge, ed è sopravvissuto all'ultimo attacco. Può aiutarti a trovare il gigante.", enHash = "bbc1d5ce", vanilla = true },
        objectives = { it = "Parla con Sprogger.", enHash = "5d081e5b", vanilla = true },
        reward = { it = "Salve, salve, $N. Il capitano mi ha detto che vuoi dare la caccia a Negolash, eh?", enHash = "d4bb909b", vanilla = true },
    },
    [616] = {
        title = { it = "L'isola infestata", enHash = "275f1ab1", vanilla = true },
        text = { it = "Baron Revilgaz mi ha chiesto di tenere le orecchie aperte per le voci su cose strane e fuori posto a Booty Bay e a Stranglethorn. Di solito non do molto peso alle storie di fantasmi, ma alla taverna ho sentito dei marinai parlare di un'isola infestata al largo della costa. Dei Water Elemental e un fantasma goblin che delira, dicono.\n\nSe vai a parlare con Revilgaz, potresti riferirgli questa storia?", enHash = "6f81d32f", vanilla = true },
        objectives = { it = "Parla con Baron Revilgaz, a Booty Bay.", enHash = "73f8735c", vanilla = true },
        reward = { it = "Interessante. Tempo fa, mi pare di ricordare di aver letto un libro che suggeriva...\n\nAh, certo, era una leggenda troll. Se quello che riferisce Krazek è vero, forse presto potrò aggiungere la Stone of the Tides alla mia collezione di manufatti e reliquie antiche.", enHash = "7e4f0e1c", vanilla = true },
    },
    [617] = {
        title = { it = "Akiris a mazzi", enHash = "256946d7", vanilla = true },
        text = { it = "Cerchi lavoro, $N? Potrei averne un po', se te la senti di affrontare una piccola sfida.\n\nHo un amico, Groy, che fa soldi a palate vendendo quella che i naga chiamano Akiris Reed: è una specie di pregiata canna marina. Non so bene a cosa serva, ma paga bene per i mazzi di quella roba.\n\nPortami dieci steli di quella roba, e faremo affari. I naga sono stati visti l'ultima volta lungo la spiaggia a nord di qui.", enHash = "2ac8102b", vanilla = true },
        objectives = { it = "Porta 10 Akiris Reed a Privateer Bloads, a Booty Bay.", enHash = "c413fd36", vanilla = true },
        progress = { it = "Se non hai affari da fare con me, allora circola, $N.", enHash = "c93ebd1b", vanilla = true },
        reward = { it = "Ben fatto, $N. Dieci steli di Akiris Reed non erano poi una sfida così grande, eh? Senza offesa per i naga, ma ehi, tutti devono pur campare.", enHash = "2e425dbe", vanilla = true },
    },
    [618] = {
        title = { it = "Affrontare Negolash", enHash = "cb05d96f", vanilla = true },
        text = { it = "Negolash è un gigante affamato.\n\nQuando i giganti hanno distrutto la nostra nave, Negolash è andato dritto nella mia cucina. Non aveva fame di marinai come gli altri giganti. Negolash voleva il vino... e le mie Barbecued Buzzard Wing. Sono la mia specialità, e sono dovuto andare fino alle Badlands per la ricetta!\n\nSe vuoi attirare il gigante, procurati del vino e un mucchio di Buzzard Wing. Mettili nella nostra vecchia scialuppa, a sud-est di qui lungo la costa. Quando Negolash sentirà l'odore di tutto quel cibo, verrà di sicuro!", enHash = "ed08343a", vanilla = true },
        objectives = { it = "Porta 10 Barbecued Buzzard Wing e 5 bottiglie di Junglevine Wine a Captain Smotts' Lifeboat.\n\nUccidi Negolash e porta Smotts' Cutlass a Captain Smotts, a Stranglethorn.", enHash = "e49e5a13", vanilla = true },
        progress = { it = "Hai recuperato la mia sciabola, $N?", enHash = "7034fc52", vanilla = true },
        reward = { it = "Hai tolto la mia sciabola a Negolash! Non posso credere alla mia fortuna, $N! Incontrarti ha girato la mia sorte in meglio, puoi starne certo!\n\nGrazie! E se mai avrò una nuova nave e vorrai solcare i mari, sarai mio ospite d'onore.", enHash = "763a4a01", vanilla = true },
    },
    [619] = {
        title = { it = "Attirare Negolash", enHash = "83a5e22c", vanilla = true },
        progress = { it = "È una scialuppa di salvataggio abbandonata. Sulla fiancata, in vernice graffiata e sbiadita, sono dipinte le parole:\n\n\"Smotts' Revenge\"", enHash = "af025ea6", vanilla = true },
        reward = { it = "Ammucchi cibo e bevande sulla zattera...", enHash = "bb53e462", vanilla = true },
    },
    [620] = {
        title = { it = "La Monogrammed Sash", enHash = "7c4cdc80", vanilla = true },
        text = { it = "Questa elegante fascia ha le lettere \"HS\" ricamate lungo l'orlo.", enHash = "7abb05c5", vanilla = true },
        objectives = { it = "Riporta la Monogrammed Sash al suo proprietario.", enHash = "4e940268", vanilla = true },
        progress = { it = "Salve. Hai affari da trattare con me?", enHash = "747957af", vanilla = true },
        reward = { it = "Hai recuperato la mia fascia? Allora... devi aver ucciso Mok'rash, il gigante marino! Evviva!\n\nSono contento che quel lurido farabutto sia morto: Mok'rash era uno dei tre giganti marini che mi hanno distrutto le navi e ucciso l'equipaggio.\n\nTre volte.\n\nSei $Gun:una; $C di valore, $N.", enHash = "59724f09", vanilla = true },
    },
    [621] = {
        title = { it = "Il segreto di Zanzil", enHash = "56af754e", vanilla = true },
        text = { it = "Zanzil the Outcast vive con i suoi seguaci nelle Jubuwai e Aboraz Ruins, a nord-est di Booty Bay. È stato esiliato dalla sua tribù. Perché? Be'...\n\nZanzil conosce dei metodi per piegare la mente degli altri, e i suoi capi lo temono. Sui suoi seguaci usa una miscela di piante della giungla che ne sopprime la volontà e ne rafforza il corpo.\n\nLa sua miscela varrebbe molto per chi vuole controllare gli altri.\n\nPortami dei campioni della sua miscela, e troverò il modo di usarli.", enHash = "832ed3ba", vanilla = true },
        objectives = { it = "Porta 12 campioni di Zanzil's Mixture a Crank Fizzlebub, a Booty Bay.", enHash = "0e2955b2", vanilla = true },
        progress = { it = "Hai i campioni di Zanzil's Mixture??", enHash = "72446b13", vanilla = true },
        reward = { it = "Ah, molto bene! Ecco la tua paga.\n\nEd ecco un piccolo extra... per la tua discrezione.", enHash = "cc582494", vanilla = true },
    },
    [622] = {
        title = { it = "Torna da Corporal Kaleb", enHash = "141c6820", vanilla = true },
        text = { it = "Mentre eri via ho aggiustato la pentola che mi hai portato. Ci ho perfino aggiunto un fischietto a vapore in più, e guarda! C'è un nuovo trinciatore sul fondo che taglia anche le ossa delle gambe!\n\nSì, sì, la Krazek's Crock Pot soddisfa il cuoco al cento per cento! Sono sicuro che il suo proprietario sarà contento.", enHash = "49ca1987", vanilla = true },
        objectives = { it = "Porta Krazek's Fixed Pot a Corporal Kaleb, al Rebel Camp.", enHash = "5919d9ce", vanilla = true },
        progress = { it = "Salve, $N. Sei $Garrivato:arrivata; fino a Booty Bay? Il goblin Krazek ha aggiustato la mia pentola??", enHash = "c69577ad", vanilla = true },
        reward = { it = "È aggiustata! Fantastico, ora posso mettermi a preparare la cena! Grazie mille, $N.\n\nSpero che a Booty Bay sia andato tutto bene. Quel posto può diventare parecchio pericoloso, e... ho sentito dire che a volte i goblin trascinano i marinai ubriachi sulle loro navi di schiavi e li portano chissà dove... a fare chissà cosa...", enHash = "c10f1df2", vanilla = true },
    },
    [623] = {
        title = { it = "Akiris a mazzi", enHash = "256946d7", vanilla = true },
        text = { it = "$N, visto che sei qui: mentre eri via mi è arrivato un messaggio da Groy. Dice di essere soddisfatto dell'ultimo carico che gli è arrivato, e ha un cliente che ne vuole subito dell'altro.\n\nIo non andrò a Theramore prima di una settimana, ma se te la senti di fare il viaggio, non c'è motivo per cui tu non possa portargli la roba al posto mio.\n\nHai voglia di avventura? Lo sai dov'è il Dustwallow Marsh, vero? Però fa' attenzione: Theramore può essere pericolosa se sei della gente sbagliata.", enHash = "93d82832", vanilla = true },
        objectives = { it = "Porta un Bundle of Akiris Reeds a Privateer Groy, a Theramore.", enHash = "4aa3bdb4", vanilla = true },
        progress = { it = "Sì?", enHash = "06d87e6c", vanilla = true },
        reward = { it = "Cosa?! Ho cose molto migliori da fare che parlare con gente come te, $C. Fa' che ne valga la pena o levati di torno.\n\nEh? Ti manda Bloads, eh? Be', che mi hai portato?\n\n<Privateer Groy esamina con cura il mazzo.>\n\nNiente male, niente male davvero. Un altro mazzo renderà il mio cliente molto contento.\n\nImmagino che la tua prossima domanda riguarderà i soldi, eh, $C? Certo che sì!\n\nEcco, prendi queste monete e un consiglio: sparisci dai miei moli.", enHash = "4bd34c21", vanilla = true },
    },
    [624] = {
        title = { it = "L'indovinello di Cortello", enHash = "16f6140c", vanilla = true },
        text = { it = "Un ponte adorno, da molti passanti calcato\nA est di Deadwind e a sud di Redridge situato\nLà sotto qualcosa ti aspetta, lo sai\nChi lo chiama traccia, chi indizio: vedrai\nLì resterà per infiniti domani\nAttendendo nella Swamp of Sorrows, tra i pantani.", enHash = "fa6b484a", vanilla = true },
        objectives = { it = "Risolvi l'indovinello!", enHash = "973fca61", vanilla = true },
        reward = { it = "La pergamena fradicia contiene il prossimo indizio...", enHash = "9afafd24", vanilla = true },
    },
    [625] = {
        title = { it = "L'indovinello di Cortello", enHash = "16f6140c", vanilla = true },
        text = { it = "In Kalimdor ti attendono luoghi lontani\nDove il pericolo ha reso speranze e destini vani\nA est delle Barrens il clima è impietoso\nNel Dustwallow Marsh tutto è cupo e insidioso\nMa per chi supera la prova un indizio c'è\nIn una grotta a sud-ovest, che aspetta te.", enHash = "b2b5eeff", vanilla = true },
        objectives = { it = "Risolvi l'indovinello!", enHash = "973fca61", vanilla = true },
        reward = { it = "Trovi una pergamena ammuffita.", enHash = "984d79ec", vanilla = true },
    },
    [626] = {
        title = { it = "L'indovinello di Cortello", enHash = "16f6140c", vanilla = true },
        text = { it = "A Lordaeron! Grande terra di tormento\nDove prodi soldati si battono con la morte a ogni momento\nAttraversa i grandi disordini con coraggio\nLà troverai la fine di questo viaggio\nLungo la costa delle Hinterlands, ai piedi delle grandi cascate\nSott'acqua il tuo tesoro ti chiama dalle onde agitate!", enHash = "e7be21bd", vanilla = true },
        objectives = { it = "Risolvi l'indovinello!", enHash = "973fca61", vanilla = true },
        reward = { it = "Apri il forziere e scopri...", enHash = "cfbce4ab", vanilla = true },
    },
    [627] = {
        title = { it = "Un favore per Krazek", enHash = "b805eedf", vanilla = true },
        text = { it = "C'è una grotta di montagna nella Drywhisker Gorge, lontano a nord, negli Arathi Highlands. In quella grotta c'è un minerale raro: la sanguinaria. La sanguinaria di questa grotta non è della qualità migliore, ma anche quella di bassa qualità ha valore... per chi sa come usarla.\n\nNe vorrei un po'.\n\nIo aggiusto la tua pentola, ma mentre ci lavoro... portami dei campioni di sanguinaria. Portamene abbastanza e ti darò anche un extra.\n\nAh, e se non hai la capacità di estrarla... trova qualcuno che ce l'ha!", enHash = "ed48d814", vanilla = true },
        objectives = { it = "Porta 4 carichi di Lesser Bloodstone Ore a Krazek, a Booty Bay.", enHash = "65744f9e", vanilla = true },
        progress = { it = "Salve, $N. Hai avuto fortuna con la sanguinaria?", enHash = "a15b9ab2", vanilla = true },
        reward = { it = "Ah, splendido! Mi hai fatto proprio un bel favore.\n\nEcco il tuo compenso...", enHash = "7bf00644", vanilla = true },
    },
    [628] = {
        title = { it = "Excelsior", enHash = "5816fdf0", vanilla = true },
        text = { it = "Finito l'interno, non resta che aggiungere lo strato esterno. Per questo uso solo le migliori pelli di coccodrillo anziano. Sono più resistenti e sono una tela migliore, per così dire, per aggiungere i disegni e le rifiniture che fanno la linea Excelsior di Drizzlik.\n\nPerò è difficile trovare la pelle perfetta: l'unica adatta al mio progetto è quella di un Elder Saltwater Crocolisk. Gli esemplari anziani escono solo per difendere gli altri crocolisk d'acqua salata, quindi potresti doverne uccidere qualcuno per farne uscire uno.", enHash = "32671c4d", vanilla = true },
        objectives = { it = "Porta un Elder Crocolisk Skin a Drizzlik, a Booty Bay.", enHash = "ce027737", vanilla = true },
        progress = { it = "Ho letto da qualche parte che i crocolisk d'acqua salata si stanno lentamente estinguendo... brutte notizie per i miei affari, no?\n\nComunque, spero che tu abbia quella pelle di Elder Saltwater Crocolisk per me!", enHash = "f8ffbc46", vanilla = true },
        reward = { it = "Grande! Grazie al tuo aiuto evaderò questo ordine e lo spedirò a Director Riddlevox con la prossima nave per Undermine. Addirittura in anticipo!\n\nPer tutto il tuo lavoro, ecco: ne ho fatti qualche paio in più, quindi prendine uno. Offre Drizzlik.\n\nE ricorda: non c'è stivale più raffinato di uno della linea Excelsior di Drizzlik!", enHash = "e0d51ecc", vanilla = true },
    },
    [629] = {
        title = { it = "La Vile Reef", enHash = "6d4c1d59", vanilla = true },
        text = { it = "Tanto tempo fa, un grande tremito della terra fece sprofondare un'antica città troll sotto le acque della Savage Coast, a nord-ovest. Chiamiamo quel luogo la Vile Reef, perché ora nelle rovine della città vivono i murloc, che attaccano chiunque si avvicini.\n\nTra quelle rovine c'è una vecchia tavoletta che narra l'antica storia di Gri'lek, un eroe delle leggende troll. La storia è sacra per la tribù Darkspear, e anche se la tavoletta è troppo grande per essere spostata, ne voglio un frammento da custodire come reliquia nella nostra nuova casa a Orgrimmar.", enHash = "8284fc21", vanilla = true },
        objectives = { it = "Porta un Tablet Shard a Kin'weelay, al Grom'gol Base Camp.", enHash = "90fa2d22", vanilla = true },
        progress = { it = "Attendo il Tablet Shard, $N.", enHash = "7f9eab1c", vanilla = true },
        reward = { it = "Bene. Quando tornerò a Orgrimmar metterò questo frammento in un luogo sacro. Ci ricorderà la potenza e l'onore di Gri'lek.\n\nGrazie, $N. Le tue imprese segnano un'amicizia crescente con la tribù Darkspear.", enHash = "be6933ec", vanilla = true },
    },
    [630] = {
        title = { it = "Messaggio in bottiglia", enHash = "e4c5a867", vanilla = true },
        text = { it = "$N, ripongo la mia fiducia in te e in chiunque tu riesca a radunare per liberarmi. Il grande Skymane King Mukla è il mio carceriere. Comanda le bestie di quest'isola, e mi tengono qui contro la mia volontà con questa catena. Se riesci a ucciderlo e a trovare la chiave di questo ceppo, ti sarò molto debitrice.\n\nLo sento spesso dalla parte sud-orientale dell'isola, ma ti prego, fa' attenzione: non è uno da prendere alla leggera.", enHash = "2f104c93", vanilla = true },
        objectives = { it = "Uccidi King Mukla e torna da Princess Poobah con la Shackle Key per liberarla.", enHash = "dd79c442", vanilla = true },
        progress = { it = "Ringrazio i miei antenati che qualcuno sia venuto ad aiutarmi. Hai la chiave che mi libererà?", enHash = "2fbf454c", vanilla = true },
        reward = { it = "$N, mi hai salvata da un grande disonore. Se fosse in mio potere, ti offrirei un posto nella mia tribù. Ma per ora posso offrirti solo questo pegno, per il coraggio e la nobiltà che hai dimostrato.", enHash = "556e8709", vanilla = true },
    },
    [631] = {
        title = { it = "Il Thandol Span", enHash = "20cdaeb9", vanilla = true },
        text = { it = "Un'esplosione tremenda ha rombato tra le colline. È stato orribile, credimi!\n\nBravi soldati sono morti difendendo il Thandol Span. Longbraid dice che ci vendicheremo sui Dark Iron prima che sia tutto finito.\n\nSiamo messi malissimo, però, e non vedo rinforzi all'orizzonte. Longbraid ha mandato Ol' Rustlocke a esplorare il ponte orientale, per vedere se potevamo metterlo in sicurezza.\n\nÈ successo giorni fa. Non abbiamo uomini a sufficienza per cercarlo, con Dun Modr sotto assedio.\n\nForse tu puoi trovarlo...", enHash = "dd5dfa07", vanilla = true },
        objectives = { it = "Rhag Garmason vuole che tu trovi Ol' Rustlocke.", enHash = "dd1a9b4b", vanilla = true },
        reward = { it = "Frughi il piccolo cadavere del nano. Inciso nell'elmo si legge chiaramente: Ebenezer Rustlocke.", enHash = "bd5f5674", vanilla = true },
    },
    [632] = {
        title = { it = "Il Thandol Span", enHash = "20cdaeb9", vanilla = true },
        text = { it = "Sembra che il povero Ol' Rustlocke sia finito in un'imboscata dei Dark Iron. Noti una pergamena accanto al suo pugno serrato.\n\nRiferisci la triste notizia a Rhag Garmason e mostragli quello che hai trovato.", enHash = "786fc06e", vanilla = true },
        objectives = { it = "Torna da Rhag Garmason e mostragli la pergamena che hai trovato sul cadavere di Rustlocke.", enHash = "dcd4f4dd", vanilla = true },
        progress = { it = "Qualche traccia di Ol' Rustlocke, $N?", enHash = "4651e3bb", vanilla = true },
        reward = { it = "Oh cielo, la notizia è grave...", enHash = "76275626", vanilla = true },
    },
    [633] = {
        title = { it = "Il Thandol Span", enHash = "20cdaeb9", vanilla = true },
        text = { it = "Santo cielo, no! Povero Rustlocke. È davvero una gran tragedia.\n\nNon dobbiamo lasciare che la sua morte sia vana. Questa pergamena che hai scoperto indica che Kam Deepfury, la mente dietro l'attacco originale, ha fatto nascondere una scorta di esplosivi appena oltre il Thandol Span, negli Arathi Highlands.\n\nSe quegli esplosivi arrivano al ponte, la nostra principale linea di rifornimento verso nord sarà recisa! La scorta va distrutta, $N! Torna da me quando la missione sarà compiuta.\n\nSei la nostra unica speranza.", enHash = "cda47189", vanilla = true },
        objectives = { it = "Distruggi la scorta di esplosivi.", enHash = "0df44e0a", vanilla = true },
        progress = { it = "La scorta di esplosivi va distrutta!", enHash = "f88f8a64", vanilla = true },
        reward = { it = "Il ponte rimasto è salvo! Hai reso un grande servizio a King Magni e alla gente del Khaz Modan.\n\nOra, se solo riuscissimo a resistere abbastanza perché arrivino i rinforzi...", enHash = "3c0dd752", vanilla = true },
    },
    [634] = {
        title = { it = "Appello all'Alleanza", enHash = "30705003", vanilla = true },
        text = { it = "Ti chiedo ancora un piccolo favore, $C. Attendiamo le riserve di Ironforge. Roggo però sa di un campo dell'Alleanza a nord, negli Arathi Highlands, a Refuge Pointe.\n\nVa' laggiù e cerca Captain Nials. Chiedi alla brava Captain se l'Alleanza può concederci qualche soldato per aiutarci a riprendere Dun Modr e il Thandol Span.", enHash = "8a4f8464", vanilla = true },
        objectives = { it = "Cerca Captain Nials a Refuge Pointe.", enHash = "744f2d3d", vanilla = true },
        reward = { it = "Le mie condoglianze vanno a Longbraid e ai suoi coraggiosi soldati. La notizia della tragedia del Thandol Span e della caduta di Dun Modr mi pesa sul cuore.\n\nMa Stromgarde è caduta! Da qui la nostra presenza a Refuge Pointe. Ci troviamo a dover riprendere la nostra stessa grande città.\n\nL'onore e il dovere impongono che non lasciamo gli Highlands finché Stromgarde non tornerà a innalzare il possente stendardo del Re. Manderò a dire a Longbraid che dovrà cavarsela da solo...", enHash = "c2ca02b0", vanilla = true },
    },
    [635] = {
        title = { it = "Il cristallo nelle montagne", enHash = "95532e86", vanilla = true },
        text = { it = "Questo frammento pulsa mentre lo tieni in mano...\n\nSenti un senso di supplica provenire dal frammento, come se qualcuno cercasse di comunicare, qualcuno che ha disperatamente bisogno del tuo aiuto.\n\nNella tua mente appare una visione: le montagne settentrionali di Arathi, e un cristallo splendente che spunta dalla terra.\n\nTi senti $Gattratto:attratta; da quel luogo.", enHash = "0362becf", vanilla = true },
        objectives = { it = "Trova il cristallo della tua visione.", enHash = "4803158f", vanilla = true },
        reward = { it = "Questo cristallo pulsa, come se dentro vi fosse intrappolata una forza viva.", enHash = "f6435244", vanilla = true },
    },
    [637] = {
        title = { it = "Sully Balloo's Letter", enHash = "794e4f92", vanilla = true },
        text = { it = "La busta inzuppata e malridotta si sfalda tra le tue mani e ti lascia in pugno qualche pagina di lettera, scritta con cura minuziosa.\n\nLa lettera è indirizzata a una certa Mrs. Sara Balloo di Ironforge e comincia così: \"Mia cara Sara....\"", enHash = "ac86c74b", vanilla = true },
        objectives = { it = "Consegna Sully Balloo's Letter a Sara Balloo.", enHash = "dc832608", vanilla = true },
        progress = { it = "Sembri aver viaggiato a lungo e aver visto molti tumulti ai tuoi tempi, $C. I tempi in cui viviamo mettono a dura prova l'anima. Che notizie mi porti adesso?", enHash = "5702e3c0", vanilla = true },
        reward = { it = "Dici di aver visto il mio Sully intrappolato sotto le acque gelide? Dimmi che non è vero!\n\nLascia che legga quel che ha scritto....", enHash = "daf0fc8c", vanilla = true },
    },
    [638] = {
        title = { it = "Trollbane", enHash = "1f874ca7", vanilla = true },
        text = { it = "Con Thoras Trollbane morto e Stromgarde in rovina, Vol'jin ci ha ordinato di fare di tutto per sottrarre agli umani la leggendaria spada Trol'kalar, così da poterla usare nelle prossime battaglie contro i troll di Zul'Gurub.\n\nZengu, uno dei nostri cacciatori più esperti, è stato mandato a Hammerfall, nel nord-est degli Arathi Highlands, per occuparsi di procurarla.", enHash = "dce8b668", vanilla = true },
        objectives = { it = "Va' a Hammerfall, negli Arathi Highlands, e parla con Zengu.", enHash = "141ec175", vanilla = true },
        reward = { it = "Come va, $C? Il compito che Vol'jin ci ha affidato sarà difficile, e qualunque aiuto tu possa darci sarà gradito e necessario.", enHash = "16d1eab2", vanilla = true },
    },
    [639] = {
        title = { it = "Sigil of Strom", enHash = "67b3d932", vanilla = true },
        text = { it = "In tempi antichi, i troll combatterono contro l'Arathorian Empire e contro il nostro avversario più capace, Lord Ignaeus of Strom, detto Trollbane. Cavalcava in battaglia brandendo Trol'kalar — ammazzatroll, nella loro antica lingua.\n\nMa ora i figli di Trollbane sono indeboliti, e la loro roccaforte è andata in rovina.\n\nLa spada è protetta da diversi sigilli, divisi tra i sopravvissuti di Stromgarde, e dobbiamo recuperarli.\n\nIl primo l'ha preso il Syndicate; dovrebbe averlo uno dei loro uomini a Stromgarde.", enHash = "1c45b683", vanilla = true },
        objectives = { it = "Procura il Sigil of Strom per Zengu, a Hammerfall.", enHash = "ccac8f6d", vanilla = true },
        progress = { it = "Hai già trovato il primo sigillo? Molto probabilmente ce l'ha addosso uno degli agenti del Syndicate a Stromgarde.", enHash = "78ddca5a", vanilla = true },
        reward = { it = "Eccellente, $Gamico:amica;. È un buon inizio per raccogliere i sigilli che ci serviranno per togliere Trol'kalar dalla tomba di Trollbane.", enHash = "adbe640c", vanilla = true },
    },
    [640] = {
        title = { it = "Il sigillo spezzato", enHash = "bc4d80f8", vanilla = true },
        text = { it = "La tomba di Thoras Trollbane è protetta da tre sigilli; il primo l'hai recuperato dal Syndicate. Gli altri due saranno più difficili da prendere, perché sono in mano alla milizia di Stromgarde, ben trincerata.\n\nIl Sigil of Thoradin è stato diviso in undici pezzi dal figlio di Thoras, Galen, e distribuito tra i difensori di Stromgarde. Recupera i pezzi e portali a Tor'gan, lo sciamano troll: sarà in grado di ricomporli nel sigillo completo.", enHash = "55e2382f", vanilla = true },
        objectives = { it = "Recupera gli 11 Sigil Fragment dai difensori di Stromgarde e portali a Tor'gan, a Hammerfall.", enHash = "fecea7e0", vanilla = true },
        progress = { it = "Throm'ka, $C. Zengu mi ha detto che avevi bisogno del mio aiuto?", enHash = "50ac6d9f", vanilla = true },
        reward = { it = "Ah, hai bisogno che ricomponga questo sigillo? Non dovrebbe essere troppo difficile... tutti i pezzi sembrano esserci, e la struttura magica sarà facile da ricostruire.\n\nForse ti conviene chiudere gli occhi.", enHash = "2e28b715", vanilla = true },
    },
    [641] = {
        title = { it = "Sigil of Thoradin", enHash = "e246741c", vanilla = true },
        text = { it = "La ricostruzione è riuscita alla perfezione. Ora il sigillo può servire a spezzare il suggello sulla tomba di Trollbane. Riportalo a Zengu; di sicuro ha altri compiti per te.", enHash = "1abf81a3", vanilla = true },
        objectives = { it = "Porta il Sigil of Thoradin restaurato a Zengu, a Hammerfall.", enHash = "97006695", vanilla = true },
        progress = { it = "$N! Hai il secondo sigillo?", enHash = "7fa6801d", vanilla = true },
        reward = { it = "Siamo a metà strada per poter togliere Trol'kalar dalla tomba di Trollbane. Non sappiamo con precisione dove sia il terzo sigillo, perché chi lo custodisce sembra spostarsi parecchio per l'Arathi, ma ho fiducia che riuscirai a trovarlo.", enHash = "28ba26b2", vanilla = true },
    },
    [642] = {
        title = { it = "La principessa intrappolata", enHash = "c55746da", vanilla = true },
        text = { it = "Il mio nome è Myzrael. Sono una principessa della terra, e i miei carcerieri, i giganti, mi hanno intrappolata nelle profondità delle Arathi Highlands. Questi frammenti di cristallo sono l'unico modo in cui posso parlare con il mondo di superficie.\n\nTi prego, aiutami. Alleati dei giganti, i Drywhisker Kobold hanno un frammento come questo nella loro Drywhisker Gorge, a est. Per alimentare il gruppo di frammenti, devi raccogliere i Mote of Myzrael dai kobold e applicarli ad esso.\n\nTi supplico, $N, aiutami!", enHash = "2c983bb6", vanilla = true },
        objectives = { it = "Raccogli 12 Mote of Myzrael, poi portali agli Iridescent Shards nella Drywhisker Gorge.", enHash = "31e8a996", vanilla = true },
        progress = { it = "Questo gruppo di frammenti somiglia molto agli Shards of Myzrael. Ma non ne emana la stessa sensazione di sicurezza.", enHash = "f7699480", vanilla = true },
        reward = { it = "Ah! Hai attivato questi frammenti. Mi sento già più me stessa!\n\nMa ahimè, sono ancora lontana dall'essere libera...", enHash = "3240a413", vanilla = true },
    },
    [643] = {
        title = { it = "Sigil of Arathor", enHash = "8d9b2a4a", vanilla = true },
        text = { it = "Anche se a malapena si può dire che controllino Stromgarde, figurarsi tutti gli Arathi Highlands, il principe umano fa trottare i resti della sua cavalleria per le campagne. Non capisco perché lo faccia, ma chi capisce come ragionano gli umani, eh?\n\nQualunque sia il suo motivo, la cosa più importante è che ha dato uno dei sigilli a Lieutenant Valorcall, il capo della loro cavalleria. Trovalo e riportami il suo sigillo.", enHash = "4427809b", vanilla = true },
        objectives = { it = "Recupera il Sigil of Arathor e riportalo a Zengu, a Hammerfall.", enHash = "27f3d6d5", vanilla = true },
        progress = { it = "Non sarà facile rintracciare Valorcall, $N. A cavallo copre grandi distanze in fretta. Ciononostante, il suo sigillo ci serve.", enHash = "9a859ed7", vanilla = true },
        reward = { it = "Perdere il capo della cavalleria sarà un duro colpo per i difensori di Stromgarde. Meglio ancora, significa che ci manca un solo sigillo per poter avere Trol'kalar tutta per noi.", enHash = "aec2a1bd", vanilla = true },
    },
    [644] = {
        title = { it = "Sigil of Trollbane", enHash = "6bb0b88a", vanilla = true },
        text = { it = "L'ultimo dei sigilli necessari per aprire la tomba di Thoras Trollbane lo custodisce di persona suo figlio. Vive nel cuore di Stromgarde, in una cappella dei quartieri in mano alla milizia. Prince Galen è ben protetto, ed è lui stesso un guerriero tutt'altro che scarso, quindi questo compito potrebbe rivelarsi molto difficile.", enHash = "e05f5623", vanilla = true },
        objectives = { it = "Uccidi Prince Galen Trollbane e porta il Sigil of Trollbane a Zengu, a Hammerfall.", enHash = "d2b62d89", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata;, $N. La stirpe di Ignaeus Trollbane è spezzata?", enHash = "4c5f76a9", vanilla = true },
        reward = { it = "Che giornata, $C. Il sangue di Trollbane non perseguiterà più la mia gente, e i sigilli necessari per prendere Trol'kalar sono in nostro possesso. Presto, molto presto, colpiremo gli odiati troll di Zul'Gurub.", enHash = "43e5033e", vanilla = true },
    },
    [645] = {
        title = { it = "Trol'kalar", enHash = "5c22b15b", vanilla = true },
        text = { it = "Cos'è questo? Riuniti, i quattro sigilli si sono fusi in un unico sigillo. Non c'è dubbio che potrà spezzare le protezioni poste sulla tomba di Trollbane.\n\nI resti di Trollbane sono sepolti nel Sanctum, dietro la cappella di Stromgarde. Recupera Trol'kalar.", enHash = "a8045c65", vanilla = true },
        objectives = { it = "Recupera Trol'kalar dalla tomba di Trollbane, a Stromgarde.", enHash = "0626a497", vanilla = true },
        progress = { it = "Le incisioni nella pietra sulla facciata della tomba di Trollbane corrispondono alle linee luminose del Sigil of Ignaeus...", enHash = "b58e1bc9", vanilla = true },
        reward = { it = "Mentre fai combaciare le linee sulla facciata della tomba di Trollbane con quelle luminose del Sigil of Ignaeus, un lampo di luce lo consuma, e la leggendaria spada Trol'kalar si libera dalla stretta delle mani di pietra.", enHash = "e4bd7a35", vanilla = true },
    },
    [646] = {
        title = { it = "Trol'kalar", enHash = "5c22b15b", vanilla = true },
        text = { it = "La luce svanisce lentamente: la spada Trol'kalar, custodita in un fodero di pietra, è stata liberata.", enHash = "c39a1867", vanilla = true },
        objectives = { it = "Consegna Sheathed Trol'kalar a Zengu, a Hammerfall.", enHash = "b775455c", vanilla = true },
        progress = { it = "$N! Hai preso la spada?", enHash = "8422f0ba", vanilla = true },
        reward = { it = "Per generazioni le forze di Strom e di Arathor hanno devastato i troll. Ora la loro arma più potente è nelle nostre mani. La nostra lenta avanzata nelle foreste afose di Zul'Gurub finirà.\n\nIl tuo aiuto è stato prezioso, $N, e i troll Darkspear ti sono debitori.\n\nMi assicurerò che la spada venga consegnata a Nimboya, a Grom'gol.", enHash = "88ed2b2a", vanilla = true },
    },
    [647] = {
        title = { it = "MacKreel's Moonshine", enHash = "60fd1d2c", vanilla = true },
        text = { it = "Ieri sera ho alzato un po' troppo il gomito con la vecchia Moonshine! Longbraid mi staccherebbe la testa se sapesse che sono svenuto durante il turno di guardia.\n\nLa zucca mi fa un male cane. Mi è sembrato che una brigata intera di macchine d'assedio passasse di sopra, con tutto quel rimbombo.\n\nOh, guarda che ora! Avevo promesso a Brewmeister Bilger, a Southshore, che gli avrei ripagato il debito mandandogli un po' di Moonshine.\n\nMa mancano solo 15 minuti alla scadenza! Portagliene questa partita, per favore. E sbrigati!", enHash = "07a2ae3c", vanilla = true },
        objectives = { it = "Porta MacKreel's Moonshine a Brewmeister Bilger, a Southshore.", enHash = "1a468fb7", vanilla = true },
        progress = { it = "Che buone nuove porti, $R?", enHash = "298bb18f", vanilla = true },
        reward = { it = "Ah, niente come Foggy MacKreel's Moonshine per scaldarti in una giornata fredda! E io che pensavo che quel furfantello sarebbe stato di nuovo in ritardo con i conti. Grazie, $Gamico:amica;! Grazie mille davvero!", enHash = "575fff6d", vanilla = true },
    },
    [651] = {
        title = { it = "Stones of Binding", enHash = "95babbee", vanilla = true },
        text = { it = "Quattro Stones of Binding sono sparse per Arathi. Queste pietre mi tengono inchiodata sotto terra.\n\nPer sbloccarle devi sbloccare la più forte: la Stone of Inner Binding. E per farlo devi raccogliere le chiavi dalle altre tre.\n\nQueste pietre sono sorvegliate da guardiani, ma se sei $Gastuto:astuta;, o $Gfortunato:fortunata;, potresti trovare il modo di scacciarli.", enHash = "246c1fba", vanilla = true },
        objectives = { it = "Raccogli la Burning Key, la Cresting Key e la Thundering Key dalla Stone of West Binding, dalla Stone of East Binding e dalla Stone of Outer Binding.\n\nPortale alla Stone of Inner Binding.", enHash = "7afd79a5", vanilla = true },
        progress = { it = "Questa è la Stone of Inner Binding. È la più forte delle pietre del vincolo, e va sbloccata perché le altre si aprano.", enHash = "4acda9a6", vanilla = true },
        reward = { it = "<Myzrael parla attraverso la pietra.>\n\nCe l'hai fatta! Hai aperto le Stones of Binding! Sento allentarsi le catene che mi stringono, e la libertà si fa sempre più vicina.\n\nSei $Gun nobile:una nobile; $C, $N. $GIl mio salvatore:La mia salvatrice;!", enHash = "84e59d01", vanilla = true },
    },
    [652] = {
        title = { it = "Spezzare la Keystone", enHash = "22be9eb2", vanilla = true },
        text = { it = "Aprire le Stones of Binding ha allentato molto la mia prigionia, ma un lucchetto mi tiene ancora in catene. È la Keystone che vedi in questo cerchio di pietre. E la chiave è in mano a uno dei miei carcerieri, il guardiano di pietra Fozruk.\n\nDevi prendere a Fozruk quella chiave, che i guardiani di pietra chiamano Rod of Order, e usarla per aprire la Keystone.\n\n$N, hai fatto così tanto per aiutarmi. Ancora un piccolo sforzo... e la mia gratitudine scuoterà le fondamenta stesse della terra!", enHash = "d934c6b8", vanilla = true },
        objectives = { it = "Trova e uccidi Fozruk. Porta il Rod of Order alla Keystone, nelle Arathi Highlands.", enHash = "af0252df", vanilla = true },
        progress = { it = "La Keystone è carica di un'enorme energia geomantica.", enHash = "2c49ee62", vanilla = true },
        reward = { it = "Inserisci la verga nella Keystone. E sotto di te si avverte un fremito...", enHash = "4b6aff32", vanilla = true },
    },
    [653] = {
        title = { it = "Gli alleati di Myzrael", enHash = "9e67bb26", vanilla = true },
        text = { it = "<Myzrael parla.>\n\nLibera! SONO LIBERA! Sono libera di raccogliere le forze, nascosta ai miei carcerieri. Perché se mi affrontassero adesso, di certo mi sopraffarebbero e mi imprigionerebbero di nuovo.\n\nMa col tempo affronterò i giganti, e si pentiranno di avermi tenuta prigioniera!\n\nSei $Gun nobile alleato:una nobile alleata;, $N. Col tempo avrò di nuovo bisogno del tuo aiuto. Quando sarò pronta, dovrai evocarmi in superficie.\n\nParla con Gerrig Bonegrip. Si trova a Ironforge, in una bottega della Forlorn Cavern. Lui sa come evocarmi.", enHash = "2fd918d6", vanilla = true },
        objectives = { it = "Parla con Gerrig Bonegrip, nella Forlorn Cavern, a Ironforge.", enHash = "4ebb3f51", vanilla = true },
        reward = { it = "La Signora mi ha annunciato il tuo arrivo, $C. Sei $Gil benvenuto:la benvenuta; nella mia dimora, perché tu, come me, servi una causa più alta.", enHash = "7467bc9f", vanilla = true },
    },
    [655] = {
        title = { it = "Hammerfall", enHash = "df7b1f41", vanilla = true },
        text = { it = "Lo vedo ancora chiaro, come fosse ieri... Tanti anni senza speranza, con legno e acciaio a legarmi a questo luogo terribile. Poi finalmente, finalmente! Ecco il Capoguerra. Doomhammer nella sua armatura color mezzanotte, il martello da guerra alzato al cielo.\n\nFu... troppo terribile... Che il colpo di un codardo abbattesse il nostro più grande eroe. Arrivò alle sue spalle a cavallo, e poi la sua lancia lo trafisse... Caddi in ginocchio. Che speranza c'era? Che speranza c'è...", enHash = "ac3eb2b3", vanilla = true },
        objectives = { it = "Parla con Tor'gan, a Hammerfall.", enHash = "cbd5dc5a", vanilla = true },
        reward = { it = "Ah, parli di Gor'mul. Sì, da quello che dice, pare che non si sia mai ripreso dalla morte di Doomhammer.\n\nGor'mul era prigioniero qui quando Thrall e Orgrim combatterono per liberare il campo, ma mentre la terra tremava e i nostri fratelli fuggivano, lui fu lasciato indietro. Ha vagato da solo e smarrito per anni, senza meta né speranza, finché non siamo tornati a stabilirci qui a Hammerfall.", enHash = "a9221c5c", vanilla = true },
    },
    [656] = {
        title = { it = "Evocare la principessa", enHash = "b4c88697", vanilla = true },
        text = { it = "Devi sconfiggere Myzrael prima che diventi più forte. Altrimenti, quando avrà raccolto abbastanza potere, sfiderà i suoi carcerieri! C'è chi pensa di poterla controllare, ma se si può controllare, perché mai i giganti l'avrebbero incatenata?\n\nLogica da pazzi, eh?\n\nPer sconfiggerla, evocala agli Shards of Myzrael, dove le hai parlato la prima volta. Sconfiggila e raccogli le sue Eldritch Shackles, poi legale agli Shards of Myzrael.\n\nFallo, e sarà di nuovo intrappolata.", enHash = "5471bd48", vanilla = true },
        objectives = { it = "Va' agli Shards of Myzrael, evocala e sconfiggila.\n\nRaccogli le sue Eldritch Shackles e legale agli Shards of Myzrael.", enHash = "b1121eb4", vanilla = true },
        progress = { it = "Gli Shards of Myzrael ora sono stranamente silenziosi.", enHash = "29fd9ef0", vanilla = true },
        reward = { it = "Mentre le Eldritch Shackles vengono poste intorno agli Shards, dal profondo si leva un lamento disumano. All'urlo segue un ruggito.\n\nGli Shards of Myzrael non suscitano più il senso di calore e di sicurezza di un tempo. Ora pulsano di una minaccia aperta... come se la cosa sotto di loro nutrisse rancore verso la superficie.", enHash = "748cd96f", vanilla = true },
    },
    [657] = {
        title = { it = "Indizi di una nuova piaga?", enHash = "3f9291d9", vanilla = true },
        text = { it = "<Quae comincia a sfogliare la cartella.>\n\nQuesto sì che è interessante. Pare che Apothecary Jorell stia lavorando a esperimenti letali qui a Go'Shek. Non so cosa c'entri con Hillsbrad, ma a Phin non piacerebbe se lasciassimo che continui.\n\nAbbiamo avuto uno scontro con degli orchi mentre eri via, e non sono in condizioni di aiutare Kinelory. Se te la senti, le servirà protezione quando scenderà alla fattoria a rubare tutte le ricerche che Jorell non ha ancora mandato a Tarren Mill.", enHash = "bf35c0b3", vanilla = true },
        objectives = { it = "Parla con Kinelory.", enHash = "70d6fe18", vanilla = true },
        reward = { it = "Se questo dà pace a Phin, distruggerò ogni singolo Reietto di persona. Ha fatto tanto per noi dopo la piaga. Non avremmo mai pensato di ritrovare amici o famiglia.\n\nQuando sei $Gpronto:pronta;, fammelo sapere. Cominciamo subito.", enHash = "0d385f14", vanilla = true },
    },
    [658] = {
        title = { it = "Indizi di una nuova piaga?", enHash = "3f9291d9", vanilla = true },
        text = { it = "Allora, Phin ti ha mandato a controllare come stiamo? Non mi sorprende: si preoccupa troppo.\n\nTeniamo d'occhio la fattoria da giorni, e Kin sostiene di aver visto un corriere uscire da quella casetta a sud non molto tempo fa.\n\nParla tanto, ma dei suoi sensi mi fido sempre quando siamo in zone pericolose.\n\nNon è che per caso sei $Gun abile battitore:un'abile battitrice; di piste? Crediamo che il corriere stia portando appunti a Tarren Mill. Se riuscissimo a mettere le mani su quei documenti, forse capiremmo qualcosa di quel che sta succedendo a Hillsbrad.", enHash = "68dde621", vanilla = true },
        objectives = { it = "Trova la Forsaken Courier e porta il suo Sealed Folder a Quae, vicino alla Go'Shek Farm.", enHash = "5c77fd59", vanilla = true },
        progress = { it = "Ti siamo grati dell'aiuto nella ricerca di quel corriere, $N.\n\nMentre eri via, Kin ha visto uno speziale uscire dalla stessa casa qui a sud. Sono convinta che stiano tramando qualcosa: mi serve solo la prova prima di andare a fare qualche sciocchezza.\n\nHai avuto fortuna?", enHash = "9ef68b9a", vanilla = true },
        reward = { it = "Ottimo!\n\nVediamo di cosa si tratta...", enHash = "7e50f976", vanilla = true },
    },
    [659] = {
        title = { it = "Indizi di una nuova piaga?", enHash = "3f9291d9", vanilla = true },
        text = { it = "Salve, e ben $Gincontrato:incontrata;, $N. Guido un gruppo di avventurieri che indaga su strani fatti in questa zona.\n\nMio cugino, a Hillsbrad, ha dovuto abbattere il suo cane Stanley perché l'animale è cresciuto misteriosamente fino a diventare enorme e attaccava con ferocia chiunque gli si avvicinasse.\n\nCredo che di mezzo ci siano i non morti, e stiamo cercando prove che lo dimostrino.\n\nDue miei compagni, Quae e Kinelory, sono andati alla Go'Shek Farm, nelle Arathi Highlands, e non si fanno vivi da giorni. Me li trovi? Comincio a preoccuparmi.", enHash = "63bff5f8", vanilla = true },
        objectives = { it = "Trova Quae e Kinelory vicino alla Go'Shek Farm, nelle Arathi Highlands.", enHash = "9a20623d", vanilla = true },
        reward = { it = "Cerca di fare meno rumore possibile, $Gviaggiatore:viaggiatrice;.\n\nGli orchi non la prendono bene quando li si spia, e in questa fattoria c'è più di quel che sembra.", enHash = "087d1405", vanilla = true },
    },
    [660] = {
        title = { it = "Indizi di una nuova piaga?", enHash = "3f9291d9", vanilla = true },
        text = { it = "Bene, $N. Io sono pronta, se lo sei tu.\n\nAndiamo?", enHash = "c06433ba", vanilla = true },
        objectives = { it = "Proteggi Kinelory finché non torna da Quae.", enHash = "c9061900", vanilla = true },
        progress = { it = "Il tempo delle chiacchiere è finito. Proteggi Kinelory, se ti importa qualcosa della gente di Hillsbrad.", enHash = "996c561b", vanilla = true },
        reward = { it = "Ci hai reso un grande servizio, $N. Grazie.\n\nSpero che Kin non ti abbia dato troppo filo da torcere laggiù. È molto amichevole, ma sa essere altrettanto letale quando le sei $Gnemico:nemica;.", enHash = "40ca5744", vanilla = true },
    },
    [661] = {
        title = { it = "Indizi di una nuova piaga?", enHash = "3f9291d9", vanilla = true },
        text = { it = "Ho visto Kinelory messa molto peggio dopo una notte in taverna di come sta adesso. Si vede che l'hai protetta bene.\n\nQueste cose che ha riportato dalla fattoria dovrebbero almeno far capire a Phin cosa sta succedendo qui in Arathi. Giusto per essere sicuri che non ci siano rappresaglie dopo il vostro attacco, ci fermeremo qui ancora un po'. Te la sentiresti di tornare a Southshore e parlare con Phin?", enHash = "c7d9b622", vanilla = true },
        objectives = { it = "Trova Phin Odelic, a Southshore.", enHash = "baedbd01", vanilla = true },
        reward = { it = "Allora, i due piantagrane stanno bene dopotutto? Ahah, sono contento di saperlo. Ti ringrazio per avermi portato notizie di dove sono e di come stanno: mi fa molto piacere che siano ancora vivi; come amici e compagni di viaggio quei due sono insostituibili.\n\nMa... è più importante ringraziarti come si deve per il tuo aiuto. Tieni. Prendi questo, insieme ai ringraziamenti del mio gruppo.\n\nCon un po' di fortuna capiremo cosa stanno combinando i Reietti e vi metteremo fine.", enHash = "fee1be6a", vanilla = true },
    },
    [662] = {
        title = { it = "Recupero in acque profonde", enHash = "d978f9a2", vanilla = true },
        text = { it = "O'Breen ha guidato le navi nella baia. Eravamo certi che il tesoro si trovasse qui. La Harbinger ha attraccato senza problemi, ma mentre la Maiden's Folly e la Spirit of Silverpine si avvicinavano, la marea ha cominciato ad abbassarsi. La cosa più strana che abbia mai visto!\n\nQuelle due navi si sono arenate contro qualcosa... una specie di tempio nella scogliera. Sono affondate così in fretta, è stata una vera tragedia.\n\nPrima di partire dobbiamo recuperare i loro diari di bordo e le loro carte nautiche. Non possiamo lasciare quelle informazioni a occhi indiscreti!", enHash = "e7267909", vanilla = true },
        objectives = { it = "First Mate Nilzlix vuole che tu recuperi Maiden's Folly Charts, Maiden's Folly Log, Spirit of Silverpine Charts e Spirit of Silverpine Log.", enHash = "53a6b376", vanilla = true },
        progress = { it = "Come va la missione di ricerca e recupero, $N? Dobbiamo proprio riavere quei diari di bordo e quelle carte nautiche della Maiden's Folly e della Spirit of Silverpine.\n\nSe le informazioni di quelle fonti cadessero in mano al nemico, Fleet Master Seahorn ci farebbe camminare sull'asse.\n\nSempre che riusciamo a uscire da questo pasticcio...", enHash = "cb03f10a", vanilla = true },
        reward = { it = "Sapere che queste informazioni sono al sicuro darà un po' di sollievo al comando di Booty Bay. Ben fatto, $N.", enHash = "c5fdcb9d", vanilla = true },
    },
    [663] = {
        title = { it = "Terra in vista!", enHash = "9f81c445", vanilla = true },
        text = { it = "Lolo vede $Gun piccolo:una piccola; $R! Sempre di vedetta, Lolo è!\n\n$GBenvenuto:Benvenuta; al Faldir's Cove. Captain O'Breen ha detto che saremmo rimasti qui solo poche ore. Giusto il tempo di recuperare il tesoro e tornare a Booty Bay.\n\nMa Lolo pensa che resteremo qui molto più a lungo. Abbiamo perso le altre due navi della nostra formazione. Povere Spirit of Silverpine e Maiden's Folly. Ora riposano in fondo al mare!\n\nLolo ti consiglia di parlare con Captain O'Breen, se pensi di fermarti da queste parti.", enHash = "92d29e5c", vanilla = true },
        objectives = { it = "Parla con Captain O'Breen, al Faldir's Cove.", enHash = "f440058f", vanilla = true },
        reward = { it = "Ahoy, $Gcompagno:compagna;.\n\nÈ stato un disastro terribile. Seahorn mi toglierà la nave, se scopre cos'è successo.\n\nUno degli aggeggi del professore indicava che il tesoro perduto era vicino a questa baia. Ho portato la Harbinger all'attracco e ho fatto segno alla Spirit of Silverpine e alla Maiden's Folly di fare lo stesso.\n\nPoi il mare ha brontolato. La marea si è abbassata e le due navi si sono schiantate contro la scogliera.\n\nNon è solo una scogliera. Laggiù c'è qualcosa...\n\nAiuta il mio equipaggio e sarai $Gricompensato:ricompensata; generosamente.", enHash = "9c57525f", vanilla = true },
    },
    [664] = {
        title = { it = "Dispiaceri annegati", enHash = "764ee826", vanilla = true },
        text = { it = "Argh, che vita orribile. Adesso dovrei trovarmi in una tomba d'acqua, non seduto qui accanto al fuoco a respirare aria fresca.\n\nL'equipaggio ha fatto di tutto per salvare la mia bella Maiden's Folly. Benedetti ragazzi, benedetti i loro cuori.\n\nO'Breen è arrivato a riva sano e salvo, ma noi non siamo stati così fortunati. Il mare ci è crollato sotto, lo giuro.\n\nUn attimo prima galleggiamo e un attimo dopo l'acqua entra a fiotti. E quelle bestie! Hanno ucciso tutti i sopravvissuti. Orribile feccia naga. Ho perso i sensi e mi sono ritrovato qui, salvo.\n\nVoglio quelle bestie morte.", enHash = "f2519092", vanilla = true },
        objectives = { it = "Captain Steelgut, al Faldir's Cove, vuole che tu uccida 10 Daggerspine Raider e 3 Daggerspine Sorceress.", enHash = "b80f7a84", vanilla = true },
        progress = { it = "Bah, forse dovrei andare io stesso a uccidere quella feccia naga. È evidente che tu non lo farai.\n\nForse posso trovarti dei ferri da maglia, così hai qualcosa da fare.", enHash = "80ec400c", vanilla = true },
        reward = { it = "Bel lavoro là fuori, $N.\n\nQuella feccia ha avuto quello che si meritava. Anche se niente mi restituirà la mia nave o il mio equipaggio, la morte di quei naga mi dà un po' di conforto.", enHash = "f36e63cb", vanilla = true },
    },
    [665] = {
        title = { it = "Tesoro sommerso", enHash = "dc46ef47", vanilla = true },
        text = { it = "Ora che siamo Blackwater Raiders a tutti gli effetti, è nostro compito aiutare il signor O'Breen a trovare il tesoro elfico perduto.\n\nÈ quasi impossibile trovare le gemme nel buio del mare senza aiuto. Il dottore ha costruito degli occhialoni che serviranno allo scopo. Ha bisogno che vengano caricati con l'energia della pietra incantata che si trova nella grotta, appena su per la collina.\n\nMa la grotta è maledetta! Quando ci avviciniamo, ci tendono un'imboscata. Difendimi e riuscirò a imbrigliare negli occhialoni l'energia della pietra.", enHash = "1720c69d", vanilla = true },
        objectives = { it = "Scorta Professor Phizzlethorpe fino alla grotta e ritorno.", enHash = "82d33d40", vanilla = true },
        progress = { it = "Non è il momento di chiacchierare! Gli occhialoni devono essere caricati con il potere della pietra!", enHash = "97060b3d", vanilla = true },
        reward = { it = "Adesso gli occhialoni funzionano alla perfezione! Ben fatto, $N.", enHash = "5421d959", vanilla = true },
    },
    [666] = {
        title = { it = "Tesoro sommerso", enHash = "dc46ef47", vanilla = true },
        text = { it = "Il tesoro è rimasto sul fondo del mare così a lungo che le gemme si sono calcificate in una spessa pietra. Ma il potere racchiuso in questi occhialoni ti permetterà di trovarle facilmente.\n\nUn pizzico di ingegno gnomesco fa molta strada!\n\nQuindi prendi in prestito i Goggles of Gem Hunting, $N, e vedi se riesci a raccogliere un po' del tesoro perduto per Captain O'Breen.\n\nCi andrei a nuoto io stesso, ma... ehm... be', ho importanti faccende scientifiche da sbrigare quassù, sulla terraferma sicura e asciutta... ehm, sì.", enHash = "848baf55", vanilla = true },
        objectives = { it = "Doctor Draxlegauge, al Faldir's Cove, vuole che tu raccolga 10 Elven Gem e che restituisca i Goggles of Gem Hunting quando hai finito.", enHash = "34fc0f75", vanilla = true },
        progress = { it = "Come sono andati gli occhialoni? Ha funzionato tutto a dovere? Se serve, si possono fare delle regolazioni.\n\nAh, e quando hai finito mi servono indietro quegli occhialoni. Sono sicuro che Captain O'Breen troverà molti modi di usarli più avanti.", enHash = "f670cbec", vanilla = true },
        reward = { it = "Magnifico, $N! Il capitano sarà molto contento! E aspetta che la notizia arrivi a Fleet Master Seahorn!", enHash = "b3f91664", vanilla = true },
    },
    [667] = {
        title = { it = "Morte dal profondo", enHash = "1e4b4567", vanilla = true },
        text = { it = "Questa è brutta. Sembra che i Daggerspine si stiano radunando per un attacco.\n\nI naga sono noti per la loro spietatezza in battaglia. Continueranno ad attaccare finché non sarò morto.\n\nNon considero la mia vita più preziosa di quella dei miei uomini, ma devi aiutarmi a difendermi. L'equipaggio non riuscirà a tornare a Booty Bay senza la mia conoscenza dei mari.\n\nI naga arriveranno dal mare. Ho bisogno che resti quassù con me a respingere l'attacco. Mettiti al cannone e ricacciali indietro.\n\nSei $Gpronto:pronta;, $N?", enHash = "af023f4a", vanilla = true },
        objectives = { it = "Proteggi Shakes O'Breen durante l'attacco.", enHash = "ece94f14", vanilla = true },
        reward = { it = "Siamo sopravvissuti all'attacco!\n\nNon ce l'avremmo mai fatta senza di te, $N.\n\nSalperemo appena la marea salirà. Se non fossi $Gun eroe:un'eroina; così promettente, ti offrirei un posto nel mio equipaggio. Ma vedo che hai cose più grosse a cui pensare.\n\nAnche se sei $Gun:una; $R $Gmingherlino:mingherlina;...", enHash = "f69a9bac", vanilla = true },
    },
    [668] = {
        title = { it = "Tesoro sommerso", enHash = "dc46ef47", vanilla = true },
        text = { it = "Non facciamo aspettare Captain O'Breen. Vorrà vedere queste gemme con i suoi occhi. Dopotutto, è per questo che siamo qui!\n\nE dopo qualche settimana passata in compagnia di questi pirati, io e il professore ci siamo resi conto che la cosa peggiore per la nostra salute è farci trovare con il loro tesoro in mano.\n\nTieni, $N, portale a O'Breen.", enHash = "25f97c6c", vanilla = true },
        objectives = { it = "Porta le Elven Gems a Captain O'Breen.", enHash = "2e0380bd", vanilla = true },
        progress = { it = "Ahoy, $C. Cosa ti porta sul ponte di comando?", enHash = "ae880bd0", vanilla = true },
        reward = { it = "Allora quei piccoli gnomi si sono dimostrati utili, dopotutto? Lo sapevo che c'era un motivo per tenerci intorno quei mezzi tappi!", enHash = "9d09da9f", vanilla = true },
    },
    [669] = {
        title = { it = "Tesoro sommerso", enHash = "dc46ef47", vanilla = true },
        text = { it = "Fleet Master Seahorn vorrà sapere subito della nostra scoperta.\n\nMa come vedi, non siamo nella posizione di andarcene da qui. Non solo la marea è troppo bassa, ma quelle maledette creature che abbiamo disturbato tengono d'occhio ogni nostro movimento.\n\nPuoi rendere un grande servizio ai Blackwater Raiders se riesci a far sapere a Fleet Master Seahorn, a Booty Bay, che abbiamo scoperto il tesoro e che stiamo lavorando per recuperarne altro. Portagli questo campione come prova.", enHash = "cc0124ca", vanilla = true },
        objectives = { it = "Porta il Sample Elven Gem a Fleet Master Seahorn, a Booty Bay.", enHash = "b20acf6c", vanilla = true },
        progress = { it = "Cosa ti porta a Booty Bay, $C?", enHash = "e032e66c", vanilla = true },
        reward = { it = "Ah, ci si può sempre fidare del buon vecchio Shakes O'Breen! Sapevo che era il capitano giusto per la missione!", enHash = "b03212c5", vanilla = true },
    },
    [670] = {
        title = { it = "Tesoro sommerso", enHash = "dc46ef47", vanilla = true },
        text = { it = "Ehi, $N, mi sembri il tipo avventuroso. La mia flotta è bloccata a Booty Bay finché non riusciamo a rifornirci.\n\nQui e altrove bollono in pentola cose grosse, e devo far arrivare della corrispondenza segretissima a Shakes O'Breen, che è bloccato al largo della costa di Arathi.\n\nPosso fidarmi di te per consegnare questo messaggio al sicuro e in tutta riservatezza?", enHash = "4e5b3d18", vanilla = true },
        objectives = { it = "Consegna Seahorn's Sealed Letter a Shakes O'Breen, negli Arathi Highlands.", enHash = "9546368d", vanilla = true },
        progress = { it = "Allora, Seahorn è rimasto colpito? Scommetto che il suo sorriso andava da Booty Bay fino a Ratchet.", enHash = "eedb2656", vanilla = true },
        reward = { it = "Grazie per aver affrontato un viaggio così lungo e pericoloso. Hai la gratitudine dei Blackwater Raiders.", enHash = "d713e7c0", vanilla = true },
    },
    [671] = {
        title = { it = "Magie immonde", enHash = "318be366", vanilla = true },
        text = { it = "Ho sentito una stranezza nell'aria... una sensazione che mi ribolle nel sangue. Avevo i miei sospetti. Sono partito per trovare l'origine del mio disagio e ho scoperto a ovest, a Northfold Manor, le tracce residue di un'evocazione demoniaca. Man mano che mi avvicinavo, il sangue ha cominciato a ribollirmi e la rabbia dentro di me è cresciuta.\n\nA terra ho notato un amuleto di sanguinaria, usato per aiutare le evocazioni demoniache. Quello che ho trovato però era esaurito. Me ne servirà un altro da esaminare, ma non oso tornare al maniero. Puoi portarmene qualcuno?", enHash = "528c242b", vanilla = true },
        objectives = { it = "Procura 10 Bloodstone Amulet per Tor'gan, a Hammerfall.", enHash = "e61d3da2", vanilla = true },
        progress = { it = "Nelle mie vene scorre ancora sangue un tempo maledetto, $N. Se qualcuno... qualcosa sta evocando demoni, va fermato.", enHash = "36aa39c0", vanilla = true },
        reward = { it = "Mi ci vorrà un po' di tempo per accertare le vere intenzioni del Syndicate, ma il loro evidente legame con la magia oscura e demoniaca mi preoccupa. Ti dirò quando ne saprò di più.", enHash = "462afe96", vanilla = true },
    },
    [672] = {
        title = { it = "Risollevare lo spirito", enHash = "16dc4f2b", vanilla = true },
        text = { it = "Abbiamo cercato di farlo ambientare, di tirargli su il morale, raccontandogli della nostra potente città di Orgrimmar, a Kalimdor, ma niente riusciva a smuoverlo.\n\nRacconti del nostro giovane Capoguerra, Thrall, che porta l'armatura e il martello di Orgrim... ma forse... Forse! Una dimostrazione della magia sciamanica che abbiamo ritrovato da poco gli darebbe nuova speranza. Vale la pena tentare!\n\nUn piccolo oggetto che potremmo fare per lui, sì... Portami degli occhi di raptor, e vedrò cosa posso fare.", enHash = "687bbbdb", vanilla = true },
        objectives = { it = "Procura 10 Highland Raptor Eye dagli Highland Strider e dagli Highland Thrasher per Tor'gan, a Hammerfall.", enHash = "f1a28a48", vanilla = true },
        progress = { it = "Creerò un amuleto che darà a Gor'mul un po' della forza dei raptor. Forse risveglierà una fiamma dentro di lui...", enHash = "d137445a", vanilla = true },
        reward = { it = "Eccellente. Gli spiriti dei raptor che hanno dato questi occhi presteranno la loro forza a chi porterà questo amuleto.", enHash = "a91cae79", vanilla = true },
    },
    [673] = {
        title = { it = "Magie immonde", enHash = "318be366", vanilla = true },
        text = { it = "Non ho dubbi che dentro le mura di Stromgarde viva un potente stregone. Di tanto in tanto, con una reliquia magica arcana, questo stregone evoca terribili demoni in gran numero. Dobbiamo eliminare la fonte del suo potere.\n\nTrova lo stregone e uccidilo. Portami qualunque oggetto magico gli trovi addosso, e farò in modo di distruggerlo e di impedire che il suo potere venga usato ancora per portare la corruzione in questa terra.", enHash = "3cc2f656", vanilla = true },
        objectives = { it = "Recupera il Befouled Bloodstone Orb di Marez Cowl e portalo a Tor'gan, a Hammerfall.", enHash = "6ca17d69", vanilla = true },
        progress = { it = "Il bruciore nel mio sangue... cresce ogni giorno. Lo stregone va fermato.", enHash = "2d6f9905", vanilla = true },
        reward = { it = "Le mie notti inquiete diventeranno sonni tranquilli quando avrò distrutto questo globo. Grazie, $N. È un agghiacciante ricordo del terribile potere che i demoni avevano sugli orchi prima che Hellscream li liberasse dalla loro maledizione.", enHash = "22854e85", vanilla = true },
    },
    [674] = {
        title = { it = "Risollevare lo spirito", enHash = "16dc4f2b", vanilla = true },
        text = { it = "Ecco, porta questo amuleto a Gor'mul, e vedi se la forza dei raptor riesce a risvegliare la fiamma del guerriero che un tempo gli ardeva nelle vene.", enHash = "4fc63886", vanilla = true },
        objectives = { it = "Dai il Raptor Talon Amulet a Gor'mul.", enHash = "dbf1178c", vanilla = true },
        progress = { it = "Che speranza c'è, quando la mano di un codardo può uccidere il più possente tra i possenti? Che speranza, ti chiedo!", enHash = "86b8152b", vanilla = true },
        reward = { it = "Cos'è questo? Osso levigato. Che me ne faccio di un osso levigato? Un ninnolo riporterà l'Orda alla sua gloria?", enHash = "26de2157", vanilla = true },
    },
    [675] = {
        title = { it = "Risollevare lo spirito", enHash = "16dc4f2b", vanilla = true },
        text = { it = "<Gor'mul getta l'amuleto a terra.>\n\nTi ha mandato Tor'gan, vero? Pah! Non capisco perché provi pietà per me. La pietà mi è stata negata quando non mi è stato permesso di morire in battaglia con il mio Capoguerra. Un colpo crudele mi ha inflitto il destino...", enHash = "6a109ded", vanilla = true },
        objectives = { it = "Parla con Tor'gan.", enHash = "849927d6", vanilla = true },
        reward = { it = "Non ha funzionato, vedo. Tuttavia, sento che mostrargli il potere degli sciamani alla fine riporterà Gor'mul a essere fiero come un tempo. Il potere dell'amuleto non era abbastanza grande per mostrargli il nostro nuovo potere.", enHash = "46ae8402", vanilla = true },
    },
    [676] = {
        title = { it = "Il martello potrebbe cadere", enHash = "2258b7c1", vanilla = true },
        text = { it = "Deboli... tutti quanti. Tu, $C, cos'hai da guardare? Ti credi $Gqualcuno di speciale:qualcuna di speciale;, eh? Perché non lo dimostri?\n\nL'avamposto di Hammerfall, in Arathi, è sotto attacco. Se non mandiamo aiuto presto, la loro fine è vicina.\n\nMa prima di correre via, forse ti conviene mettere alla prova le tue capacità. A nord-est di Stromgarde, in Arathi, c'è un tumulo di ogre abitato dalla tribù Boulderfist. Quando te la saprai cavare con gli ogre e gli enforcer che ci sono là, va' a rapporto da Drum Fel, a Hammerfall.", enHash = "9618cdfe", vanilla = true },
        objectives = { it = "Uccidi 8 Boulderfist Ogre e 10 Boulderfist Enforcer, poi trova Drum Fel all'avamposto di Hammerfall, nelle Arathi Highlands.", enHash = "81659e37", vanilla = true },
        progress = { it = "Non ho tempo di affilare la mia ascia, figuriamoci di lasciare l'avamposto per uccidere quelle bestie che vogliono uccidere i miei simili.\n\nNon sembri avere l'esperienza di un grunt, figuriamoci quella di $Gun vero e proprio:una vera e propria; $C. Cosa vuoi, $N?", enHash = "0d1835bd", vanilla = true },
        reward = { it = "Allora, ti credi abbastanza forte da aiutare Hammerfall? E sia.\n\nO Tallow ti ha mandato a quel tumulo di ogre sperando che ti facessi ammazzare, o ti crede abbastanza forte da aiutarci. In un modo o nell'altro adesso sei qui, e a me servono altri soldati nella lotta contro questi attacchi continui.\n\nSe hai intenzione di fermarti a Hammerfall, riposati e torna a parlarmi quando sei $Gpronto:pronta;. Di battaglie da combattere ce n'è in abbondanza.", enHash = "221f9462", vanilla = true },
    },
    [677] = {
        title = { it = "Chiamata alle armi", enHash = "b408605a", vanilla = true },
        text = { it = "I troll Witherbark e gli ogre Boulderfist di Arathi collaborano per cacciarci da questa terra, ma non incontreremo il nostro destino per mano loro, né di nessun altro. Li uccideremo e mostreremo loro che anche noi abbiamo una casa qui.\n\nI troll ci hanno voltato le spalle; gli ogre ci userebbero come cibo e come giaciglio, se glielo permettessimo: tutto questo non accadrà.\n\nCominciamo il nostro attacco contro i troll Witherbark a sud di qui. Uccidili a frotte, e torna solo quando i loro accampamenti saranno inondati di sangue.", enHash = "47554b72", vanilla = true },
        objectives = { it = "Uccidi 10 Witherbark Axe Thrower, 10 Headhunter e 8 Witch Doctor, e torna da Drum Fel all'avamposto di Hammerfall.", enHash = "5446558b", vanilla = true },
        progress = { it = "Se non hai ancora portato a termine il mio compito, forse sei $Gun vigliacco:una vigliacca; di cuore, oltre che $Gun principiante:una principiante; in guerra.", enHash = "3d76cdd8", vanilla = true },
        reward = { it = "I segni della guerra sono sui tuoi abiti, e il sudore ti gocciola dalla fronte. Bene, davvero molto bene.", enHash = "1cf7789b", vanilla = true },
    },
    [678] = {
        title = { it = "Chiamata alle armi", enHash = "b408605a", vanilla = true },
        text = { it = "La tua forza è evidente, $N. Ora vediamo come te la cavi contro un vero nemico.\n\nI Boulderfist hanno una tana a sud-ovest di qui, verso il ponte dei nani, e, se non mi sbaglio, i picchiatori e i maghi che ci vivono saranno per te una sfida più grande: finora lo sono stati per noi.\n\nUccidine quanti più puoi e vieni da me in carne e ossa se ci riesci, o in spirito se fallisci. In entrambi i casi loderò la tua tenacia in battaglia.", enHash = "cc5bf57e", vanilla = true },
        objectives = { it = "Uccidi 10 Boulderfist Brute e 4 Boulderfist Magus, e torna da Drum Fel all'avamposto di Hammerfall.", enHash = "d1c236e1", vanilla = true },
        progress = { it = "Esiti. Perché? Finora hai dimostrato grande forza, $N. Non deludermi proprio adesso.", enHash = "4375a9bc", vanilla = true },
        reward = { it = "Sei forte come un kodo, e la tua sete di battaglia fa onore al tuo popolo.", enHash = "38e15e86", vanilla = true },
    },
    [679] = {
        title = { it = "Chiamata alle armi", enHash = "b408605a", vanilla = true },
        text = { it = "La testa della bestia è pronta per essere mozzata... con grande forza, $N. Hai dato ogni prova di poterci aiutare a sferrare questo potente colpo finale. I capi di questi attacchi hanno fatto la loro tana tra le rovine di Stromgarde, simbolo lampante della fragilità umana.\n\nTrova e uccidi quei Boulderfist Lord e gli sciamani loro tirapiedi che vorrebbero cacciarci da queste terre.", enHash = "8e576627", vanilla = true },
        objectives = { it = "Uccidi 15 Boulderfist Shaman e 10 Boulderfist Lord e torna da Drum Fel all'avamposto di Hammerfall.", enHash = "b94a4ed3", vanilla = true },
        progress = { it = "Vedo che il tuo coraggio finalmente vacilla. Pare che il mio istinto su di te avesse ragione: la tua forza non è niente in confronto alla tua spavalderia.\n\nTorna da me quando la testa della bestia sarà stata mozzata, o non tornare mai più.", enHash = "f705f669", vanilla = true },
        reward = { it = "Fai onore al tuo popolo, $N. La minaccia si è molto ridotta, e sono certo che cominceremo a prosperare qui nelle Highlands.", enHash = "1f297853", vanilla = true },
    },
    [680] = {
        title = { it = "La vera minaccia", enHash = "a1d2f9ad", vanilla = true },
        text = { it = "Servi bene mio marito, $C, ma lui non sa perché Hammerfall è sotto attacco.\n\nOr'Kalar, la pedina di Mug'thol a Stromgarde, nutre un odio profondo per mio marito, e non desidera altro che la sua morte, per averlo sconfitto anni fa.\n\nLe mie divinazioni mi dicono che Or'Kalar ha teso una trappola a mio marito, perciò gli ho nascosto i segni della presenza dell'ogre.\n\nSe mio marito scoprisse dove si trova l'ogre, si precipiterebbe là come uno sciocco, e io vorrei chiederti di aiutarmi a uccidere la creatura.", enHash = "47bd4bdd", vanilla = true },
        objectives = { it = "Uccidi Or'Kalar e porta Or'Kalar's Head a Korin Fel, all'avamposto di Hammerfall.", enHash = "efa3b8ad", vanilla = true },
        progress = { it = "Vicino alla Tower of Arathor: è lì che troverai Or'Kalar. La sua morte fermerà gli attacchi a Hammerfall e proteggerà la vita di mio marito.\n\nVedo nei tuoi occhi che mi credi debole, persino senza onore, per il mio silenzio. Un giorno imparerai cosa significa amare come amo io. Forse allora capirai che esiste un altro tipo di forza e di onore.\n\nNel frattempo, fa' come ti chiedo e uccidi Or'Kalar.", enHash = "c493225d", vanilla = true },
        reward = { it = "Mi hai reso un grande servizio, $N. Sappi che grazie alle tue azioni la vita di mio marito e la sicurezza di Hammerfall sono salve per un altro giorno. Ti prego, accetta questo come ricompensa per il tuo coraggio.", enHash = "1325b959", vanilla = true },
    },
    [681] = {
        title = { it = "Northfold Manor", enHash = "13d8a6a3", vanilla = true },
        text = { it = "Stiamo combattendo una guerra per Stromgarde, e la stiamo perdendo. Gli ogre, il Syndicate e noi ci siamo divisi la nostra città un tempo grande, e ogni fazione combatte le altre in uno stallo sanguinoso.\n\nMa le nostre forze diminuiscono mentre il nemico cresce.\n\nCi serve aiuto dalla città di Southshore, ma è difficile ricevere rifornimenti finché il Syndicate controlla il territorio tra noi.\n\nVa' alla base del Syndicate a Northfold Manor e uccidili. Allora, forse, la pressione sui nostri convogli di rifornimenti diminuirà e ne arriveranno di più.", enHash = "5a46a052", vanilla = true },
        objectives = { it = "Uccidi 10 Syndicate Highwayman e 6 Syndicate Mercenary.\n\nTorna da Captain Nials, a Refuge Pointe.", enHash = "ff91b75d", vanilla = true },
        progress = { it = "$N, ogni ora che passa la nostra presa su Stromgarde si fa più debole. Devi sbrigarti, o la nostra città cadrà di sicuro.", enHash = "52271162", vanilla = true },
        reward = { it = "Molto bene, $N. Con la morte di quei membri del Syndicate dovremmo ricevere più facilmente i rifornimenti da Southshore.\n\nForse la nostra causa ha ancora speranza.", enHash = "381d0465", vanilla = true },
    },
    [682] = {
        title = { it = "Stromgarde Badges", enHash = "6f00bb26", vanilla = true },
        text = { it = "A Stromgarde il Syndicate combatte contro il nostro contingente di miliziani. Per spingere la marmaglia a battersi contro le nostre truppe, più disciplinate, i capi del Syndicate hanno messo una taglia sui nostri soldati: pagano in oro ogni Stromgarde Badge preso ai miliziani uccisi.\n\nVogliamo recuperare quei distintivi: non possiamo permettere a quei tagliagole di prendersi trofei dai nostri coraggiosi caduti!\n\nEntra nella zona di Stromgarde controllata dal Syndicate e dai loro la caccia per riprenderti i nostri distintivi.", enHash = "dbceeda4", vanilla = true },
        objectives = { it = "Porta gli Stromgarde Badge a Captain Nials, a Refuge Pointe.", enHash = "29c5f31a", vanilla = true },
        progress = { it = "Hai recuperato qualche Stromgarde Badge, $N? Il Syndicate deve imparare che non può trarre profitto dai nostri morti.", enHash = "eb25d337", vanilla = true },
        reward = { it = "Grazie, $N. Informeremo le famiglie di questi soldati che sono caduti in battaglia.\n\nSarà una triste notizia da portare, ma è meglio dell'incertezza per una persona cara scomparsa.", enHash = "bd80eb3f", vanilla = true },
    },
    [683] = {
        title = { it = "La supplica di Sara Balloo", enHash = "da3ca72a", vanilla = true },
        text = { it = "$N, ho solo una piccola richiesta da farti.\n\nPorta questo biglietto che ho preparato al nostro grande sovrano di Ironforge, King Magni Bronzebeard. È un compito da poco per una persona come te, che finora ha dato grandi prove di valore per la causa dell'Alleanza.\n\nPresentarmi davanti al Re nello stato di dolore in cui sono non gioverebbe alla mia causa. Sono certa che capisci.", enHash = "727fbaed", vanilla = true },
        objectives = { it = "Porta il biglietto di Sara Balloo a King Magni Bronzebeard, a Ironforge.", enHash = "21d59ed5", vanilla = true },
        progress = { it = "Quindi sei tu $N, $Gil:la; $C? Le notizie del tuo contributo all'Alleanza sono arrivate piuttosto lontano, lo sai?\n\nPer quale faccenda ti presenti oggi davanti a me?", enHash = "2406656c", vanilla = true },
        reward = { it = "Mi basterà un momento per scorrere questa lettera...", enHash = "2f6851e6", vanilla = true },
    },
    [684] = {
        title = { it = "Wanted! Marez Cowl", enHash = "18e20600", vanilla = true },
        text = { it = "È stata messa una taglia sulla testa di Marez Cowl, consigliera di alto rango e agente del Syndicate. È stata vista l'ultima volta nel territorio di Stromgarde controllato dal Syndicate.\n\nLa taglia si può riscuotere da Captain Nials.\n\nAttenzione: Marez è una strega abile e astuta, nota per i suoi traffici con i demoni. Si raccomanda la massima prudenza a chi le dà la caccia.", enHash = "2d1e2814", vanilla = true },
        objectives = { it = "Porta Marez's Head a Captain Nials, a Refuge Pointe.", enHash = "e8eae1a3", vanilla = true },
        progress = { it = "Salve, $C. Hai un rapporto da fare?", enHash = "a6c6a103", vanilla = true },
        reward = { it = "Hai abbattuto Marez Cowl? Ben fatto, $N. Davvero ben fatto!\n\nMarez minacciava i nostri difensori di Stromgarde, e si dice che facesse da tramite tra il Syndicate e un altro potere, più oscuro. Siamo lieti di sapere che non userà più i suoi poteri contro di noi.", enHash = "5205ea8f", vanilla = true },
    },
    [685] = {
        title = { it = "Wanted! Otto e Falconcrest", enHash = "dcd3208f", vanilla = true },
        text = { it = "La Stromgarde Militia ha messo una taglia sulla testa di Lord Falconcrest e della sua guardia del corpo, Otto. Falconcrest guida le operazioni del Syndicate nelle Arathi Highlands, e la sua morte le metterebbe in grave difficoltà.\n\nLa sua guardia del corpo, Otto, pur non essendo un obiettivo strategico, è un avversario feroce e ha ucciso decine dei nostri difensori.\n\nLe taglie si possono riscuotere da Captain Nials.", enHash = "99680403", vanilla = true },
        objectives = { it = "Porta Otto's Head e Falconcrest's Head a Captain Nials, a Refuge Pointe.", enHash = "80abe4e1", vanilla = true },
        progress = { it = "Salve. Hai un rapporto da presentare?", enHash = "4f3b0271", vanilla = true },
        reward = { it = "Falconcrest e Otto? Magnifico!\n\nEcco la tua ricompensa, $N. Sono felice di pagarla.", enHash = "9779ea2e", vanilla = true },
    },
    [686] = {
        title = { it = "Il tributo di un re", enHash = "b4613fb1", vanilla = true },
        text = { it = "Non mi aspetto che brave nane come Mrs. Balloo capiscano perché le brutture della guerra vadano sopportate per il bene più grande del nostro popolo. La perdita di suo marito, e quella di ogni nano che combatte nel nome dell'Alleanza, mi pesa sull'anima.\n\nNon posso riportare indietro suo marito dal Twisting Nether, ma posso rendergli omaggio.\n\nCommissionerò a Grand Mason Marblesten un memoriale per Sully Balloo.\n\nMandagli parola subito, $C. Sarai tu a portare il mio ordine.", enHash = "d6b9c0aa", vanilla = true },
        objectives = { it = "King Magni Bronzebeard vuole che tu parli con Grand Mason Marblesten.", enHash = "5579c3a7", vanilla = true },
        reward = { it = "Quindi ti manda King Magni Bronzebeard in persona?\n\nPerbacco! Dev'essere una cosa importante!", enHash = "55da4ba8", vanilla = true },
    },
    [687] = {
        title = { it = "Theldurin the Lost", enHash = "37a3c448", vanilla = true },
        text = { it = "Theldurin the Lost un tempo era un membro del nostro ordine, il Martello del Crepuscolo. Ma ha perso il senno e ha disprezzato i nostri insegnamenti. E prima di fuggire da noi, ha rubato la pergamena di Myzrael! Non siamo riusciti a prenderlo, ma si dice che si nasconda nei Badlands, farfugliando come un pazzo.\n\nPer riportare la Signora da noi, devi trovare la pergamena. E per farlo, devi trovare Theldurin.", enHash = "acf62be3", vanilla = true },
        objectives = { it = "Trova Theldurin the Lost.", enHash = "413c6fff", vanilla = true },
        reward = { it = "Ciao. Ciao, ciao ciao ciao ciao CIAO!\n\nMi dispiace... un momento, no, non mi dispiace affatto! Non essere scortese!\n\nOh no... questi sono discorsi da pazzo.\n\nMa... a volte essere pazzo è il mio unico conforto.", enHash = "09a2c8a6", vanilla = true },
    },
    [688] = {
        title = { it = "Gli alleati di Myzrael", enHash = "9e67bb26", vanilla = true },
        text = { it = "<Myzrael parla.>\n\nLibera! SONO LIBERA! Sono libera di raccogliere le forze, nascosta ai miei carcerieri. Perché se mi affrontassero adesso, di certo mi sopraffarebbero e mi imprigionerebbero di nuovo.\n\nMa col tempo affronterò i giganti, e si pentiranno di avermi tenuta prigioniera!\n\nSei $Gun nobile alleato:una nobile alleata;, $N. Col tempo avrò di nuovo bisogno del tuo aiuto. Quando sarò pronta, dovrai evocarmi in superficie.\n\nParla con Zaruk, a Hammerfall. Lui sa come evocarmi.", enHash = "8af29131", vanilla = true },
        objectives = { it = "Parla con Zaruk, a Hammerfall.", enHash = "73f50add", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta;, $C. La Signora mi ha informato del tuo arrivo, e se dobbiamo riportarla in superficie, abbiamo molto di cui parlare...", enHash = "e584fc5e", vanilla = true },
    },
    [689] = {
        title = { it = "Il tributo di un re", enHash = "b4613fb1", vanilla = true },
        text = { it = "Quindi il nostro buon Re vuole un memoriale in onore di un soldato di nome Sully Balloo? E tu dici che il poveretto è morto durante la tragedia del Thandol Span?\n\nBah, ci sarà mai pace su Azeroth?\n\nIn ogni caso, ogni incarico del Re è della massima importanza. Per fare un'opera davvero epica e duratura voglio lavorare con una delle pietre migliori che ci siano. Va' a Darrow Hill, a Hillsbrad, e raccogli per me un po' di Alterac Granite.", enHash = "e9d7b1fd", vanilla = true },
        objectives = { it = "Grand Mason Marblesten, a Ironforge, vuole 5 Alterac Granite.", enHash = "b4242871", vanilla = true },
        progress = { it = "$N, $N, $N! Dimmi che hai abbastanza Alterac Granite perché io possa cominciare il mio capolavoro in onore di Sully Balloo.", enHash = "67f942ce", vanilla = true },
        reward = { it = "Perfetto! Meglio di come potessi immaginare!\n\nE di immaginazione ne ho parecchia, sai...", enHash = "78d273eb", vanilla = true },
    },
    [690] = {
        title = { it = "La richiesta di Malin", enHash = "a840abd8", vanilla = true },
        text = { it = "Salve, $N. Hai l'aria di $Gun avventuriero:un'avventuriera;, e io ho un compito di cui qualcuno deve occuparsi.\n\nArchmage Trelane, il mio primo maestro, è fuggito da Stromgarde, nelle Arathi Highlands, non molto tempo fa, e mi ha chiesto di aiutarlo a recuperare alcune delle cose che ha lasciato indietro.\n\nLa città è caduta sotto assedio e lui ha tentato di difendere la Tower of Arathor, ma senza risultato. Ho già degli agenti nelle Highlands, ma mi hanno chiesto di mandare altro aiuto. Ti interessa?", enHash = "1f2f4572", vanilla = true },
        objectives = { it = "Trova Skuerto a Refuge Pointe, nelle Arathi Highlands.", enHash = "51ed8b0f", vanilla = true },
        reward = { it = "Allora, ti manda Malin? Non m'importa se Muradin è risorto dai morti e ti ha portato qui in volo su un drago. Sono occupato! Parla con Kryten se ti serve qualcosa.", enHash = "ca76de5c", vanilla = true },
    },
    [691] = {
        title = { it = "Vale tanto oro quanto pesa", enHash = "79a4881d", vanilla = true },
        text = { it = "Archmage Malin ha mandato qui Skuerto e me a raccogliere reagenti per lui. Non sapevo proprio come avrei fatto a procurarmi queste cose, ma ora che sei qui credo che il mio problema sia risolto.\n\nMi serve questo: Witherbark Tusk, Witherbark Medicine Pouch e uno Shadow Hunter Knife.\n\nPotresti trovarmeli? I Witherbark vivono nel sud-est di Arathi.", enHash = "ef91b117", vanilla = true },
        objectives = { it = "Trova 10 Witherbark Tusk, 4 Witherbark Medicine Pouch e uno Shadow Hunter Knife per Apprentice Kryten, a Refuge Pointe.", enHash = "1c8d995e", vanilla = true },
        progress = { it = "Hai avuto fortuna finora, $N?\n\n<Kryten prende qualche appunto sul suo diario mentre legge.>\n\nSe le mie ricerche sono corrette, le zanne dovrebbero venire da qualunque troll Witherbark. Le borse di medicine vengono dagli stregoni Witherbark, e i più forti tra i cacciatori delle ombre Witherbark dovrebbero portare il coltello speciale che ricevono dopo aver completato i riti di passaggio. Non c'è modo di sapere quali cacciatori delle ombre abbiano il coltello finché non li affronti.", enHash = "e3f21cb5", vanilla = true },
        reward = { it = "Incredibile! Capisco perché Malin ti ha chiesto di unirti a noi: davvero un ottimo lavoro!\n\nDi questo passo, Skuerto e io torneremo a Stormwind in un attimo.\n\nCredo che il mio compagno nano sia tornato dalla ricognizione di Boulderfist Hall; va' a parlargli quando sei $Gpronto:pronta;.\n\nSembrava che avesse avuto una piccola zuffa con gli ogre. Ma non dirglielo: è molto suscettibile alle critiche sulle sue capacità di esploratore.", enHash = "d1c1a9da", vanilla = true },
    },
    [692] = {
        title = { it = "I frammenti perduti", enHash = "51cd2db6", vanilla = true },
        text = { it = "Lo Scroll of Myzrael... lo Scroll of Myzrael?! Non ti conviene! La sua magia può trascinare Myzrael nel mondo di superficie, e se lo fai, siamo nei guai!\n\nOppure... forse è troppo tardi. Forse è già libera. Forse sta solo raccogliendo le forze prima di scatenarsi su di noi. Se è così, allora ti SERVIRÀ la pergamena!\n\n...peccato che sia distrutta. Degli elementali infuriati l'hanno rubata e fatta a pezzi, e ora si contendono i frammenti.\n\nMa se riesci a raccogliere quei frammenti, forse possiamo aggiustarla...", enHash = "fea668fa", vanilla = true },
        objectives = { it = "Porta il Torn Scroll Fragment, il Crumpled Scroll Fragment e il Singed Scroll Fragment a Theldurin the Lost.", enHash = "cf5ea717", vanilla = true },
        progress = { it = "Hai trovato quei frammenti?! Ti servirà lo Scroll of Myzrael se vuoi intrappolarla di nuovo, prima che sia troppo tardi!", enHash = "dded10fa", vanilla = true },
        reward = { it = "Ah, li hai trovati! Ottimo lavoro, $N! Potrebbero essere l'unica possibilità che abbiamo contro la malvagità di Myzrael!\n\nLasciami solo trovare il mio cricchetto per rattoppi e vedere se riesco a riattaccare questi frammenti...", enHash = "f8e6ee78", vanilla = true },
    },
    [693] = {
        title = { it = "Bacchetta in pugno", enHash = "2d5ec410", vanilla = true },
        text = { it = "Ehi, $N. Scusa se prima sono stato così sbrigativo... e no, non è una battuta sulla mia statura.\n\nHo scoperto dove è finito il primo oggetto di Trelane: ce l'ha Kor'gresh, a Boulderfist Hall. E da come scagliava raffiche di ghiaccio sui suoi simili per tenerli in riga, deve essere vicino a capire come usarne tutti i poteri.\n\nBoulderfist Hall è a sud di qui, e poi a est del Thandol Span. Trova l'ogre e riprendi quella bacchetta.\n\nMentre sei via, penserò a cosa fare con Stromgarde.", enHash = "e82d75db", vanilla = true },
        objectives = { it = "Trova Trelane's Wand of Invocation e riportala a Skuerto, a Refuge Pointe.", enHash = "868d5af3", vanilla = true },
        progress = { it = "Il nostro obiettivo è la bacchetta, $N. Per ora pensa solo a quella.", enHash = "dee455eb", vanilla = true },
        reward = { it = "Magnifico, $N. Un oggetto recuperato, e secondo la mia lista ne mancano altri tre. Gli altri tre oggetti sono tutti a Stromgarde.\n\nRiposati e recupera le forze: la prossima fase del mio piano richiederà un po' più di tempo e di impegno. Torna da me dopo aver mangiato un pasto caldo e aver riposato un po'.", enHash = "55d0d57d", vanilla = true },
    },
    [694] = {
        title = { it = "Le difese di Trelane", enHash = "1a4844b4", vanilla = true },
        text = { it = "Ti sei $Griposato:riposata;?\n\nEcco il prossimo passo: ci sono ogre tutto intorno alla Tower of Arathor, a Stromgarde. Dovremo attivare le difese della torre, se vuoi avere una possibilità contro di loro e arrivare $Gvivo:viva; fino agli oggetti. Per farlo ci servono delle gemme a cui i Boulderfist Shaman si sono affezionati. Le hanno prese dalla torre, ma non resteranno a lungo in mano loro.\n\nProcurati una di quelle gemme e portala a Kryten: conosce l'incantesimo che la farà funzionare come una chiave.", enHash = "a5987986", vanilla = true },
        objectives = { it = "Trova un'Azure Agate e portala ad Apprentice Kryten, a Refuge Pointe.", enHash = "65432008", vanilla = true },
        progress = { it = "$N, eccoti di nuovo. Hai già trovato un'Azure Agate?", enHash = "60582f3e", vanilla = true },
        reward = { it = "Mi stupisci, $N. Ancora un ottimo lavoro.\n\nDammi un momento per lanciare sulla gemma l'incantesimo adatto, e sarai $Gpronto:pronta;.", enHash = "14953056", vanilla = true },
    },
    [695] = {
        title = { it = "L'incantesimo dell'apprendista", enHash = "9bf78687", vanilla = true },
        text = { it = "Ecco a te, $N. Per attivare le difese della torre basta premere la gemma contro uno dei piedistalli vicino alla sua base. Usala quando sarai $Gpronto:pronta; a entrare nella torre per trovare gli oggetti rimasti di Trelane.\n\nBuona fortuna. Aspetterò il tuo ritorno qui all'accampamento. Ah, e parla con Skuerto prima di partire. Ti darà il resto dei dettagli che ti servono.", enHash = "57a239b7", vanilla = true },
        objectives = { it = "Parla con Skuerto.", enHash = "1b873300", vanilla = true },
        reward = { it = "Bene, bene.\n\nSe non ci sono altri ritardi, che ne dici di cominciare?", enHash = "af3b100f", vanilla = true },
    },
    [696] = {
        title = { it = "Attacco alla torre", enHash = "54d2e071", vanilla = true },
        text = { it = "Ecco cosa cerchi: Trelane's Phylactery, Trelane's Orb e Trelane's Ember Agate.\n\nTutti e tre dovrebbero trovarsi in alcuni forzieri dentro la torre, e non dovresti avere problemi ad aprirli da $Gsolo:sola;; devi solo fare attenzione agli ogre.\n\nLe difese della torre non basteranno a sistemarli: dovrai tenere le armi pronte. Se quegli ogre scoprono che sei lì a derubarli, te la faranno pagare cara.\n\nSta' $Gattento:attenta;, e buona fortuna.", enHash = "f71ba0e0", vanilla = true },
        objectives = { it = "Trova Trelane's Phylactery, Trelane's Orb e Trelane's Ember Agate, e riportali a Skuerto, a Refuge Pointe.", enHash = "613f9eef", vanilla = true },
        progress = { it = "Fai questo, e sono sicuro che Malin sarà più che soddisfatto di te.", enHash = "2bddbcba", vanilla = true },
        reward = { it = "Malin non avrebbe potuto chiedere a una persona più degna di venire qui ad aiutarci, $N. Hai fatto un lavoro magnifico!\n\nSarà contento di vedere che successo travolgente è stata la nostra missione.", enHash = "524caba2", vanilla = true },
    },
    [697] = {
        title = { it = "La richiesta di Malin", enHash = "a840abd8", vanilla = true },
        text = { it = "Porta questa lettera a Stormwind e fai sapere a Malin che Kryten e io torneremo presto a casa. Ti ricompenserà bene per averci aiutato qui, $N, non ne ho alcun dubbio.\n\nFa' buon viaggio.", enHash = "d0e5025b", vanilla = true },
        objectives = { it = "Porta la Sealed Letter ad Archmage Malin, nel Mage Quarter di Stormwind.", enHash = "0f812be7", vanilla = true },
        progress = { it = "Sì? Hai un'aria vagamente familiare. Chiedo scusa, ma ci siamo già conosciuti? Sono così impegnato che perdo il filo.", enHash = "0fc3330b", vanilla = true },
        reward = { it = "<Archmage Malin apre la lettera e sgrana gli occhi.>\n\nPer la Luce, ce l'hai fatta. Meraviglioso. Trelane sarà contentissimo. Sono sicuro che Kryten e Skuerto siano entusiasti quanto me di vederli in viaggio verso Stormwind.\n\nGrazie, $N. Ti prego, prendi questo: ti aiuterà nei tuoi viaggi.", enHash = "4c046694", vanilla = true },
    },
    [698] = {
        title = { it = "Scorte insufficienti", enHash = "1aecba04", vanilla = true },
        text = { it = "Sto cercando di mettere insieme un po' di provviste per il nostro avamposto vicino alla spiaggia, a est. Tok'Kar fa quel che può, ma tra i turni di guardia e il cucinare per i suoi soldati non gli resta molto tempo durante il giorno.\n\nA loro piace cucinare un po' di carne di sawtooth quando possono, ma non ho avuto tempo di mandargli un altro carico. Ti spiacerebbe dargli una mano?\n\nI sawtooth giovani non sono saporiti come quelli più vecchi, quindi lasciali stare; dagli un anno o due per crescere del tutto.", enHash = "478de948", vanilla = true },
        objectives = { it = "Porta 8 Unprepared Sawtooth Flank a Tok'Kar, nella Swamp of Sorrows.", enHash = "27d39c95", vanilla = true },
        progress = { it = "Lok'tar, $C. Attraversare le paludi non è un rischio da prendere alla leggera. Hai coraggio a metterti alla prova qui.", enHash = "dd04ec87", vanilla = true },
        reward = { it = "Ah! Magnifico. Carne fresca per il fuoco di stasera. Grazie, $N.\n\nHai reso le prossime notti più sopportabili. Il fuoco arde luminoso, e avremo la pancia piena.\n\nÈ una piacevole sorpresa che sia tu a portarci un carico; Dar non è l'orco più attraente su cui qualcuno abbia mai posato gli occhi, ma almeno il suo carattere puzza molto meno del suo odore.", enHash = "4d9b31ef", vanilla = true },
    },
    [699] = {
        title = { it = "Scorte insufficienti", enHash = "1aecba04", vanilla = true },
        text = { it = "Con la minaccia dei murloc lungo la costa, siamo di stanza qui per proteggere Stonard da ogni minaccia in arrivo, o per dare l'allarme se le forze sono troppo grandi. Non ci lascia molto tempo per rilassarci, e un altro po' di aiuto ci farebbe comodo, se puoi.\n\nLe chele dei Sawtooth Snapper, se preparate a dovere, diventano ottime armi. Portami un po' delle loro chele, e farò in modo che tu venga $Gricompensato:ricompensata; con una delle nostre armi, per ringraziarti della carne fresca e della buona compagnia.", enHash = "51c9fbb5", vanilla = true },
        objectives = { it = "Porta 6 Sawtooth Snapper Claw a Tok'Kar, nella Swamp of Sorrows.", enHash = "8b6b649c", vanilla = true },
        progress = { it = "Buon idromele, un fuoco caldo, un esercito di orchi e un arsenale di armi... è tutto quello che ci serve davvero qui sulla costa. Non mi pento del mio posto qui a proteggere Stonard, ma sarebbe bello se un giorno potessimo avere una tana, o almeno una torre.", enHash = "a35a1b17", vanilla = true },
        reward = { it = "Mi fa piacere vederti $Gvivo:viva; e in salute, $N.\n\nQueste chele andranno benissimo. Più armi abbiamo pronte contro gli attacchi, meglio sarà per noi.\n\nMi metterò al lavoro sulla tua arma il prima possibile. Ci vorrà poco. Sono diventato piuttosto abile e veloce nel fabbricarle.", enHash = "a511a9d0", vanilla = true },
    },
    [700] = {
        title = { it = "Il tributo di un re", enHash = "b4613fb1", vanilla = true },
        text = { it = "Ah, che bella pietra viene da Lordaeron. Che peccato che quella terra sia così allo sfascio.\n\nMa il Memoriale è venuto proprio bene! Credo che il Re ne sarà molto soddisfatto.\n\nOra, se ti va, manda parola a Sua Maestà che il Memoriale è finito come richiesto.", enHash = "8164d28a", vanilla = true },
        objectives = { it = "Fa' rapporto a King Magni Bronzebeard.", enHash = "0f92dc9a", vanilla = true },
        reward = { it = "Il granito sembra ben poca cosa in confronto alla vita di un grande nano. Ma nessun nano durerà in eterno su questo pianeta.\n\nSperiamo soltanto che il memoriale resti a ricordare a chi calcherà la grande Azeroth del futuro che è per loro che soldati coraggiosi come Sully Balloo hanno dato la vita con tanto valore.", enHash = "b5d91d7d", vanilla = true },
    },
    [701] = {
        title = { it = "L'astuzia del raptor", enHash = "eaae02e2", vanilla = true },
        text = { it = "Con qualche altro oggetto potrò creare qualcosa che infonderà in Gor'mul l'astuzia del raptor! Con il potere del raptor che gli scorre dentro, Gor'mul conoscerà il nostro nuovo potere e riscoprirà il guerriero che dorme in lui!\n\nMi servono dei Raptor Heart per creare l'oggetto e l'incantesimo.", enHash = "c063e8c6", vanilla = true },
        objectives = { it = "Procura 12 Raptor Heart dagli Highland Fleshstalker per Tor'gan.", enHash = "84992c01", vanilla = true },
        progress = { it = "I miei preparativi sono pronti: mi mancano solo i Raptor Heart.", enHash = "0f750508", vanilla = true },
        reward = { it = "Sì, questi andranno benissimo. Trasferirò il loro potere e lo spirito dei raptor in questo globo. Il globo infonderà in Gor'mul la forza ardente e l'intelligenza del raptor.", enHash = "af0335ca", vanilla = true },
    },
    [702] = {
        title = { it = "L'astuzia del raptor", enHash = "eaae02e2", vanilla = true },
        text = { it = "Prendi questo globo e usa la sua energia per dare a Gor'mul l'essenza del raptor. Di sicuro gli rinvigorirà lo spirito e darà un nuovo scopo alla sua vita. Quando sarà tornato quello di prima, potremo spiegargli come sta oggi l'Orda, e avremo l'aiuto di un grande guerriero nelle nostre battaglie senza fine.", enHash = "571f609f", vanilla = true },
        objectives = { it = "Dai Tor'gan's Orb a Gor'mul.", enHash = "9432a66c", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata; di nuovo, eh? In effetti, ora non potrei desiderare niente di meglio che altra pietà da parte di Tor'gan.\n\nCosa mi porti stavolta? Un pezzo di spago dai colori vivaci, forse? O un pezzo di corda per porre fine a questa mia miseria...", enHash = "e1de35c7", vanilla = true },
        reward = { it = "Almeno stavolta mi porti qualcosa di interessante. Emana uno strano potere...", enHash = "ab048029", vanilla = true },
    },
    [703] = {
        title = { it = "Barbecued Buzzard Wings", enHash = "8bcd3d0f", vanilla = true },
        text = { it = "Oh sì, le mie Barbecued Buzzard Wing sono le preferite di tutti! La salsa è ricca e la carne è saporita. E il profumo farà accorrere gli affamati da miglia di distanza!\n\nHo tutto quello che mi serve per prepararne una porzione. Tutto... tranne le Buzzard Wing!\n\nSe ne vuoi un po', procurami le Buzzard Wing. Portamene abbastanza e magari ti darò anche la ricetta!", enHash = "d56ddf75", vanilla = true },
        objectives = { it = "Porta 4 Buzzard Wing a Rigglefuzz.", enHash = "41b9b41c", vanilla = true },
        progress = { it = "Salve, $N. Mi hai portato le mie ali?", enHash = "4545ce31", vanilla = true },
        reward = { it = "Ah, mi metto subito al lavoro su quelle ali. Quasi quasi ne sento già il sapore!\n\nEd ecco la ricetta, nel caso volessi prepararle da te!", enHash = "3a469dc4", vanilla = true },
    },
    [704] = {
        title = { it = "La sorte di Agmond", enHash = "e7f78122", vanilla = true },
        text = { it = "L'ultimo rapporto che ho ricevuto da Agmond è preoccupante, e ancora di più ora che è morto! Diceva che i suoi scavatori avevano portato alla luce delle \"urne antiche\" nel sito di scavo fuori Uldaman. Temo che le urne trovate in quel sito abbiano aizzato i trogg, proprio come gli idoli che ho trovato qui.\n\nMi servono quelle urne per i nostri studi. Va' al sito di Uldaman, raccogli le urne, poi torna da me.", enHash = "c57146cd", vanilla = true },
        objectives = { it = "Porta 4 Carved Stone Urn a Prospector Ironband, a Loch Modan.", enHash = "5b9cdd95", vanilla = true },
        progress = { it = "Hai trovato quelle urne, $N? Dobbiamo scoprire il legame tra loro e i trogg!", enHash = "ae1738e9", vanilla = true },
        reward = { it = "Ben fatto! Con fortuna e diligenza scopriremo qualunque legame ci sia tra i trogg e questi antichi manufatti.\n\nHai compiuto una grande impresa per i cercatori, $N. I tuoi sforzi non saranno dimenticati. E nemmeno Agmond.", enHash = "d95bb411", vanilla = true },
    },
    [705] = {
        title = { it = "A caccia di perle", enHash = "d2a9fecb", vanilla = true },
        text = { it = "I Badlands sono un posto duro, pieno di predatori feroci e di necrofagi sfrontati. Fa paura, soprattutto a un goblin piccolo e basso come me. Per sopravvivere devo essere furbo!\n\nConosco la ricetta delle Flash Bomb. Le uso per spaventare gli animali. Ma sto finendo uno degli ingredienti: la polvere di perle blu frantumate. Procuramene un po' e ti ripagherò della fatica.\n\nEh, e spero che tu abbia un buon paio di stivali. Le Blue Pearl che mi servono si trovano nei molluschi del Vile Reef.\n\nGià, il Vile Reef, a Stranglethorn!", enHash = "f8932840", vanilla = true },
        objectives = { it = "Porta 9 Blue Pearl a Rigglefuzz, nei Badlands.", enHash = "0be229bf", vanilla = true },
        progress = { it = "Hai preso le mie perle? Sono quasi a corto di Flash Bomb!", enHash = "147edca0", vanilla = true },
        reward = { it = "Andranno benissimo! Devo solo ridurle in polvere... poi mescolarle con un po' di questo e un po' di quello.\n\nAttenti, necrofagi! Preparatevi a restare accecati!", enHash = "8128da30", vanilla = true },
    },
    [706] = {
        title = { it = "Incantamenti di fuoco ardente", enHash = "d0caaa71", vanilla = true },
        text = { it = "Come apprendista di Feranor Steeltoe, ho imparato la sua tecnica speciale per infondere nelle armi incantamenti di fuoco. L'ultima volta che ho avuto sue notizie, lavorava in una fucina con una compagnia di cacciatori, su a Lordaeron.\n\nNon posso dirti troppi dettagli sul procedimento, ma posso dirti che richiede il sangue del cuore ancora pulsante di un raro cucciolo di drago nero. Non ho molto da fare mentre aspetto notizie da Ironforge. Se mi porti un cuore dei cuccioli della Lethlor Ravine, ti mostrerò la mia abilità!", enHash = "51a7279e", vanilla = true },
        objectives = { it = "Procura un Black Drake's Heart per Sigrun Ironhew.", enHash = "8abdf580", vanilla = true },
        progress = { it = "Come va la caccia, $C?", enHash = "da610390", vanilla = true },
        reward = { it = "Ah sì, questo andrà benissimo. Permetterà alle tue armi di colpire con un calore rovente!", enHash = "50dd37b2", vanilla = true },
    },
    [707] = {
        title = { it = "Ironband ha bisogno di te!", enHash = "fcdbe682", vanilla = true },
        text = { it = "$N. Ho ricevuto rapporti da Prospector Ironband, dal suo sito di scavo a Loch Modan: gli serve qualcuno che si muova per un altro dei nostri scavi.\n\nNon ho altri dettagli, ma se hai voglia di sgranchirti le gambe va' a parlare con Ironband.", enHash = "978c742e", vanilla = true },
        objectives = { it = "Parla con Prospector Ironband, all'Ironband's Excavation Site di Loch Modan.", enHash = "a64a048d", vanilla = true },
        reward = { it = "Quindi ti manda Stormpike, eh? Bene.\n\nHo un bel compito per te...", enHash = "4ebeab44", vanilla = true },
    },
    [708] = {
        title = { it = "La scatola nera", enHash = "ca444d3b", vanilla = true },
        text = { it = "La superficie di questa scatola nera di metallo è tutta butterata, come se fosse stata immersa nell'acido: deve essere rimasta a lungo nello stomaco del condor gigante.\n\nRigirando la scatola, trovi un simbolo impresso sul fondo. Sotto il simbolo ci sono le parole:\n\n\"Engine #19 — Ironforge Siege Brigade\"", enHash = "9092bc3c", vanilla = true },
        objectives = { it = "Porta la Corroded Black Box all'Hall of Arms, a Ironforge.", enHash = "a25eab29", vanilla = true },
    },
    [709] = {
        title = { it = "Rimedio alla sventura", enHash = "797d3a87", vanilla = true },
        text = { it = "Povero me! Povero me! Si avvicina una sventura. Ascoltami bene! Una sventura!\n\nNo, non posso parlarne... non posso pronunciare i loro nomi, o potrebbero sentirmi! Ma se scopriamo, sì, se scopriamo di più su di loro... allora forse possiamo capire come sventare i loro piani!\n\nForse.\n\nVa' a Uldaman. No! L'ho detto! Devi trovare... trovare la tavoletta di... Ryun'eh. Sì, trovala! E non farmi pronunciare di nuovo quel nome!\n\nÈ nel profondo di quel luogo, in un antico forziere. È lì che si nasconde... in un forziere costruito prima di qualunque opera dei nani.", enHash = "5ad15c39", vanilla = true },
        objectives = { it = "Porta la Tablet of Ryun'eh a Theldurin the Lost.", enHash = "d603d783", vanilla = true },
        progress = { it = "Hai trovato la tavoletta? Deve contenere dei segreti! Segreti per salvarci!", enHash = "4a4a8e90", vanilla = true },
        reward = { it = "Oh, la fortuna è con noi! Grazie! Forse possiamo ancora salvarci!", enHash = "182a839d", vanilla = true },
    },
    [710] = {
        title = { it = "Studio degli elementi: la roccia", enHash = "54f1f0a3", vanilla = true },
        text = { it = "Qui nelle Badlands mi sono fermato a lavorare al mio ultimo progetto: i miei ceppi di vincolo elementale.\n\nUna volta completati, permetteranno ai maghi di evocare elementali ancora più potenti, da usare per compiti ancora più grandi. Per cominciare, mi servono dei Small Stone Shard per provare alcuni dei miei nuovi incantesimi offensivi, insieme a qualche aggeggio che ho messo insieme.\n\nI frammenti si raccolgono facilmente dai Lesser Rock Elemental, a ovest di qui. Potresti portarmene un po'?", enHash = "773793da", vanilla = true },
        objectives = { it = "Trova 10 Small Stone Shard e portali a Lotwil Veriatus, nelle Badlands.", enHash = "461a4448", vanilla = true },
        progress = { it = "Questa zona è perfetta per — Potresti tenermi fermi questi per un momento? Sì, proprio così, lungo la normale del vettore. Allora, cosa stavo... Ah, sì. Perfetta per provare il mio ultimo progetto. Le materie prime, lo spazio aperto... cosa potrebbe chiedere di più un praticante delle arti intelligente e illuminato?", enHash = "5077c268", vanilla = true },
        reward = { it = "Andranno benissimo, $N. Grazie. Mmh, un po' più di sabbia di quanto mi aspettassi. Dovrò correggere il coefficiente di attrito. No, aspetta; con il Frost Oil dovrebbe restare comunque trascurabile.\n\n<Borbottando tra sé, Lotwil mette un pugno nel palmo dell'altra mano e li fissa come affascinato.>", enHash = "c1057406", vanilla = true },
    },
    [711] = {
        title = { it = "Studio degli elementi: la roccia", enHash = "54f1f0a3", vanilla = true },
        text = { it = "$N, ti sei già $Gdimostrato:dimostrata; più capace di tutti i miei apprendisti messi insieme.\n\nI prossimi pezzi che mi servono richiedono un po' più di forza. Se stai $Gattento:attenta;, puoi trovare dei Large Stone Slab sui Rock Elemental. Il loro corpo è più forte e più grande, e quindi è più facile che abbia pezzi abbastanza grandi per le mie prove. Li trovi più a ovest di qui, o a sud-est, lungo i margini delle montagne.\n\nFa' con calma; mi ci vorrà un po' per provare questi pezzi più piccoli che mi hai portato.", enHash = "da9fa485", vanilla = true },
        objectives = { it = "Porta 3 Large Stone Slab a Lotwil Veriatus, nelle Badlands.", enHash = "5399b576", vanilla = true },
        progress = { it = "Sono molto soddisfatto, $N. I miei incantesimi hanno agito sui pezzi più piccoli esattamente come avevo previsto. Se questo esperimento riuscirà come prevedo, gli elementali che potrò controllare faranno sfigurare qualunque cosa sia mai stata evocata prima.", enHash = "ca970210", vanilla = true },
        reward = { it = "$N, semplicemente incredibile! Avrei pensato che ci volesse mezza dozzina di tauren per portarmi tutta questa roba.", enHash = "86d4d184", vanilla = true },
    },
    [712] = {
        title = { it = "Studio degli elementi: la roccia", enHash = "54f1f0a3", vanilla = true },
        text = { it = "$N, mi serve un'ultima parte dagli elementali qui nelle Badlands: i Bracers of Rock Binding dei Greater Rock Elemental. Secondo i miei calcoli, quei bracciali dovrebbero bastare a misurare la forza dei miei ceppi.\n\nI miei tentativi di scrutare i Greater Rock Elemental ne hanno mostrato un gruppo a sud-ovest di qui, vicino ad alcuni ogre, se ricordo bene.\n\nPortamene 5, giusto per averne di scorta. Servo è famoso per smarrire i miei reagenti e le mie ricerche.", enHash = "ce0928e9", vanilla = true },
        objectives = { it = "Porta 5 Bracers of Rock Binding a Lotwil Veriatus, nelle Badlands.", enHash = "68465526", vanilla = true },
        progress = { it = "Le lastre di pietra che hai trovato erano perfette, $N. Lucien riporterà quelle in più a Kharanos quando avremo finito qui. Dopotutto, potrebbero tornare utili.\n\nPer esempio, sarebbero un'ottima base per un comodo rifugio, quando comincerò a studiare un approccio multidisciplinare agli esplosivi ad alto potenziale...\n\n<La voce di Lotwil si spegne mentre torna al suo esperimento.>", enHash = "aedfaf27", vanilla = true },
        reward = { it = "$N, hai mai pensato di diventare assistente di ricerca? No? Non so proprio cosa farò qui senza le tue capacità. Intelligenza, curiosità e forza: tutto in un unico pacchetto.", enHash = "0a12577b", vanilla = true },
    },
    [713] = {
        title = { it = "Vince chi resta freddo", enHash = "22838702", vanilla = true },
        text = { it = "Lascia che ti dica una cosa sul Frost Oil: niente impedisce a un motore o a degli ingranaggi di surriscaldarsi come lui.\n\nLe sue proprietà refrigeranti sono straordinarie, e come lubrificante dura come nessun altro. E non è tutto: aiuta anche a mantenere gli incantamenti sugli oggetti magici.\n\nMe ne serve una fiala per aumentare la capacità magica dei miei ceppi e renderli abbastanza potenti da impedire al nostro amico evocato di ucciderci tutti.\n\nBro'kin, un mio amico goblin, può insegnarti a prepararlo. Si trova ad Alterac.", enHash = "f1d3b76a", vanilla = true },
        objectives = { it = "Trova del Frost Oil e portalo a Lotwil Veriatus, nelle Badlands.", enHash = "ace2895a", vanilla = true },
        progress = { it = "Hai trovato l'olio che mi serve? Mi sarebbe davvero utile se riuscissi a trovarne un po'.", enHash = "e13d64f6", vanilla = true },
        reward = { it = "Stupendo! Dovrebbe essere il refrigerante perfetto per i miei nuovi bracciali. Se gli incantamenti non dureranno un secolo, darò tutti i miei averi a Servo.\n\nTutti i maghi dell'Assembly resteranno a bocca aperta quando avrò finito, $N. Aspetta e vedrai.", enHash = "3936b36d", vanilla = true },
    },
    [714] = {
        title = { it = "Giro... cosa?", enHash = "e0d7d7fa", vanilla = true },
        text = { it = "$N, hai fatto il tuo lavoro ben oltre ogni aspettativa.\n\n<Lotwil è chiaramente distratto dal suo lavoro.>\n\nSe mai ci incontreremo a Kharanos, vieni pure a chiedere lavoro.\n\nOps! Presto, prendi il... sì, quello. Grazie.\n\nOra mi serve solo un'altra cosa. È un pezzo piccolo, ma piuttosto cruciale, temo: un Gyrochronatom.\n\nSe potessi andarne a prendere uno e portarmelo, dovrei essere pronto a completare il lavoro.", enHash = "d578e297", vanilla = true },
        objectives = { it = "Porta un Gyrochronatom a Lotwil Veriatus, nelle Badlands.", enHash = "4dca2859", vanilla = true },
        progress = { it = "Sì, sì, sì. Solo un momento.\n\n<Lotwil continua a lavorare a una specie di congegno.>", enHash = "f0c623de", vanilla = true },
        reward = { it = "AH!\n\n<Lotwil ti strappa di mano il Gyrochronatom.>\n\nPerfetto... ho quasi finito. No, davvero. ORA ho quasi finito. Questo progetto è la mia massima priorità... al momento. Lascia che lo metta al suo posto, e potrai vedere con i tuoi occhi cosa mi hai aiutato a creare. Mi ci vorrà solo qualche altro minuto... forse... magari di più. Be', forse molto di più. Vedremo...", enHash = "f447071b", vanilla = true },
    },
    [715] = {
        title = { it = "Pietra liquida", enHash = "6ae15881", vanilla = true },
        text = { it = "Credo che gli oggetti che hai procurato per Lotwil saranno l'ultimo dei nostri problemi, $N. D'altra parte, ti sei $Gdimostrato:dimostrata; più che abile nelle scienze che Lotwil considera sacre, quindi che ne dici di darmi una mano?\n\nMi servono una pozione d'invisibilità e una Healing Potion; potrebbero tornare utili molto presto, se lui ci riesce.\n\nIn cambio ti darò questa ricetta per una pozione che ho messo a punto mentre imparavo da Lotwil. È basata su alcune delle ricerche che sta facendo qui nelle Badlands.", enHash = "8970f2a4", vanilla = true },
        objectives = { it = "Porta una Healing Potion e una Lesser Invisibility Potion a Lucien Tosselwrench, nelle Badlands.", enHash = "0d67cf17", vanilla = true },
        progress = { it = "Sta per finire. Come vanno le cose dalla tua parte?", enHash = "06e71d26", vanilla = true },
        reward = { it = "SÌ!\n\nCioè, grazie, $N. Queste saranno utili per viaggiare attraverso le Badlands.", enHash = "39dc3ebb", vanilla = true },
    },
    [716] = {
        title = { it = "La pietra è meglio della stoffa", enHash = "d0ffca70", vanilla = true },
        text = { it = "So quanto può essere tirchio Lotwil, $N, quindi lascia che ti prepari qualcosa per tutto il disturbo. Magari ti aiuterà perfino a proteggerti dall'imminente atrocità che è l'ultima invenzione di Lotwil.\n\nHo lavorato con tutte le pietre in più che hai raccolto per lui, e posso farti dei bei bracciali che potrebbero servirti. Incantati, naturalmente.\n\nMi servono solo dei Patterned Bronze Bracers fatti da un fabbro, così posso completare i bracciali che sto preparando per te.", enHash = "43ab2af4", vanilla = true },
        objectives = { it = "Porta dei Patterned Bronze Bracers a Lucien Tosselwrench, nelle Badlands.", enHash = "428e3070", vanilla = true },
        progress = { it = "Non aspetterei troppo a procurarti quel bracciale, $N.\n\nChi sa cosa succederà adesso?", enHash = "da20edae", vanilla = true },
        reward = { it = "Ecco qua, $N. Provali.", enHash = "a7ac7224", vanilla = true },
    },
    [717] = {
        title = { it = "Tremori della terra", enHash = "3a0b73a8", vanilla = true },
        text = { it = "Ormai è evidente che non possiamo garantire che Blacklash e Hematus restino imprigionati a Lethlor. Il fatto che dei draghi neri si siano stabiliti lì, e che gli ogre siano riusciti a rubare il Sign, indica che bisognerà prendere misure più drastiche.\n\nLa prigione dei draghi è mantenuta da tre pietre runiche che si possono recuperare solo usando il Sign of the Earth. Quelle pietre runiche possono poi servire a spezzare il sigillo che li tiene prigionieri.\n\n$N... fa' che i loro sogni siano eterni.", enHash = "dfa3bf2f", vanilla = true },
        objectives = { it = "Usa il Sign of the Earth per attivare il Pillar of Amethyst, il Pillar of Opal e il Pillar of Diamond e ottenere l'Amethyst Runestone, l'Opal Runestone e la Diamond Runestone.\n\nMetti le pietre runiche nel Seal of the Earth per liberare Blacklash e Hematus.\n\nUccidili e riporta Blacklash's Bindings, le Chains of Hematus e il Sign of the Earth a Garek.", enHash = "d414f0e2", vanilla = true },
        progress = { it = "Magie e poteri forti hanno tenuto la prigione dei draghi per tanto tempo, ma non possiamo permettere che ci sia alcuna possibilità che Blacklash e Hematus vengano liberati.", enHash = "4a6fb07c", vanilla = true },
        reward = { it = "Il Kirin Tor non dovrà più preoccuparsi dei prigionieri di Lethlor. Tornerò a riferire il successo al mio maestro. Krasus sarà senza dubbio soddisfatto.", enHash = "10e8dccf", vanilla = true },
    },
    [718] = {
        title = { it = "Miraggi", enHash = "3fa832aa", vanilla = true },
        text = { it = "Nella fretta di lasciare il sito di scavo di Uldaman, siamo stati costretti ad abbandonare molti carri e casse di provviste lungo la strada. Gli ogre del Camp Kosh si sono gettati sulla nostra attrezzatura abbandonata come avvoltoi su una carcassa in putrefazione. E non hanno nemmeno un odore migliore. Delle carcasse, intendo.\n\nComunque, hanno preso il carro che trasportava tutte le nostre armi e roba simile... quindi... be', è un po' imbarazzante... non siamo riusciti a procurarci da mangiare.\n\nSiamo un po' nei guai, qui: pensi di poterci aiutare?", enHash = "031bb8a9", vanilla = true },
        objectives = { it = "Recupera la Supply Crate per Sigrun Ironhew.", enHash = "4f6aac70", vanilla = true },
        progress = { it = "Il deserto è un brutto posto dove avere fame, $Gamico mio:amica mia;, te lo dico io.\n\nEhi... cos'è quello laggiù...", enHash = "8828b1ef", vanilla = true },
        reward = { it = "Grazie mille, $N. Mentre eri via, io... ehm... ho mandato giù una boccata di sabbia. Era...\n\nBe', basta così: stasera usciamo a procurarci del cibo. Mangeremo come re!", enHash = "323e853c", vanilla = true },
    },
    [719] = {
        title = { it = "Un nano e i suoi attrezzi", enHash = "c0b99ed1", vanilla = true },
        text = { it = "Ehi, $N. Sta' $Gattento:attenta; da queste parti. Ci sono nani Dark Iron dappertutto: sembravano del clan Shadowforge.\n\nHanno appena attaccato il sito di scavo dove lavoravo e hanno ucciso quasi tutti, compreso il mio capo, Hammertoe. Ho salvato la pelle per un pelo.\n\nIl sito è appena a nord di qui, e sto cercando un modo per riprenderci un po' delle nostre provviste, soprattutto il mio piccone portafortuna.\n\nTe la senti di darmi una mano? Uno di quei maledetti Dark Iron deve avere il mio piccone! Potrebbe essere uno qualunque di loro.", enHash = "ba8755d2", vanilla = true },
        objectives = { it = "Trova Ryedol's Lucky Pick e riportalo a Prospector Ryedol, a sud dell'Hammertoe's Dig Site.", enHash = "08d22a89", vanilla = true },
        progress = { it = "Non so cosa cercassero gli Shadowforge, ma di sicuro avevano uno scopo.", enHash = "c07ffc95", vanilla = true },
        reward = { it = "Sei $Gil mio salvatore:la mia salvatrice;, $C. Sono contento che qualcuno abbia dato una lezione o due a quegli Shadowforge. Grazie per l'aiuto.", enHash = "af406183", vanilla = true },
    },
    [720] = {
        title = { it = "Un segno di speranza", enHash = "86f487e1", vanilla = true },
        text = { it = "<Sulla mappa c'è un testo scarabocchiato col gesso.>\n\n\"Ryedol,\nmi stanno portando a Uldaman. Manda aiuto.\n— Hammertoe\"", enHash = "1d816da5", vanilla = true },
        objectives = { it = "Trova Prospector Ryedol e digli che Hammertoe Grez è vivo.", enHash = "8d032bb3", vanilla = true },
        reward = { it = "Hammertoe è vivo?! È incredibile, $N!", enHash = "37f785bb", vanilla = true },
    },
    [721] = {
        title = { it = "Un segno di speranza", enHash = "86f487e1", vanilla = true },
        text = { it = "$N, riesci a trovarlo? Riesci a trovare Hammertoe a Uldaman?\n\nSe quei luridi Shadowforge lo tengono in ostaggio per scoprire cosa sa degli scavi dei titani, allora tutta Ironforge potrebbe essere in guai grossi.\n\nÈ da tanto tempo che quei Dark Iron cercano magie per costruire golem più potenti. Anche Hammertoe faceva lo stesso, certo, ma solo per fermarli.\n\nProbabilmente lo tengono in vita finché non scoprono quello che sa. Devi sbrigarti, se vuoi salvarlo!", enHash = "4146850a", vanilla = true },
        objectives = { it = "Trova Hammertoe Grez a Uldaman.", enHash = "559c8f66", vanilla = true },
        reward = { it = "Sì? Mi dispiace... <coff> Mi sento così debole. Puoi avvicinarti, $C?\n\nTi manda Ryedol? Sia lodato Muradin, quel ragazzo non è lento di comprendonio come pensavo una volta. <coff>", enHash = "24b7c0fd", vanilla = true },
    },
    [722] = {
        title = { it = "L'amuleto dei segreti", enHash = "99c877a8", vanilla = true },
        text = { it = "Hai coraggio... <coff>... a venire a Uldaman per me, $C.\n\nSe sei davvero qui per aiutare... il vecchio Hammertoe, allora... <coff>... devi trovare... il mio amuleto.\n\nCe l'ha Deepshadow... Magregan Deepshadow. È da queste parti... di sicuro tra le rovine. Quell'amuleto li porterà... <coff>... dritti alle pergamene, se nessuno lo ferma. Tocca a te, $N. Ti prego... prendi quell'amuleto.\n\nLe pergamene aiuteranno di sicuro i Dark Iron a creare golem ancora più potenti. Lo so e basta. Me lo sento nelle ossa.", enHash = "f6e88527", vanilla = true },
        objectives = { it = "Trova Hammertoe's Amulet e riportalo a Hammertoe, a Uldaman.", enHash = "93e1a62f", vanilla = true },
        progress = { it = "Il clan Shadowforge... <coff> è pericoloso. Sta' $Gattento:attenta;. <coff> Devi trovare l'amuleto.", enHash = "2f5f5ea5", vanilla = true },
        reward = { it = "Ah! <coff coff>\n\nLo sapevo che avresti trovato il mio amuleto, $N.\n\n<ansima> Ben fatto davvero, $N. <coff>", enHash = "d22276ae", vanilla = true },
    },
    [723] = {
        title = { it = "Un cercatore di fede", enHash = "b57e1e8d", vanilla = true },
        text = { it = "<Hammertoe si tiene le ferite e si prende un momento per ricomporsi prima di parlare di nuovo.>\n\nTrova Ryedol, $N. Portagli il mio amuleto. <coff coff> Lui... <coff> saprà cosa fare. Sa che cercavo le origini del nostro popolo, e lui... <coff>... sa che la mia missione era anche fermare il clan Shadowforge. Non devono trovare le pergamene... <coff>", enHash = "9587a857", vanilla = true },
        objectives = { it = "Porta Hammertoe's Amulet a Prospector Ryedol, nelle Badlands.", enHash = "eec809ad", vanilla = true },
        progress = { it = "Direi che è stata una brutta giornata, ma queste sono le Badlands: ogni giorno è una brutta giornata.", enHash = "fa23174d", vanilla = true },
        reward = { it = "Hammertoe's Amulet? Credo che il mio morale fosse più alto quando lo credevo morto. Saperlo con certezza rende il dolore solo più forte. Questo amuleto era l'opera di tutta la sua vita. Non posso lasciare che sia morto invano.", enHash = "d0bb6ba2", vanilla = true },
    },
    [724] = {
        title = { it = "Un cercatore di fede", enHash = "b57e1e8d", vanilla = true },
        text = { it = "Va bene, va bene... chi potrebbe sapere cosa fare?\n\nHistorian Karnik! Ecco!\n\nÈ a Ironforge. Lui potrà aiutarci. Lui e Hammertoe lavoravano insieme per trovare i manufatti perduti di Uldaman.\n\nSembra che gli Shadowforge abbiano scoperto che quei due ne sapevano più di quanto lasciassero intendere.\n\nRacconta a Karnik cos'è successo a Hammertoe e dagli l'amuleto: ti dirà lui cosa bisogna fare dopo.", enHash = "408c32c2", vanilla = true },
        objectives = { it = "Porta Hammertoe's Amulet a Historian Karnik, a Ironforge.", enHash = "4bb0cf6d", vanilla = true },
        progress = { it = "Ah, sì. $GUn altro viaggiatore:Un'altra viaggiatrice; che cerca qualcosa dai nani.\n\n$GSignore:Signora;, sono davvero spiacente, ma adesso non ho tempo di rispondere a domande inutili.", enHash = { "6d43c191", "b8b8ae34" }, vanilla = true },
        reward = { it = "Oh! Be', questa è tutta un'altra faccenda. Probabilmente non ti rendi ancora conto della gravità della cosa, vero?\n\nLa morte di Hammertoe mi addolora profondamente, ma se ti ha mandato qui con il suo amuleto, allora aveva capito cosa c'è in gioco.\n\nPiangeremo la sua morte più tardi.\n\nLascia che ti mostri uno dei motivi per cui questo amuleto è così prezioso.", enHash = "e0fc9a91", vanilla = true },
    },
    [725] = {
        title = { it = "Avvisare di una minaccia", enHash = "b9d478db", vanilla = true },
        text = { it = "$N, corri a cercare Advisor Belgrum il più in fretta possibile. Digli quello che hai visto e chiedigli come vuole che procediamo. Questo biglietto gli spiegherà il resto.\n\nNel frattempo, mi prenderò il tempo di parlare con lo spirito di Hammertoe. Forse sa qualcosa che ci aiuterà a fermare le attività di quei cretini degli Shadowforge nelle Badlands. Possiamo solo pregare.", enHash = "d6cf4854", vanilla = true },
        objectives = { it = "Trova Advisor Belgrum e consegnagli il suo biglietto.", enHash = "d08cc96f", vanilla = true },
        progress = { it = "Mm? Sì, $C.", enHash = "f6daef9d", vanilla = true },
        reward = { it = "Ah, notizie da Historian Karnik. Eccellente.\n\nPer le sue faccende ho sempre tempo.\n\n<Advisor Belgrum apre il biglietto e comincia a leggere.>", enHash = "b1d90ed2", vanilla = true },
    },
    [726] = {
        title = { it = "Avvisare di una minaccia", enHash = "b9d478db", vanilla = true },
        text = { it = "<Advisor Belgrum arriva in fondo al biglietto, e per un attimo spalanca gli occhi.>\n\nOhi, queste sono notizie funeste.\n\n$N, ti prego, torna da Historian Karnik e digli che, per autorità del re, deve agire su queste informazioni in modo rapido e deciso. Deve fermare le attività degli Shadowforge nelle Badlands.", enHash = "f48775f5", vanilla = true },
        objectives = { it = "Parla con Historian Karnik.", enHash = "a7db13b4", vanilla = true },
        reward = { it = "Stai trattando questa faccenda con un'urgenza che mi aspetterei dal re in persona, $N.\n\nD'accordo, allora. So io cosa metterà in ginocchio gli Shadowforge.\n\nLa loro presenza a Uldaman si può rallentare se li colpiamo nella loro base operativa: Angor Fortress.", enHash = "dc946f8e", vanilla = true },
    },
    [727] = {
        title = { it = "A Ironforge per Yagyin's Digest", enHash = "40ecd33c", vanilla = true },
        text = { it = "La tavoletta dice molto. Ma non abbastanza! Nemmeno lontanamente abbastanza!\n\nC'è un libro, un compendio che Yagyin scrisse in tempi antichi. Le... persone da cui sono fuggito... custodiscono questo libro in molti luoghi. E i più dotti tra loro lo studiano. Contiene un sapere immenso. Un sapere che può proteggerci!\n\nVa' da Gerrig Bonegrip. Ha una bottega a Ironforge, nella Forlorn Cavern. Mostragli questo sigillo e ti crederà $Guno:una; di loro. Chiedigli Yagyin's Digest... e portalo a me!", enHash = "38e3bd00", vanilla = true },
        objectives = { it = "Dai il Sigil of the Hammer a Gerrig Bonegrip, nella Forlorn Cavern, a Ironforge.", enHash = "a5926604", vanilla = true },
        progress = { it = "Salve. $GBenvenuto:Benvenuta; nella mia bottega, ma fa' attenzione a quello che tocchi.\n\nIl sapere può essere letale.", enHash = "e813301b", vanilla = true },
        reward = { it = "Oh. Salve, $Gfratello:sorella;.\n\nE lode a coloro che dimorano nel profondo.", enHash = { "4167f9df", "6a24b815" }, vanilla = true },
    },
    [728] = {
        title = { it = "All'Undercity per Yagyin's Digest", enHash = "387788f1", vanilla = true },
        text = { it = "La tavoletta dice molto. Ma non abbastanza! Nemmeno lontanamente abbastanza!\n\nC'è un libro, un compendio che Yagyin scrisse in tempi antichi. Le... persone da cui sono fuggito... custodiscono questo libro in molti luoghi. E i più dotti tra loro lo studiano. Contiene un sapere immenso. Un sapere che può proteggerci!\n\nVa' da Keeper Bel'dugur, nell'Undercity di Lordaeron. Mostragli questo sigillo e ti crederà $Guno:una; di loro. Chiedigli Yagyin's Digest... e portalo a me!", enHash = "bbd488a0", vanilla = true },
        objectives = { it = "Porta il Sigil of the Hammer a Keeper Bel'dugur, nell'Undercity.", enHash = "73cdb436", vanilla = true },
        progress = { it = "Ah, vedo che abbiamo $Gun:una; $C zelante. Sei qui per imparare dalla mia collezione? Bene!\n\nMa attenzione: come il sapere dà potere ai forti... così fa impazzire i deboli.", enHash = "e79d2c25", vanilla = true },
        reward = { it = "Sii $Gdiscreto:discreta; con i tuoi segni, $C. C'è chi non crede nella giustezza del nostro giuramento.\n\nE c'è chi vorrebbe vederci fallire, se sapesse di noi.\n\nDobbiamo sempre essere prudenti. E vigili. E pazienti.", enHash = "b3908056", vanilla = true },
    },
    [729] = {
        title = { it = "Il cercatore distratto", enHash = "22acfb26", vanilla = true },
        text = { it = "Che onore fu quando Master Greywhisker mi assegnò a lavorare sotto la guida del grande Prospector Remtravel. All'accademia di Ironforge tutti conoscevano le grandi scoperte di Remtravel.\n\nMa il cercatore è piuttosto... ehm... ignaro... di quello che ha intorno.\n\nAvevamo trovato le tracce di una grande civiltà. Golem orribili sono spuntati dal terreno e hanno invaso il sito. Remtravel non sembra essersene mai accorto. Io sono corsa ad Auberdine a cercare aiuto.\n\nTi prego, va' a sud e guarda se il cercatore sta bene!", enHash = "de431993", vanilla = true },
        objectives = { it = "Va' a sud e controlla come sta Prospector Remtravel.", enHash = "ebde6c44", vanilla = true },
        reward = { it = "Hollee, sei tu? Mi serve una mano a scalpellare questa pietra. Passami la spazzola da pietra, mi sa che vedo qualcosa.\n\nEhi, tu non sei Hollee! Non è che hai visto la mia spazzola da pietra?\n\nLascia perdere, adesso! Ho promesso alla Lega che avrei mandato il fossile misterioso che ho trovato. Dov'è finita Hollee?\n\nQuanto lavoro da fare! E ora dov'è quel fossile misterioso... e la mia spazzola... e Hollee...\n\nE tu chi sei... non importa, basta che tu sia qui per aiutare.\n\nFammi sapere quando sei $Gpronto:pronta; a cominciare a cercare.", enHash = "7fea4c57", vanilla = true },
    },
    [730] = {
        title = { it = "Guai a Darkshore?", enHash = "1abb3fda", vanilla = true },
        text = { it = "Che bello vedere $Gun:una; $C che si interessa alle grandi meraviglie archeologiche del nostro mondo.\n\nSpesso il nostro lavoro viene liquidato come un semplice passatempo dai nostri amici dell'Alleanza. Ma quello che molti non capiscono è che le scoperte recenti nel Khaz Modan hanno dimostrato che una forza grande e potente minaccia tutta Azeroth, da Lordaeron a Kalimdor.\n\nSono molto preoccupato per la squadra che ho mandato a Darkshore. Non mandano notizie da settimane.\n\nVa' ad Auberdine e cerca qualche indizio su dove si trovino.", enHash = "5dd54a03", vanilla = true },
        objectives = { it = "Va' ad Auberdine e cerca tracce della squadra di scavo dei nani.", enHash = "5766fb2d", vanilla = true },
        reward = { it = "Sono così contento che Chief Archeologist Greywhisker abbia mandato qualcuno per noi...", enHash = "84d3fae1", vanilla = true },
    },
    [731] = {
        title = { it = "Il cercatore distratto", enHash = "22acfb26", vanilla = true },
        text = { it = "Allora, Hollee... ah già, tu non sei Hollee. Dov'è Hollee?\n\nBah, non è questo il punto. Dobbiamo trovare quella spazzola da pietra... cioè, il fossile misterioso! Dobbiamo trovare quel fossile. La Lega degli Esploratori a Darnassus vorrà qualche indicazione su quello che ho combinato.\n\nFammi sapere quando sei $Gpronto:pronta; e andremo a caccia di quella spazzola... cioè del fossile! Troveremo qualcosa di scritto che soddisfi la Lega.\n\nAllora, sei $Gpronto:pronta;?", enHash = "bf4e6712", vanilla = true },
        objectives = { it = "Proteggi Prospector Remtravel mentre cerca il fossile misterioso, poi torna da Archaeologist Hollee, ad Auberdine.", enHash = "da408ae3", vanilla = true },
        progress = { it = "Il cercatore è vivo?", enHash = "adb5017e", vanilla = true },
        reward = { it = "Siano ringraziate le stelle, Prospector Remtravel è salvo! Te l'avevo detto che era distratto. Non riesco a credere che abbia insistito per restare là in mezzo a tutte quelle creature orribili.", enHash = "f6a51d63", vanilla = true },
    },
    [732] = {
        title = { it = "Tremori della terra", enHash = "3a0b73a8", vanilla = true },
        text = { it = "Sigrun mi ha detto che gli sei $Gstato:stata; di grande aiuto. Forse potrei chiedere il tuo aiuto anch'io. Mi ha mandato qui il mio maestro, Krasus del Kirin Tor, per porre fine ai guai che si stanno preparando nella Lethlor Ravine.\n\nNon posso rivelare la natura esatta del mio incarico qui, né i compiti che devo svolgere, ma stai $Gcerto:certa; che è di vitale importanza.\n\nUna banda di ogre nomadi, che a volte si vedono vicino al Camp Boff, ha rubato un oggetto chiamato Sign of the Earth; devo averlo. Portamelo, e ti dirò di più.", enHash = "ce8a3a66", vanilla = true },
        objectives = { it = "Recupera il Sign of the Earth per Garek.", enHash = "14bfb905", vanilla = true },
        progress = { it = "La banda nomade di ogre si sposta tra i suoi accampamenti in tutte le Badlands; il calore che sale dalla terra arida e i venti vorticosi renderanno difficile seguirne le tracce. Ho sentito che a volte passano per il Camp Boff. Se ti sei $Gperso:persa;, potresti cercare lì.", enHash = "d1d36a0e", vanilla = true },
        reward = { it = "Con il Sign mi porti buone notizie, $N. Il Sign of the Earth fu creato dai nani Dark Iron di Angor Fortress per imprigionare due degli spietati luogotenenti di Deathwing, i gemelli Blacklash e Hematus.", enHash = "310b30aa", vanilla = true },
    },
    [733] = {
        title = { it = "Arrangiarsi", enHash = "1373ef01", vanilla = true },
        text = { it = "Qui sarà dura andare avanti, se non riesco a racimolare un po' di materiali per costruire delle difese e altre cose necessarie. Ho notato che gli ogre della zona sembrano ben forniti di Scrap Metal. Forse le storie sulle macchine d'assedio nelle Badlands non erano poi così lontane dal vero...\n\nComunque, il cercatore si sta preoccupando per lo stato del nostro piccolo accampamento, quindi vorrei mettermi al lavoro presto, se posso.\n\nL'accampamento principale degli ogre è alla Dustbelch Grotto, un bel tratto di cammino a ovest di qui.", enHash = "c1c4bfb2", vanilla = true },
        objectives = { it = "Procura 7 pezzi di Scrap Metal per Sigrun.", enHash = "b99245d4", vanilla = true },
        progress = { it = "Be', ho fatto quel che potevo con quello che avevo, ma... non è molto. Hai trovato altre provviste?", enHash = "c6ea2d0f", vanilla = true },
        reward = { it = "È un inizio, $N, e dovrà bastare finché non avremo notizie da Ironforge o dalla Lega degli Esploratori.\n\nOra, se solo trovassi un po' di sale da qualche parte per la mia tinozza da tempra...", enHash = "c95e75c8", vanilla = true },
    },
    [734] = {
        title = { it = "Sarà dura", enHash = "4efc979d", vanilla = true },
        text = { it = "Meraviglioso, meraviglioso.\n\n<Lotwil alza lo sguardo su di te per un momento, prima di tornare ai suoi ceppi.>\n\nVa' a parlare con Lucien, $N. Mi serve un Cog #5. Me lo porti, vero?", enHash = "93efc2cf", vanilla = true },
        objectives = { it = "Parla con Lucien Tosselwrench, nelle Badlands.", enHash = "686af065", vanilla = true },
        reward = { it = "Un Cog #5, eh? Già, questo non promette niente di buono.", enHash = "1f5cceba", vanilla = true },
    },
    [735] = {
        title = { it = "La stella, la mano e il cuore", enHash = "a7727f01", vanilla = true },
        text = { it = "Yagyin's Digest, eh? Stai fondando un nuovo capitolo del nostro ordine, da qualche parte? Lascia stare, non sta a me chiederlo.\n\nTi aiuterò, perché ne ho una copia in più. Dobbiamo aiutarci a vicenda, no? È così che prosperiamo.\n\nMi servono tre oggetti di potere. Portameli e ti darò il compendio.\n\nNon pronuncerò i loro nomi. Potrebbero esserci orecchie in ascolto. Ma ecco, te li scrivo.", enHash = "25115dbd", vanilla = true },
        objectives = { it = "Porta gli oggetti elencati nella Bonegrip's Note a Gerrig Bonegrip, a Ironforge.", enHash = "1e252580", vanilla = true },
        progress = { it = "Hai le reliquie che ti ho chiesto?", enHash = "05777ac7", vanilla = true },
        reward = { it = "Sei $Gpieno:piena; di risorse, $C. Se il tuo compito è davvero fondare un nuovo capitolo del nostro ordine, credo che lo guiderai bene.", enHash = "3c921a8c", vanilla = true },
    },
    [736] = {
        title = { it = "La stella, la mano e il cuore", enHash = "a7727f01", vanilla = true },
        text = { it = "Ti serve lo Yagyin's Digest? Il tuo piano, quindi, è radunare un altro gregge? Ma certo... e certo che ti aiuterò, $Gfratello:sorella;.\n\nMa anche tu devi aiutare me.\n\nMi servono tre oggetti di potere. Portameli e il compendio sarà tuo.\n\nNon posso pronunciare i nomi di questi oggetti, ma li scriverò.\n\nProcurami gli oggetti di questa lista. Se ci riesci, allora sei davvero $Gdegno:degna; di aprire un tuo capitolo del nostro ordine.", enHash = { "83853983", "e99e9933" }, vanilla = true },
        objectives = { it = "Porta gli oggetti elencati nella Bel'dugur's Note a Keeper Bel'dugur, nell'Undercity.", enHash = "01464f96", vanilla = true },
        progress = { it = "Come procede la tua missione, $C?", enHash = "c9690de2", vanilla = true },
        reward = { it = "Mi hai davvero colpito! Hai grande abilità, o grande fortuna, per aver ottenuto queste reliquie. In ogni caso, sei una risorsa preziosa per noi.", enHash = "1c37d83b", vanilla = true },
    },
    [737] = {
        title = { it = "Il sapere proibito", enHash = "9c5a4517", vanilla = true },
        text = { it = "Ho il compendio per te, $N. Non c'è bisogno che ti dica di averne gran cura. E di tenerlo lontano da mani ostili.\n\nQuesto libro racchiude molte verità...\n\n...E la verità può bruciare.", enHash = "4b35f8bc", vanilla = true },
        objectives = { it = "Porta Yagyin's Digest a Theldurin.", enHash = "b5eb3a33", vanilla = true },
        progress = { it = "Oh! Sei $Gstato:stata; via a lungo. Hai preso il compendio?", enHash = "73d5b2e7", vanilla = true },
        reward = { it = "Ce l'hai! Oh, la speranza riluce!\n\nI tuoi sforzi potrebbero ancora salvarci, $N. Dovrebbero farti un monumento! Dovrebbero costruirti un santuario! Che il tuo nome sia lodato finché i tuoi nipoti non avranno nipoti!\n\nA meno che... LORO non vengano liberati e risalgano in superficie. Se succede, puoi scordarti i figli.\n\nSe LORO vengono liberati, siamo tutti cibo per i vermi.", enHash = "5c2b1c60", vanilla = true },
    },
    [738] = {
        title = { it = "Trova Agmond", enHash = "16c80445", vanilla = true },
        text = { it = "Prospector Agmond dirigeva i nostri siti di scavo nei Badlands, a sud-ovest. Dico \"dirigeva\" perché... be', non ho sue notizie da settimane. Ho bisogno che tu trovi Agmond, così potrò avere il suo rapporto.\n\nL'ultima volta che ne ho avuto notizie, Agmond era al sito di scavo più a sud dei Badlands: un piccolo cantiere oltre l'Angor Fortress. Io comincerei a cercarlo da lì.", enHash = "692ee0e4", vanilla = true },
        objectives = { it = "Trova Agmond.", enHash = "c2388489", vanilla = true },
        reward = { it = "Questo scheletro dev'essere ciò che resta dello sfortunato Agmond. Il suo corpo è spezzato e malridotto, e le sue ossa sono state spolpate.", enHash = "d7ccde81", vanilla = true },
    },
    [739] = {
        title = { it = "Murdaloc", enHash = "30509019", vanilla = true },
        text = { it = "Le tracce di Agmond arrivano da ovest. Dalle strisciate di sangue sulla roccia e sulla sabbia si capisce facilmente che il nano si è trascinato per un bel tratto.\n\nE qui è morto.\n\nOsservando da vicino, si vede la parola \"Murdaloc\" scarabocchiata alla meglio su un tratto di arenaria dei Badlands.\n\nScarabocchiata accanto alla mano morta di Agmond.", enHash = "587e80c8", vanilla = true },
        objectives = { it = "Uccidi l'assassino di Agmond, Murdaloc.\n\nUccidi 12 Stonevault Bonesnapper.\n\nFai rapporto a Prospector Ironband, a Loch Modan.", enHash = "576f7edd", vanilla = true },
        progress = { it = "Hai notizie sulla sorte di Agmond? L'hai trovato?", enHash = "221c6113", vanilla = true },
        reward = { it = "È una notizia amara, $N. Ma Agmond aveva un braccio forte e un colpo di martello feroce, e una testa dura come poche! Anche se è stato ucciso da quei maledetti trogg, sono sicuro che ne ha trascinati parecchi con sé.", enHash = "bc212bb0", vanilla = true },
    },
    [741] = {
        title = { it = "Il cercatore distratto", enHash = "22acfb26", vanilla = true },
        text = { it = "Quindi il cercatore vuole mandare il fossile misterioso alla Lega degli Esploratori, a Darnassus? Non me la sento di lasciare Darkshore senza di lui.\n\nEcco, $N, consegna il fossile misterioso a Chief Archaeologist Greywhisker, a Darnassus.", enHash = "f7a9f88b", vanilla = true },
        objectives = { it = "Porta il fossile misterioso a Chief Archaeologist Greywhisker, a Darnassus.", enHash = "b6a8f776", vanilla = true },
        progress = { it = "Cosa posso fare per te, $R?", enHash = "f6188307", vanilla = true },
        reward = { it = "Perbacco! Ci voleva Prospector Remtravel per fare una scoperta simile!", enHash = "3c4eb0f4", vanilla = true },
    },
    [742] = {
        title = { it = "La caccia di Ashenvale", enHash = "543bb59f", vanilla = true },
        text = { it = "Attenzione, giovani avventurieri! Le terre selvagge di Ashenvale vi aspettano!\n\nL'Orda ha stabilito una presenza solida nelle terre a nord delle Barrens. I nostri due avamposti — Splintertree Post e lo Zoram Strand Outpost — si adoperano per portare gloria all'Orda! Chi vuole mettersi alla prova dovrebbe cercare una guida laggiù. Da notare: Senani Thunderheart, a Splintertree Post, subito a nord delle Barrens, cerca avventurieri disposti a prendere parte a una grande caccia di Ashenvale!", enHash = "d1827415", vanilla = true },
        objectives = { it = "Parla con Senani Thunderheart a Splintertree Post, in Ashenvale.", enHash = "4a6d4371", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta; nella nuova frontiera, $N. Ashenvale è una terra di opportunità, dove $Gun giovane:una giovane; $C come te può trovare occasioni senza fine per dimostrare il proprio valore. Guardati intorno qui all'avamposto, e non mancare di spingerti fino allo Zoram Strand, perché anche lì l'Orda ha un altro avamposto.\n\nLa tua presenza qui mi dice che sei $Gvenuto:venuta; per sapere di più sulla caccia. Ascolta bene, e condividerò volentieri con te quello che ti serve sapere.", enHash = "5155084f", vanilla = true },
    },
    [743] = {
        title = { it = "I pericoli delle Windfury", enHash = "10ede066", vanilla = true },
        text = { it = "Grazie per aver trovato il tempo di parlare con me, $N. Sono Ruul, guerriero e maestro.\n\nÈ evidente che hai raggiunto l'età in cui devi prepararti alle tue prove, se vuoi avventurarti molto più lontano da Mulgore.\n\nSe desideri mettere alla prova la tua forza, comincia cercando le arpie Windfury a sud-est. Fanno il nido lungo i fianchi della montagna, lontano dalla strada.\n\nSono tra i nostri nemici naturali qui a Mulgore, e saranno una buona misura della tua abilità.", enHash = "e24c5a5a", vanilla = true },
        objectives = { it = "Porta 8 Windfury Talon a Ruul Eagletalon, a Bloodhoof Village.", enHash = "be2a8b9f", vanilla = true },
        progress = { it = "Le Windfury sono nemiche letali. La loro forza in battaglia è pari solo alla loro fame di carne fresca.", enHash = "8fb71ccf", vanilla = true },
        reward = { it = "Hai fatto bene, $N. Sembri ben $Gpreparato:preparata; per proseguire il viaggio. Che il vento ti sia sempre alle spalle.", enHash = "61e73656", vanilla = true },
    },
    [744] = {
        title = { it = "Preparativi per la cerimonia", enHash = "5ff0aee2", vanilla = true },
        text = { it = "$N, tra poco mio fratello si presenterà davanti a Chief Bloodhoof, ed è mio onore fargli il copricapo.\n\nVoglio chiederti un favore, mentre finisco di conciare queste cinghie di cuoio. Non ho il tempo di trovare abbastanza piume, e mi chiedevo: me ne raccoglieresti ancora?\n\nPuoi trovare piume della misura giusta dalle arpie che vivono molto a nord e a nord-ovest di Thunder Bluff. Mi servono solo 6 Azure Feather e 6 Bronze Feather per completare il disegno.", enHash = "93dcba27", vanilla = true },
        objectives = { it = "Raccogli 6 Azure Feather e 6 Bronze Feather, e portali a Eyahn Eagletalon a Thunder Bluff.", enHash = "70b7d8b1", vanilla = true },
        progress = { it = "Questo copricapo sarà di sicuro un dono magnifico per mio fratello.", enHash = "97b357e1", vanilla = true },
        reward = { it = "Grazie per il tuo aiuto, $N.\n\nLa mia parte nella cerimonia di mio fratello è quasi compiuta. Consegnargli il copricapo e assistere alla cerimonia è tutto ciò che il mio dovere mi richiede.", enHash = "dee82d8f", vanilla = true },
    },
    [745] = {
        title = { it = "Condividere la terra", enHash = "d32786fe", vanilla = true },
        text = { it = "$N, sono molti i conflitti che feriscono questa terra. Spero che tu non ne veda tanti quanti ne ho visti io. Ce n'è però uno che vorrei chiederti di andare a cercare. Ti darà un'idea di quanto possa essere terribile per la terra anche una piccola minaccia, se la si lascia crescere.\n\nGli gnoll Palemane si sono insediati a sud di Bloodhoof e in una caverna a ovest. Non rispettano i nostri tentativi di comunicare con loro, e uccidono senza freno le creature selvatiche di Mulgore.\n\nLe parole non sono più la risposta.", enHash = "5d86e49b", vanilla = true },
        objectives = { it = "Uccidi 10 Palemane Tanner, 8 Palemane Skinner e 5 Palemane Poacher, poi torna da Baine Bloodhoof a Bloodhoof Village.", enHash = "6feb1865", vanilla = true },
        progress = { it = "Se i Palemane avessero avuto più rispetto per la terra e per i suoi abitanti, questo conflitto non ci sarebbe mai stato.", enHash = "55c9c505", vanilla = true },
        reward = { it = "$N, è bene che tu abbia preso sul serio il mio compito. Il rispetto per la terra e per le sue creature è importante. La morte e la vita sono un cerchio... una necessità. L'una non può esistere senza l'altra. Prenditi il tempo di rifletterci, e fa' in modo di non dimenticarlo mai.", enHash = "1623e86f", vanilla = true },
    },
    [746] = {
        title = { it = "Scavi nanici", enHash = "fb788798", vanilla = true },
        text = { it = "Dei nani stanno preparando un sito di scavo a nord-ovest. Pensano che la terra custodisca dei segreti, ed è vero, ma svuotare e profanare la terra non è il modo per guadagnarsi i suoi insegnamenti.\n\nRaccogli gli attrezzi da scavo dei nani, distruggili, e torna da me con i Broken Tools dei nani.\n\nPuoi distruggere gli attrezzi in una forgia. Ne troverai una a Thunder Bluff, ma andrà bene qualsiasi forgia, anche quella dell'accampamento dei nani.", enHash = "b1a3efff", vanilla = true },
        objectives = { it = "Raccogli 5 Prospector's Pick.\n\nIn una forgia, distruggi le Prospector's Pick per ottenere dei Broken Tools.\n\nPorta 5 Broken Tools a Baine Bloodhoof, a Bloodhoof Village.", enHash = "a28b7062", vanilla = true },
        progress = { it = "Salve, $N. Hai i Broken Tools? Gli scavi dei nani faranno infuriare i kodo di Mulgore. Questa profanazione va fermata!", enHash = "e864d001", vanilla = true },
        reward = { it = "Grazie, $N. Questo calmerà le bestie di Mulgore. E, se gli spiriti vorranno, insegnerà ai nani che svuotare la terra non è la via della conoscenza.", enHash = "e6a20915", vanilla = true },
    },
    [747] = {
        title = { it = "La caccia comincia", enHash = "bd17a8e8", vanilla = true },
        text = { it = "Hai un'aria promettente, e dimostrerai il tuo valore alla tribù. Forse un giorno non lontano sarai $Gaccolto:accolta; nella grande città di Thunder Bluff. Ma prima che accada devi dimostrare il tuo valore a mio padre, Chief Hawkwind.\n\nQui sulla Red Cloud Mesa andiamo fieri della nostra abilità nella caccia. I tauren cacciano per necessità e per sport. Le nostre scorte di carne si sono ridotte e ci servono piume per i vestiti. Caccia i Plainstrider qui vicino e dimostra il tuo valore rifornendo il villaggio.", enHash = "3fd24cf5", vanilla = true },
        objectives = { it = "Grull Hawkwind, a Camp Narache, vuole che tu gli porti 7 Plainstrider Feather e 7 pezzi di Plainstrider Meat.", enHash = "98820e48", vanilla = true },
        progress = { it = "Procurare carne e piume per la tribù è il primo passo per dimostrarti $Gcacciatore:cacciatrice; davanti al Chief.", enHash = "39d91dfb", vanilla = true },
        reward = { it = "I tauren di Narache ti ringraziano, $N. Prometti molto bene.", enHash = "3a1354b5", vanilla = true },
    },
    [748] = {
        title = { it = "Acqua avvelenata", enHash = "bca4e1ff", vanilla = true },
        text = { it = "I goblin e i loro servi hanno contaminato i nostri sacri pozzi d'acqua! Non possiamo permetterlo.\n\nPer purificare ogni pozzo, io devo creare un totem di purificazione, e poi tu devi portare il totem al pozzo e compiere un rituale di purificazione.\n\nPer prima cosa creeremo un totem di purificazione per il Winterhoof Water Well. Per farlo, la terra deve offrire il suo aiuto. Caccia i Prairie Wolf per le loro zampe e gli Adult Plainstrider per i loro artigli. Si trovano a sud-ovest.\n\nTorna da me con le zampe e gli artigli, $N.", enHash = "e0e8e2db", vanilla = true },
        objectives = { it = "Porta 6 Prairie Wolf Paw e 4 Plainstrider Talon a Mull Thunderhorn, a Bloodhoof.", enHash = "b916767d", vanilla = true },
        progress = { it = "Hai le zampe e gli artigli, $N?", enHash = "ed32e081", vanilla = true },
        reward = { it = "Hai fatto bene, $N. Li prenderò e legherò il loro potere in un totem di purificazione.", enHash = "d03b9262", vanilla = true },
    },
    [749] = {
        title = { it = "La Ravaged Caravan", enHash = "d60db313", vanilla = true },
        text = { it = "Qualche giorno fa abbiamo trovato una carovana della Venture Co. che viaggiava sotto scorta sulla riva nord dello Stonebull Lake. In una battaglia precedente avevamo perso due dei nostri, quindi non abbiamo esitato ad attaccare e a distruggere la carovana.\n\nAbbiamo lasciato le loro casse di rifornimenti, pensando che le nostre torce avrebbero distrutto qualunque cosa di valore; ma visto che vicino ai carri bruciati sono stati avvistati dei recuperatori della Venture Co., forse ci sbagliavamo.\n\nForse potresti andare alla carovana ed esaminare il contenuto delle casse.", enHash = "735e9f3f", vanilla = true },
        objectives = { it = "Morin Cloudstalker vuole che tu esamini il contenuto di una cassa di rifornimenti alla Ravaged Caravan.", enHash = "e5d99193", vanilla = true },
        reward = { it = "Su tutti i lati della cassa c'è il marchio della Venture Co. Mining Division. Delle note scritte con cura sul fianco dell'imballaggio indicano che il contenuto deve essere lavorato in uno dei loro impianti centrali.", enHash = "1a82c4bc", vanilla = true },
    },
    [750] = {
        title = { it = "La caccia continua", enHash = "0c2af3ee", vanilla = true },
        text = { it = "Un tauren esperto nelle vie della caccia sa che la sua preda non è un semplice trofeo. Le bestie delle pianure ci danno i mezzi per sopravvivere. Farai una bella impressione sugli anziani se riuscirai a portare indietro qualche preziosa Mountain Cougar Pelt. Le bestie si aggirano tra le colline a sud.\n\nI nostri figli hanno bisogno di vestiti e le nostre tende di essere rammendate.", enHash = "30c90996", vanilla = true },
        objectives = { it = "Grull Hawkwind, a Camp Narache, vuole che tu gli porti 10 Mountain Cougar Pelt.", enHash = "71861249", vanilla = true },
        progress = { it = "Se procuri le pelli per la tribù, riferirò a mio padre, Chief Hawkwind, delle tue azioni generose.", enHash = "2dd9cdf8", vanilla = true },
        reward = { it = "I tauren di Narache ti ringraziano per queste provviste, $N. Con la tua abilità nelle vie della caccia, un giorno sarai di certo $Gvenerato:venerata; a Thunder Bluff.", enHash = "e460899f", vanilla = true },
    },
    [751] = {
        title = { it = "La Ravaged Caravan", enHash = "d60db313", vanilla = true },
        text = { it = "Forzando il coperchio, trovi un assortimento ben stipato di metalli grezzi e minerali, un'altra prova delle attività minerarie della Venture Co. a Mulgore. Da sopra i metalli e i minerali estrai un fascio di documenti ben legato.\n\nSu, tra le colline a est, senti a malapena i rumori di un lavoro in corso, e vedi del fumo salire da un grande fuoco.", enHash = "83559563", vanilla = true },
        objectives = { it = "Riporta i Venture Co. Documents a Morin Cloudstalker, vicino a Bloodhoof Village.", enHash = "bdff72f7", vanilla = true },
        progress = { it = "Salute, $N. Hai scoperto qualcosa di nuovo sui piani e sulle attività della Venture Co. nella nostra terra?\n\nSe intendono sfruttare le nostre terre come hanno fatto con altre, gli Outrunners non tarderanno a porvi fine.", enHash = "9c8008e3", vanilla = true },
        reward = { it = "Sembra proprio che la Venture Co. stia cercando di derubarci delle nostre risorse naturali. È bene saperlo con certezza, e ora, a quanto pare, dobbiamo fare qualcosa.", enHash = "b35eb499", vanilla = true },
    },
    [752] = {
        title = { it = "Un compito umile", enHash = "5d1d80eb", vanilla = true },
        text = { it = "Tutti i membri della tribù condividono l'armonia della vita. Viviamo insieme e lavoriamo insieme.\n\nIl nostro impegno reciproco porta con sé una grande responsabilità. Ora ti chiedo un compito umile.\n\nMia madre è uscita stamattina per andare a prendere l'acqua al pozzo a sud-est di Narache. Ormai è passato parecchio tempo. Potresti andare a vedere come sta, mentre io mi occupo qui delle questioni della tribù?", enHash = "e2680cfb", vanilla = true },
        objectives = { it = "Chief Hawkwind vuole che tu cerchi sua madre vicino al pozzo d'acqua a sud-est di Camp Narache.", enHash = "0c89c077", vanilla = true },
        reward = { it = "Hai fatto tutta questa strada solo per aiutare una vecchia? Ma guarda un po', che tesoro.", enHash = "4a7909d1", vanilla = true },
    },
    [753] = {
        title = { it = "Un compito umile", enHash = "5d1d80eb", vanilla = true },
        text = { it = "Ho percorso molti sentieri nella vita, e queste vecchie gambe non hanno più il vigore di un tempo. Posso ancora svolgere i miei doveri verso la tribù. A volte a una vecchia serve solo un po' più di tempo per fare le cose.\n\nMa tu hai l'aria di $Gun volenteroso:una volenterosa; $C. Mettiamo alla prova un po' di quella vitalità giovanile. Prendi una brocca d'acqua dal pozzo e portala a mio figlio, il Chief, a Camp Narache.\n\nRicorda che anche il compito più umile può guadagnarsi il riconoscimento degli anziani.", enHash = "1e29508d", vanilla = true },
        objectives = { it = "Prendi una Water Pitcher dal pozzo d'acqua.\n\nRiporta la brocca a Chief Hawkwind, a Camp Narache, a nord-ovest del pozzo d'acqua.", enHash = "a0accbd4", vanilla = true },
        progress = { it = "Hai l'aria di essere $Gtornato:tornata; dalle pianure. Hai notizie di Greatmother Hawkwind?", enHash = "b1b2e675", vanilla = true },
        reward = { it = "Hai riportato questa brocca su richiesta della Greatmother, a quanto vedo.\n\nLa tua disponibilità ad aiutare gli altri e a provvedere ai tauren di Camp Narache mi fa credere che un giorno renderesti fiera la tribù a Thunder Bluff.", enHash = "cc44621c", vanilla = true },
    },
    [754] = {
        title = { it = "Purificazione di Winterhoof", enHash = "20596ddb", vanilla = true },
        text = { it = "Ho creato il totem per purificare il Winterhoof Water Well. Ora devi portarlo al pozzo e compiere un rituale di purificazione. Lo troverai a sud-est, sorvegliato da goblin immondi!\n\nNon sarà un compito facile, ma devi portarlo a termine se vogliamo tornare a usare le sue acque.\n\nBuona fortuna, $N.", enHash = "6e40856d", vanilla = true },
        objectives = { it = "Usa il Winterhoof Cleansing Totem al Winterhoof Water Well, poi torna da Mull Thunderhorn.", enHash = "01aee7af", vanilla = true },
        progress = { it = "Non indugiare, $N. La corruzione del Winterhoof Well deve essere rimossa!", enHash = "e379070c", vanilla = true },
        reward = { it = "La notizia della tua impresa mi è giunta poco fa: già le bestie vicino al pozzo ne bevono avidamente.\n\nHai fatto una grande cosa per la terra, $N. E hai fatto una grande cosa per il popolo tauren.", enHash = "c916d7fc", vanilla = true },
    },
    [755] = {
        title = { it = "Riti della Madre Terra", enHash = "15fce5ca", vanilla = true },
        text = { it = "La tua disponibilità a svolgere un compito umile per i tauren di Narache e la tua voglia di imparare sono tratti nobili, $N. Credo che un giorno sarai $Gacclamato:acclamata; a Thunder Bluff come $Gun grande:una grande; $C.\n\nPrima però devi intraprendere i Riti della Madre Terra, che sono tre.\n\nLa prima prova è il Rito della Forza. Va' da Seer Graytongue e digli che ti manda Chief Hawkwind.\n\nTroverai la dimora del veggente subito a sud di Camp Narache, nascosta tra le colline.", enHash = "b4cb5c32", vanilla = true },
        objectives = { it = "Va' da Seer Graytongue, che vive tra le colline subito a sud di Camp Narache.", enHash = "ecbc5a1d", vanilla = true },
        reward = { it = "Ti manda Chief Hawkwind? Intraprendere i Riti della Madre Terra non è cosa da poco...", enHash = "0199821b", vanilla = true },
    },
    [756] = {
        title = { it = "Il totem di Thunderhorn", enHash = "92d2c6c8", vanilla = true },
        text = { it = "Per creare il Thunderhorn Cleansing Totem, devi raccogliere gli artigli dei predatori delle pianure di Mulgore. Caccia i Prairie Stalker per le loro Stalker Claw e i Flatland Cougar per le loro Cougar Claw, poi torna da me.\n\nTroverai i Prairie Stalker e i Flatland Cougar a est e a ovest.", enHash = "010170f0", vanilla = true },
        objectives = { it = "Porta 6 Stalker Claw e 6 Cougar Claw a Mull Thunderhorn.", enHash = "4751040c", vanilla = true },
        progress = { it = "$N, hai gli artigli che ti ho mandato a raccogliere? Il Thunderhorn Water Well diventa più corrotto a ogni ora che passa!", enHash = "6847eeea", vanilla = true },
        reward = { it = "Grazie, $N. La purezza con cui queste bestie cacciano è fondamentale per creare il prossimo totem di purificazione.\n\nI goblin non impareranno mai la differenza tra lottare contro la terra e vivere in armonia con essa.", enHash = "ce056a6b", vanilla = true },
    },
    [757] = {
        title = { it = "Rito della Forza", enHash = "8e18bf32", vanilla = true },
        text = { it = "I Riti della Madre Terra sono i passi che un giovane tauren deve compiere per guadagnarsi il rispetto a Thunder Bluff.\n\nPer prima cosa devi superare il Rito della Forza. In questa prova devi dimostrare il tuo coraggio uccidendo i nemici della tribù.\n\nI Bristleback del Brambleblade Ravine, a est, stanno invadendo le terre della nostra tribù. Tendono imboscate alle nostre battute di caccia e rubano dal villaggio con il buio.\n\nMostra il tuo valore uccidendo quei furfanti e torna dal Chief, a Camp Narache, con le loro cinture come prova delle tue imprese.", enHash = "96db0b22", vanilla = true },
        objectives = { it = "Uccidi i Bristleback nel Brambleblade Ravine e porta 12 Bristleback Belt a Chief Hawkwind, a Camp Narache.", enHash = "827c5a8f", vanilla = true },
        progress = { it = "Hai completato il Rito della Forza, $N? Voglio una prova del tuo valore contro i nemici della nostra tribù, i Bristleback.", enHash = "29f1c13f", vanilla = true },
        reward = { it = "Hai superato la prima prova dei Riti della Madre Terra. La tribù ne sarà fiera.", enHash = "5bb15660", vanilla = true },
    },
    [758] = {
        title = { it = "Purificazione di Thunderhorn", enHash = "9ac657df", vanilla = true },
        text = { it = "Il totem è pronto, $N. E ancora una volta, spetta a te compiere il rituale di purificazione.\n\nVai al Thunderhorn Water Well, a nord del villaggio, e usa il Thunderhorn Cleansing Totem nel tuo rituale. Dopo averlo fatto, torna da me.\n\nChe gli spiriti ti guidino.", enHash = "6e12472f", vanilla = true },
        objectives = { it = "Usa il Thunderhorn Cleansing Totem al Thunderhorn Water Well, poi torna da Mull.", enHash = "34730406", vanilla = true },
        progress = { it = "Il Thunderhorn Water Well è ancora corrotto, $N. Ti prego, devi compiere il rituale!", enHash = "dc2d4754", vanilla = true },
        reward = { it = "Gli antenati del clan Thunderhorn mi hanno parlato in sogno, lodandoti per ciò che hai fatto presso il loro pozzo.\n\nIn segno di gratitudine, desiderano donarti questo...", enHash = "ae0b0d00", vanilla = true },
    },
    [759] = {
        title = { it = "Il totem di Wildmane", enHash = "2a19ccf6", vanilla = true },
        text = { it = "Resta un solo pozzo da purificare, che porta il nome del clan Wildmane. Perché questo pozzo sia puro, la terra deve offrire i denti di un predatore feroce, il Prairie Wolf Alpha. Trova gli Alpha a nord, poi torna da me quando la tua caccia sarà finita.\n\nGli Alpha si aggirano spesso ai piedi della nostra possente città, Thunder Bluff.", enHash = "74c49055", vanilla = true },
        objectives = { it = "Porta 8 Prairie Alpha Tooth a Mull Thunderhorn, a Bloodhoof Village.", enHash = "ebfcb66d", vanilla = true },
        progress = { it = "$N. Hai i denti che ti ho chiesto?", enHash = "7bad1ee2", vanilla = true },
        reward = { it = "Molto bene, $N. Sento il sacrificio della terra in questa offerta, e il mio spirito si riempie di tristezza e di orgoglio.", enHash = "363902da", vanilla = true },
    },
    [760] = {
        title = { it = "Purificazione di Wildmane", enHash = "8da2970d", vanilla = true },
        text = { it = "La tua purificazione dei pozzi di Winterhoof e di Thunderhorn è sulla bocca degli spiriti, giovane $N. Il totem di Wildmane è pronto, e il tuo ultimo compito ti attende.\n\nIl Wildmane Water Well si trova a nord di Thunder Bluff. Compi il rituale! Guarisci la terra dai veleni dei goblin! Fai scorrere di nuovo l'acqua pulita!", enHash = "dadf9516", vanilla = true },
        objectives = { it = "Usa il Wildmane Cleansing Totem al Wildmane Water Well, poi torna da Mull Thunderhorn.", enHash = "cc3870cb", vanilla = true },
        progress = { it = "L'ultimo pozzo è ancora fetido e avvelenato, $N. Non devi indugiare!", enHash = "00c94f16", vanilla = true },
        reward = { it = "Ce l'hai fatta. Hai purificato i pozzi, e guarito la nostra terra. Bloodhoof Village ti è grato, $N.\n\nChe il vento sussurri le tue imprese per cento stagioni, e che le acque di Mulgore restino pure per sempre.", enHash = "94e93393", vanilla = true },
    },
    [761] = {
        title = { it = "Caccia agli Swoop", enHash = "58fb04fb", vanilla = true },
        text = { it = "Lo Swoop è un uccello astuto, difficile da trovare e da cacciare. Una raccolta di Swoop Quill è un segno di ingegno e determinazione per un cacciatore.\n\nSe sei $Gdisposto:disposta; ad accettare questo compito, allora inoltrati nelle pianure e caccia lo Swoop.\n\nPortami le loro penne, e porta onore al tuo clan.\n\nGli Swoop si trovano ovunque a Mulgore, ma i tuoi occhi devono essere acuti per scorgerli, e i tuoi zoccoli veloci per raggiungerli.", enHash = "d32a13a4", vanilla = true },
        objectives = { it = "Porta 8 Trophy Swoop Quill a Harken Windtotem, a Bloodhoof Village.", enHash = "2b91feda", vanilla = true },
        progress = { it = "Hai trovato gli Swoop, $N? Hai le loro penne?", enHash = "dba91666", vanilla = true },
        reward = { it = "So che raccogliere queste penne non è stato un compito facile, $N. Così facendo, dimostri di essere $Gun:una; $C di valore. È bello averti a Bloodhoof Village.", enHash = "28201637", vanilla = true },
    },
    [762] = {
        title = { it = "Un ambasciatore del male", enHash = "79ce74c1", vanilla = true },
        text = { it = "Ambassador Infernus è stato mandato ad Angor Fortress da Ragnaros in persona per sorvegliare gli Shadowforge che cercano i manufatti perduti a Uldaman.\n\nHa già causato perdite enormi al nostro popolo, ma è evidente che la situazione è peggiorata. Esito a immaginare quanti manufatti riuscirebbero a trovare e a usare contro Ironforge.\n\nIl nostro obiettivo è semplice, $C. Torna nelle Badlands e distruggi Ambassador Infernus. Una volta eliminata la minaccia, torna da Advisor Belgrum con una prova della tua vittoria.\n\nOra è nelle tue mani.", enHash = "9a1e4851", vanilla = true },
        objectives = { it = "Uccidi Ambassador Infernus ad Angor Fortress e porta una prova della sua morte ad Advisor Belgrum, a Ironforge.", enHash = "44d1dd88", vanilla = true },
        progress = { it = "Il tempo stringe, $N. Ragnaros non aspetterà che siamo pronti.", enHash = "14ab05bb", vanilla = true },
        reward = { it = "$N, la tua dedizione a Ironforge e al popolo dei nani è indiscutibile. Ti ringrazio per il tuo aiuto in questa faccenda.\n\nManderò notizia a Historian Karnik per informarlo che ce l'hai fatta, e farò anche mandare aiuti nelle Badlands il prima possibile, per aiutare a recuperare il sito di scavo. Grazie ancora.\n\nPrima che tu vada, c'è un'altra cosa che vorrei chiederti in nome di King Bronzebeard.", enHash = "5f1cc515", vanilla = true },
    },
    [763] = {
        title = { it = "Riti della Madre Terra", enHash = "15fce5ca", vanilla = true },
        text = { it = "Per proseguire con i Riti della Madre Terra devi superare altre due prove. È tempo che tu allarghi la tua esperienza, $N.\n\nVa' a Bloodhoof Village e cerca il Chief, Baine Bloodhoof, figlio di Cairne. Là potrai continuare il tuo viaggio e guadagnarti l'accettazione degli anziani di Thunder Bluff.\n\nPorta questo totem a Baine. Riconoscerà i miei intagli e ti aiuterà lungo il cammino.\n\nSegui la strada fuori da Camp Narache e viaggia in fretta. Non allontanarti, o perderai la via.", enHash = "b48a5321", vanilla = true },
        objectives = { it = "Porta il Totem of Hawkwind a Baine Bloodhoof, a Bloodhoof Village. Segui la strada fuori da Camp Narache.", enHash = "4405ec38", vanilla = true },
        progress = { it = "Cosa ti porta al mio villaggio, $C?", enHash = "f61ed1b3", vanilla = true },
        reward = { it = "Notizie dal mio buon amico, Chief Hawkwind! Ah, dai suoi intagli vedo che sei di una stirpe speciale.", enHash = "55734587", vanilla = true },
    },
    [764] = {
        title = { it = "La Venture Co.", enHash = "48a13706", vanilla = true },
        text = { it = "Questo spiega l'aumento di dipendenti e attrezzature della Venture Co. che abbiamo visto a Mulgore. Quei goblin... la loro compagnia si sta espandendo troppo in fretta per il loro stesso bene. Come si dice: mostra qualcosa a un goblin, e sentirai la bilancia in sottofondo.\n\nSono piccole creature avide. Purtroppo per i loro affari, noi tauren non possiamo permettere che operino nelle nostre terre. Vai alla loro miniera a nord-est della Ravaged Caravan e manda loro un messaggio.", enHash = "106aca5a", vanilla = true },
        objectives = { it = "Uccidi 14 Venture Co. Worker e 6 Venture Co. Supervisor per Morin Cloudstalker, a Bloodhoof Village.", enHash = "03b812b4", vanilla = true },
        progress = { it = "Alla Venture Co. sono stati negati i diritti di estrazione qui a Mulgore, ma a quanto pare non accettano un no come risposta. Noi tauren però non siamo tipi da giri di parole, e abbiamo altri modi per far arrivare il nostro messaggio.", enHash = "f515d3c8", vanilla = true },
        reward = { it = "Non credo che quel segnale si possa fraintendere o ignorare più di tanto, eh? La Venture Co. saprà che non deve prendere i tauren alla leggera, né essere così arrogante da credere che le permetteremmo di rubare senza protestare le risorse naturali che ci circondano.", enHash = "0a879421", vanilla = true },
    },
    [765] = {
        title = { it = "Supervisor Fizsprocket", enHash = "25f103d0", vanilla = true },
        text = { it = "Secondo i documenti che hai recuperato dalla carovana, la Venture Co. ha creato molti piani per cercare di cacciarci da queste nostre terre, così da avere mano libera nel saccheggiarle.\n\nLa bassezza a cui sarebbero disposti a scendere pur di raggiungere i loro scopi mi disgusta e mi sconvolge. Voglio che la mente dietro i loro piani venga uccisa. Si chiama Supervisor Fizsprocket: lo troverai alla miniera della Venture Co. a est della Ravaged Caravan. Portami il suo blocco per appunti, vedremo se ne ricaviamo qualcosa di utile.", enHash = "cc0e95e3", vanilla = true },
        objectives = { it = "Uccidi Supervisor Fizsprocket e porta il suo blocco per appunti a Morin Cloudstalker, a Bloodhoof Village.", enHash = "b6f7cd6d", vanilla = true },
        progress = { it = "Ribollo di rabbia al pensiero delle atrocità che la Venture Co. è disposta a commettere contro di noi in nome del profitto.", enHash = "64ade614", vanilla = true },
        reward = { it = "La mia rabbia si placa un poco alla notizia che quel furfante di Fizsprocket è morto. Esaminerò i suoi effetti personali e vedrò se ci sono altre informazioni su cosa la Venture Co. ha in programma per il futuro. Grazie per il tuo impegno, $N.", enHash = "1e4723d0", vanilla = true },
    },
    [766] = {
        title = { it = "Mazzranache", enHash = "59686aea", vanilla = true },
        text = { it = "Mio nonno mi raccontava delle sue battaglie con uno strider di nome Mazzranache. Mi parlava dei suoi demoniaci occhi rossi, degli artigli affilati come rasoi e del morso velenoso.\n\nIl caso ha voluto che, mentre attraversavo le pianure, me lo trovassi davanti, e mi ha dato un brutto morso alla spalla. Era terribile come l'aveva descritto mio nonno. Per ripulire l'infezione del suo morso mi serviranno alcune parti di animali difficili da trovare: un Prairie Wolf Heart, un Flatland Cougar Femur, una Plainstrider Scale e uno Swoop Gizzard.\n\nPresto, il tempo stringe.", enHash = "68f08dd8", vanilla = true },
        objectives = { it = "Porta un Prairie Wolf Heart, un Flatland Cougar Femur, una Plainstrider Scale e uno Swoop Gizzard a Maur Raincaller, a Bloodhoof Village.", enHash = "16dc52be", vanilla = true },
        progress = { it = "La febbre peggiora, e la mia mente scivola in incubi deliranti... Avrei dovuto sapere che una bestia che mio nonno non era riuscito a sconfiggere sarebbe stata troppo per me...\n\nHai gli ingredienti per il rimedio? Temo che, se non ripulisco presto l'infezione, sarà la mia fine.", enHash = "196b34a8", vanilla = true },
        reward = { it = "Ah, grazie, $N. Con gli oggetti che mi hai portato potrò preparare il rimedio che mi serve per fermare l'infezione e, col tempo, guarirla del tutto. Ti devo la vita.\n\nMa non dimenticherò mai quel verso stridulo quando Mazzranache mi è piombato addosso, l'esplosione di colori mentre il suo becco calava...\n\nFai attenzione nei tuoi viaggi.", enHash = "a1d3e4e3", vanilla = true },
    },
    [767] = {
        title = { it = "Rito della Visione", enHash = "45edd319", vanilla = true },
        text = { it = "Il Rito della Visione, uno dei Riti della Madre Terra, ti aiuterà a guadagnare il rispetto degli anziani di Thunder Bluff.\n\nIl nostro popolo ha imparato che la terra è il nostro sostegno più sacro. Per prendere parte alla visione rituale, devi parlare con la guida spirituale del villaggio, Zarlman Two-Moons.", enHash = "571847d4", vanilla = true },
        objectives = { it = "Parla con Zarlman Two-Moons a Bloodhoof Village.", enHash = "adc9d303", vanilla = true },
        reward = { it = "Sentivo che saresti $Gvenuto:venuta; da me, $C. Riconosco sempre chi sta cercando di superare i Riti della Madre Terra.", enHash = "23cd5571", vanilla = true },
    },
    [768] = {
        title = { it = "Raccogliere il cuoio", enHash = "9d028510", vanilla = true },
        text = { it = "Salve, giovane. Hai un luccichio nello sguardo; si vede che sei impaziente di tornare nelle pianure per la caccia. Che tu possa portare onore al tuo clan!\n\nIo lavoro le pelli delle bestie e ne ricavo vestiti e armature per la gente di Thunder Bluff.\n\nSe cacci le bestie e mi porti le loro pelli, allora fabbricherò qualcosa per te.", enHash = "d933e066", vanilla = true },
        objectives = { it = "Porta 12 pezzi di Light Leather a Veren Tallstrider a Thunder Bluff.", enHash = "73f32a8d", vanilla = true },
        progress = { it = "Salve di nuovo. Hai cacciato? Hai delle pelli per me?", enHash = "63d884fd", vanilla = true },
        reward = { it = "Ah, questi sono pezzi molto belli. Ne verranno fuori ottimi articoli di cuoio.\n\nEcco, $N. Prendi questo in cambio...", enHash = "2629a74c", vanilla = true },
    },
    [769] = {
        title = { it = "Kodo Hide Bag", enHash = "3ab2a03b", vanilla = true },
        text = { it = "Le bestie kodo di Mulgore sono forti e robuste — qualità molto rispettate tra noi. Se sei $Gesperto:esperta; di conciatura e desideri la conoscenza per fabbricare un Kodo Hide Bag, allora portami le forniture per il mio mestiere.\n\nFa' questo, e condividerò con te la mia conoscenza.", enHash = "b3eae9c5", vanilla = true },
        objectives = { it = "Porta 4 Light Leather e 4 Coarse Thread a Veren Tallstrider a Thunder Bluff.", enHash = "98b2f622", vanilla = true },
        progress = { it = "Hai le mie forniture, $N?", enHash = "2c3268c2", vanilla = true },
        reward = { it = "Ah, bene. Grazie, $N. Il mio cuore si gonfia d'orgoglio nel vedere dei giovani interessati all'arte della conciatura.", enHash = "dd35e473", vanilla = true },
    },
    [770] = {
        title = { it = "Il Demon Scarred Cloak", enHash = "4e7c177c", vanilla = true },
        text = { it = "La pelle lacera di Ghost Howl porta ancora una ferita terribile, rimediata nelle battaglie del lupo contro la Legione Infuocata.\n\nForse qualcuno a Bloodhoof Village dovrebbe sapere della morte di Ghost Howl...", enHash = "561ee43b", vanilla = true },
        objectives = { it = "Trova qualcuno che conosca Ghost Howl.", enHash = "56501be7", vanilla = true },
        reward = { it = "Stento a credere ai miei vecchi occhi! Hai sconfitto il grande lupo Ghost Howl? Ti guardo con nuovo rispetto, giovane $C. Sei $Gun cacciatore:una cacciatrice; di straordinaria abilità!\n\nLascia che ti offra qualcosa. I miei giorni di caccia sono finiti, ma sarei onorato se usassi una delle mie armi nelle tue cacce.\n\nChe colpisca a segno e ti porti fama.\n\nE speriamo che lo spirito di Ghost Howl abbia finalmente trovato pace.", enHash = "43db5a38", vanilla = true },
    },
    [771] = {
        title = { it = "Rito della Visione", enHash = "45edd319", vanilla = true },
        text = { it = "Per superare il Rito della Visione, devi raccogliere i reagenti necessari a preparare la Water of the Seers.\n\nMi serviranno delle Well Stone, che si trovano intorno ai pozzi d'acqua di Mulgore. A queste unirò l'Ambercorn, che cade sotto i possenti alberi della nostra terra.\n\nQuesti reagenti contengono elementi magici e, preparati e bevuti davanti al fuoco tribale, ti faranno avere una visione. Seguila, e ti condurrà al passo successivo di questa sacra ricerca.", enHash = "873d305d", vanilla = true },
        objectives = { it = "Raccogli 2 Well Stone e 2 Ambercorn e riportali a Zarlman Two-Moons, a Bloodhoof Village.", enHash = "8847d446", vanilla = true },
        progress = { it = "Quando avrai raccolto abbastanza Well Stone intorno ai pozzi d'acqua e Ambercorn sotto gli alberi, preparerò per te la Water of the Seers.", enHash = "1305b491", vanilla = true },
        reward = { it = "Vedo che hai imparato a raccogliere dalla nostra terra sacra, $N. Mi basterà un momento per preparare la Water of the Seers.", enHash = "00946bf7", vanilla = true },
    },
    [772] = {
        title = { it = "Rito della Visione", enHash = "45edd319", vanilla = true },
        text = { it = "Ora ti consegno la Water of the Seers.\n\nQuando sarai $Gpronto:pronta;, bevi le acque vicino al fuoco tribale. Dopo averle bevute, passeranno alcuni istanti prima che la visione prenda forma davanti al fuoco.\n\nA quel punto, starà a te seguirla verso il tuo destino...", enHash = "e92b2726", vanilla = true },
        objectives = { it = "Bevi la Water of the Seers davanti al fuoco tribale di Bloodhoof Village e segui la visione quando appare.", enHash = "b773a386", vanilla = true },
        reward = { it = "Non avere paura, $N. Hai superato il Rito della Visione.", enHash = "30421e61", vanilla = true },
    },
    [773] = {
        title = { it = "Rito della Saggezza", enHash = "47a298f2", vanilla = true },
        text = { it = "Per essere $Gaccettato:accettata; dagli anziani di Thunder Bluff, ora devi completare il Rito della Saggezza.\n\nOra che hai superato il Rito della Visione, gli spiriti degli antenati di Red Rocks ti daranno la benedizione dei nostri avi. Solo chi ha bevuto la Water of the Seers può ricevere la benedizione.\n\nViaggia a est di Thunder Bluff, fino a Red Rocks, e cerca l'Ancestral Spirit, $N.", enHash = "52a9198a", vanilla = true },
        objectives = { it = "Raggiungi Red Rocks, a est di Thunder Bluff, e parla con l'Ancestral Spirit.", enHash = "ce21540f", vanilla = true },
        reward = { it = "Hai dimostrato grande impegno nel tuo desiderio di superare i Riti della Madre Terra, $N.\n\nNoi, gli spiriti degli antenati, rappresentiamo i possenti tauren che diedero coraggiosamente la vita per fondare e proteggere la nostra grande città di Thunder Bluff. Con queste parole affido a te il compito di quella protezione.\n\nHai superato il Rito della Saggezza, giovane $C. Entra a Thunder Bluff con orgoglio.", enHash = "47fa3533", vanilla = true },
    },
    [775] = {
        title = { it = "Viaggio a Thunder Bluff", enHash = "dc05b3cf", vanilla = true },
        text = { it = "Ora sarai $Grispettato:rispettata; nella nostra grande città. Ogni $R $Gdegno:degna; di completare i Riti della Madre Terra si guadagna quell'onore.\n\nPer la tua ultima missione, cerca il nostro nobile capo, Cairne Bloodhoof, che dimora in cima alla mesa più alta di Thunder Bluff.", enHash = "865fa5b4", vanilla = true },
        objectives = { it = "Parla con Cairne Bloodhoof a Thunder Bluff.", enHash = "f9b7a55c", vanilla = true },
        reward = { it = "Salute, giovane $C. Vedo che hai trovato la strada fino alla mia porta.", enHash = "25a147f3", vanilla = true },
    },
    [776] = {
        title = { it = "Riti della Madre Terra", enHash = "15fce5ca", vanilla = true },
        text = { it = "Hai superato i Riti della Madre Terra e ti sei $Gguadagnato:guadagnata; il tuo posto a Thunder Bluff.\n\nMa per mantenere il posto che hai conquistato con tanta fatica, devi continuare a dimostrare il tuo valore al tuo popolo.\n\nNoi siamo cacciatori, $N. Laggiù a Mulgore c'è un possente kodo di nome Arra'chea. Mostrami quanto sai seguire le tracce e cacciare portandomi l'Horn of Arra'chea.", enHash = "fbeb05de", vanilla = true },
        objectives = { it = "Cairne Bloodhoof, a Thunder Bluff, vuole che tu gli porti l'Horn of Arra'chea.", enHash = "2e517768", vanilla = true },
        progress = { it = "Hai già rintracciato Arra'chea?", enHash = "a282fb3e", vanilla = true },
        reward = { it = "Ben fatto! Una bella preda, davvero.\n\nManderò un gruppo a recuperare la carcassa, così potremo ricavarne la pelle e la carne.\n\nHai compiuto una grande impresa per il tuo popolo, $N.", enHash = "a3828576", vanilla = true },
    },
    [777] = {
        title = { it = "Sarà dura", enHash = "4efc979d", vanilla = true },
        text = { it = "Ok, ecco qua.\n\nIo sarò laggiù... al riparo.\n\nSe vuoi, raggiungimi.", enHash = "72311ab0", vanilla = true },
        objectives = { it = "Porta Cog #5 a Lotwil Veriatus.", enHash = "23709c4a", vanilla = true },
        progress = { it = "<Senza alzare gli occhi dai ceppi, Lotwil tende una mano e agita le dita con impazienza.>\n\nL'ingranaggio, $N, l'ingranaggio!", enHash = "354a7ada", vanilla = true },
        reward = { it = "Ah, perfetto. Sta' indietro mentre mi preparo a fare di nuovo la storia!\n\n<Lotwil continua a lavorare febbrilmente.>", enHash = "7ed7fd51", vanilla = true },
    },
    [778] = {
        title = { it = "Sarà dura", enHash = "4efc979d", vanilla = true },
        text = { it = "Ahah! Fatto! I ceppi sono pronti!\n\nÈ il momento, Lucien. È il momento, Servo!\n\nSei $Gpronto:pronta; ad assistere alla fusione perfetta di alchimia, ingegneria e arcano, $N?\n\nOra evocherò un potente elementale. Questo è un giorno rivoluzionario per tutti noi.", enHash = "2b7f6e95", vanilla = true },
        objectives = { it = "Sconfiggi il Fam'retor Guardian e riporta Lotwil's Shackles of Elemental Binding a Lotwil Veriatus.", enHash = "e469cca1", vanilla = true },
        progress = { it = "Non proprio il risultato che mi aspettavo. Potresti recuperare i miei ceppi?", enHash = "926e448f", vanilla = true },
        reward = { it = "Grazie, $N. È stata una bella prova, vero?\n\nNon sono sicuro di cosa possa essere andato storto. Per fortuna c'erano le mie magie, ad aiutare a rimandare la creatura nel suo piano d'origine.\n\nForse un piccolo segno di gratitudine per tutto il tuo duro lavoro...", enHash = "76355de5", vanilla = true },
    },
    [779] = {
        title = { it = "Seal of the Earth", enHash = "10ee8a15", vanilla = true },
        progress = { it = "Qui c'è il Seal of the Earth, con tre nicchie incassate per l'Amethyst Runestone, l'Opal Runestone e la Diamond Runestone.", enHash = "e3b24ad5", vanilla = true },
        reward = { it = "Mentre metti le pietre runiche negli incavi corrispondenti, un violento boato scuote la terra e il sigillo si spezza.", enHash = "5facf87f", vanilla = true },
    },
    [780] = {
        title = { it = "I Battleboar", enHash = "5cea9c0e", vanilla = true },
        text = { it = "I Battleboar del Brambleblade Ravine, a est, stanno invadendo i territori di caccia della nostra tribù. Sono addestrati a essere malvagi dai quilboar Bristleback, con cui siamo in guerra.\n\nVa' a uccidere quelle creature immonde e riporta qualche grugno e qualche fianco, così potremo preparare uno stufato per i nostri piccoli.", enHash = "538bc562", vanilla = true },
        objectives = { it = "Grull Hawkwind, a Camp Narache, vuole che tu uccida i Battleboar e riporti 8 Battleboar Snout e 8 Battleboar Flank.", enHash = "1b4ff621", vanilla = true },
        progress = { it = "L'aggressività dei Battleboar cresce. Hai già mandato loro un messaggio chiaro e riportato qualche grugno e qualche fianco?", enHash = "22c4ca29", vanilla = true },
        reward = { it = "Ottimo. Questi ingredienti faranno un bello stufato, e la perdita di quei cinghiali dovrebbe essere una giusta lezione per quegli immondi Bristleback.", enHash = "c46f552c", vanilla = true },
    },
    [781] = {
        title = { it = "Attacco a Camp Narache", enHash = "faf33e68", vanilla = true },
        text = { it = "Dopo aver esaminato con attenzione la mappa, capisci che quelli che hai scoperto sono i piani preparati dal capoguerra dei Bristleback per un lungo assedio a Camp Narache.\n\nDi sicuro a Chief Hawkwind farebbe comodo questa informazione!", enHash = "5e2eb0c9", vanilla = true },
        objectives = { it = "Porta i Bristleback Attack Plans a Chief Hawkwind, a Camp Narache.", enHash = "8c83cbaa", vanilla = true },
        progress = { it = "Hai un'aria preoccupata, $N. Che notizie porti?", enHash = "a61759d4", vanilla = true },
        reward = { it = "Questo è davvero allarmante! Ma con questa informazione possiamo chiamare i nostri fratelli di Bloodhoof Village ad aiutarci a sventare l'attacco. Hai salvato la vita a molti tauren, $N.", enHash = "8d105ad8", vanilla = true },
    },
    [782] = {
        title = { it = "Alleanze spezzate", enHash = "94c8d491", vanilla = true },
        text = { it = "Dall'alleanza dell'Orda con il drago Deathwing durante la Seconda Guerra, sappiamo che due dei suoi luogotenenti, Blacklash e Hematus, furono imprigionati nella Lethlor Ravine, lontano a est. Dobbiamo mettere a tacere i nostri depravati alleati di un tempo per restituire l'onore all'Orda!\n\nAbbiamo assoldato Tho'grun e la sua banda di mercenari ogre perché ci aiutassero a ottenere il Sign of the Earth, una chiave necessaria per aprire la prigione dei draghi. Ma Tho'grun ci ha traditi: ci ha sopraffatti e l'ha tenuto per sé. Va' al Camp Boff e riprendilo!", enHash = "ea98577c", vanilla = true },
        objectives = { it = "Uccidi Boss Tho'grun e porta il Sign of the Earth a Gorn, a Kargath.", enHash = "a96af498", vanilla = true },
        progress = { it = "Il tradimento di Tho'grun... c'è da stupirsi se gli ogre non fanno più parte dell'Orda? Mi farà piacere vederlo morto, e vedere il Sign of the Earth restituito.\n\nSe non l'hai ancora tolto di mezzo, non perdere tempo e va' al Camp Boff. Si trova a sud-est di Kargath.", enHash = "60a0e1e6", vanilla = true },
        reward = { it = "Con Tho'grun morto, e il suo cadavere spolpato dai venti del deserto e dalle poiane in cerca di carcasse, gli ogre saranno nel caos. Anche se è una piccola vittoria, porterà a una ben più grande.\n\nOra il Sign of the Earth è nelle nostre mani, e possiamo aprire la prigione dei draghi neri a Lethlor. Li libereremo dalla loro prigionia senza fine, anche se per andare incontro alla loro fine!", enHash = "5eff4807", vanilla = true },
    },
    [783] = {
        title = { it = "Una minaccia interna", enHash = "d80443b2" },
        text = { it = "Spero che tu ti sia $Gallacciato:allacciata; bene la cintura, giovane $C, perché qui a Northshire c'è del lavoro da fare.\n\nE non parlo di lavorare i campi.\n\nLe guardie di Stormwind faticano a mantenere la pace qui, con tanti di noi in terre lontane e tante minacce che incombono. Per questo cerchiamo l'aiuto di chiunque sia disposto a difendere la propria casa. E la propria alleanza.\n\nSe sei qui per rispondere alla chiamata, parla con il mio superiore, Marshal McBride. È nell'abbazia, alle mie spalle.", enHash = "6bae89a7" },
        objectives = { it = "Parla con Marshal McBride.", enHash = "549c58b8" },
        reward = { it = "Ah, bene. $GUn altro volontario:Un'altra volontaria;. Ultimamente ne arrivano tanti come te.\n\nSpero che bastino.\n\nLe terre degli umani sono minacciate dall'esterno, e tante delle nostre forze sono state mandate lontano. Questo, a sua volta, lascia spazio a gruppi corrotti e fuorilegge che prosperano entro i nostri confini.\n\nCombattiamo una battaglia su molti fronti, $N. Preparati a una lunga campagna.", enHash = "e6e48b80" },
    },
    [784] = {
        title = { it = "Annienta i traditori", enHash = "0e7a7e15", vanilla = true },
        text = { it = "Guidati da Admiral Proudmoore, gli umani di Kul Tiras hanno invaso Durotar, violando il patto che il Capoguerra aveva stretto con Jaina Proudmoore per sconfiggere Archimonde anni fa.\n\nL'aggressione umana fu respinta e Tiragarde Keep cadde. Ma di recente le riserve dell'Admiral, guidate da Lieutenant Benedict, hanno ripreso la fortezza e minacciano di nuovo la nostra terra. Questi umani non hanno alcun rispetto per la diplomazia.\n\nDimostra il tuo onore e va' a sud, a Tiragarde Keep, a eliminare gli invasori umani.", enHash = "1370530c", vanilla = true },
        objectives = { it = "Uccidi 10 Kul Tiras Sailor, 8 Kul Tiras Marine e Lieutenant Benedict, poi torna da Gar'Thok a Razor Hill.", enHash = "19fe2088", vanilla = true },
        progress = { it = "Hai i tuoi ordini, $N. La sicurezza di Durotar è in gioco. Porta a termine il compito che hai davanti, o china il capo per la vergogna.\n\nMostra il tuo onore e sconfiggi gli umani di Tiragarde Keep.", enHash = "1682215b", vanilla = true },
        reward = { it = "La voce del tuo coraggio corre veloce, $C. I racconti della tua vittoria a Tiragarde Keep saranno annunciati a Orgrimmar.", enHash = "33c54a12", vanilla = true },
    },
    [785] = {
        title = { it = "Un'alleanza strategica", enHash = "dc57dd16", vanilla = true },
        text = { it = "Thrall è un capo saggio e nobile come pochi. La sua tenacia sul campo di battaglia è pari solo al suo tatto diplomatico.\n\nI Darkspear Trolls si sono rivelati alleati preziosissimi per la gente orchesca. Per lealtà e per onore abbiamo giurato con loro un patto di protezione.\n\nIl Capoguerra ha mandato ordine di accertarsi che i nostri amici Darkspear di Sen'jin Village non siano sotto una minaccia diretta. Uno dei loro esploratori più fidati, Lar Prowltusk, tiene d'occhio il loro fianco occidentale.\n\nCerca Lar e aiutalo come serve.", enHash = "5bf753e7", vanilla = true },
        objectives = { it = "Cerca Lar Prowltusk sul fianco occidentale di Sen'jin Village.", enHash = "9bfd3d23", vanilla = true },
    },
    [786] = {
        title = { it = "Sventare l'aggressione dei Kolkar", enHash = "2e09e5c2", vanilla = true },
        text = { it = "Abbassa la voce, $C. I centauri Kolkar stanno appena oltre il crinale a ovest, a Kolkar Crag.\n\nIeri notte, mentre erano fuori a razziare, mi sono intrufolato nel loro villaggio e ho scoperto che quelle sudicie bestie hanno pronto un attacco su tre fronti contro i troll e gli orchi di Durotar.\n\nNon dobbiamo lasciare che la loro invasione si compia. Forse puoi raccogliere la forza necessaria per infiltrarti a Kolkar Crag e distruggere i loro piani d'attacco.\n\nL'ultima volta che ho guardato, li avevano divisi fra tre dei loro capi.", enHash = "d5a9522b", vanilla = true },
        objectives = { it = "Lar Prowltusk, fuori da Sen'jin Village, vuole che tu distrugga i 3 Attack Plans custoditi dentro Kolkar Crag.", enHash = "5589a938", vanilla = true },
        progress = { it = "I centauri si sono dimostrati una seccatura costante per l'Orda. Le loro intenzioni di assediare la nostra terra non si possono tollerare.", enHash = "b9bc6f19", vanilla = true },
        reward = { it = "L'Orda prevarrebbe di sicuro, se i centauri Kolkar attaccassero. Ma impedendo un attacco del genere abbiamo risparmiato ai nostri possenti guerrieri un bagno di sangue inutile.\n\nE com'è certo che c'è sabbia nel deserto di Tanaris, sappiamo che il sangue scorrerà prima che questi tempi difficili siano finiti.\n\nHai servito bene il tuo popolo, $C.", enHash = "26aafdec", vanilla = true },
    },
    [787] = {
        title = { it = "La nuova Orda", enHash = "ffbf8a9d", vanilla = true },
        text = { it = "Throm'ka, $C. Sono Eitrigg: Thrall mi ha incaricato di sovrintendere all'addestramento delle reclute.\n\nL'Orda è cambiata rispetto a com'era un tempo. Ci fu un periodo in cui lasciai l'Orda, disilluso dalla crescente influenza delle pedine della Legione Infuocata, assetate di potere. Durante il mio esilio fui fatto prigioniero da un gruppo di umani, ma il Capoguerra mi salvò. Quando sentii la sua visione di un'Orda libera dall'influenza demoniaca, guidata dagli sciamani, tornai.\n\nGornek ti darà altre istruzioni.", enHash = "934b2a8d", vanilla = true },
        objectives = { it = "Presentati a Gornek nel Den.", enHash = "2e94ae2e", vanilla = true },
        reward = { it = "Un'altra recluta di Eitrigg, eh?\n\nSiamo messi proprio male, se questo è il meglio che l'Orda sa produrre. Poco importa. Quando ti riterremo $Gpronto:pronta; a lasciare la Valley, sarai $Gun fiero guerriero:una fiera guerriera; dell'Orda.", enHash = "2cf571cb", vanilla = true },
    },
    [788] = {
        title = { it = "Farsi le ossa", enHash = "e2662d98" },
        text = { it = "La prima cosa da fare è darti un po' di spina dorsale. Potrei mandarti nelle Barrens a cacciare kodo ma, a dirla tutta, ci servi più $Gvivo:viva; che $Gmorto:morta;.\n\nCredo che i Mottled Boar che troverai a nord di qui siano un avversario alla tua portata.", enHash = "88e34d7a" },
        objectives = { it = "Uccidi 10 Mottled Boar, poi torna da Gornek nel Den.", enHash = "eb7b889e" },
        progress = { it = "Spero che tu non sia $Gtornato:tornata; a cercare di convincermi di aver già finito il tuo compito, $N? No, certo che no. Ti stimo troppo per pensarlo.", enHash = "3e3dc5ce" },
        reward = { it = "Mmm, non male, $N. Ma non montarti la testa... nella tua carriera combatterai avversari ben più tosti dei cinghiali.\n\nComunque ti sei $Gdimostrato:dimostrata; all'altezza, e la tua prossima prova sarà contro un avversario molto più pericoloso, quindi ti servirà un po' di protezione in più.", enHash = "eb0bcbd4" },
    },
    [789] = {
        title = { it = "Il pungiglione dello scorpide", enHash = "15b66b1f" },
        text = { it = "Guerrieri potenti e novizi impacciati sono caduti allo stesso modo sotto il pungiglione velenoso degli scorpidi. Troverai scorpidi in gran numero a nord-ovest di qui. Portami dieci delle loro code come prova del tuo valore in battaglia.\n\nL'antidoto contro il loro veleno si ricava proprio dal veleno estratto dai loro pungiglioni. Teniamo grandi scorte di antidoto per il veleno degli scorpidi, per curare le giovani leve come te...\n\nMa sono sicuro che a te non servirà, vero?", enHash = "82f97ffc" },
        objectives = { it = "Procura 10 Scorpid Worker Tail per Gornek nel Den.", enHash = "e76aa8ec" },
        progress = { it = "Il carapace di uno scorpide non è così spesso da fermare la forza di un guerriero determinato. Colpisci con forza e senza esitare, e gli scorpidi si riveleranno prede facili.", enHash = "e7b44c03" },
        reward = { it = "C'è una lezione importante che devi imparare dagli scontri con gli scorpidi. Anche il più piccolo o il più grande degli avversari può mandarti incontro alla rovina. In un combattimento feroce, qualunque cosa può causare la tua caduta.\n\nNon ho altro da insegnarti, $N. Hai fatto bene, e seguirò i tuoi progressi con interesse.", enHash = "0ff40c90" },
    },
    [790] = {
        title = { it = "Sarkoth", enHash = "6f6b7cbc" },
        text = { it = "$C! Pensavo che sarei morto qui fuori senza che nessuno lo sapesse. Mentre cacciavo gli scorpidi della Valley, mi sono imbattuto in uno dall'aspetto particolarmente feroce. Mi ci sono scagliato contro e sono riuscito ad assestare un colpo tremendo alla sua chela, prima che mi si chiudesse attorno alla gamba.\n\nMa non ero pronto al suo pungiglione: è calato fino al mio petto, mi ha squarciato la carne e mi ha fatto sanguinare. Ti prego, devi uccidere quello scorpide per me! Il mio onore deve essere difeso! L'ho combattuto sull'altopiano, a sud.", enHash = "5d25bdf6" },
        objectives = { it = "Uccidi Sarkoth e riporta la sua chela a Hana'zua.", enHash = "f8a52b01" },
        progress = { it = "Ahhh... mio padre diceva sempre che non avrei combinato granché, e ora eccomi qui, steso sotto un albero mentre la vita mi scivola via: temo proprio che avesse ragione.\n\nAlmeno voglio morire sapendo che il mio ultimo nemico giace senza vita.", enHash = "c7c722c2" },
        reward = { it = "Il mio colpo non è bastato a ucciderlo, ma vedere il danno che gli ho inflitto mi dà un po' di orgoglio. Se morirò, sarà l'unica cosa a darmi forza, e a pensarci bene quel poco che ho realizzato nella vita mi riempie di rabbia.", enHash = "7d35da80" },
    },
    [791] = {
        title = { it = "Fai la tua parte", enHash = "b3a7af80", vanilla = true },
        text = { it = "L'età mi ha reso inutile in battaglia. Ora mi rendo utile in altri modi.\n\nDa questo punto d'osservazione sorveglio l'arrivo degli invasori. Man mano che la nostra forza qui cresce, mi ritrovo a suonare il corno d'allarme sempre più di rado.\n\nPer passare il tempo fabbrico oggetti che aiutino guerrieri più giovani e più capaci a difendere la nostra terra.\n\nPer te posso fabbricare una borsa per le tue cose. Se un oggetto del genere ti fosse utile, portami un po' di tela, un materiale comune tra gli umani e i centauri.", enHash = "db55310c", vanilla = true },
        objectives = { it = "Furl Scornbrow, nella torre di guardia di Razor Hill, vuole 8 Canvas Scrap.", enHash = "34444628", vanilla = true },
        progress = { it = "Ho combattuto con orgoglio al fianco del Capoguerra quando ci insediammo in queste terre. Le cicatrici della battaglia mi segnano la pelle.\n\nL'onore dell'Orda è stato difeso con l'aiuto della mia ascia e del mio grido di guerra durante la sconfitta di Archimonde, quando fu stretta l'alleanza empia con umani ed elfi, nata dalla necessità.\n\nMa il mio posto di sentinella e di artigiano mi ha dato un nuovo senso del mio valore.", enHash = "eff432c2", vanilla = true },
        reward = { it = "Ottimo, $N. $GQualunque buon:Qualunque buona; $C troverà di sicuro un uso per questa borsa sul campo di battaglia.\n\nSaluto il tuo vigore e la tua volontà di morire nel nome dell'Orda!", enHash = "e4bb12a1", vanilla = true },
    },
    [792] = {
        title = { it = "I Vile Familiar", enHash = "254076da" },
        text = { it = "Confido che la Valley of Trials ti insegnerà molto, giovane $C.\n\nSono stata mandata nella Valley per guidarti, ma qui ho scoperto una corruzione che cresce...\n\nUn gruppo che si fa chiamare Burning Blade ha una congrega qui nella Valley of Trials. Si nascondono in una grotta a nord-est, e i loro Vile Familiar sono dilagati fuori dall'ingresso seminando il caos.\n\nCome tuo primo compito contro la Burning Blade, ti chiedo di sconfiggere questi famigli. Uccidine molti e, se sopravvivi, torna da me.", enHash = "e423cc65" },
        objectives = { it = "Uccidi 12 Vile Familiar.\n\nTorna da Zureetha Fargaze, fuori dal Den.", enHash = "c5dd4a0d" },
        progress = { it = "Per dimostrare il tuo valore contro la Burning Blade, devi prima sconfiggere i suoi Vile Familiar. Torna da me quando l'avrai fatto.", enHash = "3d59c6da" },
        reward = { it = "Hai fatto bene, $N.\n\nAnche se i Vile Familiar erano solo animali al servizio dei poteri più oscuri della Burning Blade, il tuo successo contro di loro annuncia imprese più grandi.", enHash = "4d215652" },
    },
    [793] = {
        title = { it = "Alleanze spezzate", enHash = "94c8d491", vanilla = true },
        text = { it = "Il Seal of the Earth è tenuto da tre pietre runiche, custodite nei Pillar of Diamond, Opal e Amethyst, nella Lethlor Ravine. Usando il Sign of the Earth, potrai rimuovere le pietre runiche e aprire il Seal of the Earth.\n\nMa sta' $Gattento:attenta;, $N: i draghi neri Blacklash e Hematus non sono da prendere alla leggera. Assicurati che muoiano e riportami i loro vincoli.\n\nPer raggiungere la gola, va' all'estremità orientale delle Badlands. Ma fa' attenzione, perché la gola è la dimora di innumerevoli draghi.", enHash = "86edeaec", vanilla = true },
        objectives = { it = "Usa il Sign of the Earth per attivare il Pillar of Diamond, il Pillar of Opal e il Pillar of Amethyst e ottenere la Diamond Runestone, l'Opal Runestone e l'Amethyst Runestone.\n\nMetti le pietre runiche nel Seal of the Earth per liberare Blacklash e Hematus.\n\nUccidili e riporta Blacklash's Bindings, le Chains of Hematus e il Sign of the Earth a Gorn.", enHash = "d14b38c4", vanilla = true },
        progress = { it = "Ci sono pochi nemici più letali della stirpe dei draghi, e pochi draghi hanno combattuto con la ferocia di Blacklash e Hematus.", enHash = "9120ddbb", vanilla = true },
        reward = { it = "Lo stormo dei draghi neri continua ad allearsi con gli orchi rinnegati Blackrock, ed entrambi vanno rimessi in riga, o eliminati. Con Blacklash e Hematus morti, possiamo volgere la nostra attenzione a ovest, verso la Blackrock Spire.", enHash = "30df81ef", vanilla = true },
    },
    [794] = {
        title = { it = "Burning Blade Medallion", enHash = "487df71e" },
        text = { it = "Attraverso le mie divinazioni vedo che un oggetto di potere si nasconde nelle profondità della Burning Blade Coven, sorvegliato da bestie e magia nera.\n\nSi chiama Burning Blade Medallion, e il tuo prossimo compito è trovarlo e portarlo via dalla congrega.\n\nMa fai attenzione: il medaglione potrebbe essere nelle mani di un agente della Burning Blade, e in quel caso il suo potere sarebbe superiore a quello dei famigli che hai già incontrato.\n\nVa', $N. Troverai la congrega in una grotta, a nord-ovest.", enHash = "04bce221" },
        objectives = { it = "Porta il Burning Blade Medallion a Zureetha Fargaze, fuori dal Den.", enHash = "d407af77" },
        progress = { it = "Il tuo compito è concluso, $N? Hai il Burning Blade Medallion?", enHash = "31bcf6b6", vanilla = true },
        reward = { it = "L'hai recuperato! Ben fatto!\n\nIl tuo impegno nella Burning Blade Coven è fondamentale per estirpare questo culto dalla Valley of Trials. Ma temo che abbiano altri obiettivi nella nostra terra.\n\nNon ce ne siamo ancora liberati.", enHash = "4a3e1a46", vanilla = true },
    },
    [795] = {
        title = { it = "Seal of the Earth", enHash = "10ee8a15", vanilla = true },
        progress = { it = "Qui c'è il Seal of the Earth, con tre nicchie incassate per l'Amethyst Runestone, l'Opal Runestone e la Diamond Runestone.", enHash = "e3b24ad5", vanilla = true },
        reward = { it = "Mentre metti le pietre runiche negli incavi corrispondenti, un violento boato scuote la terra e il sigillo si spezza.", enHash = "5facf87f", vanilla = true },
    },
    [804] = {
        title = { it = "Sarkoth", enHash = "6f6b7cbc" },
        text = { it = "Vedere ciò che hai fatto per me mi tempra il cuore. Non posso cadere così facilmente! Devo resistere!\n\nMa resta il fatto che non posso tornare al Den senza aiuto. Ti prego, $N, torna al Den e racconta a Gornek la mia situazione. Forse lui può aiutarmi.", enHash = "d7080534" },
        objectives = { it = "Porta a Gornek, nel Den, la notizia della difficile situazione di Hana'zua.", enHash = "dac67762" },
        reward = { it = "Da come descrivi la bestia, credo proprio che tu stia parlando di Sarkoth! Non c'è da stupirsi che abbia avuto la meglio su Hana'zua. Gli manderemo subito aiuto: non preoccuparti più per Hana'zua.\n\nDevo dire, però, che sono molto colpito nel sapere che hai ucciso Sarkoth. È un'impresa di cui andare $Gfiero:fiera;, $N. E che tu abbia combattuto per l'onore di uno sconosciuto, mentre avevi altri compiti da svolgere, accresce il tuo stesso onore.", enHash = "c8567bc1" },
    },
    [805] = {
        title = { it = "Presentati a Sen'jin Village", enHash = "60c86337", vanilla = true },
        text = { it = "Le tue prove contro la Burning Blade sono finite... qui nella Valley. Ma voglio che tu riferisca ciò che hai scoperto.\n\nVai al villaggio troll di Sen'jin e cerca Master Gadrin. Il Sen'jin Village è a est, fuori dalla valle, poi a destra al bivio.\n\nParla a Gadrin della Burning Blade, e digli che è arrivata fino alla Valley of Trials. Scopri da lui se ha già raggiunto Sen'jin.\n\nVa', $N, e sii $Grapido:rapida;. Temo che il male trovato nella Burning Blade Coven sia solo l'araldo di una minaccia più grande...", enHash = "398f0b74", vanilla = true },
        objectives = { it = "Parla con Master Gadrin a Sen'jin Village.", enHash = "962d9478", vanilla = true },
        reward = { it = "Mmh... il tuo rapporto arriva in un brutto momento. Qui a Sen'jin la Burning Blade non si è vista, ma il suo male ha messo radici al largo della costa, sulle Echo Isles.\n\nGli orchi sono amici dei Darkspear Trolls. Amici d'onore. Vogliamo aiutare gli orchi, ma... anche noi abbiamo bisogno d'aiuto.", enHash = "b852fa59", vanilla = true },
    },
    [806] = {
        title = { it = "Tempeste oscure", enHash = "925c6c94", vanilla = true },
        text = { it = "Non possiamo permettere alla Burning Blade di mettere piede a Durotar! Dobbiamo distruggerla prima che il suo male si incancrenisca!\n\nHo condotto indagini per conto mio e ho scoperto che uno stregone della Burning Blade, il goblin Fizzle Darkstorm, si è accampato a Thunder Ridge, a nord-ovest. Lì lui e i suoi servi cultisti diffondono il caos.\n\nTrova e sconfiggi Fizzle, e portami il suo artiglio morto!", enHash = "f3654fd9", vanilla = true },
        objectives = { it = "Porta Fizzle's Claw a Orgnil Soulscar, a Razor Hill.", enHash = "6aefdfa7", vanilla = true },
        progress = { it = "Hai trovato Fizzle, $N? Lui, e tutto il resto della Burning Blade, vanno spazzati via dalle nostre terre!", enHash = "2fec249f", vanilla = true },
        reward = { it = "Aha! L'hai preso!\n\nRendi fiero il tuo clan, $N. E grazie a te, Durotar è libera da un altro agente del male.", enHash = "500fa63c", vanilla = true },
    },
    [808] = {
        title = { it = "Minshina's Skull", enHash = "439444be", vanilla = true },
        text = { it = "Sento la voce di mio fratello, Minshina, che mi chiama nei sogni.\n\nFu preso da Zalazane, lo stregone delle Echo Isles a est. Ed è morto.\n\nMa la morte non è libertà, per mio fratello. Lo spirito di Minshina è stato imprigionato nel suo stesso teschio dalle magie di Zalazane. Nei miei sogni lo vedo insieme ad altri teschi, in un cerchio di potere sulla più grande delle Echo Isles. Finché resterà lì, l'anima di mio fratello è condannata.\n\nTi prego, $N. Trova il cerchio e recupera Minshina's Skull. Portalo da me.\n\nLiberalo!", enHash = "8255bb3c", vanilla = true },
        objectives = { it = "Recupera Minshina's Skull dal cerchio di potere sulle Echo Isles.\n\nPortalo a Master Gadrin, a Sen'jin Village.", enHash = "46f7efe2", vanilla = true },
        progress = { it = "Hai il teschio di mio fratello, $N? È finalmente libero?", enHash = "ed5f9a3f", vanilla = true },
        reward = { it = "Grazie, $N. Hai salvato Minshina. Hai salvato lo spirito di mio fratello dalla schiavitù!", enHash = "2a5d06b2", vanilla = true },
    },
    [809] = {
        title = { it = "Ak'Zeloth", enHash = "7e10205f", vanilla = true },
        text = { it = "Dall'ultima grande guerra, quando la Legione Infuocata fu sconfitta, ho cercato le fonti della corruzione demoniaca nella società orchesca. Il collare che mi hai portato conferma i miei timori.\n\nAppartiene alla Burning Blade, un culto che si raccoglie attorno a un oggetto di potere demoniaco. Si chiama Demon Seed, e si trova nelle Barrens, in cima al Dreadmist Peak. Va distrutto!\n\nVa' al Far Watch Post, al confine delle Barrens a ovest, e parla con il mio assistente, Ak'Zeloth. Ti darà altre indicazioni.", enHash = "fa4c1d50", vanilla = true },
        objectives = { it = "Parla con Ak'Zeloth, nelle Barrens.", enHash = "60bc0f20", vanilla = true },
        reward = { it = "Neeru vuole che il Demon Seed sia distrutto, eh? Strano...\n\nE va bene. Se vuole che il seme sparisca, allora ti dirò come toglierlo.", enHash = "8f7ab6f9", vanilla = true },
    },
    [812] = {
        title = { it = "Serve una cura", enHash = "95e91785", vanilla = true },
        text = { it = "$N... il tuo tempismo è perfetto. Spero solo di poter fare i complimenti anche alla tua velocità.\n\nSono stato imprudente mentre combattevo contro alcuni Venomtail qui vicino, e uno di loro mi ha punto a fondo. Sento il suo veleno che mi indebolisce mentre parliamo. Di questo passo mi resta forse un'ora di vita. Ma per arrivarci mi servirà il tuo aiuto...\n\nKor'ghan, a Orgrimmar, sa come si prepara l'antidoto. Trovalo... e sbrigati, $N. Non potrò resistere ancora a lungo. Dovrebbe essere nella Cleft of Shadow.", enHash = "f8b2d4f3", vanilla = true },
        objectives = { it = "Trova Kor'ghan a Orgrimmar e fatti dare il Venomtail Antidote. Poi porta l'antidoto a Rhinag, vicino al confine nord-occidentale di Durotar.", enHash = "13586b16", vanilla = true },
        progress = { it = "Sono quasi contento di non poter tornare a Sen'jin nelle condizioni in cui sono. La mia debolezza e la mia stupidità sarebbero di sicuro derise.", enHash = "bfa47b75", vanilla = true },
        reward = { it = "$N, mi hai salvato la vita. Grazie.\n\nPrendi questo, ti prego; spero che almeno ti sia d'aiuto nei tuoi viaggi, se non altro per ricavarci qualche moneta. Da quello che dici, non lo userò tanto presto. Kor'ghan mi farà passare per altri dei suoi rituali finché non avrò dimostrato il mio valore. Altri cinghiali da ammazzare, altre code di scorpidi da raccogliere... <sospira>", enHash = "7fad3fed", vanilla = true },
    },
    [813] = {
        title = { it = "Trovare l'antidoto", enHash = "363770a4", vanilla = true },
        text = { it = "I Venomtail sono tra gli scorpidi più letali di Durotar. È stato imprudente, da parte di Rhinag, andarli a cacciare senza portarsi dietro un po' di antidoto, ma in questo momento rimproverarlo è l'ultima cosa che gli serve.\n\nPortami qualche Venomtail Poison Sac da uno qualsiasi dei Venomtail vicino all'ingresso di Orgrimmar, e gli preparerò un antidoto.\n\nFa' in fretta, $N. Uno dei nostri ha bisogno del tuo aiuto.", enHash = "2bdf1d7f", vanilla = true },
        objectives = { it = "Porta 4 Venomtail Poison Sac a Kor'ghan, a Orgrimmar.", enHash = "c3b25112", vanilla = true },
        progress = { it = "Ricorda: qualunque creatura tu cacci, faresti bene a studiarla e a capirne il comportamento. Quella conoscenza potrebbe salvarti la vita.", enHash = "b994b653", vanilla = true },
        reward = { it = "Ecco l'antidoto, $N. Portalo a Rhinag appena puoi, e sii prudente.", enHash = "89c907fe", vanilla = true },
    },
    [815] = {
        title = { it = "Rompere qualche uovo", enHash = "d57ad336", vanilla = true },
        text = { it = "Bah! Mi stavo quasi dimenticando che devo preparare la colazione.\n\n$N, muoviti e portami delle Taillasher Egg. Me ne servono almeno tre, se voglio averne abbastanza per il pasto di domani.\n\nI Bloodtalon Taillasher possono essere feroci, e il più delle volte difendono le uova fino alla morte. A volte le seppelliscono troppo in profondità perché si possano dissotterrare senza rischi, ma se vai alle Echo Isles, a sud-est di Sen'jin Village, di solito le trovi sparse per tutte quelle isole.", enHash = "7f595e3e", vanilla = true },
        objectives = { it = "Porta 3 Taillasher Egg a Cook Torka, a Razor Hill.", enHash = "a6f5245a", vanilla = true },
        progress = { it = "Colazione, pranzo, cena! A chi importa che pasto sia? Qualcuno lo deve cucinare comunque — cioè io!", enHash = "8d51a35e", vanilla = true },
        reward = { it = "Sarai anche debole, ma almeno non sei $Gmaldestro:maldestra;, $N.\n\nTieni, prendi questo e levati di torno. Ho da cucinare.", enHash = "263413bc", vanilla = true },
    },
    [816] = {
        title = { it = "Perduto ma non dimenticato", enHash = "295d4fb2", vanilla = true },
        text = { it = "$N, ti prego, puoi aiutarmi? Mio figlio Kron è andato a caccia giorni fa e non è ancora tornato. È andato a ovest, verso le Barrens, a cacciare i crocolisk lungo il Southfury River. Temo il peggio.\n\nPer quanto fosse forte, il suo orgoglio testardo l'ha sempre trascinato nei guai. L'avevo avvertito che i crocolisk erano potenti e feroci. Si è arrabbiato ed è uscito infuriato.\n\nSe non riesci a trovarlo, portami almeno un segno della sua sorte... anche se dovessi aprire lo stomaco di ogni crocolisk lungo le rive del Southfury.", enHash = "0e48d5bc", vanilla = true },
        objectives = { it = "Porta un segno della sorte di Kron a Misha Tor'kren, alla fattoria a nord-ovest di Razor Hill.", enHash = "8c09e085", vanilla = true },
        progress = { it = "Prego che Kron torni da me, ma sono quasi certa di conoscere già la sua sorte.", enHash = "3878533f", vanilla = true },
        reward = { it = "Oh, figlio mio... mio bellissimo figlio.\n\nSenza sapere che sorte avesse avuto mio figlio, mi sono tormentata da quando è partito. Ora che so cos'è successo, forse posso finalmente cominciare a piangerlo.\n\nGrazie, $N. Prendi questo, ti prego. Volevo darlo a Kron in dono quando fosse tornato vittorioso. Ora che lo so morto, non sopporto di guardarlo.", enHash = "a907e26e", vanilla = true },
    },
    [817] = {
        title = { it = "Prede utili", enHash = "f90e7161", vanilla = true },
        text = { it = "Molte delle pelli che usiamo vengono dai Durotar Tiger, $N. Coperte, armature, tende: ci sono moltissime ragioni per cui cacciamo quelle bestie, e altrettante per cui allo stesso tempo le lasciamo prosperare.\n\nÈ venuto il momento di sfoltire il branco, per così dire. Siamo sempre di più, e i nostri bisogni cominciano a superare le nostre scorte. Mi servono più pelli, se devo preparare merci adatte alla nostra gente.\n\nPortami 4 Durotar Tiger Fur e ti ricompenserò. Li trovi sulle isole a sud di qui.", enHash = "bc548346", vanilla = true },
        objectives = { it = "Porta 4 Durotar Tiger Fur a Vel'rin Fang, a Sen'jin Village.", enHash = "ea94dc99", vanilla = true },
        progress = { it = "Ricordo la mia prima caccia alla tigre, $N. Scelsi di cacciare sulla più grande delle Echo Isles, e rimasi perfettamente immobile all'ombra del fogliame per quasi un giorno intero... a guardare... ad aspettare.\n\nI miei muscoli erano tesi, ed ero pronto a colpire. Fu una delle mie più grandi vittorie, quando quella tigre finalmente abboccò.", enHash = "c2de23f3", vanilla = true },
        reward = { it = "Ne sono lieto, $N. Grazie al tuo aiuto la nostra gente sarà protetta e non patirà il freddo quando cambieranno le stagioni.\n\nGrazie.", enHash = "b5a532a6", vanilla = true },
    },
    [818] = {
        title = { it = "Uno spirito solvente", enHash = "054a03cb", vanilla = true },
        text = { it = "Anche se gli occhi mi tradiscono, ci vedo ancora abbastanza chiaro. Sempre più spesso devo affidarmi alle mie arti alchemiche per magie che un tempo mi venivano facili. Ma mi rifiuto di prendere un apprendista: non si è mai fatto avanti nessun troll o orco che ne fosse degno.\n\nTu ne sei $Gdegno:degna;? Sì, certo che lo sei... certo che credi di esserlo.\n\nMi servono alcune cose. Me le procuri?\n\nMi servono Intact Makrura Eye e fiale di Crawler Mucus. Li trovi su qualunque makrura o crawler di Durotar. Ci riparleremo presto.", enHash = "22ba0c91", vanilla = true },
        objectives = { it = "Porta 4 Intact Makrura Eye e 8 fiale di Crawler Mucus a Master Vornal, a Sen'jin Village.", enHash = "5a569c8e", vanilla = true },
        progress = { it = "Il tempo è la vera prova della tua forza e della tua volontà. Perdi la pazienza o cedi alla debolezza, e si vedrà chi sei davvero.", enHash = "68a4c095", vanilla = true },
        reward = { it = "Ben fatto, giovane... ben fatto davvero.", enHash = "c6b3bbf5", vanilla = true },
    },
    [819] = {
        title = { it = "Chen's Empty Keg", enHash = "989931d4", vanilla = true },
        text = { it = "Una piccola targhetta su uno dei fondi del barile dice:\n\n\"Chen Stormstout-\n\nChe il tuo spirito sia sollevato, e solleva sempre gli spiriti altrui.\"", enHash = "b5ab3c25", vanilla = true },
        objectives = { it = "Trova qualcuno che sappia qualcosa su Chen's Empty Keg.", enHash = "a7a87bf8", vanilla = true },
        progress = { it = "Sì?", enHash = "00388a38", vanilla = true },
        reward = { it = "Ma guarda un po'...\n\nQuesto era uno dei barili di Chen Stormstout. Viaggiò con Rexxar tanto tempo fa. Non lo vedo e non ne sento parlare da un'eternità. Ti ringrazio di avermelo portato, $N.", enHash = "316c554e", vanilla = true },
    },
    [821] = {
        title = { it = "Chen's Empty Keg", enHash = "989931d4", vanilla = true },
        text = { it = "Ti va di assaggiare la birra che porta il nome di Chen? Ahh, la stormstout è una birra possente. Chen insegnò la ricetta al mio maestro, e il mio maestro l'ha passata a me. Mi servirà che tu mi procuri qualche cosetta, ma ti dico una cosa: la botta vale la fatica.\n\nPortami 5 zanne di Savannah Lion da un qualunque Savannah Lion, 5 reni di Plainstrider da un qualunque Plainstrider e 1 corno di Thunder Lizard da una specie qualsiasi di Thunder Lizard. Dovrebbe bastare.\n\nQuesti ingredienti li trovi in giro per le Barrens.", enHash = "a97d4c3e", vanilla = true },
        objectives = { it = "Porta 5 Savannah Lion Tusk, 5 Plainstrider Kidney e 1 Thunder Lizard Horn a Brewmaster Drohn, a Ratchet.", enHash = "40ead123", vanilla = true },
        progress = { it = "Come va la ricerca?", enHash = "b0468fea", vanilla = true },
        reward = { it = "Ahah... Non avrei mai pensato di rifarne dell'altra.\n\nMi hai risvegliato una gran nostalgia, $N. Un po' mi ricorda l'ultima volta che feci una cotta di birra di trogg. Grazie. I ricordi mi scaldano lo stomaco.", enHash = "a3ca263c", vanilla = true },
    },
    [822] = {
        title = { it = "Chen's Empty Keg", enHash = "989931d4", vanilla = true },
        text = { it = "Roba buona, quella stormstout, eh?\n\nHo un'altra ricetta che ho imparato da Chen. Ti interessa? Non ci vuole molto a prepararla, e potrebbe tornarti utile se hai in mente di andare ancora in giro per avventure.\n\nPortami 5 Lightning Gland da uno Stormhide qualsiasi, 1 Thunderhawk Saliva Gland dai Greater Thunderhawk e un Kodo Liver da uno qualsiasi dei kodo delle Barrens.\n\nCome ti ho detto, questa roba ha una bella botta: è la birra dei trogg di cui ti avevo parlato.", enHash = "5f5119a5", vanilla = true },
        objectives = { it = "Porta 5 Lightning Gland, 1 Thunderhawk Saliva Gland e 1 Kodo Liver a Brewmaster Drohn, a Ratchet.", enHash = "a0c99e43", vanilla = true },
        progress = { it = "Ci stai lavorando sodo per trovare quegli ingredienti, $N?", enHash = "88d052f1", vanilla = true },
        reward = { it = "Ahah! Lo sapevo che non avresti resistito a un po' di questa birra. Torna quando vuoi se te ne serve altra, $N. Basta che mi porti altri ingredienti come quelli che ti ho fatto raccogliere.", enHash = "6229fdad", vanilla = true },
    },
    [823] = {
        title = { it = "Rapporto a Orgnil", enHash = "2a959206", vanilla = true },
        text = { it = "Anche noi di Sen'jin Village abbiamo i nostri guai, e ti ringraziamo per l'aiuto. Ma le notizie che porti sulla Burning Blade potrebbero essere un guaio per tutti.\n\nC'è un orco di stanza a Razor Hill, Orgnil Soulscar, che protegge Durotar da mali come la Burning Blade! Va' da Orgnil e raccontagli la nostra situazione, e anche le notizie che porti dalla Valley of Trials. Vorrà sapere queste cose.\n\nRazor Hill si trova a nord.", enHash = "d933d733", vanilla = true },
        objectives = { it = "Parla con Orgnil Soulscar, a Razor Hill.", enHash = "84b1e1c5", vanilla = true },
        reward = { it = "Sì? Hai qualcosa da riferire? E allora, sentiamo!", enHash = "ec48dacf", vanilla = true },
    },
    [824] = {
        title = { it = "Je'neu del Circolo della Terra", enHash = "6d4804e7", vanilla = true },
        text = { it = "Il Circolo della Terra è un gruppo sciamanico che si dedica a studiare e preservare gli elementi. Di antichi dèi folli, di leggende e di saperi antichi ha dimenticato più cose di quante la maggior parte degli studiosi ne saprà mai.\n\nPer tua fortuna, conosco qualcuno del Circolo della Terra qui ad Ashenvale. Va' allo Zoram'gar Outpost, sulla costa dello Zoram Strand; mostra a Je'neu Sancrea quello che hai trovato. Se c'è qualcuno che può capire il significato di quel globo, è lui.", enHash = "3e0af839", vanilla = true },
        objectives = { it = "Porta il Befouled Water Globe a Je'neu Sancrea, allo Zoram'gar Outpost, in Ashenvale.", enHash = "86e0a1d5", vanilla = true },
        progress = { it = "Ah, salve. Passo molto tempo a studiare l'acqua — tutti gli elementi, a dire il vero — tanto che a volte non mi accorgo nemmeno di chi mi sta intorno.\n\nC'è qualcosa in cui posso aiutarti?", enHash = "82e6fcfe", vanilla = true },
        reward = { it = "Questo globo... è davvero inquietante. Molti degli elementali più potenti ricevono potere ed energia attraverso congegni simili. Trovarne uno così quasi intatto è una cosa — trovarlo tanto corrotto è un'altra.\n\nFarò in modo che il Circolo della Terra studi questo globo come si deve. Forse possiamo mettere fine a questa corruzione degli elementi. Ti prego — accetta questo come giusto scambio per aver portato il globo all'attenzione del Circolo della Terra.", enHash = "88e9f129", vanilla = true },
    },
    [825] = {
        title = { it = "Dal relitto...", enHash = "87f806f2", vanilla = true },
        text = { it = "Uno dei miei esploratori più attenti riferisce che il relitto della flotta di Proudmoore giace ancora al largo della costa di Durotar, appena a est di Tiragarde Keep.\n\nNon è un segreto che gli umani, alleati con quelle luride creaturine chiamate gnomi, abbiano una conoscenza avanzata della meccanica. Dobbiamo capire a fondo tutti i nostri possibili nemici. E anche la nostra gente trarrà vantaggio da questa nuova conoscenza.\n\nNuota tra i resti del relitto, $N, e recupera per me gli attrezzi dell'Alleanza.", enHash = "5f9b4e22", vanilla = true },
        objectives = { it = "Gar'Thok di Razor Hill vuole che tu recuperi 3 Gnomish Tools dal relitto al largo della costa.", enHash = "f3ab3041", vanilla = true },
        progress = { it = "Quando avremo imparato come gli umani fanno funzionare le loro strane macchine, avremo più possibilità di sconfiggerli nelle battaglie future.\n\nCon questa nuova conoscenza, l'Orda non potrà che diventare più forte.", enHash = "07e1163a", vanilla = true },
        reward = { it = "La tua missione di recupero è stata un successo, $C. Farò in modo che questi attrezzi arrivino a Orgrimmar con la prossima carovana.\n\nBel lavoro.", enHash = "1fd28f5a", vanilla = true },
    },
    [826] = {
        title = { it = "Zalazane", enHash = "4a670ffa", vanilla = true },
        text = { it = "Lo stregone Zalazane dimora sulle Echo Isles a est. Sono le isole che un tempo chiamavamo casa.\n\nDa là manda i suoi troll sulla terraferma, a stregare la nostra gente e a trascinarne altra sotto il suo dominio.\n\nVa fermato.\n\nSconfiggi Zalazane e i suoi servi — un tempo troll Darkspear, ora perduti per noi. Portami la sua testa e saprò che il suo regno di male è finito.", enHash = "53b59d37", vanilla = true },
        objectives = { it = "Sconfiggi Zalazane.\n\nUccidi 8 Voodoo Troll e 8 Hexed Troll.\n\nPorta Zalazane's Head a Gadrin.", enHash = "48600d36", vanilla = true },
        progress = { it = "Zalazane è stato sconfitto, $N?", enHash = "c85ee2ff", vanilla = true },
        reward = { it = "Ora che Zalazane non c'è più, la nostra tribù può tornare a dormire in pace.\n\nGrazie, $N. La tribù Darkspear ti deve molto. Se soffri di qualche malanno, va' dal mio assistente Bom'bay, dietro di me. Il suo voodoo è forte...", enHash = "9a7d425b", vanilla = true },
    },
    [827] = {
        title = { it = "Skull Rock", enHash = "3ae68a48", vanilla = true },
        text = { it = "$N. La Burning Blade ha infestato la grotta a est di Orgrimmar chiamata Skull Rock. Dentro quella grotta compiono rituali immondi e si bruciano la carne con i Searing Collar.\n\nCredo che, portando quei collari, i cultisti si sintonizzino con il potere demoniaco. Ma per confermarlo devo avere una raccolta di collari da studiare.\n\nVa' a Skull Rock e raccogli i Searing Collar dai cultisti che vi troverai. Portameli, e ne scoprirò i segreti.", enHash = "401d3cb2", vanilla = true },
        objectives = { it = "Raccogli i Searing Collar dai cultisti a Skull Rock.\n\nPortali a Margoz, al suo accampamento.", enHash = "cc063f1c", vanilla = true },
        progress = { it = "Sei già $Gentrato:entrata; a Skull Rock, $N? Hai i Searing Collar?", enHash = "9c81619a", vanilla = true },
        reward = { it = "Bene. Dentro questi collari si nasconde il segreto della Burning Blade. E io quel segreto lo scoprirò...", enHash = "ad6fde14", vanilla = true },
    },
    [828] = {
        title = { it = "Margoz", enHash = "bf8c8674", vanilla = true },
        text = { it = "Uno dei nostri sciamani, Margoz, sa di più sulla corruzione della Burning Blade. Parla di una grotta chiamata Skull Rock tra le montagne — proprio fuori da Orgrimmar! — che dà riparo a una grossa banda di cultisti della Burning Blade.\n\nPrima di andare a Skull Rock parla con Margoz. È saggio e il suo consiglio ha valore.\n\nÈ accampato a nord-est, tra la costa e Drygulch Ravine.\n\nSegui il suo consiglio, ma qualunque cosa dica Margoz, $N, io voglio comunque che tu schiacci quei cultisti!", enHash = "8749c154", vanilla = true },
        objectives = { it = "Parla con Margoz.", enHash = "9b3d046e", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta;, $N. Mi è giunta voce del tuo arrivo e delle tue imprese a Durotar.\n\nSei $Gun:una; $C di abilità e fama crescenti.\n\nResta sulla via pura, e il tuo futuro sarà davvero grande.", enHash = "4a0b016a", vanilla = true },
    },
    [829] = {
        title = { it = "Neeru Fireblade", enHash = "c4604a93", vanilla = true },
        text = { it = "I Searing Collar che mi hai portato sono strumenti demoniaci potenti. Divinarne l'origine è, temo, oltre le mie capacità di sciamano. Ci servirà uno stregone per studiarli.\n\nPorta un Searing Collar a Neeru Fireblade. Anche se è uno stregone abile, dichiara di usare i suoi poteri per ostacolare i demoni, e sostiene che le sue ricerche nell'occulto siano innocue. Che sia vero o falso, potremmo avere bisogno del suo aiuto contro il culto demoniaco a Durotar.\n\nNeeru lo trovi a Orgrimmar, nella Cleft of Shadow.", enHash = "9eb582e7", vanilla = true },
        objectives = { it = "Porta un Example Collar a Neeru Fireblade, a Orgrimmar.", enHash = "14c02fb3", vanilla = true },
        progress = { it = "I miei più umili saluti, $C. Come posso aiutare oggi $Gmio fratello:mia sorella; $R?", enHash = { "996519ee", "6bbf732a" }, vanilla = true },
        reward = { it = "Ah, e dove l'hai preso? Ti manda il buon Margoz di Razor Hill, eh?\n\nBe', lascia che dia un'occhiata più da vicino...", enHash = "47300766", vanilla = true },
    },
    [830] = {
        title = { it = "Gli ordini dell'Admiral", enHash = "3e77db2a", vanilla = true },
        text = { it = "Apri la busta vecchia e sciupata dal tempo e trovi un documento dall'aria ufficiale. Riconosci il sigillo di Admiral Proudmoore.\n\nSembra importante. Forse a Gar'Thok, il comandante di Razor Hill, interesserebbe avere questa informazione.", enHash = "fb0965cf", vanilla = true },
        objectives = { it = "Porta Admiral Proudmoore's Orders a Gar'Thok, a Razor Hill.", enHash = "7c3170c2", vanilla = true },
        progress = { it = "Hai un'aria preoccupata, $C. Cos'hai lì?", enHash = "0b669c27", vanilla = true },
        reward = { it = "Non promette affatto bene. Hai fatto bene a portarmi questa informazione.", enHash = "d7450ff8", vanilla = true },
    },
    [831] = {
        title = { it = "Gli ordini dell'Admiral", enHash = "3e77db2a", vanilla = true },
        text = { it = "Degli umani non ci si può fidare. Abbiamo combattuto al loro fianco con il cuore stanco, sapendo che un giorno ci avrebbero traditi.\n\nLa morte di Admiral Proudmoore non è bastata a fermare la sua eredità d'inganni. Quella feccia umana aveva preparato bene i suoi piani, molto prima di incontrare la fine.\n\nA quanto pare il suo dominio non morirà nemmeno con Benedict. Chissà quanto passerà prima che le prossime ondate di uomini di Proudmoore sbarchino sulle nostre coste.\n\nDobbiamo far arrivare subito questi ordini a Nazgrel, a Orgrimmar! Lo trovi nella sala di Thrall.", enHash = "085047a6", vanilla = true },
        objectives = { it = "Consegna Admiral Proudmoore's Orders a Nazgrel, nella sala di Thrall, a Orgrimmar.", enHash = "48783f41", vanilla = true },
        progress = { it = "Non vedi che sono occupato? Spero proprio che sia urgente...", enHash = "5126a59a", vanilla = true },
        reward = { it = "Innumerevoli volte ho esortato il Capoguerra a non fidarsi degli umani, ma qui non è in gioco l'orgoglio personale.\n\nHai servito l'Orda con onore, giovane $C.\n\nOra scusami, devo consigliare Thrall su queste faccende immediatamente...", enHash = "1e0fde69", vanilla = true },
    },
    [832] = {
        title = { it = "Ombre ardenti", enHash = "4c7ea3e6", vanilla = true },
        text = { it = "<Dal pendente si levano parole che ti entrano nella mente.>\n\nGazz'uz?\n\nGazz'uz... rapporto!\n\nGira voce che vi abbiano scoperti a Skull Rock. Devi prepararti a un attacco!\n\nGazz'uz, ti ordino di parlare! Parla, o farò in modo che Neeru Fireblade sappia della tua presenza, e ti piomberà addosso con rapida brutalità.\n\nNon mettere alla prova le tue capacità contro Neeru...\n\n...Gazz'uz, ci sei...?", enHash = "32d493f9", vanilla = true },
        objectives = { it = "Porta questo occhio a Neeru Fireblade.", enHash = "e7d38008", vanilla = true },
        progress = { it = "Hai qualcosa di importante da riferire. Lo sento dietro i tuoi occhi.", enHash = "3de2136f", vanilla = true },
        reward = { it = "<Esamina l'Eye of Burning Shadow.>\n\nCurioso. La voce che hai sentito faceva il mio nome? Sono noto per dare la caccia ai nemici del nostro Capoguerra, ma... è strano che sia stato scelto proprio io. Ancora più strano che i cultisti della Burning Blade da cui hai recuperato questo pendente abbiano un nome così vicino al mio.\n\nDevo studiare questo pendente. Devo studiarlo e riflettere sul significato del suo messaggio.\n\nGrazie per avermelo fatto sapere, $N. Hai reso un grande servizio alla tua gente.", enHash = "4bac2f9c", vanilla = true },
    },
    [833] = {
        title = { it = "Una sepoltura sacra", enHash = "11cb59fa", vanilla = true },
        text = { it = "Solo i tauren più valorosi riposano a Red Rocks, il nostro sacro luogo di sepoltura. È un onore concesso ai grandi guerrieri che aiutarono a fondare e a difendere Thunder Bluff, e a chi ha dato la vita per il bene superiore delle proprie tribù e dei propri capi.\n\nMa sembra che una minaccia immonda sia giunta nella nostra terra sacra. Una banda di Bristleback Interloper sta devastando il luogo delle sepolture, e io sono troppo vecchio, e non ho più le forze di un tempo, per scacciarla.\n\nVanno cacciati con la forza, $N.", enHash = "00354873", vanilla = true },
        objectives = { it = "Lorekeeper Raintotem vuole che tu uccida 8 Bristleback Interloper a Red Rocks.", enHash = "9cf125dd", vanilla = true },
        progress = { it = "I Bristleback Interloper devono essere cacciati dal nostro sacro luogo di sepoltura, $N.", enHash = "7db3e5b4", vanilla = true },
        reward = { it = "Ben fatto. Hai mandato a quei luridi Bristleback un messaggio chiaro. Ci penseranno due volte prima di tornare a intromettersi in questo luogo sacro.", enHash = "8fb6790d", vanilla = true },
    },
    [834] = {
        title = { it = "Venti nel deserto", enHash = "8e106a8a", vanilla = true },
        text = { it = "Sono Rezlak, uno dei ragazzi di Gazlowe. Il capo mi ha mandato ad aiutare gli orchi qui a Durotar. Le cose andavano bene, tranne che per le carovane. Non riusciamo a tenerle al sicuro! Mi rende il lavoro un po' più difficile, capisci?\n\nL'ultimo carico — avevano promesso che sarebbe arrivato! — è stato arraffato dalle arpie Dustwind di... dov'era... Razorwind Canyon?\n\nMi servono quei rifornimenti o non concluderò mai niente! Segui il grande canyon verso sud: troverai la gola che taglia le pareti proprio a est e a ovest.", enHash = "2ab6e5f0", vanilla = true },
        objectives = { it = "Recupera 5 Sack of Supplies e riportali a Rezlak, vicino a Orgrimmar.", enHash = "6f6d3975", vanilla = true },
        progress = { it = "Sono bravissimo in quello che faccio, non fraintendermi, ma questo è ridicolo! Cosa dovrei fare, costruire castelli di sabbia?", enHash = "1c73ac99", vanilla = true },
        reward = { it = "Ehi, questo sì che ci voleva! Ci hai riportato i nostri rifornimenti. Fantastico. Potrò tornare al lavoro appena troverò qualcuno che mi trasporti questi sacchi.", enHash = "312be412", vanilla = true },
    },
    [835] = {
        title = { it = "Mettere in sicurezza le rotte", enHash = "135663e4", vanilla = true },
        text = { it = "Gazlowe una volta mi disse: \"Rezlak. C'è una cosa che devi sapere nella vita: se vuoi che una cosa sia fatta bene, falla da solo\".\n\nNon posso accettare di perdere tutte le nostre carovane, quindi prendo la faccenda in mano io. Drygulch Ravine si trova oltre la parte orientale di Razorwind Canyon. Se uccidiamo tutte le arpie che stanno lì, le rotte saranno sicure.\n\nCerto, c'era un'altra cosa che Gazlowe mi ha insegnato: \"Puoi far fare qualunque cosa, al prezzo giusto\". Allora, mi dai una mano, $N?", enHash = "74e2e6b9", vanilla = true },
        objectives = { it = "Uccidi 12 Dustwind Savage e 8 Dustwind Storm Witch per Rezlak, vicino a Drygulch Ravine.", enHash = "edfadeb5", vanilla = true },
        progress = { it = "Non lo diresti, da un tipo come il mio capo Gazlowe, ma sembrava sempre sapere come stavano le cose. \"Non aver paura di fare il grande passo\", diceva.\n\nLe arpie non smetteranno di darci fastidio e le carovane non smetteranno di essere attaccate finché non faremo qualcosa, eh?", enHash = "21f1e9e3", vanilla = true },
        reward = { it = "Credo di poter tirare il fiato, adesso, sapendo che le arpie non daranno più fastidio alle nostre carovane di rifornimenti. Ed era ora! Ho sentito che con il prossimo carico mi mandano certi bei giocattolini!\n\nSei piuttosto $Gbravo:brava; in quello che fai, $N: dovresti andare a cercare il mio capo a Ratchet. Scommetto che troverebbe del lavoro per te.\n\nAh, e non preoccuparti, non mi scorderei mai di pagarti per il servizio che mi hai reso.", enHash = "c2b9b41c", vanilla = true },
    },
    [837] = {
        title = { it = "Invasione", enHash = "46f68a6d", vanilla = true },
        text = { it = "Quando arrivammo, i quilboar Razormane possedevano gran parte della terra e si rivelarono una spina nel fianco. Con i nostri sforzi ne abbiamo cacciata via la maggior parte, ma in alcune zone restano ben trincerati.\n\nÈ andata avanti abbastanza così, però. Per la nostra stessa sicurezza non possiamo permettere ai Razormane nessun appiglio nelle nostre terre. I loro accampamenti si trovano a ovest di qui. Cerca i rovi e li troverai. Oggi li scacciamo da Durotar, domani, forse, da tutto Kalimdor.", enHash = "e2dc7133", vanilla = true },
        objectives = { it = "Uccidi 4 Razormane Quilboar, 4 Razormane Scout, 4 Razormane Dustrunner e 4 Razormane Battleguard per Gar'Thok, a Razor Hill.", enHash = "2e1767a5", vanilla = true },
        progress = { it = "Anche se possiedono una certa intelligenza e una certa organizzazione, continua a stupirmi che i quilboar siano riusciti a conquistare e a tenere tanto territorio in Kalimdor. Forse sono un nemico più scaltro di quanto gli riconosca...", enHash = "c8778e92", vanilla = true },
        reward = { it = "Farò sapere che i quilboar sono stati cacciati dalle loro tane e che le loro costruzioni si possono dare alle fiamme. Aver cacciato i Razormane da Durotar ci avvicina a mettere del tutto in sicurezza i confini della nostra nuova terra.", enHash = "65bcd9c1", vanilla = true },
    },
    [840] = {
        title = { it = "Coscritto dell'Orda", enHash = "050e6307", vanilla = true },
        text = { it = "Mmh, sembri piuttosto forte.\n\nSenti, il mio buon amico Kargal ha bisogno di reclute nuove per il servizio nelle Barrens. So che vuoi fare ciò che è giusto per l'Orda. Be', questa è la tua occasione.\n\nPorta questa lettera di reclutamento a Kargal e vedi se te la firma.", enHash = "2aa5f5f2", vanilla = true },
        objectives = { it = "Segui la strada occidentale che da Razor Hill porta alle Barrens, oltre un ponte.\n\nFermati all'avamposto degli orchi dall'altra parte del ponte.\n\nDai la tua lettera di reclutamento a Kargal Battlescar, all'avamposto delle Barrens.", enHash = "8afd7df1", vanilla = true },
        progress = { it = "Cosa vuoi, $Gcucciolo:cucciola;? Se non sei qui per l'arruolamento, non ho tempo per te.", enHash = "ded7294e", vanilla = true },
        reward = { it = "Oh, allora ti manda Takrin? È un esploratore eccellente, non so cosa farei senza di lui.\n\nTi firmo la lettera di reclutamento, ma quello che ci serve davvero è qualcuno al Crossroads.", enHash = "b3846731", vanilla = true },
    },
    [842] = {
        title = { it = "Arruolamento al Crossroads", enHash = "6b371208", vanilla = true },
        text = { it = "Porta al Crossroads questa lettera di reclutamento firmata.\n\nSergra Darkthorn, che la sua pelle sia maledetta, è quella al comando laggiù. È una sciamana antipatica che ti farà girare la testa a parole prima di lasciarti fare qualcosa di utile. Thrall è convinto che abbia qualcosa di speciale, ma io non ne sono così sicuro.\n\nDovrai deciderlo da $Gsolo:sola;, $Gcucciolo:cucciola;...", enHash = "a174caa5", vanilla = true },
        objectives = { it = "Segui la strada occidentale che parte dal Far Watch Outpost di Kargal.\n\nAll'incrocio a T, gira a sinistra e segui la strada verso sud.\n\nTrova Sergra Darkthorn all'incrocio delle strade, dentro il Crossroads.", enHash = "24c57d1a", vanilla = true },
        progress = { it = "Bene, bene, bene, cosa abbiamo qui? Kargal mi ha ritenuta degna di un'altra recluta?", enHash = "9057f954", vanilla = true },
        reward = { it = "Va bene, $N. Vuoi guadagnarti da vivere con l'Orda? Be', qui c'è molto da fare, quindi ascolta bene e fa' ciò che ti si dice.\n\n $GVedo quello sguardo nei tuoi occhi, non credere che tollererò insolenze. Thrall in persona ha dichiarato che le femmine dell'Orda sono alla pari con voi maschi. Mancami di rispetto anche solo un poco, e conoscerai il vero dolore.:Sono felice di averti conosciuta. Thrall sarà contento di sapere che altre donne come te e me prendono l'iniziativa per spingersi avanti nelle Barrens.;", enHash = { "21818c3f", "15be2e30" }, vanilla = true },
    },
    [843] = {
        title = { it = "La riconquista di Gann", enHash = "56ef6693", vanilla = true },
        text = { it = "In solitudine percorro queste strade.\n\nI nani di Bael Modan non mostrano rispetto per la mia terra. Esplosioni orrende aprono buche profonde nel terreno mentre macchine rumorose fanno a pezzi le colline. Terre che un tempo erano casa e sostentamento per la mia tribù sono ora crivellate di nani distruttori.\n\nI tentativi di arrivare a una soluzione diplomatica sono falliti. È il momento di un'azione decisiva.\n\nCaccia i nani dallo scavo di Bael Modan con la forza e portami il diario del loro capo, Prospector Khazgorm.", enHash = "ed4bd277", vanilla = true },
        objectives = { it = "Gann Stonespire vuole che tu uccida 15 Bael'dun Excavator e 5 Bael'dun Foreman.\n\nPorta Khazgorm's Journal a Gann Stonespire.", enHash = "ba69589c", vanilla = true },
        progress = { it = "Molti tauren innocenti hanno perso la vita o sono stati cacciati dalla terra dei loro avi quando sono arrivati i nani di Bael Modan. La mia terra va riconquistata!", enHash = "d121b92b", vanilla = true },
        reward = { it = "Khazgorm ha incontrato la sorte che si era guadagnato. Non provo rimorso per quello sciocco. Era un infedele su queste terre.\n\nChe la sua morte serva da monito a tutti quelli che minacciano di sconvolgere il nostro modo di vivere.\n\nOra lasciami un momento per studiare il diario del nano...", enHash = "8b4a8c5b", vanilla = true },
    },
    [844] = {
        title = { it = "La minaccia dei Plainstrider", enHash = "2cf8c47e", vanilla = true },
        text = { it = "La tua prima preda sarà facile.\n\nI Plainstrider a est danno fastidio alle nostre scorte di cibo e sono diventati una seccatura.\n\nAbbattili e torna da me con i loro becchi.", enHash = "d7278062", vanilla = true },
        objectives = { it = "Raccogli 7 Plainstrider Beak e portali a Sergra Darkthorn, al Crossroads.", enHash = "0b861b7e", vanilla = true },
        progress = { it = "Li hai raccolti i becchi dei Plainstrider?", enHash = "a1edd1ab", vanilla = true },
        reward = { it = "Molto bene, $N. Senza i Plainstrider ci sarà più facile tenere intatte le nostre linee di rifornimento. E spero che là fuori, nelle Barrens, tu abbia imparato qualche trucco: la tua prossima preda ha un po' più di fuoco nel sangue dei Plainstrider...", enHash = "bcf8ffe8", vanilla = true },
    },
    [845] = {
        title = { it = "Gli Zhevra", enHash = "5bcaf15d", vanilla = true },
        text = { it = "Gli Zhevra, pur non essendo le bestie più feroci delle Barrens, sono un po' più duri dei Plainstrider. Non preoccuparti — a suo tempo ti manderemo contro prede più grosse, ma per ora ti serve ancora farti le ossa.\n\nCaccia gli Zhevra a nord e a sud e raccogli i loro zoccoli. Portameli, e forse la prossima volta ti manderemo contro qualcosa di più duro.", enHash = "a8fd67c9", vanilla = true },
        objectives = { it = "Uccidi gli Zhevra Runner per raccogliere 4 Zhevra Hoof per Sergra Darkthorn, al Crossroads.", enHash = "510f5fea", vanilla = true },
        progress = { it = "Quanti Zhevra hai ucciso?", enHash = "64c0bc2a", vanilla = true },
        reward = { it = "Niente male, $N. Quegli Zhevra hanno molta forza nelle zampe. Un loro calcio secco stende anche un tauren!\n\nA quanto pare un po' di forza ce l'hai anche tu. Sei $Gpronto:pronta; per una vera sfida?", enHash = "f3455931", vanilla = true },
    },
    [846] = {
        title = { it = "La vendetta di Gann", enHash = "787d110d", vanilla = true },
        text = { it = "È chiaro che il cercatore contava sugli esplosivi e su quei veicoli rumorosi per fare a pezzi il terreno. C'è da aspettarsi che presto prenda il comando un nuovo caposquadra.\n\nVoglio ripagare i nani con la loro stessa moneta. Secondo questi piani, se combiniamo nitroglicerina con pasta di legno e nitrato di sodio possiamo creare una carica esplosiva. Pare che i fucilieri, i soldati e gli ufficiali del Keep abbiano il materiale.\n\nRaccogli questa roba e portamela. Fabbricherò una carica che i nani non dimenticheranno!", enHash = "da4bd4ee", vanilla = true },
        objectives = { it = "Gann Stonespire vuole che tu gli porti 6 fiale di Nitroglycerin, 6 fasci di Wood Pulp e 6 campioni di Sodium Nitrate.", enHash = "b5b0061d", vanilla = true },
        progress = { it = "Vedo che sei $Gtornato:tornata;, $N.\n\nAnche se la morte di Khazgorm ritarderà un po' gli scavi nelle terre dei miei avi, non metterà certo fine del tutto alla distruzione.\n\nIl Keep di Bael Modan è una minaccia militare sempre più grande. Costruito per difendere il sito di scavo, ora è pronto anche a farsi forza d'attacco.\n\nSe hai gli ingredienti che ti ho chiesto, posso fabbricare una carica che farà ripensare ai nani frettolosi quello che stanno facendo qui nelle Barrens.", enHash = "ebdaa738", vanilla = true },
        reward = { it = "Vedo che sei molto $Gindustrioso:industriosa;, $C.\n\nSenza dubbio avremo presto una bella sorpresa per quei nani.", enHash = "4a662d82", vanilla = true },
    },
    [847] = {
        title = { it = "L'astuzia del raptor", enHash = "eaae02e2", vanilla = true },
        text = { it = "Questo... questo potere... È questo il potere degli sciamani che Tor'gan ha cercato di mostrarmi? Devo ammettere che è interessante. Di' a Tor'gan che mi ha convinto... per il momento. Ascolterò quello che ha da dire.", enHash = "1cc24100", vanilla = true },
        objectives = { it = "Parla con Tor'gan.", enHash = "849927d6", vanilla = true },
        reward = { it = "Quando l'incantesimo svanirà, parlerò con Gor'mul. Ti ringrazio per avermi aiutato a riportare Gor'mul nel mondo dei vivi. Non ho dubbi che anche lui ti sia molto grato.", enHash = "dc41bc60", vanilla = true },
    },
    [848] = {
        title = { it = "Fungal Spores", enHash = "3886a97b", vanilla = true },
        text = { it = "Le oasi delle Barrens nascondono un mistero. Dalle loro acque scorre energia vitale, che rinvigorisce le piante e le bestie che ne bevono.\n\nRinvigorisce, e altera.\n\nC'è un fungo che cresce vicino a queste oasi. Le sue spore hanno proprietà che noi, gli speziali di Lordaeron, troviamo utili.\n\nPortami quelle spore e ti guadagnerai la nostra gratitudine.", enHash = "11208f5f", vanilla = true },
        objectives = { it = "Porta 4 Fungal Spore ad Apothecary Helbrim, al Crossroads.", enHash = "658b5d60", vanilla = true },
        progress = { it = "Le hai le spore, $N? Devo mandare un preparato alla mia socia a Thunder Bluff, e richiede quelle spore...", enHash = "8ea2d713", vanilla = true },
        reward = { it = "Ah, sì. Questi sono buoni esemplari. Potenti.\n\nAppartengo ai Reietti, e noi onoriamo i nostri patti. Ecco la tua ricompensa, $N.", enHash = "004fcdc9", vanilla = true },
    },
    [849] = {
        title = { it = "La vendetta di Gann", enHash = "787d110d", vanilla = true },
        text = { it = "Seguendo i piani di Khazgorm non dovrebbe essere un problema fabbricare una carica esplosiva.\n\nAh, ecco fatto.\n\nOra, $N, ti affiderò un incarico speciale. Prendi questo candelotto esplosivo e usalo per far saltare la macchina volante a Bael Modan.\n\nLa macchina volante non è solo un pezzo fondamentale dell'infrastruttura del sito: serve anche come arma da guerra. E soprattutto è un simbolo di potere e un insulto alla memoria della mia tribù.\n\nRendimi fiero portando a termine questa impresa eroica, e sarai $Gricompensato:ricompensata;.", enHash = "749278bc", vanilla = true },
        objectives = { it = "Distruggi la macchina volante a Bael Modan e torna da Gann Stonespire.", enHash = "d4785c3f", vanilla = true },
        progress = { it = "Una volta distrutta la macchina volante dei nani, proverò la dolce soddisfazione della vendetta.", enHash = "25c82ef9", vanilla = true },
        reward = { it = "Hai fatto bene, $N! Che a Thunder Bluff tu sia $Gonorato:onorata; come chi difende le terre sacre dei tauren e come $Gcampione:campionessa; della tribù perduta.", enHash = "d34b3700", vanilla = true },
    },
    [850] = {
        title = { it = "I capi Kolkar", enHash = "e27ed5be", vanilla = true },
        text = { it = "I centauri tormentano i tauren da anni. E di recente i centauri Kolkar delle Barrens sono diventati una minaccia vera. Di solito da queste parti erano disorganizzati, ma tra loro si sono levati nuovi capi. Che li stanno radunando.\n\nPer conservare i nostri possedimenti qui, questi capi centauri vanno distrutti.\n\nPortami la testa di Barak Kodobane. Si accampa vicino ai Forgotten Pools, a nord.\n\nSconfiggilo, poi torna da me.", enHash = "faa03bda", vanilla = true },
        objectives = { it = "Porta Barak's Head a Regthar Deathgate, a ovest del Crossroads.", enHash = "5c9bb6f2", vanilla = true },
        progress = { it = "Salve, $N. Hai Barak's Head per me?", enHash = "0202d0a7", vanilla = true },
        reward = { it = "Ben fatto, $N. I centauri sono creature vili e brutali, ma alcuni hanno l'ingegno e la visione per comandare. E quelli sono i più pericolosi.\n\nBarak era un centauro così. È un bene che sia morto.", enHash = "c6fc24e7", vanilla = true },
    },
    [851] = {
        title = { it = "Verog the Dervish", enHash = "9a078f45", vanilla = true },
        text = { it = "Il centauro Verog the Dervish vaga per le Barrens e sarà difficile da trovare. Ma la sua base è la tenda di comando dei centauri alla Stagnant Oasis, a sud-est. Forse è possibile attirarlo a te.\n\nVa' alla Stagnant Oasis, a sud-est, e attacca i centauri vicino alla tenda di comando. Sarà pericoloso, ma se riesci a ucciderne abbastanza dovrebbero dare l'allarme. E Verog verrà.\n\nPortami la sua testa e la metterò accanto a quella di Barak Kodobane.", enHash = "4e208d63", vanilla = true },
        objectives = { it = "Porta Verog's Head a Regthar Deathgate, a ovest del Crossroads.", enHash = "cfa05874", vanilla = true },
        progress = { it = "L'hai trovato Verog, $N?", enHash = "11b9408b", vanilla = true },
        reward = { it = "Molto bene. Devi averli davvero agitati, quei centauri — le nostre guardie hanno notato movimento giù vicino alla Stagnant Oasis, e probabilmente eri tu.\n\nDovresti essere $Gfiero:fiera; di quello che hai fatto, $N. C'è molto coraggio in te.", enHash = "c72c7f64", vanilla = true },
    },
    [852] = {
        title = { it = "Hezrul Bloodmark", enHash = "16db6af3", vanilla = true },
        text = { it = "Hezrul Bloodmark è il capo dei centauri Kolkar nelle Barrens. È feroce, brutale e astuto. Sconfiggerlo spezzerebbe i Kolkar e ridurrebbe di molto la minaccia che rappresentano per noi.\n\nQuindi uccidilo. Come per Barak e Verog, portami Hezrul's Head.\n\nComanda la sua gente dalla Lushwater Oasis, a sud.", enHash = "291d2b8d", vanilla = true },
        objectives = { it = "Porta Hezrul's Head a Regthar Deathgate, a ovest del Crossroads.", enHash = "f0ef86a7", vanilla = true },
        progress = { it = "È stato sconfitto Hezrul, $N?", enHash = "36e94751", vanilla = true },
        reward = { it = "Ti faccio i miei complimenti, $N. Questi centauri sono indisciplinati e non sanno incanalare la rabbia come sappiamo fare noi orchi, ma non per questo sono meno feroci. Sconfiggendoli, hai dato prova del tuo valore.", enHash = "5bb6ed4a", vanilla = true },
    },
    [853] = {
        title = { it = "Apothecary Zamah", enHash = "d01f7123", vanilla = true },
        text = { it = "Ho ridotto in emulsione le spore che mi hai portato. Ora devo mandarla alla mia socia, Apothecary Zamah. Se accettassi di portargliela tu, potrebbe offrirti qualcosa dalle nostre scorte alchemiche.\n\nSi trova nelle Pools of Vision, una grotta sotto gli sciamani di Thunder Bluff. Il sentiero che porta a quella grotta è ben nascosto, ma dovresti riuscire a trovarlo sulla rupe di Spirit Rise.\n\nFa' in fretta. Questa emulsione manterrà la sua efficacia solo per poco tempo, e prima di allora va risigillata e lavorata.", enHash = "273cc51c", vanilla = true },
        objectives = { it = "Porta le Rendered Spores ad Apothecary Zamah, a Thunder Bluff, prima che scada il tempo.", enHash = "a401bce9", vanilla = true },
        progress = { it = "Hai qualcosa da parte di Apothecary Helbrim?", enHash = "24e5c1ad", vanilla = true },
        reward = { it = "Ah, le spore delle Barrens che Helbrim stava raccogliendo. Ha ottenuto il tuo aiuto per consegnarle? Bene.\n\nE l'emulsione è ancora efficace, quindi non devi aver perso tempo nella consegna. Ben fatto, $C.", enHash = "019f9789", vanilla = true },
    },
    [854] = {
        title = { it = "Viaggio al Crossroads", enHash = "f6ef2407", vanilla = true },
        text = { it = "Avevo previsto il tuo arrivo, giovane $C. Anche se forse non sei più così giovane.\n\nCredo sia giunto il momento che tu ti spinga più a fondo in questa terra. Sento che sei $Gdestinato:destinata; a grandi cose.\n\nÈ il Crossroads che devi cercare, perché le nostre vite si sono intrecciate con quelle degli orchi, e loro hanno bisogno di aiuto. Prosegui lungo questa strada verso est, poi seguila a nord fino al Crossroads. Cerca Thork tra le sue mura: ha la benedizione della Madre Terra.", enHash = "6f538dca", vanilla = true },
        objectives = { it = "Parla con Thork al Crossroads, nelle Barrens.", enHash = "54954244", vanilla = true },
        reward = { it = "È bello vedere che altri nostri alleati sono venuti ad aiutarci da luoghi lontani come Thunder Bluff. Di nuovo, $R, ti do il benvenuto.", enHash = "6331970d", vanilla = true },
    },
    [855] = {
        title = { it = "Centaur Bracers", enHash = "f02e6daa", vanilla = true },
        text = { it = "I Kolkar sono una minaccia per le pretese dell'Orda nelle Barrens; dobbiamo ridurne le truppe. Perciò ho per te un incarico a taglia.\n\nMentre sei nei territori Kolkar, uccidi i loro guerrieri e raccogli i Centaur Bracer. Torna quando ne avrai un mucchio e l'Orda ti ricompenserà bene.", enHash = "4d549c0c", vanilla = true },
        objectives = { it = "Porta 15 Centaur Bracer a Regthar Deathgate, a ovest del Crossroads.", enHash = "b305a5a9", vanilla = true },
        progress = { it = "Come va la caccia, $N?", enHash = "2ba64745", vanilla = true },
        reward = { it = "Ben fatto. Sono certo che hai messo paura ai centauri sopravvissuti, $N. Se hanno buon senso, ora si calmeranno e smetteranno di avanzare.\n\nMa non credo che lo faranno, ed è un peccato.\n\nUn peccato... per loro.", enHash = "5ef83f92", vanilla = true },
    },
    [857] = {
        title = { it = "La Tear of the Moons", enHash = "32c55929", vanilla = true },
        text = { it = "Il potere era mio! Proprio nelle mie mani! E lo rivoglio! Lo rivoglio, ti dico!\n\nQuegli sporchi scavatori l'hanno portata alla luce... com'era bella. La chiamarono la Tear of the Moons, fu la prima grande scoperta che facemmo a Bael Modan.\n\nDoveva essere mia! Mia, ti dico!\n\nGeneral Twinbraid diventò geloso del potere che mi dava. La chiuse a chiave nel Keep. Disse che era maledetta! Lo sciocco!\n\nAltri la volevano e bisognava fermarli! Quel bastardo di Twinbraid mi ha cacciato via.\n\nOra lo rivoglio. Lo rivoglio, ti dico!", enHash = "88c3198e", vanilla = true },
        objectives = { it = "Feegly the Exiled vuole che tu recuperi per lui la Tear of the Moons.", enHash = "54cb3357", vanilla = true },
        progress = { it = "Dov'è la Tear of the Moons? Mi serve adesso! Mi serve, ti dico!", enHash = "73a58f11", vanilla = true },
        reward = { it = "Finalmente il potere è di nuovo mio! Mio, ti dico!", enHash = "e0ba43d3", vanilla = true },
    },
    [858] = {
        title = { it = "Accensione", enHash = "a5b049ed", vanilla = true },
        text = { it = "Non è che ti ha mandato Sputtervalve? Sono in un bel guaio. Sono saltato dentro senza rendermi conto che serve una chiave per sbloccare la colonna di movimento della sminuzzatrice. Uno degli altri operatori di sminuzzatrici mi ha chiesto se andava tutto bene, e sono andato nel panico! Invece di dirgli che mi mancava la chiave, gli ho detto che c'era una specie di problema meccanico.\n\nDobbiamo andarcene da qui in fretta! Sali alla sala di controllo in cima alla torre di trivellazione: il supervisore dovrebbe avere una chiave per questa sminuzzatrice.\n\nDammi una mano!", enHash = "50b8e4b9", vanilla = true },
        objectives = { it = "Prendi l'Ignition Key e portala a Wizzlecrank.", enHash = "9006b70c", vanilla = true },
        progress = { it = "Presto! Dobbiamo andarcene da qui prima che qualcuno si insospettisca!", enHash = "7656dd21", vanilla = true },
        reward = { it = "Già, sembra proprio la chiave giusta. Fammi solo controllare di saper far funzionare questo coso...\n\nHmm... controllo di rotazione... Questo regola velocità e stabilità... controllo fine del movimento del braccio. Ma guarda qua! Non posso credere che la Venture Company sia riuscita a progettare qualcosa di tanto migliore del nostro. Devo portarlo a Ratchet!", enHash = "d57c2031", vanilla = true },
    },
    [860] = {
        title = { it = "Sergra Darkthorn", enHash = "47426717", vanilla = true },
        text = { it = "Se vuoi seguire la via del cacciatore, il tuo viaggio ti porta nelle Barrens. Le sue bestie sono fiere e di volontà forte. Cacciando là imparerai molto, e il tuo spirito crescerà.\n\nParla con Sergra Darkthorn. Sarà la tua prima guida nelle Barrens.\n\nSergra è al Crossroads. Per raggiungerla, va' a est da Bloodhoof Village dentro le Barrens, poi a nord dove la strada si divide. E sta' $Gattento:attenta; mentre viaggi — le Barrens riservano grandi pericoli a chi non è preparato e non sta in guardia.", enHash = "cac5589f", vanilla = true },
        objectives = { it = "Parla con Sergra Darkthorn, al Crossroads.", enHash = "d5f4d43c", vanilla = true },
        reward = { it = "Vuoi cacciare nelle Barrens?\n\nHai occhi impazienti, e giovani. Non ancora socchiusi dal seguire la preda per le pianure aride di questa terra.\n\nMa non temere. Ti induriremo il corpo e la mente. E ti insegneremo che cacciare è più che trovare e uccidere la preda.\n\nPreparati. Il tuo viaggio comincia. Adesso.", enHash = "a6bf8479", vanilla = true },
    },
    [861] = {
        title = { it = "La via del cacciatore", enHash = "3c942e49", vanilla = true },
        text = { it = "Sei impaziente di esplorare, lo capisco. Anch'io, una volta, avevo la smania di vagare...\n\nVagare, e cacciare. Perché la caccia è il più grande onore per un tauren.\n\nSe desideri davvero seguire le vie del cacciatore, allora Melor Stonehoof può mostrarti la strada. È a Thunder Bluff, sull'Hunter's Rise.\n\nE per mostrargli la tua abilità e la tua determinazione, portagli gli artigli dei Flatland Prowler di Mulgore. Sono duri e astuti — preda adatta a $Gun giovane:una giovane; $C sul sentiero del cacciatore.", enHash = "1b2e4e0a", vanilla = true },
        objectives = { it = "Porta 4 Flatland Prowler Claw a Melor Stonehoof, a Thunder Bluff.", enHash = "852ba4ce", vanilla = true },
        progress = { it = "Salute. C'è in te un'aria che mi dice molto. Abbiamo affari da sbrigare, io e te?", enHash = "c70fb616", vanilla = true },
        reward = { it = "Skorn Whitecloud è un tauren saggio. Ha cacciato per anni e anni e, per quanto il suo corpo sia vecchio, il suo spirito arde con forza. Siamo onorati di averlo con noi.\n\nSe Skorn ti ha mandato da me, allora anche tu devi avere lo spirito del cacciatore. E aver raccolto questi artigli dimostra che le tue capacità stanno sbocciando.\n\nForse sei $Gpronto:pronta; a percorrere il sentiero.", enHash = "7f8159ce", vanilla = true },
    },
    [862] = {
        title = { it = "Dig Rat Stew", enHash = "fab9dbcc", vanilla = true },
        text = { it = "$GUn:Una; $C come te deve avere parecchia fame qui nelle Barrens. Io muoio di fame tutto il giorno.\n\nFacciamo così: ti preparo un bello stufato. Mi servono solo un po' di Dig Rat.\n\nPare che quei sudici nani di Bael Modan siano invasi dal banchetto preferito da tutti. Ora scendi a sud fino a Bael Modan e riportami un po' di Dig Rat.\n\nNon puoi dirti $Gun avventuriero esperto:un'avventuriera esperta; finché non hai passato un po' di tempo ad ammazzare ratti! Ah!", enHash = "135121db", vanilla = true },
        objectives = { it = "Porta 8 Dig Rat a Grub, a est del Crossroads.", enHash = "22656905", vanilla = true },
        progress = { it = "Hai già fatto fuori abbastanza Dig Rat, $N?", enHash = "8c3da505", vanilla = true },
        reward = { it = "Di solito non mi piace mangiare questi roditori quando sono così... così... maturi. Mi piace lasciarli marcire per qualche settimana, per far uscire davvero il sapore. Ma sembri così $Gaffamato:affamata;.\n\nLascia che ti prepari un po' di Dig Rat Stew. Ah, ecco fatto.\n\nEcco a te!", enHash = "129225b3", vanilla = true },
    },
    [863] = {
        title = { it = "La fuga", enHash = "388ef710", vanilla = true },
        text = { it = "Immagino che imparerò strada facendo... Non può essere troppo difficile. Qualche pulsante qui, una leva o due... Allora, sei $Gpronto:pronta; a partire?", enHash = "5df20e9c", vanilla = true },
        objectives = { it = "Proteggi Wizzlecrank e la sminuzzatrice goblin rubata lungo la strada verso Sputtervalve, a Ratchet.", enHash = "1788dd15", vanilla = true },
        progress = { it = "Posso aiutarti?", enHash = "ac3f9a38", vanilla = true },
        reward = { it = "Speriamo di riuscire a ricavare qualcosa di buono dal prototipo di sminuzzatrice distrutto... il tempo stringe! Manderò subito una squadra di recupero dove si trova Wizzlecrank.\n\nOh, e lascia che ti dia qualcosa per il disturbo.", enHash = "c7ea0a78", vanilla = true },
    },
    [865] = {
        title = { it = "Corni di raptor", enHash = "bc98d046", vanilla = true },
        text = { it = "I raptor delle Barrens sono più intelligenti dei raptor delle altre terre. E secondo me tutta quell'intelligenza si nasconde nei loro corni! Se è così, potrei macinare i corni fino a ridurli in polvere e usarla per fare delle \"bevande dell'intelligenza\". Le venderei per una fortuna!!!\n\nE tu puoi aiutarmi. Trovami dei corni di raptor intatti dai Sunscale Scytheclaw. Vagano nelle Barrens del sud, e nelle Barrens del nord vicino al confine con l'Ashenvale Forest.", enHash = "3edd7fdb", vanilla = true },
        objectives = { it = "Raccogli 5 Intact Raptor Horn dai Sunscale Scytheclaw e portali a Mebok Mizzyrix, a Ratchet.", enHash = "09f0820d", vanilla = true },
        progress = { it = "Li hai presi i corni, $N? Quei cosi mi faranno fare una fortuna!", enHash = "0e71528c", vanilla = true },
        reward = { it = "Ottimo, li hai presi! Ora devo solo macinarli e mescolarli con un po' di vino, e...", enHash = "45af1969", vanilla = true },
    },
    [866] = {
        title = { it = "Root Samples", enHash = "826c5acb", vanilla = true },
        text = { it = "Le erbe delle Barrens non sono proprio come quelle di altre terre. Le loro proprietà sono quasi le stesse, ma l'acqua delle oasi di qui altera le piante: sono appena un po' diverse.\n\nVoglio studiare quelle differenze... per vedere se si possono sfruttare!\n\nSe te ne intendi di erbalismo, raccogli dei Root Sample dalle erbe che trovi nelle Barrens. Portami questi campioni, così posso confrontarli con le erbe di altre regioni.", enHash = "94082f02", vanilla = true },
        objectives = { it = "Porta 8 Root Sample a Mebok Mizzyrix, a Ratchet.", enHash = "36188bd4", vanilla = true },
        progress = { it = "Ciao, $N. Hai preso quei Root Sample?", enHash = "6b0f2013", vanilla = true },
        reward = { it = "Sì sì, questi sono molto belli! Da queste radici coltiverò degli esemplari e li studierò. Spero di scoprirne proprietà nuove. Proprietà nascoste, preziose...!\n\nE non preoccuparti: se le trovo, sarai $Gil primo:la prima; a saperlo. Perché mi servirà qualcuno che ne raccolga altri!", enHash = "4329e29c", vanilla = true },
    },
    [867] = {
        title = { it = "Arpie razziatrici", enHash = "480491de", vanilla = true },
        text = { it = "Quelle maledette arpie saccheggiano i rifornimenti delle nostre carovane da troppo tempo. È ora di tagliare qualche gola e ridurne il numero.\n\nHo curiosato intorno ai loro nidi e ho capito chi comanda chi. L'attacco più devastante distruggerà una bella fetta della loro catena di comando più bassa, e poi potremo risalire fino in cima.\n\nTi faccio partire piano: elimina le Witchwing Harpy e le Witchwing Roguefeather a nord-ovest e portami 8 Witchwing Talon. Sarebbe un buon inizio...", enHash = "9f6cdf2a", vanilla = true },
        objectives = { it = "Raccogli 8 Witchwing Talon.\n\nRiportali a Darsok Swiftdagger, al Crossroads.", enHash = "4f02e1e4", vanilla = true },
        progress = { it = "Ne hai fatte a pezzi abbastanza? Continua a squarciarle e a prendere trofei. Voglio 8 Witchwing Talon.", enHash = "5044f1b6", vanilla = true },
        reward = { it = "Oh, questi sono belli. Davvero belli... Bel lavoro, $N. Non vedo l'ora di vedere altri tuoi lavori in futuro.", enHash = "0ed51d7c", vanilla = true },
    },
    [868] = {
        title = { it = "Caccia alle uova", enHash = "f62faece", vanilla = true },
        text = { it = "Ehi, $N. Mi hanno mandato al Crossroads a sorvegliare la terra e a prendere nota di quello che ci succede, per i miei padroni a Orgrimmar.\n\nUno degli oggetti dei miei studi sono quelle creature simili a insetti che si trovano a sud, nel Field of Giants. Sappiamo poco di quelle creature, e io ci tengo a scoprirne di più. Sembrano avere una loro intelligenza, più di qualunque animale normale.\n\nPrendi questo Digging Claw e raccogli qualcuna delle uova delle creature dai loro cumuli, ma sta' $Gattento:attenta;: se le allarmi, ti attaccano.", enHash = "b360aa58", vanilla = true },
        objectives = { it = "Porta 12 Silithid Egg e il Digging Claw a Korran, al Crossroads.", enHash = "057e67ca", vanilla = true },
        progress = { it = "Sta' $Gattento:attenta; con le uova che trovi, $N. Se si rompono, per me non valgono niente.", enHash = "df458854", vanilla = true },
        reward = { it = "Sono soddisfatto di te, $N. Le uova e l'attrezzo. Ben fatto.\n\nE per la tua ricompensa...", enHash = "703fde74", vanilla = true },
    },
    [869] = {
        title = { it = "Ladri raptor", enHash = "67fbde8a", vanilla = true },
        text = { it = "Non molto tempo fa un carico d'argento è stato rubato dalla nostra torre di guardia. Doveva servire a pagare le guardie del Crossroads, e quell'argento lo rivogliamo.\n\nLa cosa strana è che... la notte del furto uno dei ladri l'abbiamo preso. Ed era... un raptor! Incredibile!\n\nNon so cosa se ne facciano i raptor dell'argento. Ma non m'importa — li voglio morti, così non ci ruberanno più niente!\n\nCaccia i raptor nelle Barrens. Raccogli per me le loro teste!", enHash = "522911d7", vanilla = true },
        objectives = { it = "Porta 12 Raptor Head a Gazrog, al Crossroads.", enHash = "1d1e27b6", vanilla = true },
        progress = { it = "Le hai quelle teste, $N?", enHash = "ec623d23", vanilla = true },
        reward = { it = "Ti sei $Gsbarazzato:sbarazzata; dei raptor!\n\nGrazie, $N. Sei $Gun:una; $C di valore.", enHash = "f2f63b8f", vanilla = true },
    },
    [870] = {
        title = { it = "I Forgotten Pools", enHash = "805264a2", vanilla = true },
        text = { it = "Molto tempo fa le Barrens erano un luogo rigoglioso, brulicante di vita. Ma la guerra e il cataclisma infuriarono su questa terra, bruciandola e lasciandone un guscio arido. Così vanno le cose, e questo mi rattrista il cuore.\n\nMa negli ultimi anni nelle Barrens si sono formate nuove oasi, e la vita si muove. E nel profondo noi druidi percepiamo un potere che filtra verso la superficie.\n\nDobbiamo trovarne l'origine. Va' ai Forgotten Pools, a nord-ovest del Crossroads. Cerca nelle loro acque una fonte di potere, poi torna qui.", enHash = "4c5e8b10", vanilla = true },
        objectives = { it = "Torna a riferire a Tonga Runetotem quello che hai scoperto.", enHash = "909a9f4d", vanilla = true },
        progress = { it = "Sei $Gstato:stata; ai Forgotten Pools, $N? Hai trovato qualcosa?", enHash = "ce324fc1", vanilla = true },
        reward = { it = "Hai trovato una fenditura nel terreno, con dei gas che ne gorgogliano fuori? Strano. Potrebbe essere una risposta alle nostre domande, ma non possiamo ancora esserne certi.\n\nMa è un indizio. E ti sono grato di averlo trovato.", enHash = "65450441", vanilla = true },
    },
    [871] = {
        title = { it = "Interrompi gli attacchi", enHash = "99e60ff1", vanilla = true },
        text = { it = "Tutti i quilboar sono nostri nemici, $N. Solo che alcuni si dimostrano più fastidiosi di altri.\n\nLa tribù Razormane attacca le nostre linee di rifornimento da Durotar, e ci dà noie senza fine. Ho esploratori che cercano il capo di queste incursioni, ma fino ad allora ogni perdita che riuscirai a infliggere a quei sudici uomini-maiale ci sarà d'aiuto.\n\nComincia a nord-est, verso Durotar. Le loro tane si riconoscono sempre dagli enormi rovi spinosi che spuntano dal terreno. Trovali e uccidili.", enHash = "895a501e", vanilla = true },
        objectives = { it = "Della tribù Razormane, uccidi 8 Water Seeker, 8 Thornweaver e 3 Hunter, poi torna da Thork, al Crossroads.", enHash = "9b2d68d5", vanilla = true },
        progress = { it = "Più tempo ci vuole a fermare questi attacchi, più sarà difficile rifornire la gente del Crossroads.", enHash = "422ce94c", vanilla = true },
        reward = { it = "Hai fatto bene, $N. Quei quilboar insolenti impareranno finalmente che la potenza dell'Orda non si ignora.", enHash = "3f9ef84f", vanilla = true },
    },
    [872] = {
        title = { it = "La fine delle incursioni", enHash = "c5dd6a76", vanilla = true },
        text = { it = "Uno dei miei esploratori ha assistito a un attacco a una carovana proveniente da Durotar, $N. I colpevoli sono proprio i quilboar della tribù Razormane. E uno di loro in particolare guida le incursioni: Kreenig Snarlsnout. È stato visto a nord-est di qui, appena a sud della strada che viene da Durotar. Se vogliamo porre fine alla minaccia, Kreenig deve morire.\n\nMa per essere certi che gli attacchi cessino, dico di aggiungere la beffa al danno. Uccidi Kreenig e altri della sua tribù, e torna da me quando avrai la sua zanna.", enHash = "a06c9c5d", vanilla = true },
        objectives = { it = "Uccidi 8 Razormane Geomancer, 8 Razormane Defender e Kreenig Snarlsnout.\n\nPoi porta Kreenig Snarlsnout's Tusk a Thork, al Crossroads.", enHash = "2d815bf1", vanilla = true },
        progress = { it = "Taglia la testa al loro capo e ne seguirà il caos, $N. Impara bene questa lezione: ti servirà in futuro.\n\nQuei maiali brancoleranno senza una guida, e noi potremo riprenderci le Barrens.", enHash = "09f445e8", vanilla = true },
        reward = { it = "Ben fatto, $N. Con la morte di Kreenig gli attacchi alle nostre carovane caleranno di sicuro.\n\nLa tua gente dovrebbe essere fiera di annoverarti tra i suoi.", enHash = "a7bfa81d", vanilla = true },
    },
    [873] = {
        title = { it = "Isha Awak", enHash = "9f37a93d", vanilla = true },
        text = { it = "Il grande Isha Awak è signore di queste acque. Grande è la sua forza, e solenne il suo orgoglio. Gli umani sulla costa lo temono, perché ne ha divorati molti.\n\nMa io non lo temo. Sono grata che sia qui. È una sfida degna, e una preda onorevole.\n\nSe sei $Gpronto:pronta;, allora nuota al largo e cerca Isha Awak, il Deep Doom.\n\nIl suo spirito dimora nel suo cuore, e sentirne il battito è conoscere il proprio destino.", enHash = "47b41baa", vanilla = true },
        objectives = { it = "Porta l'Heart of Isha Awak a Mahren Skyseer.", enHash = "1f223eb7", vanilla = true },
        progress = { it = "Non temere le acque, $R.", enHash = "6086b704", vanilla = true },
        reward = { it = "Ora sei una cosa sola con Isha Awak, $N. Il suo spirito è con te. Si acquatta nei tuoi occhi...\n\nOcchi che, un giorno, impareranno a vedere.", enHash = "82268f53", vanilla = true },
    },
    [874] = {
        title = { it = "Mahren Skyseer", enHash = "8c801ac7", vanilla = true },
        text = { it = "Hai cacciato le bestie delle Barrens. Il tuo spirito è forte. Ma un cacciatore deve essere sempre pronto. Un vero cacciatore sa inseguire la preda per qualunque sentiero. Montagne e paludi non $Glo:la; faranno vacillare.\n\nE nemmeno il mare.\n\nTrova mia sorella, Mahren. Caccia le grandi bestie d'acqua lungo la costa. Sarà lei a insegnarti le loro vie.\n\nMa sta' $Gattento:attenta; mentre la cerchi, perché la costa delle Barrens è in mano agli umani.", enHash = { "ef93957e", "db657207" }, vanilla = true },
        objectives = { it = "Parla con Mahren Skyseer.", enHash = "1426867b", vanilla = true },
        reward = { it = "Ti manda mio fratello, vero? Allora devi esserti $Gguadagnato:guadagnata; la sua stima. Se hai ottenuto il rispetto di Jorn, hai anche il mio.\n\nSei $Gpronto:pronta; a percorrere ancora la via del cacciatore?", enHash = "e7a3f134", vanilla = true },
    },
    [875] = {
        title = { it = "Le luogotenenti delle arpie", enHash = "6a93d0be", vanilla = true },
        text = { it = "Ahahah, $N. Sei $Gtornato:tornata; per altro? Bene, mi piace sentirlo.\n\nQuesta volta voglio che elimini qualcuna delle luogotenenti delle arpie nelle Dry Hills. Solo le Witchwing Slayer possono essere luogotenenti, e le riconosci dagli anelli che portano. Sono una brutta razza, ma comandano alcune delle sottoposte di quella zona. Farne fuori 6 sarà un colpo decisivo al loro matriarcato.\n\nAssicurati che muoiano tra i dolori, $N. Vogliamo che quelle megere alate capiscano che cercare rogna con l'Orda è da idioti.", enHash = "5c829e35", vanilla = true },
        objectives = { it = "Raccogli 6 Harpy Lieutenant Ring dalle Witchwing Slayer e riportali a Darsok Swiftdagger, al Crossroads.", enHash = "6c5708e7", vanilla = true },
        progress = { it = "Li hai già 6 Harpy Lieutenant Ring? Devono pagare per i loro attacchi feroci contro l'Orda.", enHash = "1a74f249", vanilla = true },
        reward = { it = "Ottimo lavoro, $Gamico mio:amica mia;. Credo che andrai lontano nell'Orda.", enHash = "27f96d59", vanilla = true },
    },
    [876] = {
        title = { it = "Serena Bloodfeather", enHash = "2e941811", vanilla = true },
        text = { it = "Te la sei cavata così bene con le luogotenenti e le sottoposte che voglio chiederti un'ultima cosa.\n\nSerena Bloodfeather è la sorella di un'arpia di nome Bloodfeather, uccisa da Rexxar parecchio tempo fa. A quanto pare questi attacchi alle carovane dell'Orda sono la vendetta per la morte della sorella.\n\nVoglio che le tagli la gola e mi porti la sua testa. La metterò sulla prossima carovana che mandiamo fuori... Così quelle arpie avranno di che riflettere.", enHash = "103532da", vanilla = true },
        objectives = { it = "Uccidi Serena Bloodfeather e porta la sua testa a Darsok Swiftdagger, al Crossroads.", enHash = "50c8fa6f", vanilla = true },
        progress = { it = "Non avrai niente finché non vedo la testa di Serena.", enHash = "390e6488", vanilla = true },
        reward = { it = "HA! Ben fatto, $N! Davvero ben fatto... Non ero sicuro che fossi all'altezza, ma hai dimostrato di saper tagliare gole. Grazie ancora per averci aiutato a contenere l'epidemia di arpie. Ecco la tua ricompensa, usala bene.", enHash = "4d7a67c1", vanilla = true },
    },
    [877] = {
        title = { it = "La Stagnant Oasis", enHash = "6ae076ba", vanilla = true },
        text = { it = "Come quella che hai trovato ai Forgotten Pools, potrebbero esserci fenditure anche nelle altre oasi delle Barrens. Se è così, forse sono proprio le fenditure la fonte di vita delle oasi.\n\nDobbiamo verificarlo.\n\nEcco, prendi questi semi. Sono morti e infecondi, ma portali alla Stagnant Oasis, a sud-est. Se là c'è una fenditura, mettili dentro... e osserva.", enHash = "019d44c9", vanilla = true },
        objectives = { it = "Torna da Tonga, al Crossroads, dopo aver esplorato la Stagnant Oasis.", enHash = "afc32611", vanilla = true },
        progress = { it = "Sei $Gstato:stata; alla Stagnant Oasis? C'era una fenditura sotto le sue acque?", enHash = "6e3c99de", vanilla = true },
        reward = { it = "Quello che hai scoperto è straordinario! I semi che ti ho dato erano secchi, e morti. Qualunque cosa riposi sotto queste oasi è capace di creare vita dal nulla!\n\nDobbiamo studiarla ancora...", enHash = "03d19b6f", vanilla = true },
    },
    [878] = {
        title = { it = "Tribù in guerra", enHash = "884ca2f6", vanilla = true },
        text = { it = "Devi colpire i miei nemici. <grugnito> Devi aiutare Mangletooth e i Razormane indebolendo i Bristleback. Tutte e due le tribù sono molto spirituali — legate alla terra e al suo potere. <grugnito> Ci dà forza in ogni cosa... soprattutto in guerra.\n\nSe vuoi scoprire chi causa davvero a Thork <grugnito> e all'Orda tanto tormento, allora aiuta Mangletooth! Attacca i capi spirituali dei Bristleback a nord; indeboliscili, così i Razormane potranno sconfiggerli e dominare le Barrens.", enHash = "11e9b56b", vanilla = true },
        objectives = { it = "Uccidi 6 Bristleback Water Seeker, 12 Bristleback Thornweaver e 12 Bristleback Geomancer, poi torna da Mangletooth a Camp Taurajo, nelle Barrens.", enHash = "9947a66d", vanilla = true },
        progress = { it = "Altre informazioni <grugnito> per l'Orda quando avrai ucciso i saggi dei Bristleback, $R. <grugnito> Non un momento prima! Mangletooth non è uno sciocco.", enHash = "4b386f31", vanilla = true },
        reward = { it = "Sì, sì... pieno di gioia perché finalmente <grugnito> i Bristleback conoscono il dolore della mia tribù, $R. Così dovrei sentirmi, ma <grugnito> non è così.\n\nTu aiuti la tua gente e loro ti onorano. Mangletooth aiuta la sua gente, e loro che fanno? Gli voltano le spalle. Lo dimenticano e lo lasciano marcire in gabbia!\n\nIo li aiuto perfino da qui, chiuso dietro le sbarre, e loro non mandano nessuno a salvarmi!", enHash = "ea0e0cbc", vanilla = true },
    },
    [879] = {
        title = { it = "Tradimento dall'interno", enHash = "f7a0ef65", vanilla = true },
        text = { it = "Tre della mia tribù sono usciti dal Kraul per guidare le incursioni contro l'Orda, $R. <grugnito> Sono spietati e astuti, e se li sconfiggi, allora il tuo Crossroads e perfino gran parte delle Barrens conosceranno la pace... <grugnito> almeno da parte della tribù Razormane. <grugnito>\n\nNak, Kuz e Lok Orcbane sono quelli che cerchi. Sono molto a sud delle Barrens. Uno è un incantatore, un altro un battitore, e il loro capo, quello che chiamano Orcbane, <grugnito> un guerriero. Uccidili, $R, come hanno ucciso me.", enHash = "05b33952", vanilla = true },
        objectives = { it = "Uccidi Nak, Kuz e Lok Orcbane e porta i loro teschi a Mangletooth, a Camp Taurajo, nelle Barrens.", enHash = "bcc366bc", vanilla = true },
        progress = { it = "Come va la tua caccia, $R? <grugnito>\n\nThork crede di sapere la verità su chi guida le incursioni contro la sua gente, <grugnito> ma imparerà quanto si sbaglia, se riesci nell'impresa.\n\nLa mia morte è inevitabile, ma tu hai causato grande dolore ai miei nemici, quindi Mangletooth non rimpiange nulla. <grugnito>", enHash = "eea1f6e0", vanilla = true },
        reward = { it = "È fatta, allora. Meglio che finisca così, dice Mangletooth. <grugnito> Avrebbero dovuto <grugnito> assicurarsi che fossi morto quando mi hanno voltato le spalle, invece di lasciarmi <grugnito> qui in questa gabbia maledetta.\n\nResta un solo incarico da portare a termine, $R.", enHash = "56e7f4c0", vanilla = true },
    },
    [880] = {
        title = { it = "Creature alterate", enHash = "94764adf", vanilla = true },
        text = { it = "Quello che hai scoperto è incredibile, $N. Queste oasi hanno proprietà che devono venire da una fonte esterna. O forse interna.\n\nVoglio sapere come queste fenditure stanno agendo sulle bestie che bevono l'acqua delle oasi.\n\nCaccia gli snapjaw delle oasi alla Lushwater Oasis e alla Stagnant Oasis. Portami i loro gusci, così potrò esaminarli.", enHash = "77447224", vanilla = true },
        objectives = { it = "Porta 8 Altered Snapjaw Shell a Tonga Runetotem, al Crossroads.", enHash = "f84e82de", vanilla = true },
        progress = { it = "Come va la raccolta? Li hai presi i gusci?", enHash = "6da16e13", vanilla = true },
        reward = { it = "Grazie, $N. Studiare le bestie di un luogo può dire molto sul luogo stesso. Vedremo che storia raccontano questi gusci.\n\nAccetta la mia gratitudine per il tuo aiuto... e forse queste monete ti saranno utili. Io non ne ho bisogno.", enHash = "d14f5ed8", vanilla = true },
    },
    [881] = {
        title = { it = "Echeyakee", enHash = "dbcc8108", vanilla = true },
        text = { it = "Whitemist, Echeyakee nella lingua dei tauren, è il re dei felini della savana. Caccia con tale furtività che dicono sia come una sottile nebbia bianca sulla terra. E uccide così in fretta che le sue prede non hanno il tempo di provare paura, o dolore.\n\nI tauren dicono che è insieme misericordia e morte.\n\nScoprirai se è vero, perché ora ti metto sulla strada per cacciare Echeyakee. La sua tana è a nord-est del Crossroads, tra le ossa di kodo giganti.\n\nVa'. Suona questo corno quando arrivi alla sua tana. Suona il corno, e lui verrà.", enHash = "caee6441", vanilla = true },
        objectives = { it = "Porta Echeyakee's Hide a Sergra Darkthorn, al Crossroads.", enHash = "c1c7e507", vanilla = true },
        progress = { it = "Il grande felino ti chiama, $N.", enHash = "38feb1df", vanilla = true },
        reward = { it = "Hai battuto Echeyakee, e anche se i suoi giorni di caccia sono finiti... il suo spirito è con te. Ti mostrerà la forza che si trova nella sottigliezza, e l'onore che si trova nella misericordia.\n\nLa tua strada è ancora lunga, $C. Speriamo che tu la percorra bene.", enHash = "1d0ef22f", vanilla = true },
    },
    [882] = {
        title = { it = "Ishamuhale", enHash = "cc35ab3d", vanilla = true },
        text = { it = "Ishamuhale, Speartooth, è il più feroce dei raptor Sunscale delle Barrens. Non caccia per sport, né per fame. Caccia perché cacciare è la sua passione. Uccide perché uccidere è la sua natura.\n\nE tu conoscerai la sua natura, $N, perché la tua strada ora segue le orme artigliate di Ishamuhale.\n\nComincia la caccia. Uccidi la sua preda preferita, uno Zhevra, poi porta la carcassa all'albero morto a nord-ovest di Ratchet. Ishamuhale ne sentirà l'odore e ne sarà attirato.\n\nFatti trovare $Gpronto:pronta; quando arriva.", enHash = "dc9d5f0c", vanilla = true },
        objectives = { it = "Porta Ishamuhale's Fang a Jorn, a Camp Taurajo.", enHash = "ec793381", vanilla = true },
        progress = { it = "$N, hai battuto Ishamuhale?", enHash = "c123ba60", vanilla = true },
        reward = { it = "Questa zanna è soltanto un pegno, ma quello che rappresenta è profondo.\n\nLa forza di Ishamuhale è in te, $N. Usala con misura. Questo è il tuo fardello.\n\nQuesto è il tuo onore.", enHash = "eef62dac", vanilla = true },
    },
    [883] = {
        title = { it = "Lakota'mani", enHash = "03bda8f0", vanilla = true },
        text = { it = "L'Hoof of Lakota'mani è simbolo della forza del grande kodo.", enHash = "e0331d54", vanilla = true },
        objectives = { it = "Porta l'Hoof of Lakota'mani a Jorn, a Camp Taurajo.", enHash = "43e16af2", vanilla = true },
        progress = { it = "$N, quando ti sei $Gavvicinato:avvicinata; ho visto un potere nuovo nel tuo passo. Dimmi — il tuo spirito ha incontrato il grande Lakota'mani?", enHash = "ec2f0823", vanilla = true },
        reward = { it = "Lakota'mani nella nostra lingua si chiama \"Earthshaker\", e i suoi passi sono come tuono raccolto. Ora è con te, e il suo coraggio si mescola al tuo. Insieme non c'è scontro che non possiate affrontare.\n\nCammina a testa alta, $N. Cammina a testa alta, Earthshaker.", enHash = "d8b225b1", vanilla = true },
    },
    [884] = {
        title = { it = "Owatanka", enHash = "4dbe7cde", vanilla = true },
        text = { it = "Al tocco, dalla spina della coda di Owatanka volano scintille.", enHash = "e9997d0b", vanilla = true },
        objectives = { it = "Porta Owatanka's Tailspike a Jorn, a Camp Taurajo.", enHash = "c9136870", vanilla = true },
        progress = { it = "$N, c'è un potere nuovo dietro i tuoi occhi! Hai incontrato il possente Owatanka, non è vero?", enHash = "10b56be5", vanilla = true },
        reward = { it = "Il thunder lizard Owatanka è chiamato \"Bluebolt\" dai tauren, perché dentro di lui risiede una velocità che smentisce la sua mole. Si dice che un fulmine abbia colpito Bluebolt molto tempo fa e che, nutrita dall'ira del cielo, l'energia della grande bestia sia senza limiti.\n\nChe la sua energia scorra in te, $N. Perché ora tieni il passo di Owatanka.", enHash = "f74bc191", vanilla = true },
    },
    [885] = {
        title = { it = "Washte Pawne", enHash = "24d77a0d", vanilla = true },
        text = { it = "La piuma di Washte Pawne fa male al tatto.", enHash = "6c42f00a", vanilla = true },
        objectives = { it = "Porta Washte Pawne's Feather a Jorn Skyseer, a Camp Taurajo.", enHash = "a700e894", vanilla = true },
        progress = { it = "C'è una nuova determinazione dentro di te, $N. Una determinazione nata dal dolore...\n\nTi pesa la morte di Washte Pawne?", enHash = "a5cc05c6", vanilla = true },
        reward = { it = "Il thunderhawk è una bestia rara delle Barrens, e la sua morte può presagire grande fortuna, o grande rovina.\n\nMa Washte Pawne, chiamato \"Spirit Biter\" in Taurahe, non può portare né l'una né l'altra... o tutte e due.\n\nIl dolore che hai provato cacciando Spirit Biter è la fitta che provano tutti quelli che ottengono molto a caro prezzo. La stretta che hai sentito è il dolore del rimpianto.\n\nMa vedo che l'hai superata. Hai imparato che il rimpianto diventa saggezza, e che attraverso il dolore si guadagna forza.\n\nHai imparato molto, $N.", enHash = "bfaf498b", vanilla = true },
    },
    [886] = {
        title = { it = "Le oasi delle Barrens", enHash = "509bc54b", vanilla = true },
        text = { it = "I druidi di Thunder Bluff percepiscono uno strano potere che filtra nelle Barrens, a est di Mulgore.\n\nTonga Runetotem è stato mandato a scoprire l'origine di questo potere, ma temiamo che avrà bisogno di aiuto.\n\nVa' nelle Barrens e parla con Tonga. Sarà al Crossroads. Per arrivarci, prendi la strada che esce a est da Bloodhoof Village. Entra nelle Barrens, poi gira a nord dove la strada si divide. Continua a nord e troverai il Crossroads.\n\nE non lasciare la strada, $N, perché le Barrens sono una terra dura.", enHash = "d2717927", vanilla = true },
        objectives = { it = "Parla con Tonga Runetotem, al Crossroads.", enHash = "3d715f77", vanilla = true },
        reward = { it = "I miei fratelli di Thunder Bluff hanno fatto bene a mandarti, giovane $C. Perché il mistero delle Barrens non è di quelli che io possa sciogliere da solo.\n\nCon il tuo aiuto, speriamo di trovare risposte alle nostre domande.", enHash = "c3ee0487", vanilla = true },
    },
    [887] = {
        title = { it = "Southsea Freebooters", enHash = "abef558a", vanilla = true },
        text = { it = "Vorrei proprio che Vice Admiral Grezzlik facesse un lavoro migliore nel tenere i mari sicuri per le nostre navi mercantili. Con tutto l'oro che i principi del commercio hanno versato nelle Trade Fleets, mi fa girare le scatole vedere tanti pirati scorrazzare a piacere, assaltare le mie navi e rubarmi la roba!\n\nHo sentito che i Southsea Freebooters si sono accampati appena a sud di qui. Sono una bella spina nel fianco e, se Grezzlik non se ne occupa, be', magari puoi aiutarmi tu a sbarazzarmene.", enHash = "998a658a", vanilla = true },
        objectives = { it = "Uccidi 12 Southsea Brigand e 6 Southsea Cannoneer per Gazlowe, a Ratchet.", enHash = "144e13fe", vanilla = true },
        progress = { it = "Non voglio nemmeno pensare ai guadagni che ho perso per le razzie dei pirati, e adesso si accampano pure sull'uscio di casa mia? Sta sfuggendo di mano: a Undermine devono fare qualcosa.", enHash = "614f3f1a", vanilla = true },
        reward = { it = "Hai fatto bene, $Gragazzo:ragazza;. Ancora un po' di lavoro così e sarà un pensiero in meno. Speriamo che si convincano a spostare la baracca altrove.\n\nNel frattempo, resta la faccenduola di riprendermi la roba che mi hanno rubato!", enHash = "08cecd9d", vanilla = true },
    },
    [888] = {
        title = { it = "Bottino rubato", enHash = "581d8b8e", vanilla = true },
        text = { it = "Mi piacerebbe recuperare tutta la mia roba, ma sono sicuro che non è possibile. Però ci sono un paio di cose che devo assolutamente riavere!\n\nCome vedi, il mio osservatorio è pronto a partire, ma gli manca la più piccola delle due lenti. La prima è arrivata con una carovana da Durotar, ma la seconda viaggiava per nave, e non è mai arrivata. E poi non ho mai ricevuto il mio carico di stivali da Drizzlik, a Booty Bay!\n\nFatti un salto all'accampamento dei pirati e vedi se riesci a trovarli.", enHash = "8699158e", vanilla = true },
        objectives = { it = "Recupera lo Shipment of Boots e la Telescopic Lens per Gazlowe, a Ratchet.", enHash = "c5271e95", vanilla = true },
        progress = { it = "Le hai trovate le mie cose, $N?", enHash = "0cc1a34d", vanilla = true },
        reward = { it = "Che sollievo riavere tutta questa roba, quindi grazie dell'aiuto, $N. Sai, mi farebbe comodo $Gun:una; $R come te per dare una mano alla mia attività qui. Se mai cercassi lavoro, non dimenticarti di quanto bene paga Gazlowe per un servizio!", enHash = "9dafdcdd", vanilla = true },
    },
    [889] = {
        title = { it = "Spirito del vento", enHash = "78cd48d1", vanilla = true },
        progress = { it = "Porta a Mangletooth 10 Blood Shard e ti benedirò con una grande velocità. Correrai insieme agli Zhevra e il vento sarà geloso di te.\n\nNon durerà a lungo, ma dovrebbe bastarti per viaggiare per le Barrens.", enHash = "32e15262", vanilla = true },
        reward = { it = "Bene. Va' con lo spirito di Agamaggan a guidarti, $R. Torna da me se desideri altra magia di Agamaggan.", enHash = "82d6a678", vanilla = true },
    },
    [890] = {
        title = { it = "Il carico mancante", enHash = "7c63d2e3", vanilla = true },
        text = { it = "È una vita che aspetto l'ultimo carico di merce da Booty Bay! Sono quasi sicuro che l'abbiano rubato i Freebooter, ma per esserne certo: vai giù al molo e chiedi a Dizzywig se la mia roba è già finita nel mio magazzino a mia insaputa.\n\nEcco, porta giù il mio registro a Dizzywig e fagli confrontare le mie scritture di magazzino con i suoi libri.", enHash = "33bcbd09", vanilla = true },
        objectives = { it = "Porta Gazlowe's Ledger a Wharfmaster Dizzywig.", enHash = "3bb12a54", vanilla = true },
        progress = { it = "Merce da spedire con la prossima nave, $N?", enHash = "5e0859ab", vanilla = true },
        reward = { it = "Ah, ti manda Gazlowe, eh? Un attimo, fammi dare un'occhiata ai miei libri e accertarmi di non aver fatto mandare il carico di Gazlowe nel posto sbagliato.\n\nScommetto che aspetta quegli stivali da Drizzlek...", enHash = "f55c84a4", vanilla = true },
    },
    [891] = {
        title = { it = "I cannoni di Northwatch", enHash = "f16232b5", vanilla = true },
        text = { it = "Un'altra nave della mia flotta è andata perduta per colpa di quegli umani fanatici di Northwatch Hold!\n\nBisogna occuparsi di quei bastardi. La loro paranoia li ha messi in uno stato di frenesia: zoticoni col grilletto facile che sparano a qualunque cosa capiti a tiro.\n\nVa' a sud lungo la Merchant Coast fino al forte e assedia le loro forze. Portami le medaglie dei loro soldati come prova. E per l'amore della mia flotta, uccidi Captain Fairmount e i suoi cannonieri fanatici!", enHash = "02b9f6d5", vanilla = true },
        objectives = { it = "Captain Thalo'thas Brightsun, a Ratchet, vuole che tu raccolga 10 Theramore Medal e uccida Captain Fairmount, Cannoneer Whessan e Cannoneer Smythe.", enHash = "5f2a2afd", vanilla = true },
        progress = { it = "La mia flotta è in pericolo, con Captain Fairmount e i suoi maledetti cannonieri che bombardano da Northwatch Hold. Voglio che paghino anche i suoi soldati. Riempimi la mano con le medaglie dei loro morti e saprò che i miei corsari caduti sono stati vendicati.", enHash = "cc24a37b", vanilla = true },
        reward = { it = "Ahimè, i giusti cannoni dell'Alleanza sono stati messi a tacere. Sarai $Gricompensato:ricompensata; per il tuo aiuto, $N.\n\nOra al triste compito di recuperare i corpi dei morti...", enHash = "2b30ecd5", vanilla = true },
    },
    [892] = {
        title = { it = "Il carico mancante", enHash = "7c63d2e3", vanilla = true },
        text = { it = "Dai miei registri risulta tutto in ordine, $N. Torna da Gazlowe e digli che è andata male. Non mi stupirei se a fregargli la roba fossero stati i pirati.\n\nNon posso fare altro per lui. Ah... però potresti dirgli che ho della roba da Undermine per lui, quando ha tempo di passare a ritirarla.", enHash = "801184e1", vanilla = true },
        objectives = { it = "Riporta Gazlowe's Ledger a Gazlowe, a Ratchet.", enHash = "73de6e40", vanilla = true },
        progress = { it = "Allora, cos'ha detto Dizzywig?", enHash = "deb39013", vanilla = true },
        reward = { it = "Niente da fare, eh? Allora devono essere stati i Freebooter... Dizzywig è uno onesto, sono sicuro che non mi fregherebbe così. In fondo è sul mio libro paga.\n\nPare che abbia della roba da riprendermi, $N. Che ne dici?", enHash = "069ff98c", vanilla = true },
    },
    [893] = {
        title = { it = "Armi preferite", enHash = "78c64d01", vanilla = true },
        text = { it = "I quilboar Razormane a sud, oltre il Field of Giants, non hanno fabbri esperti, da quel che mi risulta, ma a quanto pare hanno cominciato a mettere a punto armi più robuste. Vorrei mettere le mani su qualche tipo diverso, per imparare le loro tecniche, se possibile.\n\nSe vuoi portare onore all'Orda, allora portami degli esemplari delle loro armi. Trovami un pugnale dai loro Stalker, una bacchetta dai loro Seer e uno scudo dai loro Warfrenzy. Sarebbe perfetto!", enHash = "82e8b91b", vanilla = true },
        objectives = { it = "Porta un Razormane Backstabber, un Charred Razormane Wand e un Razormane War Shield a Tatternack Steelforge, a Camp Taurajo, nelle Barrens.", enHash = "18b6a07a", vanilla = true },
        progress = { it = "Anch'io dubito che quei patetici quilboar possano raggiungere un qualche livello di abilità nella forgiatura, ma faccio come comanda il Capoguerra, e imparerò quello che posso sulla tribù Razormane.\n\nHo avuto incarichi più umili di questo, e li svolgo volentieri se servono al popolo degli orchi.", enHash = "aac7ec22", vanilla = true },
        reward = { it = "Esemplari eccellenti, davvero eccellenti.\n\nI quilboar sono più avanti di quanto mi aspettassi.\n\nEcco, $C, prendi questo e togliti di mezzo. È meglio che dia un'occhiata più attenta a queste armi. Potremmo aver sottovalutato il nemico, ed è il tipo di errore che non possiamo permetterci.", enHash = "a176d956", vanilla = true },
    },
    [894] = {
        title = { it = "Samophlange", enHash = "7aa77acf", vanilla = true },
        text = { it = "La Venture Company ha messo su un piccolo impianto di ricerca molto più a nord di qui, a sud-ovest dello Sludge Fen. Non so granché di quello che combinano, ma sono riuscito a scoprire che stanno sperimentando una cosa chiamata \"samophlange\".\n\nE che diamine sarebbe un samophlange? Be', qualunque cosa sia, voglio esaminarlo, quindi mi serve qualcuno che vada a prenderlo.\n\nMi sono procurato una copia del manuale d'uso del loro sistema di controllo: da lì dovresti riuscire a capire come staccare il samophlange.", enHash = "dcab3508", vanilla = true },
        objectives = { it = "Accedi alla console di controllo nel sito di ricerca della Venture Company.", enHash = "e50f5c17", vanilla = true },
        reward = { it = "Una varietà di pulsanti, leve e spie lampeggianti è disposta in modo piuttosto disordinato sulla faccia della console di controllo. Un piccolo indicatore segnala che l'apparecchio sta funzionando entro i livelli ottimali, e che le valvole di controllo da uno a tre sono aperte. Sul lato inferiore destro del pannello c'è una piccola serratura.", enHash = "e2828b38", vanilla = true },
    },
    [895] = {
        title = { it = "WANTED: Baron Longshore", enHash = "4e478b4e", vanilla = true },
        text = { it = "WANTED!\n\nBaron Longshore, capitano dell'Heedless\n\nIl capitano Longshore di Gilneas comanda navi dei Southsea Freebooters ed è ricercato con l'accusa di pirateria. I resti devono essere in condizioni riconoscibili!\n\n— Gazlowe", enHash = "162909eb", vanilla = true },
        objectives = { it = "Porta la testa di Baron Longshore a Gazlowe, a Ratchet.", enHash = "a83ce9df", vanilla = true },
        progress = { it = "Che si dice? Posso esserti utile in qualcosa? Merce da spedire, magari un lavoro d'ingegneria?", enHash = "b955a619", vanilla = true },
        reward = { it = "Ahhhh! Quel genere di affari. Sai, una volta ho visto l'Heedless in mare aperto. Nave temibile, o era battello... i marinai sono così pignoli!\n\nComunque, guardarla scivolare sull'acqua era proprio uno spettacolo. Sono contento che il suo famigerato capitano non darà più noie alle mie navi.", enHash = "996c5557", vanilla = true },
    },
    [896] = {
        title = { it = "La fortuna del minatore", enHash = "5f54c90c", vanilla = true },
        text = { it = "Essendo Wharfmaster di un porto trafficato come Ratchet, so sempre che aria tira. So tutto degli scambi di merci e denaro tra qui e Booty Bay.\n\nL'ultima notizia che mi è arrivata riguarda la miniera Boulder Lode della Venture Company, a nord-est dello Sludge Fen. Uno dei minatori ha scoperto uno smeraldo grosso come il tuo pugno. Conosco qualche compratore che sarebbe interessato a mettere le mani su una cosa del genere, e sarei disposto a fare a metà sulla vendita.", enHash = "8cd824d0", vanilla = true },
        objectives = { it = "Recupera il Cats Eye Emerald da uno dei Venture Co. Overseer o Enforcer per Wharfmaster Dizzywig, a Ratchet.", enHash = "5187ea40", vanilla = true },
        progress = { it = "Se solo sapessimo quale dei minatori ha trovato lo smeraldo, sarebbe una passeggiata...", enHash = "1d514452", vanilla = true },
        reward = { it = "Ma guarda che roba, $N! Diventeremo ricchi! Vediamo, stando ai prezzi che ho visto sulle gemme che arrivano a Undermine, dovrei riuscire a calcolare la tua parte — cinquanta per cento, non preoccuparti!\n\nVediamo un po'... Credo che così ci siamo. È un piacere fare affari con te, $N.", enHash = "54316cce", vanilla = true },
    },
    [897] = {
        title = { it = "The Harvester", enHash = "70b96ce7", vanilla = true },
        text = { it = "Questa strana creatura simile a un insetto sembra fuori dall'ordine naturale, come se non appartenesse alle Barrens.", enHash = "c5a3c44b", vanilla = true },
        objectives = { it = "Porta l'Harvester's Head a Jorn Skyseer.", enHash = "b1c0214d", vanilla = true },
        progress = { it = "Sembravi $Gturbato:turbata;, $N. Come vanno le tue lezioni nelle Barrens? Hai trovato qualcosa che ti inquieta?", enHash = "cc96c727", vanilla = true },
        reward = { it = "Non posso dire nulla della natura di questa bestia, perché il suo spirito è fuggito. Ma come avevi intuito, non appartiene alle Barrens. Temo che possa annunciare un futuro cupo per la nostra gente...\n\nMa per ora preparati, e speriamo che il tempo sciolga il mistero di questa creatura.", enHash = "3fbc3464", vanilla = true },
    },
    [898] = {
        title = { it = "Libero dal forte", enHash = "b9c62810", vanilla = true },
        text = { it = "Finalmente! Qualcuno venuto a salvarmi!\n\nNon posso credere che tu sia $Griuscito:riuscita; a passare le guardie. Questi fanatici di Theramore sono fuori di testa. Hanno affondato la nostra nave e hanno imprigionato me, l'unico sopravvissuto. Mi hanno definito un nemico e una minaccia per l'Alleanza.\n\nIo! Una minaccia per quella loro grande finta Alleanza? Ero un mozzo su un trasporto di contrabbando tra Ratchet e Booty Bay.\n\nBasta chiacchiere. Mi aiuti a tornare a Ratchet? Fammi sapere quando sei $Gpronto:pronta; e ce la filiamo.", enHash = "cdcd787f", vanilla = true },
        objectives = { it = "Scorta Gilthares Firebough sano e salvo fino a Captain Brightsun, a Ratchet.", enHash = "15d8d26c", vanilla = true },
        progress = { it = "Sì?", enHash = "00388a38", vanilla = true },
        reward = { it = "E pensare che credevamo Firebough morto da un pezzo!\n\nIl tuo eroismo ti ha guadagnato un posto d'onore tra i Thalo'dan Privateer, $N.", enHash = "bc1fce11", vanilla = true },
    },
    [899] = {
        title = { it = "Divorato dall'odio", enHash = "fb7e5dc7", vanilla = true },
        text = { it = "Forse conosci il dolore dell'incertezza, forse no, $C. Ma sappi questo: io sto qui ogni giorno, dal sorgere del sole al suo calare, a scrutare l'orizzonte in cerca di altri di quei mostri. Da allora ho ucciso ogni uomo-maiale in cui mi sono imbattuto, ma la mia sete del loro sangue è lontana dall'essere spenta. Forse, invece di andare a nord al Crossroads, avrei dovuto andare a Taurajo.\n\nTu, $C — tu potresti aiutarmi.\n\nUccidili. Uccidine più che puoi. Portami le loro zanne, e festeggeremo insieme la loro morte.", enHash = "0b10ec80", vanilla = true },
        objectives = { it = "Porta 60 Bristleback Quilboar Tusk a Mankrik, al Crossroads.", enHash = "b07f16de", vanilla = true },
        progress = { it = "I quilboar la pagheranno, $N. Lo giuro.", enHash = "1108f5df", vanilla = true },
        reward = { it = "$C, prendi sul serio il mio incarico, e di questo ti ringrazio.\n\nAnche se il desiderio di vendetta resta, almeno posso sorridere vedendo che i quilboar hanno provato il dolore anche loro.", enHash = "817033cf", vanilla = true },
    },
    [900] = {
        title = { it = "Samophlange", enHash = "7aa77acf", vanilla = true },
        text = { it = "Le tre valvole di controllo sono aperte. Le varie letture sul pannello di controllo ti fanno supporre che vadano chiuse prima di poter spegnere l'apparecchio.", enHash = "3aa7ff9a", vanilla = true },
        objectives = { it = "Chiudi la Fuel Control Valve, la Regulator Valve e la Main Control Valve, poi usa di nuovo la console di controllo.", enHash = "906c2b40", vanilla = true },
        progress = { it = "Le spie lampeggianti sulla console di controllo indicano che le valvole di controllo principali non sono state chiuse.", enHash = "3ace659d", vanilla = true },
        reward = { it = "Le spie delle tre valvole di controllo si affievoliscono mentre vengono chiuse. Le luci verdi sfumano lentamente nel giallo, e l'interruttore che comanda l'apparecchio ora si muove: con le valvole chiuse, si può spegnere.", enHash = "6c5eb99f", vanilla = true },
    },
    [901] = {
        title = { it = "Samophlange", enHash = "7aa77acf", vanilla = true },
        text = { it = "Con l'apparecchio disattivato, il pannello di controllo si può aprire e il samophlange si può staccare dalla console. Tutto il resto è a posto: non resta che procurarsi la chiave per sbloccare la console.", enHash = "964a0f2b", vanilla = true },
        objectives = { it = "Prendi la Console Key da Tinkerer Sniggles e usala sulla console di controllo.", enHash = "09230abf", vanilla = true },
        progress = { it = "Le spie della console sono spente e gli indicatori e i quadranti segnano tutti lo zero: tutto è fermo.", enHash = "0e7d09ed", vanilla = true },
        reward = { it = "Girando la chiave nella serratura, la console di controllo si sblocca. Una spia rossa in cima alla console si spegne e tutta l'energia defluisce dal terminale.", enHash = "8f92f8ba", vanilla = true },
    },
    [902] = {
        title = { it = "Samophlange", enHash = "7aa77acf", vanilla = true },
        text = { it = "Aprendo il pannello frontale della console di controllo si scopre un fitto groviglio di fili, tubi e altri strani oggetti meccanici — la maggior parte dei quali sembra non servire a niente di pratico. Spostandoli da parte e scavando più a fondo nella console, trovi il samophlange. Uno strattone lo stacca dal suo alloggiamento.", enHash = "ddbe85e4", vanilla = true },
        objectives = { it = "Riporta il Samophlange a Sputtervalve, a Ratchet.", enHash = "45707e30", vanilla = true },
        progress = { it = "Oh, sei $Gtornato:tornata;, $N! Hai il samophlange?", enHash = "fbc45cfd", vanilla = true },
        reward = { it = "Questo è... ehm... interessante... sì. Lo farò mandare al quartier generale della Tinkers' Union a Undermine. Sono sicuro che dopo un'accurata dissezione e un po' di ricerca riusciranno a cavarne qualcosa.\n\nMa forse prima ci do un'occhiatina io...", enHash = "a3cb9b79", vanilla = true },
    },
    [903] = {
        title = { it = "I prowler delle Barrens", enHash = "572a240f", vanilla = true },
        text = { it = "Adesso è ora di andare a caccia di qualcosa che morde davvero. I prowler delle Barrens sono una razza dura. Duri, pieni di risorse, scaltri... e letali. Li troverai tra l'erba alta. Ne troverai molti a sud-ovest del Crossroads.\n\nSta' $Gattento:attenta; mentre li cacci, $N, o potresti ritrovarti a non essere più $Gil predatore:la predatrice;, ma la preda.", enHash = "2beeed03", vanilla = true },
        objectives = { it = "Raccogli 7 Prowler Claw dai Savannah Prowler per Sergra Darkthorn, al Crossroads.", enHash = "1e8b30ed", vanilla = true },
        progress = { it = "Come va la caccia, $N? Li hai trovati i prowler?", enHash = "28094fb0", vanilla = true },
        reward = { it = "Ah, vedo che hai avuto da fare, in agguato tra l'erba a cacciare prowler. Allora, credi che sia ora di affrontare un campione tra loro?", enHash = "e4851cb5", vanilla = true },
    },
    [905] = {
        title = { it = "Gli scytheclaw infuriati", enHash = "21c6f15e", vanilla = true },
        text = { it = "Adesso, $N, la caccia si fa più profonda. Ora devi sconfiggere la tua preda, e poi trovare la strada per la sua tana.\n\nCaccia i raptor Sunscale a sud. Uccidili e strappa via le piume che portano. Metti le piume sui nidi degli scytheclaw a sud-ovest della Stagnant Oasis. Mostra ai loro simili che non li temi!", enHash = "2271aa04", vanilla = true },
        objectives = { it = "Uccidi i raptor Sunscale e raccogli le loro piume. Usa le piume sui 3 nidi degli Scytheclaw. Torna da Sergra Darkthorn, al Crossroads.", enHash = "b2b1d0d2", vanilla = true },
        progress = { it = "Ci sei $Gstato:stata; ai nidi, $N?", enHash = "c0a189bf", vanilla = true },
        reward = { it = "Dunque sei $Gandato:andata; ai nidi e ci hai messo dentro le piume della tua preda. Ci è voluto un bel po' di coraggio, non c'è dubbio.\n\nTi senti un po' più $Gduro:dura;, $N? Perché adesso sembri più $Gtemprato:temprata; di quando sei $Garrivato:arrivata; qui la prima volta. Direi che le Barrens stanno facendo il loro lavoro.", enHash = "01d001b2", vanilla = true },
    },
    [906] = {
        title = { it = "Tradimento dall'interno", enHash = "f7a0ef65", vanilla = true },
        text = { it = "Porta la testa di Lok a Thork, al Crossroads, $R. <grugnito> Dovrebbe capire cos'è successo alla mia tribù senza bisogno di parole — ah, non che crederebbe mai che Mangletooth abbia avuto parte <grugnito> in queste cose. Ma sono sicuro che ti ricompenserà per aver compiuto un'impresa simile. <grugnito>\n\nContinuerò a benedirti con il potere di Agamaggan finché resterò in questa gabbia, $R. Fino ad allora, addio.", enHash = "8a28c807", vanilla = true },
        objectives = { it = "Porta Lok's Skull a Thork, al Crossroads, nelle Barrens.", enHash = "84d4a488", vanilla = true },
        progress = { it = "Sì, che c'è?", enHash = "87528bdf", vanilla = true },
        reward = { it = "Hai trovato il capo dei Razormane e l'hai ucciso con le tue mani, $N? Straordinario.\n\nSono senza parole, ma questo non vuol dire che sia senza gratitudine. La gente del Crossroads farebbe bene a rispettare la tua forza.\n\nDevo ammetterlo: credevo che il capo di queste incursioni alle nostre linee di rifornimento fosse un altro quilboar. Grazie ancora, $N.", enHash = "428655dd", vanilla = true },
    },
    [907] = {
        title = { it = "I thunder lizard infuriati", enHash = "d707a4ef", vanilla = true },
        text = { it = "Adesso, $N, devi affrontare i grandi thunder lizard. Sono bestie così enormi che il terreno rimbomba quando calpestano le pianure. Sta' $Gattento:attenta; mentre li combatti: un passo falso e potresti ritrovarti sotto le loro zampe.\n\nTroverai i thunder lizard nelle Barrens del sud. Li chiamano Stormsnout, Stormhide e Thunderhead. Torna da me quando li avrai battuti.", enHash = "d1659c1b", vanilla = true },
        objectives = { it = "Porta 3 Thunder Lizard Blood a Jorn Skyseer, a Camp Taurajo.", enHash = "f990fc37", vanilla = true },
        progress = { it = "Sono stati sconfitti i thunder lizard, $N?", enHash = "b86c5a35", vanilla = true },
        reward = { it = "È bello vederti tornare con la prova della vittoria. Ed è bello sapere che l'hai fatto con le ossa intatte.", enHash = "6fb05e7a", vanilla = true },
    },
    [908] = {
        title = { it = "Tra le rovine", enHash = "89a69019", vanilla = true },
        text = { it = "Il Martello del Crepuscolo si è insediato nelle Moonshrine Ruins delle Blackfathom Deeps. La sua presenza non può che costringere gli elementi a lavorare contro di noi. Se non lo fermiamo, questa regione sarà sua per sempre.\n\n$N, va' a Blackfathom e trova la Fathom Stone delle rovine; dovrebbe essere lì vicino, nell'acqua. Dentro c'è un Fathom Core, un congegno che, letto come si deve, racconta la storia di tutta l'attività elementale. Se l'avrò io, io e il Circolo della Terra potremo forse fare qualcosa per fermarlo!", enHash = "f167810f", vanilla = true },
        objectives = { it = "Porta il Fathom Core a Je'neu Sancrea, allo Zoram'gar Outpost, in Ashenvale.", enHash = "ee0f4063", vanilla = true },
        progress = { it = "Sei $Griuscito:riuscita; a individuare il Fathom Core? Senza, non avremo idea di cosa stia combinando esattamente il Martello del Crepuscolo laggiù.", enHash = "ee8d31de", vanilla = true },
        reward = { it = "È esattamente quello che mi serve! Un Fathom Core è una fonte incredibile di informazioni, da cui potremo ricavare molto di buono. Qualunque cosa stia combinando il Martello del Crepuscolo là dentro — e credimi quando dico che non è niente di buono — io e i miei compagni ora la scopriremo.\n\nOggi qui hai fatto bene; il Circolo della Terra ti guarda con favore per averci aiutato. Hai aiutato anche l'Orda tutta, e di questo dovresti essere $Gfiero:fiera;.", enHash = "8f6a7b42", vanilla = true },
    },
    [909] = {
        title = { it = "Baron Aquanis", enHash = "f663acee", vanilla = true },
        text = { it = "L'elementale dell'acqua sconfitto ha lasciato uno strano globo d'acqua. Immagini che l'oggetto alimentasse in qualche modo la bestia. Dentro il globo sciaborda un'acqua dall'aspetto putrido. Il globo in sé sembra impermeabile a qualsiasi forza fisica.\n\nSe c'è qualcuno che può venire a capo di questo oggetto, è Je'neu Sancrea del Circolo della Terra. Si trova allo Zoram'gar Outpost dell'Orda, in Ashenvale.", enHash = "5d84f665", vanilla = true },
        objectives = { it = "Porta lo Strange Water Globe a Je'neu Sancrea, allo Zoram'gar Outpost, in Ashenvale.", enHash = "e80212f5", vanilla = true },
        progress = { it = "Ah, ciao di nuovo, $N. Stavo giusto leggendo le onde del mare, come faccio sempre. Cosa ti porta all'avamposto?", enHash = "b8adeaea", vanilla = true },
        reward = { it = "Questo... questo è proprio un bel ritrovamento, $N.\n\nDici di averlo preso a Baron Aquanis, a Blackfathom? Baron Aquanis è considerato da tempo una potenza elementale corrotta; questo globo dimostrerà che cosa esattamente lo abbia corrotto. Non sarebbe una sorpresa scoprire che è stato il Martello del Crepuscolo, ma i nostri studi mostreranno anche come ci è riuscito.\n\nHai fatto bene a portarmelo. Ti prego — prendi questo, insieme ai più calorosi saluti del Circolo della Terra.", enHash = "6b6d814f", vanilla = true },
    },
    [910] = {
        title = { it = "Giù al porto", enHash = "5c06af42", vanilla = true },
        text = { it = "Ho sentito racconti sulle grandi navi che fanno la spola tra Ratchet e Booty Bay! Sarebbe fantastico navigare sull'oceano e combattere in tante grandi battaglie navali. Forse da grande sarò un grande marinaio dell'Orda! Sì!\n\nMi porteresti a vedere il porto di Ratchet, per piacere? Prometto che non entrerò in acqua e non combinerò guai: voglio solo vedere le navi grandi e sentire l'odore dell'acqua salata! Sì!", enHash = "4ec6222c", vanilla = true },
        objectives = { it = "Porta il tuo protetto al porto di Ratchet, nelle Barrens.", enHash = "e532ef61", vanilla = true },
        progress = { it = "Siamo arrivati?", enHash = "5cf70a59", vanilla = true },
        reward = { it = "Wow, l'oceano è ENORME! C'erano anche tanti gabbiani e roba del genere: è rumoroso e movimentato proprio come pensavo. E ci sono pure dei pirati qui vicino: troppo forte!\n\nGrazie di avermi portato a Ratchet, $N. È stato fantastico!", enHash = "a0a11aaf", vanilla = true },
    },
    [911] = {
        title = { it = "La porta della frontiera", enHash = "629c0685", vanilla = true },
        text = { it = "Dicono che Ashenvale sia la nuova frontiera, e che il Mor'shan Rampart, nelle Barrens, ne sia la porta. Sarebbe fantastico essere un pioniere e ricavare tutto quello che ti serve dalle terre selvagge! Dicono che sarà lì che l'Orda e l'Alleanza si scontreranno di più in futuro, e io voglio esserci, $N!\n\nMi porteresti al Mor'shan Rampart, così vedo com'è la frontiera, per piacere? Voglio vedere dove l'Orda sta cacciando via quei puzzolenti elfi della notte!", enHash = "c4cbaa76", vanilla = true },
        objectives = { it = "Porta il tuo protetto al Mor'shan Rampart, nella parte settentrionale delle Barrens, poco prima di entrare ad Ashenvale.", enHash = "657da00c", vanilla = true },
        progress = { it = "Siamo arrivati?", enHash = "5cf70a59", vanilla = true },
        reward = { it = "Wow, è ad Ashenvale che si vivono le vere avventure! Hai mai combattuto ad Ashenvale, $N? Quando da grande diventerò un eroe, voglio venire ad Ashenvale a combattere per la gloria dell'Orda!\n\nGrazie di avermi portato alla frontiera, $N. Sei $Gil migliore:la migliore;!", enHash = "57b898b9", vanilla = true },
    },
    [912] = {
        title = { it = "Stonesplinter Trogg Disguise", enHash = "50252bdc", vanilla = true },
    },
    [913] = {
        title = { it = "Il grido del thunderhawk", enHash = "65755cef", vanilla = true },
        text = { it = "Il thunderhawk, $N, è una bestia feroce. È ora che tu li affronti. Devi trovare dove si aggira e portarmi le sue ali come prova della caccia riuscita.\n\nFa' questo, e il tuo tempo con me sarà vicino alla fine.", enHash = "94bd0c3e", vanilla = true },
        objectives = { it = "Trova e uccidi un Thunderhawk, poi porta le sue ali a Jorn Skyseer, a Camp Taurajo.", enHash = "bd634d17", vanilla = true },
        progress = { it = "È fatta? Hai ucciso il thunderhawk?", enHash = "82907367", vanilla = true },
        reward = { it = "Tu, come il thunderhawk, dovresti essere $Gfiero:fiera;. Hai battuto ogni nemico che ti abbiamo messo davanti, e l'hai fatto con forza, coraggio e onore.\n\nMa la tua strada, $N, continua. Anzi, scoprirai che i veri cacciatori si sforzano per sempre, e per sempre percorrono la loro strada con lo stesso orgoglio che hai mostrato a me.\n\nOra è tempo di andare avanti.", enHash = "2958a921", vanilla = true },
    },
    [914] = {
        title = { it = "I capi dei Druids of the Fang", enHash = "cd03a396", vanilla = true },
        text = { it = "I druidi delle Wailing Caverns, i Druids of the Fang, sono un'aberrazione. Facevano parte di un ordine di nobili druidi il cui piano era guarire le Barrens, ma ora cercano di rifare quella terra a immagine dei loro sogni contorti.\n\nI Druids of the Fang hanno quattro capi, e ognuno possiede una gemma di sogno. Perfino adesso le loro facce mi perseguitano! Sconfiggi i capi e portami le loro gemme, e le Barrens potranno conoscere di nuovo la pace.\n\nVa', $N. Li troverai in agguato nel profondo delle Wailing Caverns.", enHash = "a73067ae", vanilla = true },
        objectives = { it = "Porta le Gems of Cobrahn, Anacondra, Pythas e Serpentis a Nara Wildmane, a Thunder Bluff.", enHash = "9a7a3c39", vanilla = true },
        progress = { it = "I ricordi dei miei incubi mi perseguitano, $N. Hai sconfitto i capi dei Druids of the Fang e preso le loro gemme?", enHash = "4bb3dc74", vanilla = true },
        reward = { it = "Ce l'hai fatta, $N. Hai ucciso i capi dei Druids of the Fang. I miei sogni ora sono liberi dalle loro facce malvagie, e hai contribuito a salvare le Barrens da un futuro maledetto.\n\nTi ringrazio, $N. Ti ringrazio per me, per i druidi di Thunder Bluff e per la terra.", enHash = "ca95bb6f", vanilla = true },
    },
    [915] = {
        title = { it = "Tu gridi, io grido...", enHash = "3c38ae24", vanilla = true },
        text = { it = "GELATO! Oh, per piacere per piacere per piacere, mi prendi un gelato?! La fragola è il mio gusto preferito, e al mondo non c'è gelato alla fragola migliore del Tigule and Foror's Strawberry Ice Cream! È il mio gelato preferito in tutto il mondo!\n\nL'ho mangiato una volta, tanto tempo fa, quando ero alla pista da corsa delle Shimmering Flats, ma ho sentito dire che adesso potrebbero venderlo in città! Per piacere? Per piacere per piacere? Con sopra il Tigule and Foror's Strawberry Ice Cream??!?!", enHash = "749aca00", vanilla = true },
        objectives = { it = "Procura un po' di Strawberry Ice Cream al tuo protetto. Il ragazzo sembra preferire il gelato della marca di Tigule e Foror.", enHash = "b98ea83f", vanilla = true },
        progress = { it = "Vorrei che facessero altri gusti di gelato oltre alla fragola, ma immagino di essere fortunato, visto che la fragola è il mio preferito!", enHash = "9fc07ff4", vanilla = true },
        reward = { it = "Mmmmmmmmm! Adoro il loro gelato alla fragola! Se c'è una cosa che Tigule e Foror sanno fare, è il gelato!\n\nGrazie mille, $N: è la cosa più buona di sempre!", enHash = "7c86dd83", vanilla = true },
    },
    [916] = {
        title = { it = "Veleno di Webwood", enHash = "b13580de", vanilla = true },
        text = { it = "Sono qui a Shadowglen per osservare i Webwood Spider che vivono nella Shadowthread Cave. Sono cugini di una varietà di ragni molto più piccola; credo che l'albero del mondo abbia avuto su di loro un effetto profondo, e vorrei degli esemplari da studiare per averne conferma.\n\nPer prima cosa, vorrei un po' del loro veleno. Raccogli le Webwood Venom Sac dai ragni dentro e intorno alla Shadowthread Cave, a nord. Così potrò esaminarle e cercare somiglianze con il veleno dei loro cugini più piccoli.", enHash = "33d80081", vanilla = true },
        objectives = { it = "Porta 10 Webwood Venom Sac a Gilshalan Windwalker, ad Aldrassil.", enHash = "d5d59caf", vanilla = true },
        progress = { it = "Hai raccolto le Webwood Venom Sac, $N?", enHash = "1c84bcae", vanilla = true },
        reward = { it = "Grazie, $N. Quando tornerò a Darnassus confronterò il veleno di queste sacche con quello di altri ragni. Credo che avrà delle proprietà legate alla recente crescita del nostro nuovo albero del mondo.", enHash = "cc1b03e5", vanilla = true },
    },
    [917] = {
        title = { it = "Webwood Egg", enHash = "55f5f366", vanilla = true },
        text = { it = "Ora che ho il veleno dei ragni, vorrei qualche esemplare vivo da studiare. Purtroppo catturare un ragno gigante vivo è più di quanto possa chiederti, giovane $C. E un ragno gigante è troppo anche per me!\n\nMa se trovassi un uovo non schiuso, portare degli esemplari sarebbe molto più facile, e potrei poi fare in modo che i ragni non ancora nati vengano custoditi.\n\nDeve esserci un nido nelle profondità della Shadowthread Cave. Ti prego, cerca un uovo nel nido e portamelo.", enHash = "bd521c82", vanilla = true },
        objectives = { it = "Porta un Webwood Egg a Gilshalan, ad Aldrassil.", enHash = "37f5e977", vanilla = true },
        progress = { it = "Sei $Gstato:stata; nella Shadowthread Cave, $N? Hai trovato un uovo di ragno?", enHash = "c3c9de27", vanilla = true },
        reward = { it = "Ah, molto bene. Farò trasportare quest'uovo e il veleno a Darnassus, e tornerò lì quando avrò finito i miei studi qui. Mi aspetto di scoprire molto da questi esemplari, $N. Mi sei $Gstato:stata; di grande aiuto.", enHash = "a29aad45", vanilla = true },
    },
    [918] = {
        title = { it = "Timberling Seed", enHash = "e92bbfaf", vanilla = true },
        text = { it = "I Timberling di Teldrassil sono elementali della natura. Per certi versi riflettono l'ordine naturale delle piante e degli animali sul nostro grande albero.\n\nPer questo è inquietante vedere quanto siano diventati rabbiosi.\n\nCredo che abbia a che fare con il terreno. Ho lavorato a metodi diversi per nutrire le piante e vorrei provarli sui semi dei Timberling. Ti prego, puoi raccogliere i semi dai Timberling intorno al Lake Al'Ameth e portarmeli?", enHash = "3d6a4a6d", vanilla = true },
        objectives = { it = "Porta 8 Timberling Seed a Denelan, al Lake Al'Ameth.", enHash = "135d0db0", vanilla = true },
        progress = { it = "Hai i semi? Non vedo l'ora di piantarli.", enHash = "cdd169cf", vanilla = true },
        reward = { it = "Li hai presi. Bene!\n\nPianterò questi semi in un terreno speciale che ho preparato. Credo che i semi germoglieranno in Timberling molto più docili. Forse più avanti potrai vedere i risultati!", enHash = "66fa5ca3", vanilla = true },
    },
    [919] = {
        title = { it = "Timberling Sprout", enHash = "60bc2667", vanilla = true },
        text = { it = "Piccoli Timberling stanno spuntando intorno alle acque del Lake Al'Ameth. Temo che per questi germogli non ci sia più nulla da fare — dovremmo cercare di toglierli dalla terra prima che crescano abbastanza da creare guai.\n\nQuando giri intorno al lago, se vedi dei Timberling Sprout, prendili, per favore. Aiutaci a tenere pulita la nostra terra!", enHash = "dab7f280", vanilla = true },
        objectives = { it = "Porta 12 Timberling Sprout a Denalan, al Lake Al'Ameth.", enHash = "4d062141", vanilla = true },
        progress = { it = "Salve, $N. Hai trovato dei germogli vicino alle acque?", enHash = "10cd0eaf", vanilla = true },
        reward = { it = "Quanti! Temo che si stiano diffondendo a un ritmo pericoloso. Spero di riuscire a risolvere l'enigma di ciò che li sta contaminando.\n\nGrazie del tuo aiuto, $N. Grazie a te la terra è un luogo più pulito.", enHash = "1fbcb6ba", vanilla = true },
    },
    [920] = {
        title = { it = "La convocazione di Tenaron", enHash = "a2d527eb", vanilla = true },
        text = { it = "$N, giusto? Ho sentito che Tenaron ha chiesto di te. Lo troverai nella stanza più alta, in cima ad Aldrassil.\n\nAnche se viviamo a lungo, è meglio non farlo aspettare troppo.", enHash = "7cc4e4c5", vanilla = true },
        objectives = { it = "Parla con Tenaron Stormgrip in cima ad Aldrassil, a Shadowglen.", enHash = "1513d3e2", vanilla = true },
        reward = { it = "Ah, $N. Speravo che rispondessi in fretta alla mia convocazione. Ho un compito importante che vorrei affidarti.", enHash = "b4b5589a", vanilla = true },
    },
    [921] = {
        title = { it = "La corona della terra", enHash = "10f87d9b", vanilla = true },
        text = { it = "È tempo che tu parta alla ricerca del tuo destino, $N. Ma prima di essere $Gpronto:pronta; ad avventurarti nel mondo oltre le nostre foreste incantate, devi imparare molto sulla nostra storia recente.\n\nMolto è cambiato per il nostro popolo dalla battaglia del Mount Hyjal. Nordrassil non è che una pallida ombra di ciò che era un tempo, dopo che il suo potere è stato usato per sconfiggere Archimonde e ricacciare la Legione Infuocata...\n\nC'è un compito che devi svolgere. Vai al pozzo lunare a nord di Aldrassil e riportami una fiala della sua acqua.", enHash = "4400b23c", vanilla = true },
        objectives = { it = "Riempi la Crystal Phial e riportala a Tenaron Stormgrip, in cima ad Aldrassil.", enHash = "380f9ce7", vanilla = true },
        progress = { it = "I pozzi lunari custodiscono le acque del Well of Eternity, l'antica fonte di magia che ha portato tanti orrori nel nostro mondo.\n\nI druidi ne sfruttano le proprietà, e le Sentinelle venerano i pozzi come santuari di Elune, ma la stregoneria è proibita a tutti.", enHash = "a2749fd2", vanilla = true },
        reward = { it = "Dunque hai ascoltato la prima parte di ciò che seguì alla battaglia del Mount Hyjal. C'è molto altro da raccontare, e il compito che hai cominciato qui proseguirà per il resto del tuo viaggio attraverso Teldrassil e fino a Darnassus.", enHash = "024248d3", vanilla = true },
    },
    [922] = {
        title = { it = "Rellian Greenspyre", enHash = "498ead89" },
        text = { it = "$N, puoi portare al mio amico Rellian Greenspyre uno dei semi che mi hai procurato? È un druido a Darnassus, e l'ultima volta che ci siamo parlati mi ha rivelato il suo interesse per il mio lavoro con i Timberling. Aveva delle idee sue, e apprezzerà un seme da studiare.\n\nGrazie, $N. Mi sei $Gstato:stata; di grande aiuto. Spero che un giorno vedrai il frutto delle mie fatiche.\n\nRellian di solito lo trovi a passeggiare per i sentieri del Cenarian Enclave, a Darnassus.", enHash = "ea313dd8" },
        objectives = { it = "Porta un Timberling Seed a Rellian Greenspyre, a Darnassus.", enHash = "0427a948" },
        progress = { it = "Salve...\n\nE in cosa posso aiutarti?", enHash = "7ad81298", vanilla = true },
        reward = { it = "Ah, un Timberling Seed? Volevo provare a farne crescere uno per aiutare Denalan nei suoi studi.\n\nMa temo di aver scoperto che una corruzione è cresciuta in molti dei Timberling, e i semi di quelle creature portano la contaminazione del genitore. Sono oltre le mie capacità di guarigione.\n\nDenalan è molto abile con le cose che crescono. Forse troverà una cura per i Timberling futuri. Forse è la loro unica speranza.", enHash = "0540d369", vanilla = true },
    },
    [923] = {
        title = { it = "Tumori", enHash = "cc962164", vanilla = true },
        text = { it = "Nei Timberling sta crescendo una malevolenza. Stiamo cercando di trovarne la fonte, ma finché non ci riusciamo... per tenere Teldrassil al sicuro dobbiamo abbattere i Timberling per cui non c'è più nulla da fare. Quelli che vagano intorno al Wellspring Lake, a Teldrassil nord, sono i più contaminati. Vanno eliminati!\n\nDistruggi i Timberling che trovi là e raccogli i tumori muschiosi che crescono su di loro. Portami i tumori, così potranno essere bruciati.", enHash = "1a490075", vanilla = true },
        objectives = { it = "Porta 5 Mossy Tumor a Rellian Greenspyre, a Darnassus.", enHash = "b79aac17", vanilla = true },
        progress = { it = "Sei $Gstato:stata; al Wellspring Lake, $N? Hai dato la caccia ai Timberling là?", enHash = "bed60ca7", vanilla = true },
        reward = { it = "Ben fatto! Questi tumori sono il sintomo della malattia dei Timberling. Sono pieni di un veleno che dobbiamo togliere dalla nostra nuova terra.\n\nMi disferò io di questi tumori. Grazie, $N.", enHash = "84e11e45", vanilla = true },
    },
    [924] = {
        title = { it = "Il Demon Seed", enHash = "b7783195", vanilla = true },
        text = { it = "Il Demon Seed è uno strumento potente per la Legione Infuocata. Riposa in una grotta sul Dreadmist Peak, sopra un altare di fuoco demoniaco.\n\nHo preparato delle pietre di potere che, messe vicino al Seed, ne interromperanno il legame con la Legione.\n\nPrendi una pietra dal tavolo e portala all'altare di fuoco in cima al Dreadmist Peak. Va' a ovest, poi a nord quando la strada si divide. Il Peak sarà alla tua sinistra. La salita più sicura fino in cima è sul versante settentrionale.\n\nE sbrigati: il potere della pietra si consumerà col tempo.", enHash = "a246feb7", vanilla = true },
        objectives = { it = "Prendi una Flawed Power Stone. Portala all'Altar of Fire prima che la pietra si esaurisca, poi torna da Ak'Zeloth.", enHash = "54e73ea0", vanilla = true },
        progress = { it = "Il Demon Seed esiste ancora. Ne sento il potere...", enHash = "3853bba9", vanilla = true },
        reward = { it = "Il tuo compito è concluso. Hai distrutto il Demon Seed come Neeru aveva chiesto. Ma questa non è la fine...\n\nLa distruzione del Demon Seed ha mandato onde di potere attraverso l'etere, onde di forza sconvolgente. Io le ho sentite, e sono sicuro che le abbiano sentite anche altri esseri. Altri che si chiederanno perché il loro giocattolo si sia rotto...\n\nMa a prescindere dai guai futuri, ho qualcosa per te. Neeru l'ha mandato come pagamento. E mi ha chiesto di ringraziarti.\n\nQuindi, grazie.", enHash = "d0c249dd", vanilla = true },
    },
    [925] = {
        title = { it = "Cairne's Hoofprint", enHash = "c6faf759", vanilla = true },
        text = { it = "Dicono che Cairne Bloodhoof sia uno dei più grandi eroi che l'Orda abbia mai visto. Da grande voglio essere un eroe dell'Orda anch'io!\n\nConosci Cairne, $N? Mi faresti un favore, per piacere? Potresti procurarmi l'impronta del suo zoccolo? Non so come chiederglielo, e probabilmente sarebbe troppo occupato per uno come me... ma tu! Sei $Gun avventuriero:un'avventuriera; proprio come lui! Scommetto che a te l'impronta la darebbe subito!\n\nPer piacere?", enHash = "32b1af77", vanilla = true },
        objectives = { it = "Raggiungi Thunder Bluff e cerca di ottenere l'impronta dello zoccolo di Cairne Bloodhoof per il tuo protetto.", enHash = "bd70c81a", vanilla = true },
        progress = { it = "Quando gli orchi erano soli e senza amici, i tauren li accolsero in una terra sconosciuta e condivisero tutto con loro senza chiedere niente in cambio. Questo è onore, $N.", enHash = "06f797cf", vanilla = true },
        reward = { it = "WOW! Mi hai procurato l'impronta dello zoccolo di Cairne! Grazie mille! E wow... ci ha scritto sopra un messaggio personale, per me! Lo sapevo che sarebbe stato fantastico, lo sapevo! Magari un giorno lo ringrazierò di persona... quando diventerò un eroe dell'Orda!\n\nSei $Gil migliore:la migliore;, $N. Grazie di essere così gentile con me.", enHash = "d5849910", vanilla = true },
    },
    [926] = {
        title = { it = "Flawed Power Stone", enHash = "9829f605", vanilla = true },
        reward = { it = "Queste pietre sono intrise di energia magica, ma volutamente imperfette. Sono molto instabili e, una volta tolte dal tavolo, si consumeranno in fretta.", enHash = "8d7b1de6", vanilla = true },
    },
    [927] = {
        title = { it = "Il Moss-twined Heart", enHash = "e9ef52e9", vanilla = true },
        text = { it = "Il cuore di Blackmoss the Fetid è ricoperto da un muschio scuro e oleoso. Anzi, l'unico modo per capire che è un cuore è il suo battito lento e ritmico... Un battito che continua ancora adesso.\n\nForse Denalan vorrà vedere questo cuore.", enHash = "afcb74f3", vanilla = true },
        objectives = { it = "Porta il Moss-twined Heart a Denalan, al Lake Al'Ameth.", enHash = "36347ffe", vanilla = true },
        progress = { it = "$N! Hai qualcosa per me?", enHash = "7ef238aa", vanilla = true },
        reward = { it = "...Cos'è questo? Un cuore di Timberling?? È ricoperto da un muschio immondo!\n\nGrazie di avermelo portato, $N. Esaminerò il cuore e, se la fortuna mi assiste, capirò la natura del muschio che lo avvolge.", enHash = "3bc4c89c", vanilla = true },
    },
    [928] = {
        title = { it = "La corona della terra", enHash = "10f87d9b", vanilla = true },
        text = { it = "Anche se potrei parlarti ancora dei pozzi lunari e di Teldrassil, devo mandarti avanti. Corithras Moonrage ti aspetta. Ho versato in questo recipiente la fiala d'acqua che mi hai portato, perché tu la consegni a lui.\n\nCerca Corithras. Lo troverai presso il pozzo lunare di Dolanaar. Segui la strada verso sud da Aldrassil fino a uscire da Shadowglen, e continua a seguire l'acciottolato quando la strada piega a ovest.\n\nBada però a restare sulla strada, $N. Di recente nelle foreste si aggirano bestie pericolose.", enHash = "63b9aeb9", vanilla = true },
        objectives = { it = "Porta il Partially Filled Vessel a Corithras Moonrage, a Dolanaar.", enHash = "4304d364", vanilla = true },
        progress = { it = "Salute, $C. A cosa devo il piacere di questo incontro?", enHash = "cbf95ba4", vanilla = true },
        reward = { it = "Ah, capisco. Ti manda Tenaron. Be', allora a quanto pare abbiamo molto di cui parlare, molto da fare e poco tempo per farlo.\n\nCredo sia meglio cominciare.", enHash = "dca01565", vanilla = true },
    },
    [929] = {
        title = { it = "La corona della terra", enHash = "10f87d9b", vanilla = true },
        text = { it = "Per prima cosa, lascia che ti dica di più sul compito che devi portare a termine. I druidi di Darnassus usano l'acqua dei pozzi lunari di Teldrassil, e il loro pozzo lunare va rifornito di tanto in tanto. Con queste fiale lavorate apposta puoi raccogliere l'acqua dei pozzi lunari.\n\nPorta questo recipiente al pozzo lunare fuori da Starbreeze Village, a est, riempilo con un po' delle sue acque e poi torna da me. Quando avrai portato a termine il compito, riprenderò il racconto dove l'ha lasciato Tenaron...", enHash = "cdfe21e0", vanilla = true },
        objectives = { it = "Riempi la Jade Phial e riportala a Corithras Moonrage, a Dolanaar.", enHash = "8bd74a04", vanilla = true },
        progress = { it = "Salve di nuovo, $N. Hai portato a termine il tuo compito?", enHash = "b56c91f9", vanilla = true },
        reward = { it = "Dopo la battaglia del Mount Hyjal restammo senza una direzione. Nordrassil fumava per il fuoco che aveva scatenato, e la nostra immortalità — l'essenza stessa del nostro essere! — era perduta.\n\nFu in quel tempo difficile che il Traditore venne liberato dalla sua prigione, e Shan'do Stormrage scomparve. Un tempo oscuro per tutti.", enHash = "98d82208", vanilla = true },
    },
    [930] = {
        title = { it = "Il frutto luminoso", enHash = "2a5e01fa", vanilla = true },
        text = { it = "Da sotto le fronde di questa pianta luminosa pende un frutto grande e tondo.\n\nDenalan vorrebbe studiare questo frutto, ne sei $Gcerto:certa;.", enHash = "97dd8053", vanilla = true },
        objectives = { it = "Porta il frutto luminoso a Denalan, al Lake Al'Ameth.", enHash = "1f4c6d8d", vanilla = true },
        progress = { it = "$N, hai l'aria di avere qualcosa da dirmi. Hai notizie sui Timberling?", enHash = "dfd62bd1", vanilla = true },
        reward = { it = "Hai trovato questo a Teldrassil? Curioso... questo frutto è esotico. Forse i suoi semi sono stati portati qui da lontano. Forse perfino da Azeroth! E c'è qualcosa in questo frutto... sembra aver reagito in modo molto strano con il terreno di Teldrassil.\n\nGrazie, $N. Ora, se vuoi scusarmi, devo studiarlo meglio...", enHash = "17d4a987", vanilla = true },
    },
    [931] = {
        title = { it = "La Shimmering Frond", enHash = "f2370449", vanilla = true },
        text = { it = "Le fronde di questa pianta scintillano nella luce della foresta, dandole un'aura che si torce e pulsa.\n\nCredi che Denalan vorrebbe un esemplare di questa pianta.", enHash = "c360dbf7", vanilla = true },
        objectives = { it = "Porta una Shimmering Frond a Denalan, al Lake Al'Ameth.", enHash = "af44b8fc", vanilla = true },
        progress = { it = "Hai qualcosa per me?", enHash = "ac74d893", vanilla = true },
        reward = { it = "Dove l'hai presa? Non vedevo una pianta così da quando feci un soggiorno nello Swamp of Sorrows... decenni fa! È straordinario che un esemplare sia arrivato fino a Teldrassil. Ed è cresciuto fino a queste dimensioni!\n\nGrazie, $N. Perdona la mia brevità, ma c'è una prova che vorrei fare su questa fronda...", enHash = "9caef2ed", vanilla = true },
    },
    [932] = {
        title = { it = "Odio contorto", enHash = "5a09db70" },
        text = { it = "Devo avvertirti, $N: questa faccenda deve restare tra noi. I satiri sono già abbastanza un'onta per noi, e questo è fin troppo vicino a casa.\n\nSi chiama Lord Melenas. Risiede qui vicino, nella grotta di Fel Rock, dove ha radunato un grosso gruppo di guerrieri Grell. Ha il cuore nero come la notte, e trama qualcosa di immondo.\n\nDevi trovarlo nella sua grotta qui vicino, appena a nord di qui, e portarmi la sua testa.", enHash = "ecbd028c" },
        objectives = { it = "Uccidi Lord Melenas e porta la sua testa a Tallonkai Swiftroot, a Dolanaar.", enHash = "3edfd8f7" },
        progress = { it = "Hai già ucciso Lord Melenas? È fondamentale che venga eliminato in fretta e in silenzio, $N. Il fatto che continui a esistere è un'onta per tutti noi.", enHash = "6c7f063c", vanilla = true },
        reward = { it = "Ora che Lord Melenas riposa, posso finalmente passare ad altre faccende. Grazie, $N.", enHash = "1ffadc21", vanilla = true },
    },
    [933] = {
        title = { it = "La corona della terra", enHash = "10f87d9b" },
        text = { it = "C'è un altro pozzo lunare a sud-est dell'ingresso di Darnassus, sulle rive delle Pools of Arlithrien. Le Sentinelle hanno difficoltà a pattugliare la zona per via degli attacchi e dell'umore sempre più cattivo dei furbolg Gnarlpine.\n\nSii prudente mentre cerchi il pozzo, e tieni le armi a portata di mano.", enHash = "4ffb85f6" },
        objectives = { it = "Riempi la Tourmaline Phial e riportala a Corithras Moonrage, a Dolanaar.", enHash = "c3814e1c" },
        progress = { it = "All'inizio le segnalazioni di attacchi di furbolg impazziti furono ignorate. Chi avrebbe mai pensato che gli uomini-orso amanti della pace si sarebbero abbandonati a una rabbia cieca? Un altro dei problemi che ci affliggono qui, nella nostra nuova casa.", enHash = "9666b5c5", vanilla = true },
        reward = { it = "Shan'do Stormrage non tornò mai, i druidi erano allo sbando, e ancora oggi non sappiamo che fine abbia fatto. Con Malfurion scomparso, Arch Druid Fandral Staghelm prese la guida dei druidi, convincendo il Circle of Ancients a Darkshore che era tempo per il nostro popolo di ricostruire, e tempo di riconquistare l'immortalità.\n\nCon l'approvazione del Circle, Staghelm e i druidi più potenti fecero crescere Teldrassil, il nuovo Albero del Mondo.", enHash = "c0f3ce3f", vanilla = true },
    },
    [934] = {
        title = { it = "La corona della terra", enHash = "10f87d9b", vanilla = true },
        text = { it = "Non tutto andava bene a Teldrassil, però. I piani che Staghelm aveva preparato con cura per il nuovo Albero del Mondo avevano dato i frutti sperati, ma c'era un piccolo problema, un problema a cui si possono attribuire molti dei guai di Teldrassil.\n\nNon entrerò però ancora in quell'argomento. Devi visitare l'ultimo pozzo lunare, a nord-ovest, nell'Oracle Glade. Sotto i rami dell'Oracle Tree si trova il primo e più potente dei nostri pozzi. Riportami una fiala della sua acqua.", enHash = "4d24c65a", vanilla = true },
        objectives = { it = "Riempi l'Amethyst Phial e riportala a Corithras Moonrage, a Dolanaar.", enHash = "5b27c34f", vanilla = true },
        progress = { it = "Insieme ai druidi, l'Oracle Tree e l'arcidruido hanno osservato con attenzione la crescita di Teldrassil. Ma, per quanto abbiamo una nuova casa, le nostre vite immortali non sono state restituite.", enHash = "b069de5d", vanilla = true },
        reward = { it = "Essere alla presenza dell'Oracle Tree... è quasi come sentire la saggezza prendere forma. Lascia che continui il racconto...\n\nCresciuto Teldrassil, l'arcidruido si rivolse ai draghi per le loro benedizioni, come i draghi avevano fatto con Nordrassil nei tempi antichi. Ma Nozdormu, Signore del Tempo, rifiutò di dare la sua benedizione, rimproverando il druido per la sua arroganza. D'accordo con Nozdormu, anche Alexstrasza rifiutò Staghelm e, senza la sua benedizione, la crescita di Teldrassil è stata imperfetta e imprevedibile...", enHash = "39723cb5", vanilla = true },
    },
    [935] = {
        title = { it = "La corona della terra", enHash = "10f87d9b", vanilla = true },
        text = { it = "Senza le benedizioni di Alexstrasza the Life-Binder e di Nozdormu the Timeless, la crescita di Teldrassil non è stata priva di difetti. Si segnalano strane bestie che sorgono dal terreno stesso dell'albero, e furbolg impazziti che attaccano i viaggiatori di passaggio.\n\nPosso solo sperare che la soluzione cercata dall'arcidruido si trovi presto. Verserò in questo recipiente tutte le fiale che hai portato, perché tu le consegni a Darnassus.\n\nPortalo a Fandral Staghelm: lo troverai nel boschetto dei druidi.", enHash = "16a3f7c7", vanilla = true },
        objectives = { it = "Porta il Filled Vessel ad Arch Druid Fandral Staghelm, a Darnassus.", enHash = "7ed6ff8f", vanilla = true },
        progress = { it = "So di non averti convocato, quindi non posso fare a meno di chiedermi perché tu sia $Gvenuto:venuta; a parlare con me.\n\nQualunque cosa sia, ti prego, fa' in fretta.", enHash = "742a28d1", vanilla = true },
        reward = { it = "Ah sì, l'acqua che avevo richiesto. Tenaron e Corithras se la sono presa comoda a farmela recapitare... forse non scegliendo il più affidabile dei messaggeri... mmh.\n\nComunque sia, finalmente posso tornare al mio lavoro. Il peso dei problemi di Teldrassil ricade sulle mie spalle. Un giogo di cui vorrei presto liberarmi.\n\nPrendi questo, forse ti sarà utile.", enHash = "3c038233", vanilla = true },
    },
    [937] = {
        title = { it = "Il boschetto incantato", enHash = "62e45086", vanilla = true },
        text = { it = "Sono stata mandata qui con un piccolo gruppo di Sentinelle per proteggere l'Oracle Tree dalle arpie che hanno fatto il nido tutt'intorno al boschetto. A poco a poco cerchiamo di respingerle.\n\nQuando l'Oracle Tree ha provato a mandare un corriere a Darnassus con un rapporto, il messaggero è stato attaccato e ucciso da un gruppo di arpie.\n\nSe te la senti, va' ai loro nidi, uccidile e portami le loro cinture come prova di ciò che hai fatto.", enHash = "dc602ee7", vanilla = true },
        objectives = { it = "Procurati 6 Bloodfeather Belt e portale a Sentinel Arynia Cloudsbreak, nell'Oracle Glade.", enHash = "546b9b41", vanilla = true },
        progress = { it = "I loro artigli affilati e i becchi acuminati potrebbero essere un avversario difficile per le tue capacità, $N, ma confido che non fallirai in questo compito.", enHash = "b8d43206", vanilla = true },
        reward = { it = "Sono colpita da ciò che hai fatto qui in così poco tempo, $N. Vorrei poterti chiedere di restare ad aiutarmi nei miei doveri... ma in cuor mio so che ti attendono compiti più grandi.\n\nHo notato che l'Oracle Tree ha appena lasciato cadere un pezzo della sua corteccia. Senza dubbio ha un compito che vuole veder svolto. Dovresti parlargli.", enHash = "595c0b86", vanilla = true },
    },
    [938] = {
        title = { it = "Mist", enHash = "003324fd", vanilla = true },
        text = { it = "Il pelo della sabercat è di un grigio caratteristico, che si confonde con la foresta intorno. Mentre giace là, noti che è gravemente ferita, con profonde lacerazioni sulla schiena e sul ventre.\n\nAlza la testa e ti guarda, con un'intelligenza viva che brilla negli occhi azzurri. Sembra voler venire con te.", enHash = "4aee8a13", vanilla = true },
        objectives = { it = "Scorta Mist fino a Sentinel Arynia Cloudsbreak, al pozzo lunare vicino all'Oracle Tree.", enHash = "7960e311", vanilla = true },
        progress = { it = "Mist... È stata colpa mia! Le streghe mi hanno colta alla sprovvista... Non avrei dovuto lasciare che ti portassero via...", enHash = "ef4836dc", vanilla = true },
        reward = { it = "Oh, grazie, $N! Temevo che non avrei più rivisto Mist, portandomi in cuore solo la sua morte, senza mai riunirmi alla mia fedele compagna. Ti devo più di quanto tu possa immaginare, e te ne sarò grata per sempre.", enHash = "187b8c39", vanilla = true },
    },
    [940] = {
        title = { it = "Teldrassil", enHash = "754a831b", vanilla = true },
        text = { it = "La foresta sussurra delle tue imprese di valore, $N. Quando ho sentito che le arpie venivano cacciate dai loro nidi, una calma più grande si è diffusa nella foresta, e le sue creature si sono sentite di nuovo al sicuro. Ho temuto di mandare un altro messaggero all'arcidruido, ma so che tu porterai il mio messaggio fino a lui.\n\nConsegnaglielo, e sappi che la foresta ti accompagnerà sicura lungo i suoi sentieri fino alla foresta di pietra.", enHash = "4d8e606a", vanilla = true },
        objectives = { it = "Consegna il rapporto dell'Oracle Tree ad Arch Druid Fandral Staghelm, a Darnassus.", enHash = "c335c02a", vanilla = true },
        progress = { it = "Mmh... Vieni con lo spirito della foresta forte dentro di te, $C. Che affari hai con l'arcidruido dei Kaldorei?", enHash = "a49b8ef3", vanilla = true },
        reward = { it = "Mi chiedevo perché l'Oracle Tree non comunicasse con me da tanto tempo... Sembra che alcuni problemi si attenuino mentre altri diventano preoccupazioni più grandi.\n\nTemo che il mio lavoro su Teldrassil non sarà mai compiuto, e la nostra immortalità mai restituita.\n\nCiò nonostante, hai svolto bene il compito dell'Oracle Tree, e meriti una ricompensa per la tua diligenza.", enHash = "4e9a06f7", vanilla = true },
    },
    [941] = {
        title = { it = "Piantare il cuore", enHash = "85a3608e", vanilla = true },
        text = { it = "Ho tolto quel muschio immondo dal cuore, ma resta contaminato...\n\nProva a mettere il cuore nella mia fioriera. È piena di un terreno nutriente che potrebbe purificare e guarire il cuore.", enHash = "821b9030", vanilla = true },
        objectives = { it = "Pianta il Tainted Heart nella Denalan's Planter.", enHash = "6acec383", vanilla = true },
        progress = { it = "Questa fioriera è piena di terra, preparata apposta da Denalan.", enHash = "01fa4e84", vanilla = true },
        reward = { it = "Metti il cuore nella fioriera, e quello in un attimo si interra da solo!\n\nQualche secondo dopo si divincola e riemerge, purificato. Pulsa leggermente... invitandoti a prenderlo.", enHash = "72c43b76", vanilla = true },
    },
    [942] = {
        title = { it = "Il cercatore distratto", enHash = "22acfb26", vanilla = true },
        text = { it = "Questo fossile somiglia moltissimo a uno che vidi tempo fa a Ironforge. Un archeologo di nome Flagongut lo portò al nostro convegno annuale della Lega degli Esploratori. Era convinto che il fossile avesse un potere che in qualche modo si poteva risvegliare.\n\nL'ultima volta che ne ho saputo, Flagongut si era rintanato alla Deepwater Tavern, a Menethil Harbor, in attesa di una scorta per il Whelgar Excavation Site. Cercalo e mostragli il fossile di Remtravel. Forse potrà svelare i segreti del passato.\n\nLa nave per Menethil parte da Auberdine.", enHash = "58bcb1e4", vanilla = true },
        objectives = { it = "Porta il fossile misterioso ad Archaeologist Flagongut, a Menethil Harbor.", enHash = "b13a966e", vanilla = true },
        progress = { it = "Che cos'hai lì, $Gamico:amica;?", enHash = "b4fbd159", vanilla = true },
        reward = { it = "Perbacco! Dici che viene dalle terre lontane di Kalimdor?\n\nIncredibile! Semplicemente incredibile!", enHash = "4118db77", vanilla = true },
    },
    [943] = {
        title = { it = "Il cercatore distratto", enHash = "22acfb26", vanilla = true },
        text = { it = "Prospector Whelgar ha ora il fossile originale nel suo sito, nelle Wetlands. Quando scoprii la Stone of Relu, credevo fosse la chiave per svelare il mistero del fossile.\n\nMentre viaggiavo sulla strada per incontrare Whelgar, fui attaccato dai raptor e la reliquia andò persa. Non so quale di quelle bestie chiazzate si sia inghiottita la reliquia, ma se riesci a recuperarla posso scatenare il potere di questi artefatti.\n\nPortami sia la Stone of Relu sia il fossile originale che ha lui.", enHash = "6668051e", vanilla = true },
        objectives = { it = "Archaeologist Flagongut, a Menethil Harbor, vuole che tu gli porti la Stone of Relu e Flagongut's Fossil.", enHash = "590e37dd", vanilla = true },
        progress = { it = "Con la Stone of Relu riuscirò a liberare i segreti nascosti del mio fossile e anche del fossile di Remtravel, quello di Darkshore, $N.", enHash = "e664c5e3", vanilla = true },
        reward = { it = "Ottimo, $N!\n\nOra vediamo se riesco a usare la pietra per decifrare i poteri dei fossili.", enHash = "00ddb83a", vanilla = true },
    },
    [944] = {
        title = { it = "Il Master's Glaive", enHash = "a4b61adf", vanilla = true },
        text = { it = "È strano che i naga siano qui, a Darkshore. Ma più strano ancora... è il Martello del Crepuscolo. Quel culto venera i signori antichi, antichissimi, della terra. Signori sconfitti tanto tempo fa.\n\nIl Master's Glaive, a sud, è un luogo dove uno di quei signori antichi cadde.\n\nVa' là e cerca altri cultisti del Martello del Crepuscolo.\n\nPrendi questa Phial of Scrying. Usala per creare una Scrying Bowl dopo aver perlustrato il Master's Glaive. Poi parlami attraverso la coppa.", enHash = "b9f85328", vanilla = true },
        objectives = { it = "Raccogli informazioni, poi usa la Phial of Scrying per creare una Scrying Bowl. Usa la coppa per parlare con Onu.", enHash = "f43fba26", vanilla = true },
        progress = { it = "Il Master's Glaive, $N.\n\nVa' là, poi parlami di nuovo.", enHash = "e0ca4c3c", vanilla = true },
        reward = { it = "Il Martello del Crepuscolo è al Master's Glaive?\n\nSpiacevole.\n\nIl signore antico trafitto da quella lama è morto da tempo, ma questo non vuol dire che non restino ancora schegge del suo potere.\n\nIl Martello del Crepuscolo deve essere in cerca di quel potere.", enHash = "a563cba7", vanilla = true },
    },
    [945] = {
        title = { it = "La fuga di Therylune", enHash = "aa20897d", vanilla = true },
        text = { it = "Aiuto!\n\nStavo girando dalle parti del Master's Glaive e questi sudici cultisti mi hanno circondata. Per fortuna sono brava a nascondermi!!\n\nMi aiuti a uscire di qui? E devo mandare un messaggio a mia sorella Therysil per dirle che sto bene. È in Ashenvale, a sud, allo Shrine of Aessina.", enHash = "db2e6ac3", vanilla = true },
        objectives = { it = "Aiuta Therylune a fuggire, poi di' a Therysil, allo Shrine of Aessina, che sua sorella è salva.", enHash = "d9cdd0d9", vanilla = true },
        reward = { it = "Mia sorella era dove?? Therylune non ha paura di sporcarsi, ma insomma! È un bel pezzo di strada, e il Master's Glaive è un posto malsano...\n\nBe', grazie, $N. Sei $Gstato:stata; molto gentile a farmelo sapere.", enHash = "c2a02784", vanilla = true },
    },
    [947] = {
        title = { it = "Funghi di caverna", enHash = "a2215248", vanilla = true },
        text = { it = "Sto mettendo a punto una pozione che richiede funghi rari, funghi che crescono solo in una certa caverna. La caverna si trova dietro le Cliffspring Falls, a est e leggermente a nord, lungo le montagne.\n\nCi andrei di persona, ma il Grove of the Ancients mi ha consigliato di stare alla larga da quel posto. I nostri venerabili alleati percepiscono che la caverna è il nascondiglio di un nuovo male a Darkshore.\n\nTi prego, $N, raccogli i funghi per me. E già che ci sei, esplora la caverna per confermare i timori degli Antichi.", enHash = "c7ba82f4", vanilla = true },
        objectives = { it = "Porta 5 Scaber Stalk e 1 Death Cap a Barithras Moonshade, ad Auberdine.", enHash = "bac8bfe8", vanilla = true },
        progress = { it = "Hai i miei funghi, $N? Sei $Gstato:stata; alla caverna?", enHash = "7bb7da11", vanilla = true },
        reward = { it = "Mille grazie, $N. Questi funghi sono esemplari magnifici!\n\nE quando eri alle Cliffspring Falls, hai trovato qualcosa che confermi gli avvertimenti degli Antichi?\n\nGli Antichi sono saggi, ma avevo sperato che questa volta si sbagliassero.", enHash = "4384a202", vanilla = true },
    },
    [948] = {
        title = { it = "Onu", enHash = "0001ae76", vanilla = true },
        text = { it = "Onu, un Ancient of Lore del Grove of the Ancients, sa del tuo viaggio alle Cliffwater Falls e desidera parlarti. Il boschetto si trova a sud, annidato vicino alle montagne.\n\nGli Antichi sono pazienti e saggi, $N. Ma se Onu chiede il tuo parere su ciò che hai visto alle cascate, allora temo sia urgente.", enHash = "4731afd7", vanilla = true },
        objectives = { it = "Parla con Onu, al Grove of the Ancients.", enHash = "d1ae9cee", vanilla = true },
        reward = { it = "$N. Sei qui.\n\nBene.\n\nAbbiamo delle cose... di cui parlare. Io e te.", enHash = "57cec95c", vanilla = true },
    },
    [949] = {
        title = { it = "L'accampamento del Martello del Crepuscolo", enHash = "8856f0a2", vanilla = true },
        text = { it = "Lo scopo del Martello del Crepuscolo al Master's Glaive non si conosce. Ma dev'essere oscuro.\n\nFruga nel loro accampamento al Glaive... Cerca qualcosa che ci insegni le loro intenzioni.\n\nPerché dobbiamo conoscere le loro intenzioni prima di fare un piano.", enHash = "a21c3593", vanilla = true },
        objectives = { it = "Trova un indizio nell'accampamento del Martello del Crepuscolo, al Master's Glaive.", enHash = "07488d7c", vanilla = true },
        reward = { it = "Questo libro è scritto a mano in una lingua antica, e illustrato da un maestro.", enHash = "a0660f6f", vanilla = true },
    },
    [950] = {
        title = { it = "Torna da Onu", enHash = "6ec18841", vanilla = true },
        text = { it = "Scrutare dentro il Twilight Tome fa impazzire. Il testo comincia a nuotare e a ballare dopo un solo istante di sguardo, e i fregi un tempo belli si contorcono in forme grottesche.\n\nStrappare una pagina di scarabocchi folli è tutto quello che riesci a fare, prima che ti prenda un capogiro.", enHash = "1d56d7a7", vanilla = true },
        objectives = { it = "Porta a Onu gli Insane Scribbles recuperati.", enHash = "7cfb854d", vanilla = true },
        progress = { it = "$N. Sei $Gtornato:tornata;.", enHash = "fe10dbd9", vanilla = true },
        reward = { it = "Una magia caotica e primordiale avvolge questa pergamena di scarabocchi. Ci sento dentro l'opera degli antichi.\n\nSperiamo che riveli lo scopo del Martello del Crepuscolo a Darkshore...", enHash = "c464683f", vanilla = true },
    },
    [951] = {
        title = { it = "Mathystra Relics", enHash = "53d0b61f", vanilla = true },
        text = { it = "La pergamena che hai trovato al Master's Glaive è una pagina di un testo antico... scritto dagli elfi! È pesantemente maledetta e corrotta dal Martello del Crepuscolo, ma sembra che il culto stia usando l'antica magia elfica per riportare nel nostro mondo i suoi antichi padroni.\n\nVa' alle rovine di Mathystra, a nord-est, e cerca reliquie antiche fra l'erba e le pietre spezzate. Studiandole, potremo forse capire come il Martello del Crepuscolo intenda sfruttare la magia degli elfi.", enHash = "af08e12d", vanilla = true },
        objectives = { it = "Porta 6 Mathystra Relic a Onu, al Grove of the Ancients.", enHash = "398bd5be", vanilla = true },
        progress = { it = "$N. Il tuo frugare fra le Ruins of Mathystra ha dato frutto?", enHash = "8c5e2fe8", vanilla = true },
        reward = { it = "Grazie. Queste reliquie vengono da un tempo in cui Mathystra splendeva. Quel bastione un tempo grande degli elfi si è spento, ma schegge della sua magia restano. Speriamo di riuscire a svelare i segreti di quel luogo prima dei nostri nemici...\n\nSta' $Gattento:attenta;, $N.", enHash = "f12ec5d6", vanilla = true },
    },
    [952] = {
        title = { it = "Il Grove of the Ancients", enHash = "72f2e7a6", vanilla = true },
        text = { it = "Se hai avuto tempo a sufficienza per portare messaggi all'Oracle Tree, allora sono sicuro di poterti arruolare per consegnare un messaggio al Grove of the Ancients, a Darkshore, subito a sud di Auberdine.\n\nMolto probabilmente dovrai procurarti un passaggio su un ippogrifo, ma ho abbastanza fiducia in te per credere che ce la farai. Porta questo a Onu, l'Ancient of Lore. Aspetta mie notizie, così come io aspettavo notizie dall'Oracle Glade.", enHash = "7b4af570", vanilla = true },
        objectives = { it = "Consegna il messaggio di Fandral a Onu, nel Grove of the Ancients, a Darkshore, a sud di Auberdine.", enHash = "92edc3ac", vanilla = true },
        progress = { it = "Ah. $C. In cosa può aiutarti Onu?", enHash = "4b956698", vanilla = true },
        reward = { it = "Ah. Grazie, $N. È strano, però. L'arcidruido sembra sempre avere tanta fretta. La foresta sa che ogni cosa accadrà al momento stabilito. Shan'do Stormrage lo capiva.", enHash = "3c49b69a", vanilla = true },
    },
    [953] = {
        title = { it = "La caduta di Ameth'Aran", enHash = "cc4d110b", vanilla = true },
        text = { it = "A est troverai le rovine di Ameth'Aran. Ora sono abitate dagli spiriti inquieti degli Alti Nobili che un tempo vivevano fra quelle mura, ma in passato Ameth'Aran era un luogo dove i servitori di Azshara praticavano liberamente le loro magie potenti.\n\nMi hanno mandata a esplorare le rovine e ho trovato due grandi tavole, coperte di segni che raccontano la storia di Ameth'Aran e della sua caduta. Mentre leggevo le rune, gli spiriti mi hanno assalita e sono fuggita.\n\nTi prego, se puoi, spingiti fino alle rovine e decifra le tavole al posto mio.", enHash = "81281a98", vanilla = true },
        objectives = { it = "Studia le tavole che raccontano di Ameth'Aran e della sua caduta, poi torna da Sentinel Tysha Moonblade, a Darkshore.", enHash = "a545eed7", vanilla = true },
        progress = { it = "Quando avrai studiato le tavole e saprai della caduta di Ameth'Aran, porterò quella conoscenza ad Auberdine e informerò il Circle of Ancients.", enHash = "425021ae", vanilla = true },
        reward = { it = "Abbiamo pochi documenti del periodo intorno alla Guerra degli Antichi, soprattutto vicino alla distruzione del Well of Eternity. Visti gli sconvolgimenti e gli eventi catastrofici di quei giorni, non c'è da stupirsi.\n\nGrazie, $N. Con il tuo aiuto il mio lavoro qui è finito, e potrò consegnare un rapporto completo al Circle.", enHash = "de50de08", vanilla = true },
    },
    [954] = {
        title = { it = "Bashal'Aran", enHash = "23739e26", vanilla = true },
        text = { it = "Le rovine di Bashal'Aran, a est, sono invase da servitori demoniaci. I folletti e i satiri che si sono insediati nella zona si nutrono delle energie magiche del luogo, e i loro poteri crescono con l'esposizione continua.\n\nEppure ho notato che c'è un santuario a cui non si avvicinano. Sul lato occidentale delle rovine, in cima a un piccolo poggio, aleggia una strana aura azzurra... Ci dev'essere una spiegazione alla riluttanza dei demoni.\n\nVorrei che indagassi.", enHash = "bbab52b2", vanilla = true },
        objectives = { it = "Trova l'origine della strana aura azzurra fra le rovine di Bashal'Aran.", enHash = "724442f6", vanilla = true },
        reward = { it = "Ahh... A cosa devo mai l'onore così particolare della compagnia di $Gun:una; $R come te? La dice lunga sui miei compagni attuali — senza offesa per i miei ospiti, i nobili Grell e satiri — che la tua presenza possa essere considerata un miglioramento.\n\nMa ti prego, non lasciare che la mia lingua scortese ti scacci da qui. Sono passati molti anni, decenni persino, da quando ho avuto una compagnia civile.", enHash = "ce219548", vanilla = true },
    },
    [955] = {
        title = { it = "Bashal'Aran", enHash = "23739e26", vanilla = true },
        text = { it = "Se dovessi raccontarti la storia della mia vita, non ho dubbi che supererebbe i limiti della tua pazienza. Diciamo che la mia è stata una vita lunga e dolorosa, e questa forma spettrale è forse il peggiore dei tormenti.\n\nSono trattenuto qui dalla magia. Per quanto le mie parole possano sembrare false, ti assicuro che ti sarei grato oltre ogni dire se mi aiutassi a trovare ciò che mi imprigiona. Un sigillo mi vincola e, esaminando gli orecchini dei folletti e dei Grell, potrei trovarne una traccia.", enHash = "ac46d022", vanilla = true },
        objectives = { it = "Procura 8 Grell Earring ad Asterion, a Bashal'Aran.", enHash = "d4d9ed4e", vanilla = true },
        progress = { it = "Una volta avuti gli orecchini, lancerò l'incantesimo per cercare dove si trova il sigillo che mi vincola. Per secoli ho pensato alla libertà che distruggerlo mi porterebbe... Forse quei secoli hanno fatto alla mia mente un danno da cui non mi riprenderò mai...", enHash = "d3abf984", vanilla = true },
        reward = { it = "Già... I Grell di Bashal'Aran non hanno ciò che cerco... ma ci sono venuti a contatto di recente. Di recente... a misura del tuo tempo, non del mio. Per me il recente si allunga nel velo del passato, quasi un'altra Era...", enHash = "bb4f097a", vanilla = true },
    },
    [956] = {
        title = { it = "Bashal'Aran", enHash = "23739e26", vanilla = true },
        text = { it = "Se i Grell sono venuti a contatto ravvicinato con il sigillo che vincola la mia prigione eterna, credo di sapere il perché. Senza dubbio il sigillo è finito in mano ai satiri che li guidano.\n\nSono certo che sia così, $N. Uno dei satiri deve averlo di sicuro. Se riuscissi a procurarmelo, mi porteresti così vicino a varcare le sbarre della mia prigione che mi verrebbero le lacrime agli occhi.", enHash = "c4e7f1ca", vanilla = true },
        objectives = { it = "Procurati l'Ancient Moonstone Seal e portalo ad Asterion, a Bashal'Aran.", enHash = "a8c382d8", vanilla = true },
        progress = { it = "I pilastri di questo santuario sono per me come le sbarre di una prigione, $N. Nessuna forza che ancora possiedo può spezzarli, nessuna magia che padroneggio può distruggerli...\n\nPer mille anni e più li ho fissati, chiedendomi: se alla fine sopravvivessi persino alla pietra, sarei libero? O sarebbero sbarre invisibili a trattenermi, allora...", enHash = "f443d105", vanilla = true },
        reward = { it = "È... è difficile per me persino credere che ciò che ora tengo in mano sia ciò che ha tenuto me per tanto tempo. Non perdiamo tempo, $N. Quando il sigillo sarà distrutto, potrò tornare a camminare libero per le foreste della terra.", enHash = "0da4a731", vanilla = true },
    },
    [957] = {
        title = { it = "Bashal'Aran", enHash = "23739e26", vanilla = true },
        text = { it = "Fu l'arte di uno dei più potenti fra gli Alti Nobili a creare il sigillo che ha formato la mia prigione. Ad Ameth'Aran, le rovine a sud gemelle di queste, persiste ancora oggi una fiamma antica, di colore azzurro. In quella fiamma questo sigillo si può distruggere.\n\nVa' $Gcauto:cauta; fra quelle rovine, $N...", enHash = "9a65e407", vanilla = true },
        objectives = { it = "Distruggi l'Ancient Moonstone Seal nella fiamma antica di Ameth'Aran, poi torna da Asterion, a Bashal'Aran.", enHash = "74f11b34", vanilla = true },
        progress = { it = "A dire il vero, $N, ho paura... Paura che il tuo arrivo — tutto questo — sia solo il parto di una mente sconvolta. Puoi capire che tortura sia? Io... Ti prego, va' in fretta.", enHash = "3bbec9b4", vanilla = true },
        reward = { it = "Sono libero, $N! Ora posso vedere con i miei occhi i cambiamenti che hanno investito il nostro mondo... Ne ho conosciuto solo frammenti. Pensare che l'ultima volta che camminai libero il Well of Eternity esisteva ancora e gli Alti Nobili tenevano corte con Azshara, la nostra amata regina.\n\nSento che il mio carceriere, il mio antico padrone, Athrikus, è ancora vivo... Già il mio sconforto sta lasciando il posto a pensieri di vendetta.", enHash = "7b4f0cf8", vanilla = true },
    },
    [958] = {
        title = { it = "Gli strumenti degli Alti Nobili", enHash = "29ef9607", vanilla = true },
        text = { it = "$C. Ho un compito da chiederti.\n\nHai visto le rovine di Ameth'Aran? Se no, le trovi sul lato orientale della strada principale, parecchio più a sud. Un tempo erano la dimora di molti Alti Nobili potenti, ora sono la testimonianza della distruzione che i loro armeggi hanno prodotto.\n\nLe Sentinelle mi dicono che gli spiriti degli Alti Nobili persistono, e che impugnano ancora i loro antichi strumenti magici. Quelle reliquie vanno sottratte, così da poterle distruggere.", enHash = "abbc8fc3", vanilla = true },
        objectives = { it = "Recupera 7 Highborne Relic per Thundris Windweaver, ad Auberdine.", enHash = "64b80881", vanilla = true },
        progress = { it = "Se solo gli strumenti della loro rovina fossero stati distrutti nel cataclisma che distrusse il nostro mondo... Comunque sia, dobbiamo fare il possibile perché gli orrori del nostro passato non si ripetano in futuro.", enHash = "9daba518", vanilla = true },
        reward = { it = "Anche se è di certo un parto della mia immaginazione, mi pare quasi di sentire su di esse la corruzione dell'immonda magia degli Alti Nobili. Le farò distruggere, così che il loro male a lungo sopito non si liberi mai più.", enHash = "3ac87ddc", vanilla = true },
    },
    [959] = {
        title = { it = "Guai ai moli", enHash = "3c22380d", vanilla = true },
        text = { it = "Ops!\n\nC'è stato un piccolo incidente, come vedi! Il carico che è arrivato stamattina da Booty Bay era enorme. Enorme, ti dico! Non ho mai visto tante casse. Be', cercavo di sbrigarmi e ho cominciato a scaricare un po' più di quanto riuscissi a reggere. Ed è lì che è venuto giù tutto.\n\nPrima che capissi cosa stava succedendo, ho visto quella peste di Mad Magglish scappare via con una bottiglia di porto di 99 anni. L'ho inseguito fin dentro le Wailing Caverns. Là dentro non ci entravo di sicuro.\n\nMagari tu sei abbastanza $Gcoraggioso:coraggiosa; da trovarlo?", enHash = "39ac31d3", vanilla = true },
        objectives = { it = "Crane Operator Bigglefuzz, a Ratchet, vuole che tu recuperi la bottiglia di 99-Year-Old Port da Mad Magglish, che si nasconde nelle Wailing Caverns.", enHash = "81ee9e66", vanilla = true },
        progress = { it = "Il capo del molo mi sta addosso da quando Mad Magglish se n'è andato con quel porto di 99 anni. A quanto pare quella bottiglia era un regalo per Gazlowe niente meno che da Baron Revilgaz in persona.\n\nSe sei abbastanza $Gcoraggioso:coraggiosa; e paziente da cercare Mad Magglish e riprenderti quel porto, farò in modo che tu abbia una bella ricompensa.", enHash = "53569854", vanilla = true },
        reward = { it = "Magnifico! E proprio mentre stavo per perdere il lavoro! Farò in modo che Gazlowe riceva subito questo regalo.\n\nGrazie, $N. Ben fatto, ti dico!", enHash = "6d50bba1", vanilla = true },
    },
    [960] = {
        title = { it = "Onu sta meditando", enHash = "ac9ed5c4", vanilla = true },
        reward = { it = "Sto meditando sul tuo compito, $N. Medito sulle ragioni per cui il Martello del Crepuscolo e i naga si trovano qui.\n\nQuando sei $Gpronto:pronta;, usa la Phial of Scrying per creare una Scrying Bowl. Poi contattami attraverso la coppa.\n\nSe hai perso la tua Phial of Scrying, eccotene un'altra.", enHash = "de64869c", vanilla = true },
    },
    [961] = {
        title = { it = "Onu sta meditando", enHash = "ac9ed5c4", vanilla = true },
        reward = { it = "Aver trovato dei cultisti del Martello del Crepuscolo è inquietante. Devo meditare sulle loro intenzioni...\n\nQuando avrai altre informazioni, parlami attraverso una Scrying Bowl. Se ti serve una Phial of Scrying per creare una coppa, allora... eccotene un'altra.", enHash = "67c8b3d2", vanilla = true },
    },
    [962] = {
        title = { it = "Serpentbloom", enHash = "5bfad808", vanilla = true },
        text = { it = "La Royal Apothecary Society, con sede nella grande Undercity di Lordaeron, mi ha mandata qui per un servizio molto preciso, $N. Forse vuoi aiutare me, e con me la Signora Oscura, nei nostri sforzi per far avanzare i Reietti.\n\nDi recente ho studiato un raro esemplare di flora chiamato Serpentbloom. Credo che in quantità maggiori questa erba abbia un grande potenziale.\n\nPurtroppo la Serpentbloom si trova solo nei recessi più bui delle Wailing Caverns, un sistema di grotte pericoloso che si trova nelle Barrens.", enHash = "871fc6f2", vanilla = true },
        objectives = { it = "Apothecary Zamah, a Thunder Bluff, vuole che tu raccolga 10 Serpentbloom.", enHash = "b3ea5cd3", vanilla = true },
        progress = { it = "Non vedo l'ora di scoprire se riesci a raccogliere abbastanza Serpentbloom nelle Wailing Caverns. Ne ho mandati molti a fare quello che chiedo, ma nessuno è tornato.", enHash = "15d9f281", vanilla = true },
        reward = { it = "Ah, esemplari splendidi. Hai fatto bene, $N.", enHash = "14d2d2dc", vanilla = true },
    },
    [963] = {
        title = { it = "Per amore eterno", enHash = "c90d2d46", vanilla = true },
        text = { it = "Dopo le battaglie del Well of Eternity, sentii dire che Ameth'Aran era stata distrutta e la sua gente uccisa, compreso il mio amore, Anaya.\n\nNon avrei mai pensato che, migliaia di anni dopo, il ricordo di Anaya mi avrebbe ancora perseguitato nei sogni. Vagando intontito per i boschi di Darkshore, mi ritrovai fra le rovine di Ameth'Aran... dove vidi lo spirito tormentato della mia amata.\n\nVa liberata, ma a me manca il cuore per farlo. Il suo spirito va distrutto.", enHash = "b6e0f629", vanilla = true },
        objectives = { it = "Libera lo spirito di Anaya Dawnrunner e riporta il suo ciondolo a Cerellean Whiteclaw, ad Auberdine.", enHash = "ba134c6a", vanilla = true },
        progress = { it = "Con un grande dolore nel cuore seguii lo Shan'do Stormrage nel letargo, e portai il mio dolore nei sogni, dormendo per il passare di migliaia di anni.", enHash = "5c121836", vanilla = true },
        reward = { it = "Grazie, $N. Forse sarebbe stato meglio... se l'avessi fatto io. Ma anche dopo tutte queste migliaia di anni non sono riuscito ad alzare la mano contro la mia amata.\n\nTi prego, vorrei restare solo con il mio dolore...", enHash = "981a5526", vanilla = true },
    },
    [965] = {
        title = { it = "La Tower of Althalaxx", enHash = "ccbcdb54", vanilla = true },
        text = { it = "Salve, giovane $R. Sono Elissa Starbreeze, e ho il compito di proteggere Auberdine da ogni pericolo.\n\nPer questo ho mandato Balthule Shadowstrike a osservare gli strani fatti intorno alla Tower of Althalaxx, a nord-est.\n\nDoveva essere tornato da un pezzo. Temo che nella foresta abbia incontrato qualche pericolo imprevisto. Ti sarei molto grata se lo trovassi e ti accertassi che stia bene.", enHash = "306721b8", vanilla = true },
        objectives = { it = "Trova Balthule Shadowstrike vicino alla Tower of Althalaxx, a Darkshore.", enHash = "bb21fedc", vanilla = true },
        reward = { it = "Ti manda Elissa? Allora porti buone nuove. Ho notizie preoccupanti da riferirle, e non avevo modo di farle arrivare.", enHash = "33a77063", vanilla = true },
    },
    [966] = {
        title = { it = "La Tower of Althalaxx", enHash = "ccbcdb54", vanilla = true },
        text = { it = "Un gruppo di stregoni si è insediato intorno alla torre e dentro. Sarei tornato prima ad Auberdine a riferire a Elissa, ma temevo di perdermi qualcosa mentre ero via.\n\nDelgren sospettava che una compagnia simile si stesse radunando alla torre, ma non sapeva perché.\n\nQualche brandello di pergamena che gli stregoni portano con sé mi è finito in mano, ma me ne serve altra per completare il quadro. Ti avverto però di non avventurarti nella torre: gli stregoni là dentro sono molto più potenti!", enHash = "f50c58a3", vanilla = true },
        objectives = { it = "Raccogli 4 Worn Parchment per Balthule Shadowstrike, vicino alla Tower of Althalaxx.", enHash = "35ba591b", vanilla = true },
        progress = { it = "Hai trovato altre loro pergamene? Se riesci a portarmele, dovrei riuscire a ricostruire un quadro più ampio del culto.", enHash = "5782923b", vanilla = true },
        reward = { it = "Mille grazie, $N. Questo dovrebbe fare un po' di luce su questo raduno di stregoni...\n\nHmm... il Cult of the Dark Strand... Non ho mai sentito parlare di questo gruppo. Non conoscendone la storia, è quasi impossibile dire quali siano i loro piani.\n\nNon c'è più tempo da perdere. L'avvertimento va consegnato subito a Delgren.", enHash = "e786ca07", vanilla = true },
    },
    [967] = {
        title = { it = "La Tower of Althalaxx", enHash = "ccbcdb54", vanilla = true },
        text = { it = "Il mio maestro, Delgren the Purifier, è un paladino che ha gentilmente offerto il suo aiuto per difendere le nostre foreste dalle forze dei demoni e dei non morti. Mi ha insegnato molto sull'Holy Light e sull'arte della battaglia.\n\nDelgren deve sapere subito delle attività del culto.\n\nLo troverai molto più a sud di qui, a Maestra's Post, nell'Ashenvale Forest. Fa' in fretta: temo che la minaccia del Dark Strand cresca di ora in ora.", enHash = "8c3b2f48", vanilla = true },
        objectives = { it = "Consegna la lettera di Balthule a Delgren the Purifier, nell'Ashenvale Forest.", enHash = "693e53a6", vanilla = true },
        progress = { it = "Hai qualcosa da sbrigare con me, $C?", enHash = "e9424d65", vanilla = true },
        reward = { it = "Se permetti, mi sembri un po' troppo ben $Gattrezzato:attrezzata; per fare il messaggero, eh? Immagino che Balthule volesse essere certo che la sua lettera arrivasse nelle mie mani. Vediamo cos'ha da dire...\n\nSono notizie inquietanti. Quando si trovano forze non morte o demoniache, io aiuto le Sentinelle a distruggerle.\n\nAll'inizio non ero abituato ai modi degli elfi della notte, ma ho imparato a rispettarli moltissimo come alleati.", enHash = "867f7e8a", vanilla = true },
    },
    [968] = {
        title = { it = "The Powers Below", enHash = "e00484ee", vanilla = true },
        text = { it = "Anche se è terribilmente consunto e graffiato, il titolo di questo libro si legge ancora sulla copertina:\n\nThe Powers Below\n\nDentro c'è un elenco di nomi impronunciabili con titoli minacciosi, metodi di culto e sacrifici preferiti... molti dei quali comprendono creature umanoidi vive.\n\nSul risvolto di copertina ci sono le parole: \"Bonegrip's Runes and Dooms, The Forlorn Cavern, Ironforge. Proprietario: Gerrig Bonegrip.\"\n\nSe Bonegrip vende libri come questo, forse lo ricomprerà.", enHash = "7f5b806c", vanilla = true },
        objectives = { it = "Porta il Book: The Powers Below a Gerrig Bonegrip, nella Forlorn Cavern, a Ironforge.", enHash = "9694c469", vanilla = true },
        progress = { it = "Salve, $Gsignore:signora;.\n\nPosso interessarti a uno dei miei tomi?", enHash = { "b978d192", "c4250b72" }, vanilla = true },
        reward = { it = "Ah, una copia di The Powers Below. Un testo interessante, questo. E qualcuno potrebbe trovarlo utile...\n\nMa questa copia è ridotta male. E guarda qui! Ci sono note a margine su quasi ogni pagina!\n\nHm... conosco questa copia. L'ho venduta a Bolgar l'anno scorso. Sei... $Gamico:amica; suo? Sì, l'avevo immaginato. Hai lo stesso fuoco dietro gli occhi!\n\nBe', per definizione, gli amici di Bolgar sono amici miei. E noi ci prendiamo cura dei nostri, giusto?", enHash = "2f2bf4ad", vanilla = true },
    },
    [970] = {
        title = { it = "La Tower of Althalaxx", enHash = "ccbcdb54", vanilla = true },
        text = { it = "La lettera di Balthule è allarmante. Questo Cult of the Dark Strand è una spina nel fianco che va tolta. Mi sono già occupato di un po' di quella feccia del Dark Strand a nord-est di qui, a Ordil'Aran. Uno di loro possiede una gemma dell'anima che, credo, racchiude il segreto del potere del culto.\n\nPortamela, e riuscirò a decifrare i segreti che contiene.", enHash = "18ec7407", vanilla = true },
        objectives = { it = "Procurati una Glowing Soul Gem e portala a Delgren the Purifier, a Maestra's Post.", enHash = "02454999", vanilla = true },
        progress = { it = "Ce l'hai quella gemma dell'anima?", enHash = "18cfcdfd", vanilla = true },
        reward = { it = "Hmm, una magia oscura incanta questa pietra dell'anima. Vediamo cosa c'è intrappolato dentro, che ne dici?", enHash = "9c2b34a0", vanilla = true },
    },
    [971] = {
        title = { it = "Conoscenza nelle Deeps", enHash = "c79f07bf", vanilla = true },
        text = { it = "Come forse saprai, io colleziono sapere. Sapere antico. Sapere potente. Sapere che apre porte, e sapere che può risvegliare Coloro Che Dormono.\n\nCorre voce che un antico frammento di sapere, il Lorgalis Manuscript, si trovi in fondo alle Blackfathom Deeps, in Ashenvale. Quel luogo è l'antica dimora di elfi morti da tempo. Elfi che possedevano una grande conoscenza, prima che la loro città cadesse in rovina.\n\nCerca il manoscritto nelle Blackfathom Deeps. Fallo, e non me ne dimenticherò. Nemmeno dopo... i giorni della fine.", enHash = "a18a4f76", vanilla = true },
        objectives = { it = "Porta il Lorgalis Manuscript a Gerrig Bonegrip, nella Forlorn Cavern a Ironforge.", enHash = "3db947ee", vanilla = true },
        progress = { it = "Il viaggio fino ad Ashenvale è lungo, e il tuo compito non è facile. Ma se mi porti il manoscritto, $N... allora la tua ricompensa sarà grande.", enHash = "8e143ae8", vanilla = true },
        reward = { it = "Hai trovato il manoscritto! Che giorno lieto è questo! Ne verranno fatte copie che saranno distribuite, e l'antica conoscenza di Lorgalis sarà finalmente nota ai miei fratelli e alle mie sorelle!\n\nIl tuo servizio per noi vale più di quanto tu sappia, $N. Ma spero che questo dono ti mostri la gratitudine che riserviamo ai nostri alleati.", enHash = "4508b5d7", vanilla = true },
    },
    [972] = {
        title = { it = "Water Sapta", enHash = "bc9fc586", vanilla = true },
        reward = { it = "Prendi la sapta dell'acqua e trova la pozza d'acqua corrotta a Silverpine, $N. Ho molta fiducia nelle tue capacità.", enHash = "51c208af", vanilla = true },
    },
    [973] = {
        title = { it = "La Tower of Althalaxx", enHash = "ccbcdb54", vanilla = true },
        text = { it = "Ilkrud Magthrull. Sì, so di lui. È un potente stregone orco che ha preso dimora al Fire Scar Shrine, un luogo di grande malvagità nel sud-ovest di Ashenvale.\n\nFinora è stato poco più di una seccatura e non me ne sono occupato, ma pare che il suo momento sia arrivato.", enHash = "2a188f78", vanilla = true },
        objectives = { it = "Porta Ilkrud Magthrull's Tome a Delgren the Purifier, a Maestra's Post.", enHash = "402193b7", vanilla = true },
        progress = { it = "Sembri un po' $Gscosso:scossa;, $N. Stai bene?", enHash = "931be773", vanilla = true },
        reward = { it = "Hai fatto una cosa grande, oggi, $N. Dovresti essere molto $Gfiero:fiera; di te per aver affrontato uno stregone di tale potere.\n\nOra vediamo cosa possiamo imparare dagli scritti di Ilkrud.", enHash = "45f4eda5", vanilla = true },
    },
    [976] = {
        title = { it = "Rifornimenti per Auberdine", enHash = "f6bbbb65", vanilla = true },
        text = { it = "Delgren mi ha chiesto di consegnare messaggi e rifornimenti a Sentinel Starbreeze ad Auberdine, ma non me la sento di partire da solo. Nemici pericolosi si aggirano per la foresta, e non voglio rischiare che questi rifornimenti e queste informazioni finiscano nelle mani sbagliate.\n\nSe tu e altri faceste da scorta, potrei partire subito. Con la vostra protezione non ho dubbi che riusciremo a portare questi beni fino ad Auberdine sani e salvi.", enHash = "787176da", vanilla = true },
        objectives = { it = "Parla con Delgren the Purifier a Maestra's Post dopo aver portato Feero sano e salvo attraverso l'Ashenvale Forest.", enHash = "b9526645", vanilla = true },
        progress = { it = "Le Sentinelle hanno grande bisogno di rifornimenti per rafforzarsi a Darkshore.", enHash = "25151b0e", vanilla = true },
        reward = { it = "Oggi hai fatto un buon lavoro, $C. Gli oggetti che abbiamo mandato in aiuto ad Auberdine serviranno subito ad affrontare le minacce oscure che infestano la foresta.\n\nPrendi questi, con la mia sincera gratitudine.", enHash = "9527ea05", vanilla = true },
    },
    [981] = {
        title = { it = "La Tower of Althalaxx", enHash = "ccbcdb54", vanilla = true },
        text = { it = "Per tutto il lavoro che hai fatto, meriti una bella ricompensa. Torna da Delgren e digli che Athrikus Narassin giace ucciso per mano tua, e che il Cult of the Dark Strand è battuto e disperso.", enHash = "8e720660", vanilla = true },
        objectives = { it = "Parla con Delgren the Purifier, a Maestra's Post.", enHash = "d1716a21", vanilla = true },
        reward = { it = "Sapevo che saresti $Gstato:stata; all'altezza, $N.\n\nSento che grandi imprese ti attendono, e che raddrizzerai molti dei torti che affliggono le nostre terre. Porta con te le mie benedizioni, $N, e anche questo dono.", enHash = "21ba2519", vanilla = true },
    },
    [982] = {
        title = { it = "Oceano profondo, mare sconfinato", enHash = "339e2639", vanilla = true },
        text = { it = "Al largo della costa di Darkshore, a nord di noi, ci sono due navi naufragate — la Silver Dawning e la Mist Veil. Tempo fa entrambe si sono imbattute in quei maledetti murloc mentre attraversavano il mare sconfinato dirette ad Auberdine. Ora giacciono sul fondo dell'oceano, come trofei di quei demoni.\n\nQuella notte nessuno dei due capitani se l'è cavata, e i loro diari e gli altri effetti personali sono ancora laggiù, dentro le casseforti. Vorrei che tu li recuperassi per noi: significherebbe molto per i membri dell'equipaggio ancora da queste parti.", enHash = "03943770", vanilla = true },
        objectives = { it = "Recupera la Silver Dawning's Lockbox e la Mist Veil's Lockbox per Gorbold Steelhand, ad Auberdine. Entrambe dovrebbero trovarsi a bordo dei relitti delle navi, a nord del villaggio.", enHash = "0e81b255", vanilla = true },
        progress = { it = "I capitani di quelle navi erano buoni elfi della notte, e meritavano una sorte migliore di quella che hanno avuto. Forse prendersi cura dei loro effetti personali sarà il modo migliore per dare pace ai loro spiriti.", enHash = "bb04f1f4", vanilla = true },
        reward = { it = "Hai reso a noi di Auberdine un grande servizio, $Gragazzo:ragazza;. Faremo in modo che i loro effetti siano trattati come si deve.\n\nQuanto a te, prendi questo. È il minimo che possa fare per qualcuno con il coraggio di rimettere le cose a posto.", enHash = { "661241b0", "f91b8d22" }, vanilla = true },
    },
    [983] = {
        title = { it = "Buzzbox 827", enHash = "d3406e75", vanilla = true },
        text = { it = "Ehi! Aiutami con la mia ultima invenzione, il buzzbox. Puoi parlare con gente lontanissima!\n\nForse li hai già visti: sono scatole con delle leve sopra. L'unico problema è che hanno bisogno di manutenzione continua.\n\nOgnuno ha un guasto diverso, ma io ho preso una decisione davvero furba. Li ho piazzati tutti vicino a creature che hanno i pezzi giusti per riparare quella macchina lì. Adesso il Buzzbox 827 è fuori uso. È appena a sud di Auberdine, vicinissimo. Ci vogliono 6 Crawler Leg per sistemarlo. Ti pago...", enHash = "17f856c4", vanilla = true },
        objectives = { it = "Raccogli 6 Crawler Leg e mettile nel Buzzbox 827.", enHash = "313b01c1", vanilla = true },
        progress = { it = "Il Buzzbox 827 se ne sta in un silenzio inquietante. Una sola spia lampeggiante segnala che servono 6 Crawler Leg da mettere nello scomparto.", enHash = "76c9ade1", vanilla = true },
        reward = { it = "Mentre infili le Crawler Leg nella macchina, senti gli ingranaggi cominciare a girare. A giudicare dai colpi che arrivano dal Buzzbox, le Crawler Leg stanno finendo al loro posto. Poco dopo la macchina comincia a ronzare, e senti una vocina che chiama da dentro.\n\n\"Pronto? Ehm... Pronto! L'hai riparato! Sono Wizbang, comunque! Grazie mille... Ehi, non è che ti andrebbe di ripararne un altro?\"", enHash = "ed1eb0da", vanilla = true },
    },
    [984] = {
        title = { it = "Quanto è grande la minaccia?", enHash = "5584bdb6", vanilla = true },
        text = { it = "Alcuni dei miei fratelli sono stati salvati da un furbolg corrotto, a Teldrassil, e ho giurato di fermare altre atrocità prima che altri della nostra specie vengano feriti... o peggio.\n\nA Darkshore ho già visto un paio di accenni di corruzione, ma non ho ancora trovato segni diffusi. Mi pare logico che l'indagine prosegua con i furbolg. Ti va di trovare uno dei loro accampamenti e di tornare da me se vedi segni di corruzione?", enHash = "2f319cb7", vanilla = true },
        objectives = { it = "Trova un accampamento di furbolg corrotti a Darkshore e torna da Terenthis, ad Auberdine.", enHash = "e1db7d29", vanilla = true },
        progress = { it = "Come procede la ricerca, $N?", enHash = "25ab2126", vanilla = true },
        reward = { it = "Sono notizie davvero terribili, $N.\n\nCon i furbolg così vicini ad Auberdine, dovremo prepararci all'inevitabile.\n\nGrazie, $N.", enHash = "cf8a888e", vanilla = true },
    },
    [985] = {
        title = { it = "Quanto è grande la minaccia?", enHash = "5584bdb6", vanilla = true },
        text = { it = "Hai già dimostrato di saper spiare il nostro nemico, $N. Hai anche la stoffa per combatterlo?\n\nNon tutti gli avventurieri preferiscono lo scontro diretto all'arte della furtività e dell'elusione.\n\nSe pensi di essere all'altezza, l'accampamento di furbolg a sud di Auberdine è al momento la minaccia più grande per la nostra gente. Lì troverai alcuni della tribù Blackwood. Uccidi 8 pathfinder e 5 windtalker e torna qui da me.", enHash = "5b6ba123", vanilla = true },
        objectives = { it = "Uccidi 8 Blackwood Pathfinder e 5 Windtalker e torna da Terenthis, ad Auberdine.", enHash = "d1c0bb04", vanilla = true },
        progress = { it = "Non trattenere la mano da ciò che va fatto, $Gfigliolo:figliola;. So quanto debba essere ripugnante l'idea di uccidere le creature della foresta, ma in questo caso è necessario. Non è stata trovata nessuna cura per la corruzione scatenata sulla foresta, e dobbiamo fare il possibile per fermarne l'avanzata finché non se ne troverà una.", enHash = "985c77cb", vanilla = true },
        reward = { it = "Lava il sangue dalle tue vesti, $N, e non piangere ciò che hai dovuto fare. Rendi grazie, piuttosto. Hai ridotto la minaccia per la nostra gente qui ad Auberdine, anche se Darkshore resta in pericolo per gli effetti del Fel Moss.", enHash = "77353cd3", vanilla = true },
    },
    [986] = {
        title = { it = "Un padrone perduto", enHash = "1b485d9f", vanilla = true },
        text = { it = "$N, le tue capacità mi hanno già aiutato nella mia impresa. Posso approfittarne di nuovo e chiederti di aiutare Grimclaw e il suo padrone Volcor? In più, posso crearti un mantello magico che ti permetterà di muoverti senza essere $Gdisturbato:disturbata; dalle creature di Darkshore mentre lo cerchi.\n\nPer fare il mantello mi serviranno cinque belle pellicce di moonstalker, prese da un Moonstalker Sire o da una Moonstalker Matriarch, per avere materiale a sufficienza. Quei felini si trovano vicino al Wildbend River, a sud, o anche più a sud, verso Ashenvale.", enHash = "4b0995e3", vanilla = true },
        objectives = { it = "Trova 5 Fine Moonstalker Pelt e portale a Terenthis, ad Auberdine.", enHash = "173dc525", vanilla = true },
        progress = { it = "In coscienza non posso permetterti di cercare Volcor finché non ti avrò fatto quel mantello.", enHash = "fc28ccbd", vanilla = true },
        reward = { it = "Queste andranno benissimo, $N. Mi metto subito al lavoro sul mantello.\n\nDammi qualche momento, poi torna da me.\n\nAh, un'ultima cosa: dopo aver usato l'incantesimo sul mantello sarai $Glimitato:limitata; nei tuoi rapporti con gli altri. Se puoi evitarlo, non fare altro che parlare. Qualcosa di più potrebbe dissolvere l'illusione.", enHash = "605f47db", vanilla = true },
    },
    [990] = {
        title = { it = "Viaggio verso Ashenvale", enHash = "48a4f31a", vanilla = true },
        text = { it = "$N, la mia padrona, Raene Wolfrunner, ti aspetta nella città di Astranaar, ad Ashenvale. Con il tuo aiuto, forse potremo almeno alleviare un po' della corruzione che ha messo radici laggiù.\n\nVa' a sud da qui e resta vicino alla strada: se segui queste indicazioni ci arriverai senza problemi.", enHash = "759e9d08", vanilla = true },
        objectives = { it = "Trova Raene Wolfrunner, ad Ashenvale.", enHash = "1d625702", vanilla = true },
        reward = { it = "Ah, $Gun:una; $C da Darkshore. Selarin ha fatto bene a mandarti qui così in fretta, $N. Vorrei che il tuo viaggio non fosse capitato in un momento così difficile. Forse con il tuo aiuto potremo migliorare le cose.\n\nIo comincerei la visita parlando con gli altri cittadini di Astranaar. Qualcuno avrà di sicuro bisogno del tuo aiuto.", enHash = "e9be4922", vanilla = true },
    },
    [991] = {
        title = { it = "La purificazione di Raene", enHash = "4a88f731", vanilla = true },
        text = { it = "$N, anche un mio amico di vecchia data sta aiutando le Sentinelle qui ad Ashenvale, ma non è ancora tornato.\n\nAveva delle piste per trovare un oggetto che secondo lui poteva rallentare gli attacchi dei furbolg contro la nostra gente: una verga creata da un mago malvagio, ormai morto.\n\nPrima di partire da qui, ha accennato che cercava una gemma per la verga.\n\nHa detto che la gemma poteva essere nascosta nel santuario del Lake Falathim, ai piedi della montagna a ovest. La gemma era custodita là prima che il luogo venisse invaso.\n\nTrova il mio amico, $N, ti prego.", enHash = "8d094e75", vanilla = true },
        objectives = { it = "Trova Teronis, ad Ashenvale.", enHash = "777a0d09", vanilla = true },
        reward = { it = "Il corpo di Teronis giace spezzato in cima all'isola. Per qualche ragione ignota, i murloc lo hanno lasciato stare.\n\nI tagli profondi sul suo cadavere vengono chiaramente dalle armi e dagli artigli dei murloc.", enHash = "65c3b858", vanilla = true },
    },
    [993] = {
        title = { it = "Un padrone perduto", enHash = "1b485d9f", vanilla = true },
        text = { it = "Il mantello è pronto, $N. È venuto il momento di trovare Volcor. Posso solo sperare che siamo in tempo.\n\nLa magia del mantello, una volta invocata, non durerà a lungo: forse cinque minuti. Starà a te capire quando usarla: ti consiglierei di aspettare di aver trovato Grimclaw.\n\nSe quello che mi ha raccontato è vero, troverai il suo padrone in una caverna a sud di qui. Grimclaw ti aspetterà lungo la strada. Fagli un cenno con la mano quando lo vedi, e ti indicherà la via verso il suo padrone.", enHash = "a31af8a6", vanilla = true },
        objectives = { it = "Trova Volcor a Darkshore e dagli l'Enchanted Moonstalker Cloak.", enHash = "8f7f3046", vanilla = true },
        reward = { it = "Meraviglioso! Terenthis ha trovato qualcuno che mi aiutasse.\n\nE guarda, un mantello di moonstalker...<tosse> Oh... che male. Grazie, $N.\n\nI furbolg mi hanno ferito prima che riuscissi a sfuggirgli. Dammi un momento e dovrei stare abbastanza bene da parlare ancora un po'.", enHash = "6b54ad08", vanilla = true },
    },
    [994] = {
        title = { it = "Fuga di forza", enHash = "70548071", vanilla = true },
        text = { it = "E va bene, $N, sia la forza. Usciamo di qui appena sei $Gpronto:pronta;. Ci apriremo la strada combattendo fino alla via — Grimclaw dovrebbe essere ancora lì. Arrivati là, ci separiamo.\n\nTerenthis vorrà sentire subito la tua versione dei fatti, quindi va' ad Auberdine dopo che saremo usciti.", enHash = "e637ae79", vanilla = true },
        objectives = { it = "Proteggi Volcor finché non arrivate alla strada, poi parla con Terenthis, ad Auberdine.", enHash = "d7996a57", vanilla = true },
        reward = { it = "$N! Che piacere vederti tornare con successo. Il tuo aiuto a Volcor mi dà fiducia che riusciremo a superare le prove che ci aspettano qui a Darkshore e oltre.", enHash = "bd1019bd", vanilla = true },
    },
    [995] = {
        title = { it = "Fuga di soppiatto", enHash = "64b77409", vanilla = true },
        text = { it = "E va bene... se ne sei $Gsicuro:sicura;, sgusciamo fuori di qui. Partiamo quando sei $Gpronto:pronta;.\n\nRicorda: una volta fuori, raggiungi Terenthis ad Auberdine. Io ci vado per conto mio, visto che probabilmente sarò più veloce di te.", enHash = "a181f304", vanilla = true },
        objectives = { it = "Fuggi dalla caverna dei furbolg e raggiungi Terenthis, ad Auberdine.", enHash = "721a9b7a", vanilla = true },
        progress = { it = "Sì, $N?", enHash = "befc103a", vanilla = true },
        reward = { it = "$N! Che piacere vederti tornare con successo. Il tuo aiuto a Volcor mi dà fiducia che riusciremo a superare le prove che ci aspettano qui a Darkshore e oltre.", enHash = "bd1019bd", vanilla = true },
    },
    [997] = {
        title = { it = "La terra di Denalan", enHash = "859c1a7b", vanilla = true },
        text = { it = "Stai andando a sud? Al Lake Al'Ameth? Se è così, avrei un compito da chiederti...\n\nIl mio collega Denalan ha un accampamento lungo la sponda orientale del lago, dove studia e sperimenta sulla vita vegetale di Teldrassil. Aveva richiesto un pacco di terre rare da Darnassus, ed era in ritardo: è arrivato qui a Dolanaar solo da poco.\n\nPuoi portargli il pacco?", enHash = "1ed8bff8", vanilla = true },
        objectives = { it = "Porta il pacco di Rare Earth a Denalan, al Lake Al'Ameth.", enHash = "8299ba5b", vanilla = true },
        progress = { it = "Hai qualcosa per me?", enHash = "ac74d893", vanilla = true },
        reward = { it = "Ah, è arrivata! Aspettavo questa terra rara da parecchio. Spero sia ancora fresca...\n\nGrazie di avermela portata, $N. Sei $Gun:una; $R $Ggeneroso:generosa; del tuo tempo.", enHash = { "bed55f94", "ea6a70d7" }, vanilla = true },
    },
    [1000] = {
        title = { it = "La nuova frontiera", enHash = "7d4ab5dc", vanilla = true },
        text = { it = "Attenzione, eroi!\n\nIl Cenarion Circle cerca persone in grado di aiutarlo a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una desolazione proibita, piena di pericoli inimmaginabili, e il Circle ha bisogno di persone volenterose e d'onore che agiscano per suo conto.\n\nTutti gli interessati chiedano udienza al Cenarion Circle. Parlate con Arch Druid Hamuul Runetotem, sull'Elder's Rise di Thunder Bluff, per maggiori informazioni!", enHash = "5667e653", vanilla = true },
        objectives = { it = "Parla con Arch Druid Hamuul Runetotem, sull'Elder Rise di Thunder Bluff, della chiamata del Cenarion Circle a esplorare le frontiere di Kalimdor.", enHash = "e162146d", vanilla = true },
        reward = { it = "Salve, $C.\n\nSono lieto di vedere che gente come te si interessa al benessere della natura; i racconti delle tue grandi imprese ti precedono, e qui sei $Gbenvenuto:benvenuta;. Vederti davanti a me mi dà fiducia che il Cenarion Circle riceverà l'aiuto di cui ha bisogno.\n\nIl nostro legame con il Cenarion Circle di Moonglade supera le divisioni tra razze e quelle politiche. Ricordalo mentre lavori per il Circle, e farai bene.", enHash = "37ad072b", vanilla = true },
    },
    [1001] = {
        title = { it = "Buzzbox 411", enHash = "d3405f4c", vanilla = true },
        text = { it = "Una vocina gracchia dal profondo della macchina.\n\n\"Qui Wizbang! Il prossimo Buzzbox è a nord di Auberdine, sulla spiaggia.\n\nDunque, quel Buzzbox è il numero 411 e per le riparazioni gli servono 3 Thresher Eye. Stanno appena al largo! I Darkshore Thresher... *Hic*... Scusa tanto...\n\nCome l'altra volta, quando dai al Buzzbox la roba, lui sputa fuori la tua ricompensa. *Hic*... Cosa? No, sto benissimo!\"", enHash = "8dbe13c9", vanilla = true },
        objectives = { it = "Raccogli 3 Thresher Eye dai Darkshore Thresher, in mare aperto vicino al Buzzbox 411.", enHash = "f53c9c74", vanilla = true },
        progress = { it = "Lo sportello della macchina è aperto e sembra aspettare con ansia che dentro vengano messi 3 Thresher Eye.", enHash = "5a703c94", vanilla = true },
        reward = { it = "Il Buzzbox torna a ronzare poco dopo che hai messo dentro i Thresher Eye. C'è un attimo di scariche, poi senti una vocina familiare che chiama.\n\n\"Il vino di crawler è il migliore...\" *hic*\n\n\"Cosa? Oh, l'hai già riparato? Però, sei $Gshvelto:shvelta;. Allora, ti va di ripararne un altro?\"\n\nTi sembra di sentire un liquido versato in una tazza, seguito da rumorose sorsate.", enHash = "a5bfa449", vanilla = true },
    },
    [1002] = {
        title = { it = "Buzzbox 323", enHash = "d3405bac", vanilla = true },
        text = { it = "Il Buzzbox emette una scarica mentre senti Wizbang cominciare a parlare.\n\n\"Il prossimo Buzzbox è il numero 323. Shta a nord di Auberdine ma... dov'è la birra? Eh? Ah, shta shulla strada, quindi non dovreshti faticare a trovarlo vicino al ponte.\"\n\nWizbang borbotta qualcosa di incomprensibile, poi senti una sonora sorsata.\n\n\"A queshto servono Moonstalker Fang... 6.\"", enHash = "cf49a92c", vanilla = true },
        objectives = { it = "Raccogli 6 Moonstalker Fang e mettile nel Buzzbox 323.", enHash = "cd56fb71", vanilla = true },
        progress = { it = "Anche se non hai ancora messo dentro le 6 Moonstalker Fang, ti sembra di sentire scariche e farneticazioni sconnesse di gnomo provenire dall'interno. Che qualcun altro abbia già riparato la macchina?", enHash = "efc7239b", vanilla = true },
        reward = { it = "Il Buzzbox scatta all'improvviso in funzione, e da dentro si sente distintamente il rumore di denti ridotti in polvere.\n\n\"Allora, ce l'hai fatta! Queshta shì che è una bella notizia... Allora... Perché non te ne vai? Oh! A meno che tu non voglia un altro lavoro!\"", enHash = "bc7ac5f7", vanilla = true },
    },
    [1003] = {
        title = { it = "Buzzbox 525", enHash = "d3406330", vanilla = true },
        text = { it = "Sopra i rumori di ebollizione e di gocciolio che vengono dalla macchina, senti la voce tremolante di Wizbang che chiama.\n\n\"Il proshimo è giù in fondo alla shtrada, a sud. Non dovreshti faticare a trovarlo... shta appena di lato... vicino a uno shteccato. Credo di averlo nashtosto in certi cheshpugli... Cheshpuuugli. Ehehe... Shì, il Buzzbox 525 vuole i Grizzled Scalp di quei Grizzled Thistle Bear. Ragazzi, che shcioglilingua. Grizzshled... Ehehe...\"\n\nSenti altre sorsate mentre la macchina si zittisce. Poi, all'improvviso, torna a vivere.\n\n\"4!\"", enHash = "b09717b9", vanilla = true },
        objectives = { it = "Raccogli 4 Grizzled Scalp dai Grizzled Thistle Bear a sud di Auberdine e mettili nel Buzzbox 525.", enHash = "52199d02", vanilla = true },
        progress = { it = "Senti cantare dal Buzzbox 525.\n\n\"Dolshe è il vino di crawler, buona la birra di thresher, e il dishtillato di moonstalker è shovrano. Ma nulla m'è caro come una birra di thistle bear, e preshto ne avrò una in mano!\"\n\nLo sportello è aperto e aspetta i 4 Grizzled Scalp, mentre senti la canzone ripetersi all'infinito.", enHash = "4efe830b", vanilla = true },
        reward = { it = "\"Allora, li hai mesh dentro gli scalp? Queshto shì che è bello... Eh? Be', shì, immagino che tu l'abbia capito che posho parlarti anche shenza i materiali nella macchina. Ma quando ho detto che erano rotti dicevo la verità!\n\nVedi, oltre a essere shtrumenti di comunicashione, i Buzzbox distillano anche del gran liquore. Shcusa l'ingannuccio, ma agli elfi della notte il mio commercio di liquori non gli va giù nelle loro cittadine. Ho messo qualcosha di speciale in queshta scatola per ringrasharti di quello che hai fatto. Goditelo!\"", enHash = "912f5346", vanilla = true },
    },
    [1007] = {
        title = { it = "L'Ancient Statuette", enHash = "53ca622a", vanilla = true },
        text = { it = "Vorrei affidarti un compito, $N.\n\nEro sulla mia piccola imbarcazione, a sfiorare le rovine sommerse di Zoram, quando i naga mi hanno attaccato, emergendo dall'acqua e dilaniandomi con gli artigli! Sono fuggito, portando con me le poche provviste che potevo, per allestire questo misero campo.\n\nMa quando ho raggiunto la riva e sono corso via... il mio bene più prezioso è andato perduto.\n\nTi prego, $N, trova il luogo dell'imboscata, lungo la costa a nord, e cerca un'antica statuetta. È la ragione per cui ho affrontato i pericoli dello Zoram Strand.", enHash = "8484b96c", vanilla = true },
        objectives = { it = "Porta l'Ancient Statuette a Talen, nel suo campo vicino allo Zoram Strand.", enHash = "8968963b", vanilla = true },
        progress = { it = "Hai trovato la statuetta, $N?", enHash = "5ae89566", vanilla = true },
        reward = { it = "L'hai trovata! Grazie, $N!\n\nLa vecchia città di Zoram custodisce molti segreti, e questa statuetta potrebbe essere la chiave di molti di essi.", enHash = "0e1fdb25", vanilla = true },
    },
    [1008] = {
        title = { it = "Lo Zoram Strand", enHash = "770e948c", vanilla = true },
        text = { it = "C'è un male in agguato sulla nostra costa nord-occidentale, nota come Zoram Strand.\n\nÈ il luogo di riposo della città dannata di Zoram, distrutta durante la Grande Separazione e sommersa dai mari. È perduta per gli elfi della notte da ere. Perduta, e quasi dimenticata.\n\nOra i naga sono tornati, e per quale motivo non lo sappiamo. Ma il motivo conta poco: dobbiamo uccidere questi demoni e ricacciarli negli abissi!\n\nTorna da me quando la tua missione sarà compiuta.", enHash = "eacc25ef", vanilla = true },
        objectives = { it = "Porta 20 Wrathtail Head a Shindrell Swiftfire, ad Astranaar.", enHash = "8472a0cc", vanilla = true },
        progress = { it = "Non possiamo permettere ai naga di invadere le nostre coste, $N. È fondamentale che tu vada allo Zoram Strand e porti a termine la missione.", enHash = "59996126", vanilla = true },
        reward = { it = "Molto ben fatto, $N. Le tue azioni allo Zoram Strand contro i naga sono encomiabili.\n\nSo che la tua impresa non è stata facile, perché la forza e l'astuzia dei naga sono ben note agli elfi della notte. Lo sappiamo, perché condividiamo una storia con loro.\n\nÈ una storia che non ho voglia di ripetere.", enHash = "710ccb0f", vanilla = true },
    },
    [1009] = {
        title = { it = "Ruuzel", enHash = "c9303acf", vanilla = true },
        text = { it = "Temo che i segreti dell'antica statuetta resteranno per sempre nascosti, a meno che tu non trovi la chiave della sua antica serratura.\n\nQuella chiave è un anello, il Ring of Zoram. Apparteneva a chi governava questa città, prima che le onde della Grande Separazione la sommergessero.\n\nPer anni l'anello è rimasto perduto, ma i naga l'hanno ritrovato di recente.\n\nLa loro condottiera, Ruuzel, vive su un'isola all'estremità settentrionale di Zoram. Ti prego, $N, recupera l'anello per me!", enHash = "a22d2977", vanilla = true },
        objectives = { it = "Porta il Ring of Zoram a Talen, vicino allo Zoram Strand.", enHash = "dbfa5dda", vanilla = true },
        progress = { it = "Si dice che il Ring of Zoram sia la chiave di qualsiasi serratura della città. Ce l'hai, $N?", enHash = "dbbbba35", vanilla = true },
        reward = { it = "Hai trovato l'anello! Grazie, $N. Prendi questo come pagamento, e sappi che quel che hai fatto oggi resterà per sempre nella mia memoria.", enHash = "00ddce4a", vanilla = true },
    },
    [1010] = {
        title = { it = "Bathran's Hair", enHash = "3e9bf08a", vanilla = true },
        text = { it = "C'è una pianta che un tempo cresceva nelle vecchie rovine di Bathran's Haunt, a nord. La pianta si chiamava Bathran's Hair ed era nota per curare i mali dello spirito.\n\nNel villaggio c'è una bambina malata, e credo che non sia solo un male del corpo. Vuoi andare a Bathran's Haunt e cercare Bathran's Hair? Potrebbe servirmi per curarla come si deve.\n\nBathran's Haunt si trova a nord di Maestra's Post e appena a sud del confine con Darkshore.", enHash = "062bba74", vanilla = true },
        objectives = { it = "Porta 5 Bathran's Hair a Orendil Broadleaf, ad Ashenvale.", enHash = "7ba4f8b9", vanilla = true },
        progress = { it = "Hai raccolto le Bathran's Hair, $N? La salute della bambina peggiora di ora in ora...", enHash = "a35cf5cb", vanilla = true },
        reward = { it = "Ah, hai le erbe! Ora preparerò una cura per la bambina, e pregherò che il mio intruglio funzioni.\n\nE... i Reietti sono a Bathran's Haunt? Molto preoccupante, questo. Molto preoccupante davvero...", enHash = "1f0236fa", vanilla = true },
    },
    [1011] = {
        title = { it = "Le malattie dei Reietti", enHash = "51df611a", vanilla = true },
        text = { it = "I Reietti, il braccio non morto dell'Orda, si sono insinuati ad Ashenvale e si aggirano tra le nostre rovine e i nostri tumuli. Crediamo che il loro scopo sia diffondere malattie nelle terre degli elfi della notte. Dobbiamo averne la conferma!\n\nI Reietti hanno un accampamento a sud di qui, vicino al Dor'Danil Barrow Den, dove preparano veleni e malattie e li mettono in bottiglie. Apriti la strada in quell'accampamento e ruba una bottiglia di malattia. Torna con una di quelle bottiglie. La analizzerò e ne scoprirò lo scopo.", enHash = "0b3fea58", vanilla = true },
        objectives = { it = "Porta una Bottle of Disease a Kayneth Stillwind, a Forest Song.", enHash = "55d39c4a", vanilla = true },
        progress = { it = "Hai trovato l'accampamento, $N? Hai una bottiglia di malattia?", enHash = "9b67b87f", vanilla = true },
        reward = { it = "Molto bene, $N. Ora... analizzando il contenuto di questa bottiglia, gli scopi dei Reietti verranno alla luce!", enHash = "cecc2b1c", vanilla = true },
    },
    [1012] = {
        title = { it = "Druidi impazziti", enHash = "93ca8d67", vanilla = true },
        text = { it = "Mentre lottavo con i veleni dei Reietti, ho avuto una visione. Ho visto i druidi del Dor'danil Barrow Den, avvelenati... assassinati dai non morti! Ora sono spettri erranti, separati dai loro corpi e impazziti.\n\nPerché un giorno gli spiriti dei druidi trovino pace, devi entrare nel Dor'danil Barrow Den e distruggere quelli che un tempo erano i suoi grandi capi: Taneel Darkwood, Uthil Mooncall e Mavoris Cloudsbreak.\n\nFa' questo, poi torna da me.", enHash = "65dabf42", vanilla = true },
        objectives = { it = "Uccidi i druidi: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; poi torna da Kayneth Stillwind, a Forest Song.", enHash = "452a00a1", vanilla = true },
        progress = { it = "L'angoscia dei druidi di Dor'danil perseguita ancora i miei sogni, $N. Devi distruggere i loro capi!", enHash = "bb01b9f2", vanilla = true },
        reward = { it = "Ho sentito l'angoscia dei Dor'danil Barrows attenuarsi, e ho capito che avevi portato a termine il tuo compito.\n\nÈ stato un lavoro cupo il tuo, $N, perché gli spiriti che hai distrutto erano soltanto vittime del male dei Reietti. Ma con la loro distruzione, speriamo che gli altri spiriti impazziti trovino pace.", enHash = "ee9c0292", vanilla = true },
    },
    [1013] = {
        title = { it = "Il Book of Ur", enHash = "14f3689e", vanilla = true },
        text = { it = "$N, Shadowfang Keep custodisce un libro, il Book of Ur, che sarebbe molto prezioso nella mia collezione. Ur era un grande mago di Dalaran prima dell'arrivo del Flagello, e i suoi studi su altri mondi sono di grande valore per... certi ambienti tra i Reietti.\n\nEntra a Shadowfang Keep e trova il libro. Portamelo, e riferirò il tuo servizio alla nostra Signora Oscura...", enHash = "e904b137", vanilla = true },
        objectives = { it = "Porta il Book of Ur a Keeper Bel'dugur, all'Apothecarium, nell'Undercity.", enHash = "883e1fc7", vanilla = true },
        progress = { it = "Hai trovato il libro, $N?", enHash = "dfe334c4", vanilla = true },
        reward = { it = "Molto bene. Questo libro si aggiungerà degnamente alle mie raccolte delle opere di Ur. Il suo sapere era grande, ma la sua coscienza gli impedì di arrivare al vero potere. E così, quando venne il Flagello e la sua forza fu messa alla prova, non resse.\n\nNoi Reietti non possiamo permetterci una debolezza simile, se vogliamo sopravvivere...\n\n...Se vogliamo conquistare.", enHash = "4d70230b", vanilla = true },
    },
    [1014] = {
        title = { it = "Arugal deve morire", enHash = "f03d17db", vanilla = true },
        text = { it = "Arugal risiede ancora a Shadowfang Keep. Non possiamo rivendicare Silverpine come roccaforte strategica per la Signora Oscura finché Arugal non sarà ucciso.\n\nMi occuperò io di sradicare la sua magia, $N. Ma lascio nelle tue mani il compito di far incontrare ad Arugal la morte che tanto si merita.\n\nVa' a Shadowfang Keep e metti fine una volta per tutte agli incantesimi immondi di Arugal. Portami la testa di quel vile mago!", enHash = "91815e53", vanilla = true },
        objectives = { it = "Uccidi Arugal e porta la sua testa a Dalar Dawnweaver, al Sepulcher.", enHash = "4c561161", vanilla = true },
        progress = { it = "Con la morte di Arugal rafforzeremo la presa della Signora Oscura su Lordaeron.", enHash = "17c7ee39", vanilla = true },
        reward = { it = "La Silverpine Forest è finalmente libera dalla morsa di quel miserabile di Arugal. Hai reso un grande servizio alla Signora Oscura, $N. La tua tenacia sarà ricompensata.", enHash = "e9c31ef2", vanilla = true },
    },
    [1015] = {
        title = { it = "La nuova frontiera", enHash = "7d4ab5dc", vanilla = true },
        text = { it = "Attenzione, eroi!\n\nIl Cenarion Circle cerca persone in grado di aiutarlo a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una desolazione proibita, piena di pericoli inimmaginabili, e il Circle ha bisogno di persone volenterose e d'onore che agiscano per suo conto.\n\nTutti gli interessati chiedano udienza al Cenarion Circle. Parlate con l'arcidruido di Darnassus, Fandral Staghelm, per maggiori informazioni!", enHash = "39a7f0c3", vanilla = true },
        objectives = { it = "Parla con Arch Druid Fandral Staghelm, al Cenarion Enclave di Darnassus, della chiamata del Cenarion Circle a esplorare le frontiere di Kalimdor.", enHash = "116cbdc6", vanilla = true },
        reward = { it = "Cosa ti fa pensare che io abbia voglia di essere $Gscocciato:scocciata; da gente come te, $C? Aspetta, lascia che interrompa i compiti importanti che svolgo ogni giorno per aiutarti a trovare un aggeggio da qualche parte. Ma certo, il bene di Darnassus, anzi, di tutta Teldrassil, deve venire dopo l'acquisto di un gingillo per la tua collezione.\n\nQuegli sciocchi del Moonglade mi fanno perdere tempo con le loro richieste di aiuto, e ora devo sopportare anche questo?", enHash = "55f40ca3", vanilla = true },
    },
    [1016] = {
        title = { it = "Bracciali elementali", enHash = "9c3e78bb", vanilla = true },
        text = { it = "Prendi questa pergamena divinatoria — può rivelare chi ha creato questi elementali. Ma ti servirà qualcosa che appartenga a loro, da usare come reagente per concentrare la magia della pergamena — i loro bracciali dovrebbero andare benissimo.\n\nBastano pochi bracciali intatti presi dalle creature. Gli altri bracciali non ci serviranno, ma forse per un mercante varranno qualcosa, se vuoi venderli. Quando hai i bracciali intatti, prova a usare la pergamena. Torna da me con il risultato e vedremo come procedere.", enHash = "e6916a83", vanilla = true },
        objectives = { it = "Raccogli 5 Intact Elemental Bracer e usa su di essi la Divining Scroll. Poi porta la Divined Scroll a Sentinel Velene Starstrike al Silverwind Refuge.", enHash = "632726ef", vanilla = true },
        progress = { it = "Visto che per uccidere gli elementali devi distruggere i loro bracciali, sarà probabilmente difficile trovare proprio quelli che contengono le informazioni di cui la pergamena divinatoria ha bisogno. Puoi scambiare bracciali con altri per ottenere quelli che ti servono, o forse hai già il foglio divinato?", enHash = "1b5cf517", vanilla = true },
        reward = { it = "Ben fatto, $N, questo dovrebbe darci le informazioni che ci servono per scoprire il colpevole. Che ne diresti di eliminare il mago che riempie i nostri specchi d'acqua di elementali corrotti? La corruzione di Ashenvale e di altre terre mi rivolta lo stomaco già di suo — sapere che un mago si adopera per peggiorarla mi disgusta oltre ogni dire. Gliela faremo pagare.", enHash = "3276ffa0", vanilla = true },
    },
    [1017] = {
        title = { it = "Il mago evocatore", enHash = "88b25b8f", vanilla = true },
        text = { it = "C'è un solo mago non morto nelle Barrens capace di profanare tutti questi elementali dell'acqua. Ed è anche l'unico abbastanza folle da provarci. Sarilus Foulborne se ne sta probabilmente in cima al Dreadmist Peak, a ridere di me.\n\n$N, devi entrare in territorio nemico e distruggere quel farabutto. Ne ho abbastanza della sua idiozia, e dobbiamo mostrargli cosa succede a chi infastidisce le Sentinelle.\n\nDistruggilo e portami la sua testa. Fa' attenzione, però: l'Orda potrebbe essere in cerca di te.", enHash = "7f92702e", vanilla = true },
        objectives = { it = "Uccidi Sarilus Foulborne e porta la sua testa a Sentinel Velene Starstrike, al Silverwind Refuge.", enHash = "145e6bbf", vanilla = true },
        progress = { it = "È fatta? Sarilus Foulborne è morto?", enHash = "703dff88", vanilla = true },
        reward = { it = "Ora posso vedere quel sorriso ripugnante cancellato per sempre dalla sua faccia. Hai fatto davvero un ottimo lavoro, $N. Prendi questa, la Light of Elune, e bevine quando tutto sembra perduto e la morte è vicina. Potrebbe salvarti, se la Dea vorrà.", enHash = "c8fbca89", vanilla = true },
    },
    [1020] = {
        title = { it = "Orendil's Cure", enHash = "0de110fe", vanilla = true },
        text = { it = "$N, ho creato una cura che credo aiuterà la bambina malata. Portala ad Astranaar e dalla al genitore della bambina, Pelturas Whitemoon.\n\nPer arrivare ad Astranaar, segui la strada a sud, poi a est.", enHash = "8fb0c4a4", vanilla = true },
        objectives = { it = "Porta Orendil's Cure a Pelturas Whitemoon, ad Astranaar.", enHash = "e375183b", vanilla = true },
        progress = { it = "Devo scusarmi, non ho tempo di parlare. La mia bambina, Relara, sta morendo!", enHash = "343fe71f", vanilla = true },
        reward = { it = "Questa viene da Orendil?\n\nLa sua abilità con le erbe e nella guarigione è grande. Questa cura mi dà speranza, mentre prima ne avevo poca...", enHash = "c0312187", vanilla = true },
    },
    [1021] = {
        title = { it = "Satiro immondo! Driadi in pericolo!", enHash = "2e31b654", vanilla = true },
        text = { it = "Ascolta, non so chi sei, ma mi serve il tuo aiuto. Le mie sorelle sono andate a riprendere il Branch of Cenarius ai satiri. Hanno detto che sarebbero tornate presto, ma sono passati due giorni interi!\n\n$N, devi trovarle! Cercavano le rovine di un tempio degli elfi della notte a Xavian, a nord-est. Non so cosa pensare. Cerca Anilia, era lei a guidarle nella ricerca.", enHash = "a92ba026", vanilla = true },
        objectives = { it = "Trova Anilia, a Xavian.", enHash = "8c65fa1b", vanilla = true },
        reward = { it = "A giudicare dalla ferita aperta nel fianco, Anilia è in punto di morte.", enHash = "adc6826e", vanilla = true },
    },
    [1022] = {
        title = { it = "L'Howling Vale", enHash = "767a3c4d", vanilla = true },
        text = { it = "Anche se abbiamo dedicato molte risorse e molti sforzi a scacciare i demoni rimasti dal Felwood a nord, i successi sono stati pochi. Siamo riusciti a tenere gran parte della presenza demoniaca lontana da Ashenvale.\n\nA nord, vicino al confine del Felwood, il santuario in rovina di Mel'Thandris è stato occupato da misteriosi uomini-lupo. I loro richiami agghiaccianti hanno fatto sì che la zona venisse chiamata Howling Vale. Il Tome of Mel'Thandris custodito nel santuario potrebbe far luce sul motivo per cui questi uomini-lupo sono arrivati.", enHash = "73a9ca8a", vanilla = true },
        objectives = { it = "Va' all'Howling Vale e studia il Tome of Mel'Thandris, poi torna da Sentinel Melyria Frostshadow, allo Shrine of Aessina.", enHash = "5433f892", vanilla = true },
        progress = { it = "Il tomo del santuario è un oggetto misterioso. Non è un libro nel senso comune. I fogli del tomo furono benedetti da Mel'Thandris in persona, e nelle sue pagine registra gli eventi importanti.\n\nPer me è difficile da spiegare. Se vai al santuario, capirai.", enHash = "a00fe2c5", vanilla = true },
        reward = { it = "Il Tome of Mel'Thandris funziona in modi strani. Gli eventi che registra, gli eventi che mostra... Nessuno capisce davvero perché faccia quello che fa.\n\nResta però chiaro che ciò che ha ricevuto Priestess Starsong — questa Scythe of Elune — merita altre indagini.", enHash = "9dd79a10", vanilla = true },
    },
    [1023] = {
        title = { it = "La purificazione di Raene", enHash = "4a88f731", vanilla = true },
        text = { it = "Mentre frughi tra le cose di Teronis, trovi un diario ancora in buone condizioni.\n\nPrendi il diario e lasci il corpo di Teronis com'è.\n\nNon resta che trovare la gemma che Teronis stava cercando. Raene ha detto che si trova in zona. Forse ce l'hanno i murloc...", enHash = "441de319", vanilla = true },
        objectives = { it = "Trova la Glowing Gem e torna da Raene Wolfrunner ad Astranaar con Teronis' Journal.", enHash = "f2453bab", vanilla = true },
        progress = { it = "Ah, $Gbentornato:bentornata;, $N.", enHash = "cf8cb870", vanilla = true },
        reward = { it = "È terribile, $N. Teronis è morto?!\n\nVerrà il tempo del lutto, ma per ora dobbiamo concentrare i nostri sforzi. Manderò alcune Sentinelle a recuperare il corpo di Teronis appena possibile.\n\nHai il diario di Teronis e la gemma che stava cercando. Pensi di essere in grado di portare a termine il suo compito? Dormirei molto più tranquilla sapendo che la sua morte non è stata vana.", enHash = "d86bb3ec", vanilla = true },
    },
    [1024] = {
        title = { it = "La purificazione di Raene", enHash = "4a88f731", vanilla = true },
        text = { it = "La ricerca dovrai farla da $Gsolo:sola;, ma da quel che ha annotato Teronis sembra che il prossimo passo sia trovare gli altri pezzi della verga creata da Dartol. Io comincerei andando al pozzo lunare a est dell'Iris Lake. Quando sei $Gpronto:pronta;, segui la strada e gira a nord quando arrivi a una piccola area di sosta sulla sinistra.\n\nLì c'è una driade di nome Shael'dryn, più adatta di me a guidarti. Cercala.\n\nTieni la gemma con te — a Shael'dryn servirà, se deve aiutarti a ricreare la verga.", enHash = "8fdd273b", vanilla = true },
        objectives = { it = "Trova Shael'dryn al pozzo lunare a nord-est.", enHash = "6ec1bcc9", vanilla = true },
        progress = { it = "Salve. Come stai?", enHash = "078aec20", vanilla = true },
        reward = { it = "Oh, ti manda Raene? Allora dev'essere davvero grave. In cosa posso aiutarti?", enHash = "ebc8fac6", vanilla = true },
    },
    [1025] = {
        title = { it = "Una difesa aggressiva", enHash = "f0dc1cf7", vanilla = true },
        text = { it = "Prima che tu vada al pozzo lunare ho un altro incarico che aiuterà la gente di Ashenvale, se vuoi metterti alla prova.\n\nLungo la strada che va a est, prima del Falfarren River, i furbolg attaccano i viaggiatori. Le loro menti torturate si nutrono di paura e la loro fame si sazia del sangue degli innocenti.\n\nAiuta le Sentinelle a proteggere queste terre mostrando a quei mostri la stessa pietà che hanno mostrato alla nostra gente.\n\nCredo che i loro accampamenti siano a sud della strada... sta' $Gattento:attenta;.", enHash = "8c643182", vanilla = true },
        objectives = { it = "Uccidi 1 Den Watcher, 2 Ursa, 10 Totemic e 12 Warrior della tribù Foulweald, poi torna da Raene Wolfrunner ad Astranaar.", enHash = "4b5b55bf", vanilla = true },
        progress = { it = "I furbolg non sono sempre stati nostri nemici, $N. Ma i tempi cambiano, e questo non è più un tempo di pace in questi boschi oscuri.", enHash = "08bf0fe9", vanilla = true },
        reward = { it = "Hai fatto un buon lavoro, $N. Grazie.", enHash = "456834ea", vanilla = true },
    },
    [1026] = {
        title = { it = "La purificazione di Raene", enHash = "4a88f731", vanilla = true },
        text = { it = "Vorrei che le tue notizie fossero migliori.\n\nRaene ha ragione: conosco la creazione di Dartol e i treant della zona — o almeno li conoscevo. Ora sono stati corrotti, la loro natura è stata stravolta.\n\nSe il tuo scopo è trovare il prossimo pezzo della verga, dovrai trovare la chiave per aprire la cassa in cui si trova.\n\nLa chiave di legno è addosso a uno dei treant a nord-est di qui, vicino a Felwood. Quando ce l'hai, cerca una piccola radura a ovest della strada, vicino al confine di Felwood... la cassa dovrebbe essere nascosta da quelle parti.", enHash = "a9c098e4", vanilla = true },
        objectives = { it = "Trova la Wooden Key e un pezzo di Dartol's Rod prima di tornare da Shael'dryn, al pozzo lunare.", enHash = "c33cc8df", vanilla = true },
        progress = { it = "Mi addolora tanto che i treant siano stati corrotti. Vorrei poter fare di più per aiutarli.", enHash = "af66b50e", vanilla = true },
        reward = { it = "Sono contenta di vederti di ritorno, $N.", enHash = "311727df", vanilla = true },
    },
    [1027] = {
        title = { it = "La purificazione di Raene", enHash = "4a88f731", vanilla = true },
        text = { it = "L'ultimo pezzo della verga fu affidato ai druidi di Dor'danil perché lo custodissero. Non ho idea di dove l'abbiano nascosto. Mi dispiace, non posso aiutarti oltre.\n\nPosso solo dirti di seguire la strada che porta verso le Barrens. I druidi si erano rifugiati a est di quella strada, ma non ti saranno di grande aiuto: sono stati uccisi di recente... è una cosa a cui non mi piace pensare troppo.\n\nQuando trovi l'ultimo pezzo, portamelo e ti aiuterò a ricostruire la verga.", enHash = "7f4d9e15", vanilla = true },
        objectives = { it = "Trova l'ultimo pezzo di Dartol's Rod e torna da Shael'dryn, al pozzo lunare.", enHash = "64464014", vanilla = true },
        progress = { it = "Hai trovato l'ultimo pezzo della verga, $N?", enHash = "39037fc2", vanilla = true },
        reward = { it = "Hai trovato l'ultimo pezzo? Che meraviglia per te... e per Raene.\n\nA questo punto dovremo pensare a ripararla, no?", enHash = "2d5be9d0", vanilla = true },
    },
    [1028] = {
        title = { it = "La purificazione di Raene", enHash = "4a88f731", vanilla = true },
        text = { it = "Ecco la verga completa, $N. Ricostruirla è stato semplice... la parte difficile sarà trovare il santuario che ha il potere di ricaricarla.\n\nCon un po' di concentrazione e di impegno non dovrebbe essere troppo difficile per qualcuno come te, che ha già fatto tanto.\n\nVa' a sud-est di qui — i sentieri sono pochissimi, quindi fa' attenzione — e tieni gli occhi verso nord. Il santuario è nascosto tra le montagne che circondano questa radura.\n\nUna volta lì, posa la verga nel santuario... il resto è magia. Eheh.", enHash = "6c7f920b", vanilla = true },
        objectives = { it = "Trova il santuario nascosto e incanta di nuovo Dartol's Rod.", enHash = "12c6c104", vanilla = true },
        progress = { it = "Percepisci una forza sottile ma potente nel santuario e negli alberi intorno.\n\nCominci a posare la verga nel santuario e intorno a te si leva un lieve ronzio mentre il santuario inizia a brillare...", enHash = "afa968ab", vanilla = true },
        reward = { it = "Quando il bagliore si spegne, vedi la verga di nuovo incantata nella conca del santuario.", enHash = "672eafe9", vanilla = true },
    },
    [1029] = {
        title = { it = "La purificazione di Raene", enHash = "4a88f731", vanilla = true },
        text = { it = "Ti consiglio di cercare Raene e di farle sapere che la verga è pronta. Sono sicura che saprà dirti qual è il prossimo passo.\n\nBuona fortuna, $N.", enHash = "bb6e4f0d", vanilla = true },
        objectives = { it = "Torna da Raene Wolfrunner, ad Astranaar.", enHash = "1cda53fe", vanilla = true },
        reward = { it = "Hai ricreato la verga che Teronis era partito a cercare? È una notizia meravigliosa.\n\nTeronis sarebbe fiero di vedere che la sua impresa continua anche dopo la sua tragica fine.", enHash = "4327d9c9", vanilla = true },
    },
    [1030] = {
        title = { it = "La purificazione di Raene", enHash = "4a88f731", vanilla = true },
        text = { it = "Ahimè, non sono del tutto sicura di cosa avesse in mente dopo.\n\nSe quel che diceva sul potere della verga è vero, allora ti permetterà di assumere tutt'altra forma. Quale forma, non lo so.\n\nForse voleva usarne i poteri per avvicinarsi ai furbolg corrotti, ma anche le creature non corrotte lo avrebbero fatto a pezzi, se non fosse stato prudente. Trasformato dalla verga, Dartol avrebbe dovuto parlare con un furbolg al riparo dagli effetti del Fel Moss.\n\nIo comincerei la ricerca a sud-est del Mystral Lake.", enHash = "f081f7d9", vanilla = true },
        objectives = { it = "Trova un furbolg non corrotto e, usando il potere di Dartol's Rod of Transformation, parlagli.", enHash = "b1b07d70", vanilla = true },
        reward = { it = "Sì, sì... sei $Guno:una; dei miei, ma ancora $Gintegro:integra;. Ancora $Gpuro:pura;.\n\nNon so come tu sia $Gsfuggito:sfuggita; alle atrocità che gli elfi della notte hanno inflitto alla nostra gente, ma sono lieto di sapere che non sono più solo.\n\nLa corruzione scorre ormai nelle vene dei nostri simili, giovane, una corruzione che ci hanno portato addosso gli orgogliosi elfi della notte. Sono loro ad aver fatto questo alla nostra gente... Sono loro che incolpo per essere stato cacciato dalla mia tribù.\n\nDi notte vedo ancora i fuochi da campo ardere nel buio.", enHash = "66988422", vanilla = true },
    },
    [1031] = {
        title = { it = "Il Branch of Cenarius", enHash = "d8461ce4", vanilla = true },
        text = { it = "Anilia ti posa le mani sulle spalle e ti attira a sé. Ansimando, indica l'arco a nord, prima che i suoi occhi si chiudano e l'ultimo respiro affannoso le lasci il corpo. \"L'ha preso lui... Geltharis...\" Senti nel cuore che l'ultimo desiderio di Anilia è rivedere il Branch of Cenarius nelle mani delle driadi.", enHash = "b0747eae", vanilla = true },
        objectives = { it = "Uccidi Geltharis e riporta il Branch of Cenarius a Illiyana, allo Shrine of Aessina.", enHash = "4532e5e4", vanilla = true },
        progress = { it = "Le hai trovate? Cos'ha detto Anilia? Dov'è?", enHash = "86ff4caf", vanilla = true },
        reward = { it = "Anilia è morta? No... non può essere! Era solo ieri che correvamo e giocavamo insieme nei boschi.\n\nImmagino che quei giorni siano finiti...", enHash = "89d06652", vanilla = true },
    },
    [1032] = {
        title = { it = "Strage di satiri!", enHash = "abc971d1", vanilla = true },
        text = { it = "Non riesco a credere che Anilia non ci sia più... Giocavamo sempre insieme nelle foreste. Mi sento quasi... triste.\n\nSo una cosa che potrebbe farmi stare meglio. Ti prego, uccidi i satiri che mi hanno portato via Anilia! Portami le loro corna come prova di quel che hai fatto e avrai per sempre la mia gratitudine.", enHash = "a5e986d6", vanilla = true },
        objectives = { it = "Porta 16 Satyr Horn a Illiyana, allo Shrine of Aessina.", enHash = "a0c6216e", vanilla = true },
        progress = { it = "Ti prego, aiutami a vendicare la morte di Anilia.", enHash = "4a536a29", vanilla = true },
        reward = { it = "Grazie, gentile $R. Lo spirito di mia sorella è confortato da quel che hai fatto.", enHash = "635605f9", vanilla = true },
    },
    [1033] = {
        title = { it = "Elune's Tear", enHash = "05aa4a51", vanilla = true },
        text = { it = "Speravo che la cura di Orendil salvasse Relara, ma temo che abbia solo rallentato il male che scorre in mia figlia. Dobbiamo trovare una medicina più potente! Per fortuna Orendil mi ha parlato di altri rimedi da provare, nel caso il primo fallisse.\n\nElune's Tear è un tipo di pietra che si trova in un solo posto: l'isola sull'Iris Lake, a est di Astranaar. Orendil ha detto che la pietra lava via la corruzione... ti prego, $N, portami Elune's Tear e prega che ponga fine alla malattia di mia figlia!", enHash = "1492aa37", vanilla = true },
        objectives = { it = "Porta Elune's Tear a Pelturas ad Astranaar.", enHash = "4079ee84", vanilla = true },
        progress = { it = "$N, hai trovato l'Iris Lake? Hai la Tear?", enHash = "756e8722", vanilla = true },
        reward = { it = "Oh, l'hai trovata! Metterò la lacrima in uno stufato e pregherò che la guarisca.\n\nGrazie! Grazie, $N!", enHash = "bb026ed9", vanilla = true },
    },
    [1034] = {
        title = { it = "Le Ruins of Stardust", enHash = "479e7869", vanilla = true },
        text = { it = "Elune's Tear ha lavato via una parte del male di mia figlia. I suoi incubi si sono attenuati e ringrazio la dea per la sua benedizione. Ma... la febbre infuria ancora dentro di lei.\n\nOrendil mi ha parlato di una polvere gelida che si trova tra le Ruins of Stardust. Forse placherà la febbre di Relara. Raccogline un po', poi torna da me, ti prego.\n\nLe Ruins of Stardust si trovano a sud, $N. Che Elune renda veloce il tuo viaggio.", enHash = "6d69a3e1", vanilla = true },
        objectives = { it = "Porta 5 Handful of Stardust a Pelturas ad Astranaar.", enHash = "09cb22d0", vanilla = true },
        progress = { it = "Hai già la Stardust, $N?", enHash = "50f57e24", vanilla = true },
        reward = { it = "Hai raccolto la polvere! Ne farò un impiastro — dovrebbe far scendere la febbre di Relara.\n\nGrazie ancora, $N. Senza il tuo aiuto mia figlia morirebbe di sicuro.", enHash = "df6b8477", vanilla = true },
    },
    [1035] = {
        title = { it = "Il Fallen Sky Lake", enHash = "15d7106a", vanilla = true },
        text = { it = "La febbre di Relara è passata, ma è ancora molto debole. Non credo che il tempo da solo le restituirà le forze che ha perso. Credo che serva il potere di una pietra di luna.\n\nUn tempo raccoglievamo pietre di luna al Fallen Sky Lake, a sud-est... finché non sono arrivati gli Shadethicket.\n\nIl loro capo, uno Shadethicket Oracle, ha raccolto tutte le Fallen Moonstone e se le tiene. Ora devi recuperarne una dall'Oracle.\n\nE per farlo, temo che dovrai ucciderlo.", enHash = "f165a9b5", vanilla = true },
        objectives = { it = "Recupera una Fallen Moonstone dallo Shadethicket Oracle, poi portala a Pelturas ad Astranaar.", enHash = "f3c574de", vanilla = true },
        progress = { it = "Hai affrontato lo Shadethicket Oracle, $N? Se sì, dammi la Fallen Moonstone, ti prego. A Relara restano le forze per pochi respiri!", enHash = "d786eb92", vanilla = true },
        reward = { it = "Oh, $N, hai salvato mia figlia! So che il potere della pietra di luna le ridarà le forze!\n\nNon potrò mai ripagarti del tutto per l'aiuto che mi hai dato, ma... ti prego, prendi questo. A parte Relara, è la cosa più cara che ho.", enHash = "2427926a", vanilla = true },
    },
    [1036] = {
        title = { it = "Alt là, canaglia", enHash = "d6dc5a62", vanilla = true },
        text = { it = "$N... sì, ho sentito parlare di te. Ho sentito che non sei $Gamico:amica; di Booty Bay, proprio come noi Bloodsail Buccaneers. Fleet Master Firallon cerca $Guomini:donne; forti e $Gvigorosi:vigorose; proprio come te per una missione speciale.\n\nSe ti interessa, va' alla Crimson Veil e parlagli sottocoperta. È ancorata al largo della Wild Shore, a est di qui, accanto alla Riptide e alla Damsel's Luck.", enHash = { "5f267fa0", "5a5dd708" }, vanilla = true },
        objectives = { it = "Parla con Fleet Master Firallon a bordo della Crimson Veil, al largo della costa di Stranglethorn Vale.", enHash = "41d531a0", vanilla = true },
        reward = { it = "Alt là, canaglia. Mi dicono che sei il tipo da qualche losco affare. Be', se non sei $Gamico:amica; di Booty Bay, allora potresti avere un posto speciale tra i Bloodsail Buccaneers.\n\nArrrrr...", enHash = "652c9538", vanilla = true },
    },
    [1037] = {
        title = { it = "Velinde Starsong", enHash = "39cad064", vanilla = true },
        text = { it = "Velinde Starsong era la mia predecessora qui nell'Ashenvale Forest. All'inizio sembrava che avesse la situazione del Felwood sotto controllo, ma a poco a poco i suoi sforzi si sono indeboliti. Un giorno è semplicemente sparita.\n\nMi hanno mandata qui a continuare il suo lavoro. Temo però di non sapere nulla della sacerdotessa. Forse Thyn'tel Bladeweaver, una delle comandanti delle Sentinelle, conosce altri dettagli sulla sua scomparsa che a me non sono stati riferiti.\n\nDi sicuro capirà l'importanza di simili informazioni.", enHash = "ffb2d07e", vanilla = true },
        objectives = { it = "Parla con Thyn'tel Bladeweaver, alla Warrior's Terrace di Darnassus.", enHash = "0f28836d", vanilla = true },
        reward = { it = "Velinde Starsong? Che la sacerdotessa sia sparita tempo fa è quasi di sicuro cosa risaputa. Quanto ad altri dettagli sugli eventi attorno alla sua partenza... mi servirebbe una buona ragione per divulgare simili informazioni.", enHash = "5308855d", vanilla = true },
    },
    [1038] = {
        title = { it = "Gli effetti personali di Velinde", enHash = "56117bd1", vanilla = true },
        text = { it = "Il Tome of Mel'Thandris ti ha mostrato questo? Immagino non ci sia gran male a lasciarti esaminare le sue cose. Questa chiave ti permetterà di aprire la cassa in cui abbiamo riposto la sua roba, nella camerata delle Sentinelle. Teneva un diario dei suoi incarichi: se c'è qualcosa da scoprire, verrà da lì.\n\nDevo dirti che le Sentinelle credono che avesse le sue ragioni per andarsene, e si aspettano che possa tornare da un momento all'altro. In passato la sacerdotessa ha fatto molto per guadagnarsi la nostra fiducia.", enHash = "f20f5bf0", vanilla = true },
        objectives = { it = "Cerca il diario nella cassa di Velinde, poi riportalo insieme alla chiave a Thyn'tel Bladeweaver, a Darnassus.", enHash = "29bd49a8", vanilla = true },
        progress = { it = "Cos'hai scoperto?", enHash = "b22aa2f8", vanilla = true },
        reward = { it = "Sembra che la scomparsa di Velinde sia più inquietante di quanto sembrasse all'inizio. Eppure non riesco a credere che abbia fatto una brutta fine. Forse ci gioverebbe metterci in contatto con lei.\n\n$N, visto che hai dimostrato un interesse personale in questa faccenda, vorrei chiedere il tuo aiuto.", enHash = "8bb4305f", vanilla = true },
    },
    [1039] = {
        title = { it = "Il porto delle Barrens", enHash = "4cece905", vanilla = true },
        text = { it = "Ratchet è l'unico porto delle Barrens. Con ogni probabilità Velinde ha trovato a Ratchet una nave mercantile che la portasse a Blackwater Cove, ad Azeroth. Abbiamo pochi rapporti con i goblin che gestiscono il porto, ma il padrone del molo dovrebbe avere informazioni sull'andirivieni dei passeggeri.\n\nSegui la strada a sud-est attraverso Ashenvale e ti ritroverai nelle Barrens. Guarda dove metti i piedi, $N: guerrieri dell'Orda pattugliano quelle terre. Al porto, però, sarai al sicuro.", enHash = "b9dfd221", vanilla = true },
        objectives = { it = "Parla con Wharfmaster Dizzywig, a Ratchet.", enHash = "472b8e77", vanilla = true },
        reward = { it = "$R, eh? Devo ammettere che da queste parti non ne capitano molti come te. Cerchi qualcuno, eh? Dammi solo un momento, sono sicuro di averlo scritto in uno dei miei registri.\n\nDi gente però ne passa parecchia, quindi dammi un attimo.", enHash = "d710b117", vanilla = true },
    },
    [1040] = {
        title = { it = "Passaggio per Booty Bay", enHash = "78ccd46e", vanilla = true },
        text = { it = "Ah, sì, finalmente l'ho trovato. Dovevi dirmi che era passata di qui così tanto tempo fa. Vediamo.\n\nVelinde. Ha prenotato un passaggio per Booty Bay sulla Black Osprey. Qui non c'è scritto niente in contrario, quindi direi che sia arrivata in porto senza problemi.\n\nOltre a questo non posso esserti di grande aiuto, ma mi ha chiesto dei viaggi via terra dall'altra parte del mondo, e le ho parlato di Ruzzgot, un carovaniere che sta a Booty Bay. Può darsi che questa Velinde abbia viaggiato con lui.\n\nOra circola. Non ho tutto il giorno per te.", enHash = "67355fa5", vanilla = true },
        objectives = { it = "Prendi una nave per Booty Bay e parla con Caravaneer Ruzzgot.", enHash = "5517e782", vanilla = true },
        reward = { it = "Sì? Be', non mi sembri il tipo con merce da spedire, quindi o cerchi lavoro con la mia carovana — e di lavoro adesso non ce n'è — o probabilmente stai parlando con il goblin sbagliato.\n\nAllora, quale delle due?", enHash = "a0c0ba8a", vanilla = true },
    },
    [1041] = {
        title = { it = "La strada della carovana", enHash = "a9ced359", vanilla = true },
        text = { it = "A quanto pare su di te mi sbagliavo, e non è una cosa che capiti tutti i giorni.\n\nGuarda caso mi ricordo di questa Velinde che cerchi. Non capita tutti i giorni che una sacerdotessa elfa della notte voglia viaggiare con una carovana vecchia e sporca — ma perfetta per le tue spedizioni! — come la mia.\n\nCi siamo separati lungo la strada verso nord, lei era diretta a Darkshire. Il cancelliere di là tiene registri di ogni genere. Potrebbe sapere qualcosa di utile.\n\nFa' attenzione nella giungla: è un posto letale anche nei periodi migliori.", enHash = "dd4552bd", vanilla = true },
        objectives = { it = "Parla con Clerk Daltry, a Darkshire.", enHash = "0dd69cdb", vanilla = true },
        reward = { it = "Con tutte le stranezze degli ultimi anni, tengo i registri degli stranieri più accurati che posso. Non si sa mai quando possano tornare utili... anche se di solito, quando succede, non è per faccende piacevoli. Non che voglia insinuare nulla su questa Velinde che cerchi.", enHash = "cfc44052", vanilla = true },
    },
    [1042] = {
        title = { it = "La famiglia Carevin", enHash = "51e3c869", vanilla = true },
        text = { it = "No, non ho alcuna traccia di una Velinde Starsong che abbia soggiornato a Darkshire... anche se, se posso permettermi, faccio fatica a immaginare una sacerdotessa elfa della notte che prende una stanza alla locanda, mi spiego?\n\nQuesti uomini-lupo di cui parli, però, ne ho sentito parlare. Proprio l'altro giorno Calor è arrivato in città con una fila delle loro teste. Lavora con la famiglia Carevin. Cacciatori di demoni, non morti e altre mostruosità. Parla con Jonathan, è lui il capofamiglia.", enHash = "b8073b0c", vanilla = true },
        objectives = { it = "Parla con Jonathan Carevin, a Darkshire.", enHash = "fc602d87", vanilla = true },
        reward = { it = "Sono tempi oscuri. Brutte notizie si sussurrano da ogni ramo che oscilla, e il male si trova sotto ogni pietra.\n\nE in tempi simili $Guno sconosciuto:una sconosciuta; entra in casa mia e chiede dei worgen... Non chiederò scusa per i miei sospetti, voglio solo risposte.\n\nE risposte avrò.", enHash = "b843c0bb", vanilla = true },
    },
    [1043] = {
        title = { it = "La Scythe of Elune", enHash = "c1a69725", vanilla = true },
        text = { it = "La tua storia suona vera... Non capisco del tutto le tue ragioni, ma se quel che hai da fare qui a Duskwood comporta liberare la foresta da un certo numero di worgen, allora posso rinunciare a capire in cambio di risultati.\n\nA sud c'è una miniera invasa dai worgen... Sono comparsi dal nulla, ma da quel che sappiamo è lì che sono stati visti per la prima volta.\n\nFa' quel che devi, ma ti chiedo che, se trovi qualcosa di importante, tu lo condivida con me. Accetteremo qualsiasi aiuto nella nostra guerra contro il male.", enHash = "8daa19d2", vanilla = true },
        objectives = { it = "Cerca tracce della Scythe of Elune, poi torna da Jonathan Carevin, a Darkshire.", enHash = "e7b7ab51", vanilla = true },
        progress = { it = "I boschi sono pericolosi per chi non è preparato. Tieni le armi a portata di mano e l'ingegno ancora più vicino, o il tuo prossimo viaggio nella foresta infestata potrebbe essere l'ultimo.", enHash = "d4a722d1", vanilla = true },
        reward = { it = "È una storia interessante quella che racconti, $N. Anche se l'influenza della famiglia Carevin non è tale da permetterci di trovare la radice di questi guai e di porvi fine una volta per tutte, faremo il possibile per contenere il numero dei worgen a Duskwood.\n\nHo già ordinato a Calor di farne la sua prima priorità.", enHash = "70cd315e", vanilla = true },
    },
    [1044] = {
        title = { it = "Domande con risposta", enHash = "e20209ca", vanilla = true },
        text = { it = "Terremo a freno il problema dei worgen, non preoccuparti. Questo male che la tua amica ha portato nei nostri boschi verrà contenuto, e non le porto rancore per quel che ha fatto. In questi tempi accadono cose strane, $N, e l'oscurità non conosce tregua.\n\nNon ti tratterrò oltre. Immagino che ci siano altri che dovrebbero sapere quel che hai trovato nelle miniere di Duskwood.", enHash = "240bb16f", vanilla = true },
        objectives = { it = "Torna da Thyn'tel Bladeweaver, a Darnassus.", enHash = "100f823d", vanilla = true },
        reward = { it = "Dunque questo è il destino di Velinde? La somma sacerdotessa sarà delusa nel saperlo: erano buone amiche prima della sua scomparsa. Eppure la Scythe of Elune le fu certo concessa in dono dalla nostra dea, e mi inquieta che sia sfuggita dalle mani delle sue serve.\n\nMa questa è un'altra faccenda, per un'altra volta. Ti devo un ringraziamento non da poco per quel che hai fatto.", enHash = "7e583b33", vanilla = true },
    },
    [1045] = {
        title = { it = "La purificazione di Raene", enHash = "4a88f731", vanilla = true },
        text = { it = "Gli elfi della notte sono antichi come il tempo, ma la loro arroganza distrugge il loro stesso mondo. E ora distrugge anche le nostre vite. Ma ormai non si può più controllare...\n\nDo la colpa agli elfi per molte cose, ma restiamo comunque responsabili delle nostre azioni. Anche al di là della corruzione, siamo capaci di grande male.\n\nRan Bloodtooth è uno di questi mali. Avido di potere, bramoso... la corruzione lo ha solo reso più forte. Il mio odio per gli elfi brucia, ma non auguro il male ai loro figli, quindi dobbiamo fare ordine tra i nostri.", enHash = "7cb66561", vanilla = true },
        objectives = { it = "Uccidi Ran Bloodtooth e 4 Bloodtooth Guard, poi torna da Krolg, vicino al Lake Mystral.", enHash = "3f7f3f96", vanilla = true },
        progress = { it = "Hai già ucciso Ran, $Gamico mio:amica mia;?\n\nPersino gli elfi della notte non meritano davvero la sua ira. Il suo odio brucia ancora più del mio, ma la sua mente non gli appartiene più. È una minaccia per tutte le creature naturali di questa foresta.", enHash = "dbba7345", vanilla = true },
        reward = { it = "Hai fatto bene, $Gamico mio:amica mia;.\n\nLa foresta è ancora corrotta, ma almeno sappiamo di aver fatto la nostra piccola parte per riportarla all'antica gloria. Se vorrai tornare da me, mi farebbe piacere la compagnia di uno dei miei.\n\nStammi bene. Forse le nostre tribù si incontreranno di nuovo in tempi meno violenti.", enHash = "836d0aed", vanilla = true },
    },
    [1046] = {
        title = { it = "La purificazione di Raene", enHash = "4a88f731", vanilla = true },
        text = { it = "Torna dalla tua tribù e falle sapere della tua vittoria qui.\n\nMostra loro il tuo trofeo, e crogiolati nella gloria...", enHash = "db4bed0e", vanilla = true },
        objectives = { it = "Porta Ran Bloodtooth's Skull e Dartol's Rod of Transformation a Raene Wolfrunner, ad Astranaar.", enHash = "9485ad32", vanilla = true },
        progress = { it = "Le Sentinelle fanno quel che possono qui ad Ashenvale, ma è grazie a gente come te se abbiamo guadagnato il terreno che abbiamo.", enHash = "8cb130b9", vanilla = true },
        reward = { it = "Dunque questo è il teschio della più feroce minaccia furbolg di Ashenvale?\n\nSono più che soddisfatta delle tue capacità, $N. Le Sentinelle non potranno mai ringraziarti abbastanza. Spero che in futuro potremo contare ancora su di te per aiutare la nostra gente.\n\nMetterò questo teschio e Dartol's Rod in un luogo d'onore, perché tutti li vedano.\n\nTeronis ne sarebbe fiero. Grazie ancora.", enHash = "a4a8871b", vanilla = true },
    },
    [1048] = {
        title = { it = "Nello Scarlet Monastery", enHash = "95e3a561", vanilla = true },
        text = { it = "Mentre la Signora Oscura si occupa della pressante questione dell'avanzata del Re dei Lich a nord, io faccio in modo che le faccende più vicine a casa vengano sistemate come si deve.\n\nNon c'è dubbio che i parassiti umani che si fanno chiamare Crociata Scarlatta si stiano rivelando la spina più dolorosa nel nostro fianco, qui in patria. Le Tirisfal Glades brulicano letteralmente di quelle piccole formiche rosse.\n\nVa' al Monastery, $C, e annienta High Inquisitor Whitemane e i suoi luogotenenti più alti in grado.", enHash = "7b97844c", vanilla = true },
        objectives = { it = "Uccidi High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion e Houndmaster Loksey, poi torna a riferire a Varimathras, nell'Undercity.", enHash = "1db6432a", vanilla = true },
        progress = { it = "Forse non sono stato abbastanza esplicito nei miei ordini, $C. Voglio High Inquisitor Whitemane morta, una volta per tutte. E già che ci sei, elimina anche i suoi pezzi grossi.\n\nUccidi quel fanatico, Scarlet Commander Mograine. Annienta Herod, the Scarlet Champion. E massacra Houndmaster Loksey, e anche i suoi luridi cagnacci.\n\nOra vattene!", enHash = "b9ef9a08", vanilla = true },
        reward = { it = "Hai servito bene la Signora Oscura, $C. Non era cosa da poco, quello che ti ho chiesto.\n\nLa tua lealtà verso i Reietti è stata notata. E la tua tenacia in combattimento sarà ricordata.", enHash = "e49df179", vanilla = true },
    },
    [1049] = {
        title = { it = "Compendium of the Fallen", enHash = "f1f7d6d1", vanilla = true },
        text = { it = "Il Circolo della Terra aveva intenzioni pure nei confronti dei nostri fratelli appestati. Ma chi può conoscere le motivazioni di chi sussurra all'orecchio dell'Elder Council?\n\nI Reietti con cui ci siamo alleati hanno un passato intriso di inganni. Il nostro patto è stato troppo frettoloso. Forse Cairne avrebbe fatto bene a dare ascolto agli avvertimenti di Orgrimmar.\n\nNel profondo dello Scarlet Monastery si trova il Compendium of the Fallen, sorvegliato da folli fanatici umani. Il loro metodo nasce dalla follia, ma le loro ricerche potrebbero rivelarsi utili.", enHash = "1bc8e227", vanilla = true },
        objectives = { it = "Recupera il Compendium of the Fallen dal Monastery nelle Tirisfal Glades e torna da Sage Truthseeker, a Thunder Bluff.", enHash = "dc306d50", vanilla = true },
        progress = { it = "Cairne è un capo coraggioso e nobile, e gli affiderei la mia stessa vita. Ma in questo clima politico sono altri quelli di cui non mi fido.\n\nQuando avrò modo di raccogliere tutte le conoscenze disponibili, potrò dare consigli solidi al capotribù.\n\nHai avuto modo di andare nelle Tirisfal Glades? Allo Scarlet Monastery? Il Compendium of the Fallen è solo un pezzo di questo complicato rompicapo...", enHash = "c0f1edfc", vanilla = true },
        reward = { it = "Il Compendium of the Fallen! Cominciavo a chiedermi se quel libro esistesse davvero!\n\nHai servito bene i tauren di Thunder Bluff, $N. La tua dedizione non sarà dimenticata.", enHash = "de110872", vanilla = true },
    },
    [1050] = {
        title = { it = "Mythology of the Titans", enHash = "ef640bc3", vanilla = true },
        text = { it = "Il futuro è inevitabile! Ci gettiamo verso di esso come gocce di pioggia che cadono nel Great Sea.\n\nMa forse, studiando il passato, possiamo sapere cosa aspettarci ed essere più preparati all'ignoto.\n\nPrima che terribili sventure si abbattessero su Lordaeron, c'era un bastione del sapere nascosto nelle Tirisfal Glades. Si dice che un libro intitolato Mythology of the Titans fosse custodito nella biblioteca del vecchio Monastery.\n\nPortamelo, e forse insieme potremo svelare i segreti del passato!", enHash = "e22484cc", vanilla = true },
        objectives = { it = "Recupera Mythology of the Titans dal Monastery e portalo a Librarian Mae Paledust, a Ironforge.", enHash = "f44b9272", vanilla = true },
        progress = { it = "Il Monastery era un seminario per paladini in addestramento. Un tempo roccaforte della Luce, è caduto nelle mani dei folli fanatici della Crociata Scarlatta.\n\nLa Crociata riteneva nobile il proprio scopo: purificare la terra dalla piaga dei non morti. Ma la follia ha corrotto la sua missione, e ora è nemica di tutti.\n\nPortami Mythology of the Titans, così potrò studiarlo e custodirlo qui a Ironforge.\n\nLe sale corrotte del Monastery non sono il posto per un tesoro storico simile.", enHash = "e463abe9", vanilla = true },
        reward = { it = "Hai salvato il testo sacro!\n\nIl tuo viaggio è stato lungo e recuperare il libro non è stato certo un compito facile. Ma i nani di Ironforge trarranno beneficio dal tuo successo.\n\nGrazie, $N, a nome della Lega degli Esploratori.", enHash = "2fda8cc7", vanilla = true },
    },
    [1051] = {
        title = { it = "La vendetta di Vorrel", enHash = "a3afa496", vanilla = true },
        text = { it = "Anche se la mia volontà è libera, non posso più servire la Signora Oscura. Sento che il mio tempo su Azeroth è giunto alla fine. La mia forza vitale è distrutta.\n\nÈ stato Interrogator Vishas a ridurmi così! Mi ha torturato per settimane! Mi ha preso la fede nuziale e l'ha data a sua moglie. Quel bastardo!\n\nVendetta... voglio vendetta!\n\nQuello stolto pieno di sé si vantava della sua preziosa moglie, Nancy, che viveva sulle rive del Lake Lordamere. Trova quella donnaccia, uccidila e riporta la mia fede nuziale a mia moglie, Monika, a Tarren Mill.\n\nRispetta le mie ultime volontà...", enHash = "a3348145", vanilla = true },
        objectives = { it = "Riporta la fede nuziale di Vorrel Sengutz a Monika Sengutz, a Tarren Mill.", enHash = "c90678bb", vanilla = true },
        progress = { it = "Cosa vuoi, $Gstraniero:straniera;?", enHash = "c400b74b", vanilla = true },
        reward = { it = "Vorrel ha avuto un'esistenza così travagliata. E che buon compagno era...\n\nMaledetti quei luridi umani!\n\nVorrel non c'è più, e non godrà mai più della non morte. Almeno posso trovare conforto nella vendetta che hai compiuto in suo nome. Per questo ti ringrazio.\n\nOra lasciami al mio lutto...", enHash = "40b031b3", vanilla = true },
    },
    [1052] = {
        title = { it = "Lungo il sentiero scarlatto", enHash = "3e70c398", vanilla = true },
        text = { it = "Noi della Crociata Scarlatta rivendichiamo roccaforti da Hearthglen fino alle Tirisfal Glades. Siamo molto fieri dei nostri bastioni di purificazione in tutta Lordaeron.\n\nHai dimostrato il tuo valore contro i non morti di Desolace. Ma la vera minaccia della piaga si trova a Lordaeron.\n\nVa' nella cittadina di Southshore, negli Eastern Kingdoms. Cerca un crociato di nome Raleigh the Devout. Dagli questa Letter of Commendation con il mio sigillo e ti accompagnerà a un posto d'onore nel nostro Scarlet Monastery.", enHash = "efeb2eba", vanilla = true },
        objectives = { it = "Porta la Letter of Commendation di Brother Anton a Raleigh the Devout, a Southshore.", enHash = "50bc842c", vanilla = true },
        progress = { it = "Chi va là? Che cosa vuoi da me?", enHash = "ff44106a", vanilla = true },
        reward = { it = "Brother Anton diffonde ancora la parola della Crociata Scarlatta? Oh, cielo...", enHash = "78861526", vanilla = true },
    },
    [1053] = {
        title = { it = "Nel nome della Luce", enHash = "95224269", vanilla = true },
        text = { it = "Un tempo servivo la Crociata Scarlatta con onore, lealtà e orgoglio. Credevo che la sua causa fosse nobile: liberare Azeroth dai non morti.\n\nMa durante il tempo che ho passato al Monastery, nelle Tirisfal Glades, mi sono reso conto che stavano perdendo il contatto con la realtà. Ora pensano che chiunque non indossi il tabarro della Crociata sia appestato. Uomini e donne innocenti sono stati torturati perché, a quanto si diceva, erano appestati.\n\nLa Crociata Scarlatta deve essere schiacciata nel nome della Luce. Tu, $N, devi distruggere questo regime folle.", enHash = "b1c73bee", vanilla = true },
        objectives = { it = "Uccidi High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion e Houndmaster Loksey, poi torna a riferire a Raleigh the Devout, a Southshore.", enHash = "2401d8e2", vanilla = true },
        progress = { it = "La corruzione nel Monastery non finirà finché non saranno eliminati i suoi capi di grado più alto.\n\nNel nome della Luce, uccidi High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion e Houndmaster Loksey. Una volta caduti loro, forse la vera causa potrà riaccendersi. Fino ad allora, chiunque incroci il cammino della Crociata è in pericolo.\n\nParti da Southshore e fa' che accada!", enHash = "cc99f6ec", vanilla = true },
        reward = { it = "Anche se i discepoli della Luce non gioiscono mai della perdita di vite, dobbiamo accettare che a volte questi sacrifici siano necessari per il bene superiore del Regno e del pianeta.\n\nCon le tue imprese nel Monastery hai risparmiato molte vite innocenti, $N. Rendo omaggio alla tua tenacia.", enHash = "6f3d262f", vanilla = true },
    },
    [1054] = {
        title = { it = "Ridurre la minaccia", enHash = "1b0f3999", vanilla = true },
        text = { it = "Subito a nord di Astranaar ci sono i furbolg Thistlefur. I miei esploratori riferiscono che il loro numero è cresciuto molto negli ultimi mesi. Se diventano troppi, potrebbero trovare il coraggio di attaccare Astranaar direttamente.\n\nUccidine quanti più puoi, ma portami il teschio del loro capotribù come prova che i loro sforzi sono stati soffocati... per ora.\n\nIo resterò qui ad Astranaar e aspetterò tue notizie. Che Elune sia con te.", enHash = "1317d868", vanilla = true },
        objectives = { it = "Porta Dal Bloodclaw's Skull a Raene Wolfrunner, ad Astranaar.", enHash = "926cc171", vanilla = true },
        progress = { it = "La corruzione dei furbolg ha ridotto Ashenvale a una frazione della sua antica gloria.", enHash = "2217694f", vanilla = true },
        reward = { it = "Ben fatto, $N.\n\nI furbolg ci minacciano di continuo. Si spera che questo li tenga a bada ancora per un po'.", enHash = "e5ca7bbc", vanilla = true },
    },
    [1055] = {
        title = { it = "La purificazione di Raene", enHash = "4a88f731", vanilla = true },
        text = { it = "La verga, ora completa, è nelle tue mani. Shael'dryn vorrà sapere del tuo successo.", enHash = "a2ce8b35", vanilla = true },
        objectives = { it = "Torna da Shael'dryn, al pozzo lunare.", enHash = "0ae97c17", vanilla = true },
        reward = { it = "Ce l'hai fatta, $N! Ben fatto!", enHash = "cda5fcaa", vanilla = true },
    },
    [1056] = {
        title = { it = "Viaggio verso lo Stonetalon Peak", enHash = "0d7548e1", vanilla = true },
        text = { it = "Gli spiriti della foresta mi dicono che sei $Gcoraggioso:coraggiosa; e $Gdisposto:disposta; a viaggiare.\n\nA sud, non lontano dal Mystral Lake, c'è un tunnel chiamato Talondeep Path. Attraverso quel tunnel arriverai in una zona nota come Windshear Crag, nelle Stonetalon Mountains. Una volta là, viaggia verso sud-ovest oltre il Cragpool Lake e poi a nord, su per il pendio ripido, finché non raggiungi lo Stonetalon Peak.\n\nLà ti attende Keeper Albagorm. Segui le sue indicazioni, $R.\n\nIl viaggio sarà pericoloso.", enHash = "6f3250dc", vanilla = true },
        objectives = { it = "Raggiungi Keeper Albagorm sullo Stonetalon Peak.", enHash = "85c28125", vanilla = true },
        reward = { it = "Finalmente arrivi. Vedo che Faldreas ha ascoltato gli spiriti della foresta...", enHash = "42ba8402", vanilla = true },
    },
    [1057] = {
        title = { it = "Riconquistare la Charred Vale", enHash = "6237101f", vanilla = true },
        text = { it = "Come $Gprotettore:protettrice; degli spiriti della foresta, puoi senza dubbio immaginare perché sono allarmato.\n\nHai attraversato queste montagne per raggiungere questo picco. Di certo hai visto lo scempio che si è abbattuto su questa terra. L'avidità ha portato alla distruzione di queste colline sacre.\n\nLa Charred Vale a sud è stata data alle fiamme dall'avida armata meccanizzata degli industriali. Peggio ancora, le Bloodfury che hanno invaso la terra ci negano il passaggio per cominciare a farla rinascere.\n\nScaccia le miserabili arpie, $N!", enHash = "38ba5d8d", vanilla = true },
        objectives = { it = "Keeper Albagorm, su Stonetalon Peak, vuole che tu uccida 7 Bloodfury Harpy, 7 Bloodfury Ambusher, 7 Bloodfury Slayer e 7 Bloodfury Roguefeather.", enHash = "662496ba", vanilla = true },
        progress = { it = "C'è molto lavoro da fare prima che la Charred Vale possa tornare la foresta rigogliosa che era un tempo.\n\nRipulisci la zona da quelle minacce immonde, $N! Solo allora potremo cominciare a riprenderci ciò che appartiene alla natura.", enHash = "4178fbda", vanilla = true },
        reward = { it = "Ora che le Bloodfury hanno subito una perdita così grande, forse il vero lavoro di risanamento della terra può cominciare...", enHash = "d17b90c6", vanilla = true },
    },
    [1058] = {
        title = { it = "La magia della foresta di Jin'Zil", enHash = "65ae4699", vanilla = true },
        text = { it = "Come sono emozionato!\n\nTre gabbiette per tre elfetti! Ma cosa ne facciamo dei nostri cari amici amanti degli alberi? Ma sì, diamogli un assaggio di... come la chiamano... magia della foresta!\n\nMi servirà un bel mucchio di Stonetalon Sap. Da quei felini orrendi portami dei Twilight Whisker. Per questa ci vogliono un sacco di Courser Eye, naturalmente: gli occhi non bastano mai. Ah, e non dimentichiamo, una preziosa scaglia di Fey Dragon.\n\nCorri allo Stonetalon Peak, $N, così posso preparare un po' di magia della foresta!", enHash = "5362c29d", vanilla = true },
        objectives = { it = "Witch Doctor Jin'Zil, a Malaka'jin, vuole 5 porzioni di Stonetalon Sap, 5 Twilight Whisker, 30 Courser Eye e un Fey Dragon Scale.", enHash = "22bbc93d", vanilla = true },
        progress = { it = "Guarda i nostri poveri amici elfi. Tutti in gabbia, senza una foresta in cui sgambettare!\n\nAllora, sei $Griuscito:riuscita; a trovarmi un po' di linfa? E i baffi dei Twilight Runner? Non è che per caso hai addosso quel Fey Dragon Scale?\n\nE occhi! Mi serviranno tanti occhi! Non si può proprio mescolare un bell'intruglio di magia della foresta senza una buona dose di occhi!", enHash = "4111cdf0", vanilla = true },
        reward = { it = "Oh, come saranno felici queste ninfette dei boschi! Le faremo sentire proprio a casa con questo intruglio speciale!", enHash = "494f4a7b", vanilla = true },
    },
    [1059] = {
        title = { it = "Riconquistare la Charred Vale", enHash = "6237101f", vanilla = true },
        text = { it = "Le Bloodfury sono state sottomesse. Ma si riorganizzeranno molto presto, se non si fa qualcosa.\n\nMolto a sud delle Barrens si estende una terra conosciuta come Thousand Needles. Se in Thousand Needles viaggi verso ovest finché non raggiungi il limitare della foresta rigogliosa di Feralas, troverai un druido di nome Falfindel Waywarder.\n\nQuesto druido grande e saggio è capace di evocare grandi spiriti della foresta, che possono aiutare nel recupero della Charred Vale.\n\nManda notizia del nostro bisogno! Cercalo subito!", enHash = "0643db34", vanilla = true },
        objectives = { it = "Raggiungi Falfindel Waywarder al confine tra Thousand Needles e Feralas.", enHash = "94a32a56", vanilla = true },
        reward = { it = "Keeper Albagorm è stato saggio a mandarti con tanta urgenza.\n\nVediamo se non riusciamo a chiamare aiuto dalla grande foresta perché raggiunga la Charred Vale prima che sia troppo tardi.", enHash = "36097476", vanilla = true },
    },
    [1060] = {
        title = { it = "Lettera a Jin'Zil", enHash = "d1414cba", vanilla = true },
        text = { it = "Hai fatto così bene per me, $N. Sei un vero portafortuna, e c'è una cosa che voglio farti vedere.\n\nLe arpie non sono originarie delle Barrens. Vengono da un posto che si chiama Stonetalon, lontano a nord-ovest di qui. Sarà probabilmente un posto pericoloso per te, ma ho bisogno che questa lettera arrivi a un mio vecchio amico che vive là, uno stregone di nome Jin'Zil.\n\nSarà contento di sapere che Serena Bloodfeather è morta, e credo che troverai Stonetalon un posto interessante.", enHash = "389a0073", vanilla = true },
        objectives = { it = "Consegna la lettera di Darsok a Jin'Zil, nella sua grotta a Malaka'Jin, a Stonetalon.", enHash = "b3c6273b", vanilla = true },
        progress = { it = "Hai l'aria di un tipo losco. Hai qualcosa da farmi vedere?", enHash = "c0a55165", vanilla = true },
        reward = { it = "Ahh, una lettera da Darsok. Non ho sue notizie da molti anni.\n\nDunque l'ultima dei Bloodfeather è morta, eh? È una buona notizia. Mi ricordo quando il mio amico Rokhan andò con quel mok'nathal pazzo a uccidere la sorella maggiore. Ah, essere di nuovo giovani, come te.", enHash = "d26cc5b6", vanilla = true },
    },
    [1061] = {
        title = { it = "Gli spiriti di Stonetalon", enHash = "a1e10af5", vanilla = true },
        text = { it = "Gli spiriti delle Stonetalon Mountains sono adirati, perché i goblin e i loro servi stanno saccheggiando e bruciando la terra. Così la terra ha gridato, e chi ascolta queste cose... ha sentito.\n\nSeereth Stonebreak, una sciamana promettente dell'Orda, è stata mandata a Stonetalon. Riferisce di una deforestazione enorme per mano dei goblin, e chiede aiuto.\n\nRaggiungi Seereth a Stonetalon. Per arrivare da lei, segui la strada a ovest del Crossroads delle Barrens. È accampata vicino alla Greatwood Vale.", enHash = "fd928fde", vanilla = true },
        objectives = { it = "Parla con Seereth Stonebreak nelle Stonetalon Mountains.", enHash = "d0740539", vanilla = true },
        reward = { it = "Ah, $Gun:una; $C. Molto bene. Ci serviranno le tue capacità per occuparci di questi predoni!", enHash = "497f2b32", vanilla = true },
    },
    [1062] = {
        title = { it = "Invasori goblin", enHash = "5aa0d73b", vanilla = true },
        text = { it = "La Venture Company, gestita dai goblin, si è insediata nelle Stonetalon Mountains, abbattendo alberi e bruciando enormi distese di foresta. Gli spiriti di questo luogo sono quasi accecati dal dolore e dalla rabbia. Dobbiamo fermare la Venture Company!\n\nVa' a nord-ovest, oltre la Greatwood Vale e dentro il Windshear Crag. Troverai i goblin e i loro servi al lavoro: mostra loro che l'Orda non permetterà lo sfruttamento di Stonetalon. Mostraglielo nella lingua che capiscono meglio...\n\nLa violenza.", enHash = "5292bb63", vanilla = true },
        objectives = { it = "Uccidi 15 Venture Co. Logger, poi torna da Seereth Stonebreak, al confine tra Stonetalon e le Barrens.", enHash = "843b8ef7", vanilla = true },
        progress = { it = "La Greatwood Vale è a nord-ovest, $N. Va'. Incuti terrore in chi vuole saccheggiare questa terra!", enHash = "fc756788", vanilla = true },
        reward = { it = "Fatto con coraggio, $N.\n\nAlla fine ci servirà forse la saggezza degli anziani tauren per calmare gli spiriti di Stonetalon, ma...\n\nPrivare la Venture Company del suo personale è una buona prima mossa contro di loro.", enHash = "169874ad", vanilla = true },
    },
    [1063] = {
        title = { it = "L'anziana megera", enHash = "07fea8d2", vanilla = true },
        text = { it = "Per prenderci davvero cura degli spiriti di Stonetalon dobbiamo consultare gli anziani tauren.\n\nNon conosco molti nomi dei loro capi, ma uno lo conosco: Magatha. Ho sentito dire che è molto vecchia e che sa molte cose. Se qualcuno può ottenere aiuto spirituale dai tauren, è lei.\n\nMagatha risiede nella capitale tauren, Thunder Bluff, sull'Elder Rise, l'altura a nord-est della città. Parla con Magatha e raccontale del pericolo che corrono le Stonetalon Mountains.", enHash = "186d044e", vanilla = true },
        objectives = { it = "Parla con Magatha a Thunder Bluff.", enHash = "ca5686cd", vanilla = true },
        reward = { it = "Ti porgo il mio saluto. Sei qui in cerca di consiglio?", enHash = "e69ee714", vanilla = true },
    },
    [1064] = {
        title = { it = "L'aiuto dei Reietti", enHash = "2e67fcb9", vanilla = true },
        text = { it = "I tauren hanno un legame con la terra, e mi fa male sentire delle sofferenze di Stonetalon. Ma temo che, per guarire la terra, dobbiamo prima togliere la malattia che la affligge.\n\nNon è una fortuna, allora, che i Reietti siano alleati con noi? Loro sanno molto di malattie. Credo che possano aiutarci, e così facendo rafforzeranno la fiducia tra i nostri popoli.\n\nParla con Apothecary Zamah. È una studiosa e un'emissaria dei Reietti. La troverai nelle Pools of Vision, sotto lo Spirit Rise.", enHash = "0aa3493e", vanilla = true },
        objectives = { it = "Parla con Apothecary Zamah nelle Pools of Vision, a Thunder Bluff.", enHash = "4a14d749", vanilla = true },
        reward = { it = "Magatha ha mandato notizia del tuo arrivo, $N. Anche se il mio cuore non batte più, provo ancora dolore per gli spiriti di Stonetalon.\n\nI Reietti sono impazienti di offrire tutto l'aiuto che possiamo.", enHash = "07a9cc22", vanilla = true },
    },
    [1065] = {
        title = { it = "Viaggio a Tarren Mill", enHash = "65d3c961", vanilla = true },
        text = { it = "Per liberare Stonetalon dalla Venture Company dobbiamo prendere misure estreme. Estreme, ma senza spargimento di sangue.\n\nUn mio collega potrebbe avere proprio lo strumento che ci serve. Si chiama Lydon; vive nella cittadina di Tarren Mill, nelle Hillsbrad Foothills, nella lontana terra di Lordaeron.\n\nPer raggiungere Hillsbrad, viaggia in zeppelin fino alla nostra capitale, l'Undercity. Poi va' a nord verso le Tirisfal Glades, a sud-ovest verso Silverpine e a sud verso Hillsbrad.\n\nCerca Lydon e portagli questa nota. Gli espone nel dettaglio i nostri bisogni.", enHash = "6a231a6d", vanilla = true },
        objectives = { it = "Porta Zamah's Note ad Apothecary Lydon, a Tarren Mill.", enHash = "0a9a4bdb", vanilla = true },
        progress = { it = "Ah, sei qui con i miei nuovi soggetti da esperimento?", enHash = "d1a44a0c", vanilla = true },
        reward = { it = "Una nota da Zamah? I suoi bisogni devono essere grandi, per mandare notizia da così lontano. Vediamo cosa dice...\n\nAh, splendido! So esattamente cosa fare!", enHash = "e4627cfe", vanilla = true },
    },
    [1066] = {
        title = { it = "Sangue di innocenti", enHash = "3a08ff42", vanilla = true },
        text = { it = "Creerò una tossina per prosciugare la violenza dalla Venture Company, rendendoli deboli e docili. Dovrebbe risolvere il problema dell'Orda a Stonetalon, no?\n\nMa per creare la tossina mi servirà il sangue di innocenti, un ingrediente difficile da procurarsi.\n\nPer fortuna il Syndicate, un gruppo di briganti umani di questa zona, si serve di maghi delle ombre... e quei maghi raccolgono sangue innocente per i loro scopi poco raccomandabili.\n\nPuoi trovare i Syndicate Shadow Mage a Durnholde Keep, a sud-est.", enHash = "c501f0b2", vanilla = true },
        objectives = { it = "Porta 5 Vial of Innocent Blood ad Apothecary Lydon, a Tarren Mill.", enHash = "332307e1", vanilla = true },
        progress = { it = "Hai trovato i Syndicate Shadow Mage e raccolto da loro il sangue?", enHash = "8a28042e", vanilla = true },
        reward = { it = "Molto bene! Immagino che il Syndicate ti abbia dato poco filo da torcere, no?\n\nCome ho detto, il sangue di innocenti non è una cosa facile da procurarsi. Siamo fortunati che i Syndicate Shadow Mage abbiano fatto il lavoro difficile per noi.\n\nOra aspetta un momento, mentre preparo il mio intruglio...", enHash = "05d33b80", vanilla = true },
    },
    [1067] = {
        title = { it = "Ritorno a Thunder Bluff", enHash = "21c8293a", vanilla = true },
        text = { it = "Ecco la tossina. Se la usi contro la Venture Company dovrebbe dare risultati favorevoli, forse perfino contagiosi. Devo dire che è piuttosto entusiasmante vedere il mio lavoro applicato sul campo!\n\nMa prima di usarla, portala ad Apothecary Zamah. Deve creare un metodo per somministrare la tossina, in modo da massimizzarne l'effetto.", enHash = "5415762a", vanilla = true },
        objectives = { it = "Porta Lydon's Toxin ad Apothecary Zamah, a Thunder Bluff.", enHash = "3c3b7a78", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata;, $N. Porti aiuto da parte di Apothecary Lydon?", enHash = "c780f3ef", vanilla = true },
        reward = { it = "Una tossina da Apothecary Lydon? Molto bene. Se conosco Lydon, questa tossina sarà piuttosto efficace contro la Venture Company...", enHash = "ad7b2397", vanilla = true },
    },
    [1068] = {
        title = { it = "Macchine sminuzzatrici", enHash = "48151552", vanilla = true },
        text = { it = "C'è un legame tra la magia spirituale degli sciamani e la magia naturale dei druidi. È per questo che noi sciamani possiamo sentire la supplica degli spiriti di Stonetalon. Molti dei loro sussurri mi sfuggono, ma un messaggio, una visione, è chiara...\n\nHo avuto la visione di due macchine a forma d'uomo nel Windshear Crag, a nord-ovest della Greatwood Vale, che abbattevano alberi a una velocità impossibile. Queste bestie di metallo vanno fermate!\n\nNella mia visione, le macchine erano marchiate con simboli strani:\n\nXT:4 e XT:9.", enHash = "626c358a", vanilla = true },
        objectives = { it = "Uccidi le sminuzzatrici XT:4 e XT:9, poi torna da Seereth Stonebreak, al confine tra le Stonetalon Mountains e le Barrens.", enHash = "3ddafc13", vanilla = true },
        progress = { it = "Gli spiriti degli alberi gemono per la perdita dei loro fratelli, $N. Devi distruggere le sminuzzatrici XT:4 e XT:9, o temo che Stonetalon non sarà mai risanata.", enHash = "2dce0528", vanilla = true },
        reward = { it = "La distruzione delle macchine XT:4 e XT:9 ha placato molti degli spiriti di Stonetalon, $N. Con la loro perdita, speriamo che la Venture Company si tolga da queste montagne.\n\nPerché se non lo farà, temo che le atrocità subite da questo luogo impallidiranno davanti a ciò che verrà.", enHash = "66265a41", vanilla = true },
    },
    [1069] = {
        title = { it = "Uova di ragno deepmoss", enHash = "d47572b7", vanilla = true },
        text = { it = "Le frittate di uova di ragno sono l'ultima moda a Booty Bay! Il problema è che... a Booty Bay le uova non ce le hanno.\n\nIo ci sento un affare!\n\nA Windshear Crag e a Sishir Canyon, nelle Stonetalon Mountains a nord-ovest, vive il ragno deepmoss. Portami le sue uova e ti pago un mucchio di soldi!\n\nA Windshear Crag le uova stanno ammassate sotto quel che resta degli alberi.\n\nA Sishir Canyon... be', se hai lo stomaco debole forse faresti meglio a raccogliere le uova solo a Windshear Crag...", enHash = "3ed7e5c0", vanilla = true },
        objectives = { it = "Porta 15 Deepmoss Egg a Mebok Mizzyrix, a Ratchet.", enHash = "9f138d65", vanilla = true },
        progress = { it = "Le hai prese le uova, $N? Ho già fatto un accordo di spedizione con Wharfmaster Dizzywig!", enHash = "5c4d36c1", vanilla = true },
        reward = { it = "Le hai prese! Grazie!\n\nLe farò mandare a Dizzywig e spedire a Booty Bay. Sento già il sapore del guadagno!\n\nEcco la tua parte, $N. Senza di te non avrei potuto fare questo affare.", enHash = "9643c7ba", vanilla = true },
    },
    [1070] = {
        title = { it = "Di guardia a Stonetalon", enHash = "c40d7458", vanilla = true },
        text = { it = "Salve, $N.\n\nA vederti sembri $Gpieno:piena; di voglia di girare il mondo. Sei mai $Gstato:stata; alle Stonetalon Mountains? È una terra flagellata dalla Venture Co. e da altri nemici degli elfi della notte.\n\nDi recente Sentinel Wolfrunner ha mandato là la mia amica Kaela Shadowspear a indagare su quel che sta accadendo a quella terra, ma non ho ancora sue notizie. Sono ancora più preoccupata perché l'Alleanza ha mandato con lei un mago gnomo... segno di guai, di sicuro.\n\nLa cercheresti, per poi riferire a me?", enHash = "23740731", vanilla = true },
        objectives = { it = "Trova Kaela Shadowspear, che domina la valle all'ingresso di Windshear Crag, nelle Stonetalon Mountains.", enHash = "efbf884a", vanilla = true },
        reward = { it = "Ah, sei $Gvenuto:venuta; da Ashenvale per volere di Tara — quanto mi mancano lei, la mia terra e i miei amici. Deve cavarsela bene con le Sentinelle, se può permettersi di assoldare avventurieri per altri incarichi. Sono orgogliosa di lei.\n\nÈ un piacere conoscerti, $N.", enHash = "e10dda6c", vanilla = true },
    },
    [1071] = {
        title = { it = "La tregua di uno gnomo", enHash = "d7b9b083", vanilla = true },
        text = { it = "Vedi, $N, io sono un membro dell'Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, e il mio obiettivo... anzi, il mio DOVERE! è mostrare agli elfi della notte che un misto di magia, miscele e meccanismi può aiutare a salvare le loro foreste.\n\nMa è una guerra dura da combattere, e i goblin sembra si riproducano come conigli. Non ho nemmeno avuto il tempo di costruire le mie invenzioni più nuove!\n\nMi serve un po' di tempo per pianificare e organizzarmi. Ma per farlo mi serve il tuo aiuto per tenere a bada i goblin nel Windshear Crag, a est...", enHash = "282c6919", vanilla = true },
        objectives = { it = "Uccidi 10 Venture Co. Logger e 10 Venture Co. Deforester, poi torna da Gaxim Rustfizzle a Stonetalon.", enHash = "7bde9650", vanilla = true },
        progress = { it = "Come va la battaglia dalle tue parti, $N?", enHash = "0b00cf91", vanilla = true },
        reward = { it = "Grazie mille del tuo aiuto, $N. Sei $Gtornato:tornata; giusto in tempo, tra l'altro.\n\nCredo di avere un piano perfetto... esplosivi. No, quello non è il piano, ma ne fa parte.\n\nVedi, sto usando esplosivi ad alto potenziale (non preoccuparti, non sono pericolosi come pensano tutti) per ricacciare un po' indietro i goblin. Riesco a spingerli dove voglio con qualche detonazione ben piazzata lungo i bordi delle montagne, ma da qualche giorno sono a corto di scorte...", enHash = "0360a883", vanilla = true },
    },
    [1072] = {
        title = { it = "Un vecchio collega", enHash = "1cce2e43", vanilla = true },
        text = { it = "Il congegno a cui penso è la mia versione più avanzata finora. Ma servirà una pozione speciale perché funzioni. Tanto vale prendere la roba buona, visto che questa missione potrebbe essere la tua ultima.\n\nE per questo ci serviranno esplosivi potenti: il Nitromirglyceronium.\n\nL'unico che sa fare l'NG-5 è un mio vecchio amico: Lomac Gearstrip. Cercalo a Tinker Town.\n\nTu convincilo a farcene un po', di NG-5, e io mi metto al lavoro sulla disposizione dei miei congegni.", enHash = "f7ceec98", vanilla = true },
        objectives = { it = "Parla con Lomac Gearstrip a Ironforge.", enHash = "9811bdc8", vanilla = true },
        reward = { it = "Ahhh... Ti manda Gaxim, eh? E come faccio a sapere che non mi stai mentendo?! Mmh? Mmh...?", enHash = "8f920c1b", vanilla = true },
    },
    [1073] = {
        title = { it = "Incapacità + sostanze chimiche = divertimento", enHash = "a74c164f", vanilla = true },
        text = { it = "Ahahah... ti serve il Nitromirglyceronium per impedire a dei goblin di distruggere una foresta?!\n\nNon mi importa se conosci Gaxim o no... ti do la roba solo per vedere te o loro esplodere in mille pezzettini.\n\nC'è un problema, però: sono a secco.\n\nMa facciamo così: tu mi porti le pozioni giuste e io te ne preparo subito un po'.\n\nIl minimo che puoi fare è dimostrare di avere un po' di abilità come alchimista, prima che ti dia un campione della mia più grande creazione.", enHash = "692ad758", vanilla = true },
        objectives = { it = "Porta 4 Minor Mana Potion e 2 Elixir of Fortitude a Lomac Gearstrip, a Ironforge.", enHash = "43f0634c", vanilla = true },
        progress = { it = "Non posso fare Nitromirglyceronium se non ho le pozioni... sono essenziali per prepararlo.", enHash = "97c3f0c3", vanilla = true },
        reward = { it = "Andranno benissimo.\n\nSe non sapessi come stanno le cose, $Gstraniero:straniera;, direi che te ne intendi di alchimia. Bene, bene... il mondo non è fatto solo di spade e stregoneria, sai?", enHash = "12607131", vanilla = true },
    },
    [1074] = {
        title = { it = "Incapacità + sostanze chimiche = divertimento", enHash = "a74c164f", vanilla = true },
        text = { it = "Eccoti $Gservito:servita;, $Gstraniero:straniera;. Stacci $Gattento:attenta;, però... è roba volatile.\n\nSe sei davvero $Gun amico:un'amica; di Gaxim, salutamelo. Se non lo sei, divertiti a farti saltare in aria.", enHash = "c7d2286c", vanilla = true },
        objectives = { it = "Riporta il Nitromirglyceronium a Gaxim Rustfizzle, a Stonetalon.", enHash = "079169b9", vanilla = true },
        progress = { it = "Ah, che bello, sei $Gtornato:tornata;.", enHash = "9bba0c9b", vanilla = true },
        reward = { it = "Il tuo compito è stato svolto alla perfezione, $N.\n\nL'NG-5 è il componente indispensabile della ricetta per far detonare i carri di dinamite.\n\nCosa? Sì, dinamite... carri interi. È la distrazione perfetta, te lo dico io... aspetta e vedrai.", enHash = "d3507045", vanilla = true },
    },
    [1075] = {
        title = { it = "Una pergamena da Mauren", enHash = "3db1821c", vanilla = true },
        text = { it = "Bene, passiamo alla parte del mio piano sulla detonazione a distanza... oh, non te l'ho ancora spiegata, vero?\n\nAllora, in breve è così: con un po' di magia posso fare in modo che gli esplosivi saltino mentre tu non sei nei paraggi. Sto mettendo insieme un congegno che ti permetterà di premere un solo pulsante e far esplodere l'NG-5 quando sei $Gpronto:pronta;.\n\nMa mi serve un incantesimo da un amico a Stormwind: si chiama Collin Mauren. Lo trovi nel Mage Quarter, laggiù. È umano, quindi non dovrebbe essere difficile da notare.", enHash = "c3490f01", vanilla = true },
        objectives = { it = "Trova Collin Mauren a Stormwind.", enHash = "64ac037a", vanilla = true },
        reward = { it = "Dunque, questo incantesimo che ti serve: uno che ti permetta di far detonare esplosivi a distanza... mmm.", enHash = "52532632", vanilla = true },
    },
    [1076] = {
        title = { it = "Diavoli a Westfall", enHash = "5a184120", vanilla = true },
        text = { it = "Ah, credo di averlo. Un incantesimo di messaggio... credo sia questo l'effetto che cerca.\n\nDovrò creare una pergamena con l'incantesimo impresso sopra. Per farlo mi serviranno i detriti di un Dust Devil.\n\nMentre io raccolgo il resto dei componenti, perché non vai a Westfall a cercare una di quelle creature immonde? Sono pericolose, ma sono sicuro che non è nulla che tu non possa gestire, se sei $Gdisposto:disposta; a sottoporti a uno degli esperimenti di Gaxim.\n\nSarò qui quando torni.", enHash = "a05b5f9e", vanilla = true },
        objectives = { it = "Porta Dust Devil Debris a Collin Mauren, a Stormwind.", enHash = "c479c6b9", vanilla = true },
        progress = { it = "Salve, $N. Hai trovato il componente che mi serve?", enHash = "a659ae4b", vanilla = true },
        reward = { it = "Concedimi solo qualche momento e avrò pronta la tua pergamena.", enHash = "f7bf6e16", vanilla = true },
    },
    [1077] = {
        title = { it = "Consegna speciale per Gaxim", enHash = "3da84406", vanilla = true },
        text = { it = "Ecco a te, $N. Questa dovrebbe andare benissimo.\n\nTi prego, porta i miei saluti a Gaxim quando lo rivedrai. Non vedo l'ora di sentire di questa avventura, quando sarà giunta al termine.\n\nSta' bene.", enHash = "34b627ca", vanilla = true },
        objectives = { it = "Porta la Scroll of Messaging a Gaxim Rustfizzle, a Stonetalon.", enHash = "508a9aa6", vanilla = true },
        progress = { it = "Ahah! Sei $Gtornato:tornata;! Ce l'hai? Hai l'incantesimo?", enHash = "06ebd8d0", vanilla = true },
        reward = { it = "È perfetto, $N! Ben fatto.\n\nQuesto incantesimo, mescolato all'NG-5, farà l'esplosivo a distanza perfetto.\n\nRiusciremo a creare la distrazione perfetta per te, così potrai intrufolarti e rubare le lettere e i piani di ingegneria della Venture Co.\n\nQuesto rallenterà di sicuro le loro opere di deforestazione.", enHash = "a59ab1fe", vanilla = true },
    },
    [1078] = {
        title = { it = "Recupero per Mauren", enHash = "d5616b3d", vanilla = true },
        text = { it = "I viaggiatori continuano a chiedermi delle Stonetalon Mountains. Pare sia un luogo molto amato per le avventure: non importa se cerchi wyvern, elementali o se hai affari con la Venture Co.\n\nNella Charred Vale, nel cuore di Stonetalon, c'era una specie di basilischi le cui scaglie, ridotte in polvere, erano un reagente meraviglioso per certi incantesimi che ho creato.\n\nSe quei basilischi vivono ancora, mi piacerebbe molto avere qualcuna delle loro scaglie.\n\nFa' con calma, non c'è fretta, ma posso pagare bene.", enHash = "5606f83b", vanilla = true },
        objectives = { it = "Porta 8 Crystalized Scale a Collin Mauren, a Stormwind.", enHash = "1991af83", vanilla = true },
        progress = { it = "Salve di nuovo, $N.\n\nSei già $Gtornato:tornata; dalla Vale di Stonetalon con quelle scaglie?", enHash = "d977e83a", vanilla = true },
        reward = { it = "È perfetto, $N. Grazie infinite.\n\nForse un giorno, in futuro, potrò aiutarti come tu hai aiutato me.", enHash = "940cf299", vanilla = true },
    },
    [1079] = {
        title = { it = "Operazioni segrete — Alpha", enHash = "9801f43a", vanilla = true },
        text = { it = "Ci siamo, $N. Presta molta attenzione. I congegni sono pronti e possono essere usati.\n\nPrendi queste pagine: ti spiegheranno meglio i detonatori e gli esplosivi, e dove dovresti piazzarli.\n\nRicorda, il successo della tua missione non dipende da quanta distruzione provochi. Il successo del piano Alpha dipende dal fatto che tu riporti indietro i piani di ingegneria della Venture Co. da dentro la segheria a sud del Cragpool Lake.", enHash = "82c4a830", vanilla = true },
        objectives = { it = "Recupera i Venture Co.'s Engineering Plans dalla segheria nel Windshear Crag.", enHash = "cb50c956", vanilla = true },
        progress = { it = "Hai preso i piani, $N?", enHash = "cee91a12", vanilla = true },
        reward = { it = "Davvero straordinario! È un colpo enorme per la Venture Co.\n\nRiusciremo a trovare i punti deboli delle loro macchine e anche a incorporare i loro progetti nelle nostre creazioni. Questa sì che è una giornata meravigliosa.", enHash = "fa179f6c", vanilla = true },
    },
    [1080] = {
        title = { it = "Operazioni segrete — Beta", enHash = "36740794", vanilla = true },
        text = { it = "Il piano Beta è proprio come il piano Alpha, $N.\n\nCreiamo una distrazione e poi rubiamo le loro preziose lettere.\n\nLa chiave è prendere le lettere... ricordalo.\n\nLe pagine che ti ho già dato ti diranno dove piazzare gli esplosivi. Tu torna qui $Gvivo:viva; e con quelle lettere...", enHash = "f645b028", vanilla = true },
        objectives = { it = "Recupera le Venture Co. Letters dalla Windshear Mine, all'estremità est del Windshear Crag.", enHash = "0e329256", vanilla = true },
        progress = { it = "Com'è andata, $N?", enHash = "f13d1977", vanilla = true },
        reward = { it = "Incredibile, $N! Kaela e le Sentinelle saranno felicissime. Con la tua abilità e le mie creazioni, siamo inarrestabili.", enHash = "ec7596b6", vanilla = true },
    },
    [1081] = {
        title = { it = "Accoglienza da Tyrande", enHash = "b22658b6", vanilla = true },
        text = { it = "$N, non ho dubbi che Tyrande Whisperwind in persona vorrebbe ringraziarti per aver preso parte a questa missione.\n\nIn superficie può non sembrare, ma quello che hai contribuito a mettere in moto potrebbe benissimo rafforzare la nostra posizione nelle Stonetalon Mountains.\n\nSe ti consideri $Gnostro alleato:nostra alleata; contro queste atrocità, va' da Tyrande nel Temple of the Moon, a Darnassus.", enHash = "84991abd", vanilla = true },
        objectives = { it = "Trova Tyrande Whisperwind a Darnassus.", enHash = "1f9d23a1", vanilla = true },
        reward = { it = "Salve, $N. Ho davvero già sentito il tuo nome e, per quanto tu sia ancora $Gpieno:piena; di giovinezza, sono lieta di vedere la strada che hai scelto per te $Gstesso:stessa;.\n\nMi faresti un grande onore se accettassi questo come dono di riconoscenza.", enHash = "0bb6a459", vanilla = true },
    },
    [1082] = {
        title = { it = "Aggiornamento per Sentinel Thenysil", enHash = "bf124628", vanilla = true },
        text = { it = "$N, hai compiuto una grande azione dando una mano qui.\n\nLe Sentinelle di Ashenvale ti ricompenseranno bene se le informerai che Gaxim e io siamo vivi. Di' loro che siamo sulla buona strada per fermare la Venture Co. e risanare queste terre.\n\nTrova Tara Thenysil ad Astranaar; sarà contenta di vedere che sei $Gtornato:tornata; con buone notizie.", enHash = "8d0dd96e", vanilla = true },
        objectives = { it = "Torna da Sentinel Thenysil, ad Ashenvale.", enHash = "59abb167", vanilla = true },
        reward = { it = "Grazie, $N. Hai reso un servizio alle Sentinelle.\n\nSono felice di sapere che Kaela... e persino Gaxim, stanno bene.\n\nTi sei $Gguadagnato:guadagnata; la nostra stima.", enHash = "19c3f86f", vanilla = true },
    },
    [1083] = {
        title = { it = "Spiriti infuriati", enHash = "59ed1430", vanilla = true },
        text = { it = "Non so con certezza cosa abbia fatto la Venture Co. alla Vale, ma è evidente che sono stati sopraffatti dalle creature del posto.\n\nHanno dato fuoco alla foresta e hanno usato le loro invenzioni di distruzione per decimare quanto più possibile della Vale.\n\nMa nella loro ignoranza hanno liberato anche qualcos'altro: spiriti ardenti, elementali di fiamma, pietra e rabbia.\n\nLa terra non ha speranza di vedere il sorriso di Elune finché queste creature vagano libere.\n\nPortami i loro Smoldering Ember a dimostrazione di averne ridotto il numero.", enHash = "14eaec76", vanilla = true },
        objectives = { it = "Porta 8 Smoldering Ember, presi da uno qualsiasi degli elementali del fuoco nella Charred Vale, a Kaela Shadowspear, a Stonetalon.", enHash = "56ebe1eb", vanilla = true },
        progress = { it = "La prima volta che ho visto la Charred Vale ho quasi pianto, $N.", enHash = "11a7b1a9", vanilla = true },
        reward = { it = "I resti del nostro nemico... la tua forza ci è molto utile, $N. Grazie.", enHash = "5e1be540", vanilla = true },
    },
    [1084] = {
        title = { it = "Antichi feriti", enHash = "029eca29", vanilla = true },
        text = { it = "Mi sembra evidente che i protettori della Vale, i treant, c'entrino qualcosa con il fatto che la Venture Co. sia stata respinta. Purtroppo, anche quei guardiani, un tempo gloriosi, ora sono corrotti.\n\nGaxim pensa che la loro corruzione sia in qualche modo legata alle armi che i goblin hanno usato durante la ritirata.\n\nGli ho detto che avrei raccolto un campione da un treant ferito e gliel'avrei lasciato studiare, per capire se è vero.\n\nPortami un po' di quelle schegge, così lo gnomo potrà dirmi di più...", enHash = "dce3af8e", vanilla = true },
        objectives = { it = "Porta un pezzo di Corroded Shrapnel a Kaela Shadowspear, a Stonetalon.", enHash = "0a0d64a1", vanilla = true },
        progress = { it = "Ho la sensazione che Gaxim troverà un uso per quelle schegge, a prescindere da come la Venture Co. le ha usate in passato.", enHash = "7868cf73", vanilla = true },
        reward = { it = "Grazie, $N.\n\nQuesto dovrebbe bastare e avanzare perché Gaxim capisca come i treant sono stati corrotti. Glielo porterò subito.", enHash = "732e2fcd", vanilla = true },
    },
    [1085] = {
        title = { it = "Di guardia a Stonetalon", enHash = "c40d7458", vanilla = true },
        text = { it = "La situazione qui a Stonetalon è evidentemente grave, se un elfo della notte e uno gnomo lavorano insieme.\n\nLa Venture Co. ha devastato queste terre e ho passato quasi tutto il mio tempo a mettere fine alla distruzione.\n\nNon giudicare Gaxim troppo in fretta: capisce che abbiamo bisogno di collaborare.\n\nSe vuoi aiutarci, comincia col parlare con Gaxim.\n\nMi dispiace di non poterti ancora rimandare da Tara con buone notizie. Forse presto.", enHash = "9fe18cba", vanilla = true },
        objectives = { it = "Parla con Gaxim.", enHash = "831d6263", vanilla = true },
        reward = { it = "Infida... infida e pericolosa, ecco com'è questa terra.\n\nMa io sono qui per mostrare agli elfi della notte che con l'aiuto della cara vecchia ingegneria e un pizzico di magia è un po' più sicura.\n\nVedi, rinunciare del tutto alla magia non aiuterà gli elfi della notte — ne hanno bisogno. Il mondo ne ha bisogno. E se ci metti anche ingegneria e alchimia, non puoi sbagliare. Le possibilità sono infinite.", enHash = "f62bf81b", vanilla = true },
    },
    [1086] = {
        title = { it = "L'aeroporto delle macchine volanti", enHash = "980f0ef0", vanilla = true },
        text = { it = "La tossina è pronta. Non resta che consegnarla. Sei tu, $N, a doverlo fare.\n\nLa Venture Company deve pur avere un modo per mandare messaggi e carichi leggeri tra il suo quartier generale e le sue attività a Stonetalon. Probabilmente è un piccolo porto aereo — non abbastanza grande per uno zeppelin, ma forse per una macchina volante. Devi cercare nelle zone di Stonetalon controllate dalla Venture Company e trovare questo porto aereo, se esiste. Se lo trovi, metti lì la tossina.\n\nMettila, e corri via.", enHash = "1adb069b", vanilla = true },
        objectives = { it = "Porta il Toxic Fogger al porto aereo della Venture Co., poi torna da Apothecary Zamah.", enHash = "92ea2c02", vanilla = true },
        progress = { it = "Devi trovare l'aeroporto della Venture Company, se esiste, $N.", enHash = "331e3edd", vanilla = true },
        reward = { it = "Hai trovato il porto? Ben fatto, $N! Sono certa che i goblin siano rimasti piuttosto sorpresi dalla tua consegna! Speriamo che quella tossina trovi la strada per il loro quartier generale.\n\nHai servito bene il tuo popolo, e ti consiglio di ignorare qualunque senso di colpa tu possa provare per aver avvelenato la Venture Company. Meritano di molto peggio.\n\nE se c'è un briciolo di saggezza che i Reietti possono insegnare ai loro alleati, è questo:\n\nNon evitare le strade oscure... se quelle strade portano alla vittoria.", enHash = "50271358", vanilla = true },
    },
    [1087] = {
        title = { it = "L'eredità di Cenarius", enHash = "09438a0c", vanilla = true },
        text = { it = "Non puoi immaginare l'odio che provo per questa terra miserabile. La genia di Cenarius e i druidi kaldorei sul picco usano i loro patetici poteri per soffocare il flusso della magia, persino così a sud dei loro patetici possedimenti... le loro amate foreste.\n\nVorrei poter tornare a Jaedenar ed esultare nel flusso della magia, ma il mio padrone non mi permetterà di tornare finché il mio lavoro non sarà finito.\n\nNon ho dubbi che tu ami gli elfi della notte e i loro alleati quanto poco li amo io. Aiutami, e i nostri fini saranno soddisfatti entrambi.", enHash = "0bcb2724", vanilla = true },
        objectives = { it = "Uccidi 4 Son of Cenarius, 4 Daughter of Cenarius e 4 Cenarion Botanist per Braelyn Firehand, vicino al Sun Rock Retreat.", enHash = "671ba288", vanilla = true },
        progress = { it = "Qui, incanalare la magia è come tirare su acqua da un pozzo con un secchio pieno di buchi.", enHash = "60a352fb", vanilla = true },
        reward = { it = "Già lo sento... sì... un potere così dolce... la piena che irrompe. I kaldorei sono sciocchi a disprezzare i doni di questo mondo, a rifiutare lo scorrere della magia mentre fluisce cantando nelle tue vene.\n\nChe pallida farsa è la vita senza il suo abbraccio ardente!", enHash = "9cf59892", vanilla = true },
    },
    [1088] = {
        title = { it = "Ordanus", enHash = "b80b19ec", vanilla = true },
        text = { it = "Credevano di poter fermare il flusso della magia. Si sbagliavano. Credevano di poter nascondere Ordanus, ma avrò la sua testa!\n\nLa magia mi concede la vera vista. Sì... eccolo là. Un crocevia... In cima a un grande albero, nell'Ashenvale Forest. Un nome... Raynewood. Uno dei figli più antichi del dio della foresta. Lo hanno portato via dal picco prima che potessi trovarlo, ma il suo tempo sta per finire.\n\nPortamela, e condividerò con te un dono potente.", enHash = "4b9e2fac", vanilla = true },
        objectives = { it = "Porta la testa di Ordanus a Braelyn Firehand, vicino al Sun Rock Retreat.", enHash = "4c807d22", vanilla = true },
        progress = { it = "Quando il mio padrone mi ha mandata al picco di Stonetalon, mi aspettavo che tutto ciò che mi sarebbe servito fosse fare scempio degli elfi della notte che brulicavano tra le sacre rovine del nostro antico tempio di Azshara, profanandone la sacralità con il loro tocco... ma Ordanus mi era sfuggito.", enHash = "bf7194f5", vanilla = true },
        reward = { it = "Ho conosciuto Ordanus, un tempo, molto tempo fa. Aveva l'arroganza della sua specie, e si teneva al di sopra perfino degli Alti Nobili.\n\nOra la sua testa non sta più così in alto, vero, $N?\n\nTi ho promesso una ricompensa, e l'avrai. Vieni da me.", enHash = "ccb50e0c", vanilla = true },
    },
    [1089] = {
        title = { it = "Il Den", enHash = "af6a2fde", vanilla = true },
        text = { it = "I druidi hanno costruito il Talon Den su Stonetalon Peak, dove custodiscono molti oggetti potenti.\n\nHanno ideato uno schema complesso per impedire che finiscano nelle mani sbagliate.\n\nPer fortuna, sono riuscita a... estrarre qualche dettaglio da uno di loro.\n\nNascosta in una piccola lanterna all'ingresso del Den, troverai la Gatekeeper's Key: con quella potrai aprire i nascondigli sparsi per il Den. Gli oggetti di quei nascondigli ti permetteranno di aprire il loro tesoro, che si trova in una delle aree centrali.", enHash = "1b00a134", vanilla = true },
        objectives = { it = "Raggiungi il Den su Stonetalon Peak. Usando la Gatekeeper's Key, procurati gli oggetti nascosti dei druidi. Usa quegli oggetti per aprire il Talon Den Hoard.", enHash = "9707785e", vanilla = true },
        progress = { it = "Tre serrature sono scolpite nella pietra.", enHash = "b7cc4a8f", vanilla = true },
        reward = { it = "Mentre le tre chiavi scivolano nelle rispettive aperture, in mezzo alla luce splendente compaiono diversi oggetti.", enHash = "88820f1b", vanilla = true },
    },
    [1090] = {
        title = { it = "Gli ordini di Gerenzo", enHash = "b41bb1a7", vanilla = true },
        text = { it = "Sai, un tempo ero la seconda persona più importante di questo cantiere. È cambiato tutto quando è arrivato Gerenzo. Ha licenziato il mio capo, Ziz Fizziks, e mi ha spedito a lavorare giù nelle miniere. Ziz però mi ha detto di restare qui e raccogliere informazioni. Il suo nuovo capo ci pagherà bene se riusciamo a scoprire quali sono i piani di Gerenzo.\n\nComunque, quello che so è che Gerenzo ha ordinato di estrarre grandi quantità di questo minerale verde-oro. Posso procurarti un campione da portare a Ziz, ma dovrai fare attenzione alle pattuglie mentre lo prendo.", enHash = "153de227", vanilla = true },
        objectives = { it = "Prendi il minerale misterioso da Piznik dopo che ha finito di estrarlo.", enHash = "3e11ad15", vanilla = true },
        reward = { it = "Grazie, $N. Per un attimo si è messa un po' male e probabilmente abbiamo attirato fin troppa attenzione su di noi.\n\nLa cosa importante, però, è che abbiamo il campione di minerale, e dovremmo portarlo a Ziz il prima possibile.", enHash = "a2e1a97e", vanilla = true },
    },
    [1091] = {
        title = { it = "L'aggiornamento di Kaela", enHash = "dc19f339", vanilla = true },
        text = { it = "$N, porta queste lettere a Kaela. Sono sicuro che vorrà saperne. O almeno lo vorranno le Sentinelle.\n\nMi raccomando, raccontale che successo abbiamo avuto e che non ce l'avremmo fatta senza un po' di magia.", enHash = "1a7e6a06", vanilla = true },
        objectives = { it = "Porta le Venture Co. Letters a Kaela Shadowspear.", enHash = "dba1c0fb", vanilla = true },
        progress = { it = "Sì, $N? Cosa posso fare per te?", enHash = "ccc443af", vanilla = true },
        reward = { it = "Questo è davvero interessante.\n\nTu e Gaxim avete fatto un ottimo lavoro, $N. Grazie.", enHash = "c0402932", vanilla = true },
    },
    [1092] = {
        title = { it = "Gli ordini di Gerenzo", enHash = "b41bb1a7", vanilla = true },
        text = { it = "Credo che farei meglio a pensare ad andarmene anch'io. Non ci vorrà molto perché la voce di quello che è successo qui arrivi ai piani alti, e sono sicuro che non la prenderebbero bene a rivedermi.\n\nSgattaiolerò via e raggiungerò Ziz. Si spera che riesca a trovarmi un nuovo lavoro!\n\nProverò a ripulire un po' questo disastro, ma tu porta subito il campione di minerale a Ziz. Mi ha detto che si sarebbe accampato da qualche parte sul lato occidentale del Windshear Crag. Buona fortuna.", enHash = "17e040f8", vanilla = true },
        objectives = { it = "Consegna l'Unidentified Ore a Ziz Fizziks, nelle Stonetalon Mountains.", enHash = "5b234791", vanilla = true },
        progress = { it = "Posso aiutarti in qualcosa?", enHash = "9d407e26", vanilla = true },
        reward = { it = "Ahhh, sapevo di aver fatto la cosa giusta a dire a Piznik di restare indietro. Sono sicuro che gli ingegneri di Undermine saranno molto interessati a dare un'occhiata a questo...\n\nNaturalmente vorrò tenerne un pezzetto per me, ma quello che non sanno non gli fa male, no?", enHash = "54b5d93b", vanilla = true },
    },
    [1093] = {
        title = { it = "Super Reaper 6000", enHash = "df82b4c6", vanilla = true },
        text = { it = "Terribile quello che la Venture Company ha fatto qui, eh? Ma cosa avevano in testa? Una compagnia di goblin che assume uno gnomo!\n\nPer mia fortuna, Sputtervalve riconosce un genio quando lo vede. Mi ha assunto appena dopo che mi avevano cacciato!\n\nMi dice che hanno costruito una macchina taglialegna enorme, e Sput' vuole che gli rubi i progetti. Purtroppo Gerenzo, maledetto gnomo, mi vuole morto a vista... magari potresti rubare tu i progetti per me? Dovresti riuscire a trovarli addosso a uno dei loro operatori.", enHash = "9dc4aeef", vanilla = true },
        objectives = { it = "Procura i Super Reaper 6000 Blueprints a Ziz Fizziks, nelle Stonetalon Mountains.", enHash = "b9031ad0", vanilla = true },
        progress = { it = "Hai trovato quei progetti? Non vedo l'ora di fare colpo sul nuovo capo. Si spera che, una volta convinto della mia lealtà (be', per quanto lo si possa convincere... onore da goblin, sai com'è?), si senta a suo agio a servirsi del mio genio piuttosto notevole.", enHash = "9607218f", vanilla = true },
        reward = { it = "Ehi, è quello che penso? Ottimo!\n\nAllora, vediamo. Uff... come dovrei capirci qualcosa... non riesco a farmi una ragione di come ragionano gli gnomi. Ti dirò, mi stupisce che siano riusciti a costruire la ruota, figurarsi quelle macchine volanti che gli piacciono tanto.", enHash = "9397e1f4", vanilla = true },
    },
    [1094] = {
        title = { it = "Altre istruzioni", enHash = "0865ae21", vanilla = true },
        text = { it = "Questa busta contiene tutte le informazioni che sono riuscito ad arraffare mentre mi buttavano fuori dalla porta... documenti interni della Venture Company, qualche manuale, roba tecnica... Ah, e naturalmente i Super Reaper 6000 Blueprints.\n\nSputtervalve si è stabilito a Ratchet, nelle Barrens. Non dovresti far fatica a trovarlo: è un tipetto verde.", enHash = "6b655848", vanilla = true },
        objectives = { it = "Consegna la Sealed Envelope a Sputtervalve, nelle Barrens.", enHash = "d30a39a7", vanilla = true },
        progress = { it = "Salve! Come posso aiutarti?", enHash = "ac2df813", vanilla = true },
        reward = { it = "Fizziks, eh? Non posso dire di fidarmi di lui, ma queste informazioni sembrano abbastanza buone. Cosa non darei per togliermi la Venture Company dai piedi.\n\nCerte macchine però le inventano buone... non posso negare che abbiamo tratto vantaggio da qualcuna delle migliorie che hanno messo a punto.", enHash = "1ba59efd", vanilla = true },
    },
    [1095] = {
        title = { it = "Altre istruzioni", enHash = "0865ae21", vanilla = true },
        text = { it = "La faccenda di questo gnomo assunto dalla Venture Company ha fatto un po' di rumore a Undermine. I principi del commercio non approvano che Razdunk si accompagni a questo Gerenzo.\n\nRiddlevox mi ha chiesto di occuparmi del problema, e sono sicuro che glielo abbiano ordinato uno o più principi del commercio. Naturalmente, il direttore non me l'ha detto. Diciamo che ho un presentimento.\n\nComunque sia, Gerenzo va tolto di mezzo, e sarebbe una prova adatta affidare a Fizziks il compito di sistemarlo.", enHash = "c1a4c9cd", vanilla = true },
        objectives = { it = "Porta i nuovi ordini a Ziz Fizziks, nelle Stonetalon Mountains.", enHash = "096cc8b3", vanilla = true },
        reward = { it = "Eliminare Gerenzo? Ecco una prospettiva a cui non ho niente da obiettare.\n\nGli gnomi sono già abbastanza insopportabili di loro, ma quello che ho saputo di Gerenzo peggiora solo le cose. A quanto pare era uno dei capi ingegneri a Gnomeregan, dove lavorava al loro progetto segreto: non siamo mai riusciti a infiltrarci a Dun Morogh abbastanza a fondo da scoprire i dettagli precisi. È stato un fallimento. I nostri rapporti dicono che, qualunque cosa fosse, è letteralmente esplosa in faccia a loro.", enHash = "bf61cdf5", vanilla = true },
    },
    [1096] = {
        title = { it = "Gerenzo Wrenchwhistle", enHash = "cc68aa5b", vanilla = true },
        text = { it = "Ho incontrato Gerenzo una volta, ma lascia che te lo dica: non è bello da vedere. La sua carne sembra marcire, e si è innestato metallo e ingranaggi sul corpo, sostituendo alcune membra con altre meccaniche.\n\nA nord-est di qui, molto sopra Cragpool Lake, su vicino alla ruota ad acqua, è lì che Gerenzo sorveglia tutto il cantiere. Non c'è verso che io riesca a farmi strada combattendo fin lassù, per non parlare di affrontare Gerenzo... Ma tu hai l'aria di potercela fare.\n\nSe lo uccidi per me, ti ricompenserò a dovere!", enHash = "8d557fa4", vanilla = true },
        objectives = { it = "Porta Gerenzo Wrenchwhistle's Mechanical Arm a Ziz Fizziks, nelle Stonetalon Mountains.", enHash = "a583d023", vanilla = true },
        progress = { it = "Sputtervalve vorrà una qualche prova che Gerenzo è morto. Credo che il suo braccio meccanico andrà bene.", enHash = "5cf1246b", vanilla = true },
        reward = { it = "Guarda quel coso... ci voleva uno gnomo per inventarsi una cosa del genere. Non riesco a capire perché uno dovrebbe tagliarsi un braccio e sostituirlo con quello, quando potrebbe benissimo tenerseli tutti e due e aggiungerne un terzo!\n\nGnomi, te lo dico io...\n\nAlmeno Gerenzo è fuori gioco. Speriamo che basti come prova e che Sputtervalve mi assegni a una delle officine della Tinkers' Union a Gadgetzan o magari perfino a Undermine.", enHash = "e3ea24dd", vanilla = true },
    },
    [1097] = {
        title = { it = "L'incarico di Elmore", enHash = "81751bfd" },
        text = { it = "C'è un armaiolo nano a Stormwind, Grimand Elmore, che ha mandato a dire che gli serve aiuto per una consegna. Credo che voglia spedire un pacco alla sua terra d'origine, a nord.\n\nHai un bel paio di gambe robuste! Quindi, se ti interessa un po' di lavoro di gambe, parla con Grimand. Ci faresti comodo quaggiù, ma dobbiamo anche tenere saldi i legami con i nani.\n\nGrimand Elmore lo trovi al negozio di armi nel Dwarven District di Stormwind, nella parte nord-orientale della città.", enHash = "9667ef45" },
        objectives = { it = "Parla con Grimand Elmore.", enHash = "cd7c276e" },
        reward = { it = "Sei qui per aiutarmi con la consegna? Benissimo!", enHash = "329714a6", vanilla = true },
    },
    [1098] = {
        title = { it = "Inseguitori della Morte a Shadowfang", enHash = "bf3eb72a", vanilla = true },
        text = { it = "In preparazione di un assalto a Shadowfang, due Inseguitori della Morte sono stati mandati alla fortezza per raccogliere informazioni. Sono passati molti giorni e non sono tornati, ma dobbiamo avere il loro rapporto se vogliamo sperare in un attacco riuscito!\n\nEcco dunque il tuo compito, $N. Va' a Shadowfang Keep, a sud, e trova Deathstalker Adamant e Deathstalker Vincent. Trovali, e se hanno bisogno di aiuto daglielo.\n\nQuesta missione è tanto pericolosa quanto decisiva, $N. Non fallire.", enHash = "485e138a", vanilla = true },
        objectives = { it = "Trova Deathstalker Adamant e Deathstalker Vincent.", enHash = "1f1092f0", vanilla = true },
        reward = { it = "Il corpo di Vincent giace spezzato e immobile.\n\nDeathstalker Adamant manderà il suo rapporto a Hadrec... ma qualunque altro dettaglio Vincent avesse scoperto resterà con lui.\n\nStretto nella sua mano, però, c'è un piccolo ninnolo...", enHash = "de0ccc39", vanilla = true },
    },
    [1100] = {
        title = { it = "Il diario di Lonebrow", enHash = "fa7f2d75", vanilla = true },
        text = { it = "Apri lentamente il diario consunto di Henrig Lonebrow....", enHash = "c0eafb34", vanilla = true },
        objectives = { it = "Leggi Henrig Lonebrow's Journal.", enHash = "38f6d8e2", vanilla = true },
        progress = { it = "Dalla tua aria preoccupata capisco che qualcosa non va....", enHash = "29854253", vanilla = true },
        reward = { it = "Dici di aver trovato questo diario addosso a un nano morto? Dammi solo un momento per scorrere le pagine...", enHash = "84b47a02", vanilla = true },
    },
    [1101] = {
        title = { it = "La megera del Kraul", enHash = "22b3ca71", vanilla = true },
        text = { it = "Povero Heralath! E questo nano... Lonebrow. Che anima coraggiosa era.\n\nNon dobbiamo lasciare che il loro valore vada sprecato. Questa megera... Charlga Razorflank... va fermata.\n\nDi sicuro infiltrarsi nel Kraul sarà pericoloso. Non c'è tempo di mandare notizia a Darnassus. $N, raduna un gruppo per uccidere la megera.\n\nPortami Razorflank's Medallion come prova della sua fine.", enHash = "94681dfa", vanilla = true },
        objectives = { it = "Porta Razorflank's Medallion a Falfindel Waywarder, a Thalanaar.", enHash = "818b8570", vanilla = true },
        progress = { it = "Finché Charlga Razorflank raduna forze nel Razorfen Kraul, queste terre sono in grave pericolo.", enHash = "fe50b0f9", vanilla = true },
        reward = { it = "La megera ha trovato il riposo eterno. È una notizia fantastica, $N.\n\nIn questi tempi di pericolo, è confortante vedere una persona coraggiosa come te.\n\nCon i tirapiedi di Razorflank sistemati, i nostri studi nella zona possono continuare. Forse adesso potremo capire meglio che cosa, esattamente, abbia corrotto il luogo di riposo di Agamaggan.\n\nTemo però che anche la risposta a questa domanda stia nel tradimento...", enHash = "542fae54", vanilla = true },
    },
    [1102] = {
        title = { it = "Un destino di vendetta", enHash = "4f57f36d", vanilla = true },
        text = { it = "Cairne è un nobile capo, per aver unito il nostro popolo qui a Thunder Bluff.\n\nMa io non riesco a perdonare chi ci ha cacciati dalle nostre terre ancestrali con la stessa facilità di altri. Il mio popolo ha abitato le Barrens meridionali per decenni. Quella terra per noi era sacra. Ma siamo stati cacciati da numerosi nemici.\n\nUn destino di vendetta attende la megera, Charlga Razorflank, che raduna un immondo esercito dall'interno del Razorfen Kraul.\n\nPortami il cuore di Razorflank e potrò morire in pace, $N.", enHash = "25929ee9", vanilla = true },
        objectives = { it = "Porta Razorflank's Heart ad Auld Stonespire, a Thunder Bluff.", enHash = "88f87ab9", vanilla = true },
        progress = { it = "Quando saprò che le immonde bestie del Razorfen Kraul sono state cacciate dalla loro immonda tana, potrò riposare in pace, sapendo che la vendetta è stata servita.\n\nHai cacciato i quilboar dal Kraul? Mi porti buone notizie sotto forma del cuore di Razorflank?", enHash = "2dc40612", vanilla = true },
        reward = { it = "Vedo che l'odiosa tribù del Razorfen Kraul ora conosce il dolore del mio popolo. Ben gli sta, a quelle bestie immonde.\n\nCacciare qualcuno da una terra sacra è un peccato che merita la vendetta più severa.\n\nGrazie, $N, per avermi aiutato nella mia sventura.", enHash = "63da2a90", vanilla = true },
    },
    [1104] = {
        title = { it = "Veleno delle saline", enHash = "1f066460", vanilla = true },
        text = { it = "Ho tanti progetti per la nostra auto a razzo! Tantissimi! E devo provarli tutti!!\n\nSto lavorando a un nuovo tipo di carburante. Uno che brucia davvero davvero davvero caldo!! Non ho ancora azzeccato la miscela, ma credo di sapere cosa mi serve...\n\nGli scorpidi che vagano per le Shimmering Flats hanno un veleno pieno zeppo di sale. È unico nel suo genere! Ed è proprio quel che mi serve!\n\nPortami il veleno e fidati: la nostra auto volerà!!", enHash = "b6efaa2b", vanilla = true },
        objectives = { it = "Porta 6 Salty Scorpid Venom a Fizzle Brassbolts, nelle Shimmering Flats.", enHash = "b3177950", vanilla = true },
        progress = { it = "Ehi ehi ehi! L'hai preso quel veleno??", enHash = "fe641bf0", vanilla = true },
        reward = { it = "Benissimo! Questo veleno funzionerà alla grande! Grazie, $N!\n\nOra devo solo farlo bollire, applicare lo skipper-otomero, aggiungere un nega-catalizzatore e... Accidenti! Dove sono i miei appunti!?", enHash = "cad8ff05", vanilla = true },
    },
    [1105] = {
        title = { it = "Gusci induriti", enHash = "7d965290", vanilla = true },
        text = { it = "Mio fratello sta lavorando a un nuovo carburante per la sua auto a razzo. È geniale, davvero. Così geniale che... credo che quel nuovo carburante che sta progettando sia abbastanza forte da mangiarsi il telaio dell'auto!\n\nVoglio rinforzare i serbatoi prima che succeda.\n\nLe tartarughe là fuori nelle saline hanno gusci durissimi. Voglio usarli per fare serbatoi nuovi per la nostra auto a razzo. Serbatoi che reggano il nuovo carburante di mio fratello.\n\nMi sembri abbastanza responsabile. Me li prendi quei gusci?", enHash = "84fc36f7", vanilla = true },
        objectives = { it = "Porta 9 Hardened Tortoise Shell a Wizzle Brassbolts, nelle Shimmering Flats.", enHash = "9af6dd0e", vanilla = true },
        progress = { it = "Mio fratello sta facendo progressi con il suo nuovo carburante, e la cosa mi preoccupa. Devo mettermi al lavoro su un serbatoio di guscio di tartaruga il prima possibile!\n\n$N, ce li hai quei gusci?", enHash = "96dab13a", vanilla = true },
        reward = { it = "Li hai presi! Grazie, $N!\n\nCaspita, questi gusci sono più duri di quanto pensassi! Eh, a lavorarli piegherò di sicuro una cassetta intera di attrezzi!", enHash = "723a0e05", vanilla = true },
    },
    [1106] = {
        title = { it = "Martek the Exiled", enHash = "532d9b68", vanilla = true },
        text = { it = "Sto sviluppando un motore nuovo che farà andare l'auto velocissima! Abbastanza veloce da volare, lo so! Mi servono solo pistoni che reggano sforzi molto molto pesanti. Tutte le mie prove sono fallite perché non riesco a fare pistoni abbastanza duri!\n\nMa c'è qualcuno che forse sa come si fa.\n\nSi chiama Martek the Exiled. È un grande fabbro e di metalli ne sa più di chiunque altro. Portagli questa lettera, so che può aiutare!\n\nMa è lontano lontano: ad Azeroth, nei Badlands, in un accampamento, con un goblin!\n\nTrovalo!", enHash = "37391192", vanilla = true },
        objectives = { it = "Porta Fizzle's Letter a Martek the Exiled, nei Badlands.", enHash = "f46940ce", vanilla = true },
        progress = { it = "Be', mi hai trovato. Buon per te.\n\nSei qui per quell'ascia che ho fatto per Gath'Ilzogg? O sei qui a riscattare l'onore di Duchess Pamay?\n\nA dire il vero non m'importa quale delle due. Se sei qui per combattere, allora sbrighiamoci...", enHash = "c26a0eb9", vanilla = true },
        reward = { it = "Ti manda Fizzle? Be', allora la cosa cambia! Certo che ti aiuto. Fizzle e suo fratello sono tra le poche persone che non mi vogliono morto!\n\nQuindi Fizzle vuole fare dei pistoni, eh? Pistoni abbastanza robusti da reggere qualunque sforzo abbia in mente, e se conosco Fizzle questa sua nuova auto è un vulcano su ruote!", enHash = "d96e7ffe", vanilla = true },
    },
    [1107] = {
        title = { it = "Encrusted Tail Fins", enHash = "8e709015", vanilla = true },
        text = { it = "La nostra auto a razzo è la cosa più veloce delle saline! Così veloce che... temo che l'attrito la farà a pezzi!\n\nPer evitarlo devo creare un composto con cui rivestire le parti in movimento. Deve essere duro ma non fragile, e deve resistere alla corrosione del sale, altrimenti il tempo passato nelle Shimmering Flats se lo mangerà.\n\nHai mai sentito parlare del Vile Reef, $N? È al largo della costa di Stranglethorn Vale. Là vivono i murloc Saltscale, e le loro pinne caudali sono un ingrediente fondamentale del mio composto.", enHash = "4a07c0d0", vanilla = true },
        objectives = { it = "Porta 10 Encrusted Tail Fin a Wizzle Brassbolts, nelle Shimmering Flats.", enHash = "edffeb2e", vanilla = true },
        progress = { it = "Ce le hai le pinne caudali? Se non riesco a proteggere la nostra auto dalla sua stessa velocità, in queste corse non durerà molto.", enHash = "f97ac572", vanilla = true },
        reward = { it = "Grazie, $N! Dopo averle macinate e fuse con qualche altro ingrediente, il composto sarà pronto. E dopo di che l'auto sarà al sicuro dalla propria velocità.\n\nAl sicuro, finché non va a sbattere contro qualcosa...", enHash = "64756c60", vanilla = true },
    },
    [1108] = {
        title = { it = "Indurium", enHash = "0793a485", vanilla = true },
        text = { it = "Non sto qui fuori solo per stare lontano dalla gente. Nei Badlands c'è una ricchezza di metallo, $N, se hai il fegato di andartela a prendere.\n\nIl metallo si chiama indurium e, guarda caso, si dice che abbia un'alta resistenza al calore e agli sforzi. Potrebbe andar bene per l'auto di Fizzle.\n\nMa assicuriamocene. Procurami dei campioni di indurium e ne proverò le proprietà.\n\nIl vero minerale di indurium sta nel profondo di Uldaman, ma i trogg Stonevault dei Badlands a volte ne hanno addosso delle scaglie. Portami quelle scaglie.", enHash = "f6e85ef2", vanilla = true },
        objectives = { it = "Porta 10 Indurium Flake a Martek the Exiled, nei Badlands.", enHash = "67dfaf24", vanilla = true },
        progress = { it = "Hai trovato delle scaglie di indurium, $N? Ho la forgia accesa e pronta per provarle.", enHash = "3ff2bdb3", vanilla = true },
        reward = { it = "Ah sì, queste andranno bene. Ora mettiamole sul fuoco e vediamo come se la cavano...", enHash = "5eab38eb", vanilla = true },
    },
    [1109] = {
        title = { it = "Uno, due... guano!", enHash = "427030ad", vanilla = true },
        text = { it = "Come vedi, $N, alla Royal Apothecary Society stiamo conducendo degli esperimenti molto... interessanti.\n\nIn quanto Master, qui, è mio compito sovrintendere ai più ambiziosi dei nostri tentativi alchemici. Tanto lavoro e così poco tempo!\n\nPer $Gun:una; $C, hai l'aria di chi ha viaggiato molto. Forse puoi aiutarmi.\n\nHo bisogno di una sostanza rara. È un materiale immondo; viene da una rara specie di pipistrelli che si trova solo in quel buco fangoso noto come Razorfen Kraul. Portami il guano dei Kraul Bat, così potremo cominciare il nostro lavoro...", enHash = "4ca7678d", vanilla = true },
        objectives = { it = "Porta 1 mucchio di Kraul Guano a Master Apothecary Faranell, nell'Undercity.", enHash = "d481ba34", vanilla = true },
        progress = { it = "Ah, vedo che sei $Gtornato:tornata;. Sei $Griuscito:riuscita; a procurarti del Kraul Guano?", enHash = "b78dd6e2", vanilla = true },
        reward = { it = "Splendido! È proprio l'inizio che ci serviva, $N.", enHash = "7359d590", vanilla = true },
    },
    [1110] = {
        title = { it = "Rocket Car Parts", enHash = "fac87148", vanilla = true },
        text = { it = "Eh eh, con tutte le corse che fanno qui, non c'è da stupirsi che ogni tanto capiti qualche incidente. Se ti guardi intorno nelle Shimmering Flats vedrai i segni degli schianti passati: pezzi di auto a razzo sparsi dappertutto!\n\nE quei pezzi valgono soldi per gnomi e goblin. Sono sempre a caccia di altri aggeggi da montare sulle loro auto.\n\nQuindi va' là fuori e procurami dei pezzi. Portamene un mucchio e ti pagherò bene.", enHash = "3798eabc", vanilla = true },
        objectives = { it = "Porta 30 Rocket Car Parts a Kravel Koalbeard, nelle Shimmering Flats.", enHash = "35fdc423", vanilla = true },
        progress = { it = "$N, sei $Gstato:stata; là fuori nelle Flats? Hai riportato quel carico di pezzi che volevo?", enHash = "ed2be531", vanilla = true },
        reward = { it = "Perbacco, guarda che roba! In quel mucchio di rottami c'è della bella merce. Sono sicuro che riuscirò a rivenderla per una bella sommetta.\n\nE... è un orecchio quello che vedo schiacciato tra quelle due lamiere?? Ahia! Eh, non vorrei proprio essere quel pilota!\n\nGrazie, $N. Ecco la tua paga. Ed ecco un consiglio, gratis...\n\nSe cerchi abbastanza bene, nella disgrazia altrui trovi sempre un profitto.", enHash = "bfd20d8e", vanilla = true },
    },
    [1111] = {
        title = { it = "Wharfmaster Dizzywig", enHash = "264ca25b", vanilla = true },
        text = { it = "Il mio mestiere è procurare alla gente quel che le serve, e gli gnomi là in fondo hanno un ordine di pezzi da far arrivare. I loro pezzi sono stati spediti a Ratchet una settimana fa, ma non sono riuscito a fare il viaggio.\n\nAllora, te la senti di sgambettare un po'? Va' a Ratchet e consegna questo ordine a Wharfmaster Dizzywig: probabilmente sarà ai moli.\n\nFammi questo favore e avrò altri lavori per te.\n\nLavori, $Gamico mio:amica mia;, con un bel potenziale di profitto...", enHash = "ceff25e6", vanilla = true },
        objectives = { it = "Porta Kravel's Parts Order a Wharfmaster Dizzywig, a Ratchet.", enHash = "1dc29abb", vanilla = true },
        progress = { it = "Parla più forte! Dimmi, consegni o ritiri?", enHash = "210f5388", vanilla = true },
        reward = { it = "Oh sì. I pezzi per Kravel. Meno male che sei qui. Questa roba è rimasta qui fuori per giorni e temevo che arrugginisse!", enHash = "75fa5230", vanilla = true },
    },
    [1112] = {
        title = { it = "Parti per Kravel", enHash = "b08229fa", vanilla = true },
        text = { it = "Ecco il pacco di Kravel, $N. E quando glielo consegni, digli... che se vuole altri ordini speciali, dovrà pagare il conto!", enHash = "9139b81a", vanilla = true },
        objectives = { it = "Porta Kravel's Parts a Kravel Koalbeard, nelle Shimmering Flats.", enHash = "60ea7783", vanilla = true },
        progress = { it = "Ce l'hai fatta ad arrivare a Ratchet e a prendere quei pezzi?", enHash = "39ed37ac", vanilla = true },
        reward = { it = "Ottimo, li hai presi! Ora dobbiamo portarli agli gnomi. Ma prima...\n\nTogliamo un piccolo pezzo...", enHash = "89ae7620", vanilla = true },
    },
    [1113] = {
        title = { it = "Hearts of Zeal", enHash = "fbfb650c", vanilla = true },
        text = { it = "Perché mi serve un tipo raro di guano, ti chiederai. Be', con questo esperimento voglio vedere che effetto possono avere l'una sull'altra due sostanze chimiche diametralmente opposte, soprattutto se unite entrambe a un agente sempre tossico, per ottenere i risultati più... raccapriccianti.\n\nTra le vette nord-orientali delle Tirisfal Glades si trova lo Scarlet Monastery. Là si radunano i folli discepoli della Crociata Scarlatta. Uccidili e portami i loro cuori zelanti.\n\nIl nostro intruglio sarà malvagissimo!", enHash = "32cb20b9", vanilla = true },
        objectives = { it = "Master Apothecary Faranell, nell'Undercity, vuole 20 Heart of Zeal.", enHash = "43d3e1b1", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata; dallo Scarlet Monastery? Mi serviranno molti cuori per questo delizioso esperimento!\n\nSenza dubbio anche Varimathras e la Signora Oscura saranno lieti di sbarazzarsi della feccia scarlatta...", enHash = "072c6da0", vanilla = true },
        reward = { it = "Caspita, quanto sangue mi hai portato, $N! I tuoi sforzi sono stati eccellenti!", enHash = "879d3387", vanilla = true },
    },
    [1114] = {
        title = { it = "Consegna agli gnomi", enHash = "6f18269b", vanilla = true },
        text = { it = "Ora che ho quel che mi serve, da' questi pezzi a Fizzle Brassbolts. Li aspetta da un pezzo: sono sicuro che non sentirà la mancanza del pezzettino che ho tolto dal suo ordine...\n\nE non mi metterei a parlargliene. Era piccolo e senza valore.\n\nFidati.", enHash = "4863e8cf", vanilla = true },
        objectives = { it = "Porta le Delicate Car Parts a Fizzle Brassbolts, nelle Shimmering Flats.", enHash = "e3f9e14a", vanilla = true },
        progress = { it = "Hai qualcosa per me? Che bello! Vediamo!", enHash = "f044acc2", vanilla = true },
        reward = { it = "Eccoli! I miei cricchetti idraulici e i bulloni a ripetizione! Andranno benissimo. Grazie!", enHash = "9f228a63", vanilla = true },
    },
    [1115] = {
        title = { it = "Il pettegolo", enHash = "f770afc6", vanilla = true },
        text = { it = "Ora che abbiamo fatto un servizio agli gnomi, è ora di fare un favore ai goblin!\n\nHo sentito che il pilota goblin Nazz Steamboil non si è sempre chiamato così. Mi chiedo perché abbia cambiato nome. Mi chiedo se sia un segreto e... mi chiedo quanto ci tenga a quel segreto.\n\nSe qualcuno sa la verità, è Krazek di Booty Bay, sulla punta meridionale di Stranglethorn. Parla con Krazek e chiedigli del nostro pilota goblin.\n\nSe riesci a farti dare informazioni utili, magari ci ricaviamo un profitto.", enHash = "c87b744d", vanilla = true },
        objectives = { it = "Parla con Krazek, a Booty Bay.", enHash = "5fa0c4df", vanilla = true },
        reward = { it = "Vuoi sapere di Nazz Steamboil? È un pilota da corsa là alle Shimmering Flats, no?\n\nSì, forse riesco a scoprire qualcosa su di lui... ma non sarà facile. Né veloce.\n\nNé a buon mercato.", enHash = "42359f17", vanilla = true },
    },
    [1116] = {
        title = { it = "Dream Dust nella palude", enHash = "0d9edb07", vanilla = true },
        text = { it = "Avere informazioni su Nazz è un bel favore, $N. Sì, proprio un bel favore. Ma sei $Gvenuto:venuta; fin qui dalle Shimmering Flats per averle... te la senti di viaggiare ancora un po'?\n\nMentre contatto le mie fonti, perché non mi raccogli qualcosa, eh?\n\nHmm... cosa potrebbe essere? Che ne dici di un po' di Dream Dust, dai cuccioli di drago dello Swamp of Sorrows. Sì, mi piacerebbe avere un po' di Dream Dust per la mia tabacchiera!\n\nProcuramela, $N, e ti darò le informazioni che cerchi.", enHash = "bb5bba81", vanilla = true },
        objectives = { it = "Porta 10 Speck of Dream Dust a Krazek, a Booty Bay. La Dream Dust si raccoglie dai cuccioli di drago dello Swamp of Sorrows.", enHash = "f04cd0ad", vanilla = true },
        progress = { it = "Già di ritorno? Ce l'hai la mia Dream Dust?", enHash = "0c6acfd7", vanilla = true },
        reward = { it = "Ma guarda un po'. Hai trovato la Dream Dust!\n\nE com'è la palude, $N? Non è facile mangiare caldo là, vero?", enHash = "7d4343bf", vanilla = true },
    },
    [1117] = {
        title = { it = "Voci per Kravel", enHash = "b7a9ecf4", vanilla = true },
        text = { it = "Ho dovuto spendere qualche favore, regalare una rara bottiglia di vino elfico e fare anche un bel po' di deduzioni da solo! Ma le informazioni che cerchi le ho trovate.\n\nTieni, ho scritto una lettera con qualche particolare molto interessante sul nostro amico Nazz Steamboil. Fanne quel che vuoi: per me è troppo pericoloso usarla.\n\nSolo, non dire a nessuno da chi l'hai avuta!", enHash = "1607a48b", vanilla = true },
        objectives = { it = "Porta i Goblin Rumors a Kravel Koalbeard, nelle Shimmering Flats.", enHash = "22efaf4e", vanilla = true },
        progress = { it = "Hai trovato qualcosa su Nazz Steamboil? Qualcosa che magari vorrebbe tenere segreto??", enHash = "08cb08aa", vanilla = true },
        reward = { it = "Bene bene! Questa è interessante... molto interessante. Eh, forse la prossima volta che lo vedo dovrei fare un inchino al pilota goblin.\n\nVale parecchio, $N. Sono sicuro che Nazz pagherà una piccola fortuna per tenere il suo segreto... segreto.", enHash = "b0b8a626", vanilla = true },
    },
    [1118] = {
        title = { it = "Ritorno a Booty Bay", enHash = "6f64bf75", vanilla = true },
        text = { it = "$N, sei $Gun:una; $C di cui posso fidarmi, sia per portare a termine il lavoro sia per tenere la bocca chiusa mentre lo fai.\n\nSto architettando un nuovo piano. È rischioso, ma se funziona potremmo fare un bel gruzzolo tutti e due! E credo che tu sia proprio la persona giusta per portarlo a compimento.\n\nPer cominciare, devi tornare a Booty Bay. Chiedo scusa, $Gbuon:buona; $N. So che il mio ultimo incarico ti ha già portato là. Ma questa volta parla con Crank Fizzlebub.\n\nDagli questa lettera. E se ha bisogno di aiuto, fa' del tuo meglio per aiutarlo. Ne varrà la pena.", enHash = "0990dc16", vanilla = true },
        objectives = { it = "Porta Kravel's Scheme a Crank Fizzlebub, a Booty Bay.", enHash = "e3a57b3d", vanilla = true },
        progress = { it = "Salve, salve. E cosa porta $Gun nobile:una nobile; $R come te quaggiù a Booty Bay?", enHash = "d39f07f2", vanilla = true },
        reward = { it = "Capisco. Kravel ha in mente un grosso piano. Ha una mente diabolica — ed è questo che mi piace di lui.\n\nQuindi ti servirà qualcosa per annebbiare il cervello, eh? Qualcosa di potente...\n\nMi chiedo se si potrebbe usare la miscela che Zanzil dà ai suoi zombi...", enHash = "b78681f1", vanilla = true },
    },
    [1119] = {
        title = { it = "Zanzil's Mixture e una Fool's Stout", enHash = "64197b75", vanilla = true },
        text = { it = "Ho capito come usare Zanzil's Mixture con la stout per ottenere una bevanda potente. Una Fool's Stout. Credo che sarà proprio quello che serve a Kravel, ma provala e fammi sapere come funziona.\n\nE, $N, non tenere questa roba troppo a lungo senza usarla. Zanzil's Mixture ha uno strano effetto sul lievito della stout: lo fa lavorare a pieno ritmo. Quindi non resterà fresca per sempre.", enHash = "bfe2eacc", vanilla = true },
        objectives = { it = "Riporta la Fool's Stout a Kravel, nelle Shimmering Flats.", enHash = "5aa8e656", vanilla = true },
        progress = { it = "Salve, $N. Fizzlebub è riuscito ad aiutarci?", enHash = "848b9a83", vanilla = true },
        reward = { it = "Magnifico! Fizzlebub ce l'ha fatta! Me ne ricorderò la prossima volta che lo vedrò.\n\nE grazie, $N. Stai facendo un ottimo lavoro, e tutti e due potremmo guadagnarci un sacco di soldi...", enHash = "725b8b4d", vanilla = true },
    },
    [1120] = {
        title = { it = "Fai ubriacare gli gnomi", enHash = "3d17ea90", vanilla = true },
        text = { it = "Dobbiamo provare la Fool's Stout su una delle squadre ai box. Se vuoi provarla sugli gnomi, allora tieni — prendi la stout e dalla allo Gnome Pit Boss.\n\nE non aspettare troppo. Prima o poi questa stout andrà a male.", enHash = "abfc28da", vanilla = true },
        objectives = { it = "Porta la Fool's Stout allo Gnome Pit Boss.", enHash = "d189c6da", vanilla = true },
        progress = { it = "Ciao! Hai qualcosa per me?", enHash = "09680fd3", vanilla = true },
        reward = { it = "Una stout? Che pensiero gentile! Grazie!\n\nCon la corsa in arrivo non dovremmo bere, ma... forse ai miei ragazzi un goccio non farebbe male. E poi, non può essere così forte, no?", enHash = "31881fa0", vanilla = true },
    },
    [1121] = {
        title = { it = "Fai ubriacare i goblin", enHash = "e5318447", vanilla = true },
        text = { it = "Dobbiamo provare la Fool's Stout su una delle squadre ai box. Se vuoi provarla sui goblin, allora tieni — prendi la stout e dalla al Goblin Pit Boss.\n\nE non aspettare troppo. Prima o poi questa stout andrà a male.", enHash = "c88dd850", vanilla = true },
        objectives = { it = "Porta la Fool's Stout al Goblin Pit Boss.", enHash = "2d634aa3", vanilla = true },
        progress = { it = "Che hai da guardare?", enHash = "abcdfa06", vanilla = true },
        reward = { it = "Cos'abbiamo qui? Alcol, eh?\n\nBe', non mi dispiace se ne beviamo solo un goccio...", enHash = "4b7def34", vanilla = true },
    },
    [1122] = {
        title = { it = "Torna a riferire a Fizzlebub", enHash = "5952703b", vanilla = true },
        text = { it = "Quella Fool's Stout ha funzionato alla grande! Ho scommesso sulla prossima corsa e... speriamo che la squadra che hai fatto ubriacare abbia conciato per le feste la propria auto!\n\nTi resta solo un altro compito — riporta questo biglietto a Crank Fizzlebub, a Booty Bay. Vorrà sapere che la prova è riuscita.\n\nE speriamo di poter avere altra Fool's Stout per le prossime corse!", enHash = "719bbd41", vanilla = true },
        objectives = { it = "Porta il Fool's Stout Report a Crank Fizzlebub, a Booty Bay.", enHash = "19ff95ad", vanilla = true },
        progress = { it = "Salve, $N. Com'è andata con quella stout? È roba forte, vero?", enHash = "7de03a3a", vanilla = true },
        reward = { it = "Qui dice che la Fool's Stout è stata un successo. È una bella notizia!\n\nSe mai ne vorrai ancora, fammelo sapere e ti farò raccogliere altra Zanzil's Mixture.", enHash = "3dd4ec74", vanilla = true },
    },
    [1123] = {
        title = { it = "Rabine Saturna", enHash = "da7823c3", vanilla = true },
        text = { it = "Per questo compito, il maggiordomo di Keeper Remulos a Moonglade — Rabine Saturna — cerca aiuto per esplorare le vaste desolazioni molto a ovest di Tanaris e di Un'Goro. Si trova a Nighthaven, il villaggio principale di Moonglade.\n\nVoglio farti capire quanto sia importante la tua presenza. Crescono le tensioni tra gli elfi della notte di Darnassus e il Cenarion Circle di Moonglade. Guarda oltre i confini tra le razze e attingi alla saggezza dei tuoi antenati nei rapporti con il Circle laggiù, $N. Buona fortuna.", enHash = "c2de90fc", vanilla = true },
        objectives = { it = "Parla con Rabine Saturna nel villaggio di Nighthaven, a Moonglade. Moonglade si trova tra il Felwood e Winterspring, e ci si arriva da un sentiero che parte dalla Timbermaw Hold.", enHash = "ea8b2429", vanilla = true },
        reward = { it = "Sono Rabine Saturna, e a nome di Keeper Remulos e di tutti gli abitanti di questa radura sacra ti do il benvenuto.\n\nApprezzo il tuo interesse e la tua voglia di aiutare il Cenarion Circle. I tauren hanno mostrato un'incredibile inclinazione verso i precetti di Cenarius, e grazie a loro l'Orda è accolta al sicuro in questa radura. La salvaguardia di Azeroth è un obiettivo che condividiamo.\n\nQui sei tra amici, $N.", enHash = "a52b4811", vanilla = true },
    },
    [1130] = {
        title = { it = "Melor manda notizia", enHash = "8ba55128", vanilla = true },
        text = { it = "$N, Melor Stonehoof ha sentito parlare delle tue imprese, e ti ha posto davanti un cammino.\n\nSe vuoi intraprenderlo, va' a Thunder Bluff e parla con Melor. Lo troverai sull'Hunter's Rise.", enHash = "cf1de352", vanilla = true },
        objectives = { it = "Parla con Melor Stonehoof a Thunder Bluff.", enHash = "e3c3d2a8", vanilla = true },
        reward = { it = "Dunque, $N, sei $Gvenuto:venuta;. E ora, sei $Gpronto:pronta; a viaggiare per terre lontane?\n\nSe è così, giovane $C, allora ascolta...", enHash = "e0696a54", vanilla = true },
    },
    [1131] = {
        title = { it = "Steelsnap", enHash = "3e1ce415", vanilla = true },
        text = { it = "A volte cacciamo per il cibo. A volte cacciamo per l'onore. E a volte cacciamo per meritare gli insegnamenti della Madre Terra.\n\nMa la caccia che ora ti affido non è nessuna di queste cose. È uccidere una creatura fuori dalla benedizione della Madre Terra.\n\nLa iena Steelsnap si aggira per le Thousand Needles, a sud delle Barrens. È un tiranno: attira a sé altre iene e sparge paura e sangue tra le bestie più pacifiche.\n\nTrova Steelsnap, $N. Trovalo, e sconfiggilo.", enHash = "0abdb855", vanilla = true },
        objectives = { it = "Porta Steelsnap's Rib a Melor Stonehoof, a Thunder Bluff.", enHash = "bf63f011", vanilla = true },
        progress = { it = "Hai sconfitto l'immondo Steelsnap, $N?", enHash = "fe464328", vanilla = true },
        reward = { it = "Sconfiggendo la creatura Steelsnap, hai purificato le Thousand Needles da una corruzione orribile.\n\nE questa, $N, è la tua lezione di oggi.", enHash = "42e8f7fc", vanilla = true },
    },
    [1132] = {
        title = { it = "Fiora Longears", enHash = "12be979e", vanilla = true },
        text = { it = "Oh, essere di nuovo per mare! Sentire il bacio del vento, e farmi cullare dalle onde come faceva la mia benedetta madre, tanto tempo fa!\n\nOh, vorrei avere la tua fortuna, $Gcaro:cara; $C, perché nel tuo futuro vedo il mare!\n\nÈ il mio mestiere raccontare alle anime desiderose della terra di Kalimdor, la terra delle opportunità! Se te la senti di tentare la sorte oltre il mare, prendi una nave da qui per il bel porto di Theramore. Là parla con la mia socia, l'elfa Fiora Longears.\n\nSarà lei ad avviarti nella tua avventura a Kalimdor!", enHash = "36c1c235", vanilla = true },
        objectives = { it = "Parla con Fiora Longears, a Theramore.", enHash = "fee2923e", vanilla = true },
        reward = { it = "Buona giornata a te! Ti manda Mr. Flint, di Menethil Harbor? Be', Mr. Flint sa giudicare bene le persone. Se ti ha mandato lui, non c'è dubbio che il tuo posto sia qui a Kalimdor!", enHash = "07fbda5c", vanilla = true },
    },
    [1133] = {
        title = { it = "Viaggio ad Astranaar", enHash = "f7f935d0", vanilla = true },
        text = { it = "Se sei appena $Gsbarcato:sbarcata; dalla nave di Menethil, la prima cosa che dovresti fare è... andare ad Astranaar. Di sicuro un membro dell'Alleanza pieno di entusiasmo come te può fare del vero bene laggiù. Parla con Shindrell Swiftfire e offri i tuoi servigi.\n\nMa non darti la pena di dire chi ti ha mandato. Shindrell non mi conosce...", enHash = "d749f315", vanilla = true },
        objectives = { it = "Parla con Shindrell Swiftfire, ad Astranaar.", enHash = "0528522e", vanilla = true },
        reward = { it = "Sei qui per offrire i tuoi servigi all'Alleanza, $N? L'aiuto è ben accetto, perché anche se la sua bellezza è rimasta... l'Ashenvale Forest non è più il luogo tranquillo di un tempo.", enHash = "4e35e25f", vanilla = true },
    },
    [1134] = {
        title = { it = "I Pridewing di Stonetalon", enHash = "80e07ba2", vanilla = true },
        text = { it = "Non siamo in guerra aperta con l'Orda, ma la nostra è una pace fragile. Spesso scopriamo i loro agenti che tramano contro di noi, ma lo fanno di nascosto.\n\nUna di queste mosse ci è stata rivelata da fonti nascoste a Theramore: dicono che gli orchi raccolgano il veleno dai Pridewing vicino al Mirkfallon Lake, nelle Stonetalon Mountains a sud. Poi gli assassini orchi usano quel veleno nelle loro incursioni mortali e segrete contro l'Alleanza!\n\nSe è vero, dobbiamo fermarli, $N. Dobbiamo togliere loro la fonte del veleno.", enHash = "dc2d5b11", vanilla = true },
        objectives = { it = "Porta 12 Pridewing Venom Sac a Shindrell Swiftfire ad Astranaar.", enHash = "527a8976", vanilla = true },
        progress = { it = "Hai le Pridewing Venom Sac, $N? Non possiamo permettere che gli orchi usino contro di noi il veleno di quelle bestie!", enHash = "6bcfa54f", vanilla = true },
        reward = { it = "Grazie, $N. Mi rattrista ordinare il massacro di creature che forse non aiutano di loro volontà i nostri nemici, eppure è mio dovere farlo.\n\nIl tuo cuore forse piangerà per i Pridewing che hai ucciso, $Gamico mio:amica mia;, ma che poi si riempia di gioia sapendo che i tuoi alleati sono al sicuro dal veleno dei Pridewing.", enHash = "afe50488", vanilla = true },
    },
    [1135] = {
        title = { it = "Il veleno di Highperch", enHash = "ae64d77d", vanilla = true },
        text = { it = "Come forse sai, i wyvern vengono spesso addomesticati dagli orchi per farne cavalcature. Ma quello che si sa meno è che il veleno di un wyvern, in certi ambienti, vale più della bestia stessa. Quindi, se non hai paura di andare un po' a caccia di wyvern, allora... ho un lavoro per te.\n\nC'è un posto chiamato Highperch nella terra di Thousand Needles, a ovest di qui. Gli Highperch Wyvern hanno un veleno potente. Potente, e prezioso.", enHash = "d56893c3", vanilla = true },
        objectives = { it = "Porta 10 Highperch Venom Sac a Fiora Longears, a Theramore.", enHash = "8b167a2b", vanilla = true },
        progress = { it = "Hai trovato Highperch, $N? Hai avuto fortuna con i wyvern laggiù?", enHash = "7bddc2a9", vanilla = true },
        reward = { it = "Ah, quasi tutte queste stanno per scoppiare di veleno, $N. Di solito sacche così si raccolgono solo dai wyvern giovani o dalle femmine fertili. Dev'essere stata una bella strage lassù a Highperch!", enHash = "3eeb5993", vanilla = true },
    },
    [1136] = {
        title = { it = "Frostmaw", enHash = "b633201f", vanilla = true },
        text = { it = "$N, è giunto il momento che tu viaggi verso terre lontane. Sei $Gpronto:pronta;.\n\nOra dai la caccia a Frostmaw, uno yeti nelle Alterac Mountains. È sfuggente, e il suo manto bianco si confonde con le nevi della sua montagna. Si mostra di rado.\n\nMa io ti mostrerò come attirare una creatura come lui. Ecco, prendi questa pergamena. Vi ho scritto sopra come si può adescare Frostmaw.\n\nOra va', $N. Il tuo viaggio è lungo e molte prove ti aspettano. Solo quando tornerai con Frostmaw's Mane il tuo compito sarà compiuto.", enHash = "1aae9e00", vanilla = true },
        objectives = { it = "Porta Frostmaw's Mane a Melor Stonehoof, a Thunder Bluff.", enHash = "e30aad3d", vanilla = true },
        progress = { it = "Sei $Gstato:stata; alle Alterac Mountains, $N? Hai affrontato lo sfuggente Frostmaw?", enHash = "f35a7b5f", vanilla = true },
        reward = { it = "Per trovare e sconfiggere Frostmaw servivano sia la forza sia l'astuzia, $N. Tu hai entrambe.\n\nIl tuo cammino ti ha portato nelle valli delle Thousand Needles e sulle alte montagne di Alterac. Un giorno ti condurrà per tutte le terre della Madre Terra, perché tale è la via del cacciatore.", enHash = "21d6ae9e", vanilla = true },
    },
    [1137] = {
        title = { it = "Notizie per Fizzle", enHash = "db1fb2a0", vanilla = true },
        text = { it = "L'indurium ha una resistenza al calore incredibile! Sono sicuro che andrà bene per i pistoni di Fizzle. Ma gli servirà vero minerale di indurium, non solo le scaglie.\n\nPer avere il minerale bisogna estrarlo nel profondo di Uldaman, ai confini settentrionali dei Badlands. È quella la vera fonte dell'indurium.\n\nSaluta Fizzle Brassbolts da parte mia e digli quel che ti ho detto.\n\nBuon viaggio, $N. E non mi stupirò se ci rivedremo: quando Fizzle saprà dell'indurium, probabilmente ti manderà a Uldaman a prenderlo!", enHash = "f6097f8b", vanilla = true },
        objectives = { it = "Parla con Fizzle Brassbolts, nelle Shimmering Flats.", enHash = "ef23c164", vanilla = true },
        reward = { it = "$N, sei $Gtornato:tornata;! Hai trovato Martek? Gli hai parlato? Cos'ha detto? Può aiutarci??\n\nDimmi, dimmi, dimmi!!", enHash = "ac213834", vanilla = true },
    },
    [1138] = {
        title = { it = "Frutto del mare", enHash = "b5b01a63", vanilla = true },
        text = { it = "Io adoro il granchio. Il granchio è il frutto del mare! Lo puoi fare al forno, alla brace, lesso e alla griglia. Si fa in padella, fritto e saltato. C'è l'insalata di granchio, la zuppa di granchio, lo spezzatino di granchio, il granchio al pepe, il granchio al limone, il granchio al whipper root e il granchio a sorpresa di Ironforge. E... e basta, direi.\n\nAdesso sono qui a pescare, quindi non posso procurarmi dei bei Fine Crab Chunk. Li prendi dai reef crawler e dagli encrusted tide crawler. Ci fai un sacco di cose. Lo puoi fare al forno, alla brace, lesso...", enHash = "d7aff7ff", vanilla = true },
        objectives = { it = "Raccogli 6 Fine Crab Chunk per Gubber Blump, ad Auberdine.", enHash = "b8962f62", vanilla = true },
        progress = { it = "...il granchio al limone, il granchio al whipper root e il granchio a sorpresa di Ironforge. E basta, direi.\n\nOh, ciao, $N. Ce li hai quei Fine Crab Chunk di cui ti parlavo?", enHash = "8a06f44f", vanilla = true },
        reward = { it = "Però, questi Fine Crab Chunk sono proprio quello che mi serve. Grazie, $N! Questo l'ho trovato mentre pescavo, tempo fa, e non so che farmene. Magari tu ci combini qualcosa. Di sicuro non ci fai nessun bel piatto di granchio.\n\nTi ho raccontato tutto sui granchi, vero?", enHash = "0a040b59", vanilla = true },
    },
    [1139] = {
        title = { it = "Le Tablet of Will perdute", enHash = "6c71b97b", vanilla = true },
        text = { it = "Abbiamo rallentato il clan Shadowforge tagliandolo fuori dalla Blackrock Spire, ma la missione di Hammertoe non è ancora compiuta. La sua morte non deve essere stata vana. Sognava di trovare la Tablet of Will: un frammento di pietra inciso con la magia dai titani in persona per aiutare a infondere la vita nelle loro creazioni, perché avessero una volontà propria, o almeno così dicono le leggende.\n\nDobbiamo ancora recuperare la tavoletta prima che la trovi il clan Shadowforge.\n\nTorna a Uldaman, trova la tavoletta e torna qui immediatamente.", enHash = "9c5e8aa9", vanilla = true },
        objectives = { it = "Trova la Tablet of Will e riportala ad Advisor Belgrum, a Ironforge.", enHash = "72cc38b9", vanilla = true },
        progress = { it = "La missione di Hammertoe deve essere portata a compimento, $N. Glielo devo.\n\nIl tuo ritorno a Uldaman è indispensabile non solo per questo scopo, ma anche per la sicurezza di tutto il popolo dei nani. Con la tavoletta nelle mani dei Dark Iron, chissà quanto diventerebbe potente il loro esercito di golem.", enHash = "85a07350", vanilla = true },
        reward = { it = "<Advisor Belgrum scuote la testa incredulo mentre gli porgi il frammento di pietra.>\n\n$N, è straordinario. Farò portare questo ai maghi del re il prima possibile. Vorranno studiarlo per scoprire se le leggende sono vere. Ma ne parleremo un'altra volta: hai aiutato il nostro popolo più di quanto mi sarei mai aspettato. Grazie.", enHash = "6d25e383", vanilla = true },
    },
    [1140] = {
        title = { it = "La Tower of Althalaxx", enHash = "ccbcdb54", vanilla = true },
        text = { it = "La scrittura degli orchi è poco meglio degli scarabocchi di un bambino. Molti del mio ordine storsero il naso quando scelsi di impararne la lingua, ma l'ho trovato utile per capire meglio i miei nemici.\n\nDagli scarabocchi di Ilkrud sembra che Athrikus possieda ancora due gemme dell'anima, e che siano custodite a Night Run e a Satyrnaar, zone in mano ai satiri nel nord-est di Ashenvale.\n\nSta' $Gattento:attenta; là fuori, $N: i templi intrisi di sangue dei satiri possono turbare anche $Gun:una; $C $Gnavigato:navigata; come te.", enHash = "ec8b535f", vanilla = true },
        objectives = { it = "Libera le anime degli Alti Nobili intrappolate a Night Run e a Satyrnaar, poi torna da Delgren the Purifier, a Maestra's Post.", enHash = "8d83a7b7", vanilla = true },
        progress = { it = "Una volta sentii sussurrare che la storia dei satiri è in qualche modo legata a quella degli elfi della notte, ma ho trovato i miei stimati ospiti restii a parlarne.", enHash = "45fbd460", vanilla = true },
        reward = { it = "Forse ai satiri è stato permesso di restare nella foresta troppo a lungo. Ne parlerò con Elissa la prossima volta che andrò ad Auberdine.\n\nComunque sia, con le gemme dell'anima distrutte il potere di Athrikus sarà molto ridotto. Dobbiamo cogliere l'occasione per eliminare lui e il suo culto.", enHash = "0ac08e61", vanilla = true },
    },
    [1141] = {
        title = { it = "La famiglia e la canna da pesca", enHash = "93a1ae13", vanilla = true },
        text = { it = "Io amo pescare. La famiglia Blump è famosa per la pesca. Mi chiamo Gubber Blump; io pesco.\n\nDa queste parti c'è un pesce che mi piace prendere, si chiama Darkshore Grouper. Una volta uscivo in barca a pescarlo, ma non esce più nessuna barca da quando si sono piazzati qui quei murloc cattivi. Scommetto che si stanno mangiando anche tutti i grouper.\n\nDimmi, mi vuoi aiutare a prendere qualche Darkshore Grouper? Se lo fai, ti do una Blump Family Fishing Pole originale! È una canna davvero buona per prendere i pesci.", enHash = "be96943a", vanilla = true },
        objectives = { it = "Pesca 6 Darkshore Grouper per Gubber Blump, ad Auberdine.", enHash = "b76fa31e", vanilla = true },
        progress = { it = "Ci sono un sacco di buoni piatti che si fanno con i Darkshore Grouper. Sono buoni da mangiare, ma secondo me è più divertente prenderli.\n\nNe hai già presi, di Darkshore Grouper?", enHash = "e3ad3f69", vanilla = true },
        reward = { it = "Questi sì che sono dei bei grouper, $N! Grazie dell'aiuto!\n\nSei $Gbravo:brava; a pescare almeno quanto mia cugina, Graun Blump. Pure lei ha la barba e odora un po' strano, ma questo non le impedisce mica di pescare. Direi che hai la stoffa per usare una Blump Family Fishing Pole.", enHash = "65a348d2", vanilla = true },
    },
    [1142] = {
        title = { it = "La vita si spegne", enHash = "7e5392f1", vanilla = true },
        text = { it = "Non mi resta molto da vivere... così... così... debole.\n\n...il c-c-coraggioso nano, Lonebrow, è stato mandato ad a-a-avvertire Falfindel...\n\nMa prima che io... m-m-muoia...\n\n...mia moglie, Treshala... il suo ciondolo del legame con me... rubato... da uno degli i-i-immondi aggressori...\n\nTrovalo, p-p-per favore... e riportalo a Treshala, a Darnassus...\n\n...insieme alla n-n-notizia della mia solitaria... morte.", enHash = "8ca712cf", vanilla = true },
        objectives = { it = "Trova Treshala's Pendant e riportalo a Treshala Fallowbrook, a Darnassus.", enHash = "563bf83c", vanilla = true },
        progress = { it = "Cosa ti porta a casa mia, $R?", enHash = "1eb4d52b", vanilla = true },
        reward = { it = "No!\n\nNon è giusto. Oh, mondo crudele e intollerabile!\n\nOra devo portare questo fardello di dolore e non lasciare che l'opera di Heralath muoia con lui.\n\nHai avuto coraggio a venire da un luogo così pericoloso, $N. Ma ora, ti prego, lasciami.\n\nIn solitudine piangerò.", enHash = "841ebf37", vanilla = true },
    },
    [1143] = {
        title = { it = "La Tower of Althalaxx", enHash = "ccbcdb54", vanilla = true },
        text = { it = "Capisco. Be', se quello che dici è vero, allora è il momento di colpire. Credo che Athrikus stia in cima alla torre. Sta' $Gattento:attenta;, però: è circondato da molti stregoni potenti, ben più letali di quelli che hai affrontato finora.", enHash = "eb725533", vanilla = true },
        objectives = { it = "Uccidi Athrikus Narassin e porta la sua testa a Balthule Shadowstrike, vicino alla Tower of Althalaxx.", enHash = "5391db5f", vanilla = true },
        progress = { it = "Athrikus Narassin è uno stregone antico e potente. Forse dovremmo aspettare l'aiuto di Delgren, ma è evidente che aveva molta fiducia in te, per mandarti $Gda solo:da sola;.", enHash = "4c38bc6b", vanilla = true },
        reward = { it = "Con la morte di Athrikus spero che le forze demoniache di questa zona vengano respinte. Non ho dubbi che si riorganizzeranno e torneranno, ma allora saremo ancora più pronti ad affrontare la loro minaccia.", enHash = "9d23e480", vanilla = true },
    },
    [1144] = {
        title = { it = "Willix the Importer", enHash = "c0549320", vanilla = true },
        text = { it = "Finalmente sono arrivati i soccorsi!\n\nNon hai idea di quanto tempo mi abbiano tenuto prigioniero qui. Non ricordo più l'ultima volta che ho visto l'esterno di questo posto.\n\nVedi, io sono un imprenditore. Sempre a caccia di un rame, come si dice. Ho sentito dire che Mebok Mizzyrix pagava bene i Redleaf Tuber di questo porcile. Pensavo che sarebbe stato un lavoretto facile, dentro e fuori. Come vedi, mi sbagliavo un pochino!\n\nComunque, se sei così gentile da aiutarmi a uscire di qui, ti ripagherò come si deve.", enHash = "cc2715eb", vanilla = true },
        objectives = { it = "Scorta Willix the Importer fuori dal Razorfen Kraul.", enHash = "4d7831e9", vanilla = true },
        reward = { it = "Grazie ancora, $Gamico:amica;! Te l'avevo detto che ti avrei ripagato come si deve.", enHash = "c6f4bc5e", vanilla = true },
    },
    [1145] = {
        title = { it = "Lo sciame cresce", enHash = "2d037ce9", vanilla = true },
        text = { it = "Molti viaggiatori passati dal Crossroads mi hanno aiutato a raccogliere uova nel Field of Giants, e molti hanno storie su quanto sono letali quelle creature. Ne ho sentite abbastanza da considerare quegli insetti una minaccia molto più grande di quanto i miei padroni credessero all'inizio.\n\nMi serve un corriere che vada a Orgrimmar a incontrare Belgrom Rockmaul. Non è una faccenda semplice, e dovrebbe andarci qualcuno che prenda l'incarico sul serio.\n\nBelgrom di solito si trova fuori dalla casa della gilda dei guerrieri.", enHash = "7acc2d65", vanilla = true },
        objectives = { it = "Consegna la Korran's Sealed Note a Belgrom Rockmaul, a Orgrimmar.", enHash = "1f910aee", vanilla = true },
        progress = { it = "Ti invidio, $C. Hai l'aria di chi è stato fuori dalle mura di Orgrimmar per un po'.\n\nIo stesso viaggerei nel nome del Capoguerra, se Thrall non avesse bisogno delle mie capacità qui in città. Ma ci guida bene, e mi fido del suo giudizio — resto qui finché ha bisogno di me.", enHash = "bbd0620a", vanilla = true },
        reward = { it = "Ah, un biglietto da Korran. È un servitore fedele ormai da tempo. Mi chiedevo come andassero i suoi incarichi al Crossroads.", enHash = "5d62641c", vanilla = true },
    },
    [1146] = {
        title = { it = "Lo sciame cresce", enHash = "2d037ce9", vanilla = true },
        text = { it = "Quindi Korran è arrivato a una conclusione simile su questi insetti: sembrano una minaccia più grande di quanto pensassimo.\n\nQualche giorno fa un cacciatore è tornato da me da Thousand Needles, quasi morto. Era con un gruppo d'assalto mandato a cacciare una squadra di scavo nanica dalle Shimmering Flats. Durante l'attacco altri di questi insetti sono sbucati da una grotta nel sito di scavo e hanno quasi ucciso il gruppo.\n\nLi guidava Moktar Krin, e si sono rifugiati ai confini delle Shimmering Flats. Portagli questo biglietto.", enHash = "2bd0af6b", vanilla = true },
        objectives = { it = "Consegna Belgrom's Sealed Note a Moktar Krin, a Thousand Needles.", enHash = "ad6554df", vanilla = true },
        progress = { it = "È la guerra a portare me e il mio gruppo qui, nelle Shimmering Flats, $C. E te cosa ci porta?", enHash = "14ba65a5", vanilla = true },
        reward = { it = "Non badare all'eco tonante che rimbomba sulle pareti delle montagne. I goblin e gli gnomi sono là nelle Flats a correre l'uno contro l'altro su certe atrocità create da quella che chiamano scienza. Qui a Thousand Needles ci sono minacce più grosse, e una di queste ha ucciso più di metà della mia banda di guerra.\n\nMa restiamo qui finché non avremo notizie da Belgrom, a Orgrimmar. Fino ad allora teniamo la posizione e restiamo vigili.", enHash = "2a561c5b", vanilla = true },
    },
    [1147] = {
        title = { it = "Lo sciame cresce", enHash = "2d037ce9", vanilla = true },
        text = { it = "Hmm. Pare che Belgrom consideri quei mostri una minaccia. Vuole che vengano ricacciati nelle profondità da cui sono strisciati fuori.\n\nImmagino che uccidere i nani mandati dalla Lega degli Esploratori non sia bastato: adesso devo mandare in un'altra battaglia una banda di guerra mezza morta. Non possiamo farcela da soli, non nelle condizioni in cui siamo. Il sito di scavo è a sud di qui. Non dovrebbero esserci altri nani di cui occuparsi. Te la senti di impugnare una lama o un bastone e di fare la tua parte per aiutarci?", enHash = "9bbf4486", vanilla = true },
        objectives = { it = "Uccidi 5 Silithid Searcher, 5 Silithid Hive Drone e 5 Silithid Invader, poi torna da Moktar Krin, a Thousand Needles.", enHash = "d11acef0", vanilla = true },
        progress = { it = "Con tutti i viaggiatori che vanno alle Flats per quelle corse, sono sicuro che riusciremo a convincere abbastanza cercatori d'avventura ad aiutarci a ricacciare indietro quegli insetti. Io e la mia banda non potremo muoverci finché non sarà fatto.", enHash = "539dc655", vanilla = true },
        reward = { it = "Ah! Quell'icore di cui sei $Gcoperto:coperta; ti rende perfino più $Gcarino:carina;, $N! Anche se allo stesso tempo ti fa puzzare da morire. Non stare troppo vicino ai kodo: o scateni una fuga in massa o li mandi in calore.\n\nCredo che i miei compagni saranno d'accordo: già solo il tuo odore è la prova che hai fatto la tua parte per aiutarci contro quelle creature insettoidi. Grazie, $N.", enHash = "6c32151b", vanilla = true },
    },
    [1148] = {
        title = { it = "Parti dello sciame", enHash = "b2608f40", vanilla = true },
        text = { it = "Esamini con attenzione il carapace. Rigirandolo tra le mani ti accorgi che le placche chitinose si intrecciano in modo da renderlo incredibilmente resistente. Non è come niente che tu abbia mai visto. Esamini meglio il resto del cadavere e capisci che queste creature sono molto potenti e molto evolute.\n\nGuardando di nuovo il carapace, pensi che a Korran piacerebbe studiare altre creature come questa. Potrebbe aiutarlo a capire cosa sono e da dove vengono.", enHash = "b167346b", vanilla = true },
        objectives = { it = "Porta 1 Silithid Heart, 5 Silithid Talon e 3 Intact Silithid Carapace a Korran, al Crossroads.", enHash = "f0081916", vanilla = true },
        progress = { it = "Ah, è passato tanto tempo dall'ultima volta che sei $Gvenuto:venuta; a trovarmi, $N. Cosa posso fare per te oggi? Hai l'aria di chi ha visto la battaglia di recente. Bene... bene per l'Orda e bene per te. Più battaglie hai visto, più sarai utile; e anche più forte.", enHash = "7ad172b2", vanilla = true },
        reward = { it = "Ahh, hai visto Moktar di recente? Lui bada sempre a me. Mi dispiace sentire che passa il tempo a sorvegliare la sua piccola banda di guerra invece di andare in battaglia, ma sono sicuro che si gode un bel po' l'uccidere i membri della Lega degli Esploratori.\n\nHai fatto bene a portarmi questi campioni, $N. Insieme alle uova che stiamo trovando nel Field of Giants, dovrebbero darmi un buon punto di partenza per capire cosa sono questi insetti e cosa vogliono.", enHash = "fcc0ddd9", vanilla = true },
    },
    [1149] = {
        title = { it = "Prova di fede", enHash = "93cad247", vanilla = true },
        text = { it = "Allora, mi hai cercato, o forse è il destino a portarti da me? Non importa. Ora sei qui, e il tuo viaggio ricomincerà daccapo.\n\nUn essere è fatto di molte facce: lo spirito, il corpo, la mente. Alcune si possono misurare con le tradizioni di un popolo. Di altre possiamo solo sperare che esistano dentro di noi. Se sei d'accordo, metterò alla prova alcune delle facce che hai dentro.\n\nSe passerai le prove, diventerai più forte. Se fallirai, ti renderai conto della vastità del Nether.\n\nLa prima è una Prova di Fede.", enHash = "d7176f2b", vanilla = true },
        objectives = { it = "Se hai fede, salta dalle assi che si affacciano su Thousand Needles.", enHash = "ac302e1b", vanilla = true },
        progress = { it = "La fede. È molto più importante di quanto qualcuno creda.\n\nA volte non conta in cosa credi. Conta soltanto che tu creda in qualcosa.", enHash = "f6b1c8ef", vanilla = true },
        reward = { it = "È solo davanti a un'avversità imprevista che cominciamo a vedere quanto è forte il nostro spirito. Hai fatto il salto della fede pur non avendo alcuna garanzia di sopravvivere. La tua mente è aperta e il tuo spirito è pronto per quel che verrà.\n\nSe te la senti, la prossima prova è pronta.", enHash = "34863005", vanilla = true },
    },
    [1150] = {
        title = { it = "Prova di resistenza", enHash = "de158bcc", vanilla = true },
        text = { it = "Mi fa piacere vedere che il tuo coraggio resta saldo dopo quel che hai già fatto. Dato che la tua fede è intatta, è arrivato il momento di mettere alla prova il tuo corpo.\n\nPer prima cosa una prova di resistenza. Va' con degli amici alla Roguefeather Den, a ovest di Freewind Post. Arriva fino in fondo alla loro tana e distruggi le loro provviste. A quel punto dovresti averne scatenato la furia, e se riuscirai a sopravvivere abbastanza a lungo verrà a prenderti Grenka Bloodscreech in persona: uccidila e portami il suo artiglio per completare la prova.", enHash = "6a07f3a1", vanilla = true },
        objectives = { it = "Porta Grenka's Claw a Dorn Plainstalker, a Thousand Needles.", enHash = "887cef76", vanilla = true },
        progress = { it = "Devi essere $Gpronto:pronta; nello spirito, nel corpo e nella mente per le sfide che ti aspettano.\n\nTroppo spesso corriamo avanti prima di essere pronti. Considero un mio dovere verso i giovani, a qualunque tribù appartengano, prepararli ai pericoli che potranno incontrare una volta lasciata la sicurezza di casa.", enHash = "c2142c4f", vanilla = true },
        reward = { it = "Grenka era potente, perfino per $Gun:una; $R come te. Dovresti essere $Gfiero:fiera; di quel che hai compiuto oggi.\n\nNella prova di fede hai mostrato forza di spirito, e ora hai mostrato resistenza in battaglia affrontando le arpie Roguefeather, ma è arrivato il momento di una nuova prova.", enHash = "134807be", vanilla = true },
    },
    [1151] = {
        title = { it = "Prova di forza", enHash = "019e69dc", vanilla = true },
        text = { it = "Al tempo degli Antichi Dei gli elementali abitavano gran parte di questo mondo. Veneravano gli Antichi Dei, e gli Dei, con il loro potere, tenevano gli elementali legati a questo mondo. Quando gli Antichi Dei furono banditi, gli elementali svanirono dal nostro mondo e ora tornano solo al comando di maghi potenti.\n\nCi sono però delle eccezioni. Alcuni elementali erano abbastanza potenti da restare qui da soli. Uno di questi è Rok'Alim.\n\nPer mettere alla prova la tua forza, trova Rok'Alim a Thousand Needles e uccidilo.", enHash = "b85e05e2", vanilla = true },
        objectives = { it = "Porta Fragments of Rok'Alim a Dorn Plainstalker, a Thousand Needles.", enHash = "19292721", vanilla = true },
        progress = { it = "Le tribù dei centauri di Thousand Needles chiamano Rok'Alim anche il Percussore, per il tuono che fanno i suoi pugni quando prende a botte le creature abbastanza coraggiose, o stupide, da mettersi sulla sua strada.", enHash = "c743d2b1", vanilla = true },
        reward = { it = "La Prova di Forza è compiuta. Hai mostrato forza e coraggio, e ora sei $Gpronto:pronta; per l'ultima prova prima che questi riti siano completati.", enHash = "8d786023", vanilla = true },
    },
    [1152] = {
        title = { it = "Prova di sapienza", enHash = "c2b6e611", vanilla = true },
        text = { it = "Il tuo tempo con me sta per finire. Io ho molto sapere, ma la Prova di Sapienza non tocca a me. Ci sono lezioni da imparare e luoghi da visitare su cui altri rivendicano il dominio.\n\nSe sei $Gpronto:pronta;, cerca Braug Dimspirit: è uno sciamano di grande saggezza. Ti metterà ancora alla prova, quindi ascolta bene le sue parole, $N.\n\nQuando sei $Gpronto:pronta;, trova il tunnel che collega le Stonetalon Mountains con Ashenvale: Braug abita lì vicino. E sta' $Gattento:attenta;, $N, gli elfi della notte potrebbero voler ostacolare la tua prova.", enHash = "22f6468e", vanilla = true },
        objectives = { it = "Trova Braug Dimspirit vicino all'ingresso del Talondeep Path, nelle Stonetalon Mountains.", enHash = "51146ae2", vanilla = true },
        reward = { it = "I giorni e le notti si fanno più freddi in tutto il mondo mentre i goblin violentano la terra e gli elfi della notte puntano il dito contro le razze più giovani. I Reietti e gli orchi non sono i soli responsabili delle sofferenze che si trovano in tutta Kalimdor e in Lordaeron. Molte delle razze intelligenti hanno contribuito al dolore del mondo. Dorn lo sa, e ti ha mandato da me perché hai mostrato le qualità necessarie per capirlo anche tu.\n\nOra sei davanti a Braug.", enHash = "49d9128d", vanilla = true },
    },
    [1153] = {
        title = { it = "Un nuovo campione di minerale", enHash = "5f91d0c7", vanilla = true },
        text = { it = "$C, mi hai aiutato bene in passato. Il capoguerra finora è soddisfatto di quello che ho ottenuto, e mi chiede di continuare con rinnovata determinazione. Il mio onore mi impone di darti il giusto riconoscimento davanti al capoguerra per tutto quello che hai fatto, ma prima vorrei chiederti ancora aiuto.\n\nDi recente sono arrivati dei viaggiatori da sud, da un posto chiamato Thousand Needles. Là hanno ucciso un kobold che aveva un campione di minerale insolito, ma non hanno voluto venderlo. Voglio un campione di quel minerale da esaminare.", enHash = "cdcfe197", vanilla = true },
        objectives = { it = "Trova un Unrefined Ore Sample su un Gravelsnout Digger o Surveyor e portalo a Tatternack Steelforge, a Camp Taurajo, nelle Barrens.", enHash = "41515dad", vanilla = true },
        progress = { it = "Ho rivisto quei viaggiatori — quelli che non volevano vendermi un campione del minerale. Gli sputo addosso, per non aver aiutato il capoguerra.\n\nChe muoiano in battaglia come codardi e non come guerrieri, come sarebbe diritto di tutti i popoli che si alleano con l'Orda.", enHash = "1fc11df1", vanilla = true },
        reward = { it = "Un buon campione, $N. Un ottimo campione davvero.\n\nQuei viaggiatori non possono più vantarsi con me del minerale che hanno trovato, ora che tu ci sei $Griuscito:riuscita;.\n\nMi metterò al lavoro subito. Se si rivelerà abbastanza resistente, manderò al capoguerra un'arma forgiata con questo materiale, per mostrargli il nostro successo.\n\nNon dimenticherò il tuo aiuto, $C.", enHash = "9eeea3a7", vanilla = true },
    },
    [1154] = {
        title = { it = "Prova di sapienza", enHash = "c2b6e611", vanilla = true },
        text = { it = "Hai superato le prove di Dorn e ora cerchi di superare la prossima. Molto bene. Ma finora le tue sfide sono state roba da bambini. È facile mettere alla prova il tuo corpo: la tua mente è tutta un'altra faccenda.\n\nTe la spiego in modo semplice: trova il libro che ti dirò, studialo e rispondi alla mia domanda sul suo contenuto.\n\nQuale libro, ti starai chiedendo? The Legacy of the Aspects. Si trova in fondo a Dor'danil, nell'Ashenvale meridionale, protetto dai druidi morti e dai loro carnefici.", enHash = "75a8f959", vanilla = true },
        objectives = { it = "Trova la Legacy of the Aspects e portala a Braug Dimspirit, vicino all'ingresso del Talondeep Path, nelle Stonetalon Mountains.", enHash = "b39ea9f6", vanilla = true },
        progress = { it = "Portami il libro dopo che l'avrai studiato. Non ti farò la domanda finché non me lo avrai consegnato.", enHash = "325e5fe5", vanilla = true },
        reward = { it = "Questo è il libro che ti avevo detto. C'è speranza che tu risponda bene alla mia domanda, allora... a meno che tu non ti sia $Gdimenticato:dimenticata; di studiarne il contenuto.\n\nQuando sei $Gpronto:pronta;, parlami di nuovo e ti farò una domanda.", enHash = "f50c198f", vanilla = true },
    },
    [1159] = {
        title = { it = "Prova di sapienza", enHash = "c2b6e611", vanilla = true },
        text = { it = "Ben fatto, $N. Hai superato la prima parte della Prova di Sapienza, ma c'è ancora una domanda a cui rispondere. E non tocca a me farla.\n\nCerca Parqual Fintallas, a Lordaeron City. Era un grande storico degli umani, prima che la Piaga lo cogliesse. Ora continua a cercare l'illuminazione, ma di natura diversa.\n\nTi chiederà qualcos'altro prima di farti la domanda, ma finora te la sei cavata da maestro: sono sicuro che supererai anche il suo ostacolo.", enHash = "10d2de15", vanilla = true },
        objectives = { it = "Trova Parqual Fintallas, nell'Undercity.", enHash = "99b6b0d9", vanilla = true },
        reward = { it = "Ti manda Braug? Impossibile.\n\n<Parqual ti squadra da capo a piedi.>\n\nHai affrontato Dor'Danil, hai fatto il salto della fede, hai combattuto e sopraffatto un elementale potente? Bah! Probabilmente sei una farsa, $Gun avventuriero qualsiasi:un'avventuriera qualsiasi; che ha sentito due chiacchiere in taverna. E adesso credi di avere le carte in regola per superare la mia prova. E sia... $C.", enHash = "1c103874", vanilla = true },
    },
    [1160] = {
        title = { it = "Prova di sapienza", enHash = "c2b6e611", vanilla = true },
        text = { it = "Ti dirò che cosa devi cercare, e ti farò perfino la mia domanda, ma non perché tu voglia dimostrare il tuo valore. La conoscenza è molto più importante della forza. Anche se altri sembrano superarti in abilità, la tua conoscenza del mondo varrà di più.\n\nVa' al Monastery, nel nord delle Tirisfal Glades. Nella sua biblioteca si trova un libro intitolato Beginnings of the Undead Threat. I paladini di quel luogo, ora corrotti, lo usavano per addestrarsi a combattere quelli come me.\n\nPortamelo.", enHash = "442c0892", vanilla = true },
        objectives = { it = "Trova The Beginnings of the Undead Threat e riportalo a Parqual Fintallas, nell'Undercity.", enHash = "bd6cbd25", vanilla = true },
        progress = { it = "Spero che tu abbia fatto soffrire un po' la Crociata Scarlatta prima di rubarle il libro.\n\nLe mie opinioni su quella gente non sono infondate. Un tempo la Crociata avrà anche seguito la Luce, ma ora cerca di distruggere qualunque creatura non si sia schierata con la sua religione. Crede che tutti i non morti, Reietti o no, vadano purificati, e che chi viaggia nelle sue terre sia pazzo o soggiogato dalla potente magia dei non morti. Idioti. Idioti e stolti, tutti quanti.", enHash = "8653b557", vanilla = true },
        reward = { it = "Questo è il libro che ti ho mandato a cercare.\n\n<Parqual passa lentamente la mano sulla copertina del libro, fissandolo.>\n\nE ora vuoi una domanda per dimostrare che la tua mente è potente quanto il tuo corpo e il tuo spirito. Se hai studiato il libro abbastanza a lungo, ti farò la tua domanda e avrai chiuso con queste prove!", enHash = "ce4eee97", vanilla = true },
    },
    [1164] = {
        title = { it = "Rubare ai ladri", enHash = "f06cd994", vanilla = true },
        text = { it = "Quella sgualdrina! Quella scrofa! Kenata è ancora viva; la sua famiglia è sana e prospera mentre io soffro. Reietti, davvero!\n\nLa mia famiglia non c'è più, portata via dalla piaga. Anche la nostra tenuta è andata perduta, saccheggiata e bruciata durante la guerra. E dopo tutto questo, lei e i suoi figli pidocchiosi hanno avuto la sfacciataggine di rubare gli unici beni preziosi che mi erano rimasti.\n\nNon m'importa più delle cose che hanno rubato. Ora voglio le loro teste!\n\nUccidili per me! Va' alla Dabyrie Farmstead, in Arathi, a nord-est di Refuge Point.", enHash = "fdf02862", vanilla = true },
        objectives = { it = "Porta Kenata's Head, Fardel's Head e Marcel's Head dei Dabyrie a Genavie Callow, nell'Undercity.", enHash = "6d1adfa2", vanilla = true },
        progress = { it = "Uccidili tutti e portami le loro teste!", enHash = "dd48fa24", vanilla = true },
        reward = { it = "Sei davanti a me come una figura di vendetta, e mi inchino davanti a te per ringraziarti.\n\nCon la morte di quella vacca, e sapendo che il loro seme non si spargerà più sulla faccia di Azeroth, posso dedicare le mie energie a qualcosa di più redditizio. Spero che tu abbia saccheggiato la loro fattoria dopo averli fatti fuori.", enHash = "1e2fd25b", vanilla = true },
    },
    [1166] = {
        title = { it = "La preoccupazione di Overlord Mok'Morokk", enHash = "464e8620", vanilla = true },
        text = { it = "Inchinati davanti a Overlord Mok'Morokk!\n\nRexxar fare me potente capo di Stonemaul Clan!\n\nIo buon capo. Io tenere clan al sicuro.\n\nGrossi draghi venire e dare fuoco a vecchia casa. Io ogre furbo. Trovare nuova casa per clan qui.\n\nLasciare vecchia casa così in fretta, io dimenticare roba. $GPiccolo:Piccola; $R, tu andare prendere mie cose. Andare a sud e trovare mio grog buonissimo, mio tabacco da fiuto e mia cassaforte. A me piacere tu dopo che tu fare questo. Tu guardare in Den of Flame e Stonemaul Ruins... loro essere lì, io sicuro!", enHash = "b7444415", vanilla = true },
        objectives = { it = "Overlord Mok'Morokk, a Brackenwall Village, vuole che tu recuperi il suo grog, il suo tabacco da fiuto e la sua cassaforte nel Dustwallow Swamp.", enHash = "45c34583", vanilla = true },
        progress = { it = "Io avere sete di grog. A me mancare anche tabacco da fiuto. Dove essere cassaforte? Tu andare prendere per Overlord Mok'Morokk.\n\nAndare cercare a sud in vecchia casa. Io troppo occupato a guidare ogre per andare prendere.", enHash = "6a4ca3a4", vanilla = true },
        reward = { it = "Tu essere $Gun bravo:una brava; $R. A me mancare tanto mie cose. A me piacere tu adesso.", enHash = "bc146606", vanilla = true },
    },
    [1167] = {
        title = { it = "La Tower of Althalaxx", enHash = "ccbcdb54", vanilla = true },
        text = { it = "Prima di affrontare Athrikus, sarebbe saggio che ti consultassi con Balthule. Non ho dubbi che abbia vegliato con attenzione sulla torre, e potrebbe avere notizie sugli ultimi sviluppi.", enHash = "7e014282", vanilla = true },
        objectives = { it = "Parla con Balthule Shadowstrike, vicino alla Tower of Althalaxx.", enHash = "01fec8a9", vanilla = true },
        reward = { it = "Ah, che piacere rivederti, $N! Qui stanno succedendo le cose più strane, sono contento che tu sia $Garrivato:arrivata;!\n\nÈ stato stranissimo, $N. Sembrava tutto normale — be', normale per quanto lo siano le cose da queste parti — e poi all'improvviso c'è stato un lampo accecante dalla stanza in cima alla torre. Poi sono arrivate le urla. Le grida squarciavano l'aria, e ogni tanto un fulmine colpiva il terreno. Che sta succedendo?", enHash = "7b0801bc", vanilla = true },
    },
    [1168] = {
        title = { it = "L'esercito del drago nero", enHash = "504360c9", vanilla = true },
        text = { it = "Mok'Morokk è stato fatto signore supremo da Rexxar. Lui tenere più a potere che a ogre.\n\nDraghi neri uccidere molti ogre. Uccidere moglie di Tharg. Mok'Morokk dire a noi di scappare. Fare noi venire qui.\n\nOgre dovere combattere. Ogre non bravi a scappare. A Mok'Morokk importare solo di Mok'Morokk.\n\nIo chiamare casa Stonemaul Ruins. A me piacere stare a sud. Questo posto non casa.\n\nAiutare ogre combattere esercito di drago nero. Io volere vendetta. Io volere tornare a casa.", enHash = "48d13506", vanilla = true },
        objectives = { it = "Tharg, a Brackenwall Village, vuole che tu uccida 15 Firemane Scout, 10 Firemane Ash Tail e 5 Firemane Scalebane.", enHash = "41f25278", vanilla = true },
        progress = { it = "Mok'Morokk dire a tutti ogre di restare e tenere al sicuro questo posto. Io pensare ogre dovere uccidere esercito di drago nero e riprendere vecchia casa.\n\nTu aiutare ogre riprendere casa. Aiutare ogre avere vendetta.", enHash = "cb2f691c", vanilla = true },
        reward = { it = "Tu uccidere molti di esercito di drago nero. Tu $Gun:una; $R $Gcoraggioso:coraggiosa;.\n\nTu fare Tharg contento.", enHash = "2d8ace42", vanilla = true },
    },
    [1169] = {
        title = { it = "Identificare la covata", enHash = "f2b5a97b", vanilla = true },
        text = { it = "Mentre quel vile sciocco di Mok'Morokk si crogiola nel potere, e Tharg lotta con i demoni del dolore e della vendetta e si contende la guida del clan, sembra che io sia l'unico a preoccuparsi di scoprire l'origine dell'aggressione alla nostra vecchia casa.\n\nPerché quello sguardo perplesso, $N? Ti aspettavi che parlassi come un rozzo attaccabrighe solo perché sono un ogre?\n\nOra torniamo agli affari: portami i cuori e le lingue dei cuccioli e dei piccoli appena nati. Risalirò alla radice di questo male...", enHash = "a234c47e", vanilla = true },
        objectives = { it = "Draz'Zilb, a Brackenwall Village, vuole che tu gli porti 15 Searing Tongue e 15 Searing Heart.", enHash = "5a02312b", vanilla = true },
        progress = { it = "Con i cuori e le lingue della progenie bruciata dell'esercito del drago nero, potrò decifrare quale bestia immonda abbia portato la sua prole nella nostra casa. Forse, conoscendo meglio i nostri aggressori, potremo cercare di distruggerli una volta per tutte e strappare Stonemaul Village alla rovina.\n\nNaturalmente, convincere Mok'Morokk a spostare la sua pigra mole di grasso fuori da questo buco fangoso sarà già di per sé un'impresa epica...", enHash = "4c54fbfd", vanilla = true },
        reward = { it = "È stata di certo un'impresa pericolosa raccogliere tutti questi cuori e queste lingue. Mi addentrerò nelle profondità dell'arcano per risalire all'origine della minaccia nera che si è abbattuta sulla nostra vecchia casa.", enHash = "96855c3f", vanilla = true },
    },
    [1170] = {
        title = { it = "La covata di Onyxia", enHash = "8db1aea4", vanilla = true },
        text = { it = "Stonemaul Village è stato invaso dalla covata di Onyxia. Ma perché la figlia del signore dei draghi neri, Deathwing, dovrebbe calare sulle nostre terre?\n\nÈ molto preoccupante. Di certo Onyxia è stata spinta fin qui da uno scopo che va oltre l'assedio di una piccola banda di ogre.\n\nAvverti subito Mok'Morokk! Bisogna agire.", enHash = "3fd2a304", vanilla = true },
        objectives = { it = "Parla con Overlord Mok'Morokk, a Brackenwall Village.", enHash = "12aa52d9", vanilla = true },
        reward = { it = "Perché tu dire a me di draghi? A me non piacere draghi. A me piacere qui. Qui niente draghi.", enHash = "6369a1b3", vanilla = true },
    },
    [1171] = {
        title = { it = "La covata di Onyxia", enHash = "8db1aea4", vanilla = true },
        text = { it = "Tu lasciare me in pace adesso. Andare dire a Draz'Zilb che noi restare qui. Qui niente drago nero.", enHash = "4cd3bd63", vanilla = true },
        objectives = { it = "Parla con Draz'Zilb, a Brackenwall Village.", enHash = "8a12120a", vanilla = true },
        reward = { it = "Quel pigro codardo!\n\nMok'Morokk mostrava forza quando Rexxar era il nostro capo. Ma poco dopo la partenza di Rexxar, Mok'Morokk è caduto preda delle tentazioni del potere. Invece di guidare, pretendeva. Non serve la sua gente: si aspetta piuttosto che siamo noi a servire lui.\n\nBisogna fare qualcosa.", enHash = "cf2c24ae", vanilla = true },
    },
    [1172] = {
        title = { it = "La covata di Onyxia", enHash = "8db1aea4", vanilla = true },
        text = { it = "La covata di Onyxia è stata sparsa per tutto il Dragonmurk. È indispensabile che non si permetta ad altri cuccioli di uscire dall'uovo.\n\nSbrigati a raggiungere il Wyrmbog, nel sud del Dustwallow Marsh. Di certo è lì che ha fatto la sua tana. Trova le uova del drago malvagio e distruggile.\n\nNon riconquisteremo mai Stonemaul Village se i dintorni restano una zona di nidificazione.\n\nQuanto a Mok'Morokk... ho altri piani per quell'idiota.", enHash = "61ee65e4", vanilla = true },
        objectives = { it = "Draz'Zilb, a Brackenwall Village, vuole che tu distrugga 5 Egg of Onyxia.", enHash = "ee5fc071", vanilla = true },
        progress = { it = "Devi correre al Dragonmurk, $N. Con le uova di Onyxia sparse per tutto il Wyrmbog, ci troveremo davanti a un numero schiacciante di nemici, se non si fa qualcosa in fretta.\n\nDistruggi le sue uova! Non lasciare che la piaga del drago nero si diffonda nella nostra terra!", enHash = "a816c764", vanilla = true },
        reward = { it = "Splendido! Passerà del tempo prima che Onyxia possa produrre altre uova.\n\nA nome della mia gente, ti ringrazio, $N.\n\nFinora ti ho chiesto molto. Forse puoi rendere un ultimo servizio allo Stonemaul Clan.\n\nMok'Morokk non è adatto a guidarci. Tharg sarebbe un capo eccellente, ma è frenato dalle ferite e dall'età. Caccia Mok'Morokk da questo posto con la forza. Solo allora potremo nominare un nuovo capo che ci riporti alla nostra vera casa, a sud.", enHash = "9655c6ef", vanilla = true },
    },
    [1173] = {
        title = { it = "Sfida Overlord Mok'Morokk", enHash = "ae815037", vanilla = true },
        text = { it = "Tu osare sfidare Overlord Mok'Morokk?\n\nAh ah!\n\nIo schiacciare $Gpiccolo:piccola; $R!\n\nTu dire a me quando $Gpronto:pronta; per bella batosta.", enHash = "9e973cab", vanilla = true },
        objectives = { it = "Sconfiggi Mok'Morokk e riferisci la notizia a Draz'Zilb, a Brackenwall Village.", enHash = "b5010102", vanilla = true },
        progress = { it = "Credevo che avresti tentato di cacciare Mok'Morokk dal villaggio. E invece sei $Gvenuto:venuta; da me a fare due chiacchiere?", enHash = "1f52625a", vanilla = true },
        reward = { it = "Quel vile ammasso di grasso di Mok'Morokk è fuggito come un bambino spaventato. Hai reso un grande servizio, $N.\n\nOra la mia gente potrà nominare un nuovo capo, uno che ci aiuti a riconquistare una volta per tutte la nostra vecchia casa.", enHash = "5fb42a73", vanilla = true },
    },
    [1175] = {
        title = { it = "Un ostacolo sulla strada", enHash = "466363ff", vanilla = true },
        text = { it = "Dopo il grande schianto tra il Red Thunder dei goblin e un basilisco, Kronkrider mi ha assunto per occuparmi della pista. Non so cosa mangino tutti gli animali qui nelle saline per diventare così grossi, ma dobbiamo stare attenti a diradarli, così non finiscono in pista durante una corsa.\n\nFacciamo così. Se vuoi guadagnarti qualcosa, va' là fuori e togli di mezzo i basilischi della zona.", enHash = "e5af745a", vanilla = true },
        objectives = { it = "Uccidi 10 Saltstone Basilisk, 10 Saltstone Crystalhide e 6 Saltstone Gazer per Trackmaster Zherin, nelle Shimmering Flats.", enHash = "fd7bbb03", vanilla = true },
        progress = { it = "Già è brutto dover ripulire i rottami delle vetture, figurarsi doverli staccare da pezzi di animale bruciacchiati.", enHash = "b27a8b06", vanilla = true },
        reward = { it = "Spero che tu non abbia ucciso nessuno dei basilischi proprio sulla pista! Le carcasse ci mettono un sacco a decomporsi al sole, e preferirei non dover tirare fuori la pala per ripulire.", enHash = "26967d15", vanilla = true },
    },
    [1176] = {
        title = { it = "Alleggerire il carico", enHash = "c93f0ebd", vanilla = true },
        text = { it = "Quando si corre, ogni minima cosa conta! Che sia una piccola regolazione della potenza, un leggero allentamento delle molle o l'alleggerimento del telaio, devi tenere conto di tutto.\n\nPer molte delle piccole modifiche strutturali alle nostre vetture usiamo ossa di avvoltoio: hanno l'equilibrio perfetto tra robustezza e peso. E per di più è facile procurarcene altre, perché le saline sono piene di avvoltoi.\n\nPortamene un po' e te le pagherò bene.", enHash = "6292fdc5", vanilla = true },
        objectives = { it = "Procura 10 Hollow Vulture Bone a Pozzik, nelle Shimmering Flats.", enHash = "89fa3c47", vanilla = true },
        progress = { it = "Ce le hai quelle ossa per me? Stavo giusto per mettermi ad alleggerire il gruppo dello sterzo, ma non voglio aprirla senza avere tutti i pezzi che mi servono.", enHash = "3145b2cd", vanilla = true },
        reward = { it = "Ottimo! Posso mettere subito la squadra al lavoro. Grazie, $N!", enHash = "84a48333", vanilla = true },
    },
    [1177] = {
        title = { it = "Fame!", enHash = "4b6db974", vanilla = true },
        text = { it = "Mud grosso ogre.\n\nIo avere fame.\n\nTu andare picchiare pesciolini. Portare cibo a Mud.\n\nTu dare da mangiare a Mud o Mud mangiare te.", enHash = "8dd0de6a", vanilla = true },
        objectives = { it = "Mudcrush Durtfeet, nel Dustwallow settentrionale, vuole 12 Mirefin Head.", enHash = "7f940bec", vanilla = true },
        progress = { it = "Dare cibo a me o io mangiare te.", enHash = "0f88b187", vanilla = true },
        reward = { it = "A me piacere testa di pesciolino!\n\nIo non mangiare te adesso.", enHash = "456fc879", vanilla = true },
    },
    [1178] = {
        title = { it = "Gli sponsor goblin", enHash = "9fd8398d", vanilla = true },
        text = { it = "La nostra squadra da corsa è l'orgoglio dei goblin di tutto il mondo. Ti sorprenderebbe sapere quanta gente contribuisce in un modo o nell'altro alla squadra.\n\nConosci Gazlowe? Ci trova pezzi in giro per il mondo. Una volta è perfino venuto qui a lavorare su una delle nostre vetture!\n\nQualche settimana fa ha detto che ci avrebbe mandato un nuovo prototipo di regolatore del carburante, ma non è ancora arrivato. Di solito è puntualissimo... Ti dispiacerebbe andare a Ratchet a chiedergli com'è la faccenda? Non vorrei insistere, ma gli gnomi ci stanno raggiungendo!", enHash = "afe4026f", vanilla = true },
        objectives = { it = "Parla con Gazlowe, a Ratchet.", enHash = "90de062a", vanilla = true },
        reward = { it = "Ti manda Pozzik, eh? Sai, Pozzik era uno degli artigiani più rispettati di Undermine prima di ritirarsi per mettersi a lavorare sulle vetture da corsa.\n\nLa prima cosa che ha fatto quando è entrato nella squadra è stata sviluppare le vetture a due motori. Può darsi che gli affari ne risentano, senza di lui alla Tinkers' Union, ma chi se ne importa, no? Non c'è niente come le corse!", enHash = "6c252218", vanilla = true },
    },
    [1179] = {
        title = { it = "I fratelli Brassbolts", enHash = "ac91f557", vanilla = true },
        text = { it = "Hai mai sentito parlare delle Shimmering Flats? È una distesa di saline laggiù a Kalimdor, appena a sud del canyon di Thousand Needles. È un posto perfetto per le corse perché, be', è pianissimo!\n\nCi sono due fratelli gnomi laggiù, amici miei, che stanno provando la loro nuova auto a razzo, e da quel che ho sentito è veloce! Eh, così veloce che i loro piloti continuano a schiantarsi. E a prendersi delle belle botte in testa.\n\nCosì mi hanno chiesto qualche elmo da macchina d'assedio, ma io qui ho i miei compiti. Non posso fare il viaggio!\n\nTu puoi?", enHash = "a058ad3b", vanilla = true },
        objectives = { it = "Porta la cassa di caschi protettivi a Wizzle Brassbolts, nelle Shimmering Flats.", enHash = "56c0998a", vanilla = true },
        progress = { it = "Guarda dove metti i piedi! Guarda guarda guarda!! Qui c'è roba delicata, e se vogliamo vincere deve funzionare tutto alla perfezione!", enHash = "df682c65", vanilla = true },
        reward = { it = "Ah! Ti manda Longbeard con un carico di elmi! Evviva!\n\nAdesso forse riusciamo a convincere un pilota a guidare la nostra auto...", enHash = "4798236d", vanilla = true },
    },
    [1180] = {
        title = { it = "Gli sponsor goblin", enHash = "9fd8398d", vanilla = true },
        text = { it = "Torniamo al motivo per cui sei qui. Lo so che avevo promesso a Pozzik di consegnargli un nuovo regolatore del carburante, ma non l'ho ancora ricevuto. Revilgaz, laggiù a Booty Bay, aveva detto che me l'avrebbe fatto spedire, ma può darsi che in qualche modo sia finito nel dimenticatoio.\n\nSe è così, non possiamo farci molto. Almeno possiamo scoprire se è mai partito da Booty Bay.\n\nSenti Wharfmaster Lozgil laggiù: dovrebbe poter controllare i registri del carico.", enHash = "eb4d39fb", vanilla = true },
        objectives = { it = "Parla con Wharfmaster Lozgil, a Booty Bay.", enHash = "c3b7ba81", vanilla = true },
        reward = { it = "Spedizioni per Ratchet? Fammi controllare i registri...\n\nNo, l'ultima spedizione per Ratchet che risulta erano stivali di Drizzlik. Non c'è stato molto altro, a parte materiali da costruzione e attrezzi. Di sicuro nessun pezzo da corsa.", enHash = "9faa42b9", vanilla = true },
    },
    [1181] = {
        title = { it = "Gli sponsor goblin", enHash = "9fd8398d", vanilla = true },
        text = { it = "Temo di non poterti essere di grande aiuto, $N. Se vuoi approfondire, ti consiglio di rivolgerti al barone in persona. Se c'è qualcuno che conosce gli affari di Revilgaz, è Revilgaz.\n\nLo trovi alla taverna dall'altra parte del porto, all'ultimo piano.", enHash = "fa6c61ed", vanilla = true },
        objectives = { it = "Parla con Baron Revilgaz, a Booty Bay.", enHash = "73f8735c", vanilla = true },
        reward = { it = "Oh, certo che so di cosa parli. Però no, non posso aiutarti. Alcuni dei miei uomini dovevano andare a recuperare i progetti del regolatore del carburante, ma sono tornati a mani vuote.", enHash = "ce2983c9", vanilla = true },
    },
    [1182] = {
        title = { it = "Gli sponsor goblin", enHash = "9fd8398d", vanilla = true },
        text = { it = "Vedi, le sminuzzatrici della Venture Company là al Lake Nazferiti (nella Stranglethorn settentrionale) sono state dotate di un regolatore del carburante di nuovo modello. Pensavo che Pozzik potesse sfruttarlo, se solo avesse qualche dettaglio. Purtroppo Cozzle, il caposquadra laggiù, sembra un po' più furbo di quanto credessi.\n\nTu però potresti avere più fortuna nel trovare i progetti. So che li tiene in casa sua, ma quasi di sicuro sono sotto chiave.", enHash = "df3f33af", vanilla = true },
        objectives = { it = "Porta i Fuel Regulator Blueprints a Baron Revilgaz, a Booty Bay.", enHash = "d5c7a961", vanilla = true },
        progress = { it = "Per quanto mi costi ammetterlo, quella squadra di gnomi laggiù è piuttosto brava. I nostri ragazzi hanno bisogno di ogni vantaggio possibile.", enHash = "bf2873f7", vanilla = true },
        reward = { it = "Ora, fammi solo fare una copia di questi progetti per i miei appunti e poi puoi portarli dritti a Pozzik. Non vorrei che pensasse che uno dei suoi sponsor lo sta abbandonando.", enHash = "fd481c38", vanilla = true },
    },
    [1183] = {
        title = { it = "Gli sponsor goblin", enHash = "9fd8398d", vanilla = true },
        text = { it = "Dovresti essere a posto. Saluta Pozzik da parte mia e digli che se gli serve qualcosa non esiti a chiedere. Aspetto la notizia che presto batterà il record della pista!", enHash = "c7545a5e", vanilla = true },
        objectives = { it = "Consegna i Fuel Regulator Blueprints a Pozzik, nelle Shimmering Flats.", enHash = "cba19ade", vanilla = true },
        progress = { it = "$N! Sei $Griuscito:riuscita; a rintracciare il regolatore del carburante?", enHash = "c237bda5", vanilla = true },
        reward = { it = "Speravo che fosse già assemblato, ma così ho l'occasione unica di migliorare il progetto da zero. Grazie, $N. Riuscirò a buttare giù qualche schema migliorato, a costruire l'aggeggio e a farlo installare molto presto.", enHash = "85399e3b", vanilla = true },
    },
    [1184] = {
        title = { it = "Parti dello sciame", enHash = "b2608f40", vanilla = true },
        text = { it = "Torna da Belgrom, a Orgrimmar, e digli che Moktar esegue bene i suoi ordini là a Thousand Needles. Digli anche che i miei studi procedono e che spero di saperne di più presto. Questo gli farà molto piacere.", enHash = "9200d621", vanilla = true },
        objectives = { it = "Torna da Belgrom Rockmaul, a Orgrimmar.", enHash = "8e777a30", vanilla = true },
        reward = { it = "Apprezzo i tuoi sforzi, $C. Il Capoguerra sarà contento di sentire con quanta tenacia hai svolto i tuoi doveri.\n\nOh, certo che gli farò il tuo nome. Mi parla spesso e tiene molto in conto le mie opinioni.\n\nOra va', ho molto da fare. E se parlerai presto con Korran e lui avrà notizie di queste creature, torna da me: credo siano una minaccia da prendere sul serio.", enHash = "ee75d88a", vanilla = true },
    },
    [1186] = {
        title = { it = "Il diciottesimo pilota", enHash = "e1fa9bba", vanilla = true },
        text = { it = "Io sarò impegnato a integrare questo nuovo regolatore del carburante nei progetti delle nostre vetture, ma se ti va di dare ancora una mano alla squadra, parla con Razzeric. È il nostro pilota, anzi, il nostro diciottesimo pilota, per l'esattezza, e gli piace aggiungere qualche modifica sua alle vetture.\n\nÈ un po' fuori di testa, però, quindi cerca di non sembrare troppo $Gsorpreso:sorpresa;.", enHash = "a082018d", vanilla = true },
        objectives = { it = "Parla con Razzeric, nelle Shimmering Flats.", enHash = "81822f01", vanilla = true },
        reward = { it = "Sei tu $Gil:la; $R che sta dando una mano a Pozzik, vero? Una volta ero come te: correvo su e giù per i box, aiutando in qualunque lavoro i meccanici mi lasciassero fare.\n\nE adesso guardami! Il pilota straordinario della squadra da corsa dei goblin!", enHash = "c8d15f61", vanilla = true },
    },
    [1187] = {
        title = { it = "Le modifiche di Razzeric", enHash = "26b67874", vanilla = true },
        text = { it = "Pozzik è un grande meccanico, lo so, ma ha paura di caricare potenza e basta e tenersi forte. Io no, però.\n\nDopo che Pozzik ha finito una vettura, mi prendo un po' di tempo per metterci le mie modifiche: sai, allentare i comandi, togliere pezzi di telaio e aggiungere più spinta!\n\nHo ordinato un seaforium booster da Shreev, al Gizmorium di Gadgetzan, ma a quanto pare lo zeppelin su cui viaggiava si è schiantato nel Dustwallow Marsh! Mi serve, $N!", enHash = "f611af43", vanilla = true },
        objectives = { it = "Recupera il Seaforium Booster per Razzeric, nelle Shimmering Flats.", enHash = "ec80f3e0", vanilla = true },
        progress = { it = "Come faccio a farmi vedere in pista senza una spintarella in più per partire? È uno scandalo, te lo dico io.", enHash = "0d43c6a0", vanilla = true },
        reward = { it = "Ma guarda che bellezza! Quindici libbre di pura potenza al seaforium! Appena me lo lego al fianco della vettura, girerò in pista così veloce che batterò gli gnomi due volte!", enHash = "61bb7900", vanilla = true },
    },
    [1188] = {
        title = { it = "Prima la sicurezza", enHash = "02fc1fe2", vanilla = true },
        text = { it = "Ma un momento, cos'è questa? Shreev ha lasciato inserita la sicura. Così limiterà la potenza che posso tirare fuori dal booster ogni volta. Gli avevo detto che la volevo tolta! Non va bene.\n\nDevi portarlo al Gadgetzan Gizmorium, nel Tanaris Desert, e farlo togliere da Shreev.", enHash = "ac257eef", vanilla = true },
        objectives = { it = "Porta il Seaforium Booster a Shreev, a Gadgetzan.", enHash = "0b4c2266", vanilla = true },
        progress = { it = "Come saprai di certo, il Gizmorium può soddisfare ogni tua esigenza di meccanica! Come posso aiutarti?", enHash = "712198d9", vanilla = true },
        reward = { it = "Solo Razzeric poteva guardare questo aggeggio e dire che ci avevo messo su chissà quale sicura. Questo booster è quasi tutto esplosivo al seaforium. L'ho già modificato perché all'uso rilasci più carica, ma Razzeric non è mai contento finché non si arriva a undici!", enHash = "4124f595", vanilla = true },
    },
    [1189] = {
        title = { it = "Prima la sicurezza", enHash = "02fc1fe2", vanilla = true },
        text = { it = "Ecco, ho fatto quel che voleva Razzeric. Digli solo di stare attento quando lo fa partire. Se sbaglia anche di poco, non andrà avanti: sarà solo una macchia bruciata sulla pista.\n\nSarebbe anche un peccato, se succedesse. Chissà se il nostro diciannovesimo pilota sarebbe altrettanto bravo.", enHash = "1a2e442d", vanilla = true },
        objectives = { it = "Riporta il Modified Seaforium Booster a Razzeric, nelle Shimmering Flats.", enHash = "86090da9", vanilla = true },
        progress = { it = "Ci credi che Pozzik ha messo un secchio di sabbia sulla vettura? Come faccio a raggiungere la velocità massima con un secchio di sabbia sotto il sedile?", enHash = "f7c2592f", vanilla = true },
        reward = { it = "Ecco, così va meglio! Vorrei tanto vedere che faccia faranno gli gnomi quando lo vedranno partire.\n\nPeccato che sarò troppo occupato a stabilire un nuovo record sul tracciato!", enHash = "476c8283", vanilla = true },
    },
    [1190] = {
        title = { it = "Stare al passo", enHash = "3c682e16", vanilla = true },
        text = { it = "I fratelli Brassbolts hanno scoperto un nuovo materiale da costruzione: è l'unica spiegazione che abbia senso. Le loro auto vanno più veloci di prima, ma i progetti, e tutti gli altri dati che abbiamo raccolto dalle loro corse, sono identici.\n\nQuel che sappiamo è che Rizzle Brassbolts è concentrato quasi di continuo sui piani di questa nuova scoperta.\n\nZamek può creare un diversivo per te, così potrai rubargli quei piani.", enHash = "d4feeb16", vanilla = true },
        objectives = { it = "Fa' creare un diversivo a Zamek, poi ruba i piani di Rizzle per Pozzik, nelle Shimmering Flats.", enHash = "8dcf1475", vanilla = true },
        reward = { it = "Scritti in fretta e furia, un rotolo di appunti e di disegni per la raffinazione di una materia prima.", enHash = "b6dd0c22", vanilla = true },
    },
    [1191] = {
        title = { it = "La distrazione di Zamek", enHash = "29da581a", vanilla = true },
        reward = { it = "Andiamo!", enHash = "c9fa0d20", vanilla = true },
    },
    [1192] = {
        title = { it = "Indurium Ore", enHash = "148414c7", vanilla = true },
        progress = { it = "Vorrei integrare l'indurium in varie parti delle nostre vetture, ma per fare quei pezzi mi servono grandi quantità di indurium grezzo.\n\nIl minerale di indurium lo trovi nello scavo di Uldaman, nei Badlands, oltre il mare a Khaz Modan.\n\nGli gnomi si stanno procurando la loro scorta, quindi è importante che ci procuriamo la nostra per stare al passo con loro.", enHash = "72d3deb8", vanilla = true },
        reward = { it = "Eccellente! Metto subito la squadra al lavoro sui pezzi che ci serviranno per la prossima corsa.", enHash = "d13159b4", vanilla = true },
    },
    [1194] = {
        title = { it = "Gli schemi di Rizzle", enHash = "77e99cca", vanilla = true },
        text = { it = "Gli schemi di Rizzle descrivono il procedimento di raffinazione del minerale di indurium. Dai suoi scarabocchi si capisce che il minerale di indurium viene estratto dal sito di scavo nanico di Uldaman, nei Badlands.\n\nGran parte degli altri appunti riguarda le proprietà di resistenza al calore.\n\nCome fermacarte sui piani c'è un pezzo di quello che sembra minerale di indurium grezzo.", enHash = "bd415ca5", vanilla = true },
        objectives = { it = "Porta il Sample of Indurium Ore a Pozzik, nelle Shimmering Flats.", enHash = "7cab6946", vanilla = true },
        reward = { it = "Indurium? Interessante... Se resiste al calore quanto dici, spiegherebbe l'aumento di prestazioni che gli gnomi hanno mostrato ultimamente.\n\nAnche questo campione che mi hai portato sarà preziosissimo. Potrò fare qualche prova, ma perché ci serva davvero a qualcosa me ne servirà di più.", enHash = "e69eb63b", vanilla = true },
    },
    [1195] = {
        title = { it = "La fiamma sacra", enHash = "e4a31dfe", vanilla = true },
        text = { it = "I centauri Galak, nelle Thousand Needles, custodiscono un manufatto che risale al tempo della creazione dei centauri.\n\nVorremmo recuperarlo, ma ci serve una fiala d'acqua presa da uno dei pozzi lunari degli elfi della notte.\n\nPer raccogliere l'acqua dovrai prima procurarti una delle fiale portate dalle driadi vicino al Raynewood Retreat, nel cuore dell'Ashenvale Forest. C'è un pozzo lunare vicino alla riva occidentale del Falfarren River, a sud della strada principale, dove puoi riempire la fiala.", enHash = "3acb0aaa", vanilla = true },
        objectives = { it = "Riporta un Filled Etched Phial a Zangen Stonehoof, a Thunder Bluff.", enHash = "7601b369", vanilla = true },
        progress = { it = "Una volta che avremo la fiala piena, potremo mandarla al mio socio, Rau, nelle Thousand Needles. È stato lui a chiedere la fiala d'acqua, quindi saprà meglio di noi come possiamo usarla.", enHash = "32d5c971", vanilla = true },
        reward = { it = "Molto bene. Questo dovrebbe soddisfare in pieno la richiesta di Rau. Potresti consegnarglielo? Forse ti farà piacere passare un po' di tempo nelle Needles.", enHash = "490fd305", vanilla = true },
    },
    [1196] = {
        title = { it = "La fiamma sacra", enHash = "e4a31dfe", vanilla = true },
        text = { it = "Porta la fiala piena a Rau Cliffrunner, al Freewind Post, nelle Thousand Needles sud-orientali. Puoi arrivare alle Thousand Needles prendendo il Great Lift, al margine meridionale delle Barrens.\n\nNon mi stupirei se potessi aiutarci ancora.", enHash = "1bad45f9", vanilla = true },
        objectives = { it = "Consegna il Filled Etched Phial a Rau Cliffrunner, al Freewind Post.", enHash = "75a4e4cc", vanilla = true },
        progress = { it = "Non sarai $Gstato mandato:stata mandata; da Zangen, eh?", enHash = "eda31a49", vanilla = true },
        reward = { it = "Hm, sì, questa fiala d'acqua servirà perfettamente ai nostri scopi. Per via della discendenza comune delle driadi e dei centauri, l'acqua dei pozzi lunari ci permetterà di forzare la protezione della fiamma eterna che circonda la reliquia dei centauri.", enHash = "ef9f17b3", vanilla = true },
    },
    [1197] = {
        title = { it = "La fiamma sacra", enHash = "e4a31dfe", vanilla = true },
        text = { it = "Usando l'acqua che hai portato, potrai spegnere per un po' la fiamma che trattiene la reliquia dei centauri. Non durerà per sempre, però, quindi dovrai fare in fretta.\n\nTroverai lo Splithoof Crag, la roccaforte dei centauri, a nord di qui. La fiamma è custodita nello Splithoof Hold, una parte della rupe sorvegliata a vista.\n\nSta' $Gattento:attenta;, però: i centauri Galak qui sono in gran numero, e saranno piuttosto restii a cedere qualcosa a cui tengono tanto.", enHash = "e7b48487", vanilla = true },
        objectives = { it = "Recupera il Cloven Hoof per Rau Cliffrunner, al Freewind Post.", enHash = "52b6cb4f", vanilla = true },
        progress = { it = "Non vedo l'ora di mettere le mani sul Cloven Hoof. L'hai già preso?", enHash = "a07f237b", vanilla = true },
        reward = { it = "Sento una strana energia emanare dall'Hoof... Non ho dubbi che dal suo studio scopriremo informazioni nuove e sorprendenti sui centauri.\n\nTi ringrazio, $N. Ora devo cominciare a decifrare i misteri che mi hai portato.", enHash = "f58ba0ea", vanilla = true },
    },
    [1198] = {
        title = { it = "Alla ricerca di Thaelrid", enHash = "e021e345", vanilla = true },
        text = { it = "In questi giorni girano molte voci sull'unione tra il Martello del Crepuscolo e i naga nelle Blackfathom Deeps, sulle coste di Ashenvale.\n\nIl mio ruolo qui, nell'Argent Dawn, è raccogliere quante più informazioni posso, così da sapere quando e dove serve aiuto.\n\nSono passate settimane da quando ho mandato un esploratore a controllare le attività alle Blackfathom Deeps. Argent Guard Thaelrid non ha ancora riferito.\n\nGli altri miei esploratori sono impegnati in faccende urgenti.\n\nTrova Thaelrid e aiutalo per me, $N.", enHash = "2745a974", vanilla = true },
        objectives = { it = "Trova Argent Guard Thaelrid nelle Blackfathom Deeps.", enHash = "1bdbf3db", vanilla = true },
        reward = { it = "Dawnwatcher Shaedlass ha fatto bene a mandarti. In questo luogo corrotto è davvero in corso un piano malvagio.", enHash = "f1765289", vanilla = true },
    },
    [1199] = {
        title = { it = "Il Twilight cade", enHash = "719aeec8", vanilla = true },
        text = { it = "Rafforzati dai riti ancestrali dei caotici Antichi Dei, i membri del Martello del Crepuscolo si adoperano per riportare i loro oscuri padroni e diffondere morte e terrore per il mondo.\n\nCrediamo che il Martello del Crepuscolo si sia alleato con i naga e si stia radunando nelle Blackfathom Deeps, sulla costa di Ashenvale.\n\nQualunque piano malvagio si stia preparando nelle profondità dell'antico tempio va sventato.\n\nMuovi guerra al Martello e riporta la prova delle tue imprese. I tuoi sforzi saranno ricompensati con generosità.", enHash = "2c4855eb", vanilla = true },
        objectives = { it = "Porta 10 Twilight Pendant ad Argent Guard Manados, a Darnassus.", enHash = "40547617", vanilla = true },
        progress = { it = "Le Blackfathom Deeps un tempo erano un antico tempio degli elfi della notte. Un tempo ospitavano un pozzo lunare potentissimo. Chissà quale male vi si prepara ora per mano del Martello del Crepuscolo.\n\nHai fatto progressi nel liberare il luogo dalla loro presenza?", enHash = "9822bdcc", vanilla = true },
        reward = { it = "Sei senza dubbio di sangue coraggioso e nobile, $N. L'Argent Dawn ti loda per i tuoi sforzi contro il male.", enHash = "78eb6791", vanilla = true },
    },
    [1200] = {
        title = { it = "La malvagità di Blackfathom", enHash = "6864f43a", vanilla = true },
        text = { it = "Le forze mi hanno abbandonato. Serve il tuo aiuto!\n\nTanto tempo fa questo luogo era un grande tempio di Elune. Ma la sventura lo portò in rovina quando la corruzione di un Antico Dio filtrò da sotto la terra e contaminò il sacro pozzo lunare.\n\nAku'Mai, servitore dell'Antico Dio, si levò dalle acque.\n\nI cultisti del Martello del Crepuscolo si sono alleati con i naga per occupare questi luoghi. I cultisti, guidati da Kelris, sacrificano innocenti ad Aku'Mai per averne potere.\n\nUccidi Kelris e porta la sua testa a Selgorm, a Darnassus, $N, ti prego.", enHash = "1d12d98f", vanilla = true },
        objectives = { it = "Porta la testa di Twilight Lord Kelris a Dawnwatcher Selgorm, a Darnassus.", enHash = "fbf034f8", vanilla = true },
        progress = { it = "Il tempo è una merce preziosa, $C.\n\nIl mio ruolo qui a Darnassus è fare in modo che l'Argent Dawn prosperi e che le forze del male che avanzano su Kalimdor siano fermate.\n\nDi' in fretta cosa vuoi, oppure va' per la tua strada.", enHash = "2ce72b51", vanilla = true },
        reward = { it = "Kelris ci è sfuggito per parecchio tempo.\n\nSembra che ogni volta che il male si è fatto sentire da queste parti, Kelris ci avesse messo lo zampino. Per un po' lo abbiamo creduto morto o scomparso.\n\nMa ora torna tutto. Ponendo fine al suo dominio hai risparmiato la vita a molti innocenti.\n\nPer la Luce! Sacrificare qualcuno a un servitore di un Antico Dio per il proprio tornaconto è al di là di ogni vergogna!\n\nHai compiuto una grande impresa, $N. Ti saluto a nome dell'Argent Dawn.", enHash = "418c02e7", vanilla = true },
    },
    [1201] = {
        title = { it = "Spie di Theramore", enHash = "162bc92f", vanilla = true },
        text = { it = "L'Orda e l'Alleanza mantengono una tregua precaria. Scaramucce ai confini e azioni segrete vengono condotte da una parte contro l'altra, ed è nostro dovere fare in modo che l'Orda abbia la meglio!\n\nOra è il momento di fare proprio questo.\n\nInfiltrati dell'Alleanza hanno preso posizione a est di Brackenwall Village. Spiano il villaggio e riferiscono i nostri movimenti a Theramore, cosa che non possiamo permettere.\n\nDai la caccia agli infiltrati e uccidili. Manda ai loro superiori un messaggio chiaro: non tollereremo la presenza delle loro spie!", enHash = "30fb1208", vanilla = true },
        objectives = { it = "Uccidi 9 Theramore Infiltrator, poi torna da Nazeer Bloodpike, a Brackenwall Village.", enHash = "b4315dde", vanilla = true },
        progress = { it = "Hai trovato gli infiltrati, $N?", enHash = "4d80fe12", vanilla = true },
        reward = { it = "Buon lavoro. I loro infiltrati sono abili, ma non abbastanza da sfuggire all'occhio vigile dell'Orda!", enHash = "9c60004f", vanilla = true },
    },
    [1202] = {
        title = { it = "I moli di Theramore", enHash = "271058c6", vanilla = true },
        text = { it = "$N, due delle nostre spie sono state mandate a rubare dei documenti da una nave ai moli di Theramore. Hanno preso le carte ma sono state scoperte, e sono state costrette a gettare i documenti in mare.\n\nPiù tardi una delle spie è fuggita, ma non è riuscita a recuperare il bottino. Mi ha riferito il suo fallimento, e ora affido il compito a te.\n\nI documenti sono in un baule, da qualche parte nell'acqua sotto i moli di Theramore. Trova quei documenti, $N, e portameli.", enHash = "71db9803", vanilla = true },
        objectives = { it = "Porta i Captain's Documents a Nazeer Bloodpike, a Brackenwall Village.", enHash = "57269539", vanilla = true },
        progress = { it = "Hai trovato i documenti, $N? Contengono informazioni vitali per la stabilità dell'Alleanza e, quindi, vitali per la sicurezza dell'Orda.", enHash = "4947f4d0", vanilla = true },
        reward = { it = "Mi congratulo con te, $N. Non era una missione facile. Ma i documenti che hai preso sono molto apprezzati dai nostri superiori.", enHash = "93a74f93", vanilla = true },
    },
    [1203] = {
        title = { it = "A Jarl serve una lama", enHash = "1aa3e4e7", vanilla = true },
        text = { it = "Devo tagliare delle cose. Non posso dirti cosa taglierò, ma... mi serve una lama. Una lama particolare...\n\nAlcuni la chiamano Moonsteel Broadsword. Io la chiamo lama da falciare.\n\nMi aiuti? Magari la trovi in città, magari parli con un fabbro e lui te la fa apposta.\n\nMa non dormirci sopra. Quello che devo tagliare non si conserva per sempre...", enHash = "8d196fbc", vanilla = true },
        objectives = { it = "Porta un Moonsteel Broadsword a Jarl, nel Dustwallow Marsh.", enHash = "baae0808", vanilla = true },
        progress = { it = "Hai la mia lama??", enHash = "3e9cc73b", vanilla = true },
        reward = { it = "È una bella lama. Falcia bene. È proprio una bella lama da falciare. Grazie. Grazie, grazie, grazie!!! Adesso voglio provarla...\n\nDopo. La provo dopo. Ma come stavo dicendo... grazie.", enHash = "6d761ca2", vanilla = true },
    },
    [1204] = {
        title = { it = "Zuppa di Mudrock e crostacei", enHash = "cd081472", vanilla = true },
        text = { it = "Sto lavorando a un piatto che chiamo \"Zuppa di Mudrock e crostacei\". Mi mancano ancora gli ingredienti principali, e... be', non credo che durerei a lungo arrancando per il Dustwallow Marsh!\n\nAllora, $N, puoi andare a caccia per me? Prima di tutto mi servono le lingue delle tartarughe Mudrock. Trovi le Mudrock lungo la costa, soprattutto intorno alla baia.\n\nMa non voglio lingue qualsiasi! Ho sentito che alcune Mudrock hanno la lingua biforcuta...\n\nDicono che le lingue biforcute abbiano un sapore particolare, e io voglio quel sapore nel mio piatto...", enHash = "caf6781b", vanilla = true },
        objectives = { it = "Porta 8 Forked Mudrock Tongue a Morgan Stern, a Theramore.", enHash = "43828ca4", vanilla = true },
        progress = { it = "Hai preso le lingue biforcute?", enHash = "c6fd41f4", vanilla = true },
        reward = { it = "Queste andranno benissimo! Grazie, $N!\n\nOra proverò diverse tecniche di cottura su queste lingue, per trovare il modo migliore di esaltarne il sapore.\n\nAlla fine avrò un piatto degno di essere servito al Blue Recluse di Stormwind!", enHash = "83cb445e", vanilla = true },
    },
    [1205] = {
        title = { it = "Deadmire", enHash = "1e054f33", vanilla = true },
        text = { it = "Deadmire è un antico crocolisk del Dustwallow Marsh. Ed è giunta la sua ora di morire.\n\nLe vecchie ossa scricchiolano mentre trascina il suo corpo enorme attraverso la palude, e benché si muova ancora con la forza e la velocità della giovinezza, il suo corpo che invecchia tormenta il grande spirito che racchiude, uno spirito la cui fiamma non vacilla.\n\nEppure ora vive in un dolore costante, che fa impazzire. Devi porre fine alla vita di questa nobile creatura, $N. Devi condurre Deadmire alla pace.", enHash = "9e9b543f", vanilla = true },
        objectives = { it = "Porta Deadmire's Tooth a Melor, a Thunder Bluff.", enHash = "3a064c97", vanilla = true },
        progress = { it = "Hai il dente di Deadmire, $N? Hai posto fine alle sofferenze della creatura?", enHash = "3ed22961", vanilla = true },
        reward = { it = "Molto bene, $N.\n\nSono sicuro che la caccia non sia stata facile, ma è bello sapere che il dolore della bestia è finalmente finito.", enHash = "7e3f866b", vanilla = true },
    },
    [1206] = {
        title = { it = "A Jarl servono occhi", enHash = "be48a1d4", vanilla = true },
        text = { it = "Il succo d'occhi è un buon succo da bere. Peccato che quasi tutte le bestiole abbiano solo due occhi.\n\nMa i ragni hanno tanti occhi. Tanti, tantissimi. E il succo d'occhi di Darkmist è saporito. Vellutato e salato! Occhi di ragno non scoppiati... ne sento già il sapore.\n\nI Darkmist Spider sono a ovest di qui, nella Darkmist Cavern. Secondo te i ragni prendono il nome dalla caverna... o è il contrario?", enHash = "75aab867", vanilla = true },
        objectives = { it = "Porta 40 Unpopped Darkmist Eye a \"Swamp Eye\" Jarl, allo Swamplight Manor.", enHash = "6bab72e0", vanilla = true },
        progress = { it = "Dove sono quegli occhi?", enHash = "1c989545", vanilla = true },
        reward = { it = "Hai gli occhi! Hai gli occhi! Gustosi, gustosi occhi di ragno!\n\nCerti occhi... quando li fissi, ti fissano anche loro. Quelli mangiali per ultimi. Ti tengono compagnia... qui fuori nella palude.\n\nCiao, occhietti di ragno. Ciao! Sapete di pollo. Pollo appiccicoso e salato!\n\nMmmh.", enHash = "62a86ab2", vanilla = true },
    },
    [1218] = {
        title = { it = "Soothing Spices", enHash = "cb72e7aa", vanilla = true },
        text = { it = "Mi piace cucinare. La buona cucina di palude. Cosce di rana verde fritte e cose simili.\n\nE per cucinare mi servono spezie. Spezie lenitive. Poi preparo uno stufato, lo faccio stufare per bene, me lo sorbisco e ne do un po' anche a te.\n\nTi piace lo stufato?", enHash = "c7d8fe8b", vanilla = true },
        objectives = { it = "Porta 3 Soothing Spices a \"Swamp Eye\" Jarl, nel Dustwallow Marsh.", enHash = "8dc5f3ea", vanilla = true },
        progress = { it = "Spezie. A tutti farebbe comodo un po' di spezie nella vita. Sei d'accordo?", enHash = "20d55c6c", vanilla = true },
        reward = { it = "Ah, queste sì che sono spezie! Ecco del buono stufato di palude.", enHash = "31c06479", vanilla = true },
    },
    [1219] = {
        title = { it = "Il rapporto dell'orco", enHash = "fbec1fd7", vanilla = true },
        text = { it = "Setacciando la terra smossa, si trova la mano mozzata di un orco. E stretto nella mano c'è un tubo intagliato nell'osso. E nel tubo c'è una pergamena macchiata di terra.\n\nLa pergamena è scritta in orchesco... e sembra importante.", enHash = "2594d6ad", vanilla = true },
        objectives = { it = "Porta lo Spy's Report a un Theramore Lieutenant.", enHash = "ce7ba81f", vanilla = true },
        progress = { it = "Hai un rapporto da fare?", enHash = "9b5cfaf7", vanilla = true },
        reward = { it = "Hm... non leggo molto bene l'orchesco, ma questo sembra un rapporto... scritto da una spia orchesca!", enHash = "70c3a6a2", vanilla = true },
    },
    [1220] = {
        title = { it = "Captain Vimes", enHash = "bdd2da4c", vanilla = true },
        text = { it = "Captain Vimes dovrebbe vedere il rapporto orchesco che hai trovato, $N. Conosce la lingua degli orchi meglio di molti altri. E dovrebbe sapere che ci sono spie dell'Orda vicino a Theramore!\n\nIl capitano è nella caserma, sul lato nord-orientale di Theramore Isle.", enHash = "75ec6e32", vanilla = true },
        objectives = { it = "Porta lo Spy's Report a Captain Garran Vimes.", enHash = "98d352b5", vanilla = true },
        progress = { it = "Hai qualcosa per me?", enHash = "ac74d893", vanilla = true },
        reward = { it = "Un rapporto di una spia orchesca! Come l'hai trovato? Non importa, vediamo cosa dice...", enHash = "f3329280", vanilla = true },
    },
    [1221] = {
        title = { it = "Blueleaf Tubers", enHash = "e6fb522d", vanilla = true },
        text = { it = "I Blueleaf Tuber sono una prelibatezza in tutto il mondo! Ma sono rari, molto rari. L'unico posto dove trovarli è qui nelle Barrens, nelle profondità della terra, nel Razorfen Kraul.\n\nE anche lì è impossibile trovarli, a meno di sapere esattamente dove cercare! Per questo ho addestrato questi Snufflenose Gopher a trovarli per me. Hanno un gran fiuto e sentono l'odore di un tubero a cinquanta passi di distanza.\n\nNon sarà facile, ma se mi porti qualche tubero ti pagherò profumatamente.", enHash = "e9de6028", vanilla = true },
        objectives = { it = "Prendi una Crate with Holes.\nPrendi uno Snufflenose Command Stick.\nPrendi e leggi lo Snufflenose Owner's Manual.\n\nNel Razorfen Kraul, usa la Crate with Holes per evocare uno Snufflenose Gopher e usa il Command Stick sul gopher per fargli cercare i Tuber.\n\nPorta 6 Blueleaf Tuber, lo Snufflenose Command Stick e la Crate with Holes a Mebok Mizzyrix, a Ratchet.", enHash = "7c1781e6", vanilla = true },
        progress = { it = "Hai i tuberi, $N?", enHash = "6f1ce58b", vanilla = true },
        reward = { it = "Perfetto, li hai presi! Posso venderli ai miei contatti a peso d'oro!\n\nGrazie della consegna, $N! Sei $Gun ottimo socio:un'ottima socia;.", enHash = "02112957", vanilla = true },
    },
    [1222] = {
        title = { it = "La fuga di Stinky", enHash = "1aa7f941", vanilla = true },
        text = { it = "Grande, finalmente qualcosa che non vuole mangiarmi!\n\nMi serve aiuto per tenere a bada le bestiacce di qui, e tu fai al caso mio, $Gamico:signora;.\n\nIl cuoco Morgan Stern sta studiando una nuova ricetta, e mi ha mandato qui a raccogliere foglie di bogbean. Immagino che le trovi gustose.\n\nComunque, mentre cercavo una pianta di bogbean... mi sono fatto circondare! Puoi aiutarmi a uscire di qui e guardarmi le spalle mentre cerco il bogbean?", enHash = { "a3a54ed0", "8ead9a50" }, vanilla = true },
        objectives = { it = "Scorta \"Stinky\" Ignatz, poi parla con Morgan Stern, a Theramore.", enHash = "d862c3bc", vanilla = true },
        progress = { it = "Hai visto il signor Ignatz? L'ho mandato nella palude un po' di tempo fa e non è tornato!", enHash = "c62a10aa", vanilla = true },
        reward = { it = "Il signor Ignatz è appena passato di qui con le foglie di bogbean, e mi ha detto che l'hai aiutato a uscire da un bel guaio.\n\nGrazie, $N. Chiederò a mio zio di offrirti un banchetto la prossima volta che visiterai il Blue Recluse, a Stormwind.", enHash = "64c8e802", vanilla = true },
    },
    [1238] = {
        title = { it = "Il rapporto perduto", enHash = "5799b081", vanilla = true },
        text = { it = "Setacciando la terra smossa, si trova la mano mozzata di un orco. E stretto nella mano c'è un tubo intagliato nell'osso. E nel tubo c'è una pergamena macchiata di terra.\n\nLa pergamena è un rapporto scritto da un orco che ha passato settimane a spiare la città di Theramore.\n\nDopo aver scorso la pergamena, è chiaro che va portata al capo delle spie degli orchi, a Brackenwall Village.", enHash = "40b68b03", vanilla = true },
        objectives = { it = "Porta lo Spy's Report a Nazeer Bloodpike, a Brackenwall Village.", enHash = "e056cd97", vanilla = true },
        progress = { it = "Hai qualcosa per me?", enHash = "ac74d893", vanilla = true },
        reward = { it = "Buon lavoro, $N. Il nostro agente, Marg Nighteye, era di stanza fuori Theramore. Aveva il compito di spiare la città.\n\nQuesto è il suo rapporto più recente, e potrebbe essere l'ultimo: da quello che racconti, temo che Marg abbia trovato la fine nella palude...", enHash = "247dff37", vanilla = true },
    },
    [1239] = {
        title = { it = "La testa mozzata", enHash = "bdb286df", vanilla = true },
        text = { it = "Uno scavo vigoroso porta alla luce la testa di un orco maschio, mozzata malamente all'altezza del collo. Le labbra sono irrigidite in un ringhio, e gli occhi scuri fissano con aria di sfida.", enHash = "158acb0d", vanilla = true },
        objectives = { it = "Porta la Defiant Orc Head a Nazeer Bloodpike, a Brackenwall Village.", enHash = "101dd686", vanilla = true },
        progress = { it = "Hai un'altra questione da riferire, $N?", enHash = "7be22cb3", vanilla = true },
        reward = { it = "Questa è la testa di Marg Nighteye! Come temevo, è morto.\n\nGuarda la ferita sul collo! Può essere stata un'arma a fare quel taglio frastagliato, o è stata qualche bestia a uccidere il nostro agente?\n\nÈ un mistero che dobbiamo risolvere, $N. Dobbiamo scoprire se la morte di Marg è opera dell'Alleanza!", enHash = "847ce95a", vanilla = true },
    },
    [1240] = {
        title = { it = "Lo stregone troll", enHash = "f2d12ae3", vanilla = true },
        text = { it = "Dobbiamo conoscere i fatti legati alla morte di Marg! E l'unico modo per farlo, $N, è la magia stregonesca dei troll.\n\nPorta la testa di Marg a Kin'weelay, nella Stranglethorn Vale, al Grom'gol Base Camp.\n\nKin'weelay è lo stregone più potente dei troll Darkspear. Se qualcuno può parlare con lo spirito di Marg Nighteye, è lui.", enHash = "05664a0e", vanilla = true },
        objectives = { it = "Porta la Defiant Orc Head a Kin'weelay, al Grom'gol Base Camp, nella Stranglethorn Vale.", enHash = "cc7f34ce", vanilla = true },
        progress = { it = "C'è uno spirito furioso intorno a te, $Gfratello:sorella;. Cosa ti porta da Kin'weelay?", enHash = { "c1cb5bb1", "cb97b29b" }, vanilla = true },
        reward = { it = "Ah, ora vedo. Lo spirito di questo orco è legato al nostro mondo, e ribolle di rabbia per un compito non ancora portato a termine.\n\nBene, facciamo due chiacchiere con questo orco arrabbiato...", enHash = "97a1dff6", vanilla = true },
    },
    [1241] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Di recente un diplomatico è stato mandato a Theramore per incontrare Jaina Proudmoore. Quel diplomatico non è mai arrivato.\n\nCredo che in questa trama ci siano di mezzo i Defias, ma non so come. La scomparsa del diplomatico sfugge ancora all'attenzione del pubblico, ma non potrà restare così a lungo.\n\nGli agenti del re stanno già setacciando la città in cerca di indizi, ma ho anche i miei contatti, e voglio coinvolgerli.\n\nNella Valley of Heroes c'è un mio vecchio amico di nome Jorgen. Trovalo, dagli questo biglietto e segui le sue istruzioni.", enHash = "3d15f126", vanilla = true },
        objectives = { it = "Trova Jorgen, a Stormwind City.", enHash = "048749ef", vanilla = true },
        progress = { it = "Hmph, sarà meglio che tu abbia un buon motivo per disturbare un uomo che pesca. Non mi vanno a genio i venditori ambulanti, figurarsi gli accattoni.", enHash = "39f563c3", vanilla = true },
        reward = { it = "Hmm... <Jorgen alza gli occhi verso di te socchiudendoli.>\n\nVa bene. Ti aiuto, ma non perché ne ho voglia: perché sono obbligato.\n\nE mettiamo in chiaro una cosa: già così ne sai molto più di quanto dovresti. Teniamolo per noi questo piccolo segreto, e non andare a spettegolare nelle taverne di quel che scopri. Intesi?", enHash = "9d059294", vanilla = true },
    },
    [1242] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Porta questo biglietto a Elling Trias. Non dirgli nient'altro. Sii soltanto $Geducato:educata; e aspetta che risponda. E non preoccuparti, risponderà.\n\nTe lo ripeto un'ultima volta, $N: prendi questa faccenda sul serio, e tieni la bocca chiusa.\n\nTrias lo trovi alla sua bottega di formaggi, Trias' Cheese, nel Trade District. Buona fortuna.", enHash = "82af32bb", vanilla = true },
        objectives = { it = "Consegna Jorgen's Sealed Note a Elling Trias, a Stormwind City.", enHash = "5c82d209", vanilla = true },
        progress = { it = "Salve, $N. C'è qualcosa che posso fare per te? Magari vuoi assaggiare un po' del nostro cheddar speciale di Trias? O un pezzo di bleu darnassiano?", enHash = "c8f424c7", vanilla = true },
        reward = { it = "Scusa, una lettera per me? Ma guarda... non capita spesso di ricevere una consegna che non sia una cassa o un barile, quando non fai altro che lavorare. Vediamo di che si tratta.\n\n<Elling alza gli occhi verso di te mentre apre la lettera.>\n\nSembri un po' $Gteso:tesa;, tutto bene, $N?", enHash = "de442be5", vanilla = true },
    },
    [1243] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Jorgen, vecchio figlio di.... Ah, quindi la mettiamo così, eh?\n\nVa bene, posso conviverci. Spero che finisca nel Twisting Nether il prima possibile!\n\nEcco come andrà, $N. Io comincio a muovere i miei contatti qui, ma il grosso del lavoro sul campo lo fai tu, così risparmio qualche moneta.\n\nVa' a Darkshire, a Duskwood, e trova Watcher Backus: di solito pattuglia la strada a nord, appena fuori dal paese. Digli soltanto che stai indagando per me su eventuali attività dei Defias e ti darà tutte le informazioni che può.", enHash = "f59cb43a", vanilla = true },
        objectives = { it = "Consegna la Sealed Note a Watcher Backus, a Duskwood.", enHash = "a855c1f7", vanilla = true },
        progress = { it = "Non è troppo sicuro andare in giro per i boschi, $N. Sta' $Gattento:attenta;, e se vedi qualcosa di sospetto o pericoloso avvisa subito i Watcher. Non provare ad affrontare niente da $Gsolo:sola;. Noi non siamo responsabili di quel che di terribile potrebbe capitarti.\n\nMa lo sappiamo tutti e due che mi ignorerai e combatterai comunque qualunque cosa sbuchi dal buio, vero? Ahah, già, voi avventurieri... tutti uguali.", enHash = "e048ebe3", vanilla = true },
        reward = { it = "Oh, ti manda Trias, eh? Allora è un'altra cosa.\n\nCombatti pure qualunque mostruosità ti venga addosso dal buio. Sono sicuro che te la caverai facilmente, se sei il tipo che bazzica con uno come lui.\n\nAllora, cosa vuole il mio amico da me in una giornata tetra come questa?", enHash = "88e0f617", vanilla = true },
    },
    [1244] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Attività dei Defias? Be', un po' di attività c'è sempre; anche se se ne stanno per conto loro li consideriamo una minaccia.\n\nMa ora che ci penso, c'è stato un avvistamento recente che pareva strano. Sarà stato un paio di settimane fa: alcuni dei loro agenti si erano radunati intorno ad Addle's Stead. Dal rapporto, direi che è successo qualcosa di grosso.\n\nPerché non provi a controllare prima là e mi riporti quel che trovi?\n\nLa fattoria è a sud della strada che viene da Westfall, appena entri a Duskwood.", enHash = "fce9fbf5", vanilla = true },
        objectives = { it = "Trova il Defias Docket e portalo a Watcher Backus, a Duskwood.", enHash = "e5204447", vanilla = true },
        progress = { it = "Sta' $Gattento:attenta; là fuori, $N. So che è stato Trias a mandarti qui, ma questo non vuol dire che nei boschi non ci sia in agguato qualcosa capace di darti dei guai... soprattutto se stai indagando sui Defias.", enHash = "bd8fb0dd", vanilla = true },
        reward = { it = "Sei di ritorno $Gsano:sana; e $Gsalvo:salva;. Non si può chiedere molto di più, no?\n\nOra, vediamo cos'abbiamo qui. Sembra piuttosto ufficiale, per quel che ho visto dei documenti dei Defias. Ma potrebbe essere un falso, giusto per farti perdere le tracce di quel che stai cercando.", enHash = "88b187f4", vanilla = true },
    },
    [1245] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Uau, questo sembra troppo complesso per essere qualcosa messo lì solo per sviarti. Non dovrei nemmeno metterci gli occhi sopra. Portalo a Trias: lui saprà venirne a capo. E NON lasciare che nessuno ti metta i bastoni tra le ruote. Questa cosa è più grossa di me. Forse è più grossa anche di lui, ma vedremo.\n\nE fammi un favore, $N: non dire a nessuno che ti ho aiutato. Se i miei superiori scoprissero che sapevo di tutto questo e non gliel'ho detto, probabilmente mi impiccherebbero.", enHash = "1f6e44f9", vanilla = true },
        objectives = { it = "Porta il Defias Docket a Elling Trias, a Stormwind.", enHash = "60057da6", vanilla = true },
        progress = { it = "Vedo che sei di ritorno, e tutto $Gintero:intera;. Sappiamo tutti e due che non sei qui per il formaggio, quindi tagliamo corto con i convenevoli. Backus è stato d'aiuto, o non sei ancora $Gpartito:partita; per Duskwood?", enHash = "c47fc715", vanilla = true },
        reward = { it = "Già... è una lettura interessante. Jorgen e DeLavey hanno fatto bene a coinvolgermi.\n\nPare che i Defias si siano dati parecchio da fare per portare a termine questo loro piano. Hmm... e questo cos'è? \"Fist\"? È un nome che mi dice qualcosa.", enHash = "4519a400", vanilla = true },
    },
    [1246] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Già, ora che ci penso... Dashel... Dashel qualcosa... Come si chiamava? FIST! Dashel Stonefist. In certi giri lo chiamano Fist, probabilmente perché gli piace fare a botte.\n\nDi solito lo trovi a Old Town, proprio nel bel mezzo. Va' a parlargli. Se serve, usa una spada o qualcosa di pesante e smussato per convincerlo ad aprirsi un po'. E non esitare. Se è dentro questa storia fino al collo come dicono queste carte, non ti darà nessuna informazione di sua spontanea volontà.", enHash = "36a40126", vanilla = true },
        objectives = { it = "Parla con Dashel Stonefist, a Stormwind.", enHash = "7cf12231", vanilla = true },
        reward = { it = "Cosa?!\n\nTu vieni nel mio vicolo a far domande sugli affari miei? Affari con cui evidentemente non c'entri niente.", enHash = "5c69d6e6", vanilla = true },
    },
    [1247] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Allora sì... ehm... qualcosa su quell'incontro ad Addle's Stead forse la so. È successo qualche settimana fa, mi pare. Io non c'entravo davvero niente. La mia parte era finita quando è fallito il piano A... maledetti avventurieri.\n\nIl tizio che abbiamo messo dentro per il piano B veniva da Menethil; uno che chiamano Slim. È tutto quel che so del loro piano di riserva.", enHash = "f6c07a2a", vanilla = true },
        objectives = { it = "Parla con Elling Trias, a Stormwind.", enHash = "48d31969", vanilla = true },
        reward = { it = "Bello vedere che sei ancora $Gvivo:viva;, $N. Quindi con Dashel è andata bene, eh?\n\nHo letto meglio questo loro piano e, anche se non dice il nome del diplomatico che volevano, parla di questo piano B che hanno messo in atto dopo aver fallito il primo tentativo di catturarlo.\n\nDi questo Slim che ha nominato Dashel qui non c'è scritto nessun altro nome, ma se dici che è a Menethil, è già un inizio.", enHash = "6114b84d", vanilla = true },
    },
    [1248] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Un mio contatto si è ritirato nelle Wetlands, nella città portuale di Menethil. Dovrebbe essere disposto ad aiutarti sulla mia sola parola, se gli dici che lavori per me. Si chiama Mikhail. Prima di lasciare Stormwind, qualche anno fa, aveva accennato che voleva fare il barista.\n\nParlagli, trova questo Slim e scopri se c'è altro da sapere su questo diplomatico rapito. Dobbiamo scoprire dove l'hanno portato, o almeno chi è. Il Defias Docket non dice niente sui loro piani dopo la cattura.", enHash = "05bf217b", vanilla = true },
        objectives = { it = "Parla con Mikhail, nelle Wetlands.", enHash = "f36ba30e", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta;, $Gbenvenuto:benvenuta;, $Gbenvenuto:benvenuta;, $N. Fai bene a unirti a noi. Magari una birra, oggi? O del montone?\n\nDi' pure cosa desideri e farò in modo che tu sia $Gservito:servita; a dovere. Mi chiamo Mikhail, e non vedo l'ora di servirti.\n\nHmm? Cosa? Trias? Abbassa la voce, $Gamico mio:amica mia;. Non è una cosa che debba sentire tutta la taverna.", enHash = "69b8231e", vanilla = true },
    },
    [1249] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Dici che ti manda Elling? E allora l'ospitalità che ti ho offerto adesso vale dieci volte tanto. Qualunque cosa ti serva, basta chiedere. Farò del mio meglio per aiutarti.\n\nHmm, Slim, dici? Non sono sicuro che il nome mi dica qualcosa, ma terrò gli occhi aperti.\n\nNon guardare adesso, $N, ma il signore laggiù vicino all'uscita sta guardando da questa parte. Ascolta la nostra conversazione un po' troppo attentamente, se capisci cosa intendo. Se fossi in te, farei il possibile per bloccarlo prima che scappi verso la porta.", enHash = "1e32aa1d", vanilla = true },
        objectives = { it = "Blocca Tapoke Jahn prima che scappi, poi torna da Mikhail, a Menethil.", enHash = "2a50a682", vanilla = true },
        progress = { it = "Ti è sgusciato via? Aveva un'aria losca, dal modo in cui ci guardava.", enHash = "5fa41e9f", vanilla = true },
        reward = { it = "L'hai preso, eh? $GBravo:Brava;. Mi sorprende che fosse Slim.\n\nSarò sincero: non avrei mai pensato di sentire la mancanza dell'eccitazione di certe attività clandestine più losche. Immagino che il vizio sia duro a morire. Non dirlo a Elling: se sapesse che mi manca l'azione, probabilmente cercherebbe di farmi tornare a Stormwind.\n\nSono contento di esserti stato almeno un po' utile mentre eri a Menethil. Se ti serve altro, basta chiedere.", enHash = "9dd732b1", vanilla = true },
    },
    [1250] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "I Defias non mi pagavano abbastanza da morire per la loro causa. Hanno preso il re. Sì, il re di Stormwind, non un diplomatico qualunque. Stava andando a Theramore per incontrare Jaina Proudmore: a quanto pare era una cosa grossa, e un gran segreto. Ma non ci sono dentro solo i Defias. Stanno lavorando con qualcuno. Credo sapessero che la cosa era più grande di loro.\n\nLa mia parte era solo far salire il loro uomo sulla nave del re mentre era in porto. Il tizio si chiamava Hendel. È tutto quel che so. Lo giuro!", enHash = "0a7b3739", vanilla = true },
        objectives = { it = "Parla con Mikhail, nelle Wetlands.", enHash = "f36ba30e", vanilla = true },
        reward = { it = "IL RE?! Cioè... il re? Il re vero? Stai scherzando? Non avevi detto che cercavi i rapitori del re. Non avevo nemmeno sentito che era scomparso... questo spiegherebbe in parte perché abbiano incoronato suo figlio.\n\nManderò subito parola a Elling. Vorrà sapere che sei sulle tracce.\n\nNon avrei mai immaginato che Jahn avrebbe venduto Stormwind per due monete schifose. Anche un ladro deve avere il suo onore su certe cose.\n\nOra il punto è trovare questo Hendel. E credo di poterti aiutare.", enHash = "85ba081f", vanilla = true },
    },
    [1251] = {
        title = { it = "Lo scudo nero", enHash = "1ef1d9f9", vanilla = true },
        text = { it = "Uno scudo di ferro, annerito dall'incendio che ha devastato la locanda, è fissato al camino in rovina, una delle poche parti rimaste dell'edificio che un tempo era la Shady Rest Inn.\n\nLo scudo si può staccare dai mattoni del camino.", enHash = "77217de9", vanilla = true },
        objectives = { it = "Porta il Blackened Iron Shield a Krog, a Brackenwall Village.", enHash = "a4c09840", vanilla = true },
        progress = { it = "Che cos'è quello che hai lì, $N? Delle prove dai resti della Shady Rest Inn?", enHash = "abc25d15", vanilla = true },
        reward = { it = "Ammetto che gli umani abbiano strani gusti nell'arredamento, ma userebbero davvero un semplice scudo di ferro per decorare il camino? Forse questo scudo l'hanno messo lì quelli che hanno bruciato la locanda.\n\nUn avvertimento? Una minaccia?", enHash = "ec923709", vanilla = true },
    },
    [1252] = {
        title = { it = "Lieutenant Paval Reethe", enHash = "bc78d8d8", vanilla = true },
        text = { it = "Un luccichio a terra, sotto le macerie, attira il tuo sguardo. Togliendo i detriti e la cenere incrostati sull'oggetto, appare l'insegna di un'ancora d'oro su fondo bianco, smaltata sulla superficie: il simbolo di Theramore.\n\nSotto l'ancora è impresso in rilievo il nome \"Lieutenant Paval Reethe\".", enHash = "590136fd", vanilla = true },
        objectives = { it = "Porta Reethe's Badge a Captain Garran Vimes, a Theramore.", enHash = "4641d880", vanilla = true },
        progress = { it = "Hai trovato qualcosa di interessante alla Shady Rest Inn?", enHash = "0466f9bb", vanilla = true },
        reward = { it = "Non è mai una buona notizia quando mi portano il distintivo di una guardia.\n\nA volte è un uomo o una donna caduti in battaglia, e tocca a me portare la notizia alla famiglia in lutto. Altre volte non scopriamo mai cosa gli sia successo. E altre volte è anche peggio.", enHash = "18c0e162", vanilla = true },
    },
    [1253] = {
        title = { it = "Lo scudo nero", enHash = "1ef1d9f9", vanilla = true },
        text = { it = "Uno scudo di ferro, annerito dall'incendio che ha devastato la locanda, è fissato al camino in rovina, una delle poche parti rimaste dell'edificio che un tempo era la Shady Rest Inn.\n\nLo scudo si può staccare dai mattoni del camino.", enHash = "77217de9", vanilla = true },
        objectives = { it = "Porta il Blackened Iron Shield a Captain Garran Vimes, a Theramore.", enHash = "7d350ccf", vanilla = true },
        progress = { it = "Hai trovato prove sul luogo della Shady Rest Inn?", enHash = "515bbad1", vanilla = true },
        reward = { it = "Hm, non sono un esperto nella costruzione di armi e armature. Nel loro uso sì, ma non nella loro fabbricazione.\n\nQuesto scudo sembra comunissimo, a parte i danni dell'incendio che ha avvolto la locanda.", enHash = "b3b1e673", vanilla = true },
    },
    [1258] = {
        title = { it = "... e crostacei", enHash = "54995e9a", vanilla = true },
        text = { it = "Un altro ingrediente della mia nuova ricetta è la zampa con il guscio di un granchio gigante. E i granchi che hanno nel Dustwallow — li chiamano Muckshell — proprio non vanno bene! Temo che gli unici granchi adatti vivano lontano, nella Swamp of Sorrows.\n\nIl guscio della zampa è un elemento chiave nella presentazione del piatto, quindi mi servono zampe intatte, senza graffi. Un granchio adulto può averne solo una o due così, e a me ne servono molte per mettere a punto il piatto.\n\nAllora, $N... sei $Gdisposto:disposta; a viaggiare?", enHash = "0a91dbd9", vanilla = true },
        objectives = { it = "Porta 12 Pristine Crawler Leg a Morgan Stern, a Theramore.", enHash = "3e11abc5", vanilla = true },
        progress = { it = "Le mie ricerche sulle lingue di Mudrock procedono bene. La tua caccia ai granchi va bene, spero?", enHash = "183e4ee7", vanilla = true },
        reward = { it = "Sono esemplari magnifici, $N! I gusci sono in perfette condizioni, e la carne è rosa e tenera. Nelle tue vene scorre sangue da chef, ne sono sicuro!", enHash = "c46b01b9", vanilla = true },
    },
    [1259] = {
        title = { it = "Lieutenant Paval Reethe", enHash = "bc78d8d8", vanilla = true },
        text = { it = "Non riconosco il nome di Lieutenant Paval Reethe. La cosa migliore è chiedere ad Adjutant Tesoran. Tiene i registri di tutta la guardia di Theramore, dal personale all'equipaggiamento.\n\nCon una rapida occhiata ai suoi libri dovrebbe riuscire a dirti chi è questo Reethe.", enHash = "5bbcd0e4", vanilla = true },
        objectives = { it = "Scopri di più su Reethe da Adjutant Tesoran, a Theramore.", enHash = "9ba8daa1", vanilla = true },
        reward = { it = "Salve, $N. Vuoi informazioni su un membro in particolare della guardia di Theramore? Reethe, hai detto?\n\nDammi solo un momento per trovare il libro giusto.", enHash = "cbf62716", vanilla = true },
    },
    [1260] = {
        title = { it = "Morgan Stern", enHash = "9a6f5204", vanilla = true },
        text = { it = "Sto preparando un nuovo menù per il ristorante. Sarà pieno di piatti rustici a tema \"bayou\". Credo che la mia clientela del Blue Recluse li adorerà!\n\nHo mandato mio nipote Morgan a Theramore, una città ai margini del Dustwallow Marsh. È lì a raccogliere ricette dalla gente del posto, e devo sapere che cosa ha trovato finora.\n\nIl viaggio fino a Theramore è lungo. Troppo lungo per me. Ma scommetto che $Gun giovane:una giovane; $C come te coglierebbe al volo l'occasione di viaggiare, vero?", enHash = "b5b1d761", vanilla = true },
        objectives = { it = "Parla con Morgan Stern, a Theramore.", enHash = "bb48c524", vanilla = true },
        reward = { it = "Oh, ti ha mandato mio zio, eh?\n\nBe', sto facendo ricerche sulle ricette e ho qualche pista, ma mi serve aiuto.\n\nL'aiuto di qualcuno che non abbia paura di bagnarsi i piedi.", enHash = "c535d86d", vanilla = true },
    },
    [1261] = {
        title = { it = "Marg parla", enHash = "2ea4d818", vanilla = true },
        text = { it = "Maledetto muckshell! Non puoi uccidere Marg! Ah, ma io sono morto. Quindi deve avermi ucciso...\n\nMa la mia missione! La mia missione! Tu, $N, devi portarla a termine.\n\nMentre ero vicino a Theramore, ho spiato un gruppo di soldati dell'Alleanza accampati sulla spiaggia. E un soldato portava un ciondolo... un ciondolo carico di più gemme di quante un soldato potrebbe mai permettersi!\n\nQuella notte mi sono intrufolato nel loro accampamento e ho rubato il ciondolo, ma sulla via del ritorno alla base un uomo-granchio muckshell mi ha ucciso!\n\n$N, devi trovare quel muckshell e recuperare il ciondolo!", enHash = "53da4957", vanilla = true },
        objectives = { it = "Porta il Jeweled Pendant a Nazeer, a Brackenwall Village.", enHash = "85adb3c2", vanilla = true },
        progress = { it = "$N, hai scoperto la sorte di Marg?", enHash = "faaad55f", vanilla = true },
        reward = { it = "Questo ciondolo lo portava un soldato di Stormwind??\n\nGrazie, $N. Hai svelato il segreto della morte di Marg. Ma questo ciondolo è un nuovo mistero da risolvere, un mistero che potrebbe avere conseguenze terribili per l'Alleanza, e per l'Orda.", enHash = "ea1197e4", vanilla = true },
    },
    [1262] = {
        title = { it = "Rapporto a Zor", enHash = "d0bd4d24", vanilla = true },
        text = { it = "È strano che il ciondolo rubato da Marg fosse nelle mani di semplici soldati. Forse il suo proprietario era travestito, o forse l'hanno rubato i soldati stessi!\n\nQualunque sia la verità, questo è il ciondolo di un nobile, e dobbiamo scoprire il suo vero proprietario se vogliamo svelarne il mistero.\n\nPorta il ciondolo a Zor Lonetree, a Orgrimmar. Conosce bene la politica dell'Alleanza, e saprà se questo ciondolo ha una storia tra i nobili di Stormwind.", enHash = "15f7afb0", vanilla = true },
        objectives = { it = "Porta il Jeweled Pendant a Zor Lonetree, a Orgrimmar.", enHash = "a84f16fe", vanilla = true },
        progress = { it = "Hai viaggiato da Brackenwall Village, nel Dustwallow? Come sta Nazeer, e come procedono i suoi sforzi nella palude?", enHash = "3d9e51f8", vanilla = true },
        reward = { it = "Questo ciondolo è stato lavorato con grande abilità e precisione, $N. Nessun orco desidererebbe un gioiello simile...\n\nMa molti umani sì.\n\nFarò studiare questo ciondolo. Speriamo che col tempo i suoi misteri ci vengano svelati.", enHash = "9d3e8060", vanilla = true },
    },
    [1264] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "All'inizio di ogni mese i Kul Tiras Marine vengono pagati e di solito lasciano Theramore per andare da qualche altra parte. Molti vengono qui a correre dietro alle donne, a far baldoria e a divertirsi. Uno di quei gruppi ormai lo considero di casa qui alla taverna, e credo che questo Hendel sia dei loro.\n\nCommander Samaul, a Theramore, potrebbe aiutarti a trovarlo se Hendel è ancora di stanza là. È del tutto fedele a Proudmoore, ma se fai il nome di Elling dovrebbe darti una mano... con discrezione.", enHash = "30df01ef", vanilla = true },
        objectives = { it = "Trova Commander Samaul, nel Dustwallow Marsh.", enHash = "0155dc94", vanilla = true },
        reward = { it = "Un piacere conoscerti, $N. Sono Commander Samaul. Comando io le forze di Miss Proudmoore qui a Theramore.\n\nAnche se sono molto occupato, se hai domande non farti problemi a parlare. Forse dovrò essere breve, ma non c'è motivo che io sia scortese se ti serve il mio aiuto.\n\nSe hai intenzione di viaggiare fuori città, ti consiglio di stare $Gattento:attenta;. Oltre a ogre, orchi e murloc, la parte meridionale della palude è piena di draghi neri.", enHash = "ab011804", vanilla = true },
    },
    [1265] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Hendel? Sì, conosco quell'uomo. Ma perché ti servirebbe uno dei miei soldati?\n\nTi manda Elling a cercarlo? Hmm, la cosa non mi piace. Elling non ti avrebbe mandato prima da me se la tua faccenda non fosse seria. Capisco se non puoi dirmi di cosa si tratta, ma sappi una cosa: ho il dovere di proteggere queste terre. Se hai intenzione di creare disordini, allora ti consiglio di informarmi di quel che puoi.\n\nCredo che Hendel fosse di stanza alla prima torre fuori Theramore. Sta' $Gattento:attenta;.", enHash = "e1233416", vanilla = true },
        objectives = { it = "Cerca a Sentry Point qualche traccia di Private Hendel.", enHash = "c2c635cd", vanilla = true },
        progress = { it = "Sì, $N?", enHash = "befc103a", vanilla = true },
        reward = { it = "L'uomo che cerchi, quello noto come Hendel, non è qui. Altre fonti hanno portato a Lady Proudmoore informazioni che credo tu già conosca. Mi ha chiesto di trovarti e di darti aiuto nella tua impresa. Se me lo permetti, ti dirò dove trovare Private Hendel, così potremo consegnarlo alla giustizia.", enHash = "8a591530", vanilla = true },
    },
    [1266] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Private Hendel è a ovest di qui. Al momento è di guardia e protegge alcuni degli infiltrati di Theramore mentre riposano. Tengono d'occhio la base dell'Orda, Brackenwall, e cercano qualunque altra cosa possa minacciare i nostri confini.\n\nNon dovresti avere problemi a trovarlo: cerca le tende lungo la strada.\n\nHo un'altra faccenda da sbrigare, ma ti raggiungerò presto. Se hai problemi, mi trovi sempre nella torre di Lady Proudmoore.", enHash = "d1ec646c", vanilla = true },
        objectives = { it = "Trova Private Hendel, nel Dustwallow Marsh.", enHash = "1f7a8a5e", vanilla = true },
        reward = { it = "Salve, $Gcittadino:cittadina;. Questo è un posto pericoloso in cui andare in giro. Se tieni alla vita, non mi fermerei troppo a lungo.\n\nSe fai domande brevi, vedrò di aiutarti. Tieni solo gli occhi aperti per quei luridi ogre. Si dice che ci sia una base dell'Orda da qualche parte nelle paludi. Gli infiltrati fanno quel che possono per trovarla, ma il lavoro va a rilento e abbiamo fatto pochi progressi.", enHash = "51ceb4e8", vanilla = true },
    },
    [1267] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        objectives = { it = "Parla con Jaina Proudmore, nel Dustwallow Swamp.", enHash = "05bb4830", vanilla = true },
        reward = { it = "Lascia che sia io la prima a ringraziarti per tutto quel che hai fatto, $N. Sei $Gstato:stata; una benedizione incredibile per la mia gente e per quella di Stormwind. Mi dispiace non aver potuto fare la tua conoscenza in circostanze migliori.\n\nCapisci anche che non posso ringraziarti apertamente per i tuoi sforzi, ma ti assicuro ancora una volta che sono apprezzati.\n\nQuando in futuro verrai a Theramore, cercami e cercherò di tenerti $Gaggiornato:aggiornata; sulla situazione.\n\nGrazie ancora, $N.", enHash = "31191d2c", vanilla = true },
    },
    [1268] = {
        title = { it = "Impronte di zoccoli sospette", enHash = "83045aa7", vanilla = true },
        text = { it = "File di impronte di zoccoli si allontanano dallo scheletro ancora fumante della Shady Rest Inn. Ci sono almeno alcune impronte visibili, e altre file di orme quasi impercettibili nel fango molle della palude.", enHash = "d00fab73", vanilla = true },
        objectives = { it = "Riferisci a Krog, a Brackenwall Village, delle impronte sospette alla Shady Rest Inn.", enHash = "87a9f648", vanilla = true },
        reward = { it = "Impronte di zoccoli... Potrebbero essere stati i quilboar, suppongo. O forse perfino i centauri. La loro presenza nelle Barrens non è trascurabile, e non mi sembrerebbe esagerato pensarli capaci di un gesto simile.\n\nTe l'ho detto? Non hanno soltanto bruciato la locanda... La donna e il cucciolo del proprietario sono stati uccisi. Brutta faccenda.\n\nComunque, manderò Kagoro a scoprire dove portano le tracce.", enHash = "ac50c526", vanilla = true },
    },
    [1269] = {
        title = { it = "Lieutenant Paval Reethe", enHash = "bc78d8d8", vanilla = true },
        text = { it = "Un luccichio a terra, sotto le macerie, attira il tuo sguardo. Togliendo i detriti e la cenere incrostati sull'oggetto, appare l'insegna di un'ancora d'oro su fondo bianco, smaltata sulla superficie: il simbolo di Theramore.\n\nSotto l'ancora è impresso in rilievo il nome \"Lieutenant Paval Reethe\".", enHash = "1af393cb", vanilla = true },
        objectives = { it = "Porta Reethe's Badge a Krog, a Brackenwall Village.", enHash = "bb783cb1", vanilla = true },
        progress = { it = "Hai trovato qualche pista su cosa è successo alla Shady Rest Inn?", enHash = "20edeb77", vanilla = true },
        reward = { it = "Conosco questo umano, Paval Reethe. Patetico, perfino per quelli della sua razza. Ha abbandonato i suoi commilitoni e ora si nasconde nei boschi.\n\nHo mandato Ogron a cercarlo. Alcuni degli altri sospettano che abbia rubato dalle nostre provviste. Mi pare di aver visto Ogron dirigersi a sud-est.", enHash = "f0d05815", vanilla = true },
    },
    [1270] = {
        title = { it = "La fuga di Stinky", enHash = "1aa7f941", vanilla = true },
        text = { it = "Grande, finalmente qualcosa che non vuole mangiarmi!!\n\nMi serve aiuto per tenere a bada le bestiacce di qui, e tu fai al caso mio, $Gamico:signora;.\n\nUn goblin di Ratchet che si chiama Mebok Mizzyrix ha bisogno di foglie di bogbean per una pozione, o roba simile... Sinceramente non m'importa il perché: pagava bene e io questa palude la conosco, quindi eccomi qui.\n\nPeccato che mi sia fatto circondare prima di trovare il bogbean! Puoi aiutarmi a uscire di qui e guardarmi le spalle mentre cerco la pianta di Mebok?", enHash = { "39a37498", "4abd1f9a" }, vanilla = true },
        objectives = { it = "Scorta \"Stinky\" Ignatz, poi parla con Mebok Mizzyrix, a Ratchet.", enHash = "0e68bad2", vanilla = true },
        reward = { it = "Stinky è passato di qui con le erbe che gli avevo chiesto, e mi ha detto che l'hai tirato fuori dai guai. Ottimo lavoro! Chi è amico di Stinky è amico mio!\n\nMi ha chiesto di darti questo se mai ti avessi visto, poco prima di tornarsene a sud, verso la palude.", enHash = "d0b402c4", vanilla = true },
    },
    [1271] = {
        title = { it = "Banchetto al Blue Recluse", enHash = "28feedc4", vanilla = true },
        reward = { it = "Mio nipote mi ha detto che l'hai aiutato nelle sue ricerche nel Dustwallow e che hai tirato fuori dai guai il suo socio. Beh, noi Stern restiamo uniti e non ci dimentichiamo dei nostri amici!\n\nQuindi lavati le mani, $N, perché stiamo per dare una festa in tuo onore!", enHash = "56cae8ef", vanilla = true },
    },
    [1273] = {
        title = { it = "Interrogare Reethe", enHash = "92dc0903", vanilla = true },
        text = { it = "Ci è voluto tanto, ma ho trovato Reethe. Si è nascosto bene, per essere un umano.\n\nOgron teme che sia diventato pazzo dopo tanto tempo nella palude. Vieni con me, così andiamo a farci dare delle risposte.", enHash = "5e77954b", vanilla = true },
        objectives = { it = "Vai con Ogron a parlare con Reethe, poi torna da Krog, a Brackenwall Village.", enHash = "8ec59965", vanilla = true },
        progress = { it = "Hai trovato Reethe?", enHash = "94cf05fb", vanilla = true },
        reward = { it = "Hmph. È un bene che Reethe non si aggiri più per la palude, ma è un peccato che gli umani siano fatti così fragili che lui non sia riuscito a riprendersi da una piccola ferita di freccia.\n\nSembra che questa pista del mistero non abbia portato da nessuna parte, e dobbiamo cercare altrove.", enHash = "20968b85", vanilla = true },
    },
    [1274] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Scusami, $Gsignore:signora;. Bishop DeLavey mi ha chiesto di rivolgermi agli avventurieri che potrebbero aiutarlo in una faccenda delicata.\n\nSe puoi andare a Stormwind Keep senza dare nell'occhio e parlargli appena ti è possibile, sono sicuro che apprezzerà il tuo aiuto. Ancora una volta, ti prego, sii $Gdiscreto:discreta;. È una faccenda di una certa importanza.", enHash = { "66c2a0db", "e7ebe2bb" }, vanilla = true },
        objectives = { it = "Trova Bishop DeLavey, a Stormwind Keep.", enHash = "8b0b12e7", vanilla = true },
        reward = { it = "Salve, $N. Io sono Bishop DeLavey.\n\nSe mi chiedi dei miei affari qui nella fortezza, di sicuro il giovane Thomas è riuscito a reclutarti per aiutare il nostro regno. È sempre stato bravo a seguire le mie richieste.\n\nTemo di non avere tempo per dilungarmi, quindi lascia che sia schietto... e ti prego, cerca di non farne cosa di dominio pubblico.", enHash = "1b1bf569", vanilla = true },
    },
    [1275] = {
        title = { it = "Studiare la corruzione", enHash = "b3eed2c3", vanilla = true },
        text = { it = "Gli sciocchi elfi del sangue si trastullano con la magia demoniaca. Non hanno visto cosa è successo ai naga e ai satiri di Kalimdor?\n\nTemo che gli elfi del sangue vadano incontro a una deformazione simile. Azeroth non può permettersi di dare alla luce un'altra razza immonda di mostri.\n\nDesidero studiare i tronchi encefalici dei satiri e dei naga, per dedurre verso quale destino siano diretti gli elfi. Nelle Blackfathom Deeps, sulla costa di Ashenvale, troverai sia satiri sia naga.\n\nÈ un lungo viaggio, $N.", enHash = "befcd664", vanilla = true },
        objectives = { it = "Gershala Nightwhisper, ad Auberdine, vuole 8 Corrupt Brain Stem.", enHash = "d67e1207", vanilla = true },
        progress = { it = "Una volta che avrò abbastanza campioni da studiare, potrà cominciare il mio vero lavoro. Con i tronchi encefalici corrotti dei satiri e dei naga delle Blackfathom Deeps posso provare a stabilire una correlazione tra le mutazioni.\n\nForse, con quella conoscenza, potremo impedire agli elfi del sangue di sprofondare ancora di più nella deformità e nel male.", enHash = "aa35b629", vanilla = true },
        reward = { it = "Hai viaggiato a lungo e senza dubbio hai affrontato grandi pericoli.\n\nLe tue azioni sono state altruiste. È per il bene di tutta Azeroth che mi aiuti nella mia ricerca. Ti ringrazio, $N, per tutto quello che hai fatto.\n\nOra, se vuoi scusarmi, ho molto lavoro da fare...", enHash = "b65cfa8e", vanilla = true },
    },
    [1276] = {
        title = { it = "Lo scudo nero", enHash = "1ef1d9f9", vanilla = true },
        text = { it = "Ah, ora ricordo! Mosarn è un fabbro molto stimato di Thunder Bluff. Sapevo di aver già sentito il suo nome da qualche parte.\n\nPer ringraziarmi, il Circolo della Terra mi ha donato un'armatura forgiata da Mosarn. Ottimo lavoro.\n\nForse può dirti di più sullo scudo che ha forgiato.\n\nNon è una gran pista, ma visto che da Reethe non abbiamo ricavato niente di utile, è tutto quello che abbiamo.", enHash = "51bfd3ed", vanilla = true },
        objectives = { it = "Mostra il Blackened Iron Shield a Mosarn, a Thunder Bluff.", enHash = "19c15d81", vanilla = true },
        progress = { it = "Salve, $C. Posso aiutarti in qualcosa?", enHash = "ff5d9c21", vanilla = true },
        reward = { it = "Sì, hai senz'altro ragione. Questo è uno scudo fatto da me.\n\nTemo però di non poterti dire molto altro, $N. Forgio così tanti scudi e armature diversi che non riesco a ricordarmeli tutti.", enHash = "d8e41928", vanilla = true },
    },
    [1282] = {
        title = { it = "Lo chiamano Smiling Jim", enHash = "030a3cd5", vanilla = true },
        text = { it = "Non posso farci niente se mi dispiace per il vecchio Jim, laggiù. Non è sempre stato così. Per un po' ha gestito una locanda là fuori nella palude, un posto meraviglioso.\n\nSenti, non ho proprio voglia di parlarne. Chiedi a Captain Vimes, se proprio devi.", enHash = "61381010", vanilla = true },
        objectives = { it = "Parla con Captain Garran Vimes, a Theramore.", enHash = "e3ed198b", vanilla = true },
        reward = { it = "Il suo vero nome è James Hyal. Ha aperto una locanda al limitare delle Barrens. Voleva creare un bel posto dove i viaggiatori potessero fermarsi...\n\nForse puntava troppo in alto, ma per un po' la locanda è andata bene. Poi abbiamo perso il controllo delle strade nella palude, e gli ogre hanno preso il sopravvento.\n\nJames era troppo testardo per rinunciare al suo sogno in cambio della sicurezza dentro le nostre mura, e la Shady Rest Inn è stata rasa al suolo dalle fiamme. Stiamo indagando, ma finora con poca fortuna. Se vuoi dare una mano, guarda cosa riesci a trovare tra le macerie.", enHash = "3ec57469", vanilla = true },
    },
    [1284] = {
        title = { it = "Impronte di zoccoli sospette", enHash = "83045aa7", vanilla = true },
        text = { it = "File di impronte di zoccoli si allontanano dallo scheletro ancora fumante della Shady Rest Inn. Ci sono almeno alcune impronte visibili, e altre file di orme quasi impercettibili nel fango molle della palude.", enHash = "d00fab73", vanilla = true },
        objectives = { it = "Riferisci a Captain Garran Vimes, a Theramore, delle impronte sospette alla Shady Rest Inn.", enHash = "fe51c4d7", vanilla = true },
        reward = { it = "Impronte di zoccoli, eh? È vero che nelle terre vicino al Dustwallow Marsh c'è un'attività straordinaria di centauri. In brevi incursioni nelle Barrens abbiamo trovato i loro accampamenti e i loro possedimenti sparsi per la zona.\n\nManderò Falgran Hastil, uno dei nostri esploratori, a vedere se riesce a scoprire dove portano le tracce.", enHash = "ed79abea", vanilla = true },
    },
    [1285] = {
        title = { it = "Gli uomini di Daelin", enHash = "f91f682b", vanilla = true },
        text = { it = "Reddon... Redpath... Ah, eccolo! Lieutenant Paval Reethe.\n\nSi è unito alla guardia di Theramore insieme alla maggior parte delle reclute che hanno attraversato il mare con Lady Proudmoore. Arruolato nella fanteria di marina di Kul Tiras all'età di sedici anni. Servizio distinto, promozioni...\n\nRisulta disperso.", enHash = "df9ae36c", vanilla = true },
        objectives = { it = "Riporta a Captain Garran Vimes, a Theramore, le informazioni su Reethe.", enHash = "08b6c4e9", vanilla = true },
        reward = { it = "Disperso? È il modo gentile di Tesoran per dire traditore.\n\nSenza dubbio è uno di quegli stolti così ciecamente fedeli ad Admiral Daelin da diventare un traditore. Non è un'ironia deliziosa? I disertori accusano noi di tradire l'Alleanza.", enHash = "df722e2f", vanilla = true },
    },
    [1286] = {
        title = { it = "I disertori", enHash = "d7c7ac42", vanilla = true },
        text = { it = "È stata una lotta mantenere una presenza nella palude, ma grazie alla forza della nostra determinazione siamo riusciti a mantenere diverse torri di guardia difensive in tutta la zona.\n\nLe ultime informazioni e i rapporti degli esploratori che ho ricevuto indicano che un gruppo di disertori si è stabilito abusivamente nella nostra torre abbandonata a Lost Point, a sud-est della locanda.\n\nIl capo dei disertori è un uomo di nome Jacken. Vedi se riesci a cavargli qualche informazione.\n\nTi avverto, $N. Potrebbe essere un osso duro.", enHash = "03d14a8c", vanilla = true },
        objectives = { it = "Ottieni informazioni su Reethe da Balos Jacken e dai disertori, nel Dustwallow Marsh.", enHash = "cefe8aa6", vanilla = true },
        reward = { it = "Ti ha mandato Vimes? Non poteva fare il lavoro sporco da solo, eh...", enHash = "0cb834c9", vanilla = true },
    },
    [1287] = {
        title = { it = "I disertori", enHash = "d7c7ac42", vanilla = true },
        text = { it = "Reethe? Quel codardo?\n\nL'abbiamo cacciato dal campo perché insisteva a razziare le provviste degli ogre su a Brackenwall Village. Non siamo abbastanza numerosi da poter tener testa a quei bruti senza cervello.\n\nHa passato il limite una volta di troppo, così l'abbiamo lasciato a cavarsela da solo.\n\nOra, io ti ho aiutato... Allora perché non aiuti noi e ti dimentichi di averci incontrati?", enHash = "d2ee4e09", vanilla = true },
        objectives = { it = "Parla con Captain Garran Vimes, a Theramore, di Reethe.", enHash = "895d497f", vanilla = true },
        reward = { it = "Manderò Lieutenant Caldwell a occuparsi dei disertori a Lost Point. Inoltre gli darò ordine di trovare Reethe. La palude non è così grande e senza sentieri da impedirgli di trovarlo.", enHash = "7f229cf2", vanilla = true },
    },
    [1288] = {
        title = { it = "Vimes's Report", enHash = "577c2960", vanilla = true },
        text = { it = "Hai fatto un buon lavoro, $N, il migliore che abbia mai visto da parte di $Gun dilettante:una dilettante;.\n\nLady Proudmoore mi ha chiesto di tenerla informata su questa situazione delicata, e ormai è da un po' che non le parlo.\n\nAvevo intenzione di consegnarle il mio rapporto più tardi, ma mi sembra più giusto che sia tu a parlargliene. Probabilmente puoi rispondere alle sue domande meglio di me.", enHash = "6ba62f41", vanilla = true },
        objectives = { it = "Porta Vimes's Report a Lady Jaina Proudmoore, a Theramore.", enHash = "136cdf76", vanilla = true },
    },
    [1289] = {
        title = { it = "Vimes's Report", enHash = "577c2960", vanilla = true },
        text = { it = "Bene, a giudicare dal rapporto di Captain Vimes, hai dato un enorme aiuto alla sua indagine, e per questo ti ringrazio.\n\nHo la mente più in pace sapendo che la faccenda è in mani così capaci. Se vuoi, ti chiederei di tornare da Captain Vimes e di aiutarlo ad andare fino in fondo a questo mistero.", enHash = "3ce499df", vanilla = true },
        objectives = { it = "Torna da Captain Garran Vimes, a Theramore.", enHash = "420d8314", vanilla = true },
    },
    [1301] = {
        title = { it = "James Hyal", enHash = "343dba58", vanilla = true },
        text = { it = "Prima di lavorare qui al Blue Recluse, sono stato istruito da uno dei migliori cuochi e locandieri che abbia mai conosciuto. Si chiamava James Hyal. Tutto quel che ho e tutto quel che ho raggiunto nella vita lo devo a lui.\n\nMi chiedo come se la passi. Lui e suo fratello Vincent sono andati a lavorare in una taverna a Menethil Harbor, ma da un po' non ho sue notizie.\n\nSe mai dovessi andare da quelle parti, magari potresti salutarlo da parte mia?", enHash = "e72573bc", vanilla = true },
        objectives = { it = "Parla con Vincent Hyal, a Menethil Harbor.", enHash = "969e1f68", vanilla = true },
        reward = { it = "James? Oh, se n'è andato parecchio tempo fa.\n\nGli è tornata la voglia di patria, immagino. Non è difficile capire perché. Con tutta la follia che c'è in Lordaeron, molti si sono uniti a Jaina Proudmoore quando ha attraversato il mare.", enHash = "2c6bf9a9", vanilla = true },
    },
    [1302] = {
        title = { it = "James Hyal", enHash = "343dba58", vanilla = true },
        text = { it = "Mio fratello James è partito con Lady Proudmoore oltre il mare. L'ultima volta che ne ho avuto notizia, i combattimenti laggiù si erano calmati e James stava aprendo una locanda da qualche parte sul continente. Ovunque sia, sono sicuro che gli affari gli vanno bene. Era un gran cuoco.\n\nNon ho sue notizie da un pezzo ormai (troppo preso dalla locanda, scommetto), ma l'impiegato di Theramore potrebbe indicarti dove trovarlo.", enHash = "a302902b", vanilla = true },
        objectives = { it = "Parla con Clerk Lendry, a Theramore.", enHash = "5ff92201", vanilla = true },
        reward = { it = "James Hyal, James Hyal... Perché quel nome mi suona così familiare?\n\nMa certo! L'incidente della Shady Rest Inn. Se hai qualche informazione su quello che è successo laggiù, ti consiglio vivamente di parlarne con Captain Vimes. È lui che segue le indagini.", enHash = "e206d11a", vanilla = true },
    },
    [1319] = {
        title = { it = "Lo scudo nero", enHash = "1ef1d9f9", vanilla = true },
        text = { it = "Mi dispiace non poterti essere di grande aiuto, $N, ma posso indirizzarti da qualcuno che lo sarebbe. Caz Twosprocket, uno dei nostri migliori fabbri, lavora alla forgia della bottega del fabbro.\n\nPortagli lo scudo e senti cosa sa dirti.", enHash = "46b82ec6", vanilla = true },
        objectives = { it = "Mostra il Blackened Iron Shield a Caz Twosprocket, a Theramore.", enHash = "f6b125b2", vanilla = true },
        progress = { it = "Qualcosa da farmi vedere?", enHash = "7330b085", vanilla = true },
        reward = { it = "Hm... interessante pezzo di ferro, quello che hai qui. Di sicuro non l'ha fatto nessuno dei fabbri che conosco da questa parte del mare, e di certo non è opera mia.", enHash = "357c7922", vanilla = true },
    },
    [1320] = {
        title = { it = "Lo scudo nero", enHash = "1ef1d9f9", vanilla = true },
        text = { it = "Ah, per poco non mi sfuggiva... La cinghia di cuoio sul retro dev'essere bruciata, ma sembra fatta per una persona grossa. Direi un tauren, a dire il vero.\n\nÈ più o meno tutto quello che posso dirti. Di' a Captain Vimes che mi dispiace di non aver potuto aiutare di più.", enHash = "4edf475d", vanilla = true },
        objectives = { it = "Parla con Captain Garran Vimes, a Theramore.", enHash = "e3ed198b", vanilla = true },
        reward = { it = "Non sono molte informazioni su cui lavorare, ma dovremo tenerne conto. Speriamo che altri pezzi di questo mistero vadano al loro posto e ci diano un quadro più utile di quello che è successo.", enHash = "81131684", vanilla = true },
    },
    [1321] = {
        title = { it = "Lo scudo nero", enHash = "1ef1d9f9", vanilla = true },
        text = { it = "Hmm... non vedo niente di strano in questo scudo. Dovremmo farlo vedere a Do'gol, il fabbro, e sentire se può dirci qualcosa di più, ma non ci spererei troppo...", enHash = "f8a76c4d", vanilla = true },
        objectives = { it = "Mostra il Blackened Iron Shield a Do'gol, a Brackenwall Village.", enHash = "f9972cb4", vanilla = true },
        progress = { it = "Qualcosa per me, $C?", enHash = "b2e077d7", vanilla = true },
        reward = { it = "Questo è un buono scudo. Molto forte, pesante, buono. Ma a Do'gol non serve. Io gli scudi li faccio, non li compro, $N.\n\nDovresti saperlo.", enHash = "c1bb6971", vanilla = true },
    },
    [1322] = {
        title = { it = "Lo scudo nero", enHash = "1ef1d9f9", vanilla = true },
        text = { it = "Hmmm, c'è una scritta proprio qui sul bordo dello scudo, ma è difficile da leggere con tutta questa roba bruciata.\n\nMi serve dell'acido per renderla chiara. Il veleno dei Darkfang Spider della palude andrebbe bene. Portami un po' delle loro sacche e posso ripulirlo.", enHash = "81f1c15a", vanilla = true },
        objectives = { it = "Procura 6 Acidic Venom Sac per Do'gol, a Brackenwall Village.", enHash = "60afb09a", vanilla = true },
        progress = { it = "Hai preso quelle sacche dai ragni?", enHash = "ef47448c", vanilla = true },
        reward = { it = "Non mi piacciono i ragni così grossi che non posso sedermici sopra e schiacciarli.\n\nGrazie di averle prese, $N. Ora le squarcio e le verso sullo scudo...", enHash = "130d0275", vanilla = true },
    },
    [1323] = {
        title = { it = "Lo scudo nero", enHash = "1ef1d9f9", vanilla = true },
        text = { it = "Oh, credo di aver versato troppo acido sullo scudo. Fammi solo strofinare un po'...\n\nHm, si legge a fatica, ma sembra il nome Mosarn. Mai sentito nominare. Forse Krog lo sa. Krog conosce tanta gente.", enHash = "f8f4e79f", vanilla = true },
        objectives = { it = "Parla con Krog, a Brackenwall Village.", enHash = "30b36056", vanilla = true },
        reward = { it = "Mosarn? Mi dice qualcosa... ma non riesco a ricordare cosa. Forse mi verrà in mente più tardi.\n\nProbabilmente non è importante. Uno scudo può venire da qualsiasi parte e non significare niente...", enHash = "13b5670c", vanilla = true },
    },
    [1324] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Cosa?! Vieni qui ad accusarmi di essermi alleato con i Defias, e pensi che me ne starò qui fermo mentre mi insulti?! Qualcosa mi dice che te la sei cercata da un pezzo.", enHash = "ab5bfb9e", vanilla = true },
        objectives = { it = "Sconfiggi Private Hendel, nel Dustwallow Marsh.", enHash = "a37ba8d8", vanilla = true },
        progress = { it = "Ciao di nuovo, $N. Spero non ti dispiaccia l'aiuto, ma non potevamo permetterci che Hendel scappasse o, peggio, che ci restasse secco.", enHash = "ee8d957a", vanilla = true },
        reward = { it = "Ti assicuro che siamo tutti parecchio scossi da quel che sta succedendo, ma lascia che lo riportiamo a Theramore per qualche domanda, e vedremo di trovare il Re.\n\nSono sicuro che la mia signora Proudmore vorrà ringraziarti per l'aiuto. Parlale quando hai un momento.", enHash = "b66a64c5", vanilla = true },
    },
    [1338] = {
        title = { it = "L'ordinazione di Stormpike", enHash = "67f6b0d6", vanilla = true },
        text = { it = "C'è un armaiolo nanico il cui lavoro ammiro moltissimo. Si chiama Furen Longbeard, e la sua abilità non ha rivali. Mi serve uno scudo nuovo, e deve essere uno dei suoi!\n\nIl problema è che... Furen è molto più a sud, nel quartiere dei nani dentro Stormwind. In terra umana! Non riesco a immaginare perché viva là, così lontano da Ironforge. Gli umani devono pagarlo a peso d'oro per tenerlo lì!\n\nAllora, se hai voglia di viaggiare e non ti dispiace guadagnare qualcosa, gli porteresti la mia richiesta di uno scudo?", enHash = "a1ef9252", vanilla = true },
        objectives = { it = "Porta Stormpike's Request a Furen Longbeard, a Stormwind.", enHash = "a8601fea", vanilla = true },
        progress = { it = "Una lettera dalle terre dei nani? Chissà chi mi chiama da così lontano, a nord...\n\nTi prego, fammi vedere l'ordinazione.", enHash = "503eb1a8", vanilla = true },
        reward = { it = "Ah, una richiesta da uno degli Stormpike. È un clan orgoglioso, pieno di nani di qualità. E anche ricchi.\n\nGrazie, $N. Entro fine giornata mi metto al lavoro sullo scudo di Mountaineer Stormpike.", enHash = "3b18531d", vanilla = true },
    },
    [1339] = {
        title = { it = "Il compito di Mountaineer Stormpike", enHash = "a993a398", vanilla = true },
        text = { it = "Ho sentito che Mountaineer Stormpike cerca un corriere. Qualcuno che viaggi un po' per lui. Che ne dici? Sei tu $Gil:la; $R che fa al caso?\n\nSe è così, Stormpike lo trovi in cima alla torre di guardia a nord.", enHash = "6d3cbfd4", vanilla = true },
        objectives = { it = "Parla con Mountaineer Stormpike.", enHash = "32c4e059", vanilla = true },
        reward = { it = "Proprio così. Ho un compito che non posso svolgere mentre sono di guardia. Anzi, ti porterà lontano dal Loch Modan.\n\nL'occasione perfetta per un'avventura!", enHash = "ae617bee", vanilla = true },
    },
    [1358] = {
        title = { it = "Un campione per Helbrim", enHash = "040efb36", vanilla = true },
        text = { it = "Un collega a Kalimdor, Apothecary Helbrim, sta studiando gli effetti delle tossine di Lordaeron sulle bestie di Kalimdor. Sarebbe molto interessato a un campione dei cuori di lupo che mi ha mandato Renferrel.\n\nHelbrim è di stanza nelle Barrens, in un villaggio chiamato Crossroads. Per raggiungerlo, devi prendere lo zeppelin fino alla capitale degli orchi, Orgrimmar, poi viaggiare a piedi verso sud, fino a Durotar. Va' a ovest nelle Barrens e raggiungerai presto il Crossroads.", enHash = "f1dd2109", vanilla = true },
        objectives = { it = "Porta il Wolf Heart Sample ad Apothecary Helbrim, nelle Barrens.", enHash = "36b20b20", vanilla = true },
        progress = { it = "Hai un pacco per me?", enHash = "ad4bd2a0", vanilla = true },
        reward = { it = "Ah, molto bene. Se i primi rapporti sono veri, la tossicità di questi cuori potrebbe portare a nuovi progressi nella nostra conoscenza dei veleni.\n\nÈ una consegna gradita, $N. La tua ricompensa è ben meritata.", enHash = "a4bcf8ea", vanilla = true },
    },
    [1359] = {
        title = { it = "La consegna per Zinge", enHash = "8d14d80b", vanilla = true },
        text = { it = "I cuori di lupo che hai procurato hanno una qualità mai vista in esemplari simili. Contengono una tossicità che dovrebbe essere letale per gli stessi lupi in cui battono quei cuori!\n\nÈ davvero incredibile, e dobbiamo studiarlo meglio. Ho tenuto qualche campione dei cuori. Portali alla mia collega, Apothecary Zinge. La troverai nel nostro quartier generale, nell'Undercity.", enHash = "ddfa4f6c", vanilla = true },
        objectives = { it = "Porta i Wolf Heart Samples ad Apothecary Zinge, nell'Undercity.", enHash = "ceb869cb", vanilla = true },
        progress = { it = "Hai qualcosa per me?", enHash = "ac74d893", vanilla = true },
        reward = { it = "Ah sì, i campioni di cuore di cui parlava Renferrel. Non vedo l'ora di sperimentarli... alla Royal Apothecary Society interessa sempre quando si scoprono nuove forme di tossine.", enHash = "fffc2efc", vanilla = true },
    },
    [1360] = {
        title = { it = "Tesori recuperati", enHash = "745655cc", vanilla = true },
        text = { it = "Avevo un bel lavoro come scavatore al sito di scavo di Uldaman, nelle Badlands... finché non sono arrivati quei maledetti trogg. Sono scampato per un pelo con la pelle a malapena intera, e nient'altro. Nel caos ho lasciato il mio bene più prezioso. È al sicuro dai trogg nel mio forziere, certo, ma proprio in mezzo a loro.\n\nTi sarei debitore, sia in onore sia in monete, se potessi andarlo a prendere per me! In fondo alla North Common Hall c'è un forziere con il mio nome sopra. È quello che devi aprire.", enHash = "9de1c1a3", vanilla = true },
        objectives = { it = "Prendi il bene più prezioso di Krom Stoutarm dal suo forziere nella North Common Hall di Uldaman, e portalo a Krom, a Ironforge.", enHash = "55d0044b", vanilla = true },
        progress = { it = "Allora, sei $Griuscito:riuscita; a tenere a bada quei trogg abbastanza a lungo da aprire il mio forziere e prendere il mio tesoro?", enHash = "48da6032", vanilla = true },
        reward = { it = "Ah, mi sento di nuovo completo: grazie di cuore.\n\nAlcuni nani apprezzano la lucentezza del metallo, e altri lo scintillio delle gemme... ma uno Stoutarm senza il suo prezioso boccale in mano non è quasi più uno Stoutarm!", enHash = "4d6c23a6", vanilla = true },
    },
    [1361] = {
        title = { it = "Regthar Deathgate", enHash = "ce331218", vanilla = true },
        text = { it = "Un guerriero dell'Orda, Regthar Deathgate, sta reclutando agenti per una missione nella terra di Desolace. Parla con lui se vuoi offrirti come $Gvolontario:volontaria;. È di stanza nelle Barrens, in una serie di bunker a ovest del Crossroads.\n\nE affila le armi. Desolace è un luogo dilaniato dalla guerra.", enHash = "d2026dd2", vanilla = true },
        objectives = { it = "Parla con Regthar Deathgate.", enHash = "217e8c62", vanilla = true },
        reward = { it = "Sì, sto reclutando. Questa missione porta a Desolace, contro i centauri che ci vivono. Sarò breve, così potrai cominciare subito.", enHash = "7faef67b", vanilla = true },
    },
    [1362] = {
        title = { it = "I Kolkar di Desolace", enHash = "71aa4420", vanilla = true },
        text = { it = "I centauri Kolkar vivono a Desolace, e le loro forze si sono estese fino alle Barrens. È un fatto noto, e qui abbiamo agenti dell'Orda che se ne occupano.\n\nMa finché i centauri saranno forti a Desolace, saranno sempre una minaccia. È ora di liberarci di quella minaccia.\n\nParla con Felgur Twocuts al Ghost Walker Post, a Desolace. È stato mandato a raccogliere informazioni sui centauri. Saprà come affrontare al meglio i Kolkar di Desolace.", enHash = "2a89ce16", vanilla = true },
        objectives = { it = "Parla con Felgur Twocuts al Ghost Walker Post, a Desolace.", enHash = "b8a5c833", vanilla = true },
        reward = { it = "Sei qui per ordine di Regthar? Allora sei qui per occuparti dei centauri. Bene.\n\nSpero che tu sia $Griposato:riposata;. Non so come finirà la nostra campagna contro i centauri, ma so che la lotta sarà lunga.\n\nSiediti e ascolta.", enHash = "27ba0f00", vanilla = true },
    },
    [1363] = {
        title = { it = "L'incarico di Mazen", enHash = "75dcbca6", vanilla = true },
        text = { it = "In quanto custode delle opere di questa biblioteca dell'Academy of Arcane Arts and Sciences, è mia responsabilità assicurarmi che tutti i tomi e le pergamene magiche siano sempre al loro posto. Chissà quali follie succederebbero se alcuni di questi testi incantati finissero nelle mani sbagliate?\n\nIl che mi ricorda... il mio assistente, Dellis, la settimana scorsa ha fatto un errore terribile. In biblioteca se la cava bene, ma quando esce dalle porte di Stormwind è un incapace. Fa' $Gl'eroe:l'eroina;, e aiuta il vecchio Dellis, vuoi?", enHash = "0042891d", vanilla = true },
        objectives = { it = "Parla con Acolyte Dellis, a Stormwind.", enHash = "a592a184", vanilla = true },
        reward = { it = "Non è stata colpa mia. Davvero, non è stata colpa mia.", enHash = "2003f723", vanilla = true },
    },
    [1364] = {
        title = { it = "L'incarico di Mazen", enHash = "75dcbca6", vanilla = true },
        text = { it = "Le istruzioni del maestro Mazen erano chiarissime: consegnare un saggio importantissimo a Watcher Mahar Ba, a Nethergarde Keep.\n\nMa io non ero mai stato nelle Blasted Lands! Il viaggio è stato spaventoso!\n\nQuando sono arrivato nella Swamp of Sorrows, ho sbagliato strada e mi sono ritrovato circondato da orribili creature della palude simili a piante. Barcollavano verso di me come per attaccarmi, e così sono scappato. Ma nella fretta ho perso il saggio. Una di quelle bestie l'ha preso, ne sono sicuro.\n\nPotresti provare a recuperarlo e consegnarlo a Mahar Ba?", enHash = "e90c493f", vanilla = true },
        objectives = { it = "Recupera Khadgar's Essays on Dimensional Convergence e consegnali a Watcher Mahar Ba, a Nethergarde Keep.", enHash = "7f059817", vanilla = true },
        progress = { it = "Che cosa ti porta a Nethergarde Keep, $R?", enHash = "39b561b8", vanilla = true },
        reward = { it = "Ah, splendido!\n\nPer un po' ho temuto che la mia richiesta di Khadgar's Essays on Dimensional Convergence fosse stata trascurata dal maestro Mazen dell'Academy of Arcane Arts and Sciences.\n\nDev'essere sommerso di richieste, visti i tanti strani avvenimenti in corso.\n\nOra, se vuoi scusarmi, devo cominciare subito le mie ricerche. Poter finalmente intravedere il pensiero di qualcuno grande come Khadgar mi entusiasma senza fine.", enHash = "98d6b44c", vanilla = true },
    },
    [1365] = {
        title = { it = "Khan Dez'hepah", enHash = "1f70f9b6", vanilla = true },
        text = { it = "I Kolkar non sono gli unici centauri di Desolace. Molti clan vagano per queste pianure aride, combattendo e morendo l'uno contro l'altro. Ed è un bene che combattano tra loro, perché sono forti e brutali. Se i centauri si unissero contro di noi, sarebbero un nemico feroce.\n\nDobbiamo occuparci di loro prima che si uniscano.\n\nIl tuo primo compito è gettare nel caos il clan Kolkar. Fallo uccidendo il suo capo, Khan Dez'hepah.\n\nIl Kolkar Village è a nord-est di qui. Va', e che la fortuna ti accompagni.", enHash = "0d7cc333", vanilla = true },
        objectives = { it = "Porta Khan Dez'hepah's Head a Felgur Twocuts, a Desolace.", enHash = "2a2f5f56", vanilla = true },
        progress = { it = "$N, hai sconfitto Khan Dez'hepah?", enHash = "2cc9ded6", vanilla = true },
        reward = { it = "Ben fatto. Questa rapida azione contro i Kolkar è un'efficace dimostrazione di forza, e la forza è ciò che i centauri capiscono meglio.\n\nLa morte del capo dei Kolkar non solo getterà nel caos quel clan, ma farà riflettere anche gli altri.", enHash = "2591af09", vanilla = true },
    },
    [1366] = {
        title = { it = "Taglia sui centauri", enHash = "18228bf5", vanilla = true },
        text = { it = "Ora che hai spaventato i clan dei centauri, è il momento di dissanguarli. Quando viaggi per Desolace, dai la caccia ai centauri. Non m'importa a quale clan. Raccogli orecchie e basta. Un mucchio di orecchie.\n\nRiducendo il loro numero indebolirai la loro determinazione e soffocherai ogni pensiero di espansione.\n\nBuona caccia, $N.", enHash = "7fd5168a", vanilla = true },
        objectives = { it = "Porta 15 Centaur Ear a Felgur Twocuts, a Desolace.", enHash = "efadc4f1", vanilla = true },
        progress = { it = "Come va la tua collezione di orecchie, $N? È grande?", enHash = "b404a51a", vanilla = true },
        reward = { it = "Ormai i centauri devono conoscere il tuo nome. Sono sicuro che lo conoscono, lo rispettano e lo temono. E così come conoscono te, conoscono lo stendardo sotto cui cavalchi.\n\nLo stendardo dell'Orda.", enHash = "0ebac884", vanilla = true },
    },
    [1367] = {
        title = { it = "Alleanza con i Magram", enHash = "9d7772cc", vanilla = true },
        text = { it = "Per battere i centauri dobbiamo usare il loro odio contro di loro. Ci alleeremo con uno dei clan e, attraverso di loro, impareremo a sconfiggere tutti i clan.\n\nSe scegli di allearti con i Magram, uccidi i loro nemici, i Gelkis. Così ti guadagnerai il rispetto dei Magram. Quando ne avrai abbastanza, incontra il portavoce dei Magram, Warug, ai margini del Magram Village, nel sud-est di Desolace.", enHash = "465af417", vanilla = true },
        objectives = { it = "Raggiungi la reputazione Friendly con i Magram, poi parla con Warug.", enHash = "23322953", vanilla = true },
        progress = { it = "Vattene! I Magram non parlano con i deboli. Noi li uccidiamo!\n\nSe vuoi parlare con me, dimostrami che sei forte. Torna dopo aver ucciso molti Gelkis.", enHash = "485ff21d", vanilla = true },
        reward = { it = "I Gelkis piangono quando sentono il tuo nome, $N. Ti temono e ti odiano. Ti odiano come odiano i Magram!\n\nForse sei forte come i Magram. Vedremo...", enHash = "90ebc660", vanilla = true },
    },
    [1368] = {
        title = { it = "Alleanza con i Gelkis", enHash = "dd5bf370", vanilla = true },
        text = { it = "Per battere i centauri dobbiamo usare il loro odio contro di loro. Ci alleeremo con uno dei clan e, attraverso di loro, impareremo a sconfiggere tutti i clan.\n\nSe scegli di allearti con i Gelkis, uccidi i loro rivali più odiati, i Magram. Dopo aver ottenuto il rispetto dei Gelkis, incontra la sciamana dei Gelkis, Uthek the Wise, ai margini del Gelkis Village, nel sud-ovest di Desolace.", enHash = "9d59f2ab", vanilla = true },
        objectives = { it = "Raggiungi la reputazione Friendly con i Gelkis, poi parla con Uthek the Wise.", enHash = "af11feef", vanilla = true },
        progress = { it = "I tuoi due piedi calpestano la terra dei Gelkis. Qui non sei $Gbenvenuto:benvenuta;!\n\nDimostra che cerchi l'amicizia dei Gelkis. Uccidi i centauri Magram. Torna quando il terreno sarà bagnato di sangue Magram.", enHash = "7487d8d9", vanilla = true },
        reward = { it = "La terra mi parla. E dice che hai ucciso molti Magram. Questo è bene.\n\nSe sei $Gun amico:un'amica; dei Gelkis, allora ascolta. Ho altri compiti per te.", enHash = "4283b9ee", vanilla = true },
    },
    [1369] = {
        title = { it = "Broken Tears", enHash = "183ca246", vanilla = true },
        text = { it = "I Gelkis pensano che Theradras, la madre di noi centauri, ci protegga. Sono stupidi. Nessuno protegge i centauri. I Magram non hanno bisogno di protezione! Siamo i più forti!\n\nMostra ai Gelkis che sono stupidi. Va' nella grotta del loro villaggio. In quella grotta accumulano cristalli, le lacrime di Theradras. Distruggi le lacrime e portami i pezzi rotti!", enHash = "1cbc9e7d", vanilla = true },
        objectives = { it = "Mantieni la tua reputazione con i Magram e porta 3 Broken Tear a Warug, al Magram Village.", enHash = "6729d65b", vanilla = true },
        progress = { it = "Se non sei $Gnostro nemico:nostra nemica;, farai quello che ti chiedo!", enHash = "9ca10efb", vanilla = true },
        reward = { it = "Hai preso le lacrime! Ora i Gelkis sapranno che Theradras non li aiuterà. Non piangerà quando li schiacceremo! I Magram regneranno!\n\nSei $Gfurbo:furba; ad aiutarci, $N. Siamo i più forti.", enHash = "aea3757a", vanilla = true },
    },
    [1370] = {
        title = { it = "Rubare le provviste", enHash = "ab60531a", vanilla = true },
        text = { it = "Quando non siamo in guerra, cacciamo per procurarci carne. La carne ci dà forza, e le pance piene combattono meglio di quelle vuote.\n\nÈ lo stesso per i Magram. Mettono da parte carne in più per poter combattere più a lungo tra una caccia e l'altra. Se fai razzia nel loro villaggio a est e prendi le loro scorte di carne, la loro forza verrà meno.", enHash = "954b376d", vanilla = true },
        objectives = { it = "Porta 6 sacchetti di Crudely Dried Meat a Uthek the Wise, al Gelkis Village.", enHash = "333f459f", vanilla = true },
        progress = { it = "Torna dopo aver dimostrato ancora il tuo valore ai Gelkis!", enHash = "115f37d0", vanilla = true },
        reward = { it = "Bene. Sento brontolare le rumorose pance dei Magram fin dal loro villaggio, lontano!\n\nDarò questa carne ai Gelkis. E combatteremo per molti giorni senza riposo.\n\nQuello che hai fatto è un bene per i Gelkis, $N.", enHash = "86fc5986", vanilla = true },
    },
    [1371] = {
        title = { it = "Un aggeggio per Warug", enHash = "be6e803d", vanilla = true },
        text = { it = "Tanto tempo fa, un piccolo gnomo venne a Desolace. Aveva cavalli e un carro, e il carro conteneva cose strane. Cose buffe. Cose che bruciavano di colori diversi. Cose che si muovevano e non erano vive. Ho ucciso il piccolo gnomo, ma prima... mi ha fatto ridere.\n\nMi sono tenuto la cosa che mi piaceva di più del suo carro. Era un umano di legno, e mi salutava con la mano finché non l'ho colpito e rotto.\n\nNe voglio uno nuovo. Portamene uno nuovo!", enHash = "f9e1dd42", vanilla = true },
        objectives = { it = "Mantieni la tua reputazione con i Magram e porta un Advanced Target Dummy a Warug, al Magram Village, a Desolace.", enHash = "265461dd", vanilla = true },
        progress = { it = "Se non sei $Gnostro nemico:nostra nemica;, farai quello che ti chiedo!", enHash = "9ca10efb", vanilla = true },
        reward = { it = "Sì, è proprio quello che avevo! Lo farò muovere di nuovo. Mi fa ridere!", enHash = "621eb0b5", vanilla = true },
    },
    [1372] = {
        title = { it = "Nient'altro che la verità", enHash = "9c65600a", vanilla = true },
        text = { it = "La nostra forza di spedizione è stata mandata per volere di Varimathras a perlustrare la parte bassa di Azeroth.\n\nMentre ero in ricognizione ho notato un Infiltrator umano che spiava il Beggar's Haunt. Prima che riuscissi a catturarlo, alcuni dei nostri... fratelli... orchi l'hanno preso e portato a Stonard, la loro roccaforte nella Swamp of Sorrows.\n\nVoglio... aiutare... i nostri alleati orchi. Non hanno visto il nostro accampamento qui, ma voglio comunque dare una mano.\n\nLavora con Faustin, qui, per preparare un... siero della verità per il nostro amico a Stonard.", enHash = "067c44fd", vanilla = true },
        objectives = { it = "Parla con Apothecary Faustin al Beggar's Haunt.", enHash = "1ac95a9d", vanilla = true },
        reward = { it = "Zraedus mi stava giusto parlando di quel ficcanaso di un Infiltrator, prima che arrivassi.\n\nUn bel problema, davvero. L'ultima cosa che ci serve è un impiccione che fiuta in giro per il Beggar's Haunt.\n\nSono sicuro che gli orchi di Stonard siano ansiosi di sentire cosa ha da dire il nostro amico. Visto che sono nostri alleati, ehm, dobbiamo aiutarli a ottenere dall'umano tutte le informazioni che possono.\n\nLavora con me, $N, e porteremo un siero della verità a Stonard.\n\nPer l'Orda!\n\n...l'ho detto giusto?", enHash = "87c0b319", vanilla = true },
    },
    [1373] = {
        title = { it = "Ongeku", enHash = "c3a86127", vanilla = true },
        text = { it = "Hai ancora molto da dimostrare, e il tuo prossimo compito ti porterà lontano, quindi per ora i Gelkis combatteranno i Magram senza di te.\n\nLa terra sussurra molti segreti a chi ascolta. Uno dei segreti che sento parla di un cristallo rosso. Si chiama draenethyst, ed è nuovo per la nostra terra. Viene da un luogo dove le montagne volano e dove regnano i demoni.\n\nPortami una scheggia di draenethyst, e renderà forte la mia magia! La scheggia si trova in un luogo chiamato Swamp of Sorrows, nelle mani del perduto Ongeku.", enHash = "7314d809", vanilla = true },
        objectives = { it = "Mantieni la tua reputazione con i Gelkis e porta una Draenethyst Shard a Uthek the Wise, al Gelkis Village, a Desolace.", enHash = "151a0449", vanilla = true },
        progress = { it = "Dimostrami che sei $Gun amico:un'amica; dei Gelkis, $N.", enHash = "5cc366c2", vanilla = true },
        reward = { it = "Sì, questa è la scheggia di cui sussurrava la terra. Sento una magia potente al suo interno! Userò questa magia contro i nemici dei Gelkis.\n\nHai svolto un altro compito per noi, $N. Forse presto ti chiameremo $Gamico:amica;.", enHash = "9ed7f3fc", vanilla = true },
    },
    [1374] = {
        title = { it = "Khan Jehn", enHash = "f4facf97", vanilla = true },
        text = { it = "La terra mi parla, e dice che i Magram si stanno indebolendo. Ora è il momento di uccidere il loro Khan!\n\nPortami la testa del Khan dei Magram, Jehn!", enHash = "8fd3eb69", vanilla = true },
        objectives = { it = "Porta la Khan Jehn's Head a Uthek the Wise, al Gelkis Village, a Desolace.", enHash = "4f09207f", vanilla = true },
        progress = { it = "Dimostrami che sei $Gun amico:un'amica; dei Gelkis, $N.", enHash = "5cc366c2", vanilla = true },
        reward = { it = "Khan Jehn era forte, ma stupido. Pensava che la sua forza fosse grande. Non vedeva che la magia della terra è più forte. Ora i centauri Magram cadranno senza il loro capo, e un giorno i Gelkis regneranno!", enHash = "564b73ec", vanilla = true },
    },
    [1375] = {
        title = { it = "Khan Shaka", enHash = "aadf39ac", vanilla = true },
        text = { it = "Tu aiuti i Magram, e mi piaci. Ora uccidi il Khan dei Gelkis! È Khan Shaka, e voglio la sua testa! Voglio fissare la sua testa e ridere di lui!", enHash = "8e146d41", vanilla = true },
        objectives = { it = "Mantieni la tua reputazione con i Magram e porta l'Head of Khan Shaka a Warug, al Magram Village, a Desolace.", enHash = "f6a3265d", vanilla = true },
        progress = { it = "Fai dei compiti per i Magram, e io ti aiuterò.", enHash = "2099174c", vanilla = true },
        reward = { it = "Khan Shaka è morto! Metterò la sua testa su una picca e la terrò con me, così Shaka potrà vedere la forza dei Magram!", enHash = "5e01d70a", vanilla = true },
    },
    [1380] = {
        title = { it = "Khan Hratha", enHash = "9ecfbb0c", vanilla = true },
        text = { it = "$N, ci hai aiutato contro i Magram. Ora aiutaci a battere i Maraudine! Uccidi il capo del loro clan, Khan Hratha!\n\nPer affrontarlo, suona il Maraudine War Horn. Si trova in cima a un'alta rupe nella Valley of Spears.\n\nMa per suonare il corno ti serve un bocchino per il corno da guerra. Sono rari, e li portano solo i centauri Maraudine di fiducia.\n\nDopo che avrai suonato il corno, arriveranno i centauri. Uccidili finché non compare Hratha.\n\nKhan Hratha custodisce il pezzo di... una chiave. Portamelo...", enHash = "808fe442", vanilla = true },
        objectives = { it = "Mantieni la tua reputazione con i Gelkis e porta il Maraudine Key Fragment a Uthek the Wise, al Gelkis Village.", enHash = "8e11e08a", vanilla = true },
        progress = { it = "Khan Hratha è morto? Hai il frammento di chiave?", enHash = "b89fa42c", vanilla = true },
        reward = { it = "È morto! Khan Hratha è morto! E ora i Maraudine cadranno! Quando i Gelkis regneranno su questa terra, $N, ci ricorderemo di te. E gli spiriti della terra canteranno il tuo nome per sempre.", enHash = "a802509e", vanilla = true },
    },
    [1381] = {
        title = { it = "Khan Hratha", enHash = "9ecfbb0c", vanilla = true },
        text = { it = "Il Khan dei Gelkis è morto, e ora cadranno i Maraudine! Uccidi il Khan dei Maraudine, Hratha!\n\nPer affrontarlo, suona il corno sull'alta rupe nella Valley of Spears. Ma per suonare il corno ti serve un bocchino. Per avere un bocchino, uccidi i centauri Maraudine. Continua a ucciderli finché non trovi un bocchino. Poi suona il corno.\n\nFai questo e i centauri Maraudine verranno alla torre. Uccidili finché non compare Khan Hratha. Hratha ha il pezzo di una chiave. Dai questo pezzo a me...", enHash = "f53188e2", vanilla = true },
        objectives = { it = "Mantieni la tua reputazione con i Magram e porta il Maraudine Key Fragment a Warug, al Magram Village, a Desolace.", enHash = "38ee477c", vanilla = true },
        progress = { it = "Fai quello che ti chiedo. Dimostrami che sei $Gun alleato:un'alleata; dei Magram!", enHash = "2c78587f", vanilla = true },
        reward = { it = "Khan Hratha è morto! Ora i Magram sono i più forti tra i centauri! Schiacceremo gli altri e regneremo su Desolace!\n\nCi ricorderemo di te, $N, e sarai $Grisparmiato:risparmiata; dai nostri zoccoli quando tutti gli altri saranno calpestati.", enHash = "122c5b2a", vanilla = true },
    },
    [1382] = {
        title = { it = "Una strana alleanza", enHash = "8bf0545b", vanilla = true },
        text = { it = "Siamo fortunati che i clan dei centauri combattano tra loro, perché se si unissero in un'unica forza sarebbero inarrestabili. Sì, siamo fortunati, e dovremmo sfruttare il nostro vantaggio.\n\nUno dei clan dei centauri, il clan Gelkis, è in guerra brutale con il clan Magram. Se attacchiamo i Magram, forse potremo stringere un'alleanza con i Gelkis.\n\nParla con Uthek the Wise, ai margini degli accampamenti Gelkis nel sud-ovest di Desolace. Attraverso di lei potremmo stringere un'alleanza con i Gelkis.", enHash = "a34e2d23", vanilla = true },
        objectives = { it = "Raggiungi la reputazione Friendly con i Gelkis, poi parla con Uthek the Wise.", enHash = "af11feef", vanilla = true },
        progress = { it = "Sparisci! I Gelkis non ti vogliono qui. Vattene subito!!\n\nTorna dopo aver ucciso molti Magram, e allora parlerò con te.", enHash = "878daf4b", vanilla = true },
        reward = { it = "Il tuo nome si sussurra tra i Gelkis. Hai molto sangue Magram sulle mani. Questo è bene.\n\nForse è bene anche che parliamo. Parliamo di cosa puoi fare tu per i Gelkis, e di cosa possiamo fare noi per te.", enHash = "1c43bd45", vanilla = true },
    },
    [1383] = {
        title = { it = "Nient'altro che la verità", enHash = "9c65600a", vanilla = true },
        text = { it = "Ho in mente proprio il siero giusto. Tratterà la verità esattamente come la verità va trattata.\n\nPer questo intruglio mi serviranno parecchi cuori di Shadow Panther della Swamp. Mi serve anche il fungo incantato del Mire Lord che vive laggiù. Sono sicuro che qualcuno in gamba come te, $N, saprà convincerlo a cedertene un po'.\n\nOra, la parte difficile sarà trovare un tumore di Deepstrider nella lontana Desolace. Molto di rado i giganti di laggiù si ammalano e si forma un tumore.\n\nOra, va'!", enHash = "559acd02", vanilla = true },
        objectives = { it = "Apothecary Faustin, al Beggar's Haunt, ha bisogno di 5 Shadow Panther Heart, del Mire Lord Fungus e di un Deep Strider Tumor.", enHash = "efffd92c", vanilla = true },
        progress = { it = "Quell'Infiltrator a Stonard di sicuro... si aprirà... dopo aver bevuto il mio siero speciale. Ahah!\n\nGli ingredienti che servono non sono affatto facili da procurare. Le Shadow Panther sono comuni nella Swamp, ma raccogliere abbastanza cuori per il nostro scopo può essere un'impresa. E il Mire Lord sa essere una bestia molto difficile.\n\nQuanto al tumore di Deepstrider, è terribilmente difficile da trovare. Ma la reazione chimica che posso ricavarne non ha eguali.", enHash = "f4f68432", vanilla = true },
        reward = { it = "Splendido, $N! E proprio in tempo. Da quel che mi dice Zraedus, l'Infiltrator si è ripreso dalle ferite ed è pronto per essere interrogato dagli orchi.\n\nDammi solo un momento per preparare il vel... voglio dire, per preparare il siero della verità.", enHash = "4336f907", vanilla = true },
    },
    [1384] = {
        title = { it = "Incursione contro i Kolkar", enHash = "8be9a6ae", vanilla = true },
        text = { it = "I centauri Kolkar pensano che la loro magia sia forte. Non sanno cos'è la magia! Non la riconoscerebbero nemmeno se li mordesse!\n\nTu mostrerai loro che la loro magia è debole. Va' dai Kolkar a nord-est e uccidili. Prendi i loro amuleti. Portami gli amuleti e io li getterò nel fuoco ridendo!", enHash = "b37b1f1e", vanilla = true },
        objectives = { it = "Mantieni la tua reputazione con i Gelkis e porta 10 Crude Charm a Uthek the Wise, al Gelkis Village, a Desolace.", enHash = "54ea0a2f", vanilla = true },
        progress = { it = "Hai gli amuleti? Hai mostrato ai Kolkar che sono deboli?", enHash = "bee672fa", vanilla = true },
        reward = { it = "Fai una cosa buona per i Gelkis. I Kolkar sono deboli e moriranno. La loro magia è patetica e non li salverà. Tu gliel'hai mostrato, e la loro paura li renderà ancora più fiacchi!\n\nE nelle nostre terre, chi è fiacco muore presto.", enHash = "397d78eb", vanilla = true },
    },
    [1385] = {
        title = { it = "Politica brutale", enHash = "9bf55d67", vanilla = true },
        text = { it = "Desolace è una terra in guerra. I centauri si fanno guerra tra loro, e crediamo che il vincitore finirà per riversarsi fuori e minacciare le nostre roccaforti. Questo non possiamo permetterlo.\n\nDobbiamo imparare a battere i centauri, e per farlo... dobbiamo allearci con uno dei clan. I centauri Magram sono in guerra con i Gelkis. Se combatti i Gelkis, i Magram potrebbero prendere in considerazione un'alleanza.\n\nGuadagnati il favore dei Magram, poi parla con Warug, nel villaggio dei Magram, nel sud-est di Desolace.", enHash = "4fdb49b4", vanilla = true },
        objectives = { it = "Raggiungi la reputazione Friendly con i Magram, poi parla con Warug.", enHash = "23322953", vanilla = true },
        progress = { it = "Ora te ne vai, o i Magram ti schiacceranno! Per essere $Gnostro amico:nostra amica;, devi uccidere i Gelkis.", enHash = "1190f970", vanilla = true },
        reward = { it = "Molti Gelkis cadono per mano tua. Mi piace. Forse puoi fare altre cose che mi piacciono. Forse tu e i Magram potete essere amici.", enHash = "98877de2", vanilla = true },
    },
    [1386] = {
        title = { it = "Assalto ai Kolkar", enHash = "451d74a1", vanilla = true },
        text = { it = "I Kolkar pensano di essere forti, ma noi ridiamo di loro! Ridiamo e li uccidiamo! Uccidili anche tu. Dimostrami che sai uccidere i Kolkar come facciamo noi. Va' a nord e sterminali tutti!", enHash = "baca0f95", vanilla = true },
        objectives = { it = "Mantieni la tua reputazione con i Magram. Uccidi 12 Kolkar Centaur, 12 Kolkar Scout e 6 Kolkar Mauler, poi torna da Warug, al Magram Village, a Desolace.", enHash = "2321bc31", vanilla = true },
        progress = { it = "Hai paura dei Kolkar? Perché non li uccidi? Forse hai dimenticato come si uccide. Sbrigati e uccidi i Kolkar prima che siano morti!", enHash = "ff6d9289", vanilla = true },
        reward = { it = "Ora i Kolkar hanno paura di te! Spero che tu abbia riso mentre li uccidevi. È meglio ridere quando uccidi, così il nemico vede che è debole.", enHash = "9cb7fb18", vanilla = true },
    },
    [1387] = {
        title = { it = "Taglia sui centauri", enHash = "18228bf5", vanilla = true },
        text = { it = "La razza dei centauri è formata da molti clan. Ognuno ha il suo capo e i suoi scopi, ma tutti i clan hanno una cosa in comune. La crudeltà.\n\nSe vogliamo mai trovare la pace, i centauri vanno eliminati. E perciò affido a te proprio questo compito.\n\nMentre giri per Desolace, dai la caccia ai centauri e prendi le loro orecchie. Portami tante, tante orecchie.\n\nFallo al servizio dell'Alleanza, $N, e saremo un passo più vicini alla fine della guerra.", enHash = "87b7572d", vanilla = true },
        objectives = { it = "Porta 15 Centaur Ear a Corporal Melkins, a Nijel's Point, a Desolace.", enHash = "1e7e6f03", vanilla = true },
        progress = { it = "Hai un rapporto, $N?", enHash = "23e280ec", vanilla = true },
        reward = { it = "Ah, le orecchie. Ben fatto.\n\nIl tuo servizio all'Alleanza è fuori discussione, $N. Il sangue che hai versato a Desolace salverà, senza dubbio, innumerevoli vite.", enHash = "45943287", vanilla = true },
    },
    [1388] = {
        title = { it = "Nient'altro che la verità", enHash = "9c65600a", vanilla = true },
        text = { it = "Tutto procede secondo i piani, $N. Voglio che tu dia questo siero della verità a Deathstalker Zraedus, e lui ti mostrerà come somministrarlo... come si deve.\n\nAhah!", enHash = "977d56c0", vanilla = true },
        objectives = { it = "Dai Faustin's Truth Serum a Deathstalker Zraedus al Beggar's Haunt.", enHash = "92659fdc", vanilla = true },
        progress = { it = "Spero che tu ti sia $Gdimostrato:dimostrata; utile al nostro caro amico, Apothecary Faustin.", enHash = "1363324c", vanilla = true },
        reward = { it = "Sapevo che il vecchio Faustin avrebbe tirato fuori qualcosa di buono! Sei $Gstato:stata; di grandissimo aiuto, non c'è dubbio.\n\nOra mettiamoci al lavoro, che ne dici?", enHash = "cb67339f", vanilla = true },
    },
    [1389] = {
        title = { it = "Draenethyst Crystals", enHash = "4c8347e0", vanilla = true },
        text = { it = "I perduti che vivono nel Fallow Sanctuary hanno il nostro aspetto, ma sono mostri... impazziti per le fatiche del nostro viaggio verso Azeroth. Un tempo erano nostri fratelli, ora vivono nel Fallow Sanctuary a est, e catturano o uccidono chiunque si avvicini.\n\nE ci hanno rubato qualcosa di sacro: i cristalli di draenethyst.\n\nNon abbiamo le forze per entrare nel Fallow Sanctuary e riprenderci il draenethyst che ci hanno rubato, tra le loro capanne e i loro fuochi, ma senza quei cristalli... anche noi potremmo perdere la strada.", enHash = "69cdee02", vanilla = true },
        objectives = { it = "Porta 6 Draenethyst Crystal a Magtoor, all'Harborage, nella Swamp of Sorrows.", enHash = "53ec89fb", vanilla = true },
        progress = { it = "Hai i cristalli?", enHash = "beffcf11", vanilla = true },
        reward = { it = "Grazie, $N. Siamo in debito con te.", enHash = "a78c0e14", vanilla = true },
    },
    [1390] = {
        title = { it = "Ops, li abbiamo uccisi di nuovo.", enHash = "7bd4fe8a", vanilla = true },
        text = { it = "Testo mancante.", enHash = "b831a3a7", vanilla = true },
        objectives = { it = "Testo mancante.", enHash = "b831a3a7", vanilla = true },
        reward = { it = "Grazie per il lavoro fatto!", enHash = "8a93830f", vanilla = true },
    },
    [1391] = {
        title = { it = "Nient'altro che la verità", enHash = "9c65600a", vanilla = true },
        text = { it = "Dobbiamo agire con una certa discrezione. Dopotutto, non è che puoi entrare lì con disinvoltura e convincere quell'idiota a bere l'intruglio di Faustin, giusto?\n\nMa se c'è una cosa a cui quegli umani non sanno dire di no, è l'alcol. Prenderò il siero di Faustin e lo mescolerò a questa birra. Ti garantisco che quel poveraccio non esiterà un attimo a scolarsi una birra.\n\nSbrigati a raggiungere Stonard, nella Swamp of Sorrows, $N. E mi raccomando, che la nostra piccola missione resti tranquilla e silenziosa...", enHash = "051902ee", vanilla = true },
        objectives = { it = "Porta Zraedus's Brew a Infiltrator Marksen, a Stonard.", enHash = "909c2aaf", vanilla = true },
        progress = { it = "Ti prego, abbi pietà di me! Ho informazioni che vanno oltre gli schieramenti. Non sono un simpatizzante dell'Orda, ma c'è in atto un tradimento politico che deve essere svelato!", enHash = "23b4c4a2", vanilla = true },
        reward = { it = "Da bere per me? Che gentile. Sono giorni che non mi lasciano bere. Fammi mandare giù questa, e poi ti dirò quello che ho scoperto...", enHash = "f89eab1f", vanilla = true },
    },
    [1392] = {
        title = { it = "Noboru the Cudgel", enHash = "58c7815a", vanilla = true },
        text = { it = "Da mesi Noboru tormenta i draenei dell'Harborage, e il suo randello è un simbolo della brutalità che hanno subito per mano dei perduti.", enHash = "8e1bf4c2", vanilla = true },
        objectives = { it = "Porta Noboru's Cudgel al capo dell'Harborage, nella Swamp of Sorrows.", enHash = "633e5311", vanilla = true },
        progress = { it = "Salute. E $Gbenvenuto:benvenuta; all'Harborage.", enHash = "0f4e3414", vanilla = true },
        reward = { it = "Hai preso l'arma del temuto Noboru? Allora è morto?\n\nÈ un giorno di gioia per l'Harborage. Noboru e la sua banda ci terrorizzavano, vagando per le paludi e uccidendo tutti i draenei che incrociavano la sua strada. Era una minaccia diretta alla nostra sopravvivenza, e non avevamo la forza di affrontarlo.\n\nSiamo fortunati ad avere in te $Gun amico:un'amica;, $N.", enHash = "ebcf17f3", vanilla = true },
    },
    [1393] = {
        title = { it = "La fuga di Galen", enHash = "c4d4755a", vanilla = true },
        text = { it = "Aiuto, ti prego! Queste creature stanno per mangiarmi!\n\nAiutami a uscire di qui, e ti darò un grande tesoro! È nel mio accampamento nella palude, a nord di Stonard, ma è chiuso in un forziere che si può aprire solo con un trucco che conosco soltanto io.\n\nSe mi aiuti a scappare, te lo insegnerò.", enHash = "37ebc418", vanilla = true },
        objectives = { it = "Scorta Galen fuori pericolo, poi trova il suo accampamento nella Swamp of Sorrows e apri il suo forziere.", enHash = "18d07e1d", vanilla = true },
        progress = { it = "Il buco della serratura di questo forziere è pieno di resina nera. È impossibile aprirlo.", enHash = "d2673be2", vanilla = true },
        reward = { it = "Il buco della serratura di questo forziere è pieno di resina nera. È impossibile aprirlo.\n\nMa Galen ti ha parlato di un fermo nascosto sul fondo del forziere...\n\n...Dopo una breve ricerca, il fermo viene trovato. Il fermo viene sganciato, e il forziere si apre...", enHash = "14d4acd3", vanilla = true },
    },
    [1394] = {
        title = { it = "Il passaggio finale", enHash = "13f8d6a4", vanilla = true },
        text = { it = "Hai fatto bene, $N. Hai superato la mia prova e quelle prima della mia. Torna da Dorn, a Thousand Needles. Sentirà il cambiamento dentro di te e vedrà che la tua mente, il tuo corpo e il tuo spirito sono abbastanza forti da meritare una ricompensa per quel che hai fatto.\n\nResta fedele all'equilibrio che hai mostrato in tutte queste prove, $N. Se lo farai, in futuro Dorn ti metterà di nuovo alla prova.", enHash = "378ed77c", vanilla = true },
        objectives = { it = "Parla con Dorn Plainstalker, a Thousand Needles.", enHash = "f75e822d", vanilla = true },
        reward = { it = "Ah, $N. È passato molto tempo dall'ultima volta che hai messo piede in casa mia. Sembrano passate molte lune da quando hai fatto il primo salto che ti ha messo sul tuo cammino.\n\nE ora torni da me più forte di prima... più $Gilluminato:illuminata;. Questo mi fa piacere. Ed è giusto che tu sia $Gricompensato:ricompensata; per aver portato a termine le mie prove.", enHash = "26019317", vanilla = true },
    },
    [1395] = {
        title = { it = "Rifornimenti per Nethergarde", enHash = "d822e2d7", vanilla = true },
        text = { it = "Questa cassa di pietre del potere deve arrivare a Nethergarde Keep, nelle Blasted Lands. Non conserveranno il loro potere a lungo, quindi non possiamo spedirle con la prossima carovana.\n\nDevi portarle tu, e devi portarle in fretta.\n\nPortale a Quartermaster Lungertz, a Nethergarde Keep. Per raggiungere la fortezza devi andare a est attraverso il Deadwind Pass, poi a est attraverso la Swamp of Sorrows, poi a sud attraverso le Blasted Lands.\n\nSta' $Gattento:attenta;, $N. Attraverserai terre pericolose, eppure non devi fallire.", enHash = "d95a7429", vanilla = true },
        objectives = { it = "Porta la Crate of Powerstones a Quartermaster Lungertz, prima che le pietre del potere si esauriscano.", enHash = "d8176496", vanilla = true },
        progress = { it = "Salve! Non badare a tutto questo trambusto, è la solita vita di Nethergarde Keep.\n\nHai qualcosa per me?", enHash = "dc2f6495", vanilla = true },
        reward = { it = "Ah, le pietre del potere! I maghi saranno contenti di vederle!\n\nMille grazie, $N. So che il viaggio da Darkshire non è stato facile.", enHash = "2900abb1", vanilla = true },
    },
    [1396] = {
        title = { it = "La fauna selvatica avanza", enHash = "78d66653", vanilla = true },
        text = { it = "La mia carovana era diretta alla costa orientale, ma non abbiamo raggiunto la meta. I Perduti ci hanno attaccati, uccidendo le guardie e distruggendo le provviste.\n\nSono l'unico sopravvissuto al loro assalto. Ho giurato di proteggere le provviste rimaste, ma le creature selvatiche si aggirano qui vicino. Ti prego, aiutami a difendere il mio accampamento dalle bestie!", enHash = "9aa4e065", vanilla = true },
        objectives = { it = "Uccidi 8 Young Sawtooth Crocolisk, 10 Sorrow Spinner e 10 Swamp Jaguar, poi torna da Watcher Biggs, nella Swamp of Sorrows.", enHash = "5bea3029", vanilla = true },
        progress = { it = "Le creature della palude si fanno sotto, $N. Ti prego, devi difendere l'accampamento!", enHash = "4a0cf5ef", vanilla = true },
        reward = { it = "I versi degli animali ora sono deboli, più lontani. Grazie, $N. Speriamo che non tornino!", enHash = "123fe638", vanilla = true },
    },
    [1398] = {
        title = { it = "Legni spiaggiati", enHash = "941861d6", vanilla = true },
        text = { it = "Ti devo moltissimo, $N. Dentro di te batte un cuore onorevole. E ora ho un altro compito per cui chiedo umilmente il tuo aiuto.\n\nSe mai voglio raggiungere Nethergarde, devo riparare questo carro. E per farlo... mi servirà del legno. Legno robusto e asciutto, non il legno spugnoso e contorto degli alberi della palude.\n\n$N, va' a est verso la costa e cerca legni spiaggiati seccati dal sole. Portameli.", enHash = "c76fe937", vanilla = true },
        objectives = { it = "Porta 8 pezzi di Sundried Driftwood a Watcher Biggs, nella Swamp of Sorrows.", enHash = "6af83003", vanilla = true },
        progress = { it = "Hai trovato dei legni spiaggiati, $N?", enHash = "03099404", vanilla = true },
        reward = { it = "Questo legno è leggero, ma resistente. Grazie, $N. Andrà benissimo.", enHash = "0acf1b6c", vanilla = true },
    },
    [1418] = {
        title = { it = "Neeka Bloodscar", enHash = "45b5c1bf", vanilla = true },
        text = { it = "I Badlands sono una terra dura e si trovano vicino a Loch Modan, terra controllata dall'Alleanza, perciò le comunicazioni tra Stonard e l'avamposto di Kargath nei Badlands vengono spesso interrotte.\n\nDimostra il tuo valore, $N. Va' nei Badlands e parla con Neeka Bloodscar, a capo degli esploratori dell'avamposto di Kargath. Parla con lei, e poi rimanda a me il suo rapporto.", enHash = "99154ed1", vanilla = true },
        objectives = { it = "Parla con Neeka Bloodscar.", enHash = "74c8349b", vanilla = true },
        reward = { it = "Helgrum vuole un rapporto, eh? Ho mandato un corriere a Stonard nemmeno tre giorni fa. Ha fallito la sua missione? Se Stonard non ha il mio rapporto, allora sembra proprio che abbia fallito.\n\nSperiamo che il prossimo corriere che mando abbia più abilità, o più fortuna.", enHash = "5f97411c", vanilla = true },
    },
    [1419] = {
        title = { it = "I coyote ladri", enHash = "d1e44e67", vanilla = true },
        text = { it = "Hai passato molti giorni nei Badlands, $C? Hai sentito il caldo di questa terra? Hai affrontato le bestie che vagano per le sue pianure polverose? È ora di farlo.\n\nI Crag Coyote sono una razza tosta. Tosti, e abbastanza sfrontati da intrufolarsi a Kargath e rubare le nostre provviste di cibo. Aiutaci a liberare l'avamposto da questi ladri!\n\nDai la caccia ai Crag Coyote, $N. Cacciali e portami le loro mascelle. Portamene abbastanza, e forse ti crederò quando dirai di conoscere i Badlands.", enHash = "f5a06b31", vanilla = true },
        objectives = { it = "Porta 30 Coyote Jawbone a Neeka Bloodscar, a Kargath.", enHash = "268906f2", vanilla = true },
        progress = { it = "Hai le mascelle?", enHash = "5fdb5d3f", vanilla = true },
        reward = { it = "Una bella collezione di mascelle, $N. Ora quei coyote non faranno più a pezzi le nostre provviste in cerca di avanzi.\n\nBen fatto. I coyote dei Badlands non sono prede facili. La tua impresa mi dimostra che forse qui riuscirai a sopravvivere.", enHash = "d86c7e88", vanilla = true },
    },
    [1420] = {
        title = { it = "A rapporto da Helgrum", enHash = "9fe57a19", vanilla = true },
        text = { it = "Ho scritto un nuovo rapporto per Helgrum, a Stonard. Portaglielo.\n\nE se ti consideri una staffetta, allora non perderti per strada. E non cadere per mano di un nemico.", enHash = "60f84144", vanilla = true },
        objectives = { it = "Porta Neeka's Report a Helgrum the Swift, a Stonard.", enHash = "deb58675", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata;. Hai un rapporto?", enHash = "e00504b3", vanilla = true },
        reward = { it = "Grazie, $N. Dal rapporto di Neeka vedo che anche l'Alleanza ha i suoi problemi. E potremmo scoprire di avere qualche nemico in comune.", enHash = "dc0ce775", vanilla = true },
    },
    [1421] = {
        title = { it = "La carovana perduta", enHash = "7b616349", vanilla = true },
        text = { it = "Sono rimasto stordito durante l'attacco dei Perduti, ma prima che mi si oscurasse la vista ho visto uno dei nostri carri trascinato al Fallow Sanctuary, il villaggio dei perduti a nord.\n\nIn quel carro c'era una Caravan Chest con reagenti preziosi, reagenti vitali per gli studi dei maghi della Nethergarde Keep. Trova la cassa e prendi quei reagenti, $N. Prendili e portali a me.", enHash = "ce2e2cb1", vanilla = true },
        objectives = { it = "Trova la Caravan Chest nel Fallow Sanctuary, prendi i Wizards' Reagents e portali a Watcher Biggs.", enHash = "98c134f2", vanilla = true },
        progress = { it = "Hai i reagenti dei maghi, $N?", enHash = "c6f94608", vanilla = true },
        reward = { it = "Ah, li hai trovati! Con questi, i maghi di Nethergarde potranno continuare il loro lavoro. Non so che cosa facciano di preciso, ma ha a che fare con il Dark Portal nelle Blasted Lands, ed è vitale per la sicurezza dell'Alleanza.", enHash = "d679905f", vanilla = true },
    },
    [1422] = {
        title = { it = "Minaccia dal mare", enHash = "42d7cdf0", vanilla = true },
        text = { it = "Mentre comincio a lavorare alla tua arma, perché non parli con Katar? Ha detto che gli serve aiuto con le pattuglie lungo la spiaggia, e preferirei vederti con la mente lucida e le armi pronte, invece che a ubriacarti con qualcuno degli altri pidocchi con cui divido questo accampamento.", enHash = "aceaa3f9", vanilla = true },
        objectives = { it = "Parla con Katar, nella Swamp of Sorrows.", enHash = "1e2289c6", vanilla = true },
        reward = { it = "Fa' silenzio un momento, $C. Anche sopra il ruggito sordo del mare si sentono ancora quei disgustosi gorgoglii degli uomini pesce.", enHash = "7807a6c2", vanilla = true },
    },
    [1423] = {
        title = { it = "Le Lost Supplies", enHash = "8e3fb5da", vanilla = true },
        text = { it = "Questo barile è piccolo ma robusto. Le giunture sono sigillate con una cera gialla dall'odore pungente. Sul fondo del barile sono stampate le parole:\n\nQUARTERMASTER LUNGERTZ\n\nNETHERGARDE KEEP", enHash = "d05c82a7", vanilla = true },
        objectives = { it = "Porta le Lost Supplies a Quartermaster Lungertz.", enHash = "6a639476", vanilla = true },
        progress = { it = "Hai qualcosa per me?", enHash = "ac74d893", vanilla = true },
        reward = { it = "Ah, grazie, $N! Tra Darkshire e qui si perdono così tante provviste. È bello vedere che qualcuna viene recuperata.", enHash = "46eebdc3", vanilla = true },
    },
    [1424] = {
        title = { it = "Il Pool of Tears", enHash = "3197d64c", vanilla = true },
        text = { it = "Il Capoguerra ci ha mandati a indagare su strani avvenimenti al Temple of Atal'Hakkar.\n\nI troll Atal'ai sono una tribù di incantatori oscuri, noti per praticare magie proibite. Puoi immaginare il nostro stupore quando, arrivati qui, abbiamo scoperto che il tempio era sprofondato.\n\nOra i draghi verdi sorvegliano il luogo, e sostengono di essere i protettori di Azeroth.\n\nDobbiamo scoprire cos'è successo. Esplora i dintorni del Pool of Tears e raccogli degli Atal'ai Artifact. Partendo da quelli potrò cominciare a ricomporre questo enigma.", enHash = "eb1b2a00", vanilla = true },
        objectives = { it = "Fel'zerul, a Stonard, vuole che tu raccolga 10 Atal'ai Artifact.", enHash = "17850b93", vanilla = true },
        progress = { it = "Nessuno sa quali pratiche oscure si svolgessero dentro il Temple of Atal'Hakkar. Ma sappiamo che sono state usate forze magiche grandi e potenti.\n\nDobbiamo imparare il più possibile su questa magia. Forse gli incantesimi degli Atal'ai si riveleranno utili all'Orda.\n\nQuando avrai raccolto abbastanza Atal'ai Artifact intorno al Pool of Tears, potrò cominciare a capire cosa speravano di ottenere i troll e cosa è andato così terribilmente storto.", enHash = "7dc053d4", vanilla = true },
        reward = { it = "La diligenza con cui hai raccolto gli Atal'ai Artifact merita un elogio, $C.", enHash = "8bf9a0dc", vanilla = true },
    },
    [1425] = {
        title = { it = "Consegna il carico", enHash = "38c20b84", vanilla = true },
        text = { it = "Mentre riparo questo carro, $N, ho un ultimo compito per te.\n\nHo imballato le provviste più vitali salvate dagli attacchi degli ogre. Portale alla Nethergarde Keep. La fortezza è annidata tra le colline settentrionali delle Blasted Lands, e sorveglia il Dark Portal.\n\nPer raggiungere Nethergarde, segui la strada verso est. Quando si dirama, va' a sud nelle Blasted Lands, poi alla biforcazione successiva gira a sinistra. Segui la strada, $N, e fa' attenzione.", enHash = "e333a840", vanilla = true },
        objectives = { it = "Porta lo Shipment to Nethergarde a Quartermaster Lungertz, nella Nethergarde Keep.", enHash = "34a5bf5e", vanilla = true },
        progress = { it = "Hai qualche affare con me?", enHash = "faa48416", vanilla = true },
        reward = { it = "Cosa? Un pacco dalla carovana di Biggs? Credevamo che la carovana, e lui, fossero andati perduti.\n\nGrazie, $N. Con un po' di fortuna, queste provviste conterranno il reagente di cui abbiamo tanto bisogno, gli Azoran Crystal. Le nostre scorte si stanno esaurendo...", enHash = "8424f03e", vanilla = true },
    },
    [1426] = {
        title = { it = "Minaccia dal mare", enHash = "42d7cdf0", vanilla = true },
        text = { it = "Non ho alcun amore per il mare, né per le creature che ho visto uscire dai suoi abissi. È un'amante potente ma cieca; spietata e brutale. Mi darebbe un gran piacere uccidere gli uomini pesce a centinaia, se fosse in mio potere. Ma provo un certo piacere a guardarli morire per mano di chiunque compia la volontà dell'Orda.\n\nIl che ci porta a te, $C. Quanti riesci a ucciderne? Vuoi metterti alla prova contro i più potenti della loro specie?", enHash = "11a68a91", vanilla = true },
        objectives = { it = "Uccidi 10 Marsh Murloc, 10 Marsh Inkspewer e 10 Marsh Flesheater, poi torna da Katar, nella Swamp of Sorrows.", enHash = "cf58b20a", vanilla = true },
        progress = { it = "Sono paziente. Paziente ed eterno come una vecchia pietra kank di Draenor. Gli uomini pesce non supereranno i nostri confini, non finché resterò in piedi. Se avessimo un esercito a disposizione, ripulirei questo mondo e tutti gli altri dalla loro presenza. Sento il mio odio ribollire solo a parlarne.", enHash = "c1df7ecd", vanilla = true },
        reward = { it = "Il mare sembra vasto e implacabile, ma tu l'hai macchiato con il sangue della sua stessa progenie. Gli uomini pesce conoscono il dolore. La loro stupidità li costringerà a rinforzare le file dopo la devastazione che hai causato, ed è un bene.\n\nChe le loro grida gorgoglianti coprano il ruggito del mare fino a notte fonda. Sorriderò ogni volta che ne sentirò uno messo a tacere.\n\nTorna da me se vuoi uccidere altri uomini pesce. Ti ricompenserò di nuovo volentieri.", enHash = "286baa26", vanilla = true },
    },
    [1427] = {
        title = { it = "Minaccia dal mare", enHash = "42d7cdf0", vanilla = true },
        text = { it = "Prima di riposarti, parla di nuovo con Tok'Kar. Mentre eri via credo abbia finito qualche arma. Per il tuo aiuto qui, vorrebbe offrirtene una. Faresti bene a metterne alla prova la forza contro gli uomini pesce quando sarai $Gpronto:pronta;... ma solo per farmi ancora più piacere.", enHash = "9bc4a3a0", vanilla = true },
        objectives = { it = "Parla con Tok'Kar, nella Swamp of Sorrows.", enHash = "f35df445", vanilla = true },
        reward = { it = "Ah, $N, sei $Gtornato:tornata;. Bene. Ho finito di forgiare altre armi per la nostra lotta contro i murloc. Per averci portato la carne fresca di sawtooth, e per aver strappato un piccolo sorriso a Katar, te ne offro una.", enHash = "4b0e58c8", vanilla = true },
    },
    [1428] = {
        title = { it = "Una minaccia che continua", enHash = "958792fd", vanilla = true },
        text = { it = "Mi fa piacere vedere che il tuo odio per gli uomini pesce cresce insieme al mio.\n\nTrovane altri della loro specie lungo la spiaggia, e quando avrai combattuto abbastanza torna da me. Allora parleremo di una ricompensa per la tua diligenza.", enHash = "70ba0287", vanilla = true },
        objectives = { it = "Uccidi 10 Marsh Inkspewer, 10 Marsh Flesheater e 10 Marsh Oracle, poi torna da Katar, nella Swamp of Sorrows.", enHash = "6dc7408a", vanilla = true },
        progress = { it = "Non sarò soddisfatto finché il mare e tutti i suoi figli non saranno ridotti al silenzio... soprattutto quei disgustosi uomini pesce.", enHash = "9bb30035", vanilla = true },
        reward = { it = "Ben fatto, $C. Voglio altro del loro sangue. Che periscano tutti gli uomini pesce.", enHash = "de36980d", vanilla = true },
    },
    [1429] = {
        title = { it = "L'Atal'ai Exile", enHash = "16dc69f1", vanilla = true },
        text = { it = "Mentre affrontavi i pericoli del Pool of Tears, uno dei miei esploratori è tornato con una pergamena scritta col sangue su pelle secca. Sembra una sentenza contro un sacerdote della tribù Atal'ai.\n\nTra gli Atal'ai, questo sacerdote è stato condannato a un destino peggiore della morte.\n\nÈ stato esiliato a vivere lontano, a nord, nelle Hinterlands, con i troll Witherbark.\n\nImpacchetterò questi manufatti. Tu devi cercare l'esule e scoprire a cosa servono davvero. Torna da me quando il tuo viaggio sarà concluso.", enHash = "47aedc3d", vanilla = true },
        objectives = { it = "Porta il Bundle of Atal'ai Artifacts all'Atal'ai Exile, nelle Hinterlands.", enHash = "4d77cea6", vanilla = true },
        progress = { it = "Hai coraggio a venire qui. Coraggio o follia...", enHash = "62e0572d", vanilla = true },
        reward = { it = "Mi porti i manufatti di evocazione degli Atal'ai?\n\nVedo che Jammal'an the Prophet sta guidando i discepoli della Chamber of Blood verso il destino che hanno scelto. Mi chiedo se Hakkar sia tornato al tempio. Si è compiuto il loro destino?", enHash = "484fec9b", vanilla = true },
    },
    [1430] = {
        title = { it = "Carne fresca", enHash = "ce6dd77d", vanilla = true },
        text = { it = "Tra i miei clienti c'è molta richiesta del sapore succulento della carne di crawler, soprattutto quella dei Monstrous Crawler.\n\nSe hai intenzione di andare sulla costa, potrei facilmente fare in modo che ti convenga riportarmi un po' delle loro zampe, da spedire a Orgrimmar.\n\nLa costa è a est di qui, e non dovresti avere problemi a trovare le creature che zampettano lungo le spiagge e sotto il mare.", enHash = "b5243731", vanilla = true },
        objectives = { it = "Porta 10 Monstrous Crawler Leg a Dar, nella Swamp of Sorrows.", enHash = "a7c098ca", vanilla = true },
        progress = { it = "Ho una botte di vino che aspetta il tuo successo, $N. È giusto che io assaggi la merce prima di spedirla ai miei clienti.", enHash = "7d7cdb2f", vanilla = true },
        reward = { it = "Ah, queste dovrebbero essere perfette. Non vedo l'ora di assaggiarle, dopo averle cotte a puntino sul fuoco. Dovresti portartene un campione nei tuoi viaggi. È davvero deliziosa.", enHash = "45617d18", vanilla = true },
    },
    [1431] = {
        title = { it = "Rapporti con l'Alleanza", enHash = "d975994e", vanilla = true },
        text = { it = "Fermati, $C, e lascia che ti dica una cosa importante per il nostro popolo, ma tutt'altro che ovvia.\n\nSiamo una razza orgogliosa, e la guerra con gli umani ha messo alla prova perfino la grande pazienza di Thrall. Vedi, il nostro Capoguerra è saggio e prudente, e continua a mettere al primo posto la sua gente. In fondo è un diplomatico, e nel tempo passato con gli umani ha imparato molto dei loro modi.\n\nSe la storia che ho cominciato ti incuriosisce, cerca Keldran vicino all'uscita occidentale della città. La sua casupola è là.", enHash = "51caea34", vanilla = true },
        objectives = { it = "Parla con Keldran, a Orgrimmar.", enHash = "c78b9f73", vanilla = true },
        reward = { it = "Putanni, nobile $C. Io sono Keldran, studioso di magia... e di altre arti mistiche.\n\nLa faccenda di cui Craven ti ha mandato a parlarmi richiede un po' più di finezza di quanta te ne sia servita finora, ma questo non vuol dire che tu non possa comunque aiutare la nostra causa.\n\nTi prego, mettiti $Gcomodo:comoda;, e ti dirò perché il Capoguerra ha bisogno del mio aiuto... e del tuo.\n\nTutto comincia dalle apparenze, $N. Da come l'Orda vede se stessa. Da come ci vedono i nostri alleati. E soprattutto da come ci vedono i nostri nemici.", enHash = "2a6afa3f", vanilla = true },
    },
    [1432] = {
        title = { it = "Rapporti con l'Alleanza", enHash = "d975994e", vanilla = true },
        text = { it = "Mentre l'Alleanza avanza sempre più a fondo in Kalimdor, si potrebbero trarre conclusioni sbagliate sull'Orda e su presunti patti con la Legione Infuocata. Il Capoguerra non può permetterlo. E con la sua benedizione sto prendendo io in mano il compito di farli eliminare.\n\nHo agenti nella zona di Desolace, al Ghost Walker Post, a nord del grande Kodo Graveyard. Va' a sud del Charred Vale, nelle Stonetalon Mountains, e lo troverai. Quando arrivi, cerca Takata Steelblade.", enHash = "cebf0c02", vanilla = true },
        objectives = { it = "Parla con Takata Steelblade, a Desolace.", enHash = "05d09459", vanilla = true },
        reward = { it = "Salve, $C. Porti notizie da Orgrimmar: bene.\n\nL'infestazione di demoni soffoca questa zona ancora più della puzza di sterco di centauro. Gli uomini-cavallo rivendicano questa terra come propria, ma è chiaro che ci sono forze fuori dal loro controllo che li schiacceranno, se non le si tiene a bada.\n\nNon mi fa piacere che aiutiamo indirettamente i centauri, ma è per il bene dell'Orda, quindi faccio il mio dovere per il Capoguerra, anche se vuol dire aiutare gli stregoni dentro l'Orda.", enHash = "d048cc20", vanilla = true },
    },
    [1433] = {
        title = { it = "Rapporti con l'Alleanza", enHash = "d975994e", vanilla = true },
        text = { it = "I Burning Blade hanno molti piani, ma sappi che sono malvagi fino al midollo, con lo spirito corrotto, e distruggerli è l'unico modo per mandare all'aria i loro obiettivi.\n\nKeldran ha mandato Maurin con me per la sua conoscenza della Blade e delle vie degli stregoni.\n\nÈ lui a guidare le nostre trame contro la Blade, mentre io mi occupo delle altre minacce demoniache qui a Desolace.\n\nParlagli e ti guiderà nei suoi piani.", enHash = "14a90bae", vanilla = true },
        objectives = { it = "Parla con Maurin Bonesplitter, a Desolace.", enHash = "35cbd961", vanilla = true },
        reward = { it = "Ah, sì. L'aiuto di chi è fedele al Capoguerra è sempre gradito.\n\nMi chiamo Maurin. Sono qui su richiesta di Keldran e del cucciolo di Capoguerra, Thrall. È mio desiderio aiutare quel giovane capo contro i mali che minacciano il suo governo.\n\nVieni, avvicinati, $C. Ti spiegherò il mio piano per eliminare quel bubbone purulento che sono i Burning Blade.", enHash = "dbc2539b", vanilla = true },
    },
    [1434] = {
        title = { it = "Corrotti dai satiri", enHash = "92994714", vanilla = true },
        text = { it = "Un'infestazione di demoni non capita senza altre influenze: c'è sempre qualcos'altro che permette al male di prendere piede.\n\nPuò cominciare con uno spirito indebolito, con un desiderio inutile di potere; forse è sete di vendetta, o il richiamo di una giustizia definitiva. Quando siamo assaliti dal dolore, il male approfitta di noi: un male come i satiri.\n\nSono stati trovati legami tra loro e i Burning Blade, e Thrall li vuole morti. Cercali a nord-est di qui e torna da me quando li avrai ricacciati indietro.", enHash = "51f4c502", vanilla = true },
        objectives = { it = "Uccidi 7 Hatefury Rogue, 7 Hatefury Felsworn, 7 Hatefury Betrayer e 7 Hatefury Hellcaller, poi torna da Takata Steelblade, a Desolace.", enHash = "ba8e806b", vanilla = true },
        progress = { it = "Un compagno tauren mi ha avvertito che i satiri non sono come sembrano. Crede che ci sia qualcosa di più in loro, che il loro male sia una distorsione della loro vera natura. Ma io queste cose non le ho viste.\n\nIo vedo solo il massacro spietato dei deboli e la corruzione di chi cerca un potere oscuro.\n\nContinuerò nel mio dovere di annientarli finché il Capoguerra non mi ordinerà altro. Fino ad allora, non ho pietà di loro.", enHash = "2a94104b", vanilla = true },
        reward = { it = "Hai fatto bene, $C. Hai mostrato onore e dedizione.\n\nQuando la nostra campagna a Desolace sarà finita, il Capoguerra saprà che ci hai aiutato in quel che abbiamo fatto qui e che hai contribuito a realizzare la sua volontà.\n\nTi ringrazio.", enHash = "13a3e16c", vanilla = true },
    },
    [1435] = {
        title = { it = "Spiriti in fiamme", enHash = "b0b847f5", vanilla = true },
        text = { it = "La morte è quanto di più desiderabile per quelle creature spregevoli che voltano le spalle al loro signore per ragioni tanto egoistiche. Ma la morte non basta, quando si ha a che fare con chi si è consegnato all'oscurità.\n\nPrendi questa gemma. Quando uno dei Burning Blade è vicino alla morte, attivane la magia. L'incantesimo strapperà lo spirito corrotto dalla sua vittima e lascerà una gemma infusa.\n\nPortami queste gemme infuse, così potrò disfarmene come si deve.\n\nOra va', e possa tu sfuggire alla morte.", enHash = "5a91a3ab", vanilla = true },
        objectives = { it = "Riporta la Burning Gem e 15 Infused Burning Gem a Maurin Bonesplitter, a Desolace.", enHash = "1eabf2f8", vanilla = true },
        progress = { it = "Ho cercato di rendere la magia più semplice possibile. Tirare fuori lo spirito della tua vittima dal suo corpo ferito dovrebbe essere un gioco da ragazzi. Non contare sul potere della gemma per uccidere del tutto il nemico. Devi attivarla solo quando è vicino alla morte, altrimenti non servirà a nulla.", enHash = "a30094e4", vanilla = true },
        reward = { it = "Ah, sei $Gtornato:tornata; con successo. Bene. Dammi le gemme e le metterò in un posto sicuro....\n\nI miei compiti per te sono finiti, $C. Parla con Takata quando ti sarai $Griposato:riposata;. Potrebbe avere altri incarichi per te, o magari avrà bisogno che tu torni a Orgrimmar a informare Keldran dei nostri progressi qui a Desolace.", enHash = "a052da85", vanilla = true },
    },
    [1436] = {
        title = { it = "Rapporti con l'Alleanza", enHash = "d975994e", vanilla = true },
        text = { it = "La lotta va bene, $N. Forse il Capoguerra ci lascerà tornare alle nostre case prima del cambio di stagione, se continuiamo a fare passi avanti così grandi nella battaglia contro i demoni e i loro servi.\n\nTorna da Keldran e fagli sapere cosa abbiamo fatto. Sono sicuro che ti ricompenserà per quel che hai fatto qui. La sua causa gli sta a cuore, e sarà fiero di sapere che il Capoguerra tiene conto delle sue preoccupazioni.", enHash = "c50e6776", vanilla = true },
        objectives = { it = "Parla con Keldran, a Orgrimmar.", enHash = "c78b9f73", vanilla = true },
        reward = { it = "Sei $Gtornato:tornata; da Desolace con più che un successo, $N. Grazie.\n\nGrazie per il tuo impegno, per il tuo tempo e per aver capito la mia richiesta. Thrall comprende e desidera la pace tra l'Orda e l'Alleanza, e prendendo provvedimenti perché il nostro aspetto sia accettabile, non provocheremo altre minacce di violenza inutile.\n\nTi sono debitore.", enHash = "ed7a5cc3", vanilla = true },
    },
    [1437] = {
        title = { it = "La ricerca di Vahlarriel", enHash = "aa046a5e", vanilla = true },
        text = { it = "Sono Vahlarriel, $N. Mi trovo qui per scoprire dove siano finiti due nobili scomparsi di una famiglia di mercanti di Darnassus, la casata Malem. Il padre della casata teme il peggio, e io devo fare tutto il possibile per ritrovare i suoi figli scomparsi. Non ho ancora cominciato a cercare Tyranis o Dalinda, ma spero di non dover restare qui a lungo.\n\nLe ultime notizie dicono che sono passati per le Stonetalon Mountains qualche settimana fa.\n\nSe trovi il loro carro, ti prego, vieni a cercarmi immediatamente.", enHash = "d51decba", vanilla = true },
        objectives = { it = "Trova e perquisisci il carro di Tyranis e Dalinda Malem, a Desolace.", enHash = "1fd3e613", vanilla = true },
        reward = { it = "Frugando tra i resti del carro, diventa evidente che è stato attaccato sia con incantesimi sia con armi. Lo scontro sembra essere stato rapido e a senso unico: non c'è traccia di sangue, né resti di corpi.\n\nChiunque abbia attaccato il carro è stato efficiente e rapido.", enHash = "b4de6d27", vanilla = true },
    },
    [1438] = {
        title = { it = "La ricerca di Vahlarriel", enHash = "aa046a5e", vanilla = true },
        text = { it = "Trova sia Dalinda sia Tyranis, se puoi, e torna da me con quello che hai scoperto. Comincia le ricerche da questa fortezza. Contatterò subito i miei superiori a Darnassus e li informerò della situazione.\n\n$N, c'è un'altra cosa che voglio farti capire bene. I miei superiori si sono mostrati preoccupati per Tyranis e per i motivi che l'hanno spinto a venire qui. Per loro è più importante che Dalinda venga ritrovata e riportata a casa sana e salva. Tyranis va... valutato prima di essere riportato a casa.", enHash = "47e97599", vanilla = true },
        objectives = { it = "Trova Dalinda Malem, a Desolace.", enHash = "4cf21fb5", vanilla = true },
        reward = { it = "Grazie a Elune, finalmente qualcuno è venuto ad aiutarmi. Ti prego, $C, ho bisogno del tuo aiuto. Mio fratello Tyranis e io siamo stati catturati e portati qui dalla Burning Blade. Credo che vogliano sacrificarmi ai loro padroni demoniaci!\n\nSapevo che venire a Desolace era un errore, ma di recente Tyranis ha cominciato a bramare la conoscenza di tutto ciò che è arcano, perfino contro la volontà del nostro popolo. Ha deciso di fare questo viaggio anche dopo aver sentito i racconti sull'infestazione di demoni di questa terra.\n\nTemo il peggio per lui.", enHash = "e41af07a", vanilla = true },
    },
    [1439] = {
        title = { it = "Alla ricerca di Tyranis", enHash = "df939b55", vanilla = true },
        text = { it = "Siamo stati portati qui dopo che gli orchi hanno massacrato tutte le nostre guardie e i nostri servitori. Oh, le cose terribili che hanno fatto loro! Pensavo che di sicuro ci avrebbero uccisi lì, seduta stante, ma è diventato chiaro che avevano altri piani.\n\nTyranis ha cercato di parlare con loro. Credo che volesse impressionarli con la sua conoscenza dell'arcano... non so bene perché.\n\nTi prego, non posso andarmene da qui finché non so cosa è successo a mio fratello. Trovalo, poi torna a prendermi quando la sua sorte sarà nota.", enHash = "7efe89b7", vanilla = true },
        objectives = { it = "Trova Tyranis Malem, a Desolace.", enHash = "ede8f722", vanilla = true },
        progress = { it = "Temo che Tyranis cercherà di imparare i segreti della Burning Blade e di unirsi a loro, se glielo permetteranno: ha sempre adorato il potere che la magia dà a chi se ne lascia sedurre.\n\nNon so se potrei sopportare di tornare a casa dalla mia famiglia con la notizia che Tyranis sta flirtando con simili pericoli. Tra la mia gente è già un crimine abbastanza grave inseguire queste cose, ma diventare ciò da cui cerchiamo di proteggerci, beh, è riprovevole.", enHash = "b04e5c90", vanilla = true },
        reward = { it = "È terribile! Ma suppongo che fosse necessario. Se non fosse stato per mano tua, di sicuro sarebbe stato per mano della mia gente. Credo di doverti ringraziare... perdonami se il mio grazie non sembra sincero. Non intendo offenderti.\n\nOra che conosco la sorte di mio fratello, sembra che sia giunto il momento della mia fuga. Se sei ancora $Gdisposto:disposta;, accetterò il tuo aiuto per fuggire da questo posto orribile.\n\nQuando sei $Gpronto:pronta;, possiamo metterci in salvo.", enHash = "2805deb3", vanilla = true },
    },
    [1440] = {
        title = { it = "Ritorno da Vahlarriel", enHash = "835dfe53", vanilla = true },
        text = { it = "Allora, è giunto il momento? Apprezzo i tuoi sforzi, e se poi non ci sarà occasione, lascia che ti ringrazi adesso per tutto quello che hai fatto per me e per la mia famiglia. Se sei $Gpronto:pronta;, qui non c'è più niente per me: possiamo partire quando ritieni che sia il momento giusto.", enHash = "f04337ea", vanilla = true },
        objectives = { it = "Scorta Dalinda Malem fuori dalla Thunder Axe Fortress, poi torna da Vahlarriel Demonslayer, a Desolace.", enHash = "cea96ada", vanilla = true },
        reward = { it = "Grazie, $N. Dalinda è tornata sana e salva qui a Nijel's Point, e in condizioni molto migliori di quanto potessi sperare. Il fatto che sia arrivata qui con le sue forze è un buon segno. Tu stai bene, spero?\n\nMi addolora sapere che non sono tornati entrambi, Tyranis e Dalinda, ma la vergogna per le scelte di Tyranis dovrà sopportarla lei. È qualcosa che dovrà affrontare quando tornerà a Darnassus.", enHash = "8c222e37", vanilla = true },
    },
    [1447] = {
        title = { it = "Il diplomatico scomparso", enHash = "a6d3009b", vanilla = true },
        text = { it = "Già, non sei certo $Gil:la; $C più $Gsveglio:sveglia; che sia mai entrato a Stormwind, ma stai per essere $Guno:una; dei più stupidi che non ne usciranno mai.\n\nHai conosciuto i miei amici?", enHash = "9242dbb8", vanilla = true },
        objectives = { it = "Sconfiggi Dashel Stonefist, a Stormwind.", enHash = "23f50147", vanilla = true },
        progress = { it = "Non volevo dire niente con quella battuta sul fatto che sei $Gun:una; $C $Gstupido:stupida;. Siamo amici, no? Nessun rancore?", enHash = "2fa072a7", vanilla = true },
        reward = { it = "Allora, sei $Gvenuto:venuta; da me per un motivo. Di cosa hai bisogno?", enHash = "348630d5", vanilla = true },
    },
    [1448] = {
        title = { it = "Alla ricerca del Tempio", enHash = "c99e8068", vanilla = true },
        text = { it = "C'è stato un tempo in cui ero giovane e pieno di vigore come te, $C.\n\nMa ora sono vecchio e non posso più esplorare il mondo come facevo una volta. Ah, le cose che ho visto!\n\nMa c'era un mistero che mi è sempre sfuggito. Per la mia ultima impresa, la Lega degli Esploratori mi ha mandato in cerca del Temple of Atal'Hakkar. Si diceva che si trovasse nella Swamp of Sorrows.\n\nVisto il mio stato fragile, ho sorvolato i cieli in grifone per cercarlo, ma non l'ho mai trovato.\n\nDai una mano a un vecchio nano? Magari tu avrai più fortuna a piedi.", enHash = "e3765b40", vanilla = true },
        objectives = { it = "Brohann Caskbelly, a Stormwind, vuole che tu cerchi il Temple of Atal'Hakkar.", enHash = "3de7e68a", vanilla = true },
        progress = { it = "Ho girato il mondo, dalle giungle di Azeroth alle cime innevate di Khaz Modan.\n\nMai prima d'ora avevo chiesto aiuto nelle mie avventure. Ma le mie vecchie ossa sono stanche.\n\nNiente mi renderebbe più soddisfatto che sapere di aver portato a termine la mia ultima impresa per la Lega degli Esploratori.\n\nSe fossi così gentile da aiutarmi a cercare il Temple of Atal'Hakkar, $C, te ne sarei molto grato.\n\nPerlustra la Swamp of Sorrows e torna a riferirmi quello che hai trovato!", enHash = "51bb92ec", vanilla = true },
        reward = { it = "Il Temple of Atal'Hakkar è sprofondato sotto il Pool of Tears? E circondato dallo stormo dei draghi verdi?\n\nUna scoperta incredibile, $C. Ma è chiaro che qualcosa è andato terribilmente storto.", enHash = "5aa1fbcc", vanilla = true },
    },
    [1449] = {
        title = { it = "Verso le Hinterlands", enHash = "e55f4e20", vanilla = true },
        text = { it = "Come ti ho detto prima, ho cercato di esplorare il tempio da solo, dall'alto. Be', non ero proprio solo.\n\nSono andato alla famosa voliera dei grifoni dell'Aerie Peak, nelle Hinterlands. Lì ho chiesto l'aiuto di uno dei loro piloti migliori. Il pilota è caduto dalla sua cavalcatura, giù nella palude...\n\nAlla mia età il nome di quel poveretto mi sfugge. Il capo della voliera se lo ricorderà di sicuro.\n\nVa' laggiù e cerca Falstad Wildhammer.\n\nDobbiamo scoprire che fine ha fatto quel pilota.", enHash = "d394cc5b", vanilla = true },
        objectives = { it = "Parla con High Thane Falstad Wildhammer all'Aerie Peak, nelle Hinterlands.", enHash = "345c2bef", vanilla = true },
        reward = { it = "Che vuoi, $Gragazzo:ragazza;? Non vedi che ho dei problemi da sistemare qui? Chi ha tempo di stare lì a chiacchierare con $Gun:una; $R $Gchiacchierone:chiacchierona;?\n\nI troll sbucano da tutte le parti! Sbrigati.", enHash = { "cd22dc74", "45953b3b" }, vanilla = true },
    },
    [1453] = {
        title = { it = "Affari dei Reclaimers a Desolace", enHash = "b588ce65", vanilla = true },
        text = { it = "C'è del lavoro da fare a Desolace, $N. È un posto atroce, infestato dai centauri e da altre bestiacce. Ma se cerchi una buona settimana di lavoro onesto, va' là, incontra Kreldig Ungor e digli che ti mando io.\n\nLo trovi rintanato a Nijel's Point: è un piccolo accampamento accogliente nascosto tra le montagne della Desolace settentrionale. Se entri dalle Stonetalon Mountains, va' semplicemente a est. È facile non vederlo, quindi tieni gli occhi aperti.", enHash = "21a61578", vanilla = true },
        objectives = { it = "Parla con Kreldig Ungor, a Desolace.", enHash = "0240fc51", vanilla = true },
        reward = { it = "Che piacere vedere che ai Reclaimers non manca il lavoro, né gente disposta a dare una mano.\n\nIo sono Kreldig, $N. Hai fatto una mossa furba a dare una mano ai Reclaimers. Di questi tempi tutti hanno bisogno di qualcosa: chi ha perso un cimelio di famiglia, chi un oggetto magico, chi una persona cara. Non si sa mai. Ma finché ci sono i Reclaimers, non c'è motivo che qualcuno non ritrovi quel che ha perso, al giusto prezzo.", enHash = "a46a9591", vanilla = true },
    },
    [1454] = {
        title = { it = "Il naufragio di Karnitol", enHash = "a10386df", vanilla = true },
        text = { it = "Il mio primo incarico è per il mago Karnitol, un nobile di qualche tipo a Stormwind. Pare che la sua nave sia stata attaccata dai giganti marini al largo della costa, nel nord-ovest di Desolace. Lui e i suoi servitori hanno cercato di portare a riva uno dei suoi forzieri più preziosi, ma quando i giganti marini hanno attaccato in massa, ha scelto di abbandonarlo e di teletrasportare sé stesso e i servitori al sicuro.\n\nVuole che troviamo il forziere e il suo contenuto e che glieli riportiamo a Stormwind.", enHash = "727b6550", vanilla = true },
        objectives = { it = "Trova Karnitol's Chest, a Desolace.", enHash = "fc763db1", vanilla = true },
        reward = { it = "Noti che il forziere non sembra danneggiato dall'acqua.\n\nLa seconda cosa che noti è che il coperchio è stato forzato, e qualunque trappola magica fosse stata messa a proteggerlo è scattata da tempo: lo si capisce chiaramente dai segni di bruciatura lungo i bordi.", enHash = "bebc7e70", vanilla = true },
    },
    [1455] = {
        title = { it = "Il naufragio di Karnitol", enHash = "a10386df", vanilla = true },
        text = { it = "Ti prendi qualche momento per capire che cosa abbia scardinato il forziere, e noti lungo i lati e sul coperchio dei graffi lunghi e profondi, segno che qualcosa di diverso da un uomo o da un gigante si è interessato al forziere. I segni non sembrano fatti da un pugnale o da una spada.\n\nFrugando nel forziere, scopri che è completamente vuoto.\n\nNon avendo altro da fare, chiudi il forziere e ti prepari ad andartene. Kreldig sarà deluso.", enHash = "fca45008", vanilla = true },
        objectives = { it = "Torna da Kreldig Ungor, a Desolace.", enHash = "4277012f", vanilla = true },
        reward = { it = "$GBentornato:Bentornata; a Nijel's Point, $N. Allora, dimmi cosa hai trovato.\n\nCosa!? Niente? Temo che un forziere vuoto non ci farà pagare.\n\nRaccontami di più di quei segni che hai visto... di quei tagli.", enHash = "6f4c1dd5", vanilla = true },
    },
    [1456] = {
        title = { it = "Il naufragio di Karnitol", enHash = "a10386df", vanilla = true },
        text = { it = "Interessante.\n\nBeh, forse non abbiamo ancora perso ogni speranza.\n\nLungo quella stessa costa, ma più a nord, vicino alla Ranazjar Isle, ci sono delle rovine degli elfi della notte in fondo all'oceano. Una tribù di naga, gli Slitherblade, ci ha fatto casa. Credo che sia la nostra carta migliore.\n\nSe un gruppo di esploratori si è spinto così a sud, doveva essere piuttosto potente. Se vuoi trovare gli effetti personali di Karnitol, io comincerei dai naga più potenti: i tidehunter o le sea witch.", enHash = "d79f333c", vanilla = true },
        objectives = { it = "Trova Karnitol's Satchel e riportala a Kreldig Ungor, a Desolace.", enHash = "4c282550", vanilla = true },
        progress = { it = "Senza offesa per chiunque sia questo Nijel, ma questo accampamento non è il posto più comodo in cui abbia mai passato una notte, se capisci cosa intendo, $N.", enHash = "8cd4fb0d", vanilla = true },
        reward = { it = "Fantastico, $N! Hai trovato gli effetti personali di Karnitol!\n\nQuei maledetti naga, sempre a creare guai. Credo che preferirei passare la vita in guerra con l'Orda piuttosto che dover affrontare quelli della loro specie. Hai reso un grande servizio ai Reclaimers.", enHash = "7743bfba", vanilla = true },
    },
    [1457] = {
        title = { it = "Il naufragio di Karnitol", enHash = "a10386df", vanilla = true },
        text = { it = "Riporta le cose di Karnitol a Roetten, a Ironforge, e lui ti pagherà per il lavoro ben fatto.\n\nAhah, se non fai attenzione, sarà così contento di te che ti chiederà di unirti a noi a tempo pieno.\n\nDi nuovo, ottimo lavoro, $N.\n\nFa' attenzione sulla via del ritorno, e non metterci troppo: Karnitol non è il più paziente degli uomini, ma è comunque molto generoso.", enHash = "26f6cb19", vanilla = true },
        objectives = { it = "Porta Karnitol's Satchel a Roetten Stonehammer, a Ironforge.", enHash = "34050b7b", vanilla = true },
        progress = { it = "Gli affari vanno a gonfie vele, $N, e non ho molto tempo per le domande. Se hai affari con i Reclaimers, sentiamo. Altrimenti dovrò chiederti di parlare con uno dei miei sottoposti: sono abbastanza bravi a sbrigare le cose da queste parti.", enHash = "6a828590", vanilla = true },
        reward = { it = "Ah, la faccenda di Karnitol a Desolace. Eccellente!\n\nQuindi il forziere è stato distrutto, ma gli oggetti ci sono tutti, eh? Beh, lascerò che sia lui a giudicare. Una cosa buona di questo mio giro d'affari è che, se non sono soddisfatti, posso mandarli a quel paese! Contano su di noi per ritrovare la loro roba... non per assicurarci che sia tutta bella e in buono stato quando la riavranno.\n\nBuon lavoro, $N. Vediamo di farti pagare.", enHash = "4f77d9db", vanilla = true },
    },
    [1458] = {
        title = { it = "Reagenti per la Reclaimers Inc.", enHash = "91a0157d", vanilla = true },
        text = { it = "Uno dei miei compiti qui fuori è procurare dei reagenti per Leftwitch, un mago gnomo di Kharanos. Roetten pensa che siano soldi facili, visto che siamo già qui. Non gli importa granché che siamo già a corto di personale.\n\nLe prime cose sulla sua lista dovrebbero essere abbastanza facili da trovare, e ci sarebbe un bel gruzzolo per chi mi dà una mano.\n\nMi servono corna e artigli dei satiri Hatefury, a est di qui. Portameli e cominceremo con il resto della lista.", enHash = "fcd11715", vanilla = true },
        objectives = { it = "Porta 10 Hatefury Claw e 10 Hatefury Horn a Kreldig Ungor, a Desolace.", enHash = "4e70e4cc", vanilla = true },
        progress = { it = "Creature spregevoli, i satiri. Si racconta che siano in qualche modo legati agli elfi della notte, ma non so se ci credo davvero.\n\nCredo che quella storia venga da quell'elfo che li ha trascinati nella guerra qualche anno fa. Da allora il mondo non è più stato lo stesso. Molto più pericoloso, e molto più spaventoso.", enHash = "42781cb8", vanilla = true },
        reward = { it = "Bene, bene, $N. Non so se siano di buona qualità, ma se Leftwitch voleva un tipo particolare, avrebbe dovuto specificarlo prima di mandare i Reclaimers quaggiù.\n\nChe ne dici di passare alla prossima voce della sua lista?", enHash = "6ed6aee9", vanilla = true },
    },
    [1459] = {
        title = { it = "Reagenti per la Reclaimers Inc.", enHash = "91a0157d", vanilla = true },
        text = { it = "La prossima voce sulla lista di Leftwitch è... vediamo... hmm. Ah, eccola.\n\nAbbastanza semplice, ma le sue istruzioni sono piuttosto precise. Gli serve veleno di scorpashi e pelle di kodo. Le note in piccolo dicono che tutti e due devono venire da creature specifiche: il veleno deve venire da uno scorpashi qualsiasi, e la pelle da un kodo vecchio, non da quelli morenti o antichi.\n\nI maghi, te lo dico io, certe cose che vogliono... sono proprio strane.", enHash = "8c579e96", vanilla = true },
        objectives = { it = "Porta 7 fiale di Scorpashi Venom e 3 Aged Kodo Hide a Kreldig Ungor, a Desolace.", enHash = "1d64c40a", vanilla = true },
        progress = { it = "Mi dispiace di non averti saputo dire dove trovare i kodo o gli scorpashi. Non conosco molto bene la zona, e non ho avuto tempo di esplorarla.", enHash = "75fef1d0", vanilla = true },
        reward = { it = "Il tuo aiuto qui è una manna, $N. Stai dimezzando come minimo il tempo che devo passare qui a Desolace. Con il tuo aiuto, in un attimo sarò di nuovo a Ironforge a scaldarmi i piedi.\n\nQuando avremo sistemato questa lista e sarò di nuovo a casa, vieni a trovarmi: una birra te la offro di sicuro.\n\nMa fino ad allora, raccogliamo il resto di questi reagenti.", enHash = "955dc3b8", vanilla = true },
    },
    [1462] = {
        title = { it = "Earth Sapta", enHash = "2135a679", vanilla = true },
        objectives = { it = "Parla con Seer Ravenfeather per avere un'altra Earth Sapta.", enHash = "50ca3fcc", vanilla = true },
        reward = { it = "Prendila, e ricorda: è sacra.", enHash = "599773be", vanilla = true },
    },
    [1463] = {
        title = { it = "Earth Sapta", enHash = "2135a679", vanilla = true },
        objectives = { it = "Parla con Canaga Earthcaller per avere un'altra Earth Sapta.", enHash = "e9d6caf2", vanilla = true },
        reward = { it = "Te ne do una in buona fede. Hai già dimostrato il tuo valore una volta, ma secondo me in futuro dovresti stare più $Gattento:attenta;.", enHash = "93545056", vanilla = true },
    },
    [1464] = {
        title = { it = "Fire Sapta", enHash = "838d6365", vanilla = true },
        objectives = { it = "Parla con Telf Joolam per avere un'altra Fire Sapta.", enHash = "76bd5d61", vanilla = true },
        reward = { it = "Che il fuoco arda nel tuo cuore, $N.\n\nGli elementi ti aspettano.", enHash = "cc0043ef", vanilla = true },
    },
    [1465] = {
        title = { it = "La ricerca di Vahlarriel", enHash = "aa046a5e", vanilla = true },
        text = { it = "Continuando a perquisire il carro trovi non solo un ciondolo, ma anche delle impronte che si allontanano verso sud. In lontananza vedi il fumo che sale da un grande forte. È il fumo di un fuoco acceso di proposito, non di edifici in fiamme, e l'istinto ti dice che i Malem, se ancora vivi, sono stati portati in quella direzione.\n\nPensi che Vahlarriel, a Nijel's Point, non debba solo vedere il ciondolo che hai trovato, ma anche sapere dei segni di vita a sud.", enHash = "2a9de48f", vanilla = true },
        objectives = { it = "Riporta il Malem Pendant a Vahlarriel Demonslayer, a Desolace.", enHash = "a81fbeb6", vanilla = true },
        reward = { it = "Esasperante! Tutto questo disastro!\n\nEntrambi erano stati avvertiti di quanto sarebbe stato pericoloso venire qui. Ora sono spariti tutti e due... o peggio.\n\nHai detto di aver visto delle tracce dirette verso un forte qui vicino? Potrebbe essere la nostra carta migliore.\n\nDa quello che dice la gente del posto, quella fortezza è infestata da membri della Burning Blade, orchi che si sono votati alla causa dei demoni. Forse non rappresentano ciò in cui crede la maggior parte dell'Orda, ma sono malvagi e ti uccideranno a vista se ti sorprendono a spiare.", enHash = "9d3b458e", vanilla = true },
    },
    [1466] = {
        title = { it = "Reagenti per la Reclaimers Inc.", enHash = "91a0157d", vanilla = true },
        text = { it = "Questa è l'ultima voce, e non ti mentirò: non è una bella cosa. Mi aspetto anche che ti porti via un po' più di tempo delle altre.\n\nAllora, basta avvertimenti, cominciamo. Leftwitch dice che gli servono: dieci cervelli di mana eater, mage hunter o ley hunter. Dieci Nether Wing da una nether maiden, sister o sorceress. E... dieci fiale di Doomwarder Blood da un doomwarder captain o lord.\n\nAbbastanza semplice, eh? Accidenti... se vuoi rinunciare a questa, ti capirei.", enHash = "ec917f2c", vanilla = true },
        objectives = { it = "Porta 10 Felhound Brain, 10 Nether Wing e 10 fiale di Doomwarder Blood a Kreldig Ungor, a Desolace.", enHash = "3db62dff", vanilla = true },
        progress = { it = "Non sapevo nemmeno che a Desolace ci fossero queste cose demoniache. L'ultima volta che ho letto qualcosa in proposito, i centauri erano praticamente i padroni di queste terre, da quando gli elfi della notte avevano fatto i bagagli ed erano partiti anni fa.\n\nMi chiedo perché si siano stabiliti qui, e come.", enHash = "d90c3720", vanilla = true },
        reward = { it = "Sul serio? Non l'avrei mai detto. Sei incredibile, $N. Affrontare dei demoni per gli esperimenti di un mago, e per giunta tornare $Gtutto intero:tutta intera;. Ottimo lavoro!\n\nParlerò di te a Roetten di persona quando tornerò a Ironforge.", enHash = "a4618bed", vanilla = true },
    },
    [1467] = {
        title = { it = "Reagenti per la Reclaimers Inc.", enHash = "91a0157d", vanilla = true },
        text = { it = "Per ricevere la paga, dovrai tornare a Ironforge e parlare con Roetten in persona. Sarà comunque felice di togliersi di mezzo il pacco di Leftwitch. Dagli solo questo e dovrebbe bastare per avere il tuo bottino.\n\nE non preoccuparti, metterò comunque una buona parola per te quando tornerò. Non dovrei restare a Desolace ancora per molto.", enHash = "a780ad77", vanilla = true },
        objectives = { it = "Riporta Leftwitch's Package a Roetten Stonehammer, a Ironforge.", enHash = "87abe3de", vanilla = true },
        progress = { it = "Salute, $N. Gli affari vanno a gonfie vele, il suono delle incudini risuona per tutta Ironforge, i mantici attizzano i fuochi e mia moglie mi sta preparando una torta per il dessert dopo la cena di stasera. La vita potrebbe essere più bella?", enHash = "8ed4e97e", vanilla = true },
        reward = { it = "Ah, il pacco per Leftwitch da Desolace. Eccellente. Apprezzo il lavoro, e la tua puntualità, $C. Sono contento di averti avuto con noi almeno per questo piccolo lavoro.\n\nHo il tuo pagamento proprio qui. Che si sappia: la Reclaimers Inc. paga sempre bene per una dura settimana di lavoro.", enHash = "0d05f9d4", vanilla = true },
    },
    [1468] = {
        title = { it = "Settimana dei Bambini", enHash = "7db99b89", vanilla = true },
        text = { it = "Vuoi aiutarci qui all'orfanotrofio? Che il cielo ti benedica, $Gamico:amica;: il tuo aiuto durante la Settimana dei Bambini sarà prezioso.\n\nPrendi questo fischietto. Potrai usarlo solo per poco tempo, di solito non più a lungo della Settimana dei Bambini stessa. Quando lo usi, potrai parlare con il bambino di cui hai accettato di occuparti. Se lo usi di nuovo, il bambino se ne andrà.\n\nForza, $N, usa il fischietto e conosci il tuo protetto! Sono sicura che il bambino non vedrà l'ora di conoscerti.", enHash = "0af62f95", vanilla = true },
        objectives = { it = "Usa lo Human Orphan Whistle per parlare con il bambino di cui ti occuperai durante la Settimana dei Bambini.", enHash = "480a4251", vanilla = true },
        reward = { it = "Ehm... ciao. Mi chiamo Randis, e immagino che sarai tu a occuparti di me? Sei $Gun avventuriero:un'avventuriera;, come lo erano la mia mamma e il mio papà. Sono contento di conoscerti.\n\nSpero che ci divertiremo un sacco insieme. Ho alcune cose che vorrei fare, e la matrona dice che durante questa settimana sarai come $Gun fratello maggiore:una sorella maggiore; per me. Mi piacerebbe un sacco, sì, $Gsignore:signora;.", enHash = { "312addae", "79688f3d" }, vanilla = true },
    },
    [1470] = {
        title = { it = "Squarciare il velo", enHash = "46455a1c" },
        text = { it = "Salve, $Gfigliolo:figliola;. Vedo che sei ancora $Gacerbo:acerba; nelle vie $Gdel:della; $C, e il potere ti sfugge ancora di mano. Percepisco la tua voglia di imparare.\n\nE imparerai.\n\nNon c'è forza nell'ignoranza. La conoscenza è il nostro potere più grande. Applicandola possiamo controllare le magie caotiche e gli esseri del vuoto, piegandoli alla nostra volontà.\n\nTi mostrerò come vincolare un servitore alla tua volontà, ma prima devi portarmi tre teschi dei Rattlecage Skeleton vicino alla fucina abbandonata.", enHash = "9f9b7ddd" },
        objectives = { it = "Porta a Venya Marthand 3 Rattlecage Skull.", enHash = "9eb7fd7d" },
        progress = { it = "Il tuo potere ora è poco, anche se sospetto che tu ne intuisca già le possibilità.\n\nPerfino i morti potrebbero sentirsi vivi, con quel potere che ci scorre dentro.", enHash = "7f698fdc", vanilla = true },
        reward = { it = "Anche se non sei ancora $Gstato messo:stata messa; alla prova e sei agli inizi del tuo apprendistato, hai dimostrato di possedere abilità sufficienti a padroneggiare l'evocazione e il vincolo di un Imp. Non lasciarti ingannare dalle dimensioni di un Imp. Anche se gli manca la forza fisica, possiede poteri e un'astuzia che ti saranno molto utili.\n\nAscoltami con attenzione, $N, perché non ripeterò questa lezione, e lascerò a te il compito di padroneggiarla.", enHash = "f07862af", vanilla = true },
    },
    [1471] = {
        title = { it = "Il vincolo", enHash = "2a2909d6", vanilla = true },
        text = { it = "Avrai certamente visto il cerchio di evocazione qui sotto? Solo lì potrai richiamare un Voidwalker non vincolato.\n\nCon queste rune potrai richiamarlo, e poi dovrai dominarlo con la forza delle armi e della magia.\n\nUna volta sottomesso, sarà al tuo servizio. Allora vieni da me, e ti spiegherò l'incantesimo di evocazione, così che possa servirti per qualunque scopo tu voglia.", enHash = "1a6d4e4b", vanilla = true },
        objectives = { it = "Usando le Runes of Summoning, evoca e sottometti un Voidwalker, poi riporta le Runes of Summoning a Carendin Halgar, nel Magic Quarter dell'Undercity.", enHash = "74f2dfd8", vanilla = true },
        progress = { it = "Mi aspetto di sentire del tuo successo, $N. Se dovessi fallire, però, deludere le mie aspettative sarà l'ultima delle tue preoccupazioni.", enHash = "403ecce3", vanilla = true },
        reward = { it = "Hai fatto bene, $N. Ora ti trasmetterò l'incantesimo per evocare il Voidwalker.\n\nIl potere che ha scatenato contro di te ora è tuo da comandare. Usalo con saggezza.", enHash = "bf34df67", vanilla = true },
    },
    [1472] = {
        title = { it = "Divoratrice di anime", enHash = "b530f7f3", vanilla = true },
        text = { it = "Una Succubus è una divoratrice di anime, una distruttrice di cuori, una tentatrice di uomini. Una creatura di profonda malvagità, con la mente fissa su un solo scopo.\n\nNon può essere portata nel nostro mondo senza uno stimolo.\n\nPer questo usiamo la sua stessa forza contro di lei. Con i cuori di uomini buoni, uomini puri, uomini amorevoli, la Succubus non potrà resistere e passerà nel nostro mondo. Allora potrai dominarla e renderla tua.\n\nParla con il mio assistente, Godrick Farsan, nel Temple. Ti aiuterà a trovare l'esca.", enHash = "43bbf863", vanilla = true },
        objectives = { it = "Parla con Godrick Farsan, nel Temple of the Damned.", enHash = "83351428", vanilla = true },
        reward = { it = "Ti manda Carendin? Allora sei $N.\n\nNon prendermi alla leggera perché ho perso la vista. Ora vedo le cose che si celano dietro, con una chiarezza che non avevo mai conosciuto. Quella che un tempo credevo una maledizione, ora è una benedizione.", enHash = "15506b0e", vanilla = true },
    },
    [1473] = {
        title = { it = "Creatura del vuoto", enHash = "de4975ab", vanilla = true },
        text = { it = "Sembra che tutti siano d'accordo sul fatto che tu sia $Gpronto:pronta; a imparare a evocare un Voidwalker.\n\nÈ un essere creato dal caos che si trova oltre: se ne evochi uno ma non riesci a controllarlo, verrai $Gfatto:fatta; a pezzi.\n\nIl primo Voidwalker fu evocato da Egalin, e il procedimento è spiegato nel suo grimorio.\n\nPurtroppo ce l'ha rubato un agente della Crociata Scarlatta, che lo tiene nascosto nella sua base, in una torre a ovest. Portamelo, e ti trasmetterò la conoscenza.", enHash = "78e60b56", vanilla = true },
        objectives = { it = "Recupera Egalin's Grimoire e portalo a Carendin Halgar, nel Temple of the Damned.", enHash = "13e1704e", vanilla = true },
        progress = { it = "Egalin è stato il maestro che mi ha istruito. Gli bastava un'occhiata per comandare il Voidwalker che aveva evocato.\n\nQuando venne il mio turno di provarci, peccai di presunzione. Non prendere alla leggera i poteri che maneggi, $N: possono consumare anche chi sta in guardia.", enHash = "92946010", vanilla = true },
        reward = { it = "Ah, è eccellente. Con ogni probabilità, Perrine ignorava il vero potere del libro ammuffito che ci aveva rubato.\n\nNon ci sfuggirà più di mano. Osserva, $N, la struttura dell'incantesimo, il modo in cui il tuo potere deve essere incanalato.", enHash = "cd4912ce", vanilla = true },
    },
    [1474] = {
        title = { it = "Il vincolo", enHash = "2a2909d6", vanilla = true },
        text = { it = "Usando questi cuori, lancia un incantesimo nel cerchio di evocazione per aprire un varco da cui la Succubus possa passare. Ora i tuoi poteri sono maggiori, e ti serviranno tutti per sconfiggere la Succubus.\n\nGuardati dal suo fascino, $N: molte menti forti sono state piegate alla sua volontà. Una volta sconfitta, la Succubus tornerà nel vuoto, e io ti insegnerò l'incantesimo per richiamarla ai tuoi ordini.", enHash = "2ef09590", vanilla = true },
        objectives = { it = "Usando i Pure Hearts, evoca e sottometti una Succubus, poi riporta i Pure Hearts a Carendin Halgar, nel Magic Quarter dell'Undercity.", enHash = "616883b5", vanilla = true },
        progress = { it = "Tra i poteri che vengono da oltre il vuoto, la Succubus è uno dei più pericolosi, perché i deboli sono i più facili da rigirare come vuole.\n\nRicordalo, ora e in futuro.", enHash = "46f56712", vanilla = true },
        reward = { it = "Ancora una volta hai fatto bene, $N. Era da parecchio tempo che non vedevo $Gun giovane stregone:una giovane strega; con un potenziale come il tuo. Ti assicuro che continuerò a seguire i tuoi progressi, e a prepararti e aiutarti nelle tue prove future.\n\nPer ora, lascia che ti mostri l'incantesimo di evocazione per la Succubus che hai appena dominato.", enHash = "592ffca2", vanilla = true },
    },
    [1476] = {
        title = { it = "I cuori dei puri", enHash = "48aebabd", vanilla = true },
        text = { it = "Uomini d'onore e di bontà? Esiste davvero un uomo così?\n\nCi sono volute molte ricerche, ma mettendo insieme frammenti di storie sentite qua e là, sono riuscito a trovare due uomini che dovrebbero andare bene.\n\nIl primo è Dalin Forgewright, che si è dedicato alla cura dei profughi di Lordaeron, respinti dalla loro stessa gente al Greymane Wall.\n\nL'altro è Comar Villard, un uomo che resta fedele al suo amore perduto e vaga per le Wetlands in cerca di un segno di sua moglie.\n\nConsegna i loro cuori a Carendin. Ma prima, lascia che ti mostri le tue prede.", enHash = "c27c3c08", vanilla = true },
        objectives = { it = "Porta i cuori di Dalin Forgewright e di Comar Villard a Carendin Halgar, nel Temple of the Damned.", enHash = "7cb69ee4", vanilla = true },
        progress = { it = "Sono piacevolmente sorpreso dalla rapidità dei tuoi progressi finora, $N. Portami i cuori e mi stupirai ancora una volta.", enHash = "4cb6ca86", vanilla = true },
        reward = { it = "Il cuore di un uomo buono sembra uguale a qualsiasi altro, visto così, non trovi?\n\nForse abbiamo una visione un po'... diversa... della cosa. Questi andranno bene, comunque. Non ho dubbi che una Succubus sarebbe attratta dalla loro purezza.", enHash = "d7b3293f", vanilla = true },
    },
    [1477] = {
        title = { it = "Rifornimenti vitali", enHash = "0b84d761", vanilla = true },
        text = { it = "I nostri maghi stanno conducendo delle ricerche a Nethergarde Keep, nelle Blasted Lands: ricerche vitali per capire i Dark Portal. Hanno bisogno di rifornimenti quasi continui, ma la nostra linea di rifornimento verso Nethergarde è fragile.\n\nDevi aiutarci a fare in modo che i rifornimenti arrivino a Nethergard. Presentati a Watchmaster Sorigal, a Darkshire, e fa' quello che ti chiede. Questo compito ti porterà in terre ostili, $N. Preparati.", enHash = "1f46cbb3", vanilla = true },
        objectives = { it = "Parla con Watchmaster Sorigal.", enHash = "7e855f4a", vanilla = true },
        reward = { it = "Ti ha mandato Andromath? Molto bene. Ho un compito importante per te...", enHash = "4a16efa6", vanilla = true },
    },
    [1478] = {
        title = { it = "La convocazione di Halgar", enHash = "872fe5e3", vanilla = true },
        text = { it = "Ah, $N! Ho appena saputo da Carendin Halgar che vorrebbe vederti per continuare il tuo addestramento.\n\nDovresti essere $Gfiero:fiera; di te $Gstesso:stessa;, $N. Non capita tutti i giorni che il maestro Halgar ritenga opportuno istruire di persona $Gun giovane stregone:una giovane strega;.\n\nLo troverai nel Magic Quarter dell'Undercity, vicino al Temple of the Damned.", enHash = "a4a17584", vanilla = true },
        objectives = { it = "Parla con Carendin Halgar, nell'Undercity.", enHash = "711074a2", vanilla = true },
        reward = { it = "Bene, vedo che Ageron ti ha trovato, $N. Non perdiamo tempo in chiacchiere e convenevoli e concentriamoci sul tuo addestramento. Hai ancora molto da imparare.", enHash = "80d92b0e", vanilla = true },
    },
    [1479] = {
        title = { it = "Il Bough of the Eternals", enHash = "fa2478a8", vanilla = true },
        text = { it = "Ho sentito storie su come gli elfi della notte tengano la loro banca in un albero, uno che sembra un orso! Troppo forte! Gli elfi della notte sono simpatici, con quella loro passione per la natura e tutto il resto, ma gli orsi sono proprio fantastici!\n\nMi porteresti a vedere l'albero-orso a Darnassus, per piacere? C'è una nave che ci porta lì vicino, e non dovrebbe volerci molto. Per piacere, per piacere, per piacere!", enHash = "bc3d75c3", vanilla = true },
        objectives = { it = "Porta l'orfano alla banca di Darnassus. La banca è scavata in un albero noto come Bough of the Eternals.", enHash = "d3009a6a", vanilla = true },
        progress = { it = "Siamo arrivati?", enHash = "5cf70a59", vanilla = true },
        reward = { it = "Wow, era ancora più bello di come me l'ero immaginato: il Bough of the Eternals! Non pensavo fosse così grande, e invece lo era! Hai visto anche l'uccello in cima?! Chissà come hanno fatto a dare quella forma ai rami!\n\nGrazie di avermi portato a Darnassus, $N. Sei $Gfantastico:fantastica;!", enHash = "6cb2d0da", vanilla = true },
    },
    [1480] = {
        title = { it = "Il corruttore", enHash = "33c06e8b", vanilla = true },
        text = { it = "La pelle strappata ha un odore di marcio ed è sorprendentemente flessibile per qualcosa che sembra secco e fragile.\n\nMentre la srotoli, vedi chiaramente su un lato dei segni rossi di una qualche lingua. In fondo alla pelle c'è un simbolo molto chiaro che immagini sia una specie di firma.\n\nForse Maurin potrebbe dirti qualcosa di più?", enHash = "ec6fe290", vanilla = true },
        objectives = { it = "Porta la Flayed Demon Skin a Maurin Bonesplitter, a Desolace.", enHash = "e6101d87", vanilla = true },
        progress = { it = "Quelli della Burning Blade cominciano a capire quanto siano davvero deboli. Le loro magie sono patetiche, la loro forza misera.\n\nIl loro unico potere viene da coloro che servono, non da una vera comprensione del potere e della conoscenza.", enHash = "0d8d80e7", vanilla = true },
        reward = { it = "Hmm, queste rune sono davvero una lingua, $N, una lingua antica. Somigliano vagamente alla lingua Eredun, ma le differenze sono enormi. Se non mi sbaglio, questo è una specie di contratto... Qui, sì, questo simbolo è la firma del demone: Lord Azrethoc.", enHash = "7f60db10", vanilla = true },
    },
    [1481] = {
        title = { it = "Il corruttore", enHash = "33c06e8b", vanilla = true },
        text = { it = "Credo di poter trovare questo signore dei demoni, con i reagenti giusti.\n\nSe è davvero potente come sospetto, mi serviranno oggetti presi da creature letali. Ma tu agisci in nome del Capoguerra, quindi di sicuro accetterai il mio compito.\n\nPer prima cosa dovrò spezzare le protezioni che ha contro la divinazione. Per questo mi servirà lo scalpo di un satiro, ma non di un satiro qualsiasi. Lo scalpo deve venire da un Hatefury Shadowstalker.\n\nCercali tra le antiche rovine nel nord-est di Desolace.", enHash = "ff485843", vanilla = true },
        objectives = { it = "Porta uno Shadowstalker Scalp a Maurin Bonesplitter, a Desolace.", enHash = "c10f39e3", vanilla = true },
        progress = { it = "Non portarmi uno scalpo sbagliato, $C. Usare i reagenti sbagliati potrebbe costarci la vita. Il signore dei demoni potrebbe avere su di sé incantesimi di riserva per uccidere chi tenta di spiarlo con la divinazione.\n\nIl destino mi ha già inflitto abbastanza dolore.", enHash = "8dd3a179", vanilla = true },
        reward = { it = "Gli shadowstalker non sono riusciti a ucciderti, $C. Notevole... davvero notevole.\n\nQuesto scalpo andrà benissimo per il mio incantesimo. Mentre eri via, ho potuto raccogliere alcuni degli altri reagenti necessari per l'incantesimo.\n\nCi sono quasi. Mi serve solo un catalizzatore per l'incantesimo: qualcosa che proietti un'immagine del signore dei demoni e del luogo in cui si trova.", enHash = "15901715", vanilla = true },
    },
    [1482] = {
        title = { it = "Il corruttore", enHash = "33c06e8b", vanilla = true },
        text = { it = "Un Oracle Crystal andrebbe benissimo. I naga li fabbricano perché li usino i loro oracoli.\n\nA nord-ovest di qui, lungo la costa, c'è una vasta barriera corallina che i naga hanno preso come dimora quando si trovano così vicini alla riva. Là troverai i loro oracoli. Gli Slitherblade sono letali e non accoglieranno di buon grado le tue intrusioni, quindi fa' attenzione e sbrigati.\n\nQuando tornerai, vedremo di trovare questo signore dei demoni, Azrethoc.", enHash = "9d95fcdd", vanilla = true },
        objectives = { it = "Porta un Oracle Crystal a Maurin Bonesplitter, a Desolace.", enHash = "7c8d49e8", vanilla = true },
        progress = { it = "Sono pronto per l'Oracle Crystal, $C. Trovare e distruggere questo Lord Azrethoc ci farebbe guadagnare parecchio favore presso il Capoguerra, a tutti e due. Faremmo bene a lavorare insieme, e a farlo in fretta, così da perseguire i nostri scopi e ingraziarci il Capoguerra.", enHash = "be5c243a", vanilla = true },
        reward = { it = "Un prezioso Oracle Crystal... perfetto... bellissimo. Davvero.\n\nCominceremo subito. Trovare questo signore dei demoni dev'essere la nostra prima preoccupazione, e ucciderlo richiede tutta la nostra attenzione.\n\nFai un passo indietro, $C, e vediamo che cos'è questo demone e dove si può trovare.", enHash = "698d30af", vanilla = true },
    },
    [1483] = {
        title = { it = "Ziz Fizziks", enHash = "99b7cd79", vanilla = true },
        text = { it = "La Venture Company ci ha rubato molte delle migliori teste goblin, ma ogni tanto capita l'occasione di rubarne indietro qualcuna.\n\nTempo fa la squadra della Venture Company nelle Stonetalon Mountains ha assunto Gerenzo Wrenchwhistle — uno gnomo! L'altro loro ingegnere, Ziz Fizziks, ci è rimasto talmente male che mi ha supplicato di trovargli un nuovo impiego nella Tinkers' Union. Gli ho affidato qualche incarico, ma potrebbe aver bisogno d'aiuto.\n\nMagari potresti andare a dargli un'occhiata per me? Sta al margine occidentale di Windshear Crag.", enHash = "8700ecc5", vanilla = true },
        objectives = { it = "Parla con Ziz Fizziks, a Windshear Crag.", enHash = "03c6a74a", vanilla = true },
        reward = { it = "Pensavo che i pezzi grossi della Venture Company fossero degli aguzzini, poi ho conosciuto Sputtervalve, il più crudele di tutti!\n\nAh! Anche se è sempre meglio che restare senza lavoro, immagino... O peggio, lavorare con quel Gerenzo. Se sei qui per aiutare, ho qualcosa da farti fare.", enHash = "044071e6", vanilla = true },
    },
    [1484] = {
        title = { it = "Il corruttore", enHash = "33c06e8b", vanilla = true },
        text = { it = "Questa creatura è molto più pericolosa di quanto avessi previsto. Di sicuro Takata dubita delle mie capacità di affrontare una creatura simile, e sarebbe un'offesa al suo onore non informarlo di quello che è appena successo.\n\nParla con lo spadaccino, digli che sei $Gdisposto:disposta; a uccidere il demone se lui te lo permette, ma non insistere troppo. È meglio se pensa che l'idea sia sua.", enHash = "a1e70522", vanilla = true },
        objectives = { it = "Parla con Takata Steelblade, a Desolace.", enHash = "05d09459", vanilla = true },
        reward = { it = "Ho visto quello che è appena successo con Maurin e il signore dei demoni. Quella creatura, anche solo come apparizione, sembra avere più potere del mio compagno stregone. Mi chiedo: sarà all'altezza di sconfiggere il mostro? Servirei meglio il Capoguerra se andassi io stesso, ma con le responsabilità che ho qui, disonorerei il mio clan se voltassi le spalle ai miei doveri per combattere questo male in nome del mio onore.", enHash = "8b8ce07a", vanilla = true },
    },
    [1485] = {
        title = { it = "I Vile Familiar", enHash = "254076da", vanilla = true },
        text = { it = "Gli stregoni che ci hanno preceduto si sono guadagnati la sfiducia dell'Orda, e anche se siamo tollerati, non siamo amati.\n\nQuesto però non ha avvicinato gli stregoni tra loro, perché molti scelgono di vivere appartati, dilettandosi con la magia da soli. Non cercherò di condurti su una strada o sull'altra, ma solo di aiutarti a crescere.\n\nPrima che ti insegni l'arte dell'evocazione, portami sei teste dei Vile Familiar dalla caverna a nord-est.", enHash = "942814f0", vanilla = true },
        objectives = { it = "Porta 6 Vile Familiar Head a Ruzan.", enHash = "d09e9d43", vanilla = true },
        progress = { it = "È importante che tu sappia controllare gli esseri che evochi con la tua magia. Sono così pochi quelli interessati a imparare le vie $Gdel:della; $C che non rischierei la tua vita insegnandoti qualcosa prima che tu sia $Gpronto:pronta;.", enHash = "d210c9e4", vanilla = true },
        reward = { it = "Durante il tuo addestramento da $C, imparerai a richiamare esseri di molti tipi. Alcuni potrebbero non sembrarlo, ma sono tutti strumenti utili.\n\nNon lasciarti ingannare dalle piccole dimensioni dell'Imp. Come avrai certamente notato, resta un avversario temibile.", enHash = "2ef21a2e", vanilla = true },
    },
    [1486] = {
        title = { it = "I Deviate Hide", enHash = "632037ef", vanilla = true },
        text = { it = "Mentre Naralex scendeva sempre più a fondo nel suo incubo, una strana stirpe di bestie è salita da sotto le Barrens dentro le Wailing Caverns.\n\nQueste creature deviate hanno proprietà strane, ultraterrene. Sono malvagie per natura, ma secondo me dalla loro esistenza qui in Kalimdor può venire qualcosa di buono. Credo che le loro pelli saranno particolarmente utili nella conciatura.\n\nSe te la senti, avventurati nelle grotte qui sotto e recupera qualche Deviate Hide.", enHash = "ebbda4ce", vanilla = true },
        objectives = { it = "Nalpak, nelle Wailing Caverns, vuole 20 Deviate Hide.", enHash = "43d4ebd8", vanilla = true },
        progress = { it = "Mi interessa molto esaminare le pelli delle creature deviate che hanno infestato queste grotte. Hai avuto fortuna a raccoglierne qualcuna, $C?", enHash = "bfefe72b", vanilla = true },
        reward = { it = "I tuoi sforzi nel raccogliere queste pelli non passeranno inosservati, $N.\n\nGrazie per la tua dedizione.", enHash = "e15c7869", vanilla = true },
    },
    [1487] = {
        title = { it = "Sterminio dei deviate", enHash = "b5836089", vanilla = true },
        text = { it = "Naralex aveva un fine nobile.\n\nIl nostro grande capo aspirava a entrare nell'Emerald Dream e ad aiutare queste terre dure a tornare la foresta rigogliosa che erano un tempo. Ma qualcosa è andato terribilmente storto.\n\nIl sogno di Naralex si è trasformato in un incubo e creature corrotte hanno cominciato ad abitare le caverne.\n\nMentre alcuni Disciples of Naralex cercano di svegliare il nostro maestro, io mi preoccupo di liberare queste grotte dalle bestie malvagie.\n\nAffronta le caverne, $N, e stermina la progenie dei deviate.", enHash = "54bc50e8", vanilla = true },
        objectives = { it = "Ebru, nelle Wailing Caverns, vuole che tu uccida 7 Deviate Ravager, 7 Deviate Viper, 7 Deviate Shambler e 7 Deviate Dreadfang.", enHash = "df5a705f", vanilla = true },
        progress = { it = "$N, noi Disciples of Naralex abbiamo bisogno del tuo aiuto. Il nostro numero si assottiglia, con il nostro maestro intrappolato nel suo incubo contorto. Non abbiamo le forze necessarie per affrontare le creature corrotte che ora infestano queste caverne.\n\nTi supplico, entra nelle grotte e fa' guerra alle creature deviate!", enHash = "e7b22d43", vanilla = true },
        reward = { it = "Da Disciple of Naralex, lodo il tuo coraggio, $N.\n\nIl tuo aiuto nel ripulire le caverne è il primo passo nella nostra lunga battaglia per vedere le Barrens risanate.\n\nGrazie, e che tu prosperi.", enHash = "b87e72af", vanilla = true },
    },
    [1488] = {
        title = { it = "Il corruttore", enHash = "33c06e8b", vanilla = true },
        text = { it = "Anche se non so nulla di questo Lord Azrethoc, sono d'accordo con Maurin: va fermato, soprattutto se sta cercando di ottenere influenza sulla Burning Blade per i suoi scopi.\n\nHai già dimostrato di voler aiutare il Capoguerra, e mi fiderei di te per radunare un gruppo e uccidere il signore dei demoni e il suo servo stregone.\n\nQuando sei $Gpronto:pronta;, va' dritto a sud, e torna da me quando la minaccia sarà eliminata.", enHash = "862cc884", vanilla = true },
        objectives = { it = "Uccidi Lord Azrethoc e Jugkar Grim'rod e torna da Takata Steelblade, a Desolace.", enHash = "a852f1aa", vanilla = true },
        progress = { it = "Gloria all'Orda, e morte ai nostri nemici, $N!\n\nI demoni di Desolace sono una minaccia più grande che mai. La mia speranza di tornare dal Capoguerra si affievolisce man mano che compaiono sempre più di quelle creature immonde.\n\nA volte vorrei che avessimo a che fare solo con i centauri.", enHash = "b6721630", vanilla = true },
        reward = { it = "Una vittoria possente per tutti noi, $N. Gioiamo del tuo successo. Ora confido che il nostro futuro qui non sia così cupo come pensavo un tempo.\n\nI demoni saranno uccisi, la Burning Blade fallirà nei suoi sforzi, e un giorno potremo avere di nuovo un posto da chiamare casa, al sicuro.", enHash = "c02a811a", vanilla = true },
    },
    [1489] = {
        title = { it = "Hamuul Runetotem", enHash = "a8d1115f", vanilla = true },
        text = { it = "I gusci che mi hai portato hanno una corruzione, una che non avevo mai visto prima. Sono certo che la causa sia l'acqua delle oasi, e sento la confusione che provocano in questa terra. È come se la terra sognasse e non riuscisse a svegliarsi.\n\nLe Wailing Caverns devono essere l'origine della corruzione. Ma prima di andarci, parla con Hamuul Runetotem, il druido anziano. Gli ho mandato notizia di quello che succede nelle Barrens. È saggio, e può darti consiglio.\n\nLo troverai a Thunder Bluff, sull'Elder Rise.", enHash = "c049d767", vanilla = true },
        objectives = { it = "Parla con Hamuul Runetotem.", enHash = "ac96cfab", vanilla = true },
        reward = { it = "Ti porgo il mio saluto, $N. Sei $Gil benvenuto:la benvenuta; qui, e ti consiglio di raccogliere tutte le tue forze. Perché l'incarico che ora ti mettiamo davanti... è terribile.", enHash = "d39a5443", vanilla = true },
    },
    [1490] = {
        title = { it = "Nara Wildmane", enHash = "86ef8c53", vanilla = true },
        text = { it = "Sono entrato nella terra dei sogni, e ho sognato di una setta di druidi che abita nelle Wailing Caverns. Ho visto che un tempo i loro fini erano nobili, ma hanno perso la strada. Ora sono servi della corruzione che filtra nelle Barrens.\n\nSono vecchio e le forze mi vengono meno. Non potevo restare a lungo in quel luogo di sogno e so poco altro dei druidi corrotti. Ma Nara è giovane e il suo spirito è fiero. Lei è rimasta nel sogno quando io sono fuggito.\n\nParla con Nara. È nella tenda, là in fondo.", enHash = "f6bcb3e1", vanilla = true },
        objectives = { it = "Parla con Nara Wildmane.", enHash = "157adf87", vanilla = true },
        reward = { it = "Sì, è vero. So dei druidi nelle Wailing Caverns. Ho visto le loro facce contorte e squamose. Conosco i loro crimini, e conosco i loro piani.\n\nDevi fermarli, $N.", enHash = "c8ec3fd0", vanilla = true },
    },
    [1491] = {
        title = { it = "Bevande dell'intelligenza", enHash = "d066e912", vanilla = true },
        text = { it = "Ok, i corni di raptor non hanno funzionato granché. Ma va bene — nessuno è diventato ricco al primo tentativo! E poi credo di aver trovato qualcosa che funzionerà ancora meglio nelle mie bevande dell'intelligenza!\n\nC'è una sostanza che si chiama Wailing Essence, e secondo me è la causa delle piante e degli animali strani delle Barrens. Procurami quella e la proverò nella mia bevanda!\n\nHo sentito che l'essenza si raccoglie nelle creature ectoplasmiche delle Wailing Caverns, a ovest. Caccia quelle creature e raccogli l'essenza.", enHash = "404596ce", vanilla = true },
        objectives = { it = "Porta 6 porzioni di Wailing Essence a Mebok Mizzyrix, a Ratchet.", enHash = "038f8b8b", vanilla = true },
        progress = { it = "Dov'è la mia Wailing Essence?", enHash = "865efc31", vanilla = true },
        reward = { it = "Ottimo, ce l'hai! Non vedo l'ora di provarla. Questa mi farà fare una fortuna, lo so e basta!\n\nGrazie, $N. Prendi questo, e quando sarò ricco te ne manderò dell'altro, promesso!", enHash = "f9d7812c", vanilla = true },
    },
    [1492] = {
        title = { it = "Wharfmaster Dizzywig", enHash = "264ca25b", vanilla = true },
        text = { it = "Devo mandare una cassa di pozioni, reagenti e altri oggetti ai miei soci nell'Old World. Ho poco tempo per portarla io stesso al molo di Ratchet, e l'ultima carovana è già partita.\n\nSe puoi, porta questa a Wharfmaster Dizzywig. Farà in modo che finisca sulla prossima nave per Blackwater Cove.", enHash = "175eb96c", vanilla = true },
        objectives = { it = "Porta la Secure Crate a Wharfmaster Dizzywig, a Ratchet.", enHash = "70688b87", vanilla = true },
        progress = { it = "Cerchi un passaggio sulla prossima nave, o hai qualcosa da spedirci?", enHash = "54e3afc2", vanilla = true },
        reward = { it = "Una cassa abbastanza piccola. Sì, dovrei riuscire a trovarle posto a bordo. La nave salpa con la prossima marea, spero sia abbastanza presto. Ottimo. Lascia solo che la registri.\n\nTutto sistemato! Buona giornata, $C.", enHash = "5d11401b", vanilla = true },
    },
    [1498] = {
        title = { it = "La via della difesa", enHash = "0c7fcbd2", vanilla = true },
        text = { it = "Per noi guerrieri, uno dei compiti più importanti è... la protezione. Siamo lo scudo dell'Orda, e teniamo al sicuro i nostri fratelli più deboli. Se vuoi unirti alle nostre file, devi dimostrarmi quanto vali.\n\nVa' a Thunder Ridge, in Durotar, dove vivono i Lightning Hide e i Thunder Lizard. Caccia quelle bestie! Dimostrami che sei più resistente di loro! Affronta i loro attacchi e portami un mucchio delle loro Singed Scale come prova.\n\nFallo, e allora ti insegnerò.", enHash = "62403f2f", vanilla = true },
        objectives = { it = "Porta 5 Singed Scale a Uzzek, al Far Watch Post, nelle Barrens.", enHash = "f49e0c28", vanilla = true },
        progress = { it = "Hai le scaglie, $N? Se non riesci a resistere agli attacchi dei Thunder Lizard, i miei insegnamenti non ti serviranno a niente.", enHash = "d5f846f8", vanilla = true },
        reward = { it = "Ah. Vedo che hai sconfitto i Thunder Lizard, e questo dimostra che sei resistente. Ora ti mostrerò come una pelle dura e movimenti accorti possano unirsi a formare un impenetrabile muro di difesa.\n\nImpara bene la lezione, $N. E tieniti $Gpronto:pronta; per i prossimi insegnamenti.", enHash = "d459c329", vanilla = true },
    },
    [1499] = {
        title = { it = "I Vile Familiar", enHash = "254076da", vanilla = true },
        text = { it = "Zureetha manda i novizi come te ad aiutare a sfoltire le creature nella caverna vicino a dove hai combattuto i Vile Familiar.\n\nCredo che ti farebbe bene fare esperienza aiutandola. Dille che hai contribuito a risolvere il problema degli Imp: probabilmente avrà una ricompensa per te.", enHash = "bf26de28", vanilla = true },
        objectives = { it = "Parla con Zureetha Fargaze.", enHash = "80972510", vanilla = true },
        reward = { it = "Hai fatto un buon lavoro, $N.\n\nAnche se i Vile Familiar erano solo animaletti al servizio dei poteri più oscuri della Burning Blade, il tuo successo contro di loro fa presagire imprese più grandi.", enHash = "4d215652", vanilla = true },
    },
    [1501] = {
        title = { it = "Creatura del vuoto", enHash = "de4975ab", vanilla = true },
        text = { it = "Sono rimasti così pochi stregoni... Rischiamo molto, ma i rischi sono giustificati. Devi raggiungere in fretta la piena maturità nelle tue capacità, se vuoi essere utile all'Orda e al Capoguerra.\n\nÈ ora che tu impari un nuovo incantesimo di evocazione.\n\nPrima devi recuperare la Tablet of Verga, rubata dagli stregoni della Burning Blade e ora custodita nel loro covo a Skull Rock, a est della città. Con la tavoletta, ti mostrerò le rune necessarie per evocare un Voidwalker.", enHash = "065015bc", vanilla = true },
        objectives = { it = "Recupera la Tablet of Verga per Gan'rul Bloodeye, a Orgrimmar.", enHash = "a8d1699a", vanilla = true },
        progress = { it = "Hai la Tablet of Verga, $N? Se no, non voglio parlarti finché non ce l'avrai.", enHash = "84f4388a", vanilla = true },
        reward = { it = "Bene. Spero che tu abbia inflitto qualche altra perdita alla Burning Blade quando sei $Gandato:andata; a recuperarla.\n\nSono stati una grande seccatura per il Capoguerra, e una grande piaga per tutti gli stregoni.", enHash = "e685c475", vanilla = true },
    },
    [1502] = {
        title = { it = "Thun'grim Firegaze", enHash = "d3ba42f2", vanilla = true },
        text = { it = "È fondamentale che l'arma di un guerriero sia di qualità. E se c'è un orco capace di forgiare armi di qualità, quell'orco è Thun'grim Firegaze. È un eremita che vive in cima alle colline a est del Crossroads.\n\nSe cerchi un'arma, $Gguerriero:guerriera;, allora dovresti cercare Thun'grim. Per trovarlo, raggiungi prima il Crossroads, a ovest, poi dirigiti a est tra le colline. Il suo accampamento è in alto, sulla cima di una collina.", enHash = "3cbe21ce", vanilla = true },
        objectives = { it = "Parla con Thun'grim Firegaze, nelle Barrens.", enHash = "917657cb", vanilla = true },
        reward = { it = "I miei occhi si sono seccati da tempo a forza di fissare la fiamma della forgia, ma certe cose riesco ancora a vederle. Vedo che vuoi qualcosa.\n\nE se hai trovato la strada fin qui, posso immaginare cosa desideri.", enHash = "29101717", vanilla = true },
    },
    [1503] = {
        title = { it = "Acciaio forgiato", enHash = "f31a2dc8", vanilla = true },
        text = { it = "Ti darò un'arma, $N, ma prima devi aiutarmi. I Razormane a nord-ovest sono entrati nel mio accampamento qualche notte fa. Non volevano affrontarmi in combattimento, ma sanno che ci vedo poco: alcuni mi hanno distratto con i loro grugniti mentre altri mi derubavano! Codardi!\n\nHanno preso un forziere di ferro, e dentro c'erano delle Forged Steel Bars. Se riesci a recuperarle, ti darò l'arma che cerchi.\n\nCerca la cassa di ferro negli accampamenti dei quilboar e torna con le Forged Steel Bars.", enHash = "a407694f", vanilla = true },
        objectives = { it = "Porta le Forged Steel Bars a Thun'grim Firegaze, nelle Barrens.", enHash = "b0d0afff", vanilla = true },
        progress = { it = "Hai le mie barre d'acciaio?", enHash = "90172618", vanilla = true },
        reward = { it = "Le hai trovate! E ci sono tutte, il che non mi sorprende. Non credevo che i Razormane sapessero cosa farsene di un acciaio pregiato come questo.\n\nGrazie, $N. Ecco la tua ricompensa. Che ti sia utile.", enHash = "2d996e6a", vanilla = true },
    },
    [1504] = {
        title = { it = "Il vincolo", enHash = "2a2909d6", vanilla = true },
        text = { it = "Ora osserva la Tablet of Verga, perché contiene i glifi che ti serviranno per l'evocazione. Portali al cerchio nella tenda di Neeru Fireblade, dall'altra parte della caverna. Lì potrai richiamare il Voidwalker.\n\nDevi sconfiggerlo con qualunque mezzo fisico e magico tu abbia a disposizione. Fatto questo, torna da me con le Glyphs of Summoning e ti mostrerò come vincolare la creatura alla tua volontà.", enHash = "ee4eb6e2", vanilla = true },
        objectives = { it = "Usando le Glyphs of Summoning, evoca e sottometti un Voidwalker, poi riporta le Glyphs of Summoning a Gan'rul Bloodeye, a Orgrimmar.", enHash = "4f672e1d", vanilla = true },
        progress = { it = "Il Voidwalker è una creatura potente. Ricordo quando ero io al tuo posto, $N. Negli anni il mio Voidwalker ha imparato a combattermi di meno, anche se sospetto che sia solo perché spera che io abbassi la guardia.\n\nRicordalo, $N.", enHash = "d61fcba3", vanilla = true },
        reward = { it = "Hai fatto bene, $N. Ti mostrerò come evocare un Voidwalker simile a quello che hai appena sconfitto.\n\nDevi sapere che abbiamo grandi aspettative su di te, e finora le hai rispettate.\n\nMa non montarti la testa, perché i compiti che ti aspettano faranno sembrare questo facile come svegliarsi al mattino.", enHash = "3159e486", vanilla = true },
    },
    [1505] = {
        title = { it = "Il veterano Uzzek", enHash = "2d13e13a", vanilla = true },
        text = { it = "L'Orda onora i suoi guerrieri perché la loro forza è indiscussa. Ma i guerrieri davvero grandi sono anche grandi allievi.\n\nCerca Uzzek. È un veterano di molte battaglie e ora insegna ai giovani guerrieri le vie del combattimento. Lo troverai a sud del Far Watch Post, la guarnigione orchesca al confine tra le Barrens e Durotar, a est.", enHash = "c4eb06ba", vanilla = true },
        objectives = { it = "Parla con Uzzek al Far Watch Post.", enHash = "05103038", vanilla = true },
        reward = { it = "Salve, giovane. Sei qui per un po' di addestramento, eh?", enHash = "bae35873", vanilla = true },
    },
    [1506] = {
        title = { it = "La convocazione di Gan'rul", enHash = "dc0e3714", vanilla = true },
        text = { it = "Ehi, tu. $N, giusto?\n\nSpero che tu non abbia troppi impegni, perché Gan'rul vuole vederti subito. Lo troverai con gli stregoni anziani nella Cleft of Shadow.\n\nA giudicare dai miei trascorsi con Gan'rul, questa convocazione è o un'ottima cosa o una pessima cosa.", enHash = "33c7e238", vanilla = true },
        objectives = { it = "Parla con Gan'rul Bloodeye, a Orgrimmar.", enHash = "1c1fe78a", vanilla = true },
        reward = { it = "Bene. Temevo che Ophek non riuscisse a raggiungerti.\n\nÈ ora che io porti avanti il tuo addestramento da $Gstregone:strega;. Qualunque faccenda tu abbia in corso dovrà aspettare.\n\nConfido che non ci saranno problemi?", enHash = "6d5103d0", vanilla = true },
    },
    [1507] = {
        title = { it = "Divoratrice di anime", enHash = "b530f7f3", vanilla = true },
        text = { it = "È giunto il momento che tu impari di più sulle magie di evocazione. Imparerai a evocare una Succubus, una creatura dai poteri mentali incredibili. Può ridurre al suo servizio chi ha una mente debole, ma non temere! Sono certo che sarai all'altezza della sfida.\n\nUna Succubus si può evocare solo attirandola con un oggetto che rappresenti una grande devozione e un grande amore. Lascio a te il compito di trovarlo.\n\nUn suggerimento? Parla con Cazul... Sembra che ci sia ben poco che l'antico stregone non sappia.", enHash = "a4e3a3be", vanilla = true },
        objectives = { it = "Parla con Cazul, nella Cleft of Shadow.", enHash = "202b7c2c", vanilla = true },
        reward = { it = "Mm... $N. Sei ancora agli inizi del tuo cammino, ma percepisco in te la possibilità della grandezza.\n\nSei $Gnato:nata; con dei doni, $N. Fa' in modo che non vadano sprecati.", enHash = "e5cbdbeb", vanilla = true },
    },
    [1508] = {
        title = { it = "Il cieco Cazul", enHash = "678636e8", vanilla = true },
        text = { it = "Mm... Ma certo, non è per questo che sei $Gvenuto:venuta; a parlarmi.\n\nSe Gan'rul ti ha mandato da me, dev'essere che devi evocare una Succubus e ti serve un oggetto per attirarla.\n\nMm... Se ti fidi a farti guidare da un cieco, $N, allora ascolta. Sulle alture di Orgrimmar, a ovest della torre dei wind rider, vive Zankaja. Aspetta il ritorno del suo compagno.\n\nVa' da lei.", enHash = "3177cc72", vanilla = true },
        objectives = { it = "Parla con Zankaja, a Orgrimmar.", enHash = "9a5160e5", vanilla = true },
        reward = { it = "Porti notizie di Dogran? Sarebbe dovuto tornare giorni fa, e non ho saputo niente...", enHash = "4412b754", vanilla = true },
    },
    [1509] = {
        title = { it = "Notizie di Dogran", enHash = "219946bf", vanilla = true },
        text = { it = "Il mio compagno, Dogran, è stato mandato da poco in servizio al Crossroads. Era una promozione, e ne andava molto fiero.\n\nIo ero triste, naturalmente, ma non gliel'ho fatto capire. E anche preoccupata. Le Barrens sono un posto più pericoloso di Orgrimmar, e temevo il peggio.\n\nOra è passata una settimana da quando sarebbe dovuto tornare, e non ho ricevuto sue notizie...\n\nForse potresti andare al Crossroads a vedere se hanno notizie? Lavorava con Gazrog, che dovrebbe essere ancora di stanza lì.", enHash = "48bc52ed", vanilla = true },
        objectives = { it = "Parla con Gazrog, al Crossroads.", enHash = "5faebe89", vanilla = true },
        reward = { it = "Zankaja? È la compagna di Dogran, giusto?\n\nSì, ho avuto sue notizie, ma non sono il genere di notizie da far arrivare a lei...\n\nNo, non è morto. Ma è ferito ed è prigioniero dei quilboar.", enHash = "e323c315", vanilla = true },
    },
    [1510] = {
        title = { it = "Notizie di Dogran", enHash = "219946bf", vanilla = true },
        text = { it = "Era di stanza a Camp Taurajo, dove stiamo cercando di sbarazzarci dei quilboar. Ha guidato alcuni grunt in uno dei loro accampamenti, dove è stato ferito gravemente. Gli altri sono riusciti a tornare e hanno cercato di salvarlo. Era messo male, le ferite si erano infettate, quindi avevano paura di spostarlo senza prima medicarlo.\n\nHanno mandato un messaggio qui, chiedendo una pozione curativa ai troll di Malaka'jin, ai piedi delle Stonetalon Mountains. Abbiamo mandato qualcuno a prenderla, ma non è ancora tornato.", enHash = "6b7d349e", vanilla = true },
        objectives = { it = "Parla con Ken'zigla, a Malaka'jin.", enHash = "9c842add", vanilla = true },
        reward = { it = "$GUn altro orco:Un'altra orchessa;, eh? Spero che tu non sia qui per l'altro. Non ce l'ha fatta. Quei goblin l'hanno sistemato per bene.\n\nHa detto che gli serviva una pozione curativa, e poco altro.", enHash = "01345e9a", vanilla = true },
    },
    [1511] = {
        title = { it = "Ken'zigla's Draught", enHash = "e0edadd7", vanilla = true },
        text = { it = "Immaginavo che sarebbe venuto qualcun altro a prendere la pozione, così l'ho preparata comunque.\n\nEcco qua, $N. Mi raccomando, dagliene solo metà! Gli darà abbastanza forza per muoversi senza dissanguarsi. Aspetta una notte, poi dagli l'altra metà.\n\nComunque, dovrai portarla a Logmar, a Camp Taurajo. Da quello che mi ha detto il primo, lui dovrebbe sapere dove si trova questo Dogran.", enHash = "77bda1d5", vanilla = true },
        objectives = { it = "Porta Ken'zigla's Draught a Grunt Logmar, a Camp Taurajo.", enHash = "978b79cc", vanilla = true },
        progress = { it = "Sì, che c'è?", enHash = "87528bdf", vanilla = true },
        reward = { it = "Beh, era ora! Dogran sta morendo là fuori, in attesa di questa.\n\nDobbiamo fargliela avere subito, ma la maggior parte dei grunt di stanza qui è fuori in missione per procurarsi viveri.", enHash = "a852e7e5", vanilla = true },
    },
    [1512] = {
        title = { it = "Il dono dell'amore", enHash = "e4f903f2", vanilla = true },
        text = { it = "Zankaja è giovane e bella. Legata a un invalido... Non le permetterò di subire questa ingiustizia.\n\nLasciami, $N. E grazie. Potrò porre fine alla mia vita in una battaglia gloriosa, invece che come un guscio vuoto.\n\nE ti prego, non dire niente di tutto questo alla mia compagna... Non voglio che si senta in colpa.", enHash = "fa9052fb", vanilla = true },
        objectives = { it = "Porta il Dirt-caked Pendant a Gan'rul Bloodeye, a Orgrimmar.", enHash = "adb35de2", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata;. Sei $Gpronto:pronta; ad affrontare una Succubus?", enHash = "67020c8e", vanilla = true },
        reward = { it = "Se mi dici che basterà, allora mi fido di te, $N. Lascia però che lo pulisca... Immacolato e splendente, potrebbe essere ancora più allettante per una Succubus.", enHash = "6d44b90e", vanilla = true },
    },
    [1513] = {
        title = { it = "Il vincolo", enHash = "2a2909d6", vanilla = true },
        text = { it = "Porta questo al cerchio di evocazione nella tenda di Neeru, $N. Richiama un'immonda Succubus, poi mostrale la tua maestria. Credo nella forza della tua magia. Come sempre, però, sta' in guardia, perché l'orgoglio e la presunzione hanno perduto molti stregoni promettenti.\n\nQuando l'avrai sconfitta, riportami il ciondolo, così che io possa dare la notizia a Zankaja.", enHash = "52e895cd", vanilla = true },
        objectives = { it = "Usando Dogran's Pendant, evoca e sottometti una Succubus, poi riporta Dogran's Pendant a Gan'rul Bloodeye, a Orgrimmar.", enHash = "6154569a", vanilla = true },
        progress = { it = "Quando guardo una Succubus, il mio cuore prende il volo... Ma allo stesso tempo, sento quasi la mia anima che si ritira, come la marea.\n\nSta' in guardia, $Gamico mio:amica mia;.", enHash = "6e44fa07", vanilla = true },
        reward = { it = "Ce l'hai fatta! Non mi aspettavo niente di meno $Gdal mio allievo migliore:dalla mia allieva migliore;.\n\nHai dimostrato il tuo valore, e ti mostrerò volentieri il metodo per evocare la Succubus che hai sottomesso. Ora va', hai molto da imparare, e la prossima volta che ti vedrò mi aspetto che tu abbia raggiunto la vera padronanza della tua Succubus.\n\nLascia il dolore di Dogran e Zankaja a quelli tra noi che hanno più anni sulle spalle, ma ricordalo, e tienilo come protezione contro le lusinghe del potere oscuro che hai imparato a evocare oggi.", enHash = "9b52f29a", vanilla = true },
    },
    [1515] = {
        title = { it = "La prigionia di Dogran", enHash = "d4cde1ae", vanilla = true },
        text = { it = "Sei $Garrivato:arrivata; fin qui, quindi se vuoi andare fino in fondo, non ti fermerò. Però non posso darti altri uomini: sarai $Gda solo:da sola;.\n\nDogran è tenuto prigioniero in un accampamento dei quilboar a nord di qui. Cerca un gruppo di due capanne. Sarà sorvegliato a vista... sempre che non l'abbiano già ucciso, o che non sia morto per le ferite.\n\nBuona fortuna.", enHash = "2c5543b3", vanilla = true },
        objectives = { it = "Porta Ken'zigla's Draught a Dogran, nelle Barrens.", enHash = "df7d391e", vanilla = true },
        progress = { it = "Urrrghhhh...", enHash = "a1b8a2c4", vanilla = true },
        reward = { it = "Che intruglio disgustoso...\n\nOra sento la forza dentro di me, abbastanza per trascinarmi via... Ma la gamba, l'avrò persa per il resto della mia vita. E anche il braccio.", enHash = "5d909643", vanilla = true },
    },
    [1516] = {
        title = { it = "Il richiamo della terra", enHash = "e9b66c43", vanilla = true },
        text = { it = "È giunto il momento, giovane $C. Sei $Gdiventato:diventata; forte e il tuo spirito resiste come la terra. Seguire la via dello sciamano è segno che hai saggezza, prima ancora di aver dimostrato il tuo valore.\n\nL'elemento della terra guiderà il tuo destino, e diventerà parte di te se sei $Gpronto:pronta;. Ma devi presentarti davanti alla terra stessa. Se sei $Gpronto:pronta;, vedrai cose che solo gli sciamani conoscono.\n\nCerca i Felstalker a nord e prendi due dei loro zoccoli. Poi torna da me, e parleremo ancora del tuo futuro.", enHash = "7cc20311", vanilla = true },
        objectives = { it = "Porta 2 Felstalker Hoof a Canaga Earthcaller, nella Valley of Trials.", enHash = "36da7ef9", vanilla = true },
        progress = { it = "La pazienza è la più grande virtù della terra. La terra è testimone del ciclo di tutte le cose: le montagne che diventano deserti; i fiumi che diventano canyon. La terra è il più ostinato e il più saggio di tutti gli elementi, e non tollera l'impazienza.\n\nLa terra ti chiama ora perché si avvicina un tempo di conflitto. Quando tornerai da me $Gvittorioso:vittoriosa;, sarai molto più $Gvicino:vicina; a raggiungere la tua pienezza.\n\nGli altri invidieranno la tua saggezza e ti odieranno per la loro ignoranza.", enHash = "35bc1d38", vanilla = true },
        reward = { it = "Eccellente. Il tuo successo dimostra che sei $Gpreparato:preparata;.\n\nDi tutti gli elementi, la terra rappresenta le fondamenta di ogni cosa. È la tua forza, la tua resistenza e la tua pazienza. La terra ti proteggerà, ma solo se le si mostra il dovuto rispetto. Come gli altri elementi, anche la terra può essere volubile. La terra è la base della vita, e osservandone le leggi otterrai una saggezza più grande. Non dimenticare mai i segreti che la terra condivide con te.\n\nOra preparerò una sapta per te, e accettandola capirai qual è la tua strada.", enHash = "1c68b2d7", vanilla = true },
    },
    [1517] = {
        title = { it = "Il richiamo della terra", enHash = "e9b66c43", vanilla = true },
        text = { it = "La sapta è una bevanda creata per legare i nostri spiriti agli elementi. Intrisa di magia, la pozione permette a chi ha una volontà forte di vedere gli elementi come nessun altro può. Il tuo spirito sarà legato all'elemento per cui la sapta è stata creata, e solo una ristretta cerchia di sciamani ne conosce la ricetta.\n\nLa sapta si beve sempre in un luogo sacro, e mai altrove — ricordalo.\n\nCerca la Spirit Rock, a sud-ovest di qui — si trova alla fine dell'Hidden Path. Bevi lì la tua sapta, e... be', vedrai.", enHash = "1623639b", vanilla = true },
        objectives = { it = "Trova la Spirit Rock e bevi l'Earth Sapta.", enHash = "ec9db8c8", vanilla = true },
        reward = { it = "Ah... $N... lieta è la terra di averti qui.\n\nOra che siamo uniti nel corpo e nello spirito, andrai avanti sapendo che le montagne sono la tua forza; le pianure, la tua pazienza; e il mondo stesso la tua essenza.\n\nPresentarti umilmente davanti alla terra è tutto ciò che ti si chiede per superare questo rito. Ma gli altri elementi non sono altrettanto tranquilli. Possono essere caotici e spesso violenti, ma tale è la natura degli elementi. Nature doppie che si oppongono l'una all'altra: devi imparare a conoscerle a fondo.", enHash = "104d02d8", vanilla = true },
    },
    [1518] = {
        title = { it = "Il richiamo della terra", enHash = "e9b66c43", vanilla = true },
        text = { it = "Prendi da me questo Rough Quartz e portalo a Canaga Earthcaller come prova del nostro incontro. Creerà un totem per te, e questo sassolino ne sarà il cuore. Per quanto possa sembrare piccolo, scoprirai che le dimensioni non contano, e che anche le cose più piccole possono sopravvivere a molte altre.\n\nSii paziente, $N. Resta forte. E cerca la saggezza. Questo è ciò che la terra ti chiede. Alla fine diventerai una cosa sola con la terra — rispettala, come lei rispetterà te.", enHash = "4f7d9341", vanilla = true },
        objectives = { it = "Porta il Rough Quartz a Canaga Earthcaller, nella Valley of Trials.", enHash = "588f747b", vanilla = true },
        progress = { it = "Voglio essere il primo a darti il benvenuto, a pieno titolo, sulla prima delle quattro vie che guideranno per sempre il tuo destino.\n\nSe hai la pietra che ti ha dato la terra, ti darò il totem che ti ha promesso.\n\nAltrimenti, vattene finché non avrai trovato la tua strada.", enHash = "0ca4b9ab", vanilla = true },
        reward = { it = "Eccellente!\n\nIl totem che creerò per te è più di un simbolo del tuo rango di $C — ha anche poteri che vanno oltre. Il totem serve, tra l'altro, a concentrare gli incantesimi. Quegli incantesimi sono legati alla terra, e man mano che la tua saggezza crescerà, ti saranno accessibili sempre più poteri della terra.\n\nGli istruttori sapranno quando sarai $Gpronto:pronta; per conoscenze più grandi.\n\nMa per ora prendi questo Earth Totem, e una pergamena che ti insegnerà la tua prima abilità.", enHash = "1d1db29b", vanilla = true },
    },
    [1519] = {
        title = { it = "Il richiamo della terra", enHash = "e9b66c43", vanilla = true },
        text = { it = "È giunto il momento, giovane $C. Il tuo corpo matura e si fa forte, e il tuo spirito resiste come la terra. Lo vedo dentro di te — hai già saggezza.\n\nLa terra guida il nostro popolo, e ci parla, come a suo tempo parlerà a te. Ma devi essere $Gmesso:messa; alla prova. Se sei $Gpronto:pronta;, vedrai cose che solo la nostra gente conosce.\n\nCerca gli sciamani Bristleback nel loro burrone a est, e prendi loro un unguento che usano nei loro rituali. Torna da me solo quando ne avrai abbastanza per la tua pozione.", enHash = "8afdc681", vanilla = true },
        objectives = { it = "Porta 2 dosi di Ritual Salve a Seer Ravenfeather, a Camp Narache.", enHash = "3c40c35d", vanilla = true },
        progress = { it = "La terra è paziente, e ti aspetterà finché non sarai $Gpronto:pronta;, perché sa che col tempo tutte le cose si consumano e rinascono. È il ciclo delle cose. Le montagne diventano deserti. I fiumi diventano canyon. La terra è il più ostinato e il più saggio di tutti gli elementi.\n\nDevi imparare la pazienza e la resistenza sopra ogni cosa. La terra ora ti chiama perché sente che sei $Gpronto:pronta;. Se ci riuscirai, considerala la tua rinascita. Dopo, non potrai mai più tornare all'ignoranza.", enHash = "77cfc926", vanilla = true },
        reward = { it = "Bene, $N. Il tuo ritorno significa che sei davvero $Gpronto:pronta; per il passo successivo.\n\nDi tutti gli elementi, la terra rappresenta le fondamenta di ogni cosa. È la tua forza, la tua resistenza e la tua pazienza. La Madre Terra ti proteggerà, ma solo se le mostrerai il dovuto rispetto. Lei è la base della vita, e osservandone le leggi otterrai una saggezza più grande. Non dimenticare mai i segreti che condivide con te.\n\nOra preparerò la tua sapta, e accettandola vedrai aprirsi davanti a te una nuova strada.", enHash = "6cf42a3a", vanilla = true },
    },
    [1520] = {
        title = { it = "Il richiamo della terra", enHash = "e9b66c43", vanilla = true },
        text = { it = "La sapta è una bevanda creata per legare i nostri spiriti agli elementi. Intrisa di magia, la pozione permette a chi ha la mente aperta di vedere gli elementi come nessuno li ha mai visti. Il tuo spirito sarà legato per sempre all'elemento per cui la sapta è stata creata, e solo una ristretta cerchia della nostra gente conosce i segreti della sua preparazione.\n\nLa sapta si beve sempre in un luogo sacro, e mai altrove.\n\nCerca il santuario sciamanico a est di qui e bevi la sapta.", enHash = "1d8d37c4", vanilla = true },
        objectives = { it = "Trova la Kodo Rock e bevi l'Earth Sapta.", enHash = "4dbdeb86", vanilla = true },
        reward = { it = "Ah... $N... lieta è la terra di averti qui.\n\nOra che siamo uniti nel corpo e nello spirito, andrai avanti sapendo che le montagne sono la tua forza; le pianure, la tua pazienza; e il mondo stesso la tua essenza.\n\nPresentarti umilmente davanti alla terra è tutto ciò che ti si chiede per superare questo rito. Ma gli altri elementi non sono altrettanto tranquilli. Possono essere caotici e spesso violenti, ma tale è la natura degli elementi. Nature doppie che si oppongono l'una all'altra: devi imparare a conoscerle a fondo.", enHash = "104d02d8", vanilla = true },
    },
    [1521] = {
        title = { it = "Il richiamo della terra", enHash = "e9b66c43", vanilla = true },
        text = { it = "Prendi da me questo Rough Quartz e portalo a Seer Ravenfeather come prova del nostro incontro. Creerà un totem per te, e questo sassolino ne sarà il cuore. Per quanto possa sembrare piccolo, scoprirai che le dimensioni non contano, e che anche le cose più piccole possono sopravvivere alle montagne.\n\nSii paziente, $N. Resta forte. E cerca la saggezza. Questo è ciò che la terra ti chiede. Alla fine diventerai una cosa sola con la terra — rispettala, come lei rispetterà te.", enHash = "890af7d4", vanilla = true },
        objectives = { it = "Porta il Rough Quartz a Seer Ravenfeather, a Camp Narache.", enHash = "83d59024", vanilla = true },
        progress = { it = "Salve, $N. Non torneresti da me se non avessi portato a termine il tuo compito. Lascia che sia la prima a darti il benvenuto, a pieno titolo, sulla prima delle quattro vie che governeranno per sempre i tuoi viaggi.\n\nSe hai la pietra che ti ha dato la terra, ti darò il totem che ti ha promesso. Altrimenti, mi fai pena. Quando ci si dedica completamente agli elementi, c'è molto di cui andare fieri.", enHash = "21a5807e", vanilla = true },
        reward = { it = "Splendido.\n\nIl totem che creerò per te è più di un simbolo — ha anche poteri che vanno oltre. Il totem serve, tra l'altro, a concentrare gli incantesimi. Quegli incantesimi sono legati alla terra, e man mano che la tua saggezza crescerà, ti saranno accessibili sempre più poteri della terra. Gli istruttori che troverai in tutta Kalimdor sapranno quando sarai $Gpronto:pronta; per conoscenze più grandi, e te lo diranno quando andrai da loro.\n\nMa per ora prendi questo Earth Totem...", enHash = "6cae9f87", vanilla = true },
    },
    [1522] = {
        title = { it = "Il richiamo del fuoco", enHash = "9c2fbf1d", vanilla = true },
        text = { it = "Il fuoco sia con te, $Gamico:amica;. Vedo che sei già forte nelle vie della terra, e secondo me sei $Gpronto:pronta; a parlare con Kranal.\n\nKranal vive a nord del Crossroads, nelle Barrens. È forte nelle vie degli elementi e può insegnarti le vie del fuoco... se pensi di essere $Gpronto:pronta;.\n\nÈ facile da trovare, basta non andare troppo lontano — se vai troppo lontano, ti ritrovi nelle terre degli elfi.", enHash = "42fffc13", vanilla = true },
        objectives = { it = "Trova Kranal Fiss, nelle Barrens.", enHash = "8aab5a8a", vanilla = true },
        reward = { it = "Hmmm, ti ha mandato Searn, vero?\n\nBe', di Searn ci si è sempre potuti fidare, quindi vuol dire che sei $Gpronto:pronta; a prendere la prossima sapta — la sapta del fuoco.\n\nLo vedo già nei tuoi occhi: l'ardore, il desiderio. Hai assaggiato il potere, e ora sei $Gpronto:pronta; per averne di più. Pazienza, $N. Ricorda ciò che ti ha insegnato la terra. Il potere e la distruzione verranno facilmente, ma devi comunque sapere quando trattenere la mano.", enHash = "a409f7bb", vanilla = true },
    },
    [1523] = {
        title = { it = "Il richiamo del fuoco", enHash = "9c2fbf1d", vanilla = true },
        text = { it = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai dimostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la distruzione... e il caos. Comprendere l'elemento del fuoco è alla tua portata, se sei $Gdisposto:disposta; a pagarne il prezzo.\n\nCerca Kranal Fiss nelle Barrens. Vive in una piccola dimora a nord del Crossroads, ma fai attenzione: se arrivi alle terre degli elfi della notte, sei $Gandato:andata; troppo lontano.", enHash = "768b7404", vanilla = true },
        objectives = { it = "Trova Kranal Fiss, nelle Barrens.", enHash = "8aab5a8a", vanilla = true },
        reward = { it = "Hmmm, ti ha mandato Narm, vero?\n\nBe', di Narm ci si è sempre potuti fidare, quindi vuol dire che sei $Gpronto:pronta; a prendere la prossima sapta — la sapta del fuoco.\n\nLo vedo già nei tuoi occhi: l'ardore, il desiderio. Hai assaggiato il potere, e ora sei $Gpronto:pronta; per averne di più. Pazienza, $N. Ricorda ciò che ti ha insegnato la terra. Il potere e la distruzione verranno facilmente, ma devi comunque sapere quando trattenere la mano.", enHash = "766eec79", vanilla = true },
    },
    [1524] = {
        title = { it = "Il richiamo del fuoco", enHash = "9c2fbf1d", vanilla = true },
        text = { it = "Sei abbastanza potente per impugnare il Fire Totem, ma questo non significa che tu sia $Gpronto:pronta;.\n\nLungo il Southfury River, a Durotar, prima del Great Sea, c'è un sentiero nascosto che porta a una delle vette più alte di queste terre. Trova la strada per la cima e troverai uno dei nostri santuari sacri, custodito da Telf Joolam — lo Shrine of the Dormant Flame.\n\nPortagli questa torcia — è il segno che stai tentando di domare il fuoco. Riportamela dopo averla accesa al braciere del santuario, e farò in modo che tu riceva il Fire Totem.", enHash = "a964d7d2", vanilla = true },
        objectives = { it = "Porta la Torch of the Dormant Flame a Telf Joolam, a Durotar.", enHash = "ea32c5b3", vanilla = true },
        progress = { it = "Salve, $N. Sei $Garrivato:arrivata; allo Shrine of the Dormant Flame. Solo chi è abbastanza esperto nelle arti sciamaniche arriverà mai a conoscere i segreti di questo luogo e il potere che custodisce. Mi dispiace che tu abbia fatto tutta questa strada per essere $Grespinto:respinta; proprio adesso — dopotutto la salita fin quassù è tutt'altro che sicura — ma sono il custode del santuario, e non posso permettere a chiunque di aggirarsi da queste parti.", enHash = "5aeece59", vanilla = true },
        reward = { it = "Ah, errore mio, $N. Ti chiedo scusa. Non mi ero accorto che avessi con te la torcia. Sono lieto di fare la tua conoscenza.\n\nMolti avventurieri arrivano fin qui in cerca di tesori perduti o attratti dalla promessa di creature mistiche da uccidere, solo per essere respinti da un santuario che sembra vuoto. Ma noi conosciamo la verità, non è vero, $N?\n\nQuesto santuario custodisce un segreto più grande, nascosto ai membri comuni dell'Orda. Per noi è sacro.", enHash = "c915da67", vanilla = true },
    },
    [1525] = {
        title = { it = "Il richiamo del fuoco", enHash = "9c2fbf1d", vanilla = true },
        text = { it = "Ma non sei $Gvenuto:venuta; qui per una lezione di storia, vero? Sei $Gvenuto:venuta; per l'Eternal Flame e per il Fire Totem.\n\nIl primo passo è creare una sapta e legarti alla fiamma.\n\nPosso creare la sapta del fuoco per te, se mi porti due oggetti. Il primo è il Fire Tar, un oggetto comune che di solito portano con sé gli incantatori Razormane nelle Barrens orientali.\n\nIl secondo sarà più pericoloso da procurare: una Reagent Pouch presa a uno dei cultisti della Burning Blade. Li trovi in una grotta sopra i burroni a nord-est di Razor Hill.", enHash = "06999bf6", vanilla = true },
        objectives = { it = "Porta 1 Fire Tar e 1 Reagent Pouch a Telf Joolam, a Durotar.", enHash = "1816e263", vanilla = true },
        progress = { it = "Ho abbastanza ingredienti per una sapta del fuoco, se riesci a trovare la Reagent Pouch e un po' di Fire Tar. I fanatici della Burning Blade tengono in quelle sacche i componenti adatti per la maggior parte dei loro incantesimi, e di solito hanno abbastanza di quello che mi serve, così non dovremo cercare nient'altro molto più lontano.\n\nLe sapta si preparano sempre con ingredienti strettamente legati ai rispettivi elementi. Grazie al legame degli stregoni con il fuoco, il nostro lavoro è più facile.", enHash = "fa3d464d", vanilla = true },
        reward = { it = "Andranno benissimo, $N.\n\nIl fuoco è più che caos e distruzione — faresti bene a ricordarlo. Riguarda anche la vita, e la creazione. Tutte le cose sono legate tra loro in questo modo. Le forze si oppongono l'una all'altra, ma allo stesso tempo l'una non può esistere senza l'altra. Si spengono a vicenda, ma si danno anche un senso a vicenda. Ricordalo sempre.\n\nUsare diversi tipi di magia insieme dimostrerà non solo una vera abilità, ma anche una grande saggezza.", enHash = "eecd356b", vanilla = true },
    },
    [1526] = {
        title = { it = "Il richiamo del fuoco", enHash = "9c2fbf1d", vanilla = true },
        text = { it = "La sapta del fuoco è pronta. È giunto il momento di affrontare la fiamma. Usa la sapta al santuario e sali in cima alla montagna per affrontare la manifestazione che si trova lassù. Non attaccherà finché non sarai $Gpronto:pronta;, ma si renderà conto che riesci a vederla.\n\nAbbattila in fretta, $N, perché più tempo impiegherai a ucciderla, più diventerà potente. Una volta sconfitta, metti le sue braci ardenti nel braciere e accendi la torcia.", enHash = "80c953c7", vanilla = true },
        objectives = { it = "Sconfiggi la Minor Manifestation of Fire e metti la Glowing Ember nel braciere in cima allo Shrine of Eternal Flame.", enHash = "8b6c9b8f", vanilla = true },
        progress = { it = "Il braciere è alto circa un terzo di te, e sembra normale, a parte le iscrizioni lungo i suoi lisci montanti di metallo. Il metallo non mostra segni di usura dovuti alle intemperie, e la coppa posta in cima è fresca al tatto.", enHash = "c4f1cff5", vanilla = true },
        reward = { it = "Una fiamma bianca, rovente, si accende nella coppa quando ci metti dentro la brace. Senti gli effetti magici della sapta scorrerti nel corpo, e il fuoco danza a ritmo davanti a te.\n\nInfili la punta della torcia nel bacile, e prende subito fuoco.", enHash = "59e2fbf4", vanilla = true },
    },
    [1527] = {
        title = { it = "Il richiamo del fuoco", enHash = "9c2fbf1d", vanilla = true },
        text = { it = "Con la torcia ben stretta in mano, ti allontani dal braciere e il tuo sguardo spazia su Durotar. Senti un fremito agitarti lo spirito, mentre il vento si alza e costringe la fiamma a una danza violenta.\n\nTi incammini lungo il sentiero che riporta alle Barrens, in cerca di Kranal Fiss.", enHash = "950e54fd", vanilla = true },
        objectives = { it = "Porta la Torch of Eternal Flame a Kranal Fiss, nelle Barrens.", enHash = "11972324", vanilla = true },
        progress = { it = "Sì, $N? Cos'hai lì?", enHash = "b47e80f3", vanilla = true },
        reward = { it = "Il tuo spirito arde più luminoso di qualunque torcia io abbia mai visto, $N, e per questo dovresti andarne $Gfiero:fiera;.\n\nSe continuerai su questa strada, gli elementi saranno ai tuoi ordini, e i nostri fratelli si rivolgeranno a te per avere guida e saggezza. Lascia che sia il primo a congratularmi con te e a consegnarti il tuo nuovo totem.", enHash = "03076188", vanilla = true },
    },
    [1528] = {
        title = { it = "Il richiamo dell'acqua", enHash = "eab41910", vanilla = true },
        text = { it = "C'è acqua nel tuo futuro, $Gamico:amica;. Vedo che sei già forte nelle vie del fuoco, e secondo me sei $Gpronto:pronta; a parlare con Islen.\n\nIslen vive lungo la costa delle Barrens. Se vai a sud lungo il Southfury River, non puoi sbagliare — cerca il grosso squalo! È forte nelle vie degli elementi e può insegnarti le vie dell'acqua... se pensi di essere $Gpronto:pronta;.\n\nÈ facile da trovare, basta non andare troppo a sud — sta appena oltre Ratchet.", enHash = "ce61319a", vanilla = true },
        objectives = { it = "Trova Islen Waterseer, nelle Barrens.", enHash = "6d0a2807", vanilla = true },
        reward = { it = "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già riscaldato dal fuoco — direi che è ora che tu conosca la purezza dell'acqua.\n\nLa tua strada ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più avanti. Ma il primo passo spetta a te.", enHash = "b02d93ed", vanilla = true },
    },
    [1529] = {
        title = { it = "Il richiamo dell'acqua", enHash = "eab41910", vanilla = true },
        text = { it = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai dimostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.\n\nCerca Islen Waterseer nelle Barrens. Si trova lungo la costa orientale, a sud del Southfury River e di Ratchet. La troverai lì, alla sua capanna da pesca. Buona fortuna, $N.", enHash = "ad11a582", vanilla = true },
        objectives = { it = "Trova Islen Waterseer, nelle Barrens.", enHash = "6d0a2807", vanilla = true },
        reward = { it = "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già riscaldato dal fuoco — direi che è ora che tu conosca la purezza dell'acqua.\n\nLa tua strada ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più avanti. Ma il primo passo spetta a te.", enHash = "b02d93ed", vanilla = true },
    },
    [1530] = {
        title = { it = "Il richiamo dell'acqua", enHash = "eab41910", vanilla = true },
        text = { it = "Se c'è una lezione che devi imparare sull'acqua, è questa: l'acqua significa rinascita.\n\nIl suo potere scorre, erode e purifica ogni genere di cosa. Scoprirai che la sua capacità di guarire e di ristorare non ha eguali, ma solo quando è pura.\n\nQuando capirai che l'acqua, se inquinata, può devastare tutto ciò che tocca, comprenderai quanto sia vitale questa risorsa.\n\nSe vuoi la sapta dell'acqua, trova Brine nel profondo delle Barrens del sud. La sua casa è continuamente tormentata dai quilboar della zona.", enHash = "2b64092a", vanilla = true },
        objectives = { it = "Trova Brine, nelle Barrens del sud.", enHash = "ca135f0b", vanilla = true },
        reward = { it = "Sì?\n\nMmm. Ho la sensazione di sapere cosa stai per chiedermi: cosa spinge qualcuno a vivere quaggiù, nella parte più remota delle Barrens, con la minaccia dei quilboar tutt'intorno e nessuna protezione? Be', tutti abbiamo le nostre ragioni per giustificare quello che facciamo. La vera domanda è: cosa porta $Gun semplice:una semplice; $R fin nel cuore delle Barrens a parlare con una donna a cui chiaramente non importa niente della propria incolumità?\n\nScommetto che la risposta la conosciamo $Gtutti e due:tutte e due;.", enHash = "b956b562", vanilla = true },
    },
    [1531] = {
        title = { it = "Il richiamo dell'aria", enHash = "e4017783", vanilla = true },
        text = { it = "Stai facendo progressi, $Gamico:amica;. Sei $Gpronto:pronta; a dimostrare di essere $Gdegno:degna; dell'Air Totem, ma prima devi trovare Prate Cloudseer a Thousand Needles. Sarà disposta a dirti come ottenere il tuo Air Totem, se la tratti con abbastanza rispetto.\n\nVa' a sud attraverso le Barrens, e quando arrivi a Thousand Needles, va' a est. La troverai nascosta in una buca con il suo fidanzato — ah ah, non dirle che parlo male di lei — non la prenderebbe molto bene.", enHash = "1cebc44e", vanilla = true },
        objectives = { it = "Trova Prate Cloudseer, a Thousand Needles.", enHash = "e45968f4", vanilla = true },
        reward = { it = "Per il momento, ti darò ciò che ti serve per concentrare i tuoi incantesimi e invocare gli spiriti dell'aria. Prendi questo totem, e quando sarai $Gpronto:pronta;, allenati ancora con me.", enHash = "c4707b15", vanilla = true },
    },
    [1532] = {
        title = { it = "Il richiamo dell'aria", enHash = "e4017783", vanilla = true },
        text = { it = "I venti di Kalimdor ti corrono incontro, e sarai $Gannoverato:annoverata; tra $Gi nostri fratelli:le nostre sorelle; più potenti. È un orgoglio per me vedere che sei $Garrivato:arrivata; fin qui e che hai un futuro così promettente.\n\nL'elemento dell'aria è difficile da controllare, ma ho fiducia che le tue abilità supereranno qualunque ostacolo ti venga posto davanti.\n\nVa' all'estremo sud delle Barrens ed entra a Thousand Needles. È lì, molto a est, che troverai Prate Cloudseer. Ti insegnerà di più.", enHash = { "e0ea65d7", "4322fe7f" }, vanilla = true },
        objectives = { it = "Trova Prate Cloudseer, a Thousand Needles.", enHash = "e45968f4", vanilla = true },
        reward = { it = "Per il momento, ti darò ciò che ti serve per concentrare i tuoi incantesimi e invocare gli spiriti dell'aria. Prendi questo totem, e quando sarai $Gpronto:pronta;, allenati ancora con me.", enHash = "c4707b15", vanilla = true },
    },
    [1534] = {
        title = { it = "Il richiamo dell'acqua", enHash = "eab41910", vanilla = true },
        text = { it = "Prendi quest'otre e addentrati nella foresta rigogliosa che gli elfi della notte chiamano Ashenvale. Si trova all'estremo nord delle Barrens.\n\nQuando sarai nella foresta, dirigiti a ovest. Lungo le montagne che separano Stonetalon e Ashenvale, e oltre il Lake Mystral, troverai un luogo sacro: le Ruins of Stardust. Al centro del lago troverai una piccola fontana.\n\nPortami un campione dell'acqua della fontana. Sarà l'ultimo componente che ti servirà prima che ti rimandi da Islen.", enHash = "af15d87c", vanilla = true },
        objectives = { it = "Riempi l'Empty Blue Waterskin alle Ruins of Stardust, in Ashenvale, e torna da Brine, nelle Barrens.", enHash = "30d1c158", vanilla = true },
        progress = { it = "Hai già l'acqua, $N? Le leggende dicono che le rovine erano protette da grandi creature della natura a cui non piacciono i visitatori, ma potrebbero essere miti per spaventare i nemici degli elfi della notte.\n\nIn ogni caso, fai attenzione.", enHash = "a2a060c8", vanilla = true },
        reward = { it = "Magnifico, $N. Con tutti e tre i campioni raccolti, posso creare per te una fiala dell'acqua più pura che una creatura vivente possa trovare. Servirà nelle prossime tappe del tuo rito di passaggio.\n\nSono lieta di contarti tra la nostra gente, $N. Fai onore a ogni $C, e non vedo l'ora di sentir parlare delle tue imprese in futuro.", enHash = "bf461aaf", vanilla = true },
    },
    [1535] = {
        title = { it = "Il richiamo dell'acqua", enHash = "eab41910", vanilla = true },
        text = { it = "Per arrivare a capire, e per ottenere da me la sapta, devi cercare solo le forme più pure d'acqua. Mentre raccogli i campioni per me, osserva bene ciò che ti circonda. Fai attenzione alle creature che dipendono dall'acqua, che la proteggono. Guarda come influisce sulle foreste e sui deserti. Osserva come proprio la sostanza che sostiene la vita spinga le creature a uccidere.\n\nCominceremo con un compito semplice: sotto la mia capanna c'è uno stagno di questo liquido prezioso. Riempi quest'otre e torna da me.", enHash = "8ba5f1c2", vanilla = true },
        objectives = { it = "Riempi l'Empty Brown Waterskin alla pozza sotto la capanna di Brine e riportalo a lei, nelle Barrens.", enHash = "1906bee9", vanilla = true },
        progress = { it = "Sono quasi pronta a mandarti a svolgere gli altri compiti. Hai già riempito l'otre?\n\nSo quanto possono essere protettivi i quilboar. Anche una fonte d'acqua così piccola per loro è un immenso tesoro. Fanno grandi banchetti ogni volta che sulle Barrens cade anche la più leggera pioggia. L'acqua è sacra per la loro specie perché è così scarsa. Capisci?", enHash = "1f1f4376", vanilla = true },
        reward = { it = "Immaginavo che ci sarebbe scappato del sangue se avessi provato a prendere l'acqua dalla pozza. È un peccato che i quilboar non si rendano conto che tutti gli esseri viventi sono legati tra loro; che la loro avidità non fa che perpetuare il dolore e la sofferenza del loro popolo. Quante cose potrebbero ottenere, se mettessero da parte le loro divisioni e i loro clan si unissero.\n\nAncora una volta, è un peccato, ma con ogni probabilità è una fortuna per le altre razze delle Barrens.", enHash = "074c638a", vanilla = true },
    },
    [1536] = {
        title = { it = "Il richiamo dell'acqua", enHash = "eab41910", vanilla = true },
        text = { it = "Molto tempo fa seguii alcuni compagni nelle Hillsbrad Foothills. Ci difendemmo da certi umani tenaci che vivono lì, e ci ritrovammo in una cittadina che i Reietti avevano conquistato: Tarren Mill.\n\nFu lì che trovai una cosa davvero curiosa: al centro del paese c'era un piccolo pozzo di acqua sorgiva fresca. Non sono sicura che gli abitanti appestati della cittadina ne capiscano davvero il valore — è un piccolo vestigio sacro in un mare sconsacrato.\n\nPortami un campione di quell'acqua in quest'otre.", enHash = "b1393bdd", vanilla = true },
        objectives = { it = "Riempi l'Empty Red Waterskin al pozzo di Tarren Mill e torna da Brine, nelle Barrens.", enHash = "457d28da", vanilla = true },
        progress = { it = "Il pozzo rimasto puro in mezzo alla cittadina mi ricorda le storie che mi raccontavano quand'ero più giovane, $N. Anche nei momenti di grande dolore e tristezza si può trovare uno spiraglio di speranza, un piccolo simbolo attorno a cui stringersi. Gli orchi vedono Thrall in questo modo. È sopravvissuto contro ogni previsione e si è sollevato per guidare il nostro popolo con la sua forza e il suo esempio.\n\nNon so se ci sia un orco che abbia sofferto quanto lui, ma allo stesso tempo non so nemmeno se ci sia un orco forte quanto lui.", enHash = "8eb54249", vanilla = true },
        reward = { it = "Bene così, $N. Ti dedichi al compito che hai davanti e sai cercare ciò che serve.\n\nMi serve solo un altro campione per creare il reagente necessario per la tua sapta. Anche Islen ne sarà contenta.", enHash = "5068f31d", vanilla = true },
    },
    [1558] = {
        title = { it = "La Stonewrought Dam", enHash = "68fcbecc", vanilla = true },
        text = { it = "Ironforge è dove vivono tutti i nani e gli gnomi. Lì vicino c'è un posto chiamato Loch Modan, e i nani ci hanno costruito una diga ENORME. Dicono che sia una delle cose più grandi che siano mai state costruite. Wow!\n\nMi porteresti a Loch Modan a vedere la diga, per piacere? Mi sembra che si chiami Stone... ehm... Stonewrench Dam? Stonewrought? È grande, questo è sicuro. Vorrei affacciarmi sulla grande cascata. Prometto che non mi sporgerò troppo!", enHash = "0ced45da", vanilla = true },
        objectives = { it = "Porta l'orfano alla Stonewrought Dam, a Loch Modan. Dovresti portarlo al centro della diga, così potrà guardare la cascata gigante.", enHash = "d615cccf", vanilla = true },
        progress = { it = "Siamo arrivati?", enHash = "5cf70a59", vanilla = true },
        reward = { it = "WOW, la diga era MOLTO più grande di quanto pensassi! Riuscivo a malapena a sentirmi parlare per il rumore di tutta quell'acqua che scorreva! Ehi, pensi che l'acqua possa mai finire? Accidenti, cosa succederebbe se quella diga si rompesse! WOW, sarebbe spaventoso!\n\nGrazie di avermi portato a vedere la diga. È stato molto gentile da parte tua. Te l'avevo detto che non mi sarei sporto troppo!", enHash = "43a1d922", vanilla = true },
    },
    [1559] = {
        title = { it = "La ricetta delle Flash Bomb", enHash = "e134dc9c", vanilla = true },
        reward = { it = "Quindi sei $Gun ingegnere:un'ingegnera;, eh? Be', in cambio del tuo aiuto per procurarmi quelle perle, ecco la ricetta delle Flash Bomb.\n\nBuona fortuna, e cerca di non accecarti!", enHash = "56874edb", vanilla = true },
    },
    [1578] = {
        title = { it = "Rifornire il fronte", enHash = "efc2366d", vanilla = true },
        text = { it = "I montanari del Loch Modan stanno combattendo contro i trogg, e hanno il loro bel da fare! Hanno bisogno di rifornimenti continui di armature e armi nuove, se vogliamo mai riuscire a tenere a bada quei trogg.\n\nPer questo il mio collega Thorvald è laggiù, a cercare di tenere i montanari ben equipaggiati. Quindi, se tu fabbricassi qualche Copper Axe e qualche Copper Chain Belt e li portassi a Thorvald, te ne sarebbe grato. Potrebbe perfino condividere con te le sue conoscenze.\n\nThorvald si trova nella torre di guardia a sud del Loch Modan.", enHash = "e272c8e4", vanilla = true },
        objectives = { it = "Porta 6 Copper Axe e 6 Copper Chain Belt a Thorvald, nella torre di guardia a sud del Loch Modan.", enHash = "10fad1cc", vanilla = true },
        progress = { it = "Non ho tempo per chiacchierare. Hai qualche affare da sbrigare con me?", enHash = "03f79331", vanilla = true },
        reward = { it = "Ah, scusami! Non avevo capito che eri qui per aiutare a rifornire le nostre truppe. Quello che hai fabbricato sarà di grande aiuto!\n\nEcco gli schemi di un'armatura. Spero che ti siano utili.", enHash = "c4cc849f", vanilla = true },
    },
    [1579] = {
        title = { it = "Gaffer Jacks", enHash = "b2a4105b", vanilla = true },
        text = { it = "Sono venuto ad Auberdine per la tranquillità. Voglio inventare le mie invenzioni dove c'è silenzio, perché dopo una notte di bevute non sopporto tutto il rumore di Ironforge!\n\nCosì ho preso una nave per Auberdine e durante il viaggio ho bevuto un po' troppo. Ho fatto cadere in mare la mia scatola di Gaffer Jack! Mi servono i miei Gaffer Jack!\n\nNon so di preciso dove li ho fatti cadere, ma se li peschi nell'oceano forse ti andrà bene...", enHash = "18c78ae0", vanilla = true },
        objectives = { it = "Porta 8 Gaffer Jack a Wizbang Cranktoggle, ad Auberdine.", enHash = "2dd3a41f", vanilla = true },
        progress = { it = "Hai trovato i miei Gaffer Jack, $N? Senza i miei Gaffer Jack non posso regolare i miei pioli stintle!", enHash = "ceb8d12f", vanilla = true },
        reward = { it = "Non ci posso credere, li hai trovati! Devi essere $Gil:la; $R più $Gfortunato:fortunata; di Kalimdor!", enHash = "d9394b8f", vanilla = true },
    },
    [1580] = {
        title = { it = "Electropellers", enHash = "f2e9bd85", vanilla = true },
        text = { it = "Sappiamo che sei $Gfortunato:fortunata;, ma... quanto sei $Gfortunato:fortunata;, di preciso, $N?\n\nUna notte vagavo per le strade di Darkshore. Cercavo un bel fiume o un lago per provare il mio nuovo richiamo per anatre esplosivo e semovente, e credo di essere stato un po' brillo... perché sono svenuto e mi sono risvegliato ore dopo ad Auberdine. Avevo i capelli bruciacchiati e la mia borsa di Electropeller era sparita! Devo averli fatti cadere in acqua!\n\nMi servono quegli Electropeller! Magari riesci a ripescarli da qualche lago o torrente di Darkshore...", enHash = "d16623ea", vanilla = true },
        objectives = { it = "Porta 12 Electropeller a Wizbang Cranktoggle, ad Auberdine.", enHash = "f6f2a87a", vanilla = true },
        progress = { it = "Hai trovato qualche Electropeller? Mi serviranno se voglio continuare le mie ricerche sui richiami per anatre...", enHash = "6c914d25", vanilla = true },
        reward = { it = "Non ci posso credere! Li hai trovati! Sei $Gil miglior pescatore:la miglior pescatrice; che abbia mai visto!\n\nGrazie, $N. E tieni, prendi questi. Anche se sei così $Gbravo:brava; che probabilmente non ti servono, ti aiuteranno a pescare.", enHash = "b3542cf4", vanilla = true },
    },
    [1581] = {
        title = { it = "Elisir per i Bladeleaf", enHash = "d6402e0f", vanilla = true },
        text = { it = "Il nostro negozio di erbe e di alchimia va a gonfie vele, ma mio marito passa così tanto tempo a mescolare pozioni che non abbiamo mai tempo l'uno per l'altra.\n\nPuoi aiutarci?\n\nSe mi porti una scorta di elisir già pronti, sarò felice di fare uno scambio con te. Ho alcune erbe rare che potrebbero esserti utili.", enHash = "afed283d", vanilla = true },
        objectives = { it = "Porta 6 Elixir of Lion's Strength e 2 Elixir of Minor Defense a Syral Bladeleaf, a Dolanaar.", enHash = "36157f62", vanilla = true },
        progress = { it = "Salve, $N. Hai gli elisir da scambiare?", enHash = "50b281c1", vanilla = true },
        reward = { it = "Sono miscelati bene. Metti grande cura nel tuo mestiere, $N, ed è importante per un alchimista.\n\nEcco le tue erbe, appena raccolte. Possa tu usarle bene.", enHash = "d3eaa2f7", vanilla = true },
    },
    [1582] = {
        title = { it = "Moonglow Vest", enHash = "a1eeae22", vanilla = true },
        text = { it = "Noi di Darnassus, e soprattutto noi artigiani, abbiamo molto da fare. I giovani avventurieri sono impazienti di mettersi alla prova nelle terre selvagge, e hanno sempre bisogno di rifornimenti.\n\nSe mi aiuti a evadere i miei ordini di articoli di cuoio, forse potrò insegnarti una tecnica di conciatura avanzata.", enHash = "cb34459d", vanilla = true },
        objectives = { it = "Porta 1 Embossed Leather Gloves, 5 Embossed Leather Boots e 5 Embossed Leather Cloak a Lotherias, a Darnassus.", enHash = "2ffe83d3", vanilla = true },
        progress = { it = "Salve, $N.", enHash = "115a2b96", vanilla = true },
        reward = { it = "Sì, sono pezzi di buona fattura. Hai una mano abile e occhio per i dettagli. Come $Gconciatore:conciatrice; hai un futuro promettente.\n\nEcco, $N. Lascia che ti mostri lo schema per fare il Moonglow Vest.", enHash = "d6a4bbb0", vanilla = true },
    },
    [1598] = {
        title = { it = "Il tomo rubato", enHash = "d69eb77d", vanilla = true },
        text = { it = "Ehi, tu! $N, giusto?\n\nSpero che tu sia $Gsicuro:sicura; di voler diventare $Gun stregone:una strega;, perché se non riesci a cavartela, rischi di essere $Gtrascinato:trascinata; a fondo.\n\nDevo insegnarti, ma prima devo assicurarmi che tu sia abbastanza forte.\n\nC'era un novizio che studiava all'Abbey ed è scappato per unirsi alla Defias Brotherhood. Perché mi importa? Beh, ha rubato alcuni libri importanti.\n\nUno di questi è proprio un libro che volevo per me, Powers of the Void. Rubamelo: lo tengono nascosto nella loro tenda nei Vineyards.", enHash = "1777e926", vanilla = true },
        objectives = { it = "Recupera Powers of the Void per Drusilla La Salle.", enHash = "b6707f70", vanilla = true },
        progress = { it = "Sarebbe stato troppo vistoso rubare il libro di persona. Che fortuna che uno dei loro galoppini abbia fatto il lavoro sporco al posto mio.", enHash = "f98e8a3d", vanilla = true },
        reward = { it = "Eccellente... Non ero mai riuscita ad accedere a questo testo: era custodito in un'ala protetta della biblioteca, e se mi fossi aggirata da quelle parti sarei sembrata sospetta.\n\nBeh, hai fatto un buon lavoro a procurartelo, e sono convinta che probabilmente sai gestire un Imp tutto tuo, quindi non c'è motivo per non mostrarti come evocarne uno.", enHash = "5a171ede", vanilla = true },
    },
    [1599] = {
        title = { it = "Gli inizi", enHash = "43190736", vanilla = true },
        text = { it = "Devi essere $Gil nuovo stregone:la nuova strega; di cui tutti parlano sottovoce. Dev'essere che qualcuno ti ha preso in simpatia, se mi hanno chiesto di sottrarre tempo alle mie ricerche per cominciare il tuo addestramento.\n\nNon preoccuparti, non te ne faccio una colpa.\n\nL'incantesimo di evocazione più semplice che imparerai è quello dell'Imp. Prima di trasmettertelo, però, devi dimostrare di avere le capacità magiche e fisiche necessarie.\n\nPortami tre Feather Charm dei Frostmane Novice che stanno nella caverna a sud-ovest.", enHash = "6d272c72", vanilla = true },
        objectives = { it = "Porta 3 Feather Charm ad Alamar Grimm, ad Anvilmar.", enHash = "625d2a62", vanilla = true },
        progress = { it = "Quei Feather Charm che portano i novizi hanno una sorta di potere magico. Sarà interessante studiarli. Non me lo sarei aspettato dai troll.", enHash = "2f385b39", vanilla = true },
        reward = { it = "Molto bene, molto bene! Hai fatto un buon lavoro, $N. Forse l'interesse che ti stanno dimostrando è meritato, dopotutto.\n\nSaranno gli altri a deciderlo, sempre che il tuo Imp non abbia la meglio su di te e stronchi la tua carriera sul nascere. Per ora sono soddisfatto: probabilmente sopravviverai ai tuoi primi mesi da $C.\n\nUn consiglio sull'Imp, $N. Come sa ogni $R, non lasciarti ingannare dalle sue dimensioni: la sua magia può essere molto pericolosa.", enHash = "c2264990", vanilla = true },
    },
    [1618] = {
        title = { it = "Equipaggiare Redridge", enHash = "c7173247", vanilla = true },
        text = { it = "Non siamo solo noi nani a combattere. Anche i nostri alleati umani hanno il loro bel da fare!\n\nRedridge subisce attacchi periodici dagli orchi Blackrock, e le loro scorte di equipaggiamento sono sempre scarse. Se li aiutassi, di sicuro il loro fabbro, Verner Osgood, ti insegnerebbe un trucco o due.", enHash = "0725fa5f", vanilla = true },
        objectives = { it = "Tormus Deepforge vuole che tu porti 4 Runed Copper Belt e 4 Heavy Copper Maul a Verner Osgood, a Redridge.", enHash = "c3fc647b", vanilla = true },
        progress = { it = "Spero che tu sia qui con buone notizie da Ironforge. Perché io non so più dove sbattere la testa!", enHash = "e842ddb1", vanilla = true },
        reward = { it = "Grazie, $N. Questo mi aiuterà tantissimo. Con gli orchi Blackrock che attaccano dallo Stonewatch Keep e gli gnoll di Redridge in agguato sulle colline a nord, non faccio che riparare armature e forgiare armi nuove per le nostre truppe.\n\nI rifornimenti che hai portato mi daranno un momento di pace. Avrò abbastanza tempo per insegnarti qualcosa...", enHash = "d629c008", vanilla = true },
    },
    [1638] = {
        title = { it = "L'addestramento di un guerriero", enHash = "0c6f49b0", vanilla = true },
        text = { it = "Hai dimostrato di essere $Gun guerriero capace:una guerriera capace;, $N. Ma sei ancora giovane e hai molto da imparare.\n\nParla con Harry Burlguard: di solito sta nella taverna Pig and Whistle, nell'Old Town di Stormwind. Harry è un vecchio veterano e un buon insegnante. Può mostrarti qualche mossa che ti terrà in vita più a lungo.", enHash = "37702013", vanilla = true },
        objectives = { it = "Parla con Harry Burlguard.", enHash = "4f020e02", vanilla = true },
        reward = { it = "Oh oh! Bevi qualcosa con me, $N. Fuori sembri $Gtosto:tosta;, ma vediamo se il tuo stomaco regge qualche boccale della roba più forte del Pig and Whistle!!\n\nOppure... sei qui per una lezione?", enHash = "fbb29c6e", vanilla = true },
    },
    [1639] = {
        title = { it = "Bartleby l'ubriacone", enHash = "b6c4f1a6", vanilla = true },
        text = { it = "Sì, posso insegnarti. Ma prima voglio vedere che mosse conosci già.\n\nVedi quell'ubriaco laggiù, in fondo al bancone? Bartleby? Voglio che tu gli prenda il boccale.\n\nAh, e se conosci Bartleby, sai che non te lo darà tanto facilmente.", enHash = "8a46d911", vanilla = true },
        objectives = { it = "Parla con Bartleby.", enHash = "7718dbb1", vanilla = true },
        reward = { it = "Salve, $Gbel ragazzino:bella ragazzina;! Che ci fa una cosina delicata come te al Pig and Whistle? Sta' $Gattento:attenta;, o potresti romperti un'unghia...", enHash = { "31637e36", "800d800c" }, vanilla = true },
    },
    [1640] = {
        title = { it = "Batti Bartleby", enHash = "9448f6fb", vanilla = true },
        text = { it = "Che cosa vuoi?? Sei $Gpazzo:pazza;!\n\nL'unico modo per avere questo boccale è strapparmelo dalle dita fredde e morte...", enHash = "d5b281e1", vanilla = true },
        objectives = { it = "Batti Bartleby, poi parla con lui.", enHash = "e5f59c87", vanilla = true },
        progress = { it = "L'unico modo per avere questo boccale è strapparmelo dalle dita fredde e morte...", enHash = "782c9ca3", vanilla = true },
        reward = { it = "Sei molto più $Gtosto:tosta; di quanto sembri!", enHash = "af5a9a8d", vanilla = true },
    },
    [1641] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        reward = { it = "Qui a Stormwind, il mio compito è avviare i paladini sul cammino verso una virtù più grande, mentre si dedicano alla Luce e difendono Azeroth dal Flagello e da altre minacce.\n\nÈ giunto il momento che tu faccia il primo passo per diventare $Gdavvero virtuoso:davvero virtuosa;. Se accetti, ti darò un Book of Divinity. Studiandolo, imparerai qualcosa sulla Luce, e su ciò che ci si aspetta da te. Se lo comprenderai, e ne sarai capace, riuscirai a ottenere abilità più grandi.", enHash = "81e3c14d", vanilla = true },
    },
    [1642] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "In ogni cosa, un paladino deve riflettere la Luce che integra la nostra forza. Per uno come noi, sforzarsi di essere divino non significa aspirare alla divinità — significa sforzarsi di essere buoni in ogni azione.\n\nAnche se in questi tempi duri sei $Gchiamato:chiamata; a colpire il male, devi sempre ricordare che è aiutare gli altri che ti distinguerà davvero dagli abitanti di Azeroth. Compassione, pazienza, coraggio — queste cose contano per un paladino quanto la forza in battaglia.\n\nSappilo bene, e non dimenticarlo mai.", enHash = "458a8f6d", vanilla = true },
        objectives = { it = "Parla con Duthorian Rall, a Stormwind.", enHash = "b20f83f0", vanilla = true },
        reward = { it = "Ciao di nuovo, $N. Come procedono i tuoi studi sul Tome of Divinity?\n\nAllora dovresti essere $Gpronto:pronta; a essere $Gmesso:messa; alla prova. Ci sono sempre compiti da svolgere in città e nelle nostre terre; atti di compassione e di comprensione; persone che hanno bisogno di aiuto; creature da uccidere.\n\nDimostrando di avere la pazienza di aiutare gli altri, soprattutto i meno fortunati, dimostri di essere $Gun servitore:una servitrice; della Luce e di mente salda.", enHash = "f66ad705", vanilla = true },
    },
    [1643] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Il tuo compito, allora, $N, è trovare qualcuno qui a Stormwind che abbia bisogno di aiuto. Qualcuno puro di cuore e di intenzioni. Forse qualcuno che aiuta gli altri. Forse qualcuno che ha bisogno di una guida. In ogni caso, quella persona deve avere intenzioni nobili e contare sulla tua gentilezza.\n\nFa' questo, e torna da me quando hai finito. Allora parleremo ancora del tuo cammino e di cosa significa essere un paladino della Luce.", enHash = "e071aefa", vanilla = true },
        objectives = { it = "Cerca Stephanie Turner nel Trade District di Stormwind.", enHash = "b7d37fe9", vanilla = true },
        reward = { it = "Oh, ciao, tesoro. Come vanno le tue avventure? Oh, sono così contenta di sentire che ti va tutto bene.\n\nOh, io? Grazie per avermelo chiesto — sto bene, tutto sommato.\n\nL'aumento degli artigiani ha un po' ridotto la quantità di cuoio e di stoffa che la gente è disposta a cedere di questi tempi, quindi è stato più difficile fare vestiti per i bambini dell'orfanotrofio, ma ce la caveremo. Con \"noi\" intendo me e mio marito. È su a Ironforge a cercare aiuto tra i cittadini di là.", enHash = "6e73fcda", vanilla = true },
    },
    [1644] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Poveri cari, quasi tutti non hanno più una famiglia per colpa degli attacchi del Flagello nell'ultimo decennio.\n\nMio marito John raccoglie i materiali con cui cucio le camicie e i pantaloni per i bambini, ma non ho avuto nemmeno il tempo di farlo. Ho pensato solo a mettere il cibo nei loro piatti e un tetto sopra le loro teste.\n\nCome dici? Saresti $Gdisposto:disposta; ad aiutarmi? Oh, sia ringraziata la Luce, e grazie a te, $N.\n\nSe potessi portarmi un po' di Linen Cloth per cucire i vestiti ai bambini, mi aiuteresti tantissimo.", enHash = "9dee70f7", vanilla = true },
        objectives = { it = "Porta 10 Linen Cloth a Stephanie Turner, a Stormwind.", enHash = "e5172943", vanilla = true },
        progress = { it = "Spero che il mio John abbia più fortuna a Ironforge. Detesta tanto i suoi viaggi là, perché lasciano soli me e i bambini, ma sa che vanno fatti. Ha un cuore così buono.\n\nAlcuni anni sono stati più facili di altri, ma questo è stato di gran lunga il più duro. È quasi come se nell'aria ci fosse il segnale di un grande cambiamento. Ma chi lo sa?", enHash = "9210363c", vanilla = true },
        reward = { it = "Grazie, $N, grazie mille!\n\nI bambini saranno contentissimi, e mi hai fatto risparmiare un sacco di tempo. Ora potrò pensare agli altri bisogni dei bambini, e spero che il mio John possa tornare a casa prima del previsto.\n\nGrazie ancora, $N. Sapevo di poter contare sulla carità degli altri. Che la Luce sia con te.", enHash = "a196da13", vanilla = true },
    },
    [1645] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        reward = { it = "Piacere di conoscerti, $N. Il mio compito è avviare i paladini sul cammino verso una virtù più grande, mentre si dedicano alla Luce e difendono Azeroth dal Flagello e da altre minacce.\n\nÈ giunto il momento che tu faccia il primo passo per diventare $Gdavvero virtuoso:davvero virtuosa;. Se accetti, ti darò un Book of Divinity. Studiandolo, imparerai qualcosa sulla Luce, e su ciò che ci si aspetta da te. Se lo comprenderai, e ne sarai capace, riuscirai a ottenere abilità più grandi.", enHash = "cd16625a", vanilla = true },
    },
    [1646] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "In ogni cosa, un paladino deve riflettere la Luce che integra la nostra forza. Per uno come noi, sforzarsi di essere divino non significa aspirare alla divinità — significa sforzarsi di essere buoni in ogni azione.\n\nAnche se in questi tempi duri sei $Gchiamato:chiamata; a colpire il male, devi sempre ricordare che è aiutare gli altri che ti distinguerà davvero dagli abitanti di Azeroth. Compassione, pazienza, coraggio — queste cose contano per un paladino quanto la forza in battaglia.\n\nSappilo bene, e non dimenticarlo mai.", enHash = "458a8f6d", vanilla = true },
        objectives = { it = "Parla con Tiza Battleforge, a Ironforge.", enHash = "4c136c4c", vanilla = true },
        reward = { it = "$GBentornato:Bentornata;, $N. Hai passato del tempo a leggere il libro, spero?\n\nAllora dovresti essere $Gpronto:pronta; a essere $Gmesso:messa; alla prova. Ci sono sempre compiti da svolgere in città e nelle nostre terre; atti di compassione e di comprensione; persone che hanno bisogno di aiuto; creature da uccidere.\n\nDimostrando di avere la pazienza di aiutare gli altri, soprattutto i meno fortunati, dimostri di essere $Gun servitore:una servitrice; della Luce e di mente salda.", enHash = "77bf2a83", vanilla = true },
    },
    [1647] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Il tuo compito, allora, $N, è trovare qualcuno qui a Ironforge che abbia bisogno di aiuto. Qualcuno puro di cuore e di intenzioni. Forse qualcuno che aiuta gli altri. Forse qualcuno che ha bisogno di una guida. In ogni caso, quella persona deve avere intenzioni nobili e contare sulla tua gentilezza.\n\nFa' questo, e torna da me quando hai finito. Allora parleremo ancora del tuo cammino e di cosa significa essere un paladino della Luce. Resterò qui nel tempio ad aspettare il tuo ritorno. Anche altri paladini avranno bisogno della mia guida.", enHash = "0ec68e8b", vanilla = true },
        objectives = { it = "Cerca John Turner nell'anello esterno di Ironforge.", enHash = "59f0ebcc", vanilla = true },
        reward = { it = "L'ORFANOTROFIO DI STOR... oh, scusa, non volevo urlarti contro, $Gsignore:signorina;.\n\nMi chiamo John Turner. Come stai?\n\nBene, bene, sono contento di sapere che ti va tutto bene. Ho già avuto una lunga giornata di lavoro, e mi manca terribilmente mia moglie, ma è il prezzo da pagare quando ci sono bocche da sfamare e schiene da vestire.", enHash = { "0d082091", "799591b5" }, vanilla = true },
    },
    [1648] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Mia moglie e io gestiamo un orfanotrofio a Stormwind, soprattutto per i bambini che hanno perso i genitori negli attacchi del Flagello dell'ultimo decennio. Vengo a Ironforge più o meno una volta al mese per vedere di raccogliere altre provviste dai cittadini di qui, e per parlare con i vari gruppi e capire se possono fare qualcosa per aiutare.\n\nQuesto viaggio è stato lentissimo, e non molto fruttuoso.\n\nSe solo riuscissi a procurare un po' di lino in più a mia moglie per fare dei vestiti, potrei finalmente spedire un carico a casa.", enHash = "52298b66", vanilla = true },
        objectives = { it = "Porta 10 Linen Cloth a John Turner, a Ironforge.", enHash = "aebaffa3", vanilla = true },
        progress = { it = "Con tutti gli artigiani che arrivano qui e in tutta Azeroth, ci sono meno materiali per fare i vestiti ai bambini del nostro orfanotrofio. Aiutarmi a raccogliere il lino perché mia moglie possa fargli dei vestiti nuovi è molto nobile da parte tua, $N. Grazie.\n\nSpero di poter tornare presto a casa da mia moglie.", enHash = "8b57202e", vanilla = true },
        reward = { it = "È davvero magnifico da parte tua, $N. Grazie ancora.\n\nSei $Gun uomo nobile:una donna nobile; a fare questo per me. Non c'è da stupirsi che tu abbia scelto di seguire la Luce. Vorrei che ci fosse un modo per ripagarti di tutto quello che hai fatto... come dici? È il minimo che potessi fare? Visto? È proprio di questo che parlo, $N: nobile fino in fondo.\n\nStammi bene, e che la Luce ti protegga nei tuoi viaggi.", enHash = { "c3eb7ced", "f4fce785" }, vanilla = true },
    },
    [1649] = {
        title = { it = "Il Tome of Valor", enHash = "f377d3f9", vanilla = true },
        text = { it = "Il valore, e tutte le virtù che lo accompagnano, sono come minerali rari: devi custodirli gelosamente quando li trovi, per il loro valore, ma devi anche prenderti il tempo di estrarli... di raffinarli. Quando si fondono nel modo giusto, formano una lega resistente, a volte infrangibile anche dai colpi più potenti.\n\nQuesta forza, la tua fede, il tuo coraggio, devono essere messi alla prova. Devi imparare a non perdere mai la fede, e a capire che con il potere della Luce puoi superare prove che la maggior parte degli altri non riesce a superare.", enHash = "6356be04", vanilla = true },
        objectives = { it = "Parla con Duthorian Rall, a Stormwind.", enHash = "b20f83f0", vanilla = true },
        reward = { it = "Ah, desideri chiedermi una prova di valore. Splendido.\n\nCi sono molti compiti in città e nelle terre circostanti che presentano grandi sfide, e servirebbe $Gun uomo:una donna; con le tue capacità.\n\nQuesta prova non va presa alla leggera, $N. Questa, come molte cose lungo il nostro cammino, potrebbe costarci la vita. La Chiesa desidera sempre rafforzare i suoi ranghi, ma comprende i sacrifici necessari per assicurarsi che i paladini al suo servizio ne siano degni.\n\nSei $Gpronto:pronta;?", enHash = { "a95cebea", "bc77b2d2" }, vanilla = true },
    },
    [1650] = {
        title = { it = "Il Tome of Valor", enHash = "f377d3f9", vanilla = true },
        text = { it = "Bene! Non hai esitato, ed è il segno sicuro che sei $Gpronto:pronta; e impaziente di metterti alla prova. Così sia.\n\nProprio in fondo alla Longshore, a Westfall, c'è una casetta che si affaccia sull'oceano. Lì vive una coppia, gli Stilwell. Jordan è un fabbro straordinario, ed è andato per un po' a Ironforge a incontrare i nani. Ma così Daphne, sua moglie, è rimasta sola e senza protezione.\n\nStando ai rapporti, i Defias hanno quasi preso il controllo della zona: Daphne potrebbe aver bisogno di qualcuno che la protegga da quei furfanti. Va' laggiù.", enHash = "2b378574", vanilla = true },
        objectives = { it = "Trova Daphne Stilwell a Westfall.", enHash = "9cd9196a", vanilla = true },
        reward = { it = "Salve, $N. Con tutta quell'armatura e quell'arma, immagino che tu sia qui o per cercare di prenderti la mia terra, o perché la Chiesa ha finalmente mandato qualcuno ad aiutarmi a difendermi finché il mio Jordan è via.\n\nBe', lascia che mi presenti: sono Daphne Stilwell. Piacere.\n\nComunque, non sei in ritardo... Dall'alba ho fatto fuori solo una mezza dozzina di quei farabutti. Ci hanno messo un po' a sbucare dalla curva lassù, ma probabilmente ti hanno visto arrivare, quindi saranno qui da un momento all'altro.", enHash = "33b931cc", vanilla = true },
    },
    [1651] = {
        title = { it = "Il Tome of Valor", enHash = "f377d3f9", vanilla = true },
        text = { it = "Allora, torneranno presto, ci scommetto, quindi preparati.\n\nIn casa ho un fucile. Vado a prenderlo e sarò pronta a darti una mano, ma per lo più te la dovrai cavare da $Gsolo:sola;.\n\nNon ho idea di quanti ne manderanno, ma di sicuro saranno più dei pochi che hanno mandato prima.\n\nChiedi alla Luce tutte le benedizioni che puoi, perché... hai sentito? Credo che stiano arrivando.\n\nResisteremo vicino alla casa!", enHash = "80b7437f", vanilla = true },
        objectives = { it = "Difendi Daphne Stilwell dall'attacco dei Defias.\n\nSe vuoi riuscire, nessuno dei vostri due spiriti deve abbandonare il proprio corpo mortale.\n\nDopo la vittoria, parla di nuovo con Daphne Stilwell.", enHash = "7d061026", vanilla = true },
        progress = { it = "Resisteremo qui, alla casa!", enHash = "f75fb434", vanilla = true },
        reward = { it = "Ce l'abbiamo fatta, $N! Grazie per l'aiuto. Là fuori sei $Gstato:stata; davvero $Gstraordinario:straordinaria;. Non avrei mai pensato che un paladino potesse tenere testa a così tanti nemici tutti insieme.\n\nHai dimostrato un vero coraggio, contro forze di gran lunga superiori.", enHash = "65d3ad39", vanilla = true },
    },
    [1652] = {
        title = { it = "Il Tome of Valor", enHash = "f377d3f9", vanilla = true },
        text = { it = "Ti prego, torna da Duthorian e fagli sapere che per ora sono al sicuro. Per questo devo ringraziare te e la Chiesa.\n\nManderà un messaggio a Ironforge per far sapere al mio Jordan che non ha niente da temere.\n\nOh, quanto mi manca mio marito. Non vedo l'ora che torni.", enHash = "8e6a732e", vanilla = true },
        objectives = { it = "Parla con Duthorian Rall, a Stormwind.", enHash = "b20f83f0", vanilla = true },
        reward = { it = "Dunque ci rincontriamo, $N, e vedo che sei di ottimo umore.\n\nLa casa degli Stilwell sarà al sicuro per un altro giorno, e dal tuo racconto capisco che il pericolo non è mancato. Ben fatto.\n\nDaphne e Jordan hanno aiutato molto la Chiesa, e mandarti a proteggere la loro proprietà — e la loro stessa vita — era il minimo che potessimo fare per loro.\n\nPer il tuo valore, sarai $Gricompensato:ricompensata;.", enHash = "4b2199bf", vanilla = true },
    },
    [1653] = {
        title = { it = "La prova della rettitudine", enHash = "4426ce11", vanilla = true },
        text = { it = "A dire il vero, non ho dubbi che Jordan in persona vorrebbe ringraziarti, e visto che mi serve un messaggero che gli faccia sapere che sua moglie è salva, penso che saresti la scelta perfetta.\n\nJordan doveva diventare un paladino della Luce, prima che la dedizione al mestiere di suo padre lo portasse su un'altra strada — conosce a fondo il nostro modo di vivere, ed è considerato tra i nostri più fedeli.\n\nDovrebbe essere ancora a Ironforge — di giorno gli piace lavorare fuori dai cancelli, per via dell'aria fresca di montagna o qualcosa del genere.", enHash = "68064ce0", vanilla = true },
        objectives = { it = "Parla con Jordan Stilwell, a Ironforge.", enHash = "0499966d", vanilla = true },
        reward = { it = "Buongiorno, $N. La Luce è con te, spero?\n\nCome dici? Ti ha mandato Duthorian!? Mia moglie, come sta? Sapevo che ci sarebbero stati guai se fossi partito. Ti prego, dimmi che è... oh, grazie al cielo. Sono così contento che sia salva. I Defias erano una minaccia molto prima di questi attacchi, ma ora i consiglieri del re non possono più negarlo.\n\nCos'altro ha detto Duthorian?\n\nSei tu che hanno mandato a proteggere mia moglie? Allora ti ringrazio di nuovo, $N. Non saprei immaginare una prova di valore migliore di questa.", enHash = "d2148784", vanilla = true },
    },
    [1654] = {
        title = { it = "La prova della rettitudine", enHash = "4426ce11", vanilla = true },
        text = { it = "Vorrei ricompensarti, se ti va di accettare una cosa del genere. Non fraintendermi, la mia generosità dipende da quanto potrai essermi d'aiuto, ma vedo un grande vantaggio per tutti e due in un'alleanza del genere.\n\nForgerò per te un'arma degna di ciò che hai compiuto, un simbolo della condizione di paladino e della Luce, ma dovrai raccogliere tu gli oggetti che mi servono per forgiarla. Ho già cominciato a prendere appunti sugli oggetti, serve solo qualcuno abbastanza coraggioso e abile da recuperarli. Che ne dici, $C?", enHash = "fd1222c1", vanilla = true },
        objectives = { it = "Usando Jordan's Weapon Notes, trova del Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer e una Kor Gem, e riportali a Jordan Stilwell, a Ironforge.", enHash = "bf5a876a", vanilla = true },
        progress = { it = "Gli oggetti che cerchi saranno difficili da procurare, ma ti assicuro che l'arma che forgerò per te varrà la fatica.\n\nSarà il mio lavoro migliore fino a oggi, e solo un piccolo compenso per il servizio che mi hai reso.", enHash = "cb405a6a", vanilla = true },
        reward = { it = "È magnifico! Hai preso tutti gli oggetti.\n\nNon dovrei avere problemi a forgiarti un'arma grandiosa con questi. A dire il vero ho i progetti per farla da un po' di tempo. Non avevo mai avuto l'occasione di raccogliere il materiale. Grazie, $N.\n\nÈ bello riavere il martello di mio padre... e una Kor Gem. Non avrei mai pensato di vederne una con i miei occhi.", enHash = "3427a8f0", vanilla = true },
    },
    [1656] = {
        title = { it = "Un compito lasciato a metà", enHash = "3a91edc7", vanilla = true },
        text = { it = "$N, ti prego, ti supplico, puoi aiutarmi? Non ho finito i miei compiti qui sulla Mesa — sono nel mezzo del mio Rito della Forza — e mio padre mi ha chiesto di consegnare queste pellicce alla locanda di Bloodhoof.\n\nNon ho riposato abbastanza per portare a termine sia il mio rito sia questo compito per mio padre. Ti dispiacerebbe andarci tu per me?\n\nLa locanda è piacevole e un posto perfetto per riposare durante i lunghi viaggi. Sono sicuro che sarai d'accordo, una volta che la vedrai.", enHash = "477aa61f", vanilla = true },
        objectives = { it = "Porta il Bundle of Furs a Innkeeper Kauth, a Bloodhoof Village.", enHash = "c9fa6496", vanilla = true },
        progress = { it = "Sì, giovane? Cosa può fare Kauth per te?\n\nIl viaggio fin qui dalla Mesa può essere un fardello enorme per alcuni, ma una vista gradita per altri. Chissà cos'è stato per te.", enHash = "b751fa94", vanilla = true },
        reward = { it = "Ah, le pellicce che aspettavo. Grazie.\n\nSono arrivate più in fretta di quanto pensassi. Faranno buone coperte per chiunque voglia fermarsi qui.\n\nTrattieniti pure quanto vuoi. La mia locanda è sempre aperta e tutta la nostra gente è la benvenuta. E non sottovalutare una buona notte di riposo: può fare una gran differenza quando sei in viaggio.", enHash = "58e632b9", vanilla = true },
    },
    [1657] = {
        title = { it = "Appestare Southshore", enHash = "3f615a62", vanilla = true },
        text = { it = "Festeggia la Veglia delle Ombre con stile... portando dolore ai nostri nemici di Southshore!\n\nPrendi una di queste bombe puzzolenti preparate apposta. È piena di un tanfo nauseabondo che nessun umano, né alcuna bestia dalla volontà debole, può sopportare di annusare. Dovrai lanciarla proprio nel cuore di Southshore perché faccia effetto, quindi preparati a combattere contro l'Alleanza!\n\nQuando avrai portato a termine questo compito... questo tributo alla nostra liberazione, torna da me!", enHash = "32fdf2c7", vanilla = true },
        objectives = { it = "Lancia tre Forsaken Stink Bomb nel cuore di Southshore, nelle Hillsbrad, e torna da Darkcaller Yanka al Wickerman Festival, nelle Tirisfal Glade.", enHash = "19bbe0f8", vanilla = true },
        progress = { it = "Hai consegnato il nostro \"regalo\" alla gente di Southshore?\n\n<Darkcaller Yanka ride malvagiamente.>", enHash = "0b81d043", vanilla = true },
        reward = { it = "Ah, ben fatto! Spero che l'Alleanza soffochi con il regalo schifoso che le abbiamo fatto, proprio come noi siamo stati costretti a soffocare sotto il giogo della schiavitù al Flagello!\n\nHai onorato il vero spirito della Veglia delle Ombre, $N, e per questo ti rendo omaggio. Come premio in più, lascia che divida con te alcuni di questi dolcetti della Veglia delle Ombre. Credo che li troverai un diversivo piuttosto piacevole!", enHash = "2cf156d9", vanilla = true },
    },
    [1658] = {
        title = { it = "Imbucarsi al Wickerman Festival", enHash = "b6d8a6d9", vanilla = true },
        text = { it = "Mi servono persone coraggiose che vadano nelle Tirisfal Glade a dare un'occhiata al Wickerman Festival. Non ti mentirò: andare lassù sarà pericoloso. Le guardie della festa saranno spietate come non mai. Però dobbiamo sapere quanto è grande la festa quest'anno, e quanti guai ci daranno i Reietti durante la Veglia delle Ombre.\n\nSe te la senti, va' a Tirisfal e perlustra la festa. Torna da me con le informazioni, e farò in modo che tu venga $Gricompensato:ricompensata; bene.", enHash = "fddf93d1", vanilla = true },
        objectives = { it = "Trova il Wickerman Festival dei Reietti nelle Tirisfal Glade. Quando l'avrai trovato, torna da Sergeant Hartman a Southshore.", enHash = "0db737d9", vanilla = true },
        progress = { it = "Sei $Gandato:andata; nelle Tirisfal Glade a dare un'occhiata? Di solito tengono la festa vicino all'Undercity...", enHash = "f844cdef", vanilla = true },
        reward = { it = "Ben fatto, $N. Il Wickerman Festival continuerà a darci problemi finché agli abominevoli Reietti sarà permesso di infestare i resti di Lordaeron. NON è un tributo degno di quel regno un tempo fiero, te lo dico io...\n\nEcco qualche moneta per le riparazioni che ti serviranno, e nello spirito della festa ci ho messo anche qualche dolcetto che potrebbe piacerti. Buona Veglia delle Ombre: cerchiamo di passarla il più possibile al sicuro, qui a Southshore.", enHash = "d5be67f1", vanilla = true },
    },
    [1665] = {
        title = { it = "Bartleby's Mug", enHash = "573bbfdc", vanilla = true },
        text = { it = "Va bene, ecco il mio boccale. Aspetta! Prima lasciami finire quello che c'è dentro... ecco fatto.", enHash = "ac366a2f", vanilla = true },
        objectives = { it = "Porta Bartleby's Mug a Burlguard.", enHash = "6bb755c9", vanilla = true },
        progress = { it = "Ho visto il tuo scontro con Bartleby. Bel lavoro! Hai preso il suo boccale?", enHash = "39f95c63", vanilla = true },
        reward = { it = "Eccolo! Di certo non voleva separarsene, ma sei $Gstato:stata; convincente. Ben fatto.\n\nE ora la tua lezione...", enHash = "7ee01e21", vanilla = true },
    },
    [1666] = {
        title = { it = "Marshal Haggard", enHash = "4146a598", vanilla = true },
        text = { it = "Hai imparato qualche mossa, ma ti farebbe comodo un'arma decente. Scommetto che, se parlassi con Marshal Haggard, potrebbe aiutarti.\n\nMarshal Haggard vive in una casa padronale nell'Elwynn Forest, all'Eastvale Lumber Camp. Ora è in pensione, ma durante la sua carriera ha messo insieme un sacco di equipaggiamento.\n\nDigli che ti mando io e, con un po' di fortuna, avrà un'arma in più da offrirti.", enHash = "1d937512", vanilla = true },
        objectives = { it = "Parla con Marshal Haggard.", enHash = "eb53cbe2", vanilla = true },
        reward = { it = "Chi è?\n\nBurlguard, sei tu?\n\nDevi avvicinarti un po'. I miei occhi non sono più quelli di una volta.\n\nA vederti arrivare così, ti avevo preso per uno gnoll!", enHash = "dc908ed9", vanilla = true },
    },
    [1667] = {
        title = { it = "Dead-tooth Jack", enHash = "74c8d340", vanilla = true },
        text = { it = "Ti manda Burlguard, eh? Sì, qui ho delle armi in più, ma prima ho un compito per te...\n\nTempo fa un furfante dei Defias, Dead-tooth Jack, mi ha ingannato. Era buio, lui indossava una tabarda di Stormwind e io l'ho preso per Marshal Dughan. Ha detto che gli serviva il mio vecchio distintivo da maresciallo di Stormwind e io gliel'ho dato... poi è scoppiato a ridere ed è scappato prima che riuscissi a prenderlo!\n\nRiprendi il mio distintivo! Probabilmente Dead-tooth Jack l'ha nascosto nel suo accampamento, a sud.", enHash = "f31b74f3", vanilla = true },
        objectives = { it = "Recupera Haggard's Badge dall'accampamento di Dead-tooth Jack e torna da Marshal Haggard.", enHash = "e2232738", vanilla = true },
        progress = { it = "Hai il mio distintivo? Non voglio neanche pensare ai guai che Dead-tooth Jack potrebbe combinare con quello.", enHash = "821af4d5", vanilla = true },
        reward = { it = "Magnifico, l'hai trovato! Temevo che fosse perduto per sempre, e che i Defias lo usassero per spacciarsi per un funzionario di Stormwind. Beh, ora non succederà, grazie a te.\n\nEcco alcune armi che usavo quando ero maresciallo. Le ho tenute in ottimo stato: scegli quella che preferisci!", enHash = "15bd5b95", vanilla = true },
    },
    [1678] = {
        title = { it = "Vejrek", enHash = "cf1d071d", vanilla = true },
        text = { it = "Se vuoi salire di grado tra i guerrieri, faresti meglio a essere $Gtosto:tosta;. Posso insegnarti mosse nuove, ma prima dimostrami che sai cavartela contro nemici veri.\n\nVejrek è il troll più duro che troverai da queste parti, ed è lui che devi battere. Ha una capanna sulle colline appena a sud del Frostmane Hold.\n\nPortami la testa di Vejrek e saprò che hai fegato.", enHash = "4a52acf5", vanilla = true },
        objectives = { it = "Porta Vejrek's Head a Muren Stormpike, a Ironforge.", enHash = "a73b4d4b", vanilla = true },
        progress = { it = "Sei $Gstato:stata; alla capanna di Vejrek, $N? È puzza di $R quella che sento addosso a te?", enHash = "81baa704", vanilla = true },
        reward = { it = "Era proprio brutto, Vejrek, eh? Bel lavoro, $N! Hai la stoffa giusta, ora cominciamo la lezione...\n\nForse non lo sai, ma per $Gun:una; $C una buona difesa è molto importante. Permette di restare in piedi contro nemici che abbatterebbero chiunque altro, ed è proprio quello di cui i tuoi alleati hanno bisogno.", enHash = "bc40d93b", vanilla = true },
    },
    [1679] = {
        title = { it = "Muren Stormpike", enHash = "a502578f", vanilla = true },
        text = { it = "Salve, $Gguerriero:guerriera;! Sei molto promettente, ma devi ancora imparare qualche trucco, e Muren Stormpike è proprio il nano giusto per insegnarteli.\n\nTroverai Muren all'Hall of Arms, nel Military Ward di Ironforge. Parla con lui quando sei $Gpronto:pronta; a imparare cosa significa essere $Gun guerriero:una guerriera;.", enHash = "b4d93b21", vanilla = true },
        objectives = { it = "Parla con Muren Stormpike.", enHash = "ff0e58cb", vanilla = true },
        reward = { it = "Ah, $N. Ho sentito i guerrieri del Dun Morogh fare il tuo nome. Spero che tu non abbia passato tutto il tempo nei birrifici!", enHash = "edddfa97", vanilla = true },
    },
    [1680] = {
        title = { it = "Tormus Deepforge", enHash = "c93befef", vanilla = true },
        text = { it = "Ora che hai imparato qualche mossa, è il momento di procurarti un'arma decente. Parla con Tormus Deepforge. Può farti un'arma che, ne sono sicuro, ti piacerà.\n\nTroverai Tormus qui a Ironforge, alla Great Forge.", enHash = "c22f9225", vanilla = true },
        objectives = { it = "Parla con Tormus Deepforge.", enHash = "d3341953", vanilla = true },
        reward = { it = "Ti manda Muren, eh? Sì, posso farti una bella arma... ma prima ho un favore da chiederti.\n\nNon preoccuparti. È parecchio pericoloso e potrebbe costarti la vita: è proprio il genere di lavoro che $Gun:una; $C desidera.", enHash = "9327c4dd", vanilla = true },
    },
    [1681] = {
        title = { it = "Ironband's Compound", enHash = "13908f02", vanilla = true },
        text = { it = "Il mio maestro, Sturgy Ironband, aveva un complesso a sud dell'Helm's Bed Lake, nel Dun Morogh orientale. Lì insegnava la forgiatura, ed era il migliore.\n\nMa un giorno uno dei suoi allievi gli portò un carico di uno strano minerale. Mastro Ironband lo chiamò Umbral Ore e non vedeva l'ora di lavorarlo, ma poco dopo il suo arrivo... una banda di nani Dark Iron attaccò il complesso. Uccisero tutti!\n\nEntra nell'Ironband's Compound, $N, e vendica la morte del mio maestro. E portami il carico di Umbral Ore che l'ha causata.", enHash = "5a9792f1", vanilla = true },
        objectives = { it = "Porta un carico di Umbral Ore a Tormus Deepforge, a Ironforge.", enHash = "8b57de2f", vanilla = true },
        progress = { it = "Sei $Gentrato:entrata; nell'Ironband's Compound? Hai trovato l'Umbral Ore?", enHash = "c3c576b7", vanilla = true },
        reward = { it = "L'hai trovato! Ben fatto!\n\nSpero che tu abbia ucciso una schiera di nani Dark Iron mentre cercavi. Temo che l'Ironband's Compound non sarà l'ultimo posto in cui li vedremo.\n\nMa grazie per il minerale, $N. Non vedo l'ora di lavorarlo e di scoprirne le proprietà.", enHash = "9d7a805a", vanilla = true },
    },
    [1682] = {
        title = { it = "Armi di ferro grigio", enHash = "49177220", vanilla = true },
        reward = { it = "Ecco delle armi, appena uscite dall'incudine e fatte con il nuovo Umbral Ore che mi hai portato!\n\nPer favore, $N, scegli quella che preferisci!", enHash = "5405430d", vanilla = true },
    },
    [1683] = {
        title = { it = "Vorlus Vilehoof", enHash = "73ee0d39", vanilla = true },
        text = { it = "Prima che io possa insegnarti, devi dimostrarmi la tua determinazione.\n\nIl satiro Vorlus Vilehoof ha trovato uno dei nostri pozzi lunari più remoti, a sud-est del Ban'ethil Barrow Den. Ora ci sguazza dentro, profanando le sue acque pure con la sua sozzura.\n\nTrova Vorlus al pozzo lunare e distruggilo. Portami il suo corno come prova e comincerò il tuo addestramento avanzato da $Gguerriero:guerriera;.\n\nIl sentiero per il pozzo lunare è ben nascosto, $N, ma resta $Gconcentrato:concentrata; e vigile e lo troverai.", enHash = "f51532d9", vanilla = true },
        objectives = { it = "Porta l'Horn of Vorlus a Elanaria, a Darnassus.", enHash = "b848251f", vanilla = true },
        progress = { it = "Hai il corno, $N? Il nostro pozzo lunare è libero da quel demonio di Vorlus?", enHash = "2195ae08", vanilla = true },
        reward = { it = "Ben fatto, $N. È bello sapere che Vorlus è stato sconfitto e che il nostro pozzo lunare è purificato, ed è bello vedere giovani guerrieri desiderosi di tenere la nostra amata Teldrassil libera dalla corruzione.\n\nOra cominciamo il tuo addestramento...", enHash = "8941405f", vanilla = true },
    },
    [1684] = {
        title = { it = "Elanaria", enHash = "f8b9b21d", vanilla = true },
        text = { it = "Salve, $Gguerriero:guerriera;. La tua abilità cresce, ma nella tua professione c'è più di quanto tu possa credere. Per progredire ancora, presto dovrai trovare un insegnante.\n\nLa guerriera Elanaria vive a Darnassus, alla Warrior's Terrace. Sarà lei a istruirti.", enHash = "3e2734d6", vanilla = true },
        objectives = { it = "Parla con Elanaria.", enHash = "1c7710e5", vanilla = true },
        reward = { it = "Ti porgo i miei saluti, $N. Il tuo nome risuona forte a Darnassus, perché mostri del talento. Ma presto vedremo se possiedi la forza di volontà per seguire la via $Gdel:della; $C.", enHash = "d0702849", vanilla = true },
    },
    [1685] = {
        title = { it = "La convocazione di Gakin", enHash = "ee9110f4", vanilla = true },
        text = { it = "Non va sempre così? Ti ho cercato tutto il giorno senza trovarti, e ora che non me lo aspetto, mi vieni incontro.\n\nHo perso abbastanza tempo a cercarti, quindi non ti trattengo oltre. Il maestro Gakin ti ha convocato per un ulteriore addestramento. Mi sa che dovresti andare a cercarlo il prima possibile.\n\nLo troverai nel seminterrato della taverna Slaughtered Lamb. A proposito, faresti bene a non parlare in giro di quel posto. Meglio che non se ne sparga la voce.", enHash = "3119e15f", vanilla = true },
        objectives = { it = "Presentati da Gakin the Darkbinder, nel Mage Quarter di Stormwind.", enHash = "2a38b56d", vanilla = true },
        reward = { it = "Era ora che arrivassi. Anche se forse avrei dovuto mandare qualcuno più capace di Remen a cercarti.\n\nNon importa.\n\nSei $Grimasto:rimasta; troppo a lungo senza addestramento, e uno stregone senza addestramento difficilmente tiene la testa sulle spalle a lungo.", enHash = "db7b97f2", vanilla = true },
    },
    [1686] = {
        title = { it = "La Shade of Elura", enHash = "c4daf3f6", vanilla = true },
        text = { it = "Hai imparato molto, $N. Ora ti forgeremo un'arma. Un'arma da guerriero.\n\nPer farlo, devi andare a Darkshore.\n\nMolto tempo fa una nave si schiantò sugli scogli vicino al faro di Auberdine, spargendo molte casse di Elunite Ore sul fondo dell'oceano.\n\nPrima devi sconfiggere la guardiana dell'elunite, la Shade of Elura. Un tempo era il capitano della nave; lanciò una maledizione su se stessa per vagare negli abissi e proteggere il suo carico in eterno. Sconfiggila, prendi il suo medaglione e raccogli le casse di Elunite perduta.", enHash = "280fbef9", vanilla = true },
        objectives = { it = "Porta 8 carichi di Elunite Ore e il Medallion of Elura a Elanaria, a Darnassus.", enHash = "63a54942", vanilla = true },
        progress = { it = "Hai sconfitto la Shade of Elura, $N? E hai l'Elunite Ore perduto?", enHash = "c0cd4cfb", vanilla = true },
        reward = { it = "Hai agito con coraggio, $N.\n\nHai dato alla Shade of Elura la pace che meritava, e useremo l'elunite raccolta per forgiarti un'arma pregiata.", enHash = "bb8c586f", vanilla = true },
    },
    [1687] = {
        title = { it = "Il faro spettrale", enHash = "b5ccd3df", vanilla = true },
        text = { it = "A volte, a notte fonda, le matrone dell'orfanotrofio ci raccontano storie di paura. Sono FANTASTICHE! Ce n'è una su un fantasma che infesta un faro a Westfall. Dicono che fosse un capitano pirata a cui altri pirati avevano preso la nave. Wow!\n\nMi porteresti a vedere il faro a Westfall, per piacere? Voglio vedere se il fantasma di quel capitano c'è davvero! Prometto di starti vicino; non scapperò né niente!", enHash = "a7ccbe4b", vanilla = true },
        objectives = { it = "Porta l'orfano a vedere il faro al largo della costa di Westfall.", enHash = "324466ea", vanilla = true },
        progress = { it = "Siamo arrivati?", enHash = "5cf70a59", vanilla = true },
        reward = { it = "WOW, era un fantasma vero! È stato fantastico: non vedo l'ora di raccontarlo a tutti all'orfanotrofio. Captain Grayson... sembrava proprio un pirata! Da grande voglio essere un pirata fantasma anch'io!\n\nGrazie di avermi portato a Westfall, $N. So che là fuori, nelle terre selvagge di Westfall, ci sono cose che fanno paura, e spero di non essere stato troppo una seccatura. Sei $Gfantastico:fantastica;!", enHash = "75ef2041", vanilla = true },
    },
    [1688] = {
        title = { it = "Surena Caledon", enHash = "e62c53f4", vanilla = true },
        text = { it = "Avevo un'allieva di nome Surena Caledon. Stava dove stai tu ora, desiderosa di imparare la magia degli stregoni, e con un talento non da poco. Per di più era giovane e piacevole allo sguardo. Se solo me ne fossi accorto allora, quella sgualdrina traditrice!\n\nQuella ladra è scappata con uno dei Defias, Erlan Drudgemoor. La sua perdita conta poco, ma le avevo regalato un Bloodstone Choker che devo riavere.\n\nOra la sua vita non significa niente per me. La troverai al Brackwell Pumpkin Patch. Recupera ciò che è mio.", enHash = "64a49565", vanilla = true },
        objectives = { it = "Recupera il Surena's Choker per Gakin the Darkbinder, a Stormwind.", enHash = "f7a047d2", vanilla = true },
        progress = { it = "Anche i più anziani e saggi possono perdere la testa davanti alle lusinghe della giovinezza e della bellezza, $N. Un consiglio che faresti bene a ricordare per tutta la vita.", enHash = "1e71c477", vanilla = true },
        reward = { it = "Surena aveva talento, ma non abbastanza da padroneggiare da sola la magia degli stregoni. È un peccato vedere un talento sprecato, ma a volte è necessario.\n\nSpero che l'investimento che ho fatto su di te dia risultati diversi.", enHash = "361f20fa", vanilla = true },
    },
    [1689] = {
        title = { it = "Il vincolo", enHash = "2a2909d6", vanilla = true },
        text = { it = "Recuperando il mio collare e battendo Surena, hai dimostrato di essere capace almeno quanto lei.\n\nDetto questo, vedo che hai un disperato bisogno di addestramento. Sai gestire i flussi della magia, sì, ma essere uno stregone è molto più di questo.\n\nTi mostrerò come comandare un Voidwalker, ma prima devi richiamarne uno in un cerchio di evocazione e sottometterlo con qualunque arma, fisica o magica, tu abbia a disposizione. Usa la magia di questo collare nel cerchio di evocazione qui sotto.", enHash = "cfb00bfe", vanilla = true },
        objectives = { it = "Usando il Bloodstone Choker, evoca e sottometti un Voidwalker, poi riporta il Bloodstone Choker a Gakin the Darkbinder, a Stormwind.", enHash = "7837bd50", vanilla = true },
        progress = { it = "Non posso mostrarti come controllare un Voidwalker finché non ne avrai sopraffatto uno.", enHash = "f4545ccd", vanilla = true },
        reward = { it = "Hai fatto meglio di quanto mi aspettassi, $N, ma bene quanto speravo. Ora puoi imparare a comandare il Voidwalker che hai soggiogato, un alleato che ti sarà prezioso nelle prove che di certo ti aspettano.\n\nPer ora non ho altro da insegnarti, ma con te sono ben lontano dall'aver finito, $N.", enHash = "856d3b73", vanilla = true },
    },
    [1692] = {
        title = { it = "Smith Mathiel", enHash = "98a76fab", vanilla = true },
        text = { it = "Ho messo in una cassa l'elunite che hai raccolto. Portala al fabbro Mathiel, e lui ti forgerà un'arma di elunite.\n\nMathiel è a sud, dall'altra parte di questo edificio.", enHash = "b9c8807d", vanilla = true },
        objectives = { it = "Porta la Case of Elunite a Smith Mathiel.", enHash = "3862b48c", vanilla = true },
        progress = { it = "Salve, giovane $C. Come posso servirti con la mia arte?", enHash = "5197af9b", vanilla = true },
        reward = { it = "Ah, l'Elunite Ore. È un metallo splendido da lavorare, perché è benedetto dalla dea Elune in persona. Sarebbe un onore forgiare armi con esso.\n\nAttendi, per favore, mentre lavoro...", enHash = "7cf6cddf", vanilla = true },
    },
    [1693] = {
        title = { it = "Armi di elunite", enHash = "10fa17ba", vanilla = true },
        reward = { it = "$N, ho forgiato queste armi con l'elunite che mi hai portato. Per favore, prendi quella che ti si addice di più.\n\nE devo ringraziarti. Lavorare l'elunite è sia un onore sia un piacere.", enHash = "59d6857a", vanilla = true },
    },
    [1698] = {
        title = { it = "Yorus Barleybrew", enHash = "34c183d5", vanilla = true },
        text = { it = "Yorus Barleybrew ha lanciato una sfida a tutti i guerrieri valenti dell'Alleanza. Aspetta alla Lakeshire Inn, a Redridge, e promette una grande ricompensa a chiunque riesca a superare la sua prova.", enHash = "e657393d", vanilla = true },
        objectives = { it = "Parla con Yorus Barleybrew.", enHash = "d861022d", vanilla = true },
        reward = { it = "Ah! Quindi hai sentito parlare della mia sfida, eh?\n\nBeh, siediti e ascolta. Bevi qualcosa, e gustatelo... perché potrebbe essere l'ultimo.", enHash = "2563ba2c", vanilla = true },
    },
    [1699] = {
        title = { it = "La Prova di Rethban", enHash = "cb1d06c1", vanilla = true },
        text = { it = "La mia sfida la chiamo la Prova di Rethban. Per superarla, devi solo entrare nelle Rethban Caverns, arrivare al primo bivio e tornare qui. Facile! Se non fosse per qualche piccolo intoppo...\n\nDevi tornare entro un'ora.\n\nSulla strada ci sono mucchi di gnoll di Redridge.\n\nPrima di partire, devi mandare giù un sorso della bevanda tipica della mia famiglia: la Barleybrew Scalder!\n\nAllora, che ne dici? Le Rethban Caverns sono sulle colline a nord di Lakeshire. Sei $Gpronto:pronta; ad affrontare la Prova di Rethban?", enHash = "90cf1519", vanilla = true },
        objectives = { it = "Entra nelle Rethban Caverns, raggiungi il primo bivio e torna da Yorus Barleybrew entro il tempo stabilito.\n\nNon devi morire né rilasciare lo spirito.", enHash = "292a2304", vanilla = true },
        progress = { it = "Il tempo stringe, $N. Se fossi in te, mi darei una mossa...", enHash = "4f9ebeea", vanilla = true },
        reward = { it = "Ce l'hai fatta! Ben fatto! Tre urrà per $N!", enHash = "30b44ae7", vanilla = true },
    },
    [1700] = {
        title = { it = "Grimand Elmore", enHash = "cc490f74", vanilla = true },
        text = { it = "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre facevo la tua armatura, e devo farli avere a Grimand Elmore. È qui nel Dwarven District, nella bottega di armi.\n\nE abbassati quando glieli dai. È orgogliosissimo della sua abilità, e non gli piacerà l'idea di imparare qualcosa da me...", enHash = "d8591e91", vanilla = true },
        objectives = { it = "Porta Furen's Notes a Grimand Elmore.", enHash = "4dfb67aa", vanilla = true },
        progress = { it = "Salve, piacere di conoscerti. Come posso esserti utile?", enHash = "fef1c773", vanilla = true },
        reward = { it = "L'ha scritto Furen? Come si permette! Ma se gli ho insegnato tutto quello che sa! Pensare che possa insegnarmi qualcosa è un oltraggio! Un oltraggio!\n\nMm... però c'è una cosa nei suoi appunti che vorrei provare...", enHash = "ea53f135", vanilla = true },
    },
    [1701] = {
        title = { it = "Maglia temprata nel fuoco", enHash = "c14e32da", vanilla = true },
        text = { it = "Ti ho dato un bello scudo, ma non dobbiamo fermarci qui. Conosco i segreti per fare un'armatura di maglia durissima. Non è facile e servono materiali molto rari, ma se sei $Gdisposto:disposta; a darti da fare, te ne farò un pezzo.\n\nChe ne dici, $N? Se sei all'altezza della sfida, ti darò un elenco di cosa procurarti e dove trovarlo.", enHash = "b3aeee91", vanilla = true },
        objectives = { it = "Raccogli i materiali che servono a Furen Longbeard e portaglieli, a Stormwind.", enHash = "6d4c1322", vanilla = true },
        progress = { it = "Come va la caccia al tesoro, $N? Hai i materiali?", enHash = "db8ca259", vanilla = true },
        reward = { it = "Hai preso tutto? Incredibile! Temevo proprio che quelle chimere ti avrebbero divorato!\n\nBeh, mettiamoci al lavoro su quell'armatura...", enHash = "e91ddf12", vanilla = true },
    },
    [1702] = {
        title = { it = "Il fabbro di scudi", enHash = "7834190b", vanilla = true },
        text = { it = "Hai davvero dimostrato di che pasta sei $Gfatto:fatta; quando hai affrontato la Prova di Rethban, $N. E io mantengo la parola. Ti darò la ricompensa che ti ho promesso...\n\nSolo che si trova a Stormwind.\n\nParla con il mio amico Furen Longbeard, nel Dwarven District di Stormwind. È il miglior fabbro di scudi che incontrerai mai, e mi deve un grosso favore.\n\nEcco, porta a Furen questo barile di Barleybrew Scalder e chiedigli uno scudo. Te ne darà uno bello.", enHash = "af73932d", vanilla = true },
        objectives = { it = "Porta il Cask of Scalder a Furen Longbeard.", enHash = "e7aec1ed", vanilla = true },
        progress = { it = "Salve! Che sete, di questi tempi, non trovi?", enHash = "aae3c1d2", vanilla = true },
        reward = { it = "Ah, la Barleybrew Scalder. Roba ottima! Quindi sei $Gstato:stata; da Yorus, eh?\n\nUno scudo te lo procuro, eccome! Non ne troverai uno migliore, e non è una bugia!", enHash = "09790b44", vanilla = true },
    },
    [1703] = {
        title = { it = "Mathiel", enHash = "3220d2c8", vanilla = true },
        text = { it = "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre facevo la tua armatura, e devo farli avere al fabbro Mathiel. Vive a Darnassus, che è piuttosto lontano, ma sono sicuro che sarà molto grato di imparare quello che ho imparato io.", enHash = "dbc3a770", vanilla = true },
        objectives = { it = "Porta Furen's Notes a Mathiel.", enHash = "068e9bf6", vanilla = true },
        progress = { it = "Ti porgo i miei saluti, $C.", enHash = "c455d5fc", vanilla = true },
        reward = { it = "Sono interessanti, davvero molto interessanti. Il mio collega nano Furen ha fatto una grande scoperta!\n\nGrazie, $N. Sarà un onore applicare le sue nuove tecniche alle mie creazioni.", enHash = "ffd5a4c1", vanilla = true },
    },
    [1704] = {
        title = { it = "Klockmort Spannerspan", enHash = "85661a35", vanilla = true },
        text = { it = "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre facevo la tua armatura, e mi serve qualcuno che li porti a Klockmort Spannerspan. È un fabbro gnomo di Ironforge, e quando scoprirà quello che ho imparato... scommetto che si strapperà la barba per l'emozione.", enHash = "124a6f97", vanilla = true },
        objectives = { it = "Porta Furen's Notes a Klockmort Spannerspan.", enHash = "7e554629", vanilla = true },
        progress = { it = "Buona giornata. O buongiorno, o buonasera: da quaggiù non riesco a capirlo. Allora, hai affari per me?", enHash = "82322311", vanilla = true },
        reward = { it = "Oh, cielo! Questi appunti sono fantastici! E per giunta... sono incredibili, sono stupefacenti e mi fanno tremare le ginocchia!\n\nFuren ha fatto una scoperta! Una vera scoperta! Non vedo l'ora di provare la sua nuova tecnica!", enHash = "d83889a5", vanilla = true },
    },
    [1705] = {
        title = { it = "Burning Blood", enHash = "0f66c74d", vanilla = true },
        text = { it = "Mi secca ammetterlo, ma Furen potrebbe aver davvero scoperto qualcosa. Per esserne sicuro, però, devo provare le sue tecniche su un'armatura nuova. Se mi aiuti con i materiali, $N, l'armatura potrai tenerla tu.\n\nPer fare questa armatura mi servono dei campioni di Burning Blood e una Burning Rock.\n\nL'unico posto che conosco dove trovarli è Duskwood. I worgen Nightbane che hanno la loro base nella miniera di Roland's Doom hanno il Burning Blood, e il loro capo, Gutspill, avrà la roccia.\n\nChe la fortuna ti metta le ali ai piedi, $N.", enHash = "0f5ba479", vanilla = true },
        objectives = { it = "Porta 20 fiale di Burning Blood e 1 Burning Rock a Grimand Elmore, a Stormwind.", enHash = "fa5314d8", vanilla = true },
        progress = { it = "$N, hai il Burning Blood e la Burning Rock? Mi servono per completare l'armatura.", enHash = "f47a196b", vanilla = true },
        reward = { it = "Bel lavoro! Ora, se vuoi scusarmi, anch'io ho del lavoro da fare...", enHash = "e85398e5", vanilla = true },
    },
    [1706] = {
        title = { it = "L'armatura di Grimand", enHash = "f6403973", vanilla = true },
        reward = { it = "Stento a crederci! La tecnica di Furen ha funzionato, e questa armatura dovrebbe reggere a sollecitazioni enormi.\n\nEccola, $N. E grazie. Non avrei creduto alla scoperta di Furen se tu non avessi raccolto i materiali che mi servivano per metterla alla prova di persona.", enHash = "7a4d278f", vanilla = true },
    },
    [1708] = {
        title = { it = "Corallo di ferro", enHash = "3a6b16d9", vanilla = true },
        text = { it = "Voglio provare le nuove tecniche di Furen Longbeard su un'armatura tutta mia. E visto che tu hai aiutato Furen e lui ha aiutato me, l'armatura, una volta fatta, sarà tua!\n\nPer finire il pezzo mi serve un corallo speciale, il Searing Coral. Cresce in un solo posto: lungo la costa a sud di Menethil Harbor, nelle Wetlands.\n\nPortami abbastanza Searing Coral e mi metterò subito al lavoro sull'armatura. E sbrigati, $N. Sono così impaziente di cominciare che mi si attorcigliano le dita dei piedi!", enHash = "c602fd11", vanilla = true },
        objectives = { it = "Porta 20 carichi di Searing Coral a Klockmort Spannerspan, a Ironforge.", enHash = "9a14910c", vanilla = true },
        progress = { it = "Salve, salve, $N! Hai il Searing Coral? Non vedo l'ora di mettermi al lavoro!", enHash = "93322d08", vanilla = true },
        reward = { it = "È questo! Ben fatto! Ora lascia che lo fonda e lo martelli, così posso combinare la tecnica di Furen con la mia, e poi vediamo che succede!\n\nOh cielo, oh cielo! Me lo sento che l'armatura sarà molto molto molto resistente!", enHash = "f24b7557", vanilla = true },
    },
    [1709] = {
        title = { it = "La creazione di Klockmort", enHash = "8ec25299", vanilla = true },
        reward = { it = "Ecco la tua armatura, $N. Il procedimento di Furen ha funzionato benissimo! Alla perfezione! Davvero a meraviglia!\n\nPotresti passarci sopra con una macchina d'assedio e riprenderebbe subito la sua forma!", enHash = "4aa764dc", vanilla = true },
    },
    [1710] = {
        title = { it = "Sunscorched Shells", enHash = "f243c240", vanilla = true },
        text = { it = "Il mio collega Furen Longbeard ha fatto una scoperta che non vedo l'ora di mettere alla prova. Vorrei provarla su una nuova armatura che sto studiando, perché credo che le tecniche di Furen daranno risultati migliori.\n\nMi aiuterai? Se raccogli ciò che mi serve per fare l'armatura, ne farò un pezzo in più per te.\n\nMi servono i gusci d'uovo bruciati dal sole degli Highperch Wyvern che vivono a Highperch, nelle Thousand Needles. Cerca i gusci sotto i loro nidi, e torna da me quando ne avrai abbastanza.", enHash = "4fd289d0", vanilla = true },
        objectives = { it = "Porta 20 Sunscorched Shell a Mathiel, a Darnassus.", enHash = "63ca41d2", vanilla = true },
        progress = { it = "Hai i gusci, $N? Sono molto robusti, e se ne può ricavare una lacca con cui rivestirò gli anelli della mia nuova armatura di maglia.", enHash = "5d8359be", vanilla = true },
        reward = { it = "Ah, grazie. Andranno benissimo!\n\nComincerò subito a forgiare l'armatura...", enHash = "c4f866f7", vanilla = true },
    },
    [1711] = {
        title = { it = "L'armatura di Mathiel", enHash = "dd877413", vanilla = true },
        reward = { it = "Ho finito il tuo pezzo d'armatura, e ne sono molto soddisfatto. Le nuove tecniche di Furen si sono fuse alla perfezione con le mie, e sono sicuro che questa armatura si dimostrerà molto resistente.\n\nGrazie, $N. Che ti sia utile nelle battaglie future.", enHash = "abd57d1c", vanilla = true },
    },
    [1712] = {
        title = { it = "Cyclonian", enHash = "a3893818", vanilla = true },
        text = { it = "Ho passato secoli a osservare questo luogo. Osservo, perché un giorno possa vedere cadere il grande Cyclonian. Ma non ho ancora trovato un campione capace di sconfiggere il signore del vento.\n\nForse sei tu quel campione.\n\nDimostramelo. Raccogli gli oggetti che mi servono per evocare Cyclonian, e saprò che sei $Gun grande guerriero:una grande guerriera;. Forse allora potrai sconfiggerlo e prendere il suo Whirlwind Heart.\n\nSe ci riuscirai, infonderò il potere del cuore in un'arma, e quell'arma la darò a te.\n\nEcco una pergamena con gli oggetti che mi servono.", enHash = "732f876b", vanilla = true },
        objectives = { it = "Porta gli oggetti elencati nella Bath'rah's Parchment a Bath'rah the Windwatcher, ad Alterac.", enHash = "75a54739", vanilla = true },
        progress = { it = "Hai gli oggetti, $N? Raccoglierli è la prova che mi serve per sapere che hai la forza di affrontare Cyclonian.", enHash = "cdda6cbb", vanilla = true },
        reward = { it = "Hai raccolto gli oggetti per il mio incantesimo, e mi hai mostrato la tua forza e la tua astuzia. Ma la prossima fase della nostra impresa è ancora più pericolosa.\n\nSperiamo che la tua forza non vacilli.", enHash = "5fa2e4e3", vanilla = true },
    },
    [1713] = {
        title = { it = "L'evocazione", enHash = "d5f16a72", vanilla = true },
        text = { it = "Sono pronto a compiere il rituale per evocare Cyclonian. Quando sarà evocato, dovrai sconfiggerlo e prendere il suo Whirlwind Heart. Lo userò per infondere in un'arma il potere di Cyclonian.\n\n$N, sei $Gpronto:pronta; ad affrontare il signore del vento?", enHash = "692794ad", vanilla = true },
        objectives = { it = "Porta il Whirlwind Heart a Bath'rah Windwatcher.", enHash = "8e10c16d", vanilla = true },
        progress = { it = "$N, devo avere il Whirlwind Heart!", enHash = "75729f06", vanilla = true },
        reward = { it = "Ce l'hai fatta! Hai sconfitto Cyclonian e hai preso il Whirlwind Heart!", enHash = "5cc13780", vanilla = true },
    },
    [1714] = {
        title = { it = "Essence of the Exile", enHash = "3061e6e7", vanilla = true },
        progress = { it = "Il calderone ribolle. I suoi vapori ti chiamano...", enHash = "07101911", vanilla = true },
        reward = { it = "Gli amuleti affondano lentamente nelle profondità del calderone...\n\nUna grossa bolla sale in superficie e scoppia...\n\n...e appare un grumo di roccia fusa che ribolle.", enHash = "b1ca4466", vanilla = true },
    },
    [1715] = {
        title = { it = "Lo Slaughtered Lamb", enHash = "8cb85da7", vanilla = true },
        text = { it = "Hmph. Un tempo tutti gli stregoni del Khaz Modan venivano addestrati sotto la guida dei maestri di Gnomeregan, ma ora che siamo stati tutti costretti a trasferirci in questa tana di topi a Ironforge, e che Magni ha deciso di tenerci d'occhio, dobbiamo mandare i nostri novizi ad addestrarsi a Stormwind.\n\nPer fortuna Gakin non è uno sprovveduto, quindi imparerai comunque quello che ti serve, ma mi fa ribollire il sangue!\n\nComunque, troverai Gakin nel seminterrato dello Slaughtered Lamb, a Stormwind.", enHash = "4c7964a4", vanilla = true },
        objectives = { it = "Presentati da Gakin the Darkbinder, nel Mage Quarter di Stormwind.", enHash = "2a38b56d", vanilla = true },
        reward = { it = "Ti manda Blackwrench, eh? Quei dannati stregoni di Ironforge devono sistemare le loro faccende. A Stormwind c'è poco spazio e ci sono pochi insegnanti. Con tutto questo via vai, prima o poi attireremo l'attenzione.", enHash = "95f3474f", vanilla = true },
    },
    [1716] = {
        title = { it = "Divoratrice di anime", enHash = "b530f7f3", vanilla = true },
        text = { it = "Una Succubus è una divoratrice di anime, una distruttrice di cuori e una dominatrice di menti. Non conosce altro che il male.\n\nSarà questa la creatura che imparerai a evocare e controllare, ma non può essere portata nel nostro mondo senza uno stimolo.\n\nCon un simbolo d'amore come esca, risponderà di certo al tuo richiamo. Allora potrai sconfiggerla e farne il tuo strumento.\n\nSarà difficile trovare qualcosa del genere, però. Dovresti parlare con Takar the Seer. Lo troverai nelle Barrens di Kalimdor, vicino a Camp Taurajo.", enHash = "5ccc52e2", vanilla = true },
        objectives = { it = "Parla con Takar the Seer, nelle Barrens.", enHash = "c68e6a58", vanilla = true },
        reward = { it = "La traversata è stata difficile, $N? Hai fatto molta strada per parlare con me. Ma non temere: so perché Gakin ti ha mandato, e ha fatto bene, perché posso aiutarti nella tua ricerca.", enHash = "5538c93a", vanilla = true },
    },
    [1717] = {
        title = { it = "La convocazione di Gakin", enHash = "ee9110f4", vanilla = true },
        text = { it = "$N! Non mi aspettavo di vederti da queste parti, ma mi avevano chiesto di tenere gli occhi aperti nel caso passassi.\n\nÈ più che ora che tu riceva altro addestramento, quindi la prossima volta che sei a Stormwind dovresti passare da Gakin. Ti starà aspettando.", enHash = "4157a744", vanilla = true },
        objectives = { it = "Presentati da Gakin the Darkbinder, nel Mage Quarter di Stormwind.", enHash = "2a38b56d", vanilla = true },
        reward = { it = "Sono contento che qualcuno sia riuscito a rintracciarti, $N. Cominciavo a temere il peggio. Sarebbe un peccato perderti, dopo tutto il tempo che abbiamo investito su di te.\n\nMa ne parleremo più tardi. Adesso conta solo il tuo addestramento.", enHash = "bb08c03b", vanilla = true },
    },
    [1718] = {
        title = { it = "L'isolano", enHash = "ff8ce451", vanilla = true },
        text = { it = "La tua fama di $Gguerriero:guerriera; cresce, $N. Ora è il momento di misurarti con i tuoi pari e di vedere a che punto sei.\n\nAl largo della costa delle Barrens, a sud di Ratchet, c'è un'isola. Si chiama Fray Island, ed è un luogo dove i guerrieri si incontrano.\n\nSi incontrano, e combattono.\n\nParla con il capo dei guerrieri di Fray Island, Klannoc Macleod. Se ti riterrà $Gdegno:degna;, Klannoc ti guiderà più avanti sulla via del guerriero.\n\nPer raggiungere Fray Island, cerca le secche del banco di sabbia lungo la Merchant Coast.", enHash = "f11d2bd0", vanilla = true },
        objectives = { it = "Parla con Klannoc Macleod.", enHash = "19458329", vanilla = true },
        reward = { it = "Salve, $Gguerriero:guerriera;. Mi fa piacere vedere che sei $Garrivato:arrivata; a Fray Island. Spero che sia di tuo gradimento...", enHash = "e138fa9e", vanilla = true },
    },
    [1719] = {
        title = { it = "La Zuffa", enHash = "3105fe38", vanilla = true },
        text = { it = "Se vuoi imparare da me, prima devi superare la Zuffa. È una sfida che noi di Fray Island offriamo ai guerrieri emergenti che si credono duri, e se riesci a superarla saprò che lo sei davvero.\n\nPer cominciare, entra in mezzo a quella folla laggiù e sali sulla grata. Così Twiggy Flathead saprà che sei $Gpronto:pronta;, e ti manderà contro degli sfidanti.\n\nBatti tutti gli sfidanti e lui chiamerà Big Will. Uccidi Big Will, e torna da me entro il tempo concesso.", enHash = "9627f705", vanilla = true },
        objectives = { it = "Uccidi Big Will, poi parla con Klannoc Macleod, a Fray Island.", enHash = "d62419b3", vanilla = true },
        progress = { it = "Hai completato la tua sfida?", enHash = "8cc974fb", vanilla = true },
        reward = { it = "Ben fatto, $N. Hai superato la Zuffa!\n\nSei $Gun guerriero degno:una guerriera degna;, ed è un onore per me insegnarti...", enHash = "d395221c", vanilla = true },
    },
    [1738] = {
        title = { it = "Heartswood", enHash = "742ca11a", vanilla = true },
        text = { it = "In attesa del tuo arrivo, ho usato la mia vista per scrutare il mondo attraverso le nebbie del tempo. Ho trovato ciò che cerchi.\n\nDurante la Guerra degli Antichi, due amanti caddero insieme in battaglia. Là dove esalarono l'ultimo respiro crebbe un albero noto come Heartswood, simbolo del loro amore eterno.\n\nDovrebbe bastare a tentare una Succubus. Lo troverai tra le rovine di Ordil'Aran, nella parte nord-occidentale della foresta di Ashenvale.", enHash = "5297a70b", vanilla = true },
        objectives = { it = "Recupera l'Heartswood ad Ashenvale e portalo a Gakin the Darkbinder, nel Mage Quarter di Stormwind.", enHash = "3d11be7b", vanilla = true },
        progress = { it = "La tua ricerca ha avuto successo, $N?", enHash = "55cbd6df", vanilla = true },
        reward = { it = "Sì, vedo che andrà benissimo. Lascia che ci lavori un momento...\n\nTakar è un tipo pieno di risorse, vero? Se solo riuscissi a convincerlo a tornare alla civiltà.", enHash = "7d5e981b", vanilla = true },
    },
    [1739] = {
        title = { it = "Il vincolo", enHash = "2a2909d6", vanilla = true },
        text = { it = "Con l'Heartswood Core potrai lanciare un incantesimo nel cerchio di evocazione, nella cripta qui sotto, per aprire un portale da cui la Succubus possa passare.\n\nFa' attenzione, $N: le Succubus hanno sopraffatto anche le menti più forti.\n\nUna volta che l'avrai battuta e rimandata nel vuoto, torna da me e ti mostrerò come richiamarla e controllarla.", enHash = "f9ecc5fe", vanilla = true },
        objectives = { it = "Usando l'Heartswood Core, evoca e sottometti una Succubus, poi riporta l'Heartswood Core a Gakin the Darkbinder, allo Slaughtered Lamb.", enHash = "3ed91b37", vanilla = true },
        progress = { it = "A volte mi chiedo se Surena non fosse una Succubus travestita, mandata a distorcere e confondere la mia mente... Ah! Credo di darle troppo credito.", enHash = "9edfd2ea", vanilla = true },
        reward = { it = "Ben fatto, ben fatto, $N. Vedo che abbiamo fatto bene a decidere di addestrarti. Le tue prove non deludono di certo.\n\nNon ho esitazioni a mostrarti come controllare la Succubus che hai appena vincolato. Osserva con attenzione.", enHash = "99dd8dc1", vanilla = true },
    },
    [1740] = {
        title = { it = "L'Orb of Soran'ruk", enHash = "5075bc2b", vanilla = true },
        text = { it = "Quando i demoni della Legione cadono in disgrazia, i loro spiriti vengono imprigionati in sfere e distribuiti ai loro maghi e stregoni.\n\nMolte furono portate su Azeroth dai loro servitori. Anche in frammenti, possiedono ancora i poteri dei demoni intrappolati al loro interno.\n\nL'Orb of Soran'ruk fu spezzata in due parti: una fu ridotta in pezzi ancora più piccoli, usati dagli accoliti del Martello del Crepuscolo nelle Blackfathom Deeps. L'altra, più grande, era in possesso di un mago di Shadowfang Keep. Trovale e potrò ricomporla.", enHash = "56d7727c", vanilla = true },
        objectives = { it = "Trova 3 Soran'ruk Fragment e 1 Large Soran'ruk Fragment e riportali a Doan Karhan, nelle Barrens.", enHash = "b36ca5f0", vanilla = true },
        progress = { it = "Mi ci sono voluti molti anni per raccogliere i pezzi della sfera di Zargain, ma mi è stata molto utile, come sono sicuro che l'Orb of Soran'ruk sarà utile a te.", enHash = "2f1d9f20", vanilla = true },
        reward = { it = "Sì... La sfera non era molto frammentata, e qui ci sono quasi tutti i pezzi. Ricomporli è una cosa semplice, e Soran'ruk tornerà intera.\n\nHo dedicato la mia vita allo studio delle sfere della Legione Infuocata e alla loro ricostruzione. Mi hai fatto un favore raccogliendo questi pezzi da studiare, e te li restituirò — completamente ricostruiti — nella forma che preferisci.", enHash = "a9db099c", vanilla = true },
    },
    [1758] = {
        title = { it = "Tome of the Cabal", enHash = "3a671d24", vanilla = true },
        text = { it = "Per richiamare un Felhunter da sfidare non basterà un semplice cerchio di evocazione.\n\nI miei tre accoliti e io ti aiuteremo a creare i cerchi magici. Ti serve una copia del Tome of the Cabal, che abbiamo perduto da tempo. Fu scritto dal primo gruppo di stregoni che riuscì a evocare un Felhunter senza aiuto.\n\nForse Krom Stoutarm può aiutarti. Oggi è uno stregone girovago, e passa le giornate ad accumulare testi antichi e ad aggirarsi furtivo nella biblioteca di Ironforge.", enHash = "d8c1a8d1", vanilla = true },
        objectives = { it = "Parla con Krom Stoutarm, a Ironforge.", enHash = "c23c3908", vanilla = true },
        reward = { it = "Il Tome of the Cabal? Mm... mi dice qualcosa. Però qui non l'ho mai visto — e credimi, mi ricordo ogni libro che leggo.\n\nMm...\n\nAh, sì! Ne ho visto dei riferimenti nei cataloghi della biblioteca.", enHash = "81b7385a", vanilla = true },
    },
    [1778] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Vedrò di organizzarmi per tornare presto a casa. Spero che Stephanie stia bene, a Stormwind. Non vedo l'ora di rivederla. Alla prossima, $C.", enHash = "a0aafb93", vanilla = true },
        objectives = { it = "Parla con Tiza Battleforge, a Ironforge.", enHash = "4c136c4c", vanilla = true },
        reward = { it = "Allora, sei $Ggià tornato:già tornata;, eh? E di grazia, cosa hai combinato mentre eri via?\n\nSei $Griuscito:riuscita; ad aiutare una nobile causa? Forse hai imparato il valore della carità, o qualcosa di più sui tuoi doveri verso i cittadini di Azeroth. Dimmi, chi hai aiutato e come... Notevole, $N, queste sono di certo le azioni di chi segue la Luce.\n\nUn simile sacrificio sarà sempre ricompensato, col tempo.", enHash = "372836fd", vanilla = true },
    },
    [1779] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Voglio che tu prenda questo, $N. Si chiama Symbol of Life.\n\nHai dato prova di carità e di pazienza, e ora voglio che tu dimostri quanto sei $Gdiventato:diventata; abile sia nel combattimento sia nel potere.\n\nMio marito Muiredon è tornato di recente da uno scontro con alcuni nani Dark Iron, e ne è uscito vivo per un pelo — è laggiù a farsi curare le ferite da uno dei nostri sacerdoti.\n\nPrendi il Symbol e parla con lui. Se riesci ad aiutarlo, ci parleremo di nuovo presto. Che la Luce risplenda su di te.", enHash = "d3433fe5", vanilla = true },
        objectives = { it = "Prendi il Symbol of Life e parla con Muiredon Battleforge, a Ironforge.", enHash = "72f2c7bb", vanilla = true },
        reward = { it = "*tossisce*\n\nBuongiorno a te, $C. Non badare alle mie ferite, il buon sacerdote qui si prenderà cura del vecchio Muiredon a tempo debito. Non ho ancora bisogno del potere di quel Symbol of Life che hai lì.\n\nAllora, mia moglie ti ha mandato qui a parlare con me, eh? D'accordo. Mi prenderò il tempo di parlarti — ti racconterò esattamente cos'è successo a Muiredon e al suo migliore amico Narm, un paladino proprio come te.", enHash = "533c483a", vanilla = true },
    },
    [1780] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Porterò queste cose ai bambini oggi stesso. Ti prego, sta' $Gattento:attenta;, $Gbuon:buona; $C. Non capita spesso che $Guomini:donne; della tua levatura si facciano vedere in città, ma hai dimostrato che i paladini qui a Stormwind non volteranno mai le spalle a chi ha bisogno.\n\nAddio.", enHash = { "8f6b2866", "279a3a4e" }, vanilla = true },
        objectives = { it = "Parla con Duthorian Rall, a Stormwind.", enHash = "b20f83f0", vanilla = true },
        reward = { it = "Sei $Gtornato:tornata; così in fretta, $N. E cosa hai combinato mentre eri $Glontano:lontana; dalla Cathedral?\n\nHai aiutato una nobile causa? Forse hai imparato il valore della carità, o qualcosa di più sui tuoi doveri verso i cittadini di Azeroth. Dimmi, chi hai aiutato e come... Be', sono colpito, $N, queste sono di certo le azioni di chi segue la Luce e mette gli altri prima di sé.\n\nUn simile sacrificio sarà sempre ricompensato, col tempo.", enHash = "277b158f", vanilla = true },
    },
    [1781] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Prendi questo, $N. Si chiama Symbol of Life.\n\nHai dato prova di carità e di pazienza, e ora è giunto il momento di vedere se sei abbastanza potente da concentrare uno dei più grandi doni della Luce.\n\nIl mio amico Gazin è tornato di recente da uno scontro con alcuni Defias a Elwynn, vicino all'Heroes' Vigil — ne è uscito vivo per un pelo. È vicino all'altare a farsi curare le ferite dai nostri sacerdoti.\n\nPrendi il Symbol e parla con lui. Se riesci ad aiutarlo, ci parleremo di nuovo presto. Che tu possa crogiolarti nella gloria della Luce.", enHash = "0044ea7e", vanilla = true },
        objectives = { it = "Porta il Symbol of Life a Gazin Tenorm, a Stormwind.", enHash = "2a6b6e8a", vanilla = true },
        reward = { it = "*tossisce*\n\nPiacere di conoscerti, $C. Non badare alle mie ferite, il buon sacerdote qui stavolta si prenderà cura del vecchio Gazin. Non avrò bisogno del potere di quel Symbol of Life che hai lì... non ancora, almeno.\n\nAllora, ti ha mandato Duthorian a parlare con me, eh? D'accordo. Ti racconterò esattamente cosa è capitato a me e al mio amico Henze. E con un po' di fortuna, e un po' di abilità da parte tua, forse puoi ancora aiutarci tutti.", enHash = "bbb4b3f3", vanilla = true },
    },
    [1782] = {
        title = { it = "L'armatura di Furen", enHash = "c38002b7", vanilla = true },
        reward = { it = "Ecco la tua armatura, $N. Reggerà agli assalti più violenti, o non mi chiamo Furen Longbeard!\n\nE devo ringraziarti. Ho imparato molto lavorando con i materiali\nche mi hai portato. Credo che un giorno farò un'altra scoperta!\n\nManderò quello che ho imparato ad altri\nfabbri dell'Alleanza.\n\nDirò loro che mi sei $Gstato:stata; di grande aiuto, e magari vorranno ricambiare il favore.", enHash = "82c7af1a", vanilla = true },
    },
    [1783] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Stavamo spiando alcuni dei nani Dark Iron che si sono trincerati a sud dell'Helm's Bed Lake. Sapevamo che stavano tramando qualcosa, così Narm e io abbiamo pensato di dare un'occhiata più da vicino — siamo riusciti a vedere il loro capo che dava ordini ad alcuni dei suoi uomini.\n\nNarm e io ne abbiamo approfittato per farne fuori qualcuno, ma si sono rivelati più duri del previsto, e altri di loro ci sono piombati addosso. Narm mi ha detto di scappare e di andare a cercare rinforzi, ed eccomi qui.\n\nNarm ha bisogno di aiuto, e non avrò pace finché non l'avrà avuto.\n\nPuoi dare una mano, $N?", enHash = "1c11b2de", vanilla = true },
        objectives = { it = "Prendi il Symbol of Life e riporta in vita Narm Faulk, a Dun Morogh.", enHash = "e2e991e6", vanilla = true },
        reward = { it = "Non so come ringraziarti, $Gfratello:sorella;.\n\nSe porti il Symbol of Life, posso solo pensare che ti abbiano mandato qui Tiza e Muiredon ad aiutarmi.\n\nÈ vero, sono caduto per mano dei Dark Iron mentre cercavo di prendere uno dei loro documenti: ho resistito abbastanza a lungo da permettere a Muiredon di fuggire, ma la Luce mi aveva quasi del tutto accolto quando sei $Garrivato:arrivata; tu. Il fatto che tu sia $Gstato:stata; abbastanza potente da usare il Symbol significa grandi cose per te, ma ci sarà tempo per parlarne più avanti.", enHash = { "991eb9f7", "3c46af65" }, vanilla = true },
    },
    [1784] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Prima che cadessi in battaglia, Muiredon e io avevamo quasi sconfitto una delle spie Dark Iron vicino a quella casetta. Avevamo visto il loro capitano passare degli ordini alle spie, e abbiamo cercato di ucciderlo e di prendere gli ordini.\n\nAlcuni membri del consiglio di Ironforge non credono ancora che a Dun Morogh ci siano nani Dark Iron. Se prendiamo uno di quei documenti, non solo avremo la prova dei loro movimenti, ma forse anche un'idea di cosa stanno tramando.\n\nPrendi uno di quei documenti e portalo a Muiredon, $N.", enHash = "9ce56ee2", vanilla = true },
        objectives = { it = "Recupera un Dark Iron Script dai nani Dark Iron vicino all'Helm's Bed, e torna da Muiredon Battleforge, a Ironforge.", enHash = "7b77070e", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata;! Mi fa piacere vederti, $N. Le mie ferite sono guarite e sono quasi pronto a tornare all'Helm's Bed Lake, appena riesco a convincere mia moglie che starò bene.", enHash = "b8eaa039", vanilla = true },
        reward = { it = "Ah ah! Ce l'hai fatta! Hai salvato Narm, e hai trovato la prova che serve a mia moglie da portare al consiglio. Sei una benedizione della Luce, se mai ne ho vista una... senza contare mia moglie, s'intende.\n\nGrazie ancora, $N.", enHash = "a1bb5d92", vanilla = true },
    },
    [1785] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Vedo che mia moglie laggiù è già raggiante d'orgoglio. Faresti meglio a portare le tue chiappe laggiù, e alla svelta. Credo proprio che voglia dirti qualcosa.\n\nLa Luce sia con te, possente $C. Ti cercherò sul campo di battaglia contro il Flagello e quei Dark Iron, quando verrà il momento.", enHash = "829fd0ac", vanilla = true },
        objectives = { it = "Parla con Tiza Battleforge, a Ironforge.", enHash = "4c136c4c", vanilla = true },
        reward = { it = "Oggi hai fatto un grande favore a tutta Ironforge, $N. Sono fiera di annoverarti tra noi, e se ti senti $Gpronto:pronta;, vorrei benedirti con questa pergamena. Il Symbol of Life avrebbe funzionato solo nelle mani di un paladino pronto per una delle più grandi benedizioni della Luce — il potere di riportare in vita i morti.\n\nTi insegnerò l'abilità di resuscitare i tuoi compagni. Usala con saggezza, $N, e grazie, a nome mio, di mio marito e di Ironforge.", enHash = "d64e7822", vanilla = true },
    },
    [1786] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Henze e io eravamo arrivati all'Heroes' Vigil, un'isola in mezzo allo Stone Cairn Lake, nel nord-est di Elwynn. Avevamo sentito che i Defias si erano infiltrati oltre i nostri confini, e volevamo una prova da portare ai consiglieri del re.\n\nAbbiamo avvistato un paio di quei farabutti che esaminavano dei documenti, e li abbiamo attaccati. Purtroppo siamo stati presto sopraffatti da altri maghi.\n\nHenze li ha trattenuti per me mentre scappavo... quello sciocco, a fare il coraggioso.\n\nÈ ancora là fuori, Henze. Puoi aiutarci, $N?", enHash = "2f3cb32f", vanilla = true },
        objectives = { it = "Prendi il Symbol of Life e riporta in vita Henze Faulk, a Elwynn.", enHash = "69c461f8", vanilla = true },
        reward = { it = "Grazie, $Gfratello:sorella;.\n\nVisto che impugni il Symbol of Life, posso supporre che ti abbiano mandato Duthorian o Gazin?\n\nSono caduto per mano degli incantatori Defias mentre Gazin e io cercavamo di sottrarre loro i piani: ho resistito abbastanza a lungo da permettere a Gazin di fuggire, ma alla fine la loro magia mi ha sopraffatto.\n\nMa tu sei $Griuscito:riuscita; a riportarmi indietro: la capacità di usare il Symbol non è concessa a chiunque, $N. È di buon auspicio per te che tu sia $Griuscito:riuscita; a caricarlo con la tua fede.", enHash = { "4db94fb7", "413b8935" }, vanilla = true },
    },
    [1787] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Avremo tempo di parlare ancora del Symbol più avanti. Ora l'importante è prendere quelle carte che abbiamo visto esaminare dai Defias. Se riusciamo a metterci le mani sopra, potremo dimostrare che i Defias si sono infiltrati a Elwynn, e magari capire qualcosa dei loro piani.\n\nPer ora non sono in condizioni di combattere, $N. Pensi di essere abbastanza forte da prendere quelle carte ai Defias qui sull'isola?\n\nSe riesci a prenderle, portale a Gazin e digli che sto bene.", enHash = "fc43aae4", vanilla = true },
        objectives = { it = "Recupera un Defias Script dai Defias Rogue Wizard a Elwynn, e torna da Gazin Tenorm, a Stormwind.", enHash = "4716f2d0", vanilla = true },
        progress = { it = "Henze è salvo, $N? Ci sei $Griuscito:riuscita;?\n\nTra la tua abilità con le armi e il potere della Luce, immagino che l'Heroes' Vigil sia al sicuro da qualunque minaccia dei Defias, ma questo spetta al Re e ai suoi consiglieri dirlo.", enHash = "e8147f95", vanilla = true },
        reward = { it = "Magnifico! Ce l'hai fatta, e hai salvato Henze. La Luce è con te, non c'è dubbio, $N!", enHash = "60e549d5", vanilla = true },
    },
    [1788] = {
        title = { it = "Il Tome of Divinity", enHash = "0f9ce023", vanilla = true },
        text = { it = "Porterò il documento ai consiglieri del re dopo che Duthorian gli avrà dato un'occhiata, ma nel frattempo dovresti andare a parlare con Duthorian. Vorrà di sicuro darti una pacca sulla spalla!\n\nGrazie ancora, $N. Spero che ci rivedremo. Sei di sicuro $Gun alleato:un'alleata; che sono fiero di chiamare $Gamico:amica;.", enHash = "82263cce", vanilla = true },
        objectives = { it = "Parla con Duthorian Rall, a Stormwind.", enHash = "b20f83f0", vanilla = true },
        reward = { it = "Oggi hai fatto un buon lavoro, $N. Dovresti andare un po' $Gfiero:fiera; di quello che hai realizzato.\n\nE ancora di più dovresti essere $Gfiero:fiera; delle tue capacità. Non tutti possono usare il potere del Symbol of Life. Invocare la Luce per riportare indietro i morti significa che sei $Gpronto:pronta; per uno dei più grandi onori del paladino: il potere della resurrezione.\n\nAvrai il potere di riportare indietro i compagni caduti, proprio come hai fatto con Henze.\n\nStammi bene, $N. La Luce risplende su di te, e dovresti accoglierla del tutto.", enHash = "5180e035", vanilla = true },
    },
    [1789] = {
        title = { it = "Il Symbol of Life", enHash = "9e8a10ac", vanilla = true },
        reward = { it = "Affrettati, $N: se fallisci, più di una vita è in pericolo.\n\nSe per qualche motivo non riesci ad aiutare Muiredon e Narm, torna da me e ti darò un altro Symbol of Life per il viaggio.\n\nNon scambiare il mio aiuto per semplice carità: devi dimostrarti $Gdegno:degna; come $Gqualunque altro:qualunque altra; $C, e i fallimenti continui potrebbero ricadere su di te più avanti.", enHash = "37db22ab", vanilla = true },
    },
    [1790] = {
        title = { it = "Il Symbol of Life", enHash = "9e8a10ac", vanilla = true },
        reward = { it = "Affrettati, $N: se fallisci, più di una vita è in pericolo.\n\nSe per qualche motivo non riesci ad aiutare Gazin e Henze, torna da me e ti darò un altro Symbol of Life per il viaggio.\n\nNon scambiare il mio aiuto per semplice carità: devi dimostrarti $Gdegno:degna; come $Gqualunque altro:qualunque altra; $C, e i fallimenti continui potrebbero ricadere su di te più avanti.", enHash = "ee7ac4bb", vanilla = true },
    },
    [1791] = {
        title = { it = "Il Windwatcher", enHash = "7e54db85", vanilla = true },
        text = { it = "Ora che hai imparato la Berserker Stance, ti servirà una bella arma da usare con quella.\n\nParla con Bath'rah the Windwatcher, un eremita troll che vive tra le Alterac Mountains e le Western Plaguelands. È un abile fabbricante d'armi e un potente sciamano.\n\nPer trovare Bath'rah, raggiungi il fiume che scorre lungo il fianco orientale di Tarren Mill. Seguilo verso nord: Bath'rah è accampato vicino a delle rovine sulla riva est del fiume.", enHash = "d0731bae", vanilla = true },
        objectives = { it = "Parla con Bath'rah the Windwatcher.", enHash = "09338f38", vanilla = true },
        reward = { it = "Hai viaggiato a lungo, $Ggiovane guerriero:giovane guerriera;. Vedo fuoco nei tuoi occhi. Cerchi un'arma di grande potere, vero?\n\nPosso aiutarti nella tua ricerca. E tu puoi aiutare me nella mia.", enHash = "be7e05e9", vanilla = true },
    },
    [1792] = {
        title = { it = "L'arma del turbine", enHash = "94948a02", vanilla = true },
        reward = { it = "Ho il Whirlwind Heart, e sono pronto a infonderlo nell'arma che sceglierai.\n\nScegli la tua arma, $N, e sappi che il suo potere è il potere di Cyclonian.", enHash = "c8e6cc6c", vanilla = true },
    },
    [1793] = {
        title = { it = "Il Tome of Valor", enHash = "f377d3f9", vanilla = true },
        reward = { it = "È stato dimostrato che la Luce è con te, $N, ma man mano che i tempi si fanno più pericolosi, diventa importante sapere quale forza si nasconde sotto la carne. Quando demoni, draghi o qualunque altro male metteranno piede nelle tue terre, la tua tempra sarà messa alla prova. Sarai abbastanza forte?\n\nIl coraggio, qualunque sia la situazione, fa parte dell'essere paladino quanto la Luce, la tua armatura e la tua arma. Proteggere i deboli e non perdere la fede sono altre due lezioni che dovrai padroneggiare mentre studi nella Cathedral of Light.", enHash = "e0b2bd7a", vanilla = true },
    },
    [1794] = {
        title = { it = "Il Tome of Valor", enHash = "f377d3f9", vanilla = true },
        reward = { it = "È stato dimostrato che la Luce è con te, $N, ma man mano che i tempi si fanno più pericolosi, diventa importante sapere quale forza si nasconde sotto la carne. Quando demoni, draghi o qualunque altro male metteranno piede nelle tue terre, la tua tempra sarà messa alla prova. Sarai abbastanza forte?\n\nIl coraggio, qualunque sia la situazione, fa parte dell'essere paladino quanto la Luce, la tua armatura e la tua arma. Proteggere i deboli e non perdere la fede sono altre due lezioni che dovrai padroneggiare mentre studi nella Cathedral of Light.", enHash = "e0b2bd7a", vanilla = true },
    },
    [1795] = {
        title = { it = "Il vincolo", enHash = "2a2909d6", vanilla = true },
        text = { it = "Se sei abbastanza $Gpreparato:preparata;, possiamo cominciare. Lascia che ti spieghi il procedimento.\n\nComincerò creando il cerchio di evocazione di base. Quando sarà finito, i miei accoliti useranno i Rod of Channeling per creare il cerchio maggiore.\n\nFatto questo, leggi l'incantesimo dal Tome of the Cabal, e il Felhunter verrà richiamato. Fa' attenzione, $N. Un Felhunter è un avversario potente, e mi piacerebbe vederti con la testa ancora sulle spalle.", enHash = "cbff6d6f", vanilla = true },
        objectives = { it = "Usando il Tome of the Cabal, evoca e sottometti un Felhunter, poi riporta il Tome of the Cabal a Strahad Farsan, a Ratchet.", enHash = "004337ba", vanilla = true },
        progress = { it = "Ogni stregone dovrebbe avere un Felhunter ai suoi ordini. Anche se è difficile da domare, i poteri che dà al suo padrone valgono ben più del prezzo.", enHash = "480c706d", vanilla = true },
        reward = { it = "Devo dire che sono colpito, $N. Quando affrontai il mio Felhunter, me la cavai per un pelo. Sento che hai il potenziale per diventare $Guno degli stregoni più potenti:una delle streghe più potenti; di quest'epoca.", enHash = "15ddd7a8", vanilla = true },
    },
    [1798] = {
        title = { it = "In cerca di Strahad", enHash = "07e01085", vanilla = true },
        text = { it = "È ora che tu impari a evocare il Felhunter, $N. Qui non ho i reagenti e gli oggetti necessari per insegnartelo, quindi dovrai cercare qualcun altro, Strahad Farsan, anche lui della nostra cerchia ristretta.\n\nAbita nel porto goblin di Ratchet. Gli manderò un messaggio per avvisarlo del tuo arrivo.", enHash = "4591d9d1", vanilla = true },
        objectives = { it = "Parla con Strahad Farsan, nelle Barrens.", enHash = "085dbfc7", vanilla = true },
        reward = { it = "$N? Ah, certo. Il nostro ultimo prodigio. Temo che la realtà non sia all'altezza della leggenda.\n\nNon importa: sei qui per imparare, non per sentirmi fare battute a me stesso.", enHash = "1937424e", vanilla = true },
    },
    [1800] = {
        title = { it = "Lordaeron Throne Room", enHash = "42ac720b", vanilla = true },
        text = { it = "Le matrone dell'orfanotrofio dove vivo, la sera, ci raccontano grandi storie di battaglie e di leggende, se siamo stati buoni e abbiamo fatto le faccende. Una storia parlava di come cadde Lordaeron, e di come il malvagio Arthas tolse la vita a suo padre per diventare sovrano.\n\nNon aveva onore, $N! Quando sarò grande e diventerò un grande guerriero dell'Orda, la mia lama sarà guidata dall'onore, mai dal male!\n\nMi porteresti a vedere la sala del trono, per piacere? È proprio prima di dove si scende nell'Undercity.", enHash = "3017cf93", vanilla = true },
        objectives = { it = "Porta il tuo protetto alla vecchia Lordaeron Throne Room, che si trova poco prima della discesa nell'Undercity.", enHash = "570a9e0d", vanilla = true },
        progress = { it = "Siamo arrivati?", enHash = "5cf70a59", vanilla = true },
        reward = { it = "Quella sala del trono faceva paura, $N! Anche se era vuota, sembrava che lì fosse successo un grande male. Mi sono sentito arrabbiato... ma anche triste. Capisco perché le matrone ci raccontano storie così: io non tradirò mai il mio popolo in quel modo!\n\nGrazie di avermi portato nella sala del trono, $N. Ho imparato tante cose.", enHash = "07a9de38", vanilla = true },
    },
    [1801] = {
        title = { it = "Tome of the Cabal", enHash = "3a671d24", vanilla = true },
        text = { it = "Per richiamare un Felhunter da sfidare non basterà un semplice cerchio di evocazione.\n\nI miei tre accoliti e io ti aiuteremo a creare i cerchi magici. Ti serve una copia del Tome of the Cabal, che abbiamo perduto da tempo. Fu scritto dal primo gruppo di stregoni che riuscì a evocare un Felhunter senza aiuto.\n\nForse Jorah Annison può aiutarti. Oggi lavora come cartografo nell'Undercity, ma di testi antichi ne sa più di chiunque io conosca.", enHash = "8a9009c2", vanilla = true },
        objectives = { it = "Parla con Jorah Annison, nell'Undercity.", enHash = "dd4a86c7", vanilla = true },
        reward = { it = "Fare mappe! Immagini, stime della realtà. Non so che farmene.\n\nNei libri, nel racconto, nella descrizione! È lì che sta la verità. Darei tutte le mappe di questo negozio per un solo libro sull'ascesa della negromanzia, o per un racconto del trionfo della Signora Oscura.", enHash = "dab1aff9", vanilla = true },
    },
    [1802] = {
        title = { it = "Tome of the Cabal", enHash = "3a671d24", vanilla = true },
        text = { it = "È andato perduto, ma c'è qualche idea su dove si possa trovare.\n\nNe fu fatta una sola copia, che a un certo punto venne danneggiata: una buona parte fu strappata dalla rilegatura. Si dice che in qualche modo sia finita nelle mani dei centauri delle Thousand Needles.\n\nIl resto andò perduto al largo della costa a ovest di Southshore, mentre veniva trasportato in nave a Menethil Harbor. Non arrivò mai.\n\nIn cambio di queste informazioni ti chiedo solo una cosa: se lo trovi, portamelo, così posso vederlo.", enHash = "aefcf36b", vanilla = true },
        objectives = { it = "Recupera il Moldy Tome e il Tattered Manuscript per Krom Stoutarm, a Ironforge.", enHash = "91090e48", vanilla = true },
        progress = { it = "Le voci si sono rivelate vere, $N?", enHash = "8bdc4dc5", vanilla = true },
        reward = { it = "Fantastico! Ora potrò unirmi ai pochi che ne hanno sbirciato il contenuto.\n\nNon vedo l'ora di studiare meglio questo testo. È un gran giorno, $N! Lasciami solo dargli un'occhiata prima che tu te ne vada. Sono sicuro che Strahad sarà disposto a mandarmene una copia.", enHash = "982fa70d", vanilla = true },
    },
    [1803] = {
        title = { it = "Tome of the Cabal", enHash = "3a671d24", vanilla = true },
        text = { it = "Ah! Vedo che sei $Gun stregone:una strega; con gusti simili ai miei. Procurarsi il Tome of the Cabal è davvero un'aspirazione degna. Sapevi che un tempo era custodito tra le mura di Lordaeron? Però fu danneggiato, e quasi metà delle pagine venne strappata. Chi commetterebbe un atto così infame?\n\nQuella metà è perduta, anche se si dice che sia finita nelle mani dei centauri delle Thousand Needles.\n\nIl resto del testo doveva essere trasferito a Ironforge, ma andò perduto durante il viaggio, sulla costa a ovest di Southshore.", enHash = "fab0a805", vanilla = true },
        objectives = { it = "Recupera il Moldy Tome e il Tattered Manuscript per Jorah Annison, nell'Undercity.", enHash = "232abc07", vanilla = true },
        progress = { it = "Può darsi che tu stia inseguendo delle favole, $N, ma un fondo di verità si trova anche nelle voci più assurde.", enHash = "6e8aa994", vanilla = true },
        reward = { it = "Bene bene bene! Cosa abbiamo qui?\n\nÈ notevole, $N. Non l'avrei creduto possibile, eppure eccolo qui, nelle mie mani: il Tome of the Cabal completo.\n\nLasciami sfogliare le sue pagine solo un momento, prima che tu riparta.", enHash = "1e40f953", vanilla = true },
    },
    [1804] = {
        title = { it = "Tome of the Cabal", enHash = "3a671d24", vanilla = true },
        text = { it = "Beh, ecco, è difficile lasciarlo andare. Ma l'hai trovato tu, e hai cose più importanti da farci, naturalmente. Solo, ti prego, ricordati di dire a Strahad che ne volevo una copia.\n\nMentre eri via, ti ha mandato un messaggio. Voleva che ti dicessi che, perché i suoi accoliti possano aiutarti con l'evocazione, dovrai procurarti tre Rod of Channeling.\n\nLui forse non sa dove trovarli, ma io sì! Gli ultimi a usarli sono stati gli orchi del clan Dragonmaw, nelle Wetlands. Io controllerei i loro incantatori!", enHash = "f8a06ee2", vanilla = true },
        objectives = { it = "Porta il Reconstructed Tome e 3 Rod of Channeling a Strahad Farsan, a Ratchet.", enHash = "af066be0", vanilla = true },
        progress = { it = "È da un po' che non ti vedo da queste parti. Hai trovato il tomo e le verghe?", enHash = "b998825e", vanilla = true },
        reward = { it = "Ben fatto! Il Tome of the Cabal e tre Rod of Channeling in perfetto stato — be', un po' graffiati, direi.\n\nSarà interessante. È da tempo che $Gun giovane stregone:una giovane strega; non affronta un Felhunter per farlo suo.", enHash = "1f06bfe6", vanilla = true },
    },
    [1805] = {
        title = { it = "Tome of the Cabal", enHash = "3a671d24", vanilla = true },
        text = { it = "È uno dei testi più interessanti che abbia letto negli ultimi anni. Qui la scelta è scarsa — soprattutto libri di geografia — e li ho già letti tutti. Spero che Strahad mi mandi una copia di questo tomo quando potrà.\n\nA proposito di lui, mentre eri via mi ha mandato un messaggio. Per il tuo compito devi procurarti tre Rod of Channeling.\n\nPer avermi lasciato guardare questo testo, ti svelerò un segreto: le verghe le trovi sugli orchi del clan Dragonmaw, nelle Wetlands.", enHash = "c58681b4", vanilla = true },
        objectives = { it = "Porta il Reconstructed Tome e 3 Rod of Channeling a Strahad Farsan, a Ratchet.", enHash = "af066be0", vanilla = true },
        progress = { it = "Sì, $N? In cosa posso esserti utile?", enHash = "33830c93", vanilla = true },
        reward = { it = "Ben fatto! Il Tome of the Cabal e tre Rod of Channeling in perfetto stato — be', un po' graffiati, direi.\n\nSarà interessante. È da tempo che $Gun giovane stregone:una giovane strega; non affronta un Felhunter per farlo suo.", enHash = "1f06bfe6", vanilla = true },
    },
    [1806] = {
        title = { it = "La prova della rettitudine", enHash = "4426ce11", vanilla = true },
        text = { it = "Perché non andiamo alla forgia e cominciamo? È da un po' che mi preparo al tuo arrivo, quindi non ci vorrà molto.\n\nQuando avremo finito, sarai molto più $Gpronto:pronta; di prima a difendere la Luce, questo te lo giuro.\n\nTi confesso una cosa, $N: vedere i frutti delle tue imprese mi rende un po' invidioso. Ma sapere che posso dare alle tue avventure un contributo tutto mio, e non da poco, mi rende contento.", enHash = "a83801a7", vanilla = true },
        objectives = { it = "Aspetta che Jordan Stilwell finisca di forgiare un'arma per te.", enHash = "e8e8fd13", vanilla = true },
        reward = { it = "Eccola, $N. Un'arma degna di $Gun campione:una campionessa; della Luce come te. Le ho dato il nome di un grande paladino nanico, un mio amico. Si chiamava Verigan... Bosch Verigan.\n\nTi prego, accettala da parte mia e di mia moglie. Abbiamo un grande debito con te, e il mondo sarà un posto più sicuro con qualcuno abile come te in giro per queste terre.", enHash = "341fc97c", vanilla = true },
    },
    [1818] = {
        title = { it = "Parla con Dillinger", enHash = "9378d99e", vanilla = true },
        text = { it = "Mi hanno detto che Deathguard Dillinger ha un lavoro per qualcuno come te. Se vuoi dimostrare il tuo valore alle forze della Signora Oscura, presentati subito da Dillinger.\n\nDeathguard Dillinger è di guardia all'estremità ovest di Brill, vicino al cimitero.", enHash = "09883bd6", vanilla = true },
        objectives = { it = "Parla con Deathguard Dillinger, a Brill.", enHash = "79b14277", vanilla = true },
        reward = { it = "Sei qui per una missione? Bene. Ne ho una importante, che metterà alla prova la tua abilità in combattimento... e la tua determinazione nel difendere i Reietti.", enHash = "0c05f619", vanilla = true },
    },
    [1819] = {
        title = { it = "Ulag the Cleaver", enHash = "e5deb76c", vanilla = true },
        text = { it = "Quando il Flagello dilagò nelle Tirisfal Glades, ne catturammo uno per studiarlo. Aveva una mente libera, e si faceva chiamare Ulag the Cleaver. Ma, anche se la sua volontà era libera, era ancora soggiogato dal Re dei Lich.\n\nSperavamo di trovare un modo per spezzare il controllo del re su Ulag, ma abbiamo fallito. Ora, finalmente, è il momento di liberarlo.\n\nLiberalo, e uccidilo.\n\nAttiva il meccanismo della pietra a forma di teschio vicino al mausoleo, a nord. Solleverà il sigillo magico che lo tiene prigioniero.\n\nPoi... tieniti $Gpronto:pronta;, $N.", enHash = "c3b5f9e2", vanilla = true },
        objectives = { it = "Uccidi Ulag the Cleaver, poi parla con Deathguard Dillinger.", enHash = "75b0a808", vanilla = true },
        progress = { it = "Il tuo compito non è ancora compiuto, $N. Non è saggio per un guerriero mostrare paura...", enHash = "68d10a6e", vanilla = true },
        reward = { it = "Ben fatto, $N. Ulag non era un agente qualsiasi del Flagello. Hai dimostrato ai Guardiamorte, e quindi alla Signora Oscura, di essere $Gun guerriero:una guerriera; di abilità e determinazione, e di meritare un ulteriore addestramento.", enHash = "70dfd65d", vanilla = true },
    },
    [1820] = {
        title = { it = "Parla con Coleman", enHash = "a1cd0c89", vanilla = true },
        text = { it = "Hai dimostrato il tuo valore alla Signora Oscura; ora forse puoi dimostrarlo a uno dei suoi sudditi.\n\nColeman Farthing aspetta un guerriero disposto a essere lo strumento della sua vendetta contro i nemici dei Reietti.\n\nLo troverai alla Gallows' End Tavern, nella parte est di Brill.", enHash = "f431e96d", vanilla = true },
        objectives = { it = "Parla con Coleman Farthing.", enHash = "3f799000", vanilla = true },
        reward = { it = "Sì, è vero. Ho bisogno delle tue abilità in combattimento. I miei mezzi sono pochi, ma il mio compito aiuta sia me sia la causa dei Reietti. Fallo, e la tua ricompensa sarà doppia.", enHash = "4e29827c", vanilla = true },
    },
    [1821] = {
        title = { it = "I cimeli degli Agamand", enHash = "9cde9a31", vanilla = true },
        text = { it = "Lavoravo per la famiglia Agamand quando ero in vita, e sono stati loro la causa della mia morte! È giusto che ora gli Agamand siano servitori senza mente del Re dei Lich.\n\nOra voglio prendermi quel che resta del loro onore. Entra nella loro cripta di famiglia e deruba gli Agamand dei cimeli di famiglia: una spada, un'ascia, un pugnale e una mazza. Portameli!\n\nLa cripta della famiglia Agamand si trova all'estremità nord degli Agamand Mills, protetta dal Flagello in agguato e dagli Agamand morti.", enHash = "611cacc7", vanilla = true },
        objectives = { it = "Porta a Coleman Farthing l'Agamand Family Axe, l'Agamand Family Sword, l'Agamand Family Mace e l'Agamand Family Dagger.", enHash = "81c3c892", vanilla = true },
        progress = { it = "Hai i cimeli, $N?", enHash = "2c225da6", vanilla = true },
        reward = { it = "Ah! Li hai recuperati! Ora l'ultima parvenza di onore e di memoria è strappata alle maledette terre degli Agamand. La famiglia non esiste davvero più!", enHash = "4fad7f23", vanilla = true },
    },
    [1822] = {
        title = { it = "L'arma di famiglia", enHash = "8cf1e1d5", vanilla = true },
        reward = { it = "Terrò tre delle armi che mi hai riportato, come ricordo del mio dolore e della mia perdita. Ma ti prego, $N, scegli il cimelio che preferisci e tienilo per te.\n\nChe ti serva meglio di quanto abbia servito i suoi maledetti vecchi proprietari.", enHash = "44b380e5", vanilla = true },
    },
    [1823] = {
        title = { it = "Parla con Ruga", enHash = "2a4d66a9", vanilla = true },
        text = { it = "Sei $Gun guerriero:una guerriera; di talento e di fama crescente. Forse sei $Gpronto:pronta; per la prova di Ruga Ragetotem? Se è così, trova Ruga a Camp Taurajo, nelle Barrens.\n\nAspetta i guerrieri che rispondono alla sua chiamata.", enHash = "ded821a3", vanilla = true },
        objectives = { it = "Parla con Ruga Ragetotem.", enHash = "39a8d7f1", vanilla = true },
        reward = { it = "Sei qui per la mia prova, $N?", enHash = "4b9c7d05", vanilla = true },
    },
    [1824] = {
        title = { it = "La prova al Field of Giants", enHash = "447a093f", vanilla = true },
        text = { it = "Per superare questa prova, devi andare a sud, nel Field of Giants. Lì troverai una moltitudine di creature striscianti simili a insetti. Sono arrivate da poco nelle Barrens, e non mi piace ciò che annunciano.\n\nPortami le loro antenne ancora frementi, e non perdere tempo, $N, perché le antenne raccolte non fremono a lungo. Portami le antenne entro il tempo stabilito e avrai superato la prova.", enHash = "bdb9def2", vanilla = true },
        objectives = { it = "Porta 5 Twitching Antenna a Ruga Ragetotem, a Camp Taurajo.", enHash = "35001acc", vanilla = true },
        progress = { it = "Hai le antenne? Se sì, dammele in fretta, perché le antenne frementi non fremono per sempre...", enHash = "52d0f000", vanilla = true },
        reward = { it = "Ottimo lavoro, $N! Superando la prova al Field of Giants, fai un altro passo lungo la via $Gdel:della; $C.", enHash = "828e815d", vanilla = true },
    },
    [1825] = {
        title = { it = "Parla con Thun'grim", enHash = "4bbb4f3d", vanilla = true },
        text = { it = "Thun'grim Firegaze, un famoso fabbro orco, ha sentito parlare delle tue continue imprese valorose al servizio dell'Orda. Vorrebbe forgiarti un'armatura, e ti chiede di andare subito a parlare con lui.\n\nL'accampamento di Thun'grim è a est del Crossroads, nelle Barrens.", enHash = "729b673c", vanilla = true },
        objectives = { it = "Parla con Thun'grim Firegaze, nelle Barrens.", enHash = "917657cb", vanilla = true },
        reward = { it = "Sì, sei $Gvenuto:venuta;. Bene, perché abbiamo molto di cui discutere, io e te.", enHash = "a675c91d", vanilla = true },
    },
    [1838] = {
        title = { it = "L'armatura brutale", enHash = "fe065cf9", vanilla = true },
        text = { it = "Ho sentito racconti sulla tua forza e sul tuo valore, e voglio farti un'armatura, una compagna che ti aiuti mentre crescono i racconti delle tue grandi imprese.\n\nMa forgiare questa armatura sarà un'impresa a sé, $N. Mi servirà il tuo aiuto, e quello di altri fabbri dell'Orda.\n\nEcco, prendi questa pergamena. Ho passato molte notti, lottando con i miei occhi quasi ciechi, a scriverci ciò che mi serve per l'armatura. Portami gli oggetti di questa pergamena e ti creerò il primo pezzo.", enHash = "536a551e", vanilla = true },
        objectives = { it = "Porta a Thun'grim Firegaze 15 Smoky Iron Ingot, 10 Powdered Azurite, 10 Iron Bar e una Vial of Phlogiston.", enHash = "2c1c0c54", vanilla = true },
        progress = { it = "Hai gli oggetti della mia pergamena, $N?", enHash = "1f482490", vanilla = true },
        reward = { it = "Hai portato tutto quello che ho chiesto. Ora farò la mia parte...", enHash = "5ecae2b2", vanilla = true },
    },
    [1839] = {
        title = { it = "Ula'elek e i Brutal Gauntlets", enHash = "513e2de1", vanilla = true },
        text = { it = "Il fabbro troll Ula'elek ti forgerà i Brutal Gauntlets. Vive in Durotar, a Sen'jin Village, con i suoi fratelli Darkspear, e aspetta il tuo arrivo.", enHash = "a3489891", vanilla = true },
        objectives = { it = "Parla con Ula'elek, in Durotar.", enHash = "3f6f0048", vanilla = true },
        reward = { it = "Salve, $N. Il vecchio Thun'grim mi ha avvisato del tuo arrivo, ma anche se non avesse detto niente, la tua presenza qui non mi avrebbe sorpreso.\n\nGli spiriti seguono i tuoi progressi, giovane $C, e mi dicono che molti nemici sono caduti davanti a te.", enHash = "4f89ed17", vanilla = true },
    },
    [1840] = {
        title = { it = "Orm Stonehoof e il Brutal Helm", enHash = "8b837379", vanilla = true },
        text = { it = "Orm Stonehoof è molto rispettato per la sua abilità. Sarà lui a farti il Brutal Helm.\n\nCercalo a Thunder Bluff, vicino alla pozza accanto al grande totem centrale della città.", enHash = "69da5e07", vanilla = true },
        objectives = { it = "Parla con Orm Stonehoof, a Thunder Bluff.", enHash = "99a7b55b", vanilla = true },
        reward = { it = "Salve, $C. Sono Orm, e Thun'grim mi dice che vuoi farti fare un elmo?", enHash = "14e61cb5", vanilla = true },
    },
    [1841] = {
        title = { it = "Velora Nitely e i Brutal Legguards", enHash = "d7ea0376", vanilla = true },
        text = { it = "Si dice che, prima di morire, Velora Nitely fosse una delle migliori armaiole di Lordaeron. A quanto pare la morte non ha diminuito il suo talento. Parla con Velora: sarà lei a farti i Brutal Legguards.\n\nVelora esercita il suo mestiere nell'Undercity di Lordaeron, nel Trade Quarter.", enHash = "d1bc240f", vanilla = true },
        objectives = { it = "Parla con Velora Nitely, nell'Undercity.", enHash = "edefc0a1", vanilla = true },
        reward = { it = "Sei qui per un'armatura per le gambe? Magnifico!\n\nEhm... sono io che faccio l'armatura per te, o sei tu che la fai per me?\n\nEra una battuta. Faceva ridere? Non riesco a capirlo... Ho perso il senso dell'umorismo insieme all'olfatto. Più o meno quando ho smesso di respirare.", enHash = "093ea358", vanilla = true },
    },
    [1842] = {
        title = { it = "Zoccoli di satiro", enHash = "3bea901d", vanilla = true },
        text = { it = "Posso farti un paio di Brutal Gauntlets, e racchiuderanno una grande magia. Ma prima devi raccogliere questa magia e portarmela.\n\nI satiri vivono nella parte nord-orientale di Ashenvale per via del potere della foresta. Si nutrono della sua purezza, succhiandola e corrompendola. Puoi capire quali satiri hanno assorbito più magia di Ashenvale dai loro zoccoli gonfi e non fessi.\n\nQuesti zoccoli racchiudono un grande potere. Mi serviranno per forgiare i tuoi guanti.", enHash = "1cac7e7d", vanilla = true },
        objectives = { it = "Porta 7 Uncloven Satyr Hoof a Ula'elek, a Sen'jin Village, in Durotar.", enHash = "42ee299c", vanilla = true },
        progress = { it = "Hai gli zoccoli, $N? La magia che contengono è forte.", enHash = "15cdc4be", vanilla = true },
        reward = { it = "Ah, li hai! Ora, proprio come i satiri succhiavano la forza di Ashenvale, io succhierò il potere racchiuso in questi zoccoli e lo imbriglierò nel mio lavoro...", enHash = "7964cf07", vanilla = true },
    },
    [1843] = {
        title = { it = "Brutal Gauntlets", enHash = "e29fa9d3", vanilla = true },
        reward = { it = "Grazie, $N. Questi guanti sono il mio lavoro migliore. Prendili. Indossandoli, porti onore a me e ai miei antenati.", enHash = "fd2ae25c", vanilla = true },
    },
    [1844] = {
        title = { it = "Il corno della chimera", enHash = "79a82944", vanilla = true },
        text = { it = "Ti farò l'elmo, ma devi dimostrarmi di esserne $Gdegno:degna;.\n\nNelle regioni nord-occidentali delle Stonetalon Mountains si trova la Charred Vale. Un tempo era un luogo verdeggiante, ma ora è profanata e coperta di cenere, e le creature che vi sono rimaste sono impazzite per il dolore e la disperazione.\n\nÈ lì che ti mando, $N.\n\nDevi andare nella Charred Vale e trovare una Chimaera Matriarch. Uccidila, liberala dalla sua sofferenza. Portami il suo Galvanized Horn come prova, e ti farò l'elmo.", enHash = "0d54a207", vanilla = true },
        objectives = { it = "Porta un Galvanized Horn a Orm Stonehoof, a Thunder Bluff.", enHash = "e1417a2d", vanilla = true },
        progress = { it = "Hai il corno? La matriarca è libera dal dolore?", enHash = "1d8d99b1", vanilla = true },
        reward = { it = "Hai portato a termine il tuo compito, $N, e mi hai mostrato il tuo valore e la tua determinazione. L'elmo sarà tuo...", enHash = "500f7042", vanilla = true },
    },
    [1845] = {
        title = { it = "Brutal Helm", enHash = "630b7444", vanilla = true },
        reward = { it = "Ti consegno questo elmo.\n\nGrandi imprese ti hanno portato da me, $N, e, se la Madre Terra vorrà... imprese ancora più grandi ti attendono.", enHash = "cf9b8736", vanilla = true },
    },
    [1846] = {
        title = { it = "Gli stinchi dei Dragonmaw", enHash = "ae8d3a85", vanilla = true },
        text = { it = "Per fare i Brutal Legguards mi serve un paio di stinchi robusti. Gli orchi Dragonmaw delle Wetlands hanno stinchi belli spessi. Mi servono i loro.\n\nMa devono essere robusti. Assicurati di metterli alla prova mentre li raccogli. Se riesci a spezzarli a mani nude, non saranno abbastanza robusti per lavorarci.", enHash = "607cc8d4", vanilla = true },
        objectives = { it = "Porta 8 Sturdy Dragonmaw Shinbone a Velora Nitely, nell'Undercity.", enHash = "d0f936ba", vanilla = true },
        progress = { it = "Aspetto quegli stinchi, $N. Faranno da bella struttura per le tue gambiere.", enHash = "ebb36ad5", vanilla = true },
        reward = { it = "Ben fatto! Sembrano tutti robusti. Credo che andranno benissimo. Come l'hanno presa quegli orchi, quando gli hai portato via gli stinchi, $N? Si sono lamentati molto?\n\nEra un'altra battuta. Non ridi.\n\nNon sono molto divertente di questi tempi, vero...", enHash = "75acfc57", vanilla = true },
    },
    [1847] = {
        title = { it = "Brutal Legguards", enHash = "76faa4b6", vanilla = true },
        reward = { it = "Ecco le tue gambiere, $N. Fammi sapere come ti stanno o se servono modifiche. Il mio scopo è accontentare! Almeno, una volta lo era.\n\nDi questi tempi non m'importa molto del mio mestiere. Ma è sempre meglio che essere una serva senza mente del Flagello!\n\nCredo.", enHash = "6e4a5a40", vanilla = true },
    },
    [1848] = {
        title = { it = "Brutal Hauberk", enHash = "eb96ef92", vanilla = true },
        reward = { it = "Sono sicuro che hai sopportato molte fatiche e versato molto sangue per il mio compito, $N. Ecco il frutto del tuo lavoro.\n\nPortalo bene, e che un giorno tu possa tornare qui a raccontarmi come ti ha servito.", enHash = "37f7f990", vanilla = true },
    },
    [1858] = {
        title = { it = "La Shattered Hand", enHash = "ccde0ee6", vanilla = true },
        text = { it = "Lascio a te il compito di aprire Tazan's Satchel e di tornare da me con il suo contenuto. Il meccanismo della serratura è complesso, quindi probabilmente la cosa più facile sarebbe procurarti la chiave.\n\nVisto che non l'hai trovata sul corpo di Tazan, posso solo supporre che l'abbia lasciata in custodia a qualcun altro... Ah, sì, è così. Aveva un assistente di nome Gamon. È un ubriacone: con ogni probabilità lo troverai alla taverna. Forse potresti alleggerirlo della chiave senza dare nell'occhio.", enHash = "fd09a843", vanilla = true },
        objectives = { it = "Ruba la chiave di Tazan, poi usala per aprire la sua borsa (Tazan's Satchel) e consegnane il contenuto a Therzok, nella Cleft of Shadow, a Orgrimmar.", enHash = "4beab05a", vanilla = true },
        progress = { it = "Non è irritante avere l'oggetto del desiderio a portata di mano, e nessun modo per arrivarci?", enHash = "5289ddc4", vanilla = true },
        reward = { it = "Mmm, questo sì che è interessante. Con questo hai più che dimostrato il tuo valore, $N. Sono davvero colpito. Considerati il membro più recente della Shattered Hand. E prendi questo: penso che in futuro ti sarà di grande aiuto.", enHash = "82ca6c4d", vanilla = true },
    },
    [1859] = {
        title = { it = "Therzok", enHash = "af8fca15", vanilla = true },
        text = { it = "Abbassa la voce, $N. Sì, so come ti chiami. Mi hanno detto di tenere d'occhio $Gun orco:un'orchessa; che corrisponde alla tua descrizione.\n\nDa quello che abbiamo sentito su di te, sai cavartela in combattimento, e ogni tanto non disdegni un po' di sotterfugi.\n\nHo ragione?\n\nComunque, dovresti andare a trovare Therzok a Orgrimmar. Ha un'offerta da farti.", enHash = "64a6b965", vanilla = true },
        objectives = { it = "Parla con Therzok nella Cleft of Shadow, a Orgrimmar.", enHash = "bf2e7b5d", vanilla = true },
        reward = { it = "Molto bene, sono contento che Kaplak ti abbia rintracciato.\n\nAbbiamo alcune cose di cui parlare, non ultimo il tuo futuro con la Hand.", enHash = "a3f4bf5e", vanilla = true },
    },
    [1860] = {
        title = { it = "Parla con Jennea", enHash = "be098f63", vanilla = true },
        text = { it = "Noi maghi abbiamo un compito da portare a termine. Un compito vitale per la sicurezza di Stormwind e dell'Elwynn Forest.\n\nI dettagli li ha Jennea Cannon. Studia nel Wizard's Sanctum, nel Mage District di Stormwind. Dovresti raggiungerla al più presto.", enHash = "046c4eb8", vanilla = true },
        objectives = { it = "Parla con Jennea Cannon, a Stormwind.", enHash = "294dce72", vanilla = true },
        reward = { it = "Ti hanno mandato ad aiutarmi nel mio compito, $N? Bene. Fa piacere vedere giovani maghi così desiderosi di aiutare la nostra causa...\n\nQuale causa, chiedi? A tempo debito, giovane. Lo saprai... a tempo debito.", enHash = "c225f10f", vanilla = true },
    },
    [1861] = {
        title = { it = "Mirror Lake", enHash = "94909550", vanilla = true },
        text = { it = "Questo mondo è stato vittima di immense lotte mistiche, che hanno strappato le correnti magiche a canali un tempo stabili. Facciamo fatica a capire quali effetti abbiano causato questi cambiamenti, e alcuni di noi temono il peggio!\n\nMa te ne parlerò meglio più avanti. Per ora ci serve che tu raccolga informazioni.\n\nEcco, prendi questa fiaschetta. Va' ai piedi della cascata del Mirror Lake, a sud-ovest delle porte di Stormwind, e preleva un campione dell'acqua. Riportamelo, così potrò analizzarlo per vedere se contiene tracce di corruzione magica.", enHash = "f05fca72", vanilla = true },
        objectives = { it = "Porta un campione del Mirror Lake a Jennea Cannon, a Stormwind.", enHash = "78627cf2", vanilla = true },
        progress = { it = "Hai il campione, $N? Il flusso della magia a Stormwind e a Elwynn è stato alterato, e devo sapere se sta filtrando nell'acqua.", enHash = "c30312c3", vanilla = true },
        reward = { it = "Grazie, $N. Analizzerò quest'acqua per scoprire se ha proprietà magiche. Speriamo che non ne abbia, altrimenti potremmo scoprire che chi beve dal Mirror Lake troppo a lungo ne subisce gli effetti negativi.\n\nEcco, $N. Prendi questo globo o questo bastone come segno di riconoscimento per il tuo servizio. Che possa esserti utile.", enHash = "5b830edd", vanilla = true },
    },
    [1879] = {
        title = { it = "Parla con Bink", enHash = "2a45f490", vanilla = true },
        text = { it = "$N! Bink, la mia collega gnoma di Ironforge, manda a dire che ha un compito da sbrigare e che non lo affiderà a nessuno se non a un mago! Sei tu $Gquel mago:quella maga;, $N?\n\nSe è così, va' a parlare con Bink. Passa le sue giornate nell'Hall of Mysteries, nel Mystic Ward di Ironforge.", enHash = "6611d737", vanilla = true },
        objectives = { it = "Parla con Bink, a Ironforge.", enHash = "a7219eba", vanilla = true },
        reward = { it = "Oh, vedo che hai del potenziale, eccome se ce l'hai! Ma per essere un buon mago non basta il potenziale. E se non sei $Gun buon mago:una buona maga;, allora sei $Gun pessimo mago:una pessima maga;. E i pessimi maghi fanno parte del problema, eccome se ne fanno parte!\n\nOps, sto correndo troppo. Cominciamo dall'inizio!", enHash = "cb8e72f8", vanilla = true },
    },
    [1880] = {
        title = { it = "Mage-tastic Gizmonitor", enHash = "b33d94ec", vanilla = true },
        text = { it = "Noi maghi non ci limitiamo ad agitare le dita e a fare delle belle scintille! Noi controlliamo la magia, il tessuto fondamentale del nostro mondo! E per farlo servono grande attenzione e determinazione. E conoscenza... tantissima conoscenza!\n\nUno dei miei congegni, il Mage-tastic Gizmonitor, raccoglie e conserva quella conoscenza in quantità enormi! Ma è andato perduto! Quando siamo fuggiti da Gnomeregan, la nostra casa, l'ho lasciato in una cassa, dentro una delle nostre capanne fuori città, e adesso il posto brulica di Leper Gnome!\n\nTi prego, $N, recupera il mio gizmonitor!", enHash = "cff810df", vanilla = true },
        objectives = { it = "Porta a Bink il suo Mage-tastic Gizmonitor.", enHash = "67312969", vanilla = true },
        progress = { it = "Hai trovato il gizmonitor? Devo riaverlo prima che la sua riserva di energia si esaurisca!", enHash = "59448ead", vanilla = true },
        reward = { it = "Oh, che splendida giornata! Quando ho costruito il gizmonitor non mi rendevo conto di quanto ne sarei diventata dipendente. Adesso posso ricominciare i miei studi!\n\nGrazie, $N! Ed ecco — questi sono stati i miei primi strumenti da maga. Sono un po' graffiati, ma sono ben collaudati. Scegli quello che preferisci — sono sicura che l'uno o l'altro ti tornerà utile.", enHash = "b08edf3c", vanilla = true },
    },
    [1881] = {
        title = { it = "Parla con Anastasia", enHash = "a4b414b3", vanilla = true },
        text = { it = "$N, Anastasia Hartwell ha un compito per qualcuno con il tuo talento. Va' a parlarle nel Magic Quarter dell'Undercity e preparati al tuo primo incarico per i maghi dei Reietti.", enHash = "dd9d816b", vanilla = true },
        objectives = { it = "Parla con Anastasia Hartwell.", enHash = "ca1651d8", vanilla = true },
        reward = { it = "Salve, $N. Hai agito con saggezza rispondendo alla mia chiamata, e ne mostrerai ancora di più se darai ascolto a quello che sto per dirti...", enHash = "5c5703e5", vanilla = true },
    },
    [1882] = {
        title = { it = "La Balnir Farmstead", enHash = "0eb918ea", vanilla = true },
        text = { it = "Le Plaguelands a est sono un'aberrazione. Ideate dal Re dei Lich, diffondono la loro magia nel suolo, corrompendo e uccidendo tutto ciò che vive. Per quanto le forze distruttive della piaga abbiano un certo fascino, noi maghi dei Reietti riteniamo che sia ingovernabile e che vada tenuta a freno.\n\nMa prima dobbiamo misurare fin dove si è estesa dentro Tirisfal. Va' alla Balnir Farmstead, nella parte orientale di Tirisfal. Nel giardino ci sono dei fiori — bocche di leone. Raccoglile e torna qui.", enHash = "413f807f", vanilla = true },
        objectives = { it = "Porta Balnir Snapdragons ad Anastasia Hartwell, nel Mage Quarter dell'Undercity.", enHash = "1e4fd235", vanilla = true },
        progress = { it = "Hai le bocche di leone? Quella varietà di fiore è molto sensibile alle energie magiche, e studiando quelle cresciute così vicino alle Plaguelands possiamo capire se la piaga è entrata nelle Tirisfal Glades.", enHash = "d20d176a", vanilla = true },
        reward = { it = "Ah, questo è un bell'esemplare. Lo farò studiare ai nostri speziali, per stabilire fin dove arriva la corruzione delle Plaguelands.\n\nBen fatto, $N. Per i tuoi servigi ti offro una scelta: un globo o un bastone. Qualunque cosa sceglierai, ti sarà molto utile.", enHash = "bd56ac31", vanilla = true },
    },
    [1883] = {
        title = { it = "Parla con Un'thuwa", enHash = "3bd67569", vanilla = true },
        text = { it = "Un'thuwa, il mago della tribù di Sen'jin Village, avverte una perturbazione nelle correnti magiche di Durotar e chiede aiuto. Parla con Un'thuwa e fa' il possibile per aiutarlo.\n\nFallo, e col tempo ti saranno svelati altri segreti.", enHash = "7dc2f70f", vanilla = true },
        objectives = { it = "Parla con Un'thuwa.", enHash = "3ef837e5", vanilla = true },
        reward = { it = "Salute, $N. Sia lode a te, perché la mia richiesta d'aiuto ha avuto risposta. Speriamo che tu sia all'altezza del compito...", enHash = "0fd6c777", vanilla = true },
    },
    [1884] = {
        title = { it = "I Ju-Ju Heap", enHash = "c943e734", vanilla = true },
        text = { it = "Lo stregone Zalazane delle Echo Isles ha sconvolto il normale flusso della magia in Durotar. Ci riesce grazie a dei feticci corrotti, i Ju-Ju Heap, che ha piazzato fra le sue capanne sull'isola principale delle Echo Isles.\n\nQuesti cumuli corrompono la nostra fauna e danno potere agli stregoni e alle creature infernali in agguato negli angoli oscuri di queste terre.\n\nDevi distruggere i Ju-Ju Heap, $N, prima che il flusso della magia cambi per sempre.", enHash = "7b49b907", vanilla = true },
        objectives = { it = "Distruggi 4 Ju-Ju Heap, poi torna da Un'thuwa, a Sen'jin Village.", enHash = "4fb66778", vanilla = true },
        progress = { it = "Devi sbrigarti, $N. Distruggi i Ju-Ju Heap!", enHash = "b3cc5ee8", vanilla = true },
        reward = { it = "Sento che i Ju-Ju Heap di Zalazane sono stati distrutti, e con il tempo e un po' di fortuna il flusso della magia in Durotar tornerà normale.\n\nHai compiuto una grande impresa per la tua gente, $N. E hai dimostrato il tuo valore a noi maghi dell'Orda.", enHash = "25514d0a", vanilla = true },
    },
    [1885] = {
        title = { it = "Mennet Carkad", enHash = "64ff13b3", vanilla = true },
        text = { it = "$N? Non proprio ciò che mi aspettavo, visto che Carkad in persona si è interessato a te. Ma l'apparenza inganna, giusto?\n\nIn ogni caso, dovresti andare da lui il prima possibile. Non vorresti sapere cosa è successo agli ultimi che hanno scelto di ignorare la sua convocazione.", enHash = "97ec6494", vanilla = true },
        objectives = { it = "Parla con Mennet Carkad nel Rogues' Quarter dell'Undercity.", enHash = "eb57c48c", vanilla = true },
        reward = { it = "Mm. Senza dubbio sei $Gvenuto:venuta; qui appena hai sentito parlare della mia convocazione, vero? Naturalmente. Non mi aspetterei niente di meno da chi aspira a diventare Inseguitore della Morte.", enHash = "1bc6a114", vanilla = true },
    },
    [1886] = {
        title = { it = "Gli Inseguitori della Morte", enHash = "b9a9e66c", vanilla = true },
        text = { it = "Se vuoi unirti agli Inseguitori della Morte, la guardia scelta di Lord Varimathras, dovrai dimostrare il tuo valore.\n\nNon ti mentirò, $N: questo compito potrebbe costarti la vita.\n\nHo alcune faccende di cui occuparmi. Mi servono gli effetti personali di Astor Hadren, che porta messaggi tra Silverpine e l'Undercity. Lascio a te la scelta del modo di procurarteli.\n\nMeglio per te sapere il meno possibile sulla natura di questa faccenda. Riesci, e ti dirò di più.", enHash = "d1e15893", vanilla = true },
        objectives = { it = "Procurati Astor's Letter of Introduction e riportala a Mennet Carkad, nel Rogues' Quarter.", enHash = "0f61b638", vanilla = true },
        progress = { it = "Hai buone notizie da riferire?", enHash = "b1855923", vanilla = true },
        reward = { it = "Ben fatto, $N. Hai superato la prima parte di questa prova. Speriamo che Andron non abbia avuto sentore delle tue attività: così potremo convincerlo che sei proprio $Gil messaggero:la messaggera; che aspetta.", enHash = "3ddb4e15", vanilla = true },
    },
    [1898] = {
        title = { it = "Gli Inseguitori della Morte", enHash = "b9a9e66c", vanilla = true },
        text = { it = "La lettera di presentazione dovrebbe bastare a convincere Andron che sei $Gil messaggero:la messaggera; che aspettava. Ho già incontrato Andron: non ha abbastanza cervello per essere così sospettoso.\n\nLord Varimathras sospetta che Andron stia aiutando qualche altro gruppo. Vuole sapere di quale organizzazione si tratta, e gliene serve la prova.\n\nVoglio che tu parli con Andron e che ottenga questa informazione. Lo troverai nella sua bottega, vicino all'Apothecarium.", enHash = "e70e4f62", vanilla = true },
        objectives = { it = "Parla con Andron Gant, nell'Undercity.", enHash = "cd0a7f2f", vanilla = true },
        progress = { it = "Salve. Posso fare qualcosa per te?", enHash = "e2b8343b", vanilla = true },
        reward = { it = "Ah, sì, ti stavo aspettando. Non ho dubbi che i nostri comuni conoscenti siano soddisfatti delle informazioni che ho fornito finora, vero?\n\nImmagino sia inutile chiederlo a te: dubito che ti carichino di queste conoscenze. Perché riporre tanta fiducia in chi porta i messaggi, eh?", enHash = "8d3f2fbd", vanilla = true },
    },
    [1899] = {
        title = { it = "Gli Inseguitori della Morte", enHash = "b9a9e66c", vanilla = true },
        text = { it = "Il registro con le informazioni che cercano i tuoi datori di lavoro è sullo scaffale dietro di me. Consegnalo con i miei saluti, e di' loro che preferirei che mandassero te, se ritengono che valga la pena continuare il nostro accordo.", enHash = "0c38dfba", vanilla = true },
        objectives = { it = "Porta Astor's Ledger a Mennet Carkad, nel Rogues' Quarter dell'Undercity.", enHash = "3b0b7d3c", vanilla = true },
        progress = { it = "Ce l'hai fatta, $N?", enHash = "d62c749e", vanilla = true },
        reward = { it = "Beh, sono certamente più informazioni di quante mi aspettassi di ottenere da Andron. Dammi un momento per esaminarle, prima di affidarti il prossimo compito.", enHash = "d2e6f39f", vanilla = true },
    },
    [1918] = {
        title = { it = "L'elemento corrotto", enHash = "9556886d", vanilla = true },
        text = { it = "L'elementale ucciso ha lasciato un globo d'acqua che brilla intensamente. Il contenuto del globo è, a dir poco, disgustoso. È lecito supporre che ciò che ha corrotto l'acqua del Mystral Lake si trovi con ogni probabilità anche nell'acqua del globo.\n\nNon è cosa risaputa chi possa interessarsi a un ritrovamento simile; forse chi ti ha mandato al lago, Mastok Wrilehiss a Splintertree Post, ha qualche idea.", enHash = "5baef40f", vanilla = true },
        objectives = { it = "Porta il Befouled Water Globe a Mastok Wrilehiss, a Splintertree Post, in Ashenvale.", enHash = "8b5faf86", vanilla = true },
        progress = { it = "Sì, cosa ti serve?", enHash = "e971dfa8", vanilla = true },
        reward = { it = "Trovi una brutta palla d'acqua e decidi di portarla a me? Chi sono io, il Circolo della Terra o roba del genere?\n\nA dire il vero, mi viene un'idea... forse per questa cosa ti serve davvero il Circolo della Terra. Voglio dire, se serve a sistemare per sempre la situazione al lago, ci sto.\n\nSai chi è il Circolo della Terra, $N?", enHash = "8f67a047", vanilla = true },
    },
    [1919] = {
        title = { it = "Presentati a Jennea", enHash = "21595370", vanilla = true },
        text = { it = "La tua conoscenza dell'arte cresce, giovane $N. Adesso sei $Gpronto:pronta; a cominciare le tue vere lezioni? Sei $Gpronto:pronta; a prendere il tuo posto nella guerra segreta che combattiamo?\n\nSe è così, parla con Jennea Cannon, nel Wizard's Sanctum, nel Mage District di Stormwind. Ha per te un compito che ti aprirà la prima finestra sul mondo invisibile.", enHash = "895da6ec", vanilla = true },
        objectives = { it = "Parla con Jennea Cannon, a Stormwind.", enHash = "294dce72", vanilla = true },
        reward = { it = "$N, ho una missione per te, qui nel Mage District. Ascoltami bene, perché non c'è tempo da perdere.", enHash = "483d0fe1", vanilla = true },
    },
    [1920] = {
        title = { it = "Indaga sul Blue Recluse", enHash = "d98307d5", vanilla = true },
        text = { it = "È stata segnalata una perturbazione alla taverna Blue Recluse, nel Mage Quarter. Strane creature invisibili ora si aggirano per la taverna, e temo che lì si sia aperta una fenditura di mana.\n\nVoglio che tu indaghi nella taverna e catturi quelle creature. Usa la Cantation of Manifestation dentro la taverna per renderle visibili, sottomettile e poi usa uno scrigno di contenimento (Containment Coffer) per catturarle. Quando ne avrai abbastanza, torna da me con gli scrigni pieni, quelli vuoti e la Cantation of Manifestation.", enHash = "723707fd", vanilla = true },
        objectives = { it = "Prendi una Cantation of Manifestation e una Chest of Containment Coffers alle spalle di Jennea Cannon. Porta 3 Filled Containment Coffer a Jennea, al Wizard's Sanctum.", enHash = "02327459", vanilla = true },
        progress = { it = "Hai catturato le creature, $N? Vanno studiate per capire il motivo del loro arrivo.", enHash = "021a2fda", vanilla = true },
        reward = { it = "Ottimo lavoro! Studierò queste creature e, con impegno e un po' di fortuna, scoprirò come sono sgusciate nel nostro mondo.\n\nIl tuo valore per la società dei maghi cresce, $N.", enHash = "fdfb65f7", vanilla = true },
    },
    [1921] = {
        title = { it = "Raccogliere i materiali", enHash = "2f417b53", vanilla = true },
        text = { it = "Hai servito bene i tuoi compagni maghi, e ora è tempo che tu indossi la tua veste da $Gmago:maga;. Wynne Larson può confezionartela, ma devi portarle i materiali necessari.\n\nLa veste sarà di lino, che è facile da trovare, ma dovrai anche procurarti delle Charged Rift Gem, e l'unico posto noto in cui trovarle è la Silver Stream Mine di Loch Modan: la lega dei minatori nani le ha lasciate lì, in alcune casse.\n\nRaccogli il lino e le gemme e portali a Wynne Larson, ai Larson Clothiers nel Mage District.", enHash = "d1a899a2", vanilla = true },
        objectives = { it = "Porta 10 Linen Cloth e le 6 Charged Rift Gem a Wynne Larson, a Stormwind.", enHash = "f52bb8e3", vanilla = true },
        progress = { it = "Ciao, $N. Jennea mi aveva detto che saresti $Gvenuto:venuta;. Hai qualcosa per me?", enHash = "e6797090", vanilla = true },
        reward = { it = "Sì, questi sono ottimi pezzi di lino. Ci posso fare una bella veste. E quando ci avrò intessuto le gemme, avremo un abito degno di un mago!", enHash = "09721bad", vanilla = true },
    },
    [1938] = {
        title = { it = "Ur's Treatise on Shadow Magic", enHash = "09a56306", vanilla = true },
        text = { it = "Molto tempo fa, tre maghi studiavano in questa torre, finché uno di loro cadde preda delle arti oscure. Fu esortato ad abbandonare quella magia malvagia, ma non riuscì a resisterle. E così fu esiliato.\n\nIl nuovo dominio del mago caduto è la Tower of Ilgalar, a Redridge, e con sé ha portato un libro potente — Ur's Treatise on Shadow Magic.\n\nNoi maghi di Stormwind vogliamo che quel libro ci venga restituito. Entra nella Tower of Ilgalar, trova il tomo nella sua biblioteca e portamelo.", enHash = "5773a7e7", vanilla = true },
        objectives = { it = "Porta Ur's Treatise on Shadow Magic a High Sorcerer Andromath, a Stormwind.", enHash = "a92d70fc", vanilla = true },
        progress = { it = "Hai il libro, $N? I suoi segreti non sono fatti per chi non ha la preparazione necessaria, e scandagliarne le profondità può portare alla rovina e alla distruzione.", enHash = "02bdeeb0", vanilla = true },
        reward = { it = "Temevo che Morganth avesse nascosto il libro altrove, o che avesse trovato il modo di aprirlo e di leggerne il contenuto.\n\nPer fortuna non l'ha fatto, e i sigilli che abbiamo posto su Ur's Treatise on Shadow Magic reggono ancora.", enHash = "6819d5d1", vanilla = true },
    },
    [1939] = {
        title = { it = "High Sorcerer Andromath", enHash = "220036e1", vanilla = true },
        text = { it = "High Sorcerer Andromath desidera parlarti, $N. Si trova in cima al Wizard's Sanctum, nel Mage District di Stormwind.\n\nFaresti bene a parlargli, perché Andromath è uno dei maghi più potenti fra quelli che non sono rinchiusi a Dalaran. Un suo consiglio è davvero un consiglio di alto livello.", enHash = "b98396c4", vanilla = true },
        objectives = { it = "Parla con High Sorcerer Andromath.", enHash = "5b7f57b9", vanilla = true },
        reward = { it = "Salve, $N. Sono lieto di vederti, e spero che tu abbia il tempo di ascoltare le parole di un vecchio...", enHash = "ddec44a3", vanilla = true },
    },
    [1940] = {
        title = { it = "Pristine Spider Silk", enHash = "c1574628", vanilla = true },
        text = { it = "Il tuo impegno non è mai venuto meno, $N. Penso che forse sia giunto il momento che tu abbia un abito più raffinato, più adatto al tuo rango di $Gmago esperto:maga esperta;. Se raccoglierai i materiali necessari, provvederemo a farti confezionare la veste.\n\nDevi andare a Duskwood e cacciare i ragni (Carrion Recluse). Estrai la loro seta, ma andrà bene solo la seta più fine e immacolata. Quando ne avrai abbastanza, portala a Wynne Larson, qui nel Mage District, ai Larson Clothiers. Sarà lei a confezionarti la veste.", enHash = "25161ef3", vanilla = true },
        objectives = { it = "Porta 8 Pristine Spider Silk a Wynne Larson, a Stormwind.", enHash = "2ac694ad", vanilla = true },
        progress = { it = "Ah, sì. I maghi del Wizard's Sanctum mi avevano detto che saresti $Gvenuto:venuta; a parlarmi. Hai la seta che serve?", enHash = "4ee73ce9", vanilla = true },
        reward = { it = "Begli esemplari, questi. Mi metto subito al lavoro!", enHash = "5bfd0a22", vanilla = true },
    },
    [1941] = {
        title = { it = "Manaweave Robe", enHash = "bdf7b0e5", vanilla = true },
        reward = { it = "Ecco la tua veste. È una delle migliori che abbia mai fatto! Indossala con orgoglio, e quando te lo chiederanno... di' che l'hai presa ai Larson Clothiers!", enHash = "266af552", vanilla = true },
    },
    [1942] = {
        title = { it = "Astral Knot Garment", enHash = "9e408043", vanilla = true },
        reward = { it = "Il tuo abito è pronto! E quella seta che hai raccolto era così bella... non ti dispiace se l'ho fatto un filo più corto per tenermi un avanzo di seta, vero?\n\nSto solo scherzando. Ti starà benissimo, e sarà perfetto sia per l'avventura sia per le cene di gala. Goditelo!", enHash = "a0b982a2", vanilla = true },
    },
    [1943] = {
        title = { it = "Parla con Deino", enHash = "1e92e8fd", vanilla = true },
        text = { it = "La maga troll Deino ha bisogno del tuo aiuto, $N. Vive a Orgrimmar, nella Darkbriar Lodge.", enHash = "49c306b4", vanilla = true },
        objectives = { it = "Parla con Deino.", enHash = "b3ca36d1", vanilla = true },
        reward = { it = "Bene, sei $Gvenuto:venuta;. Il mio compito non è facile, ma è vitale per la società dei maghi. Se mi aiuterai, sono sicura che ne varrà la pena.", enHash = "8b4e05fe", vanilla = true },
    },
    [1944] = {
        title = { it = "Le acque di Xavian", enHash = "4ea77e0e", vanilla = true },
        text = { it = "La leggendaria città di Xavian si trova annidata nel cuore della parte orientale di Ashenvale, e i racconti sul suo antico sapere sono ben noti fra i dotti. Si dice che le acque di Xavian abbiano immensi poteri magici.\n\nVorrei un campione di quelle acque, preso alla fonte.\n\nPrendi questa fiasca e va' a Xavian. Raccogli l'acqua ai piedi della sua cascata più alta e torna da me. E fa' attenzione mentre ti muovi in quell'antica città — ora le rovine sono in mano ai satiri, che non gradiscono che i maghi ficchino il naso nei loro affari.", enHash = "fcf81ba4", vanilla = true },
        objectives = { it = "Porta lo Xavian Water Sample a Deino, a Orgrimmar.", enHash = "f0993b14", vanilla = true },
        progress = { it = "Sono lieta che tu sia $Gtornato:tornata; con la pelle intatta, $N. Hai il campione d'acqua? Non vedo l'ora di studiarne le proprietà.", enHash = "7ed52061", vanilla = true },
        reward = { it = "Ah, molto bene. I satiri di Xavian non ti hanno dato troppi problemi, spero?\n\nGrazie, $N. Studierò subito questo campione d'acqua di Xavian.", enHash = "86f56ef8", vanilla = true },
    },
    [1945] = {
        title = { it = "Le Laughing Sister", enHash = "b11b4b70", vanilla = true },
        text = { it = "Per i tuoi servigi ho fatto in modo che ti venga confezionata una veste nuova, purché tu riesca a raccogliere i materiali necessari...\n\nPer questa veste devi tornare in Ashenvale a prendere le ciocche di capelli delle Laughing Sister — driadi che si radunano vicino al Raynewood Retreat.\n\nQuando avrai i loro capelli, portali a Kil'hala, un sarto troll al Crossroads, nelle Barrens. Ti starà aspettando, e sarà lui a confezionarti la veste.", enHash = "cfd41457", vanilla = true },
        objectives = { it = "Porta 12 Laughing Sister's Hair a Kil'hala, al Crossroads.", enHash = "d0d284e4", vanilla = true },
        progress = { it = "Salve, $N. Deino mi ha detto che saresti $Gvenuto:venuta; e che mi avresti portato i capelli delle Laughing Sister. Ce li hai?", enHash = "e4530d4a", vanilla = true },
        reward = { it = "Ah, con questi capelli si tesserà una bella veste, $N. Peccato che le Laughing Sister siano dovute morire per separarsene, anche se dubito che li avrebbero mai dati di loro spontanea volontà.\n\nUn peccato, ma da poco.", enHash = "b8d89cc5", vanilla = true },
    },
    [1946] = {
        title = { it = "Nether-lace Garment", enHash = "a422e902", vanilla = true },
        reward = { it = "Ecco il tuo nether-lace, $N. È comodo e resistente, e racchiude la magia dei capelli delle Laughing Sister.\n\nGoditelo e, se ti soddisfa, per favore fallo sapere a Deino. È una maga con cui ci tengo a restare in buoni rapporti...", enHash = "75f328e1", vanilla = true },
    },
    [1947] = {
        title = { it = "Viaggio nella palude", enHash = "dd991cbf", vanilla = true },
        text = { it = "Ora è il momento di guadagnarti la tua bacchetta da $Gmago:maga;. Per cominciare questa impresa, parla con Tabetha, l'eremita umana, nel Dustwallow Marsh. Troverai la sua capanna nel cuore della palude, a ovest di Theramore.\n\nParla con lei, perché il suo sapere è vasto. Troverai la casupola di Tabetha a ovest di Theramore, appena a nord delle Stonemaul Ruins.", enHash = "7f25bd32", vanilla = true },
        objectives = { it = "Parla con Tabetha.", enHash = "8824131d", vanilla = true },
        reward = { it = "Silenzio! Sono in un momento delicato e non devo essere disturbata!\n\nUn momento...", enHash = "f95d7540", vanilla = true },
    },
    [1948] = {
        title = { it = "Oggetti di potere", enHash = "c6b05ddc", vanilla = true },
        text = { it = "Costruire la bacchetta di un mago non è facile. Servono sostanze rare, e bisogna creare un recipiente capace di contenere grandi quantità di energia magica. Devi raccogliere queste cose e portarmele.\n\nSu questa pergamena ho scritto ciò che ti serve e come procurartelo. Portami esattamente quello che c'è nell'elenco, e segui alla lettera le mie istruzioni scritte, perché se non lo farai, quando creeremo la tua bacchetta le cose potrebbero andare... male.", enHash = "39f84373", vanilla = true },
        objectives = { it = "Porta 1 Jade e il Bolt Charged Bramble a Tabetha, nel Dustwallow Marsh.", enHash = "b30813cb", vanilla = true },
        progress = { it = "Ciao, $N. Hai gli oggetti che mi servono?", enHash = "a3b13540", vanilla = true },
        reward = { it = "Aha! Hai preso la Jade e hai preparato il rovo! Ben fatto!\n\nÈ fumo quello che ti vedo uscire dalle orecchie? Forse ti sei $Gavvicinato:avvicinata; troppo quando il fulmine ha colpito i bastoncini del totem, ma non preoccuparti. Essere colpiti da un fulmine porta fortuna!", enHash = "ea54497d", vanilla = true },
    },
    [1949] = {
        title = { it = "Segreti nascosti", enHash = "4887774d", vanilla = true },
        text = { it = "Per fare la tua bacchetta devo leggere alcuni passi fondamentali di un certo libro. Si intitola Rituals of Power, e l'ha scritto Magus Tirth.\n\nNon ho una copia del suo libro, e nessuna delle grandi biblioteche del mondo lo possiede. Quindi devi parlare con Tirth e fartelo dare da lui.\n\nBuona fortuna. Un tempo Tirth era un grande mago e studioso, ma ora passa il tempo alle corse degli gnomi e dei goblin nelle Shimmering Flats, a bere e a scommettere.", enHash = "59ba8b12", vanilla = true },
        objectives = { it = "Parla con Magus Tirth, nelle Shimmering Flats.", enHash = "2f3612f3", vanilla = true },
        reward = { it = "Cosa? Parla più forte! Queste vecchie orecchie non sono più buone come una volta.\n\nBeh, spero che tu sia qui con un boccale di birra appena spillata o con qualche soffiata sulla prossima corsa! Altrimenti faresti meglio a tirare dritto... perché ho una bacchetta di metamorfosi con sopra scritto il tuo nome!", enHash = "387ec633", vanilla = true },
    },
    [1950] = {
        title = { it = "A caccia di notizie", enHash = "7f0d3987", vanilla = true },
        text = { it = "Posso aiutarti con il libro, ma prima devi aiutare me!\n\nIl tomo che cerchi è nel mio forziere chiuso con la magia. Per aprirlo bisogna pronunciare una frase speciale, e io non me la ricordo! Di solito è il mio assistente ad aiutarmi a ricordare queste cose, ma non si trova da nessuna parte.\n\nSe vuoi il mio libro, allora trova il mio apprendista! Chiedi in giro vicino alla pista delle corse — con un po' di fortuna, qualcuno l'avrà visto. Trascinalo qui, o almeno fatti dire da lui la mia frase magica, così possiamo aprire il forziere!", enHash = "e6f670a2", vanilla = true },
        objectives = { it = "Trova la frase che apre il forziere di Tirth, poi torna da Tirth.", enHash = "d00d8ba4", vanilla = true },
        progress = { it = "Cosa aspetti? Mi serve la mia frase magica!", enHash = "72c7a666", vanilla = true },
        reward = { it = "Ah, ora mi ricordo...\n\nMi ero dimenticato di quella piccola maledizione che ho lanciato su Johnson. Non ricordo perché l'ho fatto, ma di sicuro se l'era meritata, quel piccolo ingrato!", enHash = "f6ef5ecc", vanilla = true },
    },
    [1951] = {
        title = { it = "Rituals of Power", enHash = "040327ec", vanilla = true },
        text = { it = "Mm... ora che ci penso, il libro non ce l'ho! Vedi, avevo dei debiti di gioco, e per saldarli ho venduto l'ultima copia di Rituals of Power a un membro del clero...\n\nUn membro della Scarlet Brotherhood. Deve averlo portato nella loro biblioteca, allo Scarlet Monastery nelle Tirisfal Glades!\n\nSe vuoi quel libro, dovrai andare al monastero a cercarlo. E scusa per tutto il disturbo. In questi giorni non sono in me...", enHash = "e1f42e3e", vanilla = true },
        objectives = { it = "Porta il libro Rituals of Power a Tabetha, nel Dustwallow Marsh.", enHash = "679046ca", vanilla = true },
        progress = { it = "Salve, $N. Hai trovato il libro Rituals of Power?", enHash = "e27f03b8", vanilla = true },
        reward = { it = "È questo! È proprio quello che mi serve per preparare il rituale che creerà la tua bacchetta! Spero che trovarlo non ti abbia dato troppo disturbo...", enHash = "5ac9ff11", vanilla = true },
    },
    [1952] = {
        title = { it = "Bacchetta da mago", enHash = "dafeced5", vanilla = true },
        text = { it = "Ora vado a fare le bacchette.", enHash = "601b4970", vanilla = true },
        objectives = { it = "Parla con Tabetha dopo il suo rituale.", enHash = "367429ed", vanilla = true },
        reward = { it = "Ecco le bacchette che ho fatto. Scegli quella che preferisci!", enHash = "703be242", vanilla = true },
    },
    [1959] = {
        title = { it = "Presentati ad Anastasia", enHash = "a423b986", vanilla = true },
        text = { it = "I maghi dell'Undercity hanno notato una perturbazione magica all'interno della città, e hanno mandato a chiamare i maghi dell'Orda perché indaghino.\n\nAnastasia Hartwell può dirti di più. Va' a parlarle nel Magic Quarter dell'Undercity.", enHash = "5265c01c", vanilla = true },
        objectives = { it = "Parla con Anastasia Hartwell.", enHash = "ca1651d8", vanilla = true },
        reward = { it = "È vero. Nella nostra città è stata rilevata una perturbazione magica. Non siamo ancora certi della sua origine, né se sia maligna o benigna. Prima dobbiamo raccogliere altre informazioni...\n\nE questo, $N, ci porta al tuo compito.", enHash = "0b70f89d", vanilla = true },
    },
    [1960] = {
        title = { it = "Indaga sulla bottega dell'alchimista", enHash = "c089deb4", vanilla = true },
        text = { it = "La bottega d'alchimia di Algernon, nell'Apothecarium, è il centro di una strana perturbazione. Creature invisibili, fatte solo di magia, si aggirano per la bottega — ci dev'essere un motivo, e dobbiamo scoprirlo!\n\nIndaga sulla perturbazione e cattura quelle creature. Prendi una cassa di scrigni e una pergamena, qui dietro di me. Usa la pergamena nella bottega per rendere visibili le creature, sottomettile con i tuoi incantesimi, poi getta a terra uno scrigno per catturarle. Torna con gli scrigni pieni, quelli vuoti e la Cantation of Manifestation.", enHash = "8509a715", vanilla = true },
        objectives = { it = "Prendi una Cantation of Manifestation e una Chest of Containment Coffers alle spalle di Anastasia Hartwell. Porta 3 Filled Containment Coffer, la Chest of Containment Coffers e la Cantation of Manifestation ad Anastasia, nell'Undercity.", enHash = "284c1d51", vanilla = true },
        progress = { it = "Hai indagato sulla perturbazione, $N? Hai catturato le creature?", enHash = "01828d67", vanilla = true },
        reward = { it = "Molto bene, $N. Le creature chiuse in questi scrigni di contenimento saranno studiate dalle nostre menti migliori, e il motivo della loro presenza nell'Undercity verrà chiarito.\n\nSe la loro comparsa è causata da una fenditura nel flusso naturale della magia, dobbiamo stabilire se la fenditura è stata casuale. Se non lo è stata, e si tratta invece di un attacco da parte di qualche forza magica, allora dobbiamo prepararci a perturbazioni future, e più gravi.", enHash = "f5824390", vanilla = true },
    },
    [1961] = {
        title = { it = "Raccogliere i materiali", enHash = "2f417b53", vanilla = true },
        text = { it = "È tempo che tu indossi la tua prima veste da $Gmago:maga;, $N. È un segno del tuo rango e una prova del tuo valore.\n\nPer ottenerla, devi prendere le gemme di mana ai maghi di Dalaran che stanno a Silverpine. Le loro convinzioni sono simili alle nostre, quindi ucciderli è un po' sgradevole; ma se non hanno la forza di resisterci, non meritano di vivere.\n\nPorta le gemme e una scorta di lino a Josef Gregorian, nella sartoria del Magic Quarter.", enHash = "6eeb5613", vanilla = true },
        objectives = { it = "Porta 10 Linen Cloth e 6 Dalaran Mana Gem a Josef Gregorian.", enHash = "d2aa58fc", vanilla = true },
        progress = { it = "Anastasia mi ha detto che saresti $Gvenuto:venuta; da me, e sono pronto a confezionare la tua veste. Hai le gemme e il lino?", enHash = "53d681c7", vanilla = true },
        reward = { it = "È un materiale molto buono, e anche se non ho il talento per giudicare la qualità di queste gemme di mana, sapremo presto se hanno il potere necessario per creare le Spellfire Robes...", enHash = "52d3b672", vanilla = true },
    },
    [1962] = {
        title = { it = "Spellfire Robes", enHash = "db3d21f1", vanilla = true },
        reward = { it = "Ecco la tua veste, $N. Indossala degnamente.", enHash = "afd009af", vanilla = true },
    },
    [1963] = {
        title = { it = "La Shattered Hand", enHash = "ccde0ee6", vanilla = true },
        text = { it = "Il Capoguerra è troppo sottile nei suoi metodi. È cauto nello scatenare la potenza dell'Orda. Un tempo eravamo più forti, tutti potenti conquistatori. Dobbiamo riconquistare quell'orgoglio, e la Shattered Hand lo farà.\n\nCostruiamo la nostra forza nell'ombra e colpiamo chi resta scoperto, abbattendo i nostri nemici in segreto. C'è un compito che devi portare a termine per me, per dimostrare il tuo valore.\n\nIl troll Tazan commercia con i pirati vicino a Ratchet. Ha delle informazioni che devo avere. Uccidilo e portami la sua borsa.", enHash = "c18fb042", vanilla = true },
        objectives = { it = "Uccidi Tazan e porta la sua borsa (Tazan's Satchel) a Therzok, nella Cleft of Shadow, a Orgrimmar.", enHash = "d909a43b", vanilla = true },
        progress = { it = "Solo uno sciocco crede che una carica con l'ascia in pugno sia più pericolosa di un coltello nel buio.", enHash = "2ac01902", vanilla = true },
        reward = { it = "Mm, anche se mi fa piacere sapere che Tazan non è più tra noi, una borsa chiusa a chiave non ci serve a niente. Ci servono le informazioni che contiene.\n\nQuesta dovrebbe essere una seconda prova degna per chi desidera unirsi alla Shattered Hand.", enHash = "cb528798", vanilla = true },
    },
    [1978] = {
        title = { it = "Gli Inseguitori della Morte", enHash = "b9a9e66c", vanilla = true },
        text = { it = "Il Syndicate? Non l'avrei mai sospettato. Sembra che i nobili di Alterac siano caduti molto in basso negli anni dopo il loro tradimento.\n\nLord Varimathras sarà lieto di saperlo, e visto che sei $Gstato:stata; così determinante per questa scoperta, sarebbe giusto che fossi tu a consegnarglielo.\n\nAh, e come potevo dimenticarlo?\n\n$GBenvenuto:Benvenuta; tra gli Inseguitori della Morte.", enHash = "013b0d68", vanilla = true },
        objectives = { it = "Consegna Andron's Ledger a Varimathras nella Hall of the Dark Lady, nell'Undercity.", enHash = "882710c1", vanilla = true },
        progress = { it = "Sì?", enHash = "00388a38", vanilla = true },
        reward = { it = "Mmm, questo è interessante. Gli Inseguitori della Morte hanno svolto il loro compito in modo egregio, scovando tutto questo.\n\nA quanto mi risulta, anche tu meriti un encomio per il tuo operato. Spero che per te diventi un'abitudine, $N: ai miei Inseguitori della Morte fa sempre comodo $Gun uomo:una donna; in gamba.", enHash = { "d57219aa", "53286f02" }, vanilla = true },
    },
    [1998] = {
        title = { it = "Fenwick Thatros", enHash = "2819d478", vanilla = true },
        text = { it = "Lord Varimathras mi ha appena mandato un messaggio su una minaccia per i Reietti che va eliminata immediatamente. Si chiama Fenwick Thatros, e Lord Varimathras crede che sia uno dei capi dei non morti che hanno messo radici nella Silverpine Forest.\n\nIl tuo nome mi è venuto subito in mente, $N. Ho abbastanza fiducia nelle tue capacità da essere certo che porterai a termine questa missione alla perfezione.\n\nGli ultimi rapporti degli Inseguitori della Morte a Silverpine indicano che Thatros si trova vicino al molo in rovina sul Lordamere.", enHash = "3b73ea63", vanilla = true },
        objectives = { it = "Uccidi Fenwick Thatros e porta la sua testa a Mennet Carkad, nel Rogues' Quarter dell'Undercity.", enHash = "e495c03d", vanilla = true },
        progress = { it = "Ho riposto in te la massima fiducia perché tu renda questo servizio a Lord Varimathras.", enHash = "08ef336e", vanilla = true },
        reward = { it = "Hai fatto bene, $N. Mi rendo conto che hai reso molti servigi agli Inseguitori della Morte, dimostrando il tuo valore, e che forse è tempo di approfondire il tuo addestramento nelle arti dell'ombra.", enHash = "7b5f74f2", vanilla = true },
    },
    [1999] = {
        title = { it = "Gli attrezzi del mestiere", enHash = "ba6d2011", vanilla = true },
        text = { it = "I maghi del Kirin Tor ad Ambermill hanno messo al sicuro documenti importanti sulla situazione attuale di Dalaran. Lo sappiamo dalla confessione di uno dei nostri prigionieri. Lord Varimathras ha affidato agli Inseguitori della Morte il compito di recuperarli.\n\nQuesto compito spetta a te, $N. Però ti serviranno un po' di attrezzatura e la capacità di scassinare le serrature. Parla con Estelle Gendry, la nostra fornitrice, e chiedile un set di attrezzi prima di partire.", enHash = "cd6a7c10", vanilla = true },
        objectives = { it = "Trova il Dalaran Status Report e riportalo a Mennet Carkad, nel Rogues' Quarter dell'Undercity.", enHash = "2ae0f230", vanilla = true },
        progress = { it = "Hai trovato i documenti, $N?", enHash = "27e42c7f", vanilla = true },
        reward = { it = "Molto bene, $N! Hai imparato bene la raffinata arte dello scasso, e più in fretta di quanto potessi mai aspettarmi.\n\nVedo che ho fatto bene a fidarmi di te. Credimi, $Gragazzo:ragazza;, prevedo che farai molta strada in questo mestiere.", enHash = { "a8ffdbd4", "63642b94" }, vanilla = true },
    },
    [2038] = {
        title = { it = "I rifornimenti perduti di Bingles", enHash = "294ed17a", vanilla = true },
        text = { it = "Come se schiantarmi nel Loch non bastasse, i trogg dell'isola qui vicino mi hanno attaccato e mi hanno rubato gli attrezzi e i miei esplosivi speciali Blastenheimer Blastencapper. Senza girocottero e senza esplosivi, il movimento non ha speranze!\n\nRiprendi i miei attrezzi e trova i miei esplosivi Blastencapper, $N. Per Gnomeregan!", enHash = "c6c4cd62", vanilla = true },
        objectives = { it = "Trova e riporta i rifornimenti di Bingles:\n\nBingles' Wrench, Bingles' Screwdriver, Bingles' Hammer e Bingles' Blastencapper.", enHash = "941a8b12", vanilla = true },
        progress = { it = "$N! Dove sono le mie cose?!", enHash = "4648b7ed", vanilla = true },
        reward = { it = "Hai reso un grande servizio al movimento, $N. I trogg e i Leper Gnome che infestano Gnomeregan sentiranno presto tutto il peso di un assalto aereo gnomesco!", enHash = "b97865bf", vanilla = true },
    },
    [2039] = {
        title = { it = "Trova Bingles", enHash = "fa92de73", vanilla = true },
        text = { it = "Abbiamo perso i contatti con Bingles! Era stato mandato in missione di ricognizione sopra Gnomeregan e non fa rapporto da più di una settimana. Sono sicuro che è andato a farsi saltare in aria.\n\nL'ultima volta è stato visto mentre sorvolava il Loch. Forse puoi indagare tu, $N.", enHash = "b322887c", vanilla = true },
        objectives = { it = "Trova Bingles Blastenheimer, a Loch Modan.", enHash = "db42ce7a", vanilla = true },
        reward = { it = "Quindi Gnoarn non si fida delle mie capacità di ricognizione? Chissà perché...\n\nMa lasciamo perdere, mi serve il tuo aiuto! Anzi, no! È al movimento che serve il tuo aiuto!", enHash = "4b671a18", vanilla = true },
    },
    [2040] = {
        title = { it = "Assalto sotterraneo", enHash = "27b795fc", vanilla = true },
        text = { it = "Gnomeregan è caduta sotto il controllo di quegli infami trogg! La situazione è grave, ma forse puoi aiutarci, $N.\n\nNelle profondità delle Deadmines c'è una sminuzzatrice goblin ancora funzionante. Trova quella sminuzzatrice e riporta indietro l'alimentatore intatto. Con l'alimentatore della sminuzzatrice possiamo dare ai nostri escavatori girotrivellomatici la potenza che serve per sfondare le barriere di roccia sotterranee di Gnomeregan, aprendo la strada a un assalto gnomesco!", enHash = "f5c7a388", vanilla = true },
        objectives = { it = "Recupera lo Gnoam Sprecklesprocket dalle Deadmines e riportalo a Shoni the Shilent, a Stormwind.", enHash = "7ee742a4", vanilla = true },
        progress = { it = "Hai trovato lo Gnoam Sprecklesprocket, $N?", enHash = "1a15b40d", vanilla = true },
        reward = { it = "Ben fatto, $N. Grazie a te, Gnomeregan è un passo più vicina al giorno della sua liberazione!", enHash = "c6bdda32", vanilla = true },
    },
    [2041] = {
        title = { it = "Parla con Shoni", enHash = "1f67bd29", vanilla = true },
        text = { it = "Forse... forse puoi aiutarci nella battaglia per Gnomeregan.\n\nA Stormwind troverai la comandante della nostra squadra d'assalto sotterranea, Shoni the Shilent. A Shoni serve aiuto con i suoi gyrodrillmatic excavationator.\n\nProbabilmente la troverai tra i nani, a Stormwind.\n\nBuona fortuna, $N.", enHash = "6a28a04a", vanilla = true },
        objectives = { it = "Parla con Shoni the Shilent, a Stormwind.", enHash = "7e43ff65", vanilla = true },
        reward = { it = "Porti notizie dal comando centrale?", enHash = "540ef763", vanilla = true },
    },
    [2078] = {
        title = { it = "La vendetta di Gyromast", enHash = "2738589a", vanilla = true },
        text = { it = "Marinaio d'acqua dolce, devi trovarmi il mio secondo.\n\nPrendi 'sta chiave, piantagliela nella zucca e riportamelo qui a servire il Capitano.\n\nQuei murloc e il loro capo non saranno mica contenti quando il mio secondo gli metterà le mani addosso!", enHash = "5cedaed3", vanilla = true },
        objectives = { it = "Trova il secondo di Gelkak, il Threshwackonator 4100, e riportalo da Gelkak.", enHash = "6450ebd1", vanilla = true },
        progress = { it = "Dov'è il mio secondo, $N? Ceppi e squali per te, se non ti sbrighi!", enHash = "8a84eaa1", vanilla = true },
        reward = { it = "Yarrr... Stai dimostrando d'essere più di un lupo di mare codardo, marinaio d'acqua dolce.\n\nSe vai avanti così, il Capitano magari ti promuove a mozzo del cassero di poppa...", enHash = "e17db253", vanilla = true },
    },
    [2098] = {
        title = { it = "Il recupero di Gyromast", enHash = "e6a01164", vanilla = true },
        text = { it = "La vita del pirata non è facile, marinaio d'acqua dolce. Non è tutta saccheggi e bevute! Ahimè, la mia nave è colata a picco appena al largo, grazie a quei maledetti Threshadon.\n\nQuello che mi serve è il mio secondo rimesso in sesto!\n\nQuando sono finito sulla spiaggia, la chiave del mio secondo si è spezzata sugli scogli e le bestiacce di Darkshore se la sono fregata. Con la coda dell'occhio ho visto dei Ragin' Crawler, un Ferocious Foreststrider e dei murloc rovistare fra i relitti...", enHash = "40828473", vanilla = true },
        objectives = { it = "Trova e riporta i tre pezzi di Gelkak's Key a Gelkak Gyromast.", enHash = "274be867", vanilla = true },
        progress = { it = "L'hai trovata la mia chiave rotta, marinaio d'acqua dolce?", enHash = "57cb6d14", vanilla = true },
        reward = { it = "Alt là, lupo di mare scorbutico! Ce l'hai fatta! Presto il mio secondo sarà rimesso in sesto e quelle bestiacce non capiranno cosa le ha colpite!\n\nUhm, l'hai visto il mio secondo?", enHash = "47a20b33", vanilla = true },
    },
    [2118] = {
        title = { it = "Terre appestate", enHash = "f2402fba", vanilla = true },
        text = { it = "Un morbo si diffonde per Darkshore e attanaglia la mente e il corpo di tutto ciò che tocca.\n\nI Thistle Bear sono stati colpiti più duramente di tutti da questa piaga. Quelle bestie un tempo nobili ora sono uno strumento di distruzione — rabbiose e furiose. Forse ho una cura per questo male.\n\nPorta questa trappola nella foresta e posala a terra. Qualunque Rabid Thistle Bear attraversi la luce diventerà docile per un breve tempo. Una volta docile, l'orso ti seguirà. Riportalo qui, $N.", enHash = "1468a5a2", vanilla = true },
        objectives = { it = "Cattura un Rabid Thistle Bear vivo e riportalo a Tharnariun.\n\nSe non riesci a catturare un Rabid Thistle Bear e perdi la trappola, torna da Tharnariun Treetender e chiedigliene un'altra.", enHash = "a058398d", vanilla = true },
        progress = { it = "Mi hai portato l'animale malato, $N?\n\nSe non riesci a far scattare la trappola, non angustiarti — Tharnariun's Hope è eterna. Se ti serve un'altra trappola, abbandona il compito e torna a riferirmelo.", enHash = "c6e68306", vanilla = true },
        reward = { it = "Il nostro lavoro è appena cominciato, $N. Sei $Gpronto:pronta; per il prossimo compito?", enHash = "931ead79", vanilla = true },
    },
    [2138] = {
        title = { it = "Purificazione degli infetti", enHash = "4f0bce24", vanilla = true },
        text = { it = "Come temevo, la cura non funziona.\n\nMi rattrista moltissimo ordinare la morte di una qualunque bestia della natura, ma i Thistle Bear malati e corrotti vanno abbattuti.\n\nTorna nella foresta e uccidi 20 Rabid Thistle Bear, $N. Di certo non fermerà la piaga, ma per un po' rallenterà i danni che quegli animali stanno facendo alla nostra foresta e a chi ci vive.", enHash = "96e13212", vanilla = true },
        objectives = { it = "Ripulisci la foresta da 20 Rabid Thistle Bear e torna da Tharnariun Treetender, a Darkshore.", enHash = "2ed26392", vanilla = true },
        progress = { it = "Hai portato a termine il tuo compito?", enHash = "64b058e2", vanilla = true },
        reward = { it = "Hai reso ad Auberdine un grande servizio, $N, ma il tuo compito non è ancora finito.\n\nTorna da me quando ti sarai $Griposato:riposata;.\n\n...e $N, prepara la mente e l'anima ad altro sangue.", enHash = "654d91a3", vanilla = true },
    },
    [2139] = {
        title = { it = "Tharnariun's Hope", enHash = "f3017988", vanilla = true },
        text = { it = "La sopravvivenza del nostro popolo e delle nostre terre ha un prezzo doloroso, $N.\n\nHai versato il sangue dei servitori della natura; hai abbattuto molti animali malati. La gente di Auberdine ti è debitrice, perché il dolore della foresta si è alleviato — anche solo per un momento.\n\nHo un ultimo compito per te, ma sappi che dovrai uccidere ancora. Spero che sia l'ultima volta che ti chiamo, $N.\n\nIn una caverna a nord-est, vicino a Bashal'Aran, vive la Den Mother. Uccidila.", enHash = "6af47911", vanilla = true },
        objectives = { it = "Trova e uccidi la Den Mother.", enHash = "fadc15f7", vanilla = true },
        progress = { it = "Con la Den Mother infetta uccisa, il numero di Rabid Thistle Bear che entrano nelle nostre terre diminuirà. Non perdere tempo, $N.", enHash = "a9356785", vanilla = true },
        reward = { it = "Hai combattuto per Auberdine con coraggio e onore, $N. Nelle nostre terre dilaniate dalla guerra, la morte e la disperazione sono cosa comune. Molti non sapranno reggere la sfida di vivere nella nostra nuova casa, e sceglieranno di nascondersi in casa o di fuggire nelle terre più fortificate dell'Alleanza.\n\nGrazie, $N. Forse un giorno non lontano combatteremo fianco a fianco come compagni, contro un altro nemico.", enHash = "ccc45b44", vanilla = true },
    },
    [2158] = {
        title = { it = "Riposo e relax", enHash = "78d5be1a" },
        text = { it = "Ogni avventuriero dovrebbe riposare quando arriva la stanchezza — e non c'è posto migliore per riposarsi e rilassarsi della Lion's Pride Inn!\n\nIl mio migliore amico, Innkeeper Farley, gestisce la Lion's Pride. Se gli dici che ti mando io, magari ti farà i prezzi scontati su cibo e bevande.\n\nPer trovare la Lion's Pride Inn, viaggia verso sud lungo la strada che parte da qui — non puoi sbagliarti!", enHash = "931c3f3a" },
        objectives = { it = "Parla con Innkeeper Farley, alla Lion's Pride Inn.", enHash = "f8a1b79f" },
        reward = { it = "Riposo e relax per chi è stanco e infreddolito — questo è il nostro motto! Prego, siediti accanto al fuoco e riposa le ossa stanche.\n\nTi va di assaggiare un po' del nostro buon cibo e delle nostre bevande?", enHash = "5466d203" },
    },
    [2159] = {
        title = { it = "Dolanaar Delivery", enHash = "21cfb030", vanilla = true },
        text = { it = "Salute, giovane $C. Puoi darmi aiuto? Ho un pacco di erbe che devo consegnare alla città di Dolanaar. Ma ho ancora affari con i druidi di Shadowglen e non posso ancora andarmene.\n\nPuoi consegnare tu questo pacco per me? Va portato a Innkeeper Keldamyr, alla locanda di Dolanaar. Si trova lungo la strada, a sud.", enHash = "e433c89d", vanilla = true },
        objectives = { it = "Porta la Dolanaar Delivery a Innkeeper Keldamyr.", enHash = "23a11d1a", vanilla = true },
        progress = { it = "In cosa posso esserti utile, giovane? Sei qui per riposare alla locanda? Ti serve un'Hearthstone?", enHash = "ac0de220", vanilla = true },
        reward = { it = "Ah sì, la consegna di erbe da Shadowglen. È un peccato che Porthannius non abbia potuto portarla di persona, perché abbiamo molto di cui parlare, lui e io. Ma sono comunque felice di avere le erbe, e felice che tu sia $Gvenuto:venuta;.\n\nGià che sei qui, ti prego, riposati. Gli eroi devono tenere alte le forze e lo spirito, e devono trovare riposo e conforto ogni volta che possono. Perché trascurare la pace del corpo e della mente è una via sicura verso il fallimento.\n\nQuindi... riposa.", enHash = "5aa49f9a", vanilla = true },
    },
    [2160] = {
        title = { it = "Rifornimenti per Tannok", enHash = "5f32e63b", vanilla = true },
        text = { it = "Ehi! Hai l'aria di $Gun avventuriero in gamba:un'avventuriera in gamba;. Se hai intenzione di affrontare il passo, credi di poter portare un pacco alla locanda di Kharanos?\n\nAvevi intenzione di fermarti alla locanda, vero? Se ce la fai ad attraversare il passo, vorrai di sicuro prenderti una pausa lì.\n\nComunque, porta questo a Tannok Frosthammer, l'assistente del locandiere. Io il passo non posso attraversarlo, e passeranno giorni prima che arrivi una scorta di Mountaineer!", enHash = "ded480b1", vanilla = true },
        objectives = { it = "Consegna la Crate of Inn Supplies a Tannok Frosthammer, a Kharanos.", enHash = "09844836", vanilla = true },
        progress = { it = "Salve! Entra, siediti accanto al fuoco e scaldati con un boccale di birra.", enHash = "5828808c", vanilla = true },
        reward = { it = "Ah, finalmente, i rifornimenti di Hands! Cominciavo a preoccuparmi: da quando i trogg hanno invaso il passo, da Anvilmar arrivano pochissime notizie.\n\nGrazie di avermeli portati, $N. E mettiti pure $Gcomodo:comoda;. Devi essere $Gstanco:stanca; dopo il viaggio.", enHash = "cbf2dab5", vanilla = true },
    },
    [2161] = {
        title = { it = "Il fardello di un peon", enHash = "bc3a250f", vanilla = true },
        text = { it = "Scusa? Puoi aiutarmi?\n\nHo qui un carico di cibo. Ho camminato lungo la strada e ho affrontato scorpidi e ragni e di peggio! Ho portato il cibo alla Valley of Trials perché pensavo che ne avessero bisogno e mi piace dare una mano. Ma non hanno bisogno di cibo! Ora devo riportarlo a Razor Hill e ho paura di tutte le bestie lungo il cammino...\n\nPuoi portarlo tu per me? Io sono solo un peon, ma tu sei $Gun eroe:un'eroina;. Non temi niente!\n\nPortalo a Innkeeper Grosk, alla locanda di Razor Hill. Grazie!", enHash = "3d33dc9a", vanilla = true },
        objectives = { it = "Porta Ukor's Burden a Innkeeper Grosk, a Razor Hill.", enHash = "1cd2c6a9", vanilla = true },
        progress = { it = "$GBenvenuto:Benvenuta; a Razor Hill!", enHash = "a4b64907", vanilla = true },
        reward = { it = "Ah, questo è il cibo che Ukor ha portato alla Valley of Trials. Non ne avevano bisogno? Be', immagino che gli piaccia far patire la fame a voi eroi in addestramento. Tempra lo spirito, dicono!\n\nGrazie per aver riportato il cibo. Lo rimetto sugli scaffali... ma tieni, prima lascia che ti offra qualcosa da bere!\n\nE non dimenticare di riposare qui alla locanda. Sarai anche $Gun coraggioso:una coraggiosa; $C $Gpronto:pronta; ad affrontare il mondo, ma se le energie sono esaurite non farai molto bene né a te né all'Orda.", enHash = "c3637691", vanilla = true },
    },
    [2178] = {
        title = { it = "Vita facile con gli strider", enHash = "471e3bce", vanilla = true },
        text = { it = "Senti questo profumo delizioso? È la mia ricetta segreta, $N — Strider Stew appena fatto. Delizioso!\n\nTi piacerebbe imparare la ricetta?\n\nPrima di insegnartela, dovrai dimostrare di saper tenere testa a quelle bestie.\n\nOra, non mi aspetto che tu vada ad addomesticarne uno e me lo riporti in groppa, ma se riesci a ucciderne qualcuno e a riportarmi un po' della loro carne succulenta, forse riuscirai a convincermi a mostrarti i segreti dello Strider Stew.", enHash = "8c601c40", vanilla = true },
        objectives = { it = "Riporta 5 Strider Meat ad Alanndarian Nightsong, ad Auberdine.", enHash = "bb320909", vanilla = true },
        progress = { it = "La pentola è vuota e ho fame! Perché ci metti così tanto?", enHash = "1a26ae41", vanilla = true },
        reward = { it = "Fantastico! Assaggialo e dimmi cosa ne pensi, $N!", enHash = "4593b3d6", vanilla = true },
    },
    [2198] = {
        title = { it = "La Shattered Necklace", enHash = "30800c6d", vanilla = true },
        text = { it = "Hai trovato una collana annerita, anche se la patina nasconde una lavorazione elaborata e magica. La collana è rotta: al castone sembrano mancare tre gemme. Sul retro della collana c'è l'impronta sbiadita del sigillo cittadino di Ironforge. Sotto il sigillo ci sono tre minuscole lettere incise: \"TdK\".\n\nSe c'è qualcosa da ricavare da questa collana, dovrai scoprirne le origini. Forse il sigillo e le iniziali sono un punto di partenza...", enHash = "08935914", vanilla = true },
        objectives = { it = "Cerca chi ha creato la Shattered Necklace, per scoprire quanto potrebbe valere.", enHash = "25dadbae", vanilla = true },
        progress = { it = "Hai sbagliato gnomo, $Gamico:amica;! Io non c'ero! Non puoi dimostrare niente!\n\nAspetta un attimo... chi sei? Ma che... dove l'hai trovata questa collana?", enHash = "b850620c", vanilla = true },
        reward = { it = "Sì... sono io il gioielliere che ha fatto questa collana. E non sono nemmeno uno che dà informazioni gratis. Le informazioni non sono mai gratis, $Gamico:amica;. Se devo aiutarti, prima devi aiutare ME.", enHash = "d6d0f3ac", vanilla = true },
    },
    [2199] = {
        title = { it = "Informazioni a pagamento", enHash = "4e243a49", vanilla = true },
        text = { it = "Sono un gioielliere di grande fama, qui a Ironforge! Be', di fama passata, almeno... Sono caduto in disgrazia per colpa degli imbrogli di un concorrente! In questo mestiere una cattiva reputazione vuol dire la rovina. Il risultato è che mi ritrovo senza un soldo, con un buon nome che al momento è infangato.\n\nVoglio che tu mi procuri cinque Silver Bar per completare un ordine che ho ricevuto, il primo da quella che sembra un'eternità.\n\nPortami quelle cinque Silver Bar, e risponderò alle tue domande sulla collana.", enHash = "fb9fd7a9", vanilla = true },
        objectives = { it = "Porta cinque Silver Bar a Talvash del Kissel, a Ironforge.", enHash = "5809da1d", vanilla = true },
        progress = { it = "Hai le cinque Silver Bar che ti ho chiesto? Ti racconterò la mia triste storia di sventure riguardo alla collana che hai adesso... ma solo dopo aver avuto quelle barre! Ti prego, dai una mano a uno gnomo, vuoi?", enHash = "ffff97ef", vanilla = true },
        reward = { it = "Per me sei a posto; non m'importa cosa dicono tutti gli altri... Scherzo, scherzo! Davvero, grazie, $Gamico mio:amica mia;.\n\nAllora, la collana che hai è una delle mie creazioni migliori, ma le mancano tre gemme che la aiutano a legare a sé il potere magico. L'ho fatta tempo fa per un paladino. Si era dato da solo la missione di ripulire dalla \"corruzione malvagia\" un sito di scavo nelle Badlands chiamato Uldaman.\n\nBe'... quel paladino è morto a Uldaman, e quello è stato solo l'inizio delle mie disgrazie.", enHash = "f566e019", vanilla = true },
    },
    [2200] = {
        title = { it = "Ritorno a Uldaman", enHash = "edd66fba", vanilla = true },
        text = { it = "Un mio concorrente ha messo in giro la voce che la mia collana ha maledetto il paladino. Inutile dire che nessuno vuole comprare oggetti maledetti da un gioielliere.\n\n$N, ti propongo un accordo: trova le gemme e io rimetterò insieme la collana, a patto che tu vada in giro a dire che io NON faccio oggetti maledetti!\n\nProva a cercare indizi a Uldaman; magari vedi se il corpo del paladino è laggiù, visto che è l'ultimo che sappiamo averla avuta! Quando trovi le gemme, usa questa: ti permetterà di contattarmi qui a Ironforge.", enHash = "4b51c26b", vanilla = true },
        objectives = { it = "Cerca a Uldaman indizi su dove si trova ora la collana di Talvash. Il paladino ucciso di cui ha parlato è l'ultimo che l'ha avuta.", enHash = "dac4e66f", vanilla = true },
        reward = { it = "Resti di un paladino: leggendo il diario scopri che, dopo molti sforzi, il paladino aveva individuato dove si trovano tutte e tre le gemme mancanti:\n\nI nani Shadowforge hanno nascosto il rubino nella loro zona barricata, mentre combattevano contro i trogg per il controllo di Uldaman.\n\nI trogg hanno nascosto il topazio in un'urna vicino ad alcuni abitanti insoliti di Uldaman: dei nani dell'Alleanza!\n\nInfine, l'anziano dei trogg in persona ha preso lo zaffiro per sé.", enHash = "c1a9759d", vanilla = true },
    },
    [2201] = {
        title = { it = "Trova le gemme", enHash = "5d7173da", vanilla = true },
        text = { it = "Il diario del paladino ha fornito forse gli unici indizi che Uldaman potrà dare su dove si trovano le gemme della collana. Se quello che ha scritto il paladino è ancora esatto, bisognerà occuparsi dei nani Shadowforge e dei trogg che si contendono il controllo del sito di scavo.\n\nForte di queste informazioni, la ricerca delle gemme comincia sul serio. Quando avrai recuperato tutte le gemme, dovrai avvisare Talvash, a Ironforge, con la Phial of Scrying, come da sue istruzioni.", enHash = "e00e21aa", vanilla = true },
        objectives = { it = "Trova il rubino, lo zaffiro e il topazio sparsi per Uldaman. Una volta recuperati, contatta Talvash del Kissel a distanza usando la Phial of Scrying che ti ha dato.\n\nDal diario sai che...\n* Il rubino è stato nascosto in una zona barricata degli Shadowforge.\n* Il topazio è stato nascosto in un'urna in una delle zone dei trogg, vicino ad alcuni nani dell'Alleanza.\n\n* Lo zaffiro se l'è preso Grimlok, il capo dei trogg.", enHash = "7ba5422a", vanilla = true },
        progress = { it = "Dalle acque della Scrying Bowl prende forma l'immagine di Talvash.\n\n\"Wow, sei ancora $Gvivo:viva;! Sei $Griuscito:riuscita; a trovare le gemme? Sei davvero $Gil salvatore:la salvatrice; della mia reputazione che speravo? Ti prego, dimmi che non hai sprecato una carica della fiala solo per chiacchierare: quelle cose NON costano poco, e sono già in gravi difficoltà economiche.", enHash = "f787668a", vanilla = true },
        reward = { it = "Sì, sono proprio le tre gemme. Ottimo lavoro! Purtroppo il tuo lavoro non è ancora del tutto finito.\n\nNo, non sto cercando di fregarti, $C $Gsciocco:sciocca;. Si tratta di fare gioielli magici: gioielli della qualità di Talvash del Kissel! Serve una fonte di energia potente per dargli un po' di grinta. Be', quella collana di grinta da dare non ne ha più.", enHash = "f4f800d9", vanilla = true },
    },
    [2202] = {
        title = { it = "Reagenti da Uldaman", enHash = "7a56b083", vanilla = true },
        text = { it = "Ho sentito parlare di una pianta scoperta da poco, i Magenta Fungus Cap. Crescono a grappoli, nel profondo del sito di scavo di Uldaman; forse si trovano anche altrove, ma per ora è l'unico posto che conosco. Voglio studiarne il possibile uso in alchimia, ed è qui che entri in gioco tu.\n\nTrova i Magenta Cap Clusters e portami una dozzina di cappelli. Sta' $Gattento:attenta;: se li urti, i grappoli potrebbero sputare spore velenose.\n\nFallo per me, e ti preparerò una partita di uno dei miei famosi elisir ristoratori!", enHash = "09ecf1bb", vanilla = true },
        objectives = { it = "Porta 12 Magenta Fungus Cap a Jarkal Mossmeld, a Kargath.", enHash = "99bffc5e", vanilla = true },
        progress = { it = "Ti sei $Gprocurato:procurata; i Magenta Fungus Cap che mi servono per il mio lavoro alchemico? Niente cappelli, niente ricompensa!", enHash = "4e727109", vanilla = true },
        reward = { it = "Ben fatto, $N: hai dimostrato ancora una volta quanto vali! I cappelli saranno uno studio interessante, puoi scommetterci.\n\nE ora, come promesso, gusta un assaggio di uno dei miei intrugli ristoratori più potenti, dalla mia scorta personale...\n\nSe sei $Gun alchimista esperto:un'alchimista esperta;, forse potremmo fare altri affari. In ogni caso, ti ringrazio per il tuo aiuto!", enHash = "4c090a65", vanilla = true },
    },
    [2203] = {
        title = { it = "Reagenti dalle Badlands II", enHash = "896150c0", vanilla = true },
        text = { it = "Mi sei $Gstato:stata; di grande aiuto, $C. Vorrei ricompensarti con la ricetta stessa dell'intruglio che ti ho dato prima... ma devo chiederti un compito piuttosto pericoloso. Ascolta la mia richiesta.\n\nIn questa cassetta ci sono tre recipienti taumaturgici vuoti; sono intrisi di un'aura di sintonia che assorbirà il sangue di uno Scorched Guardian. Usarne uno sulla bestia la farà infuriare parecchio, quindi sei $Gavvisato:avvisata;. Quando li avrai riempiti tutti e tre, portameli.\n\nFallo, e la ricetta sarà tua.", enHash = "04cfa8ca", vanilla = true },
        objectives = { it = "Usa gli Empty Thaumaturgy Vessel sugli Scorched Guardian delle Badlands. Quando li avrai riempiti, portali a Jarkal Mossmeld, a Kargath.", enHash = "9ce933b4", vanilla = true },
        progress = { it = "Hai usato i recipienti per procurarmi il sangue di Scorched Guardian che mi serve? Sì, lo so che è un compito pericoloso... ma la ricetta del mio intruglio ristoratore aspetta solo il tuo successo. Rischio e ricompensa, $Gamico mio:amica mia;... rischio e ricompensa...", enHash = "ef0fee9b", vanilla = true },
        reward = { it = "Da alchimista ad alchimista, ti rendo omaggio. Ecco, prendi questa ricetta e imparala a memoria. Che ti porti il successo e le ricompense che ha portato a me in tutti questi anni.", enHash = "e9136678", vanilla = true },
    },
    [2204] = {
        title = { it = "Restaurare la collana", enHash = "2af7ee7a", vanilla = true },
        text = { it = "Dovrai trovare un po' di \"grinta\" per la collana, e Uldaman è probabilmente il posto migliore dove cercarla, in effetti. Immagino che là dentro ci siano un sacco di costrutti in giro, eh? Be', fai fuori il costrutto più grosso e più cattivo di quel posto e prendi la sua fonte di energia! Sono quasi sicuro di poterla fondere con la collana.\n\nSenza quella fonte di energia sarà impossibile riparare la collana. Torna da me qui a Ironforge quando l'avrai, e ti sistemeremo tutto!", enHash = "bf1bf4b2", vanilla = true },
        objectives = { it = "Procurati una fonte di energia dal costrutto più potente che riesci a trovare a Uldaman, e consegnala a Talvash del Kissel, a Ironforge.", enHash = "e75c1385", vanilla = true },
        progress = { it = "Non ti sei nemmeno $Gfermato:fermata; a darti una ripulita dopo aver lasciato Uldaman, eh? Sei $Gvenuto:venuta; dritto qui, alla faccia degli odori di sotterraneo che ti porti dietro. Be', speriamo che questa visita sia solo maleodorante, e non pure inutile.\n\nHai la fonte di energia per la collana?", enHash = "62e1306e", vanilla = true },
        reward = { it = "Accidenti: sono proprio contento di vedere te e questa fonte di energia tutti interi. Mi ci vorrà un momento per fondere magicamente la fonte di energia con la collana, ora che le gemme sono tornate al loro posto. Una volta finito, però, la collana sarà tua!\n\nSei $Gemozionato:emozionata;, vero? $GTutto:Tutta; un fremito per l'attesa? Ora, dove ho messo quel focus per incantesimi...", enHash = "867ebaef", vanilla = true },
    },
    [2205] = {
        title = { it = "Cerca lo SI: 7", enHash = "5736f4c1", vanilla = true },
        text = { it = "Il distintivo? Oh, non è niente, $Gpivello:pivella; — niente alla tua portata, in ogni caso. A giudicare dal tuo aspetto, direi che Mathias probabilmente ti scambierà per $Gil ragazzo:la ragazza; che consegna il formaggio invece che per $Gun vero ladro:una vera ladra;. Comunque sia, mi è stato affidato un lavoro e ho promesso di portarlo a termine.\n\nA proposito di consegne, porta questo pacco a Mathias: forse ti darà un incarico o due.\n\nDatti da fare.", enHash = { "a372d3ff", "b2d4a059" }, vanilla = true },
        objectives = { it = "Consegna il pacco di Keryn Sylvius a Master Mathias Shaw, agli Stormwind Barracks.", enHash = "ccec87c4", vanilla = true },
        progress = { it = "Posso aiutarti, $C?", enHash = "f0fb1ee5", vanilla = true },
        reward = { it = "Mi hai trovato — e a guardarti, direi che la corsa e la ricerca che ne è seguita potrebbero averti messo a dura prova, sia nella mente sia nel corpo.\n\nVuoi che Renzik ti mostri la strada per una locanda, o sei $Gpronto:pronta; per un po' di lavoro?", enHash = "ee233c65", vanilla = true },
    },
    [2206] = {
        title = { it = "Arraffa e scappa", enHash = "65ae47c2", vanilla = true },
        text = { it = "I nostri agenti sul campo riferiscono un'intensa attività dei Defias a sud di Goldshire. Dai rapporti risulta che i Defias hanno preso il controllo di Jerod's Landing e ora lo usano per contrabbandare grandi quantità di merce illegale da Redridge a Westfall.\n\nHo bisogno che tu ti infiltri nella casa del molo e mi porti quello Shipping Schedule, $N. Probabilmente lo troverai sepolto in fondo alle tasche del Dockmaster.\n\n...e, $N, se dovessi essere $Gscoperto:scoperta;, lo SI:7 negherà di sapere alcunché della tua esistenza.", enHash = "fedd90f1", vanilla = true },
        objectives = { it = "Trova il Defias Dockmaster e recupera lo Shipping Schedule per Master Mathias Shaw.", enHash = "c5041a31", vanilla = true },
        progress = { it = "La tua vita mortale si consuma a ogni istante che sprechi a gironzolare per la caserma, $C.", enHash = "4c6c1ba5", vanilla = true },
        reward = { it = "Sono sbalordito... Sbalordito che Keryn abbia finalmente trovato una recluta che forse ha la stoffa per diventare $Gun vero ladro:una vera ladra;. Prendi questa lama, $N. Verrà il giorno in cui sarai $Gchiamato:chiamata; di nuovo a servire lo SI:7. Affina le tue abilità, tieni gli occhi aperti e quella lama affilata.\n\nNon ci vedrai arrivare, ma lo sentirai, quando arriveremo...", enHash = "fe190e96", vanilla = true },
    },
    [2218] = {
        title = { it = "La via della salvezza", enHash = "7cfb6b38", vanilla = true },
        text = { it = "Un'altra anima perduta in cerca di una guida, eh? Immagino che tu voglia trovare uno scopo — il tuo scopo. L'ho visto mille volte: $Gun altro eroe:un'altra eroina; in cerca di lavoro.\n\nBeh, oggi è il tuo giorno fortunato, $Gamico:amica;. Hogral ha la cura per il tuo male.\n\nEcco cosa devi fare: prendi questa strada fino a Ironforge e raggiungi la Forlorn Cavern. Una volta lì, trova la gilda dei ladri e parla con Hulfdan Blackbeard. Sarà lui a metterti sulla via della salvezza.", enHash = "1a215ed1", vanilla = true },
        objectives = { it = "Parla con Hulfdan Blackbeard, a Ironforge.", enHash = "1b22b1bd", vanilla = true },
        reward = { it = "Così credi d'essere $Gun vero furfante:una vera furfante;? $GDestinato:Destinata; a essere $Guno:una; dei pochi eletti di Blackbeard — $Gun ufficiale:un'ufficiale; dell'Hidden Circle?\n\nSolo un buono a nulla da strapazzo penserebbe così bene di sé.\n\nÈ proprio quello che cerchiamo! $GBenvenuto:Benvenuta; a bordo, $N!", enHash = "72835420", vanilla = true },
    },
    [2238] = {
        title = { it = "Semplici sotterfugi", enHash = "547593f9", vanilla = true },
        text = { it = "Vedi, il re sta raschiando la cava fino all'osso per estrarre minerali e gemme. Più ricchezze di quante un nano dovrebbe vederne in dieci vite.\n\nL'Hidden Circle ha dei valori, $N. Diamo valore a ciò che ha valore. Capisci?\n\nOra, noi pensiamo che il re dovrebbe spartire un po' di quel bottino, ma non vogliamo che il vecchio 'Barbapuzza' sappia che sta spartendo... se capisci cosa intendo.\n\nC'è bisogno che tu vada a parlare con Onin MacHammar, dalle parti di Gnomeregan, e che ci riporti un rapporto. Quel nano furbo si è nascosto tra i lebbrosi. Fa' attenzione.", enHash = "12110300", vanilla = true },
        objectives = { it = "Trova Onin MacHammar, vicino a Gnomeregan.", enHash = "fcd41220", vanilla = true },
        reward = { it = "Shhhh! Abbassa la voce, testa vuota. Ci sentiranno.", enHash = "75d73a39", vanilla = true },
    },
    [2239] = {
        title = { it = "Onin's Report", enHash = "68289be4", vanilla = true },
        text = { it = "La cava? Sì, vedo passare qui davanti quei mostruosi carri a vapore corazzati quasi ogni giorno.\n\nI miei contatti a est mi dicono che il carro parte da Ironforge, carica merce alla Gol'Bolar Quarry, si ferma a Kharanos per fare rifornimento e poi, per qualche maledetto motivo, fa il giro lungo passando da Gnomeregan, prima di arrivare a Ironforge a scaricare la merce.\n\nÈ tutto nel rapporto, $R. Riportalo a Hulfdan, così può pianificare la prossima mossa.", enHash = "6d38de29", vanilla = true },
        objectives = { it = "Riporta Onin's Report a Hulfdan, a Ironforge.", enHash = "f7391f73", vanilla = true },
        progress = { it = "Ti è piaciuto il fetore degli gnomi lebbrosi? Te lo chiedo solo perché hai un sorriso folle stampato in faccia.\n\nChe notizie mi porti da Onin?", enHash = "ce576ae3", vanilla = true },
        reward = { it = "Il giro lungo? Per la mia barba!\n\nHai fatto un buon lavoro, $N. Prendi questo pugnale e sparisci. Il Circle ti chiamerà di nuovo quando il passo tre sarà pronto per partire.\n\nCos'è il passo tre? Viene subito dopo il passo due: io che ti pianto lo stivale nel sedere.\n\nTi interessa?", enHash = "89d3af56", vanilla = true },
    },
    [2240] = {
        title = { it = "La camera nascosta", enHash = "103a42b7", vanilla = true },
        text = { it = "E ora veniamo al compito da svolgere.\n\nC'è una camera segreta, la Chamber of Khaz'mul, che va esplorata. Il problema è che la camera si trova dietro un'enorme porta chiusa! Per fortuna io so come aprirla.\n\nHo descritto tutto nel mio diario, qui sul tavolo. Io e la mia banda per ora siamo bloccati qui... quindi tocca a te, $N, trovare la Chamber of Khaz'mul per noi!\n\nLeggi il mio diario, esplora la camera, poi fai rapporto a Prospector Stormpike, alla Lega degli Esploratori, a Ironforge.", enHash = "21e48d57", vanilla = true },
        objectives = { it = "Leggi Baelog's Journal, esplora la camera nascosta, poi fai rapporto a Prospector Stormpike.", enHash = "8df2e01e", vanilla = true },
        progress = { it = "Hai qualcosa da riferire?", enHash = "458aca6e", vanilla = true },
        reward = { it = "Hai visto la Chamber of Khaz'mul? Straordinario! Baelog era sicuro che esistesse, ma devo ammettere che avevo i miei dubbi.\n\nGrazie, $N. Con un po' di fortuna la tua scoperta spingerà i nostri capi a rinnovare gli sforzi per riprendere Uldaman. E se mai tornerà sotto il controllo di Ironforge, i segreti della Chamber of Khaz'mul saranno nostri!", enHash = "f6fc857c", vanilla = true },
    },
    [2241] = {
        title = { it = "La mela cade", enHash = "a0608ee3", vanilla = true },
        text = { it = "Dicono che sono 'innamorato perso', qualunque cosa voglia dire.\n\nCerto, passo ogni momento da sveglio a pensare a Syurna. Certo, la mia casa è piena di quadri e disegni di Syurna. Certo, spesso passo giorni senza mangiare, senza dormire e senza bere, mentre mi struggo per l'amore che avremmo potuto avere. È così sbagliato?\n\nE ora lei non vuole vedermi! ME! Ho provato a mandarle dei messaggi, ma lei non parla nemmeno con chi non sia un ladro.\n\nPotresti consegnarle questo fiore? Non dimenticare di dirle che è da parte di Jannok.", enHash = "b55e63bf", vanilla = true },
        objectives = { it = "Porta Jannok's Rose a Syurna, a Darnassus.", enHash = "a10b4635", vanilla = true },
        progress = { it = "Oh, ma che meraviglia. Hai portato dei fiori per il tuo funerale.", enHash = "8f38ebe1", vanilla = true },
        reward = { it = "Se avessi conservato ogni fiore che quello zuccone di Jannok mi ha mandato, avrei avuto di che aprire un negozio. Comunque sia, sembra che $Gl'ultimo messaggero:l'ultima messaggera; di Jannok possa rivelarsi utile.\n\nTi interessa un po' di lavoro, $C?", enHash = "c8c1ac95", vanilla = true },
    },
    [2242] = {
        title = { it = "Il destino chiama", enHash = "78290e47", vanilla = true },
        text = { it = "Crediamo che esista un essere che potrebbe aiutarci a capire cosa sta succedendo alle foreste di Teldrassil. Purtroppo, convincere la creatura a collaborare si è rivelato un disastro.\n\nSi nasconde su un ramo ai margini dell'Oracle Glade. Tutti quelli che finora si sono avvicinati al satiro, con la forza o con la diplomazia, hanno fatto una brutta fine. Forse la risposta è la furtività, $N.\n\nScopri cosa porta Sethir the Ancient nelle sue borse e fammi rapporto.", enHash = "f8b5b4c6", vanilla = true },
        objectives = { it = "Trova Sethir the Ancient e porta a Syurna tutti gli indizi che riesci a scoprire.", enHash = "86f4e970", vanilla = true },
        progress = { it = "Hai qualcosa da riferire su Sethir the Ancient, $N?", enHash = "419022df", vanilla = true },
        reward = { it = "Sono notizie cupe, $N. Sembrerebbe che il morbo che ha colpito le foreste e i fiumi di Darkshore abbia cominciato a portare la corruzione nella nostra casa.\n\nCi hai servito bene, ma qui non c'è più nulla che tu possa fare. Prendi questa lama come ricompensa per i tuoi servigi a Teldrassil.", enHash = "264480d0", vanilla = true },
    },
    [2258] = {
        title = { it = "Reagenti dalle Badlands", enHash = "1dbee480", vanilla = true },
        text = { it = "$N, mi servirebbe il tuo aiuto, se te la senti. Sono un alchimista di una certa fama, e cerco il tuo aiuto per procurarmi alcuni reagenti che si trovano nelle Badlands.\n\nPer rifornire le mie scorte mi servono queste cose: cinque Buzzard Gizzard, dieci Crag Coyote Fang e cinque Rock Elemental Shard. Ovviamente puoi prenderli dalle bestiacce stesse; se non sei $Gil tipo:la tipa; che combatte, trovati degli amici che lo siano.\n\nProcurami queste cose e ci guadagnerai qualche moneta. Allora, che vuoi fare?", enHash = "cc3e2d78", vanilla = true },
        objectives = { it = "Porta 5 Buzzard Gizzard, 10 Crag Coyote Fang e 5 Rock Elemental Shard a Jarkal Mossmeld, a Kargath, nelle Badlands.", enHash = "ae48cb54", vanilla = true },
        progress = { it = "Hai già preso le cose che mi servono? Non sarai $Gpagato:pagata; se non mi porti quei reagenti.", enHash = "9735ae37", vanilla = true },
        reward = { it = "Ah, ben fatto! Queste mi basteranno almeno per un po'. Ecco la tua paga, come promesso.\n\nSe ti interessa, ci sono altri reagenti che mi farebbero comodo. Questi però si trovano solo nelle profondità degli scavi di Uldaman. Non sarà facile procurarli, ma se vorrai aiutarmi ancora farò in modo che ne valga la pena.\n\nMagari qualcosa di più di qualche moneta luccicante, eh?", enHash = "bd33b814", vanilla = true },
    },
    [2259] = {
        title = { it = "Erion Shadewhisper", enHash = "886e947a", vanilla = true },
        text = { it = "Non preoccuparti, $N, non ti sto mandando da Syurna. Erion richiede la tua presenza al Cenarion Enclave. Sbrigati!", enHash = "6df9317c", vanilla = true },
        objectives = { it = "Mettiti in contatto con Erion Shadewhisper, a Darnassus.", enHash = "eade3c9d", vanilla = true },
        reward = { it = "È ora di allargare i tuoi orizzonti, $R: il mondo ti aspetta.", enHash = "475447e6", vanilla = true },
    },
    [2260] = {
        title = { it = "Per volere di Erion", enHash = "8bc4de7a", vanilla = true },
        text = { it = "La notizia delle tue imprese si è diffusa in lungo e in largo, $N. Così lontano, anzi, che la Stormwind Intelligence ha chiesto di te per nome.\n\nIl viaggio è faticoso e non privo di pericoli, ma l'occasione di addestrarsi presso lo SI:7 non va presa alla leggera.\n\nUn mondo nuovo ti aspetta, $N. Raggiungi Old Town, a Stormwind, e parla con Renzik \"The Shiv\" al quartier generale dello SI:7.", enHash = "d9286c43", vanilla = true },
        objectives = { it = "Raggiungi Stormwind City e chiedi di parlare con Renzik \"The Shiv\".", enHash = "27fe7e8b", vanilla = true },
        reward = { it = "Hai risposto alla chiamata dello SI:7, $N, e hai viaggiato da coste lontane per unirti a noi; tuttavia, hai ancora molto da imparare.", enHash = "c11fddd0", vanilla = true },
    },
    [2278] = {
        title = { it = "I dischi di platino", enHash = "071ba219", vanilla = true },
        text = { it = "Al centro di questa camera del tesoro ci sono quattro enormi dischi di platino, ognuno ornato di numerosi sigilli di origine sconosciuta. Toccarli ti fa formicolare la mano. Subito dopo che hai toccato i dischi, compare l'immagine di un grande guardiano di pietra.\n\n\"Saluti. Sono un custode della conoscenza. La sintesi dei Terrigeni compiuta dai Creatori è stata registrata e conservata qui, per questo mondo, nei Discs of Norgannon.\"\n\nHai scoperto una ricchezza di sapere sul mondo mai scoperta prima!", enHash = "5e342c1c", vanilla = true },
        objectives = { it = "Parla con il guardiano di pietra e scopri quale antico sapere custodisce. Quando avrai appreso il sapere che ha da offrire, attiva i Discs of Norgannon.", enHash = "7a9865d3", vanilla = true },
        progress = { it = "La voce del guardiano di pietra sembra risuonare nel profondo del tuo essere:\n\n\"Prima devi soddisfare il requisito di assimilazione dei dati dei Discs of Norgannon; una volta soddisfatto questo requisito, ti sarà permesso ottenere una versione portatile dei dati archiviati. Assicurati prima di aver esplorato a fondo le informazioni di questo archivio.\"", enHash = "ed1e80a1", vanilla = true },
        reward = { it = "Seguendo le istruzioni del guardiano di pietra, accedi di nuovo ai Discs of Norgannon, ora che hai appreso la storia dei Terrigeni, dei trogg e dei nani. Dall'interno dei dischi si sente un ronzio debole e breve. Poi il guardiano di pietra parla:\n\n\"I dischi sono stati sintetizzati. Accedi ancora una volta ai Discs of Norgannon per ricevere la tua copia personale.\"", enHash = "2d53d7bd", vanilla = true },
    },
    [2279] = {
        title = { it = "I dischi di platino", enHash = "071ba219", vanilla = true },
        text = { it = "Toccare di nuovo i Discs of Norgannon ti fa formicolare la mano. Questa volta, però, dall'interno dei dischi si sente uno strano rumore di ingranaggi.\n\nIl tuo zaino diventa all'improvviso più pesante di prima. Dentro scopri una versione in miniatura dei dischi!\n\nSenza dubbio, un oggetto del genere sarebbe prezioso per chiunque si interessi alla storia antica di Azeroth. La Lega degli Esploratori di Ironforge è proprio un gruppo così, conosciuto in tutta l'Alleanza; forse potrà farne buon uso.", enHash = "d535e937", vanilla = true },
        objectives = { it = "Porta la versione in miniatura dei Discs of Norgannon alla Lega degli Esploratori, a Ironforge.", enHash = "1a7de5a9", vanilla = true },
        progress = { it = "Sì, posso aiutarti in qualcosa? Ti assicuro che in questo momento sono molto occupato. Se però è una questione di grande importanza per la Lega degli Esploratori, allora sono tutt'orecchi!", enHash = "cea397d0", vanilla = true },
        reward = { it = "Cos'hai lì... oh, cielo. Dove l'hai trovato?\n\nNo, davvero?\n\nHai parlato con chi, di cosa?\n\nNO, DAVVERO?!\n\n$GMio caro:Mia cara; $C, potresti aver appena fatto la scoperta archeologica dell'anno! Per gli dèi, chi voglio prendere in giro: la scoperta del secolo! Se questi dischi sono quello che penso, potrebbero essere proprio la chiave che cercavamo! Potrebbero dimostrare una volta per tutte la legittimità della creazione incantata dei nani!", enHash = "8b1072c3", vanilla = true },
    },
    [2280] = {
        title = { it = "I dischi di platino", enHash = "071ba219", vanilla = true },
        text = { it = "Toccare di nuovo i Discs of Norgannon ti fa formicolare la mano. Questa volta, però, dall'interno dei dischi si sente uno strano rumore di ingranaggi.\n\nIl tuo zaino diventa all'improvviso più pesante di prima. Dentro scopri una versione in miniatura dei dischi!\n\nSenza dubbio, un oggetto del genere sarebbe prezioso per chiunque si interessi alla storia antica di Azeroth. I saggi di Thunder Bluff sono proprio storici di questo tipo, conosciuti in tutta l'Orda; forse potranno farne buon uso.", enHash = "73c6b1dd", vanilla = true },
        objectives = { it = "Porta la versione in miniatura dei Discs of Norgannon a uno dei saggi di Thunder Bluff.", enHash = "7de3a420", vanilla = true },
        progress = { it = "Sì, giovane, ti vedo entrare nella mia tenda con passo deciso... con determinazione nei tuoi propositi. Cerchi il mio consiglio su una questione di grande importanza per l'Orda? O forse desideri che ti venga svelato un mistero dell'universo?", enHash = "522ef690", vanilla = true },
        reward = { it = "Cosa sono questi, allora?\n\nNotevole, giovane! In questi dischi percepisco segreti che la terra ha custodito gelosamente per molti anni. Hai fatto molto bene a portarli qui da me.", enHash = "e6288185", vanilla = true },
    },
    [2281] = {
        title = { it = "Appuntamento a Redridge", enHash = "126f64db", vanilla = true },
        text = { it = "Mandarti sul campo adesso sarebbe un suicidio. A Renzik non serve un altro ladro morto sulla coscienza. Ma non preoccuparti, $N: Renzik ti metterà al passo.\n\nRaggiungi le Redridge Mountains e parla con un collaboratore dello SI:7 di nome Lucius. Lo troverai a bighellonare vicino ai moli di Lakeshire, insieme agli altri buoni a nulla dall'aria losca.", enHash = "ad16c4a7", vanilla = true },
        objectives = { it = "Mettiti in viaggio verso Lakeshire, nelle Redridge Mountains, e parla con Lucius.", enHash = "497b4571", vanilla = true },
        reward = { it = "Ah, quindi hai le dita un po' grassocce, eh? Non preoccuparti, $N: ho trasformato in ladri provetti dei borsaioli ben più inetti di te.", enHash = "c04f30e6", vanilla = true },
    },
    [2282] = {
        title = { it = "Alther's Mill", enHash = "ea9a6044", vanilla = true },
        text = { it = "Qui addestriamo ladri da anni! Dopotutto, non tutti i furfanti nascono con la grazia e la finezza del vecchio Lucius.\n\nQui sopra, poco fuori dalla strada, troverai Alther's Mill. Lassù ho un forziere con dentro una cosa importante. Va' a prendermela! Riportami quel gettone e riceverai il tuo Certificate of Thievery!", enHash = "5ddd47de", vanilla = true },
        objectives = { it = "Apri Lucius's Lockbox, recupera il Token of Thievery e riportalo a Lucius, a Lakeshire.", enHash = "25977b6f", vanilla = true },
        progress = { it = "Mi sono dimenticato di dirti degli orchi?\n\nHo sentito che ficcanasano lassù, vicino al mulino.", enHash = "394353e6", vanilla = true },
        reward = { it = "L'hai scassinato, eh? Bel lavoro, $N.\n\nSe muori adesso, possiamo stare tranquilli: sarà per colpa della tua stupidità e non dell'inesperienza.", enHash = "0c5451ee", vanilla = true },
    },
    [2283] = {
        title = { it = "Recupero della collana", enHash = "a704d2ff", vanilla = true },
        text = { it = "Abbiamo un lavoro per te, sempre che tu abbia il fegato di farlo!\n\nNel profondo delle Badlands c'è il sito di scavo di Uldaman. Ci è arrivata la storia di un paladino idiota che ci è morto di recente. Il motivo per cui ce ne importa è che aveva addosso una collana di grande valore. A quanto pare ha tre grosse gemme: un rubino, uno zaffiro e un topazio.\n\nEcco il punto: la vogliamo, e per averla paghiamo IL MASSIMO in argento. Potrebbe essere danneggiata, ma poco importa: qualunque graffio abbia, lo sistemiamo noi.", enHash = "71fadd1f", vanilla = true },
        objectives = { it = "Cerca una collana di valore nel sito di scavo di Uldaman e riportala a Dran Droffers, a Orgrimmar. La collana potrebbe essere danneggiata.", enHash = "7a6ddfa9", vanilla = true },
        progress = { it = "Allora, ce l'hai la collana? Da noi non vedrai un soldo, se non hai quella collana!", enHash = "1f955189", vanilla = true },
        reward = { it = "Mmm, roba da recupero! Sento l'odore della collana da qui. Ora diamo un'occhiata a questa bellezza...\n\nEhi, cosa credi di fare? Questa collana non ha le gemme! Pensavi che non ce ne saremmo accorti? Perfino Malton vedrebbe che le gemme non ci sono.\n\nBe', forse non le hai rubate tu... ma senza quelle gemme questa collana non vale niente! Il tuo lavoro qui non è ancora finito, nemmeno per sogno!", enHash = "3baf6cc3", vanilla = true },
    },
    [2284] = {
        title = { it = "Recupero della collana, secondo tentativo", enHash = "7933b54c", vanilla = true },
        text = { it = "Com'è vero che Malton è uno stupido, quelle gemme sono ancora da qualche parte a Uldaman. Dovrai tornare laggiù a cercarle.\n\nCome ho detto prima, se le informazioni che abbiamo sono giuste, con la collana vanno un rubino, uno zaffiro e un topazio. Trovali e rimettili nella collana.\n\nQuanto a dove siano le gemme, chi lo sa? Magari avrai fortuna e troverai il cadavere del paladino. Se non l'hanno già spogliato di tutto, magari le ha ancora addosso.", enHash = "dbcf0207", vanilla = true },
        objectives = { it = "Trova un indizio su dove si trovano le gemme, nelle profondità di Uldaman.", enHash = "eb75fdd4", vanilla = true },
        reward = { it = "Sembra che tu abbia trovato i resti del paladino di cui ti aveva parlato Dran. Frugando tra i resti scopri quello che sembra il suo diario. Il libro è in pessime condizioni: il sangue secco ha macchiato quasi tutto il testo. Quello che riesci a leggere, però, è incomprensibile: per quanto ne sai, è scritto nella lingua degli umani.\n\nSe vuoi ricavarne qualcosa, dovrai far tradurre il libro.", enHash = "fbeea47d", vanilla = true },
    },
    [2298] = {
        title = { it = "Una retata reale", enHash = "e4fc76ec", vanilla = true },
        text = { it = "Allora, eravamo lì lì per cominciare a pianificare la fase III, quando un paio di teste di legno di Magni piombano qui dentro parlando di un qualche colpo e arrestano alcuni dell'Hidden Circle.\n\nBeh, nessuno mette i ferri al vecchio Blackbeard! La discussione si è fatta pesante e accesa, e in qualche modo è saltato fuori il tuo nome!\n\nIl mio consiglio? Prendi il primo grifone che parte da Ironforge e vai a Stormwind. Raggiungi Old Town e, una volta lì, parla con un mio vecchio amico di nome Renzik \"The Shiv\".", enHash = "f2b5466b", vanilla = true },
        objectives = { it = "Raggiungi Stormwind e cerca Renzik \"The Shiv\".", enHash = "5b1fbccb", vanilla = true },
        reward = { it = "Fa sempre piacere avere $Guno:una; dei ladri di Hulfdan tra le nostre file!", enHash = "ca45072e", vanilla = true },
    },
    [2299] = {
        title = { it = "Da Hulfdan!", enHash = "0ad1ea7c", vanilla = true },
        text = { it = "Dove ti eri $Gcacciato:cacciata;, $N? Hulfdan ti sta cercando dappertutto. Pensavamo che il re ti avesse messo ai ferri.\n\nVa' a Ironforge il prima possibile e parla con Hulfdan!", enHash = "98f413f7", vanilla = true },
        objectives = { it = "Raggiungi Ironforge e parla con Hulfdan Blackbeard.", enHash = "bed7a9c4", vanilla = true },
        reward = { it = "Abbassa la voce, $N, le guardie potrebbero sentirti.", enHash = "a900c877", vanilla = true },
    },
    [2300] = {
        title = { it = "SI:7", enHash = "0035d813", vanilla = true },
        text = { it = "Renzik ti stava cercando, $Gpivello:pivella;.\n\nIo, al posto tuo, non farei aspettare il vice di Mathias.", enHash = "77b4acd1", vanilla = true },
        objectives = { it = "Raggiungi Stormwind e cerca Renzik \"The Shiv\".", enHash = "5b1fbccb", vanilla = true },
        reward = { it = "Sei $Gpronto:pronta; a metterti al lavoro o ti serve un pisolino prima di cominciare?", enHash = "d17dbd11", vanilla = true },
    },
    [2318] = {
        title = { it = "Tradurre il diario", enHash = "9c493073", vanilla = true },
        text = { it = "In una specie di vicolo cieco, sai che dovrai far tradurre il libro in una lingua che capisci. Nel mondo ci sono di sicuro parecchie persone in grado di farlo; il posto più vicino dove potrebbe esserci qualcuno capace, però, è l'avamposto di Kargath, nelle Badlands. Forse è un buon punto di partenza.", enHash = "9d430fb5", vanilla = true },
        objectives = { it = "Trova qualcuno che sappia tradurre il diario del paladino. Il posto più vicino dove potrebbe esserci qualcuno è Kargath, nelle Badlands.", enHash = "4e4553de", vanilla = true },
        reward = { it = "Potente $C, so cosa fai qui nelle Badlands. So che cerchi il mio dono delle lingue. Sei sulle tracce dei pezzi di quella collana che hai trovato a Uldaman.\n\nTi sorprende? Non dovrebbe: sapere queste cose è il mio lavoro. Parliamo piuttosto di cosa farai in cambio di un diario tradotto. Fidati: sono l'unico che troverai in grado di tradurlo.\n\nMeglio ancora, lascia che ti faccia un'offerta migliore di quella di Dran Droffers, che ti permetterà comunque di portare a termine il tuo accordo con loro. Ora ti interessa, vero?", enHash = "982f2a10", vanilla = true },
    },
    [2338] = {
        title = { it = "Tradurre il diario", enHash = "9c493073", vanilla = true },
        text = { it = "Quelli della Droffers and Son Salvage non sono abbastanza furbi da ridare magia alla collana, ma io sì. Voglio solo studiare la collana per imparare a farne anch'io. Per farlo, mi serve la tua collana. Prestamela, e in cambio del tempo che avrò per studiarla ti tradurrò il diario. Mentre tu cerchi le gemme, dovrei avere abbastanza tempo per imparare quello che mi serve.\n\nÈ un accordo semplice, e nessun altro lo verrà a sapere. Allora, che vuoi fare?", enHash = "8a2b9119", vanilla = true },
        objectives = { it = "Presta la collana a Jarkal. In cambio, lui ti tradurrà il diario.", enHash = "fc597f2f", vanilla = true },
        progress = { it = "Ci hai pensato, vero? Sei $Gun:una; $C $Gfurbo:furba; se accetti questo accordo: tu e io otterremo quello che vogliamo tutti e due, e quelli della Droffers and Son Salvage crederanno di ottenere quello che vogliono loro.", enHash = "ac305f8e", vanilla = true },
        reward = { it = "Un buon affare lo riconosci quando lo vedi: sapevo di poter contare su di te.\n\nCi vorrà solo un momento, il tempo di lanciare un incantesimo per tradurre in fretta la lingua degli umani in una forma che tu possa capire. Sono un troll di parola: chiedi a chiunque nell'Orda di Jarkal Mossmeld. Ora cominciamo...", enHash = "06553b1e", vanilla = true },
    },
    [2339] = {
        title = { it = "Trova le gemme e la fonte di energia", enHash = "d7ec8ec5", vanilla = true },
        text = { it = "Ecco il diario, tradotto perché tu possa leggerlo da te. Il succo è che i nani hanno nascosto il rubino, i trogg hanno nascosto il topazio, e un trogg di nome Grimlok ha lo zaffiro.\n\nSenti: ti servirà una fonte di energia per far funzionare di nuovo la collana. Dran Droffers non lo sa. Per trovarne una, ecco cosa farei io: scendi più in profondità che puoi a Uldaman e uccidi il costrutto più forte che c'è. Senza dubbio, qualunque cosa sia, ce l'avrà.\n\nQuando avrai raccolto tutto, torna qui!", enHash = "7c4d4ef2", vanilla = true },
        objectives = { it = "Recupera a Uldaman tutte e tre le gemme e una fonte di energia per la collana, poi portale a Jarkal Mossmeld, a Kargath. Jarkal crede che una fonte di energia si possa trovare sul costrutto più forte di Uldaman.\n\nDal diario sai che...\n* Il rubino è stato nascosto in una zona barricata degli Shadowforge.\n* Il topazio è stato nascosto in un'urna in una delle zone dei trogg, vicino ad alcuni nani dell'Alleanza.\n* Lo zaffiro se l'è preso Grimlok, il capo dei trogg.", enHash = "62c444fd", vanilla = true },
        progress = { it = "Ti aspetta un altro viaggio nelle profondità di Uldaman, se non hai le gemme e una fonte di energia in grado di incanalare di nuovo il potere magico nella collana.\n\nLe gemme te le riprenderai per consegnarle a quegli scagnozzi di Orgrimmar; io terrò la fonte di energia, visto che è proprio quella che farà funzionare la collana...", enHash = "b603dc19", vanilla = true },
        reward = { it = "Ben fatto davvero, $C. Ora i frutti del nostro piccolo dirottamento ripagheranno lautamente. Con la collana in sé ho finito, e sono sicuro di poter ripetere il procedimento di costruzione ogni volta.\n\nMa prima userò un incantesimo preparato apposta per analizzare in fretta quelle gemme, prima che tu riporti loro e la collana a Orgrimmar. Ci vorrà solo un attimo.", enHash = "7916af79", vanilla = true },
    },
    [2340] = {
        title = { it = "Consegna le gemme", enHash = "871679ee", vanilla = true },
        text = { it = "Va bene qualunque castone e qualunque gemma, purché siano dello stesso materiale. Questa fonte di energia, invece, è quella che riporterà la magia nella collana... spero.\n\nTi fornirò volentieri le gemme che servono per la tua versione della collana, a patto che la fonte di energia funzioni davvero.\n\nVa' a Orgrimmar e mantieni la tua parte del patto con la Droffers and Son Salvage. Solo, tieni la bocca chiusa sul nostro accordo, e quando torni potrei avere una splendida sorpresa per te.", enHash = "9572c4a4", vanilla = true },
        objectives = { it = "Consegna il Necklace and Gem Salvage a Dran Droffers, a Orgrimmar.", enHash = "87fa0c75", vanilla = true },
        progress = { it = "Ma guarda chi si vede! Te la sei presa comoda, vedo. Speriamo che non sia una perdita di tempo! Non verrai $Gpagato:pagata; se non hai tutto quello che ti ho chiesto. E fidati: controlleremo tutto due e tre volte!", enHash = "b7169510", vanilla = true },
        reward = { it = "Sì, c'è tutto. Senti, ti spiace se ci teniamo anche la borsa? No? Grazie, molto gentile! Ah!\n\nQuesta collana sarà il nostro colpo migliore di sempre! Ma non prendertela troppo: sono sicuro che comunque la collana non ti sarebbe andata. Ah, di nuovo!\n\nPatti chiari: ecco il tuo compenso per il recupero. Per ora i nostri affari sono chiusi; ripassa più tardi per vedere se abbiamo altro lavoro. Fino ad allora, sparisci!", enHash = "d105310b", vanilla = true },
    },
    [2341] = {
        title = { it = "Recupero della collana, terzo tentativo", enHash = "7933b54d", vanilla = true },
        text = { it = "Mentre Dran e Malton Droffers cominciano a litigare sul loro nuovo bottino, metà dell'accordo è conclusa. Ora ci vuole un viaggio nelle Badlands per chiudere la faccenda: Jarkal Mossmeld, a Kargath, potrebbe avere una ricompensa speciale che ti aspetta.", enHash = "448e43cb", vanilla = true },
        objectives = { it = "Va' da Jarkal Mossmeld, a Kargath, per vedere se ci è riuscito.", enHash = "1824fe7e", vanilla = true },
        reward = { it = "La fonte di energia che mi hai dato ha superato ogni mia aspettativa. Sono riuscito a fare una collana per te e una per me, e me ne avanza abbastanza per farne almeno altre tre. Frutteranno un bel compenso, e la Droffers and Son Salvage non ne saprà niente.\n\nEcco a te, $Gamico mio:amica mia;. Ti ringrazio per un lavoro splendido... e ti do qualcosa di davvero speciale per il disturbo.", enHash = "5eb3d02c", vanilla = true },
    },
    [2342] = {
        title = { it = "Tesori recuperati", enHash = "745655cc", vanilla = true },
        text = { it = "Spazzare i recinti dei pipistrelli con questa scopa non si addice a un Garrett! Con questo lavoro maledetto ho messo da parte qualche moneta, e sono disposto a spenderla per te pur di migliorare la mia posizione.\n\nL'arma preferita della famiglia Garrett è chiusa nel nostro forziere nella South Common Hall di Uldaman, da quando noi Garrett lavoravamo lì come scavatori. Senza di essa resterò bloccato qui per sempre, letteralmente, a spazzare dietro a questi pipistrelli infernali.\n\nRecupera il tesoro della mia famiglia e portamelo! Aiutami a riprendermi ciò che mi spetta per nascita!", enHash = "29419bc1", vanilla = true },
        objectives = { it = "Prendi il tesoro di famiglia di Patrick Garrett dal forziere di famiglia nella South Common Hall di Uldaman, e portalo a Patrick, nell'Undercity.", enHash = "b85fed5f", vanilla = true },
        progress = { it = "Non si finisce mai di spazzare... questi pipistrelli non si stancano mai di prendersi gioco di me e della mia scopa. Dimmi che hai recuperato il tesoro della mia famiglia! Ti ho offerto il mio argento: non basta?!", enHash = "bc51bb79", vanilla = true },
        reward = { it = "Finalmente, una scopa degna di un Garrett. Vali fino all'ultima moneta d'argento che ho speso per te, parola mia!\n\nMi sentite, pipistrelli schifosi? Ora impugno l'arma preferita della famiglia Garrett! Tremate, pipistrelli, tremate!!", enHash = "5a539072", vanilla = true },
    },
    [2358] = {
        title = { it = "Horns of Nez'ra", enHash = "6c8dd5ac", vanilla = true },
        text = { it = "Molti anni fa, gli Horns of Nez'ra furono rubati dal Ravenholdt Manor. Li ho cercati attraverso continenti e oceani, solo per scoprire che queste bestie insignificanti li avevano sempre avuti in mano loro.\n\nUccidi ogni orco Blackrock che incontri finché non avrai recuperato gli Horns of Nez'ra. Se recuperi le corna, mi troverai a Lakeshire.\n\nFallo per me, e il tuo nome sarà noto a Ravenholdt, $N.", enHash = "52050705", vanilla = true },
        objectives = { it = "Riporta gli Horns of Nez'ra ad Arantir's Shadow, a Lakeshire.", enHash = "b93ad018", vanilla = true },
        progress = { it = "Hai le corna del principe demone?", enHash = "ea8112b4", vanilla = true },
        reward = { it = "Negare il manufatto a Ravenholdt significherebbe negare la propria stessa esistenza. Ben fatto, $Gladro:ladra;. Un giorno potresti camminare tra gli assassini di Ravenholdt.\n\nDa giovane ladro, durante le mie avventure a Darkshore, ho scoperto un tè che ridà energia in combattimento. Mi è stato utile per tutti questi anni, e ora ti lascio assaggiare il Thistle Tea. Bevilo quando sei $Gstanco:stanca;, $N, e torna a combattere con vigore!", enHash = "0f7c7a3d", vanilla = true },
    },
    [2359] = {
        title = { it = "Klaven's Tower", enHash = "7d01d494", vanilla = true },
        text = { it = "Tengo d'occhio questa torre da settimane, $N. Di recente è arrivato un grosso carico da Duskwood, e insieme sono arrivate quelle guardie.\n\nChe cosa sono? Ne so quanto te. Una cosa però posso dirtela: non sono umani.\n\nComunque, nel carico c'era un forziere, ed è quello che immagino stiano sorvegliando quegli abomini. Lo zombie con gli spuntoni ha una chiave che ci servirà.\n\nPrendi quella chiave, entra nella torre e scopri cosa c'è in quel forziere. Porta quello che trovi a Mathias.", enHash = "306ce073", vanilla = true },
        objectives = { it = "Ruba la Defias Tower Key, entra con la forza nella Defias Tower e scopri il contenuto della Duskwood Chest. Porta tutte le informazioni che trovi a Mathias Shaw, a Stormwind. Leggi Kearnen's Journal per saperne di più sulla torre.", enHash = "5ac65455", vanilla = true },
        progress = { it = "Notizie da Agent Kearnen?", enHash = "7310a7eb", vanilla = true },
        reward = { it = "Questo spiegherebbe i droni dei Defias che tu e Kearnen avete visto fuori dalla torre, $N. E spiegherebbe anche il coinvolgimento della Venture Company con i Defias e gli strani carichi provenienti da Duskwood.\n\nSecondo questo libro, i troll di Zanzil a Stranglethorn hanno scoperto un modo per risvegliare i morti con le pozioni... o, per essere più precisi, con il veleno.\n\nSenza una solida conoscenza dei veleni non servirai a niente allo SI:7, $N — soprattutto ora che abbiamo a portata di mano la ricetta per creare la non morte.", enHash = "2b9cc92d", vanilla = true },
    },
    [2360] = {
        title = { it = "Mathias e i Defias", enHash = "3500961b", vanilla = true },
        text = { it = "Appena in tempo, $N. La ricognizione dello SI:7 segnala un'attività dei Defias insolitamente intensa a Westfall.\n\nSembra che i Defias abbiano occupato una torre di guardia abbandonata dell'Alleanza a sud-est di Sentinel Hill, e che la usino come base operativa per contrabbandare merci dalla via di rifornimento di Redridge.\n\nRaggiungi Westfall e mettiti in contatto con Agent Kearnen per il resoconto. La troverai nascosta vicino alla torre.\n\n...e, $N, se dovessi essere $Gscoperto:scoperta;, lo SI:7 negherà di sapere alcunché della tua esistenza.", enHash = "75a6edcc", vanilla = true },
        objectives = { it = "Raggiungi Westfall e trova Agent Kearnen per il resoconto.", enHash = "85f3c565", vanilla = true },
        reward = { it = "Mathias ha finalmente mandato $Gun altro agente:un'altra agente; a darmi man forte, eh? Beh, spero che sia $Gpronto:pronta; a sentire qualche brutta notizia.", enHash = "2b437869", vanilla = true },
    },
    [2361] = {
        title = { it = "Restaurare la collana", enHash = "2af7ee7a", vanilla = true },
        reward = { it = "Ti do volentieri questa collana, potente $C. Mi hai reso un servizio inestimabile, e per questo ti ringrazio. Indossala con orgoglio, e assicurati di dire ad alta voce e più volte chi te l'ha fatta!\n\nE poi, se potessi aggiungere che non è affatto maledetta, sarebbe fantastico.", enHash = "122fe398", vanilla = true },
    },
    [2378] = {
        title = { it = "Trova la Shattered Hand", enHash = "23b81cad", vanilla = true },
        text = { it = "Hai servito bene gli Inseguitori della Morte, $N, ma forse è ora che tu ti spinga più lontano. Anche se hai mostrato attitudine per la furtività e l'inganno, hai ancora bisogno di molto addestramento.\n\nGli Inseguitori della Morte hanno degli alleati nella Shattered Hand. Cerca quelli che potrebbero aiutarci: trova Shenthul a Orgrimmar.", enHash = "9b4d8be7", vanilla = true },
        objectives = { it = "Raggiungi Orgrimmar e parla con Shenthul nella Cleft of Shadow.", enHash = "20980aca", vanilla = true },
        reward = { it = "Dunque è questo ciò che i nostri potenti alleati hanno mandato a Shenthul? Che delusione...", enHash = "629bca15", vanilla = true },
    },
    [2379] = {
        title = { it = "Zando'zan", enHash = "70b0bc92", vanilla = true },
        text = { it = "La tua determinazione da sola non basta a superare gli ostacoli che ci aspettano.\n\nParla con Zando'zan per cominciare il tuo addestramento come agente della Shattered Hand.\n\nSolo quando avrai padroneggiato le arti della furtività e del furto potrai fare il passo successivo verso il tuo destino.", enHash = "dc247eb5", vanilla = true },
        objectives = { it = "Parla con Zando'zan nella Cleft of Shadow.", enHash = "5e415ffd", vanilla = true },
        reward = { it = "Forse Zando'zan si è sbagliato. Zando'zan chiede scusa.", enHash = "efee954a", vanilla = true },
    },
    [2380] = {
        title = { it = "A Orgrimmar!", enHash = "0bcccbfa", vanilla = true },
        text = { it = "Non sei $Gun maestro:una maestra; della furtività e dell'inganno, ma tutto questo può cambiare, e cambierà. Evidentemente hai fatto colpo su chi comanda con le tue misere abilità, visto che il grande Shenthul ha chiesto di te per nome.\n\nPrendi la strada a nord di qui fino a Orgrimmar e parla con Shenthul nella Cleft of Shadow.", enHash = "bef63ee7", vanilla = true },
        objectives = { it = "Parla con Shenthul nella Cleft of Shadow, a Orgrimmar.", enHash = "dc1d679f", vanilla = true },
        reward = { it = "È importante che la Shattered Hand resti vigile di fronte ai cambiamenti che Thrall vuole portare nell'Orda. Il nostro numero da solo non basterà a rovesciare il suo dominio: bisogna padroneggiare la furtività e l'inganno.", enHash = "1dddb8de", vanilla = true },
    },
    [2381] = {
        title = { it = "Depredare i predoni", enHash = "3bfc03f3", vanilla = true },
        text = { it = "Non voglio spaventarti, $N, ma gli ultimi cinque ladri che ho mandato a rubare il Southsea Treasure mi sono tornati indietro a pezzi.\n\nPiù a sud lungo la costa troverai la Tide Razor, la nave dei Southsea Freebooter. Nella stiva c'è il bottino: il Southsea Treasure. Al secondo ponte della nave c'è il covo dei pirati, il posto dove addestrano tutti i loro ladri.\n\nSali su quella nave, ruba il tesoro e portamelo. Se hai bisogno di esercitarti a rubare, usa il covo dei pirati, ma fa' attenzione!", enHash = "b8f73cfe", vanilla = true },
        objectives = { it = "Riporta il Southsea Treasure a Wrenix the Wretched, a Ratchet. Non dimenticare di prendere un E.C.A.C. e i Thieves' Tools da Wrenix's Gizmotronic Apparatus. Ti serviranno entrambi per completare la missione.\n\nSe dovessi essere $Gattaccato:attaccata; da pappagalli insolitamente ostili, usa il tuo E.C.A.C.!", enHash = "949edef5", vanilla = true },
        progress = { it = "Beh, almeno hai ancora tutti i pezzi al loro posto. Hai trovato il tesoro?", enHash = "3c0b6e50", vanilla = true },
        reward = { it = "Incredibile! Improbabile! Semplicemente strabiliante! Hai talento, $N. O quello, o sei $Gl'uomo più fortunato:la donna più fortunata; del mondo!\n\nEcco la tua parte del bottino. Di sicuro tu ne farai un uso migliore del mio.", enHash = { "3cb85804", "f8f6632c" }, vanilla = true },
    },
    [2382] = {
        title = { it = "Wrenix di Ratchet", enHash = "b441a97d", vanilla = true },
        text = { it = "Zando'zan l'ha visto! Sì, il giorno arriva! La morte di Thrall... il pugnale nella sua schiena, il veleno che gli scorre in ogni vena... Zando'zan ha detto troppo.\n\n$N! Zando'zan ha un compito per $N! $N deve andare a Ratchet, a est del Crossroads, e parlare con Wrenix the Wretched. Va'!", enHash = "671fb787", vanilla = true },
        objectives = { it = "Raggiungi Ratchet e parla con Wrenix the Wretched.", enHash = "ae7c6781", vanilla = true },
        reward = { it = "$GUn altro:Un'altra;? Gli ultimi cinque che quel troll matto mi ha mandato sono finiti in pasto agli squali. Speriamo che a te vada un po' meglio, eh?", enHash = "db354fd4", vanilla = true },
    },
    [2383] = {
        title = { it = "Simple Parchment", enHash = "b246ba36" },
        text = { it = "Ah, mentre eri via è arrivata una pergamena per te, $N.\n\nLeggila quando hai tempo. Se non sbaglio, viene da Frang, l'istruttore di guerrieri. Vuole parlarti quando sei $Gpronto:pronta;. Lo trovi fuori dal Den, al riparo all'ombra.", enHash = "27acdd1a" },
        objectives = { it = "Leggi la Simple Parchment e parla con Frang, nella Valley of Trials.", enHash = "7befc94e" },
        progress = { it = "Cos'hai lì? Una pergamena? Non sarai $Guno studioso:una studiosa;, spero...", enHash = "09df7c2f" },
        reward = { it = "Ah, è la mia pergamena. Avevo sentito che saresti $Garrivato:arrivata; nella Valley, $N. Sono contento di vedere che ce l'hai fatta: speriamo che tu sopravviva alle prove che ti aspettano. Come dicevo, man mano che cresci in potenza vieni da me: farò il possibile per addestrarti nelle vie $Gdel:della; $C.\n\nBuona fortuna, $N, e torna da me quando ti senti $Gpronto:pronta;.", enHash = "99ee97b1" },
    },
    [2398] = {
        title = { it = "I nani perduti", enHash = "d4ea6773", vanilla = true },
        text = { it = "Il sito di scavo di Uldaman non è sempre stato invaso. Noi nani di Ironforge controllavamo la zona, ma... era prima che arrivassero i trogg. Sono arrivati così in fretta e in numero così grande che nemmeno la forza dei nani è riuscita a fermarli!\n\nAnzi, il loro attacco è stato così improvviso che temo che alcuni dei nostri siano rimasti intrappolati dietro le linee nemiche.\n\nIl mio amico Baelog ha guidato un piccolo gruppo di nani nel cuore del sito poco prima che si facessero vivi i trogg. Se lui e la sua compagnia sono vivi, voglio che tu li trovi.", enHash = "3dc7e469", vanilla = true },
        objectives = { it = "Trova Baelog a Uldaman.", enHash = "f766a828", vanilla = true },
        reward = { it = "Era ora che arrivassi! Stavo per perdere una scommessa con Olaf!\n\nAveva scommesso che la barba gli sarebbe arrivata alle ginocchia prima di vedere $Gun altro:un'altra; $R in vita. Be', eccoti qui, e come vedi alla barba di Olaf mancano ancora un bel po' di centimetri.\n\nGrazie, $N. Dividerò la vincita con te.", enHash = "708dcad0", vanilla = true },
    },
    [2399] = {
        title = { it = "Le fronde germogliate", enHash = "eec39913", vanilla = true },
        reward = { it = "Le fronde che Denalan ha piantato nel suo giardino sono germogliate e cresciute. Tremano, impazienti di essere colte...", enHash = "0ac6a5ed", vanilla = true },
    },
    [2418] = {
        title = { it = "Pietre energetiche", enHash = "a3e6b429", vanilla = true },
        text = { it = "Tempo fa ho avuto una disavventura con i nani Shadowforge. Mi hanno portato ad Angor Fortress per studiare due tipi di strane pietre di Uldaman. Ho scoperto che, se trattate nel modo giusto, erano fonti di energia durature e stabili. È incredibile quello che si trova in quel vecchio sito di scavo!\n\nComunque, dopo che gli ho svelato il segreto delle pietre, mi hanno cacciato da Angor Fortress e si sono messi a scavare a Uldaman per trovarne altre.\n\nQuelle pietre le voglio io! Portami tutti e due i tipi e ti pagherò un sacco!", enHash = "4d775a38", vanilla = true },
        objectives = { it = "Porta 8 Dentrium Power Stone e 8 An'Alleum Power Stone a Rigglefuzz, nei Badlands.", enHash = "2b456ed6", vanilla = true },
        progress = { it = "Hai le pietre energetiche, $N? Ho un roditore robotico che ha bisogno di una fonte di energia...", enHash = "401d9dd0", vanilla = true },
        reward = { it = "Fantastico, ne hai trovate! Grazie mille, $N. Sei $Gil:la; $R più affidabile che abbia mai incontrato!\n\nNon vedo l'ora di provarle su certi congegni che sto mettendo a punto. Scommetto che, nelle giuste condizioni, i congegni alimentati con queste pietre andranno avanti, e avanti, e avanti...", enHash = "95aa7add", vanilla = true },
    },
    [2438] = {
        title = { it = "L'Emerald Dreamcatcher", enHash = "0e524410", vanilla = true },
        text = { it = "Un tempo mi fu donato un Emerald Dreamcatcher da Gaerolas Talvethen, il custode dei druidi nel Ban'ethil Barrow Den. Questo potente amuleto è in grado di attingere energia dall'Emerald Dream, donando fortuna a chi lo porta con sé.\n\nPurtroppo non sono riuscito a recuperarlo dal mio cassettone a Starbreeze Village... Anche se un tempo Starbreeze era un luogo tranquillo, ora è caduta nella corruzione dei furbolg che vi risiedono.\n\nForse saresti $Gdisposto:disposta; a recuperare il mio acchiappasogni, $C?", enHash = "79e096cf", vanilla = true },
        objectives = { it = "Porta l'Emerald Dreamcatcher a Tallonkai Swiftroot, a Dolanaar.", enHash = "58a885d6", vanilla = true },
        progress = { it = "Ti prego, muoviti in fretta. Posso solo sperare che il mio Emerald Dreamcatcher non sia stato danneggiato dai furbolg.\n\nL'hai già recuperato, $N?", enHash = "7249a879", vanilla = true },
        reward = { it = "Il mio Emerald Dreamcatcher ha per me grande importanza. È un dono concesso a pochi. Grazie per averlo restituito, $N.", enHash = "f7fd7bc9", vanilla = true },
    },
    [2440] = {
        title = { it = "I dischi di platino", enHash = "071ba219", vanilla = true },
        text = { it = "Concentrerò le mie energie su questi dischi; a tempo debito mi riveleranno il loro vero funzionamento.\n\nQuanto a te, $N, ora ti ricompenserò per la diligenza con cui me li hai segnalati. Porta questo buono a Bena Winterhoof, l'istruttrice di alchimia di Thunder Bluff. Ti darà un oggetto speciale che credo troverai interessante, e ti offrirà una scelta di pozioni dalla mia scorta personale.\n\nTorna presto da me, perché sento che c'è ancora molto da fare riguardo a questa scoperta.", enHash = "b053af06", vanilla = true },
        objectives = { it = "Porta il Reward Voucher a Bena Winterhoof, a Thunder Bluff.", enHash = "c03f22bd", vanilla = true },
        progress = { it = "Salve, $C! Sei qui per imparare l'alchimia, o per qualcos'altro?", enHash = "8a077a6f", vanilla = true },
        reward = { it = "Be', $N, devi aver fatto molto piacere a Sage Truthseeker, se ti ha dato questo oggetto. Ti spetta anche un dono dalla sua scorta di pozioni; come ricompensa puoi scegliere tra 5 Superior Healing Potion e 5 Greater Mana Potion.", enHash = "020014fb", vanilla = true },
    },
    [2458] = {
        title = { it = "Sotto copertura", enHash = "48830383", vanilla = true },
        text = { it = "La Venture Company... Forse ne hai sentito parlare?\n\nPer un anno ci siamo impegnati a infiltrare un agente nel cuore delle loro file. Con molto lavoro e un'attenta pianificazione, ci siamo riusciti.\n\nDi recente ci è giunta voce che la Venture Co. sta preparando qualcosa in grande. Va' a nord dello Sludge Fen, alla torre della Venture Co., e mettiti in contatto con il nostro agente sotto copertura, Taskmaster Fizzule.\n\nQuando trovi la torre, usa questa Flare Gun, poi avvicinati a Fizzule e fagli il saluto della Shattered Hand.", enHash = "6445461b", vanilla = true },
        objectives = { it = "Raggiungi la Venture Co. Tower, a nord dello Sludge Fen, e mettiti in contatto con l'agente segreto della Shattered Hand, Taskmaster Fizzule.\n\nQuando la torre è in vista, usa la Flare Gun per segnalare il tuo arrivo a Taskmaster Fizzule. Spara DUE razzi, poi avvicinati a Taskmaster Fizzule ed esegui lo Shattered /Salute.\n\nQueste azioni vanno eseguite nell'ordine giusto, perché Fizzule attacca ed elimina chiunque non riconosca.", enHash = "c85fe065", vanilla = true },
        reward = { it = "Fa piacere vedere $Gun altro agente:un'altra agente; della Shattered Hand da queste parti; però il razzo forse era un po' troppo!\n\nLa prossima volta che devi parlarmi, soffia due volte in questo fischietto e saprò che sei $Gun alleato:un'alleata;.", enHash = "2f31b106", vanilla = true },
    },
    [2459] = {
        title = { it = "Ferocitas the Dream Eater", enHash = "8aa33a1d" },
        text = { it = "Lo smeraldo... Non c'è più! Il mio acchiappasogni è stato danneggiato!\n\nC'è una banda di mistici Gnarlpine a nord di Starbreeze. Ho sentito dire che il loro capo, Ferocitas the Dream Eater, porta una collana che brilla di verde nella notte. Ora, vedendo il mio acchiappasogni, sono sicuro che mi abbia rubato lo smeraldo... Non si renderebbe mai conto che il suo potere per lui è inutile.\n\nTrova questo gioiello scomparso, $N. E già che sei lì, elimina anche qualcuno di quei mistici corrotti.", enHash = "92cc3bbd" },
        objectives = { it = "Tallonkai Swiftroot, a Dolanaar, vuole che tu uccida 7 Gnarlpine Mystic e trovi la Missing Jewel.", enHash = "fc88bbf9" },
        progress = { it = "Ferocitas e i mistici Gnarlpine devono restituire ciò che è mio. Ti prego, recupera lo smeraldo, così che io possa riparare il mio Emerald Dreamcatcher.", enHash = "81023cc8" },
        reward = { it = "Ora posso riparare il mio acchiappasogni. Grazie, $N.", enHash = "84601f5e" },
    },
    [2460] = {
        title = { it = "Lo Shattered Salute", enHash = "205aa1bf", vanilla = true },
        text = { it = "Come $Gladro:ladra; della Shattered Hand, è indispensabile che tu impari lo Shattered Salute. È l'unico modo per riconoscere con certezza un altro membro della Hand.\n\nGuarda, impara, ripeti.", enHash = "508c2013", vanilla = true },
        objectives = { it = "Esegui lo Shattered Salute davanti a Shenthul.", enHash = "c1c67546", vanilla = true },
        progress = { it = "Esercitati!", enHash = "daf6a646", vanilla = true },
        reward = { it = "Ben fatto, $N. Ora sei $Gpronto:pronta; per andare avanti.", enHash = "271e486d", vanilla = true },
    },
    [2478] = {
        title = { it = "Missione: possibile ma non probabile", enHash = "a0ef4178", vanilla = true },
        text = { it = "Dovrai rubare la chiave della torre a Foreman Silixiz, $N. Una volta che l'avrai in tuo possesso, tienila: potrebbe servirmi più tardi.\n\nRicorda, il veleno ha indebolito tutti quelli che stanno in questa torre. Usa le tue abilità per portare caos e distruzione tra i suoi abitanti. Uccidili tutti — nessuna pietà!\n\nQuando dentro non resterà che un mucchio di corpi insanguinati, scassina Gallywix's Lockbox e ruba la scorta della miscela di Zanzil che contiene. Porta sia la testa di Gallywix sia la miscela a Shenthul, a Orgrimmar.", enHash = "b2fe5a88", vanilla = true },
        objectives = { it = "Ruba Silixiz's Tower Key a Foreman Silixiz, poi uccidi due Mutated Venture Co. Drone, due Venture Co. Patroller e due Venture Co. Lookout.\n\nAssassina Grand Foreman Gallywix e prendi la sua testa, poi scassina Gallywix's Lockbox e ruba la Cache of Zanzil's Altered Mixture. Porta la Cache e Gallywix's Head a Shenthul, a Orgrimmar, per ulteriori istruzioni.", enHash = "118c30b1", vanilla = true },
        progress = { it = "Cosa hai da riferire, $N?", enHash = "348e0a65", vanilla = true },
        reward = { it = "Povero Fizzule, era un buon agente — uno dei nostri migliori. Ahimè, è il prezzo che paghiamo, $N. Essere un agente sul campo della Shattered Hand è un lavoro pericoloso.\n\nHai svolto bene il tuo dovere, $C. Sarebbe un peccato se non vivessi abbastanza da servirci ancora.", enHash = "c96fb8bb", vanilla = true },
    },
    [2479] = {
        title = { it = "L'aiuto di Hinott", enHash = "6d84156a", vanilla = true },
        text = { it = "Porta un campione della miscela a Serge Hinott, a Tarren Mill.\n\nSe qualcuno può curarti, quello è Serge. Se vivrai abbastanza, Serge ti mostrerà come si creano e si usano i veleni.", enHash = "46dc0c62", vanilla = true },
        objectives = { it = "Raggiungi Tarren Mill, nelle Hillsbrad Foothills, e consegna il Sample of Zanzil's Mixture a Serge Hinott.\n\nPer arrivare a Tarren Mill, prendi lo zeppelin per l'Undercity e segui la strada verso sud attraverso Silverpine, in direzione di Hillsbrad. Segui i cartelli!", enHash = "66ad7c49", vanilla = true },
        progress = { it = "Cos'è questo???", enHash = "c31f73d1", vanilla = true },
        reward = { it = "Hai un pallore delizioso, $C. E cos'è quell'odore nauseabondo che emani? Devo saperlo!", enHash = "575a6492", vanilla = true },
    },
    [2480] = {
        title = { it = "L'aiuto di Hinott", enHash = "6d84156a", vanilla = true },
        text = { it = "Non ho mai visto risultati così meravigliosi da un veleno! Zanzil, dici? Mai sentito nominare; però devo fargli i miei complimenti per aver creato questo intruglio.\n\nDunque, dovrei curarti da questo e poi insegnarti a usare il veleno?\n\nDammi qualche momento per esaminare la tossina, $N.", enHash = "8f97c498", vanilla = true },
        objectives = { it = "Aspetta che Serge Hinott abbia preparato la cura.", enHash = "15cecc1e", vanilla = true },
        reward = { it = "La cura è pronta! Bevi questa antitossina e la follia strisciante si fermerà; per l'odore, però, non potrò fare niente.", enHash = "55fac5fd", vanilla = true },
    },
    [2498] = {
        title = { it = "Torna da Denalan", enHash = "50dc6b70", vanilla = true },
        text = { it = "Ho appena saputo che Denalan, al Lake Al'Ameth, ha scoperto quella che potrebbe essere la causa dei tumori che affliggono i Timberling. Ti prego, parla con lui e digli che ti mando io.\n\nFa' in fretta, $N: ha bisogno del nostro aiuto.", enHash = "61c76d2e", vanilla = true },
        objectives = { it = "Rellian Greenspyre vuole che tu parli con Denalan, al Lake Al'Ameth.", enHash = "abd265e2", vanilla = true },
        reward = { it = "Ah, così Rellian ti manda ad aiutarmi. Sono contento che tu sia $Garrivato:arrivata; così presto.\n\nHo scoperto qualcosa di molto inquietante!", enHash = "7c554717", vanilla = true },
    },
    [2499] = {
        title = { it = "Oakenscowl", enHash = "25f19132", vanilla = true },
        text = { it = "In una grotta lungo la sponda meridionale del lago, un Timberling di nome Oakenscowl sta diffondendo la corruzione a tutte le creature che hanno fatto del Lake Al'Ameth la loro casa.\n\nNon ho osato avvicinarmi troppo, ma anche da lontano è evidente: Oakenscowl è avvelenato dal più grande tumore che io abbia mai visto... Lo definirei addirittura gigantesco.\n\n$N, hai già fatto molto per aiutarmi, ma ti chiedo un altro compito. Dai la caccia a Oakenscowl e raccogli il tumore; togli questa fonte di corruzione dalla mia casa.", enHash = "9feebe4b", vanilla = true },
        objectives = { it = "Denalan, al Lake Al'Ameth, vuole che tu raccolga il Gargantuan Tumor da Oakenscowl.", enHash = "f2d8f4b1", vanilla = true },
        progress = { it = "Hai già individuato Oakenscowl, $R?", enHash = "ece4c37c", vanilla = true },
        reward = { it = "Sapevo che eri più che capace di liberare il lago da quella bestia orribile.\n\nÈ una situazione dolorosa: un tempo Oakenscowl era un grande capo tra i suoi simili... ma la corruzione non distingue fra gli umili e i nobili.\n\nLe dimensioni di questo tumore sono davvero inquietanti, ma devo studiarlo per capire meglio la malattia che sconvolge la popolazione dei Timberling.\n\nGrazie, $N.", enHash = "b9bb08fc", vanilla = true },
    },
    [2500] = {
        title = { it = "Reagenti dalle Badlands", enHash = "1dbee480", vanilla = true },
        text = { it = "$C, vorrei avvalermi dei tuoi servigi. Sono un alchimista di una certa fama, e cerco il tuo aiuto per procurarmi alcuni reagenti che si trovano nelle Badlands.\n\nPer rifornire le mie scorte mi servono queste cose: cinque Buzzard Gizzard, dieci Crag Coyote Fang e cinque Rock Elemental Shard. Ovviamente puoi prenderli dalle bestiacce stesse; se non sei $Gil tipo:la tipa; che combatte, trovati degli amici che lo siano.\n\nProcurami queste cose e ci guadagnerai qualche moneta.\n\nAllora, che ne dici?", enHash = "a1dee496", vanilla = true },
        objectives = { it = "Procurati i reagenti delle Badlands che servono a Ghak Healtouch, poi torna da lui a Thelsamar.", enHash = "17e0cb29", vanilla = true },
        progress = { it = "Hai già preso le cose che mi servono? Non sarai $Gpagato:pagata; se non mi porti quei reagenti.", enHash = "9735ae37", vanilla = true },
        reward = { it = "Ah, ben fatto, $N. Queste mi basteranno almeno per un po'. Ecco la tua paga, come promesso.\n\nSe ti interessa, ci sono altri reagenti che mi farebbero comodo. Questi però si trovano solo nelle profondità degli scavi di Uldaman. Non sarà facile procurarli, ma se vorrai aiutarmi ancora farò in modo che ne valga la pena.\n\nMagari qualcosa di più di qualche moneta luccicante, eh?", enHash = "c77ea443", vanilla = true },
    },
    [2501] = {
        title = { it = "Reagenti dalle Badlands II", enHash = "896150c0", vanilla = true },
        text = { it = "Mi sei $Gstato:stata; di grande aiuto, $N. Vorrei ricompensarti con la ricetta stessa dell'intruglio che ti ho dato prima, ma devo chiederti un favore piuttosto pericoloso.\n\nIn questa cassetta ci sono tre recipienti taumaturgici vuoti; sono intrisi di un'aura di sintonia che assorbirà il sangue di uno Scorched Guardian. Usarne uno sulla bestia la farà infuriare parecchio, quindi sta' $Gattento:attenta;. Quando li avrai riempiti tutti e tre, portameli.\n\nFallo, e la ricetta sarà tua.", enHash = "86508474", vanilla = true },
        objectives = { it = "Usa gli Empty Thaumaturgy Vessel sugli Scorched Guardian delle Badlands. Quando li avrai riempiti, portali a Ghak Healtouch a Thelsamar.", enHash = "33a13638", vanilla = true },
        progress = { it = "Hai usato i recipienti per procurarmi il sangue di Scorched Guardian che mi serve? Sì, lo so che è un compito pericoloso... ma la ricetta del mio intruglio ristoratore aspetta solo il tuo successo. Rischio e ricompensa, $Gamico mio:amica mia;... rischio e ricompensa...", enHash = "ef0fee9b", vanilla = true },
        reward = { it = "Da alchimista ad alchimista, ti rendo omaggio. Ecco, prendi questa ricetta e imparala a memoria. Che ti porti il successo e le ricompense che ha portato a me in tutti questi anni!", enHash = "e913666b", vanilla = true },
    },
    [2518] = {
        title = { it = "Lacrime della luna", enHash = "f257422a", vanilla = true },
        text = { it = "Lady Sathrah era un tempo amata da Elune. Ragno aggraziato e puro, filava i suoi fili d'argento nella luce della luna, catturando la nebbia della sera. La rugiada argentea aveva forti poteri curativi ed era custodita qui nel tempio.\n\nMa di recente Sathrah è sprofondata nella follia. Ora sono minacciate anche le sue generazioni future.\n\nTrova Lady Sathrah, $N, e poni fine alla sua sofferenza. Dimora lungo i confini settentrionali di Teldrassil, vicino al Wellspring Lake. Raccogli le sue filiere argentee e riportamele.", enHash = "0fc31e13", vanilla = true },
        objectives = { it = "Priestess A'moora, nel Temple of the Moon a Darnassus, vuole che tu le porti Lady Sathrah's Silvery Spinnerets.", enHash = "081f0a69", vanilla = true },
        progress = { it = "Mi dispiace per il compito che ti ho chiesto di svolgere, ma per Lady Sathrah non c'è più speranza.\n\nIl nostro desiderio è offrire il sacrificio delle filiere a Elune. Con questo sacrificio, Elune benedirà Sathrah, perché possa rinascere e trovare pace.", enHash = "401d7851", vanilla = true },
        reward = { it = "La foresta piange Lady Sathrah, ma era una cosa che andava fatta.\n\nGrazie, $N.", enHash = "8f30e20c", vanilla = true },
    },
    [2519] = {
        title = { it = "Il Temple of the Moon", enHash = "6f6ce235", vanilla = true },
        text = { it = "Una creatura della foresta, un tempo magnifica, ha bisogno di aiuto, $R.\n\nC'è un compito difficile da portare a termine.\n\nTi prego, cerca Priestess A'moora: sarà lei a spiegarti le cose. La trovi a sud-est di qui, dentro il Temple of the Moon.", enHash = "4ea1f268", vanilla = true },
        objectives = { it = "Sister Aquinne vuole che tu parli con Priestess A'moora, nel Temple of the Moon.", enHash = "19ab8f62", vanilla = true },
        reward = { it = "Dunque, ti manda Sister Aquinne?", enHash = "334c9d5d", vanilla = true },
    },
    [2520] = {
        title = { it = "Il sacrificio di Sathrah", enHash = "59982654", vanilla = true },
        text = { it = "Ora devi portare a termine il compito che ti è stato affidato. Prendi le filiere e offri il sacrificio di Lady Sathrah a Elune; dai riposo al grande ragno.\n\nDentro questo tempio, trova la fontana centrale. È lì che puoi lasciare il sacrificio. Le acque sacre purificheranno e laveranno via la corruzione che ha reso folle Sathrah.\n\nQuando l'avrai fatto, torna da me.", enHash = "2b6d4cbe", vanilla = true },
        objectives = { it = "Priestess A'moora vuole che tu deponga le filiere argentee di Lady Sathrah alla fontana dentro il tempio, e poi torni da lei.", enHash = "0e31bdce", vanilla = true },
        progress = { it = "Hai deposto il sacrificio alla fontana, $N?", enHash = "3e39c119", vanilla = true },
        reward = { it = "La perdita di Lady Sathrah è dolorosa, ma solo così potrà rinascere con uno spirito rinnovato.\n\nChe Elune accolga di buon grado il sacrificio che le hai offerto.", enHash = "af7396a5", vanilla = true },
    },
    [2541] = {
        title = { it = "Il druido dormiente", enHash = "d41efe25", vanilla = true },
        text = { it = "Gli sciamani Gnarlpine che abitano questo luogo hanno scoperto un modo per separare lo spirito di un druido addormentato dal corpo fisico. I furbolg hanno animato la mia forma fisica e la usano per attaccare chiunque provi a esplorare il Ban'ethil Barrow Den. Ora sono intrappolato nell'Emerald Dream, impotente a fermarli.\n\nDevi aiutarmi. Gli sciamani Gnarlpine portano con sé uno strano amuleto usato per compiere questo rituale, e vorrei esaminarlo. Ti prego, $N, portamene uno.", enHash = "62bb78fb", vanilla = true },
        objectives = { it = "Porta uno Shaman Voodoo Charm a Oben Rageclaw, nel Ban'ethil Barrow Den.", enHash = "d8faf5e2", vanilla = true },
        progress = { it = "Se posso esaminare l'amuleto, forse riuscirò a capire come spezzare l'incantesimo. Ne hai trovato uno?", enHash = "bc7a1bd5", vanilla = true },
        reward = { it = "Grazie, $N.\n\nChe ninnolo strano... Sento l'aura immonda che ne emana: è un incantesimo molto potente.", enHash = "2233cc71", vanilla = true },
    },
    [2561] = {
        title = { it = "Druid of the Claw", enHash = "a0e66ef6", vanilla = true },
        text = { it = "Dopo aver esaminato questo amuleto, $N, ora vedo cosa si deve fare. Ti prego, prendilo e fa' come ti chiedo.\n\nDovrai esplorare le zone più profonde del Ban'ethil Barrow Den. Là troverai il mio corpo senz'anima... Anche se mi duole ciò che sto per dirti, non vedo altro modo per liberarmi dal controllo dei Gnarlpine.\n\nPerché io possa sfuggire loro, devi uccidere la mia forma fisica. Fatto questo, usa il Voodoo Charm sul mio corpo caduto. Quando avrai portato a termine questo compito, ti prego, torna da me.", enHash = "4c89aa74", vanilla = true },
        objectives = { it = "Oben Rageclaw vuole che tu uccida il suo corpo senz'anima e poi usi il Voodoo Charm.", enHash = "6a455b18", vanilla = true },
        progress = { it = "$N, sii prudente quando ti avvicini alla mia forma fisica: l'incantesimo che la governa è molto potente.", enHash = "011fedd1", vanilla = true },
        reward = { it = "Sono finalmente libero dal controllo dei Gnarlpine. Grazie, $N.\n\nOra il mio spirito può riposare in pace per sempre nell'Emerald Dream.\n\nForse un giorno ci incontreremo di nuovo, giovane $C. Ma per ora, ti prego, accetta questa ricompensa come segno della mia gratitudine.", enHash = "9cf38b38", vanilla = true },
    },
    [2607] = {
        title = { it = "Il tocco di Zanzil", enHash = "d9e020af", vanilla = true },
        text = { it = "Sembra che tu abbia riportato più informazioni di quante me ne aspettassi perfino io. Questa sì che è una strana piega degli eventi, $N.\n\nUna cura? Mmh... Scendi in cantina e parla con Doc Mixilpixil: forse può aiutarti.", enHash = "a4874238", vanilla = true },
        objectives = { it = "Parla con Doc Mixilpixil nella cantina dei Barracks.", enHash = "d4becbf9", vanilla = true },
        reward = { it = "Era ora! Metti il formaggio sul tavolo e fila via. Osborne ti pagherà all'uscita.", enHash = "0e9efa09", vanilla = true },
    },
    [2608] = {
        title = { it = "Il tocco di Zanzil", enHash = "d9e020af", vanilla = true },
        text = { it = "Oh cielo, sembri la morte in persona. Correggo: io la morte l'ho vista, e tu sei $Gmesso:messa; peggio. Tu, $Gsignore:signorina;, saresti quello che la morte ha tossito fuori alla sua ultima visita medica.\n\nAh! Hai sentito, Noarm? Scrivitela!\n\n*Coff* Ehm, sì, per poterti aiutare dovrò prelevarti un po' di sangue. Non preoccuparti, fa male solo le prime... cinquanta volte o giù di lì... Usa /lay down quando sei $Gpronto:pronta; per il trattamento, $N.", enHash = { "97356eeb", "5311d28d" }, vanilla = true },
        objectives = { it = "Usa /Lay down per farti visitare da Doc Mixilpixil. Come può trovare la cura se non trova la causa?", enHash = "69704335", vanilla = true },
        progress = { it = "Quando sei $Gpronto:pronta; per la visita, sdraiati a terra con /lay down e comincerò la flebotomia.", enHash = "1b2e4a69", vanilla = true },
        reward = { it = "Dammi un momento per consultarmi con i miei colleghi, $N. Dottor Montgomery, signor Noarm, a consulto!", enHash = "425c321d", vanilla = true },
    },
    [2609] = {
        title = { it = "Il tocco di Zanzil", enHash = "d9e020af", vanilla = true },
        text = { it = "Siamo tutti d'accordo, $N. Hai la 'ite'.\n\nPer fortuna, ho una cura per la 'ite'.\n\nEcco cosa mi serve: un mazzo di Simple Wildflowers, un Leaded Vial, un Bronze Tube e, ultimo ma non meno importante, uno Spool of Light Chartreuse Silk Thread. Ol' Emma me ne ha lasciata una bobina a 'The Finest Thread'. Trovi la bottega lungo i canali.\n\nOra sbrigati, $N, e cerca di non toccare nessuno finché non sarai $Gguarito:guarita;. Ah, e il dottor Montgomery dice che hai bisogno di una doccia — parole sue, non mie.", enHash = "659b7c3b", vanilla = true },
        objectives = { it = "Porta a Doc Mixilpixil un mazzo di Simple Wildflowers, un Leaded Vial, un Bronze Tube e uno Spool of Light Chartreuse Silk Thread. La 'ite' non guarisce da sola, $Ggiovanotto:signorina;.", enHash = { "8f7f3eab", "c2e31cc5" }, vanilla = true },
        progress = { it = "Se vuoi guarire dalla 'ite', dovrai impegnarti più di così, $N. Dove sono i reagenti per la cura?", enHash = "59596d5c", vanilla = true },
        reward = { it = "Che cosa sto facendo? Che cosa ti sembra che stia facendo? Sto preparando una cura per la tua 'ite'! Non ti indignare con me, $N!\n\nAncora qualche secondo. Ecco! Spruzzati addosso questa, ehm, medicina dal profumo fantastico e tornerai $Gcome nuovo:come nuova;.", enHash = "21dbbb39", vanilla = true },
    },
    [2622] = {
        title = { it = "Gli ordini scomparsi", enHash = "7b93826e", vanilla = true },
        text = { it = "Gli ordini? Cosa te ne faresti mai degli ordini?\n\nCosa vorresti insinuare, $N? Certo che ho trasmesso quegli ordini! I soldati a cui li avevo affidati sono stati attaccati e massacrati di botte dai murloc. Ne è sopravvissuto uno solo, se così si può dire. Riesce a malapena a parlare, non può camminare, e bisogna nutrirlo con un tubo. Se vuoi sapere che fine hanno fatto quegli ordini, parla con Bengor. Sono sicuro che è qui da qualche parte... e, $N, sta' $Gattento:attenta; a dove ficchi il naso: potrebbero staccartelo a morsi.", enHash = "54f7c6aa", vanilla = true },
        objectives = { it = "Parla con Bengor.", enHash = "de556058", vanilla = true },
        reward = { it = "Swamp tal... talk... talker...", enHash = "bb04bc12", vanilla = true },
    },
    [2623] = {
        title = { it = "Lo Swamp Talker", enHash = "daf760e8", vanilla = true },
        text = { it = "Ordini dati dal comandante dei dispacci. Noi presi... presi ordini. Verso Blasted Lands, agguato.\n\nMurloc... Tanti murloc... Uno chiamato Swamp Talker. Preso ordini da mie mani mentre lancia entrava nel cranio. Est... grotta...\n\n<Bengor sviene.>", enHash = "64e0a346", vanilla = true },
        objectives = { it = "Recupera i Warchief's Orders e riportali al Fallen Hero of the Horde.", enHash = "1213de90", vanilla = true },
        progress = { it = "In attesa di ordini.", enHash = "87a0a095", vanilla = true },
        reward = { it = "È peggio di quanto immaginassi. Diciannove dei miei uomini avrebbero potuto essere risparmiati dall'agonia che hanno affrontato. Se solo non avessi agito in modo così irrazionale.\n\nDevi aiutarli, $N! Io non posso fare niente.", enHash = "556b6728", vanilla = true },
    },
    [2745] = {
        title = { it = "Infiltrarsi nel castello", enHash = "3cf61bba", vanilla = true },
        text = { it = "Hmm, una storia interessante, e non da prendere alla leggera. Sì, posso aiutarti, ma quel che devi fare è distribuire una forma di giustizia che non è... legale, se vuoi arrivare in fondo a questa storia.\n\nBisogna occuparsi di Lescovar e Marzon, e in fretta. Pensi di essere in grado di una cosa simile?\n\nDecidi tu. Se sì, allora corri al castello e trova un mio vecchio amico, uno gnomo di nome Tyrion. Sono un paio di settimane che tiene d'occhio Lescovar. Dovrebbe riuscire ad aiutarti a chiudere questa faccenda.", enHash = "75cc95ae", vanilla = true },
        objectives = { it = "Parla con Tyrion, a Stormwind Castle.", enHash = "a04d2dda", vanilla = true },
        reward = { it = "Ma che...?! Non sbucarmi addosso in quel modo! E abbassa la voce! In nome dell'Ombra, perché mai vieni a sbucarmi addosso di soppiatto? Non vedi che sono occupato, $Gstupido sciocco:stupida sciocca;?\n\nCome sarebbe, cosa sto facendo? Sto aspettando che si apra il prossimo Dark Portal, tu che diamine credi che stia facendo? Di' quel che hai da dire e vattene... prima che le guardie notino noi due nascosti insieme tra i cespugli. Ho una reputazione da mantenere.", enHash = "aff61717", vanilla = true },
    },
    [2746] = {
        title = { it = "Oggetti di una certa importanza", enHash = "3253b8e0", vanilla = true },
        text = { it = "Trias vuole anticipare un po' i tempi, eh? Va bene, si può fare, ma io non sono pronto. E sappi una cosa: la parte difficile la faccio io, ma sei tu $Gquello:quella; che si sporcherà le mani, chiaro? Bene.\n\nAllora, mi serve che tu mi procuri qualche cosa prima che possa mettere in atto il mio piano. Ho il travestimento perfetto per far passare Spybot davanti a quelle guardie.\n\nPortami un po' di seta e un paio di mele. La seta la trovi come vuoi, ma la piccola fattoria di Clara appena fuori città ha mele della misura perfetta.", enHash = { "746d00f7", "facb0d3a" }, vanilla = true },
        objectives = { it = "Porta 3 Silk Cloth e 2 Clara's Fresh Apple a Tyrion, a Stormwind.", enHash = "a2acfd6c", vanilla = true },
        progress = { it = "Sono un paio di settimane che tengo d'occhio Lescovar. Trias non si è mai fidato di lui, ma non sospettavamo che fosse coinvolto in qualcosa che riguarda la Defias Brotherhood. Seguivamo piste che lo legavano al Martello del Crepuscolo. In ogni caso è diventato più pericoloso di quanto questa città possa gestire, ed è lì che entriamo in gioco noi.\n\nProcurami quelle cose e potremo mettere in atto il mio piano.", enHash = "d245aa73", vanilla = true },
        reward = { it = "Questi andranno benissimo, $N. Ottimo lavoro.\n\nIl resto dell'attrezzatura che mi serve ce l'ho nello zaino... ringrazio la Luce di essermi fatto fare da un amico sarto una borsa di seta. Stavo finendo lo spazio, a portarmi dietro tutta la roba.\n\nPrima che Spybot entri, mettiamo a punto i dettagli, così sai cosa devi fare.", enHash = "6b20f12c", vanilla = true },
    },
    [2766] = {
        title = { it = "Trova OOX-22/FE!", enHash = "175f348f", vanilla = true },
        text = { it = "Hai scoperto una specie di strano congegno di metallo a forma di uovo. Armeggiando con una delle sue manopole, l'uovo prende vita e si apre in una specie di aggeggio robotico gnomesco! Dall'interno dell'uovo robotico gracchia una voce.\n\n\"Mi chiamo Oglethorpe Obnoticus, e il mio robot a ritorno automatico si è schiantato! Ti ricompenserò se lo recuperi; ti prego, porta questo segnalatore al robot!\"\n\n\"Ho calcolato per te le coordinate del robot: è in una grotta vicino a Feral Scar Vale!\"", enHash = "520c3616", vanilla = true },
        objectives = { it = "Porta l'OOX-22/FE Distress Beacon al robot a ritorno automatico di Oglethorpe, in una grotta vicino a Feral Scar Vale.", enHash = "b1063c81", vanilla = true },
        progress = { it = "Sembra che tu abbia scoperto il relitto di... un pollo robotico? La voce dall'interno dell'uovo gracchia di nuovo:\n\n\"Sì, ottimo lavoro! Questo è proprio il mio robot a ritorno automatico, anche se i miei sensori indicano che ha bisogno di una spinta per ripartire prima di poter tornare in volo a Booty Bay per le riparazioni. Coraggio, metti il segnalatore dentro il rover: al resto penserà il segnalatore!\"", enHash = "f7662879", vanilla = true },
        reward = { it = "Metti l'uovo... il segnalatore di soccorso... dentro il pollo... il robot a ritorno automatico.\n\nDall'interno del robot si sentono ronzii e fruscii mentre cerca di rimettersi in piedi. Quando il robot prende vita, si sente di nuovo la voce di Oglethorpe, ma ora dall'interno del robot:\n\n\"OOX-22/FE almeno funziona, ma ha bisogno di riparazioni importanti! È troppo pesante perché tu possa portarlo... ma credo di avere un'idea. Te la senti di sorvegliarlo ancora un po'?\"", enHash = "7dbafe25", vanilla = true },
    },
    [2767] = {
        title = { it = "Salva OOX-22/FE!", enHash = "d3c91875", vanilla = true },
        text = { it = "La voce dello gnomo gracchia di nuovo dal robot:\n\n\"Devo portare OOX-22/FE in un posto aperto e sicuro, così potrà cominciare una lunga procedura di decollo. Ha un occultamento incorporato, ma dalla mia parte mi serve tempo per rimetterlo in funzione. Scorta il robot da dove si trova ora fino a, diciamo, il molo lungo la Forgotten Coast! Dovrebbe essere il posto perfetto, e il tempo sufficiente, per rimettere tutto in linea!\"\n\n\"Scortalo al molo sano e salvo, e poi vieni a parlarmi a Booty Bay! Oglethorpe Obnoticus, passo e chiudo!\"", enHash = "090bccf4", vanilla = true },
        objectives = { it = "Scorta OOX-22/FE fino al molo lungo la Forgotten Coast, poi fai rapporto a Oglethorpe Obnoticus, a Booty Bay.", enHash = "9e19ab4b", vanilla = true },
        progress = { it = "Sì, sono Oglethorpe Obnoticus, maestro inventore al tuo servizio! Allora, c'è qualcosa in cui posso aiutarti?", enHash = "9ac46e3f", vanilla = true },
        reward = { it = "Oh, sei TU $Gil grande salvatore:la grande salvatrice; di OOX-22/FE! Non so nemmeno da dove cominciare per ringraziarti del tuo aiuto! La mia serie di robot a ritorno automatico ha bisogno di altro sviluppo, ma il tuo recupero mi ha risparmiato innumerevoli ore di ricostruzione, e anche parecchie monete d'oro in costi di fabbricazione!\n\nTi prego, scegli uno di questi oggetti che ho. Grazie ancora per il tuo generoso aiuto, $N: io e i miei robot siamo in debito con te!", enHash = "05ab99c3", vanilla = true },
    },
    [2768] = {
        title = { it = "Divino-matic Rod", enHash = "e4d1a00d", vanilla = true },
        text = { it = "Sergeant Bly mi ha derubato! Aveva detto che me la prendeva solo in prestito, ma mi ha rubato la mia preziosa Divino-matic Rod!! Senza quella verga come faccio a sapere dove scavare nuovi pozzi d'acqua??\n\nTrova Bly e riportami la mia verga! Ho sentito che ha portato la sua banda di avventurieri di dubbia fama a caccia di tesori a Zul'Farrak, a ovest. Scommetto che lo troverai lì.\n\nSperiamo che i troll l'abbiano già sistemato, perché se dovrai batterti con lui per la verga, ti aspetta uno scontro serio.", enHash = "eec22374", vanilla = true },
        objectives = { it = "Porta la Divino-matic Rod a Chief Engineer Bilgewhizzle, a Gadgetzan.", enHash = "31faca23", vanilla = true },
        progress = { it = "Hai trovato Sergeant Bly? Hai preso la mia Divino-matic Rod?", enHash = "1db2160c", vanilla = true },
        reward = { it = "L'hai trovata! Ben fatto, $N! Hai dovuto combattere con Bly per averla? Spero che tu abbia steso lui e la sua banda come si deve!", enHash = "62a0983c", vanilla = true },
    },
    [2769] = {
        title = { it = "I fratelli Brassbolts", enHash = "ac91f557", vanilla = true },
        text = { it = "Hai conosciuto i fratelli Brassbolts? Sono laggiù nelle Shimmering Flats, in Kalimdor, a gareggiare con la loro auto a razzo contro i goblin. Di solito vincono, e non c'è da stupirsi — l'auto dei goblin esplode così spesso che non taglia quasi mai il traguardo!\n\nMa anche così, i fratelli Brassbolts cercano sempre nuovi modi per far andare più veloce la loro auto, e Wizzle mi ha detto che gli serve un componente molto raro per il suo prossimo esperimento.\n\nProbabilmente ha bisogno di aiuto per procurarsi quel pezzo. Parla con lui e scoprilo.", enHash = "a45d8961", vanilla = true },
        objectives = { it = "Parla con Wizzle Brassbolts, nelle Shimmering Flats.", enHash = "6cdc4873", vanilla = true },
        reward = { it = "Ah, vuoi aiutarmi? Fantastico!\n\nC'è un pezzo che voglio per un esperimento a cui sto lavorando, e mi serve $Gun:una; $C $Gcoraggioso:coraggiosa; come te che mi aiuti a procurarmelo!", enHash = "edfdf32e", vanilla = true },
    },
    [2770] = {
        title = { it = "Gahz'rilla", enHash = "29b1dfef", vanilla = true },
        text = { it = "Nel profondo di Zul'Farrak, la città dei troll delle sabbie a Tanaris, c'è una vasca sacra. Da quella vasca i troll evocano una bestia enorme! Gahz'rilla! È così feroce che perfino le sue scaglie crepitano di energia. È quell'energia che voglio imbrigliare per la mia macchina!\n\nPortami la scaglia elettrificata di Gahz'rilla!\n\nMa l'evocazione di Gahz'rilla è un segreto ben custodito dai troll. Per affrontarlo, prima dovrai strappare loro il segreto.", enHash = "8538bbd0", vanilla = true },
        objectives = { it = "Porta Gahz'rilla's Electrified Scale a Wizzle Brassbolts, nelle Shimmering Flats.", enHash = "f2c5ba27", vanilla = true },
        progress = { it = "Hai la scaglia? Non vedo l'ora di provare vari modi per imbrigliarne l'energia!", enHash = "3e3cd3a2", vanilla = true },
        reward = { it = "Caspita, hai preso la scaglia! Grazie, $N. Non vedo l'ora di mettermi al lavoro su questa cosa!\n\nAllora hai visto Gahz'rilla? Era grosso come dicono??", enHash = "df1e4796", vanilla = true },
    },
    [2841] = {
        title = { it = "La guerra dei rig", enHash = "a671f39b", vanilla = true },
        text = { it = "La tecnologia gnomica: due anni fa la si usava soprattutto come battuta finale. I tempi sono cambiati, eccome. Adesso hanno costruito un rig nuovo che è meglio di tutti i nostri modelli di sminuzzatrice messi insieme. Mi servono i progetti, $N!\n\nPurtroppo i piani sono chiusi in una cassaforte vicino a Mekgineer Thermaplugg. E per peggiorare le cose, la combinazione della cassaforte la conosce solo Mekgineer Thermaplugg.\n\nFa' quel che devi per avere quella combinazione, $N. Poi apri quella cassaforte e riporta indietro quei progetti!", enHash = "dd015b5b", vanilla = true },
        objectives = { it = "Recupera i Rig Blueprints e Thermaplugg's Safe Combination da Gnomeregan e portali a Nogg, a Orgrimmar.", enHash = "deb4daed", vanilla = true },
        progress = { it = "Non vedo nessun progetto. Li hai nascosti da qualche parte addosso o te ne stai qui impalato solo per irritarmi?", enHash = "3534b4c6", vanilla = true },
        reward = { it = "Sapevo che ce l'avresti fatta, $N! Sovik invece aveva i suoi dubbi.\n\n<Nogg si schiarisce la gola.>\n\nOra che i progetti sono nostri, è solo questione di tempo prima che capiamo tutte le trovate gnomiche finite nella costruzione del rig e le trasformiamo in trovate goblin per i nostri nuovi modelli di sminuzzatrice.", enHash = "b34dec44", vanilla = true },
    },
    [2842] = {
        title = { it = "Chief Engineer Scooty", enHash = "59e2afab", vanilla = true },
        text = { it = "Appena abbiamo avuto notizie da Kernobee sul nuovo rig gnomico, io e Scooty ci siamo messi a lavorare al Transpolyporter 6000: il modo più veloce e affidabile per arrivare a Gnomeregan.\n\nFinalmente è pronto a imbarcare passeggeri, $N. Se vuoi provarlo, va' a Booty Bay e parla con Scooty al posatoio dei wind rider. Per arrivare a Booty Bay, prendi la nave da Ratchet.\n\nCerto, potresti sempre provare a farti la corsa fino a Gnomeregan attraverso le montagne di Dun Morogh infestate dai nani!", enHash = "dc33d110", vanilla = true },
        objectives = { it = "Parla con Scooty, a Booty Bay.", enHash = "28bf4009", vanilla = true },
        reward = { it = "È una bellezza, vero? L'apice della tecnologia goblin dei trasporti — è esplosa sì e no una dozzina di volte.\n\nNon preoccuparti, $N, l'ho rimessa a posto tutta. Non ti scoppierà addosso — e se succede, sarà rapido e indolore.", enHash = "64e16756", vanilla = true },
    },
    [2843] = {
        title = { it = "Gnomer-gooooone!", enHash = "887be407", vanilla = true },
        text = { it = "Finché hai il transponder con te, basta che salga sulla piattaforma e verrai $Gteletrasportato:teletrasportata; a Gnomeregan.\n\nPotresti avvertire qualche effetto collaterale insolito, ma nessuno dovrebbe essere permanente... ormai.\n\nQuasi dimenticavo la parte più importante: tornare indietro. Quando sei $Gpronto:pronta; a rientrare, sali sulla piattaforma del transpolyporter a Gnomeregan!\n\nOra calibriamo il transponder sulla tua taglia e sul tuo peso.", enHash = "3fa1f9fd", vanilla = true },
        objectives = { it = "Aspetta che Scooty calibri il Goblin Transponder.", enHash = "b8b39729", vanilla = true },
        progress = { it = "È pronto!", enHash = "68b56787", vanilla = true },
        reward = { it = "Fatto! Quando sei $Gpronto:pronta;, sali sulla piattaforma.", enHash = "92613753", vanilla = true },
    },
    [2846] = {
        title = { it = "La Tiara of the Deep", enHash = "b364067f", vanilla = true },
        text = { it = "Molto tempo fa possedevo un gioiello bellissimo, la Tiara of the Deep. E non era solo graziosa: racchiudeva un grande potere per chi sapeva usarlo.\n\nQuando la voce della tiara arrivò a Hydromancer Velratha, lei volle averla a tutti i costi. Mandò dei suoi agenti a casa mia, e me la rubarono mentre ero via. Ladri!\n\nRivoglio la mia tiara! Va' a Zul'Farrak, la città troll di Tanaris, trova Velratha e strappale la tiara. Riportamela e ti guadagnerai il mio favore.", enHash = "b18fd125", vanilla = true },
        objectives = { it = "Porta la Tiara of the Deep a Tabetha, nel Dustwallow Marsh.", enHash = "77105a86", vanilla = true },
        progress = { it = "Hai la tiara, $N? Velratha ha imparato quanto costa mettersi contro di me?", enHash = "74cf7c6d", vanilla = true },
        reward = { it = "Magnifico! L'hai trovata! E cosa altrettanto importante, Velratha non ce l'ha più! Grazie, $N. Ti sarò per sempre debitrice!\n\nE se prima ti sono sembrata un po'... cattiva, non farci caso. Scoprirai che sono una persona molto più gentile con chi non mi ha derubata.", enHash = "5a5d1be0", vanilla = true },
    },
    [2847] = {
        title = { it = "Armatura Wild Leather", enHash = "bb1218b2", vanilla = true },
        text = { it = "$N, come $Gconciatore:conciatrice; stai diventando davvero abile! Conosco alcuni schemi che potrebbero interessarti... l'armatura Wild Leather! Il Wild Leather sfrutta le proprietà potenti e caotiche delle Wildvine, che si trovano nelle zone di vegetazione rigogliosa e addosso ad alcune delle creature che ci vivono. Per chi ha la tua abilità non c'è armatura migliore di quella che se ne ricava, garantito.\n\nTi insegnerò a farla, ma per un po' lavorerai per me. Come primo pagamento mi bastano dieci pezzi di Thick Leather. Dopo, parleremo dei dettagli.", enHash = "1a13da57", vanilla = true },
        objectives = { it = "Porta 10 Thick Leather a Pratt McGrubben, a Feathermoon Stronghold.", enHash = "3633475d", vanilla = true },
        progress = { it = "Come ti ho detto, lavorerai per me mentre impari a conoscere l'armatura Wild Leather. Dato che le Wildvine sono insieme potenti e caotiche, danno un vantaggio casuale ma forte all'armatura che realizzerai, già robusta di suo. Però non è stato facile per me arrivare a questa conoscenza.\n\nPer avviare il lavoro, il costo iniziale è di dieci pezzi di Thick Leather.\n\nQuando avremo sistemato questo, passeremo al lavoro che dovrai fare per ottenere gli schemi.", enHash = "07fb8401", vanilla = true },
        reward = { it = "Bene, $N, sono contento di averti con me. Come $Gconciatore:conciatrice; hai fatto una scelta intelligente: chi indossa armature di cuoio farà a gara per venire da te, quando avrai imparato a fare uno qualsiasi dei pezzi dell'armatura Wild Leather.\n\nMettiamoci al lavoro — da dove vuoi cominciare?", enHash = "8613f323", vanilla = true },
    },
    [2848] = {
        title = { it = "Wild Leather Shoulders", enHash = "0ffa78c6", vanilla = true },
        text = { it = "I Wild Leather Shoulders sostengono benissimo il fisico di chi li indossa e offrono una protezione di prim'ordine alla parte alta delle braccia e alle spalle stesse. Come per tutta l'armatura Wild Leather, cucendoci dentro la Wildvine il pezzo acquista un vantaggio potente ma casuale.\n\nPer questo schema mi serviranno sei Thick Armor Kit e una Wildvine. Non dovrebbe essere un ordine troppo impegnativo da evadere, per te.", enHash = "5d573f92", vanilla = true },
        objectives = { it = "Porta 6 Thick Armor Kit e una Wildvine a Pratt McGrubben, a Feathermoon Stronghold.", enHash = "f224756d", vanilla = true },
        progress = { it = "Hai i sei Thick Armor Kit e la Wildvine che ti ho chiesto?\n\nNon pensare che fare kit per armature sia un lavoro monotono: il metodo di lavorazione regolare che acquisisci esercitando il mestiere su questi kit ti aiuta a sviluppare le capacità necessarie per il lavoro minuzioso che richiede l'armatura Wild Leather.\n\nVedi, c'è un vero motivo dietro a quello che fai per me...", enHash = "b736580a", vanilla = true },
        reward = { it = "Questi kit per armature sono di buona qualità, $N. Se c'è una cosa che pretendo, non solo dal mio lavoro ma anche da quello di chi lavora per me, è la qualità.\n\nHai lavorato bene per guadagnarti questo schema; spero che ti renda quanto ha reso a me.", enHash = "e17f4142", vanilla = true },
    },
    [2849] = {
        title = { it = "Wild Leather Vest", enHash = "8a333b7d", vanilla = true },
        text = { it = "I Wild Leather Vest sono il pezzo base di ogni set di armatura Wild Leather. La struttura del corpetto si fonde con la Wildvine per dare vita a un capo che offre la massima protezione al torso, lasciando che la potente magia si diffonda in tutto l'indumento.\n\nPer questo schema mi serviranno due Turtle Scale Breastplate, due paia di Turtle Scale Gloves e una Wildvine. È un ordine impegnativo, ma non dovresti avere grandi difficoltà a evaderlo per me.", enHash = "e790b758", vanilla = true },
        objectives = { it = "Porta 2 Turtle Scale Breastplate, 2 Turtle Scale Gloves e una Wildvine a Pratt McGrubben, a Feathermoon Stronghold.", enHash = "b6f9e0c4", vanilla = true },
        progress = { it = "Hai le due Turtle Scale Breastplate e i Turtle Scale Gloves che ti ho ordinato? E non dimenticare la Wildvine!\n\nGià dai primi schemi impariamo che le basi della forma si applicano bene anche ai capi più difficili. Anche se sono oggetti diversi, la forma delle Turtle Scale Breastplate ti prepara ai dettagli che servono per fare un Wild Leather Vest.\n\nE i guanti... be', quelli servono solo a me. Ricorda che lavori per me!", enHash = "049cd891", vanilla = true },
        reward = { it = "Sono pezzi davvero belli, $N. Solo per la maestria e la cura con cui sono stati fatti, varrebbero diverse monete d'argento in più rispetto a un pezzo qualunque.\n\nHai evaso il mio ordine, e per questo ti spetta la ricompensa. Ora la conoscenza per fare i Wild Leather Vest è tua!", enHash = "499fb082", vanilla = true },
    },
    [2850] = {
        title = { it = "Wild Leather Helmet", enHash = "b26b3b5a", vanilla = true },
        text = { it = "Un Wild Leather Helmet offre a chi lo indossa una protezione superiore per i punti vitali della testa, senza rinunciare alla comodità. Come per tutta l'armatura Wild Leather, la Wildvine incorporata nell'elmo dà alla sua struttura un potenziamento forte ma casuale. Chi indossa il cuoio vorrà di sicuro questo pezzo!\n\nPer questo schema mi serviranno due Nightscape Tunic, due Nightscape Headband e una Wildvine. Completa questo ordine e lo schema sarà tuo!", enHash = "98caa1fc", vanilla = true },
        objectives = { it = "Porta 2 Nightscape Tunic, 2 Nightscape Headband e una Wildvine a Pratt McGrubben, a Feathermoon Stronghold.", enHash = "45c893ea", vanilla = true },
        progress = { it = "Ho bisogno che tu mi faccia quelle tuniche e quelle fasce, e mi serve anche quel pezzo di Wildvine, prima di svelarti come si fanno i Wild Leather Helmet.\n\nTra gli avventurieri le protezioni per la testa sono molto ricercate, che si tratti di una fascia di una semplicità disarmante o di un elmo che copre tutto il capo. Le basi per creare un copricapo pregiato restano le stesse, qualunque sia il suo aspetto esteriore.", enHash = "a02b85e8", vanilla = true },
        reward = { it = "L'equipaggiamento Nightscape che mi hai portato soddisfa l'ordine alla perfezione, $N. Non mi aspetto niente di meno da $Gun conciatore:una conciatrice; del tuo calibro.\n\nQuesto schema te lo sei davvero $Gguadagnato:guadagnata;. Te lo do volentieri, e spero che tu ne tragga il giusto profitto.", enHash = "65bc862f", vanilla = true },
    },
    [2851] = {
        title = { it = "Wild Leather Boots", enHash = "bb1edb34", vanilla = true },
        text = { it = "Ormai hai imparato parecchio, $N, ma c'è ancora altro da imparare. Adesso tocca ai Wild Leather Boots, la pietra angolare di ogni set.\n\nQuesti stivali sono fatti per avvolgere il piede nella comodità e al tempo stesso proteggerlo dai pericoli dell'avventura. Le suole morbide sono una benedizione per chi cerca calzature con cui muoversi in silenzio.\n\nPer questo schema devi evadere un ordine di due Nightscape Pants e due Nightscape Boots. Mi serviranno anche due Wildvine... non una sola. Quando hai tutto, fammelo sapere.", enHash = "9f21e36f", vanilla = true },
        objectives = { it = "Porta 2 Nightscape Pants, 2 Nightscape Boots e 2 Wildvine a Pratt McGrubben, a Feathermoon Stronghold.", enHash = "fd0b4607", vanilla = true },
        progress = { it = "L'ordine dei pantaloni, degli stivali e delle Wildvine va evaso prima che tu abbia lo schema, $N. Hai finito?\n\nFin dal primo paio di stivali che impariamo a fare, cominciamo a capire che uno stivale di qualità deve stare in perfetto equilibrio tra comodità e funzionalità. Unendole, riusciamo a creare oggetti che permettono a chi li indossa di ignorare una fatica che stroncherebbe chi porta articoli di qualità inferiore.", enHash = "a7b67a2a", vanilla = true },
        reward = { it = "Ancora una volta hai evaso un ordine complesso con l'abilità di un professionista esperto. Ti sei $Gguadagnato:guadagnata; questo schema, e anche la mia gratitudine.", enHash = "0a0b8acb", vanilla = true },
    },
    [2852] = {
        title = { it = "Wild Leather Leggings", enHash = "5b338017", vanilla = true },
        text = { it = "Ora che hai le basi, sei $Gpronto:pronta; a padroneggiare lavori più complessi, $N. I Wild Leather Leggings sono tra i pezzi di cuoio più robusti e potenti che esistano. Vita, cosce, polpacci e punti vitali — tutto riceve una protezione enorme. Con in più il potenziamento della Wildvine, gli avventurieri che li possiedono ti ringrazieranno ogni volta che ti vedranno.\n\nPer questo schema devi evadere un ordine di due Turtle Scale Helm, due Turtle Scale Bracers e due Wildvine.", enHash = "106bb74a", vanilla = true },
        objectives = { it = "Porta 2 Turtle Scale Helm, 2 Turtle Scale Bracers e 2 Wildvine a Pratt McGrubben, a Feathermoon Stronghold.", enHash = "18550f8b", vanilla = true },
        progress = { it = "Hai pronti i Turtle Scale Bracers e i Turtle Scale Helm? Non dimenticare le due Wildvine che mi servono!\n\nOrmai cominci a renderti conto di quanto potere possa racchiudere l'armatura Wild Leather. Un'armatura che non ha limiti di impiego ha un valore quasi inestimabile per un conciatore. Gli unici limiti stanno nella quantità di materiali per fare gli oggetti — non nella qualità dei prodotti finiti!", enHash = "cff390e5", vanilla = true },
        reward = { it = "Di nuovo hai evaso un ordine senza sbavature. Forse un giorno sarò io a venire da TE in cerca di conoscenza, eh, $N?\n\nEcco lo schema dei gambali, con la mia gratitudine. Fai tesoro di questo sapere, e lascia che i tuoi prodotti finiti attingano alla tua notevole abilità!", enHash = "1ebb4bfb", vanilla = true },
    },
    [2853] = {
        title = { it = "$GMaestro:Maestra; del Wild Leather", enHash = "2cbbc98d", vanilla = true },
        text = { it = "Be', $N, sei la diligenza fatta persona. Rimane un solo schema dell'armatura Wild Leather; gli altri li padroneggi già. Non ti farò sgobbare inutilmente per averlo. Te lo sei $Gguadagnato:guadagnata; pienamente, e anche di più... ma non posso dartelo io. È il mio maestro, colui che mi ha iniziato al mestiere, che deve ricompensarti.\n\nPorta questa lettera a Telonis; insegna conciatura a Darnassus. Mostragli la lettera, e lascia che ti riconosca come $Gsuo pari:sua pari;, come faccio io.", enHash = "63915213", vanilla = true },
        objectives = { it = "Consegna Pratt's Letter a Telonis, il maestro conciatore di Darnassus.", enHash = "d29f4832", vanilla = true },
        progress = { it = "Salve, $R... dal tuo aspetto capisco che sei $Gun conciatore:una conciatrice; come me. Sei $Gvenuto:venuta; ad attingere alla mia abilità, o forse hai altre faccende da sbrigare con me?", enHash = "a331fb56", vanilla = true },
        reward = { it = "Ah, sì, ti manda Pratt. Anche se è un umano, a volte mi ricorda noi elfi della notte. La sua dedizione e il suo talento con il cuoio sono notevoli. Se in questa lettera ti loda così tanto, è un segno di rispetto che riconosco.\n\nSo che ti ha insegnato l'arte del Wild Leather. Permettimi di completare il tuo addestramento con questo schema. Usalo bene; pochi al mondo conoscono i segreti dei Wild Leather Cloak.", enHash = "f2082a37", vanilla = true },
    },
    [2854] = {
        title = { it = "Armatura Wild Leather", enHash = "bb1218b2", vanilla = true },
        text = { it = "$N, la tua abilità di $Gconciatore:conciatrice; ti precede. Custodisco un sapere di conciatura che faresti bene ad acquisire... l'armatura Wild Leather! Il Wild Leather sfrutta le proprietà potenti e caotiche delle Wildvine, che si trovano nelle zone di vegetazione rigogliosa e addosso ad alcune delle creature che ci vivono. Per $Gun artigiano:un'artigiana; della tua abilità non c'è armatura migliore di quella che se ne ricava, garantito.\n\nTi insegnerò, ma per un po' lavorerai per me. Come primo pagamento mi bastano dieci pezzi di Thick Leather. Dopo, parleremo dei dettagli.", enHash = "c594214b", vanilla = true },
        objectives = { it = "Porta 10 Thick Leather a Jangdor Swiftstrider, a Camp Mojache.", enHash = "423ffe24", vanilla = true },
        progress = { it = "Mettiamo le cose in chiaro: sarai $Gil mio apprendista:la mia apprendista; mentre impari l'arte dell'armatura Wild Leather. Dato che le Wildvine sono insieme potenti e caotiche, danno un vantaggio casuale ma forte all'armatura che realizzerai, già robusta di suo. Però non è stato facile per me acquisire questa conoscenza.\n\nPer avviare il lavoro, il costo iniziale è di dieci pezzi di Thick Leather.\n\nQuando avremo sistemato questo, passeremo al lavoro che dovrai fare per ottenere gli schemi.", enHash = "c0413938", vanilla = true },
        reward = { it = "Bene, $N, sono lieto di averti come $Gmio apprendista:mia apprendista;. Come $Gconciatore:conciatrice; hai fatto una scelta saggia: chi usa armature di cuoio farà a gara per venire da te, quando avrai imparato a padroneggiare l'arte del Wild Leather.\n\nMettiamoci al lavoro — da dove vuoi cominciare?", enHash = "dc78c1b3", vanilla = true },
    },
    [2855] = {
        title = { it = "Wild Leather Shoulders", enHash = "0ffa78c6", vanilla = true },
        text = { it = "I Wild Leather Shoulders sostengono benissimo il fisico di chi li indossa e offrono una protezione superiore alla parte alta delle braccia oltre che alle spalle. Come per tutta l'armatura Wild Leather, cucendoci dentro la Wildvine il pezzo si impregna di un potenziamento casuale ma molto potente.\n\nPer questo schema mi serviranno sei Thick Armor Kit e una Wildvine. Non dovrebbe essere un ordine troppo impegnativo da evadere, per te.", enHash = "4dda7b3e", vanilla = true },
        objectives = { it = "Porta 6 Thick Armor Kit e una Wildvine a Jangdor Swiftstrider, a Camp Mojache.", enHash = "9cae4614", vanilla = true },
        progress = { it = "Hai i sei Thick Armor Kit e la Wildvine che ti ho chiesto?\n\nConsidera la fabbricazione dei kit per armature una lezione di lavoro costante e affidabile: il metodo di lavorazione regolare che acquisisci esercitando il mestiere su questi kit ti aiuta a sviluppare le capacità necessarie per il lavoro minuzioso che richiedono le armature Wild Leather.\n\nOgni lezione ha uno scopo, $N. È importante accoglierle tutte con lo spirito giusto.", enHash = "7a1d0659", vanilla = true },
        reward = { it = "Questi kit per armature sono di buona qualità, $N. Se c'è una cosa che pretendo, non solo dal mio lavoro ma anche da quello di chi è sotto la mia guida, è la qualità.\n\nHai lavorato bene per guadagnarti questo schema; spero che ti renda quanto ha reso a me.", enHash = "793e45b2", vanilla = true },
    },
    [2856] = {
        title = { it = "Wild Leather Vest", enHash = "8a333b7d", vanilla = true },
        text = { it = "I Wild Leather Vest sono il pezzo base di ogni set di armatura Wild Leather. La struttura del corpetto e la Wildvine intrecciata al suo interno danno vita a un capo che offre la massima protezione al torso, lasciando che una potente magia si diffonda in tutto l'indumento.\n\nPer questo schema mi serviranno due Turtle Scale Breastplate, due paia di Turtle Scale Gloves e una Wildvine. Non è una lezione facile, ma di sicuro hai l'abilità per portarla a termine.", enHash = "253cbe9a", vanilla = true },
        objectives = { it = "Porta 2 Turtle Scale Breastplate, 2 Turtle Scale Gloves e una Wildvine a Jangdor Swiftstrider, a Camp Mojache.", enHash = "363ae05d", vanilla = true },
        progress = { it = "Hai le due Turtle Scale Breastplate e i Turtle Scale Gloves? E non dimenticare la Wildvine!\n\nGià dai primi schemi impariamo che le basi della forma si applicano bene anche ai capi più difficili. Anche se sono oggetti diversi, la forma delle Turtle Scale Breastplate ti prepara ai dettagli che servono per fare un Wild Leather Vest.\n\nMan mano che andrai avanti con le lezioni, le abilità che ti insegno diventeranno arte.", enHash = "f784d436", vanilla = true },
        reward = { it = "Sono pezzi davvero belli, $N. La maestria e la cura con cui li hai fatti mostrano che hai scelto di dedicarti completamente a questi compiti.\n\nHai soddisfatto le mie richieste, e per questo ti spetta la ricompensa. Ora la conoscenza per fare i Wild Leather Vest è tua!", enHash = "12fc0fab", vanilla = true },
    },
    [2857] = {
        title = { it = "Wild Leather Helmet", enHash = "b26b3b5a", vanilla = true },
        text = { it = "Un Wild Leather Helmet offre a chi lo indossa una protezione superiore per i punti vitali della testa, senza rinunciare alla comodità. Come per tutta l'armatura Wild Leather, la Wildvine incorporata nell'elmo infonde nella sua struttura una magia potente ma casuale. Chi indossa il cuoio vorrà di sicuro questo pezzo!\n\nPer questo schema mi serviranno due Nightscape Tunic, 2 Nightscape Headband e una Wildvine. Completa questa lezione e lo schema sarà tuo!", enHash = "e9988355", vanilla = true },
        objectives = { it = "Porta 2 Nightscape Tunic, 2 Nightscape Headband e una Wildvine a Jangdor Swiftstrider, a Camp Mojache.", enHash = "86e64d77", vanilla = true },
        progress = { it = "Ho bisogno che tu mi faccia quelle tuniche e quelle fasce, e mi serve anche quel pezzo di Wildvine, prima di svelarti come si fanno i Wild Leather Helmet.\n\nTra gli avventurieri le protezioni per la testa sono molto ricercate, che si tratti di una fascia di una semplicità disarmante o di un elmo che copre tutto il capo. Le basi per creare un copricapo pregiato restano le stesse, qualunque sia il suo aspetto esteriore.", enHash = "f2e5a700", vanilla = true },
        reward = { it = "L'equipaggiamento Nightscape che mi hai portato soddisfa alla perfezione le richieste che ti avevo fatto, $N. Non mi aspetto niente di meno da $Gun conciatore:una conciatrice; del tuo calibro.\n\nTi sei $Gguadagnato:guadagnata; l'onore di fabbricare i Wild Leather Helmet. Ti do questo schema volentieri, e spero che tu ne tragga il giusto profitto.", enHash = "ec919338", vanilla = true },
    },
    [2858] = {
        title = { it = "Wild Leather Boots", enHash = "bb1edb34", vanilla = true },
        text = { it = "La tua conoscenza dell'armatura Wild Leather cresce, $N, ma c'è ancora altro da imparare.\n\nI Wild Leather Boots sono la pietra angolare di ogni set. Stivali come questi sono fatti per avvolgere il piede nella comodità e al tempo stesso proteggerlo dai pericoli dell'avventura. Le suole morbide sono una benedizione per chi cerca calzature con cui muoversi in silenzio.\n\nPer questo schema devi fabbricare due Nightscape Pants e due Nightscape Boots. Mi serviranno anche due Wildvine... non una sola. Quando avrai questi oggetti, andremo avanti.", enHash = "561edbcd", vanilla = true },
        objectives = { it = "Porta 2 Nightscape Pants, 2 Nightscape Boots e 2 Wildvine a Jangdor Swiftstrider, a Camp Mojache.", enHash = "2c59fd3a", vanilla = true },
        progress = { it = "I pantaloni, gli stivali e le Wildvine devono arrivarmi prima che tu impari lo schema, $N. Hai fatto come ti ho chiesto?\n\nFin dal primo paio di stivali che impariamo a fare, cominciamo a capire che uno stivale di qualità deve stare in perfetto equilibrio tra comodità e funzionalità. Unendole, riusciamo a creare oggetti che permettono a chi li indossa di ignorare una fatica che stroncherebbe chi porta articoli di qualità inferiore.", enHash = "42940a07", vanilla = true },
        reward = { it = "Ancora una volta hai prodotto oggetti con l'abilità di un professionista esperto. Ti sei $Gguadagnato:guadagnata; questo schema, e anche le mie congratulazioni.", enHash = "be9aee2a", vanilla = true },
    },
    [2859] = {
        title = { it = "Wild Leather Leggings", enHash = "5b338017", vanilla = true },
        text = { it = "Sei $Gpronto:pronta; a padroneggiare lezioni più complesse, $N. I Wild Leather Leggings sono tra i pezzi di cuoio più robusti e potenti che esistano. Vita, cosce, polpacci e punti vitali — tutto riceve una protezione enorme. Con in più il potenziamento della Wildvine, gli avventurieri che li possiedono ti ringrazieranno ogni volta che ti vedranno.\n\nPerché tu possa avere questo schema, mi servono due Turtle Scale Helm, due Turtle Scale Bracers e due Wildvine.", enHash = "ce24e38a", vanilla = true },
        objectives = { it = "Porta 2 Turtle Scale Helm, 2 Turtle Scale Bracers e 2 Wildvine a Jangdor Swiftstrider, a Camp Mojache.", enHash = "dfb15136", vanilla = true },
        progress = { it = "Hai pronti i Turtle Scale Bracers e i Turtle Scale Helm? Non dimenticare le due Wildvine che ti ho chiesto.\n\nOrmai cominci a renderti conto di quanto potere possa racchiudere l'armatura Wild Leather. Un'armatura che non ha limiti di impiego ha un valore quasi inestimabile per un conciatore. Gli unici limiti stanno nella quantità di materiali per fare gli oggetti — non nella qualità dei prodotti finiti!", enHash = "15aee013", vanilla = true },
        reward = { it = "Di nuovo hai portato a termine il mio compito senza sbavature. Forse un giorno sarò io a venire da TE in cerca di conoscenza, eh, $N?\n\nEcco lo schema dei gambali, con la mia gratitudine. Fai tesoro di questo sapere, e lascia che i tuoi prodotti finiti attingano alla tua notevole abilità!", enHash = "a49bdfea", vanilla = true },
    },
    [2860] = {
        title = { it = "$GMaestro:Maestra; del Wild Leather", enHash = "2cbbc98d", vanilla = true },
        text = { it = "$N, hai imparato tutto quello che sono in grado di insegnarti. Resta però un ultimo schema dell'armatura Wild Leather. Non ti farò sgobbare inutilmente per averlo; te lo sei $Gguadagnato:guadagnata; pienamente, e anche di più. Questo schema, però, non posso condividerlo con te liberamente.\n\nÈ la mia maestra, colei che mi ha iniziato al mestiere, che deve ricompensarti. Porta questo biglietto a Una; insegna conciatura a Thunder Bluff. Mostrale la lettera, e lascia che ti riconosca come $Gsuo pari:sua pari;, come faccio io.", enHash = "87019e71", vanilla = true },
        objectives = { it = "Consegna Jangdor's Letter a Una, la maestra conciatrice di Thunder Bluff.", enHash = "970f6a25", vanilla = true },
        progress = { it = "Salve, $R... dal tuo aspetto capisco che sei $Gun conciatore:una conciatrice; come me. Sei $Gvenuto:venuta; ad attingere alla mia abilità, o forse hai altre faccende da sbrigare con me?", enHash = "5baf4a42", vanilla = true },
        reward = { it = "Ah, sì, ti manda Jangdor. Sono lieta di vedere che uno dei miei allievi migliori ora ha $Gun allievo tutto suo:un'allieva tutta sua;.\n\nLa sua dedizione e il suo talento con il cuoio sono notevoli. Se in questa lettera ti loda così tanto, è un segno di rispetto che riconosco.\n\nSo che ti ha insegnato l'arte del Wild Leather. Permettimi di completare il tuo addestramento con questo schema. Usalo bene; pochi al mondo conoscono i segreti dei Wild Leather Cloak.", enHash = "99e46ec6", vanilla = true },
    },
    [2861] = {
        title = { it = "Il compito di Tabetha", enHash = "87107e5c", vanilla = true },
        text = { it = "Si dice che Tabetha, una collega maga che vive nel profondo del Dustwallow Marsh, abbia un conto in sospeso con un certo troll delle sabbie di Zul'Farrak. Se parli con Tabetha, potrà dirti di più.\n\nE porta con te qualche amico, $N. Se Tabetha ti manda a Zul'Farrak, non vorrai andarci da $Gsolo:sola;.\n\nTroverai la casetta di Tabetha a ovest di Theramore, appena a nord della Stonemaul Ruin.", enHash = "49a36c9a", vanilla = true },
        objectives = { it = "Parla con Tabetha, nel Dustwallow Marsh.", enHash = "009646eb", vanilla = true },
        reward = { it = "Proprio così. Ho davvero un conto in sospeso con una troll. Anzi, più d'uno. Voglio tutte le sue ossa!\n\nVuoi aiutarmi?", enHash = "d319f724", vanilla = true },
    },
    [2862] = {
        title = { it = "Guerra ai Woodpaw", enHash = "8b925da1", vanilla = true },
        text = { it = "Gli gnoll... sono più di un fastidio. Sono una minaccia costante per l'esistenza stessa di questo campo! Poco importa se siano originari di Feralas o no: se non rafforziamo la nostra determinazione contro di loro, ci ritroveremo cacciati dall'intera regione.\n\nUltimamente gli attacchi degli gnoll contro il campo si sono fatti più accaniti. Ci serve il tuo aiuto per sfoltirne il numero; portami dieci delle loro criniere, e ti ricompenserò generosamente per il tuo impegno.\n\nVa'!", enHash = "a38d9d73", vanilla = true },
        objectives = { it = "Porta 10 Woodpaw Gnoll Mane a Hadoken Swiftstrider, a Camp Mojache.", enHash = "16a1541a", vanilla = true },
        progress = { it = "Li respingiamo, eppure continuano ad attaccare! Qualcuno o qualcosa deve farli impazzire... oh, sei $Gtornato:tornata;, eh, $N? Hai le criniere che mi servono per riscuotere la taglia?", enHash = "f2b409de", vanilla = true },
        reward = { it = "Questa è la prova di un buon inizio, $N. Le tue capacità di $Gsoldato:soldatessa; meritano un elogio.\n\nNon sei $Gl'unico:l'unica; a cui chiedo questo compito. Molti prima di te li hanno combattuti, e in passato i nostri sforzi li hanno tenuti a bada. Di recente, però, i loro tentativi di spingersi a nord, nella nostra zona d'influenza, sono aumentati moltissimo. E anche i loro attacchi sono diventati più feroci... quasi come se fossero disperati.\n\nMa ho un piano, $N, che potrebbe sistemare le cose con loro una volta per tutte...", enHash = "e83e16dd", vanilla = true },
    },
    [2863] = {
        title = { it = "Attacco agli Alpha", enHash = "9aa870b4", vanilla = true },
        text = { it = "Il piano è abbattere in rapida successione vari capi degli gnoll, gli Alpha, come si fanno chiamare. Se riusciamo a colpirli con una devastazione così rapida e precisa, porteremo il caos nelle loro file. Forse faremo anche entrare nelle loro teste dure e piene di pulci il messaggio che possiamo distruggerli, e che lo faremo!\n\nVoglio che tu sia $Gil messaggero:la messaggera; della mia volontà: elimina cinque dei loro Alpha entro un'ora perché funzioni, $N, altrimenti resteremo in questa situazione di stallo!", enHash = "5803a421", vanilla = true },
        objectives = { it = "Uccidi 5 Woodpaw Alpha e torna da Hadoken Swiftstrider entro un'ora.", enHash = "d1a72310", vanilla = true },
        progress = { it = "Il tempo stringe, $N! Se non sei qui per riferirmi che hai fatto fuori gli Alpha, stai perdendo tempo!", enHash = "63144107", vanilla = true },
        reward = { it = "Hai fatto quello che ti ho chiesto, e per questo ti rendo onore. Prendi questa piccola ricompensa come compenso per i tuoi sforzi, $N.\n\nCon il loro numero sfoltito e i loro capi uccisi, gli gnoll ci penseranno due volte prima di assaltare il campo. Ma questo non chiude la questione...\n\nDeve esserci un motivo se gli gnoll sono stati aizzati fino a questo stato di frenesia. Prima che abbiano la possibilità di riorganizzarsi, voglio scoprire cosa lo provoca.", enHash = "790b769d", vanilla = true },
    },
    [2864] = {
        title = { it = "Tran'rek", enHash = "4c3658bc", vanilla = true },
        text = { it = "Mio cugino Tran'rek è in una situazione difficile. Settimane fa mi aveva promesso un carico di gusci di scarabeo e non l'ha ancora consegnato. È mio cugino, quindi non vorrei dover mandare qualcuno a Gadgetzan a rompergli qualcosa addosso.\n\nPuoi parlare con Tran'rek per me? Fagli sapere che deve preparare quella consegna prima che io faccia qualcosa di avventato!\n\nGadgetzan si trova nel nord di Tanaris, in Kalimdor.", enHash = "7d4f94a0", vanilla = true },
        objectives = { it = "Parla con Tran'rek, a Gadgetzan.", enHash = "112077f6", vanilla = true },
        reward = { it = "Salve!\n\nOh, hai parlato con mio cugino Krazek? Come sta? Spero che Booty Bay lo tratti bene...\n\nGusci di scarabeo, dici? Be'... lascia che ti racconti una storia...", enHash = "e25e4e2d", vanilla = true },
    },
    [2865] = {
        title = { it = "Gusci di scarabeo", enHash = "aafa07c1", vanilla = true },
        text = { it = "Gli scarabei di Tanaris hanno gusci durissimi! Abbastanza duri da usarli come materiale da costruzione per un sacco di cose. Tantissime cose!\n\nAnzi, quei gusci sono così utili... che gli scarabei sono stati cacciati quasi fino all'estinzione!\n\nIo so dove ci sono altri scarabei, e se mi prometti di portarmi i loro gusci, ti dirò dove sono. Promesso?\n\nBene, gli scarabei hanno una colonia a Zul'Farrak. A quanto pare i troll non li cacciano per i gusci.\n\nMa tu sì! Va' a Zul'Farrak e portami dei gusci non incrinati!", enHash = "2f9ceb95", vanilla = true },
        objectives = { it = "Porta 5 Uncracked Scarab Shell a Tran'rek, a Gadgetzan.", enHash = "c413b297", vanilla = true },
        progress = { it = "Hai i gusci? Mio cugino a Booty Bay aspetta un carico, e si sta spazientendo!", enHash = "72156efe", vanilla = true },
        reward = { it = "Oh, fantastico! Ce l'hai fatta!\n\nGrazie, $N. Mi hai proprio salvato la vita!", enHash = "cdaa1c7e", vanilla = true },
    },
    [2866] = {
        title = { it = "Le Ruins of Solarsal", enHash = "50fb62e2", vanilla = true },
        text = { it = "A sud di qui ci sono le Ruins of Solarsal: una zona che risale a molto prima dei tempi moderni. All'inizio abbiamo esplorato le rovine e non abbiamo trovato niente di notevole; per questo le abbiamo lasciate in pace.\n\nDi recente, però, i naga Hatecrest hanno occupato queste rovine in numero allarmante. All'inizio l'abbiamo considerato il preludio di un attacco. Anche se quella minaccia resta possibile, crediamo che stia succedendo qualcos'altro.\n\nVa' là, esplora le rovine e cerca qualunque cosa ti sembri fuori dal comune. Buona fortuna, $N.", enHash = "837562a9", vanilla = true },
        objectives = { it = "Esplora le Ruins of Solarsal e indaga sulla presenza dei naga.", enHash = "60343e86", vanilla = true },
        reward = { it = "Esaminando il gazebo scopri alcune cose interessanti e insolite, rispetto alle rovine circostanti.\n\nPrima di tutto, il gazebo è chiaramente una costruzione più recente degli altri elementi delle rovine. Poi, sui suoi lati è incisa una piccola serie di glifi; i glifi seguono uno schema che si ripete, ma per il resto la loro origine e il loro significato sono sconosciuti. Infine, la pietra del gazebo è calda al tatto.\n\nQuesto rientra di sicuro tra le cose \"fuori dal comune\" nella ricerca tra le rovine!", enHash = "47fb545f", vanilla = true },
    },
    [2867] = {
        title = { it = "Ritorno alla Feathermoon Stronghold", enHash = "ae4eaba7", vanilla = true },
        text = { it = "Con la scoperta dello strano gazebo nel cuore delle Ruins of Solarsal, è giunto il momento di tornare alla Feathermoon Stronghold e riferire a General Shandris Feathermoon quello che hai scoperto.", enHash = "96cfeb34", vanilla = true },
        objectives = { it = "Torna da Shandris Feathermoon, alla Feathermoon Stronghold, e riferisci le tue scoperte.", enHash = "b3768129", vanilla = true },
        reward = { it = "$GBentornato:Bentornata;, $N. Il tuo rapporto su questo gazebo è molto... inquietante. Sembra che, anche se i naga non stavano progettando un attacco, la loro presenza continua non promette niente di buono per la nostra avanzata in Feralas. Comunque, ecco un compenso per la tua indagine.\n\nSembra che la Feathermoon Stronghold abbia un disperato bisogno di altro aiuto contro i naga Hatecrest. Vorrei affidarti questo compito, se te la senti. C'è molto da fare.", enHash = "3b975b23", vanilla = true },
    },
    [2869] = {
        title = { it = "Contro gli Hatecrest", enHash = "33871ebf", vanilla = true },
        text = { it = "A questo punto la cosa migliore da fare è dare per scontato che, qualunque cosa stiano tramando, i naga prima o poi cercheranno di prendersi l'isola. Dobbiamo fare passi decisi per contrastare questa minaccia prima che sia troppo tardi.\n\nPortami dieci Hatecrest Naga Scale in buone condizioni; dovrebbe esserti chiaro come procurartele. Farai le tue prime armi contro i naga, e noi avremo una presenza naga più debole a Sardor Isle: due prospettive che vanno entrambe a nostro vantaggio.", enHash = "ab694801", vanilla = true },
        objectives = { it = "Porta 10 Hatecrest Naga Scale a Latronicus Moonspear, alla Feathermoon Stronghold.", enHash = "97943204", vanilla = true },
        progress = { it = "$N, se sei qui per il compito che ti è stato affidato, ottimo: cerco dieci scaglie Hatecrest. Se sei qui per fare due chiacchiere, al momento non ho tempo per simili sciocchezze.\n\nSappi questo: noi elfi della notte non siamo guerrafondai. La nostra razza è votata alla conservazione della pace e dell'armonia. Questo però non vuol dire che non proteggeremo in anticipo i nostri interessi. È il mio dovere verso il generale Feathermoon e verso la roccaforte.", enHash = "3c782991", vanilla = true },
        reward = { it = "Sì, sì, queste scaglie sono più che soddisfacenti. Anzi, credo che le manderò giù a Pratt perché le guardi. Magari riuscirà a ricavarne qualcosa di utile.\n\nQuanto a te, ho un'altra missione per cui voglio mandarti. Ma prima, ecco la tua ricompensa per le scaglie. Il tuo servizio costante per il generale e per tutta la Feathermoon Stronghold è una benedizione nelle avversità.", enHash = "39f482bf", vanilla = true },
    },
    [2870] = {
        title = { it = "Contro Lord Shalzaru", enHash = "81e3bd96", vanilla = true },
        text = { it = "$N, nuovi rapporti degli esploratori ci hanno dato un'idea chiara della catena di comando dei naga. Tra le loro file c'è anche la nobiltà, ed è lei a dare tutti gli ordini.\n\nIn particolare, abbiamo individuato uno dei nobili più crudeli: Lord Shalzaru. Gli esploratori riferiscono che lui stesso ha portato alla luce una strana reliquia durante un recente scavo dei naga, in una grotta a sud delle rovine principali, oltre l'acqua, sulla Isle of Dread.\n\nMetti fine a tutto questo mettendo fine a lui, e portami la sua reliquia perché possiamo studiarla.", enHash = "2ece99d4", vanilla = true },
        objectives = { it = "Elimina Lord Shalzaru, poi porta la Mysterious Relic che ha portato alla luce a Latronicus Moonspear, alla Feathermoon Stronghold.", enHash = "2a4802bd", vanilla = true },
        progress = { it = "Abbattere Lord Shalzaru farebbe di sicuro arretrare i loro piani di settimane, se non di mesi. Oltretutto, la reliquia che ha portato alla luce ci interessa senza dubbio.\n\nHai portato a termine la missione che ti è stata affidata, $N?", enHash = "8ae048ca", vanilla = true },
        reward = { it = "Ben giocata, $N! La morte di Lord Shalzaru getterà i naga nello scompiglio per un po' di tempo, se non per sempre. La minaccia che rappresentano è ora sotto il nostro controllo più di quanto lo sia mai stata, e lo dobbiamo a te.\n\nEcco altro denaro della taglia dalle casse della roccaforte: te lo sei $Gguadagnato:guadagnata; fino all'ultima moneta. Tu e i tuoi siete sempre i benvenuti alla Feathermoon Stronghold, $Gamico mio:amica mia;.\n\nUn'ultima cosa prima che tu vada, $N... se potessi...", enHash = "ad143e8b", vanilla = true },
    },
    [2871] = {
        title = { it = "Consegnare la reliquia", enHash = "b5e08341", vanilla = true },
        text = { it = "Se fossi così gentile da consegnare la reliquia a mia moglie Vestia, te ne sarei grato. Non è solo un'ottima sacerdotessa per la nostra comunità, ma è anche una delle studiose più esperte che troverai ovunque. Io non capirei nulla di questo congegno nemmeno se ci fosse una scommessa in ballo. Mia moglie invece, se c'è qualcuno che può capire cos'è questa cosa, è lei... e dobbiamo saperlo!\n\nÈ appena dietro l'angolo, di sicuro a studiare. Grazie, $N.", enHash = "01961737", vanilla = true },
        objectives = { it = "Consegna la Mysterious Relic a Vestia Moonspear, alla Feathermoon Stronghold.", enHash = "c2cd47a1", vanilla = true },
        progress = { it = "Sì, posso esserti utile?\n\nAspetta, sei tu $Gil:la; $C che ha aiutato il generale Feathermoon e Latro con la minaccia dei naga, vero? Sono Vestia, la moglie di Latro... ehm, anzi, di Latronicus. È un piacere conoscerti!\n\nScusa, sei qui per lavoro, naturalmente. Hai qualcosa per me... da parte sua, per caso?", enHash = "77fb643f", vanilla = true },
        reward = { it = "Interessante... dici che viene dalle Ruins of Solarsal? Be', Latro ha ragione: devo esaminarla. A prima vista non sembra originaria delle rovine. D'altra parte, non è di fattura naga... non una cosa così aliena.\n\nCi vorrà un po' di tempo per studiare questo oggetto. Quando avrò finito le mie ricerche, forse sfrutterò il tuo talento, se sarai da queste parti.\n\nTieni, prendi uno di questi oggetti in più che abbiamo; spero che ti sia utile!", enHash = "6f607eb7", vanilla = true },
    },
    [2902] = {
        title = { it = "Indagine sui Woodpaw", enHash = "3c6c35fb", vanilla = true },
        text = { it = "Gli gnoll non sono esattamente dei geni, ma di sicuro avranno una qualche strategia scritta sulle loro attività recenti. Se trovassimo quei piani, avremmo un'idea più chiara di cosa li agita tanto.\n\nVoglio che tu torni dai Woodpaw e trovi qualunque cosa somigli ai loro piani di battaglia. Devono avere qualcosa: i loro attacchi sono stati troppo coordinati per essere fatti senza. Trovali, e torna da me quando li avrai.", enHash = "c929e614", vanilla = true },
        objectives = { it = "Trova i piani di battaglia degli gnoll da qualche parte negli accampamenti degli gnoll a sud di Camp Mojache.", enHash = "0f9c7811", vanilla = true },
        reward = { it = "Esaminando la mappa scopri che si tratta dei piani di battaglia che vuole Hadoken Swiftstrider. Sulla mappa sono disegnate numerose frecce che forse rappresentano movimenti di truppe, anche se quasi tutte sembrano dirette verso sud, e non verso nord, dove si trova Camp Mojache.\n\nUn'altra parte della mappa mostra il disegno di quello che credi sia un grosso insetto di qualche tipo, con sotto varie tacche. A giudicare dagli gnoll, forse rappresentano le loro perdite contro questi insetti sconosciuti...", enHash = "2e947d13", vanilla = true },
    },
    [2903] = {
        title = { it = "I piani di battaglia", enHash = "cfdbe451", vanilla = true },
        text = { it = "Ora che hai scoperto i piani di battaglia degli gnoll, non resta che riportarli a Hadoken Swiftstrider, a Camp Mojache. Forse lui, o qualcun altro lì, riuscirà a capire meglio cosa stanno tramando gli gnoll.", enHash = "61fe2140", vanilla = true },
        objectives = { it = "Porta i Woodpaw Battle Plans a Hadoken Swiftstrider, a Camp Mojache.", enHash = "b212dd6a", vanilla = true },
        progress = { it = "$GBentornato:Bentornata;, $N. Sei $Griuscito:riuscita; a trovare qualche prova concreta dei piani degli gnoll?", enHash = "8b26852f", vanilla = true },
        reward = { it = "Ah, è proprio quello che ci serviva. Anche se non sono molto abile a decifrare la maggior parte degli scarabocchi di questa mappa, ai miei tempi ho visto abbastanza piani di battaglia da capire cosa sta succedendo con gli gnoll. Sembra che al momento stiano combattendo una guerra su due fronti. Uno è contro di noi... ma pare che le loro energie principali siano rivolte contro un nemico a sud.\n\nQui c'è più di quanto sembri. Forse è il momento di capire chi sia davvero quest'altro nemico che stanno affrontando.", enHash = "8492e3a6", vanilla = true },
    },
    [2904] = {
        title = { it = "Un bel guaio", enHash = "0bb2739f", vanilla = true },
        text = { it = "<Kernobee geme.> Cos... Cos'è successo?\n\nL'ultima cosa che ricordo è che un gruppo di nani Dark Iron mi ha catturato, mi ha pestato a un passo dalla morte e poi mi ha buttato qui dentro con questi trogg immondi.\n\nPortami fuori di qui, $N!\n\nEcco il piano: portami all'uscita; se ne usciamo vivi, tu vai a Booty Bay e fai sapere a Scooty che sono andato a Ratchet ad avvertire Tinkerwiz che i Dark Iron hanno messo mano alla costruzione di quel super rig.\n\nMuoviamoci!", enHash = "cd8485e2", vanilla = true },
        objectives = { it = "Scorta Kernobee fino all'uscita della Clockwerk Run, poi riferisci a Scooty, a Booty Bay.", enHash = "7b9ae08f", vanilla = true },
        progress = { it = "Eh? Kernobee è vivo??", enHash = "14cdab0a", vanilla = true },
        reward = { it = "Immagino che tu meriti una ricompensa per averci riportato Kernobee tutto intero, $N. Se torni a Gnomeregan, questi potrebbero darti il vantaggio che ti serve per sconfiggere quel buono a nulla di un traditore, Mekgineer Thermaplugg.", enHash = "ff57e5fa", vanilla = true },
    },
    [2922] = {
        title = { it = "Salva il cervello di Techbot!", enHash = "81813951", vanilla = true },
        text = { it = "Quando la nostra amata città di Gnomeregan è caduta, una scintilla impazzita deve aver scosso la mia povera creatura, Techbot. Un tempo aiutava me e i miei soci con i suoi innumerevoli aggeggi e il suo sterminato archivio di informazioni, ma il suo cervello positronico si è polarizzato. Adesso è negatronico... e i comportamenti di Techbot sono invertiti. Si aggira per Gnomeregan in preda alla frenesia!\n\nMa forse si può recuperare. Forse, se riesci a recuperare il Memory Core di Techbot e a portarmelo, posso scoprire la causa della polarizzazione e riparare il mio povero Techbot.", enHash = "8aab3652", vanilla = true },
        objectives = { it = "Porta Techbot's Memory Core a Tinkmaster Overspark, a Ironforge.", enHash = "e9703e99", vanilla = true },
        progress = { it = "L'hai trovato Techbot? L'hai recuperato il suo Memory Core??", enHash = "78a26417", vanilla = true },
        reward = { it = "Oh, è meraviglioso! Grazie, $N! Mi metto subito al lavoro!!\n\nPovero, povero Techbot... Non prendertela. Ti rimettiamo a posto noi.\n\nOra, dove ho messo lo spinotto della mia chiave idro-snodata...", enHash = "b9c55dbb", vanilla = true },
    },
    [2923] = {
        title = { it = "Tinkmaster Overspark", enHash = "d29f053d", vanilla = true },
        text = { it = "Tinkmaster Overspark è molto turbato per la sorte della sua creatura meccanica, Techbot. Io ricordo Techbot come uno strumento gentile e utile per gli gnomi, ma Overspark mi dice che si è guastato.\n\nMolto triste. Ma con un po' di fortuna forse lo si può riparare!\n\nParla con Tinkmaster Overspark, a Tinker Town, a Ironforge. Sarà contento del tuo aiuto.", enHash = "0298744a", vanilla = true },
        objectives = { it = "Parla con Tinkmaster Overspark, a Ironforge.", enHash = "af4cbff3", vanilla = true },
        reward = { it = "Sì, è vero. Techbot è impazzito! Ti prego, puoi aiutarmi?", enHash = "a257199d", vanilla = true },
    },
    [2924] = {
        title = { it = "Essential Artificials", enHash = "a60429a7", vanilla = true },
        text = { it = "Un componente meccanico quasi universale — l'Essential Artificial — era molto utile ai meccanici e ai fabbri di Gnomeregan. Ma durante l'esodo frenetico dalla nostra città nessuno si è ricordato di portarne via nemmeno uno! E a me ne serve una grande scorta per un lavoro che comincerò presto.\n\nTi prego, entra a Gnomeregan e portamene un po'. Li troverai nelle zone più profonde della nostra città, dentro contenitori chiamati artificial extrapolator.\n\nGrazie, $N, e fa' in fretta, ti prego!", enHash = "f1f1a123", vanilla = true },
        objectives = { it = "Porta 12 Essential Artificial a Klockmort Spannerspan, a Ironforge.", enHash = "b25d7c24", vanilla = true },
        progress = { it = "Ce li hai gli Essential Artificial?", enHash = "07a0bca9", vanilla = true },
        reward = { it = "Li hai presi! Ora posso cominciare i miei nuovi esperimenti!\n\nNon so come ringraziarti, $N! Il tuo coraggio ha fatto fare alla ricerca gnomica un balzo in avanti!", enHash = "d16be104", vanilla = true },
    },
    [2925] = {
        title = { it = "Gli essenziali di Klockmort", enHash = "dc93d41f", vanilla = true },
        text = { it = "Un amico gnomo, Klockmort Spannerspan, mi ha mandato un messaggio da Ironforge. Mi dice che gli serve aiuto per una missione pericolosa, ma essenziale, dentro Gnomeregan, la città gnomica un tempo grande e ora contaminata e piena di gnomi impazziti e dei loro congegni.\n\nIo devo restare qui, ma il cuore mi si stringe dalla voglia di aiutare il mio amico. Se puoi andare al mio posto, ti sarò molto in debito.\n\nKlockmort lo trovi a Tinkertown, a Ironforge.", enHash = "c293d91e", vanilla = true },
        objectives = { it = "Parla con Klockmort Spannerspan, a Ironforge.", enHash = "a049a5d3", vanilla = true },
        reward = { it = "Sì! Sì che mi serve aiuto per una missione dentro Gnomeregan. E tu sei proprio $Gil:la; $C che ci vuole!", enHash = "a2874dd2", vanilla = true },
    },
    [2926] = {
        title = { it = "Gnogaine", enHash = "49c9955e", vanilla = true },
        text = { it = "Dall'incidente in poi, Gnoarn non pensa e non parla d'altro che ripulire Gnomeregan dall'infestazione dei trogg e trovare una cura per il male che l'affligge, $N.\n\nPer fortuna io e Razzle siamo vicini a una specie di cura — o quello, o la ricetta di un rum davvero potente. Non lo sapremo finché non proviamo! Naturalmente, per provare la nostra teoria ci serviranno alcune cose: in particolare, la ricaduta radioattiva dei trogg irradiati di Gnomeregan. Riempi questa fiala con il bagliore verde e riportamela!", enHash = "424b9267", vanilla = true },
        objectives = { it = "Usa l'Empty Leaden Collection Phial sugli Irradiated Invader o sugli Irradiated Pillager per raccogliere la ricaduta radioattiva. Quando è piena, riportala a Ozzie Togglevolt, a Kharanos.", enHash = "b6cc5d4f", vanilla = true },
        progress = { it = "Non vedi che qui stiamo cercando di curare un'intera specie di gnomi??! Ci serve altro bagliore verde!", enHash = "278f7e75", vanilla = true },
        reward = { it = "Ottimo lavoro! È arrivato il momento di provare la nuova formula. Se funziona, non solo quel Leper Gnome catturato sarà guarito, ma io dovrei ritrovarmi con una bella chioma folta! Indietro!", enHash = "2790080f", vanilla = true },
    },
    [2927] = {
        title = { it = "Il giorno dopo", enHash = "fef44369", vanilla = true },
        text = { it = "Non penserai mica che sia sempre stato calvo, vero? No di certo, $Gsignore:signora;! È stata la fuga di radiazioni a Gnomeregan a causare questa tragica perdita di capelli. Prima di quel giorno avevo l'unico gnomefro di tutta Azeroth.\n\n<Gnoarn agita il pugno in aria.>\n\nMaledetti quei maledetti sporchi trogg — maledetti tutti!!\n\nForse non è troppo tardi, $N. Forse possiamo ancora salvarla — la città, intendo! Parla con Ozzie Togglevolt, a Kharanos. Lui e il suo socio Razzle stanno lavorando a una soluzione.", enHash = { "566dc999", "02ee3e56" }, vanilla = true },
        objectives = { it = "Parla con Ozzie Togglevolt, a Kharanos.", enHash = "555b0cfe", vanilla = true },
        reward = { it = "Pensavo che perdere quella chioma straordinaria sarebbe stata la sua fine, e invece è sopravvissuto!\n\nEro proprio accanto a lui quando l'ha colpito la scarica di radiazioni. Quelle deliziose ciocche castane sono cadute a terra a ciuffi! A grappoli! E l'orrore è diventato ancora più grande quando Gnoarn è andato completamente fuori di testa! Oh sì, fuori di testa, dico! Gnoarn si è toccato la testa pelata incredulo, e lo sguardo nei suoi occhi urlava vendetta, $N! Poi ha rivolto la sua rabbia contro i trogg!\n\n<Ozzie rabbrividisce.>", enHash = "5884a01c", vanilla = true },
    },
    [2928] = {
        title = { it = "Gyrodrillmatic Excavationators", enHash = "617762db", vanilla = true },
        text = { it = "È terribile, $N. Non avremo abbastanza pezzi per portare la nostra flotta di gyrodrillmatic excavationator fino a Dun Morogh.\n\nQuel che ci serve sono pezzi di ricambio, $N. E quale posto migliore di Gnomeregan per procurarsi i ricambi dei nostri veicoli? Mi dicono che là dentro bot e mech girano come mandrie al pascolo.\n\nQuel che devi fare è andare a Gnomeregan e fare a pezzi quei robot. Riportami le loro interiora meccaniche. Due dozzine dovrebbero bastare.", enHash = "6da529f0", vanilla = true },
        objectives = { it = "Porta ventiquattro Robo-mechanical Gut a Shoni, a Stormwind.", enHash = "c1188d01", vanilla = true },
        progress = { it = "Se fosse una gara, a quest'ora avresti perso.", enHash = "7a8baead", vanilla = true },
        reward = { it = "Questi andranno benissimo, $N. Un gyrodrillmatic excavationator riparato; ne restano 398.", enHash = "0c9aabf8", vanilla = true },
    },
    [2929] = {
        title = { it = "Il grande tradimento", enHash = "70ed1c07", vanilla = true },
        text = { it = "Mi fidavo di Thermaplugg, $R. Non avrei mai immaginato che avrebbe tradito me e l'intero popolo gnomico. E per cosa? Potere? Ricchezza? Tutte cose che col tempo avrebbe avuto. Ora siamo stati cacciati da casa nostra e quel pazzo comanda. Il re del nulla....\n\nRiprenderemo Gnomeregan, $N. Non ci fermeremo finché la città non tornerà sotto il nostro controllo. Se vuoi unirti alla nostra lotta, ti chiedo un compito semplice: uccidi il traditore. Distruggi Mekgineer Thermaplugg.", enHash = "93780a44", vanilla = true },
        objectives = { it = "Va' a Gnomeregan e uccidi Mekgineer Thermaplugg. Torna da High Tinker Mekkatorque a lavoro finito.", enHash = "66b964a7", vanilla = true },
        progress = { it = "Il compito è finito? Ha implorato clemenza? Pietà??", enHash = "7b83b714", vanilla = true },
        reward = { it = "Mi piace pensare che l'ultima cosa che gli è passata per la testa mentre crollava a terra sia stato il tuo piede, $R. Con Thermaplugg morto, i nostri piani per riprendere Gnomeregan sono un passo più vicini a diventare realtà.", enHash = "b2cce978", vanilla = true },
    },
    [2930] = {
        title = { it = "Recupero dati", enHash = "a992eac9", vanilla = true },
        text = { it = "Quando siamo fuggiti da Gnomeregan ci siamo lasciati dietro tantissimi dati! Dati di importanza vitale!\n\nMi servono i dati su una Prismatic Punch Card, da un terminale ad alta sicurezza Matrix Punchograph 3005-D, in fondo a Gnomeregan. Devi accedere a quel terminale, ma per farlo ti serve prima l'autorizzazione... e per averla devi accedere ai terminali a sicurezza più bassa: i modelli -A, -B e -C. E per fare QUELLO ti servono le punch card di sicurezza, a cominciare da quella bianca... e le punch card le abbiamo lasciate tutte in città.\n\nÈ una catastrofe! Puoi aiutarci?", enHash = "022b1ded", vanilla = true },
        objectives = { it = "Porta una Prismatic Punch Card a Master Mechanic Castpipe, a Ironforge.", enHash = "2cdbe29b", vanilla = true },
        progress = { it = "Ce l'hai la Prismatic Punch Card??", enHash = "7c6202e5", vanilla = true },
        reward = { it = "Ce l'hai fatta! Hai trovato la Prismatic Punch Card e recuperato i dati perduti! Dati di importanza vitale, critica, incommensurabile, senza i quali non saremmo potuti andare avanti un altro istante!\n\nIl servizio che hai reso agli gnomi sarà ricordato a lungo, $N.", enHash = "44cfba8f", vanilla = true },
    },
    [2931] = {
        title = { it = "L'incarico di Castpipe", enHash = "fb7cb1ec", vanilla = true },
        text = { it = "Master Mechanic Castpipe, a Ironforge, ha bisogno di avventurieri! Sta organizzando squadre per rientrare a Gnomeregan in una missione di recupero dati della massima segretezza e importanza.\n\nCastpipe non sarà un membro dell'Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences come me, ma resta uno gnomo in gamba: quindi, se lui pensa che sia importante, per i miei calcoli c'è una probabilità dell'ottantaquattro per cento che lo sia davvero!\n\nSono buone probabilità!", enHash = "b6a0c114", vanilla = true },
        objectives = { it = "Parla con Master Mechanic Castpipe, a Ironforge.", enHash = "cba2e881", vanilla = true },
        reward = { it = "Sto organizzando missioni di estrazione dati dentro Gnomeregan. Se sei qui per questo, ascolta bene!", enHash = "d193eba4", vanilla = true },
    },
    [2936] = {
        title = { it = "La dea ragno", enHash = "764f8fd0", vanilla = true },
        text = { it = "I Witherbark adorano una dea ragno, e da lei raccolgono il loro veleno più potente. Quindi, se vuoi il veleno, devi evocare la loro dea!\n\nPer farlo devi conoscere il suo vero nome, e quel nome è su una tavoletta sepolta a Tanaris, nella città troll di Zul'Farrak, in una tomba sorvegliata da Theka the Martyr.\n\nSconfiggi Theka, trova la sua tavoletta e leggila per scoprire il nome della dea ragno. Quando lo conoscerai, torna da me.", enHash = "98539e7e", vanilla = true },
        objectives = { it = "Leggi la Tablet of Theka per scoprire il nome della dea ragno dei Witherbark, poi torna da Master Gadrin.", enHash = "488d2e81", vanilla = true },
        progress = { it = "Conosci il nome della dea ragno?", enHash = "5822540f", vanilla = true },
        reward = { it = "Ah, Elortha no Shadra... pronuncia questo nome solo a bassa voce, perché nei regni dello spirito ha un gran peso.\n\nLo metterò per iscritto e creerò per te un incantesimo di evocazione...", enHash = "2cc85542", vanilla = true },
    },
    [2945] = {
        title = { it = "Grime-Encrusted Ring", enHash = "4865674a", vanilla = true },
        text = { it = "Dal cadavere di uno dei nani Dark Iron hai tirato fuori quello che sembra un anello. È difficile però dire che tipo di anello sia: terra e residui induriti lo ricoprono del tutto e rendono impossibile indossarlo. Ti pare di intravedere il lieve luccichio di un metallo prezioso e forse perfino il bagliore di una gemma sotto i residui.\n\nSe vuoi servirti di questo anello, dovrai trovare qualcosa che gli tolga di dosso i residui induriti.", enHash = "6cd0a4f1", vanilla = true },
        objectives = { it = "Trova un modo per togliere la sporcizia dal Grime-Encrusted Ring.", enHash = "87902fad", vanilla = true },
        progress = { it = "L'aggeggio gnomico davanti a te porta una targa che lo chiama \"The Sparklematic 5200\". Dalle istruzioni sotto la targa si capisce che la macchina serve a strofinare via lo sporco che un oggetto può avere. Ha una fessura per le monete, e accetta tre monete d'argento per avviare il processo una volta che l'oggetto è dentro.\n\nPare proprio che il Grime-Encrusted Ring che hai trovato prima sia la cosa giusta da provare in questa macchina!", enHash = "8fd358c2", vanilla = true },
        reward = { it = "Metti l'anello dentro lo Sparklematic 5200 e infili una moneta d'argento nella fessura.\n\nDalla macchina escono stridori dolorosi mentre comincia a sobbalzare violentemente. Si può solo immaginare cosa stia succedendo all'anello là dentro...\n\nLa macchina si ferma di colpo e annuncia la fine con un semplice \"Ding!\". Il ricettacolo si apre e rivela una scatoletta avvolta con cura in un nastro rosso. Pare che lo Sparklematic 5200 faccia anche i pacchetti regalo!", enHash = "67c24f14", vanilla = true },
    },
    [2947] = {
        title = { it = "Il ritorno dell'anello", enHash = "557d4db8", vanilla = true },
        text = { it = "Aprendo la scatola prodotta dallo Sparklematic 5200 trovi quel che sospettavi: un anello lucente! Indossandolo, senti un potere magico scorrerti nel corpo.\n\nDentro il cerchio c'è un'impronta piccola ma riconoscibile del sigillo di Ironforge. Accanto sono incise tre piccole iniziali: \"TdK\". Potrebbero essere le iniziali del precedente proprietario, oppure quelle di chi ha forgiato l'anello. Tenere l'anello... o restituirlo a questa persona. Che dilemma...", enHash = "5b9382cf", vanilla = true },
        objectives = { it = "Puoi tenere l'anello, oppure cercare la persona a cui si devono l'impronta e le incisioni all'interno del cerchio.", enHash = "79aba66c", vanilla = true },
        progress = { it = "Ehi, calma, socio: sono un uomo d'affari molto importante! Sono sicuro che il corriere è solo in ritardo con la consegna dell'affitto... aspetta... tu non sei $Gil mio padrone:la mia padrona; di casa.\n\nMa certo che no, che sciocco! Sei $Gvenuto:venuta; da me perché cerchi il miglior gioielliere di tutta Ironforge, uno che NON fa oggetti MALEDETTI! Sì!\n\nEhm... di cosa hai bisogno?", enHash = "af098e65", vanilla = true },
        reward = { it = "Un anello, dici? Vediamo... sì, perbacco, quell'anello l'ho fatto io.\n\nPrima che Gnomeregan saltasse avevo una botteguccia là. Forse è uno di quelli che mi sono lasciato dietro quando sono scappato a gambe levate: è un disegno semplice, e ne ho fatti parecchi così. Magari era di qualcuno che non ce l'ha fatta a uscire.\n\nCe l'avevano dei nani Dark Iron? Be', questo aggiunge uno strato di cospirazione ai nove che già girano. Forse le autorità vorrebbero saperlo; con uno come me è fiato sprecato.\n\nOra, torniamo all'anello...", enHash = "c514ef9f", vanilla = true },
    },
    [2948] = {
        title = { it = "Miglioria gnomesca", enHash = "e3f8d884", vanilla = true },
        text = { it = "Senti, $N, quell'anello è tuo, certo... ma te ne posso fare uno migliore! Quel disegno, come ti ho detto, è davvero semplice. Ora sono molto più bravo, e per la modica cifra di trenta monete d'argento te lo rimetto a nuovo! Be', un pochino più di trenta, a dire il vero...\n\nAl momento sono in difficoltà: le mie scorte di materiale sono esaurite. Se mi porti una barra d'argento e un'agata muschiata, aggiungo all'anello un reticolo d'argento e agata che gli darà un po' più di brio!\n\nFidati!", enHash = "f70d7299", vanilla = true },
        objectives = { it = "Porta il Brilliant Gold Ring, un Silver Bar, un Moss Agate e 30 monete d'argento a Talvash del Kissel, a Ironforge.", enHash = "a9eeaa61", vanilla = true },
        progress = { it = "Ce li hai i materiali che mi servono? Non te li chiederei, se non fossi in un periodo sfortunato...", enHash = "4cbc156f", vanilla = true },
        reward = { it = "Ah, proprio quel che mi serviva! Un giorno, quando sarò uscito da questo buco in cui mi trovo ingiustamente, farò per te, anzi, per TUTTI, i ninnoli più belli di tutta Azeroth! Fino ad allora, grazie della comprensione per i reagenti. Di solito per un anello di questa qualità chiedo dieci volte tanto...\n\nA proposito di anelli, ecco quello nuovo!", enHash = "97719907", vanilla = true },
    },
    [2949] = {
        title = { it = "Il ritorno dell'anello", enHash = "557d4db8", vanilla = true },
        text = { it = "Aprendo la scatola prodotta dallo Sparklematic 5200 trovi un anello lucente! Indossandolo, senti un potere magico scorrerti nel corpo.\n\nDentro il cerchio c'è un'impronta piccola ma riconoscibile del sigillo di Orgrimmar. Accanto ci sono delle lettere incise, ma anche dopo la pulizia se ne distinguono solo le prime tre: \"NOG...\"\n\nPotrebbero essere le iniziali del precedente proprietario, oppure quelle di chi ha forgiato l'anello. Tenere l'anello... o trovare \"NOG\": che dilemma...", enHash = "490bd7f5", vanilla = true },
        objectives = { it = "Puoi tenere l'anello, oppure cercare la persona a cui si devono l'impronta e le incisioni all'interno del cerchio.", enHash = "79aba66c", vanilla = true },
        progress = { it = "Uno penserebbe che un modo per battere quegli sporchi gnomettini ce lo trovassimo da soli. Anzi, scommetterei che quel rig ce l'hanno rubato loro, tanto per cominciare! Bah, quegli unti, lerci... ehm, sì? Ti serve qualcosa?", enHash = "35aaea13", vanilla = true },
        reward = { it = "Un anello da Gnomeregan? Vediamo... non è mio, ma è interessante.\n\nLa faccenda di Gnomeregan: non poteva capitare a un gruppo di teste di legno più simpatico. Per anni sono stati una barzelletta, e adesso, quasi da un giorno all'altro, costruiscono rig migliori dei nostri?\n\nCe l'avevano dei nani Dark Iron, l'anello? Questo è ancora più interessante! Sai, magari gli gnomi hanno rubato i loro progetti folli dei golem e li hanno modificati. E quei Dark Iron vorrebbero di sicuro una bella vendetta. Vale di sicuro la pena indagare.\n\nA proposito, quell'anello...", enHash = "307d718a", vanilla = true },
    },
    [2950] = {
        title = { it = "L'anello rifatto da Nogg", enHash = "603c84db", vanilla = true },
        text = { it = "No, no, no: non sto dicendo che all'improvviso l'anello è mio. Di solito non lo faccio, ma le tue informazioni sui Dark Iron sono state molto utili. Te lo miglioro io l'anello, meglio di come avrebbe mai potuto fare chi ha fatto questa cosetta semplice. Probabilmente qualche gnomo...\n\nSe mi porti una barra d'argento, un'agata muschiata e trenta monete d'argento per il disturbo, aggiungo all'anello un reticolo d'argento e agata che rafforzerà la magia che ha dentro. Ti interessa?", enHash = "6a324c24", vanilla = true },
        objectives = { it = "Porta il Brilliant Gold Ring, un Silver Bar, un Moss Agate e 30 monete d'argento a Nogg, a Orgrimmar.", enHash = "a699609a", vanilla = true },
        progress = { it = "Ce li hai i materiali che mi servono? Senza tutto quel che ti ho chiesto non posso migliorare questo lavoro.", enHash = "cd8af127", vanilla = true },
        reward = { it = "Ecco il tuo anello, meglio di prima. Grazie ancora per le informazioni su quei nani Dark Iron. Sembra una buona pista per capire come mai quegli gnomi si siano ritrovati di colpo con un'ispirazione da goblin.", enHash = "6591f666", vanilla = true },
    },
    [2951] = {
        title = { it = "The Sparklematic 5200!", enHash = "bcfe6e77", vanilla = true },
        text = { it = "Questo aggeggio spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice \"The Sparklematic 5200\", e sotto c'è scritto:\n\n\"Sporcizia e residui rovinano i tuoi gioiellini? Lo Sparklematic 5200 rimette lo splendore nello splendi-fantastico! Inserisci l'oggetto da pulire e deposita tre monete d'argento nella fessura. Concedi allo Sparklematic 5200 qualche istante di lavoro e voilà! I tuoi oggetti di valore usciranno puliti e splendenti!\"", enHash = "aeab26b8", vanilla = true },
        objectives = { it = "Inserisci un Grime-Encrusted Item nello Sparklematic 5200, e assicurati di avere tre monete d'argento per far partire la macchina.", enHash = "c2b6523f", vanilla = true },
        progress = { it = "Pare che al congegno serva una specie di oggetto incrostato di sporcizia da pulire e tre monete d'argento per mettersi in moto. Se ci sono tutti e due, lo Sparklematic 5200 dovrebbe funzionare...", enHash = "ce3ed7a7", vanilla = true },
        reward = { it = "Inserisci l'oggetto incrostato e tre monete d'argento nello Sparklematic 5200. La macchina si anima in un tentativo frenetico di ripulire dalla sporcizia l'oggetto sconosciuto. Dal cuore della macchina battono rumori forti e violenti di ingranaggi che girano. Il telaio metallico della bestia scricchiola e geme mentre sobbalza da un lato all'altro...", enHash = "9cc4fed2", vanilla = true },
    },
    [2952] = {
        title = { it = "The Sparklematic 5200!", enHash = "bcfe6e77", vanilla = true },
        reward = { it = "Com'è cominciato, così lo Sparklematic 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\", e la bocca della macchina si apre a spirale verso l'alto. Dentro lo Sparklematic 5200 c'è una scatoletta avvolta in un nastrino. Pare che la macchina incarti l'oggetto dopo avergli tolto le incrostazioni. Anche se la macchina non avesse funzionato, almeno adesso l'oggetto è avvolto in una bella scatola.\n\nBe', c'è un modo solo per scoprire se l'ha pulito o no...", enHash = "f478e516", vanilla = true },
    },
    [2953] = {
        title = { it = "Ancora un giro di Sparklematic", enHash = "4ba20567", vanilla = true },
        progress = { it = "Lo Sparklematic 5200 è vuoto, in attesa di un oggetto incrostato da pulire e di tre monete d'argento per partire!", enHash = "4b6ea245", vanilla = true },
        reward = { it = "Lo Sparklematic 5200 si anima, sobbalzando avanti e indietro. Dentro, la sporcizia indifesa che incrostava l'oggetto viene polverizzata dal detergente gnomico della macchina.\n\nLo Sparklematic 5200 si ferma, annunciato da un familiare \"ding!\". Il ricettacolo della macchina si apre a spirale e rivela una scatola avvolta con cura.", enHash = "12dbe743", vanilla = true },
    },
    [2962] = {
        title = { it = "L'unica cura è altro bagliore verde", enHash = "559dd1f5", vanilla = true },
        text = { it = "Il tuo campione non solo era insufficiente per quantità: era anche impuro.\n\nQuel che ci serve è altro bagliore verde. È chiaro che i trogg non sono irradiati abbastanza per i nostri scopi. Dovrai entrare a Gnomeregan e riportare della ricaduta radioattiva, presa direttamente alla fonte. Parlo degli slime, dei lurker e degli horror irradiati. Attenzione: contenere questo tipo di ricaduta è difficile. Potresti dover fare diversi tentativi con la fiala prima di recuperare un campione adatto.", enHash = "ea8145b9", vanilla = true },
        objectives = { it = "Va' a Gnomeregan e riporta un High Potency Radioactive Fallout. Attenzione: la ricaduta è instabile e decade piuttosto in fretta.\n\nA lavoro finito Ozzie vorrà anche la tua Heavy Leaden Collection Phial.", enHash = "45c4488f", vanilla = true },
        progress = { it = "Hrm, non stai brillando. È un buon segno.", enHash = "d2b4054e", vanilla = true },
        reward = { it = "<Ozzie ti esamina.> Notevole, hai ancora tutti gli arti al loro posto. Ora vediamo cosa sa fare questa roba!", enHash = "cfe934c2", vanilla = true },
    },
    [2965] = {
        title = { it = "Presagi di Uldum", enHash = "f594d1d3", vanilla = true },
        text = { it = "Ah, $N, è una fortuna che tu sia $Gvenuto:venuta; di nuovo da me. Le tue scoperte agli scavi di Uldaman hanno di certo dato a noi saggi molto di cui discutere. Ne stavo parlando proprio con una dei druidi, Nara Wildmane, quando mi è venuto in mente che le sue passate esperienze di avventuriera potrebbero avere grande importanza per il prossimo passo da compiere.\n\nVorrei che tu parlassi con lei dei suoi viaggi nella Valley of the Watchers, nel deserto di Tanaris. Ti aspetta sull'Elder Rise.", enHash = "f230a3e2", vanilla = true },
        objectives = { it = "Parla con Nara Wildmane, sull'Elder Rise di Thunder Bluff.", enHash = "bd716bd0", vanilla = true },
        reward = { it = "Nel cuore del deserto di Tanaris c'è un luogo chiamato Valley of the Watchers. I dischi che hai recuperato... i loro glifi tradotti parlano di un luogo chiamato Uldum. Quasi tutti pensano che sia un mito.\n\nIo so che non è così; Uldum esiste. Ci sono stata. Be'... fuori, almeno.\n\nIl punto è questo, $N: pensiamo che ci sia un legame tra i dischi e Uldum, e vogliamo che tu ci vada.", enHash = "e4d3f44a", vanilla = true },
    },
    [2966] = {
        title = { it = "Vedere cosa succede", enHash = "8aba7206", vanilla = true },
        text = { it = "Sage Truthseeker e io vorremmo che portassi i dischi in miniatura che hai trovato alle porte sigillate di Uldum. Non... non siamo sicuri di cosa succederà quando lo farai.\n\nSembra rischioso, certo, lo riconosciamo. Ma potrebbe anche non succedere niente. Forse dovrai usare i dischi su qualcosa. Forse le porte si aprono quando hai i dischi con te. Sii $Gdisposto:disposta; a provare qualsiasi cosa, e $Gpronto:pronta; a qualsiasi evenienza.\n\nScopri quello che puoi, poi torna da me. Avremo molto di cui parlare.", enHash = "9f89c365", vanilla = true },
        objectives = { it = "Porta i Miniature Platinum Discs alle porte di Uldum, a Tanaris, e cerca indizi sul legame tra le due cose.", enHash = "72f54fc0", vanilla = true },
        progress = { it = "Questo piedistallo dall'aspetto familiare spunta dalla sabbia rovente. Forse la sua presenza qui ha un significato...", enHash = "b66d54a3", vanilla = true },
        reward = { it = "Quando tocchi il piedistallo, i dischi in miniatura di Uldaman vibrano e brillano nel tuo zaino. Un formicolio familiare ti attraversa le mani, mentre l'immagine di un altro Stone Watcher prende vita davanti alle porte di Uldum.\n\n\"Saluti. Sono un guardiano dell'ingresso. Ai dischi usati per l'accesso mancano i dischi d'ingresso corretti, le Plates of Uldum. Si prega di integrare queste piastre nella struttura dei dischi e di ripetere la sequenza di accesso. Grazie.\"", enHash = "2438d7aa", vanilla = true },
    },
    [2967] = {
        title = { it = "Ritorno a Thunder Bluff", enHash = "21c8293a", vanilla = true },
        text = { it = "Accedi di nuovo al piedistallo; i dischi di platino ricompaiono all'improvviso nel tuo zaino.\n\nOra che hai appreso ciò che sa il guardiano di pietra e i dischi sono tornati in tuo possesso, è giunto il momento di tornare a Thunder Bluff e informare Nara Wildmane della tua scoperta.", enHash = "4dfaaa48", vanilla = true },
        objectives = { it = "Parla con Nara Wildmane, a Thunder Bluff.", enHash = "bcc9e2e1", vanilla = true },
        progress = { it = "$GBentornato:Bentornata;, $N. Sei $Griuscito:riuscita; a usare i dischi a tuo vantaggio, o è stato tutto inutile?", enHash = "ee79651f", vanilla = true },
        reward = { it = "Ti mancavano dei dischi? È interessante: sembra che i Discs of Norgannon siano solo una parte del set completo — come le chiavi di un mazzo, per così dire.\n\nSe riusciamo a trovare le Plates of Uldum, potremmo davvero accedere al complesso di Uldum. Non so se esserne entusiasta o terrorizzata.\n\nPotremmo dover rischiare tutto per fare in modo che i segreti custoditi dalla terra, che ci distruggerebbero tutti, restino proprio questo — segreti.", enHash = "45177f37", vanilla = true },
    },
    [2968] = {
        title = { it = "Un compito futuro", enHash = "344edc83", vanilla = true },
        text = { it = "Be', $N... sembra che siamo arrivati a un punto morto, purtroppo. Sappiamo cosa ci serve — le Plates of Uldum — ma non abbiamo idea di dove possano essere. Faremo delle ricerche, e poi elaboreremo un solido piano d'attacco. Ho un paio di idee su dove cominciare a cercare; spero proprio che presto ti chiederemo di unirti di nuovo ai nostri sforzi per scoprire la verità.\n\nSage Truthseeker deve esserne informato, $N; di certo vorrà anche ringraziarti di persona per aver risposto ancora una volta alla chiamata.", enHash = "f0843527", vanilla = true },
        objectives = { it = "Parla con Sage Truthseeker, a Thunder Bluff.", enHash = "c3f17242", vanilla = true },
        reward = { it = "Siamo tutti d'accordo, allora — la cosa migliore è aspettare finché non riusciremo a restringere le zone in cui potrebbero essere nascoste queste piastre. Ci hai portati fin qui, $N, e spero che sarai tu a tornare sul campo per affrontare i segreti di Uldum.\n\nNel frattempo permettimi di darti questo compenso; dovrebbe coprire le spese che hai sostenuto per aiutarci, più un piccolo extra. Torna presto a trovarci... Uldum chiama tutti noi, giovane.", enHash = "50a7dfe9", vanilla = true },
    },
    [2973] = {
        title = { it = "Una nuova lucentezza per il mantello", enHash = "8f1cc4b6", vanilla = true },
        text = { it = "$GBen trovato:Ben trovata;, $C. Sono venuto in Feralas con i miei compagni, per una missione per i nostri superiori di Orgrimmar.\n\nLa mia compagna di vita, Korrin, adora i vestiti nuovi, quindi voglio farle un nuovo mantello adornato con le ali diafane dei draghi fatati. Potresti aiutarmi? Gli Sprite Darter con le splendide ali che voglio si trovano a ovest di Camp Mojache.", enHash = "9ea5ff0f", vanilla = true },
        objectives = { it = "Porta 10 Iridescent Sprite Darter Wing a Krueg Skullsplitter, a Camp Mojache.", enHash = "40fefc38", vanilla = true },
        progress = { it = "Gli Sprite Darter possono essere bestiole pericolose, se provocati. Sta' $Gattento:attenta; quando hai a che fare con loro, $C. E fa' ancora più attenzione agli elfi della notte della zona. Quegli sciocchi fastidiosi tendono a rintanarsi anche loro nelle foreste.\n\nQuando avrai abbastanza ali, fammelo sapere: ti ricompenserò bene, puoi starne certo!", enHash = "9c2d0ab2", vanilla = true },
        reward = { it = "Magnifico, $C! Queste andranno benissimo. Ce n'è abbastanza per fare un mantello per Korrin, e forse anche di più! Grazie.\n\nSpero che il viaggio non sia stato troppo pericoloso? La zona di Feralas non è nota per essere clemente, ma è chiaro che te la sei $Gcavato:cavata; bene.\n\nGrazie ancora, $C.", enHash = "61952e37", vanilla = true },
    },
    [2974] = {
        title = { it = "Una scoperta cupa", enHash = "d978f7be", vanilla = true },
        text = { it = "Cosa?! Hai incontrato dei tauren da queste parti? Stai scherzando! Che aspetto avevano?!\n\nIl clan Grimtotem! Ne hai trovati alcuni? Belgrom, uno dei nostri superiori, ha un interesse per quelli come loro... ha perfino messo una taglia su di loro.\n\nDevi tornarci, $C. Torna e portami le loro corna... a mucchi, se puoi. I Grimtotem non vanno presi alla leggera né sottovalutati. Torna e uccidili; che i fiumi di Feralas scorrano rossi del loro sangue oscuro.", enHash = "fd2458cc", vanilla = true },
        objectives = { it = "Porta 20 Grimtotem Horn a Krueg Skullsplitter, a Camp Mojache.", enHash = "ffa5e84a", vanilla = true },
        progress = { it = "Prendi sul serio le mie parole, $C: il clan Grimtotem è malvagio. Se hai scoperto dove si trovano, tocca a te tornare e sferrare il primo colpo contro il loro clan... prima che possano venire nelle nostre terre e radere al suolo i nostri villaggi, o saccheggiare le nostre terre.", enHash = "faddd467", vanilla = true },
        reward = { it = "Sono buone corna, $C. Ben fatto. Le prendo io, e mi assicurerò di dirlo a Belgrom appena torneremo a Orgrimmar. Mi hai aiutato due volte, ormai, e per questo hai il mio riconoscimento. Forse in futuro potrò aiutarti io! Buona fortuna.", enHash = "91da70c9", vanilla = true },
    },
    [2975] = {
        title = { it = "Gli ogre di Feralas", enHash = "9c81e58e", vanilla = true },
        text = { it = "Gli effetti della tribù dei Gordunni Ogre non possono passare inosservati da queste parti. Guardati intorno, $N: la loro sola presenza sfregia questa terra. Dobbiamo respingerli prima che si espandano ancora di più in Feralas.\n\nSegui il fiume verso nord e troverai il loro avamposto. Riduci il loro numero, $N. Dobbiamo mostrare loro che qui la loro specie non è gradita.", enHash = "a43f36a2", vanilla = true },
        objectives = { it = "Rok Orhan, a Camp Mojache, vuole che tu uccida 10 Gordunni Ogre, 10 Gordunni Ogre Mage e 5 Gordunni Brute.", enHash = "7e7a321b", vanilla = true },
        progress = { it = "Muoviti in fretta, $N. O il compito che ti ho chiesto è troppo difficile?", enHash = "5873f628", vanilla = true },
        reward = { it = "Eccellente, $N. Col tempo, la terra guarirà. Non dobbiamo arrenderci.", enHash = "f63221ae", vanilla = true },
    },
    [2976] = {
        title = { it = "Una scoperta cupa", enHash = "d978f7be", vanilla = true },
        text = { it = "Cosa?!\n\nAh, allora ho parlato di una taglia, vero? Be', così imparo ad aprire bocca, no?\n\nIl lavoro l'hai fatto tu, quindi immagino sia giusto che tu ne raccolga la ricompensa più grande. Prendi le corna: le farò mettere in una cassa per te. Trova Belgrom Rockmaul nella Valley of Honor: vorrà sapere cosa hai visto, e ti ricompenserà per il tuo duro lavoro.\n\nStammi bene, $C, e grazie ancora per tutto quello che hai fatto.", enHash = "e07fd7a2", vanilla = true },
        objectives = { it = "Porta la Crate of Grimtotem Horns a Belgrom Rockmaul, a Orgrimmar.", enHash = "c7ba5b93", vanilla = true },
        progress = { it = "Fa' presto, $C, oggi ho molto da fare.", enHash = "28398a38", vanilla = true },
        reward = { it = "I Grimtotem!? Interessante. Dici di averli incontrati mentre cacciavi in Feralas? Davvero?\n\nI miei pari vorranno sentire le tue notizie, $C. Raccontami di più, e intanto ti conto le monete.\n\nE prima che tu vada, sappi che ti ringrazio per le informazioni che mi hai dato oggi.", enHash = "d3637ecc", vanilla = true },
    },
    [2978] = {
        title = { it = "La Gordunni Scroll", enHash = "1b6cdb50", vanilla = true },
        text = { it = "Raccogliendo la pergamena sudicia, noti che sembra raffigurare una specie di incontro o di cerimonia. A Rok Orhan interesserebbe questa pergamena, e cosa potrebbe significare per i Gordunni.", enHash = "22fa63f9", vanilla = true },
        objectives = { it = "Porta la Gordunni Scroll a Rok Orhan, a Camp Mojache.", enHash = "52c06872", vanilla = true },
        progress = { it = "Cos'è questo?", enHash = "3f86b0c7", vanilla = true },
        reward = { it = "Questa pergamena... L'hai trovata nel Gordunni Outpost?", enHash = "989d1e1b", vanilla = true },
    },
    [2980] = {
        title = { it = "Gli ogre di Feralas", enHash = "9c81e58e", vanilla = true },
        text = { it = "Ora che hai dimostrato di essere $Gun vero combattente:una vera combattente;, confido che tu abbia il coraggio di continuare con il compito da svolgere.\n\nVa' nella High Wilderness, a sud-ovest di qui. Lì ci sono alcune strutture abbandonate e distrutte, su terre che un tempo appartenevano agli elfi della notte. Cerca queste rovine, e quando vedrai gli alberi avvizziti e il terreno profanato, troverai i Gordunni. Respingili.\n\nQuesti ogre sono molto più forti di quelli che hai affrontato prima, $N. Sta' $Gattento:attenta;.", enHash = "1a2c3fef", vanilla = true },
        objectives = { it = "Rok Orhan, a Camp Mojache, vuole che tu uccida 10 Gordunni Shaman, 10 Gordunni Warlock e 5 Gordunni Mauler.", enHash = "42e7e8b0", vanilla = true },
        progress = { it = "Hai trovato le rovine, $N?", enHash = "e6193f5c", vanilla = true },
        reward = { it = "Hai dimostrato di essere $Gun alleato fidato e affidabile:un'alleata fidata e affidabile;, $N.", enHash = "4ee3e325", vanilla = true },
    },
    [2982] = {
        title = { it = "La High Wilderness", enHash = "7843245d", vanilla = true },
        text = { it = "Anche se è pericoloso, io e Troyas stiamo esplorando le rovine che coprono le foreste di Feralas.\n\nUltimamente, però, Troyas va da solo nella High Wilderness, e sono davvero in pensiero per lui. I Gordunni Ogre hanno preso possesso di quella zona, e non vedono di buon occhio chiunque entri nel loro territorio.\n\nSperavo che fossi $Gdisposto:disposta; a raggiungere le rovine a sud-est e a sgombrare un po' di ogre. Rendi quel posto un po' più sicuro per il mio Troyas, e te ne sarò estremamente grata.", enHash = "670bb6f9", vanilla = true },
        objectives = { it = "Angelas Moonbreeze vuole che tu uccida 8 Gordunni Warlock, 8 Gordunni Shaman e 8 Gordunni Brute.", enHash = "d0a6dd01", vanilla = true },
        progress = { it = "Fa' attenzione con i Gordunni, $N. La loro magia sembra devastare la terra stessa su cui si trovano.", enHash = "e44b4013", vanilla = true },
        reward = { it = "Ti sono molto grata per aver fatto questo per me.\n\nOra, ti prego, non dire una parola a Troyas di tutto questo...", enHash = "e88bb861", vanilla = true },
    },
    [2983] = {
        title = { it = "Il richiamo del fuoco", enHash = "9c2fbf1d", vanilla = true },
        text = { it = "È passato un po' di tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora sei $Gstato:stata; paziente nei tuoi studi, ma è ora che tu conosca poteri più grandi... è ora che tu conosca il vero potere. L'elemento del fuoco è tuo, se sei $Gdisposto:disposta; a pagarne il prezzo.\n\nCerca Kranal Fiss nelle Barrens. Vive in una piccola dimora a nord del Crossroads, ma fai attenzione: se arrivi a quelle maledette terre degli elfi della notte, sei $Gandato:andata; fin troppo lontano.", enHash = "8eaec81b", vanilla = true },
        objectives = { it = "Trova Kranal Fiss, nelle Barrens.", enHash = "8aab5a8a", vanilla = true },
        reward = { it = "Hmmm, ti ha mandato Swart, vero?\n\nBe', di Swart ci si è sempre potuti fidare, quindi vuol dire che sei $Gpronto:pronta; a prendere la prossima sapta — la sapta del fuoco.\n\nLo vedo già nei tuoi occhi: l'ardore, il desiderio. Hai assaggiato il potere, e ora sei $Gpronto:pronta; per averne di più. Pazienza, $N. Ricorda ciò che ti ha insegnato la terra. Il potere e la distruzione verranno facilmente, ma devi comunque sapere quando trattenere la mano.", enHash = "a02e6023", vanilla = true },
    },
    [2984] = {
        title = { it = "Il richiamo del fuoco", enHash = "9c2fbf1d", vanilla = true },
        text = { it = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai dimostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la distruzione... e il caos. Comprendere l'elemento del fuoco è alla tua portata, se sei $Gdisposto:disposta; a pagarne il prezzo.\n\nCerca Kranal Fiss nelle Barrens. Vive in una piccola dimora a nord del Crossroads, ma fai attenzione: se arrivi alle terre degli elfi della notte, sei $Gandato:andata; troppo lontano.", enHash = "768b7404", vanilla = true },
        objectives = { it = "Trova Kranal Fiss, nelle Barrens.", enHash = "8aab5a8a", vanilla = true },
        reward = { it = "Hmmm, ti ha mandato Narm, vero?\n\nBe', di Narm ci si è sempre potuti fidare, quindi vuol dire che sei $Gpronto:pronta; a prendere la prossima sapta — la sapta del fuoco.\n\nLo vedo già nei tuoi occhi: l'ardore, il desiderio. Hai assaggiato il potere, e ora sei $Gpronto:pronta; per averne di più. Pazienza, $N. Ricorda ciò che ti ha insegnato la terra. Il potere e la distruzione verranno facilmente, ma devi comunque sapere quando trattenere la mano.", enHash = "766eec79", vanilla = true },
    },
    [2985] = {
        title = { it = "Il richiamo dell'acqua", enHash = "eab41910", vanilla = true },
        text = { it = "Mi sembri $Gpronto:pronta; per la tua prossima prova, $N. Sei $Gstato:stata; paziente nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.\n\nCerca Islen Waterseer nelle Barrens. Si trova lungo la costa orientale, a sud del Southfury River e di Ratchet. La troverai lì, alla sua capanna da pesca. Buona fortuna, $N.", enHash = "cefcebf8", vanilla = true },
        objectives = { it = "Trova Islen Waterseer, nelle Barrens.", enHash = "6d0a2807", vanilla = true },
        reward = { it = "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già riscaldato dal fuoco — direi che è ora che tu conosca la purezza dell'acqua.\n\nLa tua strada ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più avanti. Ma il primo passo spetta a te.", enHash = "b02d93ed", vanilla = true },
    },
    [2986] = {
        title = { it = "Il richiamo dell'acqua", enHash = "eab41910", vanilla = true },
        text = { it = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai dimostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.\n\nCerca Islen Waterseer nelle Barrens. Si trova lungo la costa orientale, a sud del Southfury River e di Ratchet. La troverai lì, alla sua capanna da pesca. Buona fortuna, $N.", enHash = "ad11a582", vanilla = true },
        objectives = { it = "Trova Islen Waterseer, nelle Barrens.", enHash = "6d0a2807", vanilla = true },
        reward = { it = "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già riscaldato dal fuoco — direi che è ora che tu conosca la purezza dell'acqua.\n\nLa tua strada ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più avanti. Ma il primo passo spetta a te.", enHash = "b02d93ed", vanilla = true },
    },
    [2987] = {
        title = { it = "Gordunni Cobalt", enHash = "ef0876a5", vanilla = true },
        text = { it = "Sono appena arrivato qui in Feralas, e ho sentito che i Gordunni Ogre che abitano queste terre selvagge hanno dei minerali interessanti. Chissà cosa combinano, ma di sicuro sono molto gelosi di quella roba! Non la lasciano in giro, no: la seppelliscono, per impedire a gente come me di metterci le mani sopra.\n\nSe ti va, ti darò la mia pala. Va' al Gordunni Outpost, a nord di qui, e dissotterrami un po' di Gordunni Cobalt. Cerca il bagliore blu, poi comincia a scavare!", enHash = "2ad569a2", vanilla = true },
        objectives = { it = "Orwin Gizzmick, a Camp Mojache, vuole 12 campioni di Gordunni Cobalt.", enHash = "7559f5e9", vanilla = true },
        progress = { it = "Vai lassù e comincia a scavare!\n\nHo posti dove andare e gente da vedere: il tempo è denaro!", enHash = "f13981e5", vanilla = true },
        reward = { it = "Perfetto! Li porterò con me nei miei viaggi, $N. Sono sicuro di poter trovare qualcuno che pagherà un bel po' per questo cobalto.\n\nTieni, prendi questo per il disturbo.", enHash = "93e2ed81", vanilla = true },
    },
    [2991] = {
        title = { it = "Nekrum's Medallion", enHash = "68162515", vanilla = true },
        text = { it = "Scoprirò dov'è il tuo grifone, ma prima devi fare qualcosa per me. A Zul'Farrak c'è un troll, Nekrum Gutchewer, che possiede un medaglione che vorrei tanto studiare. Portami quel medaglione e userò i miei poteri per trovare Sharpbeak.\n\nZul'Farrak è oltre l'oceano, a ovest, nel deserto di Tanaris.", enHash = "f8d8219f", vanilla = true },
        objectives = { it = "Porta Nekrum's Medallion a Thadius Grimshade, nelle Blasted Lands.", enHash = "bd9ebddf", vanilla = true },
        progress = { it = "Hai Nekrum's Medallion, $N? Dentro ci sono poteri nascosti che sono ansioso di scoprire.", enHash = "a470ec22", vanilla = true },
        reward = { it = "Ah, il medaglione di Nekrum. Si dice che abbia dato al troll una vita innaturalmente lunga, ma a caro prezzo. Spero di scoprire un modo per sfruttare il potere del medaglione evitando i suoi... sgradevoli effetti collaterali.\n\nMi hai reso un servizio, $N. Ora manterrò la mia parte del patto.", enHash = "bcbf1482", vanilla = true },
    },
    [2996] = {
        title = { it = "In cerca di Strahad", enHash = "07e01085", vanilla = true },
        text = { it = "Ti ho insegnato delle abilità in passato, ma è giunto il momento che sia un altro a istruirti. Si trova a Ratchet, e il suo nome è Strahad. È umano, ma non lasciarti ingannare e non pensare che sia debole. È potente, anche se può sembrare piccolo. Può insegnarti evocazioni più potenti: credo che tu sia $Gpronto:pronta;. Va' da lui ora. Si trova a Ratchet... sopra la città portuale, vicino alla sua torre.", enHash = "a39e88b5", vanilla = true },
        objectives = { it = "Parla con Strahad Farsan, a Ratchet.", enHash = "63deeb35", vanilla = true },
        reward = { it = "Una giornata piena di movimento a Ratchet, vero? Quanto mi piace osservare la fatica di una città portuale. Tanto mistero, tanta avventura... tanta ignoranza.\n\nÈ odio quello che vedo nei tuoi occhi, $N? Bene, lo metteremo a buon frutto.", enHash = "0e89635b", vanilla = true },
    },
    [2997] = {
        title = { it = "Tome of Divinity", enHash = "ea461054", vanilla = true },
        text = { it = "Salve, $N. So che sei $Gimpegnato:impegnata; ad aiutare la gente di Dun Morogh, ma quando hai tempo dovresti salire fino a Ironforge per parlare con una delle figure più rispettate della nostra gente: Tiza Battleforge. È da lei che vanno i paladini più giovani quando è il momento di imparare di più sulla Luce e su ciò che ci si aspetta da te.\n\nLa trovi al piano di sopra, nell'Hall of Mysteries. Se non ci sei mai $Gstato:stata;, è nel Mystic Ward. Buona fortuna, $N.", enHash = "e1f5d0d7", vanilla = true },
        objectives = { it = "Parla con Tiza Battleforge, a Ironforge.", enHash = "4c136c4c", vanilla = true },
        reward = { it = "$GBen trovato:Ben trovata;, $N. Spero che la Luce ti mostri la vera via e ti protegga dal male.", enHash = "ae2e4d8c", vanilla = true },
    },
    [2998] = {
        title = { it = "Tome of Divinity", enHash = "ea461054", vanilla = true },
        text = { it = "Salve, $Gfratello:sorella;. Duthorian Rall, uno dei nostri paladini più influenti, parlava di te di recente. L'ho sentito dire che era ora di metterti un po' alla prova... insieme a parecchi complimenti su quanto bene te la sei cavata finora.\n\nSe fossi in te, andrei a Stormwind a parlargli quando hai tempo. Di sicuro è nella Cathedral of Light — è lì che passa la maggior parte del tempo.", enHash = { "5ba58f57", "b668d297" }, vanilla = true },
        objectives = { it = "Parla con Duthorian Rall, a Stormwind.", enHash = "b20f83f0", vanilla = true },
        reward = { it = "È bello qui a Stormwind, non trovi?\n\nIn realtà non avresti potuto scegliere un momento migliore, $N.", enHash = "5eb54f05", vanilla = true },
    },
    [2999] = {
        title = { it = "Tome of Divinity", enHash = "ea461054", vanilla = true },
        text = { it = "Salve, $N. So che sei $Gimpegnato:impegnata; ad aiutare la gente di Dun Morogh, ma quando hai tempo dovresti salire al piano di sopra e parlare con una delle figure più rispettate della nostra gente: Tiza Battleforge. È da lei che vanno i paladini più giovani quando è il momento di imparare di più sulla Luce e su ciò che ci si aspetta da te.", enHash = "8cace1d5", vanilla = true },
        objectives = { it = "Parla con Tiza Battleforge, a Ironforge.", enHash = "afdf9822", vanilla = true },
        reward = { it = "$GBen trovato:Ben trovata;, $N. Spero che la Luce ti mostri la vera via e ti protegga dal male.", enHash = "ae2e4d8c", vanilla = true },
    },
    [3000] = {
        title = { it = "Tome of Divinity", enHash = "ea461054", vanilla = true },
        text = { it = "Salve, $N. So che sei $Gimpegnato:impegnata; ad aiutare la gente di Azeroth, ma quando hai tempo dovresti tornare a Ironforge e parlare con una dei paladini più rispettati della tua terra: Tiza Battleforge. È da lei che vanno i giovani paladini nani quando è il momento di imparare di più sulla Luce e su ciò che ci si aspetta da tutti noi.\n\nLa trovi al piano di sopra, nell'Hall of Mysteries, che si trova nel Mystic Ward.", enHash = "38be5984", vanilla = true },
        objectives = { it = "Parla con Tiza Battleforge, a Ironforge.", enHash = "4c136c4c", vanilla = true },
        reward = { it = "Ti saluto, e ti do il benvenuto, $N.", enHash = "1406b020", vanilla = true },
    },
    [3001] = {
        title = { it = "In cerca di Strahad", enHash = "07e01085", vanilla = true },
        text = { it = "Ti ho insegnato delle abilità in passato, ma è giunto il momento che sia un altro a istruirti. Si trova a Ratchet, e il suo nome è Strahad. È umano, ma non lasciarti ingannare e non pensare che sia debole, né che sia tuo nemico... almeno per ora. È potente e va rispettato. Può insegnarti evocazioni più grandi, evocazioni per cui credo tu sia $Gpronto:pronta;. Va' da lui ora.\n\nLo trovi a Ratchet... sopra la città portuale, vicino alla torre.", enHash = "74d2fc12", vanilla = true },
        objectives = { it = "Trova Strahad Farsan, a Ratchet.", enHash = "aa0bf505", vanilla = true },
        reward = { it = "Una giornata piena di movimento a Ratchet, vero? Quanto mi piace osservare la fatica di una città portuale. Tanto mistero, tanta avventura... tanta ignoranza.\n\nÈ odio quello che vedo nei tuoi occhi, $N? Bene, lo metteremo a buon frutto.", enHash = "0e89635b", vanilla = true },
    },
    [3042] = {
        title = { it = "Troll Temper", enHash = "8461ab13", vanilla = true },
        text = { it = "I troll Sandfury di Zul'Farrak ricavano un agente di tempra dalle arenarie, e io posso usarlo per temprare le cose che fabbrico, eccome se posso! È molto apprezzato dagli intenditori, quindi se mi porti una buona scorta di tempra, ti ricompenserò bene.\n\nZul'Farrak è a nord-ovest di Gadgetzan. Buona fortuna.", enHash = "708b2f5f", vanilla = true },
        objectives = { it = "Porta 20 Troll Temper a Trenton Lighthammer, a Gadgetzan.", enHash = "6424ee88", vanilla = true },
        progress = { it = "Mi hai portato la tempra, $N?", enHash = "90a1ea59", vanilla = true },
        reward = { it = "Ah, questa sì che è un'ottima tempra! E quanta! Ci lavorerò per giorni prima di finirla tutta!\n\nGrazie, $N. Ti prego, prendi questo come pagamento.", enHash = "7647add9", vanilla = true },
    },
    [3065] = {
        title = { it = "Simple Tablet", enHash = "832e8894", vanilla = true },
        text = { it = "Ah, mentre eri via è arrivata una pergamena per te, $N.\n\nLeggila quando hai tempo. Se non sbaglio, viene da Frang, l'istruttore di guerrieri. Vuole parlarti quando sei $Gpronto:pronta;. Lo trovi fuori dal Den, al riparo all'ombra.", enHash = "27acdd1a", vanilla = true },
        objectives = { it = "Leggi la Simple Tablet e parla con Frang, nella Valley of Trials.", enHash = "f44af41a", vanilla = true },
        progress = { it = "$GUn altro:Un'altra; $R a rinforzare le file. Per me va bene.\n\nProbabilmente farai fatica a sollevare una buona arma come un'ascia, ma una lancia vale quanto qualsiasi altra cosa.\n\n$GBenvenuto:Benvenuta; nella Valley of Trials.", enHash = "60cf4212", vanilla = true },
        reward = { it = "Vedrai che questo posto è adatto a te, mentre continui ad addestrarti nelle vie $Gdel:della; $C. Se hai domande, chiedi pure a chiunque qui intorno, e quando ti senti $Gpronto:pronta;, torna da me per l'addestramento. Ne so quanto qualsiasi $C qui nella Valley e posso trasmetterti quello che so... per un compenso.", enHash = "4ae3a0f8", vanilla = true },
    },
    [3082] = {
        title = { it = "Etched Tablet", enHash = "e3ab8e33", vanilla = true },
        text = { it = "Ah, mentre eri via è arrivata una tavoletta per te, $N.\n\nLeggila quando hai tempo. Se non sbaglio, viene da Jen'shan, l'istruttrice di cacciatori. Vuole parlarti quando sei $Gpronto:pronta;.", enHash = "a67edddb", vanilla = true },
        objectives = { it = "Parla con Jen'shan, nella Valley of Trials.", enHash = "47a7eff2", vanilla = true },
        progress = { it = "Jen'shan vede davanti a sé $Gun potente cacciatore:una potente cacciatrice;, e gli spiriti approvano.\n\nLa via del cacciatore è uno dei nostri modi di vivere più antichi. Quelli dell'Orda si sono rivolti a noi quando lottavano soltanto per sopravvivere su Azeroth, e ci hanno chiesto di insegnare loro, di mostrare loro i segreti di molte cose. Erano già forti: forti nelle vie degli sciamani; forti nelle vie dei guerrieri. Ma la via del cacciatore non era la loro via... allora.", enHash = "34d04590", vanilla = true },
        reward = { it = "Ora noi insegniamo loro quelle cose, e loro ne insegnano altre a noi. Diventiamo una sola razza... quasi. Siamo alleati da tanto tempo ormai. Perciò ricordati di aiutarli. E Jen'shan si ricorda di aiutare te.\n\nJen'shan ti insegna le vie del cacciatore — te le insegna bene. Non dimenticarlo mai: i cacciatori sono molto rispettati dalla tribù. Avrai un ruolo importante da svolgere nel futuro... non dimenticarlo mai.\n\nQuando ne senti il bisogno, vieni da Jen'shan. Lei ti insegna tutto quello che può, quando sente che sei $Gpronto:pronta;.", enHash = "f63a9e14", vanilla = true },
    },
    [3083] = {
        title = { it = "Encrypted Tablet", enHash = "1d72a842", vanilla = true },
        text = { it = "Ah, mentre eri via è arrivata una tavoletta per te, $N.\n\nLeggila quando hai tempo. Se non sbaglio, viene da Rwag, l'istruttore di ladri. Vuole parlarti quando sei $Gpronto:pronta;.", enHash = "dccb8305", vanilla = true },
        objectives = { it = "Leggi l'Encrypted Tablet e parla con Rwag, nella Valley of Trials.", enHash = "e974136b", vanilla = true },
        progress = { it = "$GBenvenuto:Benvenuta; nella Valley of Trials, $N. Non saresti qui se non avessi ricevuto la mia tavoletta, quindi vengo al punto.\n\nSono Rwag, e mi occupo di addestrare i ladri, i furfanti e i tagliaborse qui nella Valley. Sono io quello a cui si rivolgerà la Hand se non sarai $Gpronto:pronta; per ciò che ti aspetta. Ma non preoccuparti: la Hand non controllerà tutto quello che fai, anche se, qualora avessero bisogno dei tuoi talenti, sarebbe saggio collaborare con loro.", enHash = "cd2cb29c", vanilla = true },
        reward = { it = "Fino ad allora, sarai sotto la mia tutela. Ti insegnerò i trucchi del mestiere, come dice qualcuno. Quando ti senti $Gpronto:pronta;, vieni da me e vedrò di addestrarti ancora. Nel frattempo, esercita le tue abilità e tienile affilate come un rasoio. Non si sa mai quando potrà servirti anche l'abilità più insignificante.", enHash = "883b2f0b", vanilla = true },
    },
    [3084] = {
        title = { it = "Rune-Inscribed Tablet", enHash = "e6578544", vanilla = true },
        text = { it = "Ah, mentre eri via è arrivata una tavoletta per te, $N.\n\nLeggila quando hai tempo. Se non sbaglio, viene da Shikrik, l'istruttrice di sciamani. Vuole parlarti quando sei $Gpronto:pronta;.", enHash = "dc74a8de", vanilla = true },
        objectives = { it = "Parla con Shikrik, nella Valley of Trials.", enHash = "d098ce19", vanilla = true },
        progress = { it = "Ah, $Gbenvenuto:benvenuta;, $N. Sono lieta che tu sia $Garrivato:arrivata;. Con tutti questi allievi da istruire le mie giornate sono diventate lunghe e anche molto impegnate, ma l'arrivo di qualcuno come te mi dà un grande senso di soddisfazione — ricordo i giorni in cui ero io l'allieva di uno sciamano del tuo popolo.", enHash = "54288211", vanilla = true },
        reward = { it = "Come probabilmente sai, gli elementi ci danno il nostro potere. Fuoco, terra, acqua e aria — sono i nostri strumenti.\n\nLa nostra forza viene dagli spiriti dei nostri antenati. Siamo le guide del nostro popolo. Come Thrall lo è per l'Orda, così saremo noi per i villaggi e le cittadine che visitiamo. Si rivolgeranno a noi per avere saggezza e protezione. Per essere più $Gpreparato:preparata;, devi allenarti spesso. Quando senti di aver acquisito più potere, vieni da me e ti insegnerò quello che posso.", enHash = "050ecc90", vanilla = true },
    },
    [3085] = {
        title = { it = "Hallowed Tablet", enHash = "8ce62246", vanilla = true },
        text = { it = "Ah, mentre eri via è arrivata una tavoletta per te, $N.\n\nLeggila quando hai tempo. Se non sbaglio, viene da Ken'jai, l'istruttore di sacerdoti. Vuole parlarti quando sei $Gpronto:pronta;.", enHash = "ac6ac4d5", vanilla = true },
        objectives = { it = "Leggi l'Hallowed Tablet e parla con Ken'jai, fuori dal Den, nella Valley of Trials.", enHash = "eee25938", vanilla = true },
        progress = { it = "Allora ce l'hai fatta... bene, bene! Gli spiriti mi avevano detto che saresti $Gvenuto:venuta; presto da Ken'jai. Lascia che sia uno dei primi a darti il benvenuto nella Valley of Trials. Questo posto non sarà casa tua per molto, ma finché lo è, perché non ne approfitti al meglio?", enHash = "49b8bfd6", vanilla = true },
        reward = { it = "Mettendoti alla prova, scoprirai di avere un controllo sempre migliore sugli spiriti — li chiamerai per cose sempre più grandi... ed è lì che entra in gioco il vecchio Ken'jai. Vieni a parlare con il vecchio Ken'jai quando ti senti $Gpronto:pronta;. Se gli spiriti sono d'accordo, allora vedremo di insegnarti abilità più potenti... ma solo se gli spiriti sono d'accordo.\n\nOra va', parla con il resto della gente della Valley. Torna a parlarmi più tardi.", enHash = "b3f6f9c9", vanilla = true },
    },
    [3086] = {
        title = { it = "Glyphic Tablet", enHash = "e8c2b880", vanilla = true },
        text = { it = "Ah, mentre eri via è arrivata una tavoletta per te, $N.\n\nLeggila quando hai tempo. Se non sbaglio, viene da Mai'ah, l'istruttrice di maghi. Vuole parlarti quando sei $Gpronto:pronta;.", enHash = "d43fc57e", vanilla = true },
        objectives = { it = "Leggi la Glyphic Tablet e parla con Mai'ah, vicino all'ingresso del Den, nella Valley of Trials.", enHash = "21face78", vanilla = true },
        progress = { it = "Hai già l'aria di voler fare contenta Mai'ah, $N. Questo è bene. Tu porti rispetto a Mai'ah, e forse Mai'ah ricambia il rispetto. Ma basta con questo: sei qui per imparare la magia, non per sentire Mai'ah chiacchierare.\n\nC'è una sola cosa sulla magia che Mai'ah non può insegnarti, $N, ed è come fermare la corruzione.", enHash = "2cb1d789", vanilla = true },
        reward = { it = "Sei tra gli esseri più potenti del pianeta, $N... su questo non si discute. E lo sanno tutti... e pure bene!\n\nMa devi stare in guardia! Perché non devi avere paura degli orchi, degli elfi o dei nani... ma delle cose che non puoi vedere. La magia è potente. Ti fa fare cose che forse non vuoi fare. Ti fa credere di essere più potente di quanto sei davvero. Sii paziente. Usa la testa.\n\nQuando pensi di essere $Gpronto:pronta; per l'addestramento, torna da Mai'ah. Lei ti insegna quello che sei $Gpronto:pronta; a imparare, nessun problema.", enHash = "2ba67ebd", vanilla = true },
    },
    [3087] = {
        title = { it = "Etched Parchment", enHash = "2737dc37", vanilla = true },
        text = { it = "Ah, mentre eri via è arrivata una pergamena per te, $N.\n\nLeggila quando hai tempo. Se non sbaglio, viene da Jen'shan, l'istruttrice di cacciatori. Vuole parlarti quando sei $Gpronto:pronta;.", enHash = "12bf87b5", vanilla = true },
        objectives = { it = "Leggi l'Etched Parchment e parla con Jen'shan, nella Valley of Trials.", enHash = "fc2a0fab", vanilla = true },
        progress = { it = "Ah, allora sei $Garrivato:arrivata;, finalmente. Bene. Jen'shan ti stava aspettando.\n\nIn molti pensano che sia una via facile, ma Jen'shan ti dice che non è vero. Padroneggiare le bestie di Durotar e oltre richiede tanta abilità quanta ne serve per padroneggiare le arti arcane o per parlare con i nostri antenati.\n\nTirare con l'arco o con il fucile forse non è pericoloso per te quanto lanciare un incantesimo, ma di sicuro è altrettanto pericoloso per il tuo nemico.", enHash = "16b574e3", vanilla = true },
        reward = { it = "Quando avremo finito di parlare, dovresti rivolgerti al resto degli abitanti della Valley. Ti chiedono di fare delle cose per loro... cose che metteranno alla prova la tua abilità e ti insegneranno alcuni dei pericoli di questa terra.\n\nMan mano che crescerai in esperienza e saggezza, avrai bisogno che Jen'shan ti mostri tecniche e abilità migliori. Torna spesso da Jen'shan. Ti farò sapere cosa posso insegnarti.", enHash = "2354546d", vanilla = true },
    },
    [3088] = {
        title = { it = "Encrypted Parchment", enHash = "cfe953c8", vanilla = true },
        text = { it = "Ah, mentre eri via è arrivata una pergamena per te, $N.\n\nLeggila quando hai tempo. Se non sbaglio, viene da Rwag, l'istruttore di ladri. Vuole parlarti quando sei $Gpronto:pronta;.", enHash = "522a98eb", vanilla = true },
        objectives = { it = "Leggi l'Encrypted Parchment e parla con Rwag, nella Valley of Trials.", enHash = "6f6d6237", vanilla = true },
        progress = { it = "Shhh, non così forte. Di Nartok, laggiù, non mi fido. Chi deve nascondersi in una caverna più in fondo di me non è uno con cui scherzare.\n\nImmagino che tu non abbia avuto problemi a trovare la strada?", enHash = "136a6eee", vanilla = true },
        reward = { it = "Ora che sai dove mi sono rintanato, devo dirti una cosa: la Shattered Hand mi ha chiesto di tenerti d'occhio. Vogliono che sia io ad addestrarti e a tenerti al corrente di tutto ciò di cui potrebbero aver bisogno. Anche se per ora non ti interessa aiutarli — e saresti $Gpazzo:pazza; a non volerlo — farò quello che posso per addestrarti... in cambio di un piccolo compenso. Torna da me ogni volta che pensi di essere $Gpronto:pronta;, e vedremo cosa sei $Gpronto:pronta; a imparare.", enHash = "2e9969ac", vanilla = true },
    },
    [3089] = {
        title = { it = "Rune-Inscribed Parchment", enHash = "10fc3f86", vanilla = true },
        text = { it = "Ah, mentre eri via è arrivata una pergamena per te, $N.\n\nLeggila quando hai tempo. Se non sbaglio, viene da Shikrik, l'istruttrice di sciamani. Vuole parlarti quando sei $Gpronto:pronta;.", enHash = "beea5bc4", vanilla = true },
        objectives = { it = "Leggi la Rune-Inscribed Parchment e parla con Shikrik, nella Valley of Trials.", enHash = "5f56db4f", vanilla = true },
        progress = { it = "Allora sei $Garrivato:arrivata;. Cominciavo a chiedermi quando ti saresti $Gfatto vivo:fatta viva;. Ho mandato la pergamena un po' di tempo fa — non ero sicura che fosse arrivata.\n\nMa basta chiacchiere... sei qui perché sei $Gstato scelto:stata scelta;, $Gscelto:scelta; per guidare la vita spirituale del nostro popolo.", enHash = "43fda25b", vanilla = true },
        reward = { it = "Sarai il tramite attraverso cui parlano i nostri antenati. Avrai il potere degli elementi ai tuoi ordini. Fare a pezzi i tuoi nemici sarà un gioco da ragazzi; curare i tuoi alleati sarà facile come respirare. Tieni a mente queste cose quando affronterai nuove sfide, e torna da me tutte le volte che vuoi. Resterò qui per insegnarti nuovi incantesimi e per metterti sulla strada giusta, quando sarai $Gpronto:pronta;.", enHash = "7f460ebd", vanilla = true },
    },
    [3090] = {
        title = { it = "Tainted Parchment", enHash = "34276445", vanilla = true },
        text = { it = "Ah, mentre eri via è arrivata una pergamena per te, $N.\n\nDi solito, se posso, evito di avere a che fare con gli stregoni, ma credo che dovresti leggerla quando hai tempo. Se non sbaglio, viene da Nartok, il tuo nuovo istruttore. Vuole parlarti quando sei $Gpronto:pronta;.", enHash = "4d218c47", vanilla = true },
        objectives = { it = "Leggi la Tainted Parchment e parla con Nartok, dentro il Den, nella Valley of Trials.", enHash = "186514d0", vanilla = true },
        progress = { it = "Finalmente sei $Garrivato:arrivata;... e con discrezione, per giunta. Bene.\n\nIl nostro mondo è pieno di sciocchi, $N. Perfino il potente Thrall ha difetti più grandi di quanto molti riescano a vedere. Volta le spalle al potere che servirebbe per rendere questa terra completamente nostra! Non siamo più lo stesso popolo che fu manipolato e usato dalle creature del Nether. Siamo un popolo a sé. Siamo fieri... e siamo forti.", enHash = "f2dc6d8a", vanilla = true },
        reward = { it = "E ora anche tu sei $Gentrato:entrata; nelle nostre file. Non fraintendermi, $N. Solo perché hai accesso a un potere che molti ti invidieranno, non significa che sarai $Gaccettato:accettata; facilmente. Thrall permette alla nostra gente di stare a Orgrimmar perché siamo ancora suoi consanguinei: non può voltarci le spalle, altrimenti diventeremmo patetici come gli umani che lo resero schiavo. Il punto è: sta' $Gattento:attenta;. Puoi essere potente, ma se sei $Gsciocco:sciocca;, sei come morto.\n\nSe hai bisogno di imparare incantesimi, torna da me.", enHash = "961c91de", vanilla = true },
    },
    [3091] = {
        title = { it = "Simple Note", enHash = "a7f3ada0", vanilla = true },
        text = { it = "Poco fa una messaggera ti stava cercando, $N. Credo che l'abbia mandata Harutt, l'istruttore di guerrieri. Se il biglietto è di Harutt, al posto tuo non aspetterei a leggerlo.", enHash = "17ae679f", vanilla = true },
        objectives = { it = "Leggi la Simple Note e parla con Harutt Thunderhorn, a Camp Narache.", enHash = "63af021c", vanilla = true },
        progress = { it = "Ah, finalmente sei $Garrivato:arrivata;, $C. Nel mio biglietto non ho mentito, $N. Anche noi siamo una stirpe speciale, come i druidi o gli sciamani della nostra tribù. Tu sei altrettanto importante. Siamo noi quelli chiamati a difendere i nostri confini, a cacciare i centauri e ad andare in guerra.", enHash = "f7201658", vanilla = true },
        reward = { it = "Ognuno di noi ha un ruolo nella nostra tribù. E ognuno di noi deve anche passare per gli stessi riti. Non lasciare mai che il tuo orgoglio ti dica il contrario.\n\nIo resto qui per addestrare i nuovi guerrieri che cercano la gloria della battaglia e seguono le vie dei nostri antenati più antichi. Quando ti senti $Gpronto:pronta;, torna da me e farò il possibile per addestrarti ancora. Va' con la benedizione della tribù, $N.", enHash = "999b1d85", vanilla = true },
    },
    [3092] = {
        title = { it = "Etched Note", enHash = "84e38eff", vanilla = true },
        text = { it = "Poco fa una messaggera ti stava cercando, $N. Credo che l'abbia mandata Lanka, l'istruttore di cacciatori. Se questo biglietto viene da Lanka, non aspetterei troppo a leggerne il contenuto.", enHash = "a6cea123", vanilla = true },
        objectives = { it = "Leggi l'Etched Note e parla con Lanka Farshot, sulla Red Cloud Mesa.", enHash = "7577eca7", vanilla = true },
        progress = { it = "$GBenvenuto:Benvenuta; a Camp Narache, $N. Sento dire cose buone su di te. La tua stirpe è forte, e molti degli anziani ti ritengono già abile. Ma questo lo metteremo alla prova.\n\nLe pianure di Mulgore saranno la tua casa per un po' di tempo — dovresti fare del tuo meglio per conoscerle molto bene. Un giorno viaggerai verso terre sconosciute per padroneggiare abilità più grandi. Devi essere $Gpronto:pronta;.", enHash = "995a6fa9", vanilla = true },
        reward = { it = "Ed è mio compito assicurarmi che tu sia $Gpreparato:preparata;, insegnandoti le basi della nostra professione — come addomesticare il tuo animale, come sparare con il fucile, e molte altre abilità che diventeranno necessarie.\n\nI cacciatori sono una parte importante della nostra tradizione e della nostra storia, $N. Faresti bene a ricordare quanto sei importante per la tribù. Sarai $Grispettato:rispettata; e $Gvenerato:venerata; se servirai bene il nostro popolo.", enHash = "c443a89f", vanilla = true },
    },
    [3093] = {
        title = { it = "Rune-Inscribed Note", enHash = "f1941650", vanilla = true },
        text = { it = "Poco fa una messaggera ti stava cercando, $N. Credo che l'abbia mandata Meela, l'istruttrice di sciamani. Se questo biglietto viene da Meela, non aspetterei troppo a leggerne il contenuto.", enHash = "ae09a149", vanilla = true },
        objectives = { it = "Leggi il Rune-Inscribed Note e parla con Meela Dawnstrider, a Camp Narache.", enHash = "99cc8f52", vanilla = true },
        progress = { it = "Veloce come l'acqua che cade dal cielo, eccoti davanti a me. La tua rapidità mi fa piacere. Vuol dire che hai capito quanto sono importanti sia il nostro incontro sia il fatto che tu sia qui. Non sono una guida, ma comprendo gli elementi e so parlare con gli spiriti del nostro popolo. Ti insegnerò a fare lo stesso.", enHash = "f339a44a", vanilla = true },
        reward = { it = "Ci incontreremo molte volte nei giorni a venire. Ogni volta, spero, te ne andrai da me un po' più potente... un po' più $Gpreparato:preparata;. Come l'Eternal Flame, il tuo spirito arderà intenso e luminoso.\n\nOra va', $N. Va' e mettiti alla prova. Sarò qui per te quando ne avrai bisogno.", enHash = "e3e90b02", vanilla = true },
    },
    [3094] = {
        title = { it = "Verdant Note", enHash = "dcb4baac", vanilla = true },
        text = { it = "Poco fa una messaggera ti stava cercando, $N. Credo che l'abbia mandata Gart, l'istruttore di druidi. Se questo biglietto viene da Gart, non aspetterei troppo a leggerne il contenuto.", enHash = "708a5e88", vanilla = true },
        objectives = { it = "Leggi il Verdant Note e parla con Gart Mistrunner, a Camp Narache.", enHash = "79404796", vanilla = true },
        progress = { it = "Sei $Garrivato:arrivata;. Bene. Gli spiriti dei nostri antenati sono diventati inquieti in tutta Mulgore e oltre, ma non riesco a capire perché. Sarà per sempre tuo dovere imparare ad ascoltare gli spiriti della natura, e a essere la loro incarnazione. Tienilo a mente.", enHash = "147f13e1", vanilla = true },
        reward = { it = "Anche se ci unisce un legame comune, non aspettarti una grande accoglienza dagli elfi della notte. Il loro orgoglio offusca ancora il loro sguardo, ma non è affar nostro. Gli insegnamenti della Madre Terra sono tutto ciò di cui devi preoccuparti, e ti insegnerò quello che so man mano che crescerai in saggezza.\n\nTorna spesso da me, $N. Scoprirai che la Madre Terra concede abilità incredibili a chi le è più devoto.", enHash = "929ed76b", vanilla = true },
    },
    [3095] = {
        title = { it = "Simple Scroll", enHash = "819d30fb", vanilla = true },
        text = { it = "Ah, mentre eri via a vedertela con il Flagello senza mente, è arrivato questo rotolo per te. Credo sia una faccenda importante, perché sembra portare il sigillo di Dannal, l'istruttore di guerrieri. Io mi prenderei il tempo di leggerlo prima di ripartire.", enHash = "7a9304c7", vanilla = true },
        objectives = { it = "Leggi il Simple Scroll e parla con Dannal Stern, a Deathknell.", enHash = "1ff48c6d", vanilla = true },
        progress = { it = "Ah, dunque sei $Garrivato:arrivata;. Bene. Ho sentito dire che alcuni altri sono riusciti a sfuggire alla \"morte\" e stavano venendo in città. Forse questa tenacia ripagherà anche in futuro.\n\nPuoi ringraziare Sylvanas per la tua libertà... libertà della mente e del corpo. Anche se sei ancora $Gtormentato:tormentata; dalla piaga e dai suoi effetti, ora sei $Glibero:libera; di andare e venire come meglio credi.", enHash = "407b8cce", vanilla = true },
        reward = { it = "Sarò qui ad addestrarti man mano che acquisti esperienza... vieni da me tutte le volte che vuoi. Chiedo un compenso minimo, ma vedrai che tutto quello che posso insegnarti ne vale la pena.\n\nOra va' e metti alla prova la tua abilità. Molte altre cose ti saranno rivelate man mano che acquisti esperienza, e di alcune non posso parlarti qui. Sappi solo che in futuro Sylvanas avrà bisogno di guerrieri della tua tempra. Sarai la spina dorsale della nostra salvezza. Non dimenticarlo.", enHash = "ed95aebe", vanilla = true },
    },
    [3096] = {
        title = { it = "Encrypted Scroll", enHash = "1be150a9", vanilla = true },
        text = { it = "Ah, mentre eri via a vedertela con il Flagello senza mente, è arrivato questo rotolo per te. Credo sia una faccenda importante, perché sembra portare il sigillo di David Trias, l'istruttore di ladri. Io mi prenderei il tempo di leggerlo prima di ripartire.", enHash = "89181cf6", vanilla = true },
        objectives = { it = "Leggi l'Encrypted Scroll e parla con David Trias, a Deathknell.", enHash = "e755c864", vanilla = true },
        progress = { it = "Quindi ce l'hai fatta? Bene, col tempo avremo bisogno di altri ladri. Probabilmente gli Shadowstalker finiranno per trovarti quando riterranno che sia il momento giusto, perciò non commettere passi falsi e non fare niente di cui potresti pentirti. Hanno bisogno di agenti di talento... non di borseggiatori e di sciocchi.", enHash = "ea7d07ca", vanilla = true },
        reward = { it = "Passo la maggior parte del tempo qui alla locanda, a tenere d'occhio le facce nuove e a seguire da vicino le giovani promesse. Fila dritto e farò quello che posso per insegnarti un paio di cose. Torna da me quando vuoi, e vedremo se sei $Gpronto:pronta; per un'abilità nuova o due.", enHash = "faa97c9d", vanilla = true },
    },
    [3097] = {
        title = { it = "Hallowed Scroll", enHash = "8b54caad", vanilla = true },
        text = { it = "Ah, mentre eri via a occuparti delle creature senza mente del Flagello, è arrivata questa pergamena per te. Immagino sia qualcosa di importante, perché sembra portare il sigillo di Duesten, l'istruttore di sacerdoti. Io mi prenderei il tempo di leggerla prima di ripartire.", enHash = "b3414dc9", vanilla = true },
        objectives = { it = "Leggi l'Hallowed Scroll e parla con Dark Cleric Duesten nella chiesa di Deathknell.", enHash = "7b59cc1e", vanilla = true },
        progress = { it = "Ah, dunque tra incendi, peste, rivolte e cose ben peggiori, un altro dei \"fedeli\" bussa alla mia porta. Be', lascia che ti dia il benvenuto, $C. E concedimi un momento per spiegarti un paio di cose prima che tu decida che è ora di cercare ciò che ti spinge avanti: l'Holy Light non ti riguarda più, gli spiriti dei tuoi antenati sono favole e le creature del Nether non ti vogliono.\n\nFin qui mi segui?", enHash = "ddb17b04", vanilla = true },
        reward = { it = "C'è una sola cosa che devi sapere: siamo sopravvissuti solo grazie alla volontà. È la fede in noi stessi che ci separa dagli altri, e con i nostri poteri porteremo un grande cambiamento in tutta Azeroth. I deboli verranno ad appoggiarsi a te. I lebbrosi ti chiameranno $GSignore:Signora;. E gli ignoranti si rivolgeranno a te per avere una guida. È mio dovere assicurarmi che tu abbia gli strumenti necessari, così che quando verrà il momento sarai $Gpronto:pronta;. Man mano che acquisti esperienza, vieni a cercarmi. Ti insegnerò poteri più grandi, se sarai $Gpronto:pronta;.", enHash = "08e4e8db", vanilla = true },
    },
    [3098] = {
        title = { it = "Glyphic Scroll", enHash = "e73160e7" },
        text = { it = "Ah, mentre eri via a occuparti delle creature senza mente del Flagello, è arrivata questa pergamena per te. Immagino sia qualcosa di importante, perché sembra portare il sigillo di Isabella, che addestra ogni $C come te. Al posto tuo la leggerei prima di ripartire.", enHash = "5d987a68" },
        objectives = { it = "Leggi il Glyphic Scroll e parla con Isabella nella chiesa di Deathknell.", enHash = "302ee7bf" },
        progress = { it = "Sapevo che saresti $Gvenuto:venuta; da me, $N. Non perché ti manchi la volontà di seguire la tua strada, ma perché siamo anime affini. $GEntrambi:Entrambe; abbiamo provato il dolore. $GEntrambi:Entrambe; abbiamo sofferto. E ora vogliamo il potere per riprenderci ciò che sappiamo che ci appartiene: questa terra, le nostre vite, i nostri destini. Ma hai ancora molto da imparare.", enHash = "fe83aa0c" },
        reward = { it = "Dovrai tornare spesso da me, se vuoi diventare abbastanza potente da distruggere chi ci si oppone. Le regole della magia valgono ancora per te, $N. Scoprirai che la corruzione ti segue come un branco di lupi affamati nella notte. Scoprirai che la sua carezza somiglia a una dipendenza, a un vecchio amante che vuole ancora starti accanto. Ma queste cose si possono tenere a bada. Ti controlleranno solo se glielo permetterai.\n\nOra va', e torna da me quando sarai $Gdiventato:diventata; più potente.", enHash = "3123c39d" },
    },
    [3099] = {
        title = { it = "Tainted Scroll", enHash = "0530594c", vanilla = true },
        text = { it = "Ah, mentre eri via a vedertela con il Flagello senza mente, è arrivato questo rotolo per te. Credo sia una faccenda importante, perché sembra portare il sigillo di Maximillion, l'istruttore di stregoni. Io mi prenderei il tempo di leggerlo prima di ripartire.", enHash = "022b5fe0", vanilla = true },
        objectives = { it = "Leggi il Tainted Scroll e parla con Maximillion, a Deathknell.", enHash = "f09090b1", vanilla = true },
        progress = { it = "$GBenvenuto:Benvenuta;, $Gfratello:sorella;. Sapevo che saresti $Gvenuto:venuta;. Era solo questione di tempo.\n\nQuello che ho detto ti ha interessato, vero? Ho toccato una corda... qualcosa dentro di te sapeva che quello che affermavo era la verità. Bene.\n\nMa sappi questo: non sono un traditore di Sylvanas. Semmai, lei apprezzerebbe le mie parole, visto che sono state proprio le sue convinzioni a mettere i Reietti nella posizione in cui si trovano ora.", enHash = { "261162ed", "0f31a033" }, vanilla = true },
        reward = { it = "Ho detto che uno schiavo resta uno schiavo, qualunque sia il padrone. Ricordi? Sappiamo entrambi che è quel tipo di controllo, quel tipo di potere, a guidarci ora. Vogliamo creature che ci servano. Sappiamo di essere più potenti e di meritare più rispetto di quanto ci concedano gli altri... e così ora cerchiamo di prendercelo.\n\nSarò tuo alleato in questa lotta, la lotta per la nostra libertà. La libertà di scegliere le nostre alleanze. Quando ti senti $Gpronto:pronta;, torna da me e ti insegnerò tutto quello che so.", enHash = "5a663a99", vanilla = true },
    },
    [3100] = {
        title = { it = "Simple Letter", enHash = "75c86e54", vanilla = true },
        text = { it = "Mi hanno chiesto di darti questo non appena fossi $Gtornato:tornata; dagli accampamenti dei kobold, $N. Sembra una lettera sigillata con lo stemma di Llane, il nostro istruttore di guerrieri. Al posto tuo la leggerei subito, prima di occuparti di qualsiasi altra faccenda qui all'Abbey.", enHash = "ef9e6481", vanilla = true },
        objectives = { it = "Leggi la Simple Letter e parla con Llane Beshere, alla Northshire Abbey.", enHash = "8dff77ed", vanilla = true },
        progress = { it = "Ah, hai ricevuto la mia lettera, $N... bene.\n\nUltimamente a Elwynn sono arrivati molti guerrieri: una buona cosa per Stormwind, ma una brutta notizia per i kobold e i Defias della zona.", enHash = "7b075de1", vanilla = true },
        reward = { it = "Sistemati per bene, impara com'è fatta la zona e torna da me ogni volta che hai bisogno di addestramento. Sarò qui giorno e notte.\n\nI Cavalieri della Mano d'Argento hanno fatto un buon lavoro nel rendere questo posto abbastanza sicuro, ma quando conoscerai gli altri cittadini, credo che scoprirai che tutti hanno problemi per cui un aiuto farebbe comodo — un aiuto che $Gun:una; $C può dare loro. Buona fortuna.", enHash = "281bdc1e", vanilla = true },
    },
    [3101] = {
        title = { it = "Consecrated Letter", enHash = "98545551" },
        text = { it = "Mi è stato chiesto di fartela avere appena fossi $Gtornato:tornata; dagli accampamenti dei kobold, $N. Sembra una lettera sigillata con l'insegna di Brother Sammuel, il nostro istruttore di paladini. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui nell'Abbey.", enHash = "f4269477" },
        objectives = { it = "Leggi la Consecrated Letter e parla con Brother Sammuel, nella Northshire Abbey.", enHash = "1caf4f66" },
        progress = { it = "Finalmente! Ci incontriamo faccia a faccia, da fratello a $Gfratello:sorella;. Ti do il benvenuto a Northshire. Questa sarà la tua casa per un breve periodo, mentre impari come funzionano le cose, ma sappi che Stormwind non è lontana, e prima o poi il tuo cammino ti porterà là. Ma fino ad allora, abbi pazienza... $GCavaliere:Cavaliera; della Mano d'Argento.", enHash = { "a709e3ab", "69104401" } },
        reward = { it = "Nel frattempo, dovresti sapere un paio di altre cose. Sei un simbolo per molti, qui in questa terra — comportati di conseguenza. L'Holy Light risplende dentro di te, e sarà evidente sia ai tuoi alleati sia ai tuoi nemici.\n\nInoltre, man mano che crescerai in saggezza e potere, dovrai addestrarti per imparare nuove abilità. È qui che entro in gioco io. Quando senti di aver fatto un po' di esperienza qui a Northshire, torna da me e ti insegnerò quello che sento che sei $Gpronto:pronta; a imparare. Buona fortuna... $C!", enHash = "516c8a7d" },
    },
    [3102] = {
        title = { it = "Encrypted Letter", enHash = "100c8e02", vanilla = true },
        text = { it = "Mi hanno chiesto di darti questo non appena fossi $Gtornato:tornata; dagli accampamenti dei kobold, $N. Sembra una lettera sigillata con lo stemma di Jorik, uno dei nostri istruttori. Al posto tuo la leggerei subito, prima di occuparti di qualsiasi altra faccenda qui all'Abbey.", enHash = "49df6e23", vanilla = true },
        objectives = { it = "Leggi l'Encrypted Letter e parla con Jorik Kerridan, nella stalla dietro la Northshire Abbey.", enHash = "c97d8190", vanilla = true },
        progress = { it = "Sei $Garrivato:arrivata; fin qui senza un graffio, e non sembra che ti abbiano visto in molti. Tanto mi basta. Qui dietro non mi piace attirare troppo l'attenzione... tutto bello tranquillo. Sono sicuro che capisci.\n\nHai già avuto qualche guaio? Mi fa piacere sentire di no. Le cose cambieranno presto.", enHash = "800d1e8f", vanilla = true },
        reward = { it = "Troverai parecchi gruppi che farebbero di tutto per avere le nostre abilità, $N. Gli avventurieri, lo SI:7... accidenti, perfino la Defias Brotherhood non disdegnerebbe una spia o due dentro Stormwind. Ma ricordati questo: rispondi solo a te $Gstesso:stessa;. Non lasciare che nessuno ti costringa a fare qualcosa che non vuoi fare! E poi, le carte in mano le abbiamo tutte noi... almeno finché la partita non è finita. Capisci cosa intendo?\n\nComunque, volevo solo presentarmi e farti sapere che sono qui se hai bisogno di addestramento. Passa quando vuoi.", enHash = { "54dab462", "5c94b28a" }, vanilla = true },
    },
    [3103] = {
        title = { it = "Hallowed Letter", enHash = "7f800806", vanilla = true },
        text = { it = "Mi è stato chiesto di fartela avere appena fossi $Gtornato:tornata; dagli accampamenti dei kobold, $N. Sembra una lettera sigillata con l'insegna di Priestess Anetta, la nostra istruttrice di sacerdoti. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui nell'Abbey.", enHash = "617a00e4", vanilla = true },
        objectives = { it = "Leggi l'Hallowed Letter e parla con Priestess Anetta, nella Northshire Abbey.", enHash = "d0e1191e", vanilla = true },
        progress = { it = "Ah, finalmente sei $Garrivato:arrivata;. Sapevo che avresti trovato la strada fino a me. L'Holy Light risplende su di te e sul cammino che hai scelto. Questi sono tempi duri: la Legione Infuocata è ancora presente su Azeroth, l'intero Kalimdor cerca nuovi modi per difendersi dalle proprie tribolazioni, e sta a te aiutare quante più persone puoi.", enHash = "49a5571f", vanilla = true },
        reward = { it = "Man mano che acquisti esperienza, torna da me e farò il possibile per trasmetterti il mio sapere. Fino ad allora, va' con la compassione nel cuore, e lascia che la saggezza ti guidi. Ricorda: il mondo diventa un posto migliore solo se sei tu a renderlo tale.", enHash = "3e692c24", vanilla = true },
    },
    [3104] = {
        title = { it = "Glyphic Letter", enHash = "db5c9e40", vanilla = true },
        text = { it = "Mi è stato chiesto di fartela avere appena fossi $Gtornato:tornata; dagli accampamenti dei kobold, $N. Sembra una lettera sigillata con l'insegna di Khelden, il nostro istruttore di maghi. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui nell'Abbey.", enHash = "c1ba5ff2", vanilla = true },
        objectives = { it = "Leggi la Glyphic Letter e parla con Khelden Bremen, dentro la Northshire Abbey.", enHash = "8af41fb4", vanilla = true },
        progress = { it = "Salve, $N. Sono Khelden. Posso fare qualcosa per te?", enHash = "a022706d", vanilla = true },
        reward = { it = "Ah ah, sapevo che il mio biglietto non ti avrebbe distolto dal tuo cammino. Quindi sei $Gpronto:pronta;, vero? $GPronto:Pronta; ad accettare il tuo destino? $GPronto:Pronta; a sfidare gli dei e qualsiasi altra forza ti si pari davanti nella ricerca della conoscenza e del potere?\n\nNon ti mentirò, $N: sarai $Gtemuto:temuta; quanto $Grispettato:rispettata;. Ma sappi anche questo: sarò qui per te quando avrai bisogno di addestramento. Basterà che tu venga a cercarmi man mano che diventerai più potente.", enHash = "9d91c5c1", vanilla = true },
    },
    [3105] = {
        title = { it = "Tainted Letter", enHash = "f95b96a5", vanilla = true },
        text = { it = "Mi hanno chiesto di darti questo non appena fossi $Gtornato:tornata; dagli accampamenti dei kobold, $N. Sembra una lettera sigillata con lo stemma di Drusilla, una delle nostre istruttrici. Al posto tuo la leggerei subito, prima di occuparti di qualsiasi altra faccenda qui all'Abbey.", enHash = "9f172676", vanilla = true },
        objectives = { it = "Leggi la Tainted Letter e parla con Drusilla La Salle, accanto alla Northshire Abbey.", enHash = "86e4be5b", vanilla = true },
        progress = { it = "Ah, dunque sei $Garrivato:arrivata;, e appena in tempo, $N. Poco fa alcune guardie erano qui e mi lanciavano occhiate curiose... patetici profani.", enHash = "20188d1b", vanilla = true },
        reward = { it = "Man mano che cresci in potere, sarai $Gtentato:tentata;: devi sempre ricordarti di controllarti. Non ti mentirò: la corruzione può colpire chiunque pratichi l'arcano, soprattutto chi ha a che fare con le creature del Twisting Nether. Sii paziente, e sii prudente... ma non lasciare che questo soffochi la tua ambizione.\n\nQuando sarai più potente, torna da me e ti insegnerò di più sulle nostre vie.", enHash = "e145de16", vanilla = true },
    },
    [3106] = {
        title = { it = "Simple Rune", enHash = "a7f594e8", vanilla = true },
        text = { it = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Thran, l'istruttore di guerrieri. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.", enHash = "f8b0290d", vanilla = true },
        objectives = { it = "Leggi la Simple Rune e parla con Thran Khorman, nella Coldridge Valley.", enHash = "c4028bb3", vanilla = true },
        progress = { it = "Accidenti che freddo oggi, eh? Sembra che la neve non se ne vada mai, $N.\n\nProbabilmente l'hai già notato, ma adesso nella nostra città vivono degli gnomi. È perché sono riusciti a farsi saltare in aria la loro casa. Non andarlo a raccontare in giro, ma non posso proprio dargli torto — credo che anch'io sarei ricorso agli esplosivi, se Ironforge fosse stata infestata dai Dark Iron o gente simile.", enHash = "52653bc0", vanilla = true },
        reward = { it = "Altre cose che probabilmente vedrai, così sei al corrente: nani che in battaglia usano la magia invece del fucile. Alcuni di noi che si mettono a venerare l'Holy Light come certi umani e, ultimi ma non meno importanti, i trogg. Su di loro ne saprai di più in seguito, ma quello che devi sapere adesso è che sono qui per aiutarti.\n\nSono qui per insegnarti a essere $Gun vero:una vera; $C. Ogni volta che pensi di aver bisogno di altro addestramento, torna da me e vedrò cosa posso fare.", enHash = "6809c34f", vanilla = true },
    },
    [3107] = {
        title = { it = "Consecrated Rune", enHash = "95591725" },
        text = { it = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Bromos, l'istruttore di paladini. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.", enHash = "d3392370" },
        objectives = { it = "Leggi la Consecrated Rune e parla con Bromos Grummner, nella Coldridge Valley.", enHash = "ee0ddb48" },
        progress = { it = "Allora, ce l'hai fatta! E appena in tempo. C'è molto da fare nella Coldridge Valley e oltre. Avrò bisogno del tuo aiuto quanto tu avrai bisogno del mio!\n\nOra sei $Gun Cavaliere:una Cavaliera; della Mano d'Argento, sii $Gpronto:pronta; a comportarti come tale.", enHash = "c3aaff6b" },
        reward = { it = "Gli umani ci hanno insegnato molto sull'Holy Light e su quanto il loro ordine sia importante per loro... e per la protezione di tutta Azeroth. Abbiamo un grande rispetto per quanto sia intriso di tradizione, e per come una sola figura, un solo sacrificio, possa fare la differenza tra il dolore e la salvezza.\n\nNoi due lavoreremo insieme per un po'. Ogni volta che pensi di essere $Gpronto:pronta;, torna da me e vedremo di darti un po' di addestramento. Non possiamo mandarti in giro per il mondo $Gimpreparato:impreparata;, no?", enHash = "71d1ef8c" },
    },
    [3108] = {
        title = { it = "Etched Rune", enHash = "84e57647", vanilla = true },
        text = { it = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Thorgas, l'istruttore di cacciatori. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.", enHash = "206aeef6", vanilla = true },
        objectives = { it = "Leggi l'Etched Rune e parla con Thorgas Grimson, nella Coldridge Valley.", enHash = "44087d92", vanilla = true },
        progress = { it = "Ce l'hai fatta! Mi fa piacere! Scommetto che non hai nemmeno dovuto seguire le mie tracce per trovare il posto. Ah ah!\n\nLa nostra professione è piuttosto intrisa di tradizione, $N. Imparare le vie della terra. Imparare a seguire le tracce di un orso tra le montagne. Anche solo sopravvivere contando soltanto sul proprio ingegno richiede molto coraggio e molta astuzia. Pensi di esserne capace?", enHash = "e8840927", vanilla = true },
        reward = { it = "Una cosa che dovresti ricordare sempre è che devi rispettare il mondo in cui vivi. Le bestie che scelgono di combattere al tuo fianco; il luccichio della tua arma; il peso delle tue munizioni; il morso di un vento gelido; tutte queste cose devi conoscerle a fondo.\n\nFarò quello che posso per aiutarti, ma la maggior parte del lavoro spetta a te. Ogni volta che pensi di essere $Gpronto:pronta;, torna a parlare con me. Ti addestrerò quando potrò.", enHash = "fc40f8cc", vanilla = true },
    },
    [3109] = {
        title = { it = "Encrypted Rune", enHash = "d279c816", vanilla = true },
        text = { it = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Solm, l'istruttore di ladri. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.", enHash = "5d66a785", vanilla = true },
        objectives = { it = "Leggi l'Encrypted Rune e parla con Solm Hargrin, nella Coldridge Valley.", enHash = "54298f38", vanilla = true },
        progress = { it = "Ce l'hai fatta! Magnifico!\n\nUltimamente c'è un gran via vai, quindi sono contento di contare un altro membro del clan di Ironforge tra le nostre file. Per i miei gusti, troppi di noi guardano all'arcano e al divino. Niente contro di loro e le loro credenze, ma non c'è niente come una lama fredda in mano e un'ombra che ti tenga lontano dalla luce, capisci cosa intendo?", enHash = "df83954b", vanilla = true },
        reward = { it = "Comunque, quando comincerai a curiosare in giro per Coldridge, prima o poi avrai bisogno di addestramento. Torna da me ogni volta che senti di averne bisogno e ti insegnerò quello che so — un trucco qui, una manovra là. Sai, le cose che ti tengono in vita e ti fanno guadagnare qualche moneta in più.\n\nE tieni d'occhio anche i nostri amici gnomi... sono loro ad aver avuto la peggio, visto che Gnomeregan è stata... distrutta. Avranno bisogno del nostro aiuto per sentirsi i benvenuti.", enHash = "62825016", vanilla = true },
    },
    [3110] = {
        title = { it = "Hallowed Rune", enHash = "cdcbf31a", vanilla = true },
        text = { it = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Branstock, l'istruttore di sacerdoti. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.", enHash = "fb50db3f", vanilla = true },
        objectives = { it = "Leggi l'Hallowed Rune e parla con Branstock Khalder, ad Anvilmar.", enHash = "2a06bf4e", vanilla = true },
        progress = { it = "Ah! Ce l'hai fatta, $N! Magnifico!\n\nStavo per dirti che ormai perdevo la fede nel tuo arrivo... capito, perdere la fede? È una battuta, $Gragazzo:ragazza;... uff, lascia stare. Tanto non sei $Gvenuto:venuta; qui per le mie battutacce.", enHash = "b9a0e74e", vanilla = true },
        reward = { it = "Sono io quello che può addestrarti mentre cominci a orientarti nella Coldridge Valley. Quando ti senti $Gpronto:pronta;, torna da me e vedremo se insegnarti un incantesimo o due per difendere la valle da quei maledetti trogg.\n\nHai la Luce dalla tua parte, insieme a tutta Ironforge, $N... nessuna pressione perché tu diventi qualcosa di speciale.", enHash = "a49d8d26", vanilla = true },
    },
    [3111] = {
        title = { it = "Glyphic Rune", enHash = "ce6ccfd4", vanilla = true },
        text = { it = "Tanto tempo fa gli alti elfi insegnarono i segreti della magia a noi e ai nostri alleati umani. Ci facevano grandi prediche sulle regole e su come la magia possa farti impazzire! Ma non crederci. Noi non siamo come gli elfi; non abbiamo le loro stesse debolezze. Basta che tu resti sulla retta via, e scoprirai che la magia è potente come strumento quanto come arma.\n\nQuando sei $Gpronto:pronta;, vieni a cercarmi dentro Anvilmar. Ti aspetto!", enHash = "b855551d", vanilla = true },
        objectives = { it = "Parla con Marryk Nurribit, dentro Anvilmar.", enHash = "8e38ffea", vanilla = true },
    },
    [3112] = {
        title = { it = "Simple Memorandum", enHash = "8e962a65", vanilla = true },
        text = { it = "Mentre mi davi una mano, mi hanno dato questo memorandum da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene da Thran, l'istruttore di guerrieri. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.", enHash = "a1dd4af0", vanilla = true },
        objectives = { it = "Leggi il Simple Memorandum e parla con Thran Khorman, nella Coldridge Valley.", enHash = "814841f0", vanilla = true },
        progress = { it = "Ah, beh, un altro memorandum da $Gun:una; $R in missione... che cosa carina.\n\nNo, no, non ti sto prendendo in giro, $Gpiccoletto:piccoletta;. Bisogna rispettare la tua tenacia, questo è certo. Sarei altrettanto furioso se Ironforge fosse stata presa dai nani Dark Iron, quindi non pensare che non capisca la tua situazione...", enHash = "e4b0ddc4", vanilla = true },
        reward = { it = "Beh, visto che questa è la tua direttiva principale, o come la chiamate di questi tempi, ho dato la mia parola che avrei fatto tutto il possibile perché tu e i tuoi foste pronti a riprendervi la vostra casa... ed è proprio quello che farò.\n\nOgni volta che ti senti $Gpronto:pronta;, torna dal buon vecchio Thran e sarò felice di condividere con te quello che so. L'addestramento ha un costo, ma non sarà troppo caro. Buona fortuna.", enHash = "a58e60f4", vanilla = true },
    },
    [3113] = {
        title = { it = "Encrypted Memorandum", enHash = "2546c313", vanilla = true },
        text = { it = "Mentre mi davi una mano, mi hanno dato questo memorandum da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene da Solm, l'istruttore di ladri. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.", enHash = "a4ec3d42", vanilla = true },
        objectives = { it = "Leggi l'Encrypted Memorandum e parla con Solm Hargrin, nella Coldridge Valley.", enHash = "50058d5b", vanilla = true },
        progress = { it = "Sono contento di vedere che hai ricevuto il mio biglietto e che sei $Gvenuto:venuta;. Scusa se ho finto che fosse un memorandum dei tuoi superiori... non volevo offenderti. Sapevo solo che noi due, insieme agli altri come noi, dobbiamo restare uniti.\n\nNon sono in molti a pensare che sia una gran cosa avere la tua gente e la mia rintanate nella stessa città, ma io credo che possiamo andare d'accordo benissimo. Tu che ne pensi?", enHash = "04635905", vanilla = true },
        reward = { it = "Qui me ne sto per conto mio, così nessuno ci dà la colpa delle cose che spariscono, ma se ti serve qualcosa, un po' di addestramento o altro, torna pure quando vuoi.\n\nIo e te ci capiamo. Sappiamo che, quando si arriva al dunque, ci si può fidare solo della famiglia... ed è proprio quello che abbiamo qui, no? Anche se Gnomeregan è stata... invasa, e qualunque altra cosa ci capiti addosso, possiamo contare gli uni sugli altri per guardarci le spalle. Giusto?", enHash = "4bd70185", vanilla = true },
    },
    [3114] = {
        title = { it = "Glyphic Memorandum", enHash = "ad788451", vanilla = true },
        text = { it = "Mentre mi davi una mano, mi hanno dato questo memorandum da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene da Marryk, l'istruttore di maghi. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.", enHash = "c195f119", vanilla = true },
        objectives = { it = "Leggi il Glyphic Memorandum e parla con Marryk Nurribit, dentro Anvilmar, sopra la Coldridge Valley.", enHash = "8b7b9016", vanilla = true },
        progress = { it = "Sì, cosa c'è, $R? Parla più forte, se non ti dispiace. Dopo qualche birra non ci sento tanto bene.", enHash = "8e7986e8", vanilla = true },
        reward = { it = "Ah, già! Le Arti Arcane... ma certo.\n\nEcco quello che devi sapere, $N: non cacciarti in troppi guai. Metti da parte qualche moneta per offrirmi una birra... o per qualunque incantesimo tu voglia. E per carità, stai alla larga da Gnomeregan. A parte questo, buona giornata! Sono qui se hai bisogno di me o vuoi addestrarti... o per qualsiasi altra cosa.", enHash = "eaec76c3", vanilla = true },
    },
    [3115] = {
        title = { it = "Tainted Memorandum", enHash = "48cac236", vanilla = true },
        text = { it = "Mentre mi davi una mano, mi hanno dato questo memorandum da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene da Alamar, l'istruttore di stregoni. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.\n\nE guardati le spalle, $N: da queste parti quelli come te non godono di molta fiducia.", enHash = "e34e3350", vanilla = true },
        objectives = { it = "Leggi il Tainted Memorandum e parla con Alamar Grimm, dentro Anvilmar, sopra la Coldridge Valley.", enHash = "d40a3d4c", vanilla = true },
        progress = { it = "Magnifico! Hai ricevuto il mio memorandum, a quanto vedo.\n\nIgnora gli sciocchi che ti circondano, $N. L'Holy Light?! La spada e lo scudo?! Non sono vie per menti aperte come le nostre. Guarda cos'ha fatto la magia \"normale\" alla nostra casa. Insieme a quei dannati inventori, la nostra razza si è quasi estinta. E ora dobbiamo contare sui nani, che preferiscono passare il tempo ad allearsi con gli umani piuttosto che aiutarci a ricostruire la nostra casa. Siamo come cittadini di serie B. Hai visto come ci guardano?", enHash = "5b2cfbbe", vanilla = true },
        reward = { it = "Ma niente di tutto questo conta. Quello che conta è che hai visto la tua personale Holy Light! Sai da dove viene davvero il potere. Ti rendi conto che avere alleati tutti nostri è molto più... prudente. Alleati speciali. Alleati che, qualunque sia il compito, obbediranno fino all'ultimo respiro.\n\nEd è qui che entro in gioco io, $N. Posso insegnarti i primi rudimenti di quei poteri speciali. Vieni a trovarmi spesso e farò il possibile per insegnarti nuovi incantesimi.", enHash = "4adda89b", vanilla = true },
    },
    [3116] = {
        title = { it = "Simple Sigil", enHash = "56c591c6", vanilla = true },
        text = { it = "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice di guerrieri, Alyissia. Sembra che Alyissia voglia parlarti quando hai un momento. Leggilo e poi portalo a lei.", enHash = "0cd03fdf", vanilla = true },
        objectives = { it = "Leggi il Simple Sigil e parla con Alyissia, a Shadowglen.", enHash = "fa145805", vanilla = true },
        progress = { it = "Ce l'hai fatta. Ne sono davvero felice.\n\nNegli ultimi anni sono successe molte cose, $N: la creazione di Teldrassil, la corruzione di molte creature della foresta, qui e altrove, la scoperta di terre che credevamo perdute, come Feralas... tante cose, in così poco tempo. Ma queste sono solo alcune delle ragioni per cui siamo qui; la più importante è proteggere la nostra gente da altro male.", enHash = "d7292cf5", vanilla = true },
        reward = { it = "Presto vedrai gente di altre razze tra i rami della nostra casa: non lasciare che questo faccia nascere in te dei pregiudizi. Sono i benvenuti. Ci aiuteranno quando potranno. Non tutti saranno disinteressati, ma meritano un po' di fiducia.\n\nMa ora niente di tutto questo conta. Ora dobbiamo concentrarci su di te e su come puoi aiutare la nostra gente. Sono qui proprio per questo. Ti addestrerò nelle vie $Gdel:della; $C man mano che diventi più forte. Torna da me quando vuoi, e farò quello che posso per aiutarti.", enHash = "7b460929", vanilla = true },
    },
    [3117] = {
        title = { it = "Etched Sigil", enHash = "17d1dc47", vanilla = true },
        text = { it = "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice di cacciatori, Ayanna. Sembra che Ayanna voglia parlarti quando hai un momento. Leggilo e poi portalo a lei.", enHash = "c09fb43f", vanilla = true },
        objectives = { it = "Leggi l'Etched Sigil e parla con Ayanna Everstride, in cima ad Aldrassil, a Shadowglen.", enHash = "81bd816b", vanilla = true },
        progress = { it = "Sei $Garrivato:arrivata;, e appena in tempo, $N. $GBenvenuto:Benvenuta; a Shadowglen.\n\nConfido che il mio sigillo ti abbia trovato in buona salute e di buon umore?\n\nCome ho detto prima, sono qui per addestrarti come $Gcacciatore:cacciatrice;, per insegnarti ad addomesticare le bestie perché ti aiutino in battaglia; a usare l'arco con precisione infallibile; a rispettare le terre che chiamiamo casa, e anche le terre al di là.", enHash = "00b99428", vanilla = true },
        reward = { it = "Mentre scopri quello che Shadowglen ha da insegnarti, vieni a trovarmi — potrò aiutarti a capire meglio il tuo ruolo di $Gcacciatore:cacciatrice; e ciò di cui sei capace.\n\nSono tempi pericolosi, $N, non dare per scontata l'abilità dei tuoi animali — in questo mondo ci sono cose più pericolose di quanto tu possa immaginare. Va' con Elune, e torna ancora da me.", enHash = "22515f98", vanilla = true },
    },
    [3118] = {
        title = { it = "Encrypted Sigil", enHash = "7cc7c458", vanilla = true },
        text = { it = "Questo sigillo mi è stato consegnato da un messaggero del nostro istruttore di ladri, Frahun. Sembra che Frahun voglia parlarti quando hai un momento. Leggilo e poi portalo a lui.", enHash = "575c20b6", vanilla = true },
        objectives = { it = "Leggi l'Encrypted Sigil e parla con Frahun Shadewhisper, a Shadowglen.", enHash = "11dc9ea9", vanilla = true },
        progress = { it = "Salve, $N. Sono contento che tu mi abbia trovato. Pensavo che magari ti fossi $Gperso:persa; lungo la strada.\n\nA Shadowglen non è successo niente di davvero nuovo da quando ti ho mandato il mio sigillo, ma lascio a te il compito di raccogliere informazioni. Parla con le altre persone intorno ad Aldrassil, se vuoi.", enHash = "9f48c920", vanilla = true },
        reward = { it = "Fino ad allora, sappi che quelli come noi servono più che mai in questi tempi incerti. La pace con le altre razze può venire meno da un momento all'altro, e si parla molto di membri dell'Orda che cercano di seminare ancora più sfiducia. Ricordalo.\n\nMan mano che acquisti potere e ti senti più $Gpreparato:preparata;, torna da me qui e vedrò di farti avere un po' di addestramento. È importante che tu sappia maneggiare l'arma che preferisci, tra le altre cose.", enHash = "63db7690", vanilla = true },
    },
    [3119] = {
        title = { it = "Hallowed Sigil", enHash = "ebbaf9d4", vanilla = true },
        text = { it = "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice di sacerdoti, Shanda. Sembra che Shanda voglia parlarti quando hai un momento. Leggilo e poi portalo a lei.", enHash = "cace171f", vanilla = true },
        objectives = { it = "Leggi l'Hallowed Sigil e parla con Shanda, ad Aldrassil.", enHash = "1aef57b8", vanilla = true },
        progress = { it = "Mi fa piacere vedere che sei $Garrivato:arrivata; così in fretta, $N. $GBenvenuto:Benvenuta;.\n\nCome probabilmente avrai sentito, tutta Teldrassil è in fermento per l'andirivieni dei viaggiatori. Perfino ai membri dell'Alleanza è stato concesso di salire sui rami di Teldrassil, per incontrare altri Kaldorei che si preparano alle avventure che li attendono.", enHash = "db339235", vanilla = true },
        reward = { it = "Per ora non preoccuparti del mondo sotto Teldrassil. Ci sarà tempo per quello più avanti. Ora va' a parlare con gli altri a Shadowglen — possono raccontarti di più sugli eventi che sono accaduti. Aiutali in ogni modo possibile, e ogni volta che senti di aver bisogno di altro addestramento, torna da me e ti insegnerò quello che posso.", enHash = "ba3326d7", vanilla = true },
    },
    [3120] = {
        title = { it = "Verdant Sigil", enHash = "ba26263a", vanilla = true },
        text = { it = "Questo sigillo me l'ha dato un messaggero del nostro istruttore di druidi, Mardant. Pare che Mardant voglia parlarti quando hai un momento. Leggilo e poi portaglielo.", enHash = "f3edda24", vanilla = true },
        objectives = { it = "Leggi il Verdant Sigil e parla con Mardant Strongoak, nell'albero Aldrassil, a Shadowglen.", enHash = "2a778ffa", vanilla = true },
        progress = { it = "Ah, giovane $C. Vedo che sei impaziente di continuare i tuoi studi. Bene.\n\nMi chiedo: hai già passato molto tempo nell'Emerald Dream? Forse non sei ancora $Gpronto:pronta; per questo... Col tempo lo sarai, ne sono certo.\n\nMa fino ad allora, dovremmo parlare d'altro.", enHash = "d573e714", vanilla = true },
        reward = { it = "Per ora sarò il tuo mentore e la tua guida. È mio dovere insegnarti a interpretare non solo ciò che gli spiriti ci comunicano, ma anche le complessità e i segreti dell'Emerald Dream.\n\nMan mano che imparerai e crescerai in potere, conoscerai meglio la nostra trance del sonno. Ma fino ad allora, torna da me tutte le volte che vuoi e ti insegnerò quello che posso sulle vie della nostra gente.", enHash = "484c4b19", vanilla = true },
    },
    [3130] = {
        title = { it = "Contro gli Hatecrest", enHash = "33871ebf", vanilla = true },
        text = { it = "A questo punto ti indirizzerò al mio secondo, Latronicus. Finora ha tenuto d'occhio da vicino le forze dei naga. Io valuterò la situazione generale qui, per quanto riguarda i naga; per quanto vorrei impegnare tutte le nostre forze contro di loro, lasciare la roccaforte esposta a un attacco diretto dell'Orda, o peggio, non mi sembra la scelta migliore.\n\nComunque, Latronicus ti aspetta. Buon lavoro finora, $N. Continua così.\n\nPuoi andare.", enHash = "b8b8e58c", vanilla = true },
        objectives = { it = "Fai rapporto a Latronicus Moonspear, alla Feathermoon Stronghold.", enHash = "2dcbede6", vanilla = true },
        reward = { it = "Eccellente, $N: in chi lavora con me apprezzo un atteggiamento da \"si può fare\".\n\nIl generale Feathermoon mi ha incaricato di affrontare i naga in modo diretto. I miei piani sono due: primo, indeboliremo le loro forze, sia nel numero sia nel comando; secondo, scopriremo cosa stanno facendo tra le rovine. Con il tuo aiuto contrasteremo la presenza dei naga senza sacrificare la sicurezza generale della roccaforte.", enHash = "98f6d415", vanilla = true },
    },
    [3182] = {
        title = { it = "Proof of Deed", enHash = "f0adcead", vanilla = true },
        text = { it = "Ti aspetti che creda a una storia del genere? Il vero corno avrebbe avuto ancora conficcata la testa della mia ascia spezzata.\n\nSenti, porta quel falso evidente a Curator Thorius, a Ironforge. Se lui conferma quello che dici, riceverai una Proof of Deed. Riportami quella prova e ti darò la Key to Searing Gorge.\n\nMuoviti!", enHash = "00522fe8", vanilla = true },
        objectives = { it = "Porta Margol's Gigantic Horn a Curator Thorius, a Ironforge.", enHash = "80b675f9", vanilla = true },
        progress = { it = "Ma salve, $Gmio giovane signore:mia giovane signora;. Ti piacerebbe fare un giro del museo?", enHash = { "672f62a3", "2ba682a7" }, vanilla = true },
        reward = { it = "Che cos'è questo?\n\nOh, cielo, non ci credo! Ti rendi conto di cosa hai qui, $R? Questo è il corno di Margol the Rager! Margol, la rovina di ogni archeologo che abbia mai messo piede nella Searing Gorge.\n\nPosso tenerlo?", enHash = "d8410d8e", vanilla = true },
    },
    [3221] = {
        title = { it = "Parla con Renferrel", enHash = "6f0b37b5", vanilla = true },
        text = { it = "Mentre eri in giro ad aiutare i nostri Inseguitori della Morte, Apothecary Renferrel ha mandato a chiamarti. Non mi ha dato dettagli, ma voleva parlarti dei cuori di lupo che gli avevi portato.", enHash = "e556e999", vanilla = true },
        objectives = { it = "Parla con Apothecary Renferrel, al Sepulcher.", enHash = "7ade1a26", vanilla = true },
        reward = { it = "Ah, molto bene. C'è una faccenda che riguarda i cuori di lupo che mi hai portato e richiede la nostra attenzione.", enHash = "27c6d895", vanilla = true },
    },
    [3261] = {
        title = { it = "Jorn Skyseer", enHash = "b9dbbc41", vanilla = true },
        text = { it = "Il tuo tempo con me è finito, $N. Per imparare altro devi andare a Camp Taurajo, a sud, e parlare con Jorn Skyseer. Sarà lui a continuare a guidarti.", enHash = "55b3e216", vanilla = true },
        objectives = { it = "Parla con Jorn Skyseer, a Camp Taurajo.", enHash = "f185d117", vanilla = true },
        reward = { it = "Salve, giovane. Sei qui per percorrere la via del cacciatore?\n\nMolto bene. Cominciamo.", enHash = "cde11590", vanilla = true },
    },
    [3281] = {
        title = { it = "Stolen Silver", enHash = "c8406426", vanilla = true },
        text = { it = "Avrai anche ucciso i raptor, ma l'argento che hanno rubato va recuperato! Mi riferiscono che i raptor hanno un grande insieme di nidi a sud di Ratchet, chiamato i Raptor Grounds. Probabilmente hanno portato lì il nostro argento.\n\nVa' in quel rifugio di raptor e cerca l'argento rubato. Quando lo trovi, riportamelo.", enHash = "c340cd2a", vanilla = true },
        objectives = { it = "Porta lo Stolen Silver a Gazrog, al Crossroads.", enHash = "206353f9", vanilla = true },
        progress = { it = "L'hai trovato l'argento?", enHash = "ffa6c1c1", vanilla = true },
        reward = { it = "Aha! Quindi l'argento i raptor l'avevano davvero nascosto nella loro tana. È difficile credere che quelle bestie abbiano voglia d'argento. Forse le storie sulla loro intelligenza non sono così lontane dal vero come pensavo!\n\nGrazie, $N. Prendi questo come ricompensa per il servizio che ci hai reso, e sappi che le guardie del Crossroads ti devono la paga del mese prossimo.", enHash = "8792c35c", vanilla = true },
    },
    [3301] = {
        title = { it = "Mura Runetotem", enHash = "7c830dbe", vanilla = true },
        text = { it = "Una mia compagna di clan, Mura Runetotem, è andata a Silverpine per aiutare i nostri alleati non morti. Silverpine è una foresta malata, una foresta che muore, e Mura sperava di portarle nuova vita. Forse la strana vita che si trova qui nelle Barrens può aiutarla nel suo lavoro a Silverpine.\n\nPrendi un campione dei gusci che hai raccolto e portalo a Mura, a Silverpine. Alloggia al Sepulcher. Con un po' di fortuna, studiare il guscio le darà l'intuizione che le serve per guarire quel luogo morente.", enHash = "9c20bcc1", vanilla = true },
        objectives = { it = "Parla con Mura Runetotem, al Sepulcher.", enHash = "f939241b", vanilla = true },
        progress = { it = "Sento su di te l'odore della polvere delle Barrens, $C. Hai viaggiato a lungo.", enHash = "0cc2e0fa", vanilla = true },
        reward = { it = "Ah, che cos'è questo? Il guscio ha un bagliore interno, come se pulsasse ancora di vita. Straordinario! Devo studiarlo meglio.\n\nGrazie, $N. Con un po' di fortuna questo guscio custodirà un segreto che potrò usare per aiutare la povera terra di Silverpine.", enHash = "964400b7", vanilla = true },
    },
    [3341] = {
        title = { it = "Porta la fine", enHash = "17b8881e", vanilla = true },
        text = { it = "Nelle Barrens si trova un orrendo groviglio di rampicanti chiamato Razorfen Downs. Se le nostre prime osservazioni di quel luogo avevano rivelato una minaccia modesta, le nostre scoperte recenti sono molto più gravi...\n\nI quilboar di Razorfen Downs si sono alleati con il Flagello. Ora li governa un lich di nome Amnennar the Coldbringer, che usa il potere della sua immensa coscienza per controllare ogni loro mossa.\n\nAmnennar ha un legame telepatico diretto con Ner'zhul; dobbiamo spezzare questo legame, $N. Il Coldbringer deve trovare la sua fine.", enHash = "3541a170", vanilla = true },
        objectives = { it = "Andrew Brownell vuole che tu uccida Amnennar the Coldbringer e riporti il suo teschio.", enHash = "0b6af81f", vanilla = true },
        progress = { it = "Questa faccenda è della massima importanza, $N. Dobbiamo fermare ogni tentativo del Flagello di rinforzare le sue file.", enHash = "54703b15", vanilla = true },
        reward = { it = "La lealtà di un lich è incrollabile, $N. Che sappiano che una simile lealtà porterà loro solo la distruzione.", enHash = "acfc003f", vanilla = true },
    },
    [3361] = {
        title = { it = "Il dilemma di un profugo", enHash = "71c78c03" },
        text = { it = "Abbiamo cacciato i trogg da Gnomeregan, ma poi è andato tutto terribilmente storto! Ora la nostra casa è completamente irradiata, e noi gnomi siamo sparpagliati per tutto il Dun Morogh.\n\nNella fretta di sfuggire alle radiazioni, ho perso tutti i miei effetti personali e i miei attrezzi. Me li hanno presi i troll. Mi hanno rubato il baule, la scatola e il secchio di bulloni! Li hanno portati nei loro accampamenti a sud-ovest di Anvilmar.\n\nIo non sono un avventuriero: potresti ritrovare le mie cose e riportarmele, per favore?", enHash = "dc609edc" },
        objectives = { it = "Porta Felix's Box, Felix's Chest e Felix's Bucket of Bolts a Felix Whindlebolt, ad Anvilmar.", enHash = "1238a2c8" },
        progress = { it = "Oh, santo cielo, $N, questo posto non fa per uno come me. Qui ci sono tante brutte creature quante ce n'erano a Gnomeregan prima dell'incidente!\n\nHai le mie cose? Se no, chissà cosa ne avranno fatto i troll ormai...", enHash = "d5c20bbf", vanilla = true },
        reward = { it = "Evviva, le hai trovate! Sei proprio $Gun salvatore:una salvatrice;, $Gamico mio:amica mia;. Ecco, non è molto, ma è qualcosa per il disturbo che ti ho dato! Grazie!", enHash = "02775564", vanilla = true },
    },
    [3364] = {
        title = { it = "Consegna dello Scalding Mornbrew", enHash = "45f91c4d", vanilla = true },
        text = { it = "Accidenti! Dovevo portare questo delizioso Scalding Mornbrew a Durnan Furcutter, dentro Anvilmar, già da un pezzo, ma prima ho dovuto consegnarne uno a Grelin, qui. Non arriverò mai ad Anvilmar prima che si raffreddi!\n\nTu sembri $Gsvelto:svelta;. Magari ce la fai. Questa tazza resterà calda solo per altri cinque minuti, e Durnan non ha ordinato un Mornbrew \"freddino\", quindi muoviti. Anvilmar è a nord-est, un insediamento scavato nella montagna.\n\nGrazie, $N, e non dimenticarti di riportarmi la tazza!", enHash = "b6b19701", vanilla = true },
        objectives = { it = "Porta uno Scalding Mornbrew a Durnan Furcutter, dentro Anvilmar, prima che si raffreddi tra cinque minuti!", enHash = "9c327e9c", vanilla = true },
        progress = { it = "Sì, sono Durnan Furcutter. Hai qualcosa per me?", enHash = "d8abe633", vanilla = true },
        reward = { it = "Ah, bene, questo ci voleva proprio. Lasciami fare una piccola pausa mentre mi godo questo Scalding Mornbrew!", enHash = "46991653", vanilla = true },
    },
    [3365] = {
        title = { it = "Riporta la tazza", enHash = "76702125", vanilla = true },
        text = { it = "Questo sì che ci voleva! Niente di meglio di un Mornbrew bollente, anzi, ROVENTE, in una fredda giornata d'inverno per scaldarti fino in fondo all'anima.\n\nEcco qua, $N: fammi un favore e riporta questa tazza vuota a Nori, va bene?", enHash = "71d713f7", vanilla = true },
        objectives = { it = "Riporta Nori's Mug a Nori Pridedrift.", enHash = "2c6f597d", vanilla = true },
        progress = { it = "Spero che lo Scalding Mornbrew sia arrivato a Durnan in tempo! Ti sei $Gricordato:ricordata; di riportarmi la tazza?", enHash = "19e8e652", vanilla = true },
        reward = { it = "Ottimo, $N! Non immagini quanti corrieri si dimenticano di fare una cosa semplice come riportare la tazza. Le tazze non crescono sugli alberi, o almeno così mi dicono!\n\nEcco qualcosa per il disturbo. Grazie ancora per l'aiuto.", enHash = "84da4d97", vanilla = true },
    },
    [3366] = {
        title = { it = "La scheggia luminosa", enHash = "2b105dc4", vanilla = true },
        text = { it = "La scheggia è di un verde brillante e, pur essendo solida, sotto la superficie sembra muoversi qualcosa come fumo. Non riesci a smettere di fissare le profondità del cristallo; e allo stesso tempo sai che c'è qualcosa di molto inquietante in esso.\n\nForse dovresti vedere se a Ratchet c'è qualcuno che può dirti di più su questa strana scheggia.", enHash = "5317e248", vanilla = true },
        objectives = { it = "Va' a Ratchet per scoprire il significato del Nightmare Shard.", enHash = "ff4cc32c", vanilla = true },
    },
    [3369] = {
        title = { it = "Negli incubi", enHash = "9b8a4f4f", vanilla = true },
        text = { it = "Questa scheggia custodisce grandi segreti: è la pura essenza dell'Emerald Dream. Ma quello che vedo dentro non è un sogno: una visione del genere si chiamerebbe incubo.\n\nNon voglio allarmarti, $N, ma credo sia meglio che tu consegni questa scheggia nelle mani di un druido saggio appena puoi.\n\nQuello che devi trovare è Hamuul Runetotem, sull'Elder Rise. Va' a Thunder Bluff. Non posso dire altro.", enHash = "6f27eb0f", vanilla = true },
        objectives = { it = "Porta il Nightmare Shard a Hamuul Runetotem, sull'Elder Rise.", enHash = "fc9ed56a", vanilla = true },
        progress = { it = "Posso esserti utile in qualcosa?", enHash = "b9a4ecb1", vanilla = true },
        reward = { it = "Ti manda Falla? Bene, vediamo questa scheggia di cui dici che lei era così restia a parlare...\n\n<Hamuul scruta dentro la scheggia>\n\nOh... io non... Be'.\n\n$N, ti ringrazio per avermela portata. Però ti consiglio di non parlare di cose come questa: non è saggio. Sono faccende di cui non dovresti occuparti.\n\nDiciamo solo che le cose nell'Emerald Dream non sono come credevamo...\n\nForse in futuro le nostre strade si incroceranno di nuovo.", enHash = "fc20e78f", vanilla = true },
    },
    [3370] = {
        title = { it = "Negli incubi", enHash = "9b8a4f4f", vanilla = true },
        text = { it = "Questa scheggia custodisce grandi segreti: è la pura essenza dell'Emerald Dream. Ma quello che vedo dentro non è un sogno: una visione del genere si chiamerebbe incubo.\n\nNon voglio allarmarti, $N, ma credo sia meglio che tu consegni questa scheggia nelle mani di un druido saggio appena puoi...\n\nQuello che devi trovare è Mathrengyl Bearwalker, nel Cenarion Circle. Va' a Darnassus. Non posso dire altro.", enHash = "9f185a47", vanilla = true },
        objectives = { it = "Porta il Nightmare Shard a Mathrengyl Bearwalker, a Darnassus.", enHash = "408f79a1", vanilla = true },
        progress = { it = "Posso esserti utile in qualcosa?", enHash = "b9a4ecb1", vanilla = true },
        reward = { it = "Ti manda Falla? Bene, vediamo questa scheggia di cui dici che lei era così restia a parlare...\n\n<Mathrengyl scruta dentro la scheggia>\n\nOh... io non... Be'.\n\n$N, ti ringrazio per avermela portata. Però ti consiglio di non parlare di cose come questa: non è saggio. Sono faccende di cui devono occuparsi soltanto i druidi del Cenarion Circle.\n\nDiciamo solo che le cose nell'Emerald Dream non sono come credevamo...\n\nForse in futuro le nostre strade si incroceranno di nuovo.", enHash = "539db3a8", vanilla = true },
    },
    [3374] = {
        title = { it = "L'essenza di Eranikus", enHash = "860d4384", vanilla = true },
        text = { it = "Attivi la pietra del giuramento, e Itharius ti parla direttamente nella mente attraverso la pietra.\n\n\"Accettando l'incarico racchiuso in questa pietra del giuramento, accetti di aiutare la mia causa e quella dello stormo di Ysera nel redimere l'anima corrotta di Eranikus. Il primo sacrificio, uno dei tanti che senza dubbio tu e io faremo, sarà consegnarmi la gemma che tiene incatenato ciò che resta della parte libera della mente di Eranikus.\"\n\n\"Fallo, $N, e lavoreremo insieme per redimere un'anima degna di redenzione.\"", enHash = "a1286af6", vanilla = true },
        objectives = { it = "Porta l'Oathstone of Ysera's Dragonflight e la Chained Essence of Eranikus a Itharius, nella Swamp of Sorrows. Lì sceglierai se aiutare lo stormo di Ysera oppure no.", enHash = "2c21bd48", vanilla = true },
        progress = { it = "Eccoci, $N, a un altro bivio. È giunto il momento di fare un'altra scelta. Cosa scegli, mortale?", enHash = "50074e25", vanilla = true },
        reward = { it = "Hai fatto la tua scelta, e così comincia. Finora le tue scelte sono state quelle che considererei giuste; d'ora in poi, le tue azioni e le tue imprese decideranno se continuerà a essere così.", enHash = "21b5f40e", vanilla = true },
    },
    [3376] = {
        title = { it = "Spezza Sharptusk!", enHash = "56e45ebf", vanilla = true },
        text = { it = "$N... ho sentito parlare di te, $Gnuovo arrivato:nuova arrivata;. Forse sarai tu ad aiutarci, dove altri hanno fallito.\n\nNoi tauren ci siamo scavati una casa in questa terra, ma non senza un prezzo. I quilboar Bristleback del Brambleblade Ravine, guidati da Chief Sharptusk Thornmantle, ci rendono la vita difficile con la loro guerra continua. Ti affido il compito di portarmi la testa del loro capo!\n\nLo troverai nella gola a est, nel loro villaggio di fortuna.", enHash = "664db41e", vanilla = true },
        objectives = { it = "Porta la testa di Chief Sharptusk Thornmantle a Brave Windfeather, sulla Red Cloud Mesa.", enHash = "89d90209", vanilla = true },
        progress = { it = "Sharptusk non ci darà più guai, una volta che mi avrai portato la prova della sua morte. È la sua testa che cerco, $N.\n\nNoi tauren viviamo per la caccia, e non c'è caccia più grande di quella contro chi è abbastanza astuto da poter cacciare noi. Se riuscirai in questo compito, giovane, comincerai a capire cosa intendo.", enHash = "efe99102", vanilla = true },
        reward = { it = "Oggi è stata fatta giustizia, grazie alla tua rapidità, $N. Che questa impresa serva da avvertimento a chiunque voglia minacciare la nostra casa.\n\nTi sei $Gguadagnato:guadagnata; questa ricompensa, che ti aiuti nel tuo cammino, giovane $C.", enHash = "c7ff9144", vanilla = true },
    },
    [3512] = {
        title = { it = "Con le parole di Eranikus", enHash = "320fa941", vanilla = true },
        text = { it = "$N, il nostro primo passo sarà trovare un modo per parlare con Eranikus attraverso la gemma. Ora si trova in uno stato precario tra il sonno e la morte, avvolto in una trama di incubi. Anche se l'essenza che mi hai dato è gravemente corrotta, c'è la possibilità di raggiungerlo.\n\nViaggia lontano, fino alle terre gelide di Winterspring orientale, e cerca uno dei nostri alleati mortali, Umbranse the Spiritspeaker. È un medium umano che parla per i morti. Anche se Eranikus non è davvero morto, potrebbe comunque esserci d'aiuto.", enHash = "420a5865", vanilla = true },
        objectives = { it = "Va' nella parte orientale di Winterspring e parla con Umbranse the Spiritspeaker.", enHash = "1037d7ad", vanilla = true },
        reward = { it = "Itharius ha fatto bene a mandarti da me. Anche se non è morto come tu intendi la morte, presto Eranikus ci darà consiglio con le sue stesse parole. Per ora, però, non posso aiutarti direttamente... almeno non ancora.\n\nMetterò al tuo servizio la mia abilità nel parlare con i morti, ma prima mi serve l'aiuto di qualcuno che, a differenza di me, non sia limitato dalle fragilità della vecchiaia. Il mio strumento di divinazione più potente mi è stato portato via contro la mia volontà, e se non lo riavrò non potremo aiutare Eranikus.", enHash = "248caa89", vanilla = true },
    },
    [3513] = {
        title = { it = "Il Runed Scroll", enHash = "8eefa292", vanilla = true },
        text = { it = "La pergamena, dall'aria ufficiale, è avvolta stretta in un nastro argenteo. Sei $Gsicuro:sicura; che a qualcuno interesserebbe vederla, ma a chi?\n\nC'è un avamposto vicino al confine di Ashenvale, a nord, e se le informazioni su questa pergamena riguardano gli elfi della notte, sarebbe quello il posto dove portarla.", enHash = "07fc0244", vanilla = true },
        objectives = { it = "Porta il Runed Scroll alla torre di guardia settentrionale delle Barrens.", enHash = "eeb12236", vanilla = true },
        progress = { it = "Che hai lì?", enHash = "c74cc51b", vanilla = true },
        reward = { it = "Bene, bene... Dove l'hai trovata?", enHash = "af2be46b", vanilla = true },
    },
    [3514] = {
        title = { it = "Presenza dell'Orda", enHash = "60ca508f", vanilla = true },
        text = { it = "Questa pergamena viene da quella driade intrigante di Rynthariel, Keymaster del Talon Den su Stonetalon Peak.\n\nNon avrà più contatti con il messaggero da cui l'hai presa, eh, ma qui dobbiamo tenere la posizione. L'Orda non tollererà qui le sue staffette.\n\n$N, va' al Talon Den. Uccidi Rynthariel, e poi pianta un simbolo che tutti possano vedere. Prendi questa bandiera dell'Orda, $N. Piantala nel Talon Den, così non saranno più tanto avventati da mandare un altro messaggero nel nostro territorio.", enHash = "0a949200", vanilla = true },
        objectives = { it = "Uccidi il capo del Talon Den, Rynthariel the Keymaster.", enHash = "138e43cb", vanilla = true },
        progress = { it = "Non possiamo permettere all'Alleanza di stare sulla nostra terra, $N. Fallo sapere.", enHash = "1ab7cc73", vanilla = true },
        reward = { it = "Sei $Guno tosto:una tosta;! Liberare il Den da Rynthariel è un passo importante, $N. Ci metteranno un po' a riorganizzarsi, e così possiamo contare su meno corrieri dell'Alleanza nelle Barrens. Ci penseranno due volte prima di mandarne un altro da queste parti.\n\nGrazie.", enHash = "4e954fdc", vanilla = true },
    },
    [3519] = {
        title = { it = "Un amico in difficoltà", enHash = "1d0a5cce", vanilla = true },
        text = { it = "Ughhh... Mi ha morso in modo terribile un ragno di nome Githyiss the Vile, mentre esploravo la grotta dei ragni qui vicino. Sono sicuro di essere stato avvelenato gravemente: devi aiutarmi.\n\nTi prego, avvisa Dirania Silvershine. Lei saprà aiutarmi.\n\nPresto... mi gira tanto la testa...", enHash = "fcac2eda", vanilla = true },
        objectives = { it = "Parla con Dirania Silvershine a Shadowglen.", enHash = "d99d06ac", vanilla = true },
        reward = { it = "Oh, cielo! Mi chiedevo perché oggi non avessi ancora visto Iverron. E l'ho sempre avvertito di quei ragni...", enHash = "5b8effa5", vanilla = true },
    },
    [3521] = {
        title = { it = "Iverron's Antidote", enHash = "f5d7e9bb", vanilla = true },
        text = { it = "Forse possiamo aiutare Iverron: conosco un antidoto che dovrebbe funzionare contro il veleno. Però, prima di prepararlo, mi servono alcuni ingredienti.\n\nMi serviranno degli Hyacinth Mushroom. Li trovi sotto gli alberi, oppure puoi prenderli ai Grell a sud di qui, che sembrano esserne ghiotti. Mi serviranno anche dei Moonpetal Lily, che crescono solo intorno alle pozze d'acqua.\n\nL'ultimo ingrediente potrebbe essere il più difficile. Raccogli del Webwood Ichor proprio dai ragni che hanno avvelenato Iverron.", enHash = "c3f7951e", vanilla = true },
        objectives = { it = "Raccogli 7 Hyacinth Mushroom, 4 Moonpetal Lily e 1 Webwood Ichor per Dirania Silveshine a Shadowglen.", enHash = "d91e8afb", vanilla = true },
        progress = { it = "Ti prego, raccogli gli ingredienti, $N. Iverron ha bisogno del nostro aiuto.", enHash = "3f69b73e", vanilla = true },
        reward = { it = "Sia ringraziata Elune, hai raccolto gli ingredienti così in fretta!\n\nTra un attimo l'antidoto sarà pronto.", enHash = "1d838624", vanilla = true },
    },
    [3522] = {
        title = { it = "Iverron's Antidote", enHash = "f5d7e9bb", vanilla = true },
        text = { it = "L'antidoto è pronto, $N. Ti prego, assicurati che Iverron lo beva.\n\nC'è una cosa che devi sapere: l'antidoto resterà efficace solo per 5 minuti. Devi portarglielo in tempo.\n\nChe la velocità sia con te, $N.", enHash = "0114687e", vanilla = true },
        objectives = { it = "Porta Iverron's Antidote a Iverron prima che scada il tempo. Iverron si trova vicino alla grotta a nord.", enHash = "6561e864", vanilla = true },
        progress = { it = "Oh... $N, sono così felice che tu sia $Gtornato:tornata;.", enHash = "519ff7f6", vanilla = true },
        reward = { it = "Cos'è questo, $N?\n\nOh, lo sapevo che Dirania avrebbe potuto aiutarmi!\n\n<Iverron beve l'antidoto.>\n\nMi caccio sempre nei guai, e Dirania, be', riesce sempre a tirarmene fuori.\n\nMi sento molto meglio, ma credo che resterò seduto qui ancora un po', finché non mi sarò ripreso del tutto. Be', per questo e perché speravo che mi aprissi la strada tra quei feroci Webwood Spider...", enHash = "a8cb343d", vanilla = true },
    },
    [3523] = {
        title = { it = "Il Flagello dei Downs", enHash = "e68f021f", vanilla = true },
        text = { it = "Straordinario! Mi chiamo Belnistrasz, e ti ringrazio per avermi salvato. Mi ero già dato per morto... o peggio, per il pasto di questi parassiti infestati dal Flagello. Sì — ho detto proprio Flagello; hanno stretto una specie di patto con i quilboar di qui, e questo incubo ne è il risultato.\n\nAscolta... invece di fuggire e basta, voglio fare qualcosa di concreto, per il bene di tutti noi. Te la sentiresti di aiutarmi in questo? Probabilmente è pericoloso, ma mi sembri il tipo che non se ne preoccupa troppo.", enHash = "d690c427", vanilla = true },
        objectives = { it = "Se accetti di aiutare Belnistrasz, parla di nuovo con lui e restituiscigli Belnistrasz's Oathstone che ti ha dato.", enHash = "8998e1d9", vanilla = true },
        progress = { it = "La politica non fa per me; non mi importa se stai con l'Orda o con l'Alleanza. Mi interessa di più schiacciare le minacce dirette e terribili per tutte le razze... e qui dentro ne abbiamo una bella grossa.\n\nSe vuoi essere $Gun vero eroe:una vera eroina; per tutti, allora dammi la pietra del giuramento che ti ho dato, come segno del tuo impegno. Io... non sono di queste parti; per quelli come me, una pietra del giuramento è importante come vincolo di un accordo.", enHash = "ac112532", vanilla = true },
        reward = { it = "Fantastico, mi sembravi proprio il tipo eroico! Ci aspetta un lavoro difficile, $N, non ti mentirò. Se restiamo concentrati sul compito che abbiamo davanti, dovremmo riuscire a spuntarla.\n\nOra lascia che ti metta al corrente di quello che sta succedendo...", enHash = "33ce20b3", vanilla = true },
    },
    [3524] = {
        title = { it = "Spiaggiati", enHash = "4592438e", vanilla = true },
        text = { it = "È noto che maestose creature marine si gettino sulla costa di Darkshore, restando lì arenate fino a morire. Ultimamente queste bestie si spiaggiano in numero sempre maggiore. Il Temple of the Moon mi ha mandata qui a indagare, ma la presenza dei murloc lungo l'acqua rende difficili le mie ricerche.\n\nAppena a sud di Auberdine c'è una creatura gigantesca spiaggiata, circondata dagli immondi murloc Greymist. Potresti andare fin là e recuperare delle ossa della creatura per i nostri studi?", enHash = "9a402b5c", vanilla = true },
        objectives = { it = "Recupera le Sea Creature Bones dalla creatura marina spiaggiata appena a sud di Auberdine, poi riportale a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "810c736e", vanilla = true },
        progress = { it = "È solo di recente che queste creature hanno cominciato ad arenarsi sulla costa di Darkshore in numeri così allarmanti. Non posso fare a meno di pensare che sia un presagio funesto. Recuperare un campione delle ossa di quella creatura a sud ci aiuterebbe, a Darnassus, a valutare la situazione!", enHash = "143b245f", vanilla = true },
        reward = { it = "Spero che i murloc non ti abbiano dato troppo filo da torcere! Farò in modo che parta con il prossimo ippogrifo per Darnassus. Il Temple of the Moon mi ha dato dei fondi da distribuire per l'aiuto ricevuto: prendine un po', con i nostri ringraziamenti.\n\nIl tuo successo qui mi incoraggia a offrirti la possibilità di aiutare ancora il Temple of the Moon, se ti interessa...", enHash = "9e40a429", vanilla = true },
    },
    [3525] = {
        title = { it = "Spegnere l'idolo", enHash = "b653b38f", vanilla = true },
        text = { it = "Vicino all'ingresso c'è un idolo che fa da forno macabro per i quilboar; quelle bestie... divorano letteralmente le persone che rapiscono nelle Barrens. Posso spegnere l'idolo e impedire che lo usino di nuovo, ma per farlo mi serve il tuo aiuto. Il mio piano: scortami fino all'idolo. Una volta arrivati, comincerò il rituale. Riuscirò a stento a comunicare con te, figurarsi a difendermi. Proteggimi mentre spengo l'idolo. Se mi abbattono, per noi è finita.\n\nSei con me?!", enHash = "7cea689d", vanilla = true },
        objectives = { it = "Scorta Belnistrasz fino all'idolo dei quilboar, a Razorfen Downs.\n\nProteggi Belnistrasz mentre esegue il rituale per spegnere l'idolo.", enHash = "167a01a9", vanilla = true },
        reward = { it = "L'improvvisa partenza di Belnistrasz ha lasciato dietro di sé un braciere ardente. Mentre fissi la fiamma, l'immagine di un grande drago rosso dalle ampie ali ti riempie la mente. La voce di Belnistrasz, più roca, ti parla direttamente.\n\n\"Davvero, mortali, siete gli eroi che speravo. Grazie a voi, il massacro che queste bestie compivano appartiene al passato. La mia fiducia nei mortali come te si è rinnovata ancora una volta. Prendi questo come ricompensa degna di $Gun eroe:un'eroina;.\"", enHash = "852abd68", vanilla = true },
    },
    [3526] = {
        title = { it = "Ingegneria goblin", enHash = "cef2f84a", vanilla = true },
        text = { it = "L'ingegneria di livello esperto si divide in due discipline distinte: gnomica e goblin. Ovviamente, l'ingegneria goblin è la scelta di tutti gli ingegneri brillanti. Impara a dominare il mondo con l'uso giudizioso di esplosivi ad alto potenziale e di attrezzature fantastiche!\n\n$N, leggi questo manuale. Se vuoi imparare l'ingegneria goblin, portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi assicurati che sia ciò che vuoi prima di portare a termine il suo incarico.", enHash = "2d65be6f", vanilla = true },
        objectives = { it = "Se vuoi saperne di più sull'ingegneria goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.", enHash = "fbea079d", vanilla = true },
        progress = { it = "Fiuto le nuove reclute come fiuto un'ottima polvere da mina — a un miglio di distanza. Sei $Gvenuto:venuta; a imparare come si padroneggia l'esplosione?", enHash = "bcc1428c", vanilla = true },
        reward = { it = "Be', $N, hai fatto bene a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria — gli gnomi e Gnomeregan, la loro casa irradiata, ne sono la prova. Ma per padroneggiare la disciplina dell'ingegneria goblin ci vogliono una mente salda e una mano ferma (e sottolineo FERMA).\n\nTieni le orecchie ben aperte, $N, e forse imparerai qualcosa.", enHash = "0e2d9422", vanilla = true },
    },
    [3527] = {
        title = { it = "La profezia di Mosh'aru", enHash = "f06ee442", vanilla = true },
        text = { it = "L'antica profezia di Mosh'aru parla di un modo per imprigionare l'essenza del dio Hakkar. Fu scritta su due tavolette e portata nella città troll di Zul'Farrak, a ovest di Gadgetzan.\n\nPortami le tavolette di Mosh'aru!\n\nLa prima tavoletta è custodita dal troll morto da tempo Theka the Martyr. Si dice che i suoi persecutori siano stati tramutati per maledizione in scarabei, e che ora zampettino intorno al suo santuario.\n\nLa seconda tavoletta è custodita dall'idromante Velratha, vicino alla vasca sacra di Gahz'rilla.\n\nQuando avrai le tavolette, portamele.", enHash = "f438b706", vanilla = true },
        objectives = { it = "Porta la First Mosh'aru Tablet e la Second Mosh'aru Tablet a Yeh'kinya, a Tanaris.", enHash = "9cce177e", vanilla = true },
        progress = { it = "Hai le tavolette della profezia di Mosh'aru, $N?\n\nQuando avrò le tavolette, le studierò e imparerò come imprigionare l'essenza di Hakkar!", enHash = "4d74d7bf", vanilla = true },
        reward = { it = "Ah, questo è un bene. Posso fondere insieme queste antiche tavolette, e poi studiarne i segreti nascosti.\n\nIl mio debito con te cresce, $N. E crescerà ancora.", enHash = "99552816", vanilla = true },
    },
    [3567] = {
        title = { it = "Fino in cima", enHash = "a6836c81", vanilla = true },
        reward = { it = "Ti piacerebbe vedere il panorama dalla cima di uno dei Twin Colossals? Posso mandartici io, $R.\n\nPensa però a come farai a scendere. È un viaggio di sola andata.", enHash = "1c2c698e", vanilla = true },
    },
    [3625] = {
        title = { it = "Armi demoniache di Azsharite incantate", enHash = "b624f3c3", vanilla = true },
        text = { it = "$N, la creazione di ogni arma richiederà un po' di tempo.\n\nInoltre, potrai usare il potere del Felcurse solo una volta ogni tre minuti. I suoi effetti indebolenti su Razelikh the Defiler e sui suoi servitori potrebbero avere una durata variabile. Per questo devi liberare il Felcurse solo al momento giusto!\n\nOra dammi un momento per forgiare la tua arma, $N.", enHash = "f8154b3e", vanilla = true },
        objectives = { it = "Aspetta che Galvan finisca di forgiare le armi.", enHash = "b9a6a6eb", vanilla = true },
        progress = { it = "Interrompere la forgiatura potrebbe dare un'arma imperfetta. Abbi pazienza, $N.", enHash = "595359e5", vanilla = true },
        reward = { it = "<Galvan si asciuga il sudore dalla fronte.>\n\nNon è mai esistito un ammazzademoni migliore, $N.", enHash = "07586570", vanilla = true },
    },
    [3626] = {
        title = { it = "Ritorno nelle Blasted Lands", enHash = "1854e83b", vanilla = true },
        text = { it = "L'ora della redenzione è vicina, $N. Devi tornare nelle Blasted Lands con le tue nuove armi e parlare con il Fallen Hero of the Horde per ricevere il tuo ultimo obiettivo.", enHash = "13920633", vanilla = true },
        objectives = { it = "Torna dal Fallen Hero of the Horde.", enHash = "10df61cc", vanilla = true },
        reward = { it = "Sembri $Gtemprato:temprata; dalle battaglie, $N. Sei $Gpronto:pronta; ad affrontare Razelikh e i suoi servitori?", enHash = "321de23c", vanilla = true },
    },
    [3629] = {
        title = { it = "Ingegneria goblin", enHash = "cef2f84a", vanilla = true },
        text = { it = "L'ingegneria di livello esperto si divide in due discipline distinte: gnomica e goblin. Mi prendo la briga di nominare l'ingegneria goblin solo perché sono un istruttore imparziale. Agli ingegneri goblin piace costruire cose che esplodono, e raramente badano a cosa si trovi sulla loro strada — nemmeno quando si tratta di loro stessi.\n\n$N, leggi questo manuale. Se vuoi imparare a farti saltare in aria, portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi assicurati che sia ciò che vuoi prima di portare a termine il suo incarico.", enHash = "99bf96fc", vanilla = true },
        objectives = { it = "Se vuoi saperne di più sull'ingegneria goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.", enHash = "fbea079d", vanilla = true },
        progress = { it = "Fiuto le nuove reclute come fiuto un'ottima polvere da mina — a un miglio di distanza. Sei $Gvenuto:venuta; a imparare come si padroneggia l'esplosione?", enHash = "bcc1428c", vanilla = true },
        reward = { it = "Be', $N, hai fatto bene a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria — gli gnomi e Gnomeregan, la loro casa irradiata, ne sono la prova. Ma per padroneggiare la disciplina dell'ingegneria goblin ci vogliono una mente salda e una mano ferma (e sottolineo FERMA).\n\nTieni le orecchie ben aperte, $N, e forse imparerai qualcosa.", enHash = "0e2d9422", vanilla = true },
    },
    [3630] = {
        title = { it = "Ingegneria gnomica", enHash = "5576bac1", vanilla = true },
        text = { it = "A livello esperto, l'ingegneria si divide in due discipline: gnomica e goblin. L'ingegneria gnomica è di gran lunga la migliore delle due! Si tratta di costruire congegni e dispositivi meravigliosi che migliorano la vita!\n\n$N, leggi questo manuale. Se vuoi saperne di più sull'ingegneria gnomica, porta il manuale a Tinkmaster Overspark, a Ironforge. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi accertati di esserne $Gsicuro:sicura; prima di portare a termine il suo incarico!", enHash = "7cb46718", vanilla = true },
        objectives = { it = "Se vuoi saperne di più sull'ingegneria gnomica, porta il Manual of Engineering Disciplines a Tinkmaster Overspark, a Ironforge.", enHash = "81f5c572", vanilla = true },
        progress = { it = "Sì, sì, a quali tue esigenze posso dedicarmi oggi? Evidentemente ho tutto il tempo per farlo, visto che non faccio altro che starmene qui mentre la nostra amata città giace in una nube di morte radioattiva.", enHash = "2221b036", vanilla = true },
        reward = { it = "Ah, $Gun giovane ingegnere:una giovane ingegnera; che vuole seguire l'unica, vera disciplina dell'ingegneria! Be', perdona il mio melodramma, $Gamico:amica;. Anche se la nostra situazione resta disperata, è sempre una bella giornata quando si vede $Gun altro ingegnere:un'altra ingegnera; rispondere alla chiamata della vera ingegneria!", enHash = "e6aeb77e", vanilla = true },
    },
    [3632] = {
        title = { it = "Ingegneria gnomica", enHash = "5576bac1", vanilla = true },
        text = { it = "A livello esperto, l'ingegneria si divide in due discipline: gnomica e goblin. L'ingegneria gnomica è di gran lunga la migliore delle due! Si tratta di costruire congegni e dispositivi meravigliosi che migliorano la vita!\n\n$N, leggi questo manuale. Se vuoi saperne di più sull'ingegneria gnomica, porta il manuale a Tinkmaster Overspark, qui a Ironforge. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi accertati di esserne $Gsicuro:sicura; prima di portare a termine il suo incarico!", enHash = "1c224e04", vanilla = true },
        objectives = { it = "Se vuoi saperne di più sull'ingegneria gnomica, porta il Manual of Engineering Disciplines a Tinkmaster Overspark, a Ironforge.", enHash = "81f5c572", vanilla = true },
        progress = { it = "Sì, sì, a quali tue esigenze posso dedicarmi oggi? Evidentemente ho tutto il tempo per farlo, visto che non faccio altro che starmene qui mentre la nostra amata città giace in una nube di morte radioattiva.", enHash = "2221b036", vanilla = true },
        reward = { it = "Ah, $Gun giovane ingegnere:una giovane ingegnera; che vuole seguire l'unica, vera disciplina dell'ingegneria! Be', perdona il mio melodramma, $Gamico:amica;. Anche se la nostra situazione resta disperata, è sempre una bella giornata quando si vede $Gun altro ingegnere:un'altra ingegnera; rispondere alla chiamata della vera ingegneria!", enHash = "e6aeb77e", vanilla = true },
    },
    [3633] = {
        title = { it = "Ingegneria goblin", enHash = "cef2f84a", vanilla = true },
        text = { it = "L'ingegneria di livello esperto si divide in due discipline distinte: gnomica e goblin. Ovviamente, l'ingegneria goblin è la scelta di tutti gli ingegneri brillanti. Impara a dominare il mondo con l'uso giudizioso di esplosivi ad alto potenziale e di attrezzature fantastiche!\n\n$N, leggi questo manuale. Se vuoi imparare l'ingegneria goblin, portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi assicurati che sia ciò che vuoi prima di portare a termine il suo incarico.", enHash = "2d65be6f", vanilla = true },
        objectives = { it = "Se vuoi saperne di più sull'ingegneria goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.", enHash = "fbea079d", vanilla = true },
        progress = { it = "Fiuto le nuove reclute come fiuto un'ottima polvere da mina — a un miglio di distanza. Sei $Gvenuto:venuta; a imparare come si padroneggia l'esplosione?", enHash = "a61edbd2", vanilla = true },
        reward = { it = "Be', $N, hai fatto bene a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria — gli gnomi e Gnomeregan, la loro casa irradiata, ne sono la prova. Ma per padroneggiare la disciplina dell'ingegneria goblin ci vogliono una mente salda e una mano ferma (e sottolineo FERMA).\n\nTieni le orecchie ben aperte, $N, e forse imparerai qualcosa.", enHash = "b98698be", vanilla = true },
    },
    [3634] = {
        title = { it = "Ingegneria gnomica", enHash = "5576bac1", vanilla = true },
        text = { it = "A livello esperto, l'ingegneria si divide in due discipline: gnomica e goblin. Anche se secondo me è uno spreco, dovresti conoscere la specializzazione gnomica. Gli ingegneri gnomici fanno oggetti e congegni che pretendono di cambiare il mondo, ma che raramente funzionano.\n\n$N, leggi questo manuale. Se vuoi imparare a fare fermacarte di metallo, porta il manuale a Tinkmaster Overspark, a Ironforge. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi accertati di esserne $Gsicuro:sicura; prima di portare a termine il suo incarico!", enHash = "b3fc5853", vanilla = true },
        objectives = { it = "Se vuoi saperne di più sull'ingegneria gnomica, porta il Manual of Engineering Disciplines a Tinkmaster Overspark, a Ironforge.", enHash = "81f5c572", vanilla = true },
        progress = { it = "Sì, sì, a quali tue esigenze posso dedicarmi oggi? Evidentemente ho tutto il tempo per farlo, visto che non faccio altro che starmene qui mentre la nostra amata città giace in una nube di morte radioattiva.", enHash = "29bfdfee", vanilla = true },
        reward = { it = "Ah, $Gun giovane ingegnere:una giovane ingegnera; che vuole seguire l'unica, vera disciplina dell'ingegneria! Be', perdona il mio melodramma, $Gamico:amica;. Anche se la nostra situazione resta disperata, è sempre una bella giornata quando si vede $Gun altro ingegnere:un'altra ingegnera; rispondere alla chiamata della vera ingegneria!", enHash = "69aaf2e6", vanilla = true },
    },
    [3635] = {
        title = { it = "Ingegneria gnomica", enHash = "5576bac1", vanilla = true },
        text = { it = "A livello esperto, l'ingegneria si divide in due discipline: gnomica e goblin. Anche se secondo me è uno spreco, dovresti conoscere la specializzazione gnomica. Gli ingegneri gnomici fanno oggetti e congegni che pretendono di cambiare il mondo, ma che funzionano di rado.\n\n$N, leggi questo manuale. Se vuoi imparare a fare fermacarte di metallo, porta il manuale a Oglethorpe Obnoticus, a Booty Bay. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi accertati di esserne $Gsicuro:sicura; prima di portare a termine il suo incarico.", enHash = "3d9a7d72", vanilla = true },
        objectives = { it = "Se vuoi saperne di più sull'ingegneria gnomica, porta il Manual of Engineering Disciplines a Oglethorpe Obnoticus, a Booty Bay.", enHash = "bdf27ee8", vanilla = true },
        progress = { it = "Salve! Se sei $Gvenuto:venuta; per un robot autoguidato che potrebbe aver sfondato un muro del tuo domicilio, ti rimando fin d'ora al mio legale. Altrimenti, cosa posso fare per te oggi?", enHash = "97becfa1", vanilla = true },
        reward = { it = "Sei $Gvenuto:venuta; a imparare l'ingegneria gnomica, eh? Be', sei $Gcapitato:capitata; dallo gnomo giusto. La fazione al potere a Gnomeregan può anche usare la politica per emarginare chi considera una minaccia intellettuale, ma sa che la conoscenza è qualcosa che non può controllare.\n\nLo sappiamo bene sia loro che io: quando ho lasciato Gnomeregan, hanno perso uno dei più grandi ingegneri gnomi oggi in vita. Se sei $Gun allievo capace:un'allieva capace;, ti insegnerò quello che so.", enHash = "0403bceb", vanilla = true },
    },
    [3636] = {
        title = { it = "Porta la Luce", enHash = "0c176f99", vanilla = true },
        text = { it = "Il Flagello è una minaccia costante per l'Alleanza, un fatto che di certo conosci bene. Di recente abbiamo fatto alcune scoperte molto singolari, $N.\n\nNelle Barrens si trova un orrendo intrico di rovi chiamato Razorfen Downs. Un tempo era la casa di semplici quilboar, ma ora è chiaro che è stato stretto un patto con il Flagello, che ha generato creature molto peggiori... Ora li governa il lich Amnennar the Coldbringer.\n\nSchierati con la Luce, $N; poni fine a questa unione malvagia.", enHash = "9cb0e01d", vanilla = true },
        objectives = { it = "Archbishop Benedictus vuole che tu uccida Amnennar the Coldbringer, a Razorfen Downs.", enHash = "2fd8892b", vanilla = true },
        progress = { it = "Amnennar va estirpato. Va', presto.", enHash = "e4b88c0a", vanilla = true },
        reward = { it = "Grazie, $N. Ora il Flagello ci penserà due volte prima di tentare di nuovo di rinforzare le sue file.\n\nChe la Luce ti benedica.", enHash = "9cb7ab54", vanilla = true },
    },
    [3637] = {
        title = { it = "Ingegneria gnomica", enHash = "5576bac1", vanilla = true },
        text = { it = "A livello esperto, l'ingegneria si divide in due discipline: gnomica e goblin. Anche se secondo me è uno spreco, dovresti conoscere la specializzazione gnomica. Gli ingegneri gnomici fanno oggetti e congegni che pretendono di cambiare il mondo, ma che funzionano di rado.\n\n$N, leggi questo manuale. Se vuoi imparare a fare fermacarte di metallo, porta il manuale a Oglethorpe Obnoticus, a Booty Bay. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi accertati di esserne $Gsicuro:sicura; prima di portare a termine il suo incarico.", enHash = "3d9a7d72", vanilla = true },
        objectives = { it = "Se vuoi saperne di più sull'ingegneria gnomica, porta il Manual of Engineering Disciplines a Oglethorpe Obnoticus, a Booty Bay.", enHash = "bdf27ee8", vanilla = true },
        progress = { it = "Salve! Se sei $Gvenuto:venuta; per un robot autoguidato che potrebbe aver sfondato un muro del tuo domicilio, ti rimando fin d'ora al mio legale. Altrimenti, cosa posso fare per te oggi?", enHash = "97becfa1", vanilla = true },
        reward = { it = "Sei $Gvenuto:venuta; a imparare l'ingegneria gnomica, eh? Be', sei $Gcapitato:capitata; dallo gnomo giusto. La fazione al potere a Gnomeregan può anche usare la politica per emarginare chi considera una minaccia intellettuale, ma sa che la conoscenza è qualcosa che non può controllare.\n\nLo sappiamo bene sia loro che io: quando ho lasciato Gnomeregan, hanno perso uno dei più grandi ingegneri gnomi oggi in vita. Se sei $Gun allievo capace:un'allieva capace;, ti insegnerò quello che so.", enHash = "0403bceb", vanilla = true },
    },
    [3638] = {
        title = { it = "Il Pledge of Secrecy", enHash = "b4a62f49", vanilla = true },
        text = { it = "L'ingegneria goblin punta agli usi pratici, per profitti alti e una potenza esplosiva ancora più alta! I nostri schemi ci permettono di costruire bombe potenti e armi formidabili; il manuale che hai letto ne parlava.\n\nIl manuale parlava anche del nostro antichissimo giuramento di segretezza sui nostri schemi. Una volta che diventi $Gingegnere:ingegnera; goblin, la cosa è decisa. E non potrai più accedere in alcun modo all'ingegneria gnomica.\n\nSe vuoi ancora diventare $Gingegnere:ingegnera; goblin, firma questo documento con cui ti impegni a mantenere il segreto per tutta la vita, e torna a parlarmi. Pensaci bene, $N.", enHash = "69ca59e8", vanilla = true },
        objectives = { it = "Se accetti di diventare $Gingegnere:ingegnera; goblin, fai clic destro sul Pledge of Secrecy e parla di nuovo con Nixx Sprocketspring, a Gadgetzan.", enHash = "b395b827", vanilla = true },
        progress = { it = "Se hai firmato il documento e sei $Gpronto:pronta; a consegnarmelo, la cosa è decisa. Ti è stato detto che è un viaggio di sola andata. Se sei $Gpronto:pronta;, sali a bordo!", enHash = "c66eb55c", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta; a bordo, $Gingegnere:ingegnera; goblin $N! Presto avrai accesso agli schemi d'ingegneria più potenti di tutta Azeroth.\n\nOra che ti sei $Gimpegnato:impegnata; a perseguire questa conoscenza, è il momento di esaminare i tuoi lavori d'ingegneria di stampo goblin. Da lì, ti aiuteremo a mettere a punto un piano per sfruttare al massimo il tuo talento per l'ingegneria goblin!", enHash = "eb62948b", vanilla = true },
    },
    [3639] = {
        title = { it = "Mostrami il tuo lavoro", enHash = "8217557b", vanilla = true },
        text = { it = "Come tuo mentore, voglio dei campioni del tuo lavoro. Sei $Gun ingegnere abile:un'ingegnera abile;, su questo non c'è dubbio, $N. Quello che spero di fare, però, è analizzarli per capire come dare più spazio alle tecniche goblin nei tuoi lavori futuri. Ecco cosa mi serve: venti Big Iron Bomb, venti candelotti di Solid Dynamite e cinque Explosive Sheep — e tieni le sicure inserite!\n\nConsegnami questi oggetti e ti rilascerò la tua Goblin Engineer Membership Card personale; serve per rivolgerti a tutti gli istruttori d'ingegneria goblin!", enHash = "072a0197", vanilla = true },
        objectives = { it = "Porta 20 Big Iron Bomb, 20 Solid Dynamite e 5 Explosive Sheep a Nixx Sprocketspring, a Gadgetzan.", enHash = "8d8b01ff", vanilla = true },
        progress = { it = "Appena riceverò gli oggetti d'ingegneria che hai fabbricato, perché io li esamini, ti consegnerò un'autentica Goblin Engineer Membership Card! Finché la tessera è valida, potrai rivolgerti senza limiti a qualsiasi istruttore d'ingegneria goblin, ovunque nel mondo.", enHash = "39ce0dd7", vanilla = true },
        reward = { it = "Ecco la tua prima Goblin Engineer Membership Card!\n\nLa quota di questa tessera è già pagata in anticipo per quattordici giorni; tutte le tessere scadono dopo due settimane di attività. Quando scade, paga la quota successiva a qualsiasi istruttore d'ingegneria goblin per avere un'altra tessera; senza tessera, la tua iscrizione resterà temporaneamente sospesa e non potrai accedere a nuovi schemi.\n\nQuesto non cambia mai quello che sai già: $Gingegnere:ingegnera; goblin una volta, $Gingegnere:ingegnera; goblin per sempre.", enHash = "463803a5", vanilla = true },
    },
    [3640] = {
        title = { it = "Il Pledge of Secrecy", enHash = "b4a62f49", vanilla = true },
        text = { it = "L'ingegneria gnomica è teoria ingegneristica plasmata per servire i nostri bisogni! I nostri schemi ci permettono di costruire dispositivi che controllano il mondo intorno a noi; il manuale che hai letto ne parlava.\n\nIl manuale parlava anche del nostro antichissimo giuramento di segretezza sui nostri schemi. Una volta che diventi $Gingegnere gnomico:ingegnera gnomica;, la cosa è decisa. E non potrai più accedere in alcun modo all'ingegneria goblin.\n\nSe vuoi ancora diventare $Gingegnere gnomico:ingegnera gnomica;, firma questo documento con cui ti impegni a mantenere il segreto per tutta la vita, e torna a parlarmi. Pensaci bene, $N.", enHash = "40fc4e56", vanilla = true },
        objectives = { it = "Se accetti di diventare $Gingegnere gnomico:ingegnera gnomica;, fai clic destro sul Pledge of Secrecy e parla di nuovo con Tinkmaster Overspark, a Ironforge.", enHash = "f93acae8", vanilla = true },
        progress = { it = "Se hai firmato il documento e sei $Gpronto:pronta; a consegnarmelo, la cosa è decisa.\n\nI segreti che condividerò con te sono di tale portata che la firma del Pledge of Secrecy è assolutamente indispensabile. L'ho firmato anch'io, come i miei fratelli e le mie sorelle dell'ingegneria gnomica. Entrerai a far parte di una cerchia di tutto rispetto, $Gingegnere:ingegnera; $N!", enHash = "fb33aea7", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta; a bordo, $N! Presto avrai accesso agli schemi d'ingegneria più avanzati di tutta Azeroth.\n\nOra che ti sei $Gimpegnato:impegnata; a perseguire questa conoscenza, è il momento di esaminare i tuoi lavori d'ingegneria di stampo gnomico. Da lì, ti aiuteremo a mettere a punto un piano per sfruttare al massimo il tuo talento per l'ingegneria gnomica!", enHash = "07aca7cb", vanilla = true },
    },
    [3641] = {
        title = { it = "Mostrami il tuo lavoro", enHash = "8217557b", vanilla = true },
        text = { it = "Come tuo mentore, voglio qualche campione del tuo lavoro. Sei $Gun ingegnere abile:un'ingegnera abile;, su questo non c'è dubbio, $N. Quello che spero di fare, però, è analizzare il tuo lavoro per capire come dare più spazio alle tecniche gnomiche nei tuoi lavori futuri. Mi servono questi campioni: sei Mithril Tube, un Accurate Scope e due Advanced Target Dummy.\n\nConsegnami questi oggetti e ti rilascerò la tua Gnome Engineer Membership Card personale; serve per rivolgerti a tutti gli istruttori d'ingegneria gnomica!", enHash = "1774a51b", vanilla = true },
        objectives = { it = "Porta 6 Mithril Tube, un Accurate Scope e 2 Advanced Target Dummy a Tinkmaster Overspark, a Ironforge.", enHash = "846890cb", vanilla = true },
        progress = { it = "Appena riceverò gli oggetti d'ingegneria che hai fabbricato, perché io li esamini, ti consegnerò un'autentica Gnome Engineer Membership Card! Finché la tessera è valida, potrai rivolgerti senza limiti a qualsiasi istruttore d'ingegneria gnomica, ovunque nel mondo.", enHash = "9aeda585", vanilla = true },
        reward = { it = "Ecco la tua prima Gnome Engineer Membership Card!\n\nLa quota di questa tessera è già pagata in anticipo per quattordici giorni; tutte le tessere scadono dopo due settimane di attività. Quando scade, paga la quota successiva a qualsiasi istruttore d'ingegneria gnomica per avere un'altra tessera; senza tessera, la tua iscrizione resterà temporaneamente sospesa e non potrai accedere a nuovi schemi.\n\nQuesto non cambia mai quello che sai già: $Gingegnere gnomico:ingegnera gnomica; una volta, $Gingegnere gnomico:ingegnera gnomica; per sempre.", enHash = "080aef65", vanilla = true },
    },
    [3642] = {
        title = { it = "Il Pledge of Secrecy", enHash = "b4a62f49", vanilla = true },
        text = { it = "L'ingegneria gnomica è teoria ingegneristica plasmata per servire i nostri bisogni! I nostri schemi ci permettono di costruire dispositivi che controllano il mondo intorno a noi; il manuale che hai letto ne parlava.\n\nIl manuale parlava anche del nostro antichissimo giuramento di segretezza sui nostri schemi. Una volta che diventi $Gingegnere gnomico:ingegnera gnomica;, la cosa è decisa. E non potrai più accedere in alcun modo all'ingegneria goblin.\n\nSe vuoi ancora diventare $Gingegnere gnomico:ingegnera gnomica;, firma questo documento con cui ti impegni a mantenere il segreto per tutta la vita, e torna a parlarmi. Pensaci bene, $N.", enHash = "40fc4e56", vanilla = true },
        objectives = { it = "Se accetti di diventare $Gingegnere gnomico:ingegnera gnomica;, fai clic destro sul Pledge of Secrecy e parla di nuovo con Oglethrope Obnoticus, a Booty bay.", enHash = "5bb76838", vanilla = true },
        progress = { it = "Se hai firmato il documento e sei $Gpronto:pronta; a consegnarmelo, la cosa è decisa.\n\nPotrò anche essere in totale disaccordo politico con Gnomeregan — specialmente con quello sciocco di Tinkmaster Overspark — ma il Pledge of Secrecy è al di sopra di tutto! Devi accettare di seguire un'unica strada e restarle fedele per tutta la vita.", enHash = "a075166d", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta; a bordo, $N! Presto avrai accesso agli schemi d'ingegneria più avanzati di tutta Azeroth.\n\nOra che ti sei $Gimpegnato:impegnata; a perseguire questa conoscenza, è il momento di esaminare i tuoi lavori d'ingegneria di stampo gnomico. Da lì, ti aiuteremo a mettere a punto un piano per sfruttare al massimo il tuo talento per l'ingegneria gnomica!", enHash = "1bcbdca9", vanilla = true },
    },
    [3643] = {
        title = { it = "Mostrami il tuo lavoro", enHash = "8217557b", vanilla = true },
        text = { it = "Come tuo mentore, voglio qualche campione del tuo lavoro. Sei $Gun ingegnere abile:un'ingegnera abile;, su questo non c'è dubbio, $N. Quello che spero di fare, però, è analizzare il tuo lavoro per capire come dare più spazio alle tecniche gnomiche nei tuoi lavori futuri. Mi servono questi campioni: sei Mithril Tube, un Accurate Scope e due Advanced Target Dummy.\n\nConsegnami questi oggetti e ti rilascerò la tua Gnome Engineer Membership Card personale; serve per rivolgerti a tutti gli istruttori d'ingegneria gnomica!", enHash = "1774a51b", vanilla = true },
        objectives = { it = "Porta 6 Mithril Tube, un Accurate Scope e 2 Advanced Target Dummy a Oglethorpe Obnoticus, a Booty Bay.", enHash = "b4e91082", vanilla = true },
        progress = { it = "Appena riceverò gli oggetti d'ingegneria che hai fabbricato, perché io li esamini, ti consegnerò un'autentica Gnome Engineer Membership Card! Finché la tessera è valida, potrai rivolgerti senza limiti a qualsiasi istruttore d'ingegneria gnomica, ovunque nel mondo.", enHash = "5cc4ee99", vanilla = true },
        reward = { it = "Ecco la tua prima Gnome Engineer Membership Card!\n\nLa quota di questa tessera è già pagata in anticipo per quattordici giorni; tutte le tessere scadono dopo due settimane di attività. Quando scade, paga la quota successiva a qualsiasi istruttore d'ingegneria gnomica per avere un'altra tessera; senza tessera, la tua iscrizione resterà temporaneamente sospesa e non potrai accedere a nuovi schemi.\n\nQuesto non cambia mai quello che sai già: $Gingegnere gnomico:ingegnera gnomica; una volta, $Gingegnere gnomico:ingegnera gnomica; per sempre.", enHash = "8760d8bb", vanilla = true },
    },
    [3644] = {
        title = { it = "Rinnovo della tessera d'iscrizione", enHash = "112ae272", vanilla = true },
        progress = { it = "Per rinnovare la tua tessera d'iscrizione, dovrai pagare la quota di rinnovo di due monete d'oro.", enHash = "c9778561", vanilla = true },
        reward = { it = "Visto che pratichi l'ingegneria goblin e sei in regola, posso rinnovarti una tessera d'iscrizione scaduta per la quota di due monete d'oro. Una volta pagata la quota, ti verrà rilasciata una nuova tessera. Ti permetterà di accedere agli schemi d'ingegneria goblin presso gli istruttori competenti.\n\nQuesta tessera durerà due settimane di attività, al termine delle quali dovrai pagare di nuovo la quota d'iscrizione! Se vuoi accedere agli schemi, dovrai metterti in pari con i pagamenti arretrati.", enHash = "b236d8ce", vanilla = true },
    },
    [3645] = {
        title = { it = "Rinnovo della tessera d'iscrizione", enHash = "112ae272", vanilla = true },
        progress = { it = "Per rinnovare la tua tessera d'iscrizione, dovrai pagare la quota di rinnovo di due monete d'oro.", enHash = "c9778561", vanilla = true },
        reward = { it = "Visto che pratichi l'ingegneria gnomica e sei in regola, posso rinnovarti una tessera d'iscrizione scaduta per la quota di due monete d'oro. Una volta pagata la quota, ti verrà rilasciata una nuova tessera. Ti permetterà di accedere agli schemi d'ingegneria gnomica presso gli istruttori competenti.\n\nQuesta tessera durerà due settimane di attività, al termine delle quali dovrai pagare di nuovo la quota d'iscrizione! Se vuoi accedere agli schemi, dovrai metterti in pari con i pagamenti arretrati.", enHash = "4764e9dc", vanilla = true },
    },
    [3646] = {
        title = { it = "Rinnovo della tessera d'iscrizione", enHash = "112ae272", vanilla = true },
        progress = { it = "Per rinnovare la tua tessera d'iscrizione, dovrai pagare la quota di rinnovo di due monete d'oro.", enHash = "c9778561", vanilla = true },
        reward = { it = "Visto che pratichi l'ingegneria goblin e sei in regola, posso rinnovarti una tessera d'iscrizione scaduta per la quota di due monete d'oro. Una volta pagata la quota, ti verrà rilasciata una nuova tessera. Ti permetterà di accedere agli schemi d'ingegneria goblin presso gli istruttori competenti.\n\nQuesta tessera durerà due settimane di attività, al termine delle quali dovrai pagare di nuovo la quota d'iscrizione! Se vuoi accedere agli schemi, dovrai metterti in pari con i pagamenti arretrati.", enHash = "75499f78", vanilla = true },
    },
    [3647] = {
        title = { it = "Rinnovo della tessera d'iscrizione", enHash = "112ae272", vanilla = true },
        progress = { it = "Per rinnovare la tua tessera d'iscrizione, dovrai pagare la quota di rinnovo di due monete d'oro.", enHash = "c9778561", vanilla = true },
        reward = { it = "Visto che pratichi l'ingegneria gnomica e sei in regola, posso rinnovarti una tessera d'iscrizione scaduta per la quota di due monete d'oro. Una volta pagata la quota, ti verrà rilasciata una nuova tessera. Ti permetterà di accedere agli schemi d'ingegneria gnomica presso gli istruttori competenti.\n\nQuesta tessera durerà due settimane di attività, al termine delle quali dovrai pagare di nuovo la quota d'iscrizione! Se vuoi accedere agli schemi, dovrai metterti in pari con i pagamenti arretrati.", enHash = "4764e9dc", vanilla = true },
    },
    [3681] = {
        title = { it = "Tome of Divinity", enHash = "ea461054", vanilla = true },
        text = { it = "Scusa se interrompo i tuoi viaggi, $R, ma ho pensato che dovessi sapere che di recente è arrivato un messaggio da Stormwind che chiede ai paladini di presentarsi là per l'addestramento.\n\nSe non sbaglio, direi che sei $Gvicino:vicina; a un momento speciale, ed è ora che cominci a studiare i Tome.\n\nCerca Duthorian Rall a Stormwind. Di solito addestra i paladini nella Cathedral of Light.", enHash = "0772044d", vanilla = true },
        objectives = { it = "Parla con Duthorian Rall, a Stormwind.", enHash = "49eb4505", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta; nella Cathedral of Light, $C.", enHash = "e641c784", vanilla = true },
    },
    [3741] = {
        title = { it = "Hilary's Necklace", enHash = "c5c036cd", vanilla = true },
        text = { it = "La mia amica Hilary ha perso la collana, e non riusciamo a trovarla. Abbiamo pescato qui tutto il giorno, e qui intorno abbiamo già guardato. L'unica cosa che mi viene in mente è che sia caduta nel lago. I nostri genitori non vogliono che nuotiamo nel lago... mia mamma dice che sott'acqua ci sono cose cattive, ma tu non sembri $Guno:una; che ha paura delle cose cattive.\n\nLa troveresti per lei, per favore?", enHash = "7a6a7c4a", vanilla = true },
        objectives = { it = "Trova Hilary's Necklace e riportala a Hilary, a Lakeshire.", enHash = "6102810b", vanilla = true },
        progress = { it = "Ciao. Mi manca la mia collana. Me l'ha presa il mio papà. Papà dice che nel lago ci sono i mostri. Hai picchiato qualche mostro?", enHash = "35501a18", vanilla = true },
        reward = { it = "Grazie per aver trovato la mia collana, $Gsignor:signorina; $C... sei molto gentile! Ti ringrazia anche il mio gattino — vero, Effsee?", enHash = { "85bd929d", "777c468b" }, vanilla = true },
    },
    [3761] = {
        title = { it = "Un'Goro Soil", enHash = "b5b9f1ac", vanilla = true },
        text = { it = "Si dice che la terra dell'Un'Goro Crater sia ricca di potenti qualità magiche. Il Cenarion Circle vuole studiarla in grandi quantità; addentrati nelle terre selvagge di Un'Goro e procuratene abbastanza per proseguire le nostre ricerche.\n\nQua e là la terra fertile affiora in mucchi, e alcune bestie potrebbero averne addosso dei campioni utilizzabili. Portali tutti fuori, da Ghede; basta cercare i mucchi di terra e il tauren che abbaia ordini. Ha buone intenzioni, ma non farlo arrabbiare!", enHash = "2cfbfb83", vanilla = true },
        objectives = { it = "Porta 20 Un'Goro Soil a Ghede, sull'Elder Rise di Thunder Bluff.", enHash = "481ad52e", vanilla = true },
        progress = { it = "Riposo, $Gsoldato:soldatessa;. Se sei qui per scaricare terra di Un'Goro, magnifico! Altrimenti, sparisci.", enHash = "aad9f77a", vanilla = true },
        reward = { it = "Ma certo, $Gsoldato:soldatessa; $N, non fare il minimo sforzo per aiutarmi a scaricare questa terra sui mucchi! Se i Grandi Spiriti avessero voluto che fosse fatto, ce l'avrebbero portata lassù per miracolo, non ti pare?!\n\nArch Druid Runetotem vuole parlarti di nuovo, ma per il suo prossimo incarico scopri che ti sarebbe utile una conoscenza dell'erbalismo di livello Journeyman. Se però non ce l'hai, troverà comunque un modo di impiegarti.", enHash = "0b529832", vanilla = true },
    },
    [3762] = {
        title = { it = "Aiutare Arch Druid Runetotem", enHash = "0e20aaa9", vanilla = true },
        text = { it = "Scusami, $C, ma vorrei solo un momento del tuo tempo, se possibile.\n\nIl Cenarion Circle di Thunder Bluff è molto interessato ad avventurieri esperti come te che lo aiutino in un progetto di ricerca vitale. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che Hamuul Runetotem.\n\nTi prego, se ti interessa, parla direttamente con lui sull'Elder Rise, dentro Thunder Bluff.", enHash = "4b7aee48", vanilla = true },
        objectives = { it = "Parla con Arch Druid Hamuul Runetotem, a Thunder Bluff.", enHash = "f6be8abc", vanilla = true },
        reward = { it = "Salve, $C; sono lieto che tu voglia aiutare la nostra ricerca. C'è molto da fare, e ti renderei un cattivo servizio se ti dicessi che questo lavoro non è pericoloso. Spero che questo non ti spaventi... ma, a giudicare dal tuo aspetto, direi che col pericolo hai già avuto a che fare.", enHash = "e63ed9b9", vanilla = true },
    },
    [3765] = {
        title = { it = "La corruzione lontano da qui", enHash = "5b9c6db7", vanilla = true },
        text = { it = "Stormwind — che centro brulicante di attività.\n\nHo viaggiato da lontano per cercare aiuto. Si sente dire spesso che avventurieri coraggiosi girano per queste strade.\n\nMio fratello, Gershala, ha bisogno di aiuto a Darkshore. Vive nella cittadina di mare di Auberdine.\n\nÈ un viaggio lungo ed epico. Per questo chiedo l'aiuto di $Gun:una; $C $Gesperto:esperta; come te.", enHash = "1cbdb001", vanilla = true },
        objectives = { it = "Raggiungi Gershala Nightwhisper, ad Auberdine.", enHash = "184940b0", vanilla = true },
        reward = { it = "Ah, quindi ti manda mio fratello, Argos? Immagino che tu sia $Gstanco:stanca; per il viaggio. Ma abbiamo molto di cui parlare.", enHash = "698912d5", vanilla = true },
    },
    [3782] = {
        title = { it = "Ricerche sulla Morrowgrain", enHash = "52860aea", vanilla = true },
        text = { it = "Con quella che chiamiamo Evergreen Pouch, abbiamo coltivato semi di Tharlendris nella terra dell'Un'Goro Crater. Da questi semi sono sbocciate, in modo imprevedibile, erbe potenti di ogni genere. Una di queste è la Morrowgrain, un'erba misteriosa di cui sappiamo poco; spero davvero di svelare questo mistero per il Circle.\n\nPorta questo buono a mia figlia Bashana, e lei ti darà dei semi, così potrai aiutarci. Se li finisci, dovrai comprarne altri da lei.", enHash = "f69818a6", vanilla = true },
        objectives = { it = "Porta il Seed Voucher a Bashana Runetotem, a Thunder Bluff.", enHash = "e546a5d5", vanilla = true },
        progress = { it = "Pace a te, $Gamico:amica;. Sei qui per conto dell'arcidruido in persona, vero?", enHash = "1d413733", vanilla = true },
        reward = { it = "Sì, questo buono vale venti pacchetti di semi. Se finisci i semi, ne ho altri che posso venderti.\n\nPurtroppo, $N, produrre semi di Tharlendris in quantità significative è piuttosto costoso. Per questo il Cenarion Circle chiede a chi ci aiuta di contribuire coprendo parte della spesa. Chi torna con la Morrowgrain scopre che la ricompensa offerta dall'arcidruido ripaga ampiamente la spesa.", enHash = "39b9d5a5", vanilla = true },
    },
    [3786] = {
        title = { it = "Ricerche sulla Morrowgrain", enHash = "52860aea", vanilla = true },
        text = { it = "Ecco la tua Evergreen Pouch, che ti servirà per usare i semi di Tharlendris. Devi avere a portata di mano anche dei campioni di Un'Goro Soil, da usare come fertilizzante per i semi. Usa la sacca quando hai tutto; al resto penserà lei.\n\nQuando avrai abbastanza Morrowgrain, portala a me, qui sull'Elder Rise. Per favore, non disturbare l'arcidruido; sarà molto impegnato con la ricerca, oltre che con le mille preoccupazioni che ha!", enHash = "fa6352ff", vanilla = true },
        objectives = { it = "Usa una Evergreen Pouch con un Packet of Tharlendris Seeds e due Un'Goro Soil per provare a coltivare campioni di Morrowgrain.\n\nPorta 10 Morrowgrain a Bashana Runetotem, a Thunder Bluff.", enHash = "fcb82fb9", vanilla = true },
        progress = { it = "Sì, $N, hai coltivato un po' di Morrowgrain per l'importante ricerca dell'arcidruido? Le misteriose proprietà dell'Un'Goro Crater diventano più chiare ogni giorno che passa, grazie all'aiuto che ci stai dando.", enHash = "6135fa9a", vanilla = true },
        reward = { it = "Ben fatto, $N, mi assicurerò di consegnarla all'arcidruido in persona quando ne avrà bisogno. Nel frattempo, accetta questo come segno di gratitudine del Cenarion Circle.\n\nPer ora il nostro bisogno di Morrowgrain è costante; se vuoi continuare ad aiutarci, torna quando ne avrai coltivata altra.", enHash = "21d8d94e", vanilla = true },
    },
    [3787] = {
        title = { it = "La richiesta di Jonespyre", enHash = "3097488e", vanilla = true },
        text = { it = "Scusami, $Gamico:amica;...\n\nUn mio collega vorrebbe parlarti delle ricerche che stai facendo insieme al Cenarion Circle. È un druido di nome Quintis Jonespyre, e vive a Feathermoon Stronghold, nel Feralas. Vorrebbe confrontarsi con te sulla morrowgrain... e ci terrebbe molto che la nostra conversazione non arrivasse alle orecchie dell'arcidruido.\n\nSe ti interessa, parla con lui; di sicuro, una volta che l'avrai fatto, tutto ti sarà svelato.", enHash = "9a376378", vanilla = true },
        objectives = { it = "Parla con Quintis Jonespyre a Feathermoon Stronghold.", enHash = "0f6d3c85", vanilla = true },
        reward = { it = "Ti ringrazio di essere $Gvenuto:venuta;, $Gstanco viandante:stanca viandante;! Permettimi di presentarmi: sono Quintis Jonespyre, druido e umile servitore di Malfurion e del Cenarion Circle. I miei colleghi (General Shandris Feathermoon e il Protectorate: forse hai sentito parlare di noi) e io volevamo parlarti del lavoro che stai facendo per Fandral Staghelm a Darnassus.\n\nPrima di andare oltre, vorrei chiederti che la nostra conversazione resti fra noi. Se per te va bene, possiamo proseguire.", enHash = "dd09d202", vanilla = true },
    },
    [3789] = {
        title = { it = "Aiutare Arch Druid Staghelm", enHash = "5725a3e3", vanilla = true },
        text = { it = "Scusami, $C, ma vorrei solo un momento del tuo tempo, se possibile.\n\nIl Cenarion Circle di Darnassus cerca avventurieri esperti come te che lo aiutino in un progetto di ricerca vitale. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che Arch Druid Fandral Staghelm.\n\nTi prego, se ti interessa, parla direttamente con lui nel Cenarion Enclave, a Darnassus.", enHash = "2217d51c", vanilla = true },
        objectives = { it = "Parla con Arch Druid Fandral Staghelm a Darnassus.", enHash = "cd59863f", vanilla = true },
        reward = { it = "Bene, $C... visto che ti hanno detto che sono io a guidare questa ricerca, sei $Gvenuto:venuta; più in fretta che potevi, è evidente.\n\nOra che sei qui, mi raccomando, fa' attenzione la prima volta che ti spiego i dettagli: non ho nessuna voglia di ripetermi.", enHash = "144d2a42", vanilla = true },
    },
    [3804] = {
        title = { it = "Morrowgrain per Thunder Bluff", enHash = "8d142a99", vanilla = true },
        progress = { it = "L'arcidruido cerca sempre altra Morrowgrain per il progetto di ricerca del Cenarion Circle sull'Un'Goro Crater. La accettiamo a gruppi di dieci, e in cambio ti diamo una scorta di beni che dovresti trovare utili. Quando ne avrai dieci, fammelo sapere e ti ricompenserò di conseguenza.", enHash = "64e05670", vanilla = true },
        reward = { it = "Eccellente — questa Morrowgrain sarà senza dubbio utile quando verrà il momento. Sappiamo che gli elfi della notte stanno conducendo ricerche simili su queste erbe, anche se non è chiaro a che scopo le useranno, se scopriranno qualcosa. L'arcidruido pensa che il bisogno di Morrowgrain resterà finché non avremo svelato i misteri di quest'erba.\n\nQuesto è per te, $N. Il Cenarion Circle ti ringrazia per il tuo costante sostegno.", enHash = "fb9a3d1a", vanilla = true },
    },
    [3821] = {
        title = { it = "Dreadmaul Rock", enHash = "b65bfc80", vanilla = true },
        text = { it = "Sha'ni è stata mandata a indagare su strane attività rituali segnalate tra gli ogre Firegut delle Burning Steppes, più di tre settimane fa.\n\nGoretooth mi dice che non ha avuto notizie da nessuno di quel plotone e che è meglio che io vada avanti e mi concentri sul compito che ho davanti. Ci credi? È mia moglie!\n\nNon posso lasciare il mio posto, $N, ma devo sapere che fine ha fatto Sha'ni. Va' nelle Burning Steppes e cercala.", enHash = "6008c40f", vanilla = true },
        objectives = { it = "Avventurati nelle Burning Steppes e scopri che fine ha fatto Sha'ni Proudtusk.", enHash = "d208a2f6", vanilla = true },
        reward = { it = "Il mio povero Thal'trak.\n\nAvevamo in programma di andare a vivere con mia madre e mio padre nelle Hinterlands, finito il servizio. Ora quei progetti sono rovinati!", enHash = "bbaecd15", vanilla = true },
    },
    [3901] = {
        title = { it = "Scuotere i Rattlecage", enHash = "db0dd6a5" },
        text = { it = "Hai mostrato il tuo potenziale ai Reietti in circostanze normali, $N: ora vediamo come te la cavi sotto pressione.\n\nI Rattlecage Skeleton, altri servitori senza mente del Re dei Lich, sono un nemico più duro degli zombi che hai affrontato finora. Ancora una volta, riduci il loro numero e dimostra il tuo valore ai Reietti. Non indugiare: quando hai finito, torna a parlare con me.", enHash = "2259589b" },
        objectives = { it = "Uccidi 12 Rattlecage Skeleton, poi torna da Shadow Priest Sarvis a Deathknell.", enHash = "adb45fff" },
        progress = { it = "Chi perde tempo in questo compito rischia di finire a vagare senza meta come i nostri fratelli e sorelle caduti nel villaggio. Speriamo che a te vada meglio che a loro, vero?", enHash = "f00bf6b8" },
        reward = { it = "Con te ho finito, $N: hai dimostrato di essere $Gdegno:degna; della libertà che ti è stata concessa. Molti ti si opporranno per ciò che sei $Gdiventato:diventata;, ma sappi che, qualunque cosa tentino contro di noi, siamo liberi e non ci faremo incatenare di nuovo.\n\nPrendi queste cose e riprendi il tuo cammino. Hai molto da compiere, $C.", enHash = "638deee2" },
    },
    [3902] = {
        title = { it = "Recuperi a Deathknell", enHash = "794bb1e5" },
        text = { it = "Ehi, tu! Se cerchi un modo per renderti utile, ascolta bene!\n\nCi servono reclute appena uscite dalla terra che vadano a Deathknell a cercare qualunque tipo di equipaggiamento utile. Quasi di sicuro sarà nelle cataste di casse. Presto dovrebbero risvegliarsi altre reclute, e se non vogliamo che vadano in giro nude, ci conviene metterci a rovistare!\n\nForza, al lavoro, miserabile sacco d'ossa! Non ricompenso chi non si dà da fare.", enHash = "5d6784a8" },
        objectives = { it = "Cerca a Deathknell e nei dintorni 6 pezzi di Scavenged Goods, e portali a Deathguard Saltain.", enHash = "5d2e4603" },
        progress = { it = "Sei $Griuscito:riuscita; a recuperare qualcosa di utile per noi? Non c'è niente di male a riutilizzare ciò che è stato buttato via. Nessuno ci regalerà niente: noi Reietti ce la caveremo da soli!", enHash = "939da5d7" },
        reward = { it = "Ottimo lavoro, $N, sapevo che non eri inutile. Ecco, prendi uno degli oggetti migliori che ho trovato tra quelli raccolti finora.", enHash = "9c854ae2" },
    },
    [3903] = {
        title = { it = "Milly Osworth", enHash = "606debe7" },
        text = { it = "Ti sei $Gdimostrato:dimostrata; $Gun:una; $C affidabile, $N. Affidabile, e senza paura di sporcarti le mani, eh?\n\nHo un'amica, Milly Osworth, che è nei guai. È con il suo carro dall'altra parte dell'abbazia, vicino alla stalla. Sono sicuro che le farebbe comodo un paio di mani come le tue.", enHash = "0b68a797" },
        objectives = { it = "Parla con Milly Osworth.", enHash = "6bc87273" },
        reward = { it = "Oh, è stato Deputy Willem a dirti di parlare con me? È un uomo coraggioso e sempre pronto ad aiutare, ma i suoi doveri lo tengono bloccato alla Northshire Abbey, e temo che il problema che ho oggi vada al di là delle sue possibilità.\n\nForse tu puoi aiutarmi?", enHash = "d791d094" },
    },
    [3904] = {
        title = { it = "Milly's Harvest", enHash = "1c547012" },
        text = { it = "Una banda di briganti, i Defias, si è stabilita nelle Northshire Vineyards mentre vendemmiavo! L'ho denunciato alle guardie di Northshire e mi hanno assicurato che se ne sarebbero occupate, ma... temo per il mio raccolto d'uva! Se non la rubano i Defias, temo che la calpesteranno le nostre guardie mentre cacciano via quei delinquenti.\n\nTi prego, devi aiutarmi! Ho raccolto quasi tutta l'uva nei secchi, ma li ho lasciati nei vigneti a sud-est.\n\nPortami quelle casse! Salva il mio raccolto!", enHash = "f93c3b1d" },
        objectives = { it = "Porta 8 casse di Milly's Harvest a Milly Osworth, alla Northshire Abbey.", enHash = "06c8ba8b" },
        progress = { it = "Hai il mio raccolto, $N?", enHash = "bc9b4b8a" },
        reward = { it = "Oh, grazie, $N! Hai salvato il mio raccolto! E spero che tu abbia fatto capire a qualcuno di quei Defias che qui non possono creare guai.\n\nSaremo anche a corto di guardie di questi tempi, ma siamo fortunati ad avere eroi come te a proteggerci!", enHash = "7dc774ee" },
    },
    [3905] = {
        title = { it = "Grape Manifest", enHash = "16439164" },
        text = { it = "Ora che il mio raccolto è salvo, porta questo Grape Manifest a Brother Neals. Gestisce le scorte di cibo e bevande di Northshire, e sono sicura che sarà felicissimo di sapere che ha uva fresca.\n\nTroverai Brother Neals nell'abbazia, nel campanile... dove gli piace assaggiare il suo vino.", enHash = "ba9dea5e" },
        objectives = { it = "Porta il Grape Manifest a Brother Neals, nella Northshire Abbey.", enHash = "97679651" },
        progress = { it = "Hai l'aria di chi è di ottimo umore! Vieni! Siediti e bevi qualcosa!", enHash = "23e35e42" },
        reward = { it = "Vediamo un po'...\n\nOh, cielo! L'uva di Milly è salva! Quando mi ha detto che i briganti avevano invaso i suoi vigneti, per poco non mi sono disperato, ma la mia fede nella Luce non ha vacillato!\n\nE grazie al tuo coraggio ora abbiamo uva per altro vino! Che la Luce ti benedica, $N, e ti protegga!", enHash = "b2969e37" },
    },
    [3921] = {
        title = { it = "Wenikee Boltbucket", enHash = "68878afd", vanilla = true },
        text = { it = "Credo di aver rotto quel Samophlange. Non va bene, perché ne ho già parlato a certi colleghi a Undermine ed erano molto incuriositi. Dobbiamo trovare il modo di ripararlo!\n\nPorta il samophlange rotto a Wenikee Boltbucket, appena a sud del Mor'shan Rampart, l'avamposto dell'Orda fra le Barrens e Ashenvale. È molto sveglia e curiosa. Se le mostri il samophlange, scommetto che si butterebbe sull'occasione di ripararlo.", enHash = "c1acc3b9", vanilla = true },
        objectives = { it = "Porta il Broken Samophlange a Wenikee Boltbucket.", enHash = "8066154b", vanilla = true },
        progress = { it = "Sono molto presa dal mio lavoro, $C. Se non hai qualcosa per me, faresti meglio a tirare dritto...", enHash = "dd855b1f", vanilla = true },
        reward = { it = "Oh, e questo cos'è? Un samophlange, dici? E cos'è un samophlange??\n\nAh... ma guarda come si muove quando lo maneggi. E dentro si sente un rumore di ingranaggi intricati. Perbacco! Voglio ripararlo e vedere cosa fa, tu no??", enHash = "a4d4a45c", vanilla = true },
    },
    [3922] = {
        title = { it = "Nugget Slugs", enHash = "7d3bfa5e", vanilla = true },
        text = { it = "Voglio aggiustare questo samophlange, ma per farlo mi serve del materiale. Ho finito i nugget slug calibro diciassette virgola cinque, e me ne serve un mucchio per il lavoro che mi aspetta.\n\nIl posto più vicino dove trovarli è lo Sludge Fen, a est. La Venture Company di solito li tiene nei secchi degli attrezzi. Va' allo Sludge Fen, guarda nei secchi degli attrezzi che trovi là, e poi torna da me quando ne avrai raccolti abbastanza.", enHash = "f6287fa6", vanilla = true },
        objectives = { it = "Porta 15 Nugget Slug a Wenikee Boltbucket, nelle Barrens.", enHash = "ea16c17b", vanilla = true },
        progress = { it = "Li hai i nugget slug, $N? Sto adocchiando questo Samophlange e non vedo l'ora di metterci le mani.", enHash = "75dbfb76", vanilla = true },
        reward = { it = "Ottimo, li hai presi! Ora posso mettermi al lavoro...", enHash = "705d50e2", vanilla = true },
    },
    [3923] = {
        title = { it = "Rilli Greasygob", enHash = "9598349f", vanilla = true },
        text = { it = "Be', non ha funzionato. Ho messo qualche indicatore in più sul samophlange per misurarne l'integrità strutturale, e segnano il minimo storico. Potrei aggiungere qualche quadrante e magari una leva o due per provare a sistemarlo, ma... credo che peggiorerei solo le cose.\n\nDovresti portare il samophlange da Rilli Greasygob. Lavorava per la Venture Company — se c'è qualcuno che sa come aggiustarlo, è Rilli.\n\nLo trovi al Nogg's Machine Shop di Orgrimmar, nella Valley of Honor.", enHash = "82689714", vanilla = true },
        objectives = { it = "Porta il Broken and Battered Samophlange a Rilli Greasygob, a Orgrimmar.", enHash = "683ed3a6", vanilla = true },
        progress = { it = "$GAttento:Attenta; alla testa! Non voglio che finisca in mezzo al mio lavoro!", enHash = "af7e3f2b", vanilla = true },
        reward = { it = "E questo cos'è? Ma è un samophlange! Dove l'hai preso, questo coso? Sei $Gandato:andata; a ficcare il naso nei possedimenti della Venture Company nelle Barrens?\n\nDevi essere molto $Gcoraggioso:coraggiosa;, oppure molto $Gstupido:stupida;.", enHash = "c98e6a89", vanilla = true },
    },
    [3924] = {
        title = { it = "Samophlange Manual", enHash = "3640de37", vanilla = true },
        text = { it = "Credo di poter aggiustare il samophlange, ma prima mi serve il manuale d'uso. Quando stavo nella Venture Company avevo un rivale, Boss Copperplug, che teneva per sé i segreti del samophlange e ne distribuiva solo briciole a quelli di cui si fidava. Io non ero tra i pochi fidati...\n\nBoss Copperplug stava alla Boulder Lode Mine, nelle Barrens nord-orientali. Fatti dare il manuale da lui, e se ne ha dato delle pagine a qualcuno, dovrai raccogliere anche quelle.", enHash = "8eb795e5", vanilla = true },
        objectives = { it = "Porta il Samophlange Manual a Rilli Greasygob, a Orgrimmar.", enHash = "a8c65083", vanilla = true },
        progress = { it = "L'hai preso il manuale?", enHash = "b4b64428", vanilla = true },
        reward = { it = "Hai preso il manuale! Non vedo l'ora di leggerlo e scoprire come si aggiusta il Samophlange! Ho parlato con Sputtervalve a Ratchet — voleva ringraziarti per l'aiuto e ricompensare i tuoi sforzi.\n\nVoglio ringraziarti anch'io, e se mai riuscirò ad aggiustare questo coso te lo farò sapere...", enHash = "d57c2fc3", vanilla = true },
    },
    [4021] = {
        title = { it = "Contrattacco!", enHash = "8c56115d", vanilla = true },
        text = { it = "L'Orda si compiace dei tuoi successi contro i Kolkar, ma i Kolkar stessi sono inferociti. Mi riferiscono che un contingente di Kolkar è arrivato nelle Barrens dalla loro terra di Desolace per vendicarsi. Secondo l'ultimo rapporto, proprio in questo momento stanno muovendo contro questi bunker, da ovest!\n\nAffronta gli invasori Kolkar e poni fine alla loro minaccia nelle Barrens. Uccidili finché non compare il loro capo, Warlord Krom'zar. Sconfiggilo e portami un pezzo del suo stendardo come prova.\n\nContiamo su di te, $N.", enHash = "0b7e51e0", vanilla = true },
        objectives = { it = "Porta un Piece of Krom'zar's Banner a Regthar Deathgate, a ovest del Crossroads.", enHash = "648cccda", vanilla = true },
        progress = { it = "L'hai preso lo stendardo?", enHash = "6ece9982", vanilla = true },
        reward = { it = "Ce l'hai fatta! Hai sconfitto i Kolkar!\n\nFarò in modo che Thrall sappia di quello che hai fatto qui, $N.\n\nSta' a testa alta. Rendi fieri te $Gstesso:stessa; e l'Orda.", enHash = "95f994c7", vanilla = true },
    },
    [4062] = {
        title = { it = "L'ascesa delle macchine", enHash = "6b41507c", vanilla = true },
        text = { it = "G.L.A.\n\nSono queste le \"iniziali\" impresse sui frammenti elementali. Sotto le iniziali c'è una specie di segno di grado. Le macchine che hai distrutto nelle Burning Steppes erano di \"Rank IV\". Presumo che sia un grado basso.\n\nPorta questo campione di frammento a Lotwil Veriatus, nell'accampamento a est. È uno studioso di una certa fama nel campo delle scienze elementali. Potrebbe aiutarci nella nostra ricerca.", enHash = "1fa95111", vanilla = true },
        objectives = { it = "Porta l'Elemental Shard Sample a Lotwil Veriatus.\n\nRicordi che Theodora ha detto che Lotwil si trovava in un accampamento a est.", enHash = "d408efe1", vanilla = true },
        progress = { it = "Cos'hai lì, $R?", enHash = "171985ea", vanilla = true },
        reward = { it = "<Il volto di Lotwil diventa bianco.>\n\nIo... io conosco questi segni.", enHash = "efd507d5", vanilla = true },
    },
    [4124] = {
        title = { it = "Il corriere scomparso", enHash = "77e8cfc4", vanilla = true },
        text = { it = "Un mio collega, Ginro Hearthkindle, cerca aiuto per ritrovare un corriere e i pacchi che portava. È passata una settimana circa da quando il corriere è scomparso; le nostre ricerche non hanno dato frutti, e siamo a un punto morto. Purtroppo ho dovuto dichiarare il corriere disperso in azione.\n\nSe hai tempo e risorse da dedicarci, ti prego, parla con Ginro. Dovrebbe essere qui alla roccaforte, forse nei suoi alloggi.", enHash = "ab284fff", vanilla = true },
        objectives = { it = "Parla con Ginro Hearthkindle, alla Feathermoon Stronghold.", enHash = "0b928b8f", vanilla = true },
        reward = { it = "Ti manda Latro, immagino. Anche se a questo punto credo sia una causa persa, accetterò qualunque aiuto tu possa offrire. Devo ammetterlo... sarò contento quando potrò mettermi il cuore in pace su questa faccenda. Ogni giorno parto per le terre selvagge di Feralas in cerca di tracce di Raschal, e ogni sera torno senza niente da mostrare per il mio lavoro, a parte denti di gnoll e delusione.", enHash = "0e121f98", vanilla = true },
    },
    [4125] = {
        title = { it = "Il corriere scomparso", enHash = "77e8cfc4", vanilla = true },
        text = { it = "È passata circa una settimana da quando Raschal, il corriere, è partito per Thalanaar. Conosce bene Feralas; è con noi da quando il generale Feathermoon ha guidato qui le forze di spedizione. So che il suo piano era prendere una barca a remi, scendere lungo la costa e poi provare ad attraversare il sud di Feralas per evitare il campo dell'Orda.\n\nIo non sono riuscito a trovare la sua barca, ma forse tu ci riuscirai. Forse è nascosta, o forse è affondata. In ogni caso, potrebbe contenere un indizio su dove si trova lui. Se scopri qualcosa, fammelo sapere.", enHash = "4ded486d", vanilla = true },
        objectives = { it = "Trova la barca del corriere da qualche parte lungo la costa di Feralas.", enHash = "8799d362", vanilla = true },
        reward = { it = "Hai trovato quella che sembra una barca a remi naufragata. Attraverso l'acqua un po' fangosa vedi grossi squarci che crivellano la fiancata di babordo; la barca è quasi ridotta alla sua semplice ossatura di legno. Qualunque cosa l'abbia distrutta, molto probabilmente ha cercato di spezzarla in due. Sulla fiancata di tribordo è dipinto un piccolo stemma della Feathermoon Stronghold.\n\nNel fango, alla base della barca, qualcosa di metallico ti cattura lo sguardo con un luccichio...", enHash = "183fcf1f", vanilla = true },
    },
    [4127] = {
        title = { it = "Il relitto della barca", enHash = "d2dcf7cd", vanilla = true },
        text = { it = "Passando la mano nel fango, le tue dita sfiorano il manico di un coltello. Sembra ben tenuto, e si può presumere che chi era sulla barca l'abbia perso. Forse il grosso pezzo che manca alla barca ha qualcosa a che fare con la perdita.\n\nPrendi il coltello, ricordando che Ginro Hearthkindle, alla Feathermoon Stronghold, ti ha chiesto di tornare da lui con ogni indizio trovato. Hai però la sensazione di non essere del tutto $Gsolo:sola; nell'acqua...", enHash = "b12d0b11", vanilla = true },
        objectives = { it = "Torna alla Feathermoon Stronghold e mostra a Ginro Hearthkindle il Discarded Knife che hai trovato.", enHash = "9e18841d", vanilla = true },
        progress = { it = "Ah, $Gbentornato:bentornata;, $N. Spero che tu sia $Griuscito:riuscita; a scoprire qualche indizio sulla sorte di Raschal, per quanto tragica possa essere.", enHash = "a4d7ace3", vanilla = true },
        reward = { it = "Interessante... credo che questo sia il coltello di Raschal. Dici di averlo trovato sul fondo dell'acqua, insieme alla sua barca? Be', il ritrovamento del coltello da solo potrebbe non bastare a collegarlo alla scomparsa di Raschal; abbiamo però un'opzione poco convenzionale per cercare di saperne di più.\n\nHai mai sentito parlare di psicometria?", enHash = "59833c77", vanilla = true },
    },
    [4129] = {
        title = { it = "Ciò che il coltello rivela", enHash = "49ce4bd6", vanilla = true },
        text = { it = "Il druido della roccaforte, Quintis Jonespyre, ha delle capacità... insolite. Una di queste è la psicometria: la capacità di rivelare la storia di un oggetto toccandolo. Non chiedermi come faccia; per me è una magia che non capisco e che scelgo di non capire. So però due cose: primo, l'ho vista funzionare, e secondo, quel perdigiorno è in debito con me.\n\nPorta il coltello a Quint, su nella sua casetta sull'albero qui vicino, e digli da parte mia che il suo debito di Kalimdor Hold 'Em sarà saldato se fa la sua magia su quel coltello.", enHash = "912dc58e", vanilla = true },
        objectives = { it = "Porta il Discarded Knife a Quintis Jonespyre, alla Feathermoon Stronghold.", enHash = "67d9a958", vanilla = true },
        progress = { it = "Ti manda Ginro, eh?\n\nLe mie letture psicometriche sono piuttosto sfiancanti per la mente... ma lo sono anche le mie perdite a Kalimdor Hold 'Em. Qui alla roccaforte mi chiamano \"il re delle batoste\". Sfortunato al gioco... fortunato nel padroneggiare i segreti della natura, direi.\n\nComunque, certo che lo farò. Potrebbe essere proprio la svolta che ci serve per scoprire la sorte di Raschal. Se mi dai il coltello, possiamo cominciare.", enHash = "29017d79", vanilla = true },
        reward = { it = "Grazie, $N.\n\nAnche se la psicometria non è affatto un'arte esatta, in passato l'ho usata per far luce su situazioni che altri avevano dato per perse. Credo che usarla sul coltello che hai trovato ci farà intravedere cosa è successo a Raschal.\n\nCi vorrà solo un momento, ma non è quello che chiamerei un compito leggero per chi lancia incantesimi. Abbi pazienza.", enHash = "f3291aef", vanilla = true },
    },
    [4130] = {
        title = { it = "Lettura psicometrica", enHash = "42fa5330", vanilla = true },
        text = { it = "Sono ancora un po' stordito, scusa. Comunque, ho avuto delle visioni utili.\n\nRaschal prende due grossi zaini di cuoio dalla sua barca e si addentra nell'entroterra; poi però torna alla barca. Vedo scalpi di gnoll... si è imbattuto in degli gnoll, i Woodpaw, credo si chiamino. È molto preoccupato, quasi terrorizzato, per qualcosa. Tanto che non si accorge degli elementali dell'acqua che si formano alle sue spalle. Le immagini... si fermano lì.\n\nDevo riposare, scusa, $N. Riferisci a Gin quello che ho visto. Deve saperlo.", enHash = "06b64d69", vanilla = true },
        objectives = { it = "Parla con Ginro Hearthkindle, alla Feathermoon Stronghold.", enHash = "0b928b8f", vanilla = true },
        reward = { it = "Grazie per avermi riferito le visioni di Quint, $N. Cercherò di ricordarmi di essere un po' più indulgente con lui la prossima volta che giochiamo a carte.\n\nRaschal sa cavarsela in un combattimento, e gli gnoll non sono certo qualcosa che potrebbe preoccuparlo, anzi, terrorizzarlo. Comunque, forse tu e i tuoi potete agire su queste nuove informazioni e trovare la svolta di cui abbiamo disperatamente bisogno.", enHash = "8674362d", vanilla = true },
    },
    [4131] = {
        title = { it = "Gli gnoll Woodpaw", enHash = "a3e3b441", vanilla = true },
        text = { it = "Alla fine i nostri \"amici\" Woodpaw potrebbero aver preso Raschal, ma qualcosa mi dice che non è andata così. Comunque, sono il posto migliore da cui cominciare a cercare.\n\nVorrei avere le idee più chiare su cosa fare, ma per ora ho solo \"Cerca negli accampamenti dei Woodpaw: vai.\" So che gli gnoll tengono gli oggetti che razziano e se li contendono; forse si sono imbattuti negli zaini di cui ha parlato Quint. Nelle ricerche passate non avevo rischiato uno scontro frontale, ma con la visione di Quint dico di farli a pezzi.", enHash = "d93d153c", vanilla = true },
        objectives = { it = "Cerca negli accampamenti degli gnoll Woodpaw, nel sud di Feralas, delle prove sugli averi del corriere o sul corriere stesso.", enHash = "34bb1199", vanilla = true },
        reward = { it = "Appesi a un albero lì vicino ci sono due grossi zaini di cuoio. Ognuno porta sul davanti un piccolo stemma della Feathermoon Stronghold...", enHash = "b7c561e1", vanilla = true },
    },
    [4161] = {
        title = { it = "La ricetta dei Kaldorei", enHash = "af9d6ffb", vanilla = true },
        text = { it = "Tanto tempo fa, gli elfi della notte erano chiamati kaldorei, un nome che significa \"figli delle stelle\". Conoscere il passato è un passo importante nel tuo cammino come $C, $N, quindi ascolta bene quello che ho da dirti.\n\nI kaldorei sono sempre stati molto fieri del loro rapporto armonioso con la natura. Questo significa che prendiamo dalla natura solo ciò che è necessario, e che restituiamo in egual misura. Questo equilibrio ci ha dato molto, $N.\n\nVa' a raccogliere sette Small Spider Leg — non di più, e torna da me.", enHash = "16f118fe", vanilla = true },
        objectives = { it = "Raccogli 7 Small Spider Leg per Zarrin, a Dolanaar.", enHash = "094250f4", vanilla = true },
        progress = { it = "Ricorda l'equilibrio, $N. Desidero che tu sviluppi comprensione e una forte empatia per le foreste viventi.", enHash = "6d54ead4", vanilla = true },
        reward = { it = "Ricorda sempre quello che ti ho mostrato oggi, $N. Fai parte dell'equilibrio che gli elfi della notte si sforzano di mantenere intatto, anche in tempi difficili.", enHash = "c30ed5bf", vanilla = true },
    },
    [4181] = {
        title = { it = "Ingegneria goblin", enHash = "cef2f84a", vanilla = true },
        text = { it = "L'ingegneria di livello esperto si divide in due discipline distinte: gnomica e goblin. Mi prendo la briga di nominare l'ingegneria goblin solo perché sono un istruttore imparziale. Agli ingegneri goblin piace costruire cose che esplodono, e raramente badano a cosa si trovi sulla loro strada — nemmeno quando si tratta di loro stessi.\n\n$N, leggi questo manuale. Se vuoi imparare a farti saltare in aria, portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi assicurati che sia ciò che vuoi prima di portare a termine il suo incarico.", enHash = "99bf96fc", vanilla = true },
        objectives = { it = "Se vuoi saperne di più sull'ingegneria goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.", enHash = "fbea079d", vanilla = true },
        progress = { it = "Fiuto le nuove reclute come fiuto un'ottima polvere da mina — a un miglio di distanza. Sei $Gvenuto:venuta; a imparare come si padroneggia l'esplosione?", enHash = "bcc1428c", vanilla = true },
        reward = { it = "Be', $N, hai fatto bene a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria — gli gnomi e Gnomeregan, la loro casa irradiata, ne sono la prova. Ma per padroneggiare la disciplina dell'ingegneria goblin ci vogliono una mente salda e una mano ferma (e sottolineo FERMA).\n\nTieni le orecchie ben aperte, $N, e forse imparerai qualcosa.", enHash = "0e2d9422", vanilla = true },
    },
    [4281] = {
        title = { it = "Consegna a Thalanaar", enHash = "20977c0e", vanilla = true },
        text = { it = "Questo pacco di merci che hai trovato negli accampamenti degli gnoll Woodpaw doveva essere consegnato alla piccola stazione di sosta di Thalanaar, nel sud-est di Feralas. Qualunque sia stata la sorte del corriere scomparso, il compito di consegnare il pacco resta da portare a termine.\n\nEsaminando il pacco con attenzione, scopri un nome scritto a mano sull'esterno dell'imballaggio: \"Falfindel Waywarder\". Forse è il destinatario finale del pacco.", enHash = "3318343c", vanilla = true },
        objectives = { it = "Porta l'Undelivered Parcel a Falfindel Waywarder, a Thalanaar.", enHash = "20ba2b8c", vanilla = true },
        progress = { it = "$GBenvenuto:Benvenuta; a Thalanaar, $C. Ti serve aiuto di qualche tipo?", enHash = "6491dd46", vanilla = true },
        reward = { it = "Sia lodata Elune, la consegna dalla Feathermoon Stronghold è finalmente arrivata!\n\nLa tua presenza qui mi fa pensare che forse a Raschal, il nostro solito corriere, sia capitata una brutta sorte. Spero che tutto si sistemi. So che di recente i Woodpaw si sono molto agitati per qualcosa che viene da sud. Forse è caduto lì, nelle terre selvagge; io starei attento, $Gamico:amica;.\n\nComunque, grazie ancora. Ecco il pagamento per la consegna di questo pacco.", enHash = "1fc6740b", vanilla = true },
    },
    [4295] = {
        title = { it = "La birra di Rocknot", enHash = "3cd19774", vanilla = true },
        progress = { it = "Oh, birra! Ucciderei per un po' di Dark Iron Ale!! Presto, sto tornando sobrio! Lo so perché la sobrietà mi annebbia la vista... e mi fa sembrare che tu sia $Gil:la; $R che ho ucciso la settimana scorsa!", enHash = "bdb0115a", vanilla = true },
        reward = { it = "Cos'è questo? Ah! Sa di Dark Iron Ale! Il bere mi ha annebbiato la vista, ma capisco che tu, $Gsignore:signora;, sei $Gun vero amico:una vera amica;!", enHash = { "42bdbc0c", "ca1f30ee" }, vanilla = true },
    },
    [4402] = {
        title = { it = "La Cactus Apple Surprise di Galgar", enHash = "010ff614" },
        text = { it = "Fa proprio caldo qui nella Valley of Trials.\n\n<Galgar si asciuga la fronte.>\n\nSe solo avessi delle Cactus Apple, potrei preparare la mia famosa Cactus Apple Surprise! Niente ti rinfresca più in fretta di un pezzo di quella deliziosa leccornia.\n\nFacciamo così, $N. Se mi porti 10 Cactus Apple, ti preparerò qualche porzione di Cactus Apple Surprise da portare con te nelle tue avventure, e in più un manuale di addestramento gratis. Se ti interessa, trovi le Cactus Apple vicino alle piante di cactus qui intorno.", enHash = "5237a91e" },
        objectives = { it = "Porta a Galgar 10 Cactus Apple. Ricordi che ti ha detto che si trovano vicino ai cactus.", enHash = "928fcccc" },
        progress = { it = "Hai finito di raccogliere le Cactus Apple?", enHash = "34db7fe6" },
        reward = { it = "Magnifico, $N! Come promesso, ecco la tua Cactus Apple Surprise. Prendi anche uno di questi manuali di addestramento, ce n'è per tutti.", enHash = "e59f7cda" },
    },
    [4495] = {
        title = { it = "Un buon amico", enHash = "58a53622", vanilla = true },
        text = { it = "Un mio amico, Iverron, di solito viene a trovarmi ogni giorno alla stessa ora. La cosa strana è che oggi non si è proprio visto: anzi, è in ritardo di parecchie ore.\n\nLo ammetto, sono un po' preoccupata, $N. Iverron passa molto tempo vicino alla grotta a nord, e di sicuro sai quanto è pericolosa: ragni dappertutto!\n\nSe per caso vai da quella parte, però, potresti vedere se lo trovi?", enHash = "d865b79b", vanilla = true },
        objectives = { it = "Trova Iverron vicino alla grotta a nord.", enHash = "ea8ad532", vanilla = true },
        reward = { it = "Sono così felice che tu mi abbia trovato, $N. Come sapevi che ero qui?", enHash = "0efab50a", vanilla = true },
    },
    [4542] = {
        title = { it = "Messaggio per Freewind Post", enHash = "badbbee0", vanilla = true },
        text = { it = "$GCoraggioso viaggiatore:Coraggiosa viaggiatrice;, i centauri hanno intensificato gli attacchi in questa zona. Freewind Post deve sapere subito di queste nuove molestie! Cerca Cliffwatcher Longhorn a Freewind Post, a sud-est, e consegnagli questo messaggio urgente.\n\nSta' in guardia, evita il Grimtotem Clan qui vicino... ultimamente si comportano in modo strano con noi.", enHash = "ffa263ff", vanilla = true },
        objectives = { it = "Porta l'Urgent Message a Cliffwatcher Longhorn, a Freewind Post.", enHash = "df94b2a8", vanilla = true },
        progress = { it = "Cosa vuoi, $C? Un messaggio urgente... per me?", enHash = "85e49bfa", vanilla = true },
        reward = { it = "Altre cattive notizie! Questi centauri sono andati troppo oltre! Hanno assalito una delle mie carovane di rifornimenti e massacrato l'intero gruppo. È un oltraggio, e non resterà impunito!", enHash = "c555ce3b", vanilla = true },
    },
    [4581] = {
        title = { it = "Kayneth Stillwind", enHash = "6f3776de", vanilla = true },
        text = { it = "Il druido Kayneth Stillwind mi ha mandato un messaggio. Vorrebbe un rapporto su quel che accade lungo la nostra costa e nelle foreste intorno ad Astranaar. Teme che una corruzione si stia muovendo per Ashenvale... e potrebbe avere ragione.\n\nEcco, portagli il mio rapporto. Lo troverai nel santuario di Forest Song, nei Nightsong Woods a est.", enHash = "fd0c9bb3", vanilla = true },
        objectives = { it = "Porta Shindrell's Note a Kayneth Stillwind, a Forest Song.", enHash = "e22e0fe8", vanilla = true },
        progress = { it = "Hai qualcosa per me?", enHash = "646e6548", vanilla = true },
        reward = { it = "Ah, il rapporto di Shindrell! Molte grazie, $N. Shindrell è un'ottima sentinella, coraggiosa e acuta. Devo leggerlo per cercare tracce di una malvagità che temo si stia muovendo per Ashenvale.", enHash = "ebf757d3", vanilla = true },
    },
    [4601] = {
        title = { it = "The Sparklematic 5200!", enHash = "bcfe6e77", vanilla = true },
        text = { it = "Questo aggeggio spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice \"The Sparklematic 5200\", e sotto c'è scritto:\n\n\"Sporcizia e residui rovinano i tuoi gioiellini? Lo Sparklematic 5200 rimette lo splendore nello splendi-fantastico! Inserisci l'oggetto da pulire e deposita tre monete d'argento nella fessura. Concedi allo Sparklematic 5200 qualche istante di lavoro e voilà! I tuoi oggetti di valore usciranno puliti e splendenti!\"", enHash = "aeab26b8", vanilla = true },
        objectives = { it = "Inserisci un Grime-Encrusted Item nello Sparklematic 5200, e assicurati di avere tre monete d'argento per far partire la macchina.", enHash = "c2b6523f", vanilla = true },
        progress = { it = "Pare che al congegno serva una specie di oggetto incrostato di sporcizia da pulire e tre monete d'argento per mettersi in moto. Se ci sono tutti e due, lo Sparklematic 5200 dovrebbe funzionare...", enHash = "9424b1c9", vanilla = true },
        reward = { it = "Inserisci l'oggetto incrostato e tre monete d'argento nello Sparklematic 5200. La macchina si anima in un tentativo frenetico di ripulire dalla sporcizia l'oggetto sconosciuto. Dal cuore della macchina battono rumori forti e violenti di ingranaggi che girano. Il telaio metallico della bestia scricchiola e geme mentre sobbalza da un lato all'altro...", enHash = "0e83bd30", vanilla = true },
    },
    [4602] = {
        title = { it = "The Sparklematic 5200!", enHash = "bcfe6e77", vanilla = true },
        text = { it = "Questo aggeggio spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice \"The Sparklematic 5200\", e sotto c'è scritto:\n\n\"Sporcizia e residui rovinano i tuoi gioiellini? Lo Sparklematic 5200 rimette lo splendore nello splendi-fantastico! Inserisci l'oggetto da pulire e deposita tre monete d'argento nella fessura. Concedi allo Sparklematic 5200 qualche istante di lavoro e voilà! I tuoi oggetti di valore usciranno puliti e splendenti!\"", enHash = "aeab26b8", vanilla = true },
        objectives = { it = "Inserisci un Grime-Encrusted Item nello Sparklematic 5200, e assicurati di avere tre monete d'argento per far partire la macchina.", enHash = "c2b6523f", vanilla = true },
        progress = { it = "Pare che al congegno serva una specie di oggetto incrostato di sporcizia da pulire e tre monete d'argento per mettersi in moto. Se ci sono tutti e due, lo Sparklematic 5200 dovrebbe funzionare...", enHash = "ce3ed7a7", vanilla = true },
        reward = { it = "Inserisci l'oggetto incrostato e tre monete d'argento nello Sparklematic 5200. La macchina si anima in un tentativo frenetico di ripulire dalla sporcizia l'oggetto sconosciuto. Dal cuore della macchina battono rumori forti e violenti di ingranaggi che girano. Il telaio metallico della bestia scricchiola e geme mentre sobbalza da un lato all'altro...", enHash = "9cc4fed2", vanilla = true },
    },
    [4603] = {
        title = { it = "Ancora un giro di Sparklematic", enHash = "4ba20567", vanilla = true },
        progress = { it = "Lo Sparklematic 5200 è vuoto, in attesa di un oggetto incrostato da pulire e di tre monete d'argento per partire!", enHash = "4b6ea245", vanilla = true },
        reward = { it = "Lo Sparklematic 5200 si anima, sobbalzando avanti e indietro. Dentro, la sporcizia indifesa che incrostava l'oggetto viene polverizzata dal detergente gnomico della macchina.\n\nLo Sparklematic 5200 si ferma, annunciato da un familiare \"ding!\". Il ricettacolo della macchina si apre a spirale e rivela una scatola avvolta con cura.", enHash = "12dbe743", vanilla = true },
    },
    [4604] = {
        title = { it = "Ancora un giro di Sparklematic", enHash = "4ba20567", vanilla = true },
        progress = { it = "Lo Sparklematic 5200 è vuoto, in attesa di un oggetto incrostato da pulire e di tre monete d'argento per partire!", enHash = "4b6ea245", vanilla = true },
        reward = { it = "Lo Sparklematic 5200 si anima, sobbalzando avanti e indietro. Dentro, la sporcizia indifesa che incrostava l'oggetto viene polverizzata dal detergente gnomico della macchina.\n\nLo Sparklematic 5200 si ferma, annunciato da un familiare \"ding!\". Il ricettacolo della macchina si apre a spirale e rivela una scatola avvolta con cura.", enHash = "12dbe743", vanilla = true },
    },
    [4605] = {
        title = { it = "The Sparklematic 5200!", enHash = "bcfe6e77", vanilla = true },
        reward = { it = "Com'è cominciato, così lo Sparklematic 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\", e la bocca della macchina si apre a spirale verso l'alto. Dentro lo Sparklematic 5200 c'è una scatoletta avvolta in un nastrino. Pare che la macchina incarti l'oggetto dopo avergli tolto le incrostazioni. Anche se la macchina non avesse funzionato, almeno adesso l'oggetto è avvolto in una bella scatola.\n\nBe', c'è un modo solo per scoprire se l'ha pulito o no...", enHash = "016de648", vanilla = true },
    },
    [4606] = {
        title = { it = "The Sparklematic 5200!", enHash = "bcfe6e77", vanilla = true },
        reward = { it = "Com'è cominciato, così lo Sparklematic 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\", e la bocca della macchina si apre a spirale verso l'alto. Dentro lo Sparklematic 5200 c'è una scatoletta avvolta in un nastrino. Pare che la macchina incarti l'oggetto dopo avergli tolto le incrostazioni. Anche se la macchina non avesse funzionato, almeno adesso l'oggetto è avvolto in una bella scatola.\n\nBe', c'è un modo solo per scoprire se l'ha pulito o no...", enHash = "f478e516", vanilla = true },
    },
    [4621] = {
        title = { it = "Alt là, ammiraglio!", enHash = "54e64db6", vanilla = true },
        text = { it = "Ascolta bene, lupo di mare... è il potere di Booty Bay che impedisce a noi Bloodsail di navigare dove ci pare e di prenderci quello che vogliamo per diritto di saccheggio. Se piantassi un coltello in Fleet Master Seahorn, non avremmo mai più guai con le navi di Booty Bay. Se piantassi un coltello in Baron Revilgaz, non dovremmo mai più fare i conti con la loro legge.\n\nSe vuoi diventare $Gammiraglio onorario:ammiraglia onoraria; tra noi, sì, $GAMMIRAGLIO:AMMIRAGLIA;, pianterai un coltello in tutti e due, come ho detto. Ora va', $Gragazzo:ragazza;, e torna da me quando avrai fatto il lavoro.", enHash = { "2e299630", "2e080420" }, vanilla = true },
        objectives = { it = "Uccidi Fleet Master Seahorn e Baron Revilgaz di Booty Bay, poi torna da Fleet Master Firallon a bordo della Crimson Veil, al largo della costa di Stranglethorn Vale.", enHash = "985579a5", vanilla = true },
        progress = { it = "Sei già di ritorno, maledetto marinaio! Hai fatto quello che ti ho ordinato? Deludici e camminerai sull'asse.\n\nArrrrr...", enHash = "21b91e5b", vanilla = true },
        reward = { it = "Alt là... $GAmmiraglio:Ammiraglia; $N! Sei il pirata dei pirati, $Gragazzo:ragazza;!\n\nMi scalda il cuore darti questo cappello. Non ne troverai mai un altro così da nessuna parte, e chiunque ti guardi vedrà che sei $Gun ammiraglio:un'ammiraglia; della Bloodsail Navy!", enHash = "f6b3aecf", vanilla = true },
    },
    [4641] = {
        title = { it = "Il tuo posto nel mondo", enHash = "592e356e" },
        text = { it = "Finalmente hai l'età, $N... l'età per combattere in nome dell'Orda e conquistare a gloria del Capoguerra.\n\nSì...\n\n<Kaltunk ti squadra da capo a piedi.>\n\nFarai al caso nostro.\n\nDi certo vorresti trovare un grande drago o un demone e strangolarlo a mani nude, ma forse sarebbe più saggio cominciare da qualcosa di meno... pericoloso.\n\n<Kaltunk ride.>\n\nPresentati a Gornek: saprà affidarti un compito più adatto a $Gun giovane:una giovane; $C. Lo troverai nel Den, a ovest.", enHash = "52976bac" },
        objectives = { it = "Parla con Gornek. Ricordi che Kaltunk ti ha segnato sulla mappa dove trovarlo, dicendoti che sta nel Den, un edificio a ovest.", enHash = "d1850e56" },
        reward = { it = "Un'altra recluta di Kaltunk, eh?\n\nSiamo messi proprio male, se questo è il meglio che l'Orda sa produrre. Poco importa. Quando ti riterremo $Gpronto:pronta; a lasciare la Valley, sarai $Gun fiero guerriero:una fiera guerriera; dell'Orda.", enHash = "ace010fe" },
    },
    [4681] = {
        title = { it = "Spiaggiati", enHash = "4592438e", vanilla = true },
        text = { it = "Quella creatura spiaggiata non è un caso isolato, qui a Darkshore. Ce ne sono altre lungo la costa e perfino in acqua. Vorrei che ne esaminassi un'altra di cui sappiamo: questa è stata segnalata in acqua a ovest di Auberdine, vicino a un vascello affondato. Torna da me con tutto ciò che riuscirai a recuperare e che possa aiutare le nostre ricerche.\n\nInoltre, nei tuoi viaggi potresti trovarne altre. Mi raccomando: se scopri qualcosa, faccelo sapere!", enHash = "73fae69a", vanilla = true },
        objectives = { it = "Recupera le Sea Turtle Remains dalla Skeletal Sea Turtle nelle acque a ovest di Auberdine, poi parla con Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "fd0c3bfb", vanilla = true },
        progress = { it = "Una volta che avrai esaminato i resti della creatura nell'acqua a ovest di qui, dovrei poter stendere un rapporto come si deve per il Temple of the Moon, a Darnassus. Forse allora saremo più vicini a scoprire perché queste povere creature scelgono di finire i loro giorni spiaggiate sulla costa di Darkshore.", enHash = "179172c0", vanilla = true },
        reward = { it = "Oggi sei $Gstato:stata; di enorme aiuto: ora abbiamo una possibilità concreta di sciogliere il mistero del perché queste creature scelgano di spiaggiarsi sulla costa di Darkshore. L'idea che possano fuggire dalla zona intorno a Teldrassil è inquietante. Se nei tuoi viaggi ne incontrerai altre, fammelo sapere. Le nostre ricerche qui sono solo agli inizi.\n\nA nome del Temple of the Moon, accetta questo come ringraziamento per l'impegno che ci hai messo. Grazie, $N!", enHash = "3136b695", vanilla = true },
    },
    [4722] = {
        title = { it = "Tartaruga marina spiaggiata", enHash = "c67237cb", vanilla = true },
        text = { it = "Trovi la carcassa di una tartaruga marina che si era spiaggiata sulla costa di Darkshore tempo fa. È stata spolpata dai murloc che si sono accampati intorno ai resti della creatura. Sembra comunque che sui resti siano rimasti campioni adatti, di cui Gwennyth Bly'Leggonde, ad Auberdine, potrebbe fare buon uso.", enHash = "4d16c8f7", vanilla = true },
        objectives = { it = "Porta le Sea Turtle Remains a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "4def362a", vanilla = true },
        progress = { it = "Salve, $N — hai scoperte da riferire su creature spiaggiate?", enHash = "bdabd756", vanilla = true },
        reward = { it = "Un'altra scoperta da studiare — ben fatto, $N! Questi resti saranno esaminati come si deve una volta arrivati a Darnassus. Accetta questo piccolo compenso in cambio dei resti che ci hai fornito per i nostri studi.", enHash = "a4a87e56", vanilla = true },
    },
    [4723] = {
        title = { it = "Creatura marina spiaggiata", enHash = "56e5f30e", vanilla = true },
        text = { it = "I resti di un thresher gigante — molto più grande di quanto ti aspetteresti a Darkshore — giacciono spiaggiati sulla costa del Mist's Edge. Come sia arrivata qui questa creatura non si sa: il gruppo di murloc che ora banchetta sulla carcassa sembra troppo debole, anche in gran numero, per aver abbattuto la bestia.\n\nSe pure una parte è stata ripulita, ne resta abbastanza per prendere un campione da far studiare a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "4234ba5d", vanilla = true },
        objectives = { it = "Porta le Sea Creature Bones a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "844c655f", vanilla = true },
        progress = { it = "Forse un giorno troveremo un modo per impedire a queste povere creature di finire i loro giorni inutilmente sulla costa di Darkshore. Fino ad allora, dobbiamo continuare le nostre ricerche!\n\nSalve, $N — che notizie porti?", enHash = "6c9a803c", vanilla = true },
        reward = { it = "Un'altra scoperta — ben fatto, $N! Questi resti saranno esaminati come si deve una volta arrivati a Darnassus. Accetta questo piccolo compenso in cambio dei resti che ci hai fornito per i nostri studi.", enHash = "8deda4a7", vanilla = true },
    },
    [4725] = {
        title = { it = "Tartaruga marina spiaggiata", enHash = "c67237cb", vanilla = true },
        text = { it = "Altri resti di tartaruga marina giacciono spiaggiati lungo la costa. Questi in particolare hanno un carro abbandonato agganciato al guscio della tartaruga. Forse questa creatura è stata spinta a riva da esseri sconosciuti, invece di spiaggiarsi da sé come lasciavano pensare gli altri resti. Ora i murloc Greymist hanno fatto dei resti della creatura la loro casa, banchettando sulla carogna.\n\nDentro il carro trovi una cassetta con strani segni sopra: forse Gwennyth Bly'Leggonde, ad Auberdine, riuscirà a capirci qualcosa.", enHash = "578a3e51", vanilla = true },
        objectives = { it = "Porta la Strangely Marked Box a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "e40a6130", vanilla = true },
        progress = { it = "È un piacere rivederti, $N. Stiamo facendo grandi passi avanti nello svelare il mistero del perché maestose creature marine si spiaggino sulla costa di Darkshore, ma a ogni domanda a cui rispondiamo pare che se ne aprano altre due.\n\nSei qui per darci altro aiuto nelle nostre ricerche?", enHash = "a9954191", vanilla = true },
        reward = { it = "Ho sentito parlare del genere di carri che hai trovato sul dorso della tartaruga. Quelli credo proprio siano carri dei naga, usati sia in battaglia sia per trasportare i loro rifornimenti a terra. I segni sulla cassetta che hai trovato sono dei naga: questo spiegherebbe la loro presenza invasiva nell'estremo nord di Darkshore.\n\nManderò questa cassetta a Darnassus insieme al resto delle tue scoperte. Questo è per te — grazie ancora del tuo aiuto.", enHash = "c2f42de5", vanilla = true },
    },
    [4727] = {
        title = { it = "Tartaruga marina spiaggiata", enHash = "c67237cb", vanilla = true },
        text = { it = "I resti scheletrici di una tartaruga marina giacciono nella sabbia delle spiagge settentrionali di Darkshore. I murloc Greymist o non hanno trovato questa carcassa, o forse l'hanno trovata e se ne tengono alla larga per qualche motivo sconosciuto. In ogni caso, della tartaruga resta abbastanza per portare un campione a Gwennyth Bly'Leggonde, ad Auberdine, perché il Temple of the Moon lo studi.", enHash = "4b9d55ba", vanilla = true },
        objectives = { it = "Porta le Sea Turtle Remains a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "4def362a", vanilla = true },
        progress = { it = "Salve ancora, $N — hai trovato altre creature spiaggiate di cui il Temple of the Moon dovrebbe sapere?", enHash = "cadc648e", vanilla = true },
        reward = { it = "È interessante che i murloc non fossero presenti in quel punto: ne terremo conto mentre studiamo i resti di questa creatura! Grazie del tuo impegno, $N; il Temple of the Moon vuole che ti dia questo, come compenso per il tempo che ci hai dedicato.", enHash = "e12670de", vanilla = true },
    },
    [4728] = {
        title = { it = "Creatura marina spiaggiata", enHash = "56e5f30e", vanilla = true },
        text = { it = "La carcassa di quello che sembra una specie di mammifero marino gigante giace sulla spiaggia, in parte sventrata. Accanto all'enorme creatura spiaggiata ci sono una carriola e vari attrezzi abbandonati, come se qualcuno avesse già tentato di studiarla. Anche se i murloc hanno fatto razzia della bestia, ne resta abbastanza per raccogliere un campione adatto a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "76f05b30", vanilla = true },
        objectives = { it = "Porta le Sea Creature Bones a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "844c655f", vanilla = true },
        progress = { it = "Salve di nuovo, $N! Cosa ti riporta ad Auberdine? Sei qui per riferire di un'altra scoperta, forse?", enHash = "d8c5a742", vanilla = true },
        reward = { it = "Ah, credo che tu ne abbia trovata una che stava esaminando la Lega degli Esploratori. Sono presenti qui a Darkshore, e avevano accennato che stavano studiando una delle creature spiaggiate finché i murloc non li hanno cacciati via. A quanto pare tu sei $Griuscito:riuscita; dove né noi né loro ce l'abbiamo fatta. Ti prego — accetta questo compenso a nome del Temple of the Moon.", enHash = "e9729372", vanilla = true },
    },
    [4730] = {
        title = { it = "Creatura marina spiaggiata", enHash = "56e5f30e", vanilla = true },
        text = { it = "La carcassa mezza divorata di quello che poteva essere un mammifero marino gigante giace sulla spiaggia. Un gruppo di murloc, più forti di quelli che si trovano vicino ad Auberdine, si è insediato intorno alla creatura caduta. Della creatura resta abbastanza da consegnare un campione adatto delle sue ossa a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "f91cc415", vanilla = true },
        objectives = { it = "Porta le Sea Creature Bones a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "844c655f", vanilla = true },
        progress = { it = "Salve di nuovo, $N! Sei qui per riferire di un'altra scoperta?", enHash = "602a2854", vanilla = true },
        reward = { it = "Le ossa che hai sono di mansueti mammiferi marini che vivono, per quanto ne sappiamo, nelle acque intorno alla base di Teldrassil. Non si era mai saputo che si spiaggiassero con violenza come facevano i thresher. Perché mai queste creature lo farebbero? Be', forse lo studio dei loro resti darà i frutti di conoscenza che cerchiamo.\n\nAncora una volta, grazie del tuo aiuto. Accetta questo compenso da parte del Temple of the Moon.", enHash = "a636bef4", vanilla = true },
    },
    [4731] = {
        title = { it = "Tartaruga marina spiaggiata", enHash = "c67237cb", vanilla = true },
        text = { it = "Altri resti di tartaruga marina giacciono spiaggiati lungo la costa. Questi hanno un carro abbandonato agganciato a metà al guscio della tartaruga. Forse questa creatura è stata spinta a riva da esseri sconosciuti, invece di spiaggiarsi da sé come lasciavano pensare gli altri resti. Potenti murloc Greymist hanno fatto della carcassa di questa creatura la loro casa.\n\nDentro il carro trovi una cassetta con strani segni sopra: forse Gwennyth Bly'Leggonde, ad Auberdine, riuscirà a capirci qualcosa.", enHash = "ba05be88", vanilla = true },
        objectives = { it = "Porta la Strangely Marked Box a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "e40a6130", vanilla = true },
        progress = { it = "Salve di nuovo, $N. Il lavoro che hai fatto per il Temple of the Moon è stato straordinario. Avremo la fortuna di ricevere altro aiuto da te?", enHash = "b9152e3d", vanilla = true },
        reward = { it = "Ho sentito parlare del genere di carri che si trovano sul dorso di quella tartaruga. Quelli credo proprio siano carri dei naga, usati sia in battaglia sia per trasportare i loro rifornimenti a terra. I segni sulla cassetta che hai trovato sono dei naga: forse la creatura che hai scoperto è stata uccisa mentre andava più a sud... verso Ashenvale, magari?\n\nFarò in modo di mandare questa cassetta a Darnassus con il resto delle tue scoperte. Questo è per te — grazie ancora del tuo aiuto.", enHash = "101617ac", vanilla = true },
    },
    [4732] = {
        title = { it = "Tartaruga marina spiaggiata", enHash = "c67237cb", vanilla = true },
        text = { it = "Trovi la carcassa di una tartaruga marina che si era spiaggiata sulla costa di Darkshore tempo fa. È stata ripulita quasi del tutto dai murloc Greymist, gli stessi che ora si sono accampati intorno ai resti della creatura. Sembra comunque che sui resti siano rimasti campioni adatti, di cui Gwennyth Bly'Leggonde, ad Auberdine, potrebbe fare buon uso.", enHash = "6a636df4", vanilla = true },
        objectives = { it = "Porta le Sea Turtle Remains a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "4def362a", vanilla = true },
        progress = { it = "Salve ancora, $N — hai altre scoperte da riferire al Temple of the Moon?", enHash = "283a9523", vanilla = true },
        reward = { it = "Hai trovato altre creature spiaggiate, $N? Un tempo le tartarughe marine si vedevano spesso giocare lungo la base di Nordrassil, prima che venisse distrutto. Con la nascita di Teldrassil, però, se ne vedono sempre meno. Alcune, come abbiamo scoperto, finiscono qui i loro giorni per qualche motivo sconosciuto.\n\nForse il tuo aiuto scioglierà il mistero che abbiamo davanti. Accetta questo in cambio dei resti che ci hai fornito per i nostri studi.", enHash = "de2c47d8", vanilla = true },
    },
    [4733] = {
        title = { it = "Creatura marina spiaggiata", enHash = "56e5f30e", vanilla = true },
        text = { it = "I resti di quello che sembra un thresher gigante sono stati portati a riva sull'insenatura rocciosa della Twilight Shore. Il thresher è parecchie volte più grande di qualunque altro avvistato da queste parti. Da qualunque posto venisse, questa creatura non sembra essere originaria di Darkshore.\n\nAnche se la creatura è stata spolpata in più punti, ne resta abbastanza per raccogliere un campione adatto a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "eec89610", vanilla = true },
        objectives = { it = "Porta le Sea Creature Bones a Gwennyth Bly'Leggonde, ad Auberdine.", enHash = "844c655f", vanilla = true },
        progress = { it = "Sia ringraziata Elune — che piacere rivederti, $N. Il lavoro del Temple of the Moon sullo strano fenomeno degli spiaggiamenti continua qui a Darkshore. Hai per caso qualcos'altro da offrirci?", enHash = "c80577a8", vanilla = true },
        reward = { it = "Le dimensioni del thresher di cui parli lasciano sbalorditi. Anche i thresher più vecchi di questa regione arrivano solo a una frazione di quella taglia. Se ne conoscevano alcuni più grandi vicino a Teldrassil, ma il loro numero è calato di continuo. Non posso fare a meno di chiedermi se queste creature che si spiaggiano qui non c'entrino qualcosa.\n\nMentre analizziamo le ossa che ci hai portato, accetta questo a nome del Temple of the Moon. Grazie, $N.", enHash = "7b0beb58", vanilla = true },
    },
    [4740] = {
        title = { it = "WANTED: Murkdeep!", enHash = "31f168ff", vanilla = true },
        text = { it = "Attenzione!\n\nSi offre una ricompensa per la morte del murloc \"Murkdeep\". Questa bestia immonda è ritenuta responsabile della morte di almeno una Sentinella, ed è sospettata di aver fatto affondare almeno due navi da carico nelle acque al largo di Darkshore!\n\nMurkdeep è stato avvistato l'ultima volta in un accampamento di capanne murloc a sud di Auberdine, e si pensa che stia difendendo quelle capanne. La ricompensa va richiesta a Sentinel Glynda Nal'Shea, ad Auberdine.\n\nIl Consiglio del Villaggio di Auberdine.", enHash = "b1f1883f", vanilla = true },
        objectives = { it = "Trova e uccidi il murloc noto come Murkdeep. Si pensa che stia difendendo le capanne murloc a sud di Auberdine, lungo l'acqua.\n\nRiferisci della morte di Murkdeep a Sentinel Glynda Nal'Shea, ad Auberdine.", enHash = "9ae656de", vanilla = true },
        progress = { it = "Salve, $C — in cosa possono esserti utili le Sentinelle, oggi? Forse sei qui per informarti sulla taglia su Murkdeep?", enHash = "dad5f1a5", vanilla = true },
        reward = { it = "Be', sembra che tu sia qui per qualcosa di più che informarti! I cittadini saranno felici di sapere che stanotte dormiranno un po' più tranquilli e al sicuro.\n\nOggi hai fatto da braccio della giustizia per la gente di Auberdine, $N. Per questo vorrei offrirti questo come giusta ricompensa... per $Gun vero eroe:una vera eroina; del popolo di Auberdine.", enHash = "4c1933de", vanilla = true },
    },
    [4761] = {
        title = { it = "Thundris Windweaver", enHash = "e615ecb3", vanilla = true },
        text = { it = "Quello che hai scoperto esplorando l'accampamento dei furbolg è un'informazione che Thundris Windweaver deve conoscere. È lui che fa da anziano di Auberdine, e amministra con saggezza e giustizia gli affari quotidiani del villaggio. Ti prego — condividi con lui quello che finora hai scoperto sulla faccenda dei furbolg.\n\nCredo che abbia delle idee sue sulle ragioni della loro corruzione. Forse potrete lavorare insieme per mettere in atto un piano e riportare qui l'equilibrio della natura!", enHash = "e221acb5", vanilla = true },
        objectives = { it = "Parla con Thundris Windweaver, ad Auberdine.", enHash = "f071d019", vanilla = true },
        reward = { it = "$GBen trovato:Ben trovata;, $C. La tua ricognizione sulla faccenda dei furbolg arriva in un momento fortunato per noi di Auberdine. Da tempo abbiamo a che fare non solo con abitanti della foresta apertamente ostili alla nostra presenza, ma anche con la corruzione della foresta stessa. Spero che tu possa dare una mano ad Auberdine in questi tempi difficili.", enHash = "9e9e2de1", vanilla = true },
    },
    [4762] = {
        title = { it = "Il Cliffspring River", enHash = "1c66b22a", vanilla = true },
        text = { it = "Il Cliffspring River ha cominciato a farsi fetido e corrotto. Sfocia nel Mist's Edge, e temo che la corrente arriverà presto a toccare Auberdine. Sospetto che i furbolg Blackwood più a monte siano la causa della corruzione, ma sospetto anche che non ne siano la vera radice.\n\nPrendi questo tubo per i campioni e va' alla foce del fiume, a nord di qui. Risali verso l'interno fino alla prima cascata e preleva un campione dalla pozza. Sopra di te vedrai un ponte. Una volta preso il campione, torna da me ad Auberdine.", enHash = "adee2e3d", vanilla = true },
        objectives = { it = "Va' a nord di Auberdine, fino alla prima cascata lungo il Cliffspring River, e preleva un campione dalla pozza.\n\nTorna da Thundris Windweaver, ad Auberdine, con il Cliffspring River Sample.", enHash = "d4f04b6f", vanilla = true },
        progress = { it = "L'inquinamento del Cliffspring River è solo l'inizio di una tendenza allarmante qui a Darkshore. Il campione che porterai ci aiuterà a dare forma a un piano... un piano d'attacco, comincio a sospettare.", enHash = "8ba34f4b", vanilla = true },
        reward = { it = "Non stupisce quanto sia corrotta quest'acqua, ma guarda com'è putrida ormai! Sembra proprio che serva agire al più presto, eh, $N?\n\nA est di noi c'è Felwood: è quella la vera origine di questa corruzione, una che ho già visto in passato. Prevedo che questo campione lo confermerà. Forse potremmo mettere in atto una cura qui, ma anche solo per provarci ci servirà aiuto. Quando verrà quel momento, $N, spero che potrai darci l'aiuto che ci serve.", enHash = "82be8dfa", vanilla = true },
    },
    [4763] = {
        title = { it = "I Blackwood corrotti", enHash = "5ee1e949", vanilla = true },
        text = { it = "Abbiamo scoperto che una delle fonti della corruzione dei furbolg sono i satiri. Li tengono in pugno con dei talismani attraverso cui incanalano la magia. Se i furbolg hanno una possibilità di salvezza, dobbiamo far uscire allo scoperto il satiro corruttore e prendergli quel talismano!\n\nRiempi questa coppa al nostro pozzo lunare e prendi dei campioni del cibo dei furbolg nel loro accampamento a nord. Mescolali e posa il tutto vicino al falò lungo il fiume: ogni furbolg che ne mangerà sarà purificato quel tanto che basta a far uscire allo scoperto il satiro corruttore... che a quel punto dovrai uccidere!", enHash = "a8ebc06e", vanilla = true },
        objectives = { it = "Riempi l'Empty Cleansing Bowl al pozzo lunare di Auberdine.\n\nRaccogli un campione di frutta, noci e grano negli accampamenti dei furbolg Blackwood a nord.\n\nMescola il contenuto della coppa e posala vicino al falò più vicino al Cliffspring River, nell'accampamento a nord, per evocare il satiro corruttore.\n\nPrendi il Talisman of Corruption e portalo a Thundris Windweaver, ad Auberdine.", enHash = "bfc897fa", vanilla = true },
        progress = { it = "Il Talisman of Corruption è un congegno sinistro che serve solo a pervertire l'equilibrio della natura. Quando avrai preso quell'oggetto al satiro che tormenta i furbolg e me lo porterai perché me ne sbarazzi, avremo ottenuto una grande vittoria!", enHash = "f786d303", vanilla = true },
        reward = { it = "Abbiamo appena cominciato questa guerra per riprenderci la foresta dalle forze della corruzione, ma oggi una battaglia l'abbiamo vinta! $N, la gente di Auberdine ha con te un debito di gratitudine che non sarà mai facile ripagare. Accetta questo, insieme ai nostri ringraziamenti. Quello che abbiamo imparato oggi potrebbe un giorno liberare per sempre i nostri amici furbolg dalle catene del tormento.", enHash = "f0d66f1f", vanilla = true },
    },
    [4767] = {
        title = { it = "Wind Rider", enHash = "e7f85462", vanilla = true },
        text = { it = "Mi hanno incaricato di trovare nuove reclute tra i wyvern per i maestri dei wind rider. Il loro numero cresce e anch'io spero di diventare un wind rider, un giorno. Però non riusciamo ad addestrare abbastanza wyvern per stare dietro alla richiesta. Forse puoi aiutarmi tu, $N.\n\nHo bisogno che tu vada a Highperch a raccogliere qualche uovo di wyvern. Da qui prosegui a nord-ovest lungo le pareti del canyon fino a una rampa che ti porterà a Highperch. Sta' $Gattento:attenta;: i wyvern sono molto protettivi con le loro uova e non saranno gentili con gli intrusi.", enHash = "3079b49b", vanilla = true },
        objectives = { it = "Porta 10 Highperch Wyvern Egg a Elu, a Freewind Post.", enHash = "cf4b0eb8", vanilla = true },
        progress = { it = "$N, hai recuperato le uova di wyvern che cerco? Non vedo l'ora di cominciare l'addestramento da wind rider!", enHash = "d15eeec7", vanilla = true },
        reward = { it = "Perfetto! Con queste uova spero di fare il prossimo passo per diventare un wind rider. Ecco un segno della mia riconoscenza; che la buona caccia ti accompagni sempre, $C.", enHash = "9f0dd9a7", vanilla = true },
    },
    [4770] = {
        title = { it = "Verso casa", enHash = "1642bcf9", vanilla = true },
        text = { it = "Aiutami, ti prego, $C! Sono nascosto qui a Highperch da un po' di tempo e sono giorni che non vedo una faccia amica. Sono venuto a studiare i wyvern e credo di essermi avvicinato un po' troppo. Dopo essere stato cacciato via da uno dei nidi mi sono perso.\n\nDevo tornare a Whitereach Post! Motega non sa che manco e andrà su tutte le furie quando saprà che mi sono avventurato a Highperch da solo.\n\nWhitereach Post è appena a est di qui... portamici, ti prego!", enHash = "6cfd55a6", vanilla = true },
        objectives = { it = "Scorta Pao'ka Swiftmountain fuori da Highperch, poi parla con Motega Firemane, a Whitereach Post.", enHash = "a4b6c057", vanilla = true },
        reward = { it = "Cosa?! Se avessi saputo che Pao'ka Swiftmountain sarebbe andato a ficcare il naso a Highperch, l'avrei incatenato a un totem! Suo padre era riluttante a lasciarlo venire con me a Thousand Needles. Siamo venuti qui a studiare le varie creature che abitano queste belle terre.\n\nTi ringrazio per l'aiuto che hai dato a Pao'ka. Spero che questo ripaghi i guai che l'impresa ti è costata.", enHash = "98928989", vanilla = true },
    },
    [4811] = {
        title = { it = "Il cristallo rosso", enHash = "5d8f0178", vanilla = true },
        text = { it = "A est di qui vagano moonkin ostili, in numero sempre maggiore. Un tempo si pensava fossero creature gentili, quasi mistiche. C'è ancora chi le venera, ma la sicurezza di Auberdine mi obbliga a una visione più concreta.\n\nMi sono arrivate segnalazioni che i moonkin vengano attirati da un grande cristallo rosso lungo la catena montuosa orientale di Darkshore. Nessuno ha idea di cosa sia quel cristallo, e nemmeno se esista davvero. Voglio che tu lo trovi laggiù e torni a riferirmi cosa hai visto.", enHash = "7b206ee4", vanilla = true },
        objectives = { it = "Va' a est di Auberdine e cerca un grande cristallo rosso lungo la catena montuosa orientale di Darkshore. Torna a riferire a Sentinel Glynda Nal'Shea, ad Auberdine, quello che hai trovato.", enHash = "ff218d93", vanilla = true },
        progress = { it = "Che cosa hai da riferire su quel cristallo rosso? Esiste davvero?", enHash = "8d077cfa", vanilla = true },
        reward = { it = "Quindi il cristallo esiste, $N? Affascinante... comunque, il tuo compito è stato eseguito bene; ottimo lavoro!\n\nChe cos'è di preciso questo cristallo? È solo una domanda in un mare di domande. Un'altra che mi viene in mente è perché i moonkin ne siano attratti. Il cristallo è benigno per natura, o nasconde uno scopo più sinistro?\n\nHo molte altre domande, ma per avere risposte dovremo esaminare quel cristallo da vicino.", enHash = "642f974c", vanilla = true },
    },
    [4812] = {
        title = { it = "Mentre l'acqua scorre", enHash = "0b39c6d6", vanilla = true },
        text = { it = "Usa questa fiala vuota e riempila con l'acqua del pozzo lunare qui ad Auberdine. Una magia così potente dovrebbe darci un indizio sulla composizione del cristallo. Per farlo verserai il liquido sul cristallo: al resto penserà lui.\n\nAnche se non mi aspetto che ti succeda niente di brutto, voglio comunque che tu stia $Gattento:attenta;. Sopra di noi, a est, c'è Felwood: se quel cristallo è legato a quel luogo come sospetto, potrebbe rivelarsi molto pericoloso.", enHash = "6acfc683", vanilla = true },
        objectives = { it = "Riempi l'Empty Water Tube al pozzo lunare di Auberdine, poi esamina il cristallo rosso lungo la parete montuosa orientale di Darkshore.", enHash = "58cec37c", vanilla = true },
        progress = { it = "Il cristallo ha un aspetto del tutto estraneo al paesaggio boscoso di Darkshore. Ti sembra di sentire un lievissimo ronzio venire dal suo interno.", enHash = "4d509377", vanilla = true },
        reward = { it = "Sei $Garrivato:arrivata; ancora una volta al cristallo misterioso. Togli il tappo al tubo d'acqua del pozzo lunare e ne versi con cautela il contenuto sulla sommità del cristallo. Mentre l'acqua scorre lungo le sue facce, vedi la superficie opaca farsi trasparente...", enHash = "561e7794", vanilla = true },
    },
    [4813] = {
        title = { it = "I frammenti all'interno", enHash = "d85796d7", vanilla = true },
        text = { it = "L'acqua del pozzo lunare ha rivelato che dentro il cristallo sono racchiusi alcuni piccoli frammenti d'osso e metà di una mascella. La mascella sembra appartenere a un umanoide, ma non si può dirlo con certezza senza spaccare il cristallo — un'impresa che perfino la magia più forte troverebbe quasi impossibile.\n\nCompiuto ciò che andava fatto, non resta che tornare a riferire a Sentinel Glynda Nal'Shea, ad Auberdine.", enHash = "4c4d113e", vanilla = true },
        objectives = { it = "Torna a riferire quello che hai scoperto a Sentinel Glynda Nal'Shea, ad Auberdine.", enHash = "774e2e3d", vanilla = true },
        reward = { it = "Be', sembra che anche sapendo di più su questo cristallo, il risultato siano altre domande senza risposta!\n\nPorterò le informazioni che hai raccolto al consiglio qui ad Auberdine. Forse sapranno che strada seguire su questo cristallo. Sempre che ce ne sia una da seguire: per ora la minaccia resta abbastanza a est da non farci male.\n\nQuanto a te, prendi questo. Consideralo una ricompensa per il lavoro ben fatto, $N.", enHash = "77afee0d", vanilla = true },
    },
    [4821] = {
        title = { it = "Alien Egg", enHash = "65d2ef2c", vanilla = true },
        text = { it = "È circolata la voce di un uovo alieno qui a Thousand Needles. Chi dice di averlo visto non è nemmeno riuscito ad avvicinarsi abbastanza da esaminarlo nei dettagli. I serpenti sorvegliano l'uovo come se fosse uno dei loro.\n\nVoglio che tu trovi questo uovo alieno e me lo porti, così potrò esaminarlo. Si dice che l'uovo si trovi in una tana di serpenti, ma di tane ce ne sono parecchie lungo la base delle pareti rocciose a sud e a nord-est di Freewind Post.", enHash = "341a23ab", vanilla = true },
        objectives = { it = "Porta l'Alien Egg a Hagar Lightninghoof, a Freewind Post.", enHash = "fa0f36b2", vanilla = true },
        progress = { it = "Devo saperne di più su quest'uovo misterioso: chissà cosa ne uscirà.", enHash = "63013e29", vanilla = true },
        reward = { it = "Sì, finalmente... l'uovo misterioso mi è stato finalmente consegnato. Ora, fammi dare un'occhiata più da vicino... Cosa...! Cos'è questo...?", enHash = "8759ac4b", vanilla = true },
    },
    [4822] = {
        title = { it = "Tu gridi, io grido...", enHash = "3c38ae24", vanilla = true },
        text = { it = "GELATO! Oh, per piacere per piacere per piacere, mi prendi un gelato?! La fragola è il mio gusto preferito, e al mondo non c'è gelato alla fragola migliore del Tigule and Foror's Strawberry Ice Cream! È il mio gelato preferito in tutto il mondo!\n\nL'ho mangiato una volta, tanto tempo fa, quando ero alla pista da corsa delle Shimmering Flats, ma ho sentito dire che adesso potrebbero venderlo in città! Per piacere? Per piacere per piacere? Con sopra il Tigule and Foror's Strawberry Ice Cream??!?!", enHash = "749aca00", vanilla = true },
        objectives = { it = "Procura un po' di Strawberry Ice Cream al tuo protetto. Il ragazzo sembra preferire il gelato della marca di Tigule e Foror.", enHash = "b98ea83f", vanilla = true },
        progress = { it = "Vorrei che facessero altri gusti di gelato oltre alla fragola, ma immagino di essere fortunato, visto che la fragola è il mio preferito!", enHash = "9fc07ff4", vanilla = true },
        reward = { it = "Mmmmmmmmm! Adoro il loro gelato alla fragola! Se c'è una cosa che Tigule e Foror sanno fare, è il gelato!\n\nGrazie mille, $N: è la cosa più buona di sempre!", enHash = "7c86dd83", vanilla = true },
    },
    [4841] = {
        title = { it = "Pacificare i centauri", enHash = "af5b8d71", vanilla = true },
        text = { it = "$N, ti supplico di dare la caccia a questi centauri. Sentiranno l'ira della nostra vendetta. Attacca l'accampamento dei centauri a nord di Freewind Post! Che l'ira guidi la tua mano!", enHash = "210374db", vanilla = true },
        objectives = { it = "Uccidi 12 Galak Scout, 10 Galak Wrangler e 6 Galak Windchaser, poi torna da Cliffwatcher Longhorn, a Freewind Post.", enHash = "fc762583", vanilla = true },
        progress = { it = "Suvvia, $N, lo so che non ne hai ancora uccisi abbastanza. Dagli la caccia, e ti darò una ricompensa in segno di gratitudine.", enHash = "c2f19b74", vanilla = true },
        reward = { it = "In segno di gratitudine, questo è per te, $N.", enHash = "9298f420", vanilla = true },
    },
    [4865] = {
        title = { it = "Serpente selvaggio", enHash = "585db1ef", vanilla = true },
        text = { it = "Se non l'avessi visto con i miei occhi non ci avrei mai creduto. La vendetta è arrivata a Thousand Needles!\n\n<Hagar si asciuga la fronte.>\n\n$N, devi agire in fretta! Va' subito a cercare Motega Firemane; si trova a Whitereach Post, appena a nord-ovest di Freewind Post lungo la strada. Lui saprà cosa fare!", enHash = "1a9d2b87", vanilla = true },
        objectives = { it = "Riferisci quel che hai scoperto a Motega Firemane.", enHash = "91b70aea", vanilla = true },
        reward = { it = "Vendetta! Allora la leggenda di Arikara è vera. Sì, è un problema da risolvere subito.", enHash = "cb207b39", vanilla = true },
    },
    [4881] = {
        title = { it = "Complotto omicida", enHash = "dd904a71", vanilla = true },
        text = { it = "Il tauren Kanati Greycloud ha l'ardire di piantare un campo di caccia a Thousand Needles. Dobbiamo ucciderlo per liberarci di questo campo e di tutti quelli che potrebbero seguirlo. Ci raduneremo al piccolo avamposto a sud-ovest del Great Lift.", enHash = "873812e3", vanilla = true },
        objectives = { it = "Avverti Kanati Greycloud, a Whitereach Post, del complotto per ucciderlo.", enHash = "b2c2d9cb", vanilla = true },
        reward = { it = "Vengono a uccidermi? Mostrerò loro come combatte un tauren!", enHash = "dfb1e22d", vanilla = true },
    },
    [4904] = {
        title = { it = "Finalmente libera", enHash = "0de2a4af", vanilla = true },
        text = { it = "Arnak crede che ci sposeremo... ma dopo che ho rifiutato la sua proposta è tornato quella notte e mi ha rapita. Mio fratello ha cercato di fermarlo, ma Arnak era troppo forte. Lui... ha ucciso mio fratello e poi mi ha portata qui. Povero fratello mio...\n\n$N, potresti scortarmi fuori da Darkcloud Pinnacle? Ti prego... devo tornare da Thalia! Sarà preoccupatissima per me.", enHash = "90a99e86", vanilla = true },
        objectives = { it = "Scorta Lakota Windsong fuori da Darkcloud Pinnacle, poi parla con Thalia Amberhide, a Freewind Post.", enHash = "56548e75", vanilla = true },
        progress = { it = "Thalia Amberhide:", enHash = "fd05a8fe", vanilla = true },
        reward = { it = "Grazie, $N. Lo sentivo nelle ossa che avrebbe ritrovato la strada per tornare da me. Mi ha raccontato del tuo coraggio e di come l'hai aiutata a fuggire. Questi oggetti erano di suo fratello. So che vorrebbe li avessi tu.", enHash = "8bd06d88", vanilla = true },
    },
    [4921] = {
        title = { it = "Perduta in battaglia", enHash = "e65fd617", vanilla = true },
        text = { it = "Stavamo combattendo in un piccolo accampamento tauren quando ci siamo separati — lei da sola teneva a bada tre Bristleback. Ma il loro numero ha cominciato a travolgerci. Ne ho attirati via alcuni, solo per vederla sopraffatta da altri che arrivavano. Nella mia furia mi sono voltato ad affrontare i nemici, ma mi hanno atterrato facilmente, tanti com'erano.\n\nMi sono svegliato con un druido tauren che mi curava le ferite — mi aveva trovato sulla Gold Road, là dove ero caduto.\n\nTi prego, $C, trova una traccia di mia moglie.", enHash = "e797cc35", vanilla = true },
        objectives = { it = "Trova la moglie di Mankrik, poi torna da lui al Crossroads.", enHash = "3cf36fbd", vanilla = true },
        progress = { it = "Hai trovato una traccia di lei, una qualsiasi? Il dolore che ho nel petto mi dice che è successo il peggio, ma spero ancora che tu la trovi sana e salva.", enHash = "d88eadf4", vanilla = true },
        reward = { it = "Capisco. Grazie, $C.", enHash = "13e6c159", vanilla = true },
    },
    [4966] = {
        title = { it = "Proteggi Kanati Greycloud", enHash = "dc6f4405", vanilla = true },
        text = { it = "Però i centauri potrebbero essere più di quanti pensassi: ti chiedo, $N, di combattere al mio fianco contro questi vili assassini.", enHash = "77cd930d", vanilla = true },
        objectives = { it = "Proteggi Kanati Greycloud dall'attacco dei centauri.", enHash = "e14f1172", vanilla = true },
        reward = { it = "Grazie del tuo aiuto, $N. Senza di te non sarei riuscito a tenerli a bada.", enHash = "5a48214a", vanilla = true },
    },
    [5041] = {
        title = { it = "Rifornimenti per il Crossroads", enHash = "d7e3458c", vanilla = true },
        text = { it = "Quella carovana attaccata trasportava rifornimenti di cui avevamo un bisogno disperato.\n\nFinora sei $Gstato:stata; abbastanza $Gcoraggioso:coraggiosa; da affrontare la tribù Razormane, e ti chiederò di farlo di nuovo; ma questa volta vorrei chiederti anche di tenere gli occhi aperti per qualcuno dei nostri rifornimenti perduti. Probabilmente li trovi sparsi per i loro accampamenti, mentre i quilboar ingrassano con le loro azioni disonorevoli.\n\nLa gente del Crossroads te ne sarebbe debitrice.", enHash = "2c26d8d5", vanilla = true },
        objectives = { it = "Trova e riporta Crossroads' Supply Crate a Thork, nelle Barrens.", enHash = "55520f67", vanilla = true },
        progress = { it = "Come procede la ricerca dei rifornimenti, $N? Confido che i quilboar cadano facilmente sotto la tua forza.", enHash = "3e68fd26", vanilla = true },
        reward = { it = "Ahah! Grazie, $N! Questo ci aiuterà moltissimo. Sei una fortuna per il Crossroads e per l'Orda. Se posso fare qualcosa per te, dimmelo.", enHash = "8f1f136f", vanilla = true },
    },
    [5042] = {
        title = { it = "La forza di Agamaggan", enHash = "e46575d9", vanilla = true },
        progress = { it = "Mi serviranno 4 Blood Shard, se vuoi la forza di Agamaggan, $R.\n\nI tuoi nemici si acquatteranno davanti alla tua forza, se ti venisse data questa benedizione. <grugnito>\n\nI più grandi guerrieri dei Razormane sono intrisi di questo potere!", enHash = "f34692ee", vanilla = true },
        reward = { it = "Se solo Mangletooth fosse libero di vederti decimare quelli che lo hanno tradito! <grugnito>\n\nTi ringrazio per aver distrutto altri Bristleback raccogliendo questi Blood Shard. Ti prego, continua così, e io continuerò ad aiutarti. <grugnito>", enHash = "2ff43d1d", vanilla = true },
    },
    [5043] = {
        title = { it = "L'agilità di Agamaggan", enHash = "f672b7ad", vanilla = true },
        progress = { it = "Si dice che i più grandi esploratori della mia tribù non abbiano rivali in precisione, e nessun ladro <grugnito> potrebbe reggere il confronto con la loro rapidità in battaglia.\n\nPortami 4 Blood Shard e ti renderò più agile di qualunque quilboar mai nato.", enHash = "4401d8a5", vanilla = true },
        reward = { it = "Che la tua mira non sbagli, e che il segno della tua arma sia giusto, $R.\n\nLo spirito di Agamaggan è con te. Torna <grugnito> da me se vuoi. Mangletooth ti benedirà di nuovo, se il grande dio cinghiale mi riterrà degno. <grugnito>", enHash = "81ddcc48", vanilla = true },
    },
    [5044] = {
        title = { it = "La saggezza di Agamaggan", enHash = "7be47652", vanilla = true },
        progress = { it = "Gli sciamani e i geomanti delle tribù quilboar <grugnito> invocano la forza di Agamaggan perché li aiuti in battaglia e nei loro rituali, $R.\n\nSe anche tu vuoi il potere in più della benedizione di Agamaggan sui tuoi incantesimi, portami 4 Blood Shard e Mangletooth ti aiuterà. <grugnito>", enHash = "282bcbd2", vanilla = true },
        reward = { it = "I tuoi nemici dovrebbero temerti ancora di più, $R. <grugnito>\n\nRacconta a Mangletooth le storie della tua astuzia in battaglia, la prossima volta che ci incontriamo — in questa vita o nell'altra. <grugnito>", enHash = "55824bd3", vanilla = true },
    },
    [5045] = {
        title = { it = "Spirito in ascesa", enHash = "5b72a00b", vanilla = true },
        progress = { it = "I guerrieri di ogni tipo <grugnito> hanno bisogno di uno spirito forte. Ti spinge a imprese più grandi quando ogni speranza è perduta. Non è cosa ignota ai <grugnito> Razormane. Siamo una tribù spirituale — andiamo più fieri del nostro legame con Agamaggan che del nostro valore <grugnito> in battaglia.\n\nPortami 4 Blood Shard e benedirò il tuo spirito per la battaglia. <grugnito>", enHash = "00a2e92b", vanilla = true },
        reward = { it = "I nostri guerrieri più grandi, e i nostri più grandi <grugnito> sciamani, invidierebbero la tua volontà, $R.\n\nSconfiggi altri Bristleback sapendo che non possono fermarti! <grugnito>", enHash = "0a20e009", vanilla = true },
    },
    [5046] = {
        title = { it = "Razorhide", enHash = "5c64ed90", vanilla = true },
        progress = { it = "Tutti quelli che <grugnito> vanno in battaglia hanno bisogno di protezione. Le loro ossa devono essere forti. La loro pelle dura. <grugnito> Anche la mia tribù lo sa, e per aggiungere qualcosa alla protezione naturale che ci danno le nostre spine e il nostro cuoio, <grugnito> invochiamo spesso Agamaggan perché ci protegga dal male prima di andare in guerra.\n\nPortami 4 Blood Shard <grugnito> e ti darò la stessa protezione.", enHash = "bed551df", vanilla = true },
        reward = { it = "Va' in guerra, $R.", enHash = "47337a11", vanilla = true },
    },
    [5048] = {
        title = { it = "La buona Emma", enHash = "3efb6c62", vanilla = true },
        text = { it = "È un po' scorbutica, e forse le manca qualche rotella... ma dai registri risulta che Ol' Emma corrisponde davvero a chi potrebbe essere Emma Felstone.\n\nForse hai visto Ol' Emma girare per la città: parla da sola, di solito dicendo cose senza senso. Comunque non fa male a niente e a nessuno, quindi la gente la lascia in pace.\n\nTutto considerato, direi che Ol' Emma è proprio Emma Felstone. Potresti provare a chiederle se il suo cognome è davvero Felstone.", enHash = "7b4eaa3c", vanilla = true },
        objectives = { it = "Trova Ol' Emma a Stormwind e scopri se è davvero Emma Felstone. Se lo è, forse le farebbe piacere il pacco che Janice Felstone ha preparato per lei.", enHash = "56fef300", vanilla = true },
        progress = { it = "Ti direi di levarti dal mio prato, ma come vedi non ce l'ho.", enHash = "e5d54dce", vanilla = true },
        reward = { it = "Il mio nome è proprio Emma Felstone: sei la prima persona da anni a chiamarmi così. Chi... chi sei?\n\nDici che conoscevi... mia sorella?! È ancora viva? Ma chi voglio prendere in giro, certo che no. Quando scoppiò la piaga a Lordaeron, mi aspettavo il peggio. Tanti della mia famiglia sono morti... o peggio. Ed eccomi qui, la pazza Ol' Emma, tutta sola. Che cosa sei, $Gun tombarolo:una tombarola; o qualcosa del genere? Cerchi il tuo prossimo bersaglio?\n\nCosa... hai un pacco per me da parte di mia sorella?", enHash = "341ef595", vanilla = true },
    },
    [5052] = {
        title = { it = "I Blood Shard di Agamaggan", enHash = "e4148d18", vanilla = true },
        text = { it = "Insieme alle spine, il sangue ha toccato <grugnito> altre parti della terra: pietre rosso sangue mescolate agli altri minerali. I Bristleback dissotterrano questi Blood Shard e li portano come totem <grugnito> per avere forza in battaglia e come totem per le loro magie. <grugnito>\n\nIo conosco i segreti di quella magia.\n\nPorta a Mangletooth uno di questi Blood Shard per dimostrare che hai capito. Portane molti a Mangletooth, e ti benedirà con la magia quilboar — la magia di Agamaggan! <grugnito>", enHash = "061f1934", vanilla = true },
        objectives = { it = "Porta un Blood Shard a Mangletooth, a Camp Taurajo, nelle Barrens.\n\nRaccogli altri Blood Shard se vuoi che ti benedica con il potere di Agamaggan.", enHash = "3bafdd37", vanilla = true },
        progress = { it = "Le nostre tribù si radunano nelle zone spinose di tutte le Barrens <grugnito> perché sono luoghi sacri, ma nessuno è sacro quanto il Razorfen. Il corpo di Agamaggan forma per intero il Razorfen, <grugnito> ma le Downs sono protette in modo particolare, perché l'ingresso è fatto delle sue grandi fauci! <grugnito> Inghiottirà interi quelli che non gli sono fedeli, e sputerà fuori i loro corpi dopo averli masticati! <grugnito>\n\nAgamaggan ha lasciato indietro il suo corpo per proteggerci, e dona il suo spirito perché noi possiamo proteggere lui. <grugnito>", enHash = "99bdeb00", vanilla = true },
        reward = { it = "Ah, hai capito davvero. <grugnito> Le mie parole non sono andate perse nelle tue orecchie, $R. Mangletooth sarà anche in gabbia, ma nessuna gabbia può fermare il potere di Agamaggan! <grugnito>\n\nIl contatto del Blood Shard, la sua sensazione... era da tanto, $R.\n\nSai com'è? Avere il tuo potere reciso da te?\n\nMa questa è una storia per un'altra volta. Ti ho promesso informazioni. Ti ho promesso il potere di Agamaggan. La mia gente ha voltato le spalle a Mangletooth. Ora ti scateno contro di loro. <grugnito>", enHash = "15868800", vanilla = true },
    },
    [5061] = {
        title = { it = "Aquatic Form", enHash = "e61ab7d2", vanilla = true },
        text = { it = "Hai completato le lezioni che tutti i giovani druidi devono imparare prima di poter assumere un aspetto acquatico. Ora torna dal tuo istruttore, Mathrengyl Bearwalker, a Darnassus. Mostragli il tuo pendente e dimostragli che sei $Gpronto:pronta; a imparare ciò che ha da insegnarti. Completerà il tuo addestramento, permettendoti di diventare una cosa sola con l'acqua.\n\nArrivederci, giovane $Gdruido:druida;. Parleremo ancora.", enHash = "78ed48a2", vanilla = true },
        objectives = { it = "Torna a Darnassus e mostra il Pendant of the Sea Lion a Mathrengyl Bearwalker.", enHash = "ea6fe024", vanilla = true },
        progress = { it = "La notizia del tuo ritorno a Darnassus ti ha preceduto, ma mi servirà una prova delle lezioni che hai imparato a Moonglade prima di insegnarti la tua Aquatic Form.\n\nHai il Pendant of the Sea Lion?", enHash = "02f76658", vanilla = true },
        reward = { it = "Davvero notevole, $N. Sei $Gpronto:pronta; a imparare la tua Aquatic Form, ed è un piacere per me insegnartela.\n\nInoltre, in riconoscimento di quanto hai fatto nelle due prove, ti do questo oggetto. Spero che sia un'aggiunta gradita al tuo equipaggiamento di $Gprotettore:protettrice; della natura e custode dell'equilibrio.", enHash = "5f0340bc", vanilla = true },
    },
    [5062] = {
        title = { it = "Il fuoco sacro", enHash = "96b9f73a", vanilla = true },
        text = { it = "Arikara è una creatura letale di cui bisogna occuparsi in fretta. Per darle la caccia dovrai accendere il fuoco sacro della vita: sarà questo a evocare Arikara.\n\nVa' a raccogliere la rara pianta di Incendia agave. Quando ne avrai raccolta abbastanza, va' a chiedere consiglio a Magatha Grimtotem, all'Elder Rise di Thunder Bluff. È una sciamana potente e può incantare la pianta di agave per creare una polvere che accenda il fuoco.\n\nViaggia a nord-est fino al Boiling Pool e raccogli Incendia Agave.", enHash = "c6312bc5", vanilla = true },
        objectives = { it = "Raccogli 10 fasci di Incendia Agave, poi consulta Magatha Grimtotem, all'Elder Rise di Thunder Bluff.", enHash = "19cb79a5", vanilla = true },
        progress = { it = "Allora, Motega Firemane manda notizia di Arikara... be', è una brutta notizia.\n\n<Magatha si guarda intorno.>\n\nArikara è una creatura letale che nasce solo per cercare vendetta contro chi ha commesso atti atroci.\n\n<Magatha sorride.>", enHash = "55365008", vanilla = true },
        reward = { it = "Bene, hai raccolto la quantità necessaria di Incendia agave. Quest'erba rara, che si trova solo a Thousand Needles, aiuterà ad accendere il fuoco sacro della vita, ormai sopito.\n\n<Magatha comincia a incantare l'Incendia agave.>", enHash = "07c308a4", vanilla = true },
    },
    [5064] = {
        title = { it = "Spiare i Grimtotem", enHash = "d55e3eb4", vanilla = true },
        text = { it = "$N, in passato ci hai servito bene, e per questo ora ti affido una missione importante. Il Grimtotem Clan sta tramando qualcosa in segreto. Nelle ultime settimane tre agenti di origine ignota sono stati visti in visita dai Grimtotem. Abbiamo scoperto che questi messaggi sorvegliati si trovano in casse separate a Darkcloud Pinnacle.\n\n$N, se riuscirai in questa missione pericolosa, ti ricompenserò come meriti.", enHash = "94406203", vanilla = true },
        objectives = { it = "Trova e recupera le tre Secret Note a Darkcloud Pinnacle.", enHash = "6892d2ff", vanilla = true },
        progress = { it = "Hai scoperto cosa stanno tramando i Grimtotem?", enHash = "eed42565", vanilla = true },
        reward = { it = "Grande Spirito del Totem! Sono notizie davvero gravi. Devo cominciare a prepararmi a qualunque cosa accada.\n\n$N, come promesso, ecco la tua ricompensa per il coraggioso servizio.", enHash = "0fdcae75", vanilla = true },
    },
    [5066] = {
        title = { it = "Chiamata alle armi: le Plaguelands!", enHash = "ea8300d9", vanilla = true },
        text = { it = "Udite, udite! Tutti gli eroi sono chiamati ad ascoltare queste parole!\n\nIl Regno di Stormwind ha lanciato una chiamata alle armi! Tutti coloro che sono in grado di combattere sono invitati a prendere le armi contro l'oscura minaccia del Flagello nelle terre settentrionali degli Eastern Kingdoms! Corrono voci di nuove minacce che sorgono dalle rovine delle Plaguelands!\n\nEroi del reame, cercate Commander Ashlam Valorfist, che ha allestito il suo accampamento a Chillwind Camp, a nord delle Alterac Mountains!", enHash = "de8d93fd", vanilla = true },
        objectives = { it = "Cerca Commander Ashlam Valorfist. Il suo accampamento si trova a Chillwind Camp, a nord delle Alterac Mountains.", enHash = "6cac7edb", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta; nelle Plaguelands, $Geroe:eroina;. È una delle frontiere più pericolose di Azeroth, soprattutto con la minaccia incombente del Flagello a nord e a nord-est. Sono lieto di sapere che il richiamo del dovere e del servizio al bene comune non è caduto nel vuoto con te!\n\nSe sei $Gpronto:pronta; a sporcarti le mani, qui ai margini delle Plaguelands c'è tanto da fare per gli eroi volenterosi e capaci.", enHash = "9bd842e4", vanilla = true },
    },
    [5088] = {
        title = { it = "Arikara", enHash = "d3beac5d", vanilla = true },
        text = { it = "Porta questa polvere di Incendia raffinata e purificata a Thousand Needles e gettala sul fuoco sacro della vita. Si trova a Darkcloud Pinnacle, su un pinnacolo isolato dove seppelliscono i loro morti.\n\nL'incantesimo che ho intessuto nella polvere di Incendia evocherà Arikara davanti a te, $N.\n\nTemo che stia dando la caccia a Cairne Bloodhoof; troppe tradizioni tauren sono cambiate, e temo che questo abbia fatto infuriare Arikara. Muoviti in fretta, prima che tutto sia perduto, $C!", enHash = "23f78f94", vanilla = true },
        objectives = { it = "Uccidi Arikara. Porta i suoi resti e la polvere di Incendia a Motega Firemane, a Whitereach Post, come prova di quel che hai fatto.", enHash = "1376619a", vanilla = true },
        progress = { it = "Hai ucciso il serpente feroce, Arikara, $N?", enHash = "7c1d3390", vanilla = true },
        reward = { it = "Non ha senso. Perché Arikara dovrebbe dare la caccia a Cairne Bloodhoof? Magatha non può sbagliarsi, è la nostra sciamana più potente.\n\n<Motega scuote la testa.>\n\nIn ogni caso la tua grande impresa per l'Orda non passerà inosservata: ti prego, scegli una di queste cose come ricompensa per il tuo aiuto.", enHash = "56048c1b", vanilla = true },
    },
    [5147] = {
        title = { it = "Wanted — Arnak Grimtotem", enHash = "99221715", vanilla = true },
        text = { it = "Wanted: Arnak Grimtotem\n\nArnak il reietto è ricercato per gli atroci crimini di omicidio e rapimento. Belle ricompense saranno date a chi avrà il coraggio di consegnare questo criminale alla giustizia.\n\nArnak è stato visto l'ultima volta sulle scogliere vicino a Darkcloud Pinnacle. Mostra la prova di quel che hai fatto a Cliffwatcher Longhorn, a Freewind Post, per riscuotere la ricompensa.", enHash = "cb59e4de", vanilla = true },
        objectives = { it = "Uccidi Arnak Grimtotem e porta la prova di quel che hai fatto a Cliffwatcher Longhorn, a Freewind Post.", enHash = "c99d590e", vanilla = true },
        progress = { it = "Hai notizie di quell'assassino di Arnak Grimtotem?", enHash = "3eaa7ef0", vanilla = true },
        reward = { it = "Ah! Be', questa sì che è un'ottima notizia! Cominciavo a pensare che non sarebbe mai stato consegnato alla giustizia!\n\nEccoti qua, $N... e grazie. La notizia delle malefatte di Arnak mi faceva ribollire il sangue!", enHash = "fc447ec6", vanilla = true },
    },
    [5151] = {
        title = { it = "Hypercapacitor Gizmo", enHash = "f8cd5fb0", vanilla = true },
        text = { it = "Sono l'unico superstite dell'attacco dei centauri alla nostra carovana! Una pantera rara ma possente sta facendo la guardia al mio aggeggio migliore, che porta al collo. Ah! Perfino i centauri tremano davanti a quella bestia feroce!\n\nEcco la chiave della gabbia. Là hanno preso tutto, ma lei l'hanno lasciata stare. Uccidi questa bestia e riportami il mio ipercondensatore, e ti ricompenserò.\n\nLa carovana distrutta è appena a nord di qui.", enHash = "f97d7c1e", vanilla = true },
        objectives = { it = "Uccidi la bestia e riporta l'Hypercapacitor Gizmo e la Panther Cage Key a Wizlo Bearingshiner.", enHash = "60332917", vanilla = true },
        progress = { it = "Ce l'hai il mio ipercondensatore?", enHash = "e45fca57", vanilla = true },
        reward = { it = "Il mio ipercondensatore! Questo mi terrà occupato per un bel po', finché non capirò a cosa serve...", enHash = "9bc8a021", vanilla = true },
    },
    [5261] = {
        title = { it = "Eagan Peltskinner", enHash = "1e09bab9" },
        text = { it = "Eagan Peltskinner cerca qualcuno che vada a caccia di lupi per lui. È una buona notizia, perché ultimamente vediamo molti più lupi nella Northshire Valley.\n\nSe ti interessa, parla con Eagan. È sul lato dell'abbazia, a sinistra.", enHash = "ea7bcd14" },
        objectives = { it = "Parla con Eagan Peltskinner.", enHash = "cc7cf7e1" },
        reward = { it = "È vero. Cerco qualcuno che vada a caccia di lupi per me! Sei tu la persona giusta?", enHash = "1e3f9c1d" },
    },
    [5321] = {
        title = { it = "Il dormiente si è svegliato", enHash = "24b9ddd9", vanilla = true },
        text = { it = "Ero diretto a Maestra's Post per incontrare Liladris Moonriver, ma ho deciso di fermarmi qui a farmi un pisolino. Da quando mi sono svegliato dall'Emerald Dream, ho sempre tanto sonno...\n\n<sbadiglio>\n\nTi dispiacerebbe mostrarmi la strada? Mi risulta che Maestra's Post sia a sud di qui, lungo la strada, in Ashenvale. Può essere pericoloso, quindi spero che tu abbia degli amici che vengano con noi.\n\nUn'ultima cosa: potrei addormentarmi, quindi se ti serve svegliarmi usa il mio corno. Lo trovi qui nella cassa.", enHash = "cc3b2ee7", vanilla = true },
        objectives = { it = "Scorta Kerlonian Evershade da Liladris Moonriver, a Maestra's Post, in Ashenvale.", enHash = "3ff746ce", vanilla = true },
        progress = { it = "Kerlonian è arrivato?", enHash = "b84400b5", vanilla = true },
        reward = { it = "Oh, sono così felice che Kerlonian ce l'abbia fatta! E scommetto che lo troverò addormentato qui da qualche parte, vero?\n\nGrazie per avergli mostrato la strada, $N.", enHash = "d580fe3b", vanilla = true },
    },
    [5361] = {
        title = { it = "Albero genealogico", enHash = "c10686da", vanilla = true },
        text = { it = "Mio fratello Nataka è di stanza al Ghost Walker Post, laggiù a Desolace. Vorrei chiederti... potresti consegnargli questo rapporto da parte mia? È passato un anno dall'ultima volta che gli ho scritto: da allora i centauri sono stati insolitamente attivi, e lui dovrebbe esserne informato.\n\nViaggia fino alla Stonetalon Mountain, a nord del Crossroads, e poi dirigiti a ovest nella Charred Vale. Da lì prosegui a sud, fino a Desolace; là troverai una strada che porta a sud, fino al Ghost Walker Post.", enHash = "80019c66", vanilla = true },
        objectives = { it = "Consegna Cliffwatcher Longhorn Report a Nataka Longhorn, al Ghost Walker Post, a Desolace.", enHash = "4f01c28b", vanilla = true },
        progress = { it = "Che notizie porti, $C? Ah, un messaggio da parte di mio fratello, dici? Be', allora consegnami il rapporto!", enHash = "4f923ce1", vanilla = true },
        reward = { it = "Non so che legame tu abbia con mio fratello, ma a quanto pare ha fiducia in te, $C.\n\nIo sono Nataka Longhorn e vorrei darti il benvenuto al Ghost Walker Post: abbiamo molto bisogno di $Gun:una; $C! Parla con gli altri, forse qui c'è bisogno di te.", enHash = "6a708451", vanilla = true },
    },
    [5381] = {
        title = { it = "Hand of Iruxos", enHash = "266e2068", vanilla = true },
        text = { it = "La Burning Blade possiede la Demon Box. Al suo interno si trova la potente Hand of Iruxos. La Burning Blade la usa per aprire portali demoniaci alla Mannoroc Coven. Dobbiamo fermare l'ondata di demoni che entra nel nostro mondo, $N!\n\nUsa questo Demon Pick sul cristallo rosso nella Thunder Axe Fortress per accedere alla Demon Box.", enHash = "55260d6f", vanilla = true },
        objectives = { it = "Recupera la Demon Box dalla Thunder Axe Fortress e riportala, insieme al Demon Pick, a Taiga Wisemane, a Shadowprey Village.", enHash = "ee902c84", vanilla = true },
        progress = { it = "$N, hai la Demon Box?", enHash = "3478e8d8", vanilla = true },
        reward = { it = "Ah, la Demon Box. Dammela, $C, e la aprirò... rivelandoti così la Hand of Iruxos.", enHash = "33b6514f", vanilla = true },
    },
    [5386] = {
        title = { it = "Il pescato del giorno", enHash = "442488a9", vanilla = true },
        text = { it = "Qui al Ghost Walker Post manca da tempo l'odore del pesce cotto. I troll di Shadowprey Village sono i migliori a pescare... ma purtroppo, con i centauri così attivi, ho poco tempo per fare un viaggio fino dai troll. Mmh...\n\nFammi un favore e va' a Shadowprey Village. Parla con Jinar'Zillen, il pescatore del posto, e portami i Bloodbelly Fish, i miei preferiti. La strada a sud di qui ti porterà a ovest, fino al villaggio dei troll.", enHash = "c91a3000", vanilla = true },
        objectives = { it = "Parla con Jinar'Zillen a Shadowprey Village, poi porta a Nataka Longhorn 2 Bloodbelly Fish.", enHash = "8055254c", vanilla = true },
        progress = { it = "Mi formicola lo zoccolo e mi viene l'acquolina in bocca quando penso ai Bloodbelly Fish fritti... Ne hai con te?", enHash = "97b5b681", vanilla = true },
        reward = { it = "Sei $Gun salvatore:una salvatrice;, $N! Questi Bloodbelly Fish sembrano così buoni che si potrebbero quasi mangiare crudi.\n\n<Nataka comincia a salivare.>\n\nEcco qua — scegli uno di questi oggetti come pagamento per questi pesci.", enHash = "456bb946", vanilla = true },
    },
    [5421] = {
        title = { it = "Pesci nel secchio", enHash = "460b5d5c", vanilla = true },
        progress = { it = "Ricompenserò chiunque mi renda la vita un po' più facile... Mi piace fare il meno possibile, $Gamico:amica;!\n\nSotto i moli, qui a Shadowprey Village, ho un sacco di trappole per molluschi. Se sei così gentile da fare il lavoro al posto mio e raccogliermi i molluschi, ti ricompenserò con qualcosa che vuoi... capisci cosa intendo, $Gamico:amica;? Per ogni cinque molluschi che mi porti ti darò un bel Bloodbelly Fish!", enHash = "2d902f43", vanilla = true },
        reward = { it = "Ottimo, $Gamico:amica;, non c'è niente di meglio di un lavoro fatto, soprattutto se a farlo è qualcun altro... eh?", enHash = "a0f94ccd", vanilla = true },
    },
    [5441] = {
        title = { it = "I Lazy Peon", enHash = "fc0020b3" },
        text = { it = "Maledetti peon! Lavorano sodo a raccogliere legname dagli alberi della valle, ma schiacciano sempre un pisolino! Mi serve qualcuno che aiuti a tenere in riga i peon.\n\nSembri proprio $Gun:una; $R $Gadatto:adatta; al mio compito. Ecco, prendi questo manganello e usalo su tutti i Lazy Peon che trovi a dormire sul lavoro. Una bella botta li rimetterà subito al lavoro! Riportami il manganello quando hai finito.\n\nMaledetti peon fannulloni...", enHash = "646310ea" },
        objectives = { it = "Usa il Foreman's Blackjack sui Lazy Peon quando dormono. Sveglia 5 peon, poi riporta il Foreman's Blackjack a Foreman Thazz'ril nella Valley of Trials.", enHash = "43354c13" },
        progress = { it = "Fannulloni buoni a nulla...\n\nEh? Hai il mio manganello? Hai beccato qualche peon a dormire sul lavoro?!", enHash = "47e0dc07" },
        reward = { it = "Bene, bene. Magari la prossima volta ci penseranno due volte prima di battere la fiacca! Grazie dell'aiuto!", enHash = "00f77bf6" },
    },
    [5481] = {
        title = { it = "Il compito di Gordo", enHash = "3afeb7c4", vanilla = true },
        text = { it = "Padrone vuole erbe. Noi avere mani grandi e non bravi a raccogliere. Tu aiuti noi e noi non fare male a te. Noi servire Gloom Weed. Tante erbe qui intorno e vicino strada.\n\nQuando tu avere Gloom Weed tu portare a Master Holland nel cimitero di Brill.", enHash = "23e6991a", vanilla = true },
        objectives = { it = "Raccogli 3 Gloom Weed e consegnale a Junior Apothecary Holland, nel cimitero di Brill.", enHash = "5817a520", vanilla = true },
        progress = { it = "Dov'è quell'abominio buono a nulla? O hai quello che mi serve, o faresti meglio ad andare là fuori a trovarlo.", enHash = "7d4cf971", vanilla = true },
        reward = { it = "E questo cosa sarebbe? Gloom Weed?! Non me ne faccio niente della Gloom Weed! Quella massa di carne senza cervello è là fuori a raccogliere margherite e a convincere la Signora sa quanti babbei come te a fare lo stesso. Senza offesa.\n\nE va bene, ormai sei qui, ed è questo che conta. Visto che non ho intenzione di provare a spiegare le cose a quell'abominio, che ne dici di raccogliere quello che mi serve davvero... la Doom Weed!", enHash = "6d43cc9f", vanilla = true },
    },
    [5482] = {
        title = { it = "Doom Weed", enHash = "a12c4e04", vanilla = true },
        text = { it = "Così vedi in che situazione mi trovo, $N. Quel coso è là fuori a raccogliere le erbe sbagliate! Ti ripagherò bene se raccogli tu quello che mi serve. Riportami abbastanza Doom Weed e ti darò una ricompensa adeguata.\n\nPer quanto ne so, amano infestare la flora vicino alla fossa comune, a nord del cimitero di Brill. Sbrigati, e sta' $Gattento:attenta; agli gnoll della zona.", enHash = "00ea333e", vanilla = true },
        objectives = { it = "Raccogli 10 Doom Weed e riportale a Junior Apothecary Holland.", enHash = "5641e5d6", vanilla = true },
        progress = { it = "Spero proprio che sia una buona notizia. Confido che tu abbia tutta la Doom Weed che mi serve.", enHash = "49bf329a", vanilla = true },
        reward = { it = "Ah, la mia Doom Weed. Eccellente!\n\n<Junior Apothecary Holland si sfrega le mani con avidità.>\n\nQueste torneranno molto utili. Oggi hai reso a me, ehm, alla Lady, un bel servizio, $N. Come promesso, ecco la ricompensa che ti meriti.", enHash = "5fff4b51", vanilla = true },
    },
    [5501] = {
        title = { it = "Il raccoglitore di ossa", enHash = "e7b88631", vanilla = true },
        text = { it = "Qui abbiamo per le mani una miniera d'oro, te lo dico io — una miniera d'oro! Le ossa di kodo cambieranno il mondo per sempre... ho clienti che ci fanno mobili, strumenti musicali e perfino polvere esplosiva.\n\nC'è una carovana che passa a ritirare le mie ossa di kodo e poi le vende a Shadowprey Village. Se riesci ad andare al Kodo Graveyard a sud di qui e a portarmi dieci Kodo Bone, ti darò qualcosa in cambio. Affare fatto?", enHash = "d352cbe3", vanilla = true },
        objectives = { it = "Porta 10 Kodo Bone dal Kodo Graveyard a Bibbly F'utzbuckle, al Kormek's Hut.", enHash = "677f85fe", vanilla = true },
        progress = { it = "Hai le ossa? La carovana arriverà da un momento all'altro. Mi servono solo altri dieci Kodo Bone per raggiungere il record della mia carriera. Il record della mia carriera, te lo dico io!", enHash = "48f3392e", vanilla = true },
        reward = { it = "Ah, che bello! Le mie ossa!\n\nNon vedo l'ora che i ragazzi a casa vedano la mia faccia sulla copertina di Goblin'preneur. Sarò il goblin più ricco del mondo... e il mio insegnante di educazione fisica diceva che non avrei mai combinato niente.", enHash = "c52b073e", vanilla = true },
    },
    [5502] = {
        title = { it = "$GUn tutore:Una tutrice; dell'Orda", enHash = "d9b69c70", vanilla = true },
        text = { it = "Sei $Gstato:stata; così gentile con me, $N. Non avrei mai sognato di divertirmi così tanto durante la Settimana dei Bambini. Grazie. Non sarò triste per quello che mi è successo: i miei genitori mi hanno sempre detto di superare qualunque cosa brutta succeda. Sarò un eroe... proprio come te.\n\nMi dispiace dirlo, ma è ora che torni a casa. Torniamo indietro, e dirò alla matrona che persona fantastica sei!", enHash = "86148b41", vanilla = true },
        objectives = { it = "Riporta il tuo protetto all'orfanotrofio di Orgrimmar consegnando l'Orcish Orphan Whistle a Orphan Matron Battlewail, nella Valley of Honor.", enHash = "7bc84515", vanilla = true },
        progress = { it = "È un piacere rivederti, $N. Hai portato a termine i compiti di cui ti sei $Gfatto:fatta; carico durante la Settimana dei Bambini?", enHash = "3e18d334", vanilla = true },
        reward = { it = "Che gli spiriti ti benedicano, $N. Hai fatto per Grunth più di quanto la maggior parte della gente penserebbe mai di fare per lui. Grazie: sei l'esempio perfetto di cosa significhi essere $Gun eroe:un'eroina; dell'Orda.\n\nTi prego, se riesci a trovare un po' di tempo, torna a trovarci. So che a Grunth farebbe piacere, e anche a me.\n\nGrunth si è divertito tantissimo con te, $N. Voleva darti uno dei suoi animaletti preferiti, perché ti ricordi di lui.", enHash = "9cd7e06b", vanilla = true },
    },
    [5541] = {
        title = { it = "Munizioni per Rumbleshot", enHash = "399ae054", vanilla = true },
        text = { it = "Hegnar Rumbleshot vende armi da fuoco lungo la strada per Anvilmar. Fucilieri e squadre di mortai passano molto tempo ad allenarsi vicino alla sua bottega, e ha sempre bisogno di munizioni nuove.\n\nMa... l'ultima cassa di munizioni che gli ho mandato si è persa per strada. Il mio corriere ha detto che era accampato vicino al Grizzled Den quando i Wendigo l'hanno cacciato via... e quello sciocco ha lasciato lì le munizioni di Rumbleshot!\n\n$N, puoi recuperare quelle munizioni e portarle a Rumbleshot? Le aspetta da un pezzo e di sicuro sta per restare a secco.", enHash = "30ed6a91", vanilla = true },
        objectives = { it = "Porta Rumbleshot's Ammo a Hegnar Rumbleshot, nel Dun Morogh.", enHash = "e7a1de68", vanilla = true },
        progress = { it = "Spero che tu non sia qui per le munizioni, perché sono quasi a secco!", enHash = "41582256", vanilla = true },
        reward = { it = "Ottimo, altre munizioni! La spedizione del vecchio Loslor è finalmente arrivata! Saranno anche in ritardo, ma come diceva sempre mio nonno: meglio tardi che mai!\n\nGrazie mille, $N. Ho già clienti che non vedono l'ora di mettere le mani su questa roba!", enHash = "be29e31b", vanilla = true },
    },
    [5545] = {
        title = { it = "Un fascio di guai", enHash = "50ca810d" },
        text = { it = "Ho un bel problema tra le mani. Ho una scadenza che incombe per un ordine di legname, e il tempo sta finendo. I lupi e gli orsi a nord di qui hanno cacciato via i miei operai dai Bundle of Wood che avevano già tagliato.\n\nHo già parlato con Deputy Rainer perché elimini gli animali, ma mi serve qualcuno che vada a raccogliere la legna per me. Se riuscissi a raccogliermi otto Bundle of Wood, forse ce la farei a rispettare la scadenza.", enHash = "761ac3e9" },
        objectives = { it = "Porta 8 Bundle of Wood a Raelen, all'Eastvale Logging Camp.", enHash = "4f84ca1e" },
        progress = { it = "La scadenza non si allontana di certo, $C. Ti prego, sbrigati a raccogliere quei Bundle of Wood.", enHash = "09082566" },
        reward = { it = "Eccellente! Grazie a te dovrei riuscire a completare l'ordine in tempo. Per mostrarti la mia gratitudine, vorrei offrirti qualche moneta come compenso per il disturbo.\n\nGrazie e addio.", enHash = "4feb4046" },
    },
    [5561] = {
        title = { it = "Il raduno dei kodo", enHash = "cb802278", vanilla = true },
        text = { it = "Bibbly pensa di essere l'unico goblin di Desolace che sa fare soldi. Beh, l'unica carovana abbastanza coraggiosa da viaggiare da queste parti dipende da me. Da quando ho imparato a ringiovanire e a controllare i kodo vecchi e morenti con il mio Kodo Kombobulator, Cork, il proprietario della carovana, Rigger e io siamo entrati in società.\n\nPrendi il kombobulator e usalo su qualunque kodo antico, vecchio o morente: con una scossa trasformerà la bestia in un kodo addomesticato e la costringerà a seguirti. Quando avrai addomesticato un kodo, riportamelo.", enHash = "fe276368", vanilla = true },
        objectives = { it = "Riporta cinque Tamed Kodo e il Kodo Kombobulator a Smeed Scrabblescrew, allo Scrabblescrew's Camp.", enHash = "7872b4b9", vanilla = true },
        progress = { it = "La carovana arriverà a breve: hai i cinque nuovi kodo addomesticati che ti avevo chiesto?", enHash = "f9f1d14b", vanilla = true },
        reward = { it = "<Smeed Scrabblescrew comincia a contare.>\n\nTre, quattro e cinque... eccellente, chiedo cinque kodo addomesticati e ottengo cinque kodo addomesticati... diventerò ricco... sì, ricchissimo! Spero di vedere la faccia verde di Bibbly quando saprà del mio successo!", enHash = "6352c7ed", vanilla = true },
    },
    [5581] = {
        title = { it = "I portali della Legione", enHash = "492d98d9", vanilla = true },
        text = { it = "Guarda — la Hand of Iruxos. Uno spettacolo davvero raccapricciante.\n\nDevi possederla, se si vogliono chiudere i portali demoniaci della Mannoroc Coven... ed è ciò che ora ti chiedo di fare. La minaccia dei demoni sta crescendo e dobbiamo chiudere questi portali per arginare l'ondata di demoni diretta verso questo mondo. Buona fortuna, $N... e fa' attenzione ai guardiani dei portali.", enHash = "eda08dc9", vanilla = true },
        objectives = { it = "Chiudi 6 portali alla Mannoroc Coven e torna da Taiga Wisemane, a Shadowprey Village.", enHash = "045955bf", vanilla = true },
        progress = { it = "Hai chiuso i portali demoniaci della Mannoroc Coven?", enHash = "511e55ca", vanilla = true },
        reward = { it = "Meriti un encomio, $N. Il tuo impegno ha aiutato molto nella lotta contro la minaccia dei demoni, e per questo tutta Azeroth è più sicura.", enHash = "e88641f8", vanilla = true },
    },
    [5621] = {
        title = { it = "Le vesti della Luna", enHash = "ba3524d6", vanilla = true },
        text = { it = "Ho bisogno del tuo aiuto, $N. Devo restare qui ad addestrare gli altri allievi, ma tu, tu puoi aiutare una delle nostre Sentinelle ferite, poco a sud di Dolanaar. È stata ferita mentre pattugliava il villaggio e le farebbe comodo il nostro aiuto. Si chiama Shaya.\n\nQuando la trovi, cura le sue ferite e poi rafforza il suo corpo con i tuoi incantesimi. Così almeno sarà protetta più a lungo, se dovesse finire nei guai. Torna qui da me dopo aver compiuto il tuo dovere verso Elune.", enHash = "d21da702", vanilla = true },
        objectives = { it = "Trova Sentinel Shaya e cura le sue ferite con Lesser Heal (Rank 2). Poi concedile Power Word: Fortitude e torna da Laurna Morninglight, a Dolanaar.", enHash = "4883fb12", vanilla = true },
        progress = { it = "I nostri incantesimi di Fortify sono molto potenti, Delor. Permettono ai nostri compagni di sopportare più ferite da ogni tipo di attacco e di sopravvivere in situazioni in cui di solito cadrebbero. Ma non è niente in confronto alla nostra capacità di guarire. Non ci sono guaritori più grandi di un sacerdote — ricordalo bene. Il tuo potere da solo può facilmente cambiare le sorti di una battaglia.", enHash = "66a67dd9", vanilla = true },
        reward = { it = "Hai fatto bene e hai servito Elune. Per questo ti ringrazio.\n\nTi prego, prendi questa veste come segno della mia gratitudine. Significa che hai conquistato il tuo posto nel nostro ordine. Se vuoi, indossala con orgoglio, ma in ogni caso ti riconosceremo sempre come $Guno:una; dei nostri.\n\nVa' con Elune, $N, e grazie.", enHash = "0efc270c", vanilla = true },
    },
    [5622] = {
        title = { it = "Nelle grazie di Elune", enHash = "62d3bb59", vanilla = true },
        text = { it = "$N, devi andare a Dolanaar quando avrai finito i tuoi affari qui a Shadowglen. Là troverai Laurna Morninglight. Ti istruirà ancora nelle vie di Elune, ed è con lei che ti guadagnerai le tue prime vesti, segno del tuo rango di $Gsacerdote:sacerdotessa; di Elune.\n\nAbbi cura di te, e che tu sia $Gprotetto:protetta; nei tuoi viaggi.", enHash = { "877fc712", "9a8ecebf" }, vanilla = true },
        objectives = { it = "Parla con Laurna Morninglight, a Teldrassil.", enHash = "73183862", vanilla = true },
        reward = { it = "Sono felice di vedere che Shanda ti ha mandato da me, $N. Insegnare le vie di Elune ai giovani sacerdoti mi dà una grande soddisfazione.", enHash = "6b0f0b56", vanilla = true },
    },
    [5623] = {
        title = { it = "Nelle grazie della Luce", enHash = "4ef86f1b", vanilla = true },
        text = { it = "Salve di nuovo, $Ggiovane sacerdote:giovane sacerdotessa;. È giunto il momento che tu impari di più sulla nostra religione. Dopo aver completato i compiti che hai qui a Northshire, cerca Priestess Josetta a Goldshire. Ha altro da insegnarti e ha sentito dire che stai diventando forte nelle vie della Luce. Non vede l'ora di continuare a istruirti.", enHash = { "0448d992", "2658955d" }, vanilla = true },
        objectives = { it = "Parla con Priestess Josetta, nell'Elwynn Forest.", enHash = "7896deae", vanilla = true },
        reward = { it = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Abbiamo molto di cui parlare riguardo al tuo futuro e al tuo cammino nella Luce.", enHash = "13c55c8f", vanilla = true },
    },
    [5624] = {
        title = { it = "Le vesti della Luce", enHash = "8c5e85e1", vanilla = true },
        text = { it = "Di solito propongo una piccola sfida ai seguaci della Luce per mettere alla prova la loro abilità. Voglio vedere se sono degni di indossare le loro prime vesti — segno che la chiesa approva apertamente $Gil sacerdote:la sacerdotessa; e $Glo:la; sostiene.\n\nMa questa situazione è un po' diversa. Uno dei cittadini di Goldshire ha visto una guardia ferita vicino al lago, a est di qui. Si chiama Roberts. Trovalo, curalo, rafforza il suo corpo e torna qui. Se riesci a farlo per me, considererò la tua prova superata.", enHash = { "86ce1f88", "d37a34ca" }, vanilla = true },
        objectives = { it = "Trova Guard Roberts e cura le sue ferite con Lesser Heal (Rank 2). Poi concedigli Power Word: Fortitude e torna da Priestess Josetta, a Goldshire.", enHash = "70d4cf38", vanilla = true },
        progress = { it = "Come forse avrai già imparato, le nostre magie di guarigione sono vitali per la sopravvivenza della nostra gente in questi tempi duri — soprattutto per gli avventurieri e gli eroi che impugnano armi e magia per respingere tante minacce diverse.\n\nFaresti bene a ricordare sempre quanto sia importante questa abilità. Questa, unita a Fortitude, rende i tuoi compagni molto più capaci in battaglia, perché potranno reggere un numero maggiore di colpi.\n\nNon lasciare che nessuno sminuisca quanto sono potenti le tue magie.", enHash = "7345e6a1", vanilla = true },
        reward = { it = "Eccellente, $N. Con una guardia in salute in più là fuori ad aiutare il villaggio, saremo molto più al sicuro. Mi fa piacere vedere che stai già imparando a usare le tue abilità con saggezza. Se in qualsiasi momento ti senti $Gpronto:pronta; per altro addestramento, torna pure da me. Ma per ora prendi questa veste. Farà sapere agli altri che fai parte del nostro ordine. Se non vuoi indossarla, va bene lo stesso. Più avanti ci saranno altre prove, e per quelle questa veste non serve.", enHash = "aaf97d03", vanilla = true },
    },
    [5625] = {
        title = { it = "Le vesti della Luce", enHash = "8c5e85e1", vanilla = true },
        text = { it = "Di solito è più o meno a questo punto che chi ha il tuo potere viene messo alla prova per vedere se è degno di indossare le vesti che indicano il suo posto nella chiesa. Ma, a dire il vero, ho questioni più urgenti di cui occuparmi. Un cittadino di Kharanos è appena venuto qui a dirmi di un montanaro ferito appena fuori dal villaggio, a sud — si chiama Dolf.\n\nTu cura Dolf e dagli Fortitude, e io considererò conclusa la tua prova. Che ne dici?", enHash = "0939799f", vanilla = true },
        objectives = { it = "Trova Mountaineer Dolf e cura le sue ferite con Lesser Heal (Rank 2). Poi concedigli Power Word: Fortitude e torna da Maxan Anvol, a Kharanos.", enHash = "2c42b0cf", vanilla = true },
        progress = { it = "Hai già trovato Dolf, $N?\n\nProbabilmente l'avrai già imparato, ma la nostra capacità di guarire è molto utile. Non solo possiamo prenderci cura dei feriti, ma siamo indispensabili per la sopravvivenza di tutti quegli aspiranti eroi là fuori che cercano di farsi un nome. Con Fortitude ad aumentare i colpi che possiamo reggere, e la nostra magia di guarigione a tenerli in vita, non c'è niente che non possiamo superare!", enHash = "432263df", vanilla = true },
        reward = { it = "Eccellente, $N. Con una guardia in salute in più là fuori ad aiutare il villaggio, saremo molto più al sicuro. Mi fa piacere vedere che stai già imparando a usare le tue abilità con saggezza. Se in qualsiasi momento ti senti $Gpronto:pronta; per altro addestramento, torna pure da me. Ma per ora prendi questa veste. Farà sapere agli altri che fai parte del nostro ordine. Se non vuoi indossarla, va bene lo stesso. Più avanti ci saranno altre prove, e per quelle questa veste non serve.", enHash = "aaf97d03", vanilla = true },
    },
    [5626] = {
        title = { it = "Nelle grazie della Luce", enHash = "4ef86f1b", vanilla = true },
        text = { it = "Ehi! $N! Hai un minuto?!\n\nSegui la Luce da abbastanza tempo ormai: è ora che tu vada da Maxan Anvol, a Kharanos. Ti insegnerà di più sul cammino che stai seguendo e, se ti dimostrerai $Gdegno:degna;, ti darà le tue prime vesti, segno del tuo rango di $Gsacerdote:sacerdotessa;.\n\nOra muoviti! Appena hai finito qui, attraversa il tunnel — ti starà aspettando.", enHash = { "d0c73f06", "c5ed44f3" }, vanilla = true },
        objectives = { it = "Parla con Maxan Anvol, nel Dun Morogh.", enHash = "cdb00510", vanilla = true },
        reward = { it = "Oh, quindi ti ha mandato Branstock, eh? Bene, bene! Ha ragione, è ora che tu faccia un passo molto più grande verso la Luce. Ti formerà il carattere e ti renderà più forte... ed è quello che ti servirà più di ogni altra cosa: forza del corpo... forza della volontà.", enHash = "19b45869", vanilla = true },
    },
    [5627] = {
        title = { it = "Le stelle di Elune", enHash = "626ec03b", vanilla = true },
        reward = { it = "Ti sei $Gdimostrato:dimostrata; $Gdegno:degna; dell'attenzione di Elune, $N. Se ti senti $Gpronto:pronta;, mi piacerebbe molto insegnarti uno dei suoi incantesimi riservati al nostro popolo.", enHash = "e5d7a990", vanilla = true },
    },
    [5628] = {
        title = { it = "Il ritorno a casa", enHash = "bd95f78d", vanilla = true },
        text = { it = "Ah, sì, salve, $N? Mi fa piacere che ti sia $Gfermato:fermata; a parlare un momento. Sei $Glontano:lontana; da casa, così giovane — ammiro questa ambizione. Vorrei aver trovato, da giovane, il coraggio di girare il mondo.\n\nNon molto tempo fa è passata di qui una sacerdotessa del tuo ordine a cercarti. Ha detto che era molto urgente che tu tornassi al Temple of the Moon di Darnassus e parlassi con Priestess Alathea — aveva a che fare con il tuo addestramento. Se puoi, non indugerei troppo.", enHash = "cf4478e2", vanilla = true },
        objectives = { it = "Parla con Priestess Alathea, a Darnassus.", enHash = "af036438", vanilla = true },
        reward = { it = "Magnifico, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della faccenda in questione, potrai raccontarmi di più dei tuoi viaggi.", enHash = "c9befd51", vanilla = true },
    },
    [5629] = {
        title = { it = "Il ritorno a casa", enHash = "bd95f78d", vanilla = true },
        text = { it = "Salve di nuovo, $N. So che hai avuto da fare ad aiutare la nostra gente, ma devi prenderti un po' di tempo anche per te. Priestess Alathea ha mandato qualcuno qui a cercarti. Sembra che tu abbia attirato l'attenzione dei nostri anziani, e ritengono che tu sia $Gpronto:pronta; per cose più grandi. Va' al Temple of the Moon di Darnassus e cerca Alathea. Ti starà aspettando. Buona fortuna, e che Elune sia con te.", enHash = "37dfcdc5", vanilla = true },
        objectives = { it = "Parla con Priestess Alathea, a Darnassus.", enHash = "af036438", vanilla = true },
        reward = { it = "Magnifico, sei $Gtornato:tornata;, $N. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della faccenda in questione, potrai raccontarmi di più dei tuoi viaggi.", enHash = "15166096", vanilla = true },
    },
    [5630] = {
        title = { it = "Il ritorno a casa", enHash = "bd95f78d", vanilla = true },
        text = { it = "Salve, $Gragazzo:ragazza;. Che bello vederti viaggiare in lungo e in largo verso terre lontane. Senza offesa, ma molti della tua gente di solito non sopportano bene questi climi freddi. Mi fa piacere vedere che sei $Gfatto:fatta; di una pasta più dura.\n\nNon molto tempo fa è passata di qui una delle vostre sacerdotesse a cercarti — ha detto qualcosa sul fatto che dovevi trovare una certa Priestess Alathea nel Temple of the Moon, giù a Darnassus. Ha detto che era importante e che dovresti tornarci presto.", enHash = { "40791046", "c7669a26" }, vanilla = true },
        objectives = { it = "Parla con Priestess Alathea, a Darnassus.", enHash = "af036438", vanilla = true },
        reward = { it = "Magnifico, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della faccenda in questione, potrai raccontarmi di più dei tuoi viaggi.", enHash = "c9befd51", vanilla = true },
    },
    [5631] = {
        title = { it = "Il ritorno a casa", enHash = "bd95f78d", vanilla = true },
        text = { it = "Da poco una sacerdotessa è venuta nelle nostre sale a cercarti, giovane $R. Ha detto che aveva il compito di trovarti e che dovresti tornare al Temple of the Moon di Darnassus il prima possibile. Quando arrivi, cerca una certa Priestess Alathea — ti dirà di più.\n\nChe la Luce sia con te, $N.", enHash = "d3bb0f8e", vanilla = true },
        objectives = { it = "Parla con Priestess Alathea, a Darnassus.", enHash = "af036438", vanilla = true },
        reward = { it = "Magnifico, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della faccenda in questione, potrai raccontarmi di più dei tuoi viaggi.", enHash = "c9befd51", vanilla = true },
    },
    [5632] = {
        title = { it = "Il ritorno a casa", enHash = "bd95f78d", vanilla = true },
        text = { it = "Oh, sì, certo. Salve, $N. Non molto tempo fa è passata di qui una messaggera del nostro ordine a cercarti. Ha parlato di qualcosa di importante che sta succedendo a Darnassus, e ha detto che dovresti tornare al Temple of the Moon appena puoi. Quando arrivi, parla con Priestess Alathea. Credo che abbia a che fare con i tuoi ottimi progressi nelle nostre vie.\n\nTe lo ripeto: torna a Darnassus quando puoi.", enHash = "a4e1499d", vanilla = true },
        objectives = { it = "Parla con Priestess Alathea, a Darnassus.", enHash = "af036438", vanilla = true },
        reward = { it = "Magnifico, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della faccenda in questione, potrai raccontarmi di più dei tuoi viaggi.", enHash = "c9befd51", vanilla = true },
    },
    [5633] = {
        title = { it = "Il ritorno a casa", enHash = "bd95f78d", vanilla = true },
        text = { it = "Salute, $Gragazzo:ragazza;. Che bello vederti qui nelle nostre grandi sale. Che una benedizione sia su di te e sulla tua gente.\n\nMentre viaggiavi per le nostre terre, una sacerdotessa del tuo tempio è venuta qui a cercarti. Ha detto che dovevi tornare al Temple of the Moon il prima possibile. Mi dispiace non poterti dire di più, ma sembrava importante. Quando arrivi al tempio, parla con una certa Priestess Alathea.", enHash = { "6849e952", "a04495df" }, vanilla = true },
        objectives = { it = "Parla con Priestess Alathea, a Darnassus.", enHash = "af036438", vanilla = true },
        reward = { it = "Magnifico, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della faccenda in questione, potrai raccontarmi di più dei tuoi viaggi.", enHash = "c9befd51", vanilla = true },
    },
    [5634] = {
        title = { it = "Desperate Prayer", enHash = "d4754740", vanilla = true },
        reward = { it = "Hai reso un grande servizio alla Luce diventando un esempio luminoso per chi viaggia in queste terre pericolose e oltre. Ti prego, accetta questa lezione come ringraziamento per tutto ciò che hai fatto.", enHash = "bd62089c", vanilla = true },
    },
    [5635] = {
        title = { it = "Desperate Prayer", enHash = "d4754740", vanilla = true },
        text = { it = "Hai attirato l'attenzione dei nostri superiori, $N. Ti hanno chiesto di recarti alla Cathedral of Light di Stormwind il prima possibile. A quanto pare ritengono che tu abbia già dato prova di te e che sia $Gpronto:pronta; a proseguire il tuo addestramento. Quando arrivi, cerca High Priestess Laurena. Potrà guidarti oltre. Buona fortuna, e che la Luce sia con te.", enHash = "e9ad0185", vanilla = true },
        objectives = { it = "Parla con High Priestess Laurena, a Stormwind.", enHash = "b1314e9d", vanilla = true },
        reward = { it = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominceremo subito a parlarne.", enHash = "af22f634", vanilla = true },
    },
    [5636] = {
        title = { it = "Desperate Prayer", enHash = "d4754740", vanilla = true },
        text = { it = "Elune ti benedica, $Gbuon:buona; $R. Spero che la tua Luce ti trovi e ti protegga bene oggi.\n\nNon molto tempo fa è passato di qui uno dei vostri sacerdoti a cercarti. Ha detto che dovresti tornare alla Cathedral of Light il prima possibile per parlare con High Priestess Laurena. Sembra che tu abbia fatto bene, per attirare tanta attenzione. Non passerei troppo tempo qui — la tua gente ha bisogno di te.", enHash = "53323e7b", vanilla = true },
        objectives = { it = "Parla con High Priestess Laurena, a Stormwind.", enHash = "b1314e9d", vanilla = true },
        reward = { it = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominceremo subito a parlarne.", enHash = "af22f634", vanilla = true },
    },
    [5637] = {
        title = { it = "Desperate Prayer", enHash = "d4754740", vanilla = true },
        text = { it = "È arrivato il momento che tu vada a Stormwind, $N. High Priestess Laurena, nella Cathedral of Light, vuole parlarti. Dev'essere qualcosa di molto buono o di molto brutto se la somma sacerdotessa ti vuole là di persona, ma scommetto che hai solo fatto bene, ed è una buona cosa che voglia parlarti.\n\nMa non perdere troppo tempo da queste parti. Io ci andrei appena possibile.", enHash = "f0c240e7", vanilla = true },
        objectives = { it = "Parla con High Priestess Laurena, a Stormwind.", enHash = "b1314e9d", vanilla = true },
        reward = { it = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominceremo subito a parlarne.", enHash = "af22f634", vanilla = true },
    },
    [5638] = {
        title = { it = "Desperate Prayer", enHash = "d4754740", vanilla = true },
        text = { it = "Poco tempo fa è passato di qui uno dei vostri sacerdoti a cercarti, $R. Ha detto che, se ti avessi visto, avrei dovuto indirizzarti verso la Cathedral of Light. Ha detto che era molto importante, ma al tuo posto non mi preoccuperei troppo. Sembrava di buon umore... come se si trattasse di una bella notizia. Al tuo posto non ci metterei troppo ad andarci.\n\nElune sia con te, $Gbuon:buona; $R.", enHash = "4e3f271a", vanilla = true },
        objectives = { it = "Parla con High Priestess Laurena, a Stormwind.", enHash = "b1314e9d", vanilla = true },
        reward = { it = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominceremo subito a parlarne.", enHash = "af22f634", vanilla = true },
    },
    [5639] = {
        title = { it = "Desperate Prayer", enHash = "d4754740", vanilla = true },
        text = { it = "C'è bisogno di te a Stormwind, $N. La somma sacerdotessa di laggiù, Laurena, dice che è ora che tu dimostri di essere $Gdegno:degna; del livello successivo del tuo addestramento. Non perdere troppo tempo per arrivarci. La trovi nella Cathedral of Light, al centro della città. Portale i miei saluti, e dimostra quanto sei $Gdegno:degna; di una simile chiamata. Che la Luce sia con te, $N.", enHash = "75b77529", vanilla = true },
        objectives = { it = "Parla con High Priestess Laurena, a Stormwind.", enHash = "b1314e9d", vanilla = true },
        reward = { it = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominceremo subito a parlarne.", enHash = "af22f634", vanilla = true },
    },
    [5640] = {
        title = { it = "Desperate Prayer", enHash = "d4754740", vanilla = true },
        text = { it = "Sia lodata Elune, e la tua Luce, $N.\n\nPiù o meno a questo punto, molti del nostro ordine imparano abilità che riflettono la loro fede in Elune. Se non ricordo male, credo che valga lo stesso anche per il tuo ordine.\n\nQuando avrai finito i tuoi affari a Darnassus, io cercherei una delle vostre somme sacerdotesse per proseguire l'addestramento.", enHash = "27aba8a7", vanilla = true },
        objectives = { it = "Parla con High Priestess Laurena, a Stormwind.", enHash = "b1314e9d", vanilla = true },
        reward = { it = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominceremo subito a parlarne.", enHash = "af22f634", vanilla = true },
    },
    [5641] = {
        title = { it = "Una mancanza di paura", enHash = "1bff4ab5", vanilla = true },
        reward = { it = "Hai la stoffa per diventare $Gun grande:una grande; $C, $N. Continua così!\n\nHai già dimostrato di essere $Gpronto:pronta; per la battaglia. Forse è ora di insegnarti qualcosina in più.", enHash = "8773f67d", vanilla = true },
    },
    [5642] = {
        title = { it = "Shadowguard", enHash = "a33c5985", vanilla = true },
        text = { it = "Sta succedendo qualcosa di importante a Orgrimmar, $N.\n\nI soliti messaggeri che passano di qui in cerca di sacerdoti troll di solito sono molto tranquilli. Questa volta sembravano avere molta più fretta. Non indugiare troppo a Thunder Bluff. Io tornerei alla Valley of Spirits il prima possibile.", enHash = "17bfbfce", vanilla = true },
        objectives = { it = "Parla con Ur'kyo, a Orgrimmar.", enHash = "30f8d44b", vanilla = true },
        reward = { it = "I tuoi riti arriveranno presto. Per ora ti insegno un incantesimo che ti sarà molto utile quando combatterai contro i tuoi nemici.", enHash = "d64ff152", vanilla = true },
    },
    [5643] = {
        title = { it = "Shadowguard", enHash = "a33c5985", vanilla = true },
        text = { it = "Come per molti dei nostri sacerdoti, anche la tua tribù ti sottopone a riti di passaggio. Questi riti spesso insegnano ai sacerdoti abilità speciali, vitali per la loro sopravvivenza. Sento che per te quel momento è arrivato, proprio mentre parliamo. Devi tornare alla Valley of Spirits di Orgrimmar e parlare con Ur'kyo. Ciò che ti insegnerà potrebbe essere molto importante per il futuro.", enHash = "3e38404a", vanilla = true },
        objectives = { it = "Parla con Ur'kyo, a Orgrimmar.", enHash = "30f8d44b", vanilla = true },
        reward = { it = "I tuoi riti arriveranno presto. Per ora ti insegno un incantesimo che ti sarà molto utile quando combatterai contro i tuoi nemici.", enHash = "d64ff152", vanilla = true },
    },
    [5644] = {
        title = { it = "Devouring Plague", enHash = "fec46d87", vanilla = true },
        text = { it = "Ah, un giorno meraviglioso per te, $N. Dalle lezioni che hai imparato vedo che è giunto il momento di rimandarti da Aelthalyste. Ci sono cose che solo lei può insegnarti, e anche allora solo se ti dimostrerai $Gdegno:degna;.\n\nNon ti rovinerò la sorpresa, ma ricordo quando, da giovane, imparavo cos'è il vero potere... il potere divino. Sì, quelli sì che erano bei tempi.\n\nTorna da Aelthalyste nell'Undercity, $N. Ti aspetterà nel War Quarter.", enHash = "3456d51c", vanilla = true },
        objectives = { it = "Parla con Aelthalyste, nell'Undercity.", enHash = "169ad8b0", vanilla = true },
        reward = { it = "Ti insegnerei Devouring Plague, se ti senti $Gpronto:pronta;, $N. È un incantesimo di non poca potenza, e ti aiuterà nelle battaglie che verranno. Esercitati — più avanti ci saranno delle prove.", enHash = "c52fdae2", vanilla = true },
    },
    [5645] = {
        title = { it = "Una mancanza di paura", enHash = "1bff4ab5", vanilla = true },
        text = { it = "$N, il tuo sommo sacerdote, Rohan, vorrebbe riceverti a Ironforge. Affrettati, $Gmio forte amico:mia forte amica;, la tua prossima prova si avvicina in fretta. Anche se vorrei poter assistere ai riti speciali della tua razza, il mio posto è qui. Ma che la Luce ti accompagni nei tuoi viaggi. Quando arriverai in città, Rohan dovrebbe essere ancora nel Mystic Ward. Ti starà aspettando.", enHash = "7fce641c", vanilla = true },
        objectives = { it = "Parla con High Priest Rohan, a Ironforge.", enHash = "d5e7c4a8", vanilla = true },
        reward = { it = "È un bene che tu sia $Gvenuto:venuta;, $N. La nostra razza è fiera e forte, ed è ora che tu impari non solo a esserlo $Gtu stesso:tu stessa;, ma anche a suscitare questi sentimenti e questa fiducia negli altri. Sei $Gpronto:pronta;, $Gragazzo:ragazza;?", enHash = "0357f22d", vanilla = true },
    },
    [5646] = {
        title = { it = "Devouring Plague", enHash = "fec46d87", vanilla = true },
        text = { it = "Aelthalyste mostra grande rispetto per la nostra gente rimandandola da me per altro addestramento, e ora io faccio lo stesso per la sua tribù.\n\nTorna all'Undercity, $N. Là, nel War Quarter, sarà pronta a insegnarti di più sulla tua gente e sulle sue usanze. Va' là, e non aspettare troppo.", enHash = "6d539780", vanilla = true },
        objectives = { it = "Parla con Aelthalyste, nell'Undercity.", enHash = "169ad8b0", vanilla = true },
        reward = { it = "Bene, sei $Gtornato:tornata;, e non un momento troppo tardi. Abbiamo grandi cose di cui parlare, $N. Le tue abilità si stanno rafforzando, e dobbiamo assicurarci che tu sia $Gpronto:pronta;.", enHash = "75d8dbc0", vanilla = true },
    },
    [5647] = {
        title = { it = "Una mancanza di paura", enHash = "1bff4ab5", vanilla = true },
        text = { it = "La tua razza è davvero forte, $N. Siamo orgogliosi di chiamarvi alleati. E a ogni tramonto tu e la tua gente vi avvicinate non solo a scoprire le vostre vere origini, ma anche a trovare una grande sicurezza di essere sulla strada giusta in tante cose. Quella sensazione deve farti sentire così trionfante.\n\nDa poco è arrivato un messaggio da Ironforge. Chiede che tu torni là e parli con High Priest Rohan, nel Mystic Ward. Io non lo farei aspettare. Che Elune guidi i tuoi viaggi.", enHash = "3b906592", vanilla = true },
        objectives = { it = "Parla con High Priest Rohan, a Ironforge.", enHash = "d5e7c4a8", vanilla = true },
        reward = { it = "Hai la stoffa per diventare $Gun grande:una grande; $C, $N. Continua così!\n$N, hai già dimostrato di essere $Gpronto:pronta; per la battaglia. Forse è ora di insegnarti qualcosina in più.", enHash = "eadc4a81", vanilla = true },
    },
    [5648] = {
        title = { it = "Le vesti della spiritualità", enHash = "00031505", vanilla = true },
        text = { it = "Sei $Gpronto:pronta; per la tua prima prova, $N. A sud di Razor Hill, appena fuori dal villaggio, una delle nostre grunt è ferita dopo aver respinto alcune delle vecchie truppe di Proudmoore. Non sta molto bene, e le farebbe un gran bene se qualcuno come noi potesse aiutarla. Trovala — si chiama Kor'ja — cura le sue ferite e dalle la benedizione dei nostri antenati.\n\nSe lo fai, credo che sarà una prova sufficiente che sei $Gpronto:pronta; ad andare avanti nelle nostre vie.", enHash = "d9b0f374", vanilla = true },
        objectives = { it = "Trova Grunt Kor'ja e cura le sue ferite con Lesser Heal (Rank 2). Poi concedile Power Word: Fortitude e torna da Tai'jin, a Razor Hill.", enHash = "60f32ae2", vanilla = true },
        progress = { it = "Quasi tutti pensano che sia logico che le magie di guarigione siano potenti, ma pochi capiscono quanto. Puoi tenere in vita molti che invece dovrebbero andare a incontrare i loro antenati. Questa magia di guarigione unita all'abilità Fortitude è una combinazione di incantesimi molto potente. Ricordatelo. È utile a ogni genere di persone: guerrieri, maghi e tutto quello che c'è in mezzo.", enHash = "9e0c8d60", vanilla = true },
        reward = { it = "Bene, allora Kor'ja vive e torna a difendere il nostro villaggio da quei malvagi umani. Spesso vorrei ricordare i giorni di battaglia, quando la potenza si mostrava in combattimento ed erano spesso i saggi a distruggere chi contava solo sulla propria forza.\n\nHai fatto un buon lavoro per me, $N. Ora prendi questa veste. Forse ti aiuterà, forse non ti importa, ma l'hai meritata e sono fiera di chiamarti $Gfratello:sorella;.", enHash = { "ddf7ede8", "30fd18d0" }, vanilla = true },
    },
    [5649] = {
        title = { it = "Nelle grazie della spiritualità", enHash = "f4cee98b", vanilla = true },
        text = { it = "Sì, $Gamico:amica;. La nostra gente si è unita all'Orda perché è un bene per noi. Sono leali, e ci insegnano molto su cose come l'onore. Ma le vecchie usanze sono dure a morire. Gli orchi forse non approvano tutte le nostre tradizioni, ma questo non vuol dire che non possiamo continuare a praticarne alcune in segreto.\n\nTu lo sai, ed è per questo che ti mando da Tai'jin, a Razor Hill. Ti insegnerà di più sulla nostra storia. Ti insegnerà le vie della nostra tribù. Va' da lei quando sei $Gpronto:pronta;.", enHash = "497a6ea2", vanilla = true },
        objectives = { it = "Parla con Tai'jin, a Durotar.", enHash = "930e8d3f", vanilla = true },
        reward = { it = "Ahh... allora finalmente sei $Gvenuto:venuta; da Tai'jin. Questo è un bene.\n\nSai già che non siamo la stessa tribù che un tempo si unì all'Orda. Adesso siamo molto più forti. Siamo più forti perché ci adattiamo — questo l'Orda ce l'ha insegnato. Non sconfiggiamo più i nemici per trarne forza; ora prima acquistiamo forza, e poi sconfiggiamo i nemici.\n\nLa differenza è sottile, ma imparerai. Vedrai. La tribù conta su di te perché tu impari queste cose.", enHash = "5e86b77c", vanilla = true },
    },
    [5650] = {
        title = { it = "Le vesti dell'oscurità", enHash = "e426ea53", vanilla = true },
        text = { it = "Il nostro potere viene dall'oscurità e dall'ombra, $N, ma questo non è il tuo unico ruolo. Hai riconosciuto che conoscere le arti della guarigione ha il suo valore. È una scelta saggia. Ma prima di poter conoscere il buio, devi conoscere anche la luce. E per questo ho una prova per te.\n\nA nord del cimitero c'è un Guardiamorte ferito: Deathguard Kel. Ci protegge dagli gnoll da tempo, e ha bisogno di cure. Ma devi anche rafforzare il suo corpo prima che possa tornare in servizio. Fai entrambe le cose con i tuoi incantesimi, e poi torna da me.", enHash = "7ee23c63", vanilla = true },
        objectives = { it = "Trova Deathguard Kel e cura le sue ferite con Lesser Heal (Rank 2). Poi concedigli Power Word: Fortitude e torna da Dark Cleric Beryl, a Brill.", enHash = "01bc1417", vanilla = true },
        progress = { it = "I nostri poteri ci rendono adatti a tantissime situazioni, $N. Scoprirai però che, in ogni caso, la nostra capacità di curare le ferite e di aumentare i danni che i nostri compagni possono sopportare sarà sempre il talento più richiesto tra quelli a nostra disposizione. Non lasciare che questo ti distolga dal seguire altre strade come $C — puoi essere efficace in molti modi. Ma... se desideri davvero distruggere i nemici con l'energia magica, forse l'arcano fa più per te.", enHash = "889e8e30", vanilla = true },
        reward = { it = "Hai superato la mia prova con facilità. Bene.\n\nPresto sarai $Gpronto:pronta; ad assumerti più responsabilità, e quella strada ti porterà a poteri più oscuri — poteri che $Gnessun altro:nessun'altra; $C di un'altra razza possiede.\n\nPrendi questa veste come simbolo del tuo rango. L'hai meritata. Se non vuoi indossarla, così sia: puoi farne ciò che vuoi. Io e gli altri come noi riconosceremo sempre ciò che hai ottenuto nei nostri ranghi.", enHash = "b06e8ba8", vanilla = true },
    },
    [5651] = {
        title = { it = "Nelle grazie dell'oscurità", enHash = "ea6df1d9", vanilla = true },
        text = { it = "Ci sono molte lezioni che i Reietti hanno imparato con l'esperienza: cose che alcune razze possono solo cominciare a comprendere. E anche se il nostro cammino è nell'oscurità, scoprirai che moltissime cose dipendono sia dalla luce sia dal buio. Le tue lezioni ti insegneranno a usarli entrambi... e con discrezione. Ma ascolta le mie parole: non dimenticare mai che siamo stati forgiati nella corruzione e lasciati a marcire come tante carogne. L'Oscurità è la nostra casa.\n\nCerca Dark Cleric Beryl a Brill quando sarai $Gpronto:pronta; a imparare di più.", enHash = "9ca00ba1", vanilla = true },
        objectives = { it = "Parla con Dark Cleric Beryl, nelle Tirisfal Glades.", enHash = "849a5242", vanilla = true },
        reward = { it = "Finalmente sei $Garrivato:arrivata;. La tua fede da sola non ti permetterà di superare le prove che ti attendono, giovane. Anche un senso di urgenza e un po' di ambizione ti saranno d'aiuto.", enHash = "c811fcec", vanilla = true },
    },
    [5652] = {
        title = { it = "Hex of Weakness", enHash = "a25c9073", vanilla = true },
        reward = { it = "Faresti bene a prestare attenzione a questa lezione, giovane. L'Hex of Weakness ti sarà di grande aiuto in battaglia. Più avanti avrò delle prove per te, per farti progredire e dimostrare il tuo valore alla tribù.", enHash = "c153776d", vanilla = true },
    },
    [5654] = {
        title = { it = "Hex of Weakness", enHash = "a25c9073", vanilla = true },
        text = { it = "È ora che tu incontri Ur'kyo, $N. Si trova nella Valley of Spirits, nella città degli orchi. Va' là e parlagli. È ora che tu impari di più sulle antiche vie della nostra gente. È ora che tu venga $Gaccolto:accolta; nel cerchio e che diventi $Gun vero sacerdote:una vera sacerdotessa; della nostra tribù.", enHash = "7dd0bce6", vanilla = true },
        objectives = { it = "Parla con Ur'kyo, a Orgrimmar.", enHash = "30f8d44b", vanilla = true },
        reward = { it = "Faresti bene a prestare attenzione a questa lezione, giovane. L'Hex of Weakness ti sarà di grande aiuto in battaglia. Più avanti avrò delle prove per te, per farti progredire e dimostrare il tuo valore alla tribù.", enHash = "c153776d", vanilla = true },
    },
    [5655] = {
        title = { it = "Hex of Weakness", enHash = "a25c9073", vanilla = true },
        text = { it = "Mi hanno mandato qui per assicurarmi che tu non ti allontani troppo da casa, $N. Mi mandano per assicurarmi che tu torni a casa, perché Ur'kyo, il più grande dei nostri sacerdoti, vuole parlarti. Tu vai là. Vai nella Valley of Spirits, nella città degli orchi, e parli con Ur'kyo. Ora ti sta aspettando.", enHash = "c89ef009", vanilla = true },
        objectives = { it = "Parla con Ur'kyo, a Orgrimmar.", enHash = "30f8d44b", vanilla = true },
        reward = { it = "Faresti bene a prestare attenzione a questa lezione, giovane. L'Hex of Weakness ti sarà di grande aiuto in battaglia. Più avanti avrò delle prove per te, per farti progredire e dimostrare il tuo valore alla tribù.", enHash = "c153776d", vanilla = true },
    },
    [5656] = {
        title = { it = "Hex of Weakness", enHash = "a25c9073", vanilla = true },
        text = { it = "Mi scalda sempre il cuore non morto vedere sacerdoti di tutte le culture girare il mondo. Sapere che esiste un potere che non è arcano e che è ben alla nostra portata. Ecco perché è un onore per me indirizzarti a casa, $N.\n\nUr'kyo, il tuo grande sacerdote a Orgrimmar, ha chiesto la tua presenza. Lo trovi nella Valley of Spirits.", enHash = "adb709ed", vanilla = true },
        objectives = { it = "Parla con Ur'kyo, a Orgrimmar.", enHash = "30f8d44b", vanilla = true },
        reward = { it = "Faresti bene a prestare attenzione a questa lezione, giovane. L'Hex of Weakness ti sarà di grande aiuto in battaglia. Più avanti avrò delle prove per te, per farti progredire e dimostrare il tuo valore alla tribù.", enHash = "c153776d", vanilla = true },
    },
    [5657] = {
        title = { it = "Hex of Weakness", enHash = "a25c9073", vanilla = true },
        text = { it = "Casa. Torna a casa, giovane $R.\n\nIl tuo capo spirituale Ur'kyo ti prega di tornare da lui e di parlare del cammino che percorri.\n\nVa' nella Valley of Spirits, nella grande città dell'Orda, Orgrimmar. Lo troverai là.", enHash = "ea598d6a", vanilla = true },
        objectives = { it = "Parla con Ur'kyo, a Orgrimmar.", enHash = "30f8d44b", vanilla = true },
        reward = { it = "Faresti bene a prestare attenzione a questa lezione, giovane. L'Hex of Weakness ti sarà di grande aiuto in battaglia. Più avanti avrò delle prove per te, per farti progredire e dimostrare il tuo valore alla tribù.", enHash = "c153776d", vanilla = true },
    },
    [5658] = {
        title = { it = "Touch of Weakness", enHash = "e1ccc697", vanilla = true },
        reward = { it = "Ah, giovane $C, mi fa piacere che tu sia $Gtornato:tornata; qui. Vorrei insegnarti una lezione che faresti bene a non dimenticare. Sei $Gpronto:pronta;?", enHash = "4280de7b", vanilla = true },
    },
    [5659] = {
        title = { it = "Touch of Weakness", enHash = "e1ccc697", vanilla = true },
        text = { it = "Questo non è il posto per te, $N. Dovresti andare nel War Quarter dell'Undercity il prima possibile. Aelthalyste ha convocato là tutti i suoi sacerdoti e le sue sacerdotesse, non appena saranno pronti. È ora che imparino di più sul loro potere e su come dominarlo.\n\nNon tollererà ritardi né scuse, quindi faresti meglio a metterti in cammino.", enHash = "4377f004", vanilla = true },
        objectives = { it = "Parla con Aelthalyste, nell'Undercity.", enHash = "169ad8b0", vanilla = true },
        reward = { it = "Ah, bene, ne è $Garrivato un altro:arrivata un'altra;. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai $Gricompensato:ricompensata; generosamente.", enHash = "cff6c490", vanilla = true },
    },
    [5660] = {
        title = { it = "Touch of Weakness", enHash = "e1ccc697", vanilla = true },
        text = { it = "Sei $Glontano:lontana; da casa, $C. C'è bisogno di te là, nella tua città sotto terra. La tua signora, quella che chiamate Aelthalyste, ha bisogno che tu torni là. Come per la mia tribù, ci sono cose che puoi imparare solo da lei. Non restare qui troppo a lungo. Dovresti andare al War Quarter alla velocità con cui può portarti uno zeppelin.", enHash = "0f0cb8f1", vanilla = true },
        objectives = { it = "Parla con Aelthalyste, nell'Undercity.", enHash = "169ad8b0", vanilla = true },
        reward = { it = "Ah, bene, ne è $Garrivato un altro:arrivata un'altra;. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai $Gricompensato:ricompensata; generosamente.", enHash = "cff6c490", vanilla = true },
    },
    [5661] = {
        title = { it = "Touch of Weakness", enHash = "e1ccc697", vanilla = true },
        text = { it = "Sei $Glontano:lontana; da casa, qui a Bloodhoof Village, $N. Mi hanno mandato qui a cercare sacerdoti della mia tribù da rimandare a parlare con i nostri capi, ma questo non vuol dire che non possa aiutare anche te.\n\nHo sentito dire che lo spirito della vostra sacerdotessa capo vuole che tutti i Reietti vadano da lei: ci sono cose che devi imparare.\n\nVa' a incontrare Aelthalyste nel War Quarter, in quella vostra città.", enHash = "9fa375dd", vanilla = true },
        objectives = { it = "Parla con Aelthalyste, nell'Undercity.", enHash = "169ad8b0", vanilla = true },
        reward = { it = "Ah, bene, ne è $Garrivato un altro:arrivata un'altra;. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai $Gricompensato:ricompensata; generosamente.", enHash = "cff6c490", vanilla = true },
    },
    [5662] = {
        title = { it = "Touch of Weakness", enHash = "e1ccc697", vanilla = true },
        text = { it = "Il mio rispetto a te e alla tua gente, $N. Di solito insegno solo a quelli della mia tribù. Le tue lezioni vengono da Aelthalyste, nella città un tempo chiamata Lordaeron.\n\nDovresti tornare da lei, se vuoi imparare le abilità che ti distinguono dalle altre fedi.\n\nVa' nel War Quarter dell'Undercity e là troverai la tua signora.", enHash = "b052ecee", vanilla = true },
        objectives = { it = "Parla con Aelthalyste, nell'Undercity.", enHash = "169ad8b0", vanilla = true },
        reward = { it = "Ah, bene, ne è $Garrivato un altro:arrivata un'altra;. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai $Gricompensato:ricompensata; generosamente.", enHash = "cff6c490", vanilla = true },
    },
    [5663] = {
        title = { it = "Touch of Weakness", enHash = "e1ccc697", vanilla = true },
        text = { it = "Aelthalyste ha mandato un messaggio a tutti i suoi sacerdoti. Dobbiamo indirizzare i più giovani del nostro ordine all'Undercity per altro addestramento. Se ti consideri davvero $Guno:una; dei nostri fedeli, allora dovresti tornarci anche tu.\n\nTrovi Aelthalyste nel War Quarter, nel profondo dell'Undercity.", enHash = "63afc777", vanilla = true },
        objectives = { it = "Parla con Aelthalyste, nell'Undercity.", enHash = "169ad8b0", vanilla = true },
        reward = { it = "Ah, bene, ne è $Garrivato un altro:arrivata un'altra;. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai $Gricompensato:ricompensata; generosamente.", enHash = "cff6c490", vanilla = true },
    },
    [5672] = {
        title = { it = "Elune's Grace", enHash = "aeedb5a9", vanilla = true },
        reward = { it = "Dedicandoti a Elune e al nostro popolo, hai raggiunto uno stato che non tutti noi possiamo raggiungere. È tradizione che, per la tua devozione, ti vengano insegnate abilità ancora più grandi. Accetti?", enHash = "a530f4ef", vanilla = true },
    },
    [5673] = {
        title = { it = "Elune's Grace", enHash = "aeedb5a9", vanilla = true },
        text = { it = "Sai che puoi rivolgerti a qualunque dei nostri istruttori in qualsiasi momento, $N, ma ci sono cose che non possiamo trasmetterti. Tra queste ci sono gli insegnamenti della tua dea, Elune. Concede abilità speciali ai suoi fedeli e, se non sbaglio, è ora che tu torni a casa, al tuo Temple of the Moon, per essere $Gmesso:messa; alla prova.\n\nTorna là quando puoi e parla con Priestess Alathea.", enHash = "2975ea6b", vanilla = true },
        objectives = { it = "Parla con Priestess Alathea, a Darnassus.", enHash = "af036438", vanilla = true },
        reward = { it = "Elune ti benedica per essere $Gtornato:tornata; da noi così in fretta. Questo è un momento importante del tuo addestramento, e tutto il nostro ordine lo prende molto sul serio. Quando ti sarai $Griposato:riposata; dal viaggio, fammelo sapere, ti prego. Allora potremo discutere di come proseguire il tuo addestramento e di dove ti porterà il tuo cammino.", enHash = "991511d7", vanilla = true },
    },
    [5674] = {
        title = { it = "Elune's Grace", enHash = "aeedb5a9", vanilla = true },
        text = { it = "È giunto un giorno meraviglioso, $N. Hai raggiunto l'età in cui $Gi nostri sacerdoti:le nostre sacerdotesse; vengono $Gaddestrati:addestrate; in abilità che conoscono solo gli elfi della notte. Ma non spetta a me addestrarti. Devi tornare al Temple of the Moon e parlare con Priestess Alathea non appena avrai concluso i tuoi affari qui. Ti metterà alla prova per assicurarsi che tu sia $Gpronto:pronta;, e solo allora ti insegnerà Elune's Grace.", enHash = { "e9796994", "abef8694" }, vanilla = true },
        objectives = { it = "Parla con Priestess Alathea, a Darnassus.", enHash = "af036438", vanilla = true },
        reward = { it = "Dedicandoti a Elune e al nostro popolo, hai raggiunto uno stato che non tutti noi possiamo raggiungere. È tradizione che, per la tua devozione, ti vengano insegnate abilità ancora più grandi. Accetti?", enHash = "a530f4ef", vanilla = true },
    },
    [5675] = {
        title = { it = "Elune's Grace", enHash = "aeedb5a9", vanilla = true },
        text = { it = "Non c'è tempo da perdere, $Gragazzo:ragazza;. È ora che tu torni a casa, a Darnassus. Priestess Alathea ha mandato a dire che devi tornare là per l'addestramento. Pare che ti ritengano $Gpronto:pronta; a essere $Gmesso:messa; alla prova, proprio come chi serve la Luce. Dovresti partire appena puoi. Nel suo messaggio Alathea diceva che ti avrebbe aspettato nel Temple of the Moon. Buona fortuna.", enHash = { "ea38e489", "00e25819" }, vanilla = true },
        objectives = { it = "Parla con Priestess Alathea, a Darnassus.", enHash = "af036438", vanilla = true },
        reward = { it = "Elune ti benedica per essere $Gtornato:tornata; da noi così in fretta. Questo è un momento importante del tuo addestramento, e tutto il nostro ordine lo prende molto sul serio. Quando ti sarai $Griposato:riposata; dal viaggio, fammelo sapere, ti prego. Allora potremo discutere di come proseguire il tuo addestramento e di dove ti porterà il tuo cammino.", enHash = "991511d7", vanilla = true },
    },
    [5676] = {
        title = { it = "Contraccolpo arcano", enHash = "a044741f", vanilla = true },
        reward = { it = "Siamo stati costretti a imparare alcune magie per proteggerci da quello che comunemente viene chiamato il nostro più grande nemico: l'arcano.\n\nVorrei insegnarti un incantesimo che ti aiuti a difendere te $Gstesso:stessa; e i tuoi compagni da chi vorrebbe usare un tale potere.", enHash = "c637f617", vanilla = true },
    },
    [5677] = {
        title = { it = "Contraccolpo arcano", enHash = "a044741f", vanilla = true },
        text = { it = "Per quanto mi piacerebbe mostrarti i nostri insegnamenti speciali sulla Luce, non sta a noi farlo. Il tuo posto è a Stormwind, con la tua gente, $N... per ora. Credimi, non intendo offenderti. Quando tornerai da High Priestess Laurena, nella Cathedral of Light, capirai di cosa parlo — è giunto il momento che la tua razza ti prepari per il futuro; che tu ti separi dagli altri che seguono un cammino simile.", enHash = "c4f3648b", vanilla = true },
        objectives = { it = "Parla con High Priestess Laurena, a Stormwind.", enHash = "b1314e9d", vanilla = true },
        reward = { it = "Ah, arrivi proprio al momento giusto, $N. Cominciavo a chiedermi se tutti i miei messaggeri fossero riusciti nel loro compito. Sono contenta di vedere che ci sono riusciti, altrimenti scommetto che saresti ancora in giro per il mondo a scoprire di più su tutte le minacce che incombono sul nostro popolo.\n\nSei $Gpronto:pronta;? $GPronto:Pronta; per altro addestramento, intendo. Il tuo potere cresce sempre più in fretta, e sento che sei $Gpronto:pronta; a imparare di più sulla nostra fede.", enHash = "af46adfd", vanilla = true },
    },
    [5678] = {
        title = { it = "Contraccolpo arcano", enHash = "a044741f", vanilla = true },
        text = { it = "È ora che tu torni a Stormwind, giovane. I tuoi superiori ti hanno richiamato là per altro addestramento. E anche se la cosa mi turba un po', la tua razza e la mia sono alleate, e io non lo tradirei.\n\nNon voglio essere così reticente con te — la mia diffidenza verso le magie arcane, che siano di ispirazione divina o no, è ancora forte in me.\n\nCapirai di cosa parlo quando tornerai alla tua Cathedral of Light. Parla con High Priestess Laurena quando arrivi.", enHash = "fe3cf365", vanilla = true },
        objectives = { it = "Parla con High Priestess Laurena, a Stormwind.", enHash = "b1314e9d", vanilla = true },
        reward = { it = "Ah, arrivi proprio al momento giusto, $N. Cominciavo a chiedermi se tutti i miei messaggeri fossero riusciti nel loro compito. Sono contenta di vedere che ci sono riusciti, altrimenti scommetto che saresti ancora in giro per il mondo a scoprire di più su tutte le minacce che incombono sul nostro popolo.\n\nSei $Gpronto:pronta;? $GPronto:Pronta; per altro addestramento, intendo. Il tuo potere cresce sempre più in fretta, e sento che sei $Gpronto:pronta; a imparare di più sulla nostra fede.", enHash = "af46adfd", vanilla = true },
    },
    [5679] = {
        title = { it = "Devouring Plague", enHash = "fec46d87", vanilla = true },
        reward = { it = "Ti insegnerei Devouring Plague, se ti senti $Gpronto:pronta;, $N. È un incantesimo di non poca potenza, e ti aiuterà nelle battaglie che verranno. Esercitati — più avanti ci saranno delle prove.", enHash = "c52fdae2", vanilla = true },
    },
    [5680] = {
        title = { it = "Shadowguard", enHash = "a33c5985", vanilla = true },
        reward = { it = "I tuoi riti arriveranno presto. Per ora ti insegno un incantesimo che ti sarà molto utile quando combatterai contro i tuoi nemici.", enHash = "d64ff152", vanilla = true },
    },
    [5713] = {
        title = { it = "Un colpo. Un morto.", enHash = "d9025fdc", vanilla = true },
        text = { it = "Stavo viaggiando verso Auberdine con un messaggio importante quando sono stata attaccata dal furbolg Marosh e dai suoi cacciatori. Durante l'attacco sono stata avvelenata, e ora reggermi in piedi mi costa fatica. So preparare un antidoto, ma ci vorrà del tempo prima che sia pronto.\n\nTi chiederei di difendermi finché non potrò usare l'antidoto. Ti aiuterò con il mio arco come meglio posso.\n\nSe sopravvivremo, potrò consegnare il mio messaggio ad Auberdine, mentre tu parlerai con Onaeya, a Maestra's Post, per informarla dell'accaduto.", enHash = "3292b238", vanilla = true },
        objectives = { it = "Proteggi Sentinel Aynasha, poi parla con Onaeya, a Maestra's Post, in Ashenvale.", enHash = "1ec02a24", vanilla = true },
        progress = { it = "Hai visto Sentinel Aynasha sulla strada? È partita per una missione importante e non è ancora tornata.", enHash = "6bd9080b", vanilla = true },
        reward = { it = "Porti notizie molto gradite, $C. È bello sapere che Aynasha è viva e sta bene, grazie a te. Vorrei che accettassi una ricompensa per il tuo valore. Che Elune vegli su di te e illumini il tuo cammino.", enHash = "cdd37e12", vanilla = true },
    },
    [5722] = {
        title = { it = "Alla ricerca della sacca perduta", enHash = "9a5e60a2", vanilla = true },
        text = { it = "I trogg non sono l'unica cosa che ha attirato l'interesse di Magatha sul Ragefire Chasm. Le è giunta voce che uno dei suoi servitori, un certo Maur Grimtotem, aveva trovato qualcosa di singolare mentre era nel Chasm, ma non è mai uscito per mostrarle cosa fosse. Vorrebbe che si ritrovasse il corpo di Maur — se ancora esiste — e ogni traccia di ciò che aveva scoperto mentre cercava di parlare con i trogg.\n\nPorta a Magatha qualunque oggetto interessante, e sono certo che sarà molto generosa nella ricompensa.\n\nAncora una volta, cerca il Chasm nelle zone più buie di Orgrimmar.", enHash = "52626c3a", vanilla = true },
        objectives = { it = "Cerca il cadavere di Maur Grimtotem nel Ragefire Chasm e frugalo in cerca di oggetti interessanti.", enHash = "8ed31b05", vanilla = true },
        reward = { it = "Il corpo sembra massacrato da clave o da pugni, ma quasi tutti i vestiti e l'equipaggiamento del cadavere sembrano ancora al loro posto. Pare che i trogg non tengano granché alle ricchezze materiali.\n\nCominci a frugare il corpo in cerca di qualcosa di interessante che possa aiutare Magatha.", enHash = "66cb37c8", vanilla = true },
    },
    [5723] = {
        title = { it = "Saggiare la forza del nemico", enHash = "482c31b0", vanilla = true },
        text = { it = "Sotto la città di Orgrimmar, creature tozze note come trogg hanno cominciato a salire in superficie dal fondo dei cunicoli colmi di lava. Nella sua immensa benevolenza, Magatha ha cercato di fare pace con quelle creature, ma loro si sono rivoltate contro i suoi diplomatici e li hanno uccisi. Non permetterà che il popolo tauren sia trattato così, e ora considera quelle creature una minaccia per tutta l'Orda.\n\nTi chiede di mettere fine alla minaccia dei trogg prima che sommerga l'Orda dal basso. Trova il Ragefire Chasm e distruggili tutti.", enHash = "a6edd8ab", vanilla = true },
        objectives = { it = "Cerca il Ragefire Chasm a Orgrimmar, poi uccidi 8 Ragefire Trogg e 8 Ragefire Shaman prima di tornare da Rahauro, a Thunder Bluff.", enHash = "7aefec01", vanilla = true },
        progress = { it = "Come procede la ricerca del Chasm? E i trogg?\n\nLa minaccia non può continuare — se va avanti, farà solo del male ai nostri fratelli orchi.", enHash = "9655e1eb", vanilla = true },
        reward = { it = "Sono lieto di vedere che hai preso sul serio il compito di Magatha. Grazie, $N. Sono certo che i trogg faranno molta più fatica a salire in superficie, ora che il loro numero è tanto ridotto.\n\nForse in futuro potremo prenderci il tempo di capire da dove vengano creature simili, e cosa vogliano davvero.", enHash = "289b3d75", vanilla = true },
    },
    [5724] = {
        title = { it = "Riportare la sacca perduta", enHash = "bae268b3", vanilla = true },
        text = { it = "Sotto il corpo del tauren trovi una sacca. È ancora stretta forte fra le sue braccia, come se avesse cercato di proteggerla mentre i trogg lo attaccavano.\n\nLiberata la sacca da quella morsa, la riponi insieme al tuo equipaggiamento e ti prepari a uscire dai cunicoli e a tornare da Rahauro, a Thunder Bluff.", enHash = "ad586113", vanilla = true },
        objectives = { it = "Porta la Grimtotem Satchel a Rahauro, a Thunder Bluff.", enHash = "5cab9843", vanilla = true },
        progress = { it = "Sei $Griuscito:riuscita; a trovare qualcosa, $N? Qualunque indizio sul perché uno dei suoi compagni di clan sia dovuto morire senza motivo sarebbe utile.", enHash = "bfdd4d55", vanilla = true },
        reward = { it = "Eccellente, $N. Grazie.\n\nMagatha mi ha detto di darti questo, se fossi $Griuscito:riuscita; a ritrovare il suo compagno di clan. Prendilo, ti prego, in segno di gratitudine.", enHash = "b04b2699", vanilla = true },
    },
    [5725] = {
        title = { it = "Il potere di distruggere...", enHash = "812050ef", vanilla = true },
        text = { it = "Molti abitanti della Legione elargiscono doni ai loro seguaci, come forse ben sai. Alcuni di questi doni, secondo la Signora Oscura, starebbero meglio nelle sue mani che in quelle di chi ha... una visione più angusta.\n\nUna setta del Concilio dell'Ombra nascosta nelle caverne sotto Orgrimmar, nota come Searing Blade, ne è l'esempio perfetto. La Signora mi dice che i membri della Searing Blade sono entrati in possesso di due potenti libri di incantesimi: le piacerebbe \"prenderli in prestito\". Tu glieli procurerai.", enHash = "bfffcbe8", vanilla = true },
        objectives = { it = "Porta i libri Spells of Shadow e Incantations from the Nether a Varimathras, nell'Undercity.", enHash = "6e9938f5", vanilla = true },
        progress = { it = "Ci sono altri cento compiti che attendono la mia attenzione, $C. Hai i libri?", enHash = "ad3ac04e", vanilla = true },
        reward = { it = "Bene, $C. Hai servito bene la Signora Oscura. La tua costanza e la tua ambizione saranno di grande utilità ai sudditi della Signora. Torna da me anche in futuro. Forse avrò altri compiti per te, che aiuteranno la Signora Oscura nel suo tentativo di soppiantare il Re dei Lich e di liberare del tutto il Flagello.", enHash = "118879b0", vanilla = true },
    },
    [5726] = {
        title = { it = "Nemici nascosti", enHash = "7365cdb0", vanilla = true },
        text = { it = "C'è una cosa che non tollero, $N: i traditori in mezzo a noi. Ma sarei uno sciocco a scoprire le carte così presto: non estirperebbe a fondo la corruzione dalle nostre terre e farebbe solo peggiorare l'infezione.\n\nTu però, $Gun giovane avventuriero:una giovane avventuriera;, potresti andare dove i miei agenti non possono... potresti scoprire la verità... potresti trovare la vera testa della bestia.\n\nSe hai abbastanza coraggio, entra a Skull Rock, a est di Orgrimmar, prendi l'insegna di un luogotenente da uno dei Burning Blade che ci sono là e torna da me.", enHash = "c759254c", vanilla = true },
        objectives = { it = "Porta una Lieutenant's Insignia a Thrall, a Orgrimmar.", enHash = "3d40d4af", vanilla = true },
        progress = { it = "Ce l'hai già l'insegna, $N?\n\nSarà uno strumento fondamentale per infiltrarci in quella che credo sia la più grande minaccia per l'Orda, e per trovare finalmente la pace nella nostra nuova casa.\n\nScoprirai che ragnatela intricata sanno tessere gli uomini e gli orchi quando sono mossi dall'avidità e dal potere. I piani nascosti, la corruzione: tutto ti sarà chiaro. Ti ritroverai in mezzo a una guerra di cui non sapevi nemmeno l'esistenza.", enHash = "cb6d009c", vanilla = true },
        reward = { it = "Bene, $N! Siano lodati gli spiriti: forse sei tu che metterai finalmente a tacere le mie paure più grandi! Chi avrebbe sospettato che qualcuno $Gcosì giovane e coraggioso:così giovane e coraggiosa; si sarebbe alzato a difendere la nostra causa? Mi ricordi me stesso da giovane. Farò in modo che tu sia $Gricompensato:ricompensata; come meriti, se sopravvivremo entrambi alla tempesta che arriva.\n\nMa ci sarà tempo per altri elogi. Non hai ancora fatto nulla, in confronto a quel che dovrai affrontare... ma è un buon inizio.", enHash = "932c7ca9", vanilla = true },
    },
    [5727] = {
        title = { it = "Nemici nascosti", enHash = "7365cdb0", vanilla = true },
        text = { it = "Ora vediamo se questa insegna che hai trovato vale la fatica.\n\nIn città c'è uno stregone che crede di avere la mia fiducia. Non sa che io so dove sta davvero la sua lealtà. In realtà è il capo dei Burning Blade. Ma non correre a batterti con lui: ha uno scopo, e lo useremo contro i nostri nemici.\n\nPortagli questa insegna nel Cleft of Shadow, qui a Orgrimmar, parlagli e vedi se crede che tu sia $Guno:una; dei suoi, poi torna qui da me.", enHash = "c0d1515a", vanilla = true },
        objectives = { it = "Porta la Lieutenant's Insignia a Neeru Fireblade e parlagli. Valuta se crede che tu sia dei Burning Blade, poi torna da Thrall, a Orgrimmar.", enHash = "24340d73", vanilla = true },
        progress = { it = "Allora, $C? Ci è cascato con il nostro trucco, o le cose sono peggiori di quanto avessi immaginato?\n\nRendersi utili a Neeru renderà molto più facile infiltrarci nel Concilio dell'Ombra. Avrà un mucchio di informazioni che possiamo usare per stanare chi vorrebbe distruggere tutto quel che abbiamo costruito a Durotar.", enHash = "87ce0ebc", vanilla = true },
        reward = { it = "Eccellente! Davvero eccellente, $C!\n\nQuel che hai fatto oggi è solo il primo passo di una costruzione molto più ampia: le fondamenta su cui costruiremo la distruzione definitiva del Concilio dell'Ombra.\n\nRaccontami tutto quel che ha detto... e non tralasciare una parola: potrebbe essere più importante di quanto credi.", enHash = "8c4cd4c8", vanilla = true },
    },
    [5728] = {
        title = { it = "Nemici nascosti", enHash = "7365cdb0", vanilla = true },
        text = { it = "Hmm, i capi della Searing Blade... è questo che mi preoccupa di più. Se sono loro quelli che contano per Neeru, allora sono loro il primo bersaglio. Questo satiro... Bazzalan, e l'altro che Neeru ha nominato — cos'era, uno stregone? — devono morire.\n\nTorna alla Cleft of Shadow ed entra nel Ragefire Chasm, $N. Trova questi due capi della Searing Blade e uccidili. Ma sta' $Gattento:attenta; a non far sapere a Neeru che sei $Gstato:stata; tu. Devi conservare la tua identità di $Gfratello:sorella; d'arme.", enHash = { "d0c32d46", "4c5f2090" }, vanilla = true },
        objectives = { it = "Uccidi Bazzalan e Jergosh the Invoker prima di tornare da Thrall, a Orgrimmar.", enHash = "5f1d8be7", vanilla = true },
        progress = { it = "Li hai già trovati, $N? I capi della Searing Blade.\n\nSapevo che il Concilio dell'Ombra voleva strapparmi Orgrimmar e tutta l'Orda, ma non immaginavo quanto in fretta sarebbero riusciti a infiltrarsi nella città. Quante braccia ha questa bestia... possiamo tagliarle finché non crolliamo dalla fatica, e non saremo più avanti di quando abbiamo cominciato. Dovrò far raddoppiare gli sforzi alle mie spie.", enHash = "b854b861", vanilla = true },
        reward = { it = "Sono lieto che tu sia $Gtornato:tornata;, $N. Alcuni dei miei fedeli mi hanno subito riferito che le caverne sotto Orgrimmar sono nel caos, ora che i loro capi sono stati uccisi. Ho perfino sentito dire che Neeru era più che agitato. Pare che gli abbiamo ammaccato l'armatura. Non posso dire di esserne dispiaciuto... nemmeno per una vittoria così piccola.", enHash = "a70bb27c", vanilla = true },
    },
    [5729] = {
        title = { it = "Nemici nascosti", enHash = "7365cdb0", vanilla = true },
        text = { it = "Credo che il prossimo passo debba essere metterti vicino a Neeru. Se è agitato come dicono i rapporti, possiamo ottenere due cose. La prima: potresti riuscire a sapere di più sul Concilio o almeno sui Burning Blade. La seconda: potrebbe cominciare a fidarsi di te abbastanza da chiederti di aiutarlo. Potrebbe benissimo vederti come qualcuno in grado di riempire il vuoto, ora che parte dei capi è nel caos.\n\nTorna al Cleft e parlagli di nuovo, ma non essere troppo $Gsfacciato:sfacciata;.", enHash = "9efb389f", vanilla = true },
        objectives = { it = "Parla con Neeru Fireblade, a Orgrimmar.", enHash = "ec825bf9", vanilla = true },
        reward = { it = "Cosa c'è?! Oh, sei tu, $C... chiedo scusa. La mia rabbia è pari a quella di un toro kodo rabbioso... ma forse è colpa mia. Mandando viaggiatori nel Ragefire Chasm, avrei dovuto prevedere che ne sarebbe venuto qualche danno. Pare che Bazzalan e Jergosh siano stati colti di sorpresa e uccisi da qualcuno dei benefattori di Thrall. Un momento pessimo, ma ormai non c'è niente da fare.", enHash = "5ff9de99", vanilla = true },
    },
    [5730] = {
        title = { it = "Nemici nascosti", enHash = "7365cdb0", vanilla = true },
        text = { it = "Sei $Guno:una; dei miei luogotenenti! Preparati, $C. Presto ti chiamerò.\n\nIl tempo che ho speso sulla Searing Blade forse è ormai sprecato, ma questo non vuol dire che i piani del Concilio dell'Ombra altrove debbano soffrirne. Farò quel che posso per limitare i danni qui nel Ragefire Chasm. Intanto farò cominciare ai miei agenti nelle Barrens e in Ashenvale il lavoro sul nostro nuovo piano. Torna presto da me.", enHash = "b34b765e", vanilla = true },
        objectives = { it = "Parla con Thrall, a Orgrimmar, e raccontagli quel che hai scoperto.", enHash = "4d3a44a9", vanilla = true },
        reward = { it = "Ashenvale? Hmm, non avevo sentito di nessuna presenza del Concilio o dei Burning Blade in Ashenvale. Le mie spie indagheranno, $N. Hai fatto bene.\n\nPer ora riposa e tieniti $Goccupato:occupata; con altri compiti. Presto ti chiamerò di nuovo.\n\nLok-Tar Ogar!", enHash = "c793c66e", vanilla = true },
    },
    [5741] = {
        title = { it = "Sceptre of Light", enHash = "992e8a61", vanilla = true },
        text = { it = "Si dice che la Burning Blade, nella Thunder Axe Fortress a est, si sia impossessata dello Sceptre of Light sottraendolo ai naga. La leggenda narra che lo scettro sia in grado di far sprofondare intere città sotto i grandi mari. Non si deve permettere alla Burning Blade di possedere un simile potere.\n\nPer questo devi recuperare tu $Gstesso:stessa; lo scettro! Lo custodisce un veggente della Burning Blade, che lo studia dalla cima di una delle torri di guardia di Thunder Axe.", enHash = "fb76c639", vanilla = true },
        objectives = { it = "Prendi lo Sceptre of Light e poi portalo ad Azore Aldamort, alla torre di Ethel Rethor.", enHash = "c011c44b", vanilla = true },
        progress = { it = "Hai lo Sceptre of Light?", enHash = "6ef3562d", vanilla = true },
        reward = { it = "L'inafferrabile Sceptre of Light! Recuperandolo hai eliminato una grave minaccia per il mondo. Ben fatto, $C, ben fatto.", enHash = "51411d43", vanilla = true },
    },
    [5761] = {
        title = { it = "Uccidere la bestia", enHash = "44960b81", vanilla = true },
        text = { it = "Il compito principale che il nostro grande Capoguerra mi ha affidato è stanare le creature responsabili di aver infestato la grande città del nostro signore con l'influsso demoniaco. La Burning Blade è una minaccia, ma ce ne sono altre; la Searing Blade, per esempio, che ha la sua tana nel Ragefire Chasm e tenta di sovvertire di nascosto membri innocenti dell'Orda.\n\nSe li si vuole fermare, bisogna uccidere il loro capo — un Felguard di nome Taragaman the Hungerer.\n\nUccidilo, e il suo cuore placherà Thrall, ne sono certo.", enHash = "8dc817f5", vanilla = true },
        objectives = { it = "Entra nel Ragefire Chasm e uccidi Taragaman the Hungerer, poi riporta il suo cuore a Neeru Fireblade, a Orgrimmar.", enHash = "e5ae5911", vanilla = true },
        progress = { it = "Hai ucciso la bestia? Dev'essere senza dubbio lui il capo della Searing Blade nel Ragefire Chasm.", enHash = "57a27a5b", vanilla = true },
        reward = { it = "Ah! Ce l'hai fatta! Thrall ne sarà felicissimo.\n\nMi assicurerò che questo cuore sia trattato come si deve.\n\nPer ora, però, devi festeggiare la tua vittoria. Informerò Thrall del tuo successo.\n\nGrazie del tuo aiuto, $C.", enHash = "026a2592", vanilla = true },
    },
    [5762] = {
        title = { it = "Hemet Nesingwary", enHash = "09c4b758", vanilla = true },
        text = { it = "Ho un pacco per un mio vecchio cliente, un nano di nome Hemet Nesingwary. Il pacco ci ha messo settimane ad arrivare, e ormai Hemet se n'è andato da un pezzo. Diceva che andava a Stranglethorn a cacciare le bestie di laggiù, ma mi ha lasciato dei soldi perché gli spedissi la consegna appena possibile.\n\nHemet è un nano ricco, e con i ricchi conviene tenere buoni rapporti, no? Allora... vuoi consegnargli tu il pacco?\n\nHo sentito che Hemet ha un campo a Stranglethorn, a nord di Grom'gol.", enHash = "6ec04822", vanilla = true },
        objectives = { it = "Porta Kravel's Crate a Hemet Nesingwary, a Stranglethorn.", enHash = "866a3edc", vanilla = true },
        progress = { it = "Quella sul colletto è polvere del deserto?\n\nHmm... se il naso non mi inganna, direi che non è polvere del deserto, è sale del deserto! Sei $Gstato:stata; alle Shimmering Flats, eh?", enHash = "33c117b3", vanilla = true },
        reward = { it = "Ottimo, il mio pacco da Koalbeard! Grazie, $N. Questa cassa contiene munizioni di calibro speciale, e ci servirà bene qui nella giungla!\n\nEcco la tua paga, e dimmi: come sta quel vecchio brontolone di Kravel? Ancora a combinare guai, scommetto...", enHash = "f5a3af1b", vanilla = true },
    },
    [5763] = {
        title = { it = "A caccia a Stranglethorn", enHash = "b9812ccb", vanilla = true },
        text = { it = "Tanto tempo fa, un nano venne in questa terra. Si chiamava Hemet e voleva cacciare grandi bestie. La sua abilità col fucile era prodigiosa, e passammo molti giorni a cacciare insieme. Perfino l'inimicizia tra i nostri popoli fu dimenticata.\n\nQuando lasciò Desolace per Stranglethorn, giurai che un giorno l'avrei accolto di nuovo, perché potessimo cacciare ancora. Ora è giunto quel momento.\n\nPorta questo corno di kodo a Hemet. Saprà che viene da me. Lo troverai a Stranglethorn, a nord del Grom'gol Base Camp.", enHash = "b0cd9886", vanilla = true },
        objectives = { it = "Porta Roon's Kodo Horn a Hemet Nesingwary, a Stranglethorn.", enHash = "f062805b", vanilla = true },
        progress = { it = "Siediti, $C. Presto tornerai a lanciarti nella giungla.", enHash = "14cc163d", vanilla = true },
        reward = { it = "Ah, questo corno appartiene a un tauren, Roon Wildmane. Io e lui ci siamo divertiti a cacciare le bestie di Desolace. Quindi Roon mi invita a tornare, eh?\n\nAl momento siamo immersi fino al collo nella giungla, ma grazie, $N. Forse la mia prossima spedizione mi riporterà a Desolace, la terra dei centauri.", enHash = "9cb35e5d", vanilla = true },
    },
    [5821] = {
        title = { it = "Guardia del corpo a pagamento", enHash = "f6baf928", vanilla = true },
        text = { it = "In circostanze normali, Rigger e io guideremmo i nostri kodo oltre i Kolkar Centaur. Ogni tanto sentiamo i tamburi di guerra dei centauri, e quando li sentiamo ci fermiamo. Essere morti non fa bene agli affari!\n\nFacciamo così, $C: se ci proteggi finché non avremo superato il villaggio dei Kolkar, ne varrà la pena per te.\n\nÈ solo un breve tratto: devi soltanto tenere intatta la carovana e potrai ritirare la ricompensa da Smeed Scrabblescrew, che sta un po' più avanti lungo la strada. Facciamo qualche affare insieme.", enHash = "7e5c97f4", vanilla = true },
        objectives = { it = "Scorta la Gizelton Caravan oltre il villaggio dei Kolkar Centaur. Parla con Smeed allo Scrabblescrew's Camp per la ricompensa.", enHash = "3088ada1", vanilla = true },
        progress = { it = "Perché mi ritrovo ad aspettare quella maledetta carovana?\n\n<Smeed si illumina.>\n\nAh già, pagano i conti. Li hai visti?", enHash = "4db56e1d", vanilla = true },
        reward = { it = "Sai, pagare gente come te per sorvegliare la Gizelton Caravan non sembra un grande affare. $C, se fossi un po' più alto potrei prendermi un secondo lavoro e sedermi all'amazzone su un kodo con il fucile più grosso che le mie mani possano reggere... e farei vedere io a quei maledetti centauri chi comanda.", enHash = "7105b9b5", vanilla = true },
    },
    [5881] = {
        title = { it = "Chiamare le riserve", enHash = "b185edc5", vanilla = true },
        text = { it = "L'Orda fa bene a tenere fresche le nostre truppe... dalla Grande Guerra siamo stati prosperi qui in Kalimdor.\n\nHo bisogno che tu mi faccia un favore. Ho un ragazzo di nome Grish Longrunner che presidia il Great Lift, nelle Barrens meridionali. Dagli questa lettera; la lettera gli farà sapere che ho un guerriero di riserva in arrivo per dargli il cambio, così potrà andare a trovare la famiglia. L'ha chiesto tempo fa e sarà felice di sentire la notizia.", enHash = "b42315d3", vanilla = true },
        objectives = { it = "Maggran vuole che tu consegni una lettera a Grish Longrunner, al Great Lift nelle Barrens.", enHash = "cd293cd3", vanilla = true },
        progress = { it = "Hai notizie da Maggran Earthbinder?", enHash = "7c455a00", vanilla = true },
        reward = { it = "Questa sì che è una bella notizia; sono rimasto seduto qui a fare la guardia a questo pezzo di legno per troppo tempo. Ora posso passare un po' di tempo con la mia famiglia... Evviva!", enHash = "0479749f", vanilla = true },
    },
    [5901] = {
        title = { it = "Che la piaga ti colga", enHash = "638af52b", vanilla = true },
        text = { it = "Allora, per portare dolore e discordia alla Crociata Scarlatta, voglio togliere loro la preziosa segheria. Sono sicura che perdere una risorsa del genere danneggerà molto la difesa e la ricostruzione della città, per qualunque scopo la vogliano. Mi aiuterai, $N?\n\nComincia portando questo barattolo nella Plaguewood, nelle Eastern Plaguelands. Riempilo con le termiti che trovi nei loro cumuli, sparsi per il bosco. Torna quando ne avrai abbastanza.", enHash = "86a45b8f", vanilla = true },
        objectives = { it = "Usa l'Empty Termite Jar sui Termite Mound delle Eastern Plaguelands. Quando avrai raccolto 100 Plagueland Termites, torna da Mickey Levine al Bulwark, nelle Tirisfal Glades.", enHash = "848712fc", vanilla = true },
        progress = { it = "Hai già le termiti, $N? Sono sicura che per $Gun:una; $C $Gsveglio:sveglia; come te sia una cosa ovvia.\n\nQuando ne avremo abbastanza, faremo in modo che nessuno possa più usare quella segheria!", enHash = "cdeff560", vanilla = true },
        reward = { it = "Queste andranno benissimo, $N. Grazie.\n\nSe sei $Gpronto:pronta;, possiamo passare al prossimo passo.", enHash = "57adf117", vanilla = true },
    },
    [5902] = {
        title = { it = "Che la piaga ti colga", enHash = "638af52b", vanilla = true },
        text = { it = "Ora che abbiamo termiti in abbondanza, porta questo barile rinforzato d'acciaio alla Northridge Lumber Mill, a sud di Hearthglen: la troverai a ovest della strada che porta su fino alla città.\n\nUna volta lì, metti il barile al centro della segheria, in un punto rialzato, per esempio su una cassa o qualcosa del genere.\n\nDopo che l'avrai aperto, il resto verrà da sé. Poi torna qui e ti ricompenserò per avermi aiutata.", enHash = "aec68abc", vanilla = true },
        objectives = { it = "Trova un posto adatto al centro della Northridge Lumber Mill, nelle Western Plaguelands, per mettere il Barrel of Plagueland Termites.", enHash = "3169df86", vanilla = true },
        reward = { it = "Mentre metti il barile sopra la cassa, le termiti si agitano visibilmente.", enHash = "d4613ecd", vanilla = true },
    },
    [5921] = {
        title = { it = "Moonglade", enHash = "dd2c833c", vanilla = true },
        text = { it = "Tutti i druidi sono i benvenuti nelle terre sacre di Moonglade, nonostante le attuali tensioni nel Cenarion Circle tra Arch Druid Staghelm e Keeper Remulos — il guardiano di Moonglade. Ora che stai imparando le vie dell'Unghia, ti insegnerò l'incantesimo che ti permette di trasportarti laggiù. Lancialo ogni volta che cerchi la conoscenza o il conforto di Moonglade.\n\nQuanto alla tua prima lezione, va' a Moonglade e parla con Dendrite Starblaze, a Nighthaven, del cammino che hai intrapreso. Buona fortuna, giovane $Gdruido:druida;.", enHash = "ad79a586", vanilla = true },
        objectives = { it = "Usa l'incantesimo \"Teleport: Moonglade\" per raggiungere Moonglade. Quando arrivi, parla con Dendrite Starblaze nel villaggio di Nighthaven.", enHash = "2cca3bcd", vanilla = true },
        reward = { it = "\"E così comincia, Padre Cenarius. E così comincia.\"\n\nDendrite fa un gesto rapido e invisibile nell'aria sopra di sé. Una leggera aura di potere scende su di lui.\n\n\"La prima prospettiva della natura a cui devi adattarti è quella dell'orso. Ti metterò sulla strada per comprendere questo aspetto della vita druidica, ma sei tu che devi abbracciarlo e diffonderlo — ora e per sempre!\"", enHash = "f92b7c4b", vanilla = true },
    },
    [5922] = {
        title = { it = "Moonglade", enHash = "dd2c833c", vanilla = true },
        text = { it = "Tutti i druidi sono i benvenuti nelle terre sacre di Moonglade, tauren ed elfi della notte allo stesso modo. Keeper Remulos — il guardiano di Moonglade — veglia su tutti i druidi che vi riposano in letargo. Ora che stai imparando le vie dell'Unghia, ti insegnerò l'incantesimo che ti permette di trasportarti laggiù. Lancialo ogni volta che cerchi la conoscenza o il conforto di Moonglade.\n\nQuanto alla tua prima lezione, va' a Moonglade e parla con Dendrite Starblaze, a Nighthaven, del cammino che hai intrapreso. Buona fortuna, giovane $Gdruido:druida;.", enHash = "4f6ed265", vanilla = true },
        objectives = { it = "Usa l'incantesimo \"Teleport: Moonglade\" per raggiungere Moonglade. Quando arrivi, parla con Dendrite Starblaze nel villaggio di Nighthaven.", enHash = "2cca3bcd", vanilla = true },
        reward = { it = "\"E così comincia, Padre Cenarius. E così comincia.\"\n\nDendrite fa un gesto rapido e invisibile nell'aria sopra di sé. Una leggera aura di potere scende su di lui.\n\n\"La prima prospettiva della natura a cui devi adattarti è quella dell'orso. Ti metterò sulla strada per comprendere questo aspetto della vita druidica, ma sei tu che devi abbracciarlo e diffonderlo — ora e per sempre!\"", enHash = "f92b7c4b", vanilla = true },
    },
    [5923] = {
        title = { it = "Rispondere al richiamo", enHash = "90997387", vanilla = true },
        text = { it = "Scusa, $Gamico:amica;...\n\nMi è giunta voce che Mathrengyl Bearwalker ha fatto sapere di volerti parlare. Sembra che il tuo addestramento come $Gdruido:druida; stia per entrare in una nuova fase, e sarà lui a istruirti di persona. Mathrengyl è l'assistente diretto dell'arcidruido in persona, ed è uno dei druidi più saggi e venerabili che troverai a Teldrassil.\n\nLo troverai nel Cenarion Enclave di Darnassus, al piano superiore dell'albero di Fandral Staghelm.", enHash = "3e4fc3ca", vanilla = true },
        objectives = { it = "Parla con Mathrengyl Bearwalker nel Cenarion Enclave, a Darnassus.", enHash = "bf62ccc6", vanilla = true },
        reward = { it = "Sono lieto che oggi tu abbia trovato la strada fin qui, giovane $Gdruido:druida;. È giunto il momento di fare un grande passo verso un mondo molto più grande.\n\nIn ognuno dei figli di Cenarius c'è il richiamo a servire la natura. Gli animali e le piante sono nostri amici, oltre che nostri protetti. Scegliamo di dedicare la nostra vita a custodire l'equilibrio, per il loro bene e per il nostro. Il tuo primo passo in questo mondo sarà imparare le vie dell'orso, e imparare la forza del corpo e del cuore.\n\nPreparati!", enHash = "f1f29864", vanilla = true },
    },
