    [5926] = {
        title = { it = "Rispondere al richiamo", enHash = "90997387", vanilla = true },
        text = { it = "Scusa, $Gamico:amica;...\n\nMi è giunta voce che Turak Runetotem ha fatto sapere di volerti parlare. Sembra che il tuo addestramento come $Gdruido:druida; stia per entrare in una nuova fase, e sarà lui a istruirti di persona. Turak è uno degli assistenti dell'arcidruido; è noto come un druido saggio e paziente, e dovrebbe insegnarti bene.\n\nLo troverai a Thunder Bluff, nella tenda principale del Cenarion Circle, sull'Elder Rise.", enHash = "f2149053", vanilla = true },
        objectives = { it = "Parla con Turak Runetotem sull'Elder Rise, a Thunder Bluff.", enHash = "1a92b8ed", vanilla = true },
        reward = { it = "Sono lieto che oggi tu abbia trovato la strada fin qui, giovane $Gdruido:druida;. È giunto il momento di fare un grande passo verso un mondo molto più grande.\n\nIn ognuno dei figli di Cenarius c'è il richiamo a servire la natura. Gli animali e le piante sono nostri amici, oltre che nostri protetti. Scegliamo di dedicare la nostra vita a custodire l'equilibrio, per il loro bene e per il nostro. Il tuo primo passo in questo mondo sarà imparare le vie dell'orso, e imparare la forza del corpo e del cuore.\n\nPreparati!", enHash = "b50488f0", vanilla = true },
    },
