    [5929] = {
        title = { it = "Great Bear Spirit", enHash = "31959cca", vanilla = true },
        text = { it = "Nella parte nord-occidentale di Moonglade si trova la dimora di un essere saggio e nobile che chiamiamo Great Bear Spirit. Per tutti i druidi è stato un maestro e una guida verso la prima vera comprensione della natura dell'orso. Tutti i druidi, prima o poi, cercano la saggezza dello spirito, e tu non farai eccezione.\n\nVa' ora dal Great Bear Spirit e impara ciò che ha da insegnare. Quando sarà soddisfatto di te, torna da me qui a Nighthaven. Vedremo allora se hai davvero fatto tesoro delle lezioni che impartisce.", enHash = "09e315cb", vanilla = true },
        objectives = { it = "Cerca il Great Bear Spirit nella parte nord-occidentale di Moonglade e impara ciò che ha da insegnarti sulla natura dell'orso. Una volta finito, torna da Dendrite Starblaze a Nighthaven, in Moonglade.", enHash = "5f5c9e9a", vanilla = true },
        progress = { it = "Torna solo quando il Great Bear Spirit ti avrà rimandato da me. Il tuo addestramento non può continuare senza la sua benedizione.", enHash = "c744d4b6", vanilla = true },
        reward = { it = "Mentre ti avvicini, Dendrite fa un altro gesto invisibile nell'aria sopra di sé. Un'altra aura di potere scende su di lui, e sul suo viso compare un sorriso appena accennato.\n\n\"Sento in te una saggezza, giovane, che non c'era quando ci siamo incontrati la prima volta. Mi guardi con forza e con intenzione consapevole, anche se questa intenzione non è ancora concentrata. Ora imparerai a concentrare la tua forza e a fare tua la natura dell'orso nel tuo lavoro.\"", enHash = "3107d8d4", vanilla = true },
    },
    [5930] = {
        title = { it = "Great Bear Spirit", enHash = "31959cca", vanilla = true },
        text = { it = "Nella parte nord-occidentale di Moonglade si trova la dimora di un essere saggio e nobile che chiamiamo Great Bear Spirit. Per tutti i druidi è stato un maestro e una guida verso la prima vera comprensione della natura dell'orso. Tutti i druidi, prima o poi, cercano la saggezza dello spirito, e tu non farai eccezione.\n\nVa' ora dal Great Bear Spirit e impara ciò che ha da insegnare. Quando sarà soddisfatto di te, torna da me qui a Nighthaven. Vedremo allora se hai davvero fatto tesoro delle lezioni che impartisce.", enHash = "09e315cb", vanilla = true },
        objectives = { it = "Cerca il Great Bear Spirit nella parte nord-occidentale di Moonglade e impara ciò che ha da insegnarti sulla natura dell'orso. Una volta finito, torna da Dendrite Starblaze a Nighthaven, in Moonglade.", enHash = "5f5c9e9a", vanilla = true },
        progress = { it = "Torna solo quando il Great Bear Spirit ti avrà rimandato da me. Il tuo addestramento non può continuare senza la sua benedizione.", enHash = "c744d4b6", vanilla = true },
        reward = { it = "Mentre ti avvicini, Dendrite fa un altro gesto invisibile nell'aria sopra di sé. Un'altra aura di potere scende su di lui, e sul suo viso compare un sorriso appena accennato.\n\n\"Sento in te una saggezza, giovane, che non c'era quando ci siamo incontrati la prima volta. Mi guardi con forza e con intenzione consapevole, anche se questa intenzione non è ancora concentrata. Ora imparerai a concentrare la tua forza e a fare tua la natura dell'orso nel tuo lavoro.\"", enHash = "3107d8d4", vanilla = true },
    },
    [5931] = {
        title = { it = "Ritorno a Darnassus", enHash = "7ce6903a", vanilla = true },
        text = { it = "È giunto il momento di separarci, giovane, perché mettere in pratica le tue lezioni ti riporta da chi ti ha mandato da me. Mathrengyl Bearwalker cammina davvero in equilibrio con la natura, anche se vive pericolosamente vicino al luogo in cui l'equilibrio ha vacillato. Ascolta le sue istruzioni, e presto completerai le prime lezioni del tuo ruolo di $Gprotettore:protettrice; dell'equilibrio.\n\nOra va', giovane. Ci rivedremo.", enHash = "8d98f700", vanilla = true },
        objectives = { it = "Torna a Darnassus e parla con Mathrengyl Bearwalker nel Cenarion Enclave.", enHash = "4f32bbac", vanilla = true },
        reward = { it = "$GBentornato:Bentornata;, $N. Sento che il tuo primo incontro con il Great Bear Spirit è stato come lo è per tutti i druidi quando cominciano a percorrere la via dell'Unghia... un po' sconcertante, ma molto intenso. So che per me è stato così.\n\nIl Great Bear Spirit fa parte di Azeroth da quando Azeroth esiste nei cieli. Siamo arrivati a contare sulla sua saggezza e sul suo potere per dare forza alla nostra missione. Ora è giunto il momento della tua prima prova al servizio di questa missione. Ascolta bene...", enHash = "8c67c322", vanilla = true },
    },
    [5932] = {
        title = { it = "Ritorno a Thunder Bluff", enHash = "aed7e663", vanilla = true },
        text = { it = "È giunto il momento di separarci, giovane, perché mettere in pratica le tue lezioni ti riporta da chi ti ha mandato da me. Anche se si pensa che i tauren siano giovani nelle vie di Cenarius, Turak Runetotem cammina con grande equilibrio al cospetto della natura. Ascolta le sue istruzioni, e presto completerai le prime lezioni del tuo ruolo di $Gprotettore:protettrice; dell'equilibrio.\n\nOra va', giovane. Ci rivedremo.", enHash = "11174e17", vanilla = true },
        objectives = { it = "Torna a Thunder Bluff e parla con Turak Runetotem sull'Elder Rise.", enHash = "fdd6f2da", vanilla = true },
        reward = { it = "$GBentornato:Bentornata;, $N. Sento che il tuo primo incontro con il Great Bear Spirit è stato come lo è per tutti i druidi quando cominciano a percorrere la via dell'Unghia... un po' sconcertante, ma molto intenso. So che per me è stato così.\n\nIl Great Bear Spirit fa parte di Azeroth da quando Azeroth esiste nei cieli. Noi tauren ascoltiamo con attenzione spiriti come questo, e tutti prosperiamo grazie alla sua missione. Ora è giunto il momento della tua prima prova al servizio di questa missione. Ascolta bene...", enHash = "5d22408f", vanilla = true },
    },
    [5943] = {
        title = { it = "Gizelton Caravan", enHash = "cf0df34a", vanilla = true },
        text = { it = "Sembri $Gun:una; $R capace. Forse ti interessa guadagnare qualche soldo? Cork e io abbiamo messo in piedi questa carovana per fare un mucchio di quattrini; non immaginavamo quanto potesse essere pericoloso fare affari!\n\nPiù avanti c'è la Mannoroc Coven... di solito i demoni ci ignorano, ma questa volta qualcosa ha spaventato i kodo. Ti pagherò per proteggere la carovana oltre la Mannoroc Coven. Quando l'avremo superata sani e salvi, potrai ricevere la ricompensa dal nostro socio d'affari Smeed, allo Scrabblescrew's Camp.", enHash = "a84907e9", vanilla = true },
        objectives = { it = "Scorta la Gizelton Caravan attraverso la Mannoroc Coven. Parla con Smeed allo Scrabblescrew's Camp per la ricompensa.", enHash = "79df07ad", vanilla = true },
        progress = { it = "Sai, se quella carovana dovesse mai sparire sarei rovinato! Non sei $Gil portatore:la portatrice; di cattive notizie sulla carovana, vero?\n\n<Smeed si asciuga la fronte.>\n\nSia ringraziata la dea dell'avidità!", enHash = "6c61cab2", vanilla = true },
        reward = { it = "Non sono sicuro che pagare così tanti soldi per proteggere la Gizelton Caravan sia un affare vantaggioso. Cork e Rigger guadagnano solo una moneta d'oro a settimana, ma finché continuano a pagarmi i kodo, di come mandano avanti i loro affari non me ne importa niente.", enHash = "77216fbe", vanilla = true },
    },
    [6001] = {
        title = { it = "Corpo e cuore", enHash = "8384bbbf", vanilla = true },
        text = { it = "Subito a est di Auberdine ci sono molte grotte di moonkin. In quella più vicina ad Auberdine c'è una Moonkin Stone. Lunaclaw, il difensore della pietra, ti affronterà solo quando sulla pietra verrà sparsa la Cenarion Moondust. Lunaclaw possiede una forza che tu devi usare come membro dell'Unghia.\n\nTi sei $Gguadagnato:guadagnata; il diritto di usare questa Cenarion Moondust, $N... ora dimostrami di esserti $Gguadagnato:guadagnata; il diritto di possedere la forza del corpo e la forza del cuore che ti servono come $Gdruido:druida;!", enHash = "89489e08", vanilla = true },
        objectives = { it = "Usa la Cenarion Moondust sulla Moonkin Stone di Auberdine per far comparire Lunaclaw. A quel punto dovrai affrontare Lunaclaw e guadagnarti la forza del corpo e del cuore che possiede.\n\nQuando hai finito, parla con Mathrengyl Bearwalker, a Darnassus.", enHash = "62fd3ae8", vanilla = true },
        progress = { it = "Quando avrai affrontato la sfida che ti attende, la tua comprensione della forza del corpo e della forza del cuore sarà completa. Fino ad allora, non posso aiutarti oltre.", enHash = "434c485e", vanilla = true },
        reward = { it = "Hai finalmente fatto il tuo grande passo verso un mondo molto più grande, $N. Sento dentro di te l'insegnamento del Great Bear Spirit, e sento che hai ricevuto la forza che Lunaclaw possedeva.\n\nNon ci sono più ostacoli sulla tua strada... lascia che ora ti insegni cosa significa essere $Gun Druido dell'Unghia:una Druida dell'Unghia;!", enHash = "61aeccfb", vanilla = true },
    },
    [6002] = {
        title = { it = "Corpo e cuore", enHash = "8384bbbf", vanilla = true },
        text = { it = "Nelle terre a ovest di Taurajo, nelle Barrens — appena prima che diventino Mulgore — si trova una Moonkin Stone. I moonkin sono bestie speciali, non originarie di queste parti. Lunaclaw, il difensore della pietra, ti affronterà quando sulla pietra verrà sparsa la Cenarion Lunardust. Lunaclaw possiede una forza che tu devi usare come membro dell'Unghia.\n\nTi sei $Gguadagnato:guadagnata; il diritto di usare questa Cenarion Lunardust, $N... ora dimostrami di esserti $Gguadagnato:guadagnata; il diritto di possedere la forza del corpo e la forza del cuore che ti servono come $Gdruido:druida;!", enHash = "75135018", vanilla = true },
        objectives = { it = "Usa la Cenarion Lunardust sulla Moonkin Stone tra Mulgore e le Barrens per far comparire Lunaclaw. A quel punto dovrai affrontare Lunaclaw e guadagnarti la forza del corpo e del cuore che possiede.\n\nQuando hai finito, parla con Turak Runetotem, a Thunder Bluff.", enHash = "b835a225", vanilla = true },
        progress = { it = "Quando avrai affrontato la sfida che ti attende, la tua comprensione della forza del corpo e della forza del cuore sarà completa. Fino ad allora, non posso aiutarti oltre.", enHash = "434c485e", vanilla = true },
        reward = { it = "Hai finalmente fatto il tuo grande passo verso un mondo molto più grande, $N. Sento dentro di te l'insegnamento del Great Bear Spirit, e sento che hai ricevuto la forza che Lunaclaw possedeva.\n\nNon ci sono più ostacoli sulla tua strada... lascia che ora ti insegni cosa significa essere $Gun Druido dell'Unghia:una Druida dell'Unghia;!", enHash = "61aeccfb", vanilla = true },
    },
    [6027] = {
        title = { it = "Book of the Ancients", enHash = "6b48bffc", vanilla = true },
        text = { it = "$N, ti affido la Gem of the Serpent. Metti questa gemma sulla mano della Serpent Statue, sulla Ranazjar Isle, una piccola isola a nord-ovest di qui. Posandola evocherai colui che protegge il Book of the Ancients. Questo libro contiene i segreti dei naga, segreti custoditi per secoli. Portami questo libro, e impareremo molto sui nostri nemici squamosi!", enHash = "4a28aef4", vanilla = true },
        objectives = { it = "Prendi il Book of the Ancients e riportalo ad Azore Aldamort, alla torre di Ethel Rethor.", enHash = "f90f25eb", vanilla = true },
        progress = { it = "Ah, $N! È bello rivederti. Hai il Book of the Ancients?", enHash = "6dfcb347", vanilla = true },
        reward = { it = "Il Book of the Ancients, perduto da tanto tempo! Mi assicurerò che questo libro venga consegnato all'alto consiglio. Oggi hai fatto un ottimo lavoro, e per questo meriti di essere $Gringraziato:ringraziata;... come si ringrazia un eroe!", enHash = "ae991e56", vanilla = true },
    },
    [6061] = {
        title = { it = "Addomesticare la bestia", enHash = "7e70cc92", vanilla = true },
        text = { it = "In quanto tauren, è importante seguire le tradizioni dei nostri antenati combattendo creature possenti. Sconfiggendo queste creature, possiamo accogliere in noi i loro spiriti, e questo ci permette di avvicinarci alla Madre Terra.\n\nAllo stesso modo, addomesticare una bestia perché combatta al nostro fianco ci aiuta a diventare una cosa sola con la natura che ci circonda. Col tempo imparerai ad addomesticare una bestia a tua scelta. Ma tutto richiede pratica, e hai molto da imparare. Comincia prendendo questa Taming Rod; devi addomesticare un Adult Plainstrider.", enHash = "c24adbf8", vanilla = true },
        objectives = { it = "Usa la Taming Rod per addomesticare un Adult Plainstrider. Esercita le tue abilità, poi riporta la Taming Rod a Yaw Sharpmane, a Bloodhoof Village.", enHash = "3938b4ec", vanilla = true },
        progress = { it = "Esercita le tue abilità, $N. Addomestica l'Adult Plainstrider.", enHash = "0109ac49", vanilla = true },
        reward = { it = "Mi sono apparsi dei segni dalla Madre Terra; hai fatto bene.", enHash = "84ceefab", vanilla = true },
    },
    [6062] = {
        title = { it = "Addomesticare la bestia", enHash = "7e70cc92", vanilla = true },
        text = { it = "Saper imporre la propria autorità sulla natura è un'abilità ammirevole. In quanto $Gcacciatore:cacciatrice;, devi sforzarti di imparare a usare la forza e il potere propri di qualunque creatura tu scelga.\n\nOttenere il controllo di un animale non è un'impresa facile; è un compito che devi affrontare con molta determinazione.\n\nCome primo incarico, prendi questa Taming Rod e usala per addomesticare un Dire Mottled Boar. Li trovi piuttosto vicino a Razor Hill. Esercita le tue abilità in battaglia con il cinghiale al tuo fianco, poi torna da me.", enHash = "f9919cde", vanilla = true },
        objectives = { it = "Usa la Taming Rod per addomesticare un Dire Mottled Boar. Esercita le tue abilità, poi riporta la Taming Rod a Thotar, a Razor Hill.", enHash = "59f548a3", vanilla = true },
        progress = { it = "Buona fortuna, $Ggiovane cacciatore:giovane cacciatrice;.", enHash = "13cf449f", vanilla = true },
        reward = { it = "Hai fatto bene, $N. Credo che tu sia $Gpronto:pronta; per il tuo prossimo compito.", enHash = "31c66360", vanilla = true },
    },
    [6063] = {
        title = { it = "Addomesticare la bestia", enHash = "7e70cc92", vanilla = true },
        text = { it = "In quanto $Gcacciatore:cacciatrice;, è importante che tu ricordi la responsabilità che hai tra le mani. La natura non è un potere che si possa piegare ai nostri desideri; è un potere che va rispettato e riconosciuto come qualcosa di più forte della tua stessa esistenza.\n\n$N, devi dimostrare di averlo compreso prima di ottenere la capacità di addomesticare un animale che sia tuo compagno.\n\nIl tuo primo compito è prendere questa Taming Rod. Con essa potrai addomesticare un Webwood Lurker. Addomesticalo, ed esercita le tue abilità di $Gcacciatore:cacciatrice;.", enHash = "fbd3a711", vanilla = true },
        objectives = { it = "Usa la Taming Rod per addomesticare un Webwood Lurker. Esercita le tue abilità, poi riporta la Taming Rod a Dazalar, a Dolanaar.", enHash = "3f49c3a2", vanilla = true },
        progress = { it = "Imparerai, $N, e un giorno sarai $Gun grande cacciatore:una grande cacciatrice;.", enHash = "e1d1af3d", vanilla = true },
        reward = { it = "Eccellente, $N! Impari davvero in fretta.", enHash = "6def5bb8", vanilla = true },
    },
    [6064] = {
        title = { it = "Addomesticare la bestia", enHash = "7e70cc92", vanilla = true },
        text = { it = "Ciao, $Gragazzo:ragazza;! Allora, vorresti sapere come ottenere un animale tutto tuo?\n\nBe', cominciamo. Non c'è niente di più importante del tuo equipaggiamento quando si tratta di cacciare, ma del mio nuovo Shrapnel Blaster possiamo parlare un'altra volta. Per ora concentriamoci su qualcosa che di sicuro ti interessa parecchio: un animale!\n\nIl modo migliore per imparare è provare diverse creature come compagne e vedere cosa ti piace. Quindi trova un Large Crag Boar, poi usa la Taming Rod per addomesticarlo.", enHash = { "1fe761d2", "f41c026a" }, vanilla = true },
        objectives = { it = "Usa la Taming Rod per addomesticare un Large Crag Boar. Esercita le tue abilità, poi riporta la Taming Rod a Grif Wildheart, a Kharanos.", enHash = "f46cf2d6", vanilla = true },
        progress = { it = "Non preoccuparti, $Gragazzo:ragazza;! Potrai provarne qualcuno prima di doverti decidere per uno solo.", enHash = "ac648a8b", vanilla = true },
        reward = { it = "Lo so, lo so; ti stai chiedendo cosa viene dopo, vero?!", enHash = "868ea7cd", vanilla = true },
    },
    [6065] = {
        title = { it = "La via del cacciatore", enHash = "55ee6c0b", vanilla = true },
        text = { it = "Salve, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza capace da saper gestire una bestia e addestrarla come compagna.\n\nDevi andare da Yaw Sharpmane, a Bloodhoof Village. Può metterti sulla via per guadagnarti un animale tutto tuo.", enHash = "020b2c5d", vanilla = true },
        objectives = { it = "Parla con Yaw Sharpmane, a Bloodhoof Village.", enHash = "ca5b1cbd", vanilla = true },
        reward = { it = "Sì, credo proprio che tu sia $Gpronto:pronta;...", enHash = "30947467", vanilla = true },
    },
