    [6074] = {
        title = { it = "La via del cacciatore", enHash = "55ee6c0b", vanilla = true },
        text = { it = "Salve, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza capace da saper gestire una bestia e addestrarla come compagna.\n\nDevi andare da Grif Wildheart, a Kharanos. Può metterti sulla via per guadagnarti un animale tutto tuo.", enHash = "7fbb3856", vanilla = true },
        objectives = { it = "Parla con Grif Wildheart, a Kharanos.", enHash = "092d01a4", vanilla = true },
        reward = { it = "Sì, credo proprio che anche tu sia $Gpronto:pronta;...", enHash = "9dc9ba41", vanilla = true },
    },
    [6075] = {
        title = { it = "La via del cacciatore", enHash = "55ee6c0b", vanilla = true },
        text = { it = "Salve, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza capace da saper gestire una bestia e addestrarla come compagna.\n\nDevi andare da Grif Wildheart, a Kharanos. Può metterti sulla via per guadagnarti un animale tutto tuo.", enHash = "7fbb3856", vanilla = true },
