    },
    [6081] = {
        title = { it = "Addestrare la bestia", enHash = "6f15c32a", vanilla = true },
        text = { it = "Ora hai il potere di addomesticare un animale, ma devi anche acquisire le abilità per addestrarlo.\n\nVa' a Orgrimmar. Lì dovrai parlare con uno dei nostri cacciatori più venerati, Ormak Grimshot. Ti darà la capacità di addestrare il tuo nuovo animale. Lo troverai vicino all'Hall of the Brave.\n\nBuona fortuna, $N.", enHash = "34cfb1f9", vanilla = true },
        objectives = { it = "Parla con Ormak Grimshot, a Orgrimmar.", enHash = "e4aaeb5e", vanilla = true },
        reward = { it = "$GUn giovane cacciatore:Una giovane cacciatrice;, vedo. Sì, ti concederò le abilità che ti servono per addestrare e guidare il tuo animale. Non solo potrai insegnare al tuo animale nuove abilità, ma ora potrai anche nutrirlo, e rianimarlo se dovesse cadere in battaglia.\n\nOra va', $Gcacciatore:cacciatrice;. Ci parleremo di nuovo più avanti.", enHash = "980a4e96", vanilla = true },
    },
    [6082] = {
        title = { it = "Addomesticare la bestia", enHash = "7e70cc92", vanilla = true },
        text = { it = "L'ultima creatura che devi addomesticare è una che dovresti sforzarti di emulare; l'Armored Scorpid. Colpisce con rapidità e sicurezza; controllare una forza come questa è il tuo destino di $Gcacciatore:cacciatrice;.\n\nQuando tornerai, ti concederò le abilità che ti serviranno per addomesticare un animale a tua scelta; questa creatura sarà ai tuoi ordini. Sotto il tuo controllo, il tuo animale guadagnerà esperienza insieme a te. Ti mostrerò anche come richiamarlo e congedarlo a tuo piacimento.", enHash = "20c70af6", vanilla = true },
        objectives = { it = "Usa la Taming Rod per addomesticare un Armored Scorpid. Esercita le tue abilità, poi torna da Thotar, a Razor Hill.", enHash = "9fac8464", vanilla = true },
        progress = { it = "Sei $Griuscito:riuscita; ad addomesticare lo scorpide?", enHash = "9a1b6692", vanilla = true },
        reward = { it = "Hai imparato tutto quello che potevo insegnarti, $N. È ora che tu metta a frutto quello che hai imparato qui e che scelga un animale tutto tuo.\n\nEcco a te, $N. Ora ti darò il potere di addomesticare una bestia, e anche di richiamarla e congedarla come ritieni opportuno. Usa con orgoglio le tue nuove abilità; te le sei guadagnate.", enHash = "9cfc41f9", vanilla = true },
    },
    [6083] = {
        title = { it = "Addomesticare la bestia", enHash = "7e70cc92", vanilla = true },
        text = { it = "Il vantaggio che un animale ti offre contro i tuoi rivali è ben noto, $N. Quando ottieni il controllo di un'altra creatura, aggiungi forza alla tua. Il tuo animale deve diventare un'estensione di te $Gstesso:stessa;.\n\nIl prossimo compito richiede che ti allontani dalla terraferma; troverai la prossima creatura nelle acque al largo della costa. Di fronte a Sen'jin Village, vicino alle Echo Isles, cerca un granchio vivace chiamato Surf Crawler. Usa la Taming Rod per addomesticarlo, poi esercita le tue abilità.", enHash = "bd28902c", vanilla = true },
        objectives = { it = "Usa la Taming Rod per addomesticare un Surf Crawler. Esercita le tue abilità, poi riporta la Taming Rod a Thotar, a Razor Hill.", enHash = "4914b1fc", vanilla = true },
        progress = { it = "Devi esercitarti per acquisire le abilità che ti servono a controllare con efficacia il tuo animale. Hai addomesticato un Surf Crawler?", enHash = "2719af1a", vanilla = true },
        reward = { it = "Impari in fretta, $N. Hai fatto bene.", enHash = "70fdd831", vanilla = true },
    },
    [6084] = {
        title = { it = "Addomesticare la bestia", enHash = "7e70cc92", vanilla = true },
        text = { it = "Quei Crag Boar sono piuttosto massicci; forse vorresti qualcosa con un po' più di finezza? E va bene, ho proprio quello che fa per te. A sud e a est di qui troverai dei grandi felini bianchi chiamati Snow Leopard. Proprio come un fucile elegantemente intagliato, dietro il loro bell'aspetto si nasconde un combattente potente, capace di fare danni tremendi. Vedrai che sono molto più agili e veloci del cinghiale che hai addomesticato.\n\nPrendi questa Taming Rod e vedi come ti trovi con lo Snow Leopard.", enHash = "3ece9d3b", vanilla = true },
        objectives = { it = "Usa la Taming Rod per addomesticare uno Snow Leopard. Esercita le tue abilità, poi torna da Grif Wildheart, a Kharanos.", enHash = "2e385ca8", vanilla = true },
        progress = { it = "Che ne pensi dello Snow Leopard, $N?", enHash = "5250f255", vanilla = true },
        reward = { it = "Quando sentirò che hai imparato abbastanza, ti concederò la capacità di scegliere qualunque animale ti piaccia.", enHash = "f5c4b7e9", vanilla = true },
    },
    [6085] = {
        title = { it = "Addomesticare la bestia", enHash = "7e70cc92", vanilla = true },
        text = { it = "Forse ti piacerebbe una creatura che possiede poco più della forza bruta. L'Ice Claw Bear è un compagno eccellente per $Gun cacciatore alle prime armi:una cacciatrice alle prime armi; come te, e si trova a est di Kharanos. Ecco la Taming Rod; prova questo animale come compagno e vedi se ti piace!\n\nQuando tornerai, ti darò le abilità che ti serviranno per addomesticare un animale a tua scelta; questa creatura affronterà le sfide che affronterai tu, e guadagnerà esperienza insieme a te. Ti mostrerò anche come richiamarla e congedarla come preferisci.", enHash = "28a48615", vanilla = true },
        objectives = { it = "Usa la Taming Rod per addomesticare un Ice Claw Bear. Esercita le tue abilità, poi riporta la Taming Rod a Grif Wildheart, a Kharanos.", enHash = "ac90b0e4", vanilla = true },
        progress = { it = "Hai già addomesticato l'Ice Claw Bear?", enHash = "1507b220", vanilla = true },
        reward = { it = "Ecco a te, $N. Ora ti darò il potere di addomesticare una bestia, e anche di richiamarla e congedarla come preferisci.\n\nTrovati un animale buono e fedele, e goditi la caccia!", enHash = "121c79e7", vanilla = true },
    },
    [6086] = {
        title = { it = "Addestrare la bestia", enHash = "6f15c32a", vanilla = true },
        text = { it = "$N, ora hai il potere di addomesticare un animale, ma devi anche acquisire le abilità per addestrarlo.\n\nVa' a Ironforge e cerca l'Hall of Arms. Lì dovrai parlare con una dei nostri istruttori di animali più venerati, Belia Thundergranite. Ti darà il potere di addestrare il tuo nuovo animale, quindi datti una mossa, $Gragazzo:ragazza;!\n\nBelia è una tipa cordiale; non dovresti avere problemi a ottenere la sua approvazione. Buona fortuna, $N.", enHash = { "311eedba", "1bd8e0cc" }, vanilla = true },
        objectives = { it = "Parla con Belia Thundergranite, a Ironforge.", enHash = "31bba333", vanilla = true },
        reward = { it = "Una nuova recluta, eh? Vedo che sei sulla buona strada per diventare $Gun:una; grande $C.\n\nSì, posso concederti le abilità che ti servono per addestrare e guidare il tuo animale. Non solo potrai insegnare al tuo animale nuove abilità, ma ora potrai anche nutrirlo, e rianimarlo se dovesse cadere in battaglia.\n\nRicorda che il segreto per ottenere il massimo dal tuo nuovo animale è rispettarlo e trattarlo bene. In cambio, il tuo animale sarà il tuo amico più fedele.", enHash = "d33c8b3f", vanilla = true },
    },
    [6087] = {
        title = { it = "Addomesticare la bestia", enHash = "7e70cc92", vanilla = true },
        text = { it = "Hai uno spirito ardente, $Gcacciatore:cacciatrice;, che attende con impazienza la prossima sfida.\n\nIl tuo prossimo compito è conquistare la compagnia di un lupo noto come Prairie Stalker. Questa creatura è veloce e impavida; prendendo questa bestia come tuo animale, dovrai fare tue anche queste qualità.\n\nDurante una battaglia imparerai come tu e il tuo animale diventerete una squadra. Alla fine dovrete agire come una cosa sola, muscolo a muscolo.\n\nEcco la Taming Rod, $N. Addomestica un Prairie Stalker ed esercita le tue abilità.", enHash = "6e4a3b5a", vanilla = true },
        objectives = { it = "Usa la Taming Rod per addomesticare un Prairie Stalker. Esercita le tue abilità, poi riporta la Taming Rod a Yaw Sharpmane, a Bloodhoof Village.", enHash = "fce8b4e3", vanilla = true },
        progress = { it = "Hai trovato un Prairie Stalker?", enHash = "e3852685", vanilla = true },
        reward = { it = "Sì... La Madre Terra ritiene che tu sia $Gpronto:pronta; per la prossima lezione.", enHash = "d65e53cc", vanilla = true },
    },
    [6088] = {
        title = { it = "Addomesticare la bestia", enHash = "7e70cc92", vanilla = true },
        text = { it = "L'ultimo compito che ho per te richiede che tu addomestichi una creatura che abita il cielo. Lo Swoop è un avversario difficile, ma se sarà tuo alleato, acquisirai i suoi attacchi taglienti e la sua presenza minacciosa.\n\nPer volere della Madre Terra, quando tornerai ti concederò le abilità che ti serviranno per addomesticare un animale a tua scelta che sia tuo compagno; questa creatura affronterà le sfide che affronterai tu, e guadagnerà esperienza insieme a te. Ti mostrerò anche come richiamarla e congedarla a tuo piacimento.", enHash = "0c5ff109", vanilla = true },
        objectives = { it = "Usa la Taming Rod per addomesticare uno Swoop. Esercita le tue abilità, poi riporta la Taming Rod a Yaw Sharpmane, a Bloodhoof Village.", enHash = "96eeb747", vanilla = true },
        progress = { it = "Presto sarai $Gpronto:pronta;, $N.", enHash = "3702ded2", vanilla = true },
        reward = { it = "Hai imparato tutto quello che potevo insegnarti, $N. Che le benedizioni della Madre Terra ti guidino nella scelta di un animale.\n\nEcco a te, $N. Ora ti darò il potere di addomesticare una bestia, e anche di richiamarla e congedarla come ritieni opportuno. Usa con orgoglio le tue nuove abilità e onora la Madre Terra.", enHash = "fd9f390c", vanilla = true },
    },
    [6089] = {
        title = { it = "Addestrare la bestia", enHash = "6f15c32a", vanilla = true },
        text = { it = "Ora hai il potere di addomesticare un animale, ma devi anche acquisire le abilità per addestrarlo.\n\nVa' a Thunder Bluff. Lì dovrai parlare con uno dei nostri cacciatori più venerati, Holt Thunderhorn. Se ti riterrà $Gdegno:degna;, ti darà la capacità di addestrare il tuo nuovo animale.\n\nHolt ha sconfitto le bestie più potenti e temute di Azeroth, e ha ai suoi ordini molte creature forti. I suoi legami con la Madre Terra sono forti, e puoi imparare molto da lui. Buona fortuna, $N.", enHash = "9660770b", vanilla = true },
        objectives = { it = "Parla con Holt Thunderhorn sull'Hunter Rise, a Thunder Bluff.", enHash = "58a467a1", vanilla = true },
        reward = { it = "$GUn giovane:Una giovane; $C, vedo. Sì, posso concederti le abilità che ti servono per addestrare e guidare il tuo animale. Non solo potrai insegnare al tuo animale nuove abilità, ma ora potrai anche nutrirlo, e rianimarlo se dovesse cadere in battaglia.\n\nOra va'. Che la Madre Terra ti guidi sul tuo cammino. Ci parleremo di nuovo più avanti.", enHash = "36eecc45", vanilla = true },
    },
    [6101] = {
        title = { it = "Addomesticare la bestia", enHash = "7e70cc92", vanilla = true },
        text = { it = "La varietà della natura è qualcosa su cui si può contare, $N. È prevedibile nel suo non restare mai uguale; è in continuo cambiamento.\n\nI compiti che ti affido ti aiuteranno a vedere e ad apprezzare le enormi differenze tra le creature che potresti scegliere come compagne.\n\nPrendi questa Taming Rod e usala per addomesticare un Nightsaber Stalker, che trovi a sud. Esercita le tue abilità di $Gcacciatore:cacciatrice;. Allora comincerai a capire le somiglianze e le differenze della natura.", enHash = "6595740a", vanilla = true },
        objectives = { it = "Usa la Taming Rod per addomesticare un Nightsaber Stalker. Esercita le tue abilità, poi riporta la Taming Rod a Dazalar, a Dolanaar.", enHash = "b5db7c09", vanilla = true },
        progress = { it = "Comprendere l'equilibrio tra la natura e sé stessi è uno stile di vita per ogni elfo della notte.", enHash = "7c0a0fcc", vanilla = true },
        reward = { it = "Vedo il tuo impegno, e vedo che hai compreso quello che ti ho insegnato, $N.", enHash = "b54ef115", vanilla = true },
    },
    [6102] = {
        title = { it = "Addomesticare la bestia", enHash = "7e70cc92", vanilla = true },
        text = { it = "Hai addomesticato due creature che abitano la terra, ora devi addomesticarne una che solca i cieli. Usa la Taming Rod per addomesticare uno Strigid Screecher, che trovi a ovest di qui. Esercita le tue abilità con questo possente gufo al tuo fianco.\n\nQuando tornerai, ti concederò le abilità che ti serviranno per addomesticare un animale a tua scelta che sia tuo compagno; questa creatura affronterà le sfide che affronterai tu, e guadagnerà esperienza insieme a te. Ti mostrerò anche come richiamarla e congedarla a tuo piacimento.", enHash = "620598a1", vanilla = true },
        objectives = { it = "Usa la Taming Rod per addomesticare uno Strigid Screecher. Esercita le tue abilità, poi riporta la Taming Rod a Dazalar, a Dolanaar.", enHash = "c7be74ca", vanilla = true },
        progress = { it = "Sono fiero dei tuoi successi, $N. Hai portato a termine l'ultimo compito che ti ho dato?", enHash = "540bc9ee", vanilla = true },
        reward = { it = "Hai imparato tutto quello che potevo insegnarti, $N. Permettimi di darti un ultimo consiglio: usa giudizio nello scegliere il tuo primo animale. Sceglierai una creatura della terra, dell'acqua o del cielo? Qualunque sia, senza dubbio il tuo animale resterà con te per parecchio tempo.\n\nEcco a te, $N. Ora ti darò il potere di addomesticare una bestia, e anche di richiamarla e congedarla come ritieni opportuno. Usa con orgoglio le tue nuove abilità; te le sei guadagnate.", enHash = "cf720caf", vanilla = true },
    },
    [6103] = {
        title = { it = "Addestrare la bestia", enHash = "6f15c32a", vanilla = true },
        text = { it = "Ora hai il potere di addomesticare un animale, ma devi anche acquisire le abilità per addestrarlo.\n\nVa' a Darnassus. Lì dovrai parlare con una delle nostre cacciatrici più venerate, Jocaste. Ti darà la capacità di addestrare il tuo nuovo animale, quindi affrettati.\n\nAnche se Jocaste può sembrare severa, è sempre contenta di vedere $Gun altro cacciatore:un'altra cacciatrice; salire di grado. Trattala con rispetto e lei ti ricambierà. Buona fortuna, $N.", enHash = "9dcb9a5b", vanilla = true },
        objectives = { it = "Parla con Jocaste nel Cenarion Enclave, a Darnassus.", enHash = "5b505d12", vanilla = true },
        reward = { it = "$GUn cacciatore alle prime armi:Una cacciatrice alle prime armi;, vedo. Sì, posso concederti le abilità che ti servono per addestrare e guidare il tuo animale. Non solo potrai insegnare al tuo animale nuove abilità, ma ora potrai anche nutrirlo, e rianimarlo se dovesse cadere in battaglia.\n\nRicorda, $N, rispetta sempre l'equilibrio e vivi in reverente ammirazione della natura che ti circonda. Ora va'. Ci parleremo di nuovo più avanti.", enHash = "331b8374", vanilla = true },
    },
    [6121] = {
        title = { it = "Nuove lezioni", enHash = "e0a5e464", vanilla = true },
        text = { it = "Ora sei $Gpronto:pronta; a conoscere i veleni e il potere che noi druidi abbiamo su di essi, $N. Cenarius ci ha fatto dono della capacità di purificare anche i veleni più immondi con una semplice formula. Questo dono non va preso alla leggera... e perché tu impari bene questa lezione, dovrai rimediare agli effetti degli avvelenamenti come farebbe una persona comune.\n\nVa' a Moonglade e parla con Dendrite Starblaze; aspetta il tuo arrivo per cominciare la lezione.", enHash = "4206ee25", vanilla = true },
        objectives = { it = "Va' a Moonglade e parla con Dendrite Starblaze nel villaggio di Nighthaven.", enHash = "f125ace4", vanilla = true },
        reward = { it = "Salve, giovane $Gdruido:druida;, sono lieto di vederti $Gpronto:pronta; e $Gdesideroso:desiderosa; di imparare a curare i veleni.\n\nIn passato la maggior parte dei druidi veniva sottoposta a prove preparate in anticipo, ma il tuo lavoro non avrà niente del genere. C'è stata un'ondata di avvelenamenti tra gli animali di Auberdine, e il villaggio non è riuscito a porvi rimedio. Per questo, un loro rappresentante ha chiesto aiuto a Moonglade, e noi ti mandiamo laggiù ad aiutarli. Non è un'esercitazione — il lavoro che farai è del tutto reale. Tienilo a mente.", enHash = "9a0e7b7c", vanilla = true },
    },
    [6122] = {
        title = { it = "La fonte principale", enHash = "4d08401c", vanilla = true },
        text = { it = "Le Cliffspring Falls, a Darkshore, sono la fonte principale di acqua potabile della regione, e ora sospetto che siano anche la fonte principale del veleno che sta facendo ammalare la fauna locale — i cervi, in particolare. Usa questo campionatore per prelevare un po' d'acqua dall'imboccatura della grotta; fai attenzione, perché ora in una grotta vicino alle cascate vivono naga pericolosi.\n\nUna volta riempito, consegnalo ad Alanndarian Nightsong, ad Auberdine. È lei che ha chiesto il nostro aiuto, e lavorerai con lei per affrontare questo male.", enHash = "aa087d6c", vanilla = true },
        objectives = { it = "Usa l'Empty Cliffspring Falls Sampler per prelevare un campione d'acqua dall'imboccatura della grotta vicino alle cascate.\n\nConsegna il Filled Cliffspring Falls Sampler ad Alanndarian Nightsong, ad Auberdine, in Darkshore.", enHash = "375e0876", vanilla = true },
        progress = { it = "Sei tu $Gquello:quella; che ha mandato il Cenarion Circle di Moonglade? Meraviglioso! Qui abbiamo una bella crisi per i poveri cervi, e siamo felici di ricevere tutto l'aiuto possibile.\n\nHai il campione d'acqua che Dendrite Starblaze ha detto che avresti portato? Mi ha avvisato che ne avresti prelevato uno, così potremo lavorare insieme a una cura...", enHash = "21694644", vanilla = true },
        reward = { it = "Per Elune, quest'acqua è disgustosa! Non c'è da stupirsi che i cervi stiano male.\n\nQualcosa sta inquinando l'acqua, e a sua volta corrompe l'intera falda di Darkshore. Si sono visti cervi malati in tutta la zona, e non solo vicino al fiume. Anche se quest'acqua è molto probabilmente una delle fonti principali della malattia che si sta diffondendo, qui c'è in gioco qualcos'altro.\n\nChe tu ci creda o no, quest'acqua ci aiuterà a preparare una cura. Mentre la studio, mi servono alcuni oggetti per formulare la cura...", enHash = "3e1e58cc", vanilla = true },
    },
    [6123] = {
        title = { it = "Gli ingredienti della cura", enHash = "e33bd86d", vanilla = true },
        text = { it = "L'acqua farà da base per l'unguento curativo che preparerò per i cervi. Per le proprietà curative mi serve un po' di Earthroot. Gli erboristi sanno come trovarla, quindi, se siamo sfortunati e tu non sei $Gun erborista:un'erborista;, dovrai trovarne uno che ci dia una mano.\n\nInfine, per la potenza, mi serve del Lunar Fungus. Trovare le fioriture di funghi lunari è abbastanza facile; sono dappertutto nelle grotte subito a est di qui. Nelle grotte vivono i moonkin, e ultimamente sono irritabili, quindi fai attenzione.", enHash = "c9543326", vanilla = true },
        objectives = { it = "Porta 5 Earthroot e 12 Lunar Fungus ad Alanndarian Nightsong, ad Auberdine, così che possa preparare un unguento curativo.", enHash = "fca1a73e", vanilla = true },
        progress = { it = "Hai i reagenti che mi servono per preparare l'unguento? I cervi non migliorano da soli, quindi è meglio sbrigarci ad aiutarli!", enHash = "77336aa6", vanilla = true },
        reward = { it = "È ottimo, $N, tanto che dovrebbe bastare per preparare parecchie dosi dell'unguento — almeno abbastanza da cominciare a fare la differenza.\n\nPreparare una cura contro i veleni a volte può essere piuttosto difficile, perché spesso ognuno richiede un antidoto molto specifico per contrastarlo. Immagina di poter curare un veleno a piacimento, senza doverti preoccupare di quali debbano essere esattamente gli ingredienti dell'antidoto!\n\nOra lascia che mi metta al lavoro!", enHash = "ae9f3080", vanilla = true },
    },
    [6124] = {
        title = { it = "Curare i malati", enHash = "62aed44b", vanilla = true },
        text = { it = "Con i reagenti che mi hai portato ho preparato abbastanza unguento per dieci dosi, $N. Mentre lavoro con il villaggio per cercare di prepararne ancora, vorrei che ci aiutassi a portarci avanti. In tutto Darkshore ci sono cervi malati; usa l'unguento su di loro e guariscili dal loro male.\n\nDendrite Starblaze, a Moonglade, vorrà parlarti quando avrai finito, ne sono certa. Ti prego, porta al Cenarion Circle laggiù i ringraziamenti di Auberdine... e lascia che ti ringrazi anche io direttamente per l'aiuto che ci hai dato!", enHash = "7f71c915", vanilla = true },
        objectives = { it = "Usa il Curative Animal Salve su 10 Sickly Deer che si trovano in tutto Darkshore; così dovresti curarli. Sono stati segnalati Sickly Deer dalla zona a sud del Cliffspring River, a nord di Auberdine, fino al sud di Darkshore, dove cominciano i confini di Ashenvale.", enHash = "11685281", vanilla = true },
        progress = { it = "Hai portato a termine ciò che ti ha chiesto Alanndarian Nightsong, di Auberdine? Il tuo lavoro non è completo finché non l'avrai fatto.", enHash = "b661258e", vanilla = true },
        reward = { it = "Hai fatto bene a prenderti cura dei cervi malati di Darkshore; sono vittime inconsapevoli di una corruzione, di un male più grande che si sta diffondendo in tutta la terra. A Darnassus c'è chi sceglie di riconoscere questa minaccia... e c'è chi ignora i segnali sempre più numerosi. Spero che tu non sia di quelli che si mettono i paraocchi davanti all'evidenza, $N.\n\nIn ogni caso, hai dimostrato il tuo valore come $Gamico:amica; della natura e del Circle — prendi questo come simbolo.", enHash = "6876b9e6", vanilla = true },
    },
    [6125] = {
        title = { it = "Potere sui veleni", enHash = "731a1939", vanilla = true },
        text = { it = "Hai imparato cosa significa curare un veleno senza poter contare su un aiuto spirituale. Ricorda quello che gli altri devono sopportare quando combattono gli avvelenamenti, ora che stai per fare tuo il nuovo potere sui veleni.\n\nOra dovresti tornare da Mathrengyl Bearwalker, a Darnassus, $N. Senza dubbio ha un incantesimo molto importante da insegnarti, ora che $Gl'allievo:l'allieva; ha compreso la lezione che $Ggli:le; è stata impartita.\n\nArrivederci, giovane $Gdruido:druida;. Parleremo ancora.", enHash = { "c33a548c", "8ca77fa3" }, vanilla = true },
        objectives = { it = "Torna da Mathrengyl Bearwalker, nel Cenarion Enclave, a Darnassus.", enHash = "fdb1b91d", vanilla = true },
        reward = { it = "$GBentornato:Bentornata; — ho seguito i tuoi progressi in questa lezione da quando sei $Gpartito:partita;, e devo ammettere che la situazione di Auberdine mi ha sorpreso. La faccenda merita altre indagini, perché l'arrivo di veleni come questi nell'ambiente turba moltissimo l'equilibrio.\n\nSotto pressione hai mantenuto calma e compostezza. Per questo non trovo modo migliore di ricompensarti che con un potere permanente sui veleni. Usalo bene, $N... usalo bene.", enHash = "33f5015c", vanilla = true },
    },
    [6126] = {
        title = { it = "Nuove lezioni", enHash = "e0a5e464", vanilla = true },
        text = { it = "Ora sei $Gpronto:pronta; a conoscere i veleni e il potere che noi druidi abbiamo su di essi, $N. Cenarius ci ha fatto dono della capacità di purificare anche i veleni più immondi con una semplice formula. Questo dono non va preso alla leggera... e perché tu impari bene questa lezione, dovrai rimediare agli effetti degli avvelenamenti come farebbe una persona comune.\n\nVa' a Moonglade e parla con Dendrite Starblaze; aspetta il tuo arrivo per cominciare la lezione.", enHash = "4206ee25", vanilla = true },
        objectives = { it = "Va' a Moonglade e parla con Dendrite Starblaze nel villaggio di Nighthaven.", enHash = "f125ace4", vanilla = true },
        reward = { it = "Salve, giovane $Gdruido:druida;, sono lieto di vederti $Gpronto:pronta; e $Gdesideroso:desiderosa; di imparare a curare i veleni.\n\nIn passato la maggior parte dei druidi veniva sottoposta a prove preparate in anticipo, ma il tuo lavoro non avrà niente del genere. C'è stata un'ondata di avvelenamenti tra gli animali al Crossroads, nelle Barrens, e laggiù non riescono a tenerla sotto controllo. Qualcuno del posto ha chiesto aiuto a Moonglade, quindi ti mandiamo là ad aiutarli. Non è un'esercitazione — il lavoro che farai è del tutto reale. Tienilo a mente.", enHash = "23e92287", vanilla = true },
    },
    [6127] = {
        title = { it = "La fonte principale", enHash = "4d08401c", vanilla = true },
        text = { it = "Il Dreadmist Peak, a nord-ovest del Crossroads, è con ogni probabilità uno dei candidati principali come origine del veleno che si sta diffondendo. Sulle sue alte vette ci sono pozze d'acqua che influenzano il clima della zona. Sospetto che ora l'acqua sia stata corrotta dalla Burning Blade, che adora i demoni.\n\nUsa questo campionatore per prelevare l'acqua dalla pozza che si trova proprio in cima al picco. Una volta riempito, consegnalo a Tonga Runetotem, al Crossroads. È lui che ha chiesto il nostro aiuto, e lavorerai con lui per affrontare questo male.", enHash = "2de46b04", vanilla = true },
        objectives = { it = "Usa l'Empty Dreadmist Peak Sampler per prelevare un campione d'acqua da una pozza in cima al picco.\n\nConsegna il Filled Dreadmist Peak Sampler a Tonga Runetotem, al Crossroads, nelle Barrens.", enHash = "589d73f9", vanilla = true },
        progress = { it = "Sei tu $Gquello:quella; che ha mandato il Cenarion Circle di Moonglade, vero? È una vera fortuna per noi! I nostri sforzi per ridare equilibrio alle gazzelle malate che vagano nelle Barrens del nord si sono arenati; siamo felici di ricevere tutto l'aiuto possibile.\n\nHai il campione d'acqua che Dendrite Starblaze ha detto che avresti portato? Mi ha avvisato che ne avresti prelevato uno, così potremo lavorare insieme a una cura...", enHash = "3cf0a35b", vanilla = true },
        reward = { it = "Per i miei antenati, quest'acqua è disgustosa! Non c'è da stupirsi che le gazzelle stiano male.\n\nQualcosa sta inquinando l'acqua, e a sua volta comincia a devastare l'ecosistema delle Barrens del nord. Si sono viste gazzelle malate in tutta la zona a nord della strada che qui corre da est a ovest. Anche se quest'acqua è molto probabilmente una delle fonti principali della malattia che si sta diffondendo, qui c'è in gioco qualcos'altro.\n\nChe tu ci creda o no, quest'acqua ci aiuterà a preparare una cura. Mentre la studio, mi servono alcuni oggetti per formulare la cura...", enHash = "a049e977", vanilla = true },
    },
    [6128] = {
        title = { it = "Gli ingredienti della cura", enHash = "e33bd86d", vanilla = true },
        text = { it = "L'acqua farà da base per l'unguento curativo che preparerò per le gazzelle. Per le proprietà curative mi serve un po' di Earthroot. Gli erboristi sanno come trovarla, quindi, se non conosci quest'abilità, dovrai trovarne uno che ci dia una mano.\n\nInfine, per la potenza, mi servono delle Kodo Horn — semplici schegge e frammenti non basteranno. Nella parte settentrionale delle Barrens vagano kodo alla tua portata; abbattine qualcuno per il bene superiore dell'equilibrio, $N, e portami le corna.", enHash = "f94ce0a6", vanilla = true },
        objectives = { it = "Porta 5 Earthroot e 5 Kodo Horn a Tonga Runetotem, al Crossroads, così che possa preparare un unguento curativo.", enHash = "c0c492c7", vanilla = true },
        progress = { it = "Hai i reagenti che mi servono per preparare l'unguento? Le gazzelle non migliorano da sole, quindi è meglio non indugiare se vogliamo salvarle!", enHash = "6670de06", vanilla = true },
        reward = { it = "È ottimo, $N, tanto che dovrebbe bastare per preparare parecchie dosi dell'unguento — almeno abbastanza da cominciare a fare la differenza.\n\nPreparare una cura contro i veleni a volte può essere piuttosto difficile, perché spesso ognuno richiede un antidoto molto specifico per contrastarlo. Immagina di poter curare un veleno a piacimento, senza doverti preoccupare di quali debbano essere esattamente gli ingredienti dell'antidoto!\n\nOra lascia che mi metta al lavoro!", enHash = "ae9f3080", vanilla = true },
    },
    [6129] = {
        title = { it = "Curare i malati", enHash = "62aed44b", vanilla = true },
        text = { it = "Sono riuscito a preparare abbastanza unguento per dieci dosi di cura, $N. Mentre lavoro con le autorità locali per cercare di prepararne ancora, vorrei che ci aiutassi a portarci avanti. In tutte le Barrens del nord ci sono gazzelle malate; usa l'unguento su di loro e guariscile dal loro male.\n\nDendrite Starblaze, a Moonglade, vorrà parlarti quando avrai finito, ne sono certo. Ti prego, porta al Cenarion Circle laggiù i nostri ringraziamenti... e lascia che ti ringrazi anche io direttamente per l'aiuto che ci hai dato!", enHash = "194b1d38", vanilla = true },
        objectives = { it = "Usa il Curative Animal Salve su 10 Sickly Gazelle che si trovano in tutta la parte settentrionale delle Barrens; così dovresti curarle. Sono state segnalate Sickly Gazelle a nord della strada che attraversa il Crossroads da est a ovest.", enHash = "6ddcfbd0", vanilla = true },
        progress = { it = "Hai portato a termine ciò che ti ha chiesto Tonga Runetotem, al Crossroads? Il tuo lavoro non è completo finché non l'avrai fatto.", enHash = "33a477df", vanilla = true },
        reward = { it = "Hai fatto bene a prenderti cura delle gazzelle malate delle Barrens; sono vittime inconsapevoli di una corruzione, di un male più grande che si sta diffondendo in tutta la terra. Voi tauren siete molto desiderosi di comprendere le vie di Cenarius; tu, come i tuoi anziani a Thunder Bluff, stai dimostrando che il bisogno di equilibrio supera le barriere artificiali tra le razze.\n\n$N, hai dimostrato il tuo valore come $Gamico:amica; della natura e del Circle — prendi questo come simbolo.", enHash = "e57b9b9c", vanilla = true },
    },
    [6130] = {
        title = { it = "Potere sui veleni", enHash = "731a1939", vanilla = true },
        text = { it = "Hai imparato cosa significa curare un veleno senza poter contare su un aiuto spirituale. Ricorda quello che gli altri devono sopportare quando combattono gli avvelenamenti, ora che stai per fare tuo il nuovo potere sui veleni.\n\nOra dovresti tornare da Turak Runetotem, a Thunder Bluff, $N. Senza dubbio ha un incantesimo molto importante da insegnarti, ora che $Gl'allievo:l'allieva; ha compreso la lezione che $Ggli:le; è stata impartita.\n\nArrivederci, giovane $Gdruido:druida;. Parleremo ancora.", enHash = { "d8eb2e56", "a258596d" }, vanilla = true },
        objectives = { it = "Torna da Turak Runetotem, sull'Elder Rise, a Thunder Bluff.", enHash = "2eaa0eaf", vanilla = true },
        reward = { it = "$GBentornato:Bentornata; — ho seguito i tuoi progressi in questa lezione da quando sei $Gpartito:partita;, e devo ammettere che la situazione del Crossroads mi ha sorpreso. La faccenda merita altre indagini, perché l'arrivo di veleni come questi nell'ambiente turba moltissimo l'equilibrio.\n\nSotto pressione hai mantenuto calma e compostezza. Per questo non trovo modo migliore di ricompensarti che con un potere permanente sui veleni. Usalo bene, $N... usalo bene.", enHash = "e612ca33", vanilla = true },
    },
    [6132] = {
        title = { it = "Tirami fuori di qui!", enHash = "32e153f8", vanilla = true },
        text = { it = "Tirami fuori di qui!\n\nSono salita fino alla Valley of Spears per parlare con i Maraudine. Pensavo di poter fare qualche affare con loro... ma non vogliono parlare! Credo che vogliano mangiarmi!\n\nTirami fuori di qui e mio fratello Hornizz ti pagherà profumatamente! È al nostro accampamento vicino al Kodo Graveyard, a est.\n\nSbrighiamoci, $N. Nemmeno due minuti fa ho sentito dei centauri che parlavano di prendere legna per il loro pentolone...", enHash = "b6b9516f", vanilla = true },
        objectives = { it = "Scorta Melizza Brimbuzzle, poi parla con Hornizz Brimbuzzle al Kodo Graveyard, a Desolace.", enHash = "3a895726", vanilla = true },
        progress = { it = "Hai visto mia sorella Melizza? È sempre in giro, e per questo si mette continuamente nei guai.", enHash = "86a8739d", vanilla = true },
        reward = { it = "Mia sorella Melizza ha detto che saresti $Garrivato:arrivata;. Grazie mille per averla tirata fuori dal pasticcio in cui si trovava; peccato che probabilmente si sia già cacciata in uno nuovo!", enHash = "6f3c139d", vanilla = true },
    },
    [6134] = {
        title = { it = "Raccolta di Ghost-o-plasm", enHash = "b399c30a", vanilla = true },
        text = { it = "C'è una valle a sud-est, la Valley of Bones, infestata dai fantasmi dei Magram. Fa paura, vero? Be', pensa quanta paura fa ai Magram! Se catturassimo l'energia dei fantasmi di quel posto, scommetto che per quei centauri varrebbe parecchio.\n\nTieni, prendi questa Crate of Ghost Magnets. Se metti uno dei magneti tra i due grandi scheletri della valle, i Dead Goliath, i fantasmi si avvicineranno vagando. Allontanati, fai fuori i fantasmi e prendi il loro Ghost-o-plasm — è quello che venderemo ai Magram.", enHash = "b1a611d1", vanilla = true },
        objectives = { it = "Porta 8 Ghost-o-plasm e la Crate of Ghost Magnets a Hornizz Brimbuzzle, a Desolace.", enHash = "78886d62", vanilla = true },
        progress = { it = "Dov'è il mio Ghost-o-plasm, $N?", enHash = "cf864ca5", vanilla = true },
        reward = { it = "Eccolo! Sembra che un po' sia finito anche addosso a te. Un po' viscido, eh?\n\nBe', grazie mille per il disturbo, $N. Questa roba varrà una fortuna... se riesco a convincere i centauri di cosa si tratta!", enHash = "8b6049ff", vanilla = true },
    },
    [6141] = {
        title = { it = "Brother Anton", enHash = "fe04d2a6", vanilla = true },
        text = { it = "Il mio fratello d'armi, Brother Anton, ha sentito voci di un'infestazione di non morti nella lontana Kalimdor, in una terra chiamata Desolace. Anton ha subito prenotato un passaggio per quel luogo, per scovare e distruggere la minaccia dei non morti!\n\nCerca persone con il coraggio e la determinazione per aiutarlo. Se il tuo cuore è sincero, parla con Anton. Si trova a Desolace, nella cittadina dell'Alleanza di Nijel's Point.", enHash = "8cbdccb2", vanilla = true },
        objectives = { it = "Parla con Brother Anton, a Desolace.", enHash = "f8ff2f45", vanilla = true },
        reward = { it = "Mi è giunta notizia di aiuti in arrivo da est. Sei tu l'origine di queste voci? Sei $Gvenuto:venuta; qui per aiutare lo Scarlet Brother nella sua crociata?\n\nSe è così, allora ascolta bene...", enHash = "b2b7107b", vanilla = true },
    },
    [6142] = {
        title = { it = "Esca di vongole", enHash = "f0a38095", vanilla = true },
        text = { it = "Hai l'aria $Gdi un pescatore:di una pescatrice;, $C! Adoro pescare — pesco da tutta la vita. L'esca migliore da usare è la Soft-shelled Clam Meat; i pesci proprio non resistono, capisci cosa intendo?\n\nA nord troverai una nave naufragata al largo della costa. Le vongole dal guscio molle sono sparse per tutta la zona. Se mi riporti 10 pezzi di Soft-shelled Clam Meat, ti darò qualcosa in cambio.", enHash = "5046a913", vanilla = true },
        objectives = { it = "Trova 10 pezzi di Soft-shelled Clam Meat e riportali a Mai'Lahii, a Shadowprey Village.", enHash = "89eff6d2", vanilla = true },
        progress = { it = "Non vedo l'ora di andare a pescare con un po' di Soft-shelled Clam Meat fresca; mi hai portato i 10 pezzi che mi servono?", enHash = "c26c570a", vanilla = true },
        reward = { it = "Perfetto, $Gamico:amica;, è proprio quello che lo stregone mi ha detto di fare per il mal di testa. Dice: \"Mai'Lahii — va' a pescare. Ti farà sentire meglio.\"\n\nBe', mi sento già meglio, grazie, $Gamico:amica;!", enHash = "f1ae8d9c", vanilla = true },
    },
    [6143] = {
        title = { it = "Altre gatte da pelare", enHash = "b64da3c0", vanilla = true },
        text = { it = "Forse l'hai saputo o forse no... io e il mio equipaggio eravamo a pescare vicino alla Ranazjar Isle, a nord della nave naufragata al largo della costa, lassù a nord. Pescavamo lì di continuo; ora non faccio che pensare a un modo per vendicare i miei compagni caduti.\n\nUna mattina i naga ci hanno attaccati, uccidendo tutti tranne me.\n\nLa mia coscienza non regge il senso di colpa, $C; ho bisogno che tu vada a far fuori quei naga per me. Farò in modo che ne valga la pena; pensi di potermi aiutare?", enHash = "7ef86f42", vanilla = true },
        objectives = { it = "Uccidi 7 Slitherblade Myrmidon, 7 Slitherblade Naga e 5 Slitherblade Sorceress, poi parla con Drulzegar a Shadowprey, a Desolace.", enHash = "222eaf5c", vanilla = true },
        progress = { it = "Sento ancora le loro voci che gridavano aiuto quando i naga hanno scatenato il caos su di noi. Se non avessi questo ginocchio malandato, verrei ad aiutarti a uccidere quei maledetti naga!\n\nDi solito puoi star $Gcerto:certa; di trovarli nelle profondità delle barriere coralline, sotto la superficie... in agguato... a tramare...", enHash = "f3b2a287", vanilla = true },
        reward = { it = "Per quanto sia dolce sentire che i naga sono stati sconfitti, il mio cuore si sente ancora vuoto. Per il resto della mia vita mi dedicherò a farli uccidere tutti.\n\nEcco, $Gamico:amica;, la tua ricompensa, come ti avevo promesso. È poca cosa in confronto alla soddisfazione di sapere che i naga sono stati fatti fuori per l'odioso gesto contro il mio equipaggio.", enHash = "6f9463fc", vanilla = true },
    },
    [6161] = {
        title = { it = "Reclama il tesoro di Rackmore!", enHash = "53523b6e", vanilla = true },
        text = { it = "Il diario di bordo di Rackmore racconta che la sua nave era diretta a Feathermoon Stronghold quando fu attaccata da creature marine. Per evitare che il suo tesoro cadesse in mani nemiche, nascose la sua cassa sulla Ranazjar Isle.\n\nPer aprire la cassa servono due chiavi, una d'argento e una d'oro. Le chiavi sono andate perdute, ma se si trovano le chiavi e la cassa, un tesoro attende!", enHash = "d99abe96", vanilla = true },
        objectives = { it = "Trova Rackmore's Silver Key. Trova Rackmore's Golden Key. Trova e apri Rackmore's Chest.", enHash = "cde7c1cb", vanilla = true },
        progress = { it = "Questa cassa è chiusa a chiave saldamente.", enHash = "f2e6cb1d", vanilla = true },
        reward = { it = "La cassa si apre e rivela il tesoro di Rackmore!", enHash = "081391ae", vanilla = true },
    },
    [6181] = {
        title = { it = "Un messaggio veloce", enHash = "cb6f8d7b", vanilla = true },
        text = { it = "Anche se da Stormwind non ci arriva molto aiuto diretto, ho un contatto in città che ci aiuta a rifornirci di armature. Si chiama Osric Strang. La sua bottega, Limited Immunity, è nell'Old Town di Stormwind.\n\nLe nostre scorte di armature si assottigliano, e devo contattare Osric per averne altre. Puoi portargli questo biglietto?\n\nIl modo più rapido per arrivare a Stormwind è passare da Thor, il nostro maestro dei grifoni. È appena giù per la collina: portagli il mio biglietto e poi prendi un grifone per Stormwind.", enHash = "3b394ea6", vanilla = true },
        objectives = { it = "Porta Lewis' Note a Thor, il maestro dei grifoni.", enHash = "f1000da3", vanilla = true },
        progress = { it = "Hai l'aria di avere fretta. Be', allora sei $Gcapitato:capitata; nel posto giusto!", enHash = "17c0e44a", vanilla = true },
        reward = { it = "Devi portare questo biglietto a Stormwind? Non è un problema, puoi prendere uno dei miei grifoni!", enHash = "5ab5fb2f", vanilla = true },
    },
    [6182] = {
        title = { it = "Il primo e l'ultimo", enHash = "a3c5dc8d", vanilla = true },
        text = { it = "Nathanos Marris fu il primo e l'ultimo dei signori dei ranger umani. Un discepolo di Sylvanas Windrunner, ora Regina Banshee dei Reietti.\n\nPensavamo che Nathanos fosse caduto in battaglia nella difesa di Lordaeron, cinque anni fa. Anche se il suo corpo non fu mai ritrovato, si dava per scontato che non fosse uscito vivo dalle Eastern Plaguelands.\n\nMathias Shaw sta indagando sulla sua scomparsa e potrebbe avere informazioni nuove. Presentati subito da lui. Si trova nell'Old Town, alle Barracks.", enHash = "45fdedd2", vanilla = true },
        objectives = { it = "Parla con Mathias Shaw nell'Old Town di Stormwind. Si trova alle Barracks.", enHash = "48d5f828", vanilla = true },
        reward = { it = "Dopo alcune segnalazioni di strane attività dei Reietti nelle Eastern Plaguelands, abbiamo mandato degli agenti del SI:7 a indagare. I risultati di quell'indagine sono inquietanti.", enHash = "192fc738", vanilla = true },
    },
    [6183] = {
        title = { it = "Onorare i caduti", enHash = "998655a9", vanilla = true },
        text = { it = "Cinque dei miei migliori agenti sul campo sono stati assegnati al caso Marris. Uno è tornato, ma è morto nel sonno tre giorni dopo.\n\nLe poche informazioni che siamo riusciti a cavargli erano farneticazioni incoerenti. Abbiamo capito solo due parole: \"Nathanos\" e \"Blightcaller\".\n\nNon ho uomini a disposizione per continuare l'indagine, e Ravenholdt non ci aiuterà. Dobbiamo andare fino in fondo, se non altro per dare pace alle famiglie dei caduti. Mi aiuterai?", enHash = "a30d227e", vanilla = true },
        objectives = { it = "Parla di nuovo con Mathias Shaw se vuoi accettare il suo incarico.", enHash = "aa87ee97", vanilla = true },
        reward = { it = "<Mathias annuisce.>\n\nAvevo fiducia che Bolvar mi avrebbe mandato uomini e donne d'onore: i soldati più devoti dell'Alleanza.", enHash = "889eccdf", vanilla = true },
    },
    [6186] = {
        title = { it = "Arriva il Blightcaller", enHash = "9ee31f0a", vanilla = true },
        text = { it = "<Il volto di Flint sembra essersi svuotato di ogni goccia di sangue.>\n\nNa... Nathanos ha fatto questo? Nathanos è il Blightcaller?\n\nPerché? Era... era così nobile: un signore dei ranger rispettato da tutti. L'unico umano a cui sia mai stato permesso di addestrarsi presso gli alti elfi. E ora è uno spietato agente dei Reietti?\n\nIo... mi dispiace chiedertelo, $N, ma Highlord Fordragon deve essere informato subito di questa svolta. Ti prego, torna a Stormwind e porta la notizia.", enHash = "80db92cd", vanilla = true },
        objectives = { it = "Torna a Stormwind e informa Highlord Bolvar Fordragon della sorte di Nathanos Marris.", enHash = "4e93fe98", vanilla = true },
        reward = { it = "No. Non... NO! Com'è possibile? Un agente dei Reietti? Il CAMPIONE della Regina Banshee???\n\n<Highlord Bolvar Fordragon si accascia, sconfitto.>", enHash = "20defe37", vanilla = true },
    },
    [6261] = {
        title = { it = "Dungar Longdrink", enHash = "fb846177", vanilla = true },
        text = { it = "$N, ho raccolto in questa cassa tutto ciò che Lewis ha chiesto. Puoi portargliela?\n\nSe hai già parlato con Thor in Westfall, allora puoi tornare da lui in grifone. Dungar Longdrink è il nostro maestro dei grifoni, là nel Trade District.\n\nParla con Dungar, poi porta questa cassa a Lewis il più in fretta possibile. Non vogliamo che i nostri uomini e le nostre donne che combattono in Westfall restino senza equipaggiamento nuovo!", enHash = "4db6b59e", vanilla = true },
        objectives = { it = "Porta Osric's Crate a Dungar Longdrink, il maestro dei grifoni.", enHash = "8cbce2a7", vanilla = true },
        progress = { it = "È sudore quello sulla fronte, $Gragazzo:ragazza;? Hai corso troppo. La prossima volta prendi un grifone!", enHash = { "6924db18", "330e87c8" }, vanilla = true },
        reward = { it = "Una cassa per Westfall, eh? Sei già $Gstato:stata; in Westfall? Se sì, non è un problema, $Gamico mio:amica mia;. Ho un sacco di grifoni addestrati su quella rotta!", enHash = "8aa071f6", vanilla = true },
    },
    [6281] = {
        title = { it = "Prosegui per Stormwind", enHash = "ba564be5", vanilla = true },
        text = { it = "Per una piccola cifra puoi prendere un grifone per Stormwind, così potrai consegnare il biglietto di Lewis a Osric. Non ci arriverai più in fretta in nessun altro modo.\n\nSe ti sembra accettabile, riparlami quando sei $Gpronto:pronta; per il volo. Ti farò pagare un po', ma credimi: ne varrà la pena!", enHash = "5519578a", vanilla = true },
        objectives = { it = "Compra un passaggio in grifone dal maestro dei grifoni Thor, poi porta Lewis' Note a Osric Strang, nella bottega Limited Immunity, nell'Old Town di Stormwind.", enHash = "d6ff3bfc", vanilla = true },
        progress = { it = "Hai viaggiato, eh? Sei $Gstato:stata; in qualche posto interessante?", enHash = "168666a6", vanilla = true },
        reward = { it = "Ah, un biglietto da Quartermaster Lewis? Non mi sorprende che gli serva altro equipaggiamento. Sentinel Hill è lontana, in una terra che Stormwind ha quasi dimenticato.\n\nBe', grazie, $N. Ecco un po' di denaro per coprire le tue spese di viaggio.", enHash = "ff5c6962", vanilla = true },
    },
    [6282] = {
        title = { it = "La minaccia delle arpie", enHash = "20f50de3", vanilla = true },
        text = { it = "I tauren sono fieri di essere i protettori di queste terre. Senza dubbio puoi immaginare perché sono allarmato dal numero di arpie che vivono qui a Stonetalon.\n\nLe Bloodfury sono la fonte del numero crescente di arpie in Kalimdor; invadono ogni genere di vita e impediscono agli innocenti di uscire dai loro confini.\n\nHo bisogno che tu decimi le arpie, $N!", enHash = "9675e7d6", vanilla = true },
        objectives = { it = "Maggran Earthbinder, a Sun Rock Retreat, vuole che tu uccida 7 Bloodfury Harpy, 7 Bloodfury Ambusher, 7 Bloodfury Slayer e 7 Bloodfury Roguefeather.", enHash = "e28ff44a", vanilla = true },
        progress = { it = "Sta' $Gattento:attenta; nella Charred Vale: in quelle colline vivono molte creature malvagie. Resta forte, $N, e avrai la meglio su questa minaccia al nostro popolo. Va' adesso e colpisci duro — i nostri figli non sapranno mai del male che è stato.", enHash = "b735701b", vanilla = true },
        reward = { it = "Questa sì che è una notizia eccellente! Raccontami di nuovo come hai gettato il terrore nei cuori gelidi di quelle arpie immonde. Le Bloodfury hanno subito un colpo durissimo!", enHash = "8c7df04d", vanilla = true },
    },
    [6283] = {
        title = { it = "La stirpe delle Bloodfury", enHash = "2926451e", vanilla = true },
        text = { it = "Limitare il numero delle Bloodfury Harpy non basterà. L'unica vera cura per la loro malattia sarebbe uccidere la loro condottiera, Bloodfury Ripper!\n\nPer quelle creature immonde è a tutti gli effetti una regina. Uccidila e il loro numero calerà di sicuro.\n\nTorna nella Charred Vale e la troverai lungo le colline occidentali. Non sarà facile da sconfiggere, ma la ricompensa sarà grande.", enHash = "ce35abe0", vanilla = true },
        objectives = { it = "Maggran, a Sun Rock Retreat, vuole che tu uccida Bloodfury Ripper e porti i suoi resti come prova dell'impresa.", enHash = "c0cb7359", vanilla = true },
        progress = { it = "Bloodfury Ripper è una creatura perfida! Riuscirai a trovarla lungo la linea di colline occidentale, nella Charred Vale.\n\nLe Bloodfury saranno indifese senza... di sicuro potremo sconfiggerle per sempre!", enHash = "0c034661", vanilla = true },
        reward = { it = "Sento già la rabbia lasciarmi. Cosa farò del mio tempo? Sapere che il male si muoveva vicino alla mia terra teneva in movimento i miei pensieri, e ora invece tacciono. Forse è una cosa buona... forse ora posso concentrarmi sul bene, come dovrebbero fare tutti i tauren.\n\nTi prego, accetta questo come ricompensa per il tuo disturbo.", enHash = "33b58a47", vanilla = true },
    },
    [6284] = {
        title = { it = "Aracnofobia", enHash = "433dead9", vanilla = true },
        text = { it = "Attenzione: chi si addentra nel Sishir Canyon a ovest di qui lo fa a proprio rischio.\n\nBesseleth e i suoi figli a otto zampe della foresta hanno eletto questo canyon a loro tana di ragnatele.\n\nMaggran Earthbinder, al Sun Rock Retreat, ha messo una taglia su Besseleth. Uccidila e porta la prova della tua uccisione a Maggran; là riceverai la ricompensa per aver eliminato questa minaccia a otto zampe.", enHash = "ad2f0bdb", vanilla = true },
        objectives = { it = "Uccidi Besseleth e porta Besseleth's Fang a Maggran, al Sun Rock Retreat.", enHash = "283e91fe", vanilla = true },
        progress = { it = "Besseleth è una predatrice spietata... Temo per chi percorre il Webwinder Path di notte. È allora che lei e i suoi figli fanno preda di viaggiatori innocenti. Io stesso sono caduto preda della sua zanna di morte lunga due piedi, ma per fortuna sono riuscito a respingerla e a mettermi in salvo. Darei qualsiasi cosa per vedere quel mostro distrutto.", enHash = "d72c55e5", vanilla = true },
        reward = { it = "Buona caccia, $N! Besseleth è una vecchia predatrice da queste parti... non mi mancherà. Prendi questa ricompensa come riconoscimento per essere $Gil campione:la campionessa; della foresta.\n\n<Maggran si sfrega la ferita causata da Besseleth.>\n\nForse ora molti di più viaggeranno verso il Sun Rock Retreat senza temere ciò che si annida nel buio.", enHash = "2a2b4a50", vanilla = true },
    },
    [6285] = {
        title = { it = "Torna da Lewis", enHash = "c45232d3", vanilla = true },
        text = { it = "Il maestro dei grifoni in Westfall è Thor. Se gli hai già parlato, puoi prendere uno dei miei grifoni e andare da lui.\n\nÈ una buona cosa da sapere: i grifoni sono sempre addestrati a volare verso la loro capitale, ma ti portano da un maestro dei grifoni lontano solo dopo che ci sei già $Gstato:stata;.\n\nSei già $Gandato:andata; da Thor, quindi riparlami quando sei $Gpronto:pronta; a prendere un grifone per Westfall. Una volta là, potrai consegnare Osric's Crate a Quartermaster Lewis.", enHash = "bbf81641", vanilla = true },
        objectives = { it = "Compra un passaggio in grifone per Sentinel Hill dal maestro dei grifoni Dungar Longdrink, poi porta Osric's Crate a Lewis, a Sentinel Hill.", enHash = "ab22a95d", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata; da Stormwind? Osric ha mandato le armature?", enHash = "4abfd4de", vanilla = true },
        reward = { it = "Ottimo, hai portato le armature! Le distribuiremo subito a chi ne ha bisogno.\n\nGrazie, $N. Il tuo impegno ci è stato di grande aiuto. E ora che i grifoni non ti sono più estranei, spero che verrai spesso a dare una mano a Sentinel Hill!", enHash = "82ab16ac", vanilla = true },
    },
    [6301] = {
        title = { it = "Il ciclo della rinascita", enHash = "8d8e849d", vanilla = true },
        text = { it = "L'avidità industriale e la guerra continua hanno devastato le terre di Stonetalon. Solo le benedizioni della Madre Terra possono curare una ferita simile.\n\n$N, ti chiederò di cercare un seme speciale, il Gaea Seed. Si trovano solo qui nella Stonetalon Mountain, a nord del Sun Rock Retreat, al Mirkfallon Lake, vicino alla riva.\n\nQuando mi porterai i semi, li impregnerò di potere sciamanico per accelerarne la crescita.", enHash = "57832fc3", vanilla = true },
        objectives = { it = "Tammra Windfield, al Sun Rock Retreat, vuole che tu raccolga 10 Gaea Seed.", enHash = "349771b8", vanilla = true },
        progress = { it = "La distruzione continua causata dalla guerra e da chi cerca profitto nel legname mi addolora profondamente. Per aiutare il ciclo della rinascita e ripopolare queste terre mi servono i Gaea Seed. Ce li hai, $C?", enHash = "762007e5", vanilla = true },
        reward = { it = "Ah, $N, hai i Gaea Seed. Guarda e vedi come la benedizione della Madre Terra può far sbocciare e prosperare persino questi piccoli semi di vita.\n\n<Tammra comincia a cantilenare.>", enHash = "3f438c65", vanilla = true },
    },
    [6321] = {
        title = { it = "Rifornire il Sepulcher", enHash = "bf57930b", vanilla = true },
        text = { it = "Executor Hadrec mi ha chiesto di fare l'inventario del nostro equipaggiamento al Sepulcher. Con il Flagello, e di peggio, in agguato nei boschi, non vuole che ai Guardiamorte manchi l'attrezzatura che potrebbe servire.\n\nHo trovato che in generale siamo ben forniti, ma ci servono altre armi per sostituire quelle perdute sul campo.\n\nEcco un ordine di fornitura con ciò che serve, per il mercante d'armi Gordon Wendham nell'Undercity. Porta l'ordine al nostro maestro dei pipistrelli, Karos Razok, e parlagli di un passaggio per l'Undercity.", enHash = "a95053b9", vanilla = true },
        objectives = { it = "Porta Podrig's Order a Karos Razok.", enHash = "fa5b25df", vanilla = true },
        progress = { it = "Sembri essere in missione ufficiale...", enHash = "3aee7298", vanilla = true },
        reward = { it = "Ah, un ordine di rifornimenti. Vorrai portarlo nell'Undercity, senza dubbio. E in fretta, perché il Sepulcher non deve restare senza scorte.", enHash = "36f7c880", vanilla = true },
    },
    [6322] = {
        title = { it = "Michael Garrett", enHash = "8c842dd2", vanilla = true },
        text = { it = "Ho messo in questa cassa i rifornimenti per il Sepulcher. Se hai già visitato il Sepulcher e parlato con il loro maestro dei pipistrelli, puoi tornare da lui in pipistrello.\n\nParla con il maestro dei pipistrelli dell'Undercity, Michael Garrett. Può darti un pipistrello per il Sepulcher.", enHash = "9adae00a", vanilla = true },
        objectives = { it = "Porta Gordon's Crate a Michael Garrett.", enHash = "62d12417", vanilla = true },
        progress = { it = "Se devi percorrere una lunga distanza, un pipistrello è la scelta migliore.", enHash = "431bb946", vanilla = true },
        reward = { it = "Questa cassa deve arrivare al Sepulcher, in Silverpine? È presto fatto: i nostri pipistrelli ci volano ogni giorno.", enHash = "cd7ea955", vanilla = true },
    },
    [6323] = {
        title = { it = "Passaggio per l'Undercity", enHash = "3c83b097", vanilla = true },
        text = { it = "Uno dei miei pipistrelli può portarti nell'Undercity, per una piccola cifra. Parlami di nuovo quando sei $Gpronto:pronta;, così sistemiamo il tuo trasporto.\n\nGordon Wendham lo trovi nel Trade Quarter dell'Undercity. È lo stesso quartiere in cui atterrerà il mio pipistrello.", enHash = "669d8f6c", vanilla = true },
        objectives = { it = "Compra un passaggio in pipistrello per l'Undercity dal maestro dei pipistrelli Karos Razok, poi porta Podrig's Order a Gordon Wendham, nell'Undercity.", enHash = "8eda0fbe", vanilla = true },
        progress = { it = "Tengo le mie armi in condizioni perfette. Sono pulite e pronte all'uso.", enHash = "1cd450c0", vanilla = true },
        reward = { it = "Un ordine dal Sepulcher? Molto bene. È un onore servire chi serve la nostra Signora Oscura.", enHash = "d8d91130", vanilla = true },
    },
    [6324] = {
        title = { it = "Torna da Podrig", enHash = "cd4bf300", vanilla = true },
        text = { it = "Il maestro dei pipistrelli al Sepulcher è Karos Razok. Se l'hai già incontrato, posso darti un pipistrello per tornare da lui.\n\nI nostri pipistrelli volano sempre verso l'Undercity, ma per viaggiare verso luoghi più remoti chi li cavalca deve prima aver visitato la zona e parlato con il suo maestro dei pipistrelli.\n\nHai incontrato Karos al Sepulcher, quindi ora puoi volarci. Parlami di nuovo quando sei $Gpronto:pronta;.", enHash = "67a29e63", vanilla = true },
        objectives = { it = "Compra un passaggio in pipistrello per il Sepulcher dal maestro dei pipistrelli Michael Garrett, poi porta Gordon's Crate a Deathguard Podrig, al Sepulcher.", enHash = "e60cd2bc", vanilla = true },
        progress = { it = "$N, sei $Gtornato:tornata;. Hai i nostri rifornimenti dall'Undercity?", enHash = "c2d9c483", vanilla = true },
        reward = { it = "Bel lavoro, $N. Queste armi faranno in modo che i nostri Guardiamorte non vengano colti impreparati.\n\nHai reso un servizio prezioso alla nostra Signora Oscura.", enHash = "2dc2b1e6", vanilla = true },
    },
    [6341] = {
        title = { it = "L'abbondanza di Teldrassil", enHash = "cb3a069e", vanilla = true },
        text = { it = "I pescatori di Rut'theran Village se la cavano benissimo, perché qui i pesci sono enormi e abbondanti. Vorrei confrontare l'abbondanza di qui con quella della terraferma.\n\nHo una raccolta di lische e squame che vorrei far arrivare a un mio collega, a Darkshore. Si chiama Laird ed è un venditore di pesce nel villaggio di Auberdine.\n\nPorta la mia raccolta al nostro maestro degli ippogrifi, Vesprystus, e parlagli di un viaggio per Auberdine.", enHash = "c33e87c3", vanilla = true },
        objectives = { it = "Porta Nessa's Collection a Vesprystus.", enHash = "3f09af21", vanilla = true },
        progress = { it = "Come posso aiutarti? Ti serve un passaggio?", enHash = "20d988c6", vanilla = true },
        reward = { it = "Ah, vuoi far arrivare questo ad Auberdine? Molto bene...", enHash = "c6f5d713", vanilla = true },
    },
    [6342] = {
        title = { it = "Volo per Auberdine", enHash = "906dd1a2", vanilla = true },
        text = { it = "Da Rut'theran ci sono due modi per arrivare ad Auberdine: il traghetto e l'ippogrifo. Sono entrambi rapidi e affidabili, ma se non sei ancora $Gvolato:volata; ad Auberdine in ippogrifo, ti consiglio di farlo.\n\nÈ buona regola parlare con il maestro degli ippogrifi in ogni città che ne ha uno. Una volta parlato con il maestro, potrai volare lì anche dalle altre città.\n\nEcco la raccolta di Nessa. Parlami di nuovo quando sei $Gpronto:pronta; a volare ad Auberdine e a consegnare la raccolta di Nessa a Laird.", enHash = "a14908ec", vanilla = true },
        objectives = { it = "Prendi un ippogrifo per Auberdine dal maestro degli ippogrifi Vesprystus, poi porta Nessa's Collection a Laird.", enHash = "7b9d8972", vanilla = true },
        progress = { it = "Vieni da Teldrassil? Dimmi, come si pesca laggiù?", enHash = "766b439c", vanilla = true },
        reward = { it = "Un pacco da Nessa? Grazie, $N! Mi aveva detto che mi avrebbe mandato campioni dei pesci presi vicino a Rut'theran Village. Pensa che possano essere molto diversi da quelli che si pescano qui...\n\nPerbacco! Questa mascella è quasi il doppio di quella dello stesso pesce qui da noi. E queste squame sono grandi come un pugno chiuso! Incredibile!", enHash = "ea3e01eb", vanilla = true },
    },
    [6343] = {
        title = { it = "Torna da Nessa", enHash = "c46e53f5", vanilla = true },
        text = { it = "Devo mandare una risposta a Nessa. Le interesserà molto sapere quanto i pesci di qui siano diversi da quelli lungo la costa di Teldrassil. Sulla causa possiamo solo fare congetture, ma il mio sospetto è che sia l'albero del mondo stesso a influenzare la fauna intorno a sé!\n\nTi prego, porta questa risposta a Nessa. Se vuoi tornare a Rut'theran in ippogrifo, parla con la maestra degli ippogrifi Caylais Moonfeather. Se preferisci il traghetto, ne parte uno regolarmente dal molo a nord-ovest.", enHash = "fcdbfed3", vanilla = true },
        objectives = { it = "Porta Laird's Response a Nessa Shadowsong.", enHash = "0833f541", vanilla = true },
        progress = { it = "$N, sei $Gtornato:tornata; da Auberdine? Hai parlato con Laird?", enHash = "b5721037", vanilla = true },
        reward = { it = "Molto interessante. I pesci qui sono grossi, ma non pensavo che la differenza con la terraferma fosse tanta. Ci dev'essere un motivo...\n\nBe', grazie, $N. Parlerò con gli abitanti del villaggio delle notizie che hai portato. Forse un giorno troveremo la radice di questa stranezza. Ma fino ad allora ne godremo i frutti!", enHash = "ec5e3ed8", vanilla = true },
    },
    [6344] = {
        title = { it = "Nessa Shadowsong", enHash = "45da9f2b", vanilla = true },
        text = { it = "Una mia amica, Nessa Shadowsong, è una mercante di pesce a Rut'theran Village. Deve far portare un pacco a Darkshore e cerca qualcuno che l'aiuti.\n\nSe ti interessa, per raggiungere Nessa devi prendere il portale di Darnassus per Rut'theran Village. Troverai il portale a ovest dei Temple Gardens.", enHash = "c210e25b", vanilla = true },
        objectives = { it = "Parla con Nessa Shadowsong.", enHash = "ea6b5197", vanilla = true },
        reward = { it = "Sì, mi serve un corriere che porti un pacco a Darkshore. Mi aiuti?", enHash = "1c0cddb8", vanilla = true },
    },
    [6361] = {
        title = { it = "Un fascio di pelli", enHash = "f58cec07", vanilla = true },
        text = { it = "Ho un fascio di pelli degli animali delle Barrens, e devo farlo arrivare a Thunder Bluff. Un collega laggiù, Ahanu, userà le pelli per farne articoli di cuoio.\n\nGliele porti tu per me?\n\nLa via più rapida per Thunder Bluff è in groppa a un wind rider. Porta il fascio di pelli a Devrak, il nostro maestro dei wind rider al Crossroads, e parlagli di un viaggio per Thunder Bluff.", enHash = "6e237e1a", vanilla = true },
        objectives = { it = "Porta il Bundle of Hides al maestro dei wind rider Devrak, al Crossroads.", enHash = "8182b80d", vanilla = true },
        progress = { it = "Sei qui per un wind rider? Hai qualcosa da trasportare?", enHash = "507d2282", vanilla = true },
        reward = { it = "Se devi portare queste pelli a Thunder Bluff, allora stai parlando con l'orco giusto!", enHash = "a0064aab", vanilla = true },
    },
    [6362] = {
        title = { it = "Passaggio per Thunder Bluff", enHash = "e7b50672", vanilla = true },
        text = { it = "Per una piccola cifra ti do un wind rider per Thunder Bluff. Non c'è modo più rapido di arrivare in città!\n\nSe ti va bene, parlami di nuovo quando sei $Gpronto:pronta; a partire.\n\nSe quelle pelli le porti ad Ahanu, credo che lo trovi all'Hewa's Armory, alla base della torre dei wind rider di Thunder Bluff. Ed è proprio lì che atterrerai!", enHash = "a1460f10", vanilla = true },
        objectives = { it = "Compra un wind rider per Thunder Bluff dal maestro dei wind rider Devrak, poi porta il Bundle of Hides ad Ahanu, a Thunder Bluff.", enHash = "ed211a21", vanilla = true },
        progress = { it = "Hai la polvere sulle spalle, e dev'essere quella delle Barrens. Hai parlato con il mio amico Jahan?", enHash = "2a95bf0c", vanilla = true },
        reward = { it = "Ah, un nuovo fascio di pelli. Mi ci metto subito al lavoro!\n\nGrazie, $Gfratello:sorella;. Mi hai reso un grande servizio. Ecco delle monete per ripagarti del tempo e delle spese di viaggio.", enHash = { "d8796972", "882dfac0" }, vanilla = true },
    },
    [6363] = {
        title = { it = "Tal, il maestro dei wind rider", enHash = "b9ea1830", vanilla = true },
        text = { it = "Ho preparato degli articoli di cuoio perché Jahan li venda al Crossroads. Glieli porti tu?\n\nSe sei già $Gstato:stata; al Crossroads e hai parlato con il loro maestro dei wind rider, puoi tornare da lui volando su uno dei nostri wind rider di Thunder Bluff.\n\nPorta gli articoli di cuoio a Tal, il nostro maestro dei wind rider a Thunder Bluff, e parlagli per organizzare il viaggio verso il Crossroads.", enHash = "6ebc0b29", vanilla = true },
        objectives = { it = "Porta Ahanu's Leather Goods a Tal, a Thunder Bluff.", enHash = "fc941df6", vanilla = true },
        progress = { it = "Salve, $C. Cosa posso fare per te?", enHash = "9669884a", vanilla = true },
        reward = { it = "Devi portare questo al Crossroads, eh? Nessun problema. Se ci sei già $Gstato:stata; e hai parlato con Devrak, puoi tornare da lui su uno dei miei wind rider.", enHash = "1458c692", vanilla = true },
    },
    [6364] = {
        title = { it = "Torna da Jahan", enHash = "c433f909", vanilla = true },
        text = { it = "Per volare in una città devi esserci già $Gstato:stata; e aver parlato con il maestro dei wind rider di quella città. Al Crossroads ci sei $Gstato:stata; e hai parlato con il loro maestro dei wind rider Devrak, quindi per una piccola cifra puoi prendere da qui un wind rider per andare da lui.\n\nParlami di nuovo quando sei $Gpronto:pronta;. Una volta al Crossroads, potrai consegnare gli articoli di cuoio a Jahan Hawkwing.", enHash = "064cc3e1", vanilla = true },
        objectives = { it = "Compra un wind rider per il Crossroads dal maestro dei wind rider Tal, poi porta Ahanu's Leather Goods a Jahan Hawkwing.", enHash = "54783f28", vanilla = true },
        progress = { it = "$N, sei $Gtornato:tornata; da Thunder Bluff? Hai consegnato le pelli ad Ahanu?", enHash = "77df1530", vanilla = true },
        reward = { it = "Ahanu mi ha mandato i prodotti finiti? Molto bene. Al Crossroads adesso ci sono molti cacciatori e avventurieri, e gli affari vanno bene. Sono sicuro che venderò presto questa roba.\n\nGrazie di tutto il tuo impegno, $N. Ti sono debitore.", enHash = "7895974d", vanilla = true },
    },
    [6365] = {
        title = { it = "Carni per Orgrimmar", enHash = "2dc34c1f", vanilla = true },
        text = { it = "Ho dei tagli di carne scelti che voglio mandare a un'amica. Si chiama Gryshka ed è la locandiera di Orgrimmar. La consegni tu la carne per me?\n\nLa via più rapida per Orgrimmar è su un wind rider. Porta le carni al maestro dei wind rider del Crossroads, Devrak, e parlagli di un viaggio per Orgrimmar.", enHash = "453c2761", vanilla = true },
        objectives = { it = "Porta Zargh's Meats a Devrak, al Crossroads.", enHash = "e11d8bd3", vanilla = true },
        progress = { it = "Devi arrivare in fretta da qualche parte? Allora stai parlando con l'orco giusto!", enHash = "cd0e3297", vanilla = true },
        reward = { it = "Devi portare questa carne a Orgrimmar? Nessun problema. Per una piccola cifra, il mio wind rider può portarti là.", enHash = "da6e1343", vanilla = true },
    },
    [6381] = {
        title = { it = "Vita nuova", enHash = "4e9cf97c", vanilla = true },
        text = { it = "Come hai visto, $C, anche se la terra soffre, il ciclo della vita è una cosa potente. Ora dobbiamo fare la nostra parte per aiutarlo. Devi piantare questi semi al centro della distruzione, a ovest, nella Charred Vale. Fa' attenzione, perché arpie ed elementali del fuoco infuriati infestano ancora la terra sfregiata.\n\n$N, prendi questi Enchanted Gaea Seed e piantali in cumuli di terra fertile. Il ciclo della vita deve continuare!", enHash = "046755d9", vanilla = true },
        objectives = { it = "Pianta 10 Gaea Seed nei Gaea Dirt Mound, poi riporta gli Enchanted Gaea Seed rimasti a Tammra, al Sun Rock Retreat.", enHash = "25491a05", vanilla = true },
        progress = { it = "Questi semi che pianti sono forti, resistono alla corruzione e aprono un varco ad altra vita. Cresceranno e cresceranno, dapprima impedendo la corruzione e risanando la terra sfregiata, e poi, un giorno, riportando Stonetalon a essere di nuovo una foresta rigogliosa.\n\nHai piantato tutti i Gaea Seed?", enHash = "1197b03e", vanilla = true },
        reward = { it = "Questa è una grande vittoria per la terra. Col tempo accadrà altro: la Venture Co. metterà via le sue seghe circolari e le sue asce, gli spiriti del fuoco infuriati si calmeranno e le arpie saranno respinte dalla terra stessa.\n\nSolo allora, $N, Stonetalon sarà davvero in pace.\n\nHai fatto bene, $C; prendi uno di questi oggetti come ringraziamento per la vita nuova che hai creato qui oggi.", enHash = "5ff9e555", vanilla = true },
    },
    [6382] = {
        title = { it = "La caccia di Ashenvale", enHash = "543bb59f", vanilla = true },
        text = { it = "La tua forza mi colpisce, $C. La tua voglia di abbracciare la caccia mi convince che potresti passare a prede più grandi... e a sfide più grandi.\n\nLe foreste di Ashenvale sono una vasta natura selvaggia e indomita su cui l'Orda vuole imporre la propria volontà, sul piano politico e su quello spirituale. Se vuoi metterti alla prova in una terra dove tutto è ancora da dimostrare, cerca la guida di Senani Thunderheart a Splintertree Post. L'avamposto è dritto a nord del sentiero che parte dalle Barrens.", enHash = "93387753", vanilla = true },
        objectives = { it = "Parla con Senani Thunderheart a Splintertree Post, ad Ashenvale.", enHash = "4a6d4371", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta; nella nuova frontiera, $N. Ashenvale è una terra di opportunità, dove $Gun giovane:una giovane; $C come te trova infinite occasioni per dimostrare il proprio valore. Guardati intorno qui all'avamposto, e va' anche allo Zoram Strand, perché l'Orda ha un altro avamposto anche là.\n\nLa tua presenza qui mi dice che sei $Gvenuto:venuta; a imparare di più sulla caccia. Ascolta bene, e ti dirò volentieri quello che ti serve sapere.", enHash = "5155084f", vanilla = true },
    },
    [6383] = {
        title = { it = "La Caccia di Ashenvale", enHash = "543bb59f", vanilla = true },
        reward = { it = "Ci sono tre creature leggendarie che compongono la Caccia di Ashenvale; puoi cercarle e metterti alla prova contro la loro astuzia e la loro potenza. Nel farlo, si spera, imparerai qualcosa su te $Gstesso:stessa;. Le creature sono: l'orso Ursangous, il felino nightsaber Shadumbra e l'ippogrifo Sharptalon.\n\nLe creature della Caccia di Ashenvale sono potenti, e potresti scoprire di aver bisogno di aiuto per abbatterle. Se riuscirai ad averne la meglio, portami la prova della tua impresa.", enHash = "c0da1fa8", vanilla = true },
    },
    [6384] = {
        title = { it = "Passaggio per Orgrimmar", enHash = "a8fd8f2f", vanilla = true },
        text = { it = "Per poche monete faccio in modo che un wind rider ti porti a Orgrimmar. Quando arrivi, potrai portare Zargh's Meats a Gryshka. La sua locanda è nella Valley of Strength, non lontano dalla Skytower, dove il mio wind rider ti lascerà.\n\nParlami di nuovo quando sei $Gpronto:pronta; per il viaggio.", enHash = "5650253f", vanilla = true },
        objectives = { it = "Compra un wind rider per Orgrimmar dal maestro dei wind rider Devrak, poi porta Zargh's Meats a Gryshka, a Orgrimmar.", enHash = "8175e836", vanilla = true },
        progress = { it = "Che buon profumo! Non è che hai della carne cruda addosso?", enHash = "bcaf7dfb", vanilla = true },
        reward = { it = "Oh, meraviglia! Questi sì che sono tagli buoni! Vengono da Zargh, vero? Quell'orco sa proprio come arrivare al cuore di una signora...\n\nOh, non vedo l'ora di cucinarla. Ma non troppo! La carne è meglio al sangue, non trovi?", enHash = "e427a31b", vanilla = true },
    },
    [6385] = {
        title = { it = "Doras, il maestro dei wind rider", enHash = "e9ca44ca", vanilla = true },
        text = { it = "Ho scritto una lettera di ringraziamento per Zargh. Gliela consegni tu? Se sei già $Gstato:stata; al Crossroads e hai parlato con il loro maestro dei wind rider, puoi tornarci in volo su un wind rider.\n\nPorta la mia lettera a Doras, il maestro dei wind rider di Orgrimmar, e parlagli di un viaggio per il Crossroads.", enHash = "d56970ab", vanilla = true },
        objectives = { it = "Porta Gryshka's Letter a Doras, a Orgrimmar.", enHash = "39c64ee2", vanilla = true },
        progress = { it = "Ti serve uno dei miei wind rider?", enHash = "dfd17a67", vanilla = true },
        reward = { it = "Devi portare questo al Crossroads, nelle Barrens? Sì, posso portarti là...", enHash = "816c4a1c", vanilla = true },
    },
    [6386] = {
        title = { it = "Torna al Crossroads.", enHash = "e14c7997", vanilla = true },
        text = { it = "I miei wind rider sono addestrati a volare in molti posti diversi, purché tu ci sia già $Gstato:stata; e abbia parlato con il maestro dei wind rider di quel posto.\n\nAl Crossroads ci sei $Gstato:stata; e hai parlato con il loro maestro dei wind rider Devrak, quindi da qui puoi volare dritto da lui. Una volta al Crossroads, potrai consegnare la lettera di Gryshka a Zargh.\n\nParlami quando sei $Gpronto:pronta; a partire.", enHash = "9be03b75", vanilla = true },
        objectives = { it = "Compra un wind rider per il Crossroads dal maestro dei wind rider Doras, poi porta Gryshka's Letter a Zargh, al Crossroads.", enHash = "7108b824", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata; da Orgrimmar? A Gryshka è piaciuta la carne che le ho mandato?", enHash = "5c8df6e5", vanilla = true },
        reward = { it = "Ah! Direi proprio di sì! Niente fa arrossire una signora come una bella bistecca succosa!\n\nGrazie, $N. Mi hai reso un grande servizio. Ecco del denaro per il disturbo, e non stupirti se ti invito al mio matrimonio!", enHash = "5bfa58a1", vanilla = true },
    },
    [6387] = {
        title = { it = "Studenti d'onore", enHash = "cb7c508e", vanilla = true },
        text = { it = "Vedo tanti giovani nani alla mia porta, ansiosi di imparare il mestiere del minatore. E se c'è una cosa di cui un minatore ha bisogno più di ogni altra, è un piccone!\n\nHo un elenco di studenti di estrazione mineraria che hanno ottenuto voti alti alle lezioni e si sono guadagnati un piccone d'onore. Porta il mio elenco a Golnir Bouldertoe, a Ironforge. Preparerà lui i picconi.\n\nIl modo più rapido per arrivare a Ironforge è il grifone, quindi porta l'elenco al nostro maestro dei grifoni, Thorgrum Borrelson, e parlagli di un passaggio per Ironforge.", enHash = "fd687d68", vanilla = true },
        objectives = { it = "Porta Brock's List a Thorgrum Borrelson, a Thelsamar.", enHash = "2a24326a", vanilla = true },
        progress = { it = "Ti sei già $Gstancato:stancata; di Thelsamar? Sei $Gpronto:pronta; a partire per un'altra città?", enHash = "d33ad7d2", vanilla = true },
        reward = { it = "Devi portare questo a Ironforge, eh? Per una piccola cifra posso metterti sulla groppa di uno dei miei grifoni, e ti porterà là. Che ne dici?", enHash = "4986c868", vanilla = true },
    },
    [6388] = {
        title = { it = "Gryth Thurden", enHash = "5d96a41e", vanilla = true },
        text = { it = "Ecco i picconi d'onore per gli studenti di Brock. Se sei già $Gstato:stata; a Thelsamar, allora puoi tornarci in grifone!\n\nPorta i picconi al nostro maestro dei grifoni, Gryth Thurden, e parlagli di un passaggio di ritorno per Thelsamar.", enHash = "6583de59", vanilla = true },
        objectives = { it = "Porta le Honorary Picks a Gryth Thurden, a Ironforge.", enHash = "ef2dc3b6", vanilla = true },
        progress = { it = "Hai l'aria di avere un posto dove andare. Ti serve uno dei miei grifoni?", enHash = "11ab0e5e", vanilla = true },
        reward = { it = "Devi portare questi a Thelsamar, eh? Non sarà un problema. Se sei già $Gstato:stata; a Thelsamar e hai parlato con Thorgrum Borrelson, puoi prendere uno dei miei grifoni e tornare da lui.", enHash = "356847ad", vanilla = true },
    },
    [6391] = {
        title = { it = "Passaggio per Ironforge", enHash = "cf982262", vanilla = true },
        text = { it = "Per pochi spiccioli, uno dei miei grifoni ti porterà a Ironforge. Da lì, consegna l'elenco di Brock a Golnir Bouldertoe. Lo trovi nella Deep Mountain Mining Guild. È nel Great Forge District di Ironforge, che è proprio dove ti lascerà il mio grifone!\n\nRiparlami quando sei $Gpronto:pronta; per il viaggio.", enHash = "01a1a286", vanilla = true },
        objectives = { it = "Compra un passaggio in grifone per Ironforge dal maestro dei grifoni Thorgrum Borrelson, poi porta Brock's List a Golnir Bouldertoe, a Ironforge.", enHash = "dd14ec2f", vanilla = true },
        progress = { it = "Cosa posso fare per te, $Gsignore:signora;?", enHash = { "cd1babcd", "926e012b" }, vanilla = true },
        reward = { it = "Ah, l'ultimo elenco dei migliori allievi di Brock. Ho una partita di picconi d'onore pronta da consegnare. Devo solo incidere i nomi degli studenti...", enHash = "22580d9e", vanilla = true },
    },
    [6392] = {
        title = { it = "Torna da Brock", enHash = "c3cb11d2", vanilla = true },
        text = { it = "Per una piccola cifra puoi comprare un passaggio in grifone per Thelsamar... purché tu ci sia già $Gstato:stata;. I grifoni ti portano solo nei posti in cui sei già $Gstato:stata;, quindi parla con ogni maestro dei grifoni che incontri, così potrai volare da lui più avanti.\n\nSei già $Gandato:andata; da Thorgrum, il maestro dei grifoni di Thelsamar, quindi ora puoi tornare da lui. E una volta a Thelsamar potrai consegnare i picconi a Brock Stoneseeker.\n\nParlami quando sei $Gpronto:pronta; a partire.", enHash = "0e2b42cf", vanilla = true },
        objectives = { it = "Compra un passaggio in grifone per Thelsamar dal maestro dei grifoni Gryth Thurden, poi porta le Honorary Picks a Brock Stoneseeker, a Thelsamar.", enHash = "53352328", vanilla = true },
        progress = { it = "Ah, $N. Sei $Gtornato:tornata; da Ironforge?", enHash = "c16d3f75", vanilla = true },
        reward = { it = "Hai portato i picconi. Ottimo! Li farò avere ai miei studenti di estrazione mineraria. Sono sicuro che non vedono l'ora di usarli sui giacimenti di minerale del Loch Modan.\n\nGrazie dell'aiuto, $N. Ti sono in debito, ma spero che questo denaro copra almeno le tue spese di viaggio.", enHash = "1382d854", vanilla = true },
    },
    [6393] = {
        title = { it = "Guerra elementale", enHash = "dfbf476f", vanilla = true },
        text = { it = "Il Tribunal of the Tides mi ha mandato a muovere guerra agli elementali del fuoco qui nella Stonetalon Mountain. Neptulon the Tidehunter, Signore di tutti gli elementali dell'acqua, ha preso a cuore di persona l'estinzione dei nostri cugini di fuoco.\n\n$N, puoi aiutarmi a guadagnare il favore del Tribunal distruggendo gli elementali del fuoco nella Charred Vale. Quando vengono distrutti, gli elementali del fuoco lasciano Incendrite. Riportamele e sarai $Gricompensato:ricompensata;.", enHash = "d7743a29", vanilla = true },
        objectives = { it = "Porta 10 Incendrite a Tsunaman, al Sun Rock Retreat.", enHash = "42b4ca90", vanilla = true },
        progress = { it = "Il Tribunal of the Tides si fa impaziente. Vogliono porre fine a questa guerra che infuria da eoni in tutte le dimensioni. I miei fratelli attendono con ansia notizie della gloriosa vittoria sugli odiati elementali del fuoco. Hai le Incendrite che ti ho chiesto?", enHash = "8bfcd885", vanilla = true },
        reward = { it = "Gli spiriti dell'acqua dentro di me ribollono di entusiasmo. $N, mi hai dato una vittoria gloriosa da riferire al Tribunal of the Tides.", enHash = "3235f0f2", vanilla = true },
    },
    [6394] = {
        title = { it = "Thazz'ril's Pick", enHash = "9142d8ba" },
        text = { it = "$N, sei $Gun:una; $R affidabile. Posso contare su di te per un altro compito?\n\nTempo fa stavo esplorando la grotta a nord in cerca di minerali, e ho lasciato lì il mio piccone preferito. Quando poi ho provato a riprenderlo, ho trovato la grotta piena di bestie feroci! Andresti nella grotta, la Burning Blade Coven, a prendermi il piccone?\n\nL'ho lasciato in una sala con delle cascate. Sul mio piccone c'è un incantesimo che lo rende visibile al buio, quindi non dovrai preoccuparti di trovarlo... solo di chi lo sorveglia!", enHash = "d0fe113c" },
        objectives = { it = "Porta Thazz'ril's Pick a Foreman Thazz'ril.", enHash = "11b24982" },
        progress = { it = "Sei $Gentrato:entrata; nella Burning Blade Coven, $N? Hai trovato il mio piccone?", enHash = "8a58367b" },
        reward = { it = "Grande, l'hai preso! Grazie mille, $N. È il mio piccone preferito! Ora, se i miei peon finiranno mai di abbattere questi alberi, magari troveremo una bella grotta da scavare!", enHash = "6469a6bd" },
    },
    [6395] = {
        title = { it = "L'ultimo desiderio di Marla", enHash = "8a094cd0" },
        text = { it = "La mia amica Marla Fipps viveva con suo marito Samuel prima della pestilenza, ma quando questa arrivò Samuel soccombette e si unì alle file del Flagello.\n\nMarla fu risparmiata dalla non morte solo per morire per mano del marito, ormai senza mente. Ma il suo amore era così forte che il suo ultimo desiderio, in punto di morte, fu di essere sepolta accanto al suo amato Samuel.\n\nSamuel Fipps si aggira in un accampamento in rovina lungo la strada a nord-est di Deathknell. Sconfiggilo ed esaudisci il desiderio di Marla: seppelliscilo presso la sua tomba, nella prima fila del nostro cimitero.", enHash = "ddd9710b" },
        objectives = { it = "Porta Samuel Fipps' Remains alla Marla's Grave, poi torna da Novice Elreth.", enHash = "c58c266e" },
        progress = { it = "Dobbiamo rispettare i nostri morti, $N. È uno dei modi in cui siamo diversi dal Flagello...", enHash = "9d299c17" },
        reward = { it = "Oggi hai compiuto una buona azione, $N. Anche se la nostra lotta contro il Flagello continua, speriamo che Marla e Samuel trovino pace insieme nel luogo del loro eterno riposo. Come segno della mia gratitudine, prendi uno di questi manuali che ho trovato.", enHash = "38228e46" },
    },
    [6401] = {
        title = { it = "Kaya è viva", enHash = "196b81b7", vanilla = true },
        text = { it = "Porta la buona notizia a Tammra Windfield, la zia di Kaya, che si trova al Sun Rock Retreat! Kaya è viva! L'avevamo creduta perduta dopo il brutale attacco al nostro villaggio. Segui il sentiero verso ovest per arrivare al Sun Rock Retreat.", enHash = "066a979a", vanilla = true },
        objectives = { it = "Porta la buona notizia a Tammra Windfield, al Sun Rock Retreat.", enHash = "b1bc814f", vanilla = true },
        reward = { it = "Santo cielo, mia nipote Kaya è viva! Questa sì che è una buona notizia. Grazie, $N.", enHash = "f1d552f1", vanilla = true },
    },
    [6402] = {
        title = { it = "Appuntamento a Stormwind", enHash = "3bd360c4", vanilla = true },
        text = { it = "Devi incontrare Windsor alle porte di Stormwind.\n\nQuello che Windsor sta per svelare scuoterà le fondamenta stesse del regno!\n\nNon provare ad andarci da $Gsolo:sola;, $N. Devi radunare un esercito! Raduna i tuoi compagni. Alle armi!", enHash = "97e74600", vanilla = true },
        objectives = { it = "Raggiungi Stormwind City e vai alle porte della città. Parla con Squire Rowe, così che possa avvisare Marshal Windsor del tuo arrivo.", enHash = "d7ad481c", vanilla = true },
        reward = { it = "Prima di cominciare, ti chiedo di radunare un esercito. Dopotutto, affrontiamo un drago!", enHash = "d65e8018", vanilla = true },
    },
    [6403] = {
        title = { it = "La grande mascherata", enHash = "825dca34", vanilla = true },
        text = { it = "È stata una bella avventura, $Gamico:amica;. Ti devo moltissimo. Forse, quando tutto sarà finito...\n\nCome avrai sicuramente capito ormai, Lady Prestor è Onyxia, prole di Deathwing, gemella del tiranno della Spire, Nefarian.\n\nPer troppo tempo ha tenuto il nostro regno sotto il suo sguardo ammaliatore. Persino il Gran Signore è controllato dai suoi inganni: una marionetta. Oggi finisce tutto... L'incantesimo sarà spezzato.\n\nNon preoccuparti, perché insieme vinceremo!\n\nSei $Gpronto:pronta;?", enHash = "9283de78", vanilla = true },
        objectives = { it = "Segui Reginald Windsor attraverso Stormwind. Proteggilo!", enHash = "70923e21", vanilla = true },
        progress = { it = "Io... io... io ero impotente.", enHash = "60f69ede", vanilla = true },
        reward = { it = "<Bolvar tiene in mano il medaglione in frantumi.>\n\nLa magia che contiene deve essere riaccesa. L'occhio del drago deve essere sintonizzato.\n\nIl sacrificio di Windsor ha liberato il nostro Regno, ma la minaccia di Onyxia e della sua stirpe incombe sempre.\n\nQuesto medaglione è ciò che teneva prigionieri la mia mente e il mio corpo. È anche ciò che mi dava accesso alla mente stessa di Onyxia, ai suoi segreti. Anche se ora le visioni sono confuse, alcune cose le ricordo.", enHash = "f101cfde", vanilla = true },
    },
    [6421] = {
        title = { it = "Boulderslide Ravine", enHash = "2d0da615", vanilla = true },
        text = { it = "Qualcosa non va, qui a Stonetalon. Senti anche tu la tensione nell'aria, $N?\n\nA sud-est di qui, nella Boulderslide Ravine, c'è una caverna profonda. I kobold là dentro stanno scavando febbrilmente un cristallo raro chiamato Resonite. Ho bisogno che mi riporti dei campioni di minerale, così potrò capire cosa sta succedendo in quella caverna. Ho bisogno anche che tu vada a vedere quanto è profonda.\n\nVa', giovane $C, è indispensabile che io sappia quale male si annida sotto queste montagne.", enHash = "2b4ae10d", vanilla = true },
        objectives = { it = "Esplora la caverna della Boulderslide Ravine fino in fondo e riporta 10 Resonite Crystal a Mor'rogal, al Sun Rock Retreat, perché li esamini.", enHash = "c9a92cde", vanilla = true },
        progress = { it = "Che notizie hai scoperto dalla Boulderslide Ravine? Ricordo una leggenda che parla del Resonite... ma non riesco a metterci sopra lo zoccolo. Forse sapere cosa c'è in fondo alla caverna chiarirà le loro intenzioni malvagie.", enHash = "869daa64", vanilla = true },
        reward = { it = "Ah... Sì! È questo: i cristalli di Resonite hanno una traccia della magia dei Terrigeni. I kobold devono aver scavato così a fondo da portarne alla luce uno.\n\nLa leggenda dice che i Terrigeni sono creature create dai titani. Furono usati per creare la terra su cui camminiamo. Questa è senza dubbio una minaccia che non si può ignorare.\n\n<Mor'rogal scuote la testa.>\n\nForse posso incantare questi campioni di minerale per usarli contro questo complotto dei kobold.", enHash = "579296b7", vanilla = true },
    },
    [6441] = {
        title = { it = "Satyr Horns", enHash = "860fdd6f", vanilla = true },
        text = { it = "Ehilà! Sto attraversando Ashenvale diretta a Ratchet, e ho deciso di fare una sosta qui a Splintertree. Sono sempre a caccia di affari, e pare che di questi tempi a Ratchet i Satyr Horn siano molto richiesti.\n\nHo chiesto in giro, e sembra che i satiri di Night Run, Satyrnaar e Xavian abbiano proprio il tipo di corna che cerco. Io non sono all'altezza di quei satiri... ma tu hai l'aria di esserlo!\n\nFacciamo così: tu raccogli le corna per me e io ti ripago del disturbo.", enHash = "ccded21d", vanilla = true },
        objectives = { it = "Raccogli 16 Satyr Horn per Pixel, a Splintertree Post.", enHash = "ce6fec4d", vanilla = true },
        progress = { it = "Spero che tu faccia in fretta a procurarti quelle corna, $N. Fra poco torno a Ratchet!", enHash = "042f6a18", vanilla = true },
        reward = { it = "Sono perfette, $N! Grazie dell'aiuto!\n\nAh, e questo è per il disturbo...", enHash = "c596a504", vanilla = true },
    },
    [6442] = {
        title = { it = "Naga allo Zoram Strand", enHash = "cb683206", vanilla = true },
        text = { it = "C'è un male in agguato qui lungo la costa, $R.\n\nÈ il luogo di riposo della città dannata di Zoram, distrutta da tempo e sommersa dai mari. Perduta, e quasi dimenticata.\n\nOra i naga sono tornati, e per quale motivo non lo sappiamo. Ma il motivo conta poco: dobbiamo difendere la terra che abbiamo faticato tanto a fare nostra.\n\nTorna da me con 20 delle loro teste! Ricaccia i naga negli abissi!", enHash = "5fdf459b", vanilla = true },
        objectives = { it = "Porta 20 Wrathtail Head a Marukai, lungo lo Zoram Strand.", enHash = "0d400bed", vanilla = true },
        progress = { it = "I naga aumentano di numero, $N. Ti prego, porta a termine questo compito per me.", enHash = "d8930cbc", vanilla = true },
        reward = { it = "Ci servirebbero più tipi come te da queste parti, $N. Grazie del tuo aiuto.", enHash = "6e95795a", vanilla = true },
    },
    [6461] = {
        title = { it = "Succhiasangue", enHash = "b4d01ee2", vanilla = true },
        text = { it = "Noi troll qui a Malaka'Jin abbiamo prosperato grazie alla terra; la Stonetalon Mountain offre ottima caccia per vivere.\n\nUltimamente abbiamo attirato gli ospiti a cena sbagliati... i ragni di queste montagne razziano i nostri accampamenti di notte per rubarci la selvaggina.\n\nSe ci aiutassi a sterminare queste bestie orribili, noi di Malaka'Jin ti saremmo debitori. I ragni sono dappertutto a Stonetalon: va' verso nord da qui e vedrai di cosa parlo.", enHash = "c3326c24", vanilla = true },
        objectives = { it = "Xen'zilla, a Malaka'Jin, ha bisogno che tu uccida 10 Deepmoss Creeper e 7 Deepmoss Venomspitter.", enHash = "d2e4636e", vanilla = true },
        progress = { it = "Ehi, $Gamico:amica;, hai ammazzato i pelosi succhiasangue? Io non temo nessuno qui a Stonetalon, ma di notte non vado in giro... se capisci cosa intendo, $Gamico:amica;!\n\nFinché resto fuori dal loro piatto, va tutto bene.\n\nBuona fortuna a te, $C!", enHash = "4503b716", vanilla = true },
        reward = { it = "Ottimo, $Gamico:amica;! Buone notizie: forse stasera avremo meno ospiti a cena non invitati.\n\nGrazie mille, $N. Ti siamo debitori per sempre.", enHash = "c57cab6b", vanilla = true },
    },
    [6462] = {
        title = { it = "Troll Charm", enHash = "666f9e05", vanilla = true },
        text = { it = "I miei parenti stavano venendo qui con molti sacri Troll Charm, ma i furbolg Thistlefur li hanno attaccati e uccisi prima che arrivassero a Zoram'gar! Furbolg immondi!\n\nMi mancano i miei fratelli e le mie sorelle uccisi, ma ci rivedremo nell'aldilà. I loro Troll Charm, però, in questo mondo hanno grande valore. È un oltraggio che ce li abbiano i furbolg!\n\n$N, devi recuperare gli amuleti! Sono nelle casse del Thistlefur Hold, una caverna alla fine di Thistlefur Village, a nord di Astranaar.", enHash = "f50a0e6d", vanilla = true },
        objectives = { it = "Porta 8 Troll Charm a Mitsuwa allo Zoram'gar Outpost.", enHash = "22644c69", vanilla = true },
        progress = { it = "Hai trovato gli amuleti, $N? Ogni istante in cui quei furbolg possiedono quegli oggetti sacri, il sangue mi ribolle di rabbia!", enHash = "7308db35", vanilla = true },
        reward = { it = "Li hai trovati! Grazie! Grazie, $N! Non sai che grande cosa hai fatto per me.\n\nUn troll senza il suo amuleto è come un orco senza le sue cicatrici di battaglia...\n\nNon vale nulla.", enHash = { "5f9ecb49", "282cd94f" }, vanilla = true },
    },
    [6481] = {
        title = { it = "I Terrigeni si risvegliano", enHash = "31d8bebd", vanilla = true },
        text = { it = "Hai portato alla luce una minaccia oscura per questa terra, $C. Il Resonite cask che hai trovato in quella caverna custodisce un Terrigeno addormentato di nome Goggeroc.\n\nHo cambiato la composizione dei cristalli di Resonite che hai raccolto, con i miei poteri sciamanici. Prendi l'Enchanted Resonite Crystal e sfonda il Resonite cask, che custodisce il Terrigeno.\n\nUna volta svegliato, Goggeroc sarà indebolito... Uccidilo, $N!", enHash = "dc2717e5", vanilla = true },
        objectives = { it = "Apri il Resonite cask con l'Enchanted Resonite Crystal, poi uccidi Goggeroc. Torna da Mor'rogal con la notizia e l'Enchanted Resonite Crystal.", enHash = "46849a15", vanilla = true },
        progress = { it = "Temo che, se non eliminiamo subito questa minaccia, tutta Stonetalon sarà perduta. La potenza di un Terrigeno non ha eguali. Una volta svegliato, Goggeroc sarà debole per il lungo sonno: è questa l'occasione che devi sfruttare... va' ora, $N!", enHash = "f0d7b07e", vanilla = true },
        reward = { it = "Porti buone notizie, $C! Ho paura solo a pensare a cosa significherebbe un Terrigeno per Kalimdor.\n\nUccidere Goggeroc era un compito degno di un eroe e di nessun altro. Hai fatto bene: tutta Stonetalon e Kalimdor ti sono debitrici, nobile $C.\n\nAccetta questo come tua ricompensa, $Gonoratissimo:onoratissima;.", enHash = "18209af2", vanilla = true },
    },
    [6482] = {
        title = { it = "Libertà per Ruul", enHash = "6f23fbd5", vanilla = true },
        text = { it = "Eh? Chi sei?\n\n$N? Tu non sei un furbolg. Loro sono maledetti! Mi hanno preso per un orso e mi hanno catturato, e ora mi lasciano morire di fame! Le forze mi stanno abbandonando...\n\nAiutami a fuggire, poi parla con mia sorella Yama a Splintertree Post, a est.\n\n$N! Devo fuggire!", enHash = "b3e907d0", vanilla = true },
        objectives = { it = "Scorta Ruul, poi parla con Yama Snowhoof a Splintertree Post.", enHash = "114a8fa6", vanilla = true },
        progress = { it = "Hai visto mio fratello Ruul? È entrato nella foresta giorni fa e non è più tornato...", enHash = "038a5d2f", vanilla = true },
        reward = { it = "Hai trovato mio fratello! L'hanno catturato i Thistlefur? È una notizia terribile, perché anche se molti furbolg sono creature nobili, i Thistlefur sono corrotti.\n\nGrazie per aver salvato mio fratello, $N. Non voglio nemmeno pensare a come hanno trattato il povero Ruul. Dopo una prova simile dormirà a lungo...", enHash = "ee24371a", vanilla = true },
    },
    [6501] = {
        title = { it = "L'occhio del drago", enHash = "3937585f", vanilla = true },
        text = { it = "Un frammento del medaglione in frantumi è tutto ciò che posso offrirti.\n\nDevi trovare un altro essere dal sangue di drago disposto ad aiutarti a forgiare una nuova chiave. Una volta ottenuta questa chiave, dovrai andare al Wyrmbog, nella Dustwallow Marsh. È lì che troverai la sua tana, $N.\n\nDove trovare altri stormi disposti ad aiutarti? Purtroppo non lo so... Si dice che esistano. Alcuni potrebbero perfino lavorare e vivere tra noi, sotto le sembianze di una delle razze umanoidi. Ti auguro buona fortuna.", enHash = "091e5fc7", vanilla = true },
        objectives = { it = "Devi cercare per il mondo un essere capace di ridare potere al Fragment of the Dragon's Eye. L'unica cosa che sai di un essere simile è che esiste.", enHash = "b225113a", vanilla = true },
        progress = { it = "Sento un'aura malvagia che si irradia da te, $R. Che cosa potresti avere con te che emana un'aura simile?", enHash = "c2db74a6", vanilla = true },
        reward = { it = "Avrei dovuto saperlo: un pezzo della madre della covata dei draghi neri, Onyxia. Che schifo...", enHash = "b83d2252", vanilla = true },
    },
    [6503] = {
        title = { it = "Gli Ashenvale Outrunner", enHash = "2587c4f2", vanilla = true },
        text = { it = "Ci sono arrivate segnalazioni che degli Ashenvale Outrunner hanno lasciato il Silverwing Outpost non molto tempo fa e ora si aggirano di soppiatto vicino ai nostri territori nella foresta. Non vogliamo che raccolgano informazioni sulle nostre difese!\n\nMuoviti di nascosto nelle foreste a sud del nostro avamposto e a est dell'avamposto dell'Alleanza di Silverwing. Trova e uccidi gli Outrunner, poi torna da me.", enHash = "004b7122", vanilla = true },
        objectives = { it = "Uccidi 9 Ashenvale Outrunner, poi torna da Kuray'bin allo Splintertree Outpost.", enHash = "27c0f371", vanilla = true },
        progress = { it = "Aspetto notizie degli Outrunner che hai ucciso, $N.", enHash = "cab30883", vanilla = true },
        reward = { it = "Molto bene, $N. Le tue doti di caccia sono notevoli...\n\nLa perdita di quegli Outrunner aiuta ad accecare l'Alleanza, e quando le mancano informazioni è meno probabile che sferri attacchi.", enHash = "26e2ffbb", vanilla = true },
    },
    [6504] = {
        title = { it = "Le pagine perdute", enHash = "1b7b76d7", vanilla = true },
        text = { it = "Ho appena ritirato questa sminuzzatrice a Ratchet e stavo tornando al Warsong Lumber Camp, dove dovrei essere di turno. Mi hanno dato un manuale su come far funzionare la sminuzzatrice, ma durante il viaggio di ritorno una folata di vento me l'ha strappato dalle mani. Le pagine sono volate dappertutto, e mi è rimasta solo la copertina.\n\nOrmai le pagine potrebbero essere ovunque, immagino... ma senza non so come si usa la sminuzzatrice! Le cerchi per me?", enHash = "0d7ff398", vanilla = true },
        objectives = { it = "Trova le 12 pagine mancanti dello Shredder Operating Manual e mettile insieme a formare i Chapter 1, 2 e 3. Riporta le pagine a Gurda Ragescar, vicino a Splintertree Post.", enHash = "20350ce7", vanilla = true },
        progress = { it = "Spero che tu trovi presto le pagine, $N! Ho davvero bisogno di tornare al lavoro!", enHash = "c646c49d", vanilla = true },
        reward = { it = "Leggere non è il mio forte... ma ora potrò tornare al lavoro! Grazie, $N!", enHash = "610a15e7", vanilla = true },
    },
    [6521] = {
        title = { it = "Un'alleanza empia", enHash = "ebc8e217", vanilla = true },
        text = { it = "Malcin dice di trovarsi fuori da Razorfen Downs. Questo ambasciatore deve essere ucciso: agli occhi del Re dei Lich, la sua missione dovrà risultare un fallimento.\n\nLa sua presenza là spiega molto di ciò che abbiamo scoperto sulla zona: alcuni quilboar sono diventati spaventosamente potenti, pur mostrando a loro modo i segni della Piaga. Dev'essere per forza il segno di un qualche patto che hanno stretto.\n\nTrova Malcin e uccidilo, $N. Torna da me quando l'avrai fatto.", enHash = "b5a82db7", vanilla = true },
        objectives = { it = "Porta Ambassador Malcin's Head a Varimathras, nell'Undercity.", enHash = "f53442c7", vanilla = true },
        progress = { it = "Hai trovato l'ambasciatore, $N? È morto?\n\nNon possiamo permetterci di lasciare che il Flagello prenda piede su Kalimdor. È già abbastanza una minaccia per i nostri confini senza doverlo affrontare su due fronti.\n\nL'unico segno incoraggiante negli eventi che mi hai raccontato è che la megera sembrava non corrotta. Deve sapere, nel profondo del suo spirito, che il Flagello potrà anche portare un grande potere, ma che le Barrens non sarebbero davvero sue se accettasse il suo patto.", enHash = "0eb95609", vanilla = true },
        reward = { it = "Bene. Ben fatto, $C.\n\nOra che Malcin è morto, possiamo almeno sapere che l'avanzata del Flagello sarà fermata. La Signora Oscura ti ringrazia per i tuoi sforzi e desidera ricompensarti con un dono.\n\nAnche se non conosciamo la portata dell'influenza del Flagello nei Downs, di sicuro scopriremo presto i suoi piani.", enHash = "2944f470", vanilla = true },
    },
    [6522] = {
        title = { it = "Un'alleanza empia", enHash = "ebc8e217", vanilla = true },
        text = { it = "Mia Signora,\n\nsapete benissimo che cosa vi stiamo offrendo. L'opportunità di prendere le Barrens e le terre al di là è grande. In cambio vogliamo semplicemente il vostro aiuto. E per aiuto non intendiamo altro che concederci la libertà di agire nella zona.\n\nVi prego, permetteteci di discuterne ancora. Abbiamo un grande potere e siamo disposti a condividerlo con chi è abbastanza saggio da unirsi a noi. Per il momento resterò fuori da Razorfen Downs.\n\nCordiali saluti,\nAmbassador Malcin", enHash = "7cb57344", vanilla = true },
        objectives = { it = "Porta lo Small Scroll a Varimathras, nell'Undercity.", enHash = "5612adfc", vanilla = true },
        progress = { it = "Di che affare vuoi parlare, $N? Devi ritenerlo importante, se continui a importunarmi.", enHash = "f9d5df72", vanilla = true },
        reward = { it = "Riconosco l'insegna su questa pergamena, $N. L'hai trovata addosso alla megera che regna sul Razorfen Kraul? Interessante.\n\nA quanto pare il Flagello non si accontenta di un solo continente. Questo Ambassador Malcin, quello che ha scritto il biglietto, è uno dei servitori appestati del Flagello, un diplomatico umano presso il regno di Lordaeron prima che le cose... cambiassero.\n\nSe il Flagello cerca di prendere piede su Kalimdor, allora tocca a noi agire.", enHash = "adaa8095", vanilla = true },
    },
    [6523] = {
        title = { it = "Proteggi Kaya", enHash = "ff31218f", vanilla = true },
        text = { it = "Grazie per avermi liberata! Dobbiamo andarcene in fretta, prima che scoprano che sono libera. Ti prego, scortami fino a Camp Aparaje. Da lì so ritrovare la strada.\n\nMio padre, Makaba Flathoof, sarà ansioso di sapere che sono al sicuro.", enHash = "79473d61", vanilla = true },
        objectives = { it = "Scorta Kaya Flathoof fino a Camp Aparaje, poi torna da Makaba Flathoof, vicino al margine sud-orientale di Stonetalon.", enHash = "d891be17", vanilla = true },
        reward = { it = "Kaya è viva! $N, devo ringraziare te per averla salvata.", enHash = "c00397c3", vanilla = true },
    },
    [6541] = {
        title = { it = "Presentati da Kadrak", enHash = "22d150e7", vanilla = true },
        text = { it = "Sei mai $Gstato:stata; ad Ashenvale, a nord? L'Orda ha da poco messo su un avamposto sullo Zoram Strand, e le nuove reclute per difendere i nostri fronti fanno sempre comodo.\n\nSe te la senti, va' da Kadrak, nelle Barrens del nord, alla torre di guardia. È lui a dirigere la campagna di Ashenvale e può darti altri ordini.", enHash = "fd85e37b", vanilla = true },
        objectives = { it = "Presentati da Kadrak, alla torre di guardia delle Barrens del nord.", enHash = "c1abb8f7", vanilla = true },
        reward = { it = "Ashenvale è una terra divisa, ma gli ultimi sforzi hanno dato ottimi risultati. Non abbiamo solo un avamposto allo Zoram Strand: ce n'è un altro poco a nord di qui, che si chiama Splintertree.", enHash = "7b5636a9", vanilla = true },
    },
    [6542] = {
        title = { it = "Presentati a Kadrak", enHash = "22d150e7", vanilla = true },
        text = { it = "Sei mai $Gstato:stata; ad Ashenvale, a nord? L'Orda ha da poco piazzato un avamposto sullo Zoram Strand, laggiù, e ci fanno sempre comodo reclute nuove per difendere i nostri nuovi fronti.\n\nSe pensi di essere all'altezza, cerca Kadrak nelle Barrens settentrionali, alla torre di guardia. È lui a guidare la campagna di Ashenvale e può darti altri ordini.", enHash = "fd85e37b", vanilla = true },
        objectives = { it = "Presentati a Kadrak, alla torre di guardia nelle Barrens settentrionali.", enHash = "c1abb8f7", vanilla = true },
        reward = { it = "Ashenvale è una terra divisa, ma i nostri sforzi più recenti hanno avuto molto successo. Non abbiamo solo un avamposto allo Zoram Strand, ma anche un altro appena a nord di qui, chiamato Splintertree.", enHash = "7b5636a9", vanilla = true },
    },
    [6543] = {
        title = { it = "I Warsong Reports", enHash = "828b26ed", vanilla = true },
        text = { it = "Ho mandato di recente qualche esploratore ad Ashenvale e mi serve un corriere che porti loro gli ordini e mi riporti un rapporto di quello che hanno osservato.\n\nLa prima tappa è lo Zoram'gar Outpost, lungo la costa a ovest, allo Zoram Strand, dove trovi il primo corriere. Devi passare anche a Splintertree Post, a nord, e lungo la strada a est, vicino ad Azshara. Là troverai un esploratore e un battitore.\n\nDai a ognuno un rapporto e fatti dare da loro un aggiornamento sulle loro scoperte.", enHash = "5fc8fb22", vanilla = true },
        objectives = { it = "Apri il Bundle of Reports. Porta i Warsong Reports al Warsong Scout, al Warsong Runner e al Warsong Outrider. Riporta gli aggiornamenti che ti danno a Kadrak, alla torre di guardia delle Barrens del nord.", enHash = "a026ff01", vanilla = true },
        progress = { it = "Sbrigati, $N. Devono ricevere i loro rapporti: è urgente.", enHash = "2ffb1846", vanilla = true },
        reward = { it = "Vedo che sei $Guno:una; su cui si può contare. Questi aggiornamenti sono decisivi per i nostri piani di espansione ad Ashenvale. Ora possiamo pianificare la mossa successiva.", enHash = "784398fd", vanilla = true },
    },
    [6544] = {
        title = { it = "L'assalto di Torek", enHash = "c5ac4fc6", vanilla = true },
        text = { it = "Ehi! $C! Vieni qui!\n\nIo e i miei predoni stiamo per attaccare il Silverwing Outpost a ovest. Il nostro bersaglio è chi lo comanda, Duriel Moonfire. Gli esploratori riferiscono che l'avamposto è difeso da molte sentinelle e da molti guerrieri. Sarà una battaglia gloriosa!\n\nVuoi la tua parte di gloria, $N, e darci una mano? Se sì, quando sarà finita potrai riferire il nostro successo al mio superiore, Ertog Ragetusk, a Splintertree.\n\nChe ne dici? Sei con noi?", enHash = "98981b3f", vanilla = true },
        objectives = { it = "Scorta Torek nel suo attacco al Silverwing Outpost e a Duriel Moonfire, poi riferisci a Ertog Ragetusk a Splintertree Post.", enHash = "901da421", vanilla = true },
        progress = { it = "Torek è stato mandato in missione contro il Silverwing Outpost. L'attacco è andato a buon fine?", enHash = "bac84eb0", vanilla = true },
        reward = { it = "Quindi l'attacco di Torek è andato a buon fine! Ben fatto, $N. Gli elfi della notte sono avversari niente male. Un po' magri, ma forti e feroci! Sono sicuro che la battaglia sia stata uno spettacolo...\n\nE spero che tu ci abbia guadagnato una cicatrice o due!", enHash = "ac674576", vanilla = true },
    },
    [6545] = {
        title = { it = "Aggiornamento del Warsong Runner", enHash = "a4944cd6", vanilla = true },
        progress = { it = "Allora sei qui con i miei ordini? Fa sempre piacere vedere una recluta nuova con indole esuberante e volontà ferrea.\n\nFarai meglio a imparare in fretta, se vuoi stare al passo qui. La minaccia dei naga cresce, $N. Dal mio arrivo ho osservato e organizzato le difese contro diversi attacchi a questo avamposto.\n\nMa se vuoi dare una mano in quello sforzo, parla con uno degli altri qui all'avamposto.", enHash = "22a5175e", vanilla = true },
        reward = { it = "Be', il mio rapporto spiegherà tutto questo a Kadrak. Devi riportarglielo il più in fretta possibile.", enHash = "2df7c9b7", vanilla = true },
    },
    [6546] = {
        title = { it = "Aggiornamento del Warsong Outrider", enHash = "c533e55a", vanilla = true },
        progress = { it = "Su questo sentiero c'è molto pericolo, $N. Faresti bene a ricordarlo mentre viaggi in queste terre. La minaccia dell'Alleanza è molto vicina.\n\nAbbiamo nemici su tutti i fronti. I satiri sono una forza formidabile e diffusa nell'Ashenvale orientale. Ho anche scoperto che i naga si sono impadroniti di una vasta area della terra di Azshara.\n\nFa piacere vedere che continuiamo a ingrossare le nostre file — tieniti $Gpronto:pronta; a quel che ti aspetta, $N.", enHash = "037979d8", vanilla = true },
        reward = { it = "Porta il mio rapporto a Kadrak. In fretta, $N.", enHash = "1de4ef59", vanilla = true },
    },
    [6547] = {
        title = { it = "Aggiornamento del Warsong Scout", enHash = "af600f6e", vanilla = true },
        progress = { it = "Tieni gli occhi aperti, $R. Gli elfi si nascondono spesso nell'ombra...\n\nDobbiamo restare sempre vigili. Abbiamo faticato molto per prenderci questa terra, e gli elfi aspettano l'occasione per portarcela via.\n\nImmagino che tu abbia i miei prossimi ordini da Kadrak?", enHash = "504c957a", vanilla = true },
        reward = { it = "Fa' sapere a Kadrak il successo che abbiamo avuto qui nel tenere a bada gli elfi della notte. I nostri piani procedono bene.", enHash = "8a4f3382", vanilla = true },
    },
    [6548] = {
        title = { it = "Vendica il mio villaggio", enHash = "d60f07dc", vanilla = true },
        text = { it = "Il clan Grimtotem ha razziato il mio villaggio e ucciso quasi tutti. Ne ho uccisi quanti ho potuto, ma sono scampato per un soffio.\n\n$N, ora desidero solo che altri di loro muoiano. Li troverai appena a ovest di qui.", enHash = "1b1e535c", vanilla = true },
        objectives = { it = "Uccidi 8 Grimtotem Ruffian e 6 Grimtotem Mercenary, poi torna da Makaba Flathoof, vicino al margine sud-orientale di Stonetalon.", enHash = "4dd84dcb", vanilla = true },
        progress = { it = "Li hai già uccisi?", enHash = "61f11f91", vanilla = true },
        reward = { it = "$N, ti ringrazio... ma non dimenticherò mai quello che i Grimtotem hanno fatto al mio villaggio.", enHash = "d968d023", vanilla = true },
    },
    [6561] = {
        title = { it = "La malvagità di Blackfathom", enHash = "6864f43a", vanilla = true },
        text = { it = "Le forze mi hanno abbandonato. Serve il tuo aiuto!\n\nTanto tempo fa questo luogo era un grande tempio di Elune. Ma la sventura lo portò in rovina quando la corruzione di un Antico Dio filtrò da sotto la terra e contaminò il sacro pozzo lunare.\n\nAku'Mai, servitore dell'Antico Dio, si levò dalle acque.\n\nI cultisti del Martello del Crepuscolo si sono alleati con i naga per occupare questi luoghi. I cultisti, guidati da Kelris, sacrificano innocenti ad Aku'Mai per averne potere.\n\nUccidi Kelris e porta la sua testa a Bashana, a Thunder Bluff, $N, ti prego.", enHash = "6ecf6549", vanilla = true },
        objectives = { it = "Porta la testa di Twilight Lord Kelris a Bashana Runetotem, a Thunder Bluff.", enHash = "0f011111", vanilla = true },
        progress = { it = "Che la Madre Terra sia con te, $N.\n\nLa pace tra la terra e tutti i suoi figli dovrebbe essere il nostro scopo. Lei ha un grande disegno per la natura, e tutti noi abbiamo una parte da recitare in quel disegno.", enHash = "1f677918", vanilla = true },
        reward = { it = "Kelris è sfuggito all'Argent Dawn per parecchio tempo.\n\nPer un po' lo hanno creduto morto o scomparso.\n\nPonendo fine al suo dominio hai risparmiato la vita a molti innocenti, $N.\n\nSia lodata la Madre Terra! Sacrificare un altro a un servitore di un Antico Dio per il proprio tornaconto è di una ripugnanza senza pari!\n\nOggi hai compiuto una grande cosa. Kelris era una creatura del male e cercava di riportare il mondo a un tempo di caos venerando creature come gli Antichi Dei. Grazie, $N.", enHash = "62f6ae1e", vanilla = true },
    },
    [6562] = {
        title = { it = "Guai nelle Deeps", enHash = "fc4eaee6", vanilla = true },
        text = { it = "Je'neu Sancrea ha bisogno di aiuto. Si trova allo Zoram'gar Outpost, in Ashenvale. La foresta degli elfi della notte è a nord delle Stonetalon Mountains. Puoi raggiungerla passando per il Windshear Crag oppure andando a nord attraverso le Barrens. Lo Zoram Strand è molto a ovest della foresta. Sta' $Gattento:attenta;, $N. Là ci sono forze che non prenderanno bene la tua presenza.", enHash = "1ed5360e", vanilla = true },
        objectives = { it = "Parla con Je'neu Sancrea in Ashenvale.", enHash = "492aee1a", vanilla = true },
        reward = { it = "Ti manda Tsunaman? Eccellente. Allora abbiamo questioni di cui parlare.", enHash = "4c86b97d", vanilla = true },
    },
    [6563] = {
        title = { it = "L'essenza di Aku'Mai", enHash = "70145aef", vanilla = true },
        text = { it = "Nei primi cunicoli delle Blackfathom Deeps, lungo le pareti della caverna, si trovano grossi grappoli di zaffiro. Di recente si è notato che i naga raccoglievano i cristalli. Finché non si capisce il perché, sento che dovremmo impedire ai naga di riuscirci. I cristalli hanno un grande potere elementale e, se usati in modo sbagliato, potrebbero diventare una potente componente arcana.\n\nMi aiuterai, $N? Le Blackfathom Deeps si trovano lungo lo Zoram Strand, a nord del nostro avamposto.", enHash = "7bc6a613", vanilla = true },
        objectives = { it = "Porta 20 Sapphire of Aku'Mai a Je'neu Sancrea, in Ashenvale.", enHash = "09400c7b", vanilla = true },
        progress = { it = "Come va la ricerca dei cristalli, $N? Hai visto i naga raccoglierli? Prego i miei antenati perché troviamo la ragione per cui raccolgono cose simili.", enHash = "3ebdeb88", vanilla = true },
        reward = { it = "Ben fatto, $N. Questi sono i cristalli di cui parlavo. Curioso...\n\nSento il potere che è dentro di loro. Gli spiriti dell'acqua vi si aggrappano. Qualunque cosa i naga volessero farne... be', rallegriamoci che non siano più nelle loro mani.", enHash = "d4a910b8", vanilla = true },
    },
    [6564] = {
        title = { it = "Fedeltà agli Antichi Dei", enHash = "e7f27119", vanilla = true },
        text = { it = "Sul biglietto accartocciato è scarabocchiata una grafia incerta:\n\n\"Sì, di' a tutte le sacerdotesse di portarmi i cristalli. Gli spiriti elementali dell'acqua sono forti dentro di loro e aiuteranno molto i nostri aquamancer nelle loro evocazioni.\n\nControllando il potere che è nei cristalli, placheremo Aku'Mai. Un giorno avremo potere a sufficienza per riportare Aku'Mai tra noi, e il mondo tornerà alla sua epoca più grande! Un'epoca di dominio degli Antichi Dei!\"", enHash = "2f120d4d", vanilla = true },
        objectives = { it = "Porta la Damp Note a Je'neu Sancrea, in Ashenvale.", enHash = "e73ee07d", vanilla = true },
        progress = { it = "Sì, $N? Di cosa hai bisogno? C'è ancora molto che devo imparare sui cristalli che i naga stanno raccogliendo.", enHash = "8659ec84", vanilla = true },
        reward = { it = "Questo è davvero interessante. Hai fatto bene a portarmelo.\n\nOra abbiamo un nome per i nostri guai... Lorgus Jett.", enHash = "089d82a0", vanilla = true },
    },
    [6565] = {
        title = { it = "Fedeltà agli Antichi Dei", enHash = "e7f27119", vanilla = true },
        text = { it = "A questo seguace del Martello del Crepuscolo non si può permettere di portare a termine il suo piano. Quelli del Martello del Crepuscolo non capiscono gli spiriti della natura. Credono negli Antichi Dei: creature di caos e distruzione sconfitte tanto tempo fa. A questo Lorgus non si può permettere di riuscirci. Devi fermarlo, $N. Io non posso farlo: sono troppo debole.\n\nVa' nelle Blackfathom Deeps, trovalo e uccidilo. Torna da me qui a Zoram'gar quando è fatto.", enHash = "243cde2c", vanilla = true },
        objectives = { it = "Uccidi Lorgus Jett nelle Blackfathom Deeps, poi torna da Je'neu Sancrea in Ashenvale.", enHash = "0a6c9367", vanilla = true },
        progress = { it = "L'hai già trovato, $N? Lorgus va fermato!", enHash = "396340e8", vanilla = true },
        reward = { it = "Molto bene! Grazie, $N. Forse non abbiamo fermato del tutto il Martello del Crepuscolo, ma almeno hai sventato un altro dei suoi piani per riportare al potere gli Antichi Dei.\n\nChissà quali altri piani stanno prendendo forma, ma per ora possiamo stare tranquilli.", enHash = "6b85ef3f", vanilla = true },
    },
    [6568] = {
        title = { it = "La testimonianza di Rexxar", enHash = "156e0fab", vanilla = true },
        text = { it = "Che cosa sai delle illusioni, $N? Vedi, è un'illusione che dovrai creare per aggirare le difese del Black Flight.\n\nConosco una persona che potrebbe essere disposta ad aiutarti a compiere questo inganno. In passato ha aiutato la nostra gente, quando ha ritenuto la causa degna.\n\nNelle Western Plaguelands troverai Myranda the Hag, maestra illusionista — esiliata dall'Alleanza di Lordaeron. Va' là e porta con te questo messaggio.", enHash = "bb491543", vanilla = true },
        objectives = { it = "Consegna Rexxar's Testament a Myranda the Hag, nelle Western Plaguelands.", enHash = "1df2b082", vanilla = true },
        progress = { it = "Non mi capita spesso di vedere qualcuno dell'Orda da queste parti di Lordaeron. Che cos'hai per Myranda?", enHash = "f4e33f6c", vanilla = true },
        reward = { it = "<Myranda tiene in mano il biglietto, si ferma un istante, poi sorride.>\n\nCome sta? Rexxar, intendo. Oh, suvvia, non avere un'aria così confusa. La lettera è stata lasciata in bianco di proposito. Portava con sé le intenzioni e i pensieri di chi l'ha creata. A giudicare dal contenuto, non c'è da stupirsi che Rexxar l'abbia lasciata così. Immagina se fossi $Gcatturato:catturata; o $Gucciso:uccisa; e queste informazioni venissero scoperte!\n\nOh, non importa! Myranda ti aiuterà, $R. Devo un favore o due al Capoguerra.\n\n<Myranda sorride.>", enHash = "b134c4f2", vanilla = true },
    },
    [6570] = {
        title = { it = "Emberstrife", enHash = "d8e4a4be", vanilla = true },
        text = { it = "Ho sintonizzato questo medaglione con la magia necessaria a creare e mantenere un'illusione entro i confini della tana di Emberstrife.\n\nEmberstrife è un antico drago; un vecchio guardiano delle porte di Nefarian, gravato dal compito di mettere alla prova i dragonidi che aspirano al rango di guardia scelta di Onyxia.\n\nVa' nel Wyrmbog del Dustwallow Marsh ed entra nella tana di Emberstrife. Una volta lì, indossa l'amuleto e segui la strada dove il destino ti porterà!", enHash = "1c2484f1", vanilla = true },
        objectives = { it = "Viaggia fino al Wyrmbog, nel Dustwallow Marsh, e cerca l'Emberstrife's Den. Una volta dentro, indossa l'Amulet of Draconic Subversion e parla con Emberstrife.", enHash = "4bfdaa8f", vanilla = true },
        reward = { it = "Siamo rimasti così a corto di soldati capaci che Nefarian mi manda dei cuccioli? Non supererai mai le mie prove, $Gpiccolo:piccola; della covata.", enHash = "9a744f15", vanilla = true },
    },
    [6571] = {
        title = { it = "I Warsong Supplies", enHash = "5fd2fa90", vanilla = true },
        text = { it = "Al campo di legname dei Warsong ci mancano alcune cose!\n\nPixel, a Splintertree Post, ha il nostro carico di lame per sega. Per una cassa di asce servirà un viaggio a Booty Bay, da Wharfmaster Lozgil.\n\nIl carico di olio e corda sarà più difficile. La corda l'hanno rubata i furbolg Thistlefur e Foulweald, e i satiri hanno intercettato la consegna dell'olio e ora lo usano per riti detestabili a Night Run, Satyrnaar e Xavian!\n\nPuoi aiutarmi?", enHash = "4342cdaa", vanilla = true },
        objectives = { it = "Raccogli i Warsong Supplies: Warsong Saw Blades, Logging Rope, Warsong Oil e il Warsong Axe Shipment, per Locke Okarr a Splintertree Post.", enHash = "123b2bdb", vanilla = true },
        progress = { it = "Spero che tu riesca a procurarmi i rifornimenti! Sono nei guai seri se non li consegno presto!", enHash = "517342b0", vanilla = true },
        reward = { it = "Ottimo, $N. Mi hai risparmiato un sacco di lavoro!\n\nMa non pensare che non ti sia riconoscente!", enHash = "f1a7eb12", vanilla = true },
    },
    [6581] = {
        title = { it = "Warsong Saw Blades", enHash = "5ff37375", vanilla = true },
        progress = { it = "Dritte da Ratchet, le Warsong Saw Blades! Sì, ce le ho proprio qui.\n\n...Ma che genere di pagamento hai per me? Non puoi mica prendertele e basta! Il mio tempo non è a buon mercato!\n\nQuello che mi serve davvero è una buona arma da fuoco da portarmi dietro nei viaggi. Una ragazza deve pur proteggersi, no? C'è un fucile che mi piace molto e che sono sicura un ingegnere non avrebbe problemi a costruire.\n\nQuindi, se mi porti un Deadly Blunderbuss, ti do il carico di lame. Affare fatto?", enHash = "7d473960", vanilla = true },
        reward = { it = "Questo è perfetto — proprio quel che ci vuole! Bene, ecco il carico.", enHash = "c98d3646", vanilla = true },
    },
    [6582] = {
        title = { it = "La prova dei teschi, Scryer", enHash = "775dba98", vanilla = true },
        text = { it = "Noi siamo i figli di Deathwing, $Gcucciolo:cucciola;. Il nostro dominio sugli Aspects inferiori deve essere imposto.\n\nSe sei davvero $Gdegno:degna; dell'ascesa, lo stormo inferiore avvizzirà al tuo cospetto.\n\nTrova i loro campioni e annientali in nome di nostro Padre!\n\nVa' a Winterspring e scova il possente drago blu Scryer. Schiaccia lui e chiunque del Blue Flight si metta sulla tua strada. Strappagli il teschio e riportamelo.", enHash = "05b05f9d", vanilla = true },
        objectives = { it = "Devi trovare Scryer, il drago campione dello stormo blu, e ucciderlo. Stacca il teschio dal suo cadavere e riportalo a Emberstrife.\n\nSai che Scryer si trova a Winterspring.", enHash = "b0f1b34b", vanilla = true },
        progress = { it = "<Emberstrife sibila.>", enHash = "6fa740fd", vanilla = true },
        reward = { it = "Una delle sssvariate... completata...", enHash = "0bf6a502", vanilla = true },
    },
    [6583] = {
        title = { it = "La prova dei teschi, Somnus", enHash = "7804676f", vanilla = true },
        text = { it = "Come nostro Padre schiaccia gli Aspects stessi, così anche noi dobbiamo sforzarci di portare caos e distruzione ai loro figli.\n\nDevi mettere alla prova il tuo valore in battaglia contro i sognatori insonni: i figli del Green Flight.\n\nVa' nella Swamp of Sorrows e scova Somnus, drago campione del Green Flight. Lascia scorrere il tuo odio; domina l'insetto... Torna da me con il suo teschio...", enHash = "d437f73c", vanilla = true },
        objectives = { it = "Distruggi il drago campione del Green Flight, Somnus. Prendi il suo teschio e riportalo a Emberstrife.", enHash = "670d6b34", vanilla = true },
        progress = { it = "Non tornare qui finché non ti sarai $Gimmerso:immersa; nel sangue dei nostri nemici e non ti sarai $Gabbeverato:abbeverata; della loro sofferenza.", enHash = "0c8175a1", vanilla = true },
        reward = { it = "Un'altra completata...", enHash = "762b10f8", vanilla = true },
    },
    [6584] = {
        title = { it = "La prova dei teschi, Chronalis", enHash = "76dc544d", vanilla = true },
        text = { it = "I guardiani del tempo, figli di Nozdormu — Signore dei Ssssecoli...\n\nSono in tre a sorvegliare le Caverns of Time, ma solo uno interessa al Black Flight: il Mutatempo, Chronalis, draghetto prediletto di Nozdormu.\n\nSssferra a questo campione un colpo che faccia piangere persino le stoiche sabbie del tempo. Torna da me con il suo teschio.", enHash = "94186c08", vanilla = true },
        objectives = { it = "A guardia delle Caverns of Time, nel Tanaris Desert, c'è Chronalis, figlio di Nozdormu. Distruggilo e riporta il suo teschio a Emberstrife.", enHash = "3bfc6936", vanilla = true },
        progress = { it = "Ironia della sorte, $Gcucciolo:cucciola;, il tempo è essssenziale.", enHash = "e3e8dd60", vanilla = true },
        reward = { it = "Resssta il più odiato...", enHash = "3c9e83db", vanilla = true },
    },
    [6585] = {
        title = { it = "La prova dei teschi, Axtroz", enHash = "59cf3cb4", vanilla = true },
        text = { it = "Fu sulle montagne di Grim Batol che nostro Padre si scagliò contro la forza unita degli Aspects. Il gesto vile della traditrice, Alexstrasza, fece guadagnare agli altri Aspects il tempo di sfuggire all'ira di Padre.\n\nUn gesssto così vergognoso...\n\nOra il Red Flight sorveglia Grim Batol; il suo luogotenente, Axtroz, deve essere distrutto. Riportami il teschio di Axtroz. Per Padre, $Gcucciolo:cucciola;!", enHash = "5f29fc10", vanilla = true },
        objectives = { it = "Va' a Grim Batol e scova Axtroz, drago campione del Red Flight. Distruggilo e prendi il suo teschio. Riporta il teschio a Emberstrife.", enHash = "07393f37", vanilla = true },
        progress = { it = "Cambiamenti... li sssento avvenire in te, $Gcucciolo:cucciola;. Supera questa prova e resterà solo la cerimonia.", enHash = "32d199f2", vanilla = true },
        reward = { it = "Avevo dubitato della tua dedizione, $Gcucciolo:cucciola;. Hai perseverato, dominando i nostri nemici e portando onore al nostro stormo.\n\nOra devo preparare i teschi per la tua ascesa.", enHash = "997b98e4", vanilla = true },
    },
    [6601] = {
        title = { it = "Ascesa...", enHash = "e41c237f", vanilla = true },
        text = { it = "Dai teschi dei nostri nemici si forgia un medaglione. Conosci questo medaglione, sssì? Di certo l'hai visto indossare dai tuoi anziani.\n\nPrendilo, $Gcucciolo:cucciola;. Torna alla Spire e presentalo a General Drakkisath. Il generale porrà l'incantamento finale sul medaglione, sintonizzando il monile con il tuo spirito.\n\nIndosserai il medaglione finito come segno d'onore, simbolo della tua ascesa a uno dei nostri ranghi più protetti: Guardia della madre della covata.\n\nVa'!", enHash = "92a705cc", vanilla = true },
        objectives = { it = "A quanto pare la messinscena è finita. Sai che l'Amulet of Draconic Subversion che Myranda the Hag ha creato per te non funzionerà dentro la Blackrock Spire. Forse dovresti trovare Rexxar e spiegargli la tua difficile situazione. Mostragli il Dull Drakefire Amulet. Speriamo che sappia cosa fare.", enHash = "34f03cc7", vanilla = true },
        progress = { it = "Niente panico, $N!", enHash = "2be3022e", vanilla = true },
        reward = { it = "Sono solo chiacchiere da drago, $N — più aria fritta che informazioni concrete. Da quelli della loro specie c'è da aspettarsi un comportamento pomposo e aggressivo.", enHash = "b4b68d6a", vanilla = true },
    },
    [6621] = {
        title = { it = "Il re dei Foulweald", enHash = "2cf244dc", vanilla = true },
        text = { it = "$N, un'altra tribù di furbolg, i Foulweald, vive a sud-est di Astranaar. Non sono numerosi come i Thistlefur, ma la loro ferocia è una minaccia per il futuro. Con una dimostrazione di forza possiamo togliere di mezzo quella minaccia.\n\nPrendi questo stendardo, va' al villaggio dei Foulweald e piantalo sul loro tumulo dei totem. Cercheranno di distruggere lo stendardo, ma tieni duro finché non compare il loro capo, Murgut, a salvare la faccia della tribù. Portami il totem che porta con sé.\n\nRaduna i tuoi alleati, $N. Non è un incarico per $Gun solo:una sola; $C.", enHash = "10796286", vanilla = true },
        objectives = { it = "Piazza Karang's Banner sul Foulweald Totem Mound. Non lasciare che i furbolg distruggano lo stendardo. Sconfiggi Chief Murgut e porta Murgut's Totem a Karang Amakkar, a Zoram'gar.", enHash = "b1cf83df", vanilla = true },
        progress = { it = "Hai sconfitto Chief Murgut, $N? Hai recuperato il suo Foulweald Totem?", enHash = "ee5a3b82", vanilla = true },
        reward = { it = "Buon lavoro, $N. Lanciare quella sfida ai Foulweald e sconfiggere il loro capo manda loro un messaggio chiaro:\n\nCon l'Orda non si scherza.\n\nNon credo che quella tribù ci darà molti problemi per parecchio tempo.", enHash = "a40027b0", vanilla = true },
    },
    [6626] = {
        title = { it = "Un esercito del male", enHash = "9cb94124", vanilla = true },
        text = { it = "I Reietti non trasmettono la loro... malattia... da quello che ho visto. Questo diplomatico sembra concedere la non morte a chi aspira a seguirlo. Comincio a pensare che sia uno del Flagello.\n\nPer ora, però, non mi preoccupo di lui, ma delle schiere che crescono intorno a lui. Ogni giorno strisciano fuori dall'ombra, quasi implorandolo di dare loro più potere.\n\nNon ho abbastanza potere per combatterli senza aiuto, $N. Che ne dici? Te la senti di andare a caccia?", enHash = "528afb12", vanilla = true },
        objectives = { it = "Uccidi 8 Razorfen Battleguard, 8 Razorfen Thornweaver e 8 Death's Head Cultist e torna da Myriam Moonsinger, vicino all'ingresso di Razorfen Downs.", enHash = "3a330483", vanilla = true },
        progress = { it = "Come va la caccia, $N? Aver visto anche solo questo piccolo saggio del potere di questo diplomatico mi toglie ogni dubbio: il Flagello è una delle più grandi minacce che questo mondo abbia mai visto.", enHash = "20252e97", vanilla = true },
        reward = { it = "Grazie, $N! Il lavoro che hai fatto sarà di grande aiuto, di sicuro.\n\nContinuerò a studiare questo diplomatico e il resto dei quilboar qui. Se cerchi avventure più grandi, io troverei qualche amico e mi addentrerei nella caverna che sembra le fauci di un enorme cinghiale, proprio laggiù. Sicuramente, una volta dentro, troverai sfide più grandi da affrontare.", enHash = "75fc6442", vanilla = true },
    },
    [6627] = {
        title = { it = "Prova di sapienza", enHash = "c2b6e611", vanilla = true },
        text = { it = "Mi hai portato il libro, e ora è il momento della tua domanda. Sei $Gpronto:pronta;?\n\nIl tempo non è un problema, $C, quindi non sentirti sotto pressione. Puoi prenderti tutto il tempo che vuoi per rispondere.", enHash = "6d1d5d74", vanilla = true },
        objectives = { it = "Rispondi bene alla domanda di Braug Dimspirit, poi parlagli di nuovo. Resterà nelle Stonetalon Mountains finché non sarai $Gpronto:pronta;.", enHash = "22259cb7", vanilla = true },
        progress = { it = "La vita è piena di domande, $C. Non riuscirai mai a rispondere a tutte, ma con un po' di tempo e di studio forse diventerai un po' più sapiente.", enHash = "f89c9576", vanilla = true },
        reward = { it = "Ben fatto, $C. Hai studiato il testo che ti avevo chiesto, e ora hai superato un'altra delle nostre prove.", enHash = "ab309234", vanilla = true },
    },
    [6628] = {
        title = { it = "Prova di sapienza", enHash = "c2b6e611", vanilla = true },
        text = { it = "Ecco che il momento è di nuovo arrivato. Come $Gstudente:studentessa; di sapienza hai mostrato grande tenacia accettando il mio compito.\n\nE quindi ora ti offro la tua domanda. Se sei $Gpronto:pronta;, parlami di nuovo, e prenditi tutto il tempo che ti serve, $N: non c'è fretta di rispondere.", enHash = "fab70901", vanilla = true },
        objectives = { it = "Rispondi bene alla domanda di Parqual Fintallas, poi parlagli di nuovo. Resterà nell'Undercity finché non sarai $Gpronto:pronta;.", enHash = "847953e9", vanilla = true },
        progress = { it = "C'è una sola regola che secondo me devi conoscere, se vuoi sopravvivere in questo mondo: più sai, più vedi.\n\nSe studi, se osservi, comincerai a vedere nel mondo cose che $Gnessun altro:nessun'altra; $R vedrà.", enHash = "bfb3a5e8", vanilla = true },
        reward = { it = "Ben fatto, $N. Avevo i miei dubbi che studiassi davvero il testo che ti avevo chiesto di recuperare, ma hai risposto bene.", enHash = "05cc25f2", vanilla = true },
    },
    [6629] = {
        title = { it = "Uccidi Grundig Darkcloud", enHash = "cef48bdb", vanilla = true },
        text = { it = "$N, hai fatto un ottimo lavoro uccidendo i Grimtotem. Se te la senti, Grundig Darkcloud e la sua banda personale di bruti sono di gran lunga i peggiori del gruppo. È stato lui a guidare il brutale attacco al mio villaggio.\n\nLo troverai a Grimtotem Post, poco più su lungo il sentiero verso ovest. Uccidilo, e ti sarò grato per sempre.", enHash = "a64fc8b6", vanilla = true },
        objectives = { it = "Uccidi Grundig Darkcloud e 6 Grimtotem Brute, poi torna da Makaba Flathoof, vicino al margine sud-orientale di Stonetalon.", enHash = "aaeddca6", vanilla = true },
        progress = { it = "Hai ucciso Grundig Darkcloud e la sua banda personale di Brute?", enHash = "651c1cc8", vanilla = true },
        reward = { it = "Grundig Darkcloud è morto! $N, ti sarò sempre grato per quello che hai fatto qui oggi.", enHash = "4a7cfb3e", vanilla = true },
    },
    [6641] = {
        title = { it = "Vorsha the Lasher", enHash = "268dac53", vanilla = true },
        text = { it = "Vorsha the Lasher... l'idra diabolica che si aggira per i mari...\n\nHa attaccato il nostro avamposto, ogni volta senza alcuna provocazione, devastando tutto ciò che le capita sul cammino.\n\nMa io sono pronto, $N. Mi sono preparato a battere l'idra e a porre fine a questi attacchi a Zoram'gar.\n\nI naga onorano la natura malvagia di questa bestia con un braciere che resta acceso su un'isola poco al largo della costa. Credo che, se lo spegniamo, Vorsha comparirà infuriata.\n\nCi servirà aiuto, quindi porta con te alleati forti.", enHash = "5355d672", vanilla = true },
        objectives = { it = "Proteggi Muglash mentre raggiunge il braciere. Aiutalo a spegnerlo, poi difendilo mentre combatti contro i naga.\n\nSe ci riesci, torna allo Zoram'gar Outpost e informa il Warsong Runner della morte di Vorsha the Lasher.", enHash = "c71a58ad", vanilla = true },
        reward = { it = "Da quando sono qui ho assistito a molti attacchi dei naga. Mi mette il cuore in pace sapere che Vorsha non si aggirerà più libera.\n\nAbbiamo un debito con te, $N.", enHash = "ded33195", vanilla = true },
    },
    [6661] = {
        title = { it = "Caccia ai Deeprun Rat", enHash = "72edef2d", vanilla = true },
        text = { it = "Alt là, canaglia. Arrrr... Arrrr, cerchi lavoro? Quaggiù abbiamo un bel problema di ratti e non abbastanza braccia sul cassero di poppa.\n\nChe ne dici? Ti basta prendere questo flauto acchiapparatti e suonare la melodia vicino a quei parassiti. Ti seguiranno fino ai confini del mondo!\n\nAcchiappane cinque, di quelle bestiacce, e riportameli qui. Li vogliamo vivi.\n\nArrrrr...", enHash = "3ce179f2", vanilla = true },
        objectives = { it = "Cattura 5 Deeprun Rat usando il Rat Catcher's Flute. Porta i ratti da Monty. Non dimenticare di restituire il flauto quando hai finito.", enHash = "25e5963f", vanilla = true },
        progress = { it = "Yarrr... Mozzo, cosa ci metti tanto?", enHash = "66116984", vanilla = true },
        reward = { it = "Andranno benone, $Gcompagno:compagna;. A mio fratello servono che scalpitino ancora, sennò vanno a male... Non vorrai mica assaggiare uno spiedino di ratto andato a male.", enHash = "a1220968", vanilla = true },
    },
    [6662] = {
        title = { it = "Mio fratello, Nipsy", enHash = "60bda50f", vanilla = true },
        text = { it = "Mio fratello, Nipsy, manda avanti un banco di spiedini di ratto dall'altra parte del Deeprun. Devi portargli questa cassa di ratti prima che vadano a male. Muoviti!\n\nHai già viaggiato su un tram, vero? È facile. Sali a bordo quando arriva e goditi il viaggio. E tieni braccia e gambe dentro per tutto il tragitto, se non vuoi finire con una gamba di legno per il resto dei tuoi giorni.", enHash = "39f6f3b6", vanilla = true },
        objectives = { it = "Porta la Carton of Mystery Meat a Nipsy, allo Stormwind Deeprun Tram Depot.", enHash = "169a132a", vanilla = true },
        progress = { it = "<Nipsy infila l'indice in uno dei fori d'aria della cassa.>\n\nVivi e vegeti... e giusto in tempo!", enHash = "4c5ccac5", vanilla = true },
        reward = { it = "Povero Monty. Da quando c'è stato l'incidente di Gnomeregan non è più lo stesso. Quel ragazzo non ha mai visto un oceano in vita sua, figuriamoci fare il pirata.\n\n<Nipsy sospira.>\n\nAlmeno continua a procurarci bestiole che si dimenano.", enHash = "53a25e31", vanilla = true },
    },
    [6681] = {
        title = { it = "Il maniero, Ravenholdt", enHash = "7feab647", vanilla = true },
        text = { it = "$N,\n\nRavenholdt si è interessato a te, $Ggiovane ladro:giovane ladra;. Ti abbiamo osservato. Il tuo stile è un po' goffo, ma niente che non si possa correggere.\n\nSe sei $Gpronto:pronta; a intraprendere la carriera di $Gdiscepolo:discepola; di Master Ravenholdt e di membro dell'Assassin's League, non devi far altro che portare il Seal of Ravenholdt (allegato a questa lettera) al Ravenholdt Manor.\n\nIl tuo primo compito è trovare il maniero, nascosto tra le colline di Hillsbrad, e dimostrare la tua astuzia.\n\nCordiali saluti,\n\nFahrad", enHash = "e27d9099", vanilla = true },
        objectives = { it = "Porta il Seal of Ravenholdt a Fahrad, al Ravenholdt Manor, nascosto tra le colline di Hillsbrad.\n\nLungo la strada la tua astuzia sarà messa alla prova. Preparati.", enHash = "92bd1c27", vanilla = true },
        progress = { it = "Hai incontrato Milton?\n\n<Fahrad ride.>", enHash = "687bd583", vanilla = true },
        reward = { it = "Eccellente, $Ggiovane ladro:giovane ladra;.\n\nSembri un po' $Gmalconcio:malconcia;, ma niente di grave.\n\nTi aspetta un lungo viaggio — lungo e ricco di soddisfazioni. Sei $Gpronto:pronta; ad abbracciare finalmente il tuo destino tra i maestri di Ravenholdt?\n\nParla con le guardie qui fuori. Ti faranno cominciare.", enHash = "9174a1b2", vanilla = true },
    },
    [6701] = {
        title = { it = "Syndicate Emblems", enHash = "b41d4295", vanilla = true },
        progress = { it = "Siamo impegnati da anni in una battaglia contro il Syndicate. Quello che gli manca in abilità lo compensano con il numero. È impossibile ucciderli abbastanza in fretta da ridurre in modo visibile le loro file!\n\nAbbiamo scoperto che il modo migliore per far fronte a quanti sono è rubare i loro emblemi. Quando un emblema viene rubato, il membro disonorato viene 'sistemato' dall'interno.\n\nSvuota loro le tasche e consegna gli emblemi a me o a una delle altre guardie.\n\nComincia da Durnholde, a sud di qui.", enHash = "aa17b2c7", vanilla = true },
        reward = { it = "Ehi, bel lavoro! Continua così e forse gli altri ladri smetteranno di sputarti addosso.", enHash = "eb72dff7", vanilla = true },
    },
    [6721] = {
        title = { it = "La via del cacciatore", enHash = "55ee6c0b", vanilla = true },
        text = { it = "Salve, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza capace da saper gestire una bestia e addestrarla come compagna.\n\nDevi andare da Dazalar, a Dolanaar. Può metterti sulla via per guadagnarti un animale tutto tuo.", enHash = "e23d6df2", vanilla = true },
        objectives = { it = "Parla con Dazalar, a Dolanaar.", enHash = "f1f12d62", vanilla = true },
        reward = { it = "Sì, è arrivato il momento, $C.", enHash = "938cf012", vanilla = true },
    },
    [6722] = {
        title = { it = "La via del cacciatore", enHash = "55ee6c0b", vanilla = true },
        text = { it = "Salve, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza capace da saper gestire una bestia e addestrarla come compagna.\n\nDevi andare da Dazalar, a Dolanaar. Può metterti sulla via per guadagnarti un animale tutto tuo.", enHash = "e23d6df2", vanilla = true },
        objectives = { it = "Parla con Dazalar, a Dolanaar.", enHash = "f1f12d62", vanilla = true },
        reward = { it = "Sì, è tempo di addestrarti...", enHash = "97f7e155", vanilla = true },
    },
    [6921] = {
        title = { it = "Tra le rovine", enHash = "89a69019", vanilla = true },
        text = { it = "Il Martello del Crepuscolo si è insediato nelle Moonshrine Ruins delle Blackfathom Deeps. La sua presenza non può che costringere gli elementi a lavorare contro di noi. Se non lo fermiamo, questa regione sarà sua per sempre.\n\n$N, va' a Blackfathom e trova la Fathom Stone delle rovine; dovrebbe essere lì vicino, nell'acqua. Dentro c'è un Fathom Core, un congegno che, letto come si deve, racconta la storia di tutta l'attività elementale. Se l'avrò io, io e il Circolo della Terra potremo forse fare qualcosa per fermarlo!", enHash = "f167810f", vanilla = true },
        objectives = { it = "Porta il Fathom Core a Je'neu Sancrea, allo Zoram'gar Outpost, in Ashenvale.", enHash = "ee0f4063", vanilla = true },
        progress = { it = "Sei $Griuscito:riuscita; a individuare il Fathom Core? Senza, non avremo idea di cosa stia combinando esattamente il Martello del Crepuscolo laggiù.", enHash = "2ea745e4", vanilla = true },
        reward = { it = "È esattamente quello che mi serve! Un Fathom Core è una fonte incredibile di informazioni, da cui potremo ricavare molto di buono. Qualunque cosa stia combinando il Martello del Crepuscolo là dentro — e credimi quando dico che non è niente di buono — io e i miei compagni ora la scopriremo.\n\nOggi qui hai fatto bene; il Circolo della Terra ti guarda con favore per averci aiutato. Hai aiutato anche l'Orda tutta, e di questo dovresti essere $Gfiero:fiera;.", enHash = "b33c5d7e", vanilla = true },
    },
    [6922] = {
        title = { it = "Baron Aquanis", enHash = "f663acee", vanilla = true },
        text = { it = "L'elementale dell'acqua sconfitto ha lasciato uno strano globo d'acqua. Immagini che l'oggetto alimentasse in qualche modo la bestia. Dentro il globo sciaborda un'acqua dall'aspetto putrido. Il globo in sé sembra impermeabile a qualsiasi forza fisica.\n\nSe c'è qualcuno che può venire a capo di questo oggetto, è Je'neu Sancrea del Circolo della Terra. Si trova allo Zoram'gar Outpost dell'Orda, in Ashenvale.", enHash = "5d84f665", vanilla = true },
        objectives = { it = "Porta lo Strange Water Globe a Je'neu Sancrea, allo Zoram'gar Outpost, in Ashenvale.", enHash = "e80212f5", vanilla = true },
        progress = { it = "Ah, ciao di nuovo, $N. Stavo giusto leggendo le onde del mare, come faccio sempre. Cosa ti porta all'avamposto?", enHash = "df2d03e2", vanilla = true },
        reward = { it = "Questo... questo è proprio un bel ritrovamento, $N.\n\nDici di averlo preso a Baron Aquanis, a Blackfathom? Baron Aquanis è considerato da tempo una potenza elementale corrotta; questo globo dimostrerà che cosa esattamente lo abbia corrotto. Non sarebbe una sorpresa scoprire che è stato il Martello del Crepuscolo, ma i nostri studi mostreranno anche come ci è riuscito.\n\nHai fatto bene a portarmelo. Ti prego — prendi questo, insieme ai più calorosi saluti del Circolo della Terra.", enHash = "f539aa21", vanilla = true },
    },
    [6961] = {
        title = { it = "Great-father Winter è qui!", enHash = "106efb32", vanilla = true },
        text = { it = "Che la tua Vigilia di Grande Inverno sia meravigliosa, $Gamico:amica;! Non dimenticare di salutare Greatfather Winter! Se quest'anno sei $Gstato:stata; $Gbuono:buona;, il giorno della Vigilia di Grande Inverno riceverai delle leccornie meravigliose. Mi raccomando, digli cosa speri di ricevere quest'anno!\n\nE ricordati anche di fare scorta di leccornie da regalare a chi quest'anno è stato buono. Abbiamo un'ottima scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina della Smokywood Pastures!", enHash = "af051d93", vanilla = true },
        objectives = { it = "Parla con Greatfather Winter; si trova vicino ai banchi della Smokywood Pastures, a Orgrimmar.", enHash = "70dc2ec8", vanilla = true },
        reward = { it = "Oh, oh, salve. Sono Greatfather Winter, e io, per gentile concessione della brava gente della Smokywood Pastures... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina della Smokywood Pastures\"... vorrei augurarti una fantastica Vigilia di Grande Inverno.\n\nSe quest'anno sei $Gstato:stata; $Gbuono:buona;, forse riceverai delle leccornie dalla Smokywood Pastures come regalo per la Vigilia di Grande Inverno. Evviva.", enHash = "e735a1d7", vanilla = true },
    },
    [6962] = {
        title = { it = "Dolcetti per Great-father Winter", enHash = "70c0bd6b", vanilla = true },
        text = { it = "Ehi, puoi fare un favore a Greatfather Winter, ehm, $Gpiccolo:piccola;?\n\nNon per parlare di me in terza persona senza motivo, ma Greatfather Winter è impegnato in questa faccenda da tutto il giorno, e un dolcetto gli farebbe proprio bene. Qualche biscotto di pan di zenzero e del latte freddo per mandarli giù sarebbero proprio l'ideale. Pensi di poter fare un piacere a Greatfather e procurarmene un po'?", enHash = { "c783cef9", "9793b69f" }, vanilla = true },
        objectives = { it = "Porta 5 Gingerbread Cookie e un Ice Cold Milk a Greatfather Winter, a Orgrimmar.", enHash = "fe325370", vanilla = true },
        progress = { it = "Tutto questo parlare di dolcetti mi ha fatto venire voglia. Mmmm... biscotti di pan di zenzero e latte...", enHash = "40517d86", vanilla = true },
        reward = { it = "Sei proprio un bell'aiuto per il vecchio Greatfather Winter, $N. Buona Vigilia di Grande Inverno.\n\nEcco una cosetta... sai, per il disturbo.", enHash = "65a5a343", vanilla = true },
    },
    [6963] = {
        title = { it = "Le leccornie rubate della Vigilia di Grande Inverno", enHash = "24ca5e25", vanilla = true },
        text = { it = "Senti... non per rovinare la magia della festa, ma alla Smokywood Pastures farebbe comodo un po' d'aiuto: quello che di solito date voi avventurieri.\n\nManca un carico importante di leccornie che doveva rifornirci per la festa, e adesso manca anche l'agente della Smokywood Pastures che avevamo mandato a cercarlo! Ti prego: il carico è stato segnalato l'ultima volta nelle Alterac Mountains, ed è lì che il nostro uomo è andato a cercarlo.\n\nVedi se sono tutti e due là, sani e salvi!", enHash = "079c2ce0", vanilla = true },
        objectives = { it = "Trova l'investigatore della Smokywood Pastures scomparso nelle regioni innevate delle Alterac Mountains.", enHash = "41e61c30", vanilla = true },
        reward = { it = "M-m-mi senti! Sia r-r-ringraziato il b-b-bilancio!\n\nNon sono davvero un p-p-pupazzo di neve: mi ch-ch-chiamo Sacks e l-l-lavoro per la f-f-filiale di Orgrimmar della Smokywood Pastures... Mi hanno m-m-mandato qui a cercare un p-p-pacco scomparso, quando sono stato attaccato da una c-c-creatura che non avevo mai v-v-visto p-p-prima!\n\nChe f-f-freddo...", enHash = "3ef62dbb", vanilla = true },
    },
    [6964] = {
        title = { it = "Il senso della festa", enHash = "7b2b2416", vanilla = true },
        text = { it = "Doni, leccornie, regali... bah, dico io!\n\nQuei goblin inquinano il vero significato di questa ricorrenza: la Vigilia di Grande Inverno. È un tempo di rinascita; la terra dorme sotto una coltre di neve portata da Greatfather Winter, che NON è quello sciocco pasticcione vestito di rosso laggiù!\n\nSe vuoi scoprire da te che cos'è davvero la Vigilia, chiedi a Sagorne Creststrider. Sono sicuro che sarà sorpreso che a qualcuno importi della storia più che ricevere regali.", enHash = "ae5f3f69", vanilla = true },
        objectives = { it = "Parla della Vigilia di Grande Inverno con Sagorne Creststrider, nella Valley of Wisdom di Orgrimmar.", enHash = "4ebad460", vanilla = true },
        reward = { it = "La Vigilia di Grande Inverno, dici? Ahimè, un tempo per noi tauren aveva un significato più profondo. Oggi sembra che altri abbiano trasformato la leggenda di questa stagione di rinascita in qualcosa che serve a vendere dolciumi e regali.\n\nNon c'è da stupirsi che Furmund sia amareggiato per un cambiamento del genere. Lui e altri tauren come lui si aggrappano al nostro passato come a uno stendardo di guerra. Anche se credo che un po' di festa faccia sempre bene, è importante ricordare le origini della Vigilia.", enHash = "cb4a4af5", vanilla = true },
    },
    [6981] = {
        title = { it = "La scheggia luminosa", enHash = "2b105dc4", vanilla = true },
        text = { it = "La scheggia è di un verde brillante e, pur essendo solida, sotto la superficie sembra muoversi qualcosa come fumo. Non riesci a smettere di fissare le profondità del cristallo; e allo stesso tempo sai che c'è qualcosa di molto inquietante in esso.\n\nForse dovresti vedere se a Ratchet c'è qualcuno che può dirti di più su questa strana scheggia.", enHash = "5317e248", vanilla = true },
        objectives = { it = "Va' a Ratchet per trovare qualcuno che possa dirti di più sulla scheggia luminosa.\n\nPoi consegna la scheggia dove ti verrà indicato.", enHash = "f3025413", vanilla = true },
        progress = { it = "Salve, $R. Cosa posso fare per te?", enHash = "4bbf824f", vanilla = true },
        reward = { it = "Oh... non ho mai visto niente di simile...", enHash = "72ee20aa", vanilla = true },
    },
    [6983] = {
        title = { it = "Che cattivone...", enHash = "387c0e7f", vanilla = true },
        text = { it = "Una c-c-creatura chiamata \"The Abominable Greench\" è quella che ha r-r-rubato il nostro carico di l-l-leccornie, $N. Ma sta' $Gattento:attenta;! È l-l-lui che mi ha ridotto in questo p-p-pasticcio di neve!\n\nTi s-s-servirà un po' d'aiuto per a-a-affrontarlo. L'ho visto g-g-girare dappertutto dove ci sono gli y-y-yeti; di s-s-sicuro è qui da q-q-qualche parte! T-t-trova le leccornie, $N, riportale alla Smokywood Pastures a Orgrimmar e d-d-di' che bisogna s-s-scongelarmi!", enHash = "88b3b787", vanilla = true },
        objectives = { it = "Trova e riporta gli Stolen Treats a Kaymard Copperpinch, a Orgrimmar. L'ultima volta si pensava che li avesse l'Abominable Greench, che si trova da qualche parte nelle regioni innevate delle Alterac Mountains.", enHash = "0752c927", vanilla = true },
        progress = { it = "$N, la nostra Vigilia di Grande Inverno sarà rovinata senza quelle leccornie per rifornirci! Lo stesso Graccu non potrà dividere i suoi deliziosi pasticci di carne con tutti i bambini e le bambine buoni, quest'anno...", enHash = "d92a6b4d", vanilla = true },
        reward = { it = "L'hai trovato! Hai salvato la Vigilia di Grande Inverno della Smokywood Pasture!\n\nPovero Sacks... manderemo di sicuro una squadra laggiù per trovare un modo di scongelarlo. Speriamo che torni in tempo per il giorno della Vigilia; però dovrà recuperare le ore di lavoro perse. Comunque, niente di tutto questo sarebbe possibile senza di te!", enHash = "78be9f91", vanilla = true },
    },
    [6984] = {
        title = { it = "Un grazie dalla Smokywood Pastures!", enHash = "5e57979d", vanilla = true },
        text = { it = "Noi della Smokywood Pastures ti siamo grati per aver recuperato le leccornie rubate, $N. Per questo vorremmo offrirti un regalo speciale... consegnato nientemeno che da Great-father Winter in persona!\n\nPer favore, parla con Great-father Winter: ti darà il tuo regalo della Vigilia di Grande Inverno da parte di noi della Smokywood Pastures. Dalla nostra fattoria alla tua tavola, è sempre la bontà genuina della Smokywood Pastures... grazie a te, naturalmente!", enHash = "f17a49bf", vanilla = true },
        objectives = { it = "Parla con Great-father Winter, a Orgrimmar.", enHash = "731ce13a", vanilla = true },
        reward = { it = "Oh, oh, salve, $Gavventuriero:avventuriera;!\n\nI goblin mi hanno detto che in queste feste ti sei $Gguadagnato:guadagnata; un regalo speciale, e sono lieto di dartelo. Eccolo qui: che la tua Vigilia di Grande Inverno sia meravigliosa, questa e tutte quelle che verranno.", enHash = "470194eb", vanilla = true },
    },
    [7021] = {
        title = { it = "Great-father Winter è qui!", enHash = "106efb32", vanilla = true },
        text = { it = "Che la tua Vigilia di Grande Inverno sia meravigliosa, $Gamico:amica;! Non dimenticare di salutare Greatfather Winter, che ora si trova a Orgrimmar! Se quest'anno sei $Gstato:stata; $Gbuono:buona;, il giorno della Vigilia di Grande Inverno riceverai delle leccornie meravigliose. Mi raccomando, digli cosa speri di ricevere quest'anno!\n\nE ricordati anche di fare scorta di leccornie da regalare a chi quest'anno è stato buono. Abbiamo un'ottima scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina della Smokywood Pastures!", enHash = "cfe1a608", vanilla = true },
        objectives = { it = "Parla con Greatfather Winter; si trova vicino ai banchi della Smokywood Pastures, a Orgrimmar.", enHash = "70dc2ec8", vanilla = true },
        reward = { it = "Oh, oh, salve. Sono Greatfather Winter, e io, per gentile concessione della brava gente della Smokywood Pastures... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina della Smokywood Pastures\"... vorrei augurarti una fantastica Vigilia di Grande Inverno.\n\nSe quest'anno sei $Gstato:stata; $Gbuono:buona;, forse riceverai delle leccornie dalla Smokywood Pastures come regalo per la Vigilia di Grande Inverno. Evviva.", enHash = "38ffd035", vanilla = true },
    },
    [7022] = {
        title = { it = "Greatfather Winter è qui!", enHash = "be479ebf", vanilla = true },
        text = { it = "Che la tua Vigilia di Grande Inverno sia meravigliosa, $Gamico:amica;! Non dimenticare di salutare Greatfather Winter! Se quest'anno sei $Gstato:stata; $Gbuono:buona;, il giorno della Vigilia di Grande Inverno riceverai delle leccornie meravigliose. Mi raccomando, digli cosa speri di ricevere quest'anno!\n\nE ricordati anche di fare scorta di leccornie da regalare a chi quest'anno è stato buono. Abbiamo un'ottima scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina della Smokywood Pastures!", enHash = "af051d93", vanilla = true },
        objectives = { it = "Parla con Greatfather Winter; si trova vicino ai banchi della Smokywood Pastures, a Ironforge.", enHash = "1d9401f5", vanilla = true },
        reward = { it = "Oh, oh, salve. Sono Greatfather Winter, e io, per gentile concessione della brava gente della Smokywood Pastures... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina della Smokywood Pastures\"... vorrei augurarti una fantastica Vigilia di Grande Inverno.\n\nSe quest'anno sei $Gstato:stata; $Gbuono:buona;, forse riceverai delle leccornie dalla Smokywood Pastures come regalo per la Vigilia di Grande Inverno. Evviva.", enHash = "38ffd035", vanilla = true },
    },
    [7023] = {
