    [7024] = {
        title = { it = "Great-father Winter è qui!", enHash = "106efb32", vanilla = true },
        text = { it = "Che la tua Vigilia di Grande Inverno sia meravigliosa, $Gamico:amica;! Non dimenticare di salutare Greatfather Winter, che ora si trova a Orgrimmar! Se quest'anno sei $Gstato:stata; $Gbuono:buona;, il giorno della Vigilia di Grande Inverno riceverai delle leccornie meravigliose. Mi raccomando, digli cosa speri di ricevere quest'anno!\n\nE ricordati anche di fare scorta di leccornie da regalare a chi quest'anno è stato buono. Abbiamo un'ottima scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina della Smokywood Pastures!", enHash = "cfe1a608", vanilla = true },
        objectives = { it = "Parla con Greatfather Winter; si trova vicino ai banchi della Smokywood Pastures, a Orgrimmar.", enHash = "70dc2ec8", vanilla = true },
        reward = { it = "Oh, oh, salve. Sono Greatfather Winter, e io, per gentile concessione della brava gente della Smokywood Pastures... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina della Smokywood Pastures\"... vorrei augurarti una fantastica Vigilia di Grande Inverno.\n\nSe quest'anno sei $Gstato:stata; $Gbuono:buona;, forse riceverai delle leccornie dalla Smokywood Pastures come regalo per la Vigilia di Grande Inverno. Evviva.", enHash = "e735a1d7", vanilla = true },
    },
    [7025] = {
        title = { it = "Dolcetti per Greatfather Winter", enHash = "cdf91dba", vanilla = true },
        text = { it = "Ehi, puoi fare un favore a Greatfather Winter, ehm, $Gpiccolo:piccola;?\n\nNon per parlare di me in terza persona senza motivo, ma Greatfather Winter è impegnato in questa faccenda da tutto il giorno, e un dolcetto gli farebbe proprio bene. Qualche biscotto di pan di zenzero e del latte freddo per mandarli giù sarebbero proprio l'ideale. Pensi di poter fare un piacere a Greatfather e procurarmene un po'?", enHash = { "c783cef9", "9793b69f" }, vanilla = true },
        objectives = { it = "Porta 5 Gingerbread Cookie e un Ice Cold Milk a Greatfather Winter, a Ironforge.", enHash = "aaea269d", vanilla = true },
        progress = { it = "Tutto questo parlare di dolcetti mi ha fatto venire voglia. Mmmm... biscotti di pan di zenzero e latte...", enHash = "40517d86", vanilla = true },
        reward = { it = "Sei proprio un bell'aiuto per il vecchio Greatfather Winter, $N. Buona Vigilia di Grande Inverno.\n\nEcco una cosetta... sai, per il disturbo.", enHash = "65a5a343", vanilla = true },
    },
    [7042] = {
        title = { it = "Le leccornie rubate della Vigilia di Grande Inverno", enHash = "24ca5e25", vanilla = true },
        text = { it = "Senti... non per rovinare la magia della festa, ma alla Smokywood Pastures farebbe comodo un po' d'aiuto: quello che di solito date voi avventurieri.\n\nManca un carico importante di leccornie che doveva rifornirci per la festa, e adesso manca anche l'agente della Smokywood Pastures che avevamo mandato a cercarlo! Ti prego: il carico è stato segnalato l'ultima volta nelle Alterac Mountains, ed è lì che il nostro uomo è andato a cercarlo.\n\nVedi se sono tutti e due là, sani e salvi!", enHash = "079c2ce0", vanilla = true },
        objectives = { it = "Trova l'investigatore della Smokywood Pastures scomparso nelle regioni innevate delle Alterac Mountains.", enHash = "41e61c30", vanilla = true },
        reward = { it = "M-m-mi senti! Sia r-r-ringraziato il b-b-bilancio!\n\nNon sono davvero un p-p-pupazzo di neve: mi ch-ch-chiamo Sacks e l-l-lavoro per la f-f-filiale di Ironforge della Smokywood Pastures... Mi hanno m-m-mandato qui a cercare un p-p-pacco scomparso, quando sono stato attaccato da una c-c-creatura che non avevo mai v-v-visto p-p-prima!\n\nChe f-f-freddo...", enHash = "98635bee", vanilla = true },
    },
    [7043] = {
        title = { it = "Che cattivone...", enHash = "387c0e7f", vanilla = true },
        text = { it = "Una c-c-creatura chiamata \"The Abominable Greench\" è quella che ha r-r-rubato il nostro carico di l-l-leccornie, $N. Ma sta' $Gattento:attenta;! È l-l-lui che mi ha ridotto in questo p-p-pasticcio di neve!\n\nTi s-s-servirà un po' d'aiuto per a-a-affrontarlo. L'ho visto g-g-girare dappertutto dove ci sono gli y-y-yeti; di s-s-sicuro è qui da q-q-qualche parte! T-t-trova le leccornie, $N, riportale alla Smokywood Pastures a Ironforge e d-d-di' che bisogna s-s-scongelarmi!", enHash = "bd1aa97a", vanilla = true },
        objectives = { it = "Trova e riporta gli Stolen Treats a Wulmort Jinglepocket, a Ironforge. L'ultima volta si pensava che li avesse l'Abominable Greench, che si trova da qualche parte nelle regioni innevate delle Alterac Mountains.", enHash = "df16d6d1", vanilla = true },
        progress = { it = "$N, la nostra Vigilia di Grande Inverno sarà rovinata senza quelle leccornie per rifornirci! Lo stesso Graccu non potrà dividere i suoi deliziosi pasticci di carne con tutti i bambini e le bambine buoni, quest'anno...", enHash = "d92a6b4d", vanilla = true },
        reward = { it = "L'hai trovato! Hai salvato la Vigilia di Grande Inverno della Smokywood Pasture!\n\nPovero Sacks... manderemo di sicuro una squadra laggiù per trovare un modo di scongelarlo. Speriamo che torni in tempo per il giorno della Vigilia; però dovrà recuperare le ore di lavoro perse. Comunque, niente di tutto questo sarebbe possibile senza di te!", enHash = "78be9f91", vanilla = true },
    },
    [7045] = {
        title = { it = "Un grazie dalla Smokywood Pastures!", enHash = "5e57979d", vanilla = true },
        text = { it = "Noi della Smokywood Pastures ti siamo grati per aver recuperato le leccornie rubate, $N. Per questo vorremmo offrirti un regalo speciale... consegnato nientemeno che da Greatfather Winter in persona!\n\nPer favore, parla con Greatfather Winter: ti darà il tuo regalo della Vigilia di Grande Inverno da parte di noi della Smokywood Pastures. Dalla nostra fattoria alla tua tavola, è sempre la bontà genuina della Smokywood Pastures... grazie a te, naturalmente!", enHash = "1c8d0a81", vanilla = true },
        objectives = { it = "Parla con Greatfather Winter, a Ironforge.", enHash = "4e7fc412", vanilla = true },
        reward = { it = "Oh, oh, salve, $Gavventuriero:avventuriera;!\n\nI goblin mi hanno detto che in queste feste ti sei $Gguadagnato:guadagnata; un regalo speciale, e sono lieto di dartelo. Eccolo qui: che la tua Vigilia di Grande Inverno sia meravigliosa, questa e tutte quelle che verranno.", enHash = "470194eb", vanilla = true },
    },
    [7061] = {
        title = { it = "The Feast of Winter Veil", enHash = "5355ac70", vanilla = true },
        text = { it = "Ecco: se vuoi saperne di più sulla Vigilia di Grande Inverno, leggi questo libro. Anche se credo che il nostro modo di intendere la leggenda sia quello giusto, sono abbastanza studioso di leggende da apprezzare che tutte le informazioni siano raccolte in un'unica fonte.\n\nQuando avrai finito, porta il libro a Cairne Bloodhoof, a Thunder Bluff. So per certo che gli farà piacere sapere che altri si sono interessati alla tradizione del nostro popolo.", enHash = "e7800bd9", vanilla = true },
        objectives = { it = "Leggi pure il libro, \"The Feast of Winter Veil\", per saperne di più sulla festa. Quando avrai finito, consegnalo a Cairne Bloodhoof, a Thunder Bluff.", enHash = "0b391ff5", vanilla = true },
        progress = { it = "Ti do il benvenuto a Mulgore e nella nostra umile comunità di Thunder Bluff, $Gamico:amica;. Mi interesso sempre a chi sceglie di interessarsi al regno, alla sua gente e alla sua tradizione. È per questo che sei qui davanti a me?", enHash = "3ec59f78", vanilla = true },
        reward = { it = "Le leggende e la tradizione legate alla Vigilia di Grande Inverno sono sbiadite, nel corso degli anni, dal primo piano del pensiero comune. Sì, so che i goblin stanno aiutando a far rivivere la festa per i loro scopi, ma il fatto che il nostro popolo ci rifletta, almeno in qualche forma, aiuta a mantenere viva questa tradizione.\n\nIl tuo desiderio di andare oltre le cose materiali e di conoscere il nostro passato è una qualità ammirevole, giovane $C. Rendo omaggio alla tua saggezza.", enHash = "78bed6c2", vanilla = true },
    },
    [7062] = {
        title = { it = "Il senso della festa", enHash = "7b2b2416", vanilla = true },
        text = { it = "Doni, leccornie, regali... bah, dico io!\n\nQuei goblin inquinano il vero significato di questa ricorrenza: la Vigilia di Grande Inverno. È un tempo di rinascita; la terra dorme sotto una coltre di neve portata da Greatfather Winter, che NON è quello sciocco pasticcione vestito di rosso laggiù!\n\nSe vuoi scoprire da te che cos'è davvero la Vigilia, chiedi a Historian Karnik, alla Lega degli Esploratori. Sono sicuro che sarà sorpreso che a qualcuno importi della storia più che ricevere regali.", enHash = "9c6fd9b1", vanilla = true },
        objectives = { it = "Parla della Vigilia di Grande Inverno con Historian Karnik, alla Lega degli Esploratori, a Ironforge.", enHash = "43873f16", vanilla = true },
        reward = { it = "La Vigilia di Grande Inverno, dici? Ahimè, un tempo per noi nani aveva un significato più profondo. Oggi sembra che altri abbiano trasformato la leggenda di Greatfather Winter in qualcosa che serve a vendere dolciumi e regali.\n\nNon c'è da stupirsi che Goli sia amareggiato per un cambiamento del genere. Lui e altri nani come lui si aggrappano al nostro passato come a uno stendardo di guerra. Anche se credo che un po' di festa faccia sempre bene, è importante ricordare le origini della Vigilia.", enHash = "a263e7bd", vanilla = true },
    },
    [7063] = {
        title = { it = "The Feast of Winter Veil", enHash = "5355ac70", vanilla = true },
        text = { it = "Ecco: se vuoi saperne di più sulla Vigilia di Grande Inverno, leggi questo libro. Anche se credo che il nostro modo di intendere la leggenda sia quello giusto, sono abbastanza studioso da apprezzare che tutte le informazioni siano raccolte in un'unica fonte.\n\nQuando avrai finito, porta il libro a King Magni Bronzebeard. So per certo che gli farà piacere sapere che altri si sono interessati alle leggende più antiche.", enHash = "5919aeac", vanilla = true },
        objectives = { it = "Leggi pure il libro, \"The Feast of Winter Veil\", per saperne di più sulla festa. Quando avrai finito, consegnalo a King Magni Bronzebeard, a Ironforge.", enHash = "5c48e24a", vanilla = true },
        progress = { it = "Ti do il benvenuto nel regno di Ironforge, $Gamico:amica;. Mi interesso sempre a chi sceglie di interessarsi al regno, alla sua gente e alla sua tradizione. È per questo che sei qui davanti a me?", enHash = "b27b9d4a", vanilla = true },
        reward = { it = "Le leggende e la tradizione legate alla Vigilia di Grande Inverno sono sbiadite, nel corso degli anni, dal primo piano del pensiero comune. Riconosco che i goblin stanno aiutando a far rivivere la festa per i loro scopi, ma il fatto che i cittadini ci pensino, almeno in qualche forma, aiuta a mantenere viva questa tradizione.\n\nIl tuo desiderio di andare oltre le cose materiali e di conoscere il nostro passato è una qualità ammirevole, giovane $C. Rendo omaggio alla tua erudizione.", enHash = "458f15f3", vanilla = true },
    },
    [7321] = {
        title = { it = "Soothing Turtle Bisque", enHash = "2ec79d74", vanilla = true },
        text = { it = "Chi dice che i non morti non sanno niente di cucina? Prendi la mia ricetta segreta della Turtle Bisque, per esempio. Ho conosciuto gente che tornerebbe dalla morte solo per gustarne una ciotola! Eh, eh...\n\nA proposito, ultimamente non ho potuto prepararne. Andavo di persona al Lake Lordamere a cacciare gli Snapjaw, quelle brutte bestie, ma non riesco a staccarmi dal mio lavoro qui.\n\nSe mi porti un po' di Turtle Meat dagli Snapjaw e delle Soothing Spices, ti mostrerò come si fa!", enHash = "d48f6521", vanilla = true },
        objectives = { it = "Porta 10 pezzi di Turtle Meat e delle Soothing Spices a Christoph Jeffcoat, a Tarren Mill.", enHash = "00d10171", vanilla = true },
        progress = { it = "Hai avuto fortuna con gli ingredienti? Te lo dico io, quei vermi dell'Alleanza sono fin troppi da queste parti ormai... Secondo me si sono già avvicinati fin troppo...", enHash = "da45d51b", vanilla = true },
        reward = { it = "La mia Soothing Turtle Bisque ti terrà al caldo in una notte fredda... se ti importa di queste cose.", enHash = "5a68593f", vanilla = true },
    },
    [7383] = {
        title = { it = "La corona della terra", enHash = "10f87d9b", vanilla = true },
        text = { it = "Non tutto andava bene a Teldrassil, però. I piani che Staghelm aveva preparato con cura per il nuovo Albero del Mondo avevano dato i frutti sperati, ma c'era un piccolo problema, un problema a cui si possono attribuire molti dei guai di Teldrassil.\n\nNon entrerò però ancora in quell'argomento. Devi visitare l'ultimo pozzo lunare, a nord-ovest, nell'Oracle Glade. Sotto i rami dell'Oracle Tree si trova il primo e più potente dei nostri pozzi. Riportami una fiala della sua acqua.", enHash = "4d24c65a", vanilla = true },
        objectives = { it = "Riempi l'Amethyst Phial e riportala a Corithras Moonrage, a Dolanaar.", enHash = "5b27c34f", vanilla = true },
        progress = { it = "Insieme ai druidi, l'Oracle Tree e l'arcidruido hanno osservato con attenzione la crescita di Teldrassil. Ma, per quanto abbiamo una nuova casa, le nostre vite immortali non sono state restituite.", enHash = "b069de5d", vanilla = true },
        reward = { it = "Essere alla presenza dell'Oracle Tree... è quasi come sentire la saggezza prendere forma. Lascia che continui il racconto...\n\nCresciuto Teldrassil, l'arcidruido si rivolse ai draghi per le loro benedizioni, come i draghi avevano fatto con Nordrassil nei tempi antichi. Ma Nozdormu, Signore del Tempo, rifiutò di dare la sua benedizione, rimproverando il druido per la sua arroganza. D'accordo con Nozdormu, anche Alexstrasza rifiutò Staghelm e, senza la sua benedizione, la crescita di Teldrassil è stata imperfetta e imprevedibile...", enHash = "39723cb5", vanilla = true },
    },
    [7495] = {
        title = { it = "Vittoria per l'Alleanza", enHash = "df5a254b", vanilla = true },
        text = { it = "Hai compiuto l'impossibile. La madre della covata del Black Dragonflight giace morta ai tuoi piedi. Prendi la sua testa e presentala al Gran Signore.", enHash = "a726d17e", vanilla = true },
        objectives = { it = "Porta la Head of Onyxia a Highlord Bolvar Fordragon, a Stormwind.", enHash = "891cbb99", vanilla = true },
        progress = { it = "Per la barba di Uther!", enHash = "398fcbf8", vanilla = true },
        reward = { it = "Per tanti anni sono stato prigioniero del suo sguardo ammaliatore. Finalmente vedo fatta giustizia e restituito l'onore di Stormwind! Oggi celebriamo questa gloriosa vittoria!", enHash = "f9e8746c", vanilla = true },
    },
    [7496] = {
        title = { it = "Tempi di festa", enHash = "900b64ff", vanilla = true },
        text = { it = "Cerca Major Mattingly nella Valley of Heroes, $N. Ti starà aspettando...", enHash = "f609f3b4", vanilla = true },
        objectives = { it = "Cerca Major Mattingly nella Valley of Heroes.", enHash = "0b34659a", vanilla = true },
        reward = { it = "A pochi è concessa una cerimonia simile, $N. Ti prego, scegli la tua ricompensa, così possiamo cominciare i festeggiamenti.", enHash = "94aaf804", vanilla = true },
    },
    [7497] = {
        title = { it = "Il viaggio è appena cominciato", enHash = "f800bc1e", vanilla = true },
        reward = { it = "$GUn ammazzadraghi e un esperto conciatore:Un'ammazzadraghi e un'esperta conciatrice;? Non smetti di stupire, $Geroe:eroina;. Sono lusingato.\n\nTi prego, accetta quello che sto per insegnarti. Questa conoscenza ti sarà preziosissima se vorrai distruggere ciò che resta del Black Dragonflight.\n\nCrea il mantello con le scaglie della madre della covata. Proteggerà te e i tuoi alleati dal soffio incendiario del Signore di Blackrock... Nefarian.", enHash = "253ca733", vanilla = true },
    },
    [7541] = {
        title = { it = "Al servizio dell'Orda", enHash = "2d6fa1c3", vanilla = true },
        reward = { it = "Ci vorrà tempo perché i nostri studiosi esaminino il ciondolo che ci hai portato. Ma per il tuo servizio all'Orda vorrei offrirti un piccolo segno di riconoscenza.\n\nGrazie, $N. Le tue azioni fanno onore a te, e a noi.", enHash = "3848d2e7", vanilla = true },
    },
    [7662] = {
        title = { it = "Nuovo kodo — verde acqua", enHash = "963c2840", vanilla = true },
        reward = { it = "Se mi porti il tuo vecchio kodo, te lo cambierò con uno della nuova mandria. Il nuovo kodo sarà veloce quanto il vecchio, ma avrà un aspetto diverso. Puoi guardare i grandi kodo che abbiamo già qui intorno al recinto per vedere tra quali potrai scegliere.", enHash = "3229f829", vanilla = true },
    },
    [7663] = {
        title = { it = "Nuovo kodo — verde", enHash = "3097a59f", vanilla = true },
        reward = { it = "Se mi porti il tuo vecchio kodo, te lo cambierò con uno della nuova mandria. Il nuovo kodo sarà veloce quanto il vecchio, ma avrà un aspetto diverso. Puoi guardare i grandi kodo che abbiamo già qui intorno al recinto per vedere tra quali potrai scegliere.", enHash = "3229f829", vanilla = true },
    },
    [7664] = {
        title = { it = "Sostituzione dell'Ivory Raptor", enHash = "665c595f", vanilla = true },
        reward = { it = "Tu mi porti il tuo vecchio raptor, io ti do uno nuovo con artigli appena affilati! Il nuovo raptor sarà veloce proprio come il tuo vecchio, ma con un aspetto nuovo. Puoi dare un'occhiata ai raptor veloci qui per vedere fra quali potrai scegliere.", enHash = "358538fb", vanilla = true },
    },
    [7665] = {
        title = { it = "Sostituzione del Red Raptor", enHash = "c6623e77", vanilla = true },
        reward = { it = "Tu mi porti il tuo vecchio raptor, io ti do uno nuovo con artigli appena affilati! Il nuovo raptor sarà veloce proprio come il tuo vecchio, ma con un aspetto nuovo. Puoi dare un'occhiata ai raptor veloci qui per vedere fra quali potrai scegliere.", enHash = "358538fb", vanilla = true },
    },
    [7673] = {
        title = { it = "Scambio del Frost Ram", enHash = "6ca507c1", vanilla = true },
        reward = { it = "Tu portami il tuo vecchio ariete, e io te lo cambio con uno del nuovo branco! Il nuovo ariete sarà veloce proprio come il tuo vecchio, ma con un aspetto nuovo. Puoi dare un'occhiata agli arieti veloci qui per vedere fra quali potrai scegliere.", enHash = "e51f0899", vanilla = true },
    },
    [7674] = {
        title = { it = "Scambio del Black Ram", enHash = "91e56e66", vanilla = true },
        reward = { it = "Tu portami il tuo vecchio ariete, e io te lo cambio con uno del nuovo branco! Il nuovo ariete sarà veloce proprio come il tuo vecchio, ma con un aspetto nuovo. Puoi dare un'occhiata agli arieti veloci qui per vedere fra quali potrai scegliere.", enHash = "e51f0899", vanilla = true },
    },
    [7675] = {
        title = { it = "Sostituzione dell'Icy Blue Mechanostrider", enHash = "68ba6e4b", vanilla = true },
        reward = { it = "Se vai ancora in giro su quel vecchio Icy Blue Mechanostrider Mod A, vorrai di sicuro cambiarlo con un modello più nuovo. Il tuo nuovo mechanostrider veloce mantiene tutta la velocità del vecchio, con un aspetto nuovo di zecca. Puoi dare un'occhiata ai mechanostrider veloci qui per vedere fra quali splendidi modelli potrai scegliere.", enHash = "d8326075", vanilla = true },
    },
    [7676] = {
        title = { it = "Sostituzione del White Mechanostrider", enHash = "b617929d", vanilla = true },
        reward = { it = "Se vai ancora in giro su quel vecchio White Mechanostrider Mod A, vorrai di sicuro cambiarlo con un modello più nuovo. Il tuo nuovo mechanostrider veloce mantiene tutta la velocità del vecchio, con un aspetto nuovo di zecca. Puoi dare un'occhiata ai mechanostrider veloci qui per vedere fra quali splendidi modelli potrai scegliere.", enHash = "c2b44ec5", vanilla = true },
    },
    [7781] = {
        title = { it = "Il Signore di Blackrock", enHash = "ebeff237", vanilla = true },
        text = { it = "La vecchia sensazione ritorna. Il gradito fremito della vittoria ti risuona in tutto l'essere. Davanti a te giace la testa monolitica e segnata dalle battaglie di Nefarian. Riportala al tuo Gran Signore, $Gcampione:campionessa;.", enHash = "6265e18c", vanilla = true },
        objectives = { it = "Riporta la Head of Nefarian a Highlord Bolvar Fordragon, a Stormwind.", enHash = "63be7b02", vanilla = true },
        progress = { it = "Inconcepibile!", enHash = "744c6cbb", vanilla = true },
        reward = { it = "Non c'è bisogno che ti si spieghi il significato di ciò che hai fatto, $N. Questo giorno sarà scritto negli annali della storia. Una vittoria come l'Alleanza non ne conosceva da anni, se mai ne ha conosciute!", enHash = "625cf940", vanilla = true },
    },
    [7782] = {
        title = { it = "Il Signore di Blackrock", enHash = "ebeff237", vanilla = true },
        text = { it = "Va' nella Valley of Heroes e parla con Field Marshal Afrasiabi.", enHash = "b60b3367", vanilla = true },
        objectives = { it = "Raggiungi la Valley of Heroes, a Stormwind City, e parla con Field Marshal Afrasiabi.", enHash = "14733a47", vanilla = true },
        reward = { it = "<Field Marshal Afrasiabi si inchina.>\n\nScegli la tua ricompensa, e che i festeggiamenti abbiano inizio!", enHash = "db2adaa8", vanilla = true },
    },
    [7788] = {
        title = { it = "Sconfiggi gli invasori!", enHash = "102f8e97", vanilla = true },
        text = { it = "Oltre questo tunnel troverai un campo di lotta e tumulto, giovane $C. L'Orda continua a decimare la nostra foresta sacra, abbattendo il fogliame sempreverde per alimentare le sue macchine da guerra.\n\nEntra in Warsong Gulch e difendi Silverwing Hold. Respingi le forze invasori dell'Orda!\n\nFa' questo e guadagna un Mark of Honor. Portamelo, $N, e ti ricompenserò.", enHash = "1944fe2c", vanilla = true },
        objectives = { it = "Entra in Warsong Gulch e sconfiggi l'Orda, ottieni un Warsong Gulch Mark of Honor e torna da Sentinel Farsong, al Silverwing Grove.", enHash = "18aeca16", vanilla = true },
        progress = { it = "Hai combattuto in Warsong Gulch e difeso Silverwing Hold?", enHash = "eb9e313f", vanilla = true },
        reward = { it = "Hai dimostrato quanto vali per i nostri sforzi in Warsong Gulch. Continua ad aiutare la causa e portami altri Mark of Honor. Fa' questo, e ti guadagnerai ancora più fiducia da parte nostra.", enHash = "61e49c24", vanilla = true },
    },
    [7789] = {
        title = { it = "Soffoca gli usurpatori Silverwing", enHash = "11a08c6b", vanilla = true },
        text = { it = "Le terre selvagge dell'Ashenvale Forest cederanno alla potenza dell'Orda, $R. Niente di quel che i Silverwing dicono o fanno può fermare il nostro diritto sovrano. Kalimdor appartiene all'Orda. Come osano cercare di impedirci di raccogliere quel che ci spetta!\n\nLascia che l'orgoglio ti gonfi il petto mentre abbatti i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le Silverwing Sentinel e guadagna un Mark of Honor. Torna da me con un Mark simile, $N, e sarai $Gricompensato:ricompensata;.", enHash = "4a3d4b53", vanilla = true },
        objectives = { it = "Entra in Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull, al Mor'shan Base Camp.", enHash = "7112a784", vanilla = true },
        progress = { it = "Il sangue dei nostri nemici è un marchio d'onore. Ce l'hai un marchio simile?", enHash = "4a57fa4f", vanilla = true },
        reward = { it = "<Captain Shatterskull ruggisce in trionfo>\n\nQuanto ancora possono resistere? Quanta altra feccia dell'Alleanza deve perire per mano dell'Orda prima che si ritirino? Solo il tempo lo dirà, $R...", enHash = "cc310d5e", vanilla = true },
    },
    [7791] = {
        title = { it = "Una donazione di lana", enHash = "dc2096af", vanilla = true },
        progress = { it = "Al momento accettiamo donazioni di Wool Cloth. Una donazione di sessanta Wool Cloth ti farà guadagnare il pieno riconoscimento di Stormwind per il tuo gesto generoso. Con le scorte di lana che abbiamo, da te ci bastano sessanta pezzi in tutto: il resto dovremmo riuscire a procurarcelo da altri nel regno per portare avanti la raccolta.\n\nSe hai con te i sessanta Wool Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.", enHash = "2ed94fe5", vanilla = true },
        reward = { it = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!", enHash = "4abad10f", vanilla = true },
    },
    [7792] = {
        title = { it = "Una donazione di lana", enHash = "dc2096af", vanilla = true },
        progress = { it = "Al momento accettiamo donazioni di Wool Cloth. Una donazione di sessanta Wool Cloth ti farà guadagnare il pieno riconoscimento di Darnassus per la tua generosità. Con le scorte di lana che abbiamo, da te ci bastano sessanta pezzi in tutto: il resto dovremmo riuscire a procurarcelo da altri nel regno per portare avanti la raccolta.\n\nSe hai con te i sessanta Wool Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.", enHash = "8bdf6e70", vanilla = true },
        reward = { it = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!", enHash = "4abad10f", vanilla = true },
    },
    [7793] = {
        title = { it = "Una donazione di seta", enHash = "dc1eae4f", vanilla = true },
        progress = { it = "Come per quasi tutti gli altri tessuti, le nostre scorte di seta sono al minimo storico. Con le scorte che abbiamo, da te ci bastano sessanta Silk Cloth in tutto: con l'aiuto di altri dovremmo riuscire a raggiungere l'obiettivo.\n\nUn dono generoso come la seta, aggiungerei, farebbe di certo salire la tua considerazione qui nella comunità! Se hai con te i sessanta Silk Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.", enHash = "d586dc46", vanilla = true },
        reward = { it = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!", enHash = "4abad10f", vanilla = true },
    },
    [7794] = {
        title = { it = "Una donazione di Mageweave", enHash = "b408ff56", vanilla = true },
        progress = { it = "La Mageweave Cloth sta finendo, e il tuo aiuto ci farebbe comodo per rifornire le nostre scorte! Contando sulla comunità nel suo insieme, da te ci servirebbe solo una donazione di 60 pezzi di Mageweave Cloth per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata a Stormwind, te lo assicuro!\n\nSe hai con te i sessanta pezzi di Mageweave Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.", enHash = "2dfd3edc", vanilla = true },
        reward = { it = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!", enHash = "4abad10f", vanilla = true },
    },
    [7795] = {
        title = { it = "Una donazione di Runecloth", enHash = "282bd766", vanilla = true },
        progress = { it = "$N, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre ci diamo da fare per ricostituire le nostre riserve, un tipo di stoffa resta scarsissimo: la Runecloth. Ne abbiamo un bisogno disperato, e speriamo che tu possa aiutarci come hai fatto in passato!\n\nSe vuoi, portami tutta la Runecloth di cui puoi fare a meno. Per cominciare accetteremo una sola donazione di sessanta pezzi, e poi vedremo.", enHash = "4a8eb9b4", vanilla = true },
        reward = { it = "Fantastico: la useremo subito, te lo assicuro. Grazie ancora per il tuo aiuto! Senza di te saremmo davvero persi.\n\nCon tutte le donazioni che hai fatto, accetterò volentieri qualsiasi altra donazione di Runecloth vorrai fare in futuro. Passa pure da me, e farò in modo di persona che le tue buone azioni non restino senza riconoscimento!", enHash = "f3dde41f", vanilla = true },
    },
    [7796] = {
        title = { it = "Altra Runecloth", enHash = "a7601267", vanilla = true },
        progress = { it = "Quando sei $Gpronto:pronta; a consegnare la pila di Runecloth, la accetterò.", enHash = "38a2979e", vanilla = true },
        reward = { it = "$N, senza eroi come te che lavorano per la tribù, soffriremmo di sicuro. Grazie per il tuo impegno costante!", enHash = "073e627d", vanilla = true },
    },
    [7798] = {
        title = { it = "Una donazione di seta", enHash = "dc1eae4f", vanilla = true },
        progress = { it = "Come per quasi tutti gli altri tessuti, le nostre scorte di seta sono al minimo storico. Con le scorte che abbiamo, da te ci bastano sessanta Silk Cloth in tutto: con l'aiuto di altri dovremmo riuscire a raggiungere l'obiettivo.\n\nUn dono generoso come la seta, aggiungerei, farebbe di certo salire la tua considerazione qui nella comunità! Se hai con te i sessanta Silk Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.", enHash = "d586dc46", vanilla = true },
        reward = { it = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!", enHash = "0697254d", vanilla = true },
    },
