    [7810] = {
        title = { it = "Arena Master", enHash = "072f299b", vanilla = true },
        text = { it = "Per essere $Gun maestro:una maestra; dell'arena ci vuole di più! Forse il pirata che organizza l'evento a Gurubashi lo saprà!", enHash = "26d147ea", vanilla = true },
        objectives = { it = "Parla con Short John Mithril nella Stranglethorn Arena.", enHash = "08c4dfbc", vanilla = true },
        reward = { it = "Arr, compare! Ottenere un solo monile non basta a fare di te $Gun maestro:una maestra; dell'Arena! Ora è il momento di dimostrare davvero di che tempra sei.", enHash = "085f37c9", vanilla = true },
    },
