    },
    [7822] = {
        title = { it = "Una donazione di Mageweave", enHash = "b408ff56", vanilla = true },
        progress = { it = "La Mageweave Cloth sta finendo, e il tuo aiuto ci farebbe comodo per rifornire le nostre scorte! Contando sulla comunità nel suo insieme, da te ci servirebbe solo una donazione di 60 pezzi di Mageweave Cloth per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata a Thunder Bluff, te lo assicuro!\n\nSe hai con te i sessanta pezzi di Mageweave Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.", enHash = "26e89b5e", vanilla = true },
        reward = { it = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!", enHash = "0697254d", vanilla = true },
    },
    [7823] = {
        title = { it = "Una donazione di Runecloth", enHash = "282bd766", vanilla = true },
        progress = { it = "$N, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre ci diamo da fare per ricostituire le nostre riserve, un tipo di stoffa resta scarsissimo: la Runecloth. Ne abbiamo un bisogno disperato, e speriamo che tu possa aiutarci come hai fatto in passato!\n\nSe vuoi, portami tutta la Runecloth di cui puoi fare a meno. Per cominciare accetteremo una sola donazione di sessanta pezzi, e poi vedremo.", enHash = "4a8eb9b4", vanilla = true },
        reward = { it = "Fantastico: la useremo subito, te lo assicuro. Grazie ancora per il tuo aiuto! Senza di te saremmo davvero persi.\n\nCon tutte le donazioni che hai fatto, accetterò volentieri qualsiasi altra donazione di Runecloth vorrai fare in futuro. Passa pure da me, e farò in modo di persona che le tue buone azioni non restino senza riconoscimento!", enHash = "f3dde41f", vanilla = true },
    },
    [7825] = {
        title = { it = "Altra Runecloth", enHash = "a7601267", vanilla = true },
        progress = { it = "Quando sei $Gpronto:pronta; a consegnare la pila di Runecloth, la accetterò.", enHash = "38a2979e", vanilla = true },
        reward = { it = "$N, senza eroi come te che lavorano per la tribù, soffriremmo di sicuro. Grazie per il tuo impegno costante!", enHash = "073e627d", vanilla = true },
    },
    [7826] = {
        title = { it = "Una donazione di lana", enHash = "dc2096af", vanilla = true },
        progress = { it = "Al momento accettiamo donazioni di Wool Cloth. Una donazione di sessanta Wool Cloth ti farà guadagnare il pieno riconoscimento di Orgrimmar per il tuo gesto generoso. Con le scorte di lana che abbiamo, da te ci bastano sessanta pezzi in tutto: il resto dovremmo riuscire a procurarcelo da altri nel regno per portare avanti la raccolta.\n\nSe hai con te i sessanta Wool Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.", enHash = "0ecf04aa", vanilla = true },
        reward = { it = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!", enHash = "4abad10f", vanilla = true },
    },
    [7827] = {
        title = { it = "Una donazione di seta", enHash = "dc1eae4f", vanilla = true },
        progress = { it = "Come per quasi tutti gli altri tessuti, le nostre scorte di seta sono al minimo storico. Con le scorte che abbiamo, da te ci bastano sessanta Silk Cloth in tutto: con l'aiuto di altri dovremmo riuscire a raggiungere l'obiettivo.\n\nUn dono generoso come la seta, aggiungerei, farebbe di certo salire la tua considerazione qui nella comunità! Se hai con te i sessanta Silk Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.", enHash = "d586dc46", vanilla = true },
        reward = { it = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!", enHash = "4abad10f", vanilla = true },
    },
    [7833] = {
        title = { it = "Una donazione di lana", enHash = "dc2096af", vanilla = true },
        progress = { it = "Al momento accettiamo donazioni di Wool Cloth. Una donazione di sessanta Wool Cloth ti farà guadagnare il pieno riconoscimento dei Darkspear Trolls per il tuo gesto generoso. Con le scorte di lana che abbiamo, da te ci bastano sessanta pezzi in tutto: il resto dovremmo riuscire a procurarcelo da altri nel regno per portare avanti la raccolta.\nSe hai con te i sessanta Wool Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.", enHash = "c3b8d914", vanilla = true },
        reward = { it = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!", enHash = "4abad10f", vanilla = true },
    },
    [7834] = {
        title = { it = "Una donazione di seta", enHash = "dc1eae4f", vanilla = true },
        progress = { it = "Come per quasi tutti gli altri tessuti, le nostre scorte di seta sono al minimo storico. Con le scorte che abbiamo, da te ci bastano sessanta Silk Cloth in tutto: con l'aiuto di altri dovremmo riuscire a raggiungere l'obiettivo.\n\nUn dono generoso come la seta, aggiungerei, farebbe di certo salire la tua considerazione qui nella comunità! Se hai con te i sessanta Silk Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.", enHash = "d586dc46", vanilla = true },
        reward = { it = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!", enHash = "4abad10f", vanilla = true },
    },
    [7838] = {
        title = { it = "Gran Maestro dell'Arena", enHash = "c4ed8ed5", vanilla = true },
        progress = { it = "Fermo là, $Gmarinaio d'acqua dolce:marinaia d'acqua dolce;! Portami 12 Arena Master e sarai $GGran Maestro:Gran Maestra; della Gurubashi Arena! Arrrr!", enHash = "32fc54ee", vanilla = true },
        reward = { it = "Hai versato molto sangue sulla sabbia dell'Arena, e mi fa piacere nominarti $GGran Maestro:Gran Maestra; dell'Arena!", enHash = "bdefbb43", vanilla = true },
    },
    [7863] = {
        title = { it = "Sentinel Basic Care Package", enHash = "ba521665", vanilla = true },
        reward = { it = "Hai di sicuro cominciato a dimostrare il tuo valore ai nostri occhi, $N. Come ricompensa, prendi questo pacco di rifornimenti! Dentro trovi razioni e bende utilizzabili solo dentro Warsong Gulch.\n\nContinuando a dimostrare il tuo valore nella Gulch, scoprirai che questi oggetti si potranno anche comprare. Le razioni diventano disponibili quando sei Friendly con noi, le bende quando sei Honored.", enHash = "e74bee05", vanilla = true },
    },
    [7864] = {
        title = { it = "Sentinel Standard Care Package", enHash = "a9847fbe", vanilla = true },
        reward = { it = "Hai di sicuro cominciato a dimostrare il tuo valore ai nostri occhi, $N. Come ricompensa, prendi questo pacco di rifornimenti! Dentro trovi razioni e bende utilizzabili solo dentro Warsong Gulch.\n\nContinuando a dimostrare il tuo valore nella Gulch, scoprirai che questi oggetti si potranno anche comprare. Le razioni diventano disponibili quando sei Friendly con noi, le bende quando sei Honored.", enHash = "e74bee05", vanilla = true },
    },
