    [7868] = {
        title = { it = "Outrider Advanced Care Package", enHash = "e1af9c41", vanilla = true },
        reward = { it = "Hai di sicuro cominciato a dimostrare il tuo valore ai nostri occhi, $N. Come ricompensa, prendi questo pacco di rifornimenti! Dentro trovi razioni e bende utilizzabili solo dentro Warsong Gulch.\n\nContinuando a dimostrare il tuo valore nella Gulch, scoprirai che questi oggetti si potranno anche comprare. Le razioni diventano disponibili quando sei Friendly con noi, le bende quando sei Honored.", enHash = "7e3d2321", vanilla = true },
    },
    [7871] = {
        title = { it = "Sconfiggi gli invasori!", enHash = "102f8e97", vanilla = true },
        text = { it = "Oltre questo tunnel troverai un campo di lotta e tumulto, giovane $C. L'Orda continua a decimare la nostra foresta sacra, abbattendo il fogliame sempreverde per alimentare le sue macchine da guerra.\n\nEntra in Warsong Gulch e difendi Silverwing Hold. Respingi le forze invasori dell'Orda!\n\nFa' questo e guadagna un Mark of Honor. Portamelo, $N, e ti ricompenserò.", enHash = "1944fe2c", vanilla = true },
        objectives = { it = "Entra in Warsong Gulch e sconfiggi l'Orda, ottieni un Warsong Gulch Mark of Honor e torna da Sentinel Farsong, al Silverwing Grove.", enHash = "18aeca16", vanilla = true },
        progress = { it = "Hai combattuto in Warsong Gulch e difeso Silverwing Hold?", enHash = "eb9e313f", vanilla = true },
        reward = { it = "Hai dimostrato quanto vali per i nostri sforzi in Warsong Gulch. Continua ad aiutare la causa e portami altri Mark of Honor. Fa' questo, e ti guadagnerai ancora più fiducia da parte nostra.", enHash = "61e49c24", vanilla = true },
    },
    [7874] = {
        title = { it = "Soffoca gli usurpatori Silverwing", enHash = "11a08c6b", vanilla = true },
        text = { it = "Le terre selvagge dell'Ashenvale Forest cederanno alla potenza dell'Orda, $R. Niente di quel che i Silverwing dicono o fanno può fermare il nostro diritto sovrano. Kalimdor appartiene all'Orda. Come osano cercare di impedirci di raccogliere quel che ci spetta!\n\nLascia che l'orgoglio ti gonfi il petto mentre abbatti i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le Silverwing Sentinel e guadagna un Mark of Honor. Torna da me con un Mark simile, $N, e sarai $Gricompensato:ricompensata;.", enHash = "4a3d4b53", vanilla = true },
        objectives = { it = "Entra in Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull, al Mor'shan Base Camp.", enHash = "7112a784", vanilla = true },
        progress = { it = "Il sangue dei nostri nemici è un marchio d'onore. Ce l'hai un marchio simile?", enHash = "4a57fa4f", vanilla = true },
        reward = { it = "<Captain Shatterskull ruggisce in trionfo>\n\nQuanto ancora possono resistere? Quanta altra feccia dell'Alleanza deve perire per mano dell'Orda prima che si ritirino? Solo il tempo lo dirà, $R...", enHash = "cc310d5e", vanilla = true },
    },
    [7881] = {
        title = { it = "Stivali per il luna park", enHash = "931caa53", vanilla = true },
        progress = { it = "Noi della Darkmoon Faire camminiamo parecchio. Camminiamo da un luogo della fiera all'altro... anzi, non ci vedrai mai stare seduti mentre lavoriamo! Quindi non c'è da stupirsi se consumiamo un sacco di stivali! Ci servono stivali resistenti ed eleganti, e gli Embossed Leather Boots fanno proprio al caso nostro.\n\nTu! Sei $Gun conciatore:una conciatrice;: fammi degli Embossed Leather Boots e ti darò un biglietto della Darkmoon Faire per il lavoro.", enHash = "92f14122", vanilla = true },
        reward = { it = "Grazie, $N. Sono fatti davvero bene. Una lavorazione di prim'ordine! Ecco un biglietto della Darkmoon Faire... divertiti, $Gmio signore:mia signora;.", enHash = { "0710b9ed", "91de8ecb" }, vanilla = true },
    },
    [7882] = {
        title = { it = "Farsetti per il luna park", enHash = "d4e2dccc", vanilla = true },
        progress = { it = "I nostri lavoratori della Faire fanno ben più che spazzare rifiuti e piantare picchetti! Aiutano anche a sorvegliare il luna park quando è in viaggio, e per questo hanno sempre bisogno di buoni farsetti robusti.\n\nSe fai qualche armatura di cuoio resistente e me la porti, farò in modo che arrivi alle persone giuste. E in cambio ti procurerò anche qualche biglietto della Darkmoon Faire.", enHash = "35a1641e", vanilla = true },
        reward = { it = "Ah, hai portato i farsetti. Splendido. Posso chiederti di che animale è la pelle che hai usato? Le cuciture sono fatte molto bene, e la grana del cuoio ha un aspetto rustico. Si vede che sei $Gun artigiano:un'artigiana; di talento!\n\nGrazie, $N, ed ecco i tuoi biglietti.", enHash = "62a24e6f", vanilla = true },
    },
    [7883] = {
        title = { it = "Lo gnomo più grande del mondo!", enHash = "9579e6be", vanilla = true },
        progress = { it = "Yebb Nebblegear vuole aggiungere altri talenti al suo spettacolo, e sta cercando in lungo e in largo lo gnomo più grande del mondo. Conosci qualche gnomo di dimensioni notevoli?\n\nBe', prima ancora di trovare lo gnomo, vuole avere pronto il suo costume. Credo che una Barbaric Harness sarebbe una buona base per il costume: puoi fare qualche Barbaric Harness e portarmele? Fallo, e avrò una pila di biglietti della Darkmoon Faire per te...", enHash = "e471c15d", vanilla = true },
        reward = { it = "Oh cielo, sono proprio grandi!! Non riesco a immaginare uno gnomo che ci stia comodo dentro, ma niente paura: se lo gnomo che troveremo non sarà abbastanza grande, posso sistemare il suo costume.\n\nMille grazie, $N. Ecco i biglietti che ti avevo promesso.", enHash = "ddf3494b", vanilla = true },
    },
    [7884] = {
        title = { it = "Il ragazzo crocolisco e il murloc barbuto", enHash = "25683492", vanilla = true },
        progress = { it = "Yebb sta lavorando ad altre attrazioni per il suo zoo, tra cui dimore umide e paludose per un ragazzo cresciuto dai crocolischi, e forse per un murloc. Ci serviranno dei buoni gambali impermeabili, così non ci inzupperemo durante i montaggi e gli smontaggi. Per questo lavoro credo che le Turtle Scale Leggings andranno benissimo.\n\n$N, sai fare quei gambali? Se li fai, la tua ricompensa sarà una bella pila di biglietti della Darkmoon Faire...", enHash = "92f982e8", vanilla = true },
        reward = { it = "Magnifico, li hai fatti! Andranno benissimo... Spero solo di non essere io quello che dovrà pulire la gabbia dei crocolischi, quando sarà il momento. Quelle bestie sanno essere proprio bestiali, non credi?\n\nEcco i tuoi biglietti, $N. Goditeli, e goditi il soggiorno alla Darkmoon Faire!", enHash = "2462e54c", vanilla = true },
    },
    [7889] = {
        title = { it = "Coarse Weightstone", enHash = "7d8c66fc", vanilla = true },
        progress = { it = "Ci vuole un sacco di lavoro per essere la donna più forte del mondo! I miei pesi stanno diventando troppo leggeri, e se voglio restare in forma mi serviranno altri pesi!\n\nPensi di potermi portare qualche Coarse Weightstone? Se lo fai, ti darò un biglietto della Darkmoon Faire.", enHash = "585b20b2", vanilla = true },
        reward = { it = "Fantastico! Andranno benissimo! Non sono troppo pesanti, ma nemmeno troppo leggere. Sono perfette per far crescere i muscoli!\n\nGrazie mille, $N. Ecco il tuo biglietto della Darkmoon Faire!", enHash = "bf82c7db", vanilla = true },
    },
    [7890] = {
        title = { it = "Heavy Grinding Stone", enHash = "5eeb5a8c", vanilla = true },
        progress = { it = "Per allenarmi, mi piace infilare un bastone tra due Heavy Grinding Stone e poi sollevarlo sopra la testa. Non è facile, ma essere la donna più forte del mondo, come lo sono io, non è una cosa che si guadagna stando seduti!\n\nMi aiuti? Mi servono altre Heavy Grinding Stone: portamene qualcuna e in cambio ti darò dei biglietti della Darkmoon Faire.", enHash = "66eeb1a9", vanilla = true },
        reward = { it = "Hai portato le pietre! E sono pesanti! Sento già i muscoli che crescono. Grazie, $N!\n\nEcco, prendi questi biglietti, e mi raccomando, non mangiare troppi dolci mentre sei alla fiera. $GUn:Una; $C grande e forte come te deve tenersi in forma per combattere!", enHash = { "b46e6172", "8fb4f7c9" }, vanilla = true },
    },
    [7891] = {
        title = { it = "Green Iron Bracers", enHash = "6d6c1e59", vanilla = true },
        progress = { it = "Sto preparando un nuovo costume, per quando avrò il mio stand come la donna più forte del mondo! Adesso sto cercando dei bracciali da indossare. Non devono coprire molto, perché la gente vuole vedere i miei muscoli, ma voglio comunque sfoggiare un po' di colore, capisci?\n\nChe ne dici delle Green Iron Bracers, $N? Puoi farmi delle Green Iron Bracers? Se puoi, ho un bel mucchio di biglietti della Darkmoon Faire per te.", enHash = "87978597", vanilla = true },
        reward = { it = "Sì! Sono proprio quello che mi serve! Che bel colore, e lasciano comunque le braccia scoperte, così si vede quanto sono forti! Perfetto!\n\nEcco a te, $N. Ecco i tuoi biglietti: divertiti!", enHash = "d9f57826", vanilla = true },
    },
    [7892] = {
        title = { it = "Big Black Mace", enHash = "9a984797", vanilla = true },
        progress = { it = "Per il mio numero da donna più forte del mondo, ho intenzione di farmi dare degli oggetti dal pubblico e di spaccarli con una Big Black Mace!\n\nPuoi farmi una Big Black Mace, $N?", enHash = "d0938862", vanilla = true },
        reward = { it = "Ah, perfetta! Questa mazza ha una testa grossa e pesante. Scommetto che potrei spaccarci praticamente qualsiasi cosa. Spero solo di non romperla insieme a quello che colpisco!\n\nEcco i tuoi biglietti, $N. Goditi il soggiorno alla fiera!", enHash = "ba774b33", vanilla = true },
    },
    [7894] = {
        title = { it = "Copper Modulator", enHash = "df7e8ba8", vanilla = true },
        progress = { it = "Yebb sta preparando una nuova attrazione per lo Zoo Bizarre, una che farà impazzire la gente di meraviglia e di gioia! Ma ci vorrà un sacco di lavoro, e un sacco di materiali...\n\nTra questi ci sono i Copper Modulator. Ci servono tanti modulatori per le parti meccaniche dell'attrazione. Portami dei Copper Modulator e te li scambierò con un biglietto della Darkmoon Faire.", enHash = "85fd8420", vanilla = true },
        reward = { it = "Ah! I modulatori! Magnifico!\n\nNon posso dirti esattamente cosa stiamo costruendo, ma saranno preziosissimi per costruirlo. Ti sono debitore, $N, ma ti prego, prendi questo biglietto della Darkmoon Faire come segno della mia riconoscenza.", enHash = "c443cced", vanilla = true },
    },
    [7895] = {
        title = { it = "Whirring Bronze Gizmo", enHash = "13c4f8ea", vanilla = true },
        progress = { it = "Il mio nuovo stand sarà uno spettacolo da vedere, sissignore! Uno spettacolo da vedere e... per pochi fortunati, da toccare!\n\nSento già i Whirring Bronze Gizmo che cantano la loro canzone di estasi meccanica, mentre i clienti si avvicinano al mio stand e mettono alla prova la loro abilità!\n\nAh... ora mi servono i congegni veri e propri, per avvicinare il mio sogno alla realtà. Ti prego, $N, portami dei Whirring Bronze Gizmo... e i biglietti della Darkmoon Faire saranno tuoi!", enHash = "5077a12a", vanilla = true },
        reward = { it = "Hai portato i congegni! Meraviglioso! Sento già nella mente il loro coro ronzante e fischiante! Oh, quando questo stand sarà pronto sarà la meraviglia del mondo, ricordatelo!\n\nEcco i tuoi biglietti, $N. E goditi il soggiorno alla Faire!", enHash = "384cb314", vanilla = true },
    },
    [7896] = {
        title = { it = "Green Fireworks", enHash = "5286e22f", vanilla = true },
        progress = { it = "Quando finalmente avrò messo in piedi questo stand, vorrò farmi pubblicità! E quale modo migliore per farsi pubblicità dei fuochi d'artificio?\n\nBe', qualcuno potrebbe pensare che l'odore di un calderone in cui bollono le teste dei tuoi nemici attiri di più la folla, ma... qui c'è gente di ogni genere. Quindi dovranno essere fuochi d'artificio!\n\nPortami dei Green Firework, $N, e ho una bella manciata di biglietti della Darkmoon Faire per te.", enHash = "53f7ad4d", vanilla = true },
        reward = { it = "Hai portato i fuochi d'artificio. Splendido lavoro, $N! Non vedo l'ora di accenderli e dire al mondo che il mio stand è pronto! Devo ancora aspettare, temo parecchio, ma... sarò pronto quando sarò pronto, no?\n\nEcco i biglietti, $N. Divertiti!", enHash = "b6eeb89c", vanilla = true },
    },
    [7897] = {
        title = { it = "Mechanical Repair Kits", enHash = "538da51f", vanilla = true },
        progress = { it = "Il motivo principale per cui non posso aprire il mio stand è che... è tutto rotto! Mi servono dei Mechanical Repair Kit per aggiustare tutta questa roba!\n\nPuoi portarmi quei kit, $N? Facciamo uno scambio... kit in cambio di biglietti della Darkmoon Faire. Che ne dici?", enHash = "a257ea3d", vanilla = true },
        reward = { it = "Grazie! Adesso posso mettermi ad aggiustare le cose.\n\nCi vorranno un sacco di kit di riparazione e un sacco di nottate per rimettere tutto in funzione. A volte penso che sarebbe meglio tornare alle mie radici e ricominciare la carriera di cacciatore di teste, ma... la Faire è stata buona con me.\n\nPrendi questi biglietti, $N, e divertiti!", enHash = "b3886991", vanilla = true },
    },
    [7899] = {
        title = { it = "Small Furry Paws", enHash = "60930c9c", vanilla = true },
        progress = { it = "La prima lezione per attirare la folla è: adescarla con aggeggi e ninnoli! Mi aiuti?\n\nMi servono delle Small Furry Paw da usare come premi. Le trovi sui felini delle Barrens o di Darkshore...\n\nPortami qualche zampa e in cambio ti darò un biglietto della Darkmoon Faire.", enHash = "440743cf", vanilla = true },
        reward = { it = "Magnifico, le hai trovate! Possiamo usarle per fare giocattoli e gingilli, e quelli attireranno altra gente alla Faire!\n\nEcco il tuo biglietto, $N. Te lo sei guadagnato!", enHash = "ef0227e8", vanilla = true },
    },
    [7900] = {
        title = { it = "Torn Bear Pelts", enHash = "f2c54433", vanilla = true },
        progress = { it = "I bambini adorano i giocattoli! E, di qualunque razza siano, ho scoperto che tutti i bambini adorano i giocattoli morbidi e pelosi fatti con le Torn Bear Pelt!\n\nPuoi prendere quelle pelli dagli orsi di Ashenvale o di Hillsbrad. Portamene un mucchio e guadagnati un mucchio di biglietti della Darkmoon Faire!", enHash = "fbe10648", vanilla = true },
        reward = { it = "Belle pelli, $N! Le farò cucire a qualcuno per farne un bel po' di peluche. Con un po' d'imbottitura e un po' di colore, credo che faranno invidia ai bambini di tutta Azeroth!\n\nI biglietti? Ah sì, il tuo pagamento! Eccoli!", enHash = "ba17e22a", vanilla = true },
    },
    [7901] = {
        title = { it = "Soft Bushy Tails", enHash = "03ee55de", vanilla = true },
        progress = { it = "È incredibile a cosa la gente dia valore! Prendi, per esempio, un bastoncino di legno con attaccata una Soft Bushy Tail. Ora, tu e io potremmo pensare che una cosa del genere non valga granché... ma se dai a quella cianfrusaglia un nome accattivante come \"Savage Fuzz Tail\" e la metti in una bella scatola, la gente penserà che abbia valore. La spazzatura diventa un tesoro!\n\nProcurami delle Soft Bushy Tail dai lupi di Desolace e delle Badlands, e ti darò dei biglietti della Darkmoon Faire.", enHash = "a947762d", vanilla = true },
        reward = { it = "Ben fatto, $N! Queste code saranno ottimi premi per i nostri visitatori, e questo significa visitatori contenti... che ne parlano agli amici e portano altri visitatori!\n\nEcco i tuoi biglietti! Divertiti alla Darkmoon Faire... e non dimenticare di parlare di noi ai tuoi amici!", enHash = "6dd0ec50", vanilla = true },
    },
    [7902] = {
        title = { it = "Vibrant Plumes", enHash = "e924541e", vanilla = true },
        progress = { it = "L'immaginazione di una persona è una cosa incredibile. Può far sembrare la collina più piccola la montagna più grande. Può far sembrare l'ombra più innocua quella di un incubo orribile!\n\nNoi della Darkmoon Faire lasciamo sbocciare l'immaginazione dei nostri visitatori! Ma per stimolarla un po'... a volte dobbiamo ricorrere a qualche trucco.\n\nMi servono delle Vibrant Plume per una delle mie attrazioni. Le trovi sugli uccelli delle zone più pericolose di Azeroth. Portami le piume, e molti biglietti saranno tuoi!", enHash = "dee266f6", vanilla = true },
        reward = { it = "Ah, le piume! Sono stupende, non trovi? Con bellezze così sarebbe facile accendere l'immaginazione!\n\nFai proprio un lavoro generoso, $N. I sorrisi sulle facce dei nostri visitatori quando vedono lo spettacolo sono già un grande compenso, ma ti prego, prendi anche questi biglietti.", enHash = "83589813", vanilla = true },
    },
    [7905] = {
        title = { it = "La Darkmoon Faire", enHash = "a2f86367", vanilla = true },
        text = { it = "La Darkmoon Faire sta arrivando! Quando passa in città, non perderti tutte le sue meraviglie e le sue emozioni!\n\nSe ti muovi subito, puoi riscattare questo buono per dei biglietti premio gratis! Basta che consegni il buono a Gelvas Grimgate, dentro il luna park.\n\nIn questo momento la Faire è fuori Goldshire, nell'Elwynn Forest. Non perdertela! Vacci oggi stesso!", enHash = "e1b47f74", vanilla = true },
        objectives = { it = "Consegna il Free Ticket Voucher a Gelvas Grimgate, dentro il luna park della Darkmoon Faire.", enHash = "3ac1d2ce", vanilla = true },
        progress = { it = "Sì, $Gamico:amica;, posso aiutarti? Hai un buono da riscattare?", enHash = "c4404020", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta; alla Darkmoon Faire! Questo buono vale CINQUE, sì, CINQUE biglietti premio!\n\nQuando avrai messo insieme dei biglietti premio, vieni a parlarmi per riscattarli e avere premi di valore. Più biglietti raccogli, più premi puoi vincere. Evviva!", enHash = "4f658698", vanilla = true },
    },
    [7908] = {
        title = { it = "Arena Master", enHash = "072f299b", vanilla = true },
        text = { it = "Per essere $Gun maestro:una maestra; dell'arena ci vuole di più! Forse il pirata che organizza l'evento a Gurubashi lo saprà!", enHash = "26d147ea", vanilla = true },
        objectives = { it = "Parla con Short John Mithril nella Stranglethorn Arena.", enHash = "08c4dfbc", vanilla = true },
    },
    [7926] = {
        title = { it = "La Darkmoon Faire", enHash = "a2f86367", vanilla = true },
        text = { it = "La Darkmoon Faire sta arrivando! Quando passa in città, non perderti tutte le sue meraviglie e le sue emozioni!\n\nSe ti muovi subito, puoi riscattare questo buono per dei biglietti premio gratis! Basta che consegni il buono a Gelvas Grimgate, dentro il luna park.\n\nIn questo momento la Faire è appena fuori Thunder Bluff, a Mulgore. Non perdertela! Vacci oggi stesso!", enHash = "9205e6e8", vanilla = true },
        objectives = { it = "Consegna il Free Ticket Voucher a Gelvas Grimgate, dentro il luna park della Darkmoon Faire.", enHash = "3ac1d2ce", vanilla = true },
        progress = { it = "Sì, $Gamico:amica;, posso aiutarti? Hai un buono da riscattare?", enHash = "c4404020", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta; alla Darkmoon Faire! Questo buono vale CINQUE, sì, CINQUE biglietti premio!\n\nQuando avrai messo insieme dei biglietti premio, vieni a parlarmi per riscattarli e avere premi di valore. Più biglietti raccogli, più premi puoi vincere. Evviva!", enHash = "4f658698", vanilla = true },
    },
    [7930] = {
        title = { it = "5 biglietti — Darkmoon Flower", enHash = "3511ec0d", vanilla = true },
        progress = { it = "Fatti avanti, fatti avanti! Se hai dei biglietti della Darkmoon Faire da riscattare, basta dirlo! Puoi riscattare i biglietti in vari tagli per premi meravigliosi e fantastici. Non essere $Gtimido:timida;, prova anche tu!", enHash = "9f1096fb", vanilla = true },
        reward = { it = "Ecco qua, ecco qua! Un premio degno di $Gun re:una regina;! Congratulazioni, $Gamico mio:amica mia;!\n\nSe hai altri biglietti da consegnare, fammelo sapere! Finché la Darkmoon Faire resta qui, riscatterò i tuoi biglietti.", enHash = { "d77d896d", "d488ac68" }, vanilla = true },
    },
    [7931] = {
        title = { it = "5 biglietti — Minor Darkmoon Prize", enHash = "24f18eab", vanilla = true },
        progress = { it = "Fatti avanti, fatti avanti! Se hai dei biglietti della Darkmoon Faire da riscattare, basta dirlo! Puoi riscattare i biglietti in vari tagli per premi meravigliosi e fantastici. Non essere $Gtimido:timida;, prova anche tu!", enHash = "9f1096fb", vanilla = true },
