    [7935] = {
        title = { it = "10 biglietti — Last Month's Mutton", enHash = "4d805498", vanilla = true },
        progress = { it = "Fatti avanti, fatti avanti! Se hai dei biglietti della Darkmoon Faire da riscattare, basta dirlo! Puoi riscattare i biglietti in vari tagli per premi meravigliosi e fantastici. Non essere $Gtimido:timida;, prova anche tu!", enHash = "9f1096fb", vanilla = true },
