    },
    [7944] = {
        title = { it = "La tua fortuna ti attende...", enHash = "a89d03c6", vanilla = true },
        text = { it = "\"La tua fortuna ti attende nelle Wailing Caverns.\"\n\nIl biglietto della fortuna che Sayge ti ha dato è leggermente caldo al tatto. Stringendolo forte, vedi l'immagine di una grotta a sud-ovest del Crossroads, nelle Barrens. Concentrandoti sull'immagine, segui passaggi tortuosi finché non raggiungi un portale scintillante... uno che conduce nel cuore stesso delle caverne. Quando lo attraversi, uno strano forziere compare dal nulla.", enHash = "e7ae3a65", vanilla = true },
        objectives = { it = "Raggiungi le Wailing Caverns, nelle Barrens, e va' in cerca della tua fortuna.", enHash = "92cc6279", vanilla = true },
        progress = { it = "Questo forziere somiglia a quello della tua visione...", enHash = "252d01ca", vanilla = true },
        reward = { it = "Frugando rapidamente nel forziere trovi una cassetta chiusa a chiave! Pare proprio che tu abbia trovato la tua fortuna!", enHash = "73f967de", vanilla = true },
    },
    [8149] = {
        title = { it = "In onore di un eroe", enHash = "87da1241", vanilla = true },
        text = { it = "Durante l'Harvest Festival di Azeroth rendiamo grazie agli eroi per i sacrifici, in alcuni casi il sacrificio supremo, che hanno fatto per noi. L'Alleanza riconosce molti eroi, ma nessuno ha una storia più tragica di quella di Uther Lightbringer.\n\nAiutaci a onorare Uther portando questa offerta alla sua tomba, nelle Western Plaguelands. Mettila presso la sua statua, poi torna da me. Resterò qui solo fino alla fine della festa, quindi non perdere tempo a rendere omaggio a Uther.", enHash = "24a8e587", vanilla = true },
        objectives = { it = "Raggiungi l'Uther's Tomb, nelle Western Plaguelands, usa l'Uther's Tribute presso la sua statua e poi torna da Wagner Hammerstrike, fuori da Ironforge, prima che l'Harvest Festival finisca.", enHash = "a3fb59f4", vanilla = true },
        progress = { it = "Hai fatto il viaggio fino all'Uther's Tomb e hai lasciato lì il tributo?\n\nPuò essere un viaggio pericoloso per gli avventurieri meno esperti; un modo più sicuro, per così dire, per arrivarci potrebbe essere risalire verso nord il fiume che attraversa le Hillsbrad fino alle Plaguelands. Il fiume nasce da un lago vicino a Sorrow Hill; va' verso ovest attraverso le colline, tenendoti lontano dalla tomba vicina... che è infestata dal Flagello.", enHash = "c43ba9f9", vanilla = true },
        reward = { it = "Era un eroe tra gli eroi, Uther. Non riesco nemmeno a immaginare l'angoscia che provò quando Arthas, il suo allievo migliore e qualcuno che Uther amava come un figlio, tradì tutta l'umanità. Eppure si levò per cercare di fermare Arthas, e per questo sarà ricordato per sempre come un vero paladino. Combatté fino alla fine, pensando solo a coloro che poteva salvare.\n\nGrazie, $N. Oggi hai reso omaggio a un grande eroe, onorando il suo spirito e lo spirito dell'Harvest Festival.", enHash = "c954c107", vanilla = true },
    },
    [8150] = {
        title = { it = "In onore di un eroe", enHash = "87da1241", vanilla = true },
        text = { it = "Durante l'Harvest Festival di Azeroth rendiamo grazie agli eroi per i sacrifici, in alcuni casi il sacrificio supremo, che hanno fatto per noi. L'Orda riconosce molti eroi, ma nessuno incarna la forza e il sacrificio più di Grom Hellscream.\n\nAiutaci a onorare Grom portando questa offerta al suo monumento, nel Demon Fall Canyon di Ashenvale. Mettila alla base, poi torna da me. Resterò qui solo fino alla fine della festa, quindi non perdere tempo a rendere omaggio a Grom.", enHash = "87a77f0a", vanilla = true },
        objectives = { it = "Raggiungi il Grom's Monument, nel Demon Fall Canyon di Ashenvale, e usa il Grom's Tribute alla base del monumento. Torna da Javnir Nashak, fuori da Orgrimmar, prima che l'Harvest Festival finisca.", enHash = "8f2efa0a", vanilla = true },
        progress = { it = "Hai fatto il viaggio fino al Grom's Monument e hai lasciato lì il suo tributo?\n\nIl luogo dove sorge il monumento è ancora segnato dalla corruzione della Legione Infuocata. Se hai poca esperienza nell'avventura, sta' in guardia quando ti avvicini al monumento.", enHash = "4cf9c0e4", vanilla = true },
        reward = { it = "Il nome completo di Grom, Grommash, significa \"Il cuore del gigante\"; ci volle questo e anche di più per affrontare da solo Mannoroth. Credo che il Capoguerra l'abbia detto meglio di tutti: la maledizione degli orchi cominciò e finì con Grom. È giusto che il sacrificio di Grom, e forse la sua redenzione, sia la sorgente da cui l'Orda scaturisce oggi.\n\nGrazie, $N. Oggi hai reso omaggio a un grande eroe, onorando il suo spirito e lo spirito dell'Harvest Festival.", enHash = "4ea1ad29", vanilla = true },
    },
    [8155] = {
        title = { it = "Arathi Basin Mark of Honor!", enHash = "995939af", vanilla = true },
        text = { it = "La guerra si combatte con i soldati, te lo dirà qualunque soldato. Ti diranno anche che una battaglia combattuta con un equipaggiamento scadente o a stomaco vuoto è persa prima ancora di cominciare!\n\nEcco perché Arathi Basin è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname: servono tutti, e tutti si possono ottenere lì.\n\nÈ questo che voglio da te, $N. Entra in Arathi Basin, vinci la battaglia tenendo più basi del nemico e torna da me con un Mark of Honor.", enHash = "0642dea4", vanilla = true },
        objectives = { it = "Vinci la battaglia per Arathi Basin, ottieni un Arathi Basin Mark of Honor e portalo a Sergeant Maclear, a Refuge Pointe.", enHash = "03b718ae", vanilla = true },
        progress = { it = "Hai i Mark of Honor, $N? La League of Arathor non può combattere una battaglia decente senza di essi...", enHash = "bdad530c", vanilla = true },
        reward = { it = "Hai preso il Mark! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle rapidamente alle nostre truppe.\n\nGrazie, $N. È proprio portando a termine missioni come la tua che si vincono davvero le guerre.", enHash = "2aa130c6", vanilla = true },
    },
    [8156] = {
        title = { it = "Arathi Basin Mark of Honor!", enHash = "995939af", vanilla = true },
        text = { it = "La guerra si combatte con i soldati, te lo dirà qualunque soldato. Ti diranno anche che una battaglia combattuta con un equipaggiamento scadente o a stomaco vuoto è persa prima ancora di cominciare!\n\nEcco perché Arathi Basin è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname: servono tutti, e tutti si possono ottenere lì.\n\nÈ questo che voglio da te, $N. Entra in Arathi Basin, vinci la battaglia tenendo più basi del nemico e torna da me con un Mark of Honor.", enHash = "0642dea4", vanilla = true },
        objectives = { it = "Vinci la battaglia per Arathi Basin, ottieni un Arathi Basin Mark of Honor e portalo a Sergeant Maclear, a Refuge Pointe.", enHash = "03b718ae", vanilla = true },
        progress = { it = "Hai i Mark of Honor, $N? La League of Arathor non può combattere una battaglia decente senza di essi...", enHash = "bdad530c", vanilla = true },
        reward = { it = "Hai preso il Mark! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle rapidamente alle nostre truppe.\n\nGrazie, $N. È proprio portando a termine missioni come la tua che si vincono davvero le guerre.", enHash = "2aa130c6", vanilla = true },
    },
    [8161] = {
        title = { it = "Taglia le linee di rifornimento di Arathor", enHash = "95ebbd85", vanilla = true },
        text = { it = "La League of Arathor non bada a spese nel tentativo di riprendersi Arathi. Loro, e tutte le razze dell'Alleanza, ora si riversano in questa regione lontana, decisi ad allargare il loro dominio a partire da Refuge Pointe. Dobbiamo fermarli, e il modo migliore per fermarli è prendere i loro rifornimenti.\n\nPuoi aiutarci, $N. Entra in Arathi Basin, noto per le sue ricche miniere, la terra fertile e gli abili artigiani. Conquista e controlla ogni base che puoi, vinci la battaglia e torna da me con il Mark of Honor che otterrai.", enHash = "ccd3a472", vanilla = true },
        objectives = { it = "Vinci la battaglia per Arathi Basin, ottieni un Arathi Basin Mark of Honor e portalo a Deathstalker Mortis, a Hammerfall.", enHash = "078bca30", vanilla = true },
        progress = { it = "Che c'è, $R? Hai i Mark of Honor? Torna in Arathi Basin, stermina i parassiti dell'Alleanza e impadronisciti delle sue risorse per la Signora Oscura!", enHash = "2cd8a43e", vanilla = true },
        reward = { it = "<Deathstalker Mortis sorride>\n\nUn altro colpo decisivo è stato inferto ai nostri nemici, $N. Grazie alle tue imprese, Arathi Basin cadrà presto nelle mani dei Defilers.", enHash = "25a67599", vanilla = true },
    },
    [8162] = {
        title = { it = "Taglia le linee di rifornimento di Arathor", enHash = "95ebbd85", vanilla = true },
        text = { it = "La League of Arathor non bada a spese nel tentativo di riprendersi Arathi. Loro, e tutte le razze dell'Alleanza, ora si riversano in questa regione lontana, decisi ad allargare il loro dominio a partire da Refuge Pointe. Dobbiamo fermarli, e il modo migliore per fermarli è prendere i loro rifornimenti.\n\nPuoi aiutarci, $N. Entra in Arathi Basin, noto per le sue ricche miniere, la terra fertile e gli abili artigiani. Conquista e controlla ogni base che puoi, vinci la battaglia e torna da me con il Mark of Honor che otterrai.", enHash = "ccd3a472", vanilla = true },
        objectives = { it = "Vinci la battaglia per Arathi Basin, ottieni un Arathi Basin Mark of Honor e portalo a Deathstalker Mortis, a Hammerfall.", enHash = "078bca30", vanilla = true },
        progress = { it = "Che c'è, $R? Hai i Mark of Honor? Torna in Arathi Basin, stermina i parassiti dell'Alleanza e impadronisciti delle sue risorse per la Signora Oscura!", enHash = "2cd8a43e", vanilla = true },
        reward = { it = "<Deathstalker Mortis sorride>\n\nUn altro colpo decisivo è stato inferto ai nostri nemici, $N. Grazie alle tue imprese, Arathi Basin cadrà presto nelle mani dei Defilers.", enHash = "25a67599", vanilla = true },
    },
    [8167] = {
        title = { it = "La battaglia per Arathi Basin!", enHash = "913847b3", vanilla = true },
        text = { it = "$N, la battaglia per Arathi Basin è una battaglia per le risorse e il territorio. I punti chiave della zona vanno tenuti e fatti funzionare per rifornire le nostre forze delle materie prime e delle provviste di cui hanno tanto bisogno. Ti incarico di assaltare i punti più lontani dalla nostra base di Arathi Basin.\n\nAssalta la fattoria, la miniera, la segheria e la fucina quando sono controllate dal nemico. Trova lo stendardo del nemico e strappalo dalla sua asta!\n\nQuando l'avrai fatto con tutti e quattro i punti, torna da me.", enHash = "01f6462b", vanilla = true },
        objectives = { it = "Assalta la miniera, la segheria, la fucina e la fattoria, poi torna da Field Marshal Oslight, a Refuge Pointe.", enHash = "ec18c3b8", vanilla = true },
        reward = { it = "Ho ricevuto rapporti sulle tue imprese in Arathi Basin, $N. Ben fatto! Con gente come te che si unisce alla lotta qui, ho fiducia che un giorno riprenderemo le nostre terre d'origine.", enHash = "55e4bc1a", vanilla = true },
    },
    [8168] = {
        title = { it = "La battaglia per Arathi Basin!", enHash = "913847b3", vanilla = true },
        text = { it = "$N, la battaglia per Arathi Basin è una battaglia per le risorse e il territorio. I punti chiave della zona vanno tenuti e fatti funzionare per rifornire le nostre forze delle materie prime e delle provviste di cui hanno tanto bisogno. Ti incarico di assaltare i punti più lontani dalla nostra base di Arathi Basin.\n\nAssalta la fattoria, la miniera, la segheria e la fucina quando sono controllate dal nemico. Trova lo stendardo del nemico e strappalo dalla sua asta!\n\nQuando l'avrai fatto con tutti e quattro i punti, torna da me.", enHash = "01f6462b", vanilla = true },
        objectives = { it = "Assalta la miniera, la segheria, la fucina e la fattoria, poi torna da Field Marshal Oslight, a Refuge Pointe.", enHash = "ec18c3b8", vanilla = true },
        reward = { it = "Ho ricevuto rapporti sulle tue imprese in Arathi Basin, $N. Ben fatto! Con gente come te che si unisce alla lotta qui, ho fiducia che un giorno riprenderemo le nostre terre d'origine.", enHash = "55e4bc1a", vanilla = true },
    },
    [8170] = {
        title = { it = "La battaglia per Arathi Basin!", enHash = "913847b3", vanilla = true },
        text = { it = "Come avrai senz'altro sentito, la League of Arathor sta mandando un gran numero di truppe in Arathi Basin. Avidi di cibo e provviste, questi stolti dell'Alleanza sono decisi a prendere e controllare le ricche risorse che si trovano lì. Dobbiamo dimostrargli che Arathi non sarà mai più una casa per gli umani!\n\nVa' in Arathi Basin e assalta la miniera, la segheria, la fucina e le stalle. Abbatti gli stendardi dei nemici e rivendica quei territori per l'Orda.\n\nVa', $N. Torna a riferirmi quando avrai portato a termine questo compito.", enHash = "6a0e545c", vanilla = true },
        objectives = { it = "Assalta la miniera, la segheria, la fucina e la stalla di Arathi Basin, poi torna da Deathmaster Dwire, a Hammerfall.", enHash = "ddbf105c", vanilla = true },
        reward = { it = "Un esploratore dei Defilers è venuto da me con un rapporto sul tuo successo, $N. Ben fatto.\n\nCome imparerai, per vincere la battaglia per Arathi Basin dobbiamo restare sempre vigili e schiacciare ogni tentativo di espansione dell'Alleanza. Fa' questo, e la nostra vittoria qui è assicurata.", enHash = "374fd010", vanilla = true },
    },
    [8171] = {
        title = { it = "La battaglia per Arathi Basin!", enHash = "913847b3", vanilla = true },
        text = { it = "Come avrai senz'altro sentito, la League of Arathor sta mandando un gran numero di truppe in Arathi Basin. Avidi di cibo e provviste, questi stolti dell'Alleanza sono decisi a prendere e controllare le ricche risorse che si trovano lì. Dobbiamo dimostrargli che Arathi non sarà mai più una casa per gli umani!\n\nVa' in Arathi Basin e assalta la miniera, la segheria, la fucina e le stalle. Abbatti gli stendardi dei nemici e rivendica quei territori per l'Orda.\n\nVa', $N. Torna a riferirmi quando avrai portato a termine questo compito.", enHash = "6a0e545c", vanilla = true },
        objectives = { it = "Assalta la miniera, la segheria, la fucina e la stalla di Arathi Basin, poi torna da Deathmaster Dwire, a Hammerfall.", enHash = "ddbf105c", vanilla = true },
        reward = { it = "Un esploratore dei Defilers è venuto da me con un rapporto sul tuo successo, $N. Ben fatto.\n\nCome imparerai, per vincere la battaglia per Arathi Basin dobbiamo restare sempre vigili e schiacciare ogni tentativo di espansione dell'Alleanza. Fa' questo, e la nostra vittoria qui è assicurata.", enHash = "374fd010", vanilla = true },
    },
    [8193] = {
        title = { it = "Maestro pescatore", enHash = "15eecd7d", vanilla = true },
        progress = { it = "Oggi, tra le 2 e le 4 del pomeriggio, c'è una gara per stabilire chi è il più grande pescatore di tutti! Basta essere la PRIMA PERSONA a portarmi 40 Tastyfish pescati dai banchi di Tastyfish lungo la costa di Stranglethorn, prima di chiunque altro, e sarai $Gproclamato Maestro pescatore:proclamata Maestra pescatrice;!\n\nSe non sei la prima persona a portarmi 40 pesci, la mia apprendista qui ti ricompenserà comunque con del denaro per ogni 5 Tastyfish che le porterai.\n\nAh, e non perdere tempo, i Tastyfish vanno a male in fretta!", enHash = "683ae4e6", vanilla = true },
        reward = { it = "Sbrigati a consegnarli, se vuoi essere $Gproclamato Maestro pescatore:proclamata Maestra pescatrice;! Sono qui da ORE senza niente da mangiare! Dammi quei cosi!", enHash = "ccda7914", vanilla = true },
    },
    [8260] = {
        title = { it = "Arathor Basic Care Package", enHash = "44e9b002", vanilla = true },
        reward = { it = "Hai di sicuro cominciato a dimostrare il tuo valore ai nostri occhi, $N. Come ricompensa, prendi questo pacco di rifornimenti! Dentro trovi razioni e bende utilizzabili solo dentro Arathi Basin.\n\nContinuando a dimostrare il tuo valore nel Basin, scoprirai che questi oggetti si potranno anche comprare. Le razioni diventano disponibili quando sei Friendly con noi, le bende quando sei Honored.", enHash = "b4848c79", vanilla = true },
    },
    [8263] = {
        title = { it = "Defiler's Basic Care Package", enHash = "701754e8", vanilla = true },
        reward = { it = "Hai di sicuro cominciato a dimostrare il tuo valore ai nostri occhi, $N. Come ricompensa, prendi questo pacco di rifornimenti! Dentro trovi razioni e bende utilizzabili solo dentro Arathi Basin.\n\nContinuando a dimostrare il tuo valore nel Basin, scoprirai che questi oggetti si potranno anche comprare. Le razioni diventano disponibili quando sei Friendly con noi, le bende quando sei Honored.", enHash = "b4848c79", vanilla = true },
    },
    [8266] = {
        title = { it = "Ribbons of Sacrifice", enHash = "ba49410b", vanilla = true },
        progress = { it = "Capisco che a volte può essere difficile avere la meglio in Warsong Gulch. Eppure il tuo impegno per noi — anche quando la vittoria non arriva — è importante.\n\nSe porti a termine una delle prove dentro Warsong Gulch senza ottenere la vittoria, riceverai comunque una Ribbons of Sacrifice. Portamela, così le Sentinelle potranno ricompensarti per aver agito per noi... anche se questa volta non sei $Griuscito:riuscita; a vincere.", enHash = "3fe34c7e", vanilla = true },
        reward = { it = "Be', non sei $Gfuggito:fuggita; di fronte alla sconfitta. Hai tenuto la posizione, $N, e alla fine è questo che fa un vero eroe. Di sicuro la prossima volta vincerai... ma intanto ti ringraziamo per il tuo impegno.", enHash = "98c33607", vanilla = true },
    },
    [8268] = {
        title = { it = "Ribbons of Sacrifice", enHash = "ba49410b", vanilla = true },
        progress = { it = "Capisco che a volte può essere difficile avere la meglio in Warsong Gulch. Eppure il tuo impegno per noi — anche quando la vittoria non arriva — è importante.\n\nSe porti a termine una delle prove dentro Warsong Gulch senza ottenere la vittoria, riceverai comunque una Ribbons of Sacrifice. Portamela, così i Warsong Outrider potranno ricompensarti per aver agito per noi... anche se questa volta non sei $Griuscito:riuscita; a vincere.", enHash = "1d3e8bb6", vanilla = true },
        reward = { it = "Be', non sei $Gfuggito:fuggita; di fronte alla sconfitta. Hai tenuto la posizione, $N, e alla fine è questo che fa un vero eroe. Di sicuro la prossima volta vincerai... ma intanto ti ringraziamo per il tuo impegno.", enHash = "98c33607", vanilla = true },
    },
    [8290] = {
        title = { it = "Sconfiggi gli invasori", enHash = "1109caca", vanilla = true },
        text = { it = "Oltre questo tunnel troverai un campo di lotta e tumulto, giovane $C. L'Orda continua a decimare la nostra foresta sacra, abbattendo il fogliame sempreverde per alimentare le sue macchine da guerra.\n\nEntra in Warsong Gulch e difendi Silverwing Hold. Respingi le forze invasori dell'Orda!\n\nFa' questo e guadagna un talismano di merito. Portami un talismano simile, $N, e ti ricompenserò.", enHash = "6a21b2aa", vanilla = true },
        objectives = { it = "Entra in Warsong Gulch e sconfiggi l'Orda, ottieni un Warsong Gulch Mark of Honor e torna da Sentinel Farsong, al Silverwing Grove.", enHash = "18aeca16", vanilla = true },
    },
    [8295] = {
        title = { it = "Soffoca gli usurpatori Silverwing", enHash = "11a08c6b", vanilla = true },
        text = { it = "Le terre selvagge dell'Ashenvale Forest cederanno alla potenza dell'Orda, $R. Niente di quel che i Silverwing dicono o fanno può fermare il nostro diritto sovrano. Kalimdor appartiene all'Orda. Come osano cercare di impedirci di raccogliere quel che ci spetta!\n\nLascia che l'orgoglio ti gonfi il petto mentre abbatti i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le Silverwing Sentinel e guadagna un Warsong Mark of Honor. Torna da me con un marchio simile, $N, e sarai $Gricompensato:ricompensata;.", enHash = "a5943896", vanilla = true },
        objectives = { it = "Entra in Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull, al Mor'shan Base Camp.", enHash = "7112a784", vanilla = true },
    },
    [8311] = {
        title = { it = "Dolcetti della Veglia delle Ombre per Jesper!", enHash = "1f1c52f6", vanilla = true },
        text = { it = "Voglio andare a fare dolcetto o scherzetto, ma non posso perché sono malato. Se ci vai tu per me, ti darei in cambio delle caramelle che ho già! Credo che queste caramelle ti piacerebbero: ti trasformano in cose buffe e spaventose!\n\nOgnuno dei locandieri delle grandi città ha delle caramelle che regala per la Veglia delle Ombre: parla con loro e fai gli scherzetti che ti chiedono! Anche un piccolo gnomo di nome Talvash, a Ironforge, sta distribuendo caramelle. Quando avrai tutte le caramelle, riportamele qui!", enHash = "0b075690", vanilla = true },
        objectives = { it = "Parla con i locandieri di Stormwind, Ironforge e Darnassus, e con Talvash del Kissel a Ironforge. Fai gli scherzetti che ti chiedono in cambio dei dolcetti che offrono.\n\nTorna da Jesper, allo Stormwind Orphanage, con un Darnassus Marzipan, una Gnomeregan Gumdrop, uno Stormwind Nougat e una Ironforge Mint.", enHash = "a014538d", vanilla = true },
        progress = { it = "Hai finito di fare dolcetto o scherzetto? Mi dispiace non poterci andare perché sono malato, ma il fatto che mi aiuti mi fa sentire un po' meglio...", enHash = "d639de8a", vanilla = true },
        reward = { it = "Wow, le hai prese tutte! Sei $Gfantastico:fantastica;!\n\nGrazie di aver fatto dolcetto o scherzetto al posto mio. Ecco, prendi questi dolcetti alla zucca: credo che ti piaceranno un sacco!\n\nBuona Veglia delle Ombre, $N!", enHash = "ccb4b6d0", vanilla = true },
    },
    [8312] = {
        title = { it = "Dolcetti della Veglia delle Ombre per Spoops!", enHash = "0dc10e1b", vanilla = true },
        text = { it = "Voglio andare a fare dolcetto o scherzetto, ma non posso perché sono malata. Se ci vai tu per me, ti darei in cambio delle caramelle che ho già! Credo che queste caramelle ti piacerebbero: ti trasformano in cose buffe e spaventose!\n\nOgnuno dei locandieri delle grandi città ha delle caramelle che regala per la Veglia delle Ombre: parla con loro e fai gli scherzetti che ti chiedono! Anche un troll di nome Kali Remik, a Sen'jin Village, sta distribuendo caramelle. Quando avrai tutte le caramelle, riportamele qui!", enHash = "71e01969", vanilla = true },
        objectives = { it = "Parla con i locandieri di Orgrimmar, dell'Undercity e di Thunder Bluff, e con Kali Remik a Sen'jin Village. Fai gli scherzetti che ti chiedono in cambio dei dolcetti che offrono.\n\nTorna da Spoops, all'Orgrimmar Orphanage, con un Thunder Bluff Marzipan, una Darkspear Gumdrop, un Orgrimmar Nougat e una Undercity Mint.", enHash = "50701fd6", vanilla = true },
        progress = { it = "Hai finito di fare dolcetto o scherzetto? Mi dispiace non poterci andare perché sono malata, ma il fatto che mi aiuti mi fa sentire un po' meglio...", enHash = "d639de8a", vanilla = true },
        reward = { it = "Wow, le hai prese tutte! Sei $Gfantastico:fantastica;!\n\nGrazie di aver fatto dolcetto o scherzetto al posto mio. Ecco, prendi questi dolcetti alla zucca: credo che ti piaceranno un sacco!\n\nBuona Veglia delle Ombre, $N!", enHash = "ccb4b6d0", vanilla = true },
    },
    [8322] = {
        title = { it = "Rotten Eggs", enHash = "17372608", vanilla = true },
        text = { it = "Gli umani di Southshore adorano la loro birra, e per questo tengono moltissimo alla birra servita al Southshore Inn. Ora che il caos della Veglia delle Ombre si è abbattuto su di loro, possiamo approfittarne per rovinare le loro prossime partite di birra per settimane, se non per mesi!\n\nPrendi queste uova marce e mettile nel barile principale della birra, dentro il Southshore Inn. La tua sola presenza scatenerà lo scompiglio, quindi preparati a difenderti!\n\nQuando avrai fatto assaggiare a Southshore un gusto che non dimenticherà presto, torna da me qui alla festa!", enHash = "091223e1", vanilla = true },
        objectives = { it = "Metti le Rotten Eggs nel barile principale della birra, dentro il Southshore Inn.", enHash = "92287fb4", vanilla = true },
        progress = { it = "Il barile è pieno di birra.", enHash = "cba4cae4", vanilla = true },
        reward = { it = "Dopo esserti $Gfatto:fatta; strada a forza dentro la locanda, metti le uova nel barile. Senti il fetore che impregna l'aria...", enHash = "c758b57a", vanilla = true },
    },
    [8353] = {
        title = { it = "Chiocciare per una mentina", enHash = "237c0b9f", vanilla = true },
        text = { it = "Ah, dolcetto o scherzetto per un bambino malato, eh? Stavo per dire che sei un po' $Gcresciutello:cresciutella; per andare a frugare in giro in cerca di caramelle...\n\nBe', per il mio dolcetto, una Ironforge Mint, dovrai... chiocciare come una gallina! Sì, alle galline piacciono le mentine... be', ok, forse non le ADORANO... ma non ti darò una mentina finché non chiocci come una gallina per me!\n\nAllora, $C, accetti la sfida o no?! È ora di guadagnarti il dolcetto!", enHash = "61171c80", vanilla = true },
        objectives = { it = "Fai l'emote /chicken davanti a Innkeeper Firebrew, e in cambio riceverai una Ironforge Mint!", enHash = "6534541e", vanilla = true },
        progress = { it = "Sto aspettando...", enHash = "e651ce72", vanilla = true },
        reward = { it = "Troppo divertente! Ben fatto, $N! Ecco il tuo dolcetto.\n\nBuona Veglia delle Ombre!", enHash = "af98e56a", vanilla = true },
    },
    [8354] = {
        title = { it = "Chiocciare per una mentina", enHash = "237c0b9f", vanilla = true },
        text = { it = "Ah, dolcetto o scherzetto per un bambino malato, eh? Stavo per dire che sei un po' $Gcresciutello:cresciutella; per andare a frugare in giro in cerca di caramelle...\n\nBe', per il mio dolcetto, una Undercity Mint, dovrai... chiocciare come una gallina! Sì, alle galline piacciono le mentine... be', ok, forse non le ADORANO... ma non ti darò una mentina finché non chiocci come una gallina per me!\n\nAllora, $C, accetti la sfida o no?! È ora di guadagnarti il dolcetto!", enHash = "75d9695c", vanilla = true },
        objectives = { it = "Fai l'emote /chicken davanti a Innkeeper Norman, e in cambio riceverai una Undercity Mint!", enHash = "b4f9a6b1", vanilla = true },
        progress = { it = "Sto aspettando...", enHash = "e651ce72", vanilla = true },
        reward = { it = "Troppo divertente! Ben fatto, $N! Ecco il tuo dolcetto.\n\nBuona Veglia delle Ombre!", enHash = "af98e56a", vanilla = true },
    },
    [8355] = {
        title = { it = "Arriva la caramella gommosa", enHash = "eed616b4", vanilla = true },
        text = { it = "$GUno:Una; che fa dolcetto o scherzetto! Evviva!\n\nBe', anche se stai facendo una cosa nobile raccogliendo caramelle per un bambino malato, non posso lasciarti andare così facilmente. Ho una deliziosa Gnomeregan Gumdrop da dare al bambino malato... se fai il verso di un treno per me! Ahah, sì, sarà questo lo scherzetto! Il prezzo di questa caramella è un verso da treno!\n\nCiuf ciuf, $C!", enHash = "7c7da687", vanilla = true },
        objectives = { it = "Fai l'emote /train davanti a Talvash del Kissel, e in cambio riceverai una Gnomeregan Gumdrop!", enHash = "183108b1", vanilla = true },
        progress = { it = "Be', forza...", enHash = "ce862c4d", vanilla = true },
        reward = { it = "Tuu tuu! Ben fatto, $N! Ecco il tuo dolcetto.\n\nBuona Veglia delle Ombre!", enHash = "4ac5704d", vanilla = true },
    },
    [8356] = {
        title = { it = "Muscoli in cambio di torrone", enHash = "8c8911f4", vanilla = true },
        text = { it = "È un costume... interessante, quello che indossi. Anche se sei gentile e quest'anno aiuti un bambino malato a fare dolcetto o scherzetto, temo che dovrò chiederti di fare uno scherzetto per me!\n\nVediamo... sembri così $Gforte e muscoloso:forte e muscolosa; con quel... costume... fammi vedere i muscoli! Sì, forza, mostrami i muscoli, $Guomo:donna; forte!\n\nQuando, e solo quando, mi mostrerai i muscoli, ti darò un po' di buonissimo Stormwind Nougat. È un ottimo dolcetto della Veglia delle Ombre.", enHash = { "92456251", "8cbe23f9" }, vanilla = true },
        objectives = { it = "Fai l'emote /flex davanti a Innkeeper Allison, e in cambio riceverai lo Stormwind Nougat!", enHash = "4aad4589", vanilla = true },
        progress = { it = "Niente caramelle finché non mi mostri i muscoli, $N...", enHash = "7ab56297", vanilla = true },
        reward = { it = "Sei davvero potente, ahah! Ben fatto, e grazie per essere $Gstato:stata; al gioco. Ecco la tua caramella.\n\nBuona Veglia delle Ombre, $N!", enHash = "867f9ab6", vanilla = true },
    },
    [8357] = {
        title = { it = "Ballare per il marzapane", enHash = "e3a0ac57", vanilla = true },
        text = { it = "Anche se fai dolcetto o scherzetto per un bambino malato, per avere il dolcetto devi comunque fare uno scherzetto! Non possiamo certo cambiare la tradizione, no?...\n\nCredo che oggi il prezzo di un pezzo di marzapane sia scatenarsi e BALLARE! Proprio così, fammi vedere come ti muovi! Balla per me e ti darò del buonissimo marzapane!", enHash = "604da8d4", vanilla = true },
        objectives = { it = "Fai l'emote /dance davanti a Innkeeper Saelienne, e in cambio riceverai il Darnassus Marzipan!", enHash = "c0c394ac", vanilla = true },
        progress = { it = "Sai ballare, vero? Prova così: metti dentro il piede destro... poi fuori il piede destro... dentro il piede destro... e scuotilo tutto...", enHash = "83b9db5e", vanilla = true },
        reward = { it = "Sei proprio $Gun ballerino nato:una ballerina nata;, $N!\n\nEcco il tuo dolcetto, per essere $Gstato:stata; al gioco. Buona Veglia delle Ombre, e salutami tanto il tuo piccolo amico malato! Spero che guarisca presto.", enHash = "8a6011af", vanilla = true },
    },
    [8360] = {
        title = { it = "Ballare per il marzapane", enHash = "e3a0ac57", vanilla = true },
        text = { it = "Anche se fai dolcetto o scherzetto per un bambino malato, per avere il dolcetto devi comunque fare uno scherzetto! Non possiamo certo cambiare la tradizione, no?...\n\nCredo che oggi il prezzo di un pezzo di marzapane sia scatenarsi e BALLARE! Proprio così, fammi vedere come ti muovi! Balla per me e ti darò del buonissimo marzapane!", enHash = "604da8d4", vanilla = true },
        objectives = { it = "Fai l'emote /dance davanti a Innkeeper Pala, e in cambio riceverai il Thunder Bluff Marzipan!", enHash = "4218c179", vanilla = true },
        progress = { it = "Sai ballare, vero? Prova così: metti dentro il piede destro... poi fuori il piede destro... dentro il piede destro... e scuotilo tutto...", enHash = "83b9db5e", vanilla = true },
        reward = { it = "Sei proprio $Gun ballerino nato:una ballerina nata;, $N!\n\nEcco il tuo dolcetto, per essere $Gstato:stata; al gioco. Buona Veglia delle Ombre, e salutami tanto il tuo piccolo amico malato! Spero che guarisca presto.", enHash = "8a6011af", vanilla = true },
    },
    [8368] = {
        title = { it = "La battaglia di Warsong Gulch", enHash = "8df6681f", vanilla = true },
        text = { it = "La battaglia in Warsong Gulch contro le Silverwing Sentinel è di grande importanza. Con la scusa di proteggere una foresta che non appartiene loro, l'Alleanza cerca di togliere all'Orda una delle nostre più grandi fonti di legname.\n\nNon permetterlo, $N! Torna da me con la prova di aver servito l'Orda in modo degno!", enHash = "f14bd843", vanilla = true },
        objectives = { it = "Porta 3 Warsong Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.", enHash = "ce96ac1c", vanilla = true },
        progress = { it = "Porti notizie da Warsong Gulch, $N?", enHash = "fc7f91c0", vanilla = true },
        reward = { it = "Ottimo! Hai dimostrato il tuo valore difendendo le nostre operazioni in Warsong Gulch! Che la voce del tuo onore si spanda in lungo e in largo per le nostre terre.", enHash = "5c8ab8ff", vanilla = true },
    },
    [8370] = {
        title = { it = "Conquistare Arathi Basin", enHash = "1031804f", vanilla = true },
        text = { it = "Il nostro conflitto con l'Alleanza è degenerato in una vera guerra. A questo punto nessuna delle due parti usa più, né si aspetta, falsi pretesti per scendere in battaglia.\n\nLa battaglia per Arathi Basin è una battaglia per le risorse, punto e basta. O l'Alleanza si prende le risorse e le usa contro di noi, o le prendiamo noi e le usiamo per sostenere il nostro sforzo di guerra. Aiuta i Defilers a mantenere il flusso di risorse di cui abbiamo bisogno, $N!", enHash = "372991c0", vanilla = true },
        objectives = { it = "Porta 3 Arathi Basin Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.", enHash = "a7aa8268", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata; con notizie da Arathi, $C?", enHash = "ea114e6a", vanilla = true },
        reward = { it = "Mettere al sicuro le nostre risorse in Arathi è un compito importante! Hai fatto un buon lavoro, $N.", enHash = "2b7c3007", vanilla = true },
    },
    [8372] = {
        title = { it = "Combatti per Warsong Gulch", enHash = "224ce919", vanilla = true },
        text = { it = "Le Silverwing Sentinel sono in guerra con i Warsong Outrider per la distruzione che gli orchi stanno causando alla foresta. Ci sono però più ragioni per difendere questa foresta del semplice amore per la natura.\n\nLa foresta forma una barriera strategica che rende Ashenvale difendibile contro un attacco su larga scala. Senza, Astranaar resisterebbe un giorno o due prima di essere annessa alle Barrens.\n\nFa' la tua parte combattendo i Warsong Outrider, $N! Per l'Alleanza!", enHash = "5a81f8e2", vanilla = true },
        objectives = { it = "Porta 3 Warsong Gulch Mark of Honor a un Alliance Brigadier General fuori dai campi di battaglia.", enHash = "d5dd6588", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata; con notizie dal fronte, $N?", enHash = "8b60b864", vanilla = true },
        reward = { it = "Ben fatto, $N! Hai servito bene l'Alleanza.", enHash = "df092679", vanilla = true },
    },
    [8373] = {
        title = { it = "Il potere del pino", enHash = "c89f9c8f", vanilla = true },
        text = { it = "Quello che odio di più della Veglia delle Ombre sono le bombe puzzolenti che i Reietti usano su Southshore. Chi l'avrebbe mai detto che festeggiare la liberazione volesse dire fare un tale schifo puzzolente?\n\nDurante la Veglia delle Ombre, usa questo detergente per eliminare le schifose bombe puzzolenti che l'Orda lascia cadere qui al villaggio. Usa il potere del pino per combattere i cattivi odori.\n\nFai la tua parte per tenere pulita Southshore, e ti darò qualche dolcetto della Veglia delle Ombre che di sicuro ti piacerà. Affare fatto?", enHash = "3870979d", vanilla = true },
        objectives = { it = "Usa uno Stink Bomb Cleaner per eliminare le Forsaken Stink Bomb lanciate su Southshore. Quando hai finito, torna da Sergeant Hartman a Southshore.", enHash = "b396c0b9", vanilla = true },
        progress = { it = "Quei maledetti Reietti... è già abbastanza brutto che siano non morti, ma poi si scatenano e cominciano a creare problemi nel MIO villaggio!", enHash = "bf177e1a", vanilla = true },
        reward = { it = "Ah, qui intorno si sente già un odore migliore. Quasi.\n\nGrazie a te, $N, Southshore potrebbe superare anche questa Veglia delle Ombre. Ecco i tuoi dolcetti, con i miei ringraziamenti! Se finisci le caramelle, credo che a Ironforge ci sia una gnoma di nome Katrina Shimmerstar che può vendertene altre; credo che ci sia solo durante la Veglia delle Ombre.", enHash = "9ed3aabf", vanilla = true },
    },
    [8374] = {
        title = { it = "Rivendicare Arathi Basin", enHash = "67f22438", vanilla = true },
        text = { it = "Vincere una guerra non vuol dire solo superare l'avversario in astuzia e in combattimento. Spesso la vittoria si riduce semplicemente a produrre più del nemico.\n\nQuello che abbiamo in Arathi Basin è una notevole riserva di risorse per la parte che riuscirà a impadronirsene per prima.\n\nSe sarà l'Alleanza a vincere, vorrà dire più spade e picche per le nostre truppe. Se vincesse l'Orda, quelle spade e quelle picche verrebbero fabbricate lo stesso, solo che sarebbero puntate contro di noi! È il momento di aiutare l'Alleanza in Arathi Basin, $N.", enHash = "23581ba7", vanilla = true },
        objectives = { it = "Porta 3 Arathi Basin Mark of Honor a un Alliance Brigadier General fuori dai campi di battaglia.", enHash = "1e1dc5f4", vanilla = true },
        progress = { it = "Dimmi, che notizie ci sono dal fronte?", enHash = "b5be286a", vanilla = true },
        reward = { it = "Buon lavoro, $Gsoldato:soldatessa;! Continua così e faremo scappare l'Orda fino a Orgrimmar.", enHash = "1fef3fa7", vanilla = true },
    },
    [8384] = {
        title = { it = "Rivendicare Arathi Basin", enHash = "67f22438", vanilla = true },
        progress = { it = "La guerra contro l'Orda sta esaurendo in fretta le nostre provviste, $N. È vitale mantenere il controllo di Arathi Basin perché il flusso di risorse non si interrompa! Hai già dato una mano in Arathi?", enHash = "6b865538", vanilla = true },
        reward = { it = "Buon lavoro, $Gsoldato:soldatessa;! Continua così e faremo scappare l'Orda fino a Orgrimmar.", enHash = "1fef3fa7", vanilla = true },
    },
    [8386] = {
        title = { it = "Combatti per Warsong Gulch", enHash = "224ce919", vanilla = true },
        progress = { it = "Non dimenticare che la lotta per Warsong Gulch è molto più che proteggere degli alberi. Si tratta di mantenere una barriera naturale tra Ashenvale e le Barrens. Porti notizie dal campo di battaglia, $N?", enHash = "e0f40777", vanilla = true },
        reward = { it = "Ben fatto, $N! Hai servito bene l'Alleanza.", enHash = "df092679", vanilla = true },
    },
    [8389] = {
        title = { it = "La battaglia di Warsong Gulch", enHash = "8df6681f", vanilla = true },
        progress = { it = "La battaglia in Warsong Gulch infuria, $N. Fa' la tua parte per cacciare le Silverwing Sentinel dalle nostre terre!", enHash = "2e74dc75", vanilla = true },
        reward = { it = "Ottimo! Hai dimostrato il tuo valore difendendo le nostre operazioni in Warsong Gulch! Che la voce del tuo onore si spanda in lungo e in largo per le nostre terre.", enHash = "b6bb129b", vanilla = true },
    },
    [8390] = {
        title = { it = "Conquistare Arathi Basin", enHash = "1031804f", vanilla = true },
        progress = { it = "La guerra contro la feccia dell'Alleanza richiede risorse, $N! Non possiamo permettere che le nostre scorte si esauriscano nel bel mezzo di una battaglia. Continua a fare in modo che Arathi Basin resti nelle nostre mani!", enHash = "39f71522", vanilla = true },
        reward = { it = "Mettere al sicuro le nostre risorse in Arathi è un compito importante! Hai fatto un buon lavoro, $N.", enHash = "07f0d0f3", vanilla = true },
    },
    [8391] = {
        title = { it = "Rivendicare Arathi Basin", enHash = "67f22438", vanilla = true },
        progress = { it = "La guerra contro l'Orda sta esaurendo in fretta le nostre provviste, $N. È vitale mantenere il controllo di Arathi Basin perché il flusso di risorse non si interrompa! Hai già dato una mano in Arathi?", enHash = "6b865538", vanilla = true },
        reward = { it = "Buon lavoro, $Gsoldato:soldatessa;! Continua così e faremo scappare l'Orda fino a Orgrimmar.", enHash = "1fef3fa7", vanilla = true },
    },
    [8393] = {
        title = { it = "Rivendicare Arathi Basin", enHash = "67f22438", vanilla = true },
        text = { it = "Vincere una guerra non vuol dire solo superare l'avversario in astuzia e in combattimento. Spesso la vittoria si riduce semplicemente a produrre più del nemico.\n\nQuello che abbiamo in Arathi Basin è una notevole riserva di risorse per la parte che riuscirà a impadronirsene per prima.\n\nSe sarà l'Alleanza a vincere, vorrà dire più spade e picche per le nostre truppe. Se vincesse l'Orda, quelle spade e quelle picche verrebbero fabbricate lo stesso, solo che sarebbero puntate contro di noi! È il momento di aiutare l'Alleanza in Arathi Basin, $N.", enHash = "23581ba7", vanilla = true },
        objectives = { it = "Porta 3 Arathi Basin Mark of Honor a un Alliance Brigadier General fuori dai campi di battaglia.", enHash = "1e1dc5f4", vanilla = true },
        progress = { it = "Dimmi, che notizie ci sono dal fronte?", enHash = "b5be286a", vanilla = true },
        reward = { it = "Buon lavoro, $Gsoldato:soldatessa;! Continua così e faremo scappare l'Orda fino a Orgrimmar.", enHash = "77367735", vanilla = true },
    },
    [8399] = {
        title = { it = "Combatti per Warsong Gulch", enHash = "224ce919", vanilla = true },
        text = { it = "Le Silverwing Sentinel sono in guerra con i Warsong Outrider per la distruzione che gli orchi stanno causando alla foresta. Ci sono però più ragioni per difendere questa foresta del semplice amore per la natura.\n\nLa foresta forma una barriera strategica che rende Ashenvale difendibile contro un attacco su larga scala. Senza, Astranaar resisterebbe un giorno o due prima di essere annessa alle Barrens.\n\nFa' la tua parte combattendo i Warsong Outrider, $N! Per l'Alleanza!", enHash = "5a81f8e2", vanilla = true },
        objectives = { it = "Porta 3 Warsong Gulch Mark of Honor a un Alliance Brigadier General fuori dai campi di battaglia.", enHash = "d5dd6588", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata; con notizie dal fronte, $N?", enHash = "8b60b864", vanilla = true },
        reward = { it = "Buon lavoro, $N. Grazie a te, le nostre difese naturali in Ashenvale resteranno intatte per un altro giorno.", enHash = "fae4d65e", vanilla = true },
    },
    [8400] = {
        title = { it = "Combatti per Warsong Gulch", enHash = "224ce919", vanilla = true },
        text = { it = "Le Silverwing Sentinel sono in guerra con i Warsong Outrider per la distruzione che gli orchi stanno causando alla foresta. Ci sono però più ragioni per difendere questa foresta del semplice amore per la natura.\n\nLa foresta forma una barriera strategica che rende Ashenvale difendibile contro un attacco su larga scala. Senza, Astranaar resisterebbe un giorno o due prima di essere annessa alle Barrens.\n\nFa' la tua parte combattendo i Warsong Outrider, $N! Per l'Alleanza!", enHash = "5a81f8e2", vanilla = true },
        objectives = { it = "Porta 3 Warsong Gulch Mark of Honor a un Alliance Brigadier General fuori dai campi di battaglia.", enHash = "d5dd6588", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata; con notizie dal fronte, $N?", enHash = "8b60b864", vanilla = true },
        reward = { it = "Ben fatto, $N! Hai servito bene l'Alleanza.", enHash = "b3441fd7", vanilla = true },
    },
    [8404] = {
        title = { it = "Combatti per Warsong Gulch", enHash = "224ce919", vanilla = true },
        progress = { it = "Non dimenticare che la lotta per Warsong Gulch è molto più che proteggere degli alberi. Si tratta di mantenere una barriera naturale tra Ashenvale e le Barrens. Porti notizie dal campo di battaglia, $N?", enHash = "e0f40777", vanilla = true },
