        progress = { it = "Non dimenticare che la lotta per Warsong Gulch è molto più che proteggere degli alberi. Si tratta di mantenere una barriera naturale tra Ashenvale e le Barrens. Porti notizie dal campo di battaglia, $N?", enHash = "e0f40777", vanilla = true },
