    },
    [8409] = {
        title = { it = "Barili rovinati", enHash = "f1aa36ff", vanilla = true },
        text = { it = "Le uova marce sono state messe nel barile. Le prossime partite di birra del Southshore Inn sono di sicuro rovinate!\n\nOra dovresti tornare da Darkcaller Yanka, al Wickerman Festival nelle Tirisfal Glade, per riferire il tuo successo.", enHash = "e849c5bd", vanilla = true },
        objectives = { it = "Torna da Darkcaller Yanka, al Wickerman Festival nelle Tirisfal Glade.", enHash = "542dc059", vanilla = true },
        reward = { it = "Ah, un successo! Hai mostrato il vero spirito della Veglia delle Ombre: lo spirito dei REIETTI, dovrei dire!\n\n<Darkcaller Yanka ride e si sfrega le mani.>\n\nMi rallegra sapere che Southshore ora dovrà festeggiare con birra cattiva o farne a meno! Quanto a te, prendi questi dolcetti. Credo che ne farai buon uso!", enHash = "94399300", vanilla = true },
    },
    [8426] = {
        title = { it = "La battaglia di Warsong Gulch", enHash = "8df6681f", vanilla = true },
        text = { it = "La battaglia in Warsong Gulch contro le Silverwing Sentinel è di grande importanza. Con la scusa di proteggere una foresta che non appartiene loro, l'Alleanza cerca di togliere all'Orda una delle nostre più grandi fonti di legname.\n\nNon permetterlo, $N! Torna da me con la prova di aver servito l'Orda in modo degno!", enHash = "f14bd843", vanilla = true },
        objectives = { it = "Porta 3 Warsong Gulch Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.", enHash = "fb07e49f", vanilla = true },
        progress = { it = "La battaglia in Warsong Gulch contro le Silverwing Sentinel è di grande importanza. Con la scusa di proteggere una foresta che non appartiene loro, l'Alleanza cerca di togliere all'Orda una delle nostre più grandi fonti di legname.\n\nNon permetterlo, $N! Torna da me con la prova di aver servito l'Orda in modo degno!", enHash = "454b8a7d", vanilla = true },
        reward = { it = "Ottimo! Hai dimostrato il tuo valore difendendo le nostre operazioni in Warsong Gulch! Che la voce del tuo onore si spanda in lungo e in largo per le nostre terre.", enHash = "b6bb129b", vanilla = true },
    },
    [8427] = {
        title = { it = "La battaglia di Warsong Gulch", enHash = "8df6681f", vanilla = true },
        text = { it = "La battaglia in Warsong Gulch contro le Silverwing Sentinel è di grande importanza. Con la scusa di proteggere una foresta che non appartiene loro, l'Alleanza cerca di togliere all'Orda una delle nostre più grandi fonti di legname.\n\nNon permetterlo, $N! Torna da me con la prova di aver servito l'Orda in modo degno!", enHash = "f14bd843", vanilla = true },
        objectives = { it = "Porta 3 Warsong Gulch Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.", enHash = "fb07e49f", vanilla = true },
        progress = { it = "Porti notizie da Warsong Gulch, $N?", enHash = "fc7f91c0", vanilla = true },
        reward = { it = "Ottimo! Hai dimostrato il tuo valore difendendo le nostre operazioni in Warsong Gulch! Che la voce del tuo onore si spanda in lungo e in largo per le nostre terre.", enHash = "5c8ab8ff", vanilla = true },
    },
    [8431] = {
        title = { it = "La battaglia di Warsong Gulch", enHash = "8df6681f", vanilla = true },
        progress = { it = "La battaglia in Warsong Gulch infuria, $N. Fa' la tua parte per cacciare le Silverwing Sentinel dalle nostre terre!", enHash = "2e74dc75", vanilla = true },
