    },
    [8432] = {
        title = { it = "La battaglia di Warsong Gulch", enHash = "8df6681f", vanilla = true },
        progress = { it = "La battaglia in Warsong Gulch infuria, $N. Fa' la tua parte per cacciare le Silverwing Sentinel dalle nostre terre!", enHash = "2e74dc75", vanilla = true },
        reward = { it = "Ben fatto, $C! Hai contribuito a garantire all'Orda il possesso di Warsong Gulch!", enHash = "181ff8f4", vanilla = true },
    },
    [8436] = {
        title = { it = "Conquistare Arathi Basin", enHash = "1031804f", vanilla = true },
        text = { it = "Il nostro conflitto con l'Alleanza è degenerato in una vera guerra. A questo punto nessuna delle due parti usa più, né si aspetta, falsi pretesti per scendere in battaglia.\n\nLa battaglia per Arathi Basin è una battaglia per le risorse, punto e basta. O l'Alleanza si prende le risorse e le usa contro di noi, o le prendiamo noi e le usiamo per sostenere il nostro sforzo di guerra. Aiuta i Defilers a mantenere il flusso di risorse di cui abbiamo bisogno, $N!", enHash = "372991c0", vanilla = true },
        objectives = { it = "Porta 3 Arathi Basin Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.", enHash = "a7aa8268", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata; con notizie da Arathi, $C?", enHash = "ea114e6a", vanilla = true },
        reward = { it = "Mettere al sicuro le nostre risorse in Arathi è un compito importante! Hai fatto un buon lavoro, $N.", enHash = "2b7c3007", vanilla = true },
    },
    [8438] = {
        title = { it = "Conquistare Arathi Basin", enHash = "1031804f", vanilla = true },
        text = { it = "Il nostro conflitto con l'Alleanza è degenerato in una vera guerra. A questo punto nessuna delle due parti usa più, né si aspetta, falsi pretesti per scendere in battaglia.\n\nLa battaglia per Arathi Basin è una battaglia per le risorse, punto e basta. O l'Alleanza si prende le risorse e le usa contro di noi, o le prendiamo noi e le usiamo per sostenere il nostro sforzo di guerra. Aiuta i Defilers a mantenere il flusso di risorse di cui abbiamo bisogno, $N!", enHash = "372991c0", vanilla = true },
        objectives = { it = "Porta 3 Arathi Basin Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.", enHash = "a7aa8268", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata; con notizie da Arathi, $C?", enHash = "ea114e6a", vanilla = true },
        reward = { it = "Mettere al sicuro le nostre risorse in Arathi è un compito importante! Hai fatto un buon lavoro, $N.", enHash = "07f0d0f3", vanilla = true },
    },
    [8440] = {
        title = { it = "Conquistare Arathi Basin", enHash = "1031804f", vanilla = true },
        progress = { it = "La guerra contro la feccia dell'Alleanza richiede risorse, $N! Non possiamo permettere che le nostre scorte si esauriscano nel bel mezzo di una battaglia. Continua a fare in modo che Arathi Basin resti nelle nostre mani!", enHash = "39f71522", vanilla = true },
        reward = { it = "Ottimo lavoro, $N! Finché Arathi Basin resterà sotto il nostro controllo, le nostre provviste saranno ben fornite.", enHash = "7dd588b4", vanilla = true },
    },
    [8492] = {
        title = { it = "L'Alleanza ha bisogno di Copper Bar!", enHash = "5eb0b397", vanilla = true },
        text = { it = "Ehi, $C, mi sembri abbastanza in forma per contribuire allo sforzo bellico! Qui ci serve tutto l'aiuto possibile per mettere insieme il materiale bellico per la guerra di Ahn'Qiraj, ed è il tuo giorno fortunato.\n\nRaccolgo Copper Bar in pile da venti. È per una buona causa, che ne dici? Pensi di poter dare una mano all'Alleanza?", enHash = "4badbae2", vanilla = true },
        objectives = { it = "Porta 20 Copper Bar a Sergeant Stonebrow, nel Military Ward di Ironforge.", enHash = "8e82ecff", vanilla = true },
        progress = { it = "Hai già raccolto quelle venti Copper Bar, $Gsoldato:soldatessa;?", enHash = "3f87966a", vanilla = true },
        reward = { it = "Ce l'hai fatta, $Gragazzo:ragazza;! Metteremo subito quelle Copper Bar sul mucchio e le useremo per fare il materiale bellico. Sono gli sforzi di gente come te che mi rendono orgoglioso di servire l'Alleanza. Bel lavoro, $Gsoldato:soldatessa;!\n\nE se ti capita di trovare altre Copper Bar, fa' in modo che arrivino a me.", enHash = { "a2fb38b1", "d97edc09" }, vanilla = true },
    },
    [8493] = {
        title = { it = "L'Alleanza ha bisogno di altre Copper Bar!", enHash = "b4ada8a8", vanilla = true },
        text = { it = "Di nuovo qui, $C? Magnifico! Ci servono ancora pile di Copper Bar, se riesci a procurarle per lo sforzo bellico di Ahn'Qiraj. Ci dai una mano?", enHash = "261d57b6", vanilla = true },
        objectives = { it = "Porta 20 Copper Bar a Sergeant Stonebrow, all'aerodromo di Dun Morogh.", enHash = "b2f7b0a6", vanilla = true },
        progress = { it = "Di nuovo qui, $C? Magnifico! Le barre che ci hai portato finora saranno davvero utili per fabbricare ogni genere di cose per la guerra. So, per esempio, che il rame servirà per i pezzi dei carri a vapore in costruzione, e per una piccola flotta di girocotteri che contiamo di schierare, se ci sarà tempo.\n\nMa non farti ingannare dalle pile che vedi qui: ci servono ancora Copper Bar, se riesci a procurarle per lo sforzo bellico di Ahn'Qiraj. Ci dai una mano?", enHash = "34f3f622", vanilla = true },
        reward = { it = "Ottimo lavoro! Scavare per trovare quel rame e fonderlo dev'essere stata una bella avventura. A meno che tu non abbia comprato le barre alla casa d'aste. In ogni caso, a me va bene. Meriti un encomio per il tuo contributo allo sforzo bellico, $C. E non esitare a portarmi altre Copper Bar, se ne hai.", enHash = "8576f754", vanilla = true },
    },
    [8494] = {
        title = { it = "L'Alleanza ha bisogno di Iron Bar!", enHash = "b2d4b346", vanilla = true },
        text = { it = "Ma guarda chi si vede, $Gsignor Elegantone:signorina Elegantona;, che piacere per gli occhi. Nel caso non l'avessi sentito dire mentre eri là fuori a \"fare avventure\", l'Alleanza si sta preparando a una guerra ad Ahn'Qiraj e ha bisogno di Iron Bar... un mucchio enorme. Portamele in pile da venti. Possiamo contare su di te, vero, $C?", enHash = { "65a7bb91", "fd865b52" }, vanilla = true },
        objectives = { it = "Porta 20 Iron Bar a Corporal Carnes, nel Military Ward di Ironforge.", enHash = "ccdfd056", vanilla = true },
        progress = { it = "Se hai quelle venti Iron Bar, non voglio sapere dove le tieni nascoste!", enHash = "92e324e5", vanilla = true },
        reward = { it = "Bene, bene, guarda chi c'è: $N. E ce l'hai fatta. Immagino che adesso dovrò tenerti d'occhio. Mi costa dirlo, ma grazie per i tuoi sforzi. L'Alleanza non lo dimenticherà, e nemmeno io. Ora torna là fuori e sgobba per raccogliere qualsiasi altra cosa serva.", enHash = "e04984af", vanilla = true },
    },
    [8495] = {
        title = { it = "L'Alleanza ha bisogno di altre Iron Bar!", enHash = "6efdb897", vanilla = true },
        text = { it = "Già di ritorno? Smettila di farmi rivedere la pessima opinione che ho di te, $C, mi stai facendo sentire tutto tenero dentro. Allora, come vedi non abbiamo ancora abbastanza Iron Bar per tutte le armi, le armature, i carri a vapore e compagnia bella che vanno costruiti per la caccia agli insetti. Pensi di farcela a portarmi un'altra pila di venti Iron Bar, tra un viaggio e l'altro a Zul'Gurub, o dovunque andiate a bighellonare voi ragazzi di oggi?", enHash = "ea9d7d54", vanilla = true },
        objectives = { it = "Porta 20 Iron Bar a Corporal Carnes, all'aerodromo di Dun Morogh.", enHash = "e301d77d", vanilla = true },
        progress = { it = "Già di ritorno? Smettila di farmi rivedere la pessima opinione che ho di te, $C, mi stai facendo sentire tutto tenero dentro. Allora, come vedi non abbiamo ancora abbastanza Iron Bar per tutte le armi, le armature, i carri a vapore e compagnia bella che vanno costruiti per la caccia agli insetti. Pensi di farcela a portarmi un'altra pila di venti Iron Bar, tra un viaggio e l'altro a Zul'Gurub, o dovunque andiate a bighellonare voi ragazzi di oggi?", enHash = "904d14c2", vanilla = true },
        reward = { it = "Dev'essere una giornata fredda nelle Burning Steppes. Guarda un po', c'è $N, ed è $Gvenuto:venuta; a portarmi un regalo. Venti Iron Bar! Proprio quello che ho sempre desiderato.\n\nMa scherzi a parte, grazie, $N. Fai onore a te $Gstesso:stessa; e all'Alleanza. Ora torna là fuori e porta altra roba per lo sforzo bellico!", enHash = { "5606b6f3", "fdbfe1e0" }, vanilla = true },
    },
    [8499] = {
        title = { it = "L'Alleanza ha bisogno di Thorium Bar!", enHash = "6d47776e", vanilla = true },
        text = { it = "È molto gentile da parte tua informarti su ciò di cui l'Alleanza ha bisogno. Oltre a tutte le altre raccolte in corso, ci serve una grande quantità di Thorium Bar, ed è questo il compito di cui sono responsabile. Il torio servirà a creare molte cose diverse per la guerra, prima fra tutte un battaglione di carri a vapore da trasportare per via aerea a Silithus appena saranno pronti. Puoi aiutarci in questa impresa, $C?", enHash = "1656094d", vanilla = true },
        objectives = { it = "Porta 20 Thorium Bar a Dame Twinbraid, nel Military Ward di Ironforge.", enHash = "ca9ac355", vanilla = true },
        progress = { it = "Oh, un carico da parte di mio fratello? Splendido! Oggi la fortuna mi sorride davvero!", enHash = "ed23f6f5", vanilla = true },
        reward = { it = "Quindi Gnoarn non si fida delle mie capacità di ricognizione? Chissà perché...", enHash = "05c59e2e", vanilla = true },
    },
    [8500] = {
        title = { it = "L'Alleanza ha bisogno di altre Thorium Bar!", enHash = "d6e9247d", vanilla = true },
        text = { it = "Che bello rivederti, $N. Spero che tu stia bene. È vero, abbiamo ancora bisogno di Thorium Bar. Se ne hai da parte, le raccolgo per lo sforzo bellico di Ahn'Qiraj.", enHash = "9f092ad9", vanilla = true },
        objectives = { it = "Porta 20 Thorium Bar a Dame Twinbraid, all'aerodromo di Dun Morogh.", enHash = "8ff421fc", vanilla = true },
        progress = { it = "Che bello rivederti, $N. Spero che tu stia bene. È vero, abbiamo ancora bisogno di Thorium Bar. Se ne hai da parte, le raccolgo per lo sforzo bellico di Ahn'Qiraj.", enHash = "7bec2ccb", vanilla = true },
        reward = { it = "Eccellente, $C! Un lavoro ben fatto. Mi assicurerò che quelle barre finiscano sul bancale e nelle mani dei fabbri e degli ingegneri che lavorano sodo per preparare i rifornimenti del nostro esercito. Grazie ancora, e se trovi altre Thorium Bar, passa pure da me.", enHash = "2613d1c0", vanilla = true },
    },
    [8503] = {
        title = { it = "L'Alleanza ha bisogno di Stranglekelp!", enHash = "d9443324", vanilla = true },
        text = { it = "Allora, $C, ti ho già parlato di tutti i favolosi usi della Stranglekelp? Sì? Be', pazienza... comunque ce ne serve tanta, e quando dico tanta intendo TANTISSIMA! Pensi di poterci dare una mano? So che significa rinunciare a tutte le cose meravigliose che ci puoi fare, ma è per una buona causa!", enHash = "f5cd6fa3", vanilla = true },
        objectives = { it = "Porta 20 Stranglekelp a Private Draxlegauge, nel Military Ward di Ironforge.", enHash = "19189998", vanilla = true },
        progress = { it = "Non è vero! Non prenderei mai di nascosto un po' di Stranglekelp dalle pile che ho qui. Anche se la tentazione ci sarebbe, visto che è praticamente una panacea di utilità pratica. *coff* Non è che per caso hai la Stranglekelp di cui parlavamo prima?", enHash = "b2439110", vanilla = true },
        reward = { it = "Evviva! Altre venti sistemate. Sei $Gil migliore:la migliore;. Immagino che dovrei impacchettarle tutte prima che appassiscano. Tanta Stranglekelp, così poco tempo!\n\nGrazie ancora, $C!", enHash = "9fc771eb", vanilla = true },
    },
    [8504] = {
        title = { it = "L'Alleanza ha bisogno di altra Stranglekelp!", enHash = "42e5e033", vanilla = true },
        text = { it = "Ma guarda, ciao di nuovo... com'era? Ah sì, $N! Sei $Gvenuto:venuta; a vedere se mi serve ancora Stranglekelp, eh? Be', è il tuo giorno fortunato, perché la risposta a questa importantissima domanda è un SÌ convintissimo! Pensi di riuscire a raccoglierne altre venti?", enHash = "75f00ff0", vanilla = true },
        objectives = { it = "Porta 20 Stranglekelp a Private Draxlegauge, all'aerodromo di Dun Morogh.", enHash = "280591bf", vanilla = true },
        progress = { it = "Ma guarda, ciao di nuovo... com'era? Ah sì, $N! Sei $Gvenuto:venuta; a vedere se mi serve ancora Stranglekelp, eh? Be', è il tuo giorno fortunato, perché la risposta a questa importantissima domanda è un SÌ convintissimo! Pensi di riuscire a raccoglierne altre venti?", enHash = "75f00ff0", vanilla = true },
        reward = { it = "Oh, santo cielo, che carico di Stranglekelp hai lì! Presto, mettiamola in una cassa per tenerla fresca. Portando questa partita hai fatto a me... cioè, a noi, all'Alleanza, un grande favore. Farò in modo che tutti sappiano che sei $Gstato:stata; tu, $Gil grande:la grande; $N, ad aiutare a far pendere la bilancia nello sforzo bellico di Ahn'Qiraj con il tuo contributo di Stranglekelp!", enHash = "2016b1f8", vanilla = true },
    },
    [8505] = {
        title = { it = "L'Alleanza ha bisogno di Purple Lotus!", enHash = "c546d4d9", vanilla = true },
        text = { it = "$C, il Purple Lotus è un fiore dai molteplici usi. Sono qui su richiesta dell'Alleanza come autorità in materia, per conservare le erbe raccolte e assicurarmi che il suo sforzo bellico ottenga abbastanza Purple Lotus per qualunque impiego abbia in mente.\n\nVorrei che tu viaggiassi per il mondo e tornassi da me con qualcuno di questi fiori. Puoi farlo?", enHash = "c4179268", vanilla = true },
        objectives = { it = "Porta 20 Purple Lotus a Master Nightsong, nel Military Ward di Ironforge.", enHash = "9398070a", vanilla = true },
        progress = { it = "Hai le erbe di Purple Lotus che ti ho chiesto?", enHash = "0b4e53a3", vanilla = true },
        reward = { it = "Il tuo contributo è molto apprezzato, $C. Solo con gli sforzi uniti di tutti potremo respingere l'avanzata spietata dei silitidi e di qualunque forza li stia spingendo avanti. Anche l'Orda sta ammassando la sua scorta di Purple Lotus. Se ne trovi altro, ti prego, torna da me.", enHash = "b1cadaec", vanilla = true },
    },
    [8506] = {
        title = { it = "L'Alleanza ha bisogno di altro Purple Lotus!", enHash = "2ee881e8", vanilla = true },
        text = { it = "$GBentornato:Bentornata;, $C. La nostra raccolta cresce, ma anche ora abbiamo bisogno di altro Purple Lotus. Se è ancora in tuo potere raccogliere altre di queste erbe, ti prego di farlo e di riportarmele qui.", enHash = "5fdcfcb5", vanilla = true },
        objectives = { it = "Porta 20 Purple Lotus a Master Nightsong, all'aerodromo di Dun Morogh.", enHash = "5b298831", vanilla = true },
        progress = { it = "$GBentornato:Bentornata;, $C. La nostra raccolta cresce, ma anche ora abbiamo bisogno di altro Purple Lotus. Se è ancora in tuo potere raccogliere altre di queste erbe, ti prego di farlo e di riportarmele qui.", enHash = "2a5e2673", vanilla = true },
        reward = { it = "Accetto con piacere il tuo contributo a nome dell'Alleanza, $N. I tuoi sforzi porteranno direttamente alla creazione di varie pozioni e oli a sostegno dei nostri uomini e delle nostre donne sul campo. Grazie, e se ne trovassi altro, considera di tornare da me.", enHash = "68f86b54", vanilla = true },
    },
    [8509] = {
        title = { it = "L'Alleanza ha bisogno di Arthas' Tears!", enHash = "0b5a391d", vanilla = true },
        text = { it = "Sarò semplice e diretta, $C. L'Alleanza deve raccogliere una grande quantità di Arthas' Tears per lo sforzo bellico di Ahn'Qiraj. Non chiedermi a cosa servano: io eseguo solo gli ordini. Ma vorrei che tu raccogliessi quante più di queste erbe puoi e me le riportassi qui. Sei $Gdisposto:disposta; a farlo?", enHash = "1456bf16", vanilla = true },
        objectives = { it = "Porta 20 Arthas' Tears a Sergeant Major Germaine, nel Military Ward di Ironforge.", enHash = "ee13f279", vanilla = true },
        progress = { it = "Come dici? Parla più forte, $C! Hai quel carico di Arthas' Tears che ti ho chiesto?", enHash = "7388aa56", vanilla = true },
        reward = { it = "Bel lavoro, $C. Devo dire che sono piacevolmente sorpresa. Non crederesti a quanta gente è passata di qui offrendosi di aiutare, senza poi tornare mai. Lasciami mettere queste in una cassa e registrarle a tuo nome, poi potremo riparlarne, per vedere se mi servono altre di queste piante.", enHash = "909426ec", vanilla = true },
    },
    [8510] = {
        title = { it = "L'Alleanza ha bisogno di altre Arthas' Tears!", enHash = "d5ee2dee", vanilla = true },
        text = { it = "Ok, a quanto pare mi servono ancora Arthas' Tears. Immagino che potrai trovarle più o meno nella stessa zona in cui le hai raccolte per me l'ultima volta. Prima le avremo, prima potremo lanciare l'offensiva contro le forze di Ahn'Qiraj.\n\nCi dai di nuovo una mano, $C?", enHash = "4a9f0826", vanilla = true },
        objectives = { it = "Porta 20 Arthas' Tears a Sergeant Major Germaine, all'aerodromo di Dun Morogh.", enHash = "158a8320", vanilla = true },
        progress = { it = "Ok, a quanto pare mi servono ancora Arthas' Tears, $C. Immagino che potrai trovarle più o meno nella stessa zona in cui le hai raccolte per me l'ultima volta. Lo sforzo bellico procede bene, ma prima le avremo, prima potremo lanciare l'offensiva contro le forze di Ahn'Qiraj.\n\nCi dai di nuovo una mano, $N?", enHash = "cf9231b9", vanilla = true },
        reward = { it = "Semplicemente eccezionale, $N! Fai davvero onore all'Alleanza. Metterò via queste erbe finché qualcuno non verrà a trasformarle in qualcosa di utile per la guerra. Torna pure quando vuoi, soprattutto se hai altre Arthas' Tears per me.", enHash = "f24aa1a6", vanilla = true },
    },
    [8511] = {
        title = { it = "L'Alleanza ha bisogno di Light Leather!", enHash = "2aae059f", vanilla = true },
        text = { it = "Noi Stoneflayer abbiamo una lunga tradizione di scuoiatori, $C. Per questo l'Alleanza ha chiesto alla mia famiglia di aiutare a raccogliere Light Leather per lo sforzo bellico di Ahn'Qiraj. Sono qui per assicurarmi che il cuoio venga conciato come si deve, qualunque sia l'uso che vogliono farne. Ma ci serve il tuo aiuto.\n\nVisto che devo restare qui a fare questo, ho bisogno che tu vada a raccogliere le pelli e me le riporti qui. Che ne dici, $Gragazzo:ragazza;, ci provi?", enHash = { "732085f6", "f70e011c" }, vanilla = true },
        objectives = { it = "Porta 10 Light Leather a Bonnie Stoneflayer, nel Military Ward di Ironforge.", enHash = "e375f5b3", vanilla = true },
        progress = { it = "$C, spero proprio che quello sia il Light Leather che mi avevi promesso.", enHash = "566320f2", vanilla = true },
        reward = { it = "Direi che l'Alleanza sarà molto contenta di queste tue pelli, $C. Farò in modo che non se ne sprechi nemmeno una. Grazie, e ripassa da me quando le avrò contate, per vedere se ce ne servono altre.", enHash = "9d91d48d", vanilla = true },
    },
    [8512] = {
        title = { it = "L'Alleanza ha bisogno di altro Light Leather!", enHash = "f541fa70", vanilla = true },
        text = { it = "Che piacere rivederti, $N. Sembra proprio che ci serva altro Light Leather per fabbricare il materiale bellico. Se mi portassi una pila da dieci, sarebbe perfetto.", enHash = "42e8dc85", vanilla = true },
        objectives = { it = "Porta 10 Light Leather a Bonnie Stoneflayer, all'aerodromo di Dun Morogh.", enHash = "9b93335a", vanilla = true },
        progress = { it = "Che piacere rivederti, $N. Sembra proprio che ci serva altro Light Leather per fabbricare il materiale bellico. Se mi portassi una pila da dieci, sarebbe perfetto.", enHash = "a64f02ae", vanilla = true },
        reward = { it = "Grazie per la tua generosa donazione, $N. Le metto subito sul mucchio, e vedrai che in un attimo diventeranno una bella armatura, qualche toppa di cuoio o qualcos'altro per i nostri preparativi. Pare che il Light Leather non basti mai. Torna a trovarmi presto.", enHash = "d5608b78", vanilla = true },
    },
    [8513] = {
        title = { it = "L'Alleanza ha bisogno di Medium Leather!", enHash = "cf49ac46", vanilla = true },
        text = { it = "Sì, $Gsignore:signora;, mi hanno incaricato di raccogliere e registrare tutto il Medium Leather raccolto per lo sforzo bellico. Se hai modo di procurarti del Medium Leather, da qualunque fonte, per favore portalo qui da me. Mi farebbe davvero comodo una mano, se hai un po' di tempo.", enHash = { "80295873", "d3385bd6" }, vanilla = true },
        objectives = { it = "Porta 10 Medium Leather a Private Porter, nel Military Ward di Ironforge.", enHash = "7aec9f5c", vanilla = true },
        progress = { it = "Sì, $Gsignore:signora;, mi ricordo di te. È il Medium Leather quello che hai lì con te?", enHash = { "4d9dd403", "fdab5c00" }, vanilla = true },
        reward = { it = "Caspita! Mi sembra che tu fossi qui proprio poco fa a offrirti di aiutare. Grazie mille per la donazione. Adesso le impacchetto e le conto tutte. Sai proprio come rallegrare la giornata a un povero soldato.", enHash = "befea899", vanilla = true },
    },
    [8514] = {
        title = { it = "L'Alleanza ha bisogno di altro Medium Leather!", enHash = "57345195", vanilla = true },
        text = { it = "Sì, $Gsignore:signora;, pare che finora abbiamo raccolto un sacco di pezzi di Medium Leather. So che è chiedere molto, ma se sei ancora $Gdisposto:disposta;, mi farebbe comodo il tuo aiuto per intaccare quello che resta della mia quota.", enHash = { "85c56a5e", "58c8171b" }, vanilla = true },
        objectives = { it = "Porta 10 Medium Leather a Private Porter, all'aerodromo di Dun Morogh.", enHash = "2b2b1983", vanilla = true },
        progress = { it = "Sì, $Gsignore:signora;, pare che abbiamo raccolto un sacco di pezzi di Medium Leather, ma ce ne servono altri. Ti assicuro che sarà tutto usato bene: non se ne sprecherà nemmeno un pezzo. So che è chiedere molto, ma se sei ancora $Gdisposto:disposta;, mi farebbe comodo il tuo aiuto per intaccare quello che resta della mia quota.", enHash = { "56dca16f", "4eaf91d2" }, vanilla = true },
        reward = { it = "Accidenti, che quantità di Medium Leather mi hai portato, $Gsignore:signora;! Farò in modo che venga usato tutto come si deve, sissignore. Con il tuo aiuto raggiungeremo la nostra stima di Medium Leather in un baleno!\n\nGrazie, $N!", enHash = { "b552f2dc", "50b82a7f" }, vanilla = true },
    },
    [8515] = {
        title = { it = "L'Alleanza ha bisogno di Thick Leather!", enHash = "db701ef8", vanilla = true },
        text = { it = "Oh, che bello, sarà fantastico! $C, lo sforzo bellico di Ahn'Qiraj è in pieno svolgimento, e mi hanno incaricato di tenere il conto di tutto il Thick Leather che arriva. Ci faremo un sacco di cose, ma prima dobbiamo raccoglierne una tonnellata. E lo dico alla lettera! Ed è qui che entri in gioco tu.\n\nAllora, pensi di poter andare là fuori e riportarmi una bella pila grassa di Thick Leather? Eh? Eh?!", enHash = "46ae0b59", vanilla = true },
        objectives = { it = "Porta 10 Thick Leather a Marta Finespindle, nel Military Ward di Ironforge.", enHash = "2fa2efa9", vanilla = true },
        progress = { it = "È Thick Leather quello che hai lì nello zaino, $C? Lo è? Non vedo l'ora che me lo consegni! Saranno tutti così contenti di noi, non credi?", enHash = "48f69d82", vanilla = true },
        reward = { it = "Oh, lo sapevo che ce l'avresti fatta, $C, lo sapevo! Lo metterò nelle mani giuste il prima possibile. Allora, vediamo un po'. Mmm, pare che il conto stia procedendo piuttosto bene. Ripassa da me tra un attimo, quando avrò finito di contare, per vedere se ce ne serve altro. Perché se è così, voglio che sia tu ad andare a raccoglierlo per me!", enHash = "f81324eb", vanilla = true },
    },
    [8516] = {
        title = { it = "L'Alleanza ha bisogno di altro Thick Leather!", enHash = "a60413c9", vanilla = true },
        text = { it = "Già, la pila non è ancora abbastanza alta. $N, non abbiamo ancora raggiunto il nostro obiettivo di Thick Leather. Pensa a tutte le cose che possiamo fare con tutto quel cuoio! Armature e armi di ogni tipo. Roba per l'interno dei carri a vapore e per i mirini dei fucili! Occhiali d'ingegneria, e scommetto che se finiamo per raccoglierne troppo potremmo dare il resto all'Orda per i suoi zeppelin!\n\nMi riporti altro Thick Leather?", enHash = "eec26f47", vanilla = true },
        objectives = { it = "Porta 10 Thick Leather a Marta Finespindle, all'aerodromo di Dun Morogh.", enHash = "33079850", vanilla = true },
        progress = { it = "Già, la pila non è ancora abbastanza alta. $N, non abbiamo ancora raggiunto il nostro obiettivo di Thick Leather. Pensa a tutte le cose che possiamo fare con tutto quel cuoio! Armature e armi di ogni tipo. Roba per l'interno dei carri a vapore e per i mirini dei fucili! E occhiali d'ingegneria, che sono sempre divertenti!\n\nMi riporti altro Thick Leather?", enHash = "5b4dbaaf", vanilla = true },
        reward = { it = "Ce l'hai fatta di nuovo! È semplicemente incredibile come tu vada là fuori, raccolga tutta questa roba e poi la riporti qui a consegnarla. Te lo dico io: quando scopriranno quanto hai aiutato qui, non potrai fare due passi per strada senza che la gente ti chieda l'autografo!\n\nGrazie ancora per la tua generosissima donazione di Thick Leather, $N.", enHash = "03910960", vanilla = true },
    },
    [8517] = {
        title = { it = "L'Alleanza ha bisogno di Linen Bandage!", enHash = "46074775", vanilla = true },
        text = { it = "La guerra ad Ahn'Qiraj sarà lunga e sanguinosa. L'Alleanza fa una cosa molto saggia a chiedere l'aiuto di te e di quelli come te per accumulare il materiale bellico necessario, prima di gettarsi a capofitto nel conflitto.\n\nMi è stato chiesto di dirigere la raccolta di Linen Bandage per la guerra, e spero che tu mi aiuterai a radunarne quante ne servono. Non è una questione da poco, ma almeno le Linen Bandage sono le meno difficili da preparare. Sei con noi, $C?", enHash = "c9cf2a60", vanilla = true },
        objectives = { it = "Porta 20 Linen Bandage a Sentinel Silversky, nel Military Ward di Ironforge.", enHash = "6f3e6abd", vanilla = true },
        progress = { it = "Hai le venti Linen Bandage che mi servono, $C?", enHash = "496864a4", vanilla = true },
        reward = { it = "Molti sono i soldati che trarranno beneficio dal contributo che hai dato oggi, $C. Mi assicurerò di persona che l'Alleanza venga a sapere dei tuoi sforzi. Concedimi un momento per riporre come si deve queste bende e aggiornare il conto, poi ripassa da me per vedere se me ne servono altre.\n\nChe la Luce di Elune risplenda su di te, $R!", enHash = "8fe05bdf", vanilla = true },
    },
    [8518] = {
        title = { it = "L'Alleanza ha bisogno di altre Linen Bandage!", enHash = "cdf1ecc4", vanilla = true },
        text = { it = "Sono sempre stupita dall'altruismo di alcuni, quando tanti altri si abbandonano invece all'egoismo. $C, mi serve ancora un certo numero di Linen Bandage prima che il mio incarico qui sia concluso. Mi aiuterai ancora una volta a raccoglierle?", enHash = "cf29a7b0", vanilla = true },
        objectives = { it = "Porta 20 Linen Bandage a Sentinel Silversky, all'aerodromo di Dun Morogh.", enHash = "5623bd64", vanilla = true },
        progress = { it = "Sono sempre stupita dall'altruismo di alcuni, quando tanti altri si abbandonano invece all'egoismo. $C, mi serve ancora un certo numero di Linen Bandage prima che il mio incarico qui sia concluso. Mi aiuterai ancora una volta a raccoglierle?", enHash = "cf29a7b0", vanilla = true },
        reward = { it = "Meriti un encomio, $N. Mentre c'è chi approfitta dell'economia di guerra per riempirsi le tasche in preda all'avidità, tu hai dimostrato più e più volte che la tua devozione all'Alleanza, e anzi a tutta Azeroth, viene prima di tutto.\n\nChe le benedizioni di Elune siano sempre con te!", enHash = "56ebf34b", vanilla = true },
    },
    [8520] = {
        title = { it = "L'Alleanza ha bisogno di Silk Bandage!", enHash = "b7eddaea", vanilla = true },
        text = { it = "Con la guerra di Ahn'Qiraj alle porte, dobbiamo fare tutto il possibile perché i nostri soldati abbiano tutto ciò che serve. Ed è proprio quello che facciamo qui. Per quanto mi riguarda, mi hanno affidato il compito di raccogliere abbastanza Silk Bandage.\n\nPensi di potermi aiutare, $C?", enHash = "fb3c2e05", vanilla = true },
        objectives = { it = "Porta 20 Silk Bandage a Nurse Stonefield, nel Military Ward di Ironforge.", enHash = "85b53b20", vanilla = true },
        progress = { it = "Ciao, $C, sei $Griuscito:riuscita; a procurarti quelle venti Silk Bandage?", enHash = "17f4f4e2", vanilla = true },
        reward = { it = "$C, ce l'hai fatta! Grazie a te siamo un altro passo più vicini al nostro obiettivo di Silk Bandage. Le metto via, e poi, se vuoi, possiamo parlarne ancora.", enHash = "23fef1ac", vanilla = true },
    },
    [8521] = {
        title = { it = "L'Alleanza ha bisogno di altre Silk Bandage!", enHash = "8281cfbb", vanilla = true },
        text = { it = "È molto gentile da parte tua offrirti di nuovo di aiutarmi, $C. Pare che abbiamo raccolto un bel numero di Silk Bandage, ma ce ne serviranno altre.", enHash = "539ec643", vanilla = true },
        objectives = { it = "Porta 20 Silk Bandage a Nurse Stonefield, all'aerodromo di Dun Morogh.", enHash = "85003747", vanilla = true },
        progress = { it = "È molto gentile da parte tua offrirti di nuovo di aiutarmi, $C. Pare che abbiamo raccolto un bel numero delle Silk Bandage che ci hanno chiesto, ma ce ne servono ancora. $N, c'è modo che tu riesca a mettere insieme un altro fascio e a riportarmelo qui? L'Alleanza e io te ne saremo molto grate.", enHash = "88477b12", vanilla = true },
        reward = { it = "Sei una persona davvero altruista. Grazie mille per il tuo contributo allo sforzo bellico. Sono le persone come te che faranno la differenza tra il successo e la sconfitta ad Ahn'Qiraj. Spero solo che tutto questo basti.\n\nGrazie ancora, $N.", enHash = "f8adf4c1", vanilla = true },
    },
    [8522] = {
        title = { it = "L'Alleanza ha bisogno di Runecloth Bandage!", enHash = "4ce7129b", vanilla = true },
        text = { it = "Discuti pure sull'opportunità della guerra, se vuoi, $C, ma ormai è stata avviata. Guarda la tua famiglia e i tuoi amici, e poi chiediti che cosa puoi fare perché, se saranno coinvolti, abbiano ogni vantaggio per sopravvivere alla conflagrazione.\n\nPer questo raccolgo qui Runecloth Bandage, da qualunque fonte vengano. Vuoi fare una donazione?", enHash = "c0eea230", vanilla = true },
        objectives = { it = "Porta 20 Runecloth Bandage a Keeper Moonshade, nel Military Ward di Ironforge.", enHash = "d4d922fd", vanilla = true },
        progress = { it = "I giorni passano uno dopo l'altro, e noi andiamo avanti. $C, hai quelle Runecloth Bandage?", enHash = "dc714117", vanilla = true },
        reward = { it = "Meriti un encomio per la tua perseveranza in questo compito, $C. Metterò via queste bende, e poi vorrei parlarti di nuovo della possibilità che tu raccolga ancora altre Runecloth Bandage.", enHash = "1a415d20", vanilla = true },
    },
    [8523] = {
        title = { it = "L'Alleanza ha bisogno di altre Runecloth Bandage!", enHash = "e950786a", vanilla = true },
        text = { it = "Eccoci di nuovo qui a discutere di questioni urgenti, $C. Ancora una volta ti ringrazio per i tuoi sforzi passati: non tutti darebbero con tanto altruismo. Ma c'è ancora del lavoro da fare.\n\n$N, raccoglierai ancora una volta Runecloth Bandage e me le riporterai qui?", enHash = "226d6575", vanilla = true },
        objectives = { it = "Porta 20 Runecloth Bandage a Keeper Moonshade, all'aerodromo di Dun Morogh.", enHash = "f46495a4", vanilla = true },
        progress = { it = "Eccoci di nuovo qui a discutere di questioni urgenti, $C. Ancora una volta ti ringrazio per i tuoi sforzi passati: non tutti darebbero con tanto altruismo. Ma c'è ancora del lavoro da fare.\n\n$N, raccoglierai ancora una volta Runecloth Bandage e me le riporterai qui?", enHash = "29a27c49", vanilla = true },
        reward = { it = "È una bella strada quella che percorriamo insieme, $N. Sei $Gun ottimo compagno:un'ottima compagna; di lavoro. Ancora una volta ti ringrazio per i tuoi sforzi a nome di tutta l'Alleanza. Torna presto a parlare con me.", enHash = "fac0acec", vanilla = true },
    },
    [8524] = {
        title = { it = "L'Alleanza ha bisogno di Rainbow Fin Albacore!", enHash = "ac86f2dc", vanilla = true },
        text = { it = "Ehi, $Gamico:amica;! Se ti chiedessi: \"Non pensi che i soldati debbano avere da mangiare come tutti gli altri?\", ovviamente risponderesti: \"Sì\". Sono d'accordo con te al 110%! Sono contento che la pensiamo allo stesso modo. Tutto quello che devi fare è andare là fuori, pescare un bel mucchio di Raw Rainbow Fin Albacore, cucinarlo tutto e riportarmelo proprio qui. Mmm, mmm, lo sento già in bocca.", enHash = "2fbf8920", vanilla = true },
        objectives = { it = "Porta 20 Rainbow Fin Albacore a Slicky Gastronome, nel Military Ward di Ironforge.", enHash = "3f7df50e", vanilla = true },
        progress = { it = "Scommetto che sei $Gtornato:tornata; con tutto quel Rainbow Fin Albacore di cui parlavamo prima, vero, $C?", enHash = "10bf8401", vanilla = true },
        reward = { it = "Due per l'Alleanza, uno per me, due per l'Alleanza, uno per me. Ehi, $Gpescivendolo:pescivendola;, ottimo lavoro. Vedo che farai onore al club. Mi sa però che ci serve altro albacore. Perché non vai là fuori a rimediarne ancora un po'? Sento già lo stomaco che brontola.", enHash = "534c8de7", vanilla = true },
    },
    [8525] = {
        title = { it = "L'Alleanza ha bisogno di altro Rainbow Fin Albacore!", enHash = "d42e20eb", vanilla = true },
        text = { it = "Cosa! Ancora tu? Be', e io sono lo zio di una scimmia... anzi no, sono uno gnomo. Slicky Gastronome, per la precisione! Quindi sei $Gtornato:tornata; ad aiutare, eh? Be', non posso darti torto. Non adori anche tu il profumo di tutto quel cibo? <sbava>\n\nBasta perdere tempo! Va' là fuori e riportami altro Rainbow Fin Albacore!", enHash = "0fa8d0bf", vanilla = true },
        objectives = { it = "Porta 20 Rainbow Fin Albacore a Slicky Gastronome, all'aerodromo di Dun Morogh.", enHash = "9c1f1835", vanilla = true },
        progress = { it = "Cosa! Ancora tu? Be', e io sono lo zio di una scimmia... anzi no, sono uno gnomo. Slicky Gastronome, per la precisione! Quindi sei $Gtornato:tornata; ad aiutare, eh? Be', non posso darti torto. Non adori anche tu il profumo di tutto quel cibo? <sbava>\n\nBasta perdere tempo! Va' là fuori e riportami altro Rainbow Fin Albacore!", enHash = "3018dc05", vanilla = true },
        reward = { it = "Lo sapevo che ce l'avevi dentro, $Gragazzo:ragazza;. Hai l'aria di $Guno che sa cosa gli piace:una che sa cosa le piace;. In particolare, che ti piace fare contento me e chi comanda. E ci sei $Griuscito:riuscita;, te lo garantisco.\n\nAhah, ok, metto via questi pesci come si deve, e poi io e te facciamo due chiacchiere perché tu mi raccolga altri venti albacore.", enHash = { "08535b9d", "23c42104" }, vanilla = true },
    },
    [8526] = {
        title = { it = "L'Alleanza ha bisogno di Roast Raptor!", enHash = "ef4982f3", vanilla = true },
        text = { it = "Oh, come va, $C? Vedo che ti interessa magari raccogliere cibo per la guerra di Ahn'Qiraj in arrivo? Chissà perché mio padre ha pensato che sarebbe stata una bella esperienza per me offrirmi di aiutare qui. Grosso errore. A me la carne non piace nemmeno.\n\nComunque, se ti va, potresti riportarmi un sacco di Roast Raptor. A quanto pare è quello che vorranno tutti i soldati.", enHash = "db30673f", vanilla = true },
        objectives = { it = "Porta 20 Roast Raptor a Sarah Sadwhistle, nel Military Ward di Ironforge.", enHash = "011e8462", vanilla = true },
        progress = { it = "Allora, ce l'hai tutto quel Roast Raptor?", enHash = "e54ea1f1", vanilla = true },
        reward = { it = "Uh, fantastico. Grazie di avermi portato tutta questa carne di animale bruciata, $C. La metto sul mucchio laggiù. Qualcuno se ne occuperà di sicuro. Immagino che, se hai un po' di tempo libero, vorrai portarmene altra?", enHash = "3d56ce56", vanilla = true },
    },
    [8527] = {
        title = { it = "L'Alleanza ha bisogno di altro Roast Raptor!", enHash = "58eb3002", vanilla = true },
        text = { it = "Ciao di nuovo, $C. Vedo che tutto questo ti entusiasma parecchio. Quindi immagino che tu voglia portarmi altri venti Roast Raptor. Fantastico. Be', fallo pure. Credo che ci vedremo quando torni.", enHash = "07ead0f5", vanilla = true },
        objectives = { it = "Porta 20 Roast Raptor a Sarah Sadwhistle, all'aerodromo di Dun Morogh.", enHash = "25747189", vanilla = true },
        progress = { it = "Ciao di nuovo, $C. Vedo che tutto questo ti entusiasma parecchio. Quindi immagino che tu voglia portarmi altri venti Roast Raptor? Fantastico. Be', fallo pure. Credo che ci vedremo quando torni.", enHash = "f50a70ce", vanilla = true },
        reward = { it = "Wow, hai proprio una marcia in più. Mi stanchi solo a guardarti. Comunque, grazie da parte dell'Alleanza e via dicendo. Farò in modo che tutta quella carne morta venga impacchettata. Immagino che potresti ripassare più tardi per vedere se ce ne serve ancora, anche se, se vuoi sapere come la penso, comincia a far puzzare tutto il posto.", enHash = "13154eca", vanilla = true },
    },
    [8528] = {
        title = { it = "L'Alleanza ha bisogno di Spotted Yellowtail!", enHash = "2333e971", vanilla = true },
        text = { it = "Raccogliere pesce cotto può non sembrare eroico, ma non sottovalutare il valore della preparazione, giovane $C. I soldati devono mangiare come tutti gli altri, e noi siamo qui a fare la nostra parte perché abbiano ciò che serve quando comincerà la guerra ad Ahn'Qiraj.\n\nPer questo sto facendo scorta di Spotted Yellowtail, una fonte di nutrimento versatile che si conserva bene e si può usare in molti piatti diversi. E non ha nemmeno l'odore di certi altri pesci di mare. Sei $Gdisposto:disposta; ad aiutarmi in questa impresa?", enHash = "02a879b0", vanilla = true },
        objectives = { it = "Porta 20 Spotted Yellowtail a Huntress Swiftriver, nel Military Ward di Ironforge.", enHash = "a7cb0756", vanilla = true },
        progress = { it = "Sono sicura che torni così presto con lo Spotted Yellowtail di cui abbiamo parlato.", enHash = "a32bee59", vanilla = true },
        reward = { it = "Grazie per questo dono, $C, e per giunta così tempestivo. Ai nostri soldati di certo non mancherà da mangiare. Lasciami riporre come si deve questi pesci, e poi, se sei $Gdisposto:disposta;, possiamo parlare di una seconda pescata.", enHash = "751193a1", vanilla = true },
    },
    [8529] = {
        title = { it = "L'Alleanza ha bisogno di altro Spotted Yellowtail!", enHash = "bf9d4f40", vanilla = true },
        text = { it = "Se sei ancora $Gdisposto:disposta;, vorrei rimandarti là fuori a portare un'altra pescata di Spotted Yellowtail, $N. Immagino che, con l'esperienza che ti sei $Gfatto:fatta; la prima volta, stavolta la pesca sarà molto più rapida e facile. Ci stai?", enHash = "209a5ade", vanilla = true },
        objectives = { it = "Porta 20 Spotted Yellowtail a Huntress Swiftriver, all'aerodromo di Dun Morogh.", enHash = "6a208e7d", vanilla = true },
        progress = { it = "Se sei ancora $Gdisposto:disposta;, vorrei rimandarti là fuori a portare un'altra pescata di Spotted Yellowtail, $N. Immagino che, con l'esperienza che ti sei $Gfatto:fatta; la prima volta, stavolta la pesca sarà molto più rapida e facile. Ci stai?", enHash = "209a5ade", vanilla = true },
        reward = { it = "Sei un vero membro dell'Alleanza, $N. I tuoi sforzi non passeranno inosservati, né saranno dati per scontati. E grazie anche per aver cucinato il pesce. Farò in modo che venga riposto come si deve, e poi dovrò aggiornare il conto. Ogni pesce ci avvicina un po' di più alla nostra meta.", enHash = "2ee5b143", vanilla = true },
    },
    [8530] = {
        title = { it = "L'Alleanza ha bisogno di Singed Corestone!", enHash = "38a2cd3f", vanilla = true },
        text = { it = "$C, ho bisogno del tuo aiuto. Nel Molten Core ci sono delle pietre, le Singed Corestone per la precisione, che dobbiamo raccogliere per lo sforzo bellico di Ahn'Qiraj. Mi dicono che i nostri fabbri e ingegneri sapranno farne buon uso, ed è qui che entri in gioco tu. Ho bisogno che tu vada nel Molten Core e raccolga quante più di queste pietre puoi. Naturalmente vorrai portarti dietro trentanove dei tuoi amici più cari.", enHash = "fb6a2660", vanilla = true },
        objectives = { it = "Porta 50 Singed Corestone a Commander Stronghammer, all'aerodromo di Dun Morogh.", enHash = "4c34d752", vanilla = true },
    },
    [8532] = {
        title = { it = "L'Orda ha bisogno di Copper Bar!", enHash = "d67587a0", vanilla = true },
        text = { it = "Sono davvero contento che tu abbia deciso di dare una mano. Non tutti lo farebbero, quindi devo essere sicuro che tu abbia capito bene cosa mi serve. Copper Bar, non Copper Ore. Non abbiamo né il tempo né la gente per fondere tutto noi, quindi se fossi così gentile da occupartene tu, i tuoi sforzi verranno debitamente annotati. Pensi di farcela, $C?", enHash = "838531ec", vanilla = true },
        objectives = { it = "Porta 20 Copper Bar a Miner Cromwell, nella Valley of Spirits di Orgrimmar.", enHash = "6be12927", vanilla = true },
        progress = { it = "Spero che quelle che hai con te siano le venti Copper Bar, $C.", enHash = "d6ac4efc", vanilla = true },
        reward = { it = "Queste barre andranno bene, e grazie per non averle lucidate. Non ha senso farle belle, se poi verranno maltrattate per fabbricare il materiale bellico che serve per la guerra. Le metterò io sulle pile e farò in modo che vengano usate come si deve. Parlami di nuovo se ti interessa portarne altre venti.", enHash = "a98a682f", vanilla = true },
    },
    [8533] = {
        title = { it = "L'Orda ha bisogno di altre Copper Bar!", enHash = "4a28f23f", vanilla = true },
        text = { it = "Già di ritorno? Diventerai $Gun vero minatore:una vera minatrice; in un attimo, $C. Allora, sai già come funziona: ho bisogno che tu vada là fuori, estragga un bel mucchio di Copper Ore, lo fonda in barre e me le riporti qui. So che sei in grado di farlo; la domanda è: ne hai voglia?", enHash = "9cff47bf", vanilla = true },
        objectives = { it = "Porta 20 Copper Bar a Miner Cromwell, a Durotar.", enHash = "0a39fcc6", vanilla = true },
        progress = { it = "Già di ritorno? Diventerai $Gun vero minatore:una vera minatrice; in un attimo, $C. Allora, sai già come funziona: ho bisogno che tu vada là fuori, estragga un bel mucchio di Copper Ore, lo fonda in barre e me le riporti qui. So che sei in grado di farlo; la domanda è: ne hai voglia?", enHash = "852a3f79", vanilla = true },
        reward = { it = "Mi hai dimostrato di nuovo il tuo valore, $C. Farò in modo che questo rame venga usato a suo tempo. Per ora, però, devo mettere queste Copper Bar sul bancale e contarle. Se te la senti ancora, probabilmente mi farebbe comodo il tuo aiuto per raccogliere altre Copper Bar.", enHash = "a4d6cc88", vanilla = true },
    },
    [8542] = {
        title = { it = "L'Orda ha bisogno di Tin Bar!", enHash = "4f7b74d4", vanilla = true },
        text = { it = "Lok'tar, $R, sono sicuro che sai già che andremo in guerra ad Ahn'Qiraj contro gli insetti. Ma prima il Capoguerra ha deciso che faremo una cosa chiamata \"prepararsi\". Anche se preferirei affilare armi e martellare armature, sono fiero di essere stato scelto per occuparmi della raccolta di Tin Bar qui. Ma non posso farlo senza il tuo aiuto.\n\nQuindi ho bisogno che tu vada a fare delle Tin Bar e me le riporti qui. Credo che me ne serviranno più di quante ne so contare.", enHash = "6574235b", vanilla = true },
        objectives = { it = "Porta 20 Tin Bar a Grunt Maug, nella Valley of Spirits di Orgrimmar.", enHash = "90a5b805", vanilla = true },
        progress = { it = "Quante Tin Bar hai lì, $C? Dopo la guerra credo che mi servirà qualcuno che mi insegni a contare.", enHash = "cb831a34", vanilla = true },
        reward = { it = "Be', mi pare che questo sia il numero giusto di Tin Bar. Non provare a imbrogliarmi, $C! Contare mi fa male al cranio. Ora io vado a mettere queste barre sulla pila e tu vai là fuori a riportarmene altre uguali.", enHash = "0cc2f5e1", vanilla = true },
    },
    [8543] = {
        title = { it = "L'Orda ha bisogno di altre Tin Bar!", enHash = "86562695", vanilla = true },
        text = { it = "Molto bene, vedo che prendi sul serio la guerra. Però sono un po' nervoso nell'attesa che cominci, il che vuol dire che mi arrabbierò se non inizi a portare la roba più in fretta. Magari potrei esercitarmi su di te, invece.\n\nHar! Forse no, perché poi chi mi riporterebbe le Tin Bar?", enHash = "5c3403c4", vanilla = true },
        objectives = { it = "Porta 20 Tin Bar a Grunt Maug, a Durotar.", enHash = "2f8a10a8", vanilla = true },
        progress = { it = "Molto bene, vedo che prendi sul serio la guerra. Però sono un po' nervoso nell'attesa che cominci, e sono sicuro che lo sei anche tu, $C. Sarà gloriosa, quando comincerà. L'Orda che corre sulle sabbie del deserto di Silithus, armi in pugno, e si lancia a capofitto contro le masse di insetti. Quel giorno ci sarà grande onore per tutti!\n\nHar! Ma prima ci servono altre Tin Bar. Buffo come una cosa così piccola possa fare una differenza così grande, non trovi?", enHash = "91660549", vanilla = true },
        reward = { it = "Throm'ka, $N. Onori me e l'Orda con le tue Tin Bar. Le metterò sulla pila, e poi verranno a farci delle cose. E quando sarà tutto fatto andremo in guerra e mostreremo a quella misera Alleanza come si combattono gli insetti.\n\nOra riportami altre Tin Bar!", enHash = "a5043430", vanilla = true },
    },
    [8545] = {
        title = { it = "L'Orda ha bisogno di Mithril Bar!", enHash = "f0c64040", vanilla = true },
        text = { it = "$C, la guerra sta arrivando e l'unica cosa che possiamo fare è prepararci. È lì che tu e io possiamo aiutarci a vicenda, $Gamico:amica;. Vedi, mi hanno messo a capo della raccolta di tutte le Mithril Bar che ci servono per costruire tutte le cose di cui avremo bisogno. E me ne servono ancora!\n\nQuindi spero che tu possa andare là fuori a estrarci un po' di mithril e poi fonderlo in barre. Ti sembra una cosa che puoi fare per noi?", enHash = "a38af2db", vanilla = true },
        objectives = { it = "Porta 20 Mithril Bar a Senior Sergeant T'kelah, nella Valley of Spirits di Orgrimmar.", enHash = "f5313c70", vanilla = true },
        progress = { it = "Sarebbe proprio bello avere tutte le Mithril Bar che ci servono per lo sforzo bellico di Ahn'Qiraj. È per questo che sei $Gtornato:tornata;, $Gamico:amica;? Hai le mie barre?", enHash = "70937c3a", vanilla = true },
        reward = { it = "Questo è un buon inizio per te e per me, $C. Sono altre venti Mithril Bar che posso mettere sulle pile e spuntare dalla lista. Verrà tutto usato bene per fare il materiale bellico.\n\nAssicurati di ripassare da me, perché mi sa proprio che ci serviranno ancora più Mithril Bar.", enHash = "2911bd9d", vanilla = true },
    },
    [8546] = {
        title = { it = "L'Orda ha bisogno di altre Mithril Bar!", enHash = "f3802981", vanilla = true },
        progress = { it = "Già, sono contenta che tu sia qui, $Gamico:amica;. Mi hai aiutato prima, e ora ho di nuovo bisogno del tuo aiuto. Stiamo ancora cercando di raccogliere altre Mithril Bar per lo sforzo bellico; ci faremo un sacco di armature, armi e altre cose per andare a schiacciare quegli insetti ad Ahn'Qiraj.\n\nQuindi, se sei $Gun vero amico:una vera amica;, riportami altre pile di Mithril Bar. Prendo tutte quelle che hai finché non raggiungiamo la quota. Ne hai qualcuna per me adesso?", enHash = "cd2ca2a9", vanilla = true },
        reward = { it = "Bel lavoro, $N! Altre venti barre ci portano un po' più vicino all'obiettivo, e ci danno altro materiale bellico. Mi occupo io di metterle via. E se ti procuri un'altra pila di Mithril Bar, $Gamico:amica;, assicurati di portarla qui da me.", enHash = "c2295f1b", vanilla = true },
    },
    [8549] = {
        title = { it = "L'Orda ha bisogno di Peacebloom!", enHash = "824079a6", vanilla = true },
        text = { it = "Si dice che ogni generazione debba affrontare una prova decisiva. Temo che la guerra di Ahn'Qiraj sarà il crogiolo in cui verrà messa alla prova la nostra tempra. Così ci prepariamo, e nel farlo scopriamo di che pasta siamo fatti.\n\nMi sono offerta volontaria per aiutare l'Orda raccogliendo più Peacebloom possibile, perché se ne possano fare pozioni per la guerra. Spero che tu sia qui per darmi il tuo aiuto. Se è così, ho bisogno che tu mi riporti una buona quantità di quest'erba. Mi aiuterai, $C?", enHash = "cd9db6dd", vanilla = true },
        objectives = { it = "Porta 20 Peacebloom a Herbalist Proudfeather, nella Valley of Spirits di Orgrimmar.", enHash = "432c00b8", vanilla = true },
        progress = { it = "Già di ritorno con la Peacebloom, $C?", enHash = "104cdec8", vanilla = true },
        reward = { it = "E così i nostri sforzi ci spingono un po' più vicino alla guerra. Grazie per il duro lavoro che hai fatto per raccogliere questa Peacebloom, $C. Ti assicuro che verrà usata bene, e che il tuo contributo è stato annotato, $N. Se te la senti, torna da me con altri di questi fiori. Fino ad allora, che la Madre Terra ti guidi.", enHash = "c20983d6", vanilla = true },
    },
    [8550] = {
        title = { it = "L'Orda ha bisogno di altra Peacebloom!", enHash = "6d35bf27", vanilla = true },
        progress = { it = "Ciao di nuovo, Abyssmal. Sono contenta che tu voglia parlarmi ancora del nostro bisogno senza fine di Peacebloom. Lo sforzo bellico continua, e con esso la nostra produzione di pozioni ed elisir per le battaglie che verranno. Ci aiuterai di nuovo, $C? Mi serve la stessa quantità di Peacebloom di prima, quindi se puoi raccoglierla e riportarmela qui te ne sarò molto grata. Naturalmente, se ce l'hai già con te, sarò più che felice di prenderla subito.", enHash = "4ab62e74", vanilla = true },
        reward = { it = "Grazie per il tuo impegno costante, $N. Con la tua generosità disinteressata porti grande onore a te e ai tuoi antenati, e tutti lo sapranno! Metterò via queste erbe perché restino fresche finché non serviranno. Ancora una volta mostri il vero spirito dell'Orda: la lotta per superare le difficoltà e la promessa che possiamo farlo insieme.", enHash = "daf3e6a0", vanilla = true },
    },
    [8551] = {
        title = { it = "Il forziere del capitano", enHash = "61960082", vanilla = true },
        text = { it = "Un tempo navigavo da qui fino a Ratchet, in Kalimdor. Ero un capitano di successo, con una reputazione impeccabile.\n\nFinché...\n\nQuei maledetti giganti marini mi hanno rovinato! Mi hanno distrutto la nave, ucciso l'equipaggio e mi hanno messo su una scialuppa diretta a Booty Bay. E uno dei giganti, Gorlash, mi ha rubato il mio forziere del capitano. Ha detto che lo voleva come tabacchiera. Che faccia tosta!\n\nHo sentito che Gorlash si aggira lungo la costa a est di qui. Trovalo e riportami il mio forziere! Fallo, e ti sarai $Gguadagnato:guadagnata; la gratitudine di un capitano.", enHash = "f9b80e7d", vanilla = true },
        objectives = { it = "Porta Smotts' Chest a Hecklebury Smotts, a Booty Bay.", enHash = "9e43fb2d", vanilla = true },
        progress = { it = "Ahoy, $N! Hai trovato Gorlash? Quel forziere era il mio preferito, e ha uno scomparto segreto dove tenevo i miei tesori più preziosi!", enHash = "e8131b08", vanilla = true },
        reward = { it = "L'hai trovato! Oh, che giorno felice, questo! Grazie, $N. Riavere il mio forziere spegne un po' del fuoco che ho dentro.\n\nMa la mia vendetta non è completa...", enHash = "1467b06c", vanilla = true },
    },
    [8552] = {
        title = { it = "La Monogrammed Sash", enHash = "7c4cdc80", vanilla = true },
        text = { it = "Questa elegante fascia ha le lettere \"HS\" ricamate lungo l'orlo.", enHash = "7abb05c5", vanilla = true },
        objectives = { it = "Riporta la Monogrammed Sash al suo proprietario.", enHash = "4e940268", vanilla = true },
        progress = { it = "Salve. Hai affari da trattare con me?", enHash = "747957af", vanilla = true },
        reward = { it = "Hai recuperato la mia fascia? Allora... devi aver ucciso Mok'rash, il gigante marino! Evviva!\n\nSono contento che quel lurido farabutto sia morto: Mok'rash era uno dei tre giganti marini che mi hanno distrutto le navi e ucciso l'equipaggio.\n\nTre volte.\n\nSei $Gun:una; $C di valore, $N.", enHash = "59724f09", vanilla = true },
    },
    [8553] = {
        title = { it = "La sciabola del capitano", enHash = "6b16e118", vanilla = true },
        text = { it = "Dopo aver perso la mia prima nave per colpa di quei giganti, ne ho comprata un'altra. L'ho chiamata Smotts' Revenge, l'ho riempita di provviste e di marinai e sono partito alla ricerca di quei farabutti. Li ho trovati, ma... mi hanno battuto. Hanno distrutto la Smotts' Revenge, ucciso il mio secondo equipaggio e mi hanno messo su un'altra scialuppa.\n\nStavolta un altro dei giganti, Negolash, mi ha rubato la sciabola.\n\nAffronta Negolash e riportami la mia sciabola!\n\nParla con Sprogger. Era il mio cuoco sulla Smotts' Revenge, ed è sopravvissuto all'ultimo attacco. Può aiutarti a trovare il gigante.", enHash = "bbc1d5ce", vanilla = true },
        objectives = { it = "Parla con Sprogger.", enHash = "5d081e5b", vanilla = true },
        reward = { it = "Salve, salve, $N. Il capitano mi ha detto che vuoi dare la caccia a Negolash, eh?", enHash = "640d5e53", vanilla = true },
    },
    [8554] = {
        title = { it = "Affrontare Negolash", enHash = "cb05d96f", vanilla = true },
        text = { it = "Negolash è un gigante affamato.\n\nQuando i giganti hanno distrutto la nostra nave, Negolash è andato dritto nella mia cucina. Non aveva fame di marinai come gli altri giganti. Negolash voleva il vino... e le mie Barbecued Buzzard Wing. Sono la mia specialità, e sono dovuto andare fino alle Badlands per la ricetta!\n\nSe vuoi attirare il gigante, procurati del vino e un mucchio di Buzzard Wing. Mettili nella nostra vecchia scialuppa, a sud-est di qui lungo la costa. Quando Negolash sentirà l'odore di tutto quel cibo, verrà di sicuro!", enHash = "ed08343a", vanilla = true },
        objectives = { it = "Porta 10 Barbecued Buzzard Wing e 5 bottiglie di Junglevine Wine a Captain Smotts' Lifeboat.\n\nUccidi Negolash e porta Smotts' Cutlass a Captain Smotts, a Stranglethorn.", enHash = "e49e5a13", vanilla = true },
        progress = { it = "Hai recuperato la mia sciabola, $N?", enHash = "7034fc52", vanilla = true },
        reward = { it = "Hai tolto la mia sciabola a Negolash! Non posso credere alla mia fortuna, $N! Incontrarti ha girato la mia sorte in meglio, puoi starne certo!\n\nGrazie! E se mai avrò una nuova nave e vorrai solcare i mari, sarai mio ospite d'onore.", enHash = "5fdcbebf", vanilla = true },
    },
    [8580] = {
        title = { it = "L'Orda ha bisogno di Firebloom!", enHash = "261b41ba", vanilla = true },
        text = { it = "Ehi, $C. Sì, proprio tu, $Gamico:amica;! L'Orda pensa che le serva un bel mucchio di Firebloom per questo sforzo bellico di Ahn'Qiraj. Magari la mettono in belle cose che fanno bum? Magari la danno all'Alleanza come combustibile per i suoi carri a vapore? Chi lo sa? Non Pele'keiki!\n\nPerò Pele'keiki sa questo... sa che tu lo aiuterai e gli riporterai tanta Firebloom, vero, $Gamico:amica;?", enHash = "74766b0d", vanilla = true },
        objectives = { it = "Porta 20 Firebloom a Batrider Pele'keiki, nella Valley of Spirits di Orgrimmar.", enHash = "dbe687ea", vanilla = true },
        progress = { it = "Non vuoi far arrabbiare Pele'keiki. Rendi felice Pele'keiki portandogli tanta Firebloom, e alla svelta.", enHash = "b38e6e6c", vanilla = true },
        reward = { it = "$C! Pele'keiki è felice, per ora. Pele'keiki prende tutta questa Firebloom e la mette in una cassa, così resta fresca. Pele'keiki si assicura che tutta la Firebloom diventi roba buona per la guerra. E se ne trovi ancora, vieni subito da Pele'keiki. Probabilmente a Pele'keiki ne servirà altra.", enHash = "55e63698", vanilla = true },
    },
    [8581] = {
        title = { it = "L'Orda ha bisogno di altra Firebloom!", enHash = "ca96c819", vanilla = true },
        progress = { it = "Pele'keiki sa che sei qui per aiutare. Porta tanta Firebloom e lo renderai molto felice. Pele'keiki potrebbe fare grosse bombe con la Firebloom. E sganciarle sugli insetti dal suo pipistrello sopra Ahn'Qiraj, quando arriverà la guerra. Ma a Pele'keiki serve altra Firebloom, $C!\n\nPorterai quella Firebloom a Pele'keiki, e alla svelta. Torna con almeno la stessa quantità dell'ultima volta, e Pele'keiki sarà contento.", enHash = "2fa26aa6", vanilla = true },
        reward = { it = "Non è uno scherzo, $C? Porti a Pele'keiki la Firebloom così in fretta? Pele'keiki la conta subito, $Gamico:amica;! Stai rendendo Pele'keiki così felice che dirà a tutti che $N è $Gil miglior raccoglitore:la miglior raccoglitrice; di Firebloom di sempre! Pele'keiki non vede l'ora che cominci la guerra. Adesso sì che illumineremo il cielo sopra Silithus, vero, $Gfratello:sorella;?!", enHash = "23191567", vanilla = true },
    },
    [8582] = {
        title = { it = "L'Orda ha bisogno di Purple Lotus!", enHash = "461c81f0", vanilla = true },
        text = { it = "Il Purple Lotus, $C, è un reagente di moltissime pozioni, elisir e oli, alcuni dei quali ci saranno utili ad Ahn'Qiraj. Dovremo preparare un numero enorme di queste pozioni per lo sforzo bellico. E farò anche degli esperimenti per trovare altri usi per il loto. Ma per fare tutto questo mi servirà una grande quantità di questo fiore.\n\nEd è qui che entri in gioco tu. Va' sul campo e raccogli quanti più Purple Lotus puoi. È una cosa che sei $Gdisposto:disposta; a fare per noi?", enHash = "20c15146", vanilla = true },
        objectives = { it = "Porta 20 Purple Lotus ad Apothecary Jezel, nella Valley of Spirits di Orgrimmar.", enHash = "12a8a39b", vanilla = true },
        progress = { it = "Già di ritorno con il Purple Lotus che ti ho chiesto, $C? È fondamentale che tu lo faccia il più tempestivamente possibile, se non vuoi che tutto ciò che sto tentando qui finisca nel nulla.", enHash = "c8dea028", vanilla = true },
        reward = { it = "Uno sforzo encomiabile, $C. Misurerò questi campioni per stabilirne l'uso più adatto e annoterò il tuo contributo. Poi il Purple Lotus andrà conservato come si deve finché non sarò pronta a usarlo. Quanto a te, se sei ancora disponibile, immagino che mi servirà altro Purple Lotus. Ripassa da me tra un momento.", enHash = "5d77c1b6", vanilla = true },
    },
    [8583] = {
        title = { it = "L'Orda ha bisogno di altro Purple Lotus!", enHash = "48d66b31", vanilla = true },
        progress = { it = "In effetti pare proprio che ci serva ancora altro Purple Lotus, $C. Anche se i miei studi non hanno ancora individuato un nuovo impiego utile per quest'erba, ci sono metodi collaudati ancora da applicare.\n\nHo bisogno che tu vada di nuovo sul campo a raccogliere almeno venti campioni di Purple Lotus. Riportali qui da me.", enHash = "9bf10d17", vanilla = true },
        reward = { it = "Un lavoro eccellente e preciso, $N. La tua diligenza merita un encomio, e così la tua rapidità. Mi assicurerò di persona che nessuno di questi Purple Lotus vada sprecato.\n\nGrazie ancora, e se ti capita di trovare altro Purple Lotus, non esitare a portarmelo con la massima urgenza.", enHash = "b6df44b5", vanilla = true },
    },
    [8588] = {
        title = { it = "L'Orda ha bisogno di Heavy Leather!", enHash = "3ed1d6d7", vanilla = true },
        text = { it = "Visto che ci stiamo preparando alla guerra, forse è meglio procurarci prima tutta la roba che ci serve, non credi, $Gamico:amica;? Uno dei materiali base per il materiale bellico che produciamo è l'Heavy Leather. Lo useremo praticamente per tutto, dai rinforzi alle armature, fino ai buoni vecchi teloni.\n\nMa prima dobbiamo metterci le mani sopra. Questo è compito tuo, $C. Affila il coltello e riportamene un fascio. Poi ne parleremo ancora.", enHash = "13dca599", vanilla = true },
        objectives = { it = "Porta 10 Heavy Leather a Skinner Jamani, nella Valley of Spirits di Orgrimmar.", enHash = "13a88d51", vanilla = true },
        progress = { it = "Non ho tempo per i giochi, se sei qui solo per chiacchierare, $C. Ci sono troppe pile di Heavy Leather da conciare. Torna quando ne avrai almeno dieci per me.", enHash = "360c5a88", vanilla = true },
        reward = { it = "Oh, allora ce l'hai davvero l'Heavy Leather che mi serviva. La tua lama è proprio affilata, $C: queste sono belle pelli! Ora che siamo partiti con il piede giusto, farò in modo che il tuo contributo venga usato bene. E se ti capita di trovare altro Heavy Leather, portalo da me.", enHash = "5b836a44", vanilla = true },
    },
    [8589] = {
        title = { it = "L'Orda ha bisogno di altro Heavy Leather!", enHash = "935515b6", vanilla = true },
        progress = { it = "È vero, $C, mi serve ancora altro Heavy Leather. Le richieste dei generali e dei loro furieri sembrano non finire mai. E non è niente in confronto a quello che chiedono i maestri degli zeppelin!\n\nDevo raccogliere la mia quota al più presto. $N, portami altre pile di Heavy Leather il prima possibile!", enHash = "36c5e07c", vanilla = true },
        reward = { it = "Sei $Gil migliore:la migliore;, $Gamico:amica;! Grazie mille per l'Heavy Leather. Ogni piccola parte ci avvicina un po' di più. Lo metto subito in pila, così gli altri conciatori possono metterci mano.\n\nGrazie ancora, $N, e se trovi altre pile di Heavy Leather, sai dove trovarmi.", enHash = "50f53282", vanilla = true },
    },
    [8590] = {
        title = { it = "L'Orda ha bisogno di Thick Leather!", enHash = "755014c1", vanilla = true },
        text = { it = "Sono contenta che tu abbia deciso di parlarmi di questa faccenda, $C. Pare che i preparativi dell'Orda per la guerra di Ahn'Qiraj siano in pieno svolgimento. Ma tu e io dobbiamo ancora fare la nostra parte.\n\nMi hanno chiesto di raccogliere una gran quantità di pelli di Thick Leather da usare per ogni genere di materiale bellico, e ho bisogno che tu mi aiuti andando là fuori a raccoglierle. Se deciderai di aiutarmi, ne avrai onore e la gratitudine dell'Orda. Lo farai?", enHash = "60d240df", vanilla = true },
        objectives = { it = "Porta 10 Thick Leather a Sergeant Umala, nella Valley of Spirits di Orgrimmar.", enHash = "e0e9fabc", vanilla = true },
        progress = { it = "$C, sei già $Gtornato:tornata; con i dieci Thick Leather di cui avevamo parlato?", enHash = "2ea7d3d3", vanilla = true },
        reward = { it = "Bel lavoro, $C. Sono sicura che queste pelli di Thick Leather serviranno a rinforzare gli zeppelin e a fare ogni genere di armature e armi. Ti ringrazio, a nome mio e dell'Orda. Torna ancora se nei tuoi viaggi trovi altro Thick Leather, e che la fortuna sia con te.", enHash = "3dc76511", vanilla = true },
    },
    [8591] = {
        title = { it = "L'Orda ha bisogno di altro Thick Leather!", enHash = "c9d353a0", vanilla = true },
        progress = { it = "$C, come vedi devo ancora raccogliere altro Thick Leather. Ancora una volta ti chiedo aiuto in questo compito, e ti prometto che, se lo porterai a termine, i tuoi sforzi saranno riconosciuti.\n\nIl tempo stringe! Torna da me con il Thick Leather, così potremo finire i preparativi e andare in guerra, $Geroe:eroina;!", enHash = { "898ab1b7", "e32142eb" }, vanilla = true },
        reward = { it = "Ce l'hai fatta, $N, lo sapevo! Ancora una volta, grazie a nome di tutta l'Orda. I tuoi sforzi sono stati annotati e sono molto apprezzati. E se ti ritrovi con altro Thick Leather da donare, portalo qui da me.\n\nLok'tar Ogar, $C!", enHash = "ea31ad74", vanilla = true },
    },
    [8600] = {
        title = { it = "L'Orda ha bisogno di Rugged Leather!", enHash = "27d3bf70", vanilla = true },
        text = { it = "Trovo che il modo in cui il coltello si adatta al palmo conti più del suo filo. Anche la lama più smussata può tagliare, se la pressione viene applicata nel modo giusto, non credi, $C? Ma tu e io non abbiamo di questi problemi, visto che teniamo le lame più affilate, vero?\n\nBe', non importa, ho un compito per te. Al servizio dell'Orda, e per fare la tua parte nello sforzo bellico di Ahn'Qiraj, voglio che tu torni da me con un certo numero di pelli di Rugged Leather. È una cosa che farai, no?", enHash = "c8f5d273", vanilla = true },
        objectives = { it = "Porta 10 Rugged Leather a Doctor Serratus, nella Valley of Spirits di Orgrimmar.", enHash = "e79448ba", vanilla = true },
        progress = { it = "Non è possibile che ti ci voglia tanto per tagliarmi dieci Rugged Leather! Forse dovresti affilare il coltello da scuoiatura? O forse mi sbaglio e ce le hai lì nello zaino?", enHash = "187e2d97", vanilla = true },
        reward = { it = "Molto bene, pare che tu abbia fatto un lavoro abbastanza decente, anche se alcune di quelle pelli sono un po' sfilacciate ai bordi. Non importa, il compito è fatto, e ti sei $Gguadagnato:guadagnata; la ricompensa. Se ti capita di trovare un'altra pila di Rugged Leather, portamela senza indugio.", enHash = "d1a86cd1", vanilla = true },
    },
    [8601] = {
        title = { it = "L'Orda ha bisogno di altro Rugged Leather!", enHash = "63b85c71", vanilla = true },
        progress = { it = "I preparativi per l'imminente guerra ad Ahn'Qiraj procedono, $C. Tuttavia, per essere sicuri di non restare indietro, o almeno per non essere io quello che ci fa restare indietro, voglio che tu mi riporti un'altra pila di Rugged Leather. Apprezzerò molto la tua sollecitudine in questa faccenda, $N.", enHash = "550af287", vanilla = true },
        reward = { it = "Esercizio, esercizio, esercizio. Un coltello ben affilato e l'abilità di usarlo ti porteranno lontano in questo mondo, $N. Mi sembra che i bordi di queste pelli siano migliori di quelle dell'ultima volta. Ti sei $Gcomprato:comprata; un coltello nuovo?\n\nIn ogni caso, ti ringraziamo per i tuoi sforzi. La tua donazione è stata annotata, e ti assicuro che verrà usata bene. Se ti ritrovi con altro Rugged Leather, torna pure a parlarmi, perché probabilmente mi servirà.", enHash = "19067ab3", vanilla = true },
    },
    [8604] = {
        title = { it = "L'Orda ha bisogno di Wool Bandage!", enHash = "1c50c113", vanilla = true },
        text = { it = "Salve, $C. In vista della guerra ad Ahn'Qiraj, sono qui a coordinare gli sforzi dell'Orda per raccogliere Wool Bandage. Purtroppo, sul campo, i nostri soldati non possono contare sulla presenza di un guaritore che li tenga in vita. Credimi, lo so per esperienza. Per questo stiamo preparando per loro tutte queste cassette di pronto soccorso.\n\nSe hai tempo, mi servono molte Wool Bandage. Riportamele qui e farò in modo che tu venga $Gricompensato:ricompensata; come si deve.", enHash = "ef28bef6", vanilla = true },
        objectives = { it = "Porta 20 Wool Bandage a Healer Longrunner, nella Valley of Spirits di Orgrimmar.", enHash = "45ebc0a9", vanilla = true },
        progress = { it = "Ah, $C, sei già $Gtornato:tornata; con le Wool Bandage?", enHash = "0e8078b0", vanilla = true },
        reward = { it = "Ti ringrazio, a nome mio e dell'Orda, $C. Se trovi altre Wool Bandage e vuoi contribuire ancora allo sforzo bellico, portamele qui. Fino ad allora, che i tuoi antenati veglino su di te!", enHash = "59f6f028", vanilla = true },
    },
    [8605] = {
        title = { it = "L'Orda ha bisogno di altre Wool Bandage!", enHash = "70d3fff2", vanilla = true },
        progress = { it = "Che piacere rivederti, $C. Stiamo ancora lavorando ai preparativi per lo sforzo bellico, e mi fa ancora comodo tutto l'aiuto che puoi darmi per raccogliere bende di lana. Qualsiasi aiuto sarà molto apprezzato. Spero solo che i nostri sforzi bastino. Ho perso troppe anime nobili sui campi di battaglia del passato per non fare tutto quello che posso perché non succeda di nuovo.", enHash = "b33bb3d1", vanilla = true },
        reward = { it = "Sei $Gun:una; $C d'onore, $N! Farò in modo che queste bende arrivino nelle mani giuste. Ti ringrazio, a nome mio e dell'Orda.\n\nVa' in pace, e torna da me se ti ritrovi con bende di lana in più. Qui ci serve tutto l'aiuto possibile.", enHash = "f0aa031e", vanilla = true },
    },
    [8607] = {
        title = { it = "L'Orda ha bisogno di Mageweave Bandage!", enHash = "f9f64e62", vanilla = true },
        text = { it = "Confido che tu mi stia parlando perché intendi aiutarmi con la raccolta che mi è stata affidata? Bene! Con qualunque mezzo, e intendo davvero qualunque, desidero che tu raccolga un buon numero di Mageweave Bandage. Fresche sarebbe meglio, ma non è indispensabile. Riportamele qui, $C, e mi assicurerò di persona che tu venga $Gricompensato:ricompensata; come si deve.", enHash = "670aab87", vanilla = true },
        objectives = { it = "Porta 20 Mageweave Bandage a Lady Callow, nella Valley of Spirits di Orgrimmar.", enHash = "bfc389f1", vanilla = true },
        progress = { it = "Non fallire e non farmi fare brutta figura, $C! Torna qui il prima possibile con le Mageweave Bandage di cui abbiamo parlato.", enHash = "34b1e5a3", vanilla = true },
        reward = { it = "Sorprendente, eppure accettabile. Forse ho sottovalutato le tue \"capacità\", $C. Forse. Hai portato a termine un compito molto semplice, e per questo verrai $Gricompensato:ricompensata; in modo sproporzionato. Ma non montarti la testa. Se vuoi davvero dimostrare il tuo valore, dovresti andare là fuori e portarmi un altro fascio di Mageweave Bandage.", enHash = "99b8f544", vanilla = true },
    },
    [8608] = {
        title = { it = "L'Orda ha bisogno di altre Mageweave Bandage!", enHash = "485282e3", vanilla = true },
        progress = { it = "Sei $Gtornato:tornata;? Interessante. Come vedi, sto ancora raccogliendo per lo \"sforzo bellico\" di Ahn'Qiraj. Il che significa che ho bisogno che tu vada di nuovo a raccogliere una pila di Mageweave Bandage per me. Attendo il tuo ritorno, $C.", enHash = "d341185c", vanilla = true },
        reward = { it = "Stupefacente, $C, ce l'hai fatta davvero di nuovo! Be', dicono che ho buon gusto nello scegliere chi mettere al mio servizio. Molto bene, il tuo contributo è stato annotato e riceverai i vantaggi sociali che i tuoi sforzi ti hanno procurato. Ti suggerisco però di tornare là fuori a raccogliere un altro fascio ancora di Mageweave Bandage, se vuoi davvero dimostrare quanto vali.", enHash = "5b19e6be", vanilla = true },
    },
    [8609] = {
        title = { it = "L'Orda ha bisogno di Runecloth Bandage!", enHash = "70b65272", vanilla = true },
        text = { it = "Pare inevitabile che l'Orda e l'Alleanza siano in rotta verso la guerra ad Ahn'Qiraj. Sorprendentemente, non è una guerra tra loro, ma contro i silitidi e qualunque forza li controlli. E, sorprendentemente anche questo, entrambi gli schieramenti stanno facendo la loro parte per raccogliere le risorse necessarie a combattere una guerra vittoriosa.\n\nRaccolgo Runecloth Bandage da distribuire ai soldati, ma senza aiuto non ci riuscirò, e spero che sia il tuo. Puoi aiutarmi in questo, $C?", enHash = "6966c580", vanilla = true },
        objectives = { it = "Porta 20 Runecloth Bandage a Stoneguard Clayhoof, nella Valley of Spirits di Orgrimmar.", enHash = "1ceabf9e", vanilla = true },
        progress = { it = "La guerra arriverà presto, credo, $C. Ti ringrazio per il tempo e l'impegno che dedichi ad aiutarci nelle raccolte. Sei $Gtornato:tornata; perché hai trovato le Runecloth Bandage di cui abbiamo parlato?", enHash = "94df5d84", vanilla = true },
        reward = { it = "Fai onore all'Orda, $C. Grazie per i tuoi sforzi: sono apprezzati! Dovrò mettere via queste bende fresche e rifare il conto per vedere quanto siamo vicini al nostro obiettivo. Se vuoi, puoi raccogliere altre Runecloth Bandage e riportarmele qui.", enHash = "e9d4b3cd", vanilla = true },
    },
    [8610] = {
        title = { it = "L'Orda ha bisogno di altre Runecloth Bandage!", enHash = "bf1286f3", vanilla = true },
        progress = { it = "Si avvicina sempre di più il momento in cui ci getteremo a capofitto nella conflagrazione di Ahn'Qiraj, $Gsacerdote:sacerdotessa;. Ma prima dobbiamo raccogliere le forze e prepararci, per poter sopravvivere all'assalto degli insetti e dei loro padroni.\n\nSe sei di nuovo qui, di certo vuoi fare un'altra donazione di Runecloth Bandage allo sforzo bellico? Ti prego, fallo appena puoi e torna ancora da me.", enHash = "1e685f12", vanilla = true },
        reward = { it = "Il tuo è un gesto di generosità davvero disinteressato, $N. Un gesto che probabilmente salverà la vita a molti combattenti ad Ahn'Qiraj. Grazie, e sappi che l'Orda ti è grata per la tua donazione. Se prepari, o trovi, altre Runecloth Bandage, ti prego, pensa a portarmele qui.", enHash = "23d6fd29", vanilla = true },
    },
    [8611] = {
        title = { it = "L'Orda ha bisogno di Lean Wolf Steak!", enHash = "e5cba642", vanilla = true },
        text = { it = "Non sto qui solo per prendere un po' di sole, $C. Ci sono dei preparativi di guerra da fare. Se vogliamo schiacciare quegli insetti ad Ahn'Qiraj, dobbiamo essere pronti, e questo vale anche per il cibo!\n\nMi hanno messo qui a raccogliere e salare Lean Wolf Steak per la guerra in arrivo. Ma visto che devo restare qui a occuparmi di tutto questo, ho bisogno che tu vada là fuori, uccida qualche lupo, cucini la carne per farne Lean Wolf Steak e me le riporti qui. Tutto chiaro?", enHash = "63b4cdfe", vanilla = true },
        objectives = { it = "Porta 20 Lean Wolf Steak a Bloodguard Rawtar, nella Valley of Spirits di Orgrimmar.", enHash = "5e9220db", vanilla = true },
        progress = { it = "Già di ritorno con quelle Lean Wolf Steak, $C? Non m'importa se sono troppo cotte o crude, basta che siano saporite e che me le porti in fretta!", enHash = "6b693ced", vanilla = true },
        reward = { it = "Ok, questa pila di carne mi sembra buona. Le salerò, poi le metterò via, e speriamo che restino abbastanza fresche da essere mangiabili quando sarà il momento.\n\nGrazie per il contributo, $C. Pensi di potermene portare un'altra infornata?", enHash = "e26e7a97", vanilla = true },
    },
    [8612] = {
        title = { it = "L'Orda ha bisogno di altre Lean Wolf Steak!", enHash = "bafd0703", vanilla = true },
        progress = { it = "Come vedi, $C, dobbiamo ancora mettere via altro cibo per i soldati. Non so se tu sia mai $Gstato:stata; in guerra, ma una volta superato lo shock iniziale del campo di battaglia, può venire una gran fame. L'ultima volta hai fatto un buon lavoro, quindi mi aspetto che farai altrettanto bene, se non un po' più in fretta, portandomi un'altra pila di quelle Lean Wolf Steak.", enHash = "e2ca3336", vanilla = true },
        reward = { it = "Dall'odore, tu, o qualcuno che conosci, ci sai proprio fare ai fornelli, $N. Queste Lean Wolf Steak mi fanno venire l'acquolina in bocca; immagino che se ne sparisce qualcuna nessuno se ne accorgerà. Comunque, bel lavoro. Farò in modo che qualcuno le metta via come si deve, così non si guasteranno troppo.\n\nSe ne trovi altre, sai dove trovarmi.", enHash = "7ab662a9", vanilla = true },
    },
    [8613] = {
        title = { it = "L'Orda ha bisogno di Spotted Yellowtail!", enHash = "47032948", vanilla = true },
        text = { it = "È una bella giornata per pescare, non credi, $Gamico:amica;? Meno male, perché pare che mi serva un sacco di pesce. L'Orda mi ha chiesto di occuparmi di raccogliere una montagna di Spotted Yellowtail. Dicono che gli serve per la guerra che stanno preparando ad Ahn'Qiraj. Io gli ho detto che faccio del mio meglio. Quindi mi serve un po' d'aiuto. Mi aiuti tu, $C?", enHash = "e63d8c10", vanilla = true },
        objectives = { it = "Porta 20 Spotted Yellowtail a Fisherman Lin'do, nella Valley of Spirits di Orgrimmar.", enHash = "9244ea43", vanilla = true },
        progress = { it = "Già di ritorno con lo Spotted Yellowtail, $C? Ti sei $Gricordato:ricordata; di cucinarlo per bene? Il pesce crudo ai soldati sotto il sole caldo del deserto non lo serviamo di sicuro.", enHash = "0b636cdd", vanilla = true },
        reward = { it = "Oh sì, questa è roba buona. Lo impacchetto per bene, così non va sprecato. Grazie a te per avermi aiutato così. Secondo me sei $Gun pescatore:una pescatrice; di prima classe, con tutto questo Spotted Yellowtail. E se ti capita di pescarne e cucinarne ancora, portalo qui da me: farò sapere a tutti che sei $Gstato:stata; tu!", enHash = "37b2d650", vanilla = true },
    },
    [8614] = {
        title = { it = "L'Orda ha bisogno di altro Spotted Yellowtail!", enHash = "955f5dc9", vanilla = true },
        progress = { it = "Come vedi, ci servono ancora un sacco di pescetti. I combattenti della guerra di Ahn'Qiraj in arrivo avranno bisogno di tanto da mangiare, quindi devo procurarmi tutto lo Spotted Yellowtail possibile. Tu li peschi, li cucini e me li riporti qui, e io ti ringrazio, e con me ti ringrazia l'Orda.", enHash = "bccd7666", vanilla = true },
        reward = { it = "È la pescata migliore finora, $N! Un lavoro buono e onesto. E senza nemmeno una lisca! Grazie per questo Spotted Yellowtail, $Gamico:amica;. Torna presto, se ne cucini ancora!", enHash = "b7cdab74", vanilla = true },
    },
    [8615] = {
        title = { it = "L'Orda ha bisogno di Baked Salmon!", enHash = "818646b8", vanilla = true },
        text = { it = "Lo sforzo bellico di Ahn'Qiraj è un'impresa immensa, $C. Tutti i materiali che si raccolgono qui, che siano metallo per le armi o cibo da mangiare, sono importanti allo stesso modo. Perché, se non mangi da giorni, non avrai la forza di sollevare l'ascia quando conta.\n\nPer questo raccogliamo tutto il cibo che possiamo. Io raccolgo Baked Salmon, un piatto scelto perché è nutriente e perché si conserva bene. Puoi aiutarmi in questo compito, $C?", enHash = "7b435a3c", vanilla = true },
        objectives = { it = "Porta 20 Baked Salmon a Chief Sharpclaw, nella Valley of Spirits di Orgrimmar.", enHash = "7c0e7d49", vanilla = true },
        progress = { it = "Gli Sprite Darter possono essere bestiole pericolose, se provocati. Sta' $Gattento:attenta; quando hai a che fare con loro, $C. E fa' ancora più attenzione agli elfi della notte della zona. Quegli sciocchi fastidiosi tendono a rintanarsi anche loro nelle foreste.\n\nQuando avrai abbastanza ali, fammelo sapere: ti ricompenserò bene, puoi starne certo!", enHash = "9c2d0ab2", vanilla = true },
        reward = { it = "Magnifico, $C! Queste andranno benissimo. Ce n'è abbastanza per fare un mantello per Korrin, e forse anche di più! Grazie.\n\nSpero che il viaggio non sia stato troppo pericoloso? La zona di Feralas non è nota per essere clemente, ma è chiaro che te la sei $Gcavato:cavata; bene.\n\nGrazie ancora, $C.", enHash = "61952e37", vanilla = true },
    },
    [8616] = {
        title = { it = "L'Orda ha bisogno di altro Baked Salmon!", enHash = "84402ff9", vanilla = true },
        progress = { it = "L'ultima partita di Baked Salmon che hai donato allo sforzo bellico aveva un aspetto davvero delizioso, $C. Devo ammettere che sono stato tentato di prenderne un po' per me. Come vedi, non abbiamo ancora raggiunto la nostra quota. Spero che tu sia $Gtornato:tornata; perché hai con te un'altra pila di Baked Salmon.", enHash = "95486af3", vanilla = true },
        reward = { it = "Il tempo e l'energia che doni allo sforzo bellico vanno ben oltre il dovuto, $N. Ti assicuro che le tue fatiche non sono passate inosservate. Ti ringrazio, a nome mio e dell'Orda. Torna ancora da me se ne cucini un'altra partita.", enHash = "7be2407b", vanilla = true },
    },
    [8617] = {
        title = { it = "L'Orda ha bisogno di Singed Corestone!", enHash = "5290b688", vanilla = true },
        text = { it = "È arrivato il momento che tu contribuisca allo sforzo bellico di Ahn'Qiraj, $C. Sono finiti i giorni sereni passati a oziare. Ora è il momento di servire me e l'Orda, e ti assicuro che non sono indulgente quanto il Capoguerra.\n\nRadunerai le tue forze, una gilda se ne hai una, e invaderai il Molten Core. Lì dentro scoprirai che chi lo abita ha delle Singed Corestone. Riportamele in grandi quantità.", enHash = "bd8edf66", vanilla = true },
        objectives = { it = "Porta 50 Singed Corestone a General Zog, a Durotar.", enHash = "833b5abf", vanilla = true },
    },
    [8619] = {
        title = { it = "Morndeep the Elder", enHash = "4356c645", vanilla = true },
        reward = { it = "È bello sapere che la gente di queste terre rende ancora omaggio alle razze antiche. Ti auguro ogni bene, $N, e ti offro questo pegno...", enHash = "61c94e53", vanilla = true },
    },
    [8635] = {
        title = { it = "Splitrock the Elder", enHash = "e300ec3a", vanilla = true },
        reward = { it = "Le battaglie delle ere passate sono semi da cui crescono le leggende. La tua è un'epoca di eroi, giovane. Che la tua leggenda metta radici e prosperi.\n\nTi auguro ogni bene, $N, e ti offro questo pegno...", enHash = "28c81088", vanilla = true },
    },
    [8636] = {
        title = { it = "Rumblerock the Elder", enHash = "90e93371", vanilla = true },
        reward = { it = "Ciò che appartiene alla vita è destinato a morire e a tornare alla terra, ma ciò che appartiene allo spirito vive in eterno. Ti auguro ogni bene, $N, e ti offro questo pegno...", enHash = "ce353720", vanilla = true },
    },
