    },
    [8734] = {
        title = { it = "Tyrande e Remulos", enHash = "ef10bde7", vanilla = true },
        text = { it = "Tyrande sarà avvisata, mortale. Shan'do Stormrage mi ha preparato per questa evenienza.\n\nOra devi andare nel Moonglade a parlare con Remulos. Ti darà altre istruzioni per l'evocazione di Eranikus.\n\nTi auguriamo tutti buona fortuna.", enHash = "cde595ee", vanilla = true },
        objectives = { it = "Raggiungi il Moonglade e parla con Keeper Remulos.", enHash = "e21820ab", vanilla = true },
        reward = { it = "Sarebbe impossibile strappare Eranikus al Sogno, se si rifiutasse. Però le sue intenzioni lo obbligano a entrare nel nostro mondo. Cerca di distruggere la manifestazione vivente di Malfurion. Se ci riuscisse, sarebbe la fine di uno dei più potenti alleati del Sogno. Se Malfurion cadesse, l'Incubo consumerebbe completamente tutto ciò che resterebbe...", enHash = "fa6031c2", vanilla = true },
    },
    [8744] = {
        title = { it = "Un regalo incartato con cura", enHash = "00eae25a", vanilla = true },
        reward = { it = "Sul biglietto di questo regalo c'è scritto:\n\nPer $N,\n\nche la tua Vigilia di Grande Inverno sia allegra e luminosa!", enHash = "f378092e", vanilla = true },
    },
    [8767] = {
        title = { it = "Un regalo scosso delicatamente", enHash = "593e2c58", vanilla = true },
        reward = { it = "Sembra che questo regalo sia stato scosso un paio di volte. Sul biglietto c'è scritto:\n\nPer $Gun:una; $R $C davvero speciale.", enHash = "40cfccf8", vanilla = true },
    },
    [8768] = {
        title = { it = "Un regalo incartato allegramente", enHash = "ce62d21d", vanilla = true },
        reward = { it = "Questo regalo dalla carta festosa ha sopra il tuo nome.\n\nAspetta, si è appena mosso?", enHash = "67c4704b", vanilla = true },
    },
    [8788] = {
        title = { it = "Un regalo scosso delicatamente", enHash = "593e2c58", vanilla = true },
        reward = { it = "Sembra che questo regalo sia stato scosso un paio di volte. Sul biglietto c'è scritto:\n\nPer $Gun:una; $R $C davvero speciale.", enHash = "40cfccf8", vanilla = true },
    },
    [8792] = {
        title = { it = "L'Orda ha bisogno del tuo aiuto!", enHash = "37a0fc59", vanilla = true },
        text = { it = "Ciao, sono $Pcontento:contenta; che tu abbia deciso di ascoltarmi. L'Orda ha bisogno di tutto l'aiuto possibile per prepararsi alla guerra di Ahn'Qiraj, e questo vuol dire che abbiamo bisogno di te! Proprio mentre parliamo, i raccoglitori ufficiali stanno radunando il materiale necessario per la guerra in arrivo, ma senza il tuo aiuto non riusciremo a raggiungere i nostri obiettivi, $N!\n\nDovresti andare a parlare con chi comanda, Warlord Gorchuk. Che ne dici, $C? Darai una mano con i preparativi indispensabili?", enHash = "33bceb0b", vanilla = true },
        objectives = { it = "Parla con Warlord Gorchuk nella Valley of Spirits di Orgrimmar.", enHash = "b5df402d", vanilla = true },
        reward = { it = "Throm'ka, $C! È bello vedere così tanti membri dell'Orda, come te, $N, venire a dare il loro sostegno per gettare le basi della guerra di Ahn'Qiraj in arrivo. Lo sforzo che facciamo qui ci garantirà la vittoria contro i silitidi e i loro malvagi padroni nascosti dentro Ahn'Qiraj.\n\nAllora, ora che sei qui, assicurati di parlare con i vari raccoglitori e di offrire il tuo aiuto per raccogliere i materiali più adatti a te.", enHash = "653f60ee", vanilla = true },
    },
    [8793] = {
        title = { it = "L'Orda ha bisogno del tuo aiuto!", enHash = "37a0fc59", vanilla = true },
        text = { it = "Ciao, sono $Pcontento:contenta; che tu abbia deciso di ascoltarmi. L'Orda ha bisogno di tutto l'aiuto possibile per prepararsi alla guerra di Ahn'Qiraj, e questo vuol dire che abbiamo bisogno di te! Proprio mentre parliamo, i raccoglitori ufficiali stanno radunando il materiale necessario per la guerra in arrivo, ma senza il tuo aiuto non riusciremo a raggiungere i nostri obiettivi, $N!\n\nDovresti andare a parlare con chi comanda, Warlord Gorchuk. Che ne dici, $C? Darai una mano con i preparativi indispensabili?", enHash = "33bceb0b", vanilla = true },
        objectives = { it = "Parla con Warlord Gorchuk nella Valley of Spirits di Orgrimmar.", enHash = "b5df402d", vanilla = true },
        reward = { it = "Throm'ka, $C! È bello vedere così tanti membri dell'Orda, come te, $N, venire a dare il loro sostegno per gettare le basi della guerra di Ahn'Qiraj in arrivo. Lo sforzo che facciamo qui ci garantirà la vittoria contro i silitidi e i loro malvagi padroni nascosti dentro Ahn'Qiraj.\n\nAllora, ora che sei qui, assicurati di parlare con i vari raccoglitori e di offrire il tuo aiuto per raccogliere i materiali più adatti a te.", enHash = "653f60ee", vanilla = true },
    },
