    [8818] = {
        title = { it = "Un Commendation Signet", enHash = "a0a589cc", vanilla = true },
        progress = { it = "Se un avventuriero ha un solo Commendation Signet, glielo cambio con un piccolo riconoscimento da parte di Thunder Bluff.\n\nTieni presente che è meglio consegnare una pila di dieci sigilli tutti insieme: così i tuoi sforzi riceveranno un riconoscimento maggiore. Offriamo il cambio di un singolo sigillo come servizio per chi non ne ha abbastanza per una pila completa da dieci.\n\nDetto questo, sono a tua disposizione se vuoi comunque consegnare un solo sigillo.", enHash = "f83a180b", vanilla = true },
