    [8827] = {
        title = { it = "I regali dell'inverno", enHash = "27a8f7a7", vanilla = true },
        text = { it = "Ho sentito che Greatfather Winter, con il generoso sostegno della Smokeywood Pastures, ha messo dei regali per tutti sotto l'albero a Ironforge. Vorrei tanto andarci, ma devo tenere d'occhio il PX-238 Winter Wondervolt.\n\nMa tu dovresti proprio andare a vedere. Sono sicuro che Greatfather Winter ha dei regali con sopra il tuo nome.", enHash = "5c6d40de", vanilla = true },
        objectives = { it = "Parla con Greatfather Winter. Si trova vicino ai banchi della Smokywood Pastures, a Ironforge.", enHash = "dc6fb868", vanilla = true },
        reward = { it = "Oh, oh, salve! Puoi essere qui per un solo motivo: aprire i tuoi regali della Vigilia di Grande Inverno.\n\nOra, non preoccuparti: Greatfather Winter non si è dimenticato $Gdel suo:della sua; $R $C $Gpreferito:preferita;. Guarda sotto l'albero e troverai i tuoi regali.\n\nIn questo periodo di doni, magari anche ai tuoi amici farebbe piacere ricevere qualcuno degli ottimi prodotti della Smokeywood Pasture?", enHash = "40fd2316", vanilla = true },
    },
    [8828] = {
        title = { it = "I regali dell'inverno", enHash = "27a8f7a7", vanilla = true },
        text = { it = "Ho sentito che Great-father Winter, con il generoso sostegno della Smokeywood Pastures, ha messo dei regali per tutti sotto l'albero a Orgrimmar. Vorrei tanto andarci, ma devo tenere d'occhio il PX-238 Winter Wondervolt.\n\nMa tu dovresti proprio andare a vedere. Sono sicuro che Great-father Winter ha dei regali con sopra il tuo nome.", enHash = "67d5fa33", vanilla = true },
        objectives = { it = "Parla con Great-father Winter. Si trova vicino ai banchi della Smokywood Pastures, a Orgrimmar.", enHash = "c49e7946", vanilla = true },
        reward = { it = "Oh, oh, salve! Puoi essere qui per un solo motivo: aprire i tuoi regali della Vigilia di Grande Inverno.\n\nOra, non preoccuparti: Great-father Winter non si è dimenticato $Gdel suo:della sua; $R $C $Gpreferito:preferita;. Guarda sotto l'albero e troverai i tuoi regali.\n\nIn questo periodo di doni, magari anche ai tuoi amici farebbe piacere ricevere qualcuno degli ottimi prodotti della Smokeywood Pasture?", enHash = "de97c13b", vanilla = true },
    },
    [8830] = {
        title = { it = "Un Commendation Signet", enHash = "a0a589cc", vanilla = true },
        progress = { it = "Se un avventuriero ha un solo Commendation Signet, glielo cambio con un piccolo riconoscimento da parte di Darnassus.\n\nTieni presente che è meglio consegnare una pila di dieci sigilli tutti insieme: così i tuoi sforzi riceveranno un riconoscimento maggiore. Offriamo il cambio di un singolo sigillo come servizio per chi non ne ha abbastanza per una pila completa da dieci.\n\nDetto questo, sono a tua disposizione se vuoi comunque consegnare un solo sigillo.", enHash = "e30ddf22", vanilla = true },
        reward = { it = "Molto bene: le tue gesta sono state messe agli atti, e i tuoi sforzi ti vengono debitamente riconosciuti. Continua così, $C.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", enHash = "3a023983", vanilla = true },
    },
    [8831] = {
        title = { it = "Dieci Commendation Signet", enHash = "7f08a6d0", vanilla = true },
        progress = { it = "Accetto i Commendation Signet dagli avventurieri che li hanno ricevuti nell'adempimento del dovere. Per ogni gruppo di dieci che mi consegni, mi assicurerò che le tue gesta ricevano un riconoscimento significativo da parte di Darnassus. Accetto anche i sigilli singoli, ma con un riconoscimento molto ridotto. A noi interessano molto di più le imprese di maggior valore, anche se nessuna impresa verrà ignorata.\n\nDetto questo, prenderò volentieri i tuoi sigilli, se sei $Gpronto:pronta; a consegnarne un gruppo.", enHash = "51b3bfda", vanilla = true },
        reward = { it = "Eccellente! Non è un sacrificio da poco quello che hai fatto per guadagnarti questi sigilli, e il tuo servizio sarà riconosciuto come si deve. Sono gli avventurieri come te, $N, a fare davvero la differenza.\n\nFammi sapere se hai altri sigilli da consegnare; ti aiuterò volentieri a cambiare tutti quelli che vuoi.", enHash = "35bd5db8", vanilla = true },
    },
    [8832] = {
        title = { it = "Un Commendation Signet", enHash = "a0a589cc", vanilla = true },
        progress = { it = "Se un avventuriero ha un solo Commendation Signet, glielo cambio con un piccolo riconoscimento da parte dell'Undercity.\n\nTieni presente che è meglio consegnare una pila di dieci sigilli tutti insieme: così i tuoi sforzi riceveranno un riconoscimento maggiore. Offriamo il cambio di un singolo sigillo come servizio per chi non ne ha abbastanza per una pila completa da dieci.\n\nDetto questo, sono a tua disposizione se vuoi comunque consegnare un solo sigillo.", enHash = "5b7765f0", vanilla = true },
        reward = { it = "Molto bene: le tue gesta sono state messe agli atti, e i tuoi sforzi ti vengono debitamente riconosciuti. Continua così, $C.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", enHash = "3a023983", vanilla = true },
    },
    [8833] = {
        title = { it = "Dieci Commendation Signet", enHash = "7f08a6d0", vanilla = true },
        progress = { it = "Accetto i Commendation Signet dagli avventurieri che li hanno ricevuti nell'adempimento del dovere. Per ogni gruppo di dieci che mi consegni, mi assicurerò che le tue gesta ricevano un riconoscimento significativo da parte dell'Undercity. Accetto anche i sigilli singoli, ma con un riconoscimento molto ridotto. A noi interessano molto di più le imprese di maggior valore, anche se nessuna impresa verrà ignorata.\n\nDetto questo, prenderò volentieri i tuoi sigilli, se sei $Gpronto:pronta; a consegnarne un gruppo.", enHash = "2e44717d", vanilla = true },
        reward = { it = "Eccellente! Non è un sacrificio da poco quello che hai fatto per guadagnarti questi sigilli, e il tuo servizio sarà riconosciuto come si deve. Sono gli avventurieri come te, $N, a fare davvero la differenza.\n\nFammi sapere se hai altri sigilli da consegnare; ti aiuterò volentieri a cambiare tutti quelli che vuoi.", enHash = "35bd5db8", vanilla = true },
    },
