    },
    [8846] = {
        title = { it = "Cinque sigilli per i rifornimenti di guerra", enHash = "32daebe3", vanilla = true },
        progress = { it = "Ah, sei qui per avere altri rifornimenti per te, vero? Be', capisco bene il bisogno di altro materiale bellico... basta che ti guardi intorno, se ti serve una prova.\n\nTi assegnerò altri rifornimenti, ma in cambio dovrai darmi il giusto numero di Commendation Signet. Consegnando i sigilli in questo modo non riceverai alcun riconoscimento, ma potresti trovare qualcosa di utile che ti aiuti a restare in vita quando la battaglia sarà finalmente arrivata.", enHash = "cf4ba675", vanilla = true },
        reward = { it = "Bene, allora è deciso: ecco i tuoi rifornimenti, $C. Se vuoi fare un altro scambio, sono pronto ad autorizzarlo. Dammi solo il via e ci penso io.\n\nContinua così, $N. Ci serve tutto il materiale bellico che riusciamo a mettere insieme, se vogliamo vincere questa guerra. Se ognuno fa la sua parte, la vittoria sarà a portata di mano!", enHash = "0ed9e5e3", vanilla = true },
    },
    [8847] = {
