    [8853] = {
        title = { it = "Quindici sigilli per i rifornimenti di guerra", enHash = "0fb71398", vanilla = true },
        progress = { it = "Ah, sei qui per avere altri rifornimenti per te, vero? Be', capisco bene il bisogno di altro materiale bellico... basta che ti guardi intorno, se ti serve una prova.\n\nTi assegnerò altri rifornimenti, ma in cambio dovrai darmi il giusto numero di Commendation Signet. Consegnando i sigilli in questo modo non riceverai alcun riconoscimento, ma potresti trovare qualcosa di utile che ti aiuti a restare in vita quando la battaglia sarà finalmente arrivata.", enHash = "cf4ba675", vanilla = true },
        reward = { it = "Bene, allora è deciso: ecco i tuoi rifornimenti, $C. Se vuoi fare un altro scambio, sono pronto ad autorizzarlo. Dammi solo il via e ci penso io.\n\nContinua così, $N. Ci serve tutto il materiale bellico che riusciamo a mettere insieme, se vogliamo vincere questa guerra. Se ognuno fa la sua parte, la vittoria sarà a portata di mano!", enHash = "55a02bf9", vanilla = true },
    },
    [8860] = {
        title = { it = "Festeggiamenti per il New Year!", enHash = "eddb9e55", vanilla = true },
        text = { it = "Stormwind organizza una festa per il nuovo anno! Per tutta la giornata di oggi puoi avere da bere gratis, e stanotte faranno uno spettacolo di fuochi d'artificio! Dovrebbe essere piuttosto bello... ma anche Booty Bay oggi fa una festa; scommetto che sarà ancora meglio!\n\nComunque, a Innkeeper Allison, a Stormwind, serve una scorta di cibo della Smoky Wood Pasture per sfamare tutti i festaioli. Mi fai il favore di consegnargliela?\n\nGrazie, $N! Innkeeper Allison è al Gilded Rose, nel Trade District di Stormwind.", enHash = "af0eea33", vanilla = true },
        objectives = { it = "Porta le Smokywood Supplies a Innkeeper Allison, a Stormwind.", enHash = "1cf3e21e", vanilla = true },
        progress = { it = "Salve! Sei qui per la festa? O forse devi solo far riposare quei tuoi piedi stanchi...", enHash = "92304fcb", vanilla = true },
        reward = { it = "Oh, le mie provviste della Smokywood! Splendido! Mi serviranno per sfamare tutta la gente in città per la festa!\n\nGrazie, $N. Prendi questo come pagamento, e non dimenticare di bere e ballare con i festaioli qui fuori!", enHash = "d100645a", vanilla = true },
    },
    [8861] = {
        title = { it = "Festeggiamenti per il New Year!", enHash = "eddb9e55", vanilla = true },
        text = { it = "Thunder Bluff organizza una festa per il nuovo anno! Per tutto il giorno lì troverai da bere gratis, e stanotte faranno uno spettacolo di fuochi d'artificio!\n\nDovrebbe essere piuttosto bello... ma anche Booty Bay oggi fa una festa; scommetto che sarà ancora meglio!\n\nComunque, a Innkeeper Pala, a Thunder Bluff, serve una scorta di cibo della Smoky Wood Pasture per sfamare tutti i festaioli. Mi fai il favore di consegnargliela?\n\nGrazie, $N! Innkeeper Pala è nella locanda vicino al ponte per l'Hunter's Rise.", enHash = "53d88606", vanilla = true },
        objectives = { it = "Porta le Smokywood Supplies a Innkeeper Pala, a Thunder Bluff.", enHash = "72ffa3e4", vanilla = true },
        progress = { it = "Buongiorno, $C! Sei $Gvenuto:venuta; a Thunder Bluff per i nostri festeggiamenti? O sei qui per far riposare uno zoccolo stanco tra una caccia e l'altra?", enHash = "726e9203", vanilla = true },
        reward = { it = "Oh, molto bene! Queste provviste aiuteranno a sfamare tutta la nostra gente, qui per festeggiare il nuovo anno!\n\nTi ringrazio, $N. Sei in debito con me. Ti prego, prendi queste monete... e segui il mio consiglio: bevi a volontà dai barili qui fuori, e unisciti ai festaioli in una danza di festa!", enHash = "c8ca3e8e", vanilla = true },
    },
    [8862] = {
        title = { it = "Elune's Candle", enHash = "270bfb3c", vanilla = true },
        progress = { it = "Elune's Candle è un manufatto molto venerato dai discepoli della Celebrazione della Luna. Nella candela è racchiusa la vera luce lunare, pronta a essere liberata!\n\nQuesta luce è innocua per la maggior parte delle creature, ma scoprirai che Omen e i suoi servitori ne vengono bruciati e abbagliati.", enHash = "274f0d37", vanilla = true },
        reward = { it = "Molto bene, allora: accetto questi Coin of Ancestry. Prendi Elune's Candle, con la mia benedizione. E goditi anche questi fuochi d'artificio in omaggio.\n\nChe la tua Celebrazione della Luna sia gioiosa e piena di allegria, $N.\n\nE se sceglierai di affrontare Omen e i suoi servitori, vedrai che Elune's Candle ti sarà molto utile...", enHash = "f2dcf5f6", vanilla = true },
    },
    [8863] = {
        title = { it = "Festival Dumplings", enHash = "b95b9521", vanilla = true },
        progress = { it = "Se hai fame, sei $Gcapitato:capitata; nel posto giusto, $Gamico mio:amica mia;!\n\nI ravioli sono il cibo tradizionale della Celebrazione della Luna: si servono fin dai tempi della prima Celebrazione della Luna, e mi fa piacere poterli offrire anche in questa. In cambio di un solo Coin of Ancestry, ti farò assaggiare uno dei piatti più gustosi che ti capiterà mai di provare!", enHash = "4e386559", vanilla = true },
        reward = { it = "Eccellente: goditi questi ravioli, offerti da me. Sono solo un piccolo segno di apprezzamento per l'onore che ti sei $Gguadagnato:guadagnata; con le tue azioni, ma credo che ti piaceranno lo stesso.\n\nSe hai altri Coin of Ancestry, sono a tua disposizione con un'ampia scelta di oggetti in cambio.", enHash = "231fcebe", vanilla = true },
    },
    [8864] = {
        title = { it = "Abiti festivi lunari", enHash = "be0e2553", vanilla = true },
        progress = { it = "Ho una selezione di abiti che potrebbe interessarti. Abiti come questi si indossavano un tempo durante la Celebrazione della Luna, e la selezione che ho oggi è forse la più bella che abbia mai visto. Ognuno è fatto a mano con i materiali più pregiati e morbidi.\n\nIn cambio di qualche Coin of Ancestry, ti lascerò scegliere uno dei tre modelli che ho, da tenere per te. Ti va bene?", enHash = "fa11f1ae", vanilla = true },
        reward = { it = "Molto bene, allora: accetto questi Coin of Ancestry. Prendi il tuo abito, con la mia benedizione. E goditi anche questi fuochi d'artificio in omaggio.\n\nCome hai onorato i tuoi anziani, così onori me con la tua sola presenza. Grazie, e che la tua Celebrazione della Luna sia gioiosa.", enHash = "f31cb0f7", vanilla = true },
    },
    [8865] = {
        title = { it = "Completi pantalone festivi lunari", enHash = "da05c22f", vanilla = true },
        progress = { it = "Ho il piacere di informarti che ho una bella selezione di completi pantalone festivi che possono diventare tuoi... ma solo in cambio di Coin of Ancestry. Se tieni alla moda, è proprio quello che cerchi! Ti assicuro che completi come questi non li troverai da nessun'altra parte.\n\nIn cambio di qualche Coin of Ancestry, ti lascerò scegliere uno dei tre modelli che ho, da tenere per te. Ti va bene?", enHash = "c4fd771b", vanilla = true },
        reward = { it = "Molto bene, allora: accetto questi Coin of Ancestry. Prendi il tuo completo pantalone, con la mia benedizione. E goditi anche questi fuochi d'artificio in omaggio.\n\nSe hai altri Coin of Ancestry da scambiare, torna a parlarmi. Offrirò vari oggetti per tutta la durata della Celebrazione della Luna.", enHash = "ec95626a", vanilla = true },
    },
    [8866] = {
        title = { it = "Bronzebeard the Elder", enHash = "8b227bd1", vanilla = true },
        reward = { it = "È bello sapere che la gente di queste terre rende ancora omaggio alle razze antiche. Ti auguro ogni bene, $N, e ti offro questo pegno...", enHash = "8cd04889", vanilla = true },
    },
    [8867] = {
        title = { it = "Lunar Fireworks", enHash = "50d0c262", vanilla = true },
        text = { it = "Ogni anno i druidi di Moonglade celebrano il grande trionfo della nostra città su un antico male.\n\nCelebriamo la saggezza dei nostri anziani, partecipiamo a banchetti magnifici e, naturalmente... lanciamo fuochi d'artificio!\n\nCon una piccola offerta puoi comprare dei razzi colorati dal nostro venditore. Prova a usare qualcuno dei lanciarazzi qui intorno, $N.", enHash = "cf760700", vanilla = true },
        objectives = { it = "Lancia 8 Lunar Fireworks e 2 Cluster Fireworks, poi torna da una Lunar Festival Harbinger in una qualsiasi capitale.", enHash = "ad1e7721", vanilla = true },
        progress = { it = "Hai trovato i lanciarazzi, $N?", enHash = "12cda602", vanilla = true },
        reward = { it = "Ben fatto, $N.\n\nOra che sei $Gentrato:entrata; nello spirito della festa, perché non prendi questo invito ai festeggiamenti di Moonglade?\n\nÈ una celebrazione davvero piacevole, se hai tempo. Condividiamo cibo, bevande, storie e, naturalmente... altri fuochi d'artificio!\n\nApri l'invito stando dentro il cerchio di luce lunare più intensa e verrai $Gtrasportato:trasportata; a Moonglade.", enHash = "c5b928b0", vanilla = true },
    },
    [8870] = {
        title = { it = "La Celebrazione della Luna", enHash = "742742f1", vanilla = true },
        text = { it = "È arrivato quel periodo dell'anno, $N! Il Cenarion Circle invita tutti gli abitanti di Azeroth a partecipare ai nostri festeggiamenti per la Celebrazione della Luna. Troverai la Lunar Festival Harbinger proprio in questa città, in un punto segnato da un cerchio benedetto di luce lunare. Può dirti di più sulla festa.", enHash = "3d427b5b", vanilla = true },
        objectives = { it = "Parla con la Lunar Festival Harbinger nel Mystic Ward di Ironforge. Puoi parlare anche con le Lunar Festival Harbinger delle altre capitali.", enHash = "24e6a855", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti ai festeggiamenti?", enHash = "ac2abb08", vanilla = true },
    },
    [8871] = {
        title = { it = "La Celebrazione della Luna", enHash = "742742f1", vanilla = true },
        text = { it = "È arrivato quel periodo dell'anno, $N! Il Cenarion Circle invita tutti gli abitanti di Azeroth a partecipare ai nostri festeggiamenti per la Celebrazione della Luna. Troverai la Lunar Festival Harbinger proprio in questa città, in un punto segnato da un cerchio benedetto di luce lunare. Può dirti di più sulla festa.", enHash = "3d427b5b", vanilla = true },
        objectives = { it = "Parla con la Lunar Festival Harbinger nel Park District di Stormwind. Puoi parlare anche con le Lunar Festival Harbinger delle altre capitali.", enHash = "793b2aa6", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti ai festeggiamenti?", enHash = "798d8ec4", vanilla = true },
    },
    [8872] = {
