        reward = { it = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti ai festeggiamenti?", enHash = "798d8ec4", vanilla = true },
    },
    [8875] = {
        title = { it = "La Celebrazione della Luna", enHash = "742742f1", vanilla = true },
        text = { it = "È arrivato quel periodo dell'anno, $N! Il Cenarion Circle invita tutti gli abitanti di Azeroth a partecipare ai nostri festeggiamenti per la Celebrazione della Luna. Troverai la Lunar Festival Harbinger proprio in questa città, in un punto segnato da un cerchio benedetto di luce lunare. Può dirti di più sulla festa.", enHash = "3d427b5b", vanilla = true },
        objectives = { it = "Parla con la Lunar Festival Harbinger all'Elder Rise di Thunder Bluff. Puoi parlare anche con le Lunar Festival Harbinger delle altre capitali.", enHash = "5757f1d3", vanilla = true },
        reward = { it = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti ai festeggiamenti?", enHash = "798d8ec4", vanilla = true },
    },
    [8876] = {
        title = { it = "Razzi piccoli", enHash = "bfbcce06", vanilla = true },
        progress = { it = "Custodisco i segreti per creare i razzi della Celebrazione della Luna, e mi fa piacere condividere il mio sapere con chi è degno di onore.\n\nIn cambio di qualche Coin of Ancestry, posso offrirti la ricetta per fare un razzo piccolo...", enHash = "c7c19a24", vanilla = true },
        reward = { it = "Ah, molto bene. Ecco le tue ricette, $N, e che Elune ti benedica.", enHash = "28645865", vanilla = true },
    },
    [8883] = {
        title = { it = "Valadar Starsong", enHash = "ba6123f2", vanilla = true },
        text = { it = "Ora che hai la tua Lunar Festival Invitation, puoi raggiungere Moonglade! Lì troverai molti festeggianti, e nel villaggio di Nighthaven Valadar Starsong e sua sorella Fariel aspettano chi desidera partecipare alla celebrazione.\n\nRaggiungi Moonglade attraverso la luce lunare più intensa e parla con Valadar Starsong: scopri quali premi potresti vincere durante la festa!", enHash = "2c5169d9", vanilla = true },
        objectives = { it = "Usa la tua Lunar Festival Invitation nella luce lunare per raggiungere Moonglade. Quando arrivi, parla con Valadar Starsong a Nighthaven.", enHash = "c4e5c0cb", vanilla = true },
        reward = { it = "$N, $Gbenvenuto:benvenuta; a Nighthaven, che ospita la Celebrazione della Luna! Anche se di solito il nostro villaggio è remoto e isolato dai popoli di Azeroth, in questo periodo di festa apriamo a tutti le braccia e il cuore.\n\nGoditi la visita, $N, e torna a parlare con me o con mia sorella quando sarai $Gpronto:pronta;.", enHash = "e90dbeba", vanilla = true },
    },
    [8897] = {
        title = { it = "Carissima Colara,", enHash = "e1e9f910", vanilla = true },
        text = { it = "Devo fare la guardia qui al cancello, ma sono sempre in pensiero per la mia amata, Colara. Riesco a vederla solo per qualche ora, se mi va bene, e poi... guardami. Ho la paga di un ufficiale di basso grado e potrei essere chiamato al fronte da un giorno all'altro.\n\nE se si dimenticasse di me? In città ci sono tanti uomini. Tanti uomini ricchi.\n\nComunque, ho buttato giù qualcosa... niente di che, ma se potessi portarglielo tu, sarebbe fantastico.", enHash = "ebededb2", vanilla = true },
        objectives = { it = "Consegna Lieutenant Heldric's Carefully Penned Note a Colara Dean, fuori dalla banca di Stormwind.", enHash = "0f3ea6d1", vanilla = true },
        progress = { it = "$GCiao, bel ragazzo. Posso aiutarti in qualcosa?:Oh, cielo! Posso aiutarti in qualcosa?;", enHash = { "da06fdc5", "e49bb358" }, vanilla = true },
        reward = { it = "Oh, che dolce! È la prima volta che mi manda qualcosa. Pensi che stia facendo sul serio?\n\nColara Heldric? Non suona male. Oh, ma sto correndo troppo. Grazie.", enHash = "f483c09e", vanilla = true },
    },
    [8898] = {
        title = { it = "Carissima Colara,", enHash = "e1e9f910", vanilla = true },
        text = { it = "Ho conosciuto una ragazza a Stormwind, l'ultima volta che ci sono stato per affari della banca. Mi ha rubato il cuore. E adesso non riesco a smettere di pensare a lei! Vorrei mandarle questo messaggio: l'ho riscritto dodici volte!\n\nIn questo periodo la posta è così piena, e voglio essere sicuro che arrivi.\n\nSe vai da quelle parti, potresti aiutarmi?", enHash = "63646bc9", vanilla = true },
        objectives = { it = "Consegna la Creased Letter a Colara Dean, fuori dalla banca di Stormwind.", enHash = "751d88ee", vanilla = true },
        progress = { it = "Ciao, bel ragazzo. Posso aiutarti in qualcosa?", enHash = "da06fdc5", vanilla = true },
        reward = { it = "Tormek? Oh sì, me lo ricordo. Aveva una gran bella barba, e sotto un bel sorriso.\n\nAh, non posso credere che si sia ricordato di me!", enHash = "bec74dba", vanilla = true },
    },
    [8899] = {
        title = { it = "Carissima Colara,", enHash = "e1e9f910", vanilla = true },
        text = { it = "Come descrivere la sua bellezza? Migliaia di anni di parole, e non trovo le mie.\n\nQuesti mortali confondono la mente e ci riducono a sciocchi balbettanti.\n\nHo fissato queste parole troppo a lungo. Non riesco a spremerne un significato più eloquente. No, deve riceverla adesso, o qualche altro corteggiatore le ruberà di sicuro lo sguardo.", enHash = "429dcc20", vanilla = true },
        objectives = { it = "Consegna l'Immaculate Letter a Colara Dean, fuori dalla banca di Stormwind.", enHash = "c6c23bd1", vanilla = true },
        progress = { it = "Ciao, bel ragazzo. Posso aiutarti in qualcosa?", enHash = "da06fdc5", vanilla = true },
        reward = { it = "Non avevo mai ricevuto niente del genere. Che bello!", enHash = "a15e71aa", vanilla = true },
    },
    [8900] = {
        title = { it = "Carissima Elenia,", enHash = "463b0838", vanilla = true },
        text = { it = "Era così triste. L'ho capito quando sono riuscito a guardare oltre la sua condizione. Voglio dire, sembrava triste... non lo saresti anche tu?\n\nMa dopo averle parlato, c'era un legame. Non pensavo che qualcuno potesse capire quello che pensavo, ma lei ci riusciva.\n\nQuando l'ho detto agli altri, mi hanno riso in faccia, e così non le ho più parlato. Ma mi manca. Puoi portarle questa lettera per me? Voglio essere sicuro che arrivi nelle sue mani.", enHash = "9108410d", vanilla = true },
        objectives = { it = "Consegna la Slightly Creased Note a Elenia Haydon, vicino alla banca dell'Undercity.", enHash = "4d440e3d", vanilla = true },
        progress = { it = "Oh, e a cosa devo questo piacere?", enHash = "e05b2372", vanilla = true },
        reward = { it = "Non ti aspetteresti tanta eloquenza da un orco. Certo, finora non abbiamo mai avuto davvero l'occasione di conoscerli. Grazie di avermela portata.", enHash = "df8fc9ab", vanilla = true },
    },
    [8901] = {
        title = { it = "Carissima Elenia,", enHash = "463b0838", vanilla = true },
        text = { it = "Hai mai conosciuto l'amore, giovane? Per me era una cosa sconosciuta fino a poco tempo fa, quando ho incontrato una ragazza dell'Undercity, Elenia. È già raro che uno della mia specie guardi al di fuori della propria gente, figuriamoci a una Reietta.\n\nMa ora il pensiero di lei mi occupa la mente giorno e notte.\n\nSe puoi, potresti portarle questa lettera? Vorrei che venisse qui a Mulgore. Spero che dirà di sì.", enHash = "1a8e1818", vanilla = true },
        objectives = { it = "Consegna la Carefully Written Letter a Elenia Haydon, vicino alla banca dell'Undercity.", enHash = "db2f75ae", vanilla = true },
        progress = { it = "Oh, e a cosa devo questo piacere?", enHash = "e05b2372", vanilla = true },
        reward = { it = "Che parole gentili mi scrive Temma. Ma per quanto le sue parole mi commuovano, non posso prendere in considerazione l'amore di un tauren. Nei pensieri, nel corpo e nella mente siamo troppo diversi.\n\nMeno male che non devo ricevere di persona questi suoi pensieri. Non sopporterei di spezzargli il cuore.", enHash = "f97467af", vanilla = true },
    },
    [8902] = {
        title = { it = "Carissima Elenia,", enHash = "463b0838", vanilla = true },
        text = { it = "Una vita fa ero promesso sposo di Elenia, la mia fidanzatina d'infanzia. Erano anni che non pensavo a lei, ma ultimamente occupa spesso i miei pensieri.\n\nForse, nonostante tutto quello che è successo, nelle nostre vite può esserci ancora un po' di spazio per il nostro amore.\n\nSono sicuro che anche lei sarà cambiata. Puoi consegnarle questa lettera per me? Sono troppo nervoso per dargliela di persona.", enHash = "5021e6c7", vanilla = true },
        objectives = { it = "Consegna la Lovingly Composed Letter a Elenia Haydon, vicino alla banca dell'Undercity.", enHash = "c8989f94", vanilla = true },
        progress = { it = "Oh, e a cosa devo questo piacere?", enHash = "e05b2372", vanilla = true },
        reward = { it = "Questo mi riporta alla mente ricordi di una vita fa, $N. Elenia Tor. Sarebbe stato il mio nome, sai. Avremmo fatto una bellissima cerimonia sulle rive del lago. Quando lui si fosse ritirato, avremmo trovato una fattoria dove passare la vecchiaia.\n\nSogni semplici, allora.\n\nMa se mi vedesse adesso, dubito che vedrebbe in me Elenia. Solo carne fredda e un cuore morto...", enHash = "838f8ed0", vanilla = true },
    },
    [8903] = {
        title = { it = "Amore pericoloso", enHash = "3622d388", vanilla = true },
        text = { it = "C'è qualcosa di innaturale in questa epidemia d'amore. Non è decoroso, è uno spettacolo indecente e, nel peggiore dei casi, potrebbe essere una minaccia per la sicurezza stessa dell'Alleanza.\n\nPensaci: e se anche le guardie fossero state colpite da questo strano male? Bisogna fare qualcosa.\n\nVa' da una delle guardie qui a Stormwind e vedi se anche loro sono state prese da questa follia.", enHash = "43b469fc", vanilla = true },
        objectives = { it = "Procurati una Stormwind Guard's Card e riportala ad Aristan Mottar, a Stormwind.", enHash = "86baa9b3", vanilla = true },
        progress = { it = "Avevo ragione a preoccuparmi? Le guardie sono state colpite da questo mal d'amore?", enHash = "32f86f96", vanilla = true },
        reward = { it = "Allora è vero. È incredibile. Come può essere successo? Lasciami pensare un momento. Dev'esserci una ragione dietro tutto questo.", enHash = "d2e2a3a2", vanilla = true },
    },
    [8904] = {
        title = { it = "Amore pericoloso", enHash = "3622d388", vanilla = true },
        text = { it = "C'è qualcosa di innaturale in questa epidemia d'amore. È disgustosa e, abbassando le nostre difese, potrebbe essere una minaccia per tutti noi.\n\nÈ già abbastanza grave che così tanti della nostra gente siano presi da questo comportamento ridicolo. Ma credo che si sia diffusa persino ai nostri guardiani, che dovrebbero essere immuni a cose del genere.\n\nTrova uno dei nostri guardiani e vedi se anche loro sono stati presi da questa follia.", enHash = "030db650", vanilla = true },
        objectives = { it = "Procurati una Guardian's Moldy Card e portala a Fenstad Argyle, nell'Undercity.", enHash = "8db7f7ba", vanilla = true },
        progress = { it = "Avevo ragione a preoccuparmi? Quegli idioti dei nostri guardiani hanno ceduto?", enHash = "0a4430bb", vanilla = true },
        reward = { it = "Allora è vero. È incredibile. Come può essere successo? Lasciami pensare un momento. Dev'esserci una ragione dietro tutto questo.", enHash = "d2e2a3a2", vanilla = true },
    },
    [8979] = {
        title = { it = "L'intuizione di Fenstad", enHash = "a07d1c85", vanilla = true },
        text = { it = "Credo di sapere la causa di questo comportamento recente. Hai sentito il nuovo profumo nell'aria, sopra la puzza dei canali? Le nuove acque di colonia e i profumi che sono diventati di moda?\n\nIl nostro modo di pensare è stato annebbiato da qualche alchimia immonda.\n\nC'è un solo modo per esserne sicuri: porta una bottiglia di acqua di colonia e una di profumo alla mia amica, Apothecary Zinge. La Royal Apothecary Society scoprirà la verità.\n\nTi rimborserò l'acquisto quando tornerai.", enHash = "724c3e6f", vanilla = true },
        objectives = { it = "Porta 1 Cologne Bottle e 1 Perfume Bottle ad Apothecary Zinge, nell'Apothecarium dell'Undercity.", enHash = "4ccdcbd7", vanilla = true },
        progress = { it = "Come posso servirti?", enHash = "b84a5733", vanilla = true },
        reward = { it = "Un'altra delle fissazioni di Fenstad, vedo. Crede forse che la Royal Apothecary Society non abbia niente di meglio da fare che portare avanti le sue piccole indagini?\n\nE va bene, lo accontenterò ancora una volta.", enHash = "b0d8f0b5", vanilla = true },
    },
    [8980] = {
        title = { it = "La valutazione di Zinge", enHash = "d9544919", vanilla = true },
        text = { it = "Questo non me l'aspettavo. Sembra che Fenstad, dopotutto, abbia visto giusto. Ho trovato tracce di sostanze usate nelle pozioni per il controllo della mente.\n\nNon è insolito che i profumi ne contengano un po', ma alcuni degli ingredienti che ho trovato... Questa è alchimia seria, all'altezza di un membro della Royal Apothecary Society.", enHash = "c173bf38", vanilla = true },
        objectives = { it = "Torna da Fenstad Argyle, fuori dalla banca dell'Undercity.", enHash = "ef4678bd", vanilla = true },
        reward = { it = "Allora avevo ragione. Non dobbiamo perdere tempo. Dobbiamo scoprire da dove vengono queste fragranze corrotte.\n\nEcco, per rimborsarti l'acquisto dell'acqua di colonia e del profumo.", enHash = "7b1835ca", vanilla = true },
    },
    [8981] = {
        title = { it = "Fare regali", enHash = "91f9507e", vanilla = true },
        progress = { it = "Sei $Gvenuto:venuta; a consegnare un regalo d'amore e d'affetto al tuo capo preferito?", enHash = "2ca9721a", vanilla = true },
        reward = { it = "Magnifico! Magnifico! Lo aggiungerò alla pila degli altri regali.\n\nNon me ne aspettavo così tanti! Devi proprio voler bene ai tuoi capi.\n\nOra, fammene aggiungere un altro al conteggio...", enHash = "4e884c71", vanilla = true },
    },
    [8982] = {
        title = { it = "Risalire alla fonte", enHash = "5b75b8c8", vanilla = true },
        text = { it = "Dobbiamo scoprire chi è il fornitore. Ho notato che Apothecary Katrina aveva una bottiglia di quel profumo infilata nella borsa. Mi ha detto di averla comprata da Norman, il locandiere.", enHash = "8af53b09", vanilla = true },
        objectives = { it = "Parla con Innkeeper Norman, nell'Undercity.", enHash = "6e098bef", vanilla = true },
        reward = { it = "Ah sì, ho ricevuto da poco una fornitura di profumo e acqua di colonia. Non so quanto riuscirò a tenerla sugli scaffali: sembra che nessuno ne abbia mai abbastanza.\n\nSe vuoi il mio parere, non capisco tutto questo clamore.", enHash = "f265e105", vanilla = true },
    },
    [8983] = {
        title = { it = "Risalire alla fonte", enHash = "5b75b8c8", vanilla = true },
        text = { it = "C'è qualcosa che non va nella mia merce? Be', non ho mai visto così tanta gente volere qualcosa così disperatamente.\n\nHo comprato la mia scorta da una mercante di nome Mara Rennick. È nuova in città.\n\nHa detto che doveva consegnare della merce al sarto del Mage Quarter.", enHash = "2f87cd7f", vanilla = true },
        objectives = { it = "Parla con Mara Rennick, alla bottega del sarto nel Mage Quarter dell'Undercity.", enHash = "dc2c02fa", vanilla = true },
        reward = { it = "Purtroppo ho venduto tutta la mia scorta di profumo e acqua di colonia a Norman, il locandiere. Se ne vuoi un po', dovresti parlare con lui, sempre che gliene sia rimasta.\n\nPerò non dovresti perdere tempo. Credo che troverai $Gl'acqua di colonia:il profumo; irresistibile.", enHash = { "d2bb5b14", "cbaa543f" }, vanilla = true },
    },
    [8984] = {
        title = { it = "La fonte svelata", enHash = "3b9e15e2", vanilla = true },
        text = { it = "Senti, le azioni di uno speziale rinnegato non mi riguardano. Se sta sabotando i nostri sforzi, lascia che sia io la prima a indicarti la strada giusta.\n\nSe è innocente, allora non ha niente da nascondere, giusto?\n\nHo comprato la merce da Apothecary Staffron Lerent. Lavora in un posto isolato oltre il Ravenholdt Manor, sulle colline sopra Hillsbrad. A dire il vero, mi è sembrato un po' strano.", enHash = "0f46fd55", vanilla = true },
        objectives = { it = "Trova Apothecary Staffron Lerent nelle Hillsbrad Foothills, oltre il Ravenholdt Manor.", enHash = "6bbd201d", vanilla = true },
        reward = { it = "Sì, quelle fragranze le ho fatte io. Un profumo meraviglioso, non trovi? Irresistibile.\n\nUna volta che i guerrieri dell'Alleanza e dell'Orda saranno presi da questi sentimenti d'amore, non avranno la forza di fermare l'ascesa del Concilio dell'Ombra.\n\nSaranno indeboliti, impreparati. Preoccupandosi per i loro cari, perderanno la loro prontezza.\n\nLa soluzione era così semplice. Perché ci ho messo tanto a trovarla? Il punto debole di tutti è il cuore. E non c'è niente che tu possa fare per fermare l'inevitabile.", enHash = "160ecb85", vanilla = true },
    },
    [8993] = {
        title = { it = "Fare regali", enHash = "91f9507e", vanilla = true },
        progress = { it = "Sei $Gvenuto:venuta; a consegnare un regalo d'amore e d'affetto al tuo capo preferito?", enHash = "2ca9721a", vanilla = true },
        reward = { it = "Magnifico! Magnifico! Lo aggiungerò alla pila degli altri regali.\n\nNon me ne aspettavo così tanti! Devi proprio voler bene ai tuoi capi.\n\nOra, fammene aggiungere un altro al conteggio...", enHash = "4e884c71", vanilla = true },
    },
    [9024] = {
        title = { it = "L'intuizione di Aristan", enHash = "79947bd8", vanilla = true },
        text = { it = "Ci sono! Hai sentito il nuovo profumo nell'aria? Le nuove acque di colonia e i profumi che sono diventati di moda? Le nostre guardie non trascurerebbero i loro doveri così facilmente.\n\nA meno che il loro modo di pensare non sia stato annebbiato da qualche alchimia immonda.\n\nC'è un solo modo per esserne sicuri: porta una bottiglia di acqua di colonia e una di profumo a Morgan Pestle, e riferiscigli i miei sospetti. Ti rimborserò l'acquisto quando tornerai.", enHash = "7195b964", vanilla = true },
        objectives = { it = "Porta 1 Cologne Bottle e 1 Perfume Bottle a Morgan Pestle, nel Trade District di Stormwind.", enHash = "1277d37a", vanilla = true },
        progress = { it = "Posso aiutarti in qualcosa?", enHash = "9d407e26", vanilla = true },
        reward = { it = "Capisco le preoccupazioni di Aristan, ma credo davvero che stia esagerando. Lascia che i giovani, uomini e donne, facciano come vogliono. Credo che Aristan abbia dimenticato cosa vuol dire essere giovani e innamorati.\n\nMa sarà meglio non dirglielo. Lo accontenteremo.", enHash = "e64ae35e", vanilla = true },
    },
    [9025] = {
        title = { it = "La scoperta di Morgan", enHash = "e8186f80", vanilla = true },
        text = { it = "Ma guarda un po'. Sembra che Aristan, dopotutto, abbia visto giusto. Ho trovato tracce di sostanze usate nei filtri d'amore e in subdole pozioni che alterano la mente.\n\nNon è insolito che i profumi ne contengano un po', ma alcuni degli ingredienti che ho trovato... Hanno un odore strano.", enHash = "6ca7b92f", vanilla = true },
        objectives = { it = "Torna da Aristan Mottar, fuori dalla banca nel Trade District di Stormwind.", enHash = "4f761962", vanilla = true },
        reward = { it = "Anche se pensavo che sarebbe andata così, scoprire che i miei sospetti erano fondati è comunque inquietante. Dobbiamo valutare con attenzione la nostra prossima mossa.\n\nEcco, per rimborsarti l'acquisto dell'acqua di colonia e del profumo.", enHash = "0efab6e5", vanilla = true },
    },
    [9026] = {
        title = { it = "Risalire alla fonte", enHash = "5b75b8c8", vanilla = true },
        text = { it = "Dobbiamo trovare la fonte. Ho visto molta più gente del solito, guardie comprese, entrare e uscire dal Gilded Rose. Parla con Allison. Se è lei a venderli, può dirti da dove vengono.", enHash = "63996000", vanilla = true },
        objectives = { it = "Parla con Innkeeper Allison al Gilded Rose, nel Trade District di Stormwind.", enHash = "f2be61c5", vanilla = true },
        reward = { it = "Oh sì, ho ricevuto da poco il profumo e l'acqua di colonia. Si vendono così bene che non so quanto riuscirò a tenerli sugli scaffali.\n\nSe vuoi il mio parere, è un po' noioso. Tutti con lo stesso odore? Il profumo è ottimo, ma comunque.", enHash = "ddb2b5fa", vanilla = true },
    },
    [9027] = {
        title = { it = "Risalire alla fonte", enHash = "5b75b8c8", vanilla = true },
        text = { it = "C'è qualcosa di strano nell'acqua di colonia? È possibile. Non ho mai visto così tanta gente cercare un prodotto in questo modo.\n\nSenti, se c'è qualcosa che non va, voglio saperlo anch'io. Ho comprato la mia scorta da un mercante di nome Evert Sorisam. È nuovo in città.\n\nHa detto che aveva della merce da consegnare a The Finest Thread.", enHash = "3ba6d9bb", vanilla = true },
        objectives = { it = "Parla con Evert Sorisam a The Finest Thread, lungo i Canals di Stormwind.", enHash = "a08bd94d", vanilla = true },
        reward = { it = "Sì, certo. Quelle fragranze sono gli articoli più richiesti della stagione. Sarai la quinta o sesta persona che me lo chiede nell'ultima ora.\n\nPurtroppo ho esaurito tutte le scorte. Se ne vuoi un po', dovresti parlare con Allison, la locandiera del Gilded Rose.\n\nPerò non dovresti perdere tempo. Credo che troverai $Gl'acqua di colonia:il profumo; irresistibile.", enHash = { "cf251a76", "05ee8aeb" }, vanilla = true },
    },
    [9028] = {
        title = { it = "La fonte svelata", enHash = "3b9e15e2", vanilla = true },
        text = { it = "Cosa? Tradimento? No, no. Ti assicuro che le mie intenzioni sono del tutto innocue.\n\nÈ così sbagliato aiutare chi vuole alleviare il doloroso rituale del corteggiamento? Andiamo, non è un crimine.\n\nE per dimostrare che non ho cattive intenzioni, ti dirò persino il mio fornitore.\n\nMe li ha spediti un certo Staffron Lerent, uno speziale di qualche tipo. Non ci ho mai parlato.\n\nIl nostro intermediario goblin ha detto che lavorava sulle colline sopra Hillsbrad, oltre quel misterioso Ravenholdt Manor. Ti auguro buona fortuna nel trovarlo.", enHash = "d419e90a", vanilla = true },
        objectives = { it = "Trova Apothecary Staffron Lerent nelle Hillsbrad Foothills, dietro il Ravenholdt Manor.", enHash = "c93f6785", vanilla = true },
        reward = { it = "Sì, quelle fragranze le ho fatte io. Un profumo meraviglioso, non trovi? Irresistibile.\n\nUna volta che i guerrieri dell'Alleanza e dell'Orda saranno presi da questi sentimenti d'amore, non avranno la forza di fermare l'ascesa del Concilio dell'Ombra.\n\nSaranno indeboliti, impreparati. Preoccupandosi per i loro cari, perderanno la loro prontezza.\n\nLa soluzione era così semplice. Perché ci ho messo tanto a trovarla? Il punto debole di tutti è il cuore. E non c'è niente che tu possa fare per fermare l'inevitabile.", enHash = "160ecb85", vanilla = true },
    },
    [9029] = {
        title = { it = "Un Bubbling Cauldron", enHash = "edfe39da", vanilla = true },
        reward = { it = "Un profumo gradevole si leva dal calderone.", enHash = "56ebeedd", vanilla = true },
    },
    [9247] = {
        title = { it = "La chiamata del Keeper", enHash = "ce425c31", vanilla = true },
        text = { it = "$N,\n\nIn passato hai servito gli interessi dell'Argent Dawn, sempre al meglio delle tue capacità. Ora, ancora una volta, lanciamo la chiamata alle armi nel momento del bisogno più grande.\n\n$N, ti preghiamo di presentarti al Keeper of the Rolls, alla Light's Hope Chapel negli Eastern Plaguelands, se sei $Gdisposto:disposta; ad aiutarci ancora una volta.", enHash = "dc8e3ae1", vanilla = true },
        objectives = { it = "Porta la Letter from the Keeper of the Rolls a lui, alla Light's Hope Chapel negli Eastern Plaguelands.", enHash = "1d37ec84", vanilla = true },
    },
    [9259] = {
        title = { it = "Traditore dei Bloodsail", enHash = "49a8eee6", vanilla = true },
        progress = { it = "Quel cane rognoso di Revilgaz ha offerto il perdono a tutti gli ex Bloodsail disposti a voltare le spalle al loro capitano! Quel succhiasentina mi ha chiesto di far fuori i miei vecchi compagni e di riportargli le loro bandane come prova.\n\nNon ho il cuore di farlo, e non lo chiederò nemmeno a te. Portami un po' di Silk Cloth e di Red Dye e farò delle copie credibili. Dirò al barone che hai cambiato bandiera, ma sappi che... ai Bloodsail non piacerà per niente!", enHash = "a35172f0", vanilla = true },
        reward = { it = "Osserviamo un minuto di silenzio per i nostri compagni caduti, $N.\n\n<Bloodsail Traitor ti sorride e ti fa l'occhiolino.>\n\nEssere un traditore è una cosa, ma ammazzare i propri compari... quello sì che sarebbe davvero spregevole, eh!", enHash = "a031e916", vanilla = true },
    },
    [9260] = {
        title = { it = "Indaga sul Flagello di Stormwind", enHash = "80aa9a5e", vanilla = true },
        text = { it = "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere Stormwind da questi invasori maledetti?\n \nFuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropolis là in alto. Hanno un significato, non ho dubbi, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai risultati delle tue indagini, e ti ricompenserò. Va'!", enHash = "8004c99b", vanilla = true },
        objectives = { it = "Raccogli tre Dim Necrotic Stone dal Flagello fuori da Stormwind e indaga sui cerchi runici luminosi vicino al suo accampamento.", enHash = "c4574ca9", vanilla = true },
        progress = { it = "Hai già indagato sull'invasione? Non c'è tempo da perdere!", enHash = "193ba187", vanilla = true },
        reward = { it = "Mmm. Da quello che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una magia simile. In ogni caso, sembri esserne $Guscito integro e sano:uscita integra e sana;. L'Argent Dawn apprezza i tuoi servigi.", enHash = "ebf7c605", vanilla = true },
    },
    [9261] = {
