    [9265] = {
        title = { it = "Indaga sul Flagello dell'Undercity", enHash = "01064ac1", vanilla = true },
        text = { it = "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere l'Undercity da questi invasori maledetti?\n \nFuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropolis là in alto. Hanno un significato, non ho dubbi, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai risultati delle tue indagini, e ti ricompenserò. Va'!", enHash = "d118363e", vanilla = true },
        objectives = { it = "Raccogli tre Dim Necrotic Stone dal Flagello fuori dall'Undercity e indaga sui cerchi runici luminosi vicino al suo accampamento.", enHash = "d4d8ef66", vanilla = true },
        progress = { it = "Hai già indagato sull'invasione? Non c'è tempo da perdere!", enHash = "193ba187", vanilla = true },
        reward = { it = "Mmm. Da quello che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una magia simile. In ogni caso, sembri esserne $Guscito integro e sano:uscita integra e sana;. L'Argent Dawn apprezza i tuoi servigi.", enHash = "ebf7c605", vanilla = true },
    },
    [9266] = {
        title = { it = "Fare ammenda", enHash = "af4d5bb9", vanilla = true },
        progress = { it = "Devi averla combinata proprio grossa a noi o ai nostri amici, $N. Comunque, sono qui per offrirti un modo di riguadagnarti le nostre simpatie.\n\nCome sai, Winterspring è piuttosto fredda. Con tanti di noi goblin che arrivano da altre città, ci farebbe comodo un aiuto per stare al caldo. Portami un po' di Runecloth e di Coal, e metterò una buona parola per te. Ma sta' $Gattento:attenta;: ai nostri nemici non piacerà che tu ci aiuti.", enHash = "1a02cd25", vanilla = true },
        reward = { it = "Grazie, $N. Sei sulla buona strada per riscattarti agli occhi della nostra bella città.", enHash = "4ad7eb78", vanilla = true },
    },
    [9267] = {
        title = { it = "Rimarginare vecchie ferite", enHash = "dbb09fa5", vanilla = true },
        progress = { it = "Faresti meglio a pensarci due volte prima di mettere piede a Ratchet, $N! Si è sparsa la voce delle tue malefatte.\n\nSei $Gfortunato:fortunata;, però: è appena arrivata una nave con molti feriti da uno scontro con i Bloodsail Buccaneers. È la tua occasione per dimostrare che non sei una canaglia fino in fondo. Dacci una mano portando Linen Cloth per le bende ed Empty Vial per le pozioni.", enHash = "f88013bf", vanilla = true },
        reward = { it = "Mi fa piacere che ti stia rendendo conto dei tuoi errori, $N. Continua a portare rifornimenti: non ci dimenticheremo di te così facilmente, $Gsignore:signorina;!", enHash = { "e13b7974", "65ba8862" }, vanilla = true },
    },
    [9272] = {
        title = { it = "Vestirsi per la parte", enHash = "367b2877", vanilla = true },
        reward = { it = "Yarrr... se ci tieni a goderti la compagnia di noi lupi di mare esperti, faresti meglio a smettere di vestirti come $Gun farabutto:una farabutta;! Tieni, mettiti qualcosa di decente prima che ti faccia passare sotto la chiglia.\n\nQuesti ti staranno meglio di quanto siano mai stati a quel vecchio cane di Red-Eyed Ben. L'abbiamo perso in mare, in una tempesta infernale.\n\nPortali con orgoglio, $Gcompagno:compagna;!", enHash = "24081aba", vanilla = true },
    },
    [9292] = {
        title = { it = "Cracked Necrotic Crystal", enHash = "a9c8aaa2", vanilla = true },
        text = { it = "Sul cadavere dell'abominio caduto trovi un cristallo incrinato, che pulsa lentamente di energia necrotica.", enHash = "966f6fc4", vanilla = true },
        objectives = { it = "Porta il Cracked Necrotic Crystal a Lieutenant Orrin, fuori dai cancelli di Stormwind.", enHash = "42093453", vanilla = true },
        progress = { it = "Ti serve qualcosa?", enHash = "ac0a93d0", vanilla = true },
        reward = { it = "Mm, l'hai preso dal cadavere di uno degli abomini invasori?\n\nAbbiamo ricevuto notizie degli accampamenti delle necropoli che il Flagello sta evocando. Sospetto che volessero crearne uno dentro Stormwind. È un bene che non ci siano riusciti.", enHash = "3f78d0a2", vanilla = true },
    },
    [9310] = {
        title = { it = "Faint Necrotic Crystal", enHash = "675aca87", vanilla = true },
        text = { it = "Sul cadavere dello spettro caduto trovi un cristallo che irradia debolmente energia necrotica.", enHash = "0b6febbe", vanilla = true },
        objectives = { it = "Porta il Faint Necrotic Crystal a Lieutenant Rukag, nel cortile dell'Undercity.", enHash = "fa859f70", vanilla = true },
        progress = { it = "Posso aiutarti in qualcosa?", enHash = "59eae766", vanilla = true },
        reward = { it = "Dici che l'hai preso da uno spettro che attaccava la città?\n\nAbbiamo ricevuto notizie degli accampamenti delle necropoli che il Flagello sta evocando. Sospetto che stessero cercando di crearne uno nell'Undercity. In futuro dovremo stare all'erta.", enHash = "ab7b9214", vanilla = true },
    },
    [9322] = {
        title = { it = "Fuochi selvaggi a Kalimdor", enHash = "fe4a58af", vanilla = true },
        text = { it = "I Fuochi di Mezza Estate si celebrano ovunque su Azeroth, e la variegata terra di Kalimdor non fa eccezione. Mi sembri in forma per viaggiare — forse è il caso di metterti in cammino.\n\nNon si può apprezzare davvero la festa di Mezza Estate se non si sono visti i roventi fuochi blu in terre lontane. I festeggianti hanno acceso fuochi nella fredda Winterspring occidentale, nel nord-est di Azshara, vicino al Valor's Rest nelle distese desolate di Silithus e all'ingresso del rigoglioso Un'Goro. Torna quando il tuo viaggio sarà concluso.", enHash = "1467b880", vanilla = true },
        objectives = { it = "Visita gli accampamenti di Mezza Estate ad Azshara, a Silithus, nell'Un'Goro Crater e a Winterspring, poi torna dal Festival Flamekeeper.", enHash = "d0e4a286", vanilla = true },
        progress = { it = "Le fiamme di Kalimdor ardono vivaci?", enHash = "8ba4f91c", vanilla = true },
        reward = { it = "Il tuo spirito risplende del calore dei fuochi di Kalimdor, $Gamico:amica;. Non trovi che questo calore ti rinvigorisca?\n\nQuando il potere ti avrà lasciato, forse questi ti aiuteranno a riaccendere quella sensazione.", enHash = "9aab929f", vanilla = true },
    },
    [9323] = {
        title = { it = "Fuochi selvaggi negli Eastern Kingdoms", enHash = "598597d5", vanilla = true },
        text = { it = "La nostra festa della fiamma si è diffusa in tutta la terra, $C. Non c'è un solo luogo che il calore di questa festa non abbia toccato, e i fuochi più forti ardono di un blu brillante. Cercali.\n\nNe troverai uno appena a nord della Blackrock Spire. Gli altri si trovano nel cuore degli Eastern Plaguelands, vicino a un paese in rovina; lungo la strada che porta alle scogliere, nelle montuose Hinterlands; e sulla via per il Dark Portal, nelle Blasted Lands.\n\nTorna quando il tuo viaggio sarà finito.", enHash = "f6e0ca1a", vanilla = true },
        objectives = { it = "Visita gli accampamenti dei Fuochi di Mezza Estate nelle Blasted Lands, negli Eastern Plaguelands, nelle Hinterlands e nella Searing Gorge, poi parla con il Festival Flamekeeper.", enHash = "9dff6c1a", vanilla = true },
        progress = { it = "Hai già percorso il continente? L'illuminazione ti attende.", enHash = "57ac6956", vanilla = true },
        reward = { it = "Ah, eccoti. Un po' più $Gstanco:stanca;, un po' più $Gimpolverato:impolverata;, ma $Gilluminato:illuminata;! In questa stagione il calore ci tocca tutti e ci unisce; tutto il tuo essere risplende del potere dei fuochi che hai toccato.\n\nAh, ma di questi tempi l'illuminazione è considerata una ricompensa piuttosto misera per chi viene mandato a svolgere un compito, immagino. Prendi questi, allora, e goditi la festa.", enHash = "c97114f0", vanilla = true },
    },
    [9367] = {
        title = { it = "I Fuochi di Mezza Estate", enHash = "84fb1406", vanilla = true },
        text = { it = "È di nuovo tempo di Mezza Estate!\n\nOgni anno, come vuole la tradizione, vengono scelti dei custodi della fiamma che si occupino dei falò delle nostre capitali. Mentre i fuochi ardono in tutta Azeroth, è indispensabile che i nostri siano i più caldi e i più luminosi, per rendere il dovuto omaggio alla stagione.\n\nAnzi, ho un compito per te, se non ti dispiace. Non ho ancora saputo se i fuochi di tutte le capitali ardono come si deve. Vacci di persona e scaldati accanto ai fuochi — assicurati che siano caldi!", enHash = "9c23ebd3", vanilla = true },
        objectives = { it = "Tocca i falò di Stormwind, Ironforge e Darnassus, poi parla con un Festival Loremaster nelle capitali.", enHash = "6ce1573e", vanilla = true },
        progress = { it = "I fuochi ardono?", enHash = "bb375f8a", vanilla = true },
        reward = { it = "Eccellente! Sembra che quest'anno abbiamo nominato custodi della fiamma coscienziosi, se i falò sono ben tenuti come dici. Grazie di averli controllati per me; ecco, prendi questo come piccolo segno della mia stima.", enHash = "c9599e77", vanilla = true },
    },
    [9368] = {
        title = { it = "I Fuochi di Mezza Estate", enHash = "84fb1406", vanilla = true },
        text = { it = "È di nuovo tempo di Mezza Estate!\n\nOgni anno, come vuole la tradizione, vengono scelti dei custodi della fiamma che si occupino dei falò delle nostre capitali. Mentre i fuochi ardono in tutta Azeroth, è indispensabile che i nostri siano i più caldi e i più luminosi, per rendere il dovuto omaggio alla stagione.\n\nAnzi, ho un compito per te, se non ti dispiace. Non ho ancora saputo se i fuochi di tutte le capitali ardono come si deve. Vacci di persona e scaldati accanto ai fuochi — assicurati che siano caldi!", enHash = "9c23ebd3", vanilla = true },
        objectives = { it = "Tocca i falò di Orgrimmar, Thunder Bluff e dell'Undercity, poi parla con un Festival Talespinner nelle capitali.", enHash = "34c90e30", vanilla = true },
        progress = { it = "Hai avuto fortuna, $N?", enHash = "6904992e", vanilla = true },
        reward = { it = "Eccellente! Sembra che quest'anno abbiamo nominato custodi della fiamma coscienziosi, se i falò sono ben tenuti come dici. Grazie di averli controllati per me; ecco, prendi questo come piccolo segno della mia stima.", enHash = "c9599e77", vanilla = true },
    },
    [9388] = {
        title = { it = "Fiamme tremolanti a Kalimdor", enHash = "8ec5c69e", vanilla = true },
        text = { it = "Oggi nel mondo ardono molte fiamme, $N. I fuochi più difficili da curare sono quelli che bruciano verdi: senza sorveglianza non restano accesi a lungo. Assicurati che i fuochi smeraldo ardano ancora su Kalimdor, per chi custodisce la nostra fiamma, eh?\n\nLi troverai vicino a Ratchet, nelle Barrens; accanto al Master's Glaive, a Darkshore; nella foresta di Ashenvale, presso il ponte vicino al Silverwing Outpost; e vicino alla strada per Windshear Crag, lungo la strada principale delle Stonetalon Mountains.", enHash = "ad8312fa", vanilla = true },
        objectives = { it = "Visita i falò di Ashenvale, delle Barrens, di Darkshore e delle Stonetalon Mountains, poi parla con il Festival Flamekeeper.", enHash = "e9530380", vanilla = true },
        progress = { it = "I fuochi non devono spegnersi finché la festa non è finita!", enHash = "7bae27f5", vanilla = true },
        reward = { it = "Ahhh, allora ardono ancora. Mi fa piacere: non andrebbe bene che quei fuochi si spegnessero prima del tempo. Hai fatto un buon lavoro, $N. Prendi questo, con la mia benedizione.", enHash = "702046d7", vanilla = true },
    },
    [9389] = {
        title = { it = "Fiamme tremolanti negli Eastern Kingdoms", enHash = "7f989744", vanilla = true },
        text = { it = "Per tradizione, i Fuochi di Mezza Estate illuminano la terra con una miriade di fiamme. Qualcuno sostiene che i fuochi verdi siano i più belli, perché sono i più difficili da mantenere e hanno una tinta così particolare.\n\nAssicurati che ardano ancora negli Eastern Kingdoms, per chi custodisce la nostra fiamma. Si trovano vicino a Dun Modr, nelle Wetlands; accanto a Pyrewood Village, nella Silverpine Forest; sulle scogliere che dominano il faro, a Westfall; e presso la torre in rovina, nelle Hillsbrad Foothills.", enHash = "9288e442", vanilla = true },
        objectives = { it = "Visita i falò delle Hillsbrad Foothills, della Silverpine Forest, di Westfall e delle Wetlands, poi parla con il Festival Flamekeeper.", enHash = "e866d5a1", vanilla = true },
        progress = { it = "Hai svolto il tuo compito?", enHash = "3e3ac666", vanilla = true },
        reward = { it = "Allora sei $Gtornato:tornata;, e hai controllato le fiamme smeraldo del continente. Che ne pensi, mm? Uno spettacolo raro e meraviglioso, di sicuro. So bene, però, che le ricompense concrete sono più apprezzate... quindi, ti prego, prendi questo per il disturbo.", enHash = "fd19b9a5", vanilla = true },
    },
    [9415] = {
        title = { it = "Presentati a Marshal Bluewall", enHash = "4eca8d7f", vanilla = true },
        text = { it = "Sei una delle nuove reclute di Marshal Bluewall? Certo che lo sei.\n\nCosa aspetti? Dei bravi soldati stanno morendo nel deserto. Non sei entusiasta di unirti a loro?\n\nOra muoviti, e cerca di non disidratarti per strada.", enHash = "c917e191", vanilla = true },
        objectives = { it = "Parla con Marshal Bluewall all'accampamento dell'Alleanza vicino a Hive'Zora.", enHash = "30f307ae", vanilla = true },
        reward = { it = "All'Alleanza serve ogni persona valida che riesce a trovare. L'Orda riceve un flusso costante di rinforzi dalla parte settentrionale del continente, ed è una fatica tenere il passo.\n\nLascia che ti spieghi la situazione.", enHash = "850d6e3a", vanilla = true },
    },
    [9416] = {
        title = { it = "Presentati a General Kirika", enHash = "78b7eabc", vanilla = true },
        text = { it = "Devi essere una delle nuove reclute di General Kirika. Era ora che arrivassi. Nel deserto i corpi si consumano in fretta.\n\nI nani ricevono rinforzi ogni giorno, e non possiamo permetterci di perdere terreno nella nostra lotta per le risorse di Silithus.\n\nFatti dare le istruzioni dal generale. Il mio compito non è addestrarti, solo trovarti.", enHash = "b3cf71ad", vanilla = true },
        objectives = { it = "Parla con General Kirika all'accampamento dell'Orda vicino a Hive'Regal.", enHash = "14b95307", vanilla = true },
        reward = { it = "È un bene che tu sia qui, ma non c'è tempo da perdere in chiacchiere. Ti servono istruzioni, e poi devi andare là fuori.\n\nAscolta bene.", enHash = "491a5080", vanilla = true },
    },
    [9419] = {
        title = { it = "Setacciare il deserto", enHash = "886bdf9e", vanilla = true },
        text = { it = "Da poco abbiamo scoperto che l'Orda sta setacciando il deserto di Silithus in cerca di risorse, ma non ci abbiamo fatto molto caso. Pensavamo che non valesse la pena di stanziare molti uomini in questo deserto torrido.\n\nPoi però si è scoperta l'importanza di quelle risorse, e ora ci stiamo affannando per recuperare il ritardo.\n\nSe posso contare sul tuo aiuto, devi andare nel deserto, recuperare il Silithyst e riportarlo qui.", enHash = "95181179", vanilla = true },
        objectives = { it = "Trova Silithyst e consegnalo al Silithyst Extractor, poi parla con Marshal Bluewall all'accampamento dell'Alleanza vicino a Hive'Zora.", enHash = "e29bb602", vanilla = true },
        progress = { it = "Fai attenzione là fuori, ma sbrigati. Non abbiamo tempo da perdere.", enHash = "f5563af5", vanilla = true },
        reward = { it = "Sia ringraziata la Luce, ce l'hai fatta.\n\nSe solo avessimo cominciato prima, il nostro bisogno non sarebbe così disperato. Dobbiamo impedire che le ricchezze del deserto cadano nelle mani dell'Orda.", enHash = "29ef2cf9", vanilla = true },
    },
    [9422] = {
        title = { it = "Setacciare il deserto", enHash = "886bdf9e", vanilla = true },
        text = { it = "Da un po' di tempo sfruttiamo le risorse cristalline del deserto di Silithus. Gli unici pericoli che affrontavamo erano le creature che hanno fatto di questo posto la loro casa, e la sabbia, la polvere e il caldo opprimenti.\n\nMa ora sembra che l'Alleanza si sia accorta di quello che abbiamo trovato qui. Adesso è una corsa tra noi e loro per accaparrarci le risorse naturali e tenerle lontane dagli altri.\n\nMi serve ogni paio di mani disponibile. Spero di poter contare sulle tue.", enHash = "3a4d4fbf", vanilla = true },
        objectives = { it = "Trova Silithyst e consegnalo al Silithyst Extractor, poi parla con General Kirika all'accampamento dell'Orda vicino a Hive'Regal.", enHash = "bbe047c5", vanilla = true },
        progress = { it = "Stai in guardia contro i pericoli del deserto, $N. Con l'Alleanza in agguato tra le dune, ogni passo potrebbe essere l'ultimo.", enHash = "a139f8c5", vanilla = true },
        reward = { it = "Hai fatto bene, $N. Queste risorse si aggiungeranno alle nostre scorte, e ogni briciola è un guadagno per noi e una perdita per il nemico.", enHash = "b2111063", vanilla = true },
    },
    [86784] = {
        title = { it = "Legna e ossa", enHash = "469344a9" },
        text = { it = "La mia collega Eleanor Shackleton va fiera di girare per le terre selvagge, sopravvivendo alle intemperie e ai mostri. Al momento è accampata non lontano da qui, sulle colline a ovest, e mi ricordo di un consiglio che mi ha dato una volta: \"Quando pensi di avere abbastanza legna da ardere, raccogline cinque volte tanto.\"\n\nSe hai un po' di tempo libero, potresti raccogliere un po' di legna in questo cesto e portarla al suo accampamento. Sono sicuro che potrà darti qualche consiglio sulla vita di un avventuriero girovago.", enHash = "845a73c3" },
        objectives = { it = "Raccogli 6 Dry Branch e portali a Eleanor Shackleton.", enHash = "07888683" },
    },
    [87288] = {
        title = { it = "Morbide pellicce di nightsaber", enHash = "4eb05981" },
        text = { it = "Ciao, $Gviaggiatore:viaggiatrice;! Spero che la visita al nostro villaggio ti stia piacendo. Dolanaar mi piace perché è un posto piccolo e rustico, e sono tutti cordiali.\n\nSono commerciante qui in zona, e porto ogni sorta di attrezzi e ninnoli che potrebbero esserti utili nei tuoi viaggi. Anzi, se ti interessa uno scambio, mi servirebbero delle pellicce di nightsaber. Queste maestose creature sono bellissime, ma quelle della zona sono piuttosto aggressive, quindi non sentirti troppo in colpa se devi difenderti.", enHash = "3f9e5d03" },
        objectives = { it = "Porta 6 Soft Nightsaber Pelt ad Aldria.", enHash = "54c90f3b" },
    },
    [90902] = {
        title = { it = "Riscoprire la Luce", enHash = "7e7b444d" },
        text = { it = "È un orgoglio per me accogliere tra le nostre file $Gun altro:un'altra; $C appena $Grisorto:risorta;. Mentre riprendi contatto con la Luce, potresti notare che certe abilità, un tempo per te naturali, ora possono causarti un dolore notevole, soprattutto quelle che incanalano la Luce per curare $Gte stesso:te stessa; o gli altri.\n\nL'unico modo per superare questo problema è, purtroppo, affrontarlo. Come ogni altro muscolo atrofizzato, devi spingerti oltre il dolore ed esercitare la carne perché torni a funzionare del tutto.", enHash = "49ecf23c" },
        objectives = { it = "Cura 5 Injured Deathguard con l'abilità Holy Light.", enHash = "6eab71fa" },
        progress = { it = "La padronanza della Luce tornerà, col tempo.", enHash = "bdaa62df" },
        reward = { it = "Il dolore non è una novità per chi ha sopportato la morte, e per questo i Reietti lo reggono particolarmente bene. Il dolore ha anche un potere purificatore, che dovresti accogliere come un segno d'onore e come la prova che sei ancora, a tutti gli effetti, $Gun servitore:una servitrice; della Luce, nonostante la tua nuova condizione.\n\nStammi bene, e cammina di nuovo nella Luce, $C.", enHash = "c7cc6d62" },
    },
    [91208] = {
        title = { it = "Accettare la realtà", enHash = "7013b221" },
        text = { it = "Non tutti i nostri confratelli paladini che risorgono si abituano in fretta alla nostra nuova realtà. Alcuni fanno fatica ad accettare di essere diventati, in un certo senso, proprio ciò che hanno combattuto per tutta la vita.\n\nSpesso a queste persone basta un gesto gentile e qualcuno disposto ad ascoltarle. Purtroppo, molti altri diventano presto violenti. Trova $Gil:la; $C $Gspaventato:spaventata; che è $Gfuggito:fuggita; sulle colline subito a ovest di questa cappella. $GTendigli:Tendile; una mano in amicizia. $GRiportalo:Riportala; alla Luce, se puoi.", enHash = "99041759" },
        objectives = { it = "Trova la Frightened Paladin a Deathknell.", enHash = "0dde233a" },
        progress = { it = "Accettare questa nuova vita non è facile per nessuno di noi. Per alcuni è semplicemente più di quanto riescano a sopportare.", enHash = "86aba6d6" },
        reward = { it = "Purtroppo, non sono pochi i nostri fratelli e sorelle che, dopo essere risorti, cadono in una follia simile. Per quanto ogni anima dei Reietti sia preziosa, a volte il meglio che possiamo fare è concedere una fine rapida a chi non riesce ad adattarsi.\n\nDirò una preghiera alla Luce per lei. Grazie per aver fatto ciò che andava fatto, $N.", enHash = "43ec42ae" },
    },
    [91209] = {
        title = { it = "Continua il tuo addestramento", enHash = "005c726e" },
        text = { it = "Lordaeron non sarà più quello di un tempo, ma la nostra casa ha ancora bisogno di protezione da ogni genere di minaccia, ed è ora che tu vada ad affrontare il mondo. La tua prossima tappa dovrebbe essere la cittadina di Brill, al centro delle Tirisfal Glades. Vai a incontrare Shari Stilwell: potrà seguirti nel resto del tuo addestramento.\n\nUn ultimo consiglio prima che tu parta: fai molta attenzione, perché sei $Gun:una; $C che viaggia nelle terre dei Reietti. Molti al servizio della Signora Oscura diffidano di noi e della nostra vicinanza alla Luce.", enHash = "72797450" },
        objectives = { it = "Segui la strada verso est fuori da Deathknell per trovare la cittadina di Brill. Presentati a Shari Stilwell per continuare il tuo addestramento.", enHash = "403ddaf0" },
    },
    [91282] = {
        title = { it = "Una seconda casa", enHash = "622f6bcc" },
        text = { it = "È incoraggiante vedere i miei fratelli e le mie sorelle appena risorti prosperare come hai fatto tu. Però è solo attraverso la comunità e la fede condivisa che possiamo davvero esprimere tutto il nostro potenziale, e per questo abbiamo cominciato a formare un nuovo ordine per chi è $C, proprio qui a Tirisfal.\n\nSe vuoi saperne di più, dovresti visitare il nostro monastero a Northface Rock. Si chiama Bandarion Keep. È sulle scogliere appena a nord-ovest della Solliden Farmstead, e non dovrebbe essere difficile trovarlo.", enHash = "bd6fb145" },
        objectives = { it = "Trova la fortezza di Bandarion Keep e fai rapporto a Breton Samuels.", enHash = "be265694" },
    },
    [91723] = {
        title = { it = "Strumenti delicati", enHash = "651883d9" },
        text = { it = "Maledizione! Ogni volta che provo a calibrare questi delicati strumenti arcani, un'ondata di energia li fa sballare di nuovo.\nLe ondate sembrano arrivare da nord, dove quei kobold primitivi praticano la loro rozza magia. Potresti sgombrarne un po', così posso continuare il mio lavoro?", enHash = "b07e83d9" },
        objectives = { it = "Uccidi 8 Kobold Geomancer nella Jasperlode Mine, poi torna da Hamish Bergwort, nella Tower of Azora.", enHash = "a22174f3" },
    },
    [91725] = {
        title = { it = "Stolen Enchanting Supplies", enHash = "ea954eab" },
        text = { it = "Master Theocritus mi ha mandato a ritirare delle provviste per incantamento all'emporio, ma sulla via del ritorno mi ha teso un agguato un branco di gnoll!\n\nHo lasciato cadere il pacco e sono scappata, ma se torno senza, per punizione dovrò pulire dopo gli esperimenti di metamorfosi per settimane! Pensi di poter ritrovare le provviste per me?", enHash = "ed0c03d7" },
        objectives = { it = "Raccogli 5 Stolen Enchanting Supplies negli accampamenti degli gnoll intorno allo Stone Cairn Lake, poi torna da Blixie Fitzwink, vicino alla Tower of Azora.", enHash = "2a336de7" },
    },
    [91732] = {
        title = { it = "Acciaio buono", enHash = "84f024a8" },
        text = { it = "Dopo la guerra l'acciaio buono scarseggia, e i nostri attrezzi ne hanno risentito. I minatori della Jasperlode usavano picconi di ottima fattura, e immagino che alcuni siano ancora laggiù, nelle profondità della miniera. Potresti recuperarne qualcuno per me? Vedrò se riesco a riutilizzare l'acciaio.", enHash = "33863d3a" },
        objectives = { it = "Raccogli 4 Mining Tools nella Jasperlode Mine, poi torna da Hagar Lowe, all'Eastvale Logging Camp.", enHash = "bc572553" },
    },
    [91733] = {
        title = { it = "Giù per la corrente", enHash = "85caf2a2" },
        text = { it = "Stavo riportando un carico di provviste dall'emporio, ma il mio carro si è ribaltato e le provviste sono cadute nel fiume! Prima che riuscissi a prenderle, la corrente se le era già portate a valle.\nCon i murloc e i lupi che ci sono laggiù, da solo non ho nessuna speranza di recuperarle. Tu sembri una persona robusta: pensi di poterle ritrovare per me?", enHash = "4a989977" },
        objectives = { it = "Raccogli la Waterlogged Axe, la Waterlogged Saw e la Waterlogged Toolbox che la corrente ha portato a valle dall'Eastvale Logging Camp, poi torna da Ormin Pelford.", enHash = "8dd0b7ae" },
    },
    [91741] = {
        title = { it = "Nibbled-On Book", enHash = "8ca860ad" },
        text = { it = "<Uno dei kobold ha lasciato cadere questo libro. Sembra che il kobold abbia provato a mangiarlo.\n\nBrother Paxton, nell'abbazia, si occupa di una piccola biblioteca. Il libro deve venire da lì.>", enHash = "60ba3cf5" },
        objectives = { it = "Riporta il libro a Brother Paxton.", enHash = "32ff5855" },
        progress = { it = "Cos'hai lì? Sembra uno dei miei libri.", enHash = "1631a638" },
        reward = { it = "Ehi! Come ti è capitato tra le mani? Dovrebbe stare sullo scaffale! Povero me, i kobold mi hanno rubato di nuovo i libri. Devono volerli mangiare!\n\nGrazie per avermi riportato il libro, ma come faccio con il resto della mia collezione scomparsa?", enHash = "9a5027ec" },
    },
    [91743] = {
        title = { it = "Roditori dispettosi", enHash = "5e4b1846" },
        text = { it = "Quegli orribili kobold si stanno mangiando i miei libri! Devi recuperarli prima che divorino tutta la mia biblioteca.", enHash = "5487a6e8" },
        objectives = { it = "Recupera 8 Stolen Book dai kobold della Northshire Valley e riportali a Brother Paxton.", enHash = "47907fcf" },
        progress = { it = "Hai già salvato i miei libri, $N?!", enHash = "007a53a6" },
        reward = { it = "Grazie mille! Tieni! Prendi uno di questi manuali pratici. A me non servono.\n\nMa mancano ancora tanti libri. I kobold non sembrano mangiarli. E allora, perché li vogliono?", enHash = "294e42b9" },
    },
    [91745] = {
        title = { it = "Consulente minerario", enHash = "44d3744b" },
        text = { it = "Va' a parlare con la nuova apprendista minatrice, Kelsey Fargo. Lavora proprio fuori dalla miniera, e probabilmente ha visto cosa combinano i kobold. Magari, già che ci sei, può insegnarti un paio di cose sull'estrazione.", enHash = "73478e01" },
        objectives = { it = "Parla con Kelsey Fargo fuori dall'Echo Ridge Mine, nella Northshire Valley.", enHash = "27c07f4a" },
        reward = { it = "Kobold con dei libri? Già, ho visto dei kobold correre avanti e indietro con dei libri, urlandosi addosso. Devono rubarli dalla biblioteca dentro l'abbazia.", enHash = "059170a4" },
    },
    [91752] = {
        title = { it = "Il quadro d'insieme", enHash = "3c56c0af" },
        text = { it = "Ogni tanto passa un kobold che urla \"Figure per Narf!\" Non so chi sia Narf. Forse uno dei capi kobold in fondo alla miniera? Scommetto che ormai ha un sacco pieno di libri.\n\nVa' a prendere quei libri e portali al nostro tutore dell'ordine, Marshal McBride. Faresti bene a trovarti qualcuno che ti aiuti: i kobold dentro la miniera sono molto più cattivi.", enHash = "ccd7eb7a" },
        objectives = { it = "Recupera il Sack of \"Picture\" Books da Shinyfinder Narf. Porta il sacco a Marshal McBride, appena dentro la Northshire's Abbey.", enHash = "4d1717cd" },
        progress = { it = "Hai già recuperato quei libri rubati?", enHash = "f9d66862" },
        reward = { it = "Grazie per aver riportato questi libri rubati, $N. Li restituirò subito a Brother Paxton.\n\nQui intorno stai diventando proprio $Gun eroe:un'eroina;. Ottimo lavoro!", enHash = "50dc072c" },
    },
    [91758] = {
        title = { it = "Segui quel kobold!", enHash = "b694f5ee" },
        text = { it = "Con quei kobold non hai ancora finito. Ci è appena arrivata voce da Kelsey che un kobold ha lasciato la miniera portando un grosso sacco di libri. Devo chiederti di rintracciare questo kobold, così possiamo recuperare i libri per Brother Paxton.\n\nVa' a parlare con Tordrin Sternblade. È il nuovo istruttore dei cacciatori, appena arrivato da Ironforge. Lo trovi dietro l'abbazia, vicino alla stalla. Può aiutarti a rintracciare questo kobold ladro.", enHash = "8ec6e146" },
        objectives = { it = "Parla con Tordrin Sternblade, vicino alla stalla dietro la Northshire's Abbey.", enHash = "b079705e" },
        reward = { it = "Posso aiutarti a scovare 'sta canaglia. Lascia che ti prepari qualcosa.", enHash = "058aabff" },
    },
    [91772] = {
        title = { it = "Ssst! Stiamo cacciando kobold", enHash = "56c55271" },
        text = { it = "Bene. Prendi questo kit per seguire le tracce dei kobold. Ti permetterà di seguire il kobold che preoccupa Marshal McBride.\n\nSegui le tracce e porta quello che trovi a Marshal Dughan, a Goldshire.\n\nHo la sensazione che 'ste canaglie stiano combinando qualcosa fuori da Northshire. Quindi ti servirà l'aiuto di Dughan.", enHash = "a6308bda" },
        objectives = { it = "Segui le tracce del kobold e fai rapporto a Marshal Dughan, a Goldshire, con le tue scoperte e il Kobold Tracking Kit.", enHash = "7f1b244f" },
        progress = { it = "Hai scoperto dove sono diretti i kobold?", enHash = "75cbce72" },
        reward = { it = "Cos'è questo, $N? Seguire le tracce dei kobold?\n\nBe', è ovvio che sono diretti alla Fargodeep Mine! Quel posto è infestato dai kobold.\n\nBel lavoro, direi. Mi servirà qualcuno che si occupi di quel problema.", enHash = "5efc7a05" },
    },
    [91775] = {
        title = { it = "Restituzione dei libri", enHash = "05440247" },
        text = { it = "Mentre indaghi nella Fargodeep Mine, vedi se riesci a trovare qualcuno dei libri di Brother Paxton da restituire. In particolare, Paxton è molto preoccupato per un libro intitolato \"Fun with Elementals\". Pensa che perfino un kobold potrebbe usarlo per evocare un servitore elementale. Sta' $Gattento:attenta;: le profondità della miniera sono piuttosto pericolose. Faresti bene a portarti degli amici.\n\nPrendi questa borsa per i libri, così li proteggi quando li trovi!", enHash = "9810e42c" },
        objectives = { it = "Trova 6 Lost Book e \"Fun with Elementals\" e riportali a Marshal Dughan.", enHash = "c46654d0" },
        progress = { it = "Hai già trovato tutti i libri?", enHash = "064de372" },
        reward = { it = "Mi congratulo per la tua diligenza, $N. Brother Paxton ha mandato un elenco dei libri, e tu hai trovato quasi tutti quelli che mancavano. Gli altri devono essere stati portati nella Jasperlode Mine.\n\nPuoi tenerti quella borsa per i libri!", enHash = "ebcab14f" },
    },
    [91777] = {
        title = { it = "Libri rari", enHash = "53f201ac" },
        text = { it = "Dall'elenco di Brother Paxton mancano solo due libri: \"Geomancy for Curious Young Wizards\" e \"Arcane Explainer: Magical Stuff in Simple Words\".\n\nI kobold devono averli portati nella Jasperlode Mine. Ti prego, rintraccia quei due libri e riportali a Brother Paxton.\n\nMa temo che sarà parecchio pericoloso. Se il kobold \"apprendista\" evocava un elementale, chissà cosa può fare il maestro. Se fossi in te, mi porterei degli amici.", enHash = "c3719bd9" },
        objectives = { it = "Recupera \"Geomancy for Curious Young Wizards\" e \"Arcane Explainer: Magical Stuff in Simple Words\" e riportali a Brother Paxton, dentro la Northshire's Abbey.", enHash = "2b39201a" },
        progress = { it = "Hai già trovato tutti i miei libri scomparsi?", enHash = "0ff398e5" },
        reward = { it = "Oh, $N! Grazie mille per aver salvato la mia biblioteca. Mi hai reso un servizio straordinario. Prendi pure una di queste belle armi. Erano destinate alla milizia, ma tu puoi farne un uso migliore.", enHash = "490620f7" },
    },
    [92124] = {
        title = { it = "Inventario dei libri", enHash = "8412a8e5" },
        text = { it = "Dobbiamo capire quanti libri mancano!\n\nVai a parlare con Daniel, quell'inutile del mio assistente. Può fare un rapido inventario e dirci quanto è grave il problema.\n\nÈ fissato con le varie professioni di Elwynn Forest. Quel ragazzo continua a pensare a quelle invece che al suo lavoro importante, cioè aiutare me.\n\nNon lasciare che si metta a chiacchierare di professioni, e scopri che fine hanno fatto i miei libri!", enHash = "8d40d479" },
        objectives = { it = "Parla con Daniel, l'assistente di Brother Paxton, nella biblioteca.", enHash = "228ea9bd" },
        reward = { it = "Già, ho sentito. Avevo avvertito Brother Paxton tre volte dei kobold che scavavano gallerie sotto l'abbazia.\n\nSembra che i kobold si siano presi un sacco di libri. Ci sono scaffali interi svuotati. Forse dovresti chiedere a Brother Paxton cosa vuole che tu faccia.\n\nGià che sei qui, posso parlarti delle professioni? Sarei felice di rispondere alle tue domande, o di indicarti gli istruttori della zona.", enHash = "ec6bea32" },
    },
    [92460] = {
        title = { it = "L'età adulta", enHash = "0b113175" },
        text = { it = "Ma guardati, con gli occhi che brillano e $Gpronto:pronta; all'avventura! Aspettavamo il tuo arrivo: qui a Thendal Village abbiamo proprio bisogno del tuo aiuto. Immagino che tu sia tra l'agitazione e l'entusiasmo per quello che ti aspetta. Del resto, si diventa adulti una volta sola nella vita.\n\n<Ailee sorride con gentilezza.>\n\nVa', cerca il capo del nostro villaggio, Rorian the Dayseeker, all'ingresso dell'albero del grande padre, poco a ovest di qui. Sarà lui ad avviarti nel tuo viaggio.", enHash = "dd65d8a4" },
        objectives = { it = "Parla con Rorian the Dayseeker a Thendal Grove.", enHash = "ed646ba3" },
        reward = { it = "Che il vento ti saluti, $N. È un onore per me consegnarti oggi la reliquia del passaggio all'età adulta, nel giorno in cui gli shen'dorei riconoscono il potenziale che porti con te. Nel corso della sua complessa storia, il nostro popolo ha affrontato grandi sofferenze e persecuzioni.\n\nOggi ricevi questa reliquia, una delle molte custodite da chi ti ha preceduto. Un giorno, quando le tue ceneri saranno disperse nei venti, passerà a un altro perché la nostra tradizione continui.\n\nMentre la porti con te, sappi che i venti di casa ti accompagneranno ovunque andrai.", enHash = "54e36671" },
    },
    [92461] = {
        title = { it = "Armonia nell'equilibrio", enHash = "9b7be23b" },
        text = { it = "Viviamo tempi di grande incertezza per il nostro popolo. Affrontiamo sfide senza precedenti che potrebbero richiedere soluzioni audaci, ma dobbiamo occuparci anche dell'ordinario e del banale, qui a Thendal Grove. Prendi, per esempio, il recente aumento insostenibile della popolazione di vuldren.\n\nI vuldren sono una parte vitale del nostro ecosistema. Gli squilibri, però, vanno corretti per mantenere la delicata armonia che tutte le creature di Thendal Grove condividono.\n\nVa' a est e abbattine un po'.", enHash = "72064069" },
        objectives = { it = "Uccidi 8 Vuldren Juvenile a Thendal Grove.", enHash = "9de1fc36" },
        progress = { it = "Per quanto sia sgradevole dover abbattere creature vive, serve una mano che guidi così, per evitare un disastro nella nostra terra. È una lezione importante da imparare, per chi è come te.", enHash = "8d2d3d21" },
        reward = { it = "Grazie per i tuoi servigi a Zephras, giovane $C.\n\nDi solito i vuldren sono piuttosto docili, ma gli animali che vivono a Zephras sentono quando la magia portata dai venti perde l'equilibrio, e questo, se nessuno interviene, può portare a comportamenti pericolosi e imprevedibili.", enHash = "5cf4738e" },
    },
    [92462] = {
        title = { it = "Indagine sull'infestazione", enHash = "b59d56f2" },
        text = { it = "Uno dei nostri ranger ha segnalato di recente un'infestazione di cirrusfly qui a Thendal Grove.\n\nI cirrusfly possono essere pericolosi se lo sciame diventa troppo grande, quindi ti prego, va' all'estremità orientale del Grove e sterminane quanti più puoi.", enHash = "80e056f1" },
        objectives = { it = "Uccidi 8 Pesky Cirrusfly a Thendal Grove.", enHash = "fb243486" },
        progress = { it = "Non possiamo permettere che simili parassiti mettano radici nel nostro tranquillo boschetto. Un'infestazione può diventare pericolosa in fretta, se nessuno interviene.", enHash = "056e6afb" },
        reward = { it = "A giudicare da tutte le interiora di insetto che hai addosso, dev'essere proprio una bella infestazione.", enHash = "011ad470" },
    },
    [92463] = {
        title = { it = "La Cirrusfly Queen", enHash = "06a1a5ca" },
        text = { it = "Se la foresta è davvero così piena di questi insetti, uccidere le operaie non basterà.\n\nAddentrati nella foresta e trova la regina. Sarà vicino all'alveare, circondata da soldati più grossi e più aggressivi, quindi fa' attenzione.\n\nAbbattila e torna qui quando hai finito. Sarà un problema in meno a cui pensare, da queste parti.", enHash = "a9b4cddc" },
        objectives = { it = "Distruggi la Cirrusfly Queen a Thendal Grove.", enHash = "20f75f68" },
        progress = { it = "I cirrusfly non vanno sottovalutati. Forse non sembrano pericolosi, ma devi fare attenzione a quelli più grossi. Più sono grossi, più sono cattivi!", enHash = "ab992c36" },
        reward = { it = "Ottimo lavoro, $N. Saresti $Gun ottimo:un'ottima; ranger, se questa storia $Gdell'\"avventuriero\":dell'\"avventuriera\"; non dovesse funzionare.", enHash = "c12b7044" },
    },
    [92464] = {
        title = { it = "Inquietudine elementale", enHash = "b1a8d806" },
        text = { it = "Da quando i nostri benefattori elementali ci hanno lasciato, sembra che passiamo da un'agitazione all'altra. Il problema che abbiamo ora è che le manifestazioni dei venti vicino alle pietre erette a nord-est sono agitate.\n\nNon hanno una vera coscienza di sé come gli spiriti del vento senzienti che un tempo vivevano qui: questi semplici folletti rispondono allo stesso modo alle forze, alle emozioni e alle intenzioni delle creature intorno a loro.\n\nLa mia apprendista Yala Windwatcher è andata a osservarli. Cercala e scopri che cosa ha capito.", enHash = "d7f9a8b3" },
        objectives = { it = "Parla con Yala Windwatcher a Thendal Grove.", enHash = "cad39d9b" },
        reward = { it = "Ti manda Rorian? Bene. Il tuo aiuto mi farebbe comodo.", enHash = "de47eaaa" },
    },
    [92465] = {
        title = { it = "Agitatori", enHash = "7774e4ac" },
        text = { it = "Il culto degli Al'Aketh è una piaga per quest'isola. Questi cultisti sono di sicuro i responsabili: sono loro che agitano i semplici folletti del vento che vivono qui e li rendono violenti.\n\nPurtroppo dovremo disperdere questi venti turbinanti prima che facciano del male a qualcuno. Dobbiamo anche mandare al culto un messaggio chiaro: nel boschetto non sono i benvenuti.\n\nMi darai il tuo aiuto, $C?", enHash = "77767ad0" },
        objectives = { it = "Uccidi 6 Roiling Wind e 7 Al'Aketh Convert a Thendal Grove.", enHash = "a41c2313" },
        progress = { it = "È fatta?", enHash = "2757a3fe" },
        reward = { it = "Mi addolora versare sangue shen'dorei qui nel boschetto, ma facciamo ciò che dobbiamo.", enHash = "89ba0f2d" },
    },
    [92469] = {
        title = { it = "Torna da Rorian", enHash = "d0bbdeb6" },
        text = { it = "Qui hai fatto abbastanza, $C. Io resto a ripulire gli ultimi sbandati laggiù.\n\nTorna al villaggio e riferisci a Rorian della presenza del culto. Non ne sarà contento.", enHash = "f481c086" },
        objectives = { it = "Porta notizie degli Al'Aketh a Rorian the Dayseeker, a Thendal Grove.", enHash = "ddb6b43f" },
        reward = { it = "È molto preoccupante, ma purtroppo non sorprende. Seguiamo i movimenti del culto da tempo, ma ci siamo accontentati di osservarli da lontano. Aizzare gli spiriti del vento vicino alle pietre erette è un chiaro passo avanti da parte loro.\n\nHai reso a Thendal Grove un servizio difficile ma necessario, $N. Grazie.", enHash = "34b0c0f5" },
    },
    [92470] = {
        title = { it = "Matriarca immonda", enHash = "854e516d" },
        text = { it = "Rorian ti ha detto che ti tenevo d'occhio. Ora ti offro una prova di determinazione. Ma sei $Gavvisato:avvisata;: ti porterà in grave pericolo.\n\nVa' nelle grotte a sud. Sfoltisci il numero degli ursera che ci vivono, e trova la loro matriarca, quella che i ranger chiamano \"Urs'anah\". Abbattila e portami una prova della sua morte. Quando l'avrai fatto, avrai compiuto un passo importante sul tuo cammino.", enHash = "a020e78d" },
        objectives = { it = "Uccidi 8 Ursera Scavenger e raccogli la testa della madre della tana, Urs'anah, a Thendal Grove.", enHash = "d4813f21" },
        progress = { it = "Quello che ti chiedo non è facile, ma devi essere $Gpronto:pronta; a sfide molto più grandi, se vuoi sopravvivere abbastanza a lungo da servire Zephras Isle.", enHash = "c291eed2" },
        reward = { it = "Ben fatto davvero. Hai abbattuto bestie e sconfitto intrusi del culto. Sei molto promettente, ma presto il tuo cammino dovrà portarti oltre la relativa sicurezza di Thendal Village.", enHash = "e26fdcdb" },
    },
    [92471] = {
        title = { it = "Aetheen of the Gales", enHash = "bf8c9432" },
        text = { it = "Forse non te ne rendi conto, ma tutto quello che hai fatto è stato una specie di prova. Una prova per ciò che ti aspetta. Là fuori c'è una grande isola, e Zephras ha bisogno di giovani avventurieri pieni di spirito come te, se vogliamo sopravvivere alle prove che il nostro popolo deve affrontare.\n\nQuella che chiamano Aetheen of the Gales è una delle guide del nostro popolo qui a Zephras Isle, e ti ha tenuto d'occhio. Ha un compito che devi portare a termine. Parla con lei per saperne di più.", enHash = "2f6dfdce" },
        objectives = { it = "Parla con Aetheen of the Gales, a Thendal Grove.", enHash = "7a8dd8c2" },
        reward = { it = "Rorian mi ha parlato molto di te. Probabilmente non mi conosci, ma sono un membro del Council of Elders qui a Zephras Isle. Sono venuta a leggere il flusso dei venti qui a Thendal Grove. Sono anche qui per valutare i giovani shen'dorei come te che raggiungono l'età adulta.\n\nAllora dimmi, sei $Gpronto:pronta; a fare il passo successivo? Sei $Gpronto:pronta; a servire Zephras Isle?", enHash = "32dd8feb" },
    },
    [92472] = {
        title = { it = "Il passo successivo", enHash = "c00816ea" },
        text = { it = "Una delle minacce più diffuse a Zephras Isle è il culto degli Al'Aketh. Sono fanatici religiosi votati al culto del presunto sovrano elementale di Skywall, Al'Akir the Windlord. Sono brutali, ossessionati da un unico scopo, e il loro potere e le loro ambizioni si fanno ogni giorno più letali.\n\nPresto il tuo cammino ti porterà a Shen'dar Village, a sud. Quando arrivi, presentati a Constable Aonda. Il culto minaccia Shen'dar, e il villaggio ha bisogno di aiuto. Di' ad Aonda che ti mando io.", enHash = "95938db1" },
        objectives = { it = "Fai rapporto a Constable Aonda, a Shen'dar Village.", enHash = "4ed6cfba" },
        reward = { it = "Ti manda Aetheen, dunque? Lo confesso, a me non sembri granché, ma Shen'dar Village non rifiuta un aiuto volenteroso, tanto meno un aiuto mandato da Elder Aetheen in persona.", enHash = "34baf22f" },
    },
    [92473] = {
        title = { it = "Invasione aggressiva", enHash = "46142509" },
        text = { it = "La tana degli ursera a sud-ovest sta diventando in fretta un problema. Proprio la settimana scorsa i ranger hanno dovuto uccidere un giovane ursera che si era avvicinato troppo al villaggio e aveva cercato di attaccare un bambino che giocava ai piedi dell'albero antico, al centro del villaggio.\n\nPer fortuna il bambino se l'è cavata. La fame e la disperazione rendono queste bestie troppo pericolose per lasciarle fare. Va' a sud e abbatti i più macilenti tra gli ursera. Quando hai finito, portami i loro artigli come prova.", enHash = "50aebf05" },
        objectives = { it = "Raccogli 6 Scrawny Ursera Claw dagli Scrawny Ursera a Thendal Grove.", enHash = "fe00c6c4" },
        progress = { it = "Ultimamente gli ursera sono diventati molto più aggressivi. Mi chiedo cosa sia cambiato per provocare questo cambiamento di comportamento.", enHash = "367d5ef3" },
        reward = { it = "Ben fatto, $C. I Rangers of the Grove ti sono debitori.", enHash = "82f7f942" },
    },
    [92474] = {
        title = { it = "Cadere con stile", enHash = "f4d7b910" },
        text = { it = "Ma ciao, $N! Vuoi fare un gioco?\n\nDevi solo salire su quella sporgenza... e poi saltare! Usa la tua capacità innata di camminare sull'aria per rallentare la caduta, e vedi fin dove riesci a planare in avanti.\n\nLe regole sono inventate e i punti non contano, ma prendi punti bonus se riesci ad atterrare proprio davanti a Rorian the Dayseeker e a fargli prendere uno spavento! A lui non piacerà, ma io mi farò di sicuro una bella risata se riesci a farlo arrabbiare! Ah!", enHash = "4ec450ee" },
        objectives = { it = "Salta dalla cima della torre di guardia di Thendal Grove e usa la tua abilità Walk on Air per rallentare la caduta.", enHash = "e0580a37" },
        progress = { it = "La tua capacità di camminare sull'aria può tirarti fuori da — e, be'... cacciarti in — ogni genere di guai!", enHash = "e382f8aa" },
        reward = { it = "Quante volte devo dire a Myriaal di non incoraggiare gli altri a usare in modo sconsiderato i nostri doni celesti!\n\nDetto questo, immagino che un po' di pratica nella relativa sicurezza del villaggio sia... accettabile.\n\nIn futuro ti consiglio solo di usare la tua capacità con giudizio. Non vorrai esaurire la tua magia senza pensarci, per poi non poterla usare quando ne avrai davvero bisogno.", enHash = "fdcde31e" },
    },
    [92483] = {
        title = { it = "Di casa nelle ombre", enHash = "be7c0a1d" },
        text = { it = "Mentre eri via a occuparti del nostro problema con i vuldren, il nostro istruttore $Gdel:della; $C — Akeri Duskblade — ha chiesto di parlarti. Ha lasciato questo biglietto: leggilo prima, poi cercalo dentro la torre di guardia, qui al villaggio.\n\nÈ un tipo losco, ma d'altra parte lo sei anche tu. Credo che andrete d'accordo.", enHash = "ce6beda7" },
        objectives = { it = "Leggi il Simple Note, poi parla con Akeri Duskblade dentro la torre di guardia di Thendal Grove.", enHash = "7d179361" },
        progress = { it = "<Akeri ti osserva con sospetto.>", enHash = "5e04bbaf" },
        reward = { it = "Per poco non ti sentivo arrivare, giovane $C.\n\nPer poco.\n\n\"Per poco\" non basterà, quando lascerai Thendal Grove. Devi essere una lama sottile, silenziosa e ferma. Sempre vigile e sempre consapevole di ciò che ti circonda. Forse hai quello che serve per sopravvivere ai pericoli di Zephras. O forse finirai in un fosso con la gola tagliata. Alla fine dipende solo da te.\n\nParla di nuovo con me se vuoi muovere i prossimi passi.", enHash = "be122466" },
    },
    [92514] = {
        title = { it = "Benvenuti a Shen'dar Village", enHash = "eadeb69f" },
        text = { it = "Hai quell'aria da Windshaper. È qualcosa nel modo in cui sento un pizzico di elettricità statica sulla pelle quando ho vicino qualcuno toccato dagli spiriti: ti tradisce. Prima che ti metta al lavoro come si deve qui intorno, dovresti presentarti alla nostra anziana dei Windshaper, Illaya Amberwind. È appena qui fuori, vicino al centro del paese.\n\nAh, e presentati anche a Coriella Calmbreeze: gestisce la locanda del posto e può darti alloggio e provviste, se ti servono.", enHash = "ab5b63f8" },
        objectives = { it = "Parla con Illaya Amberwind e Coriella Calmbreeze a Shen'dar Village.", enHash = "4449cc52" },
        progress = { it = "Questo posto non è granché, ma è casa.", enHash = "c0d7ccf0" },
        reward = { it = "Ti sei $Gpresentato:presentata; a Illaya, allora? Bene. In questi giorni c'è parecchia tensione tra l'High Order e i Windshaper, ma qui a Shen'dar mantengono i rapporti civili. Tutti qui sanno bene che abbiamo problemi più grossi dei loro battibecchi.\n\nOra che è fatta, mi sembri qualcuno che cerca qualcosa da fare con le proprie mani, e io ho un problema di banditi con cui speravo potessi aiutarmi.", enHash = "b59a0c22" },
    },
    [92515] = {
        title = { it = "Il problema dei Prideclaw", enHash = "d2c622f6" },
        text = { it = "Come se non bastassero i banditi e i cultisti pazzi, in questo momento le colline sono piene anche di Prideclaw. Cominciano a spingersi fino ai confini del villaggio e si fanno ogni giorno più audaci. È solo questione di tempo prima che si prendano l'animale o il figlio di qualcuno. Sarebbe un atto di misericordia sfoltirli adesso, piuttosto che dopo una tragedia.\n\nPortami una dozzina circa delle loro pelli. Posso trasformarle in ogni genere di cose utili al villaggio.", enHash = "67e3feb5" },
        objectives = { it = "Raccogli 10 Prideclaw Pelt dai Prideclaw delle Shen'dar Highlands.", enHash = "7d0904de" },
        progress = { it = "Se vuoi il mio parere, i Prideclaw sono perfino carini. Da una distanza di sicurezza... e stando dietro a qualcuno con una spada in mano, si capisce.", enHash = "65a7db8f" },
    },
    [92516] = {
        title = { it = "Molestie degli ippogrifi", enHash = "95a1467e" },
        text = { it = "Uno stormo di ippogrifi ha stabilito da poco i suoi nidi a sud-est di Shen'dar Village, e sta seminando il caos tra i viaggiatori sulla strada. Mi serve qualcuno che vada laggiù a sfoltirli per noi.", enHash = "1b9c71ba" },
        objectives = { it = "Uccidi 8 Hippogryph Youth, 6 Hippogryph Protector e una Hippogryph Matriarch nelle Shen'dar Highlands.", enHash = "05f78cbf" },
        progress = { it = "Gli ippogrifi sono creature molto orgogliose. Probabilmente è il rumore delle carovane di carri a innervosirli e a spingerli ad attaccare. Qualunque sia il motivo degli attacchi, non possiamo ignorare i carovanieri morti.", enHash = "a7f5f900" },
    },
    [92517] = {
        title = { it = "L'elemento criminale", enHash = "6e13740e" },
        text = { it = "Non lontano a nord c'è una grotta, nascosta dietro una cascata. So bene che un gruppo di banditi opera da quella grotta. Erano un problema già prima che arrivasse il culto, ma adesso sono un vero terrore. Purtroppo non posso fare a meno di nessuno per mandarlo a sgombrarli.\n\nHo bisogno che tu vada là e te ne occupi al posto mio. Uccidine più che puoi e, se possibile, fai fuori il loro capo, quello che chiamano \"Badwind\" Bennic. Quella grotta è pericolosa, quindi sta' $Gattento:attenta;.", enHash = "4e8cf8ad" },
        objectives = { it = "Uccidi 10 Highlands Bandit e il loro capo, \"Badwind\" Bennic, nelle Shen'dar Highlands.", enHash = "a6c69a9a" },
        progress = { it = "È una brutta faccenda quando degli shen'dorei si mettono a depredare il loro stesso popolo solo per sopravvivere, ma là fuori la situazione è sempre più disperata da quando i piloni hanno cominciato a cedere.", enHash = "bb9f4618" },
    },
    [92544] = {
        title = { it = "Gli scagnozzi degli Al'Aketh", enHash = "31795020" },
        text = { it = "Una banda di teppisti del culto degli Al'Aketh si è stabilita vicino alle rovine del tempio, appena a sud-ovest di qui, guidata da un vero mostro di nome Malduko Cloudcrush. Questa marmaglia è stata di sicuro mandata qui da High Priestess Lorthuna, dallo Shrine of Akir, per attaccare i viaggiatori e costringere la nostra gente a unirsi al culto.\n\nDevo restare qui al mio posto per avvisare del pericolo i viaggiatori che lasciano il boschetto, ma ti sarei grata se potessi fare qualcosa per me contro quei cultisti e il loro capo.", enHash = "e4354cd5" },
        objectives = { it = "Uccidi 6 Al'Aketh Brute, 4 Al'Aketh Neophyte e Malduko Cloudcrush a Thendal Grove.", enHash = "cd66bf77" },
        progress = { it = "Sospetto che vedere qualcuno dei loro compari sanguinare a terra farà miracoli per scoraggiare qualunque ambizione fanatica abbiano avuto questi scagnozzi.", enHash = "be6843bc" },
        reward = { it = "Ho dovuto fare di tutto per trattenermi dal venire a unirmi a te dalla mia posizione qui. Posso solo sperare che questi zoticoni abbiano capito il messaggio e se ne vadano presto da qui.\n\nGrazie, $C. I Rangers of Thendal Grove ti sono grati.", enHash = "1d860a51" },
    },
    [92553] = {
        title = { it = "Riempire le dispense", enHash = "d6a7968f" },
        text = { it = "Hai voglia di lavorare un po'? Mi farebbe comodo un po' di muscoli da $Gun tipo avventuroso e robusto:una tipa avventurosa e robusta; come te. Con quanto sono diventate pericolose le cose qui intorno, ultimamente nessuno ha avuto molto tempo per cacciare o raccogliere, e mi serve qualcuno che vada là fuori a procurarmi uova fresche e carne di strider per sfamare il villaggio.\n\nSarei felice di insegnarti una delle mie famose ricette, se riesci a portarmi quello che mi serve. Che ne dici?", enHash = "42853c2d" },
        objectives = { it = "Raccogli 3 Small Egg e 8 Strider Meat dalle creature delle Shen'dar Highlands.", enHash = "974aa48f" },
        progress = { it = "Per quanto le cose cambino qui a Zephras e diventino incerte, lo dico sempre: una pipa piena di Peacebloom essiccato e una bella pancia piena sono un conforto impareggiabile!", enHash = "fea9eaad" },
    },
    [92595] = {
        title = { it = "I Windshaper", enHash = "b5a7fb6b" },
        text = { it = "<Illaya ti sorride con calore.>\n\nSono felice che tu sia $Gtornato:tornata; a parlare con me, $Gfiglio:figlia; dei venti. L'ho capito dal primo momento in cui sei $Gcomparso:comparsa; al mio cospetto: sei forte nella skysight. Ti sorprende? Anche chi non si è addestrato come sciamano può possedere il dono.\n\nVieni, parliamo della missione dei Windshaper, della natura delle nostre lotte a Zephras e delle difficoltà del nostro popolo.", enHash = "c0e6b205" },
        objectives = { it = "Ascolta quello che ha da dire Illaya Amberwind.", enHash = "cfad0c5d" },
        progress = { it = "Il mondo sta cambiando e la strada che ci aspetta sarà difficile. Abbiamo una sola possibilità di salvarci.", enHash = "d197c086" },
        reward = { it = "Credo che ora tu capisca quanto è importante la missione dei Windshaper. Ogni anima che padroneggia la skysight è di vitale importanza, se speriamo di ristabilire il dialogo con gli spiriti dei venti.\n\nTra le minacce interne come gli Al'Aketh e l'incertezza della nostra sicurezza qui a Skywall, è nostra responsabilità come Windshaper usare i nostri doni per salvare la nostra casa e far sì che gli shen'dorei possano sopravvivere a questi tempi difficili.", enHash = "dcac49b3" },
    },
    [92597] = {
        title = { it = "Leggere le linee ley", enHash = "5c15557c" },
        text = { it = "Qui nel piano elementale, gran parte della nostra forza arcana viene dalle linee ley che scorrono ancora nel terreno sotto i nostri piedi. Di recente queste linee ley hanno cominciato a squarciare la superficie, e ci danno un accesso più diretto e potente a queste energie arcane latenti.\n\nVa' alle pietre erette a nord-est. Lì c'è una linea ley. Attingi al tuo diritto di nascita e assorbine l'energia.", enHash = "4145a621" },
        objectives = { it = "Usa la tua abilità razziale Read Ley Line presso la linea ley di Thendal Grove.", enHash = "2389c994" },
        progress = { it = "Realizzare il nostro vero potenziale come figli e figlie degli Alti Nobili è la nostra unica via di salvezza. I Windshaper sono poco meglio degli Al'Aketh: si prostrano davanti a creature indifferenti, di un altro mondo.", enHash = "ab6a6a9f" },
    },
    [92598] = {
        title = { it = "Il dono della skysight", enHash = "d2543a24" },
        text = { it = "Come Windshaper, hai la capacità di usare la sacra skysight che ci hanno donato gli spiriti elementali. Va' alle pietre erette a nord-est del villaggio. Trova lì la convergenza elementale e usa il tuo dono.\n\nScoprirai che puoi attingere alla skysight ovunque, ma il suo beneficio è molto più potente se lo fai in presenza di una convergenza elementale. A volte potresti anche ricevere altri frammenti di saggezza dagli spiriti che sono attirati da questi luoghi di potere.", enHash = "b4fd2504" },
        objectives = { it = "Usa la tua abilità razziale Skysight presso l'Elemental Convergence di Thendal Grove.", enHash = "3a015b26" },
        progress = { it = "Il dono della skysight ti darà un beneficio potente. Usalo con saggezza.", enHash = "84606600" },
        reward = { it = "Come un muscolo, la tua skysight va esercitata, se speri di diventare più forte nel dono. Usare la skysight per colmare la distanza tra il mortale e lo spirituale potrebbe rivelarsi prezioso nelle tue avventure.\n\nFaresti bene a ricordare quello che hai imparato qui oggi. La nostra capacità di usare i nostri doni per ascoltare quello che ci dicono gli elementi potrebbe essere la chiave della nostra sopravvivenza.", enHash = "a63f7667" },
    },
    [93318] = {
        title = { it = "WANTED: Vulgara the Insatiable", enHash = "c8761270" },
        text = { it = "Per ordine di Constable Aonda dei Peacekeepers, si pone una taglia sul flagello degli altopiani, Vulgara the Insatiable. Avvistata l'ultima volta sulla cima di un'altura appena a sud-ovest di Shen'dar Village, la terribile vuldren alata è molto pericolosa e va avvicinata con cautela.\n\nConsegna la testa della bestia a Danarii Bellowveil per ricevere la ricompensa.", enHash = "713b72f6" },
        objectives = { it = "Uccidi Vulgara the Insatiable nelle Shen'dar Highlands e porta la sua testa a Danarii Bellowveil.", enHash = "623b6e85" },
    },
    [93319] = {
        title = { it = "Pilfered Windstones", enHash = "b7e367b7" },
        text = { it = "Qui a Zephras dipendiamo sempre di più dalle windstone per la vita di tutti i giorni, quindi cerchiamo di tenerne una scorta di riserva per le emergenze. Ultimamente ho notato che dalle nostre provviste ne sparisce qualcuna.\n\nDi recente abbiamo trovato delle windstone addosso ai banditi che abbiamo catturato, e sospetto che dietro le nostre carenze ci siano loro.\n\nSe ti trovi vicino alla grotta dei banditi a nord, ti dispiacerebbe dare qualche bella lezione e recuperare un po' delle nostre Pilfered Windstone?", enHash = "b69a2055" },
        objectives = { it = "Raccogli 10 Pilfered Windstone dagli Highlands Bandit nelle Shen'dar Highlands.", enHash = "defc05aa" },
        progress = { it = "Probabilmente questi ladruncoli saccheggiano le nostre provviste da mesi. Ho cercato di convincere Aonda a organizzare un'incursione per sgombrare una volta per tutte quella grotta dei banditi, ma lei non voleva allontanare dal villaggio i pochi peacekeeper che abbiamo.\n\nCon i cultisti del Falaath Village a sud che aumentano di numero, immagino di non poterle dare torto.", enHash = "8ad5ca2e" },
    },
    [93552] = {
        title = { it = "Raccogliere windstone", enHash = "3d991d5d" },
        text = { it = "Le windstone sono una risorsa fondamentale su Zephras Isle, perché contengono l'energia grezza e concentrata dei venti stessi. Gli elementali del vento che vivevano qui su Zephras con noi sono scomparsi diversi secoli fa, e da allora la magia che sostiene quest'isola si sta lentamente affievolendo. Pur con i loro limiti, le windstone restano una fonte di energia affidabile, e per noi hanno un valore enorme.\n\nTroverai delle Raw Windstone sparse per il boschetto: pensi di potermi aiutare a raccoglierle?", enHash = "c4012577" },
        objectives = { it = "Raccogli 15 Windstone Cluster dalle Raw Windstone a Thendal Grove.", enHash = "329f902a" },
        progress = { it = "Ciao, $C.", enHash = "188df985" },
        reward = { it = "Grazie mille per queste. Come elfi abbiamo tutti un legame profondo con la magia, e queste windstone diventano sempre più preziose man mano che la magia infusa in quest'isola dai grandi piloni d'ancoraggio continua ad affievolirsi.\n\nLe windstone non sono l'unica cosa utile che puoi raccogliere dalla terra. Ti prego, prendi uno di questi manuali.", enHash = "87fdc487" },
    },
    [93951] = {
        title = { it = "Una piccola bellezza", enHash = "0a5d4b67" },
        text = { it = "Gli ippogrifi che si sono stabiliti a sud-ovest del villaggio possono essere una seccatura, ma offrono anche un'occasione piuttosto unica di procurarsi le loro piume. Molti skyborne amano ornarsi i capelli con piume vivaci, e il piumino di ippogrifo è eccezionalmente vivace e, soprattutto, morbido come la seta.\n\nSe vai da quelle parti, cerca di raccogliere più piume cadute che puoi dentro e intorno ai loro nidi. Ma sta' $Gattento:attenta;: gli ippogrifi selvatici non tollerano gli ospiti.", enHash = "3780602e" },
        objectives = { it = "Raccogli 8 Hippogryph Down nelle Shen'dar Highlands.", enHash = "3e8210ee" },
        progress = { it = "Che belle cose mi hai portato?", enHash = "6b48f9e7" },
    },
    [94411] = {
        title = { it = "Maghi ficcanaso", enHash = "3ed22566" },
        text = { it = "Sta' $Gattento:attenta;: sono stati visti dei membri dell'High Order nei pressi delle pietre erette a nord del villaggio. Li abbiamo avvertiti più e più volte di non immischiarsi nei nostri luoghi sacri, ma ci provocano con sempre più audacia. Dimostraci la tua determinazione: va' alle pietre erette e disperdili.\n\nNon mi piace approvare un vero spargimento di sangue, ma fa' ciò che devi per scacciarli. Torna da me quando hai finito.", enHash = "647b23d8" },
        objectives = { it = "Uccidi 6 High Order Apprentice nelle Shen'dar Highlands.", enHash = "f169a316" },
        progress = { it = "Fa' ciò che va fatto, $C.", enHash = "eac7290c" },
    },
    [94414] = {
        title = { it = "Le ancore di Zephras", enHash = "2647f2a9" },
        text = { it = "Salve, giovane $N. Vengo spesso qui a contemplare l'antico pilone d'ancoraggio. Doni degli spiriti dei venti, i piloni legano e sostengono la nostra isola. Di recente, però, la loro magia è diventata instabile e incostante.\n\nNon mostrano segni di sofferenza, per quanto posso vedere. Il loro splendore non è cambiato.\n\nSe vuoi, posso prestarti il mio dono perché tu possa osservarli con i tuoi occhi.", enHash = "c4c2f26e" },
        objectives = { it = "Parla con Halaan Hawk-Eye e fatti prestare il suo dono per osservare il pilone d'ancoraggio in lontananza.", enHash = "edd51f5d" },
        progress = { it = "Il mio dono è semplice e ordinario. Non posso scrutare tra i mondi come chi ha la skysight, né attingere alla magia delle linee ley sotto Zephras come fanno altri. Ma resta pur sempre un dono, e sono grato di averlo.\n\nApprezzare ciò che si ha è la chiave della felicità. Desiderare ciò che si potrebbe avere, o ciò che si è perso, porta solo alla disperazione.", enHash = "eb995cf7" },
        reward = { it = "Grazie per aver dedicato un momento a condividere questo con me. Continuerò a vegliare sul boschetto e a riflettere sullo stato della nostra terra natale.", enHash = "eab218fc" },
    },
    [95314] = {
        title = { it = "Quell'elisir verde di Shadowvale", enHash = "fde0101f" },
        text = { it = "Prima dell'invasione del Flagello, lo schivo villaggio di Shadowvale era famoso per il suo Whispering Elixir. Distillato da erbe che si trovano solo a Tyr's Fall, l'elisir era ricercato da speziali, mistici e avvelenatori, anche dopo essere stato vietato in città.\n\nHo ricevuto richieste da parecchi compratori ansiosi di mettere le mani su un po' di elisir. Va' alle rovine di Shadowvale, nel cuore della Whispering Forest a ovest. Sono pronta a offrire un compenso considerevole, se riesci a recuperare qualche bottiglia per me.", enHash = "e5e54d51" },
        objectives = { it = "Raccogli 8 Bottle of Whispering Elixir a Shadowvale, poi torna da Carolai Anise, a Brill.", enHash = "e8395894" },
    },
    [95998] = {
        title = { it = "La vita all'aria aperta", enHash = "d8c19bb9" },
        text = { it = "Ehi, salve, $C. Vedo che hai l'aria $Gda avventuriero:da avventuriera;. Buon per te. Il mondo ha bisogno di più anime inquiete come noi, in cerca di fortuna e di gloria.\n\nLà fuori il mondo è grande e vasto, e per avere successo dovrai imparare a prosperare nelle terre selvagge. Non so come te la cavi all'aria aperta, ma direi che potrei insegnarti un paio di cose, se sei $Gdisposto:disposta; a imparare.\n\nSiediti vicino al fuoco, mettiti $Gcomodo:comoda;. Ti spiego io come si fa.", enHash = "e760de16" },
        objectives = { it = "Siediti vicino al Sam's Basic Campfire scrivendo /sit nella finestra della chat e aspetta di ricevere il buff Boosted Rest.", enHash = "d2ef15f1" },
        reward = { it = "Ora che abbiamo imparato le basi, perché non vai a imparare una professione? Ti insegneranno anche come costruire un vero elemento da campo adatto alla tua nuova professione.", enHash = "23c726b3" },
    },
    [96101] = {
        title = { it = "La vita all'aria aperta", enHash = "d8c19bb9" },
        text = { it = "Salve, $C. Vedo che hai l'aria $Gda avventuriero:da avventuriera;. Questo è un bene. Il mondo ha bisogno di più anime inquiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so come te la cavi all'aria aperta, ma probabilmente posso insegnarti un paio di cose, se sei $Gdisposto:disposta; a imparare.\n\nSiediti vicino al fuoco e mettiti $Gcomodo:comoda;. Ti spiego io come si fa.", enHash = "1dd9fac9" },
        objectives = { it = "Siediti vicino al Raan's Basic Campfire scrivendo /sit nella finestra della chat e aspetta di ricevere il buff Boosted Rest.", enHash = "b19355a8" },
        progress = { it = "Avere le capacità necessarie per sopravvivere all'aria aperta è fondamentale. Un avventuriero ben riposato e ben preparato ha molte più probabilità di sopravvivere a questo stile di vita.", enHash = "190a7241" },
        reward = { it = "Ora che abbiamo imparato le basi, perché non vai a imparare una professione dagli istruttori del villaggio qui vicino? Ti insegneranno anche come costruire un elemento da campo adatto alla tua nuova professione.", enHash = "a6ab1e94" },
    },
    [96606] = {
        title = { it = "La vita all'aria aperta", enHash = "d8c19bb9" },
        text = { it = "Salve, $C. Vedo che hai l'aria $Gda avventuriero:da avventuriera;. Questo è un bene. Il mondo ha bisogno di più anime inquiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so come te la cavi all'aria aperta, ma probabilmente posso insegnarti un paio di cose, se sei $Gdisposto:disposta; a imparare.\n\nSiediti vicino al fuoco e mettiti $Gcomodo:comoda;. Ti spiego io come si fa.", enHash = "1dd9fac9" },
        objectives = { it = "Siediti vicino al Lyreena's Basic Campfire scrivendo /sit nella finestra della chat e aspetta di ricevere il buff Boosted Rest.", enHash = "56e14a18" },
    },
    [96626] = {
        title = { it = "Corso base di campeggio: la cucina", enHash = "41a4c801" },
        text = { it = "Allora vuoi saperne di più sul campeggio, eh? Buon per te, $C. Il primo passo che ogni avventuriero deve fare è diventare cuoco e imparare ad accendere un fuoco da campo.\n\nLa cucina non serve solo a preparare cibi gustosi. È anche la base del tuo accampamento.", enHash = "1849fc2a" },
        objectives = { it = "Parla con Tomas, a Goldshire, per imparare a diventare $Gcuoco:cuoca;.", enHash = "3f3b653e" },
        reward = { it = "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità di cucina, e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori delle altre professioni, se te ne intendi.", enHash = "eb4b2c4c" },
    },
    [96627] = {
        title = { it = "L'avventuriero", enHash = "e0e48271" },
        text = { it = "$N, finora hai dimostrato la tua competenza come $Gprotettore:protettrice;. Per questo ora ti affido un compito insolito.\n\nHo sentito parlare di un nuovo avventuriero lungo la strada, vicino a Goldshire. Va' a vedere cosa sta facendo.", enHash = "c1556c50" },
        objectives = { it = "Parla con Sam Sarsaparilla, vicino a Goldshire.", enHash = "fdf81511" },
        reward = { it = "Grazie per esserti $Gpreoccupato:preoccupata; per me, $C. Quel maresciallo è solo un apprensivo.\n\nEhi, anche tu hai l'aria $Gda avventuriero:da avventuriera;. Che ne diresti di imparare qualcosa sul campeggio?", enHash = "888f2860" },
    },
    [96638] = {
        title = { it = "L'avventuriero", enHash = "e0e48271" },
        text = { it = "Sempre più avventurieri come te cercano gloria e fortuna fuori dalla sicurezza di Thendal Grove. Uno di loro si è accampato fuori da Shen'dar Village, lungo la strada che esce da Thendal Grove verso sud-ovest.\n\nCercalo e vedi cosa puoi imparare da lui che possa aiutarti nei tuoi viaggi.", enHash = "809dd5f6" },
        objectives = { it = "Parla con Raan Wildwind, vicino a Shen'dar Village.", enHash = "44204b9f" },
        reward = { it = "$GBen trovato:Ben trovata;!", enHash = "f308b5d7" },
    },
    [96646] = {
        title = { it = "Corso base di campeggio: la cucina", enHash = "41a4c801" },
        text = { it = "Allora vuoi saperne di più sul campeggio, eh? Buon per te, $C. Il primo passo che ogni avventuriero deve fare è diventare cuoco e imparare ad accendere un fuoco da campo.\n\nLa cucina non serve solo a preparare cibi gustosi. È anche la base del tuo accampamento.", enHash = "1849fc2a" },
        objectives = { it = "Parla con Zerril Softbreeze, a Shen'dar Village, per imparare a diventare $Gcuoco:cuoca;.", enHash = "699ed694" },
        progress = { it = "Un buon fuoco da campo è la base di ogni buon accampamento.", enHash = "029d9016" },
        reward = { it = "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità di cucina, e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori delle altre professioni, se te ne intendi.", enHash = "eb4b2c4c" },
    },
    [97236] = {
        title = { it = "Fang of Githyiss", enHash = "9d60b303" },
        text = { it = "Un esemplare fresco di una bestia di queste dimensioni è una bella scoperta. Forse qualcuno ad Aldrassil che si intende di studio dei ragni sarebbe interessato alla zanna.", enHash = "58b8de03" },
        objectives = { it = "Consegna il Fang of Githyiss a qualcuno che si interessa allo studio dei ragni, ad Aldrassil.", enHash = "b40a08bc" },
    },
    [97279] = {
        title = { it = "Armi smarrite", enHash = "0cb150a2" },
        text = { it = "Con tutte queste nuove reclute come te, fatichiamo a tenere le armi rifornite. Il nostro armaiolo, Kzan, sta finendo le armi da addestramento, e io vorrei vedere di che cosa sei capace, per capire su che materiale posso contare. Per tua fortuna, ho una soluzione per entrambe le cose.\n\nMentre sei là fuori a farti le ossa sui cinghiali, recupera sei Abandoned Training Weapon: le hanno lasciate sparse a terra le reclute che non ce l'hanno fatta. Poi riportale al nostro armaiolo Kzan, dietro di me nel Den.", enHash = "eeae8d5b" },
        objectives = { it = "Raccogli 6 Abandoned Training Weapon, poi portale a Kzan Thornslash nel Den.", enHash = "07168eee" },
        progress = { it = "Throm'ka, $C. Gorak mi ha detto di aspettarti. È bello vederti $Gtutto intero:tutta intera;!\n\nSei $Griuscito:riuscita; a recuperare le armi da addestramento che ti avevo chiesto?", enHash = "269a2b84" },
        reward = { it = "Grazie per avermi riportato queste armi, $N. Mi metterò subito al lavoro per ripararle, in vista della prossima ondata di reclute.", enHash = "4b4470ac" },
    },
    [97558] = {
        title = { it = "Pelli per i Reietti", enHash = "0e3093b2" },
        text = { it = "C'è un aspetto della non morte di cui nessuno parla: cosa succede quando veniamo feriti. Come fa a guarire la pelle di $Gun:una; $R?\n\nBe', non guarisce.\n\nLa nostra è una vita maledetta, $N. Dobbiamo prendere dai vivi per prolungare la nostra esistenza.\n\nQuando subiamo una ferita, dobbiamo sostituire la pelle, e di solito questo vuol dire pelli di animali. Visto che spessori diversi vanno meglio in punti diversi del corpo, la varietà è fondamentale!\n\nPortami membrane alari di Duskbat, pelli di Darkhound e pelle di murloc Vile Fin.", enHash = "448a0abd" },
        objectives = { it = "Porta a Shelene Rhobart 8 Duskbat Wing Membrane, 6 Darkhound Hide e 3 Vile Fin Murloc Skin.", enHash = "7f9c4b00" },
    },
    [97916] = {
        title = { it = "Corso base di campeggio: la forgiatura", enHash = "e4843d25" },
        text = { it = "Allora sei $Gdiventato:diventata; fabbro. È un'ottima scelta, se vuoi essere $Gsicuro:sicura; che le tue lame non perdano mai il filo.\n\nDirei che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una Sharpening Wheel. Tirane fuori una al tuo accampamento, e tutti i guerrieri e i ladri della zona faranno la fila per affilare le loro armi.", enHash = "9cf2015c" },
        objectives = { it = "Parla con Smith Argus, a Goldshire, per imparare a fabbricare un oggetto da campo per la tua professione, quando avrai dimostrato padronanza della tua abilità.", enHash = "1582307b" },
    },
    [97919] = {
        title = { it = "Corso base di campeggio: il primo soccorso", enHash = "65ea0673" },
        text = { it = "Quindi ti sei $Gdato:data; al primo soccorso? Per $Gun:una; $C è un'attività onorevole... e pragmatica.\n\nDirei che conosco qualcuno che può insegnarti a fabbricare un First Aid Kit per il tuo accampamento. Le ferite sono una realtà nel mondo delle avventure, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe perfino salvare delle vite.", enHash = "f5229872" },
        objectives = { it = "Parla con Michelle Belle, a Goldshire, per imparare a fabbricare un oggetto da campo per la tua professione, quando avrai dimostrato padronanza della tua abilità.", enHash = "e5dacd37" },
        reward = { it = "Ecco fatto: ora puoi fabbricare il tuo First Aid Kit personale. Alla maggior parte della gente non piace molto che si allestiscano accampamenti in centro, quindi se vuoi provarlo dovrai andare nelle terre selvagge.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa istruirti nell'arte culinaria, per impararne le basi.", enHash = "0d4fb25b" },
    },
    [97920] = {
        title = { it = "Corso base di campeggio: la pesca", enHash = "d65166f1" },
        text = { it = "Forse non lo penseresti, ma la tua abilità di $Gpescatore:pescatrice; può tornarti davvero utile all'accampamento.\n\nDirei che conosco qualcuno che può insegnarti a fabbricare un Fish Bowl per il tuo accampamento. Puoi usare questo elemento per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e sono sicuro che si vedrà nelle tue capacità in combattimento.", enHash = "c86e7835" },
        objectives = { it = "Parla con Lee Brown, vicino a Goldshire, per imparare a fabbricare un oggetto da campo per la tua professione, quando avrai dimostrato padronanza della tua abilità.", enHash = "da9a1113" },
    },
    [97923] = {
        title = { it = "Corso base di campeggio: l'estrazione mineraria", enHash = "75f24b09" },
        text = { it = "L'estrazione mineraria non è il lavoro più affascinante, ma è un lavoro buono e onesto, e una bella professione da esplorare.\n\nDirei che conosco qualcuno che può insegnarti a fabbricare una Lodestone per il tuo accampamento. Costruiscine una, e chiunque voglia menare fendenti con una spada non vedrà l'ora di radunarsi intorno al tuo fuoco e di assorbire quella \"spinta\" in più che può dare per migliorare la sua abilità in combattimento.", enHash = "7216665d" },
        objectives = { it = "Parla con Gelman Stonehand, a Stormwind, per imparare a fabbricare un oggetto da campo per la tua professione, quando avrai dimostrato padronanza della tua abilità.", enHash = "c5f7df04" },
        reward = { it = "Ecco fatto: ora puoi fabbricare la tua Lodestone personale. Alla maggior parte della gente non piace molto che si allestiscano accampamenti in centro, quindi se vuoi provarlo dovrai andare nelle terre selvagge.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa istruirti nell'arte culinaria, per impararne le basi.", enHash = "d190459c" },
    },
    [97955] = {
        title = { it = "Corso base di campeggio: il primo soccorso", enHash = "65ea0673" },
        text = { it = "Quindi ti sei $Gdato:data; al primo soccorso? Per $Gun:una; $C è un'attività onorevole... e pragmatica.\n\nDirei che conosco qualcuno che può insegnarti a fabbricare un First Aid Kit per il tuo accampamento. Le ferite sono una realtà nel mondo delle avventure, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe perfino salvare delle vite.", enHash = "f5229872" },
        objectives = { it = "Parla con Nurse Neela, a Brill, per imparare a fabbricare un oggetto da campo per la tua professione, quando avrai dimostrato padronanza della tua abilità.", enHash = "24beff44" },
    },
    [97959] = {
        title = { it = "Corso base di campeggio: l'estrazione mineraria", enHash = "75f24b09" },
        text = { it = "L'estrazione mineraria non è il lavoro più affascinante, ma è un lavoro buono e onesto, e una bella professione da esplorare.\n\nDirei che conosco qualcuno che può insegnarti a fabbricare una Lodestone per il tuo accampamento. Costruiscine una, e chiunque voglia menare fendenti con una spada non vedrà l'ora di radunarsi intorno al tuo fuoco e di assorbire quella \"spinta\" in più che può dare per migliorare la sua abilità in combattimento.", enHash = "7216665d" },
        objectives = { it = "Parla con Brom Killian, nell'Undercity, per imparare a fabbricare un oggetto da campo per la tua professione, quando avrai dimostrato padronanza della tua abilità.", enHash = "f3e44cd0" },
    },
    [97970] = {
        title = { it = "Corso base di campeggio: l'estrazione mineraria", enHash = "75f24b09" },
        text = { it = "L'estrazione mineraria non è il lavoro più affascinante, ma è un lavoro buono e onesto, e una bella professione da esplorare.\n\nDirei che conosco qualcuno che può insegnarti a fabbricare una Lodestone per il tuo accampamento. Costruiscine una, e chiunque voglia menare fendenti con una spada non vedrà l'ora di radunarsi intorno al tuo fuoco e di assorbire quella \"spinta\" in più che può dare per migliorare la sua abilità in combattimento.", enHash = "7216665d" },
        objectives = { it = "Parla con Messana Crestwind, a Shen'dar Village, per imparare a fabbricare un oggetto da campo per la tua professione, quando avrai dimostrato padronanza della tua abilità.", enHash = "4fe0aa7c" },
        progress = { it = "Posso istruirti, se hai la predisposizione.", enHash = "5a4e75c5" },
    },
    [98389] = {
        title = { it = "Una luce nel buio", enHash = "9cdd4f2e" },
        text = { it = "Salve, $C. Sì, appartengo ai paladini. Nemmeno la morte può fermare la Luce.\n\nÈ questo che quelli come me hanno in comune con tutti i Reietti: abbiamo superato ciò che i vivi considerano la loro fine. Eppure alcuni, perfino tra i nostri, ci temono; sospettano che li colpiremo come fossero una mostruosità.\n\nIn verità il nostro rapporto con la non morte è complesso, ma non sono qui per fare del male ai nostri. Aiutami a dimostrarlo agli altri. Vai a Night's Web Hollow, a nord-ovest, e libera gli sciocchi appena risorti rimasti prigionieri dei ragni.", enHash = "6a25778f" },
        ["text#2"] = { it = "Se ricordi una sola cosa, sappi questo: nemmeno la morte può fermare la Luce.\n\nÈ questo che abbiamo in comune con tutti i Reietti: abbiamo superato ciò che i vivi considerano la loro fine. Eppure alcuni, perfino tra i nostri, ci temono; sospettano che li colpiremo come fossero una mostruosità.\n\nIn verità il nostro rapporto con la non morte è complesso, ma non siamo qui per fare del male ai nostri. Aiutami a dimostrarlo agli altri. Vai a Night's Web Hollow, a nord-ovest, e libera gli sciocchi appena risorti rimasti prigionieri dei ragni.\n\nAllora vedranno la nostra natura.", enHash = "fca0c3d7" },
        objectives = { it = "Libera 6 Webbed Victim a Night's Web Hollow per Aramis Hammerhand, a Deathknell.", enHash = "87f66e66" },
        progress = { it = "Hai liberato quelle povere anime sventurate intrappolate nella grotta?", enHash = "f59a0e05" },
        reward = { it = "Che questo aiuti Executor Arren e tanti altri a vedere la nostra vera natura. Come nelle nostre vite passate, viviamo per servire la nostra gente, per proteggerla con i doni che la Luce ci concede.\n\nCol tempo capiranno che per i piani della Signora Oscura valiamo quanto chiunque altro.\n\nChe la Luce sia con te.", enHash = "89c07f40" },
    },
    [98391] = {
        title = { it = "La Sisterhood of Elune", enHash = "c9e0bc0d" },
        text = { it = "Benedizioni a te, $C. Da migliaia di anni la Sisterhood of Elune è un pilastro della società kaldorei.\n\nPrima della Grande Separazione, prima della Guerra degli Antichi, durante la Lunga Veglia, abbiamo guidato e curato il nostro popolo attraverso le tenebre. Questo è il nostro compito, e questo è ciò che chiede l'impareggiabile Madre Luna.\n\nOra ci serve il tuo aiuto in una questione di grande importanza. Sister Aquinne attende il tuo arrivo a Darnassus.", enHash = "609b5c2d" },
        objectives = { it = "Parla con Sister Aquinne a Darnassus.", enHash = "96d0a37f" },
    },
    [98601] = {
        title = { it = "Un cammino difficile", enHash = "41843426" },
        text = { it = "Mentre eri via a occuparti delle creature senza mente del Flagello, è arrivata questa pergamena per te. Puzza di Luce, quindi immagino sia importante per $Gun:una; $C come te.\n\nLeggila prima di ripartire. Solo, per favore, allontanati quando lo fai. I paladini mi mettono parecchio a disagio.", enHash = "6036b555" },
        objectives = { it = "Leggi il Consecrated Scroll e parla con Aramis Hammerhand nella chiesa di Deathknell.", enHash = "03a90445" },
        progress = { it = "Dal dolore nasce la determinazione.", enHash = "a34a8782" },
        reward = { it = "Ora il tuo addestramento può cominciare sul serio, $C. Vedo in te grandi promesse, ma bada a non distoglierti dalla Luce, nemmeno per un istante. Accogli il dolore che ti causerà. Quel dolore è un crogiolo, e ne uscirai più forte di quanto tu sia mai $Gstato:stata; nella tua vita precedente.", enHash = "d65599a3" },
    },
    [99046] = {
        title = { it = "La messaggera scomparsa", enHash = "587a3a7d" },
        text = { it = "Tempo fa il Consiglio della Foresta ha mandato un piccolo gruppo di Sentinelle all'Oracle Tree. L'albero manda messaggi ai nostri anziani, e spetta a noi portarli a Darnassus in sicurezza.\n\nMi è giunta notizia che la nostra ultima messaggera non è ancora arrivata. I messaggi dell'Oracle arrivano con frequenza variabile, ma questa volta è passato un tempo insolitamente lungo.\n\nTi prego, dirigiti verso l'Oracle Glade lungo la strada a ovest e controlla come sta. Toccava a Eralya Leafshadow, e lei è ancora in addestramento. Che Elune ti guidi.", enHash = "a2e593fc" },
        objectives = { it = "Cerca Sentinel Eralya Leafshadow sulla strada che porta all'Oracle Glade.", enHash = "c3103138" },
    },
    [99127] = {
        title = { it = "Un disastro nella rete", enHash = "bbfcff63" },
        text = { it = "Oggi i pesci non abboccano proprio, e c'è qualcosa che non va in loro. Non sono solo gli ami vuoti. Non ho visto un solo pesciolino salire in superficie.\n\nLee, qui, ha piazzato delle trappole stanotte: va' a controllare se almeno lì abbiamo preso qualcosa. Se trovi qualcosa di strano, fammelo vedere.", enHash = "c8172e15" },
        objectives = { it = "Controlla le trappole per pesci nel Crystal Lake.", enHash = "ca7ec351" },
        progress = { it = "Hai preso qualcosa di degno di nota?", enHash = "d5682860" },
    },
    [99142] = {
        title = { it = "Tomb Weed", enHash = "68e178bd" },
        text = { it = "Se vai a est, verso la Balnir Farmstead, ho altro che potresti fare per me. Di questi tempi è così difficile trovare un buon aiuto, come dimostra fin troppo chiaramente il tuo incontro con Gordo.\n\nMan mano che mi procuro della Doom Weed, le apporto delle piccole modifiche alchemiche e la ripianto in quella fattoria per coltivare la mia creazione definitiva. La chiamo Tomb Weed, e sarà l'araldo del mio glorioso destino.\n\nMentre sei lì, tieni d'occhio il Flagello della zona. Sembra che sia... attirato... dall'erba. Curioso.", enHash = "2cc4e91f" },
        objectives = { it = "Raccogli 5 Tomb Weed e riportale a Junior Apothecary Holland.", enHash = "413da679" },
    },
    [99143] = {
        title = { it = "Bottiglie e cianfrusaglie", enHash = "0f0c8e12" },
        text = { it = "Quegli uomini pesce devono pensare come pesci veri, giusto? Quindi qualunque cosa piaccia a loro, piacerà anche ai pesci!\n\nSe frughi un po' tra le loro cianfrusaglie e mi riporti qualcosa che sembri adatto come esca, ti ricompenserò.", enHash = "021d7ed0" },
        objectives = { it = "Raccogli 6 Shiny Junk nell'accampamento dei murloc qui vicino.", enHash = "de3ddf48" },
    },
}
WoWForeverIT_QuestIT.GossipIT = {
    ["0051b5e0"] = { it = "Salve. Insegno a chi è $C $R, e tu sei $Gun:una; $C." },
    ["02206d93"] = { it = "Certo che posso aiutarti con l'addestramento. Anch'io sono solo un artigiano qualificato, ma sono sicuro che ci sia qualcosa che posso mostrarti." },
    ["0790d0ed"] = { it = "Da dove comincio? La nostra casa sta cedendo. Le protezioni sono cadute e le tre province hanno cominciato ad allontanarsi l'una dall'altra. Non molto tempo fa, dalla torre di guardia occidentale si vedevano le guglie di Shen'dramar. Ora non più. I piloni d'ancoraggio si stanno indebolendo, e se le catene alla fine si spezzano..." },
    ["08d1adcb"] = { it = "$GBenvenuto:Benvenuta; a villaggio di Shen'dar, dove si pesca meglio da questa parte della catena montuosa. Se vuoi pescare, posso insegnarti, a pagamento." },
    ["0a78e913"] = { it = "Sta' in guardia qui negli altopiani, $Gcittadino:cittadina;. I pericoli sono tanti, tra le bestie che vagano nelle terre selvagge, i banditi assassini e la minaccia incombente degli Al'Aketh." },
    ["0abab995"] = { it = "Potresti pensare che, solo perché viviamo su un'isola fluttuante, non ci sia bisogno di minatori come me. Eppure, dopo tante migliaia di anni, riusciamo ancora a scavare un sacco di cose interessanti.\n\nÈ quasi come se ci fosse una forza invisibile che ogni tanto crea di continuo nuovi giacimenti di minerali. Ma d'altronde è la magia, no?\n\nComunque, se ti serve un addestramento nell'estrazione mineraria, sono la shen'dorei che fa per te." },
    ["0cd5cada"] = { it = "Saluti dei venti, $Gamico:amica;. Posso aiutarti in qualcosa?" },
    ["0e76e889"] = { it = "Le professioni si dividono in due categorie principali: primarie e secondarie.\n\nPuoi avere al massimo due professioni primarie alla volta. Puoi abbandonare una professione primaria in qualsiasi momento, ma perderai tutte le conoscenze accumulate. Se deciderai di tornare alla professione di prima, dovrai ricominciare dalle basi e cercare di nuovo le ricette che avevi imparato, per riprendere confidenza con esse.\n\nLe professioni secondarie non hanno questo limite. Sono abilità legate soprattutto all'autosufficienza e ai bisogni di base per sopravvivere. Puoi impararle tutte, o solo alcune, ma potresti trovare meno occasioni per guadagnarci." },
    ["0ef49187"] = { it = "$GBen trovato:Ben trovata;, $N. È bello vedere che $Gi ladri:le ladre; come te partecipano attivamente alla protezione dei boschetti." },
    ["10177f0a"] = { it = "Su questo punto in molti non sono d'accordo. Io credo che la chiave sia la semplice comunicazione. I canti del vento risuonavano così chiari per noi, quando gli spiriti erano ancora qui. Da quando se ne sono andati, è sceso il silenzio, e il nostro potere di Plasmavento si è indebolito.\n\nPerò alcuni di noi riescono ancora a sentire qualcosa. Un tono sommesso. Frammenti di una melodia. Chi riesce ancora a sentire e a vedere nei piani elementali deve diventare più forte. Credo che sia questa la chiave della nostra salvezza." },
    ["104d09c3"] = { it = "Il culto degli Al'Aketh sostiene che Al'Akir the \"Signore del Vento\" ci salverà dai nostri guai attuali qui a Zephras. Se Al'Akir esiste ed è davvero il sovrano di Skywall, perché gli spiriti del vento si sono rifiutati di parlare di lui per così tanto tempo?\n\nO non esiste, o peggio ancora, esiste e non è benevolo come sostiene il culto. In ogni caso, niente di quello che fa il culto è buono per noi gente comune." },
    ["13c2b104"] = { it = "Stermina i tuoi nemici e fai cadere ai tuoi piedi i tuoi spasimanti con questo semplice trucco.\n\nSe segui la via $Gdel:della; $C, posso insegnarti... a un prezzo, naturalmente." },
    ["1554cc37"] = { it = "Ciao, $N! Hai mai pensato di imparare una professione?\n\nSarei felice di rispondere alle tue domande, o di indicarti gli istruttori della zona.\n\nSe ti sembra troppo, non c'è problema! Puoi sempre tornare qui, o andare dagli istruttori nelle capitali, per iniziare a creare oggetti quando vuoi." },
    ["16d74b88"] = { it = "Il culto? Sono fanatici e assassini. Credono che veniamo puniti per qualche peccato imprecisato. La realtà è che chi li guida sono opportunisti, avanzi di un dubbio ordine di cosiddetti \"sacerdoti\" di Al'Akir, the Signore del Vento.\n\nOra si trovano nella posizione di usare come un'arma la paura del nostro popolo per consolidare il proprio potere... e non hanno perso tempo a farlo." },
    ["1a48e51c"] = { it = "Non voltare le spalle alla Luce, $C: un giorno potrebbe essere l'unica cosa a salvarti." },
    ["1c9e6214"] = { it = "Salve, $Gcittadino:cittadina;." },
    ["1e979539"] = { it = "Salve, $Gviaggiatore:viaggiatrice;." },
    ["25dae66d"] = { it = "Il culto degli Al'Aketh sta diventando un problema serio, e i guardiano sembrano incapaci di fermarlo. Possiamo solo sperare che i Plasmavento e l'Alto Ordine mettano da parte i loro battibecchi e collaborino con i guardiano per proteggerci.\n\nIo di certo non voglio unirmi a un culto!" },
    ["25ea4a68"] = { it = "Come posso aiutarti?" },
    ["25f776e2"] = { it = "Cosa posso fare per te, collega Plasmavento?" },
    ["27660fc7"] = { it = "Come un gatto portato al riparo dalla pioggia, graffi e tiri fuori gli artigli, e poi ricominci da capo... Tornerò per averne ancora...\n\nOh, non ti avevo visto entrare, $N! Cosa posso fare per te?" },
    ["287e4ce2"] = { it = "Non sei $Guno stregone:una strega; e non ho tempo per te. Vattene!" },
    ["28a15689"] = { it = "Ottima scelta. Ho segnato quel luogo sulla tua mappa." },
    ["298f3931"] = { it = "Zephras è in declino, purtroppo. Gli spiriti elementali del vento che ci portarono qui a Skywall molte migliaia di anni fa sono scomparsi, e questo ci ha fatto perdere gran parte della magia da cui dipendiamo da millenni.\n\nAnche l'isola stessa è pericolosamente instabile, e abbiamo perso perfino i contatti con le altre province insulari degli shen'dorei. I pochi Plasmavento che possiedono ancora il dono della skysight hanno provato a contattare i nostri fratelli e le nostre sorelle sulle altre isole, ma non abbiamo avuto risposta.\n\nMolti tra noi temono che gli shen'dorei qui a Zephras siano tutto ciò che resta del nostro popolo." },
    ["2ca54cfd"] = { it = "Se ne hai la predisposizione, posso insegnarti a fabbricare delle belle armature di cuoio." },
    ["3177c723"] = { it = "L'arte tessile degli shen'dorei è un'imitazione armoniosa delle correnti fluide e spensierate dei venti. Anche se gli spiriti ci hanno lasciati, e non so quando potrò vederli danzare di nuovo... trovo un grande conforto nella mia arte, anche solo come distrazione.\n\nSe vuoi imparare, posso insegnare anche a te a lavorare la stoffa." },
    ["35431241"] = { it = "Il guerriero che esita è il guerriero che muore. Se vuoi guardare la morte in faccia $Gda guerriero:da guerriera;, ti insegnerò a non esitare." },
    ["361d3b2f"] = { it = "La magia può ottenere quasi tutto, ma la stagnazione e l'inerzia ci hanno fatto perdere tanto di noi stessi nelle migliaia di anni trascorsi da quando abbiamo lasciato Kalimdor. I membri dell’Alto Ordine cercano di recuperare l'eredità degli Alti Nobili che ci siamo lasciati alle spalle, e di tornare padroni del nostro destino.\n\nI Plasmavento pensano che siamo solo avventati e arroganti. Ipocrisia allo stato puro, se vuoi sapere come la penso. Quando si tratta di questa crisi, i Plasmavento non prendono in considerazione altre idee che le loro. Chi è davvero arrogante, mi chiedo?" },
    ["3838b4ab"] = { it = "La maggior parte della mia banda sì. Sfollati quando il terreno ci è franato sotto i piedi. Alcuni venivano addirittura da altre isole. Io vengo dalla città di Shen'dramar, sulla grande isola. Be', quella che un tempo era la grande isola, direi.\n\nIo e la mia famiglia siamo riusciti a salire su uno degli ultimi nave volante prima che l'intera isola andasse in pezzi. Pensavamo che Zephras ci avrebbe salvati. Be', non è stato così. Sono tutti morti da tempo, e ora sono qui, in attesa dell'esecuzione." },
    ["3b985c54"] = { it = "Sono contento che tu me lo chieda!\n\nLe professioni sono abilità legate alla creazione di oggetti, alla raccolta di materiali e alla sopravvivenza in generale. Ce ne sono molte tra cui scegliere, e ognuna offre vantaggi e opportunità economiche tutte sue. Che tu cerchi ricchezza, un modo per riempire il magazzino della tua gilda di oggetti utili, o semplicemente la soddisfazione di indossare equipaggiamento fatto con le tue mani, c'è una professione per te.\n\nLe ricette si imparano dagli istruttori, come quelli qui intorno, e da molte altre fonti in tutta Azeroth. Una volta imparata una ricetta, puoi creare quell'oggetto tutte le volte che vuoi, purché tu riesca a procurarti i materiali necessari." },
    ["4415f4e6"] = { it = "Se sei $Gdisposto:disposta; a imparare, posso insegnarti a usare il martello da fabbro." },
    ["4a30fee0"] = { it = "Salve, $Gfiglio mio:figlia mia;. Sono Illaya Amberwind, l'anziana dei Plasmavento qui a isola di Zephras. È sempre bello incontrare volti giovani e nuovi che scendono dal boschetto.\n\nNon lasciare che questa vecchia sciamana ti trattenga: di sicuro hai molte avventure che ti aspettano. Passa pure più tardi, se ti va." },
    ["4f7919e3"] = { it = "Non ho niente di personale contro i membri dei Plasmavento come te, ma non ho nemmeno bisogno di conversare con te. Va' per la tua strada, ma ti consiglio vivamente di tenerti alla larga dall'Alto Ordine e dai nostri agenti nei tuoi viaggi per l’isola di Zephras.\n\nL'Alto Ordine non cerca il conflitto... ma lo chiuderà con decisione, se il conflitto dovesse trovarci. Stai fuori dalla nostra strada, Plasmavento." },
    ["5421ba9b"] = { it = "$GBenvenuto:Benvenuta; alla locanda Brezzaserena, $Gviaggiatore:viaggiatrice;. Vuoi qualcosa per rinfrescarti?" },
    ["562e03d6"] = { it = "Disperazione? Fame? Non sono certo qui a farlo perché mi piace rapinare e uccidere. Ho perso la mia casa, non avevo dove andare, e non mi va molto di rasarmi la testa e adorare qualche immaginario dio del vento, così sono diventato un bandito. Il resto è ovvio." },
    ["59513af7"] = { it = "Ah, ma che aria robusta che hai! Forse puoi aiutarmi con una cosa o due. Da queste parti non c'è molto aiuto, a parte apprendisti alle prime armi, e loro hanno altro a cui pensare." },
    ["5ade686f"] = { it = "Gli spiriti del vento ci hanno lasciato.\n\nOra restano solo echi privi di mente. Ma sta' in guardia: questi venti non sono né benevoli né gentili." },
    ["5b21e2cd"] = { it = "Ahimè, ho chiacchierato abbastanza. Se ti capita di passare da quelle parti, cerca la mia apprendista Ayessa Dawnsinger, nel porto di Valanaar. Lei sente ancora il canto, anche se solo debolmente. Io sono vecchia, e gran parte del mio potere mi ha lasciata. Ayessa rappresenta il futuro del nostro popolo e la strada che ora dobbiamo percorrere per sopravvivere. Tocca a lei e ai giovani shen’dorei come te portare avanti le speranze del nostro popolo." },
    ["5c035a41"] = { it = "La Valle delle Prove temprerà anche il più debole, fino a farne un guerriero degno di unirsi all'Orda. Chi non sarà all'altezza delle sue prove resterà a cuocere sotto il sole rovente del deserto." },
    ["60404a92"] = { it = "Che la Luce sia con te, $C. Come posso aiutarti?" },
    ["646265ad"] = { it = "A meno che tu non sia qui per affari che riguardano la V.L.O., temo di non avere molto tempo per chiacchierare. Se vuoi dare una mano in paese, però, ti metterò di sicuro al lavoro.\n\nOh, cosa significa V.L.O.? gestione operativa del villaggio, naturalmente. Anche i paesi di frontiera come questo non si gestiscono da soli. Tra incidenti gravi, blackout imprevisti dell'energia del vento e infestazioni di insetti, mandare avanti questo posto non è uno scherzo." },
    ["65d4a06a"] = { it = "Di cosa ha bisogno adesso fratello Paxton?" },
    ["6806ac9a"] = { it = "Maledetti kobold. Non riesco a combinare niente con loro che corrono avanti e indietro e mi stanno tra i piedi. Be', non ho niente di meglio da fare: vuoi imparare qualche tecnica di estrazione? O magari ti servono solo degli attrezzi nuovi?" },
    ["68ecf317"] = { it = "Dalla tua aura capisco che discendi dagli Alti Nobili, vero? Quelli che si definiscono membri dell’Alto Ordine trovano ben pochi punti in comune con i membri del mio ordine, i Plasmavento. Fuori dalla relativa armonia del Boschetto di Thendal, potresti scoprire che queste divisioni sono molto profonde, tanto da portare a spaccature e perfino alla violenza.\n\nTienilo a mente mentre ti muovi per l’isola di Zephras. Ti do un solo avvertimento... non metterti contro i Plasmavento." },
    ["74579ed0"] = { it = "Si capisce solo da come stai in piedi che non sei $Gun guerriero:una guerriera;.\n\nPerché non vai a fare qualcosa di sicuro, tipo leggere un libro?" },
    ["74cd4bb5"] = { it = "$GBentornato:Bentornata; nella Luce, $Gamico:amica;. Hai bisogno di addestramento?" },
    ["77c1d74a"] = { it = "Salute a te, collega $Giniziato:iniziata; dell’Alto Ordine." },
    ["785cd65c"] = { it = "Nessun'altra razza di Azeroth ha sofferto quanto il nostro popolo, $C. Ridere in faccia alla morte è diventato per tutti noi una seconda natura." },
    ["7a71ab9c"] = { it = "Ho sentito che il vecchio maresciallo McBride ti mandava da me." },
    ["7fefa871"] = { it = "In tutti i nostri anni di rapporti con gli spiriti del vento, mai una volta hanno parlato del Signore del Vento come di una figura da venerare. Riconoscevano l'esistenza di un essere di nome Al'Akir, ma evitavano di invocarne il nome, quasi come se lo temessero.\n\nAnche se questo Al'Akir fosse un \"Signore del Vento\" onnipotente, o il sovrano degli elementali del vento, i miei secoli di comunione con gli spiriti mi hanno convinta che, come minimo, non è amato da tutti gli abitanti di Skywall. Temo che cercare di trattare con Al'Akir non farebbe che affrettare la nostra rovina." },
    ["8013a870"] = { it = "Ho ucciso un guardiano e rubato qualche pietra del vento." },
    ["84399b51"] = { it = "I seguaci delle antiche vie degli Alti Nobili non sono mai stati così affamati di conoscenza e così desiderosi di recuperare ciò che abbiamo perduto. Se aspiri a dominare il potere dell'arcano e ne hai l'attitudine, posso aiutarti a muovere i prossimi passi." },
    ["85607342"] = { it = "Diffida di chiunque incontri con una veste grigia e la testa rasata. Si fanno chiamare Al'Aketh, e sono una minaccia.\n\nHo perfino sentito dire che stanno facendo qualcosa ai piloni d'ancoraggio intorno all'isola.\n\nSe si deve credere ai Plasmavento, quei piloni sono l'unica cosa che tiene Zephras a galla, qui nel piano elementale. Sarebbe una follia manometterli!" },
    ["897520c4"] = { it = "I Plasmavento e l'Alto Ordine tramano qualcosa. Girano voci che entrambi i gruppi vogliano rimettere in funzione le navi volanti e usarle per lasciare Skywall. LASCIARE SKYWALL? Che assurdità. E poi dove andrebbero?" },
    ["90da079f"] = { it = "Ehi, $Gcittadino:cittadina;! Sembri una persona tosta. Noi guardie siamo un po' sparpagliate qui fuori, e un aiuto mi farebbe comodo..." },
    ["91b7da22"] = { it = "Perché sta succedendo? In poche parole, gli spiriti del vento sono... svaniti. Un giorno c'erano e il giorno dopo erano spariti. Non so descrivere bene quello che noi Plasmavento abbiamo provato quando è successo. È stato come se su tutti noi fosse calato un grande silenzio, e poi... un'assenza profonda.\n\nI piccoli spettri che probabilmente hai incontrato là fuori sono solo ombre della gloria dei veri spiriti del vento. Privi di coscienza, senza meta, e ben lontani dagli spiriti gentili con cui abbiamo vissuto in armonia per migliaia di anni." },
    ["959e0c6b"] = { it = "Se vuoi imparare a forgiare da te armi e armature, sarò felice di aiutarti." },
    ["99367246"] = { it = "Gli shen'dorei avranno sempre un debito con gli spiriti per il loro aiuto, e i Plasmavento hanno giurato di ripagare quel debito e di riportare le cose com'erano prima. Purtroppo, senza gli spiriti a guidarci, siamo pericolosamente ciechi di fronte a quello che accade intorno a noi dentro Skywall.\n\nI membri dell’Alto Ordine sono miopi e arroganti, proprio come i loro antenati, gli Alti Nobili. Cercano di dominare e controllare la magia di questo luogo. È proprio la via che ci ha portati a fuggire da Kalimdor e a stabilirci qui. Temo che, non diversamente dai nostri antenati, la loro sicurezza di sé abbia superato di gran lunga la loro competenza, e che il risultato finale possa essere disastroso." },
    ["9c478265"] = { it = "Devi ricordare che, anche se questo regno è la nostra casa da millenni, qui saremo sempre un po' estranei. Non siamo nel mondo terrestre che ha dato i natali al nostro popolo. Siamo nel regno di Skywall, una parte del piano elementale.\n\nSiamo arrivati qui come ospiti di spiriti con cui, in epoche lontane, abbiamo trovato una causa comune. Ora che noi shen'dorei ci ritroviamo privi della loro presenza e, forse, della loro protezione, non si può sapere come ci vedranno gli altri abitanti di questo piano." },
    ["9ce975bd"] = { it = "Ehi, salve, $Gviaggiatore:viaggiatrice;!" },
    ["a0dac3c9"] = { it = "Salve, $C." },
    ["a20e0f6a"] = { it = "Hai sentito cos'è successo a Ban'aethal? I guardiano avvertono tutti di stare lontani dalle rovine e dall'intera Foresta delle Burrasche Oscure.\n\nHo sentito per caso qualcuno alla locanda che raccontava di aver visto degli spiriti del vento malevoli che sembravano poco più di una sagoma nebulosa, come se fossero stati... svuotati, in qualche modo.\n\nMi vengono i brividi solo a pensarci." },
    ["a355a12e"] = { it = "No! No, no, no! Non può essere. Meglio $Gmorto che Reietto:morta che Reietta;! \n\n<$GIl:La; $C $Gspaventato:spaventata; alza l'arma, $Gpronto:pronta; ad attaccare!>" },
    ["a71f4739"] = { it = "I cacciatori e i ranger di Zephras non sono mai stati così necessari. I venti si fanno sempre più duri, e la magia che sostiene la nostra isola si sta spegnendo. Le terre selvagge non sono mai state così selvagge, e serve gente come me per tenere al sicuro il nostro popolo.\n\nSe hai la giusta attitudine come $Gcacciatore:cacciatrice;, posso darti gli strumenti per sopravvivere nelle terre selvagge." },
    ["aadb6975"] = { it = "Va' nel Quartiere dei Maghi e cerca Fyrenz Stargazer, appena a nord-ovest della torre dei maghi." },
    ["abcdfa06"] = { it = "Che hai da guardare?" },
    ["aca34af8"] = { it = "Certo! Verso quale professione vuoi che ti indirizzi?\n\nSegnerò sulla tua mappa dove trovare l'istruttore locale che sceglierai. Ricorda che nelle capitali puoi trovare istruttori per un addestramento più completo." },
    ["b3a40214"] = { it = "Forse non sei $Gun paladino:una paladina;, ma potresti comunque trovare conforto nella Luce, se lo cercherai." },
    ["b810dffb"] = { it = "Salve, $C. Spero che tu sia $Gvenuto:venuta; a rafforzare le nostre file. Bestie e ladri si stanno riversando nella nostra amata Elwynn, e abbiamo a malapena abbastanza uomini per tenere sicure le strade!\n\nE se non l'hai ancora fatto, leggi quell'avviso su Hogger. È una bestia di quei boschi laggiù, e bisogna occuparsene." },
    ["ba584eda"] = { it = "L'oscurità non ti accoglie, $C. Smettila di blaterare e togliti dalla mia vista! Sparisci!" },
    ["bbd830a1"] = { it = "Stammi lontano, mostro!" },
    ["bc0c5508"] = { it = "Salve, $C. Vieni a cercare le benedizioni del Signore del Vento?" },
    ["bceb192f"] = { it = "Ah, è già abbastanza difficile mantenere l'ordine qui intorno senza tutti questi nuovi guai che spuntano! Spero che tu abbia buone notizie, $N..." },
    ["befc0ee5"] = { it = "Sì, $C?" },
    ["c4c85fcd"] = { it = "Ah, salve. Sembra che tu abbia una domanda da farmi." },
    ["c5029f03"] = { it = "Non ho tempo da perdere con quelli come te, $C." },
    ["cd4f21ec"] = { it = "Se ti serve un addestramento in cucina, ho qualche trucco e qualche consiglio da passarti! Oh oh! Mettiti un grembiule e cominciamo!" },
    ["cd5dcc6a"] = { it = "Quassù ci si può annoiare, sai. Posso punzecchiare quel disgraziato tutto impettito di Halaan solo fino a un certo punto, poi stanca anche quello." },
    ["ce79691f"] = { it = "Notizie dei venti. In cosa posso aiutarti?" },
    ["d1db6758"] = { it = "Ultimamente vedo sempre più spesso le navi volanti solcare il cielo. È bello sapere che funzionano di nuovo. Se solo gli anziani ci dicessero cosa sta succedendo. Ci dicono soltanto che non è cambiato niente e che non abbiamo ancora contatti con le altre isole.\n\nNon posso fare a meno di chiedermi cosa significhi..." },
    ["d4dfa17f"] = { it = "Perché negarlo? La conestabile ha già emesso il suo giudizio. Non ha senso mentire." },
    ["db8a85cd"] = { it = "Zephras è in grave pericolo. Gli spiriti elementali del vento che ci portarono qui a Skywall molte migliaia di anni fa ci hanno abbandonato, e ci hanno lasciato vulnerabili in questo regno instabile. Un tempo la nostra società era forte e si estendeva su più santuari insulari nel nostro angolo di Skywall, ma ora non sappiamo nemmeno se al di fuori di questa piccola isola restino altri shen'dorei.\n\nLa situazione è disperata, ma i membri dell’Alto Ordine sono decisi ad affrontare questa sfida." },
    ["e293d462"] = { it = "In gran parte sì. Quello che abbiamo tutti in comune è che non abbiamo nessun altro posto dove andare, e che preferiamo rubare piuttosto che renderci schiavi di qualche culto folle." },
    ["e6e88276"] = { it = "Credi di avere la stoffa per estrarre minerale?" },
    ["e756211e"] = { it = "Cosa vuoi da me, $Gfiglio:figlia; di Zephras?" },
    ["e90046a5"] = { it = "<conestabile Aonda ha un'espressione intensa sul volto: è chiaramente assorta nei suoi pensieri.>" },
    ["ec5dfe55"] = { it = "Agol ne wirsh ver ne vandar novaedi veld algos nevren? Va se ras uden vrum bor garde?" },
    ["ed599bdb"] = { it = "<Lo sguardo del ranger davanti a te è fisso sull'enorme pilone d'ancoraggio in lontananza.>" },
    ["ee50e5bb"] = { it = "Sei qui per addestrarti? O sei qui solo per far perdere tempo a $Gun:una; $C?" },
    ["eff42141"] = { it = "Salve, $C.\n\nSe lo desideri, posso mostrarti come intessere la magia intorno a te per cambiare l'aspetto del tuo equipaggiamento. Vuoi usufruire dei miei servigi?" },
    ["f4deb2a1"] = { it = "Gli spiriti del vento ci avranno anche lasciato, ma il potere degli elementi non è del tutto fuori portata per chi ha la pazienza di cercarli.\n\nSe sei $Giniziato:iniziata; alle vie $Gdello sciamano:della sciamana;, posso aiutarti a comprenderli." },
    ["f67e608e"] = { it = "Che la Luce ti protegga, oggi." },
    ["f6b476e2"] = { it = "Più di quanti vorrei, temo. Siamo tormentati da un gruppo di banditi accampati in una grotta a nord, e di recente il culto degli Al'Aketh ha preso il villaggio di Falaath, a sud di noi. Mi fido di ogni guardiano e di ogni cittadino qui, ma siamo troppo pochi per tenere al sicuro il villaggio.\n\nSe il culto decide di continuare a espandersi fin qui, possiamo fare ben poco per fermarlo." },
    ["f864af73"] = { it = "Se hai l'attitudine per le arti druidiche, posso addestrarti." },
    ["fcee30d3"] = { it = "Salve... Plasmavento.\n\nChi si definisce membro dei Plasmavento trova poca causa comune con la maggior parte dei membri dell'Alto Ordine, come sono sicuro che saprai. Al di fuori della relativa armonia del Boschetto di Thendal, potresti scoprire che queste divisioni sono davvero profonde, e che in alcuni casi la rivalità può sfociare in violenza aperta.\n\nNon dirò altro in proposito, se non che dovresti badare ai fatti tuoi e non intralciare gli scopi dell'Alto Ordine, una volta lasciato il boschetto. Probabilmente è l'unico avvertimento che riceverai." },
}
WoWForeverIT_QuestIT.OptionsIT = {
    ["03a9adae"] = { it = "Dov'è l'istruttore di estrazione mineraria?" },
    ["06c8dcac"] = { it = "Vorrei proseguire l'addestramento nelle vie della Luce." },
    ["0c3677cc"] = { it = "Dov'è l'istruttore di pesca?" },
    ["0d917335"] = { it = "Dov'è l'istruttore di alchimia?" },
    ["1261ce6d"] = { it = "Dov'è l'istruttore di scuoiatura?" },
    ["14071958"] = { it = "Vorrei addestrarmi!" },
    ["1479b7cd"] = { it = "Vorrei comprare da te." },
    ["1972ee16"] = { it = "Dov'è l'istruttore di conciatura?" },
    ["1be274a3"] = { it = "Mi ricordi cosa sta succedendo a isola di Zephras?" },
    ["29d15c96"] = { it = "Che tipi di professioni esistono?" },
    ["32714819"] = { it = "Perché l'hai fatto?" },
    ["34090cb0"] = { it = "Ciao! Sono $Gun:una; $C e ho bisogno di addestramento." },
    ["35cfdf7e"] = { it = "Addestrami." },
    ["55aa8735"] = { it = "Dov'è l'istruttore di incantamento?" },
    ["640e042f"] = { it = "Halaan, ti prego, prestami il tuo dono." },
    ["6657d97e"] = { it = "Vorrei cambiare l'aspetto del mio equipaggiamento." },
    ["66a9a028"] = { it = "E gli Al'Aketh? Possono aiutarci?" },
    ["67103a0d"] = { it = "Come puoi esserne così sicura? Se non abbiamo mai trattato direttamente con il Signore del Vento, non vale la pena provarci?" },
    ["6d522904"] = { it = "Trasmogrificatore" },
    ["750ac883"] = { it = "Sembri molto \"distaccato\" al riguardo." },
    ["7db0e31b"] = { it = "Stormwind Harbor" },
    ["7e68a093"] = { it = "Il trasmogrificatore" },
    ["7fbb4f63"] = { it = "Dov'è l'istruttore di ingegneria?" },
    ["8a3fcea5"] = { it = "Mi serve addestramento da $C." },
    ["9068b961"] = { it = "E questo \"Signore del Vento\"? Al'Akir esiste davvero, o è un'invenzione del culto?" },
    ["9baf1d8e"] = { it = "Hai perso la tua casa?" },
    ["a06238d7"] = { it = "Cosa puoi dirmi sulla situazione dei Plasmavento?" },
    ["a6c2d450"] = { it = "Cosa sono le professioni?" },
    ["acabed84"] = { it = "Vorrei chiederti un'altra cosa." },
    ["ad076453"] = { it = "Come risolviamo la cosa?" },
    ["b1bcd1d8"] = { it = "Dov'è l'istruttore di forgiatura?" },
    ["b31e56bd"] = { it = "Cosa puoi dirmi sulla situazione dell’Alto Ordine?" },
    ["b35efc27"] = { it = "Dov'è l'istruttore di sartoria?" },
    ["b5755374"] = { it = "Vorrei sapere dove trovare un istruttore di professioni qui vicino." },
    ["c325de19"] = { it = "Puoi dirmi di più sullo stato dell’isola di Zephras e dei Plasmavento?" },
    ["c48b33c6"] = { it = "Salve, $C come me. So che è uno shock, ma sei risorta e ti è stata data un'altra possibilità di servire la Luce. Vieni con me e ti aiuterò ad abituarti a questa nuova realtà." },
    ["c4f1c93e"] = { it = "Conestabile, puoi dirmi cosa sta succedendo qui nelle Shen'dar Highlands?" },
    ["c6b748bc"] = { it = "Dov'è l'istruttore di cucina?" },
    ["ce4cd2cf"] = { it = "Sappiamo perché...?" },
    ["cf951011"] = { it = "<Resta in silenzio>" },
    ["da051477"] = { it = "Perché sei in questa gabbia?" },
    ["dbbb77cb"] = { it = "Dov'è l'istruttore di erbalismo?" },
    ["dc5021ca"] = { it = "Dov'è l'istruttore di primo soccorso?" },
    ["de845477"] = { it = "Vorrei disattivare la trasmogrificazione." },
    ["e749d092"] = { it = "Barbiere" },
    ["e7fb6e85"] = { it = "Tutti i banditi degli altopiani sono profughi?" },
    ["eadbc661"] = { it = "Ti prego, non farlo..." },
    ["f6a66be0"] = { it = "Molto interessante. Grazie di avermelo raccontato." },
    ["fe90013b"] = { it = "Puoi dirmi di più sullo stato dell’isola di Zephras e dell’Alto Ordine?" },
}
WoWForeverIT_QuestIT.BooksIT = {
    ["0bec7833"] = { it = "Ner'zhul, il Re dei Lich, sapeva che il suo tempo stava per finire. Imprigionato nel Frozen Throne, sospettava che Kil'jaeden avrebbe mandato i suoi agenti a distruggerlo. I danni causati dall'incantesimo di Illidan avevano spaccato il Frozen Throne; così il Re dei Lich perdeva potere ogni giorno. Disperato, per salvarsi chiamò al suo fianco il suo più grande servitore mortale: il cavaliere della morte, il principe Arthas." },
    ["0ef084c2"] = { it = "Anche se i suoi poteri erano stati prosciugati dalla debolezza del Re dei Lich, Arthas si era trovato coinvolto in una guerra civile a Lordaeron. Metà delle forze non morte ancora in piedi, guidate dalla banshee Sylvanas Windrunner, aveva organizzato un colpo di stato per prendere il controllo dell'impero dei non morti. Arthas, richiamato dal Re dei Lich, fu costretto a lasciare il Flagello nelle mani del suo luogotenente, Kel'Thuzad, mentre la guerra si estendeva in tutte le Plaguelands." },
    ["2b58a97e"] = { it = "Indebolito, ma deciso a salvare il suo signore, Arthas raggiunse Northrend, dove però trovò ad attenderlo i naga e gli elfi del sangue di Illidan. Insieme ai suoi alleati nerubiani cercò di precedere le forze di Illidan per raggiungere l'Icecrown Glacier e difendere il Frozen Throne." },
    ["4066cf42"] = { it = "<Tocchi il piccolo cristallo bianco e senti suoni flebili portati dal vento. È una specie di registrazione sonora.>\n\n\"Sullo Shal'nan\"" },
    ["7c1308ea"] = { it = "\"Uno shen'dorei dalla presenza intensa, lo Shal'nan era un grande oratore che sapeva smuovere il cuore del suo popolo e ispirare rispetto persino tra i suoi nemici. Le sue parole infuocate furono il perno che spinse il nostro popolo alla rivolta contro l'odiato Prince Tortheldrin.\n\nFurono la sua determinazione e la sua fermezza incrollabile a salvarci dopo il fallimento della rivolta. Lo Shal'nan garantì la nostra sopravvivenza durante la fuga attraverso il mare. E fu sempre lo Shal'nan in persona a mediare la pace con gli spiriti del vento e a permetterci di ascendere al piano elementale.\"" },
    ["a335d507"] = { it = "Alla fine Sylvanas e i suoi non morti ribelli (conosciuti come Reietti) rivendicarono come propria la capitale in rovina di Lordaeron. Costruita una roccaforte sotto la città distrutta, i Reietti giurarono di sconfiggere il Flagello e di cacciare Kel'Thuzad e i suoi servitori da quelle terre." },
    ["cf02e198"] = { it = "\"Qualcosa però cambiò dopo quell'ultima, fatale battaglia a Eldre'Thalas. È risaputo che negli anni successivi alla fuga dalla nostra antica casa lo Shal'nan fu sempre un capo riluttante. Erano finiti i giorni dei discorsi infuocati e dei comandi che chiamavano a raccolta; al loro posto venne una guida silenziosa e meditativa.\n\nLo Shal'nan ascoltava più di quanto parlasse, e quando parlava sceglieva le parole con cura. Sembrava esitante e, a volte, distante.\"" },
    ["dd769a9f"] = { it = "\"Molti furono costernati dalla sua abdicazione, ma molti applaudirono anche la sua disponibilità a cedere il potere con tanta facilità dopo più di un secolo di autorità quasi assoluta. Nelle migliaia di anni di storia elfica, pochi sovrani hanno mai mostrato una simile magnanimità, ed è questo gesto di altruismo che lo fisserà per sempre nella nostra memoria.\"" },
    ["eda793d1"] = { it = "\"Molti supposero che questo cambiamento nello Shal'nan fosse il risultato di una grave ferita o di un trauma subito nella sua ultima battaglia contro le forze di Tortheldrin. Altri credevano che, in quel tempo di relativa pace, semplicemente non avesse più bisogno dell'ardore che mostrava in guerra.\n\nNonostante questo cambiamento, lo Shal'nan guidò il nostro popolo con quieta determinazione in quei primi anni. Non vacillò mai nella sua risolutezza, nemmeno di fronte a sfide schiaccianti. Il nostro Shal'nan fu, stando a tutti i racconti dell'epoca, un capo eccellente malgrado il mutato contegno, fino alla sua abdicazione a favore del consiglio provinciale dopo la fondazione delle Skyborne Isles dentro Skywall.\"" },
}
